private struct ConfirmedWorkoutHRRehydrationAttemptPayload: Encodable {
    let algorithmVersion: String
    let workouts: [UserConfirmedWorkout]
    let sessions: [SavedSession]
    let restingHR: Int
    let maxHR: Int
    let profile: AthleteProfile
    let sourceFingerprint: HistoricalArchive.ConsumerSourceFingerprint
}

struct EventCivilTime {
    static func eventCalendar(timeZoneIdentifier: String?, fallback: Calendar) -> Calendar {
        guard let timeZoneIdentifier,
              let timeZone = TimeZone(identifier: timeZoneIdentifier) else {
            return fallback
        }
        var calendar = fallback
        calendar.timeZone = timeZone
        return calendar
    }

    static func day(containing date: Date,
                    eventTimeZoneIdentifier: String?,
                    outputCalendar: Calendar) -> Date {
        guard let eventTimeZoneIdentifier,
              TimeZone(identifier: eventTimeZoneIdentifier) != nil else {
            return outputCalendar.startOfDay(for: date)
        }
        let eventCalendar = eventCalendar(timeZoneIdentifier: eventTimeZoneIdentifier,
                                          fallback: outputCalendar)
        let civilDay = eventCalendar.dateComponents([.year, .month, .day], from: date)
        guard let materialized = outputCalendar.date(from: civilDay) else {
            return outputCalendar.startOfDay(for: date)
        }
        return outputCalendar.startOfDay(for: materialized)
    }

    static func localHour(of date: Date,
                          eventTimeZoneIdentifier: String?,
                          fallback: Calendar) -> Int {
        eventCalendar(timeZoneIdentifier: eventTimeZoneIdentifier, fallback: fallback)
            .component(.hour, from: date)
    }

    static func interval(forCivilDay day: Date,
                         eventTimeZoneIdentifier: String?,
                         outputCalendar: Calendar) -> DateInterval? {
        let eventCalendar = eventCalendar(timeZoneIdentifier: eventTimeZoneIdentifier,
                                          fallback: outputCalendar)
        let components = outputCalendar.dateComponents([.year, .month, .day], from: day)
        guard let start = eventCalendar.date(from: components),
              let end = eventCalendar.date(byAdding: .day, value: 1, to: start) else {
            return nil
        }
        return DateInterval(start: start, end: end)
    }

    static func days(overlappedBy start: Date,
                     end: Date,
                     eventTimeZoneIdentifier: String?,
                     outputCalendar: Calendar) -> [Date] {
        guard end > start else { return [] }
        let eventCalendar = eventCalendar(timeZoneIdentifier: eventTimeZoneIdentifier,
                                          fallback: outputCalendar)
        var cursor = eventCalendar.startOfDay(for: start)
        let finalInstant = end.addingTimeInterval(-0.001)
        var days: [Date] = []
        while cursor <= finalInstant {
            let components = eventCalendar.dateComponents([.year, .month, .day], from: cursor)
            if let materialized = outputCalendar.date(from: components) {
                days.append(outputCalendar.startOfDay(for: materialized))
            }
            guard let next = eventCalendar.date(byAdding: .day, value: 1, to: cursor),
                  next > cursor else { break }
            cursor = next
        }
        return days
    }
}

/// The live performance window is physiological, not a civil calendar day.
/// A main sleep wake starts a new cycle; naps never do. If another main sleep
/// does not arrive, deterministic wake-to-wake fallback boundaries prevent an
/// all-nighter from carrying yesterday's strain forever.
struct AtriaPhysiologicalCycle: Equatable {
    enum BoundaryKind: String, Equatable {
        case mainSleep
        case noSleepFallback
        case initialFallback
    }

    static let defaultInterval: TimeInterval = 24 * 60 * 60
    static let minimumLearnedInterval: TimeInterval = 20 * 60 * 60
    static let maximumLearnedInterval: TimeInterval = 28 * 60 * 60
    /// Sleep confirmation deliberately settles after the measured wake so a
    /// resumed fragment can join the same night. A no-sleep rollover must not
    /// race that settlement and briefly open a synthetic cycle underneath a
    /// normal overnight sleep.
    static let noSleepSettlementGrace: TimeInterval = 30 * 60
    /// Automatic detections and blank manual entries need this conservative
    /// floor before they can reset recovery or suppress an all-nighter
    /// rollover. A sensor-backed `user_adjusted_sleep` uses the shared
    /// physiological-main-sleep gate below, which accepts the editor's honest
    /// measured-coverage floor without weakening this detector/manual guard.
    static let minimumMainSleepDuration = AggregateSleepCandidate.strictMinimumDuration

    let start: Date
    let boundaryKind: BoundaryKind
    let anchorSleepID: String?
    let expectedInterval: TimeInterval

    static func latestCompletedMainSleep(now: Date,
                                         confirmedSleeps: [UserConfirmedSleep],
                                         calendar: Calendar = .current) -> UserConfirmedSleep? {
        boundaryEligibleMainSleeps(
            now: now,
            confirmedSleeps: confirmedSleeps,
            calendar: calendar
        ).last
    }

    static func current(now: Date,
                        confirmedSleeps: [UserConfirmedSleep],
                        calendar: Calendar = .current) -> Self {
        let mainSleeps = boundaryEligibleMainSleeps(
            now: now,
            confirmedSleeps: confirmedSleeps,
            calendar: calendar
        )
        let expected = learnedInterval(from: mainSleeps.map(\.end))

        guard let latest = mainSleeps.last else {
            let startOfToday = calendar.startOfDay(for: now)
            let todayFallback = calendar.date(byAdding: .hour, value: 6, to: startOfToday) ?? startOfToday
            let start = todayFallback <= now
                ? todayFallback
                : (calendar.date(byAdding: .day, value: -1, to: todayFallback) ?? startOfToday)
            return Self(start: start,
                        boundaryKind: .initialFallback,
                        anchorSleepID: nil,
                        expectedInterval: expected)
        }

        guard let fallback = latestCompletedNoSleepFallback(
            after: latest,
            at: now,
            calendar: calendar
        ) else {
            return Self(start: latest.end,
                        boundaryKind: .mainSleep,
                        anchorSleepID: latest.id,
                        expectedInterval: expected)
        }

        return Self(start: fallback,
                    boundaryKind: .noSleepFallback,
                    anchorSleepID: latest.id,
                    expectedInterval: expected)
    }

    /// The first bounded rollover after a wake, expressed in the time zone in
    /// which that wake occurred. Civil-day arithmetic keeps the local boundary
    /// stable through DST and travel; elapsed 86,400-second arithmetic does not.
    static func firstNoSleepFallback(
        after wake: Date,
        eventTimeZoneIdentifier: String?,
        calendar: Calendar
    ) -> Date? {
        let eventCalendar = EventCivilTime.eventCalendar(
            timeZoneIdentifier: eventTimeZoneIdentifier,
            fallback: calendar
        )
        guard let nextCivilWake = eventCalendar.date(
            byAdding: .day,
            value: 1,
            to: wake
        ) else {
            return nil
        }
        return nextCivilWake.addingTimeInterval(noSleepSettlementGrace)
    }

    /// 2026-07-31: the next instant at which `current` would report a new
    /// cycle start if no further main sleep is confirmed — the moment the
    /// no-sleep fallback silently rolls the wake boundary. No notification
    /// fires at that instant, so receipt/presentation refresh must schedule
    /// its own check against this boundary.
    static func nextNoSleepRollover(
        now: Date,
        confirmedSleeps: [UserConfirmedSleep],
        calendar: Calendar = .current
    ) -> Date? {
        let cycle = current(
            now: now,
            confirmedSleeps: confirmedSleeps,
            calendar: calendar
        )
        switch cycle.boundaryKind {
        case .mainSleep:
            let anchorTimeZoneIdentifier = confirmedSleeps
                .first { $0.id == cycle.anchorSleepID }?
                .eventTimeZoneIdentifier
            return firstNoSleepFallback(
                after: cycle.start,
                eventTimeZoneIdentifier: anchorTimeZoneIdentifier,
                calendar: calendar
            )
        case .noSleepFallback:
            let anchorTimeZoneIdentifier = confirmedSleeps
                .first { $0.id == cycle.anchorSleepID }?
                .eventTimeZoneIdentifier
            let eventCalendar = EventCivilTime.eventCalendar(
                timeZoneIdentifier: anchorTimeZoneIdentifier,
                fallback: calendar
            )
            return eventCalendar.date(
                byAdding: .day,
                value: 1,
                to: cycle.start
            )
        case .initialFallback:
            return calendar.date(byAdding: .day, value: 1, to: cycle.start)
        }
    }

    /// Returns the latest completed fallback without inventing a sleep record.
    /// Repeated civil-day advancement prevents an indefinitely open cycle even
    /// when the user remains awake for multiple days.
    private static func latestCompletedNoSleepFallback(
        after sleep: UserConfirmedSleep,
        at instant: Date,
        calendar: Calendar
    ) -> Date? {
        guard var fallback = firstNoSleepFallback(
            after: sleep.end,
            eventTimeZoneIdentifier: sleep.eventTimeZoneIdentifier,
            calendar: calendar
        ), fallback <= instant else {
            return nil
        }
        let eventCalendar = EventCivilTime.eventCalendar(
            timeZoneIdentifier: sleep.eventTimeZoneIdentifier,
            fallback: calendar
        )
        while let next = eventCalendar.date(
            byAdding: .day,
            value: 1,
            to: fallback
        ), next > fallback, next <= instant {
            fallback = next
        }
        return fallback
    }

    /// A sleep learned only after an earlier no-sleep boundary was completed
    /// cannot move the live cycle backwards across that sealed boundary.
    /// Sleep history still retains the record; this filter governs day
    /// ownership only. A sleep whose wake reaches or follows the boundary is
    /// accepted because it starts a later, non-overlapping physiological day.
    static func boundaryEligibleMainSleeps(
        now: Date,
        confirmedSleeps: [UserConfirmedSleep],
        calendar: Calendar
    ) -> [UserConfirmedSleep] {
        // A day the user slept more than once has one main they designated as
        // primary; the same-day main they kept as a second sleep is marked
        // `dayPrimaryChoice == false` and must NOT anchor its own physiological
        // cycle. Excluding it here lets the chosen primary own the day so the
        // second sleep falls inside that day's window (and shows as its own
        // Activity row) instead of spawning an unreachable parallel cycle. With
        // no choice recorded this set is empty and behaviour is unchanged.
        let nonPrimaryMainIDs = Set(
            confirmedSleeps.filter { $0.dayPrimaryChoice == false }.map(\.id)
        )
        let candidates = canonicalMainSleeps(from: confirmedSleeps)
            .filter { $0.end <= now && !nonPrimaryMainIDs.contains($0.id) }
            .sorted { $0.end < $1.end }
        guard let first = candidates.first else { return [] }

        var accepted = [first]
        for candidate in candidates.dropFirst() {
            guard let anchor = accepted.last else { break }
            let knownAt = min(candidate.createdAt, now)
            if let sealedFallback = latestCompletedNoSleepFallback(
                after: anchor,
                at: knownAt,
                calendar: calendar
            ), candidate.end < sealedFallback,
               !explicitUserSleepCorrection(candidate) {
                continue
            }
            accepted.append(candidate)
        }
        return accepted
    }

    /// A fallback protects the live cycle from a late automatic inference, but
    /// it cannot overrule an explicit correction. Manual/adjusted records and a
    /// candidate the user actively confirmed are durable user authority, so
    /// accepting them intentionally recomputes the affected physiological day.
    private static func explicitUserSleepCorrection(
        _ sleep: UserConfirmedSleep
    ) -> Bool {
        sleep.source.hasPrefix("manual_")
            || sleep.source.hasPrefix("user_adjusted_")
            || sleep.confidence.hasPrefix("user_confirmed_")
    }

    /// Resumed sleep is stored as a separate durable Activity record so either
    /// segment remains editable. Physiologically it is still one night: the
    /// final resumed wake starts the new cycle, while the original main-sleep
    /// ID remains the stable anchor. Canonicalizing here prevents a 4h main +
    /// 3h resumed block from producing two recovery/day boundaries.
    static func canonicalMainSleeps(
        from confirmedSleeps: [UserConfirmedSleep]
    ) -> [UserConfirmedSleep] {
        canonicalMainSleepsCancellable(
            from: confirmedSleeps,
            shouldContinue: { true }
        ) ?? []
    }

    static func canonicalMainSleepsCancellable(
        from confirmedSleeps: [UserConfirmedSleep],
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> [UserConfirmedSleep]? {
        guard shouldContinue() else { return nil }
        var mains: [UserConfirmedSleep] = []
        var resumed: [UserConfirmedSleep] = []
        mains.reserveCapacity(confirmedSleeps.count)
        resumed.reserveCapacity(min(confirmedSleeps.count, 32))
        for (index, sleep) in confirmedSleeps.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            if sleep.source != "resumed_sleep",
               SessionStore.confirmedSleepIsPhysiologicalMainSleep(sleep) {
                mains.append(sleep)
            } else if sleep.source == "resumed_sleep",
                      sleep.end > sleep.start {
                guard let effectiveDuration = sleep
                    .effectiveSleepDurationCancellable(
                        shouldContinue: shouldContinue
                    ) else { return nil }
                if effectiveDuration
                    >= AggregateSleepCandidate.resumedSleepMinimumDuration {
                    resumed.append(sleep)
                }
            }
        }
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &mains,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: { $0.end < $1.end }
        ), AtriaSleepCooperativeAlgorithms.stableSort(
            &resumed,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: { $0.start < $1.start }
        ) else { return nil }

        var canonical: [UserConfirmedSleep] = []
        canonical.reserveCapacity(mains.count)
        for (mainIndex, main) in mains.enumerated() {
            if mainIndex.isMultiple(of: 16), !shouldContinue() { return nil }
            var finalEnd = main.end
            var linked: [UserConfirmedSleep] = []
            for (segmentIndex, segment) in resumed.enumerated() {
                if segmentIndex.isMultiple(of: 32), !shouldContinue() {
                    return nil
                }
                guard segment.start >= finalEnd,
                      segment.start.timeIntervalSince(main.end)
                        <= AggregateSleepCandidate.resumedSleepMaximumSeparationFromMain else {
                    continue
                }
                // A later main sleep owns any resumed record after its wake.
                var hasCloserMain = false
                for (candidateIndex, candidate) in mains.enumerated() {
                    if candidateIndex.isMultiple(of: 32), !shouldContinue() {
                        return nil
                    }
                    if candidate.id != main.id,
                       candidate.end > main.end,
                       candidate.end <= segment.start {
                        hasCloserMain = true
                        break
                    }
                }
                guard !hasCloserMain else { continue }
                linked.append(segment)
                finalEnd = segment.end
            }
            guard !linked.isEmpty else {
                canonical.append(main)
                continue
            }

            var linkedDuration: TimeInterval = 0
            var createdAt = main.createdAt
            var linkedSessions = 0
            var linkedSamples = 0
            var peakHR = main.peakHR
            var hrvWindowCount = max(main.hrvWindowCount ?? 0, 0)
            var stages = main.stageSegments ?? []
            var stageVisit = stages.count
            for (linkedIndex, sleep) in linked.enumerated() {
                if linkedIndex.isMultiple(of: 32), !shouldContinue() {
                    return nil
                }
                guard let effectiveDuration = sleep
                    .effectiveSleepDurationCancellable(
                        shouldContinue: shouldContinue
                    ) else { return nil }
                linkedDuration += effectiveDuration
                createdAt = max(createdAt, sleep.createdAt)
                linkedSessions += sleep.sessions
                linkedSamples += sleep.samples
                peakHR = max(peakHR, sleep.peakHR)
                hrvWindowCount += max(sleep.hrvWindowCount ?? 0, 0)
                for segment in sleep.stageSegments ?? [] {
                    if stageVisit.isMultiple(of: 64), !shouldContinue() {
                        return nil
                    }
                    stages.append(segment)
                    stageVisit += 1
                }
            }
            let duration = min(
                finalEnd.timeIntervalSince(main.start),
                main.duration + linkedDuration
            )
            guard AtriaSleepCooperativeAlgorithms.stableSort(
                &stages,
                shouldContinue: shouldContinue,
                areInIncreasingOrder: { $0.start < $1.start }
            ) else { return nil }
            let physiology = [main] + linked
            func durationWeightedInt(_ value: (UserConfirmedSleep) -> Int) -> Int? {
                var weightedValue = 0.0
                var weight = 0.0
                for (index, sleep) in physiology.enumerated() {
                    if index.isMultiple(of: 32), !shouldContinue() { return nil }
                    let candidate = value(sleep)
                    guard let duration = sleep
                        .effectiveSleepDurationCancellable(
                            shouldContinue: shouldContinue
                        ) else { return nil }
                    guard candidate > 0, duration > 0 else { continue }
                    weightedValue += Double(candidate) * duration
                    weight += duration
                }
                guard weight > 0 else { return nil }
                return Int((weightedValue / weight).rounded())
            }
            func durationWeightedDouble(_ value: (UserConfirmedSleep) -> Double?) -> Double? {
                var weightedValue = 0.0
                var weight = 0.0
                for (index, sleep) in physiology.enumerated() {
                    if index.isMultiple(of: 32), !shouldContinue() { return nil }
                    guard let duration = sleep
                        .effectiveSleepDurationCancellable(
                            shouldContinue: shouldContinue
                        ) else { return nil }
                    guard let candidate = value(sleep),
                          candidate > 0,
                          duration > 0 else { continue }
                    weightedValue += candidate * duration
                    weight += duration
                }
                guard weight > 0 else { return nil }
                return weightedValue / weight
            }
            var hrvSquaredWeight = 0.0
            var hrvWeight = 0.0
            for (index, sleep) in physiology.enumerated() {
                if index.isMultiple(of: 32), !shouldContinue() { return nil }
                guard let hrv = sleep.hrv, hrv > 0 else { continue }
                let weight = Double(max(sleep.hrvWindowCount ?? 0, 1))
                let hrvValue = Double(hrv)
                hrvSquaredWeight += hrvValue * hrvValue * weight
                hrvWeight += weight
            }
            let combinedHRV: Int? = if hrvWeight == 0 {
                nil
            } else {
                // RMSSD is a root-mean-square statistic. Pool segment-level
                // values in squared space instead of arithmetically averaging.
                Int(sqrt(hrvSquaredWeight / hrvWeight).rounded())
            }
            let averageHR = durationWeightedInt(\.avgHR) ?? main.avgHR
            guard shouldContinue() else { return nil }
            let restingHR = durationWeightedInt(\.restingHR) ?? main.restingHR
            guard shouldContinue() else { return nil }
            let respiratoryRate = durationWeightedDouble(\.respiratoryRate)
            guard shouldContinue() else { return nil }
            canonical.append(UserConfirmedSleep(
                id: main.id,
                createdAt: createdAt,
                start: main.start,
                end: finalEnd,
                source: main.source,
                confidence: main.confidence,
                sessions: main.sessions + linkedSessions,
                samples: main.samples + linkedSamples,
                avgHR: averageHR,
                peakHR: peakHR,
                restingHR: restingHR,
                hrv: combinedHRV,
                hrvWindowCount: hrvWindowCount,
                respiratoryRate: respiratoryRate,
                duration: duration,
                span: finalEnd.timeIntervalSince(main.start),
                reason: main.reason,
                motionSource: main.motionSource,
                motionValidated: main.motionValidated,
                stageSegments: stages.isEmpty ? nil : stages,
                eventTimeZoneIdentifier: main.eventTimeZoneIdentifier,
                sleepNeedSeconds: main.sleepNeedSeconds,
                frozenSleepNeed: main.frozenSleepNeed
            ))
        }
        return shouldContinue() ? canonical : nil
    }

    private static func learnedInterval(from wakeTimes: [Date]) -> TimeInterval {
        var intervals: [TimeInterval] = []
        if wakeTimes.count > 1 {
            for index in 1..<wakeTimes.count {
                let interval = wakeTimes[index].timeIntervalSince(wakeTimes[index - 1])
                if interval >= 12 * 60 * 60, interval <= 40 * 60 * 60 {
                    intervals.append(interval)
                }
            }
        }
        intervals.sort()
        guard !intervals.isEmpty else { return defaultInterval }
        let middle = intervals.count / 2
        let median = intervals.count.isMultiple(of: 2)
            ? (intervals[middle - 1] + intervals[middle]) / 2
            : intervals[middle]
        return min(max(median, minimumLearnedInterval), maximumLearnedInterval)
    }
}

/// Resolves a completed Activity date to the physiological interval that owns
/// it. Historical Activity used to fall back to a midnight-to-midnight window
/// unconditionally, which put the sleep beginning late on one date beside the
/// sleep that ended that morning. A historical physiological day instead starts
/// at a confirmed main-sleep wake and ends at the next wake. When no following
/// sleep arrives, it uses the same deterministic no-sleep rollover as the live
/// cycle. A civil interval remains an explicit, inspectable fallback when there
/// is no trustworthy boundary for the requested date.
struct AtriaHistoricalPhysiologicalCycle: Equatable {
    enum StartBoundary: Equatable {
        case mainSleep(id: String)
        case noSleepFallback(anchorSleepID: String)
        case civilDayFallback
    }

    enum EndBoundary: Equatable {
        case mainSleep(id: String)
        case noSleepFallback(anchorSleepID: String)
        case civilDayFallback
    }

    let interval: DateInterval
    let displayDay: Date
    let startBoundary: StartBoundary
    let endBoundary: EndBoundary

    var usesCivilFallback: Bool {
        startBoundary == .civilDayFallback
    }

    var followingRecoverySleepID: String? {
        guard case .mainSleep(let id) = endBoundary else { return nil }
        return id
    }

    static func resolve(
        displayDay: Date,
        sleepHistory: SleepHistorySnapshot,
        calendar: Calendar = .current
    ) -> Self {
        resolve(
            displayDay: displayDay,
            confirmedSleeps: compactBoundarySleeps(from: sleepHistory),
            calendar: calendar
        )
    }

    static func resolve(
        displayDay: Date,
        confirmedSleeps: [UserConfirmedSleep],
        calendar: Calendar = .current
    ) -> Self {
        let dayStart = calendar.startOfDay(for: displayDay)
        guard let civilEnd = calendar.date(byAdding: .day, value: 1, to: dayStart),
              civilEnd > dayStart else {
            return Self(interval: DateInterval(start: dayStart, end: dayStart),
                        displayDay: dayStart,
                        startBoundary: .civilDayFallback,
                        endBoundary: .civilDayFallback)
        }

        // A physiological rollover is always due by the next event-local day.
        // Looking three output-calendar days ahead covers the next main sleep
        // through the full legal time-zone offset range without treating later
        // records as known at the historical boundary.
        let horizon = calendar.date(byAdding: .day, value: 3, to: civilEnd) ?? civilEnd
        let eligible = AtriaPhysiologicalCycle.boundaryEligibleMainSleeps(
            now: horizon,
            confirmedSleeps: confirmedSleeps,
            calendar: calendar
        )

        if let anchor = eligible.last(where: {
            calendar.isDate(wakeDisplayDay(for: $0, calendar: calendar),
                            inSameDayAs: dayStart)
        }) {
            return cycle(startingAt: anchor.end,
                         displayDay: dayStart,
                         startBoundary: .mainSleep(id: anchor.id),
                         anchor: anchor,
                         eligibleSleeps: eligible,
                         calendar: calendar)
        }

        if let fallback = noSleepFallback(
            for: dayStart,
            eligibleSleeps: eligible,
            calendar: calendar
        ) {
            return cycle(startingAt: fallback.start,
                         displayDay: dayStart,
                         startBoundary: .noSleepFallback(anchorSleepID: fallback.anchor.id),
                         anchor: fallback.anchor,
                         eligibleSleeps: eligible,
                         calendar: calendar)
        }

        return Self(interval: DateInterval(start: dayStart, end: civilEnd),
                    displayDay: dayStart,
                    startBoundary: .civilDayFallback,
                    endBoundary: .civilDayFallback)
    }

    /// The confirmed sleep that truthfully closes the physiological cycle
    /// containing this workout. If a deterministic no-sleep rollover happens
    /// first, or the workout overlaps the purported recovery sleep, no recovery
    /// score is attributed to the workout.
    static func followingRecoverySleep(
        for workout: UserConfirmedWorkout,
        confirmedSleeps: [UserConfirmedSleep],
        calendar: Calendar = .current
    ) -> UserConfirmedSleep? {
        guard workout.end > workout.start else { return nil }
        let horizon = calendar.date(byAdding: .day, value: 3, to: workout.end)
            ?? workout.end.addingTimeInterval(3 * 24 * 60 * 60)
        let eligible = AtriaPhysiologicalCycle.boundaryEligibleMainSleeps(
            now: horizon,
            confirmedSleeps: confirmedSleeps,
            calendar: calendar
        )
        let cycle = AtriaPhysiologicalCycle.current(
            now: workout.start,
            confirmedSleeps: eligible,
            calendar: calendar
        )
        guard cycle.boundaryKind != .initialFallback,
              let anchorID = cycle.anchorSleepID,
              let anchor = eligible.first(where: { $0.id == anchorID }),
              let fallback = nextFallback(
                after: cycle.start,
                boundaryKind: cycle.boundaryKind,
                anchor: anchor,
                calendar: calendar
              ) else { return nil }
        return eligible.first {
            $0.end > workout.end
                && $0.start >= workout.end
                && $0.end <= fallback
        }
    }

    static func followingRecoverySleep(
        for workout: UserConfirmedWorkout,
        sleepHistory: SleepHistorySnapshot,
        calendar: Calendar = .current
    ) -> UserConfirmedSleep? {
        followingRecoverySleep(
            for: workout,
            confirmedSleeps: compactBoundarySleeps(from: sleepHistory),
            calendar: calendar
        )
    }

    static func recoveryAttributionIsPending(
        for workout: UserConfirmedWorkout,
        confirmedSleeps: [UserConfirmedSleep],
        now: Date,
        calendar: Calendar = .current
    ) -> Bool {
        guard now >= workout.end else { return false }
        let workoutCycle = AtriaPhysiologicalCycle.current(
            now: workout.start,
            confirmedSleeps: confirmedSleeps,
            calendar: calendar
        )
        guard workoutCycle.boundaryKind != .initialFallback else { return false }
        let currentCycle = AtriaPhysiologicalCycle.current(
            now: now,
            confirmedSleeps: confirmedSleeps,
            calendar: calendar
        )
        return currentCycle.start == workoutCycle.start
            && currentCycle.boundaryKind == workoutCycle.boundaryKind
    }

    static func recoveryAttributionIsPending(
        for workout: UserConfirmedWorkout,
        sleepHistory: SleepHistorySnapshot,
        now: Date,
        calendar: Calendar = .current
    ) -> Bool {
        recoveryAttributionIsPending(
            for: workout,
            confirmedSleeps: compactBoundarySleeps(from: sleepHistory),
            now: now,
            calendar: calendar
        )
    }

    private static func cycle(
        startingAt start: Date,
        displayDay: Date,
        startBoundary: StartBoundary,
        anchor: UserConfirmedSleep,
        eligibleSleeps: [UserConfirmedSleep],
        calendar: Calendar
    ) -> Self {
        let boundaryKind: AtriaPhysiologicalCycle.BoundaryKind = switch startBoundary {
        case .mainSleep: .mainSleep
        case .noSleepFallback: .noSleepFallback
        case .civilDayFallback: .initialFallback
        }
        let fallback = nextFallback(after: start,
                                    boundaryKind: boundaryKind,
                                    anchor: anchor,
                                    calendar: calendar)
        let nextSleep = eligibleSleeps.first { $0.end > start }

        let end: Date
        let endBoundary: EndBoundary
        switch (nextSleep, fallback) {
        case let (sleep?, fallback?) where sleep.end <= fallback:
            end = sleep.end
            endBoundary = .mainSleep(id: sleep.id)
        case let (_, fallback?):
            end = fallback
            endBoundary = .noSleepFallback(anchorSleepID: anchor.id)
        case let (sleep?, nil):
            end = sleep.end
            endBoundary = .mainSleep(id: sleep.id)
        case (nil, nil):
            let civilEnd = calendar.date(byAdding: .day, value: 1, to: displayDay)
                ?? displayDay
            end = max(start, civilEnd)
            endBoundary = .civilDayFallback
        }
        return Self(interval: DateInterval(start: start, end: max(start, end)),
                    displayDay: displayDay,
                    startBoundary: startBoundary,
                    endBoundary: endBoundary)
    }

    private static func noSleepFallback(
        for displayDay: Date,
        eligibleSleeps: [UserConfirmedSleep],
        calendar: Calendar
    ) -> (start: Date, anchor: UserConfirmedSleep)? {
        var selected: (start: Date, anchor: UserConfirmedSleep)?
        for (index, anchor) in eligibleSleeps.enumerated() {
            guard let first = AtriaPhysiologicalCycle.firstNoSleepFallback(
                after: anchor.end,
                eventTimeZoneIdentifier: anchor.eventTimeZoneIdentifier,
                calendar: calendar
            ) else { continue }
            let firstDay = EventCivilTime.day(
                containing: first,
                eventTimeZoneIdentifier: anchor.eventTimeZoneIdentifier,
                outputCalendar: calendar
            )
            let delta = calendar.dateComponents([.day],
                                                from: firstDay,
                                                to: displayDay).day ?? 0
            guard delta >= 0 else { continue }
            let eventCalendar = EventCivilTime.eventCalendar(
                timeZoneIdentifier: anchor.eventTimeZoneIdentifier,
                fallback: calendar
            )
            guard let candidate = eventCalendar.date(byAdding: .day,
                                                      value: delta,
                                                      to: first),
                  calendar.isDate(
                    EventCivilTime.day(
                        containing: candidate,
                        eventTimeZoneIdentifier: anchor.eventTimeZoneIdentifier,
                        outputCalendar: calendar
                    ),
                    inSameDayAs: displayDay
                  ) else { continue }
            let nextMainWake = eligibleSleeps.indices.contains(index + 1)
                ? eligibleSleeps[index + 1].end
                : nil
            if let nextMainWake, candidate >= nextMainWake { continue }
            if let selected, candidate <= selected.start { continue }
            selected = (candidate, anchor)
        }
        return selected
    }

    private static func nextFallback(
        after start: Date,
        boundaryKind: AtriaPhysiologicalCycle.BoundaryKind,
        anchor: UserConfirmedSleep,
        calendar: Calendar
    ) -> Date? {
        switch boundaryKind {
        case .mainSleep:
            return AtriaPhysiologicalCycle.firstNoSleepFallback(
                after: start,
                eventTimeZoneIdentifier: anchor.eventTimeZoneIdentifier,
                calendar: calendar
            )
        case .noSleepFallback:
            let eventCalendar = EventCivilTime.eventCalendar(
                timeZoneIdentifier: anchor.eventTimeZoneIdentifier,
                fallback: calendar
            )
            return eventCalendar.date(byAdding: .day, value: 1, to: start)
        case .initialFallback:
            return nil
        }
    }

    private static func wakeDisplayDay(
        for sleep: UserConfirmedSleep,
        calendar: Calendar
    ) -> Date {
        EventCivilTime.day(containing: sleep.end,
                           eventTimeZoneIdentifier: sleep.eventTimeZoneIdentifier,
                           outputCalendar: calendar)
    }

    private static func compactBoundarySleeps(
        from sleepHistory: SleepHistorySnapshot
    ) -> [UserConfirmedSleep] {
        // `nights` contains the canonical main per wake day and has already
        // combined resumed segments. Additional records are still needed here:
        // an explicit user adjustment must retain the exact same boundary
        // authority as the live cycle. `canonicalMainSleeps` filters resumed
        // rows and the ID map removes the nap duplication in compact fixtures.
        let nightsByID = (sleepHistory.nights
            + sleepHistory.additionalMainNights
            + sleepHistory.napNights).reduce(into: [String: SleepHistorySnapshot.Night]()) {
                $0[$1.id] = $1
            }
        return nightsByID.values.compactMap { night in
            guard night.confirmed,
                  let start = night.start,
                  let end = night.end,
                  end > start else { return nil }
            return UserConfirmedSleep(id: night.id,
                                      createdAt: night.savedAt ?? end,
                                      start: start,
                                      end: end,
                                      source: night.source,
                                      confidence: night.confidence,
                                      sessions: 0,
                                      samples: 0,
                                      avgHR: night.restingHR ?? 0,
                                      peakHR: night.restingHR ?? 0,
                                      restingHR: night.restingHR ?? 0,
                                      hrv: night.hrv,
                                      hrvWindowCount: night.hrvWindowCount,
                                      respiratoryRate: night.respiratoryRate,
                                      duration: night.observedDuration,
                                      span: end.timeIntervalSince(start),
                                      reason: "compact historical physiological boundary",
                                      motionSource: "sleep_history_snapshot",
                                      motionValidated: false,
                                      stageSegments: night.stageSegments,
                                      eventTimeZoneIdentifier: night.eventTimeZoneIdentifier,
                                      sleepNeedSeconds: night.sleepNeedSeconds,
                                      dayPrimaryChoice: night.dayPrimaryChoice)
        }
    }
}

/// The authoritative live "Today" window. Durable history remains keyed by
/// civil date for stable storage and browsing, but live activity is accumulated
/// wake-to-now so midnight cannot erase an awake user's strain, steps, or
/// workouts. Only a completed, confirmed physiological main sleep advances the
/// boundary; naps and an in-progress/unconfirmed night do not.
struct AtriaPhysiologicalDay: Equatable {
    let start: Date
    let end: Date
    let displayDay: Date
    let boundaryKind: AtriaPhysiologicalCycle.BoundaryKind

    static func current(now: Date,
                        confirmedSleeps: [UserConfirmedSleep],
                        calendar: Calendar = .current) -> Self {
        let cycle = AtriaPhysiologicalCycle.current(now: now,
                                                    confirmedSleeps: confirmedSleeps,
                                                    calendar: calendar)
        return Self(start: cycle.start,
                    end: now,
                    displayDay: calendar.startOfDay(for: cycle.start),
                    boundaryKind: cycle.boundaryKind)
    }

    /// Presentation snapshots intentionally retain compact nights rather than
    /// the full durable sleep records. Rehydrate only the boundary fields so
    /// every Today consumer still delegates to `AtriaPhysiologicalCycle`.
    static func current(now: Date,
                        sleepHistory: SleepHistorySnapshot,
                        calendar: Calendar = .current) -> Self {
        let boundarySleeps = (sleepHistory.nights
            + sleepHistory.additionalMainNights
            + sleepHistory.napNights).compactMap { night -> UserConfirmedSleep? in
                guard night.confirmed,
                      let start = night.start,
                      let end = night.end,
                      end > start else { return nil }
                return UserConfirmedSleep(id: night.id,
                                          createdAt: night.savedAt ?? end,
                                          start: start,
                                          end: end,
                                          source: night.source,
                                          confidence: night.confidence,
                                          sessions: 0,
                                          samples: 0,
                                          avgHR: night.restingHR ?? 0,
                                          peakHR: night.restingHR ?? 0,
                                          restingHR: night.restingHR ?? 0,
                                          hrv: night.hrv,
                                          hrvWindowCount: night.hrvWindowCount,
                                          respiratoryRate: night.respiratoryRate,
                                          // `Night.duration` is physiological
                                          // total sleep time once stages exist;
                                          // boundary eligibility still owns the
                                          // independently measured coverage.
                                          duration: night.observedDuration,
                                          span: end.timeIntervalSince(start),
                                          reason: "compact physiological-day boundary",
                                          motionSource: "sleep_history_snapshot",
                                          motionValidated: false,
                                          stageSegments: night.stageSegments,
                                          eventTimeZoneIdentifier: night.eventTimeZoneIdentifier,
                                          sleepNeedSeconds: night.sleepNeedSeconds,
                                          dayPrimaryChoice: night.dayPrimaryChoice)
            }
        return current(now: now, confirmedSleeps: boundarySleeps, calendar: calendar)
    }

    func overlaps(start candidateStart: Date, end candidateEnd: Date) -> Bool {
        candidateEnd > candidateStart && candidateEnd > start && candidateStart < end
    }
}

private struct SavedSessionRespiratoryRateCacheKey: Hashable {
    let id: UUID
    let sessionStart: Date
    let sessionEnd: Date
    let rrCount: Int
    let firstT: Double
    let firstMS: Int
    let lastT: Double
    let lastMS: Int
}

private final class SavedSessionRespiratoryRateCache: @unchecked Sendable {
    private struct Entry {
        let value: Double?
    }

    private let lock = NSLock()
    private var values: [SavedSessionRespiratoryRateCacheKey: Entry] = [:]
    private var order: [SavedSessionRespiratoryRateCacheKey] = []
    private let limit = 512

    func lookup(_ key: SavedSessionRespiratoryRateCacheKey) -> (hit: Bool, value: Double?) {
        lock.lock()
        defer { lock.unlock() }
        guard let entry = values[key] else { return (false, nil) }
        return (true, entry.value)
    }

    func store(_ value: Double?, for key: SavedSessionRespiratoryRateCacheKey) {
        lock.lock()
        defer { lock.unlock() }
        if values[key] == nil {
            order.append(key)
            if order.count > limit {
                let evicted = order.removeFirst()
                values.removeValue(forKey: evicted)
            }
        }
        values[key] = Entry(value: value)
    }
}

private struct SavedSessionLocalHRVCacheKey: Hashable {
    let id: UUID
    let sessionStart: Date
    let sessionEnd: Date
    let rrCount: Int
    let firstT: Double
