        if values[key] == nil {
            order.append(key)
            if order.count > limit {
                values.removeValue(forKey: order.removeFirst())
            }
        }
        values[key] = value
    }
}

enum AtriaSleepSettlementAbort: Error, Equatable, Sendable {
    case deadlineExceeded
}

/// One monotonic deadline shared by compact motion, candidate aggregation,
/// wake detection, HRV/respiration, and stage preparation. Tests may inject a
/// deterministic monotonic clock; production always uses Dispatch uptime.
struct AtriaSleepSettlementDeadline: Sendable {
    let uptimeNanoseconds: UInt64
    private let monotonicNow: @Sendable () -> UInt64

    init(
        uptimeNanoseconds: UInt64,
        monotonicNow: @escaping @Sendable () -> UInt64 = {
            DispatchTime.now().uptimeNanoseconds
        }
    ) {
        self.uptimeNanoseconds = uptimeNanoseconds
        self.monotonicNow = monotonicNow
    }

    @inline(__always)
    func checkpoint() throws {
        if monotonicNow() >= uptimeNanoseconds {
            throw AtriaSleepSettlementAbort.deadlineExceeded
        }
    }

    func capped(afterNanoseconds interval: UInt64) -> Self {
        let now = monotonicNow()
        let local = now.addingReportingOverflow(interval).partialValue
        return .init(
            uptimeNanoseconds: min(uptimeNanoseconds, local),
            monotonicNow: monotonicNow
        )
    }
}

/// A fresh review is selected using the same unstaged metadata as before, then
/// only the winning draft runs the optional research-stage engine. Keeping the
/// exact recipe beside its draft prevents a physiological window from being
/// staged with an aggregate candidate's resting-HR or motion provenance.
private struct AtriaSleepReviewStageRecipe {
    let start: Date
    let end: Date
    let restingHR: Int
    let isNap: Bool
    let motionValidated: Bool
}

private struct AtriaSleepReviewDraft {
    let night: SleepHistorySnapshot.Night
    let stageRecipe: AtriaSleepReviewStageRecipe
}

/// Test-visible evidence that one main-review projection invokes the stage
/// engine once after selection. It is deliberately not a cache and is never
/// installed by production callers.
final class AtriaSleepReviewStageInvocationCounter: @unchecked Sendable {
    private let lock = NSLock()
    private var stageInvocationStorage = 0
    private var physiologicalDraftStorage = 0

    func recordInvocation() {
        lock.lock()
        stageInvocationStorage += 1
        lock.unlock()
    }

    func recordPhysiologicalDraft() {
        lock.lock()
        physiologicalDraftStorage += 1
        lock.unlock()
    }

    var value: Int {
        lock.lock()
        defer { lock.unlock() }
        return stageInvocationStorage
    }

    var physiologicalDraftCount: Int {
        lock.lock()
        defer { lock.unlock() }
        return physiologicalDraftStorage
    }
}

/// Cooperative revocation shared by one sleep-review projection and every
/// checked stage of its work. `DispatchWorkItem.cancel()` is advisory once a
/// block has started; this token makes a scene-background transition visible
/// at the same bounded checkpoints as the monotonic deadline.
final class AtriaSleepReviewProjectionCancellation: @unchecked Sendable {
    private let lock = NSLock()
    private var cancelled = false

    func cancel() {
        lock.lock()
        cancelled = true
        lock.unlock()
    }

    var isCancelled: Bool {
        lock.lock()
        defer { lock.unlock() }
        return cancelled
    }
}

/// Per-settlement spectral kernels for the bounded compact respiratory lane.
/// A 90-second RSA estimate always resamples to at most 361 values, but an
/// all-night candidate evaluates prefixes of that same basis hundreds of
/// times. Computing the identical maximum-length sine/cosine basis once removes
/// tens of millions of repeated transcendental calls without changing the
/// estimator's frequency grid, accumulation order, cadence, or gates.
private struct AtriaCompactRespiratoryKernelBank {
    struct Kernels {
        let cosines: [[Double]]
        let sines: [[Double]]
    }

    static let maximumSampleCount = 361
    private var value: Kernels?

    mutating func kernels(
        cooperativeDeadline: AtriaSleepSettlementDeadline
    ) throws -> Kernels {
        if let value {
            try cooperativeDeadline.checkpoint()
            return value
        }

        var cosines: [[Double]] = []
        var sines: [[Double]] = []
        cosines.reserveCapacity(43)
        sines.reserveCapacity(43)
        let sampleRate = 4.0
        for breathsPerMinute in stride(
            from: 9.0,
            through: 30.0,
            by: 0.5
        ) {
            try cooperativeDeadline.checkpoint()
            let frequency = breathsPerMinute / 60.0
            var cosine: [Double] = []
            var sine: [Double] = []
            cosine.reserveCapacity(Self.maximumSampleCount)
            sine.reserveCapacity(Self.maximumSampleCount)
            for index in 0..<Self.maximumSampleCount {
                if index.isMultiple(of: 256) {
                    try cooperativeDeadline.checkpoint()
                }
                let angle = 2.0 * Double.pi * frequency
                    * Double(index) / sampleRate
                cosine.append(cos(angle))
                sine.append(sin(angle))
            }
            cosines.append(cosine)
            sines.append(sine)
        }
        let kernels = Kernels(cosines: cosines, sines: sines)
        value = kernels
        try cooperativeDeadline.checkpoint()
        return kernels
    }
}

/// A finished heart-rate session, persisted locally (no cloud, no manufacturer account).
struct SavedSession: Codable, Identifiable {
    private static let respiratoryRateCache = SavedSessionRespiratoryRateCache()
    // Same content-keyed cache shape, separate instance: RR-implied median
    // BPM for the workout contact-artifact gate (see rrImpliedMedianBPM).
    private static let rrImpliedMedianCache = SavedSessionRespiratoryRateCache()
    private static let localHRVCache = SavedSessionLocalHRVCache()
    private static let rangeLocalHRVCache = SavedSessionRangeLocalHRVCache()

    let id: UUID
    let start: Date
    let end: Date
    let label: String
    /// (secondsFromStart, bpm) points — compact representation of the HR series.
    let points: [Point]
    /// Representative HRV (RMSSD, ms) for the session, if the realtime channel
    /// produced RR intervals. Optional so older saved sessions still decode.
    var hrv: Int?
    /// True SDNN (ms) from the same RR window that passed external validation.
    /// HealthKit's HRV type is SDNN, while Atria displays RMSSD in-app.
    var hrvSDNN: Double? = nil
    /// Respiratory rate inferred from RR modulation, in breaths per minute.
    /// Optional because older sessions and insufficient RR windows have none.
    var respiratoryRate: Double? = nil
    /// Real decoded RR/IBI intervals received from strap realtime frames during
    /// this saved session. These are preserved for audit/replay, but do not make
    /// HRV clinically usable unless the strict continuity and reference gates pass.
    var rrPoints: [RRPoint]? = nil
    /// True only after this session's RMSSD has been compared against an
    /// external RR/IBI reference within the Gate B tolerance.
    var hrvReferenceValidated: Bool?
    /// Diagnostic-only motion/sleep hints extracted from strap `0x32` text
    /// packets while this session was active. These are not validated IMU
    /// metrics and must not raise sleep confidence by themselves.
    var motionHintCount: Int? = nil
    var motionHintKinds: String? = nil
    var motionEvidenceSource: String? = nil
    var motionEvidenceValidated: Bool? = nil
    /// Numeric `motion_short` values observed in diagnostic `0x32` text packets.
    /// These are stored for audit only and are not treated as validated IMU data.
    var motionShortCount: Int? = nil
    var motionShortMean: Double? = nil
    var motionShortMin: Double? = nil
    var motionShortMax: Double? = nil
    var motionShortOverOneCount: Int? = nil
    /// Research-gated features decoded from strap `0x33` candidate IMU frames.
    /// Raw frames are not stored. These fields stay unvalidated until the strap
    /// IMU layout is proven on-device.
    var imuSampleCount: Int? = nil
    var imuFrameCount: Int? = nil
    var imuSampleRateHz: Double? = nil
    var imuScale: Double? = nil
    var imuEndian: String? = nil
    var imuStillnessRatio: Double? = nil
    var imuMovementIntensity: Double? = nil
    var imuActivityBursts: Int? = nil
    var imuValidationState: String? = nil
    /// Fixed, timestamped features from independently verified historical
    /// gravity rows. Raw frames remain in HistoricalArchive; these compact
    /// epochs preserve only the alignment needed by staging and review.
    var recoveredMotionEpochs: [AtriaRecoveredMotionEpoch]? = nil
    var strapStepResearchCount: Int? = nil
    var strapStepResearchAgreement: Double? = nil
    var strapStepResearchState: String? = nil
    var sleepWakeResearchState: String? = nil
    var sleepWakeResearchConfidence: String? = nil
    var sleepWakeResearchReason: String? = nil
    var sensorResearchProbeFrames: Int? = nil
    var spo2ResearchCandidateFrames: Int? = nil
    var skinTempResearchCandidateFrames: Int? = nil
    var skinTempResearchCandidateValueSum: Int? = nil
    var skinTempResearchCandidateValueCount: Int? = nil
    /// RESEARCH-ONLY SpO2 candidate byte-value capture at the two historical
    /// hypotheses (offsets 64/66). Sum+count so a mean can be computed and
    /// cross-checked against a reference app. Never rendered as an SpO2 value.
    var spo2ResearchCandidateOffset64ValueSum: Int? = nil
    var spo2ResearchCandidateOffset64ValueCount: Int? = nil
    var spo2ResearchCandidateOffset66ValueSum: Int? = nil
    var spo2ResearchCandidateOffset66ValueCount: Int? = nil
    /// Generation/version/provenance-aware Celsius samples produced only by a
    /// calibrated decoder. Raw research candidate words remain separate above
    /// and can never be interpreted as Celsius by session aggregation.
    var decodedSkinTemperatureCelsius: [AtriaResearchProbe.DecodedSkinTemperatureCelsius]? = nil
    /// Biological sex captured with the session so Banister TRIMP can use the
    /// matching published coefficient. Legacy sessions decode as nil and retain
    /// the historical male/unspecified coefficient instead of changing history.
    var biologicalSex: AthleteProfile.BiologicalSex? = nil
    /// Keytel HR->energy estimate persisted with the session when sex and weight
    /// are present. It is an estimate only, never a measured calorie value.
    var activeCalories: Double? = nil
    var caloriesConfidence: String? = nil
    /// Audit-only HR sample attribution for this saved session. These fields
    /// explain coverage gaps; they do not relax workout or HRV gates.
    var hrRaw2A37: Int? = nil
    var hrAccepted: Int? = nil
    var hrZero: Int? = nil
    var hrArtifactHeld: Int? = nil
    var hrArtifactDropped: Int? = nil
    var hrRawGaps: Int? = nil
    var hrAcceptedGaps: Int? = nil
    var hrMaxRawGap: Double? = nil
    var hrMaxAcceptedGap: Double? = nil
    /// Count of realtime frames where the strap's RR/IBI-implied heart rate
    /// disagreed with its own reported bpm by more than the BLE layer's
    /// mismatch threshold (AtriaBLEManager `hr_mismatch`, >30bpm). Audit-only;
    /// reserved for the workout contact-artifact sanity ceiling below. Not yet
    /// populated at finalize (BLE-layer wiring is out of scope for this pass),
    /// so it defaults to nil/0 until that plumbing lands. (2026-07-05)
    var hrRRMismatch: Int? = nil
    /// Strength sets logged during this session. Optional so old archives keep
    /// decoding while the live logger is being rolled in.
    var strengthSets: [LoggedSet]? = nil
    /// Optional session category. `breathwork` preserves HR evidence but is
    /// intentionally excluded from strain/TRIMP.
    var kind: String? = nil
    /// Workout pause spans. Strain/TRIMP and calories must ignore these windows,
    /// while raw HR remains preserved for audit/replay.
    var excludedIntervals: [ExcludedInterval]? = nil
    /// The civil timezone where this event was recorded. Missing/invalid values
    /// retain the legacy behavior of using the caller's current calendar.
    var eventTimeZoneIdentifier: String? = nil

    struct Point: Codable { let t: Double; let bpm: Int }
    struct RRPoint: Codable {
        let t: Double
        let ms: Int
        /// Optional only for decode compatibility. Newly collected intervals
        /// always carry an explicit source; nil legacy values fail metric gates.
        let source: AtriaRRSourceProvenance?

        init(t: Double,
             ms: Int,
             source: AtriaRRSourceProvenance? = nil) {
            self.t = t
            self.ms = ms
            self.source = source
        }
    }

    var duration: TimeInterval { end.timeIntervalSince(start) }
    var bpms: [Int] { points.map(\.bpm) }
    var rrSampleCount: Int { rrPoints?.count ?? 0 }
    var avg: Int {
        guard !bpms.isEmpty else { return 0 }
        return Int((Double(bpms.reduce(0, +)) / Double(bpms.count)).rounded())
    }
    var peak: Int { bpms.max() ?? 0 }
    var resting: Int { bpms.min() ?? 0 }
    var isBreathwork: Bool { kind == "breathwork" || label.localizedCaseInsensitiveContains("breathwork") }
    /// Source-ambiguous legacy and mixed-fallback RR streams remain available
    /// for export/audit, but cannot feed HRV, recovery, respiration, stress, or
    /// breathwork-derived metrics as if they were validated standard 2A37 data.
    var hasQualifiedStandardRRProvenance: Bool {
        guard let rrPoints, !rrPoints.isEmpty else { return false }
        return rrPoints.allSatisfy { $0.source == .standardHeartRateMeasurement2A37 }
    }
    /// Local physiology accepts only independently verified beat transports.
    /// Historical v24 remains explicitly labeled and is never promoted to
    /// standard 2A37 or external-reference validation.
    var hasQualifiedRRProvenance: Bool {
        guard let rrPoints, !rrPoints.isEmpty else { return false }
        return rrPoints.allSatisfy { point in
            point.source == .standardHeartRateMeasurement2A37
                || point.source == .verifiedWhoop4HistoricalV24
        }
    }

    fileprivate func hasQualifiedRRProvenance(
        cooperativeDeadline: AtriaSleepSettlementDeadline
    ) throws -> Bool {
        guard let rrPoints, !rrPoints.isEmpty else { return false }
        for (index, point) in rrPoints.enumerated() {
            if index.isMultiple(of: 256) {
                try cooperativeDeadline.checkpoint()
            }
            if point.source != .standardHeartRateMeasurement2A37,
               point.source != .verifiedWhoop4HistoricalV24 {
                return false
            }
        }
        try cooperativeDeadline.checkpoint()
        return true
    }
    var referenceValidatedHRV: Int? {
        hasQualifiedStandardRRProvenance && hrvReferenceValidated == true ? hrv : nil
    }

    func referenceValidatedHRVCancellable(
        shouldContinue: () -> Bool
    ) -> Int? {
        guard hrvReferenceValidated == true,
              let rrPoints,
              !rrPoints.isEmpty else { return nil }
        for (index, point) in rrPoints.enumerated() {
            if index.isMultiple(of: 256), !shouldContinue() { return nil }
            if point.source != .standardHeartRateMeasurement2A37 { return nil }
        }
        return shouldContinue() ? hrv : nil
    }
    var localRMSSD: Int? {
        guard hasQualifiedRRProvenance else { return nil }
        let summary = localHRVSummary()
        guard summary.windowCount >= 3 else { return nil }
        if let hrv, hrv > 0 { return hrv }
        return summary.rmssd
    }

    func localRMSSDCancellable(
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> Int? {
        guard shouldContinue(),
              let rrPoints,
              rrPoints.count >= Self.minimumQualifiedRRBeatCount() else {
            return nil
        }
        let deadline = AtriaSleepSettlementDeadline(
            uptimeNanoseconds: .max,
            monotonicNow: {
                shouldContinue() ? 0 : UInt64.max
            }
        )
        guard let windows = try? qualifiedLnRMSSDWindows(
            cooperativeDeadline: deadline
        ), windows.count >= 3, shouldContinue() else { return nil }
        if let hrv, hrv > 0 { return hrv }
        let value = Int(exp(Self.median(windows)).rounded())
        return value > 0 ? value : nil
    }

    var localHRVWindowCount: Int {
        localHRVSummary().windowCount
    }

    func localRMSSD(in start: Date, end: Date) -> Int? {
        localHRVSummary(in: start, end: end).rmssd
    }

    func localHRVWindowCount(in start: Date, end: Date) -> Int {
        localHRVSummary(in: start, end: end).windowCount
    }

    /// Checked exact-window counterpart used by recovered baseline rebuilds.
    /// A nil result means authority was revoked; `.empty` remains a successful,
    /// fully inspected window with no qualified RR evidence.
    func localHRVSummaryCancellable(
        in rangeStart: Date,
        end rangeEnd: Date,
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> (rmssd: Int?, windowCount: Int)? {
        guard shouldContinue() else { return nil }
        guard let rrPoints,
              rrPoints.count >= Self.minimumQualifiedRRBeatCount() else {
            return (nil, 0)
        }
        let deadline = AtriaSleepSettlementDeadline(
            uptimeNanoseconds: .max,
            monotonicNow: {
                shouldContinue() ? 0 : UInt64.max
            }
        )
        guard let lnRMSSDs = try? qualifiedLnRMSSDWindows(
            in: rangeStart,
            end: rangeEnd,
            cooperativeDeadline: deadline
        ), shouldContinue() else { return nil }
        let rmssd: Int?
        if lnRMSSDs.count >= 3 {
            let value = Int(exp(Self.median(lnRMSSDs)).rounded())
            rmssd = value > 0 ? value : nil
        } else {
            rmssd = nil
        }
        return (rmssd, lnRMSSDs.count)
    }

    private func localHRVSummary(in rangeStart: Date,
                                 end rangeEnd: Date) -> SavedSessionLocalHRVSummary {
        guard hasQualifiedRRProvenance,
              let rrPoints,
              rrPoints.count >= Self.minimumQualifiedRRBeatCount() else { return .empty }
        let cacheKey = SavedSessionRangeLocalHRVCacheKey(session: localHRVCacheKey(rrPoints: rrPoints),
                                                         rangeStart: rangeStart,
                                                         rangeEnd: rangeEnd)
        if let cached = Self.rangeLocalHRVCache.lookup(cacheKey) {
            return cached
        }
        let lnRMSSDs = qualifiedLnRMSSDWindows(in: rangeStart, end: rangeEnd)
        let rmssd: Int?
        if lnRMSSDs.count >= 3 {
            let value = Int(exp(Self.median(lnRMSSDs)).rounded())
            rmssd = value > 0 ? value : nil
        } else {
            rmssd = nil
        }
        let summary = SavedSessionLocalHRVSummary(rmssd: rmssd, windowCount: lnRMSSDs.count)
        Self.rangeLocalHRVCache.store(summary, for: cacheKey)
        return summary
    }

    private func localHRVSummary() -> SavedSessionLocalHRVSummary {
        guard hasQualifiedRRProvenance,
              let rrPoints,
              rrPoints.count >= Self.minimumQualifiedRRBeatCount() else { return .empty }
        let cacheKey = localHRVCacheKey(rrPoints: rrPoints)
        if let cached = Self.localHRVCache.lookup(cacheKey) {
            return cached
        }
        let lnRMSSDs = qualifiedLnRMSSDWindows()
        let rmssd: Int?
        if lnRMSSDs.count >= 3 {
            let median = Self.median(lnRMSSDs)
            let value = Int(exp(median).rounded())
            rmssd = value > 0 ? value : nil
        } else {
            rmssd = nil
        }
        let summary = SavedSessionLocalHRVSummary(rmssd: rmssd, windowCount: lnRMSSDs.count)
        Self.localHRVCache.store(summary, for: cacheKey)
        return summary
    }

    /// Independently qualified five-minute ln(RMSSD) windows. Callers may
    /// aggregate these scalars across connection-bounded sessions, but must
    /// never concatenate raw RR intervals across a reconnect boundary.
    func qualifiedLnRMSSDWindows(in absoluteStart: Date? = nil,
                                 end absoluteEnd: Date? = nil) -> [Double] {
        // The legacy path is deliberately unlimited. Compact latest-night
        // settlement uses the checked overload below so every RR-row loop
        // shares the worker's single absolute deadline.
        (try? qualifiedLnRMSSDWindowsCore(
            in: absoluteStart,
            end: absoluteEnd,
            cooperativeDeadline: nil
        )) ?? []
    }

    func qualifiedLnRMSSDWindows(
        in absoluteStart: Date? = nil,
        end absoluteEnd: Date? = nil,
        cooperativeDeadline: AtriaSleepSettlementDeadline
    ) throws -> [Double] {
        try qualifiedLnRMSSDWindowsCore(
            in: absoluteStart,
            end: absoluteEnd,
            cooperativeDeadline: cooperativeDeadline
        )
    }

    private func qualifiedLnRMSSDWindowsCore(
        in absoluteStart: Date?,
        end absoluteEnd: Date?,
        cooperativeDeadline: AtriaSleepSettlementDeadline?
    ) throws -> [Double] {
        try cooperativeDeadline?.checkpoint()
        let minimumBeatCount = Self.minimumQualifiedRRBeatCount()
        let provenanceQualified: Bool
        if let cooperativeDeadline {
            provenanceQualified = try hasQualifiedRRProvenance(
                cooperativeDeadline: cooperativeDeadline
            )
        } else {
            provenanceQualified = hasQualifiedRRProvenance
        }
        guard provenanceQualified,
              let rrPoints, rrPoints.count >= minimumBeatCount else { return [] }
        var sorted: [(t: Double, ms: Double)] = []
        sorted.reserveCapacity(rrPoints.count)
        for (index, point) in rrPoints.enumerated() {
            if index.isMultiple(of: 256) {
                try cooperativeDeadline?.checkpoint()
            }
            let absoluteTime = start.addingTimeInterval(max(0, point.t))
            if let absoluteStart, absoluteTime < absoluteStart { continue }
            if let absoluteEnd, absoluteTime > absoluteEnd { continue }
            sorted.append((t: point.t, ms: Double(point.ms)))
        }
        try Self.cooperativeStableSort(
            &sorted,
            cooperativeDeadline: cooperativeDeadline,
            areInIncreasingOrder: { $0.t < $1.t }
        )
        guard sorted.count >= minimumBeatCount else { return [] }

        var segments: [[(t: Double, ms: Double)]] = []
        var current: [(t: Double, ms: Double)] = []
        for (index, point) in sorted.enumerated() {
            if index.isMultiple(of: 256) {
                try cooperativeDeadline?.checkpoint()
            }
            if let last = current.last {
                let gap = point.t - last.t
                if gap <= 0 || gap > HRVSnapshot.maxReadyRRGapSeconds {
                    if current.count >= 2 { segments.append(current) }
                    current.removeAll(keepingCapacity: true)
                }
            }
            current.append(point)
        }
        if current.count >= 2 { segments.append(current) }

        var lnRMSSDs: [Double] = []
        for (segmentIndex, segment) in segments.enumerated() {
            if segmentIndex.isMultiple(of: 16) {
                try cooperativeDeadline?.checkpoint()
            }
            guard let first = segment.first, let final = segment.last,
                  (300...2000).contains(first.ms) else { continue }
            // RR values end at their timestamps. Tile from the beginning of the
            // first measured interval so a true 15-minute low-rate capture has
            // three five-minute windows rather than only two.
            let coverageStart = first.t - first.ms / 1_000
            guard final.t - coverageStart >= 300 else { continue }
            var windowEnd = coverageStart + 300
            let finalEnd = final.t
            var lowerIndex = segment.startIndex
            var upperIndex = segment.startIndex
            while windowEnd <= finalEnd {
                try cooperativeDeadline?.checkpoint()
                let windowStart = windowEnd - 300
                while lowerIndex < segment.endIndex, segment[lowerIndex].t <= windowStart {
                    lowerIndex += 1
                    if lowerIndex.isMultiple(of: 256) {
                        try cooperativeDeadline?.checkpoint()
                    }
                }
                if upperIndex < lowerIndex { upperIndex = lowerIndex }
                while upperIndex < segment.endIndex, segment[upperIndex].t <= windowEnd {
                    upperIndex += 1
                    if upperIndex.isMultiple(of: 256) {
                        try cooperativeDeadline?.checkpoint()
                    }
                }
                let windowCount = upperIndex - lowerIndex
                if cooperativeDeadline != nil, windowCount > 4_096 {
                    windowEnd += 300
                    continue
                }
                let window: [(t: Double, ms: Double)]
                if cooperativeDeadline != nil {
                    var checkedWindow: [(t: Double, ms: Double)] = []
                    checkedWindow.reserveCapacity(windowCount)
                    if lowerIndex < upperIndex {
                        for index in lowerIndex..<upperIndex {
                            if index.isMultiple(of: 256) {
                                try cooperativeDeadline?.checkpoint()
                            }
                            checkedWindow.append(segment[index])
                        }
                    }
                    window = checkedWindow
                } else {
                    window = Array(segment[lowerIndex..<upperIndex])
                }
                if let lnRMSSD = try Self.qualifiedLnRMSSDCore(
                    window,
                    cooperativeDeadline: cooperativeDeadline
                ) {
                    lnRMSSDs.append(lnRMSSD)
                }
                windowEnd += 300
            }
        }
        try cooperativeDeadline?.checkpoint()
        return lnRMSSDs
    }

    private func localHRVCacheKey(rrPoints: [RRPoint]) -> SavedSessionLocalHRVCacheKey {
        let first = rrPoints.first
        let last = rrPoints.last
        return SavedSessionLocalHRVCacheKey(id: id,
                                            sessionStart: start,
                                            sessionEnd: end,
                                            rrCount: rrPoints.count,
                                            firstT: first?.t ?? 0,
                                            firstMS: first?.ms ?? 0,
                                            lastT: last?.t ?? 0,
                                            lastMS: last?.ms ?? 0)
    }

    static func qualifiedLnRMSSD(_ samples: [(t: Double, ms: Double)]) -> Double? {
        try? qualifiedLnRMSSDCore(samples, cooperativeDeadline: nil)
    }

    private static func qualifiedLnRMSSDCore(
        _ samples: [(t: Double, ms: Double)],
        cooperativeDeadline: AtriaSleepSettlementDeadline?
    ) throws -> Double? {
        try cooperativeDeadline?.checkpoint()
        let minimumBeatCount = minimumQualifiedRRBeatCount()
        guard samples.count >= minimumBeatCount,
              let first = samples.first,
              let last = samples.last,
              (300...2000).contains(first.ms),
              // Match the live readiness policy: the measured RR coverage may
              // end just before the wall-clock boundary, but the uncovered tail
              // must remain within the same strict three-second continuity gate.
              last.t - (first.t - first.ms / 1_000)
                >= 300 - HRVSnapshot.maxReadyRRGapSeconds else { return nil }
        for index in 1..<samples.count {
            if index.isMultiple(of: 128) {
                try cooperativeDeadline?.checkpoint()
            }
            let gap = samples[index].t - samples[index - 1].t
            guard gap > 0, gap <= HRVSnapshot.maxReadyRRGapSeconds else { return nil }
        }
        var kept: [(ordinal: Int, value: Double)] = []
        kept.reserveCapacity(samples.count)
        for (index, sample) in samples.enumerated() {
            if index.isMultiple(of: 128) {
                try cooperativeDeadline?.checkpoint()
            }
            guard (300...2000).contains(sample.ms) else { continue }
            let lower = max(samples.startIndex, index - 2)
            let upper = min(samples.index(before: samples.endIndex), index + 2)
            let local = samples[lower...upper].map(\.ms).filter { (300...2000).contains($0) }.sorted()
            if local.count >= 3 {
                let middle = local.count / 2
                let median = local.count.isMultiple(of: 2)
                    ? (local[middle - 1] + local[middle]) / 2
                    : local[middle]
                if median <= 0 || abs(sample.ms - median) / median > 0.20 {
                    continue
                }
            }
            kept.append((ordinal: index, value: sample.ms))
        }
        guard kept.count >= minimumBeatCount,
              Double(kept.count) / Double(samples.count) >= 0.75 else { return nil }
        try cooperativeDeadline?.checkpoint()
        let diffs = AtriaHRVSuccessiveDifferences.adjacentValues(kept)
        let minimumDifferenceCount = max(
            1,
            Int(ceil(Double(max(0, kept.count - 1)) * 0.70))
        )
        guard diffs.count >= minimumDifferenceCount else { return nil }
        var squaredSum = 0.0
        for (index, diff) in diffs.enumerated() {
            if index.isMultiple(of: 128) {
                try cooperativeDeadline?.checkpoint()
            }
            squaredSum += diff * diff
        }
        let rmssd = sqrt(squaredSum / Double(diffs.count))
        return rmssd > 0 ? log(rmssd) : nil
    }

    private static func cooperativeStableSort<Element>(
        _ values: inout [Element],
        cooperativeDeadline: AtriaSleepSettlementDeadline?,
        areInIncreasingOrder: (Element, Element) -> Bool
    ) throws {
        guard values.count > 1 else { return }
        // The bottom-up merge exists solely to expose checkpoints to bounded
        // settlement. Ordinary workout/history replay has no deadline; using
        // the cooperative implementation there copied two full arrays and ran
        // Swift-level merge passes for every readiness window. Instruments
        // found this path at the top of the physical CPU-limit profile.
        guard cooperativeDeadline != nil else {
            values.sort(by: areInIncreasingOrder)
            return
        }
        var source = values
        var destination = values
        var width = 1
        while width < source.count {
            try cooperativeDeadline?.checkpoint()
            var lower = 0
            while lower < source.count {
                let middle = min(lower + width, source.count)
                let upper = min(lower + width + width, source.count)
                var left = lower
                var right = middle
                var output = lower
                while output < upper {
                    if output.isMultiple(of: 256) {
                        try cooperativeDeadline?.checkpoint()
                    }
                    if left < middle,
                       (right >= upper
                        || !areInIncreasingOrder(source[right], source[left])) {
                        destination[output] = source[left]
                        left += 1
                    } else {
                        destination[output] = source[right]
                        right += 1
                    }
                    output += 1
                }
                lower = upper
            }
            swap(&source, &destination)
            width = width > source.count / 2 ? source.count : width * 2
        }
        values = source
        try cooperativeDeadline?.checkpoint()
    }

    private static func minimumQualifiedRRBeatCount(windowSeconds: TimeInterval = 300) -> Int {
        Int(ceil(windowSeconds * HRVSnapshot.minimumReadyBeatsPerSecond))
    }

    private static func median(_ values: [Double]) -> Double {
        let sorted = values.sorted()
        let middle = sorted.count / 2
        if sorted.count.isMultiple(of: 2) {
            return (sorted[middle - 1] + sorted[middle]) / 2
        }
        return sorted[middle]
    }
    func sleepRespiratoryRate(rest: Int, maxHR: Int, calendar: Calendar = .current) -> Double? {
        guard hasQualifiedRRProvenance else { return nil }
        let isSleepEvidence = sleepWakeResearchState == "sleep_research"
            || detectedActivity(rest: rest, maxHR: maxHR, calendar: calendar)?.kind == .sleepCandidate
        guard isSleepEvidence else { return nil }
        if let respiratoryRate, respiratoryRate > 0 {
            return respiratoryRate
        }
        return derivedSleepRespiratoryRateFromRR()
    }

    func sleepRespiratoryRateCancellable(
        rest _: Int,
        maxHR _: Int,
        calendar _: Calendar = .current,
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> Double? {
        guard shouldContinue(), hasQualifiedRRProvenance else { return nil }
        // Recovered publication may not spend an unbounded detector pass to
        // infer that a generic wear session was sleep. A persisted sleep-state
        // marker (or already-frozen respiratory value) is the exact authority;
        // otherwise this metric remains explicitly unavailable.
        guard sleepWakeResearchState == "sleep_research" else { return nil }
        if let respiratoryRate, respiratoryRate > 0 { return respiratoryRate }
        guard let rrPoints, rrPoints.count >= 20 else { return nil }
        let cacheKey = respiratoryRateCacheKey(rrPoints: rrPoints)
        let cached = Self.respiratoryRateCache.lookup(cacheKey)
        if cached.hit { return cached.value }
        var samples: [(t: Date, ms: Double)] = []
        samples.reserveCapacity(rrPoints.count)
        for (index, point) in rrPoints.enumerated() {
            if index.isMultiple(of: 256), !shouldContinue() { return nil }
            let milliseconds = Double(point.ms)
            if (300...2000).contains(milliseconds) {
                samples.append((
                    t: start.addingTimeInterval(point.t),
                    ms: milliseconds
                ))
            }
        }
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &samples,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: { $0.t < $1.t }
        ), samples.count >= 20 else { return nil }
        guard let first = samples.first?.t,
              let last = samples.last?.t,
              last.timeIntervalSince(first) >= 45 else { return nil }
        let maxWindows = 48
        let span = last.timeIntervalSince(first)
        let step = max(30, span / Double(maxWindows))
        var estimates: [Double] = []
        var evaluationTime = first.addingTimeInterval(90)
        while evaluationTime <= last {
            guard shouldContinue() else { return nil }
            if let estimate = AtriaAnalytics.RespRateRsa.estimateCancellable(
                samples: samples,
                now: evaluationTime,
                shouldContinue: shouldContinue
            ) {
                estimates.append(estimate)
            }
            evaluationTime = evaluationTime.addingTimeInterval(step)
        }
        if let estimate = AtriaAnalytics.RespRateRsa.estimateCancellable(
            samples: samples,
            now: last,
            shouldContinue: shouldContinue
        ) {
            estimates.append(estimate)
        }
        guard !estimates.isEmpty,
              AtriaSleepCooperativeAlgorithms.stableSort(
                &estimates,
                shouldContinue: shouldContinue,
                areInIncreasingOrder: <
              ), shouldContinue() else { return nil }
        let middle = estimates.count / 2
        let result = estimates.count.isMultiple(of: 2)
            ? (estimates[middle - 1] + estimates[middle]) / 2
            : estimates[middle]
        guard shouldContinue() else { return nil }
        Self.respiratoryRateCache.store(result, for: cacheKey)
        return result
    }

    private func derivedSleepRespiratoryRateFromRR() -> Double? {
        guard let rrPoints, rrPoints.count >= 20 else { return nil }
        let cacheKey = respiratoryRateCacheKey(rrPoints: rrPoints)
        let cached = Self.respiratoryRateCache.lookup(cacheKey)
        if cached.hit { return cached.value }
        let samples = rrPoints
            .map { (t: start.addingTimeInterval($0.t), ms: Double($0.ms)) }
            .filter { (300...2000).contains($0.ms) }
            .sorted { $0.t < $1.t }
        guard samples.count >= 20 else {
            Self.respiratoryRateCache.store(nil, for: cacheKey)
            return nil
        }
        let estimates = respiratoryRateEstimatesAcrossRRSession(samples)
        guard !estimates.isEmpty else {
            Self.respiratoryRateCache.store(nil, for: cacheKey)
            return nil
        }
        let result = Self.median(estimates)
        Self.respiratoryRateCache.store(result, for: cacheKey)
        return result
    }

    private func respiratoryRateCacheKey(rrPoints: [RRPoint]) -> SavedSessionRespiratoryRateCacheKey {
        let first = rrPoints.first
        let last = rrPoints.last
        return SavedSessionRespiratoryRateCacheKey(id: id,
                                                   sessionStart: start,
                                                   sessionEnd: end,
                                                   rrCount: rrPoints.count,
                                                   firstT: first?.t ?? 0,
                                                   firstMS: first?.ms ?? 0,
                                                   lastT: last?.t ?? 0,
                                                   lastMS: last?.ms ?? 0)
    }

    private func respiratoryRateEstimatesAcrossRRSession(_ samples: [(t: Date, ms: Double)]) -> [Double] {
        guard let first = samples.first?.t,
              let last = samples.last?.t,
              last.timeIntervalSince(first) >= 45 else {
            return []
        }
        let maxWindows = 48
        let span = last.timeIntervalSince(first)
        let step = max(30, span / Double(maxWindows))
        var estimates: [Double] = []
        var evaluationTime = first.addingTimeInterval(90)
        while evaluationTime <= last {
            if let estimate = AtriaAnalytics.RespRateRsa.estimate(samples: samples, now: evaluationTime) {
                estimates.append(estimate)
            }
            evaluationTime = evaluationTime.addingTimeInterval(step)
        }
        if let estimate = AtriaAnalytics.RespRateRsa.estimate(samples: samples, now: last) {
            estimates.append(estimate)
        }
        return estimates
    }
    var referenceValidatedSDNN: Double? {
        guard hasQualifiedStandardRRProvenance,
              hrvReferenceValidated == true else { return nil }
        if let hrvSDNN, hrvSDNN > 0 {
            return hrvSDNN
        }
        // Legacy `hrvReferenceValidated` rows may predate persisted SDNN. Do not
        // reconstruct a HealthKit value across the entire raw session: that path
        // had no validated five-minute boundary, artifact adjacency, or continuity
        // proof. A new external validation can persist a bounded SDNN explicitly.
        return nil
    }
    var motionHintCountValue: Int { motionHintCount ?? 0 }
    var motionHintKindsValue: String {
        let trimmed = (motionHintKinds ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        return trimmed.isEmpty ? "none" : trimmed
    }
    var motionEvidenceSourceValue: String {
        let trimmed = (motionEvidenceSource ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        if !trimmed.isEmpty { return trimmed }
        return motionHintCountValue > 0 ? "diagnostic_observe_only" : "unavailable"
    }
    var motionEvidenceValidatedValue: Bool { motionEvidenceValidated == true }
    var motionShortCountValue: Int { motionShortCount ?? 0 }
    var motionShortOverOneCountValue: Int { motionShortOverOneCount ?? 0 }
    var motionShortMeanValue: Double? { motionShortMean }
    var motionShortMinValue: Double? { motionShortMin }
    var motionShortMaxValue: Double? { motionShortMax }
    var hrRaw2A37Value: Int { hrRaw2A37 ?? 0 }
    var hrAcceptedValue: Int { hrAccepted ?? 0 }
    var hrZeroValue: Int { hrZero ?? 0 }
    var hrArtifactHeldValue: Int { hrArtifactHeld ?? 0 }
    var hrArtifactDroppedValue: Int { hrArtifactDropped ?? 0 }
    var hrRawGapsValue: Int { hrRawGaps ?? 0 }
    var hrAcceptedGapsValue: Int { hrAcceptedGaps ?? 0 }
    var hrMaxRawGapValue: Double { hrMaxRawGap ?? 0 }
    var hrMaxAcceptedGapValue: Double { hrMaxAcceptedGap ?? 0 }
    var hrRRMismatchValue: Int { hrRRMismatch ?? 0 }

    /// More robust resting estimate than the raw min: the 10th percentile, so a
    /// single low blip doesn't define "resting". Used to train the baseline.
    var restingStable: Int {
        percentileHR(0.10)
    }

    /// Gate E/C fallback for RHR: during an HR-only sleep candidate, use the
    /// 5th percentile to approximate resting HR while avoiding a single-sample
    /// minimum. Motion is not decoded yet, so this remains low-confidence sleep.
    var sleepCandidateRestingHR: Int {
        percentileHR(0.05)
    }

    func percentileHRCancellable(
        _ percentile: Double,
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> Int? {
        let deadline = AtriaSleepSettlementDeadline(
            uptimeNanoseconds: .max,
            monotonicNow: { shouldContinue() ? 0 : .max }
        )
        guard let stats = try? cooperativeBPMStats(
            cooperativeDeadline: deadline
        ), !stats.sortedValues.isEmpty, shouldContinue() else { return nil }
        let clamped = min(max(percentile, 0), 1)
        let index = min(
            stats.sortedValues.count - 1,
            max(
                0,
                Int((Double(stats.sortedValues.count - 1) * clamped)
                    .rounded(.down))
            )
        )
        return stats.sortedValues[index]
    }

    private func percentileHR(_ percentile: Double) -> Int {
        guard !bpms.isEmpty else { return 0 }
        let s = bpms.sorted()
        let clamped = min(max(percentile, 0), 1)
        let index = min(s.count - 1, max(0, Int((Double(s.count - 1) * clamped).rounded(.down))))
        return s[index]
    }

    /// Banister TRIMP for this session (input to the strain score).
    func trimp(rest: Int, max: Int) -> Double {
        // Sleep is recovery evidence, not cardiovascular load. Keep this gate at
        // the shared TRIMP boundary so every day-strain consumer agrees. Do not
        // use the broad clock-based overnight predicate here: an early workout is
        // still real strain.
        guard !isBreathwork, sleepWakeResearchState != "sleep_research" else { return 0 }
        let activePoints = AtriaStrengthLog.pointsExcludingIntervals(points,
                                                                     sessionStart: start,
                                                                     excludedIntervals: excludedIntervals)
        let samples = activePoints.map {
            HRSample(t: start.addingTimeInterval(Swift.max(0, $0.t)), bpm: $0.bpm)
        }
        return AtriaAnalytics.Strain.contiguousSegments(samples, excluding: excludedIntervals)
            .reduce(0) { total, segment in
                total + Metrics.trimp(segment.map { (t: $0.t.timeIntervalSince(start), bpm: $0.bpm) },
                                      rest: rest,
                                      max: max,
                                      sex: biologicalSex ?? .unspecified)
            }
    }

    /// TRIMP contributed inside one absolute civil-day interval. Boundary
    /// values are linearly interpolated only when the surrounding real samples
    /// satisfy the shared 15-second load-evidence limit, so splitting a session
    /// at midnight neither loses a valid interval nor invents load across a gap.
    func trimp(rest: Int, max: Int, within interval: DateInterval) -> Double {
        guard !isBreathwork,
              sleepWakeResearchState != "sleep_research",
              interval.end > interval.start,
              end > interval.start,
              start < interval.end else { return 0 }
        let projected = loadPoints(within: interval)
        guard projected.count >= 2 else { return 0 }
        let clippedExclusions = (excludedIntervals ?? []).compactMap { exclusion -> ExcludedInterval? in
            let clippedStart = Swift.max(exclusion.start, interval.start)
            let clippedEnd = Swift.min(exclusion.end, interval.end)
            guard clippedEnd > clippedStart else { return nil }
            return ExcludedInterval(start: clippedStart, end: clippedEnd)
        }
        let samples = projected.map { HRSample(t: $0.date, bpm: $0.bpm) }
        return AtriaAnalytics.Strain.contiguousSegments(samples, excluding: clippedExclusions)
            .reduce(0) { total, segment in
                total + Metrics.trimp(segment.map {
                    (t: $0.t.timeIntervalSince(interval.start), bpm: $0.bpm)
                }, rest: rest, max: max, sex: biologicalSex ?? .unspecified)
            }
    }

    /// All-day cardiovascular load. Unlike workout TRIMP, this excludes the
    /// standard Z0/rest band so ordinary quiet wear cannot accumulate into a
    /// double-digit training day merely through duration.
    func dailyLoadTRIMP(rest: Int, max: Int, within interval: DateInterval) -> Double {
        guard !isBreathwork,
              sleepWakeResearchState != "sleep_research",
              interval.end > interval.start,
              end > interval.start,
              start < interval.end else { return 0 }
        let projected = loadPoints(within: interval)
        guard projected.count >= 2 else { return 0 }
        let clippedExclusions = (excludedIntervals ?? []).compactMap { exclusion -> ExcludedInterval? in
            let clippedStart = Swift.max(exclusion.start, interval.start)
            let clippedEnd = Swift.min(exclusion.end, interval.end)
            guard clippedEnd > clippedStart else { return nil }
            return ExcludedInterval(start: clippedStart, end: clippedEnd)
        }
        let samples = projected.map { HRSample(t: $0.date, bpm: $0.bpm) }
        return AtriaAnalytics.Strain.contiguousSegments(samples, excluding: clippedExclusions)
            .reduce(0) { total, segment in
                total + Metrics.dailyLoadTRIMP(segment.map {
                    (t: $0.t.timeIntervalSince(interval.start), bpm: $0.bpm)
                }, rest: rest, max: max, sex: biologicalSex ?? .unspecified)
            }
    }

    /// Recovered-derived load walk. Every archive-sized materialization,
    /// ordering pass, segment walk and integration batch shares the exact
    /// ticket checkpoint (and therefore the BG duty cycle when applicable).
    func dailyLoadTRIMPCancellable(
        rest: Int,
        max: Int,
        within interval: DateInterval,
        shouldContinue: () -> Bool
    ) -> Double? {
        guard shouldContinue() else { return nil }
        guard !isBreathwork,
              sleepWakeResearchState != "sleep_research",
              interval.end > interval.start,
              end > interval.start,
              start < interval.end else { return 0 }
        guard let projected = loadPointsCancellable(
            within: interval,
            shouldContinue: shouldContinue
        ) else { return nil }
        guard projected.count >= 2 else { return 0 }
        var clippedExclusions: [ExcludedInterval] = []
        for (index, exclusion) in (excludedIntervals ?? []).enumerated() {
            if index.isMultiple(of: 64), !shouldContinue() { return nil }
            let clippedStart = Swift.max(exclusion.start, interval.start)
            let clippedEnd = Swift.min(exclusion.end, interval.end)
            if clippedEnd > clippedStart {
                clippedExclusions.append(.init(
                    start: clippedStart,
                    end: clippedEnd
                ))
            }
        }
        var samples: [HRSample] = []
        samples.reserveCapacity(projected.count)
        for (index, point) in projected.enumerated() {
            if index.isMultiple(of: 256), !shouldContinue() { return nil }
            samples.append(.init(t: point.date, bpm: point.bpm))
        }
        guard let segments = AtriaAnalytics.Strain.contiguousSegments(
            samples,
            excluding: clippedExclusions,
            shouldContinue: shouldContinue
        ) else { return nil }
        let parameters = AtriaAnalytics.Strain.banisterParameters(
            for: biologicalSex ?? .unspecified
        )
        let configuration = AtriaStrainLoadModel.Configuration(
            restingBPM: Double(rest),
            maximumBPM: Double(max),
            intensityMultiplier: parameters.multiplier,
            intensityCoefficient: parameters.coefficient,
            mode: .continuousDay,
            maximumGap: AtriaAnalytics.Strain.maximumLoadEvidenceGap
        )
        var total = 0.0
        for (segmentIndex, segment) in segments.enumerated() {
            if segmentIndex.isMultiple(of: 8), !shouldContinue() { return nil }
            var accumulator = AtriaStrainLoadModel.Accumulator(
                configuration: configuration
            )
            for (pointIndex, point) in segment.enumerated() {
                if pointIndex.isMultiple(of: 256), !shouldContinue() {
                    return nil
                }
                accumulator.append(.init(
                    timestamp: point.t.timeIntervalSince(interval.start),
                    bpm: Double(point.bpm)
                ))
            }
            total += accumulator.result.load
        }
        return shouldContinue() ? total : nil
    }

    /// The exact pause-aware, civil-day load evidence used by strain
    /// validation. Keeping zones and TRIMP on one projection prevents the
    /// diagnostic from counting a whole cross-midnight session on its start
    /// day or treating a recorded pause as cardiovascular exposure.
    func strainValidationLoad(rest: Int,
                              max: Int,
                              within interval: DateInterval) -> (zones: Metrics.StrainZoneSummary,
                                                                 trimp: Double) {
        guard !isBreathwork,
              sleepWakeResearchState != "sleep_research",
              interval.end > interval.start,
              end > interval.start,
              start < interval.end else { return (.empty, 0) }
        let projected = loadPoints(within: interval)
        guard projected.count >= 2 else { return (.empty, 0) }
        let clippedExclusions = (excludedIntervals ?? []).compactMap { exclusion -> ExcludedInterval? in
            let clippedStart = Swift.max(exclusion.start, interval.start)
            let clippedEnd = Swift.min(exclusion.end, interval.end)
            guard clippedEnd > clippedStart else { return nil }
            return ExcludedInterval(start: clippedStart, end: clippedEnd)
        }
        let samples = projected.map { HRSample(t: $0.date, bpm: $0.bpm) }
        let segments = AtriaAnalytics.Strain.contiguousSegments(samples,
                                                                 excluding: clippedExclusions)
        let zones = segments.reduce(Metrics.StrainZoneSummary.empty) { total, segment in
            total + Metrics.strainZoneSummary(segment.map {
                (t: $0.t.timeIntervalSince(interval.start), bpm: $0.bpm)
            }, rest: rest, max: max)
        }
        let trimp = segments.reduce(0.0) { total, segment in
            total + Metrics.trimp(segment.map {
                (t: $0.t.timeIntervalSince(interval.start), bpm: $0.bpm)
            }, rest: rest, max: max, sex: biologicalSex ?? .unspecified)
        }
        return (zones, trimp)
    }

    /// Conservatively attributes an aggregate session step count to an
    /// interval when historical records lack per-step timestamps. Cumulative
    /// floor differencing conserves the exact session total across adjacent
    /// day slices and avoids counting the whole session on both days.
    func attributedStrapSteps(within interval: DateInterval) -> Int {
        let total = max(0, strapStepResearchCount ?? 0)
        let sessionDuration = end.timeIntervalSince(start)
        guard total > 0, sessionDuration > 0 else { return 0 }
        let clippedStart = Swift.max(start, interval.start)
        let clippedEnd = Swift.min(end, interval.end)
        guard clippedEnd > clippedStart else { return 0 }
        let startFraction = min(max(clippedStart.timeIntervalSince(start) / sessionDuration, 0), 1)
        let endFraction = min(max(clippedEnd.timeIntervalSince(start) / sessionDuration, 0), 1)
        return max(0, Int(floor(Double(total) * endFraction))
            - Int(floor(Double(total) * startFraction)))
    }

    private func loadPoints(within interval: DateInterval) -> [(date: Date, bpm: Int)] {
        let ordered = points.compactMap { point -> (date: Date, bpm: Int)? in
            guard point.bpm > 0 else { return nil }
            return (start.addingTimeInterval(max(0, point.t)), point.bpm)
        }.sorted { $0.date < $1.date }
        guard !ordered.isEmpty else { return [] }

        var result = ordered.filter { $0.date >= interval.start && $0.date <= interval.end }
        if let boundary = interpolatedLoadPoint(at: interval.start, in: ordered),
           result.first?.date != interval.start {
            result.insert(boundary, at: 0)
        }
        if let boundary = interpolatedLoadPoint(at: interval.end, in: ordered),
           result.last?.date != interval.end {
            result.append(boundary)
        }
        return result
    }

    private func loadPointsCancellable(
        within interval: DateInterval,
        shouldContinue: () -> Bool
    ) -> [(date: Date, bpm: Int)]? {
        guard shouldContinue() else { return nil }
        var ordered: [(date: Date, bpm: Int)] = []
        ordered.reserveCapacity(points.count)
        for (index, point) in points.enumerated() {
            if index.isMultiple(of: 256), !shouldContinue() { return nil }
            guard point.bpm > 0 else { continue }
            ordered.append((
                start.addingTimeInterval(max(0, point.t)),
                point.bpm
            ))
        }
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &ordered,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: { $0.date < $1.date }
        ) else { return nil }
        guard !ordered.isEmpty else { return [] }
        var result: [(date: Date, bpm: Int)] = []
        for (index, point) in ordered.enumerated() {
            if index.isMultiple(of: 256), !shouldContinue() { return nil }
            if point.date >= interval.start, point.date <= interval.end {
                result.append(point)
            }
        }
        // Boundary interpolation remains two bounded binary searches rather
        // than the legacy pair of full `first/last(where:)` corpus walks.
        func boundaryPoint(
            at boundary: Date
        ) -> (date: Date, bpm: Int)? {
            var lower = 0
            var upper = ordered.count
            var visits = 0
            while lower < upper {
                visits += 1
                if visits.isMultiple(of: 16), !shouldContinue() { return nil }
                let middle = lower + (upper - lower) / 2
                if ordered[middle].date < boundary {
                    lower = middle + 1
                } else {
                    upper = middle
                }
            }
            if lower < ordered.count, ordered[lower].date == boundary {
                return ordered[lower]
            }
            guard lower > 0, lower < ordered.count else { return nil }
            let previous = ordered[lower - 1]
            let next = ordered[lower]
            let span = next.date.timeIntervalSince(previous.date)
            guard span > 0,
                  span <= AtriaAnalytics.Strain.maximumLoadEvidenceGap else {
                return nil
            }
            let fraction = boundary.timeIntervalSince(previous.date) / span
            return (
                boundary,
                Int((Double(previous.bpm)
                    + Double(next.bpm - previous.bpm) * fraction).rounded())
            )
        }
        guard shouldContinue() else { return nil }
        if let boundary = boundaryPoint(at: interval.start),
           result.first?.date != interval.start {
            result.insert(boundary, at: 0)
        }
        guard shouldContinue() else { return nil }
        if let boundary = boundaryPoint(at: interval.end),
           result.last?.date != interval.end {
            result.append(boundary)
        }
        return shouldContinue() ? result : nil
    }

    private func interpolatedLoadPoint(at boundary: Date,
                                       in ordered: [(date: Date, bpm: Int)]) -> (date: Date, bpm: Int)? {
        if let exact = ordered.first(where: { $0.date == boundary }) { return exact }
        guard let previous = ordered.last(where: { $0.date < boundary }),
              let next = ordered.first(where: { $0.date > boundary }) else { return nil }
        let span = next.date.timeIntervalSince(previous.date)
        guard span > 0, span <= AtriaAnalytics.Strain.maximumLoadEvidenceGap else { return nil }
        let fraction = boundary.timeIntervalSince(previous.date) / span
        let bpm = Int((Double(previous.bpm) + Double(next.bpm - previous.bpm) * fraction).rounded())
        return (boundary, bpm)
    }

    /// Seconds spent in each HR zone, given a max-HR setting.
    func timeInZone(maxHR: Int, restingHR: Int? = nil) -> [HRZone: Double] {
        let activePoints = AtriaStrengthLog.pointsExcludingIntervals(points,
                                                                     sessionStart: start,
                                                                     excludedIntervals: excludedIntervals)
        let samples = activePoints.map {
            HRSample(t: start.addingTimeInterval(max(0, $0.t)), bpm: $0.bpm)
        }
        let summary = AtriaAnalytics.Strain.contiguousSegments(samples, excluding: excludedIntervals)
            .reduce(AtriaAnalytics.Strain.MaxHeartRateZoneSeconds.empty) { total, segment in
                total + AtriaAnalytics.Strain.maxHeartRateZoneSeconds(
                    segment.map { (t: $0.t.timeIntervalSince(start), bpm: $0.bpm) },
                    maxHR: maxHR,
                    restingHR: restingHR
                )
            }
        guard !summary.isEmpty else { return [:] }
        var out: [HRZone: Double] = [:]
        for zone in HRZone.allCases {
            let seconds = summary.seconds(forZoneRawValue: zone.rawValue)
            if seconds > 0 {
                out[zone] = seconds
            }
        }
        return out
    }

    func activeCalories(rest: Int, profile: AthleteProfile) -> Double? {
        guard !isBreathwork, sleepWakeResearchState != "sleep_research" else { return nil }
        let samples = points.map { point in
            HRSample(t: start.addingTimeInterval(max(0, point.t)), bpm: point.bpm)
        }
        let activeSamples = AtriaStrengthLog.samplesExcludingIntervals(samples,
                                                                       excludedIntervals: excludedIntervals)
        let segmentCalories = AtriaAnalytics.Strain
            .contiguousSegments(activeSamples, excluding: excludedIntervals)
            .compactMap { Metrics.activeCalories($0, rest: rest, profile: profile) }
        guard !segmentCalories.isEmpty else { return nil }
        return segmentCalories.reduce(0, +)
    }

    /// Active-energy estimate contributed inside one physiological-day slice.
    /// This uses the same interpolated, gap-bounded and pause-aware point
    /// projection as TRIMP so a cross-boundary session is neither dropped nor
    /// counted twice. `nil` means the athlete profile cannot support energy
    /// estimation; a genuine zero remains a valid, publishable estimate.
    func activeCalories(rest: Int,
                        profile: AthleteProfile,
                        within interval: DateInterval) -> Double? {
        guard !isBreathwork,
              sleepWakeResearchState != "sleep_research",
              profile.hasEnergyProfile,
              interval.end > interval.start,
              end > interval.start,
              start < interval.end else { return nil }
        let projected = loadPoints(within: interval)
        guard projected.count >= 2 else { return nil }
        let clippedExclusions = (excludedIntervals ?? []).compactMap { exclusion -> ExcludedInterval? in
            let clippedStart = Swift.max(exclusion.start, interval.start)
            let clippedEnd = Swift.min(exclusion.end, interval.end)
            guard clippedEnd > clippedStart else { return nil }
            return ExcludedInterval(start: clippedStart, end: clippedEnd)
        }
        let samples = projected.map { HRSample(t: $0.date, bpm: $0.bpm) }
        let segmentCalories = AtriaAnalytics.Strain
            .contiguousSegments(samples, excluding: clippedExclusions)
            .compactMap { Metrics.activeCalories($0, rest: rest, profile: profile) }
        guard !segmentCalories.isEmpty else { return nil }
        return segmentCalories.reduce(0, +)
    }

    var durationText: String {
        let s = Int(duration)
        return s >= 60 ? "\(s/60)m \(s%60)s" : "\(s)s"
    }
}

