    let reason: String
    var activityType: String? = nil
    var activitySubtype: String? = nil
    var exerciseNames: [String]? = nil
    var strengthSets: [LoggedSet]? = nil
    /// Frozen qualified muscular-input receipt. Nil means this workout was
