struct BehaviorCorrelationSummary: Equatable {
    let tag: BehaviorJournalEntry.Tag
    let days: Int
    let recoveryDelta: Double?
    let hrvDelta: Double?
    /// Assessment P1.9 (2026-08-14): tags pair to measured signals first.
    /// Raw-signed Δ mean overnight RHR (bpm) on tagged vs untagged days.
    let rhrDelta: Double?

    var recoveryText: String {
        recoveryDelta.map { String(format: "%+.0f%%", $0) } ?? "Learning"
    }

    var hrvText: String {
        hrvDelta.map { String(format: "%+.0f ms", $0) } ?? "Learning"
    }

    var rhrText: String {
        rhrDelta.map { String(format: "%+.0f bpm", $0) } ?? "Learning"
    }

    var detail: String {
        guard recoveryDelta != nil || hrvDelta != nil || rhrDelta != nil else {
            return "\(days) tagged days"
        }
        return "\(days) tagged days · local correlation"
    }

    // Assessment P1.9: measured signals (HRV, then RHR) lead the copy so an
    // insight survives a Recovery model bump; the composite is secondary.
    var impactMetricText: String {
        if hrvDelta != nil { return "HRV" }
        if rhrDelta != nil { return "RHR" }
        if recoveryDelta != nil { return "Recovery" }
        return "Logs"
    }

    var impactValueText: String {
        if let hrvDelta {
            return String(format: "%+.0f ms", hrvDelta)
        }
        if let rhrDelta {
            return String(format: "%+.0f bpm", rhrDelta)
        }
        if let recoveryDelta {
            return String(format: "%+.0f%%", recoveryDelta)
        }
        return "\(days)d"
    }

    /// GOODNESS-signed for direction consumers: a lower RHR is supportive, so
    /// the RHR lane inverts its raw sign here while display text stays raw.
    var impactDelta: Double? {
        hrvDelta ?? rhrDelta.map { -$0 } ?? recoveryDelta
    }

    var impactMagnitude: Double {
        abs(impactDelta ?? 0)
    }

    var impactProgress: Double {
        min(max(impactMagnitude / 10, 0), 1)
    }

    var impactDirectionSymbol: String {
        guard let impactDelta, impactDelta != 0 else { return "circle.dotted" }
        return impactDelta > 0 ? "arrow.right" : "arrow.left"
    }

    var impactToneText: String {
        guard let impactDelta, impactDelta != 0 else { return "Learning" }
        return impactDelta > 0 ? "Linked up" : "Linked down"
    }
}

/// A plain-language, effect-size-ranked finding derived from behavior tags vs
/// recovery/HRV. Confidence-gated (needs enough tagged days); never medical.
struct AtriaInsight: Identifiable, Equatable {
    enum Metric { case recovery, hrv, rhr }
    let id: String
    let tagLabel: String
    let metric: Metric
    let delta: Double        // recovery: % points; hrv: ms; rhr: bpm (raw sign)
    let days: Int

    /// Rank key: bigger absolute effect first.
    var magnitude: Double { abs(delta) }

    /// Assessment P1.9: goodness is metric-aware — a LOWER resting HR on
    /// tagged days is the supportive direction.
    var isPositive: Bool { metric == .rhr ? delta <= 0 : delta >= 0 }

    var headline: String {
        let dir = delta < 0 ? "lower" : "higher"
        let n = abs(Int(delta.rounded()))
        switch metric {
        case .recovery: return "Recovery \(n)% \(dir)"
        case .hrv: return "HRV \(n) ms \(dir)"
        case .rhr: return "RHR \(n) bpm \(dir)"
        }
    }

    var detail: String {
        "On \(days) \(tagLabel.lowercased()) day\(days == 1 ? "" : "s")"
    }
}

struct ResearchManeuverMarker: Codable, Identifiable, Equatable {
    enum Kind: String, Codable, CaseIterable, Identifiable {
        case breathHold
        case heatExposure
        case coldExposure
        case walkTest

        var id: String { rawValue }

        var label: String {
            switch self {
            case .breathHold: return "Breath hold"
            case .heatExposure: return "Mild warm condition"
            case .coldExposure: return "Mild cool condition"
            case .walkTest: return "Walk test"
            }
        }

        var shortLabel: String {
            switch self {
            case .breathHold: return "Breath"
            case .heatExposure: return "Warm"
            case .coldExposure: return "Cool"
            case .walkTest: return "Walk"
            }
        }

        var systemImage: String {
            switch self {
            case .breathHold: return "lungs.fill"
            case .heatExposure: return "thermometer.sun.fill"
            case .coldExposure: return "snowflake"
            case .walkTest: return "figure.walk.motion"
            }
        }
    }

    let id: String
    let kind: Kind
    let timestamp: Date
    let createdAt: Date
}

struct IMUAuditSummary: Equatable {
    struct SkinTemperatureDeviationSummary: Equatable {
        let latestDeltaCelsius: Double?
        let baselineSessions: Int
        let candidateFrames: Int
        let candidateValues: Int

        var valueText: String {
            guard let latestDeltaCelsius else { return "--" }
            return String(format: "%+.1f", latestDeltaCelsius)
        }

        var detailText: String {
            guard latestDeltaCelsius != nil else {
                if baselineSessions >= 3 {
                    return "\(baselineSessions) baseline nights · next sleep unlocks"
                }
                if baselineSessions > 0 {
                    return "\(baselineSessions) of 3 baseline nights"
                }
                if candidateFrames > 0 {
                    return "\(candidateFrames) candidates · baseline needed"
                }
                // Plain-language pass (2026-07-31 device review): "Sleep
                // signal" beside "--" explained nothing. Say what unlocks it.
                return "Needs 3 nights of sleep data"
            }
            return "vs sleep baseline"
        }

        var footnoteText: String {
            guard latestDeltaCelsius != nil else {
                if baselineSessions > 0 {
                    return "Relative sleep baseline building from \(baselineSessions) qualified night\(baselineSessions == 1 ? "" : "s"); no absolute temperature."
                }
                if candidateFrames > 0 {
                    return "\(candidateFrames) candidate frames; relative baseline building, no absolute temperature."
                }
                return "Sleep-only signal; no absolute temperature."
            }
            if baselineSessions > 0 {
                return "Relative sleep-only deviation from \(baselineSessions) prior local sessions; no absolute temperature."
            }
            return "Relative sleep-only deviation from a persisted qualified sleep baseline; no absolute temperature."
        }

        var isReady: Bool {
            latestDeltaCelsius != nil
        }
    }

    let frameCount: Int
    let sampleCount: Int
    let validatedFrames: Int
    let sampleRateHz: Double?
    let scale: Double?
    let endian: String?
    let strapStepCount: Int
    let agreement: Double?
    let sleepWakeState: String?
    let sleepWakeReason: String?
    let probeFrameCount: Int
    let spo2CandidateFrames: Int
    let skinTempCandidateFrames: Int
    let skinTemperatureDeviation: SkinTemperatureDeviationSummary

    init(sessions: [SavedSession],
         activeSessionID: UUID? = nil) {
        let imuSessions = sessions.filter { ($0.imuFrameCount ?? 0) > 0 || ($0.imuSampleCount ?? 0) > 0 }
        let probeSessions = sessions.filter { ($0.sensorResearchProbeFrames ?? 0) > 0 }
        let sleepTemperatureSessions = Self.sleepTemperatureSessions(from: sessions)
        let finalizedSleepTemperatureSessions: [SkinTemperatureSession]
        if let activeSessionID {
            finalizedSleepTemperatureSessions = sleepTemperatureSessions.filter { $0.id != activeSessionID }
        } else {
            finalizedSleepTemperatureSessions = sleepTemperatureSessions
        }
        frameCount = imuSessions.reduce(0) { $0 + ($1.imuFrameCount ?? 0) }
        sampleCount = imuSessions.reduce(0) { $0 + ($1.imuSampleCount ?? 0) }
        validatedFrames = imuSessions.filter { $0.imuValidationState == "gravity_validated_research" }.reduce(0) { $0 + ($1.imuFrameCount ?? 0) }
        let rates = imuSessions.compactMap(\.imuSampleRateHz)
        sampleRateHz = rates.isEmpty ? nil : rates.reduce(0, +) / Double(rates.count)
        scale = imuSessions.compactMap(\.imuScale).last
        endian = imuSessions.compactMap(\.imuEndian).last
        strapStepCount = imuSessions.reduce(0) { $0 + ($1.strapStepResearchCount ?? 0) }
        let agreements = imuSessions.compactMap(\.strapStepResearchAgreement)
        agreement = agreements.isEmpty ? nil : agreements.reduce(0, +) / Double(agreements.count)
        sleepWakeState = imuSessions.compactMap(\.sleepWakeResearchState).first
        sleepWakeReason = imuSessions.compactMap(\.sleepWakeResearchReason).first
        probeFrameCount = probeSessions.reduce(0) { $0 + ($1.sensorResearchProbeFrames ?? 0) }
        spo2CandidateFrames = probeSessions.reduce(0) { $0 + ($1.spo2ResearchCandidateFrames ?? 0) }
        skinTempCandidateFrames = probeSessions.reduce(0) { $0 + ($1.skinTempResearchCandidateFrames ?? 0) }
        skinTemperatureDeviation = Self.makeSkinTemperatureDeviationSummary(
            sleepTemperatureSessions: finalizedSleepTemperatureSessions,
            candidateFrames: skinTempCandidateFrames,
            candidateValues: sleepTemperatureSessions.reduce(0) { $0 + $1.values })
    }

    var frameText: String {
        frameCount > 0 ? "\(frameCount)" : "--"
    }

    var sampleRateText: String {
        sampleRateHz.map { String(format: "%.1f", $0) } ?? "--"
    }

    var layoutText: String {
        guard let scale, let endian, !endian.isEmpty else { return "--" }
        return "\(endian.prefix(1))/\(Int(scale.rounded()))"
    }

    var gravityText: String {
        guard frameCount > 0 else { return "--" }
        return validatedFrames > 0 ? "Seen" : "Waiting"
    }

    var strapStepText: String {
        strapStepCount > 0 ? "\(strapStepCount)" : "--"
    }

    var agreementText: String {
        strapStepCount > 0 ? "Strap IMU" : "Strap pending"
    }

    var sleepWakeText: String {
        guard let sleepWakeState else { return "--" }
        return sleepWakeState == "sleep_research" ? "Sleep" : "Wake"
    }

    var probeText: String {
        probeFrameCount > 0 ? "\(probeFrameCount)" : "--"
    }

    var probeDetail: String {
        probeFrameCount > 0 ? "O2 \(spo2CandidateFrames) · temp \(skinTempCandidateFrames)" : "none yet"
    }

    private struct SkinTemperatureSession {
        let id: UUID
        let start: Date
        let meanCelsius: Double
        let values: Int
    }

    private static func sleepTemperatureSessions(from sessions: [SavedSession]) -> [SkinTemperatureSession] {
        sessions
            .filter { $0.sleepWakeResearchState == "sleep_research" }
            .compactMap { session -> SkinTemperatureSession? in
                let samples = session.decodedSkinTemperatureCelsius?.filter(\.isAggregationEligible)
                guard let samples,
                      !samples.isEmpty else { return nil }
                return SkinTemperatureSession(id: session.id,
                                              start: session.start,
                                              meanCelsius: samples.reduce(0) { $0 + $1.celsius }
                                                / Double(samples.count),
                                              values: samples.count)
            }
            .sorted { $0.start < $1.start }
    }

    private static func makeSkinTemperatureDeviationSummary(sleepTemperatureSessions: [SkinTemperatureSession],
                                                            candidateFrames: Int,
                                                            candidateValues: Int) -> SkinTemperatureDeviationSummary {
        guard let latest = sleepTemperatureSessions.last else {
            return SkinTemperatureDeviationSummary(latestDeltaCelsius: nil,
                                                   baselineSessions: 0,
                                                   candidateFrames: candidateFrames,
                                                   candidateValues: candidateValues)
        }
        let baseline = sleepTemperatureSessions.dropLast()
        guard baseline.count >= 3 else {
            return SkinTemperatureDeviationSummary(latestDeltaCelsius: nil,
                                                   baselineSessions: baseline.count,
                                                   candidateFrames: candidateFrames,
                                                   candidateValues: candidateValues)
        }
        let baselineMean = baseline.reduce(0) { $0 + $1.meanCelsius } / Double(baseline.count)
        return SkinTemperatureDeviationSummary(latestDeltaCelsius: latest.meanCelsius - baselineMean,
                                               baselineSessions: baseline.count,
                                               candidateFrames: candidateFrames,
                                               candidateValues: candidateValues)
    }
}

struct ResearchManeuverProbeCorrelationSummary: Equatable {
    let markerCount: Int
    let matchedMarkers: Int
    let probeFrames: Int
    let oxygenCandidateFrames: Int
    let temperatureCandidateFrames: Int
    private static let correlationWindow: TimeInterval = 15 * 60

    init(markers: [ResearchManeuverMarker], sessions: [SavedSession]) {
        markerCount = markers.count
        var matchedIDs = Set<String>()
        var probeTotal = 0
        var oxygenTotal = 0
        var temperatureTotal = 0

        for marker in markers {
            let matchingSessions = sessions.filter { session in
                guard (session.sensorResearchProbeFrames ?? 0) > 0 else { return false }
                let lower = session.start.addingTimeInterval(-Self.correlationWindow)
                let upper = session.end.addingTimeInterval(Self.correlationWindow)
                return marker.timestamp >= lower && marker.timestamp <= upper
            }

            guard !matchingSessions.isEmpty else { continue }
            matchedIDs.insert(marker.id)
            probeTotal += matchingSessions.reduce(0) { $0 + ($1.sensorResearchProbeFrames ?? 0) }
            oxygenTotal += matchingSessions.reduce(0) { $0 + ($1.spo2ResearchCandidateFrames ?? 0) }
            temperatureTotal += matchingSessions.reduce(0) { $0 + ($1.skinTempResearchCandidateFrames ?? 0) }
        }

        matchedMarkers = matchedIDs.count
        probeFrames = probeTotal
        oxygenCandidateFrames = oxygenTotal
        temperatureCandidateFrames = temperatureTotal
    }

    var matchText: String {
        markerCount == 0 ? "--" : "\(matchedMarkers)/\(markerCount)"
    }

    var candidateText: String {
        probeFrames > 0 ? "O2 \(oxygenCandidateFrames) · temp \(temperatureCandidateFrames)" : "waiting"
    }
}

