private struct WorkoutReplaySummary {
    private static let reviewMinimumObservedDuration: TimeInterval = 15 * 60
    private static let reviewMinimumCoveragePercent = 40
    private static let gappedReviewMinimumObservedDuration: TimeInterval = 12 * 60
    private static let gappedReviewMinimumAverageOverRest = 35
    private static let gappedReviewMinimumP95OverRest = 40
    private static let gappedReviewMinimumPeakOverRest = 55
    private static let gappedReviewMinimumPeakAboveAverage = 20
    private static let reviewMinimumPeakOverRest = 45
    private static let reviewMinimumP95OverRest = 35
    private static let reviewMinimumModerateStrengthPeakOverRest = 35
    private static let reviewMinimumModerateStrengthP95OverRest = 30
    private static let reviewMinimumElevatedSeconds: TimeInterval = 4 * 60
    private static let reviewMinimumElevatedBout: TimeInterval = 90
    private static let reviewMinimumBorderlineSeconds: TimeInterval = 5 * 60
    private static let reviewMinimumBorderlineBout: TimeInterval = 90

    let rawSessions: Int
    let canonicalSessions: Int
    let sessionsEvaluated: Int
    let readySessions: Int
    let bestSource: String
    let bestChunkCount: Int
    let bestStart: Date?
    let bestEnd: Date?
    let bestSpan: TimeInterval
    let bestLabel: String
    let bestStatus: String
    let bestReason: String
    let bestDuration: TimeInterval
    let bestObservedDuration: TimeInterval
    let bestSamples: Int
    let bestAvgHR: Int
    let bestPeakHR: Int
    let bestP95HR: Int
    let bestP99HR: Int
    let bestThresholdHR: Int
    let bestThresholdGapBPM: Int
    let bestSamplesAboveThreshold: Int
    let bestSamplesAboveBorderline: Int
    let bestElevatedSeconds: TimeInterval
    let bestRequiredElevatedSeconds: TimeInterval
    let bestLongestBout: TimeInterval
    let bestRequiredBout: TimeInterval
    let bestElevatedFraction: Double
    let bestBorderlineThresholdHR: Int
    let bestBorderlineElevatedSeconds: TimeInterval
    let bestBorderlineLongestBout: TimeInterval
    let bestDroppedGapSeconds: TimeInterval
    let bestMaxSampleGap: TimeInterval
    let bestGapCount: Int
    let bestStreamCoveragePercent: Int
    let bestPrimaryBlocker: String
    let bestHRRaw2A37: Int
    let bestHRAccepted: Int
    let bestHRZero: Int
    let bestHRArtifactHeld: Int
    let bestHRArtifactDropped: Int
    let bestHRRawGaps: Int
    let bestHRAcceptedGaps: Int
    let bestHRMaxRawGap: TimeInterval
    let bestHRMaxAcceptedGap: TimeInterval
    let bestHRRRMismatch: Int
    /// Contact-artifact hardening carried counters (2026-07-05), mirroring
    /// WorkoutReadiness's own fields for the winning single-session/aggregate
    /// candidate. See SavedSession.hrContactCompromised/hrRRDisagreesWithReportedHR.
    let bestContactQualifiedElevatedSeconds: TimeInterval
    let bestContactQualifiedLongestBout: TimeInterval
    let bestContactCompromised: Bool
    let bestRRDisagreement: Bool
    let restHR: Int
    let maxHR: Int

    var bestHasBlockingStreamGap: Bool {
        bestPrimaryBlocker.contains("stream_gaps") || bestStreamCoveragePercent < 75
    }

    var bestHRDistributionBelowWorkoutBand: Bool {
        guard bestSamples > 0, bestThresholdHR > 0 else { return false }
        return bestP95HR < bestThresholdHR && bestElevatedSeconds < 60
    }

    var profileMaxHRForBestP95AtHRR50: Int {
        Self.profileMaxHRForHRR50Threshold(rest: restHR, targetHR: bestP95HR)
    }

    var profileMaxHRForBestP99AtHRR50: Int {
        Self.profileMaxHRForHRR50Threshold(rest: restHR, targetHR: bestP99HR)
    }

    var profileMaxHRForBestPeakAtHRR50: Int {
        Self.profileMaxHRForHRR50Threshold(rest: restHR, targetHR: bestPeakHR)
    }

    var p99ProfileMaxHRGap: Int {
        max(0, maxHR - profileMaxHRForBestP99AtHRR50)
    }

    var nearMiss: Bool {
        guard bestStatus != "ready" else { return false }
        let enoughObservedData = bestObservedDuration >= 15 * 60
        let enoughSparseCoverageToInspect = bestStreamCoveragePercent >= Self.reviewMinimumCoveragePercent
        let closeToThreshold = bestThresholdGapBPM <= 5 || bestElevatedSeconds > 0
        return enoughObservedData && enoughSparseCoverageToInspect && closeToThreshold
    }

    var nearMissReason: String {
        guard nearMiss else { return "none" }
        var reasons: [String] = []
        if bestHasBlockingStreamGap {
            reasons.append("stream_coverage_low")
        }
        if bestThresholdGapBPM > 0 {
            reasons.append("peak_within_\(bestThresholdGapBPM)_bpm_below_threshold")
        }
        if bestElevatedSeconds < bestRequiredElevatedSeconds {
            reasons.append("elevated_seconds_below_required")
        }
        if bestLongestBout < bestRequiredBout {
            reasons.append("continuous_bout_below_required")
        }
        return reasons.isEmpty ? "near_miss_low_confidence" : reasons.joined(separator: "+")
    }

    var strengthCandidate: Bool {
        guard bestStatus != "ready" else { return false }
        // Contact-artifact hardening: mirrors WorkoutReadiness.strengthCandidate
        // -- a compromised stream or RR-contradicts-reported-HR candidate must
        // never source a strength candidate, even diagnostically.
        guard !bestContactCompromised, !bestRRDisagreement else { return false }
        guard bestObservedDuration >= Self.reviewMinimumObservedDuration,
              bestStreamCoveragePercent >= Self.reviewMinimumCoveragePercent else { return false }
        let closeToWorkoutBand = bestThresholdGapBPM <= 5 || bestElevatedSeconds > 0
        let hasStrengthEffort = bestPeakHR - restHR >= Self.reviewMinimumPeakOverRest
            || bestP95HR - restHR >= Self.reviewMinimumP95OverRest
        let hasBorderlineEvidence = bestBorderlineElevatedSeconds >= Self.reviewMinimumBorderlineSeconds
            && bestBorderlineLongestBout >= Self.reviewMinimumBorderlineBout
        return closeToWorkoutBand && hasStrengthEffort && hasBorderlineEvidence
    }

    var moderateStrengthReviewCandidate: Bool {
        guard bestStatus != "ready" else { return false }
        guard !bestContactCompromised, !bestRRDisagreement else { return false }
        guard bestObservedDuration >= Self.reviewMinimumObservedDuration,
              bestStreamCoveragePercent >= Self.reviewMinimumCoveragePercent else { return false }
        return bestPeakHR - restHR >= Self.reviewMinimumModerateStrengthPeakOverRest
            && bestP95HR - restHR >= Self.reviewMinimumModerateStrengthP95OverRest
    }

    var gappedStrengthReviewCandidate: Bool {
        guard bestStatus != "ready", !strengthCandidate, !moderateStrengthReviewCandidate else { return false }
        guard bestHasBlockingStreamGap, !bestContactCompromised, !bestRRDisagreement else { return false }
        guard bestObservedDuration >= Self.gappedReviewMinimumObservedDuration,
              bestObservedDuration < Self.reviewMinimumObservedDuration,
              bestStreamCoveragePercent >= Self.reviewMinimumCoveragePercent else { return false }
        let strongDistribution = bestAvgHR - restHR >= Self.gappedReviewMinimumAverageOverRest
            && bestP95HR - restHR >= Self.gappedReviewMinimumP95OverRest
            && bestPeakHR - restHR >= Self.gappedReviewMinimumPeakOverRest
            && bestPeakHR - bestAvgHR >= Self.gappedReviewMinimumPeakAboveAverage
        let sustained = bestContactQualifiedElevatedSeconds >= Self.reviewMinimumElevatedSeconds
            && bestContactQualifiedLongestBout >= Self.reviewMinimumElevatedBout
            && bestBorderlineElevatedSeconds >= Self.reviewMinimumBorderlineSeconds
            && bestBorderlineLongestBout >= Self.reviewMinimumBorderlineBout
        return strongDistribution && sustained
    }

    var strengthCandidateReason: String {
        guard strengthCandidate || moderateStrengthReviewCandidate || gappedStrengthReviewCandidate else { return "none" }
        var reasons = ["diagnostic_only"]
        if bestHasBlockingStreamGap {
            reasons.append("stream_gaps_prevent_count")
        }
        if bestThresholdGapBPM > 0 {
            reasons.append("peak_within_\(bestThresholdGapBPM)_bpm_below_hrr50")
        }
        if bestBorderlineElevatedSeconds > 0 {
            reasons.append("borderline_hr_band_\(Int(bestBorderlineElevatedSeconds.rounded()))s")
        }
        if bestElevatedSeconds < bestRequiredElevatedSeconds {
            reasons.append("workout_band_time_insufficient")
        }
        if bestLongestBout < bestRequiredBout {
            reasons.append("continuous_bout_insufficient")
        }
        if moderateStrengthReviewCandidate && !strengthCandidate {
            reasons.append("moderate_strength_review")
        }
        if gappedStrengthReviewCandidate {
            reasons.append("strong_gapped_effort_review")
        }
        return reasons.joined(separator: "+")
    }

    var bestReviewWorthyCandidate: Bool {
        guard bestStatus != "ready" else { return true }
        // Contact-artifact hardening: never promote a compromised stream or an
        // RR-contradicts-reported-HR candidate to a review-worthy prompt.
        guard !bestContactCompromised, !bestRRDisagreement else { return false }
        if gappedStrengthReviewCandidate { return true }
        guard bestObservedDuration >= Self.reviewMinimumObservedDuration,
              bestStreamCoveragePercent >= Self.reviewMinimumCoveragePercent else { return false }
        if nearMiss {
            return (bestContactQualifiedElevatedSeconds >= Self.reviewMinimumElevatedSeconds
                    && bestContactQualifiedLongestBout >= Self.reviewMinimumElevatedBout)
                || strengthCandidate
        }
        if strengthCandidate {
            return bestBorderlineElevatedSeconds >= Self.reviewMinimumBorderlineSeconds
                && bestBorderlineLongestBout >= Self.reviewMinimumBorderlineBout
        }
        if moderateStrengthReviewCandidate {
            // Contact-artifact alignment (2026-07-06 false-positive pass):
            // mirror the nearMiss branch above -- a moderate-strength signal
            // must carry at least some contact-qualified sustained effort to
            // surface a workout review prompt. Previously this branch returned
            // review-worthy on HR thresholds alone, so ordinary daily HR
            // elevation (stairs, a stressful meeting) with no sustained
            // contact-qualified bout could nag as a possible workout -- the
            // "randomly classifies activity as a workout" the owner reported.
            return bestContactQualifiedElevatedSeconds >= Self.reviewMinimumElevatedSeconds
                && bestContactQualifiedLongestBout >= Self.reviewMinimumElevatedBout
        }
        return false
    }

    var bestNextAction: String {
        if bestStatus == "ready" { return "count_workout" }
        if strengthCandidate || moderateStrengthReviewCandidate || gappedStrengthReviewCandidate {
            return "observe_strength_signal_without_counting_and_validate_hr_reference"
        }
        let hasStreamGap = bestHasBlockingStreamGap
        let needsHRReference = bestPeakHR < bestThresholdHR
        if hasStreamGap && needsHRReference {
            return "fix_stream_continuity_and_validate_intensity"
        }
        if hasStreamGap {
            return "fix_stream_continuity_before_counting"
        }
        if needsHRReference {
            return "validate_intensity_with_reference_or_profile"
        }
        if bestHRDistributionBelowWorkoutBand {
            return "validate_wrist_hr_underreporting_or_profile_before_more_workouts"
        }
        if bestElevatedSeconds < bestRequiredElevatedSeconds || bestLongestBout < bestRequiredBout {
            return "keep_learning_until_sustained_hr"
        }
        return "inspect_detector_inputs"
    }

    private static func profileMaxHRForHRR50Threshold(rest: Int, targetHR: Int) -> Int {
        guard targetHR > rest else { return rest }
        return rest + (2 * (targetHR - rest))
    }

    static func empty(rest: Int, maxHR: Int) -> WorkoutReplaySummary {
        WorkoutReplaySummary(rawSessions: 0,
                             canonicalSessions: 0,
                             sessionsEvaluated: 0,
                             readySessions: 0,
                             bestSource: "none",
                             bestChunkCount: 0,
                             bestStart: nil,
                             bestEnd: nil,
                             bestSpan: 0,
                             bestLabel: "none",
                             bestStatus: "learning",
                             bestReason: "no_saved_session",
                             bestDuration: 0,
                             bestObservedDuration: 0,
                             bestSamples: 0,
                             bestAvgHR: 0,
                             bestPeakHR: 0,
                             bestP95HR: 0,
                             bestP99HR: 0,
                             bestThresholdHR: 0,
                             bestThresholdGapBPM: 0,
                             bestSamplesAboveThreshold: 0,
                             bestSamplesAboveBorderline: 0,
                             bestElevatedSeconds: 0,
                             bestRequiredElevatedSeconds: 0,
                             bestLongestBout: 0,
                             bestRequiredBout: 0,
                             bestElevatedFraction: 0,
                             bestBorderlineThresholdHR: 0,
                             bestBorderlineElevatedSeconds: 0,
                             bestBorderlineLongestBout: 0,
                             bestDroppedGapSeconds: 0,
                             bestMaxSampleGap: 0,
                             bestGapCount: 0,
                             bestStreamCoveragePercent: 0,
                             bestPrimaryBlocker: "no_saved_session",
                             bestHRRaw2A37: 0,
                             bestHRAccepted: 0,
                             bestHRZero: 0,
                             bestHRArtifactHeld: 0,
                             bestHRArtifactDropped: 0,
                             bestHRRawGaps: 0,
                             bestHRAcceptedGaps: 0,
                             bestHRMaxRawGap: 0,
                             bestHRMaxAcceptedGap: 0,
                             bestHRRRMismatch: 0,
                             bestContactQualifiedElevatedSeconds: 0,
                             bestContactQualifiedLongestBout: 0,
                             bestContactCompromised: false,
                             bestRRDisagreement: false,
                             restHR: rest,
                             maxHR: maxHR)
    }
}

