/// Small reusable serial worker whose low-priority requests collapse to the
/// newest snapshot. The lock protects only the pending slot; expensive work is
/// always performed on `queue`, so callers never wait for JSON/file work.
/// Required requests (manual backup and restore safety copies) remain FIFO and
/// are never discarded.
final class AtriaCoalescingSerialWorker<Input: Sendable, Output: Sendable>: @unchecked Sendable {
    typealias Completion = @Sendable (Output) -> Void

    private let queue: DispatchQueue
    private let perform: @Sendable (Input) -> Output
    private let stateLock = NSLock()
    private var pendingLatest: (input: Input, completions: [Completion])?
    private var latestDrainScheduled = false

    init(label: String,
         qos: DispatchQoS = .utility,
         perform: @escaping @Sendable (Input) -> Output) {
        queue = DispatchQueue(label: label, qos: qos)
        self.perform = perform
    }

    func enqueueLatest(_ input: Input, completion: @escaping Completion) {
        stateLock.lock()
        if var pendingLatest {
            pendingLatest.input = input
            pendingLatest.completions.append(completion)
            self.pendingLatest = pendingLatest
        } else {
            pendingLatest = (input, [completion])
        }
        let shouldSchedule = !latestDrainScheduled
        latestDrainScheduled = true
        stateLock.unlock()

        if shouldSchedule {
            queue.async { [weak self] in self?.drainOneLatest() }
        }
    }

    func enqueueRequired(_ input: Input, completion: @escaping Completion) {
        queue.async { [perform] in
            completion(perform(input))
        }
    }

    /// Async bridge for required FIFO work. Callers can await durable utility-
    /// queue completion without blocking MainActor or opening a second queue
    /// that could reorder backup/restore operations.
    func performAsync(_ input: Input) async -> Output {
        await withCheckedContinuation { continuation in
            enqueueRequired(input) { output in
                continuation.resume(returning: output)
            }
        }
    }

    func performSynchronously(_ input: Input) -> Output {
        queue.sync { perform(input) }
    }

    /// Finish every required/in-flight/coalesced operation already accepted by
    /// this worker. Restore blocks new producers before awaiting this boundary,
    /// so an older archive cannot land after the canonical restore archive.
    /// Pending completions are preserved: silently cancelling one could strand
    /// an iOS background task waiting for durable-backup acknowledgement.
    func fence() async {
        await withCheckedContinuation { continuation in
            queue.async { [weak self] in
                self?.drainLatestForFence()
                continuation.resume()
            }
        }
    }

    private func drainLatestForFence() {
        while true {
            stateLock.lock()
            guard let work = pendingLatest else {
                latestDrainScheduled = false
                stateLock.unlock()
                return
            }
            pendingLatest = nil
            stateLock.unlock()

            let output = perform(work.input)
            work.completions.forEach { $0(output) }
        }
    }

    private func drainOneLatest() {
        stateLock.lock()
        guard let work = pendingLatest else {
            latestDrainScheduled = false
            stateLock.unlock()
            return
        }
        pendingLatest = nil
        stateLock.unlock()

        let output = perform(work.input)
        work.completions.forEach { $0(output) }

        stateLock.lock()
        let hasPending = pendingLatest != nil
        if !hasPending {
            latestDrainScheduled = false
        }
        stateLock.unlock()

        // Enqueue a new block instead of looping in place. This preserves FIFO
        // service for a required/manual request that arrived during the write.
        if hasPending {
            queue.async { [weak self] in self?.drainOneLatest() }
        }
    }
}

/// FIFO async mutex used by the confirmed-record stores. Callers never block
/// MainActor while a previous JSON/file transaction is in flight, but every
/// mutation observes and rebases onto the last durably published snapshot.
@MainActor
final class AtriaConfirmedRecordTransactionGate {
    private var isHeld = false
    private var waiters: [CheckedContinuation<Void, Never>] = []

    var hasActiveOwner: Bool { isHeld }

    func acquire() async {
        guard isHeld else {
            isHeld = true
            return
        }
        await withCheckedContinuation { continuation in
            waiters.append(continuation)
        }
    }

    func release() {
        guard !waiters.isEmpty else {
            isHeld = false
            return
        }
        waiters.removeFirst().resume()
    }
}

enum AtriaConfirmedRecordWriteRequest: @unchecked Sendable {
    case loadWorkouts(
        fileURL: URL,
        defaultsKey: String
    )
    case loadSleeps(
        defaultsKey: String
    )
    case workouts(
        generation: UInt64,
        records: [UserConfirmedWorkout],
        fileURL: URL,
        defaultsKey: String
    )
    case sleeps(
        generation: UInt64,
        records: [UserConfirmedSleep],
        defaultsKey: String
    )
}

enum AtriaConfirmedRecordWriteResult: @unchecked Sendable {
    case loadedWorkouts([UserConfirmedWorkout])
    case loadedSleeps([UserConfirmedSleep])
    case workouts(
        generation: UInt64,
        records: [UserConfirmedWorkout],
        bytes: Int,
        mirrorSucceeded: Bool
    )
    case sleeps(
        generation: UInt64,
        records: [UserConfirmedSleep],
        bytes: Int
    )
    case failure(generation: UInt64, domain: String, reason: String)
}

/// Performs confirmed workout/sleep encoding and persistence on one required
/// FIFO utility lane. The persisted wire format remains the original raw
/// Codable array. Workout files remain authoritative; defaults are a mirror.
enum AtriaConfirmedRecordWriter {
    nonisolated static func write(
        _ request: AtriaConfirmedRecordWriteRequest
    ) -> AtriaConfirmedRecordWriteResult {
        let encoder = JSONEncoder()
        switch request {
        case .loadWorkouts(let fileURL, let defaultsKey):
            let data = (try? Data(contentsOf: fileURL))
                ?? UserDefaults.standard.data(forKey: defaultsKey)
            guard let data else { return .loadedWorkouts([]) }
            guard let decoded = try? JSONDecoder().decode([UserConfirmedWorkout].self, from: data) else {
                return .failure(generation: 0,
                                domain: "workouts",
                                reason: "authoritative_decode_failed")
            }
            return .loadedWorkouts(decoded.sorted { $0.start > $1.start })

        case .loadSleeps(let defaultsKey):
            guard let data = UserDefaults.standard.data(forKey: defaultsKey) else {
                return .loadedSleeps([])
            }
            guard let decoded = try? JSONDecoder().decode([UserConfirmedSleep].self, from: data) else {
                return .failure(generation: 0,
                                domain: "sleeps",
                                reason: "authoritative_decode_failed")
            }
            return .loadedSleeps(decoded.sorted { $0.start > $1.start })

        case .workouts(let generation, let records, let fileURL, let defaultsKey):
            let sorted = records.sorted { $0.start > $1.start }
            do {
                let data = try encoder.encode(sorted)
                try data.write(to: fileURL, options: .atomic)
                guard (try? Data(contentsOf: fileURL)) == data else {
                    return .failure(generation: generation,
                                    domain: "workouts",
                                    reason: "authoritative_readback_mismatch")
                }
                UserDefaults.standard.set(data, forKey: defaultsKey)
                let mirrorSucceeded = UserDefaults.standard.data(forKey: defaultsKey) == data
                return .workouts(generation: generation,
                                 records: sorted,
                                 bytes: data.count,
                                 mirrorSucceeded: mirrorSucceeded)
            } catch {
                return .failure(generation: generation,
                                domain: "workouts",
                                reason: String(describing: error))
            }

        case .sleeps(let generation, let records, let defaultsKey):
            let sorted = records.sorted { $0.start > $1.start }
            do {
                let data = try encoder.encode(sorted)
                UserDefaults.standard.set(data, forKey: defaultsKey)
                guard UserDefaults.standard.data(forKey: defaultsKey) == data else {
                    return .failure(generation: generation,
                                    domain: "sleeps",
                                    reason: "defaults_readback_mismatch")
                }
                return .sleeps(generation: generation,
                               records: sorted,
                               bytes: data.count)
            } catch {
                return .failure(generation: generation,
                                domain: "sleeps",
                                reason: String(describing: error))
            }
        }
    }
}

private struct SessionBackupWriteRequest: @unchecked Sendable {
    let label: String
    let sessions: [SavedSession]
    let baseline: PersonalBaseline
    let profile: AthleteProfile
    let dailyMetrics: [SavedDailyMetric]
    let dailyRollups: [DailyRollupStoreEntry]
    let confirmedSleeps: [UserConfirmedSleep]
    let confirmedWorkouts: [UserConfirmedWorkout]
    let backupDirectory: URL
    let mirrorsToICloud: Bool
}

private struct SessionBackupWriteResult: @unchecked Sendable {
    let url: URL?
    let status: SessionBackupStatus
    let label: String
    let sessions: Int
}

/// Pure filesystem/encoding side of a backup. Its request contains immutable
/// value snapshots captured on MainActor; no SessionStore state is touched here.
private enum SessionBackupWriter {
    nonisolated static func write(_ request: SessionBackupWriteRequest) -> SessionBackupWriteResult {
        let rrSamples = request.sessions.reduce(0) { $0 + $1.rrSampleCount }
        // HR/RR export rows are a deterministic rendering of SavedSession and
        // used to duplicate every sample as strings inside every generation.
        // Schema 4 made this section optional; exports are regenerated from the
        // canonical sessions after restore.
        let envelope = SessionBackupEnvelope(schema: 4,
                                             createdAt: Date(),
                                             app: "Atria.local",
                                             sessions: request.sessions,
                                             baseline: request.baseline,
                                             profile: request.profile,
                                             dailyMetrics: request.dailyMetrics,
                                             dailyRollups: request.dailyRollups,
                                             confirmedSleeps: request.confirmedSleeps,
                                             confirmedWorkouts: request.confirmedWorkouts,
                                             rawExport: nil)
        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .iso8601
        encoder.outputFormatting = [.prettyPrinted, .sortedKeys]

        do {
            let data = try encoder.encode(envelope)
            // A failed/oversized compression is a failed backup. Publishing an
            // uncompressed fallback can exceed the importer ceiling and create
            // a huge file that can never be restored.
            let encodedBackup = try AtriaBackupCompression.compressedArchiveData(from: data)
            try FileManager.default.createDirectory(at: request.backupDirectory,
                                                    withIntermediateDirectories: true)
            let safeLabel = request.label.replacingOccurrences(of: "[^A-Za-z0-9_-]",
                                                               with: "-",
                                                               options: .regularExpression)
            let filename = "atria-sessions-\(timestamp())-\(safeLabel).json.gz"
            let backupURL = request.backupDirectory.appendingPathComponent(filename)
            try writeDurable(encodedBackup, to: backupURL)
            guard try Data(contentsOf: backupURL) == encodedBackup else {
                try? FileManager.default.removeItem(at: backupURL)
                throw CocoaError(.fileWriteUnknown)
            }
            let digest = contentDigest(request) ?? "error"
            AtriaDebugLog("ATRIADBG session_backup path=%@ sessions=%d rollups=%d confirmed_sleeps=%d confirmed_workouts=%d rr_samples=%d raw_export_embedded=0 motion_short_samples=%d hr_raw_2a37=%d hr_accepted=%d hr_raw_gaps=%d hr_accepted_gaps=%d bytes=%d raw_bytes=%d schema=%d compressed=1 digest=%@",
                          relativePath(for: backupURL),
                          request.sessions.count,
                          request.dailyRollups.count,
                          request.confirmedSleeps.count,
                          request.confirmedWorkouts.count,
                          rrSamples,
                          request.sessions.reduce(0) { $0 + $1.motionShortCountValue },
                          request.sessions.reduce(0) { $0 + $1.hrRaw2A37Value },
                          request.sessions.reduce(0) { $0 + $1.hrAcceptedValue },
                          request.sessions.reduce(0) { $0 + $1.hrRawGapsValue },
                          request.sessions.reduce(0) { $0 + $1.hrAcceptedGapsValue },
                          encodedBackup.count,
                          data.count,
                          envelope.schema,
                          digest)
            pruneAutomaticBackups(in: request.backupDirectory, keep: 3)
            if request.mirrorsToICloud {
                mirrorToICloud(backupURL)
            } else {
                AtriaDebugLog("ATRIADBG session_backup_icloud status=skipped_toggle path=%@",
                              relativePath(for: backupURL))
            }
            let status = SessionBackupStatus(available: true,
                                             current: true,
                                             path: relativePath(for: backupURL),
                                             sessions: request.sessions.count,
                                             rrSamples: rrSamples,
                                             bytes: data.count,
                                             reason: "current")
            return SessionBackupWriteResult(url: backupURL,
                                            status: status,
                                            label: request.label,
                                            sessions: request.sessions.count)
        } catch {
            AtriaDebugLog("ATRIADBG session_backup_error error=%@", String(describing: error))
            return SessionBackupWriteResult(url: nil,
                                            status: SessionBackupStatus(available: false,
                                                                        current: false,
                                                                        path: "none",
                                                                        sessions: request.sessions.count,
                                                                        rrSamples: rrSamples,
                                                                        bytes: 0,
                                                                        reason: "write_error"),
                                            label: request.label,
                                            sessions: request.sessions.count)
        }
    }

    private nonisolated static func contentDigest(_ request: SessionBackupWriteRequest) -> String? {
        let content = SessionBackupContentFingerprint(schema: 3,
                                                      app: "Atria.local",
                                                      sessions: request.sessions,
                                                      baseline: request.baseline,
                                                      profile: request.profile,
                                                      dailyMetrics: request.dailyMetrics,
                                                      dailyRollups: request.dailyRollups,
                                                      confirmedSleeps: request.confirmedSleeps,
                                                      confirmedWorkouts: request.confirmedWorkouts)
        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .iso8601
        encoder.outputFormatting = [.sortedKeys]
        guard let data = try? encoder.encode(content) else { return nil }
        return SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
    }

    private nonisolated static func writeDurable(_ data: Data, to url: URL) throws {
        try data.write(to: url, options: .atomic)
        let handle = try FileHandle(forWritingTo: url)
        defer { try? handle.close() }
        try handle.synchronize()
        let directory = url.deletingLastPathComponent()
        let descriptor = open(directory.path, O_RDONLY | O_DIRECTORY)
        guard descriptor >= 0 else {
            throw POSIXError(POSIXErrorCode(rawValue: errno) ?? .EIO)
        }
        defer { close(descriptor) }
        guard fsync(descriptor) == 0 else {
            throw POSIXError(POSIXErrorCode(rawValue: errno) ?? .EIO)
        }
    }

    private nonisolated static func relativePath(for url: URL) -> String {
        "Documents/\(url.deletingLastPathComponent().lastPathComponent)/\(url.lastPathComponent)"
    }

    private nonisolated static func timestamp() -> String {
        let formatter = DateFormatter()
        formatter.calendar = Calendar(identifier: .gregorian)
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.timeZone = TimeZone(secondsFromGMT: 0)
        formatter.dateFormat = "yyyyMMdd'T'HHmmss'Z'"
        return formatter.string(from: Date())
    }

    private nonisolated static func isBackupFile(_ url: URL) -> Bool {
        url.pathExtension == "json" || url.pathExtension == "gz"
    }

    private nonisolated static func pruneAutomaticBackups(in directory: URL, keep: Int) {
        guard let files = try? FileManager.default.contentsOfDirectory(at: directory,
                                                                       includingPropertiesForKeys: nil,
                                                                       options: [.skipsHiddenFiles])
            .filter(isBackupFile) else { return }
        let automatic = files
            .filter { $0.deletingPathExtension().lastPathComponent.contains("-auto-") }
            .sorted { $0.lastPathComponent > $1.lastPathComponent }
        for file in automatic.dropFirst(max(0, keep)) {
            try? FileManager.default.removeItem(at: file)
        }
    }

    nonisolated static func prunePreRestoreBackups(in directory: URL, keep: Int) {
        guard let files = try? FileManager.default.contentsOfDirectory(
            at: directory,
            includingPropertiesForKeys: [.contentModificationDateKey],
            options: [.skipsHiddenFiles]
        ) else { return }
        let safety = files
            .filter { url in
                guard isBackupFile(url) else { return false }
                return url.deletingPathExtension().deletingPathExtension().lastPathComponent
                    .hasSuffix("-pre-restore")
            }
            .sorted { lhs, rhs in
                let left = (try? lhs.resourceValues(forKeys: [.contentModificationDateKey]))?.contentModificationDate
                    ?? .distantPast
                let right = (try? rhs.resourceValues(forKeys: [.contentModificationDateKey]))?.contentModificationDate
                    ?? .distantPast
                if left != right { return left > right }
                return lhs.lastPathComponent > rhs.lastPathComponent
            }
        for file in safety.dropFirst(max(0, keep)) {
            try? FileManager.default.removeItem(at: file)
        }
    }

    private nonisolated static func mirrorToICloud(_ backupURL: URL) {
        guard let container = FileManager.default.url(forUbiquityContainerIdentifier: nil) else {
            AtriaDebugLog("ATRIADBG session_backup_icloud status=unavailable path=%@",
                          relativePath(for: backupURL))
            return
        }
        let directory = container
            .appendingPathComponent("Documents")
            .appendingPathComponent("Atria Backups")
        do {
            try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
            let destination = directory.appendingPathComponent(backupURL.lastPathComponent)
            if FileManager.default.fileExists(atPath: destination.path) {
                try FileManager.default.removeItem(at: destination)
            }
            try FileManager.default.copyItem(at: backupURL, to: destination)
            pruneAutomaticBackups(in: directory, keep: 3)
            AtriaDebugLog("ATRIADBG session_backup_icloud status=ok path=Documents/Atria Backups/%@",
                          destination.lastPathComponent)
        } catch {
            AtriaDebugLog("ATRIADBG session_backup_icloud status=error error=%@", String(describing: error))
        }
    }
}

private struct SessionBackupContentFingerprint: Codable {
    let schema: Int
    let app: String
    let sessions: [SavedSession]
    let baseline: PersonalBaseline
    let profile: AthleteProfile
    let dailyMetrics: [SavedDailyMetric]?
    let dailyRollups: [DailyRollupStoreEntry]?
    let confirmedSleeps: [UserConfirmedSleep]?
    let confirmedWorkouts: [UserConfirmedWorkout]?
}

/// Immutable MainActor snapshot consumed by the serial backup I/O worker.
/// Value models in this file predate strict Sendable annotations, so the
/// boundary is explicitly unchecked and never mutates captured values.
private struct SessionBackupIOSnapshot: @unchecked Sendable {
    /// MainActor monotonic identity for every canonical destination included in
    /// this snapshot. A restore prepared from an older identity must be
    /// re-merged before it may write or publish.
    let canonicalRevision: UInt64
    let sessions: [SavedSession]
    let baseline: PersonalBaseline
    let profile: AthleteProfile
    let dailyMetrics: [SavedDailyMetric]
    let dailyRollups: [DailyRollupStoreEntry]
    let confirmedSleeps: [UserConfirmedSleep]
    let confirmedWorkouts: [UserConfirmedWorkout]
    let sessionFileURL: URL
    let canonicalBackupMirrorsToICloud: Bool
    let safetyWriteRequest: SessionBackupWriteRequest
}

private struct SessionBackupDerivedProjection: @unchecked Sendable {
    let latestReferenceValidatedHRVSource: SessionStore.LatestSessionMetricSource?
    let latestLocalRMSSDSource: SessionStore.LatestSessionMetricSource?
    let canonicalSessions: [SavedSession]
    let dailyMetricSparklines: DailyMetricSparklineCache
    let restingTrend14: [Int]
}

private struct PreparedSessionBackupRestore: @unchecked Sendable {
    let sourceURL: URL
    let safetyURL: URL
    let envelope: SessionBackupEnvelope
    let sessions: [SavedSession]
    let baseline: PersonalBaseline
    let profile: AthleteProfile
    let dailyMetrics: [SavedDailyMetric]
    let dailyRollups: [DailyRollupStoreEntry]
    let confirmedSleeps: [UserConfirmedSleep]
    let confirmedWorkouts: [UserConfirmedWorkout]
    let digest: String
    let basedOnCanonicalRevision: UInt64
    let derivedProjection: SessionBackupDerivedProjection
    var canonicalBackupStatus: SessionBackupStatus? = nil
}

private struct SessionBackupIOFailure: @unchecked Sendable {
    let reason: String
    let path: String
    let safetyURL: URL?
    let schema: Int
    let errorDescription: String?
}

private enum SessionBackupIORequest: @unchecked Sendable {
    case verifyLatest(SessionBackupIOSnapshot)
    case prepareRestore(URL, SessionBackupIOSnapshot)
    case prepareLatestRestore(SessionBackupIOSnapshot)
    case commitRestore(PreparedSessionBackupRestore, rollback: SessionBackupIOSnapshot)
}

private enum SessionBackupIOResult: @unchecked Sendable {
    case verification(SessionBackupStatus)
    case preparedRestore(PreparedSessionBackupRestore)
    case committedRestore(PreparedSessionBackupRestore)
    case failure(SessionBackupIOFailure)
}

fileprivate struct CooperativeBPMStats {
    let values: [Int]
    let sortedValues: [Int]
    let sum: Int
    let roundedAverage: Int
    let peak: Int
}

extension SavedSession {
    /// Standard BLE Heart Rate (`2A37`) can legitimately arrive in short bursts
    /// instead of at a perfect 1 Hz cadence. Use this only for HR/workout/strain
    /// coverage. RR/HRV continuity keeps its stricter no->3s-gap contract.
    static let workoutContinuityGapLimit: TimeInterval = 15
    fileprivate static let workoutBorderlineThresholdMarginBPM = 5
    fileprivate static let restReviewMinimumDuration: TimeInterval = 2 * 60
    fileprivate static let strictRestAvgOverRestBPM = 18
    fileprivate static let strictRestPeakOverRestBPM = 45
    fileprivate static let restReviewAvgOverRestBPM = 30
    fileprivate static let restReviewP95OverRestBPM = 42
    fileprivate static let restReviewPeakOverRestBPM = 55
    /// Contact-artifact hardening thresholds (2026-07-05, phantom-workout pass).
    /// See sustainedEvidence()/hrContactCompromised/hrRRDisagreesWithReportedHR.
    static let workoutMicroGapReseedCadence: TimeInterval = 3
    static let workoutMicroGapReseedJumpBPM = 25
    fileprivate static let workoutArtifactShareCeiling = 0.15
    fileprivate static let workoutZeroShareCeiling = 0.25
    fileprivate static let workoutAcceptedGapSecondsCeiling: TimeInterval = 120
    fileprivate static let workoutAcceptedGapCountCeiling = 3
    fileprivate static let workoutRRAgreementToleranceBPM = 20.0
    /// Peak-over-rest floor above which a total absence of RR/IBI samples in
    /// the observed window is treated as the loose-contact spike fingerprint
    /// rather than a genuine effort (see `impliedArtifact` in workoutReadiness).
    fileprivate static let workoutImpliedArtifactPeakOverRestFloor = 60

    /// True when this session's own audit counters show the watchdog-cycling /
    /// loose-contact fingerprint that can fabricate a workout from noise: a
    /// heavy artifact hold+drop share, a heavy zero share, or several large
    /// accepted-stream gaps. A session like this must never SOURCE an
    /// auto-detected workout candidate, whatever its raw HR values look like.
    var hrContactCompromised: Bool {
        let raw = hrRaw2A37Value
        guard raw > 0 else { return false }
        let artifactShare = Double(hrArtifactHeldValue + hrArtifactDroppedValue) / Double(raw)
        let zeroShare = Double(hrZeroValue) / Double(raw)
        if artifactShare >= Self.workoutArtifactShareCeiling { return true }
        if zeroShare >= Self.workoutZeroShareCeiling { return true }
        if hrMaxAcceptedGapValue > Self.workoutAcceptedGapSecondsCeiling
            && hrAcceptedGapsValue >= Self.workoutAcceptedGapCountCeiling { return true }
        return false
    }

    /// Median heart rate implied by this session's RR/IBI intervals (bpm =
    /// 60000/ms), or nil when there are too few RR samples to judge. This is
    /// the sanity-ceiling companion to the strap's own reported HR.
    ///
    /// Content-key cached (2026-08-07): the windowed workout-candidate pass
    /// evaluates this per session per WINDOW; uncached, the repeated full RR
    /// sort burned >80% CPU for a minute of background materialization and
    /// iOS killed the app (cpu_resource_fatal ×3), taking the drain with it.
    var rrImpliedMedianBPM: Double? {
        guard hasQualifiedRRProvenance,
              let rrPoints, rrPoints.count >= 3 else { return nil }
        let cacheKey = respiratoryRateCacheKey(rrPoints: rrPoints)
        let cached = Self.rrImpliedMedianCache.lookup(cacheKey)
        if cached.hit { return cached.value }
        let implied = rrPoints.compactMap { point -> Double? in
            guard point.ms > 0 else { return nil }
            return 60_000.0 / Double(point.ms)
        }.sorted()
        guard implied.count >= 3 else {
            Self.rrImpliedMedianCache.store(nil, for: cacheKey)
            return nil
        }
        let mid = implied.count / 2
        let median = implied.count.isMultiple(of: 2)
            ? (implied[mid - 1] + implied[mid]) / 2
            : implied[mid]
        Self.rrImpliedMedianCache.store(median, for: cacheKey)
        return median
    }

    /// True when RR intervals are present but imply a heart rate more than
    /// `workoutRRAgreementToleranceBPM` away from this session's own reported
    /// average HR. The strap's RR channel contradicting its reported HR is a
    /// strong contact-artifact signal and rejects the candidate outright.
    var hrRRDisagreesWithReportedHR: Bool {
        guard let rrImpliedMedianBPM else { return false }
        return abs(rrImpliedMedianBPM - Double(avg)) > Self.workoutRRAgreementToleranceBPM
    }

    fileprivate func cooperativeBPMStats(
        cooperativeDeadline: AtriaSleepSettlementDeadline?
    ) throws -> CooperativeBPMStats {
        try cooperativeDeadline?.checkpoint()
        var values: [Int] = []
        values.reserveCapacity(points.count)
        var sum = 0
        for (index, point) in points.enumerated() {
            if index.isMultiple(of: 256) {
                try cooperativeDeadline?.checkpoint()
            }
            values.append(point.bpm)
            sum += point.bpm
        }
        var sortedValues = values
        try Self.cooperativeStableSort(
            &sortedValues,
            cooperativeDeadline: cooperativeDeadline,
            areInIncreasingOrder: <
        )
        try cooperativeDeadline?.checkpoint()
        return .init(
            values: values,
            sortedValues: sortedValues,
            sum: sum,
            roundedAverage: values.isEmpty
                ? 0
                : Int((Double(sum) / Double(values.count)).rounded()),
            peak: sortedValues.last ?? 0
        )
    }

    private func hrRRDisagreesWithReportedHR(
        averageHR: Int,
        cooperativeDeadline: AtriaSleepSettlementDeadline
    ) throws -> Bool {
        try cooperativeDeadline.checkpoint()
        guard try hasQualifiedRRProvenance(
                cooperativeDeadline: cooperativeDeadline
              ),
              let rrPoints,
              rrPoints.count >= 3 else { return false }
        let cacheKey = respiratoryRateCacheKey(rrPoints: rrPoints)
        let cached = Self.rrImpliedMedianCache.lookup(cacheKey)
        try cooperativeDeadline.checkpoint()
        let median: Double?
        if cached.hit {
            median = cached.value
        } else {
            var implied: [Double] = []
            implied.reserveCapacity(rrPoints.count)
            for (index, point) in rrPoints.enumerated() {
                if index.isMultiple(of: 256) {
                    try cooperativeDeadline.checkpoint()
                }
                if point.ms > 0 {
                    implied.append(60_000.0 / Double(point.ms))
                }
            }
            try Self.cooperativeStableSort(
                &implied,
                cooperativeDeadline: cooperativeDeadline,
                areInIncreasingOrder: <
            )
            if implied.count >= 3 {
                let middle = implied.count / 2
                median = implied.count.isMultiple(of: 2)
                    ? (implied[middle - 1] + implied[middle]) / 2
                    : implied[middle]
            } else {
                median = nil
            }
            try cooperativeDeadline.checkpoint()
            Self.rrImpliedMedianCache.store(median, for: cacheKey)
            try cooperativeDeadline.checkpoint()
        }
        guard let median else { return false }
        return abs(median - Double(averageHR))
            > Self.workoutRRAgreementToleranceBPM
    }

    /// Ghost-workout gating hardening (2026-07-05): `contactCompromisedOverride`/
    /// `rrDisagreementOverride`/`rrSampleCountOverride` let a stitched/aggregate
    /// caller supply the WORST-of-source-chunks contact signal and the SUM of
    /// source `rrSampleCount`s, instead of this method judging only the
    /// diluted/synthetic aggregate session (whose summed artifact/zero shares
    /// dilute below the ceilings, and whose `rrPoints` is always nil). Per-
    /// session callers omit these and get the session's own signal.
    func workoutReadiness(rest: Int,
                          maxHR: Int,
                          thresholdFraction: Double = 0.50,
                          contactCompromisedOverride: Bool? = nil,
                          rrDisagreementOverride: Bool? = nil,
                          rrSampleCountOverride: Int? = nil) -> WorkoutReadiness {
        try! workoutReadinessCore(
            rest: rest,
            maxHR: maxHR,
            thresholdFraction: thresholdFraction,
            contactCompromisedOverride: contactCompromisedOverride,
            rrDisagreementOverride: rrDisagreementOverride,
            rrSampleCountOverride: rrSampleCountOverride,
            preparedBPMStats: nil,
            cooperativeDeadline: nil
        )
    }

    func workoutReadiness(
        rest: Int,
        maxHR: Int,
        thresholdFraction: Double = 0.50,
        contactCompromisedOverride: Bool? = nil,
        rrDisagreementOverride: Bool? = nil,
        rrSampleCountOverride: Int? = nil,
        cooperativeDeadline: AtriaSleepSettlementDeadline
    ) throws -> WorkoutReadiness {
        try workoutReadinessCore(
            rest: rest,
            maxHR: maxHR,
            thresholdFraction: thresholdFraction,
            contactCompromisedOverride: contactCompromisedOverride,
            rrDisagreementOverride: rrDisagreementOverride,
            rrSampleCountOverride: rrSampleCountOverride,
            preparedBPMStats: nil,
            cooperativeDeadline: cooperativeDeadline
        )
    }

    fileprivate func workoutReadiness(
        rest: Int,
        maxHR: Int,
        cooperativeDeadline: AtriaSleepSettlementDeadline,
        preparedBPMStats: CooperativeBPMStats
    ) throws -> WorkoutReadiness {
        try workoutReadinessCore(
            rest: rest,
            maxHR: maxHR,
            thresholdFraction: 0.50,
            contactCompromisedOverride: nil,
            rrDisagreementOverride: nil,
            rrSampleCountOverride: nil,
            preparedBPMStats: preparedBPMStats,
            cooperativeDeadline: cooperativeDeadline
        )
    }

    private func workoutReadinessCore(
        rest: Int,
        maxHR: Int,
        thresholdFraction: Double,
        contactCompromisedOverride: Bool?,
        rrDisagreementOverride: Bool?,
        rrSampleCountOverride: Int?,
        preparedBPMStats: CooperativeBPMStats?,
        cooperativeDeadline: AtriaSleepSettlementDeadline?
    ) throws -> WorkoutReadiness {
        try cooperativeDeadline?.checkpoint()
        let sustained = try sustainedElevatedEvidenceCore(
            rest: rest,
            maxHR: maxHR,
            thresholdFraction: thresholdFraction,
            cooperativeDeadline: cooperativeDeadline
        )
        let thresholdHR = Self.workoutElevatedThreshold(rest: rest, maxHR: maxHR, fraction: thresholdFraction)
        let borderlineThresholdHR = max(rest, thresholdHR - Self.workoutBorderlineThresholdMarginBPM)
        let borderline = try sustainedEvidenceCore(
            minimumHR: borderlineThresholdHR,
            cooperativeDeadline: cooperativeDeadline
        )
        // ONE bpm materialization + ONE sort per readiness call (2026-08-05
        // allocation audit): `bpms` is a computed property, and this function
        // used to re-map the whole points array ~20× per call (plus 3 sorts
        // via percentileHR) — ~184 transient bytes per point per call across
        // a tree that replays every session, aggregate, and window. Values
        // are byte-identical; only the copies are gone.
        let bpmStats = if let preparedBPMStats {
            preparedBPMStats
        } else {
            try cooperativeBPMStats(
                cooperativeDeadline: cooperativeDeadline
            )
        }
        let bpmValues = bpmStats.values
        let sortedBPMValues = bpmStats.sortedValues
        var samplesAboveThreshold = 0
        var samplesAboveBorderline = 0
        for (index, bpm) in bpmValues.enumerated() {
            if index.isMultiple(of: 256) {
                try cooperativeDeadline?.checkpoint()
            }
            if bpm >= thresholdHR { samplesAboveThreshold += 1 }
            if bpm >= borderlineThresholdHR {
                samplesAboveBorderline += 1
            }
        }
        let avgBPM = bpmStats.roundedAverage
        let peakBPM = bpmStats.peak
        let elevatedSeconds = sustained.total
        let observedDuration = sustained.observedDuration
        let requiredElevatedSeconds = min(max(observedDuration * 0.35, 5 * 60), 20 * 60)
        let requiredElevatedBout = min(max(observedDuration * 0.20, 3 * 60), 8 * 60)
        let avgOverRest = avgBPM - rest
        let peakOverRest = peakBPM - rest
        let thresholdGapBPM = max(0, thresholdHR - peakBPM)
        let streamCoveragePercent = Self.workoutStreamCoveragePercent(observed: observedDuration, duration: duration)
        // RR present OR an unbroken accepted-HR stream backs the elevation with
        // something other than raw wrist/strap bpm alone (see spec item 2).
        // `effectiveRRSampleCount` lets a stitched/aggregate caller substitute
        // the SUM of its source sessions' rrSampleCount, since the synthetic
        // aggregate session's own rrPoints is always nil.
        let effectiveRRSampleCount = rrSampleCountOverride ?? rrSampleCount
        let contactQualified = effectiveRRSampleCount > 0
            || (hrAcceptedGapsValue == 0 && hrMaxAcceptedGapValue <= Self.workoutContinuityGapLimit)
        let contactQualifiedElevatedSeconds = contactQualified ? elevatedSeconds : 0
        let contactQualifiedLongestBout = contactQualified ? sustained.longestBout : 0
        // Sanity ceiling: a peak effort >=60bpm over rest with zero RR/IBI
        // samples anywhere in the observed window is the loose-contact spike
        // fingerprint (a genuine effort that hard always carries RR), not a
        // real workout -- fold it into contactCompromised so every gate that
        // already respects contactCompromised rejects it for free.
        let impliedArtifact = peakOverRest >= Self.workoutImpliedArtifactPeakOverRestFloor
            && effectiveRRSampleCount == 0
        let contactCompromised = (contactCompromisedOverride ?? hrContactCompromised) || impliedArtifact
        let rrDisagreement: Bool
        if let rrDisagreementOverride {
            rrDisagreement = rrDisagreementOverride
        } else if let cooperativeDeadline {
            rrDisagreement = try hrRRDisagreesWithReportedHR(
                averageHR: avgBPM,
                cooperativeDeadline: cooperativeDeadline
            )
        } else {
            rrDisagreement = hrRRDisagreesWithReportedHR
        }
        let ready = observedDuration >= 10 * 60
            && streamCoveragePercent >= 75
            && elevatedSeconds >= requiredElevatedSeconds
            && sustained.longestBout >= requiredElevatedBout
            && contactQualifiedLongestBout >= requiredElevatedBout
            && !contactCompromised
            && !rrDisagreement
        let primaryBlocker = Self.workoutPrimaryBlocker(ready: ready,
                                                        duration: duration,
                                                        observedDuration: observedDuration,
                                                        streamCoveragePercent: streamCoveragePercent,
                                                        droppedGapSeconds: sustained.droppedGapSeconds,
                                                        maxSampleGap: sustained.maxGap,
                                                        peakHR: peakBPM,
                                                        thresholdHR: thresholdHR,
                                                        elevatedSeconds: elevatedSeconds,
                                                        requiredElevatedSeconds: requiredElevatedSeconds,
                                                        longestBout: sustained.longestBout,
                                                        requiredBout: requiredElevatedBout)
        return WorkoutReadiness(duration: duration,
                                observedDuration: observedDuration,
                                avgHR: avgBPM,
                                peakHR: peakBPM,
                                p90HR: Self.percentileHR(0.90, presorted: sortedBPMValues),
                                p95HR: Self.percentileHR(0.95, presorted: sortedBPMValues),
                                p99HR: Self.percentileHR(0.99, presorted: sortedBPMValues),
                                thresholdHR: thresholdHR,
                                thresholdGapBPM: thresholdGapBPM,
                                samplesAboveThreshold: samplesAboveThreshold,
                                samplesAboveBorderline: samplesAboveBorderline,
                                elevatedSeconds: elevatedSeconds,
                                elevatedFraction: observedDuration > 0 ? elevatedSeconds / observedDuration : 0,
                                longestElevatedBout: sustained.longestBout,
                                borderlineThresholdHR: borderlineThresholdHR,
                                borderlineElevatedSeconds: borderline.total,
                                borderlineLongestBout: borderline.longestBout,
                                borderlineElevatedFraction: borderline.observedDuration > 0 ? borderline.total / borderline.observedDuration : 0,
                                requiredElevatedSeconds: requiredElevatedSeconds,
                                requiredElevatedBout: requiredElevatedBout,
                                droppedGapSeconds: sustained.droppedGapSeconds,
                                maxSampleGap: sustained.maxGap,
                                gapCount: sustained.gapCount,
                                streamCoveragePercent: streamCoveragePercent,
                                primaryBlocker: primaryBlocker,
                                avgOverRest: avgOverRest,
                                peakOverRest: peakOverRest,
                                contactQualifiedElevatedSeconds: contactQualifiedElevatedSeconds,
                                contactQualifiedLongestBout: contactQualifiedLongestBout,
                                contactCompromised: contactCompromised,
                                rrDisagreement: rrDisagreement,
                                ready: ready)
    }

    func detectedActivity(rest: Int, maxHR: Int, calendar: Calendar = .current) -> ActivityDetection? {
        guard !isBreathwork,
              sleepWakeResearchState != "sleep_research",
              duration >= Self.restReviewMinimumDuration,
              !points.isEmpty else { return nil }

        let eventCalendar = EventCivilTime.eventCalendar(timeZoneIdentifier: eventTimeZoneIdentifier,
                                                         fallback: calendar)
        let startHour = eventCalendar.component(.hour, from: start)
        let endHour = eventCalendar.component(.hour, from: end)
        let overnight = startHour >= 20 || startHour <= 3 || endHour <= 10
        let lowHR = avg <= rest + 15 && peak <= rest + 35
        if duration >= 10 * 60 {
            let readiness = workoutReadiness(rest: rest, maxHR: maxHR)
            if readiness.ready {
                // HR/RR can prove sustained cardiovascular load, but not its
                // context. Stress, driving and a real workout can share the
                // same plateau. Keep sensor-only evidence in review until the
                // user confirms it; only UserConfirmedWorkout is counted.
                let reason = "Sustained HR-only effort; activity context unconfirmed; not counted as workout"
                return ActivityDetection(id: id, kind: .activityCandidate, confidence: .medium,
                                         start: start, end: end, duration: duration,
                                         avgHR: avg, peakHR: peak, reason: reason)
            }
            if readiness.nearMiss && readiness.reviewWorthyCandidate {
                return ActivityDetection(id: id, kind: .activityCandidate, confidence: .low,
                                         start: start, end: end, duration: duration,
                                         avgHR: avg, peakHR: peak,
                                         reason: "HR-only workout-like signal; \(readiness.nearMissReason); not counted as workout")
            }
            if readiness.strengthCandidate && readiness.reviewWorthyCandidate {
                return ActivityDetection(id: id, kind: .activityCandidate, confidence: .low,
                                         start: start, end: end, duration: duration,
                                         avgHR: avg, peakHR: peak,
                                         reason: "Strength-like HR signal; \(readiness.strengthCandidateReason); not counted as workout")
            }
            if readiness.gappedStrengthReviewCandidate {
                return ActivityDetection(id: id, kind: .activityCandidate, confidence: .low,
                                         start: start, end: end, duration: duration,
                                         avgHR: avg, peakHR: peak,
                                         reason: "Strong HR effort recovered across a stream gap; low-confidence review only; not counted as workout")
            }
            if duration >= AggregateSleepCandidate.strictMinimumDuration && overnight && lowHR {
                let motionClause = motionHintCountValue > 0
                    ? "diagnostic motion observed unvalidated (\(motionHintKindsValue))"
                    : "motion not decoded"
                return ActivityDetection(id: id, kind: .sleepCandidate, confidence: .low,
                                         start: start, end: end, duration: duration,
                                         avgHR: avg, peakHR: peak,
                                         reason: "HR-only overnight low-HR window; \(motionClause)")
            }
            // A short low-HR window is indistinguishable from quiet wakefulness
            // without validated motion. Keep it as rest evidence until the
            // multi-hour overnight aggregate gates can support main sleep.
        }
        if duration < 3 * 60 * 60
            && avg <= rest + Self.strictRestAvgOverRestBPM
            && peak <= rest + Self.strictRestPeakOverRestBPM {
            let motionClause = motionHintCountValue > 0
                ? "diagnostic motion observed unvalidated (\(motionHintKindsValue))"
                : "motion not decoded"
            return ActivityDetection(id: id, kind: .restCandidate, confidence: .low,
                                     start: start, end: end, duration: duration,
                                     avgHR: avg, peakHR: peak,
                                     reason: "Short low-HR rest/nap candidate; diagnostic only; \(motionClause)")
        }
        let p95 = Self.percentileHR(0.95, values: bpms)
        let workoutFloor = Self.workoutElevatedThreshold(rest: rest, maxHR: maxHR, fraction: 0.50)
        if duration < 3 * 60 * 60
            && avg <= rest + Self.restReviewAvgOverRestBPM
            && p95 <= rest + Self.restReviewP95OverRestBPM
            && peak <= min(workoutFloor - 5, rest + Self.restReviewPeakOverRestBPM) {
            let motionClause = motionHintCountValue > 0
                ? "diagnostic motion observed unvalidated (\(motionHintKindsValue))"
                : "motion not decoded"
            return ActivityDetection(id: id, kind: .restCandidate, confidence: .low,
                                     start: start, end: end, duration: duration,
                                     avgHR: avg, peakHR: peak,
                                     reason: "Quiet HR-only rest/nap review; below workout band; not counted as sleep or workout; \(motionClause)")
        }
        return nil
    }

    func detectedSleepOrRestActivityCancellable(
        rest: Int,
        maxHR: Int,
        calendar: Calendar = .current,
        cooperativeDeadline: AtriaSleepSettlementDeadline
    ) throws -> ActivityDetection? {
        try cooperativeDeadline.checkpoint()
        guard !isBreathwork,
              sleepWakeResearchState != "sleep_research",
              duration >= Self.restReviewMinimumDuration,
              !points.isEmpty else { return nil }
        let stats = try cooperativeBPMStats(
            cooperativeDeadline: cooperativeDeadline
        )
        let average = stats.roundedAverage
        let peak = stats.peak
        let eventCalendar = EventCivilTime.eventCalendar(
            timeZoneIdentifier: eventTimeZoneIdentifier,
            fallback: calendar
        )
        let startHour = eventCalendar.component(.hour, from: start)
        let endHour = eventCalendar.component(.hour, from: end)
        let overnight = startHour >= 20 || startHour <= 3 || endHour <= 10
        let lowHR = average <= rest + 15 && peak <= rest + 35
        if duration >= 10 * 60 {
            let readiness = try workoutReadiness(
                rest: rest,
                maxHR: maxHR,
                cooperativeDeadline: cooperativeDeadline,
                preparedBPMStats: stats
            )
            try cooperativeDeadline.checkpoint()
            if readiness.ready
                || (readiness.nearMiss && readiness.reviewWorthyCandidate)
                || (readiness.strengthCandidate
                    && readiness.reviewWorthyCandidate)
                || readiness.gappedStrengthReviewCandidate {
                return nil
            }
            if duration >= AggregateSleepCandidate.strictMinimumDuration,
               overnight,
               lowHR {
                let motionClause = motionHintCountValue > 0
                    ? "diagnostic motion observed unvalidated (\(motionHintKindsValue))"
                    : "motion not decoded"
                return ActivityDetection(
                    id: id,
                    kind: .sleepCandidate,
                    confidence: .low,
                    start: start,
                    end: end,
                    duration: duration,
                    avgHR: average,
                    peakHR: peak,
                    reason: "HR-only overnight low-HR window; \(motionClause)"
                )
            }
        }
        if duration < 3 * 60 * 60,
           average <= rest + Self.strictRestAvgOverRestBPM,
           peak <= rest + Self.strictRestPeakOverRestBPM {
            let motionClause = motionHintCountValue > 0
                ? "diagnostic motion observed unvalidated (\(motionHintKindsValue))"
                : "motion not decoded"
            return ActivityDetection(
                id: id,
                kind: .restCandidate,
                confidence: .low,
                start: start,
                end: end,
                duration: duration,
                avgHR: average,
                peakHR: peak,
                reason: "Short low-HR rest/nap candidate; diagnostic only; \(motionClause)"
            )
        }
        let p95 = Self.percentileHR(0.95, presorted: stats.sortedValues)
        let workoutFloor = Self.workoutElevatedThreshold(
            rest: rest,
            maxHR: maxHR,
            fraction: 0.50
        )
        try cooperativeDeadline.checkpoint()
        if duration < 3 * 60 * 60,
           average <= rest + Self.restReviewAvgOverRestBPM,
           p95 <= rest + Self.restReviewP95OverRestBPM,
           peak <= min(workoutFloor - 5,
                       rest + Self.restReviewPeakOverRestBPM) {
            let motionClause = motionHintCountValue > 0
                ? "diagnostic motion observed unvalidated (\(motionHintKindsValue))"
                : "motion not decoded"
            return ActivityDetection(
                id: id,
                kind: .restCandidate,
                confidence: .low,
                start: start,
                end: end,
                duration: duration,
                avgHR: average,
                peakHR: peak,
                reason: "Quiet HR-only rest/nap review; below workout band; not counted as sleep or workout; \(motionClause)"
            )
        }
        return nil
    }

    func restingHRForBaseline(rest: Int, maxHR: Int, calendar: Calendar = .current) -> (value: Int, source: String) {
        if let detection = detectedActivity(rest: rest, maxHR: maxHR, calendar: calendar),
           detection.kind == .sleepCandidate {
            return (sleepCandidateRestingHR, "hr_only_sleep_candidate_5th_percentile")
        }
        return (restingStable, "session_10th_percentile")
    }

    /// True when this session falls in an overnight / early-morning window — the
    /// same predicate the sleep detector uses (Sessions.swift overnight check). Used
    /// to tag HRV baseline samples so recovery can prefer sleep-window HRV like WHOOP.
    func isOvernightHRVWindow(calendar: Calendar = .current) -> Bool {
        let eventCalendar = EventCivilTime.eventCalendar(timeZoneIdentifier: eventTimeZoneIdentifier,
                                                         fallback: calendar)
        let startHour = eventCalendar.component(.hour, from: start)
        let endHour = eventCalendar.component(.hour, from: end)
        return startHour >= 20 || startHour <= 3 || endHour <= 10
    }

    func baselineLearningEvidence(rest: Int, maxHR: Int, calendar: Calendar = .current) -> BaselineLearningEvidence {
        baselineLearningEvidence(rest: rest,
                                 maxHR: maxHR,
                                 calendar: calendar,
                                 localRMSSD: localRMSSD)
    }

    func baselineLearningEvidence(rest: Int,
                                  maxHR: Int,
                                  calendar: Calendar,
                                  localRMSSD: Int?) -> BaselineLearningEvidence {
        let restingEvidence = restingHRForBaseline(rest: rest, maxHR: maxHR, calendar: calendar)
        // Duration floor lowered 20min -> 5min (2026-07-08, device-reported
        // "1/14 RHR" after 3 days). All-day wear, fragmented by frequent BLE
        // drops into sub-20-min segments, was silently discarding genuinely
        // restful data. This reject still sits BEFORE the avg<=rest+15 /
        // peak<=rest+35 guards below, so a 5-20 min segment must still prove
        // it is truly at rest to be accepted; sub-5-min stays rejected. The
        // 14-distinct-DAY trust gate and bounded EMA are untouched, so
        // learning states still fail closed until real multi-day history.
        if duration < 5 * 60 {
            return BaselineLearningEvidence(value: restingEvidence.value,
                                            source: restingEvidence.source,
                                            accepted: false,
                                            reason: "duration_below_5m")
        }
        if avg > rest + 15 {
            return BaselineLearningEvidence(value: restingEvidence.value,
                                            source: restingEvidence.source,
                                            accepted: false,
                                            reason: "avg_hr_above_rest_window")
        }
        if peak > rest + 35 {
            return BaselineLearningEvidence(value: restingEvidence.value,
                                            source: restingEvidence.source,
                                            accepted: false,
                                            reason: "peak_hr_above_rest_window")
        }
        // RR provenance proves the interval measurement, not that the wearer
        // was resting. It may refine the source only after the same low-HR
        // duration/shape gates every resting sample must clear.
        if localRMSSD != nil {
            return BaselineLearningEvidence(value: restingEvidence.value,
                                            source: hrvReferenceValidated == true
                                                ? "validated_hrv_window_10th_percentile"
                                                : "local_hrv_window_10th_percentile",
                                            accepted: true,
                                            reason: hrvReferenceValidated == true
                                                ? "validated_hrv_window"
                                                : "local_hrv_window")
        }
        if restingEvidence.source == "hr_only_sleep_candidate_5th_percentile" {
            return BaselineLearningEvidence(value: restingEvidence.value,
                                            source: restingEvidence.source,
                                            accepted: true,
                                            reason: "sleep_candidate")
        }
        return BaselineLearningEvidence(value: restingEvidence.value,
                                        source: "session_10th_percentile_low_hr_window",
                                        accepted: true,
                                        reason: "low_hr_window")
    }

    func baselineLearningEvidenceCancellable(
        rest: Int,
        maxHR _: Int,
        localRMSSD: Int?,
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> BaselineLearningEvidence? {
        let deadline = AtriaSleepSettlementDeadline(
            uptimeNanoseconds: .max,
            monotonicNow: { shouldContinue() ? 0 : .max }
        )
        guard let stats = try? cooperativeBPMStats(
            cooperativeDeadline: deadline
        ), !stats.sortedValues.isEmpty, shouldContinue() else { return nil }
        let index = min(
            stats.sortedValues.count - 1,
            max(0, Int((Double(stats.sortedValues.count - 1) * 0.10)
                .rounded(.down)))
        )
        let resting = stats.sortedValues[index]
        let source = "session_10th_percentile"
        if duration < 5 * 60 {
            return .init(value: resting,
                         source: source,
                         accepted: false,
                         reason: "duration_below_5m")
        }
        if stats.roundedAverage > rest + 15 {
            return .init(value: resting,
                         source: source,
                         accepted: false,
                         reason: "avg_hr_above_rest_window")
        }
        if stats.peak > rest + 35 {
            return .init(value: resting,
                         source: source,
                         accepted: false,
                         reason: "peak_hr_above_rest_window")
        }
        guard shouldContinue() else { return nil }
        if localRMSSD != nil {
            return .init(
                value: resting,
                source: hrvReferenceValidated == true
                    ? "validated_hrv_window_10th_percentile"
                    : "local_hrv_window_10th_percentile",
                accepted: true,
                reason: hrvReferenceValidated == true
                    ? "validated_hrv_window"
                    : "local_hrv_window"
            )
        }
        return .init(value: resting,
                     source: "session_10th_percentile_low_hr_window",
                     accepted: true,
                     reason: "low_hr_window")
    }

    private func sustainedElevatedEvidence(rest: Int,
                                           maxHR: Int,
                                           thresholdFraction: Double = 0.50) -> (total: TimeInterval,
                                                                                longestBout: TimeInterval,
                                                                                observedDuration: TimeInterval,
                                                                                droppedGapSeconds: TimeInterval,
                                                                                maxGap: TimeInterval,
                                                                                gapCount: Int) {
        try! sustainedElevatedEvidenceCore(
            rest: rest,
            maxHR: maxHR,
            thresholdFraction: thresholdFraction,
            cooperativeDeadline: nil
        )
    }

    private func sustainedElevatedEvidenceCore(
        rest: Int,
        maxHR: Int,
        thresholdFraction: Double,
        cooperativeDeadline: AtriaSleepSettlementDeadline?
    ) throws -> (total: TimeInterval,
                 longestBout: TimeInterval,
                 observedDuration: TimeInterval,
                 droppedGapSeconds: TimeInterval,
                 maxGap: TimeInterval,
                 gapCount: Int) {
        let elevatedThreshold = Self.workoutElevatedThreshold(rest: rest, maxHR: maxHR, fraction: thresholdFraction)
        return try sustainedEvidenceCore(
            minimumHR: elevatedThreshold,
            cooperativeDeadline: cooperativeDeadline
        )
    }

    private func sustainedEvidence(minimumHR: Int) -> (total: TimeInterval,
                                                       longestBout: TimeInterval,
                                                       observedDuration: TimeInterval,
                                                       droppedGapSeconds: TimeInterval,
                                                       maxGap: TimeInterval,
                                                       gapCount: Int) {
        try! sustainedEvidenceCore(
            minimumHR: minimumHR,
            cooperativeDeadline: nil
        )
    }

    private func sustainedEvidenceCore(
        minimumHR: Int,
        cooperativeDeadline: AtriaSleepSettlementDeadline?
    ) throws -> (total: TimeInterval,
                 longestBout: TimeInterval,
                 observedDuration: TimeInterval,
                 droppedGapSeconds: TimeInterval,
                 maxGap: TimeInterval,
                 gapCount: Int) {
        try cooperativeDeadline?.checkpoint()
        guard points.count > 1 else { return (0, 0, 0, 0, 0, 0) }
        var total: TimeInterval = 0
        var currentBout: TimeInterval = 0
        var longestBout: TimeInterval = 0
        var observedDuration: TimeInterval = 0
        var droppedGapSeconds: TimeInterval = 0
        var maxGap: TimeInterval = 0
        var gapCount = 0
        for i in 1..<points.count {
            if i.isMultiple(of: 256) {
                try cooperativeDeadline?.checkpoint()
            }
            let dt = max(0, points[i].t - points[i - 1].t)
            if dt > Self.workoutContinuityGapLimit {
                droppedGapSeconds += dt
                maxGap = max(maxGap, dt)
                gapCount += 1
                currentBout = 0
                continue
            }
            observedDuration += dt
            // Contact-artifact hardening: a reconnect/loose-contact boundary
            // often shows up as a sub-15s (so not a hard stream gap) but
            // wider-than-cadence sample spacing paired with a large bpm jump --
            // exactly the accepted-median-drift fingerprint a per-sample jump
            // filter alone cannot catch. Treat that first post-gap sample as
            // unverified so it cannot seed (or continue) an elevated bout; the
            // hard >15s gap reset above already covers the rest of the run.
            let isMicroGapReconnect = dt > Self.workoutMicroGapReseedCadence
            let bpmJumpFromPreviousSample = abs(points[i].bpm - points[i - 1].bpm)
            let unverifiedReconnectBlip = isMicroGapReconnect
                && bpmJumpFromPreviousSample >= Self.workoutMicroGapReseedJumpBPM
            let elevated = points[i].bpm >= minimumHR && !unverifiedReconnectBlip
            if elevated {
                total += dt
                currentBout += dt
                longestBout = max(longestBout, currentBout)
            } else {
                currentBout = 0
            }
        }
        try cooperativeDeadline?.checkpoint()
        return (total, longestBout, observedDuration, droppedGapSeconds, maxGap, gapCount)
    }

    static func workoutElevatedThreshold(rest: Int, maxHR: Int, fraction: Double = 0.50) -> Int {
        let reserve = max(0, maxHR - rest)
        guard reserve > 0 else {
            return max(rest, maxHR)
        }
        let clamped = min(max(fraction, 0), 1)
        return rest + Int((Double(reserve) * clamped).rounded())
    }

    private static func percentileHR(_ percentile: Double, values: [Int]) -> Int {
        return percentileHR(percentile, presorted: values.sorted())
    }

    private static func percentileHR(_ percentile: Double, presorted sorted: [Int]) -> Int {
        guard !sorted.isEmpty else { return 0 }
        let clamped = min(max(percentile, 0), 1)
        let index = min(sorted.count - 1, max(0, Int((Double(sorted.count - 1) * clamped).rounded(.down))))
        return sorted[index]
    }

    private static func workoutStreamCoveragePercent(observed: TimeInterval, duration: TimeInterval) -> Int {
        guard duration > 0 else { return 0 }
        let percent = (observed / duration) * 100
        return min(100, max(0, Int(percent.rounded())))
    }

    private static func workoutPrimaryBlocker(ready: Bool,
                                              duration: TimeInterval,
                                              observedDuration: TimeInterval,
                                              streamCoveragePercent: Int,
                                              droppedGapSeconds: TimeInterval,
                                              maxSampleGap: TimeInterval,
                                              peakHR: Int,
                                              thresholdHR: Int,
                                              elevatedSeconds: TimeInterval,
                                              requiredElevatedSeconds: TimeInterval,
                                              longestBout: TimeInterval,
                                              requiredBout: TimeInterval) -> String {
        if ready { return "none" }
        let durationBlocked = observedDuration < 10 * 60
        let actualStreamGaps = droppedGapSeconds > 0 || maxSampleGap > Self.workoutContinuityGapLimit
        let coverageBlocked = streamCoveragePercent < 75
        let streamGapBlocked = actualStreamGaps && (durationBlocked
            || (duration > 0 && droppedGapSeconds / duration >= 0.25)
            || maxSampleGap > 30
        )
        let hrBelowThreshold = peakHR < thresholdHR
        if durationBlocked && !actualStreamGaps && hrBelowThreshold { return "duration_below_10m_and_hr_below_threshold" }
        if durationBlocked && !actualStreamGaps { return "duration_below_10m" }
        if coverageBlocked && hrBelowThreshold { return "stream_gaps_and_hr_below_threshold" }
        if coverageBlocked { return "stream_gaps" }
        if streamGapBlocked && hrBelowThreshold { return "stream_gaps_and_hr_below_threshold" }
        if streamGapBlocked { return "stream_gaps" }
        if hrBelowThreshold { return "hr_below_threshold" }
        if elevatedSeconds < requiredElevatedSeconds { return "insufficient_elevated_time" }
        if longestBout < requiredBout { return "insufficient_continuous_bout" }
        return "detector_not_workout"
    }
}

/// Admission state for the current-cycle compact receipt lane. A notification
/// storm may retain one running read and the latest reason for one trailing
/// read, but it can never enqueue a read per notification.
struct AtriaCurrentCycleStepReceiptReadCoalescer: Equatable {
    enum Phase: Equatable {
        case idle
        case reading(startedAt: TimeInterval)
        case cooldown(notBefore: TimeInterval)
    }

    enum CooldownActivation: Equatable {
        case wait(TimeInterval)
        case start(String)
        case idle
    }

    private(set) var phase: Phase = .idle
    private(set) var trailingReason: String?

    var inFlight: Bool {
        phase != .idle
    }

    /// Returns `true` only when the caller should enqueue a worker. While a
    /// worker is active, newer requests replace the single trailing reason.
    mutating func admit(reason: String, now: TimeInterval) -> Bool {
        guard phase == .idle else {
            trailingReason = reason
            return false
        }
        phase = .reading(startedAt: now)
        return true
    }

    /// Completes the active worker and returns the delay for one reserved
    /// cooldown wake-up. Even a fast read with no request waiting yet retains
    /// the slot until `minimumStartInterval` has passed, so a 2 Hz notification
    /// stream cannot turn into a 2 Hz full compact decode loop.
    mutating func finish(
        now: TimeInterval,
        minimumStartInterval: TimeInterval
    ) -> TimeInterval? {
        guard case .reading(let startedAt) = phase else { return nil }
        let notBefore = startedAt + max(0, minimumStartInterval)
        if now < notBefore || trailingReason != nil {
            let deadline = max(now, notBefore)
            phase = .cooldown(notBefore: deadline)
            return max(0, deadline - now)
        }
        phase = .idle
        return nil
    }

    /// Resolves the single cooldown timer. Requests received during the wait
    /// only replace `trailingReason`; the latest one becomes the next worker.
    mutating func activateCooldown(now: TimeInterval) -> CooldownActivation {
        guard case .cooldown(let notBefore) = phase else { return .idle }
        guard now >= notBefore else { return .wait(notBefore - now) }
        guard let reason = trailingReason else {
            phase = .idle
            return .idle
        }
        trailingReason = nil
        phase = .reading(startedAt: now)
        return .start(reason)
    }

    mutating func cancel() {
        phase = .idle
        trailingReason = nil
    }

    var outstandingWorkUpperBound: Int {
        (inFlight ? 1 : 0) + (trailingReason == nil ? 0 : 1)
    }
}

/// The compact receipt lane is deliberately bounded to the open physiological
/// cycle and the one cycle that closed at its wake boundary. The role is kept
/// explicit so an empty newly opened cycle can invalidate presentation without
/// preventing the immediately prior cycle from finishing its durable receipt.
struct AtriaCurrentCycleStepReceiptWindow: Equatable, Sendable {
    enum Role: String, Equatable, Hashable, Sendable {
        case current
        case immediatelyPrior = "immediately_prior"
    }

    let role: Role
    let interval: DateInterval
}

/// Immutable-content identity for the launch workout aggregate pass. History
/// and review can materialize distinct Swift array storage for byte-identical
/// canonical sessions, especially when crossing detached-task boundaries, so
/// storage addresses are too strict and miss the rendezvous. A linear SHA-256
/// pass over exact HR/RR rows is tiny beside the multi-window replay it removes.
/// Scalar fields that affect aggregation remain value-keyed.
private struct AtriaWorkoutAggregateSessionFlightIdentity: Hashable, Sendable {
    let id: UUID
    let startBitPattern: UInt64
    let endBitPattern: UInt64
    let label: String
    let eventTimeZoneIdentifier: String?
    let pointContentDigest: Data
    let pointCount: Int
    let rrContentDigest: Data
    let rrCount: Int
    let motionHintCount: Int?
    let motionHintKinds: String?
    let hrRaw2A37: Int?
    let hrAccepted: Int?
    let hrZero: Int?
    let hrArtifactHeld: Int?
    let hrArtifactDropped: Int?
    let hrRawGaps: Int?
    let hrAcceptedGaps: Int?
    let hrMaxRawGapBitPattern: UInt64?
    let hrMaxAcceptedGapBitPattern: UInt64?
    let hrRRMismatch: Int?

    init(_ session: SavedSession) {
        id = session.id
        startBitPattern = session.start.timeIntervalSinceReferenceDate.bitPattern
        endBitPattern = session.end.timeIntervalSinceReferenceDate.bitPattern
        label = session.label
        eventTimeZoneIdentifier = session.eventTimeZoneIdentifier
        var pointHasher = SHA256()
        for point in session.points {
            Self.update(point.t.bitPattern, hasher: &pointHasher)
            Self.update(Int64(point.bpm), hasher: &pointHasher)
        }
        pointContentDigest = Data(pointHasher.finalize())
        pointCount = session.points.count
        var rrHasher = SHA256()
        for point in session.rrPoints ?? [] {
            Self.update(point.t.bitPattern, hasher: &rrHasher)
            Self.update(Int64(point.ms), hasher: &rrHasher)
            let source: UInt8 = switch point.source {
            case .none: 0
            case .standardHeartRateMeasurement2A37: 1
            case .validatedProprietaryRealtime: 2
            case .verifiedWhoop4HistoricalV24: 3
            }
            Self.update(source, hasher: &rrHasher)
        }
        rrContentDigest = Data(rrHasher.finalize())
        rrCount = session.rrPoints?.count ?? 0
        motionHintCount = session.motionHintCount
        motionHintKinds = session.motionHintKinds
        hrRaw2A37 = session.hrRaw2A37
        hrAccepted = session.hrAccepted
        hrZero = session.hrZero
        hrArtifactHeld = session.hrArtifactHeld
        hrArtifactDropped = session.hrArtifactDropped
        hrRawGaps = session.hrRawGaps
        hrAcceptedGaps = session.hrAcceptedGaps
        hrMaxRawGapBitPattern = session.hrMaxRawGap?.bitPattern
        hrMaxAcceptedGapBitPattern = session.hrMaxAcceptedGap?.bitPattern
        hrRRMismatch = session.hrRRMismatch
    }

    /// A total order is part of the cluster identity and its execution input.
    /// Start-only ordering is insufficient: two equal-start chunks can arrive
    /// in opposite array order, changing the aggregate id and stitched rows
    /// while otherwise producing the same flight key.
    static func canonicalOrder(_ lhs: SavedSession, _ rhs: SavedSession) -> Bool {
        if lhs.start != rhs.start { return lhs.start < rhs.start }
        if lhs.end != rhs.end { return lhs.end < rhs.end }
        return lhs.id.uuidString < rhs.id.uuidString
    }

    private static func update<Value: FixedWidthInteger>(
        _ value: Value,
        hasher: inout SHA256
    ) {
        var littleEndian = value.littleEndian
        withUnsafeBytes(of: &littleEndian) {
            hasher.update(bufferPointer: $0)
        }
    }
}

private struct AtriaWorkoutAggregateFlightKey: Hashable, Sendable {
    let sessions: [AtriaWorkoutAggregateSessionFlightIdentity]
    let rest: Int
    let maxHR: Int
    let thresholdFractionBitPattern: UInt64
    let calendarIdentifier: String
    let calendarTimeZoneIdentifier: String
    let calendarLocaleIdentifier: String?
    let firstWeekday: Int
    let minimumDaysInFirstWeek: Int
}

/// The corpus-level flight above cannot rendezvous History's complete source
/// image with workout review's 24-hour slice: their outer keys are correctly
/// different even when one or more expensive clusters are byte-identical.
/// Key the already-resolved cluster independently so those common units share
/// one replay without suppressing older History-only clusters.
private struct AtriaWorkoutAggregateClusterFlightKey: Hashable, Sendable {
    let orderedSessions: [AtriaWorkoutAggregateSessionFlightIdentity]
    let dayBitPattern: UInt64
    let rest: Int
    let maxHR: Int
    let thresholdFractionBitPattern: UInt64
    let calendarIdentifier: String
    let calendarTimeZoneIdentifier: String
    let calendarLocaleIdentifier: String?
    let firstWeekday: Int
    let minimumDaysInFirstWeek: Int
}

/// Process-wide rather than `SessionStore`-instance-wide because launch can
/// briefly have two consumers (History and the review cache) projecting the
/// same loaded canonical corpus. Serializing would only defer the second CPU
/// bill; this shares the first result exactly and retains it only long enough
/// for an adjacent launch consumer to rendezvous.
private final class AtriaWorkoutAggregateSingleFlight: @unchecked Sendable {
    private final class Entry: @unchecked Sendable {
        let finished = DispatchGroup()
        // Keep the exact source snapshot alive for the rendezvous grace so the
        // shared result and its audit input have one bounded lifetime.
        let retainedSessions: [SavedSession]
        var result: [AggregateWorkoutCandidate]?

        init(retainedSessions: [SavedSession]) {
            self.retainedSessions = retainedSessions
            finished.enter()
        }
    }

    private let lock = NSLock()
    private var entries: [AtriaWorkoutAggregateFlightKey: Entry] = [:]
#if DEBUG
    private var executionCount = 0
    private var sharedResultCount = 0
#endif

    func run(
        key: AtriaWorkoutAggregateFlightKey,
        retaining sessions: [SavedSession],
        operation: () -> [AggregateWorkoutCandidate]
    ) -> [AggregateWorkoutCandidate] {
        lock.lock()
        if let existing = entries[key] {
#if DEBUG
            sharedResultCount += 1
#endif
            lock.unlock()
            existing.finished.wait()
            return existing.result ?? []
        }
        let entry = Entry(retainedSessions: sessions)
        entries[key] = entry
#if DEBUG
        executionCount += 1
#endif
        lock.unlock()

        let result = operation()
        lock.lock()
        entry.result = result
        lock.unlock()
        entry.finished.leave()

        // Cover both truly concurrent launch callers and the common adjacent
        // hand-off after one queue unblocks. The bounded grace period prevents
        // a large aggregate result from becoming a process-lifetime cache.
        DispatchQueue.global(qos: .utility).asyncAfter(
            deadline: .now() + 2
        ) { [weak self, weak entry] in
            guard let self, let entry else { return }
            self.lock.lock()
            if self.entries[key] === entry {
                self.entries.removeValue(forKey: key)
            }
            self.lock.unlock()
        }
        return result
    }

#if DEBUG
    func resetCountersForTesting() {
        lock.lock()
        executionCount = 0
        sharedResultCount = 0
        entries.removeAll()
        lock.unlock()
    }

    func countersForTesting() -> (executions: Int, sharedResults: Int) {
        lock.lock()
        defer { lock.unlock() }
        return (executionCount, sharedResultCount)
    }

#endif
}

/// Process-wide cluster rendezvous shared by the independently keyed History
/// and workout-review corpus flights. Completed values have both a short TTL
/// and a strict count ceiling; active values are never evicted, because doing
/// so would permit a duplicate replay while the first operation is running.
private final class AtriaWorkoutAggregateClusterSingleFlight: @unchecked Sendable {
    private final class Entry: @unchecked Sendable {
        let finished = DispatchGroup()
        let retainedSessions: [SavedSession]
        var result: [AggregateWorkoutCandidate]?

        init(retainedSessions: [SavedSession]) {
            self.retainedSessions = retainedSessions
            finished.enter()
        }
    }

    private struct CompletedEntry {
        let key: AtriaWorkoutAggregateClusterFlightKey
        let entry: Entry
    }

    private let lock = NSLock()
    private let maximumRetainedResults = 16
    private let resultTimeToLive: TimeInterval = 10
    private var entries: [AtriaWorkoutAggregateClusterFlightKey: Entry] = [:]
    private var completedEntries: [CompletedEntry] = []
#if DEBUG
    private var executionCount = 0
    private var sharedResultCount = 0
    private var executionCountsBySessionID: [UUID: Int] = [:]
    private var sharedResultCountsBySessionID: [UUID: Int] = [:]
#endif

    func run(
        key: AtriaWorkoutAggregateClusterFlightKey,
        retaining sessions: [SavedSession],
        operation: () -> [AggregateWorkoutCandidate]
    ) -> [AggregateWorkoutCandidate] {
        lock.lock()
        if let existing = entries[key] {
#if DEBUG
            sharedResultCount += 1
            for sessionID in Set(key.orderedSessions.map(\.id)) {
                sharedResultCountsBySessionID[sessionID, default: 0] += 1
            }
#endif
            lock.unlock()
            existing.finished.wait()
            lock.lock()
            let result = existing.result ?? []
            lock.unlock()
            return result
        }

        let entry = Entry(retainedSessions: sessions)
        entries[key] = entry
#if DEBUG
        executionCount += 1
        for sessionID in Set(key.orderedSessions.map(\.id)) {
            executionCountsBySessionID[sessionID, default: 0] += 1
        }
#endif
        lock.unlock()

        let result = operation()
        lock.lock()
        entry.result = result
        completedEntries.append(CompletedEntry(key: key, entry: entry))
        while completedEntries.count > maximumRetainedResults {
            let expired = completedEntries.removeFirst()
            if entries[expired.key] === expired.entry {
                entries.removeValue(forKey: expired.key)
            }
        }
        lock.unlock()
        entry.finished.leave()

        DispatchQueue.global(qos: .utility).asyncAfter(
            deadline: .now() + resultTimeToLive
        ) { [weak self, weak entry] in
            guard let self, let entry else { return }
            self.lock.lock()
            if self.entries[key] === entry {
                self.entries.removeValue(forKey: key)
            }
            self.completedEntries.removeAll { $0.entry === entry }
            self.lock.unlock()
        }
        return result
    }

#if DEBUG
    func resetCountersForTesting() {
        lock.lock()
        executionCount = 0
        sharedResultCount = 0
        executionCountsBySessionID.removeAll()
        sharedResultCountsBySessionID.removeAll()
        entries.removeAll()
        completedEntries.removeAll()
        lock.unlock()
    }

    func countersForTesting() -> (executions: Int, sharedResults: Int) {
        lock.lock()
        defer { lock.unlock() }
        return (executionCount, sharedResultCount)
    }

    func countersForTesting(
        sessionID: UUID
    ) -> (executions: Int, sharedResults: Int) {
        lock.lock()
        defer { lock.unlock() }
        return (
            executionCountsBySessionID[sessionID, default: 0],
            sharedResultCountsBySessionID[sessionID, default: 0]
        )
    }
#endif
}

/// Main-actor state machine for the non-cancellable workout-review worker.
/// Invalidation marks the active result stale but deliberately preserves its
/// sentinel. While it drains, consumer requests replace one trailing key; the
/// completion releases the active slot before that latest request is admitted.
struct AtriaWorkoutReviewRefreshGate<Key: Equatable & Sendable>: Sendable {
    enum RequestDisposition: Equatable, Sendable {
        case start
        case joinedActive
        case coalescedTrailing
    }

    struct Completion: Equatable, Sendable {
        let completedKey: Key
        let activeWasInvalidated: Bool
        let trailingKey: Key?
    }

    private(set) var activeKey: Key?
    private(set) var trailingKey: Key?
    private(set) var activeWasInvalidated = false

    mutating func request(_ key: Key) -> RequestDisposition {
        guard let activeKey else {
            self.activeKey = key
            trailingKey = nil
            activeWasInvalidated = false
            return .start
        }
        if activeKey == key, !activeWasInvalidated {
            // This active replay already satisfies the newest consumer. Any
            // older, different trailing request is no longer authoritative.
            trailingKey = nil
            return .joinedActive
        }
        trailingKey = key
        return .coalescedTrailing
    }

    mutating func invalidate() {
        guard activeKey != nil else { return }
        activeWasInvalidated = true
    }

    mutating func finish(completedKey: Key) -> Completion? {
        guard activeKey == completedKey else { return nil }
        let completion = Completion(
            completedKey: completedKey,
            activeWasInvalidated: activeWasInvalidated,
            trailingKey: trailingKey
        )
        activeKey = nil
        trailingKey = nil
        activeWasInvalidated = false
        return completion
    }

    mutating func cancel() {
        activeKey = nil
        trailingKey = nil
        activeWasInvalidated = false
    }

    var outstandingWorkUpperBound: Int {
        (activeKey == nil ? 0 : 1) + (trailingKey == nil ? 0 : 1)
    }
}

/// Transaction-local accounting for stress replay publications that cannot be
/// exposed while recovered data is provisional. The gate stores only booleans;
/// deciding whether a concrete workout/session mutation is relevant remains at
/// the authoritative mutation callsite.
struct AtriaStressReplayTerminalPublicationGate: Equatable, Sendable {
    struct RollbackOutcome: Equatable, Sendable {
        let shouldPublish: Bool
        let requiresSessionAuthorityPublication: Bool
    }

    private(set) var transactionIsActive = false
    private(set) var mutationSnapshotIsRegistered = false
    private var preservedMutationBeforeSnapshot = false
    private var preservedSessionMutation = false
    private var preservedWorkoutAdditionAfterSnapshot = false

    mutating func beginTransaction() {
        transactionIsActive = true
        mutationSnapshotIsRegistered = false
        preservedMutationBeforeSnapshot = false
        preservedSessionMutation = false
        preservedWorkoutAdditionAfterSnapshot = false
    }

    mutating func registerMutationSnapshot() {
        guard transactionIsActive else { return }
        mutationSnapshotIsRegistered = true
    }

    /// A context mutation before the recovered rollback image is captured is
    /// part of that image and therefore survives rollback. Once the snapshot
    /// exists, sleeps and edits/deletes of existing workouts are rolled back.
    mutating func observeNonWorkoutContextMutation() {
        guard transactionIsActive,
              !mutationSnapshotIsRegistered else { return }
        preservedMutationBeforeSnapshot = true
    }

    /// Rollback's workout merge preserves only additions whose IDs were absent
    /// from its snapshot. The callsite supplies the state of the complete
    /// authoritative workout image, so an add followed by delete clears this
    /// pending edge instead of publishing a false mutation.
    mutating func observeWorkoutContextMutation(
        preservesQualifiedAdditionAfterSnapshot: Bool
    ) {
        guard transactionIsActive else { return }
        if mutationSnapshotIsRegistered {
            preservedWorkoutAdditionAfterSnapshot =
                preservesQualifiedAdditionAfterSnapshot
        } else {
            preservedMutationBeforeSnapshot = true
        }
    }

    /// Raw live sessions are outside the recovered rollback image. A delete or
    /// shrink accepted during the transaction therefore survives either
    /// terminal outcome.
    mutating func observePreservedSessionMutation() {
        guard transactionIsActive else { return }
        preservedSessionMutation = true
    }

    mutating func commitTransaction() {
        reset()
    }

    mutating func rollbackTransaction() -> RollbackOutcome {
        let outcome = RollbackOutcome(
            shouldPublish: preservedMutationBeforeSnapshot
                || preservedSessionMutation
                || preservedWorkoutAdditionAfterSnapshot,
            requiresSessionAuthorityPublication: preservedSessionMutation
        )
        reset()
        return outcome
    }

    private mutating func reset() {
        transactionIsActive = false
        mutationSnapshotIsRegistered = false
        preservedMutationBeforeSnapshot = false
        preservedSessionMutation = false
        preservedWorkoutAdditionAfterSnapshot = false
    }
}

/// Loads/saves sessions to a JSON file in the app's Documents directory.
@MainActor
final class SessionStore: ObservableObject {
    nonisolated private static let workoutAggregateSingleFlight =
        AtriaWorkoutAggregateSingleFlight()
    nonisolated private static let workoutAggregateClusterSingleFlight =
        AtriaWorkoutAggregateClusterSingleFlight()
    static let historicalRecoveryNeededNotification = Notification.Name("AtriaHistoricalRecoveryNeeded")
    static let historicalRecoveryResolvedNotification = Notification.Name("AtriaHistoricalRecoveryResolved")
    /// Emitted only after one archive revision has crossed the complete
    /// projection/rehydration/rollup/analytics publication fence.
    static let recoveredDataRecomputeDidPublishNotification = Notification.Name(
        "AtriaRecoveredDataRecomputeDidPublish"
    )
    /// Exact-store edge for a durable change to the qualified workout/sleep
    /// intervals used as historical physiological-stress context. The object is
    /// always the `SessionStore` whose canonical confirmed-record write
    /// completed. Derived/recovered transactions publish only through their
    /// existing complete recompute fence, never through this mutation edge.
    static let stressContextDidPublishNotification = Notification.Name(
        "AtriaStressContextDidPublish"
    )
    /// Exact-store terminal edge for replay-source mutations that do not flow
    /// through the ordinary workout/sleep context or recovered-success edges:
    /// saved-session removal/shrink, rollback-preserved live context, and one
    /// complete backup-restore publication.
    static let stressReplayDidPublishNotification = Notification.Name(
        "AtriaStressReplayDidPublish"
    )
    /// Exact-store terminal edge emitted after a recovered-data rollback has
    /// restored its final canonical image and released the active mutation
    /// ticket. Home uses it only to settle an O(1) pending calibration
    /// fingerprint; it is not an unconditional historical-replay trigger.
    static let stressCalibrationFenceDidReleaseNotification = Notification.Name(
        "AtriaStressCalibrationFenceDidRelease"
    )

    private struct WorkoutStressContextAuthority: Equatable {
        let start: Date
        let end: Date
        let intensity: Double
    }

    private struct WorkoutStressContextMutation {
        let previous: UserConfirmedWorkout?
        let next: UserConfirmedWorkout?

        var changesAuthority: Bool {
            SessionStore.workoutStressContextAuthority(previous)
                != SessionStore.workoutStressContextAuthority(next)
        }
    }

    private struct SleepStressContextAuthority: Equatable {
        let start: Date
        let end: Date
    }

    /// Constant-size projection used only where a callsite edits one existing
    /// workout. Exclusions are immutable on those merge/edit paths; a future
    /// exclusion editor must explicitly request publication at its own edge.
    private nonisolated static func workoutStressContextAuthority(
        _ workout: UserConfirmedWorkout
    ) -> WorkoutStressContextAuthority? {
        guard workout.start.timeIntervalSinceReferenceDate.isFinite,
              workout.end.timeIntervalSinceReferenceDate.isFinite,
              workout.end > workout.start else { return nil }
        let userConfirmed = workout.confidence
            .localizedCaseInsensitiveContains("user_confirmed")
        let recoveredMotion = workout.activityCalibrationEvidence.flatMap {
            evidence -> Double? in
            guard evidence.status == "ready",
                  evidence.motion.provenance == AtriaRecoveredMotionEpoch.source,
                  evidence.motion.validatedCoverageFraction >= 0.80,
                  let intensity = evidence.motion.meanMovementIntensity,
                  intensity.isFinite,
                  (0...1).contains(intensity),
                  intensity >= 0.08 else { return nil }
            return min(max(intensity, 0.35), 1)
        }
        guard userConfirmed || recoveredMotion != nil else { return nil }
        return WorkoutStressContextAuthority(
            start: workout.start,
            end: workout.end,
            intensity: recoveredMotion ?? 0.65
        )
    }

    private nonisolated static func workoutStressContextAuthority(
        _ workout: UserConfirmedWorkout?
    ) -> WorkoutStressContextAuthority? {
        guard let workout else { return nil }
        return workoutStressContextAuthority(workout)
    }

    private nonisolated static func sleepStressContextAuthority(
        _ sleep: UserConfirmedSleep
    ) -> SleepStressContextAuthority? {
        guard confirmedSleepIsPhysiologicalMainSleep(sleep),
              sleep.start.timeIntervalSinceReferenceDate.isFinite,
              sleep.end.timeIntervalSinceReferenceDate.isFinite else { return nil }
        let userQualified = sleep.source.hasPrefix("manual_")
            || sleep.source.hasPrefix("user_adjusted_")
            || sleep.confidence.hasPrefix("user_confirmed_")
        guard sleep.motionValidated || userQualified else { return nil }
        return SleepStressContextAuthority(start: sleep.start, end: sleep.end)
    }

    private nonisolated static func sleepStressContextAuthority(
        _ sleep: UserConfirmedSleep?
    ) -> SleepStressContextAuthority? {
        guard let sleep else { return nil }
        return sleepStressContextAuthority(sleep)
    }

    /// O(1) publication edge. Context authority is decided by the mutation
    /// callsite that already owns the single added/removed/edited record; this
    /// boundary never walks confirmed history on MainActor.
    private func publishStressContextIfNeeded(
        deferDerivedPublication: Bool,
        publicationRequested: Bool,
        rollbackWorkoutMutation: WorkoutStressContextMutation? = nil
    ) {
        guard publicationRequested,
              !deferDerivedPublication else { return }
        if stressReplayPublicationIsDeferred {
            if let mutation = rollbackWorkoutMutation {
                if stressReplayTerminalPublicationGate
                    .mutationSnapshotIsRegistered {
                    if let previousID = mutation.previous?.id,
                       recoveredStressReplayPreservedWorkoutAdditionIDs
                        .contains(previousID) {
                        recoveredStressReplayPreservedWorkoutAdditionIDs
                            .remove(previousID)
                        if let next = mutation.next,
                           Self.workoutStressContextAuthority(next) != nil {
                            recoveredStressReplayPreservedWorkoutAdditionIDs
                                .insert(next.id)
                        }
                    } else if mutation.previous == nil,
                              let next = mutation.next,
                              Self.workoutStressContextAuthority(next) != nil {
                        recoveredStressReplayPreservedWorkoutAdditionIDs
                            .insert(next.id)
                    }
                }
                stressReplayTerminalPublicationGate
                    .observeWorkoutContextMutation(
                        preservesQualifiedAdditionAfterSnapshot:
                            !recoveredStressReplayPreservedWorkoutAdditionIDs
                                .isEmpty
                    )
            } else {
                stressReplayTerminalPublicationGate
                    .observeNonWorkoutContextMutation()
            }
            return
        }
        NotificationCenter.default.post(
            name: Self.stressContextDidPublishNotification,
            object: self
        )
    }

    /// The source array/caches are already authoritative when this is called.
    /// During a recovered transaction raw session mutations are preserved by
    /// rollback, so defer their one generic edge to the terminal outcome.
    private func publishStressReplayTerminalMutationIfNeeded(reason: String) {
        if stressReplayPublicationIsDeferred {
            stressReplayTerminalPublicationGate
                .observePreservedSessionMutation()
            return
        }
        publishStressReplayTerminalEdge(reason: reason)
    }

    private func publishStressReplayTerminalEdge(reason: String) {
        NotificationCenter.default.post(
            name: Self.stressReplayDidPublishNotification,
            object: self,
            userInfo: ["reason": reason]
        )
    }

    private func publishStressCalibrationFenceDidRelease(reason: String) {
        NotificationCenter.default.post(
            name: Self.stressCalibrationFenceDidReleaseNotification,
            object: self,
            userInfo: ["reason": reason]
        )
    }

    /// Replace only the COW replay-source storage. Existing History
    /// presentation remains on its prior verified generation until the normal
    /// detached rebuild lands; stress replay can immediately snapshot the exact
    /// canonical session authority without walking HR/RR rows on MainActor.
    private func publishHistoricalStressSessionAuthority() {
        historySnapshot = HistorySnapshot(
            recoveredSessions: cachedCanonicalSessions,
            detections: historySnapshot.detections,
            trends: historySnapshot.trends,
            rollups: historySnapshot.rollups,
            preservingPresentationFrom: historySnapshot
        )
    }

    nonisolated static func stressReplaySessionHasInput(
        _ session: SavedSession
    ) -> Bool {
        !session.points.isEmpty
            || !(session.rrPoints?.isEmpty ?? true)
            || !(session.recoveredMotionEpochs?.isEmpty ?? true)
    }

    /// Constant-time conservative removal test for an in-place SavedSession
    /// replacement. Live checkpoints normally grow; only a lost boundary/row
    /// prefix or suffix needs a historical replay to remove stale minute facts.
    nonisolated static func stressReplaySessionInputShrank(
        previous: SavedSession?,
        next: SavedSession
    ) -> Bool {
        guard let previous,
              stressReplaySessionHasInput(previous) else { return false }
        if next.start > previous.start || next.end < previous.end { return true }
        if next.points.count < previous.points.count
            || (next.rrPoints?.count ?? 0) < (previous.rrPoints?.count ?? 0)
            || (next.recoveredMotionEpochs?.count ?? 0)
                < (previous.recoveredMotionEpochs?.count ?? 0) {
            return true
        }
        if let oldFirst = previous.points.first?.t,
           let newFirst = next.points.first?.t,
           newFirst > oldFirst { return true }
        if let oldLast = previous.points.last?.t,
           let newLast = next.points.last?.t,
           newLast < oldLast { return true }
        if let oldFirst = previous.rrPoints?.first?.t,
           let newFirst = next.rrPoints?.first?.t,
           newFirst > oldFirst { return true }
        if let oldLast = previous.rrPoints?.last?.t,
           let newLast = next.rrPoints?.last?.t,
           newLast < oldLast { return true }
        if let oldFirst = previous.recoveredMotionEpochs?.first?.start,
           let newFirst = next.recoveredMotionEpochs?.first?.start,
           newFirst > oldFirst { return true }
        if let oldLast = previous.recoveredMotionEpochs?.last?.end,
           let newLast = next.recoveredMotionEpochs?.last?.end,
           newLast < oldLast { return true }
        return false
    }

