    struct HistoricalArchiveStatus: Equatable {
        let exists: Bool
        let parseOK: Bool
        let rows: Int
        let metricUsableRows: Int
        let currentSessionUsableRows: Int
        let reason: String

        static let empty = HistoricalArchiveStatus(exists: false,
                                                   parseOK: true,
                                                   rows: 0,
                                                   metricUsableRows: 0,
                                                   currentSessionUsableRows: 0,
                                                   reason: "missing_archive")

        init(exists: Bool,
             parseOK: Bool,
             rows: Int,
             metricUsableRows: Int,
             currentSessionUsableRows: Int,
             reason: String) {
            self.exists = exists
            self.parseOK = parseOK
            self.rows = rows
            self.metricUsableRows = metricUsableRows
            self.currentSessionUsableRows = currentSessionUsableRows
            self.reason = reason
        }

        init(diagnostics: HistoricalArchive.Diagnostics) {
            self.init(exists: diagnostics.exists,
                      parseOK: diagnostics.parseOK,
                      rows: diagnostics.rows,
                      metricUsableRows: diagnostics.metricUsableRows,
                      currentSessionUsableRows: diagnostics.currentSessionUsableRows,
                      reason: diagnostics.reason)
        }

        var valueText: String {
            if !exists { return "None" }
            if !parseOK { return "Repair" }
            if isBoundedArchiveProbe { return "Checking" }
            if rows <= 0 { return "Empty" }
            if metricReady { return "Ready" }
            return "Saved"
        }

        var detailText: String {
            if !exists { return "Waiting for reconnect" }
            if !parseOK { return reason.replacingOccurrences(of: "_", with: " ") }
            if isBoundedArchiveProbe { return "Archive index is rebuilding safely" }
            if rows <= 0 { return "No missed readings yet" }
            if metricReady { return "\(metricUsableRows)/\(rows) metric rows" }
            if currentSessionUsableRows > 0 { return "Raw history saved" }
            return "Raw rows saved"
        }

        var userFootnoteText: String {
            if !exists { return "Reconnect fills gaps." }
            if !parseOK { return "Archive needs repair." }
            if isBoundedArchiveProbe { return "Atria is checking a large archive without blocking launch." }
            if rows <= 0 { return "Waiting for missed data." }
            if metricReady { return "\(metricUsableRows)/\(rows) rows metric-ready." }
            if currentSessionUsableRows > 0 {
                return "\(currentSessionUsableRows)/\(rows) raw history rows saved. Missing time stays excluded until those strap readings are verified."
            }
            return "\(rows) raw history rows saved locally. They are not used for metrics."
        }

        var actionText: String {
            if !exists { return "Wear normally; Atria will pull missed rows after reconnect." }
            if !parseOK { return "Keep the archive saved and repair parsing before using it for metrics." }
            if isBoundedArchiveProbe { return "Keep wearing normally; Atria will rebuild the archive index off the hot path." }
            if rows <= 0 { return "No action yet; wait for a reconnect with missed strap data." }
            if metricReady { return "Missed readings can contribute to metrics." }
            if currentSessionUsableRows > 0 {
                return "Keep the raw history; the gap remains excluded until Atria can verify those missed readings."
            }
            return "The raw archive is saved and remains outside metrics."
        }

        var metricGateText: String {
            if metricReady { return "Metric-ready" }
            // A row count from a sidecar or partial scan is not trustworthy
            // when the archive itself failed to parse. Never advertise those
            // rows as usable raw history until the archive is readable.
            if !parseOK { return "Repair needed" }
            if currentSessionUsableRows > 0 { return "Raw only" }
            if hasArchiveRows { return "Not metric-ready" }
            return "Waiting"
        }

        var metricReady: Bool {
            hasArchiveRows && metricUsableRows > 0 && currentSessionUsableRows > 0
        }

        var hasArchiveRows: Bool {
            exists && parseOK && rows > 0
        }

        private var isBoundedArchiveProbe: Bool {
            reason.hasPrefix("large_archive_index_missing_probe")
        }
    }

