    /// Fourteen daily resting-HR values from raw sessions, bounded to 45 days.
    /// Live checkpoints update one cached input and only sort when that input
    /// changes; edits/backfills take the full rebuild path.
    private func recomputeRestingTrend() {
        let now = Date()
        if pendingRestingTrendCheckpointHint != nil {
            guard Self.shouldRefreshLiveCheckpointDerivedState(
                lastRefreshAt: lastCheckpointRestingTrendRefreshAt,
                now: now,
                minimumInterval: Self.liveCheckpointSlowDerivedRefreshInterval
            ) else { return }
            lastCheckpointRestingTrendRefreshAt = now
        }
        let calendar = Calendar.current
        let cutoff = now.addingTimeInterval(-45 * 24 * 60 * 60)
        if let hint = pendingRestingTrendCheckpointHint,
           let replacement = sessions.first(where: { $0.id == hint.replacementID }) {
            var nextInputs = restingTrendInputsByID.filter { $0.value.start >= cutoff }
            let expiredInputWasRemoved = nextInputs.count != restingTrendInputsByID.count

            if !expiredInputWasRemoved,
               Self.restingTrendInputCannotChange(from: hint.previous,
                                                  to: replacement,
                                                  cutoff: cutoff) {
                return
            }

            if let input = Self.restingTrendInput(for: replacement, cutoff: cutoff) {
                nextInputs[replacement.id] = input
            } else {
                nextInputs.removeValue(forKey: replacement.id)
            }
            guard nextInputs != restingTrendInputsByID else { return }
            restingTrendInputsByID = nextInputs
        } else {
            let nextInputs = Dictionary(uniqueKeysWithValues: sessions.compactMap { session in
                Self.restingTrendInput(for: session, cutoff: cutoff).map { (session.id, $0) }
            })
            guard nextInputs != restingTrendInputsByID else { return }
            restingTrendInputsByID = nextInputs
        }

        let nextTrend = Self.restingTrendValues(from: Array(restingTrendInputsByID.values),
                                                calendar: calendar)
        if nextTrend != restingTrend14 {
            restingTrend14 = nextTrend
        }
    }

    private nonisolated static func restingTrendInput(for session: SavedSession,
                                                      cutoff: Date) -> RestingTrendInput? {
        guard session.start >= cutoff, session.points.count >= 8 else { return nil }
        let resting = session.restingStable
        guard resting > 0 else { return nil }
        return RestingTrendInput(start: session.start,
                                 eventTimeZoneIdentifier: session.eventTimeZoneIdentifier,
                                 value: resting)
    }

    private nonisolated static func restingTrendInputCannotChange(from previous: SavedSession?,
                                                                  to replacement: SavedSession,
                                                                  cutoff: Date) -> Bool {
        guard let previous, previous.start == replacement.start else { return false }
        if replacement.start < cutoff { return true }
        if previous.points.count < 8, replacement.points.count < 8 { return true }
        guard previous.points.count == replacement.points.count else { return false }
        return zip(previous.points, replacement.points).allSatisfy { old, new in
            old.t == new.t && old.bpm == new.bpm
        }
    }

    private nonisolated static func restingTrendValues(from inputs: [RestingTrendInput],
                                                       calendar: Calendar) -> [Int] {
        inputs
            .sorted { $0.start < $1.start }
            .reduce(into: [(day: Date, value: Int)]()) { days, session in
                let day = EventCivilTime.day(containing: session.start,
                                             eventTimeZoneIdentifier: session.eventTimeZoneIdentifier,
                                             outputCalendar: calendar)
                // Sessions are ascending by start, so same-day rows are
                // contiguous — only the last bucket can match. Check it
                // directly instead of an O(n) lastIndex scan per element.
                if let last = days.indices.last, calendar.isDate(days[last].day, inSameDayAs: day) {
                    days[last] = (day, min(days[last].value, session.value))
                } else {
                    days.append((day, session.value))
                }
            }
            .suffix(14)
            .map(\.value)
    }

    nonisolated static func restingTrend14(from sessions: [SavedSession],
                                           now: Date,
                                           calendar: Calendar) -> [Int] {
        let cutoff = now.addingTimeInterval(-45 * 24 * 60 * 60)
        let inputs = sessions.compactMap { restingTrendInput(for: $0, cutoff: cutoff) }
        return restingTrendValues(from: inputs, calendar: calendar)
    }

    private func recomputeCollectionResearchSummaries() {
        // These feed non-live research/collection cards, so coalesce them off the
        // hot sessions.didSet (fires on every live checkpoint) and compute OFF the
        // main thread — rebuilding IMUAuditSummary + the maneuver correlation over
        // ALL sessions on the main thread on every mutation was a stall (2026-07-08).
        if pendingRestingTrendCheckpointHint != nil {
            let now = Date()
            guard Self.shouldRefreshLiveCheckpointDerivedState(
                lastRefreshAt: lastCheckpointResearchSummaryRefreshAt,
                now: now,
                minimumInterval: Self.liveCheckpointSlowDerivedRefreshInterval
            ) else { return }
            lastCheckpointResearchSummaryRefreshAt = now
        }
        pendingResearchSummaryRecompute?.cancel()
        let sessionsSnapshot = sessions
        let markers = cachedResearchManeuverMarkers
        let work = DispatchWorkItem { [weak self, sessionsSnapshot, markers] in
            let activeSessionID = Self.freshActiveSessionIDForResearchSummary()
            let imu = IMUAuditSummary(sessions: sessionsSnapshot, activeSessionID: activeSessionID)
            let maneuver = ResearchManeuverProbeCorrelationSummary(markers: markers, sessions: sessionsSnapshot)
            DispatchQueue.main.async {
                self?.imuAuditSummary = imu
                self?.researchManeuverProbeCorrelationSummary = maneuver
            }
        }
        pendingResearchSummaryRecompute = work
        DispatchQueue.global(qos: .utility).asyncAfter(deadline: .now() + 0.4, execute: work)
    }

    nonisolated static func shouldRefreshLiveCheckpointDerivedState(
        lastRefreshAt: Date?,
        now: Date,
        minimumInterval: TimeInterval
    ) -> Bool {
        guard let lastRefreshAt else { return true }
        let age = now.timeIntervalSince(lastRefreshAt)
        return age < 0 || age >= minimumInterval
    }

    private nonisolated static func freshActiveSessionIDForResearchSummary(now: Date = Date()) -> UUID? {
        guard let record = ActiveSessionJournal.load(),
              record.schema == ActiveSessionJournal.schema,
              now.timeIntervalSince(record.updatedAt) <= 90 else {
            return nil
        }
        return record.id
    }

    private func latestFinalizedSkinTemperatureDeviationCelsius() -> Double? {
        guard AtriaResearchProbe.validatedSkinTemperatureDecoderAvailable else { return nil }
        if let value = dailyMetricHistory.first(where: { $0.skinTemperatureDeviationCelsius != nil })?.skinTemperatureDeviationCelsius {
            return value
        }
        return dailyRollupHistory.first(where: { $0.skinTemperatureDeviationCelsius != nil })?.skinTemperatureDeviationCelsius
    }

    nonisolated static func skinTemperatureDeviationSummary(finalizedDeviationCelsius: Double?,
                                                            fallback: IMUAuditSummary.SkinTemperatureDeviationSummary,
                                                            validatedSource: Bool = AtriaResearchProbe.validatedSkinTemperatureDecoderAvailable)
        -> IMUAuditSummary.SkinTemperatureDeviationSummary {
        // Candidate payloads remain useful transport/research evidence, but an
        // unvalidated byte layout must never make the application model claim a
        // temperature result is ready. Keep the non-numeric evidence counts for
        // diagnostics while failing the health value closed at this shared model
        // boundary; individual screens should not be responsible for hiding a
        // value that was never trustworthy in the first place.
        guard validatedSource else {
            return IMUAuditSummary.SkinTemperatureDeviationSummary(
                latestDeltaCelsius: nil,
                baselineSessions: 0,
                candidateFrames: fallback.candidateFrames,
                candidateValues: fallback.candidateValues)
        }
        guard let finalizedDeviationCelsius else { return fallback }
        return IMUAuditSummary.SkinTemperatureDeviationSummary(
            latestDeltaCelsius: finalizedDeviationCelsius,
            // The finalized deviation proves a qualified baseline existed; it
            // does not encode how many sessions backed it. Preserve only the
            // count still present in the loaded source instead of inventing a
            // minimum of three after session compaction or relaunch.
            baselineSessions: fallback.baselineSessions,
            candidateFrames: fallback.candidateFrames,
            candidateValues: fallback.candidateValues)
    }

    nonisolated static func isSkinTemperatureDeviationSummaryCacheFresh(
        _ record: SkinTemperatureDeviationSummaryCache,
        dailyMetricRevision: Int,
        dailyRollupRevision: Int,
        fallback: IMUAuditSummary.SkinTemperatureDeviationSummary
    ) -> Bool {
        record.dailyMetricRevision == dailyMetricRevision
            && record.dailyRollupRevision == dailyRollupRevision
            && record.fallback == fallback
    }

    nonisolated static func morningSkinTemperatureDeviation(
        for day: Date,
        computedToday: SavedDailyMetric?,
        skinTemperatureDeviationByDay: [Date: Double]? = nil,
        sessions: [SavedSession],
        activeSessionID: UUID? = nil,
        calendar: Calendar = .current,
        validatedSource: Bool = AtriaResearchProbe.validatedSkinTemperatureDecoderAvailable
    ) -> Double? {
        guard validatedSource else { return nil }
        if let computed = computedToday?.skinTemperatureDeviationCelsius {
            return computed
        }
        if let prepared = skinTemperatureDeviationByDay?[calendar.startOfDay(for: day)] {
            return prepared
        }
        return finalizedSkinTemperatureDeviationByMorningDay(sessions: sessions,
                                                             activeSessionID: activeSessionID,
                                                             calendar: calendar)[day]
    }

    // projectionScanActive added 2026-08-05 (single heavy lane): the +60s
    // cold-launch jetsam was the recovered projection's full archive scan
    // (healthy alone, ~830MB plateau) SUPERPOSED with a concurrent external
    // history refresh whose canonical-history entry load allocates ~1.3GB
    // under the iOS 27 reclaim law. Neither alone kills; together they cross
    // the ceiling. External refreshes defer while a projection scan runs —
    // the coordinator's own history step always follows the projection, so
    // freshness is preserved by the pipeline itself.
    nonisolated static func historySnapshotProjectionShouldDefer(
        exactRecoveryOwnsPriority: Bool,
        isRecoveredPublication: Bool,
        projectionScanActive: Bool = false
    ) -> Bool {
        (exactRecoveryOwnsPriority || projectionScanActive) && !isRecoveredPublication
    }

    // Widened to .deriving (2026-08-05, same evidence chain): with the scan
    // serialized and shadow skipped, the launch death moved to +151s — an
    // external reuse=0 refresh landing DURING the derived phase, atop the
    // ~1.3GB retained recovered working set. The whole recompute cycle is one
    // heavy lane; the pipeline's own history component still passes because
    // it calls with isRecoveredPublication: true.
    // Widened AGAIN to the rest window (2026-08-05, forced-gauntlet repro):
    // after a supersede the phase is .idle for the 20s inter-cycle rest with
    // trailing work queued and the working set still resident — the history
    // ENTRY load (8 large canonical payloads) ran in exactly that window and
    // climbed 1259→3372MB. heavyCycleEngaged covers it.
    private var recoveredProjectionScanActive: Bool {
        recoveredDataRecompute.heavyCycleEngaged
    }

    private var nonExactArchiveConsumerShouldDefer: Bool {
        exactRecoveryArchivePriorityLeaseActive
    }

    private func releaseExactRecoveryArchivePriority(
        for ticket: AtriaRecoveredDataRecomputeCoordinator.Ticket,
        reason: String
    ) {
        guard exactRecoveryProjectionArchiveRevisions.remove(
            ticket.archiveRevision
        ) != nil,
        exactRecoveryProjectionArchiveRevisions.isEmpty else { return }
        exactRecoveryArchivePriorityLeaseActive = false
        AtriaDebugLog(
            "ATRIADBG recovered_projection status=archive_priority_released reason=%@ generation=%llu archive_revision=%llu action=resume_coalesced_non_exact_consumers",
            reason,
            ticket.generation,
            ticket.archiveRevision
        )
        Task { @MainActor [weak self] in
            await Task.yield()
            self?.resumeDeferredForegroundArchiveWork(
                reason: "exact_recovery_\(reason)"
            )
        }
    }

    private func refreshHistorySnapshotCache(
        deferred: Bool = true,
        isRecoveredPublication: Bool = false,
        reuseLoadedCanonicalHistory: Bool = false,
        recoveredAffectedDays: Set<Date>? = nil,
        executionShouldContinue:
            @escaping @Sendable () -> Bool = { true },
        progress: ((String) -> Void)? = nil,
        completion: ((Bool) -> Void)? = nil
    ) {
        guard executionShouldContinue() else {
            completion?(false)
            return
        }
        guard !Self.historySnapshotProjectionShouldDefer(
            exactRecoveryOwnsPriority:
                nonExactArchiveConsumerShouldDefer,
            isRecoveredPublication: isRecoveredPublication,
            projectionScanActive: recoveredProjectionScanActive
        ) else {
            // The deferred branch must still advance the revision fence: the
            // inputs (confirmed sleeps, workouts, sessions) may have already
            // changed, and an in-flight worker captured BEFORE that change
            // would otherwise still satisfy `revision == historySnapshotRevision`
            // and republish the pre-edit snapshot on top of the synchronous
            // post-save image. Advancing here makes every pre-defer worker
            // stale by construction; the re-arm below recomputes fresh.
            historySnapshotRevision &+= 1
            if recoveredProjectionScanActive, !nonExactArchiveConsumerShouldDefer {
                // Single heavy lane (2026-08-05): re-armed on projection
                // failure; the publish path's own history component covers
                // freshness on success.
                pendingHistoryRefreshDeferredByProjectionScan = true
                AtriaDebugLog(
                    "ATRIADBG history_snapshot status=deferred_projection_scan_active action=single_heavy_lane"
                )
            } else {
                // Exact-recovery deferral previously re-armed nothing; reuse the
                // same single-lane re-arm so the refresh is not silently lost.
                pendingHistoryRefreshDeferredByProjectionScan = true
                AtriaDebugLog(
                    "ATRIADBG history_snapshot status=deferred_exact_recovery_projection action=preserve_shared_projection_lane"
                )
            }
            return
        }
        historySnapshotRevision &+= 1
        let revision = historySnapshotRevision
        // MainActor captures only the resident COW image. Active-journal file
        // decode and canonicalization are performed on the projection worker
        // under the exact recovered execution authority below.
        let residentCanonicalSessions = cachedCanonicalSessions
        let confirmedWorkouts = cachedConfirmedWorkouts
        let confirmedSleeps = cachedConfirmedSleeps
        let dismissedSleepCandidates = dismissedSleepCandidates
        let archiveHeartRatePoints = cachedHistoricalTodayHeartRatePoints
        let biologicalSex = profile.biologicalSex
        let baselineSnapshot = baseline
        let rest = baselineSnapshot.restingInt ?? 60
        let maxHR = profile.maxHR
        let projectionNow = Date()
        let physiologicalDayStart = AtriaPhysiologicalCycle.current(
            now: projectionNow,
            confirmedSleeps: confirmedSleeps,
            calendar: .current
        ).start
        let preservedStepEvidenceDays =
            AtriaWhoop4MotionTickDailyStore.shared
                .removingUnqualifiedResearchEvidence(
                    from: historySnapshot
                        .verifiedHistoricalStepEvidenceDays
                )
        let loadedCanonicalHistory = historySnapshot.verifiedCanonicalSources
        let loadedCanonicalPageCursor =
            historySnapshot.verifiedCanonicalPageCursor
        let loadedCanonicalHistoryHasMore =
            historySnapshot.verifiedCanonicalHistoryHasMore
        let previousHistorySnapshot = historySnapshot
        let previousSleepHistorySnapshot = sleepHistorySnapshot
        if !isRecoveredPublication {
            historySnapshot = HistorySnapshot.sessionsOnly(
                residentCanonicalSessions,
                verifiedHistoricalStepEvidenceDays: preservedStepEvidenceDays,
                rest: rest,
                maxHR: maxHR
            )
        }
        if deferred {
            Self.historySnapshotProjectionQueue.asyncAfter(deadline: .now() + 0.12) { [weak self, residentCanonicalSessions, confirmedWorkouts, confirmedSleeps, dismissedSleepCandidates, archiveHeartRatePoints, biologicalSex, baselineSnapshot, rest, maxHR, physiologicalDayStart, revision, loadedCanonicalHistory, loadedCanonicalPageCursor, loadedCanonicalHistoryHasMore, previousHistorySnapshot, previousSleepHistorySnapshot, recoveredAffectedDays, executionShouldContinue] in
                guard executionShouldContinue() else {
                    DispatchQueue.main.async { completion?(false) }
                    return
                }
                let sourceSessions = AtriaTransientWorkThread.run(
                    name: "atria.hist-entry-canonical",
                    qualityOfService: .utility
                ) { () -> [SavedSession]? in
                    guard executionShouldContinue() else { return nil }
                    let activeJournal = SessionStore
                        .loadActiveJournalSessionIfFresh(
                            now: projectionNow,
                            shouldContinue: executionShouldContinue
                        )
                    guard executionShouldContinue() else { return nil }
                    var canonicalInput = residentCanonicalSessions
                    if let activeJournal {
                        canonicalInput.append(activeJournal)
                    }
                    return SessionStore.makeCanonicalSessionsCancellable(
                        from: canonicalInput,
                        shouldContinue: executionShouldContinue
                    )
                }
                guard let sourceSessions, executionShouldContinue() else {
                    DispatchQueue.main.async { completion?(false) }
                    return
                }
                let isCurrent = DispatchQueue.main.sync {
                    self?.historySnapshotRevision == revision
                }
                guard isCurrent else {
                    DispatchQueue.main.async {
                        completion?(false)
                    }
                    return
                }
                let canonicalHistory:
                    [HistoricalArchive.VerifiedCanonicalConsumerSource]
                let canonicalPageCursor:
                    AtriaHistoricalAggregateReader.PageCursor?
                let canonicalHistoryHasMore: Bool
                if reuseLoadedCanonicalHistory {
                    // The exact recovered projection has already streamed and
                    // verified the complete archive into canonical sessions.
                    // Reopening up to eight large verified source payloads here
                    // duplicated archive I/O and exhausted the finite physical
                    // publication lease. Retain the already-loaded canonical
                    // page only for presentation metadata.
                    canonicalHistory = loadedCanonicalHistory
                    canonicalPageCursor = loadedCanonicalPageCursor
                    canonicalHistoryHasMore = loadedCanonicalHistoryHasMore
                } else {
                    // Dying thread + note (2026-08-05 heavy-lane fix): this
                    // 8-payload canonical page read is the history pass's
                    // ENTRY materialization — it climbed 1259→3372MB when it
                    // ran on this long-lived queue during a recompute rest
                    // window. The note makes the lane discriminable forever;
                    // the dying thread returns its parse garbage at teardown.
                    let canonicalPage = AtriaTransientWorkThread.run(
                        name: "atria.hist-canonical-page",
                        qualityOfService: .utility
                    ) {
                        HistoricalArchive
                            .readVerifiedCanonicalConsumerSourcePage(
                                after: nil,
                                maximumSourceCount: 8
                            )
                    }
                    canonicalHistory = canonicalPage.sources
                    canonicalPageCursor = canonicalPage.nextCursor
                    canonicalHistoryHasMore = canonicalPage.hasMore
                }
                guard executionShouldContinue() else {
                    DispatchQueue.main.async { completion?(false) }
                    return
                }
                let motionStrapIdentifier = UserDefaults.standard.string(
                    forKey: AtriaBLEManager.OfflineSyncDefaults
                        .verifiedHistoryPeripheralID
                )
                // 2026-07-31: rehydrate the recent day-keyed receipts, not
                // only the exact current-window one, so verified prior days
                // survive a relaunch that lands after a cycle rollover.
                let motionTickReceiptHistory:
                    [HistoricalArchive.MotionTickDayEvidence] =
                    AtriaWhoop4GravityCadenceStepModel
                        .releaseDailyAuthorityQualified
                    ? motionStrapIdentifier.map { strapIdentifier in
                        AtriaWhoop4MotionTickDailyStore.shared.recentReceipts(
                            strapIdentifier: strapIdentifier,
                            limit: 14
                        )
                    } ?? [] : []
                let motionTickDayEvidence = motionTickReceiptHistory.first {
                    abs($0.windowStart.timeIntervalSince(
                        physiologicalDayStart
                    )) < 1
                }
                // Only receipts that closed at or before the current wake
                // boundary are eligible as prior days; anything overlapping
                // the open cycle stays governed by the exact-window rule so a
                // prior-cycle subtotal can never masquerade as today.
                let priorMotionTickDayEvidence = motionTickReceiptHistory
                    .filter {
                        $0.windowStart < physiologicalDayStart
                            && $0.windowEnd <= physiologicalDayStart
                                .addingTimeInterval(1)
                    }
                let incremental = recoveredAffectedDays.flatMap { affectedDays in
                    SessionStore.makeIncrementalRecoveredHistorySnapshots(
                        previous: previousHistorySnapshot,
                        previousSleep: previousSleepHistorySnapshot,
                        affectedDays: affectedDays,
                        sessions: sourceSessions,
                        confirmedWorkouts: confirmedWorkouts,
                        confirmedSleeps: confirmedSleeps,
                        dismissedSleepCandidates:
                            dismissedSleepCandidates,
                        archiveHeartRatePoints: archiveHeartRatePoints,
                        biologicalSex: biologicalSex,
                        baseline: baselineSnapshot,
                        rest: rest,
                        maxHR: maxHR,
                        shouldContinue: executionShouldContinue
                    )
                }
                guard executionShouldContinue() else {
                    DispatchQueue.main.async { completion?(false) }
                    return
                }
                // Fresh dying thread for the FULL rebuild (2026-08-04): with
                // ~700k recovered archive points installed, the whole-history
                // day slicing churned ~2.4GB of transient allocations in one
                // queue-thread stretch (flat-blocks signature) and jetsammed
                // the process ~10s after a recompute cycle finished. The
                // bounded incremental path stays inline.
                let snapshots: (
                    history: HistorySnapshot,
                    sleep: SleepHistorySnapshot
                )?
                if let incremental {
                    snapshots = incremental
                } else {
                    snapshots = AtriaTransientWorkThread.run(
                        name: "atria.history-snapshots",
                        qualityOfService: .utility
                    ) {
                        SessionStore.makeHistorySnapshotsCancellable(
                            sessions: sourceSessions,
                            confirmedWorkouts: confirmedWorkouts,
                            confirmedSleeps: confirmedSleeps,
                            dismissedSleepCandidates:
                                dismissedSleepCandidates,
                            archiveHeartRatePoints: archiveHeartRatePoints,
                            canonicalHistory: canonicalHistory,
                            additionalStepEvidenceDays:
                                preservedStepEvidenceDays,
                            motionTickDayEvidence: motionTickDayEvidence,
                            priorMotionTickDayEvidence:
                                priorMotionTickDayEvidence,
                            canonicalPageCursor: canonicalPageCursor,
                            canonicalHistoryHasMore:
                                canonicalHistoryHasMore,
                            biologicalSex: biologicalSex,
                            baseline: baselineSnapshot,
                            rest: rest,
                            maxHR: maxHR,
                            preservingPresentationFrom:
                                previousHistorySnapshot,
                            shouldContinue: executionShouldContinue
                        )
                    }
                }
                guard let snapshots, executionShouldContinue() else {
                    DispatchQueue.main.async { completion?(false) }
                    return
                }
                let preparationSessions = recoveredAffectedDays.flatMap {
                    SessionStore.recoveredDailyPreparationSessions(
                        sessions: sourceSessions,
                        affectedDays: $0,
                        physiologicalDayStart: physiologicalDayStart,
                        shouldContinue: executionShouldContinue
                    )
                }
                guard recoveredAffectedDays == nil
                        || preparationSessions != nil else {
                    DispatchQueue.main.async { completion?(false) }
                    return
                }
                DispatchQueue.main.async {
                    guard let self else {
                        completion?(false)
                        return
                    }
                    guard executionShouldContinue() else {
                        completion?(false)
                        return
                    }
                    progress?("history_snapshot")
                    self.publishFullHistorySnapshotIfCurrent(revision: revision,
                                                             history: snapshots.history,
                                                             sleep: snapshots.sleep,
                                                             preparationSessions:
                                                                preparationSessions,
                                                             executionShouldContinue:
                                                                executionShouldContinue,
                                                             progress: progress,
                                                             completion: completion)
                }
            }
        } else {
            let snapshots = Self.makeHistorySnapshots(sessions: residentCanonicalSessions,
                                                      confirmedWorkouts: confirmedWorkouts,
                                                      confirmedSleeps: confirmedSleeps,
                                                      dismissedSleepCandidates: dismissedSleepCandidates,
                                                      archiveHeartRatePoints: archiveHeartRatePoints,
                                                      additionalStepEvidenceDays: preservedStepEvidenceDays,
                                                      biologicalSex: biologicalSex,
                                                      baseline: baselineSnapshot,
                                                      rest: rest,
                                                      maxHR: maxHR)
            publishFullHistorySnapshotIfCurrent(revision: revision,
                                                history: snapshots.history,
                                                sleep: snapshots.sleep,
                                                executionShouldContinue:
                                                    executionShouldContinue,
                                                progress: progress,
                                                completion: completion)
        }
    }

    private struct CurrentCycleStepLegacyMigrationAdmission {
        let generation: Int
        let expiresAt: Date
        let budget: HistoricalArchive.MotionTickDayEvidenceMigrationBudget
    }

    nonisolated static let currentCycleStepLegacyMigrationMaximumFileCount = 4
    nonisolated static let currentCycleStepLegacyMigrationMaximumTotalBytes:
        UInt64 = 32 * 1024 * 1024

    /// Legacy migration is optional freshness work over already-durable rows.
    /// It may run only during a real background-maintenance window under the
    /// same power/thermal guard as generic background projection and while no
    /// exact/recovered archive owner is active.
    nonisolated static func shouldAdmitBoundedLegacyCurrentCycleStepMigration(
        isBackgroundMaintenance: Bool,
        thermalState: ProcessInfo.ThermalState,
        isLowPowerModeEnabled: Bool,
        batteryState: UIDevice.BatteryState,
        batteryLevel: Float,
        exactRecoveryOwnsPriority: Bool,
        recoveredCycleEngaged: Bool
    ) -> Bool {
        isBackgroundMaintenance
            && !exactRecoveryOwnsPriority
            && !recoveredCycleEngaged
            && shouldStartBackgroundArchiveProjection(
                thermalState: thermalState,
                isLowPowerModeEnabled: isLowPowerModeEnabled,
                batteryState: batteryState,
                batteryLevel: batteryLevel
            )
    }

    /// Mints the sole one-shot authority for canonical v24 -> compact migration.
    /// Hot BLE, launch, foreground, rollover, and UI callbacks call the compact
    /// refresh directly and cannot construct this private admission.
    @discardableResult
    func scheduleBoundedLegacyCurrentCycleStepMigrationIfSafe(
        reason: String
    ) -> Bool {
        let isBackgroundMaintenance =
            UIApplication.shared.applicationState == .background
        guard Self.shouldAdmitBoundedLegacyCurrentCycleStepMigration(
            isBackgroundMaintenance: isBackgroundMaintenance,
            thermalState: ProcessInfo.processInfo.thermalState,
            isLowPowerModeEnabled:
                ProcessInfo.processInfo.isLowPowerModeEnabled,
            batteryState: UIDevice.current.batteryState,
            batteryLevel: UIDevice.current.batteryLevel,
            exactRecoveryOwnsPriority:
                nonExactArchiveConsumerShouldDefer,
            recoveredCycleEngaged: recoveredProjectionScanActive
        ) else {
            AtriaDebugLog(
                "ATRIADBG whoop4_daily_steps status=migration_reserved reason=%@ action=wait_for_safe_background",
                reason
            )
            return false
        }
        guard AtriaWhoop4GravityCadenceStepModel
                .releaseDailyAuthorityQualified else {
            return false
        }
        let identifiers =
            AtriaWhoop4MotionTickDailyStore.persistedStrapIdentifiers()
        guard let strapIdentifier = identifiers.first else {
            return false
        }
        let now = Date()
        let cycleStart = AtriaPhysiologicalCycle.current(
            now: now,
            confirmedSleeps: cachedConfirmedSleeps,
            calendar: .current
        ).start
        let coverage = AtriaWhoop4MotionBankCoverageLedger.intervals(
            intersecting: .init(start: cycleStart, end: now),
            strapIdentifier: strapIdentifier,
            now: now
        )
        guard !coverage.isEmpty,
              let coverageAuthority =
                AtriaWhoop4MotionBankCoverageLedger.projectionAuthority(
                    intersecting: .init(start: cycleStart, end: now),
                    strapIdentifier: strapIdentifier
                ) else {
            return false
        }
        guard !currentCycleStepCompactMigrationInFlight else {
            return false
        }
        currentCycleStepCompactMigrationInFlight = true
        currentCycleStepCompactMigrationGeneration &+= 1
        let admission = CurrentCycleStepLegacyMigrationAdmission(
            generation: currentCycleStepCompactMigrationGeneration,
            expiresAt: Date().addingTimeInterval(30),
            budget: .init(
                maximumFileCount:
                    Self.currentCycleStepLegacyMigrationMaximumFileCount,
                maximumTotalBytes:
                    Self.currentCycleStepLegacyMigrationMaximumTotalBytes
            )
        )
        let completedSignature = UserDefaults.standard.string(
            forKey: Self.currentCycleStepCompactMigrationKey
        )

        Self.historySnapshotProjectionQueue.async { [weak self] in
            guard Date() <= admission.expiresAt,
                  ProcessInfo.processInfo.thermalState != .serious,
                  ProcessInfo.processInfo.thermalState != .critical,
                  !ProcessInfo.processInfo.isLowPowerModeEnabled,
                  !HistoricalArchive
                    .exactRecoveryProjectionOwnsArchivePriority() else {
                DispatchQueue.main.async { [weak self] in
                    guard let self,
                          self.currentCycleStepCompactMigrationGeneration
                            == admission.generation else { return }
                    self.currentCycleStepCompactMigrationInFlight = false
                }
                AtriaDebugLog(
                    "ATRIADBG whoop4_daily_steps status=migration_reserved reason=%@ detail=worker_admission_expired_or_unsafe action=wait_for_next_background_maintenance",
                    reason
                )
                return
            }
            let sourceBefore =
                HistoricalArchive.consumerSourceFingerprint()
            let signatureBefore =
                Self.currentCycleStepCompactMigrationSignature(
                    strapIdentifier: strapIdentifier,
                    cycleStart: cycleStart,
                    coverageAuthority: coverageAuthority,
                    sourceFingerprint: sourceBefore
                )
            let compactBefore =
                AtriaWhoop4MotionTickCompactStore.shared
                    .motionTickDayEvidenceRead(
                        start: cycleStart,
                        end: now,
                        bankCoverage: coverage,
                        strapIdentifier: strapIdentifier
                    )
            var migrationResolved = compactBefore != .incomplete
            var canonicalRead:
                HistoricalArchive.MotionTickDayEvidenceRead?

            if !migrationResolved,
               signatureBefore != completedSignature {
                canonicalRead = HistoricalArchive
                    .boundedLegacyMotionTickDayEvidenceMigrationRead(
                        start: cycleStart,
                        end: now,
                        bankCoverage: coverage,
                        strapIdentifier: strapIdentifier,
                        budget: admission.budget,
                        compactMigrationStore:
                            AtriaWhoop4MotionTickCompactStore.shared
                    )
                let sourceAfter =
                    HistoricalArchive.consumerSourceFingerprint()
                let compactAfter =
                    AtriaWhoop4MotionTickCompactStore.shared
                        .motionTickDayEvidenceRead(
                            start: cycleStart,
                            end: now,
                            bankCoverage: coverage,
                            strapIdentifier: strapIdentifier
                        )
                migrationResolved =
                    sourceBefore == sourceAfter
                        && canonicalRead != .incomplete
                        && (
                            compactAfter != .incomplete
                                || canonicalRead
                                    == .completeNoQualifiedEvidence
                        )
                if migrationResolved,
                   let completed =
                    Self.currentCycleStepCompactMigrationSignature(
                        strapIdentifier: strapIdentifier,
                        cycleStart: cycleStart,
                        coverageAuthority: coverageAuthority,
                        sourceFingerprint: sourceAfter
                    ) {
                    UserDefaults.standard.set(
                        completed,
                        forKey: Self.currentCycleStepCompactMigrationKey
                    )
                }
            } else if migrationResolved,
                      let signatureBefore {
                UserDefaults.standard.set(
                    signatureBefore,
                    forKey: Self.currentCycleStepCompactMigrationKey
                )
            } else if signatureBefore == completedSignature {
                // A stable completed scan with no qualified canonical motion is
                // authoritative negative evidence for this exact source.
                migrationResolved = true
            }

            DispatchQueue.main.async { [weak self] in
                guard let self,
                      self.currentCycleStepCompactMigrationGeneration
                        == admission.generation else { return }
                self.currentCycleStepCompactMigrationInFlight = false
                self.refreshCurrentCycleStrapStepReceipt(
                    reason: "bounded_migration_\(reason)"
                )
            }
        }
        return true
    }

    /// 2026-07-31: schedules one cancellable check at the next no-sleep
    /// rollover boundary. When the boundary passes, the receipt refresh and
    /// the daily-store invalidation run so Home, History, and widgets move to
    /// the new cycle (disclosing the prior-cycle receipt) instead of showing
    /// yesterday's count or a frozen "--".
    func schedulePhysiologicalCycleRolloverCheck(reason: String) {
        let now = Date()
        schedulePhysiologicalCycleRolloverCheck(
            at: AtriaPhysiologicalCycle.nextNoSleepRollover(
                now: now,
                confirmedSleeps: cachedConfirmedSleeps,
                calendar: .current
            ),
            now: now,
            reason: reason
        )
    }

    /// Installs an already-prepared boundary without walking confirmed sleep
    /// history on MainActor. Recovered writes compute this value in their
    /// transient worker and defer the O(1) timer edge until transaction commit.
    private func schedulePhysiologicalCycleRolloverCheck(
        at boundary: Date?,
        now: Date,
        reason: String
    ) {
        physiologicalCycleRolloverTask?.cancel()
        physiologicalCycleRolloverTask = nil
        guard let boundary else {
            scheduledPhysiologicalCycleRolloverBoundary = nil
            return
        }
        scheduledPhysiologicalCycleRolloverBoundary = boundary
        // A short grace keeps the check strictly after the boundary so the
        // recomputed cycle start has actually moved when the task wakes.
        let delay = max(1, boundary.timeIntervalSince(now) + 1)
        AtriaDebugLog(
            "ATRIADBG whoop4_daily_steps status=cycle_rollover_scheduled reason=%@ boundary=%.3f delay=%.0f",
            reason,
            boundary.timeIntervalSince1970,
            delay
        )
        physiologicalCycleRolloverTask = Task { @MainActor [weak self] in
            try? await Task.sleep(
                nanoseconds: UInt64(delay * 1_000_000_000)
            )
            guard !Task.isCancelled else { return }
            self?.handlePhysiologicalCycleRollover(reason: reason)
        }
    }

    private func handlePhysiologicalCycleRollover(reason: String) {
        AtriaDebugLog(
            "ATRIADBG whoop4_daily_steps status=cycle_rollover_fired reason=%@",
            reason
        )
        refreshCurrentCycleStrapStepReceipt(
            reason: "physiological_cycle_rollover"
        )
        settleWakeDayFrozenMetricAtCycleRolloverIfNeeded()
        schedulePhysiologicalCycleRolloverCheck(reason: reason)
    }

    /// W3-A P0-2: the cycle flip is the exact instant the frozen wake-day
    /// metric's honesty gates (`completedBy: now`, `end <= now`) become
    /// satisfiable for a sleep that was confirmed while its measured wake was
    /// still in the future — today's shape for a shifted-schedule sleeper
    /// confirming at ~19:15. Settling here (instead of only refreshing the
    /// step receipt) closes both the future-end race and the
    /// background-deferred-confirm window with one edge. The settle is
    /// bounded by design — the minter never reads the live journal or the
    /// historical archive — and it tolerates a mutation-fence bail, relying
    /// on the existing launch-repair path in that case.
    private func settleWakeDayFrozenMetricAtCycleRolloverIfNeeded() {
        let calendar = Calendar.current
        let now = Date()
        guard let sleep = AtriaPhysiologicalCycle.latestCompletedMainSleep(
            now: now,
            confirmedSleeps: cachedConfirmedSleeps,
            calendar: calendar
        ) else { return }
        let wakeDay = EventCivilTime.day(
            containing: sleep.end,
            eventTimeZoneIdentifier: sleep.eventTimeZoneIdentifier,
            outputCalendar: calendar
        )
        let metric = dailyMetricHistory.first {
            calendar.isDate($0.day, inSameDayAs: wakeDay)
        }
        let rollup = dailyRollupHistory.first {
            calendar.isDate($0.day, inSameDayAs: wakeDay)
        }
        guard Self.cycleRolloverSettlementRequired(
            sleep: sleep,
            metric: metric,
            rollup: rollup,
            calendar: calendar
        ) else {
            AtriaDebugLog(
                "ATRIADBG morning_settlement status=already_settled reason=cycle_rollover sleep_id=%@",
                sleep.id
            )
            return
        }
        _ = settleConfirmedMorningAuthority(
            reason: "cycle_rollover_settlement",
            now: now,
            completion: { [weak self] succeeded in
                guard succeeded else { return }
                self?.publishDashboardRevision()
            }
        )
    }

    /// Pure decision for the rollover-edge settle: mint only when the wake
    /// day's frozen metric is missing or fails the exact three-way identity
    /// proof (`deferredLaunchCardSettlementMatches`) — the same check the
    /// launch fast path trusts. A matching, already-settled day is left
    /// byte-identical.
    nonisolated static func cycleRolloverSettlementRequired(
        sleep: UserConfirmedSleep,
        metric: SavedDailyMetric?,
        rollup: DailyRollupStoreEntry?,
        calendar: Calendar = .current
    ) -> Bool {
        !deferredLaunchCardSettlementMatches(
            sleep: sleep,
            metric: metric,
            rollup: rollup,
            calendar: calendar
        )
    }

    /// Publishes the current physiological cycle's strap-only step receipt
    /// without waiting for the much broader recovered-history transaction.
    ///
    /// A verified compact durability checkpoint may publish before the broader
    /// BLE transaction releases ownership. The bounded read stays on its own
    /// serial utility queue, and the daily store posts one lightweight
    /// Home/widget invalidation only after its atomic receipt is durable.
    /// No canonical archive or prior-day reader is reachable from this hot
    /// lane. Missing compact evidence waits for a later durable checkpoint or
    /// the separately admitted bounded background migration.
    enum CurrentCycleStepReceiptReadPlan: Equatable {
        case publishCompact
        case compactOnlyMissing
    }

    /// Every interactive/current-link caller is compact-only. A miss is not
    /// authority to enumerate canonical JSONL; the separately admitted bounded
    /// background migration may populate the shard on a later maintenance run.
    nonisolated static func currentCycleStepReceiptReadPlan(
        compactReadQualified: Bool
    ) -> CurrentCycleStepReceiptReadPlan {
        compactReadQualified ? .publishCompact : .compactOnlyMissing
    }

    /// Resolves exactly two wake-to-wake receipt windows: the open cycle first,
    /// followed by the cycle that ended at the open cycle's boundary. Asking the
    /// shared physiological-cycle kernel about the instant immediately before
    /// the boundary preserves main-sleep, resumed-sleep, no-sleep fallback,
    /// initial fallback, event-time-zone, and DST behavior without inventing a
    /// civil-midnight backfill lane.
    nonisolated static func currentAndPriorStepReceiptWindows(
        now: Date,
        confirmedSleeps: [UserConfirmedSleep],
        calendar: Calendar
    ) -> [AtriaCurrentCycleStepReceiptWindow] {
        let currentCycle = AtriaPhysiologicalCycle.current(
            now: now,
            confirmedSleeps: confirmedSleeps,
            calendar: calendar
        )
        guard currentCycle.start <= now else { return [] }

        let current = AtriaCurrentCycleStepReceiptWindow(
            role: .current,
            interval: .init(start: currentCycle.start, end: now)
        )
        let instantBeforeBoundary = currentCycle.start.addingTimeInterval(
            -0.001
        )
        let priorCycle = AtriaPhysiologicalCycle.current(
            now: instantBeforeBoundary,
            confirmedSleeps: confirmedSleeps,
            calendar: calendar
        )
        guard priorCycle.start < currentCycle.start else { return [current] }
        return [
            current,
            .init(
                role: .immediatelyPrior,
                interval: .init(
                    start: priorCycle.start,
                    end: currentCycle.start
                )
            ),
        ]
    }

    /// NOT CALLED IN PRODUCTION. Its only caller,
    /// `refreshPriorCivilDayStrapStepReceipts(reason:backfillDays:)`, was
    /// deleted in c18ab728 (2026-08-09, "Harden BLE continuity and bounded
    /// motion sync") because it scanned up to seven days of archive and that
    /// cost was what the change set out to bound. Two tests still exercise this
    /// helper, so it reads as covered behaviour — it is not; nothing writes a
    /// receipt for a day older than `immediatelyPrior`.
    ///
    /// The visible consequence is on the weekly steps chart: every bar older
    /// than the immediately-prior cycle is frozen at whatever the step
    /// computation produced when that day was last current, and no later fix to
    /// the computation reaches it. `AtriaWhoop4GravityCadenceStepModel
    /// .algorithmVersion` does not help — it is a release AUTHORIZATION, not a
    /// content key, so it is deliberately not bumped when the maths changes.
    ///
    /// Kept rather than deleted because it is the correct building block if the
    /// backfill lane is ever restored under a tighter budget. Do NOT reach for
    /// a store-level revision key instead: `loadRecordsLocked()` is
    /// all-or-nothing and its `catch` deletes the file, so invalidating stale
    /// receipts would erase every bar and only the two refreshed windows would
    /// ever come back.
    nonisolated static func completedPriorCivilDayWindows(
        now: Date,
        cycleStart: Date,
        calendar: Calendar,
        backfillDays: Int
    ) -> [DateInterval] {
        guard backfillDays > 0 else { return [] }
        let todayStart = calendar.startOfDay(for: now)
        let openCycleCivilDay = calendar.startOfDay(for: cycleStart)
        guard
            let dayBeforeToday = calendar.date(byAdding: .day, value: -1, to: todayStart),
            let dayBeforeCycle = calendar.date(byAdding: .day, value: -1, to: openCycleCivilDay)
        else { return [] }
        let newest = min(dayBeforeToday, dayBeforeCycle)
        var windows: [DateInterval] = []
        var cursor = newest
        for _ in 0..<backfillDays {
            guard let end = calendar.date(byAdding: .day, value: 1, to: cursor) else { break }
            windows.append(DateInterval(start: cursor, end: end))
            guard let prev = calendar.date(byAdding: .day, value: -1, to: cursor) else { break }
            cursor = prev
        }
        return windows
    }

    private func refreshCurrentCycleStrapStepReceipt(reason: String) {
        guard AtriaWhoop4GravityCadenceStepModel
                .releaseDailyAuthorityQualified else {
            currentCycleStepReceiptDeferredUntilForeground = false
            return
        }
        guard currentCycleStepReceiptReadCoalescer.admit(
            reason: reason,
            now: Self.currentCycleStepReceiptMonotonicNow()
        ) else {
            AtriaDebugLog(
                "ATRIADBG whoop4_daily_steps status=receipt_refresh_coalesced reason=%@ trailing_reason=%@ outstanding_upper_bound=%d",
                reason,
                currentCycleStepReceiptReadCoalescer.trailingReason ?? reason,
                currentCycleStepReceiptReadCoalescer.outstandingWorkUpperBound
            )
            return
        }
        startCurrentCycleStrapStepReceiptRead(reason: reason)
    }

    private func startCurrentCycleStrapStepReceiptRead(reason: String) {
        currentCycleStepReceiptGeneration &+= 1
        let generation = currentCycleStepReceiptGeneration
        // The worker derives its clock, cycle and bank coverage after it
        // actually reaches the serial lane. A coalesced trailing admission
        // captures this snapshot again, after any intervening sleep mutation.
        let confirmedSleeps = cachedConfirmedSleeps
        // Spans that cannot have produced footfalls. The strap counter is a
        // WRIST-motion counter, so a sustained upper-body or seated session
        // adds ticks with no steps behind them — on 2026-08-24 a single
        // 65-minute strength block was 5,232 of the day's 12,956 raw ticks
        // (40%). Snapshotted on the MainActor alongside the sleeps, then cut
        // out of step coverage entirely inside the read.
        let nonGaitWindows: [DateInterval] = cachedConfirmedWorkouts
            .compactMap { workout in
                guard workout.end > workout.start,
                      !AtriaWorkoutActivityType.resolved(
                          activityType: workout.activityType,
                          subtype: workout.activitySubtype,
                          label: workout.label
                      ).producesFootfalls else { return nil }
                return DateInterval(start: workout.start, end: workout.end)
            }
            // Plus every window the wearer has answered "Not walking" in the
            // unverified-movement review — the only channel that can separate
            // a meal from a walk in this data (2026-08-27: the two are the
            // same statistical population in every drained signal).
            + AtriaNonGaitArbitrationStore.shared.notWalkingWindows()
        Self.currentCycleStepReceiptQueue.async { [weak self] in
            var postsEmptyCycleInvalidation = false
            defer {
                Self.scheduleCurrentCycleStepReceiptReadFinish(
                    generation: generation,
                    reason: reason,
                    postsEmptyCycleInvalidation:
                        postsEmptyCycleInvalidation,
                    owner: self
                )
            }

            let identifiers =
                AtriaWhoop4MotionTickDailyStore.persistedStrapIdentifiers()
            guard let strapIdentifier = identifiers.first else {
                AtriaDebugLog(
                    "ATRIADBG whoop4_daily_steps status=receipt_refresh_skipped reason=%@ generation=%d detail=missing_strap_identifier",
                    reason,
                    generation
                )
                return
            }
            let now = Date()
            let receiptWindows = Self.currentAndPriorStepReceiptWindows(
                now: now,
                confirmedSleeps: confirmedSleeps,
                calendar: .current
            )
            for window in receiptWindows {
                let coverage = AtriaWhoop4MotionBankCoverageLedger.intervals(
                    intersecting: window.interval,
                    strapIdentifier: strapIdentifier,
                    now: now
                )
                if coverage.isEmpty {
                    // A freshly rolled cycle legitimately has no banked
                    // coverage. Re-resolve Home/widgets regardless of whether
                    // stored rows let us continue below — `hasStoredRows` is
                    // day-bucket granular, so on a day that already holds rows
                    // it answers true for even a minutes-old cycle, and
                    // folding it into this branch would silently stop the
                    // invalidation from ever firing.
                    if window.role == .current {
                        postsEmptyCycleInvalidation = true
                    }
                    // The bank ledger is a 512-entry FIFO and had already
                    // forgotten whole days that still held tens of thousands
                    // of decoded rows (2026-08-25: 08-22 and 08-23 scored zero
                    // steps). An empty ledger is no longer proof of no
                    // evidence — ask the store's files (one `stat` per day
                    // bucket) before giving up on the window. Evaluated only
                    // here so the common non-empty-ledger path never pays the
                    // store lock.
                    guard AtriaWhoop4MotionTickCompactStore.shared
                        .hasStoredRows(
                            start: window.interval.start,
                            end: window.interval.end,
                            strapIdentifier: strapIdentifier
                        ) else {
                        AtriaDebugLog(
                            "ATRIADBG whoop4_daily_steps status=receipt_refresh_skipped reason=%@ generation=%d window=%@ detail=no_bank_coverage_and_no_stored_rows window_start=%.3f window_end=%.3f",
                            reason,
                            generation,
                            window.role.rawValue,
                            window.interval.start.timeIntervalSince1970,
                            window.interval.end.timeIntervalSince1970
                        )
                        continue
                    }
                    AtriaDebugLog(
                        "ATRIADBG whoop4_daily_steps status=receipt_refresh_on_stored_rows reason=%@ generation=%d window=%@ detail=ledger_evicted_rows_present",
                        reason,
                        generation,
                        window.role.rawValue
                    )
                }
                let compactFingerprintBefore =
                    AtriaWhoop4MotionTickCompactStore.shared.sourceFingerprint(
                        start: window.interval.start,
                        end: window.interval.end,
                        strapIdentifier: strapIdentifier
                    )
                let compactRead = AtriaWhoop4MotionTickCompactStore.shared
                    .motionTickDayEvidenceRead(
                        start: window.interval.start,
                        end: window.interval.end,
                        bankCoverage: coverage,
                        strapIdentifier: strapIdentifier,
                        // Open-tail relaxation applies ONLY to the current cycle,
                        // whose window ends at `now` and whose final interval the
                        // compact store necessarily lags. The prior cycle ends on
                        // a real closed boundary and must stay strict.
                        allowOpenTail: window.role == .current,
                        excludedIntervals: nonGaitWindows
                    )
                let compactFingerprintAfter =
                    AtriaWhoop4MotionTickCompactStore.shared.sourceFingerprint(
                        start: window.interval.start,
                        end: window.interval.end,
                        strapIdentifier: strapIdentifier
                    )
                let compactQualified: Bool
                if case .qualified = compactRead {
                    compactQualified = true
                } else {
                    compactQualified = false
                }
                switch Self.currentCycleStepReceiptReadPlan(
                    compactReadQualified: compactQualified
                ) {
                case .publishCompact:
                    Self.completeCurrentCycleStrapStepReceiptRead(
                        compactRead,
                        stableCompleteRead:
                            compactFingerprintBefore
                                == compactFingerprintAfter,
                        reason: reason,
                        generation: generation,
                        windowRole: window.role,
                        coverageCount: coverage.count,
                        strapIdentifier: strapIdentifier
                    )
                case .compactOnlyMissing:
                    // Record WHICH non-qualified case fired so the field can tell
                    // a genuine drain backlog (.incomplete — rows still on the
                    // strap, correct to wait) from the now-edge veto
                    // (.completeNoQualifiedEvidence — rows exist but were
                    // discarded). With allowOpenTail on for .current, a case-b
                    // read now qualifies and publishes; a case still logged here
                    // for .current is therefore the genuine drain backlog.
                    let readCase: String
                    switch compactRead {
                    case .qualified: readCase = "qualified"
                    case .completeNoQualifiedEvidence: readCase = "complete_no_qualified_evidence"
                    case .incomplete: readCase = "incomplete"
                    }
                    AtriaDebugLog(
                        "ATRIADBG whoop4_daily_steps status=compact_only_missing reason=%@ generation=%d window=%@ coverage_intervals=%d read_case=%@ allow_open_tail=%d action=wait_for_compact_checkpoint_or_safe_bounded_migration",
                        reason,
                        generation,
                        window.role.rawValue,
                        coverage.count,
                        readCase,
                        window.role == .current ? 1 : 0
                    )
                }
            }
        }
    }

    nonisolated private static func currentCycleStepReceiptMonotonicNow()
        -> TimeInterval {
        TimeInterval(DispatchTime.now().uptimeNanoseconds) / 1_000_000_000
    }

    nonisolated private static func
        completeCurrentCycleStrapStepReceiptRead(
            _ read: HistoricalArchive.MotionTickDayEvidenceRead,
            stableCompleteRead: Bool,
            reason: String,
            generation: Int,
            windowRole: AtriaCurrentCycleStepReceiptWindow.Role,
            coverageCount: Int,
            strapIdentifier: String
        ) {
        guard case .qualified(let evidence) = read else {
            AtriaDebugLog(
                "ATRIADBG whoop4_daily_steps status=receipt_refresh_missing reason=%@ generation=%d window=%@ coverage_intervals=%d complete=%d",
                reason,
                generation,
                windowRole.rawValue,
                coverageCount,
                stableCompleteRead ? 1 : 0
            )
            return
        }
        do {
            let changed = try AtriaWhoop4MotionTickDailyStore.shared.save(
                evidence,
                strapIdentifier: strapIdentifier
            )
            // On relaunch the strongest receipt may already be durable. `save`
            // correctly performs no write in that case, but Home can have
            // rendered before CoreBluetooth republished the saved strap identity.
            if !changed {
                DispatchQueue.main.async {
                    NotificationCenter.default.post(
                        name: AtriaWhoop4MotionTickDailyStore
                            .didSaveNotification,
                        object: nil
                    )
                }
            }
            AtriaDebugLog(
                "ATRIADBG whoop4_daily_steps status=receipt_refresh_complete reason=%@ generation=%d window=%@ changed=%d steps=%d known_s=%d missing_s=%d read_case=qualified",
                reason,
                generation,
                windowRole.rawValue,
                changed ? 1 : 0,
                evidence.steps,
                evidence.knownCoverageSeconds,
                evidence.missingCoverageSeconds
            )
        } catch {
            AtriaDebugLog(
                "ATRIADBG whoop4_daily_steps status=receipt_save_failed reason=%@ generation=%d window=%@ error=%@",
                reason,
                generation,
                windowRole.rawValue,
                error.localizedDescription
            )
        }
    }

    nonisolated private static func scheduleCurrentCycleStepReceiptReadFinish(
        generation: Int,
        reason: String,
        postsEmptyCycleInvalidation: Bool,
        owner: SessionStore?
    ) {
        DispatchQueue.main.async { [weak owner] in
            owner?.finishCurrentCycleStepReceiptRead(
                generation: generation,
                reason: reason,
                postsEmptyCycleInvalidation:
                    postsEmptyCycleInvalidation
            )
        }
    }

    private func finishCurrentCycleStepReceiptRead(
        generation: Int,
        reason: String,
        postsEmptyCycleInvalidation: Bool
    ) {
        guard currentCycleStepReceiptGeneration == generation else {
            AtriaDebugLog(
                "ATRIADBG whoop4_daily_steps status=receipt_refresh_finish_ignored reason=%@ generation=%d active_generation=%d",
                reason,
                generation,
                currentCycleStepReceiptGeneration
            )
            return
        }
        if postsEmptyCycleInvalidation {
            NotificationCenter.default.post(
                name: AtriaWhoop4MotionTickDailyStore.didSaveNotification,
                object: nil
            )
        }
        currentCycleStepReceiptDeferredUntilForeground = false
        guard let cooldownDelay =
                currentCycleStepReceiptReadCoalescer.finish(
                    now: Self.currentCycleStepReceiptMonotonicNow(),
                    minimumStartInterval:
                        Self.currentCycleStepReceiptMinimumStartInterval
                ) else { return }
        AtriaDebugLog(
            "ATRIADBG whoop4_daily_steps status=receipt_refresh_cooldown completed_reason=%@ delay_s=%.3f trailing_reason=%@",
            reason,
            cooldownDelay,
            currentCycleStepReceiptReadCoalescer.trailingReason ?? "none"
        )
        scheduleCurrentCycleStepReceiptCooldown(after: cooldownDelay)
    }

    private func scheduleCurrentCycleStepReceiptCooldown(after delay: TimeInterval) {
        DispatchQueue.main.asyncAfter(deadline: .now() + max(0, delay)) {
            [weak self] in
            self?.handleCurrentCycleStepReceiptCooldown()
        }
    }

    private func handleCurrentCycleStepReceiptCooldown() {
        switch currentCycleStepReceiptReadCoalescer.activateCooldown(
            now: Self.currentCycleStepReceiptMonotonicNow()
        ) {
        case .wait(let remaining):
            scheduleCurrentCycleStepReceiptCooldown(after: remaining)
        case .idle:
            break
        case .start(let trailingReason):
            guard AtriaWhoop4GravityCadenceStepModel
                    .releaseDailyAuthorityQualified else {
                currentCycleStepReceiptReadCoalescer.cancel()
                currentCycleStepReceiptDeferredUntilForeground = false
                return
            }
            AtriaDebugLog(
                "ATRIADBG whoop4_daily_steps status=receipt_refresh_trailing_start trailing_reason=%@ minimum_interval_s=%.1f",
                trailingReason,
                Self.currentCycleStepReceiptMinimumStartInterval
            )
            // The cooldown activation is already the admission. Capture the
            // newest confirmed-sleep snapshot and enqueue exactly one worker.
            startCurrentCycleStrapStepReceiptRead(reason: trailingReason)
        }
    }

    nonisolated static func currentCycleStepReceiptAttemptSignature(
        strapIdentifier: String,
        cycleStart: Date,
        coverageAuthority:
            AtriaWhoop4MotionBankCoverageLedger.ProjectionAuthority,
        sourceFingerprint: HistoricalArchive.ConsumerSourceFingerprint,
        compactSourceIdentifier: String?
    ) -> String? {
        guard !strapIdentifier.isEmpty,
              let coverageIdentifier =
                coverageAuthority.stableIdentifier,
              let sourceIdentifier =
                sourceFingerprint.stableIdentifier,
              let compactSourceIdentifier else {
            return nil
        }
        let value = [
            AtriaWhoop4GravityCadenceStepModel.algorithmVersion,
            strapIdentifier.uppercased(),
            String(Int64(
                (cycleStart.timeIntervalSince1970 * 1_000).rounded()
            )),
            coverageIdentifier,
            sourceIdentifier,
            compactSourceIdentifier,
        ].joined(separator: "|")
        return SHA256.hash(data: Data(value.utf8))
            .map { String(format: "%02x", $0) }
            .joined()
    }

    nonisolated static func currentCycleStepCompactMigrationSignature(
        strapIdentifier: String,
        cycleStart: Date,
        coverageAuthority:
            AtriaWhoop4MotionBankCoverageLedger.ProjectionAuthority,
        sourceFingerprint: HistoricalArchive.ConsumerSourceFingerprint
    ) -> String? {
        currentCycleStepReceiptAttemptSignature(
            strapIdentifier: strapIdentifier,
            cycleStart: cycleStart,
            coverageAuthority: coverageAuthority,
            sourceFingerprint: sourceFingerprint,
            compactSourceIdentifier:
                "legacy-canonical-to-compact-v1"
        )
    }

    /// Loads one older verified canonical page only when a history surface asks
    /// for it. Previously loaded pages remain in the snapshot, so derived
    /// sleep/activity/strain values are rebuilt from one consistent source set.
    @MainActor
    func loadNextVerifiedCanonicalHistoryPage(maximumSourceCount: Int = 8) async -> Bool {
        guard maximumSourceCount > 0,
              historySnapshot.verifiedCanonicalHistoryHasMore,
              let cursor = historySnapshot.verifiedCanonicalPageCursor else { return false }

        historySnapshotRevision &+= 1
        let revision = historySnapshotRevision
        let sourceSessions = canonicalSessions(includeActiveJournal: true)
        let confirmedWorkouts = cachedConfirmedWorkouts
        let confirmedSleeps = cachedConfirmedSleeps
        let dismissedSleepCandidates = dismissedSleepCandidates
        let archiveHeartRatePoints = cachedHistoricalTodayHeartRatePoints
        let existingCanonical = historySnapshot.verifiedCanonicalSources
        let existingStepEvidence =
            AtriaWhoop4MotionTickDailyStore.shared
                .removingUnqualifiedResearchEvidence(
                    from: historySnapshot
                        .verifiedHistoricalStepEvidenceDays
                )
        let biologicalSex = profile.biologicalSex
        let baselineSnapshot = baseline
        let rest = baselineSnapshot.restingInt ?? 60
        let maxHR = profile.maxHR

        let output = await Task.detached(priority: .utility) {
            let page = HistoricalArchive.readVerifiedCanonicalConsumerSourcePage(
                after: cursor,
                maximumSourceCount: maximumSourceCount
            )
            var byIdentity = Dictionary(uniqueKeysWithValues: existingCanonical.map {
                ("\($0.identity.source.chunkID):\($0.identity.completionGeneration)", $0)
            })
            for source in page.sources {
                byIdentity["\(source.identity.source.chunkID):\(source.identity.completionGeneration)"] = source
            }
            let combined = byIdentity.values.sorted {
                if $0.identity.source.lastTimestamp != $1.identity.source.lastTimestamp {
                    return $0.identity.source.lastTimestamp > $1.identity.source.lastTimestamp
                }
                return $0.identity.source.chunkID < $1.identity.source.chunkID
            }
            let snapshots = SessionStore.makeHistorySnapshots(
                sessions: sourceSessions,
                confirmedWorkouts: confirmedWorkouts,
                confirmedSleeps: confirmedSleeps,
                dismissedSleepCandidates: dismissedSleepCandidates,
                archiveHeartRatePoints: archiveHeartRatePoints,
                canonicalHistory: combined,
                additionalStepEvidenceDays: existingStepEvidence,
                canonicalPageCursor: page.nextCursor,
                canonicalHistoryHasMore: page.hasMore,
                biologicalSex: biologicalSex,
                baseline: baselineSnapshot,
                rest: rest,
                maxHR: maxHR
            )
            return (page: page, snapshots: snapshots)
        }.value

        guard revision == historySnapshotRevision else { return false }
        publishFullHistorySnapshotIfCurrent(revision: revision,
                                            history: output.snapshots.history,
                                            sleep: output.snapshots.sleep)
        return output.page.nextCursor != cursor || !output.page.sources.isEmpty
    }

    /// A normal history refresh is intentionally latest-wins. Launch card
    /// settlement is different: if another legitimate refresh supersedes this
    /// request, its completion must inherit the required publication fence
    /// instead of silently dropping the widget/dashboard handoff.
    private func requestRequiredHistorySnapshotRefresh(
        deferred: Bool = true,
        completion: @escaping (Bool) -> Void
    ) {
        requiredHistoryPublicationCompletions.append(completion)
        refreshHistorySnapshotCache(deferred: deferred)
    }

    private func completeRequiredHistorySnapshotRefreshesIfPossible() {
        guard !requiredHistoryPublicationCompletions.isEmpty else { return }
        if let ticket = recoveredDataMutationTransaction.activeTicket {
            // Do not expose an intermediate recovered-data image. Keep the
            // completions pending and let the exact transaction drain them only
            // after commit. A rollback leaves them pending for the retry path.
            let registered = recoveredDataMutationTransaction.registerCommit(
                ticket: ticket
            ) { [weak self] in
                self?.completeRequiredHistorySnapshotRefreshesIfPossible()
            }
            if !registered {
                refreshRequiredHistorySnapshotIfPending()
            }
            return
        }
        let completions = requiredHistoryPublicationCompletions
        requiredHistoryPublicationCompletions.removeAll(keepingCapacity: true)
        for completion in completions {
            completion(true)
        }
    }

    private func refreshRequiredHistorySnapshotIfPending() {
        guard !requiredHistoryPublicationCompletions.isEmpty else { return }
        refreshHistorySnapshotCache(deferred: true)
    }

    private func publishFullHistorySnapshotIfCurrent(revision: Int,
                                                     history: HistorySnapshot,
                                                     sleep: SleepHistorySnapshot,
                                                     preparationSessions: [SavedSession]? = nil,
                                                     executionShouldContinue:
                                                        @escaping @Sendable () -> Bool = { true },
                                                     progress: ((String) -> Void)? = nil,
                                                     completion: ((Bool) -> Void)? = nil) {
        guard executionShouldContinue(),
              revision == historySnapshotRevision else {
            completion?(false)
            return
        }
        // Keep the visible history/sleep generation paired with the daily
        // metrics and rollups derived from it. Publishing these snapshots here
        // exposed a mixed-generation frame while the utility preparation was
        // still running (for example, a frozen 46% Recovery could briefly be
        // reprojected as 41%). The prepared publication below commits the
        // complete dashboard generation in one main-actor turn.
        prepareDailyMetricRollupPreparationIfCurrent(revision: revision,
                                                     history: history,
                                                     sleep: sleep,
                                                     preparationSessions:
                                                        preparationSessions,
                                                     executionShouldContinue:
                                                        executionShouldContinue,
                                                     progress: progress,
                                                     completion: completion)
    }

    private func prepareDailyMetricRollupPreparationIfCurrent(revision: Int,
                                                              history: HistorySnapshot,
                                                              sleep: SleepHistorySnapshot,
                                                              preparationSessions: [SavedSession]? = nil,
                                                              executionShouldContinue:
                                                                @escaping @Sendable () -> Bool = { true },
                                                              progress: ((String) -> Void)? = nil,
                                                              completion: ((Bool) -> Void)? = nil) {
        guard executionShouldContinue(),
              revision == historySnapshotRevision else {
            completion?(false)
            return
        }
        dailyRollupPreparationRevision &+= 1
        let rollupRevision = dailyRollupPreparationRevision
        let existingDailyMetrics = dailyMetricHistory
        let existingDailyMetricRevision = dailyMetricHistoryRevision
        let invalidatedDays = pendingDailyDerivedInvalidationDays
        let baselineSnapshot = baseline
        let maxHR = profile.maxHR
        let confirmedSleeps = cachedConfirmedSleeps
        let confirmedWorkouts = cachedConfirmedWorkouts
        let recoveredSkinTemperatureDeviationByDay =
            cachedRecoveredSkinTemperatureDeviationByDay
        let archiveHeartRatePoints = cachedHistoricalTodayHeartRatePoints
        let biologicalSex = profile.biologicalSex
        let activeSessionID = Self.freshActiveSessionIDForResearchSummary()
        let now = Date()
        DispatchQueue.global(qos: .utility).async { [weak self,
                                                     history,
                                                     sleep,
                                                     existingDailyMetrics,
                                                     existingDailyMetricRevision,
                                                     invalidatedDays,
                                                     baselineSnapshot,
                                                     maxHR,
                                                     confirmedSleeps,
                                                     confirmedWorkouts,
                                                     recoveredSkinTemperatureDeviationByDay,
                                                     archiveHeartRatePoints,
                                                     biologicalSex,
                                                     activeSessionID,
                                                     now,
                                                     revision,
                                                     rollupRevision,
                                                     executionShouldContinue] in
            guard executionShouldContinue() else {
                DispatchQueue.main.async { completion?(false) }
                return
            }
            let preparation = Self
                .makeDailyHistoryMetricRollupPreparationCancellable(
                    history: history,
                    sleep: sleep,
                    sessionsOverride: preparationSessions,
                    existingDailyMetrics: existingDailyMetrics,
                    baseline: baselineSnapshot,
                    maxHR: maxHR,
                    confirmedSleeps: confirmedSleeps,
                    confirmedWorkouts: confirmedWorkouts,
                    recoveredSkinTemperatureDeviationByDay:
                        recoveredSkinTemperatureDeviationByDay,
                    archiveHeartRatePoints: archiveHeartRatePoints,
                    biologicalSex: biologicalSex,
                    activeSessionID: activeSessionID,
                    now: now,
                    invalidatedDays: invalidatedDays,
                    calendar: .current,
                    shouldContinue: executionShouldContinue
                )
            guard let preparation, executionShouldContinue() else {
                DispatchQueue.main.async { completion?(false) }
                return
            }
            DispatchQueue.main.async {
                guard let self else {
                    completion?(false)
                    return
                }
                guard executionShouldContinue() else {
                    completion?(false)
                    return
                }
                self.publishPreparedDailyMetricsAndRollupsIfCurrent(
                    revision: revision,
                    rollupRevision: rollupRevision,
                    sourceDailyMetricRevision: existingDailyMetricRevision,
                    history: history,
                    sleep: sleep,
                    preparation: preparation,
                    preparationSessions:
                        preparationSessions,
                    executionShouldContinue:
                        executionShouldContinue,
                    progress: progress,
                    completion: completion
                )
            }
        }
    }

    private func publishPreparedDailyMetricsAndRollupsIfCurrent(revision: Int,
                                                                rollupRevision: Int,
                                                                sourceDailyMetricRevision: Int,
                                                                history: HistorySnapshot,
                                                                sleep: SleepHistorySnapshot,
                                                                preparation: DailyMetricRollupPreparation,
                                                                preparationSessions: [SavedSession]? = nil,
                                                                executionShouldContinue:
                                                                    @escaping @Sendable () -> Bool = { true },
                                                                progress: ((String) -> Void)? = nil,
                                                                completion: ((Bool) -> Void)? = nil) {
        guard executionShouldContinue(),
              revision == historySnapshotRevision,
              rollupRevision == dailyRollupPreparationRevision else {
            completion?(false)
            return
        }
        if sourceDailyMetricRevision != dailyMetricHistoryRevision {
            prepareDailyMetricRollupPreparationIfCurrent(revision: revision,
                                                         history: history,
                                                         sleep: sleep,
                                                         preparationSessions:
                                                            preparationSessions,
                                                         executionShouldContinue:
                                                            executionShouldContinue,
                                                         progress: progress,
                                                         completion: completion)
            return
        }
        let frozenTrends = TrendSummary.Window.allCases.map { window in
            Self.dailyMetricTrendSummary(
                metrics: preparation.metrics,
                rollups: history.rollups,
                days: window.rawValue,
                now: Date(),
                diagnosticSessionCount: history.sessions.count
            )
        }
        historySnapshot = history.replacingTrends(frozenTrends)
        sleepHistorySnapshot = sleep
        if preparation.metrics != dailyMetricHistory {
            dailyMetricHistory = preparation.metrics
            scheduleDailyMetricPersist(reason: "history_snapshot_refresh")
        }
        persistPreparedDailyRollups(preparation)
        progress?("daily_rollups")
        completion?(true)
        completeRequiredHistorySnapshotRefreshesIfPossible()
    }

    /// Read-only, flag-gated (`--atria-debug-dump-sleep`) diagnostic that makes
    /// the exact reason last night's sleep did not auto-detect observable on the
    /// device console: first the raw session inventory (is overnight HR even
    /// being captured?), then every sleep candidate the aggregator forms with
    /// its discriminator fields and the pass/fail of each auto-confirm gate. It
    /// mutates nothing and owns no BLE/archive state.
    private func dumpSleepCandidateDiagnostics(now: Date) {
        let calendar = Calendar.current
        let rest = baseline.restingInt ?? 60
        let baselineRestingIsTrusted = baseline.restingInt != nil
            && baseline.hasTrustedRestingBaseline(now: now)
        let baselineRestingIsNearTrusted = baseline.restingInt != nil
            && baseline.hasNearTrustedRestingBaselineForFragmentedSleep(now: now)
        let sessions = canonicalSessions(includeActiveJournal: true)
        let windowStart = now.addingTimeInterval(-48 * 3600)
        let recent = sessions.filter { $0.end >= windowStart }
        let totalPoints = recent.reduce(0) { $0 + $1.points.count }
        AtriaDebugLog(
            "ATRIADBG sleep_dump_inventory rest=%d resting_trusted=%d resting_near_trusted=%d sessions_48h=%d total_sessions=%d total_hr_points=%d",
            rest,
            baselineRestingIsTrusted ? 1 : 0,
            baselineRestingIsNearTrusted ? 1 : 0,
            recent.count,
            sessions.count,
            totalPoints
        )
        for session in recent.sorted(by: { $0.start > $1.start }).prefix(10) {
            AtriaDebugLog(
                "ATRIADBG sleep_dump_session start=%.0f end=%.0f dur_min=%.0f hr_points=%d rr_points=%d motion_validated=%d imu_samples=%d",
                session.start.timeIntervalSince1970,
                session.end.timeIntervalSince1970,
                session.end.timeIntervalSince(session.start) / 60,
                session.points.count,
                session.rrPoints?.count ?? 0,
                (session.motionEvidenceValidated ?? false) ? 1 : 0,
                session.imuSampleCount ?? 0
            )
        }
        let candidates = Self.aggregateSleepCandidates(
            in: sessions,
            rest: rest,
            maxHR: profile.maxHR,
            calendar: calendar,
            historicalMotionPolicy: .boundedRecent
        )
        AtriaDebugLog("ATRIADBG sleep_dump_candidates count=%d", candidates.count)
        for candidate in candidates.sorted(by: { $0.start > $1.start }).prefix(6) {
            let strong = Self.isStrongAutoConfirmableSleepCandidate(candidate)
            let unambiguous = Self.isUnambiguousHROnlyMainSleepCandidate(candidate)
            let fragmented = Self.isHighSpecificityFragmentedHROnlyMainSleepCandidate(candidate)
            let degradedReview = Self.isDegradedHROnlyOvernightSleepCandidate(candidate)
            let autoConfirmable = Self.isAutoConfirmableMainSleepCandidate(
                candidate,
                baselineRestingIsTrusted: baselineRestingIsTrusted,
                baselineRestingIsNearTrusted: baselineRestingIsNearTrusted
            )
            AtriaDebugLog(
                "ATRIADBG sleep_dump_candidate kind=%@ conf=%@ start=%.0f dur_h=%.2f span_h=%.2f maxGap_min=%.0f sessions=%d samples=%d hrCov=%.2f rrCov=%.2f maxHRgap_min=%.0f avgHR=%d medHR=%d p90=%d sd=%.1f baseRHR=%d restHR=%d elevFrac=%.3f motionValidated=%d | strong=%d unambig=%d frag=%d degradedReview=%d AUTO=%d",
                candidate.kind,
                String(describing: candidate.confidence),
                candidate.start.timeIntervalSince1970,
                candidate.duration / 3600,
                candidate.span / 3600,
                candidate.maxGap / 60,
                candidate.sessions,
                candidate.samples,
                candidate.hrObservedCoverageFraction,
                candidate.qualifiedRRCoverageFraction,
                candidate.maximumHRSampleGap / 60,
                candidate.avgHR,
                candidate.medianHR,
                candidate.hrP90,
                candidate.hrStandardDeviation,
                candidate.baselineRestingHR,
                candidate.restingHR,
                candidate.elevatedSampleFraction,
                candidate.motionEvidenceValidated ? 1 : 0,
                strong ? 1 : 0,
                unambiguous ? 1 : 0,
                fragmented ? 1 : 0,
                degradedReview ? 1 : 0,
                autoConfirmable ? 1 : 0
            )
            // Downstream + autonomic evidence: the SAME (hrv, hrvWindowCount) the
            // HRV baseline seed gates on (needs hrv>0 AND hrvWindowCount>=3), plus
            // the exact credited duration vs the 3h main-sleep floor. If a
            // confirmed version of this candidate would still fail these, fixing
            // detection alone won't lift "1 of 14 nights" / yesterday-strain.
            let m = Self.confirmedSleepWindowMetrics(
                from: sessions, start: candidate.start, end: candidate.end, rest: rest
            )
            AtriaDebugLog(
                "ATRIADBG sleep_dump_candidate_hrv start=%.0f dur_s=%.0f floor_s=%.0f meets_floor=%d hrv=%d hrvWindowCount=%d avgHR=%d restHR=%d",
                candidate.start.timeIntervalSince1970,
                candidate.duration,
                AtriaPhysiologicalCycle.minimumMainSleepDuration,
                candidate.duration >= AtriaPhysiologicalCycle.minimumMainSleepDuration ? 1 : 0,
                m.hrv ?? -1,
                m.hrvWindowCount,
                m.avgHR,
                m.restingHR
            )
        }
        // Autonomic reference: RMSSD over a recent AWAKE (daytime) window. The
        // only signal that separates real sleep from quiet-wake is a parasympathetic
        // RMSSD step-up of the candidate over this awake baseline. If candidate hrv
        // is NOT materially above this, HR-shape gates cannot safely admit it.
        if let awake = recent.sorted(by: { $0.start > $1.start }).first(where: { s in
            let ec = EventCivilTime.eventCalendar(timeZoneIdentifier: s.eventTimeZoneIdentifier, fallback: calendar)
            let h = ec.component(.hour, from: s.start)
            return h >= 9 && h <= 19 && s.end.timeIntervalSince(s.start) >= 30 * 60
        }) {
            let am = Self.confirmedSleepWindowMetrics(
                from: sessions, start: awake.start, end: awake.end, rest: rest
            )
            AtriaDebugLog(
                "ATRIADBG sleep_dump_awake_ref start=%.0f dur_min=%.0f hrv=%d hrvWindowCount=%d avgHR=%d restHR=%d",
                awake.start.timeIntervalSince1970,
                awake.end.timeIntervalSince(awake.start) / 60,
                am.hrv ?? -1,
                am.hrvWindowCount,
                am.avgHR,
                am.restingHR
            )
        }
        // Layer-2 evidence for the "no strain recorded yesterday" row: does the
        // persisted rollup for the prior civil day actually carry a strain, or is
        // the row nil only because the morning-whiteboard anchor (latestSleep.day)
        // is nil when sleep isn't detected?
        let today = calendar.startOfDay(for: now)
        for rollup in dailyRollupHistory.sorted(by: { $0.day > $1.day }).prefix(5) {
            let dayDelta = calendar.dateComponents([.day], from: calendar.startOfDay(for: rollup.day), to: today).day ?? -999
            AtriaDebugLog(
                "ATRIADBG sleep_dump_rollup day_ago=%d day=%.0f strain=%.2f trimp=%.1f strain_quality=%@",
                dayDelta,
                rollup.day.timeIntervalSince1970,
                rollup.strain ?? -1,
                rollup.trimp ?? -1,
                String(describing: rollup.strainEvidenceQuality)
            )
        }
    }

    private func persistDailyRollups(from metrics: [SavedDailyMetric]) {
        dailyRollupPreparationRevision &+= 1
        let rollupRevision = dailyRollupPreparationRevision
        let sourceSessions = sessions
        let sleep = sleepHistorySnapshot
        let baselineSnapshot = baseline
        let maxHR = profile.maxHR
        let confirmedSleeps = cachedConfirmedSleeps
        let confirmedWorkouts = cachedConfirmedWorkouts
        let archiveHeartRatePoints = cachedHistoricalTodayHeartRatePoints
        let biologicalSex = profile.biologicalSex
        let preparedAt = Date()
        DispatchQueue.global(qos: .utility).async { [weak self,
                                                     metrics,
                                                     sourceSessions,
                                                     sleep,
                                                     baselineSnapshot,
                                                     maxHR,
                                                     confirmedSleeps,
                                                     confirmedWorkouts,
                                                     archiveHeartRatePoints,
                                                     biologicalSex,
                                                     preparedAt,
                                                     rollupRevision] in
            let preparation = Self.makeDailyMetricRollupPreparation(metrics: metrics,
                                                                    sessions: sourceSessions,
                                                                    sleep: sleep,
                                                                    baseline: baselineSnapshot,
                                                                    maxHR: maxHR,
                                                                    confirmedSleeps: confirmedSleeps,
                                                                    confirmedWorkouts: confirmedWorkouts,
                                                                    archiveHeartRatePoints: archiveHeartRatePoints,
                                                                    biologicalSex: biologicalSex,
                                                                    preparedAt: preparedAt,
                                                                    invalidatedDays: [],
                                                                    calendar: .current)
            DispatchQueue.main.async {
                guard let self,
                      rollupRevision == self.dailyRollupPreparationRevision else { return }
                self.persistPreparedDailyRollups(preparation)
            }
        }
    }

    private func persistPreparedDailyRollups(_ preparation: DailyMetricRollupPreparation) {
        let calendar = Calendar.current
        let entries = preparation.rollupEntries
        AtriaDebugLog("ATRIADBG daily_rollup_persist_summary entries=%d respiratory_rows=%d rr_session_candidates=%d sessions=%d",
                      entries.count,
                      preparation.respiratoryRows,
                      preparation.rrSessionCandidates,
                      preparation.sessionsCount)
        // Pace-of-aging trend: stamp today's rollup row with the current fitness-age
        // delta (only once BiologicalAgeSummary.isReady) so the trend can be built
        // from the slope of this value over time. Past days keep whatever delta was
        // already persisted for them — makeDailyRollupStoreEntries recomputes those
        // rows fresh each refresh and has no way to know a historical delta.
        let today = calendar.startOfDay(for: preparation.preparedAt)
        let rollupVO2Estimate = vo2MaxEstimateSummary(rest: baseline.restingInt ?? 60,
                                                      maxHR: profile.maxHR)
        let todaysFitnessAgeSummary = biologicalAgeSummary(vo2MaxEstimate: rollupVO2Estimate)
        // 2026-08-22 insight dump (read-only, flag-gated): log the ACTUAL VO2max
        // and fitness-age values the app computes for display, from this reliable
        // launch-path computation, so #4's numbers are directly observable in the
        // device console rather than only inferred from inputs.
        if ProcessInfo.processInfo.arguments.contains("--atria-debug-dump-insights") {
            AtriaDebugLog(
                "ATRIADBG insight_dump rest=%d maxHR=%d resting_samples=%d vo2max_value=%.1f vo2max_confidence=%@ vo2max_detail=%@ bio_age=%d chrono_age=%d age_delta=%d aging_pace=%@ blockers=%@",
                baseline.restingInt ?? 60,
                profile.maxHR,
                baseline.freshRestingSampleCount(),
                rollupVO2Estimate.value ?? -1,
                rollupVO2Estimate.confidence,
                rollupVO2Estimate.detail,
                todaysFitnessAgeSummary.biologicalAge ?? -1,
                todaysFitnessAgeSummary.chronologicalAge,
                todaysFitnessAgeSummary.ageDelta ?? -999,
                todaysFitnessAgeSummary.agingPaceText,
                todaysFitnessAgeSummary.blockers.isEmpty
                    ? "none"
                    : todaysFitnessAgeSummary.blockers.joined(separator: ",")
            )
            // Broad insight coverage (#4 "many insights not showing"): show the
            // full spread of computable insight surfaces, not only VO2max, so it
            // is directly observable which categories render vs. are still
            // learning. Sourced from the newest prepared rollup + the baseline.
            let newest = preparation.rollupEntries.max { $0.day < $1.day }
            AtriaDebugLog(
                "ATRIADBG insight_dump_broad strain=%.2f trimp=%.1f recovery=%d sleep_perf=%d sleep_hours=%.2f hrv_nights=%d hrv_trusted=%d rhr_samples=%d rhr_trusted=%d behavior_insights=%d journal_insights=%d",
                newest?.strain ?? -1,
                newest?.trimp ?? -1,
                newest?.recovery ?? -1,
                newest?.sleepPerformance ?? -1,
                (newest?.sleepSeconds ?? 0) / 3600,
                baseline.freshHRVSampleCount(),
                baseline.hasTrustedHRVBaseline() ? 1 : 0,
                baseline.freshRestingSampleCount(),
                baseline.hasTrustedRestingBaseline() ? 1 : 0,
                behaviorInsights.count,
                journalInsightsCache.count
            )
        }
        if ProcessInfo.processInfo.arguments.contains("--atria-debug-dump-sleep") {
            dumpSleepCandidateDiagnostics(now: preparation.preparedAt)
        }
        let existingRollups = dailyRollupStore.rollups(last: 400)
        var existingFitnessAgeDeltaByDay: [Date: Int] = [:]
        var existingNutritionByDay: [Date: AtriaNutritionSummary] = [:]
        for entry in existingRollups {
            let day = calendar.startOfDay(for: entry.day)
            if let delta = entry.fitnessAgeDelta {
                existingFitnessAgeDeltaByDay[day] = delta
            }
            if let nutrition = entry.nutrition {
                existingNutritionByDay[day] = nutrition
            }
        }
        let persistedEntries = entries.map { entry -> DailyRollupStoreEntry in
            var entry = entry
            let entryDay = calendar.startOfDay(for: entry.day)
            if calendar.isDate(entry.day, inSameDayAs: today) {
                if todaysFitnessAgeSummary.isReady {
                    entry.fitnessAgeDelta = todaysFitnessAgeSummary.ageDelta
                }
            } else {
                entry.fitnessAgeDelta = existingFitnessAgeDeltaByDay[entryDay]
            }
            if entry.nutrition == nil {
                entry.nutrition = existingNutritionByDay[entryDay]
            }
            return entry
        }
        // The active Atria day is wake-to-wake, not midnight-to-midnight. The
        // preparation above intentionally retains civil-day history for charts,
        // but its current row used to persist the civil-day strain verbatim.
        // That made the stored Activity/trend value disagree with Home, widgets,
        // notifications and Lock Screen after a late wake or an all-nighter
        // fallback. Re-project only the active cycle's row from the exact same
        // canonical saved + archive evidence used by those live surfaces. No
        // live-only samples are invented here; they arrive through the normal
        // journal checkpoint path before becoming durable rollup evidence.
        let cycleAlignedEntries = Self.replacingActiveCycleStrain(
            in: persistedEntries,
            cycleStart: preparation.activeCycleStart,
            strain: preparation.activeCycleStrain,
            calendar: calendar
        )
        let didChangeRollups = !preparation.invalidatedDays.isEmpty
            || Self.preparedDailyRollupsNeedPersistence(cycleAlignedEntries,
                                                        existing: existingRollups,
                                                        calendar: calendar)
        if didChangeRollups {
            dailyRollupStore.reconcile(cycleAlignedEntries,
                                       replacingDays: preparation.invalidatedDays)
            dailyRollupHistory = dailyRollupStore.rollups(last: 400)
            dailyRollupHistoryRevision &+= 1
            if let transactionTicket = recoveredDataMutationTransaction.activeTicket {
                _ = recoveredDataMutationTransaction.registerCommit(
                    ticket: transactionTicket
                ) { [weak self] in
                    self?.publishDashboardRevision()
                }
            } else {
                publishDashboardRevision()
            }
        }
        pendingDailyDerivedInvalidationDays.subtract(preparation.invalidatedDays)
        if let transactionTicket = recoveredDataMutationTransaction.activeTicket {
            _ = recoveredDataMutationTransaction.registerCommit(ticket: transactionTicket) { [weak self] in
                self?.publishDailyRollupSideEffects(preparation: preparation,
                                                    entries: cycleAlignedEntries)
            }
        } else {
            publishDailyRollupSideEffects(preparation: preparation,
                                          entries: cycleAlignedEntries)
        }
    }

    private func publishDailyRollupSideEffects(
        preparation: DailyMetricRollupPreparation,
        entries: [DailyRollupStoreEntry]
    ) {
        refreshMaxHRSuggestion(reason: "daily_rollup", force: false)
        refreshNutritionRollupFromHealthIfEnabled(for: preparation.preparedAt, reason: "daily_rollup")
        scheduleEveningNutritionRefreshIfNeeded(now: preparation.preparedAt)
        scheduleMorningSummaryIfNeeded(metrics: preparation.metrics, now: preparation.preparedAt)
        Task { @MainActor in
            LocalNotificationScheduler.scheduleHealthDeviationIfNeeded(rollups: entries)
        }
    }

    /// Replaces only the rollup row that owns the active physiological cycle.
    /// Keeping this transformation pure makes the wake/civil-midnight contract
    /// testable without a SessionStore or filesystem.
    nonisolated static func replacingActiveCycleStrain(
        in entries: [DailyRollupStoreEntry],
        cycleStart: Date,
        strain: Double?,
        calendar: Calendar = .current
    ) -> [DailyRollupStoreEntry] {
        let cycleDay = calendar.startOfDay(for: cycleStart)
        return entries.map { entry in
            guard calendar.isDate(entry.day, inSameDayAs: cycleDay) else { return entry }
            var aligned = entry
            aligned.strain = strain
            return aligned
        }
    }

    nonisolated static func replacingActiveCycleStrain(
        in metrics: [SavedDailyMetric],
        cycleStart: Date,
        strain: Double?,
        trimp: Double? = nil,
        calendar: Calendar = .current
    ) -> [SavedDailyMetric] {
        let cycleDay = calendar.startOfDay(for: cycleStart)
        return metrics.map { metric in
            guard calendar.isDate(metric.day, inSameDayAs: cycleDay) else { return metric }
            return SavedDailyMetric(day: metric.day,
                                    recoveryPercent: metric.recoveryPercent,
                                    recoveryConfidence: metric.recoveryConfidence,
                                    hrv: metric.hrv,
                                    restingHR: metric.restingHR,
                                    respiratoryRate: metric.respiratoryRate,
                                    sleepDuration: metric.sleepDuration,
                                    sleepNeedSeconds: metric.sleepNeedSeconds,
                                    sleepSpan: metric.sleepSpan,
                                    sleepStart: metric.sleepStart,
                                    sleepEnd: metric.sleepEnd,
                                    sleepSource: metric.sleepSource,
                                    sleepStageSegments: metric.sleepStageSegments,
                                    sleepConsistencyPercent: metric.sleepConsistencyPercent,
                                    strain: strain,
                                    strainCoverageFraction: metric.strainCoverageFraction,
                                    strainEvidenceQuality: metric.strainEvidenceQuality,
                                    // Assessment P1.7: the raw TRIMP truth
                                    // rides with its display skin.
                                    dayTRIMP: trimp ?? metric.dayTRIMP,
                                    skinTemperatureDeviationCelsius: metric.skinTemperatureDeviationCelsius,
                                    recoverySummary: metric.recoverySummary)
        }
    }

    nonisolated static func preparedDailyRollupsNeedPersistence(_ prepared: [DailyRollupStoreEntry],
                                                                existing: [DailyRollupStoreEntry],
                                                                calendar: Calendar = .current) -> Bool {
        let existingByDay = Dictionary(existing.map {
            (calendar.startOfDay(for: $0.day), $0)
        }, uniquingKeysWith: { first, _ in first })
        return prepared.contains { entry in
            existingByDay[calendar.startOfDay(for: entry.day)] != entry
        }
    }

    private nonisolated static func makeDailyHistoryMetricRollupPreparation(history: HistorySnapshot,
                                                                            sleep: SleepHistorySnapshot,
                                                                            sessionsOverride: [SavedSession]? = nil,
                                                                            existingDailyMetrics: [SavedDailyMetric],
                                                                            baseline: PersonalBaseline,
                                                                            maxHR: Int,
                                                                            confirmedSleeps: [UserConfirmedSleep],
                                                                            confirmedWorkouts: [UserConfirmedWorkout] = [],
                                                                            recoveredSkinTemperatureDeviationByDay: [Date: Double] = [:],
                                                                            archiveHeartRatePoints: [HistoricalArchive.HeartRatePoint],
                                                                            biologicalSex: AthleteProfile.BiologicalSex,
                                                                            activeSessionID: UUID?,
                                                                            now: Date,
                                                                            invalidatedDays: Set<Date>,
                                                                            calendar: Calendar = .current) -> DailyMetricRollupPreparation {
        let sourceSessions = sessionsOverride ?? history.sessions
        let skinTemperatureDeviationByDay = finalizedSkinTemperatureDeviationByMorningDay(sessions: sourceSessions,
                                                                                          activeSessionID: activeSessionID,
                                                                                          calendar: calendar)
        let resolvedSkinTemperatureDeviationByDay =
            skinTemperatureDeviationByDay.merging(
                recoveredSkinTemperatureDeviationByDay,
                uniquingKeysWith: { sessionValue, _ in sessionValue }
            )
        let savedDailyMetrics = makeSavedDailyMetrics(rollups: history.rollups,
                                                      sleep: sleep,
                                                      baseline: baseline,
                                                      sessions: sourceSessions,
                                                      activeSessionID: activeSessionID,
                                                      skinTemperatureDeviationByDay: resolvedSkinTemperatureDeviationByDay,
                                                      calendar: calendar)
        let mergedDailyMetrics = mergeDailyMetricHistory(existing: existingDailyMetrics,
                                                         computed: savedDailyMetrics,
                                                         sessions: sourceSessions,
                                                         sleep: sleep,
                                                         baseline: baseline,
                                                         maxHR: maxHR,
                                                         now: now,
                                                         skinTemperatureDeviationByDay: resolvedSkinTemperatureDeviationByDay,
                                                         authoritativeDays: invalidatedDays,
                                                         calendar: calendar)
        return makeDailyMetricRollupPreparation(metrics: mergedDailyMetrics,
                                                sessions: sourceSessions,
                                                sleep: sleep,
                                                baseline: baseline,
                                                maxHR: maxHR,
                                                confirmedSleeps: confirmedSleeps,
                                                confirmedWorkouts: confirmedWorkouts,
                                                archiveHeartRatePoints: archiveHeartRatePoints,
                                                biologicalSex: biologicalSex,
                                                preparedAt: now,
                                                invalidatedDays: invalidatedDays,
                                                calendar: calendar)
    }

    private nonisolated static func makeDailyHistoryMetricRollupPreparationCancellable(
        history: HistorySnapshot,
        sleep: SleepHistorySnapshot,
        sessionsOverride: [SavedSession]? = nil,
        existingDailyMetrics: [SavedDailyMetric],
        baseline: PersonalBaseline,
        maxHR: Int,
        confirmedSleeps: [UserConfirmedSleep],
        confirmedWorkouts: [UserConfirmedWorkout] = [],
        recoveredSkinTemperatureDeviationByDay: [Date: Double] = [:],
        archiveHeartRatePoints: [HistoricalArchive.HeartRatePoint],
        biologicalSex: AthleteProfile.BiologicalSex,
        activeSessionID: UUID?,
        now: Date,
        invalidatedDays: Set<Date>,
        calendar: Calendar = .current,
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> DailyMetricRollupPreparation? {
        guard shouldContinue() else { return nil }
        let sourceSessions = sessionsOverride ?? history.sessions
        guard let sessionSkin =
                finalizedSkinTemperatureDeviationByMorningDayCancellable(
                    sessions: sourceSessions,
                    activeSessionID: activeSessionID,
                    calendar: calendar,
                    shouldContinue: shouldContinue
                ) else { return nil }
        let resolvedSkin = sessionSkin.merging(
            recoveredSkinTemperatureDeviationByDay,
            uniquingKeysWith: { sessionValue, _ in sessionValue }
        )
        guard shouldContinue() else { return nil }
        guard let savedDailyMetrics = makeSavedDailyMetricsCancellable(
            rollups: history.rollups,
            sleep: sleep,
            baseline: baseline,
            sessions: sourceSessions,
            activeSessionID: activeSessionID,
            skinTemperatureDeviationByDay: resolvedSkin,
            calendar: calendar,
            shouldContinue: shouldContinue
        ) else { return nil }
        guard let merged = mergeDailyMetricHistoryCancellable(
            existing: existingDailyMetrics,
            computed: savedDailyMetrics,
            sessions: sourceSessions,
            sleep: sleep,
            baseline: baseline,
            maxHR: maxHR,
            now: now,
            skinTemperatureDeviationByDay: resolvedSkin,
            authoritativeDays: invalidatedDays,
            calendar: calendar,
            shouldContinue: shouldContinue
        ) else { return nil }
        return makeDailyMetricRollupPreparationCancellable(
            metrics: merged,
            sessions: sourceSessions,
            sleep: sleep,
            baseline: baseline,
            maxHR: maxHR,
            confirmedSleeps: confirmedSleeps,
            confirmedWorkouts: confirmedWorkouts,
            archiveHeartRatePoints: archiveHeartRatePoints,
            biologicalSex: biologicalSex,
            preparedAt: now,
            invalidatedDays: invalidatedDays,
            calendar: calendar,
            shouldContinue: shouldContinue
        )
    }

    private nonisolated static func makeDailyMetricRollupPreparation(metrics: [SavedDailyMetric],
                                                                     sessions: [SavedSession],
                                                                     sleep: SleepHistorySnapshot,
                                                                     baseline: PersonalBaseline,
                                                                     maxHR: Int,
                                                                     confirmedSleeps: [UserConfirmedSleep],
                                                                     confirmedWorkouts: [UserConfirmedWorkout] = [],
                                                                     archiveHeartRatePoints: [HistoricalArchive.HeartRatePoint],
                                                                     biologicalSex: AthleteProfile.BiologicalSex,
                                                                     preparedAt: Date,
                                                                     invalidatedDays: Set<Date> = [],
                                                                     calendar: Calendar = .current) -> DailyMetricRollupPreparation {
        let napHoursByDay = napHoursByMorningDay(sleep: sleep, calendar: calendar)
        let rest = baseline.restingInt ?? 60
        let respiratoryPreparation = makeDailyRespiratoryRatePreparation(sessions: sessions,
                                                                         rest: rest,
                                                                         maxHR: maxHR,
                                                                         calendar: calendar)
        let cycle = AtriaPhysiologicalCycle.current(now: preparedAt,
                                                    confirmedSleeps: confirmedSleeps,
                                                    calendar: calendar)
        let physiologicalAggregate = homeSavedAggregate(
            from: makeCanonicalSessions(from: sessions),
            archiveHeartRatePoints: archiveHeartRatePoints,
            rest: rest,
            maxHR: maxHR,
            biologicalSex: biologicalSex,
            calendar: calendar,
            now: preparedAt,
            cycleStart: cycle.start,
            excludedLoadIntervals: confirmedSleeps.map {
                DateInterval(start: $0.start, end: $0.end)
            },
            rawSessionCount: sessions.count,
            // GAP-09: the persisted active-cycle strain row must fuse the same
            // logged muscular work as the live hero aggregate.
            confirmedWorkouts: confirmedWorkouts
        )
        let activeCycleStrain = physiologicalAggregate.hasSavedToday
            ? Metrics.strain(fromTRIMP: physiologicalAggregate.savedTodayTRIMP)
            : nil
        let cycleAlignedMetrics = replacingActiveCycleStrain(in: metrics,
                                                              cycleStart: cycle.start,
                                                              strain: activeCycleStrain,
                                                              trimp: physiologicalAggregate.hasSavedToday
                                                                  ? physiologicalAggregate.savedTodayTRIMP
                                                                  : nil,
                                                              calendar: calendar)
        let entries = makeDailyRollupStoreEntries(metrics: cycleAlignedMetrics,
                                                  sessions: sessions,
                                                  rest: rest,
                                                  maxHR: maxHR,
                                                  napHoursByDay: napHoursByDay,
                                                  respiratoryRateByMorningDay: respiratoryPreparation.respiratoryRateByMorningDay,
                                                  displaySleepEfficiencyByDay:
                                                    displaySleepEfficiencyByMorningDay(sleep: sleep,
                                                                                       calendar: calendar),
                                                  calendar: calendar)
        let respiratoryRows = entries.filter { $0.respiratoryRate != nil }.count
        return DailyMetricRollupPreparation(metrics: cycleAlignedMetrics,
                                            rollupEntries: entries,
                                            invalidatedDays: invalidatedDays,
                                            respiratoryRows: respiratoryRows,
                                            rrSessionCandidates: respiratoryPreparation.candidateCount,
                                            sessionsCount: sessions.count,
                                            preparedAt: preparedAt,
                                            activeCycleStart: cycle.start,
                                            activeCycleStrain: activeCycleStrain)
    }

    private nonisolated static func makeDailyMetricRollupPreparationCancellable(
        metrics: [SavedDailyMetric],
        sessions: [SavedSession],
        sleep: SleepHistorySnapshot,
        baseline: PersonalBaseline,
        maxHR: Int,
        confirmedSleeps: [UserConfirmedSleep],
        confirmedWorkouts: [UserConfirmedWorkout] = [],
        archiveHeartRatePoints: [HistoricalArchive.HeartRatePoint],
        biologicalSex: AthleteProfile.BiologicalSex,
        preparedAt: Date,
        invalidatedDays: Set<Date> = [],
        calendar: Calendar = .current,
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> DailyMetricRollupPreparation? {
        guard shouldContinue() else { return nil }
        guard let napHoursByDay = napHoursByMorningDayCancellable(
            sleep: sleep,
            calendar: calendar,
            shouldContinue: shouldContinue
        ) else { return nil }
        let rest = baseline.restingInt ?? 60
        guard let respiratory =
                makeDailyRespiratoryRatePreparationCancellable(
                    sessions: sessions,
                    rest: rest,
                    maxHR: maxHR,
                    calendar: calendar,
                    shouldContinue: shouldContinue
                ) else { return nil }
        let cycle = AtriaPhysiologicalCycle.current(
            now: preparedAt,
            confirmedSleeps: confirmedSleeps,
            calendar: calendar
        )
        guard let canonical = makeCanonicalSessionsCancellable(
            from: sessions,
            shouldContinue: shouldContinue
        ), let aggregate = homeSavedAggregateCancellable(
            from: canonical,
            archiveHeartRatePoints: archiveHeartRatePoints,
            rest: rest,
            maxHR: maxHR,
            biologicalSex: biologicalSex,
            calendar: calendar,
            now: preparedAt,
            cycleStart: cycle.start,
            excludedLoadIntervals: confirmedSleeps.map {
                DateInterval(start: $0.start, end: $0.end)
            },
            rawSessionCount: sessions.count,
            // GAP-09: the persisted active-cycle strain row must fuse the same
            // logged muscular work as the live hero aggregate.
            confirmedWorkouts: confirmedWorkouts,
            shouldContinue: shouldContinue
        ) else { return nil }
        let activeCycleStrain = aggregate.hasSavedToday
            ? Metrics.strain(fromTRIMP: aggregate.savedTodayTRIMP)
            : nil
        var cycleAlignedMetrics: [SavedDailyMetric] = []
        cycleAlignedMetrics.reserveCapacity(metrics.count)
        let cycleDay = calendar.startOfDay(for: cycle.start)
        for (index, metric) in metrics.enumerated() {
            if index.isMultiple(of: 64), !shouldContinue() { return nil }
            if calendar.isDate(metric.day, inSameDayAs: cycleDay) {
                cycleAlignedMetrics.append(SavedDailyMetric(
                    day: metric.day,
                    recoveryPercent: metric.recoveryPercent,
                    recoveryConfidence: metric.recoveryConfidence,
                    hrv: metric.hrv,
                    restingHR: metric.restingHR,
                    respiratoryRate: metric.respiratoryRate,
                    sleepDuration: metric.sleepDuration,
                    sleepNeedSeconds: metric.sleepNeedSeconds,
                    sleepSpan: metric.sleepSpan,
                    sleepStart: metric.sleepStart,
                    sleepEnd: metric.sleepEnd,
                    sleepSource: metric.sleepSource,
                    sleepStageSegments: metric.sleepStageSegments,
                    sleepConsistencyPercent:
                        metric.sleepConsistencyPercent,
                    strain: activeCycleStrain,
                    strainCoverageFraction: metric.strainCoverageFraction,
                    strainEvidenceQuality: metric.strainEvidenceQuality,
                    // Assessment P1.7: the raw TRIMP truth rides with its
                    // display skin.
                    dayTRIMP: aggregate.hasSavedToday
                        ? aggregate.savedTodayTRIMP
                        : metric.dayTRIMP,
                    skinTemperatureDeviationCelsius:
                        metric.skinTemperatureDeviationCelsius,
                    recoverySummary: metric.recoverySummary
                ))
            } else {
                cycleAlignedMetrics.append(metric)
            }
        }
        guard shouldContinue() else { return nil }
        guard let entries = makeDailyRollupStoreEntriesCancellable(
            metrics: cycleAlignedMetrics,
            sessions: sessions,
            rest: rest,
            maxHR: maxHR,
            napHoursByDay: napHoursByDay,
            respiratoryRateByMorningDay:
                respiratory.respiratoryRateByMorningDay,
            displaySleepEfficiencyByDay:
                displaySleepEfficiencyByMorningDay(sleep: sleep,
                                                   calendar: calendar),
            calendar: calendar,
            shouldContinue: shouldContinue
        ) else { return nil }
        var respiratoryRows = 0
        for (index, entry) in entries.enumerated() {
            if index.isMultiple(of: 64), !shouldContinue() { return nil }
            if entry.respiratoryRate != nil { respiratoryRows += 1 }
        }
        return shouldContinue() ? .init(
            metrics: cycleAlignedMetrics,
            rollupEntries: entries,
            invalidatedDays: invalidatedDays,
            respiratoryRows: respiratoryRows,
            rrSessionCandidates: respiratory.candidateCount,
            sessionsCount: sessions.count,
            preparedAt: preparedAt,
            activeCycleStart: cycle.start,
            activeCycleStrain: activeCycleStrain
        ) : nil
    }

    /// Attributes a nap to the next confirmed main sleep's physiological
    /// wake-to-bed interval. Civil-day bucketing gives Tuesday afternoon's nap
    /// to Tuesday morning and can retroactively credit a post-wake nap; neither
    /// reflects the sleep need that the nap actually reduced.
    nonisolated static func napHoursByMorningDay(
        sleep: SleepHistorySnapshot,
        calendar: Calendar = .current
    ) -> [Date: Double] {
        var result: [Date: Double] = [:]
        for night in sleep.nights where night.confirmed && !night.isNapEvidence {
            let hours = sleep.sameDayNapHours(for: night, calendar: calendar)
            guard hours > 0 else { continue }
            result[calendar.startOfDay(for: night.day)] = hours
        }
        return result
    }

    nonisolated static func napHoursByMorningDayCancellable(
        sleep: SleepHistorySnapshot,
        calendar: Calendar = .current,
        shouldContinue: () -> Bool
    ) -> [Date: Double]? {
        var result: [Date: Double] = [:]
        for (index, night) in sleep.nights.enumerated() {
            if index.isMultiple(of: 16), !shouldContinue() { return nil }
            guard night.confirmed, !night.isNapEvidence else { continue }
            let hours = sleep.sameDayNapHours(for: night, calendar: calendar)
            guard shouldContinue() else { return nil }
            if hours > 0 {
                result[calendar.startOfDay(for: night.day)] = hours
            }
        }
        return shouldContinue() ? result : nil
    }

    private func refreshNutritionRollupFromHealthIfEnabled(for day: Date,
                                                           reason: String,
                                                           calendar: Calendar = .current) {
        guard UserDefaults.standard.bool(forKey: AtriaNutritionContext.healthReadNutritionKey) else {
            return
        }
        healthKitExporter.fetchNutritionSummary(for: day, calendar: calendar) { [weak self] summary, healthBodyMassKg in
            guard let self,
                  let summary,
                  summary.hasData else { return }
            Task { @MainActor in
                self.upsertNutritionRollup(summary,
                                           day: day,
                                           reason: reason,
                                           healthBodyMassKg: healthBodyMassKg,
                                           calendar: calendar)
            }
        }
    }

    private func upsertNutritionRollup(_ summary: AtriaNutritionSummary,
                                       day: Date,
                                       reason: String,
                                       healthBodyMassKg: Double?,
                                       calendar: Calendar = .current) {
        let normalizedDay = calendar.startOfDay(for: day)
        let existing = dailyRollupStore.rollup(for: normalizedDay)
        let merged = DailyRollupStoreEntry(day: existing?.day ?? normalizedDay,
                                           tzOffsetMinutes: existing?.tzOffsetMinutes,
                                           recovery: existing?.recovery,
                                           lnRMSSD: existing?.lnRMSSD,
                                           rhr: existing?.rhr,
                                           sleepSeconds: existing?.sleepSeconds,
                                           sleepNeedSeconds: existing?.sleepNeedSeconds,
                                           sleepPerformance: existing?.sleepPerformance,
                                           bedtimeMinutes: existing?.bedtimeMinutes,
                                           strain: existing?.strain,
                                           strainCoverageFraction: existing?.strainCoverageFraction,
                                           strainEvidenceQuality: existing?.strainEvidenceQuality,
                                           respiratoryRate: existing?.respiratoryRate,
                                           skinTemperatureDeviationCelsius: existing?.skinTemperatureDeviationCelsius,
                                           vitals: existing?.vitals,
                                           nutrition: summary,
                                           fitnessAgeDelta: existing?.fitnessAgeDelta,
                                           calendar: calendar)
        dailyRollupStore.upsert(merged)
        dailyRollupHistory = dailyRollupStore.rollups(last: 400)
        dailyRollupHistoryRevision &+= 1
        let proteinBodyMassKg = healthBodyMassKg ?? (profile.weightKg > 0 ? profile.weightKg : nil)
        applyNutritionAutoTags(summary.autoJournalTags(bodyMassKg: proteinBodyMassKg),
                               day: normalizedDay,
                               calendar: calendar)
        AtriaDebugLog("ATRIADBG daily_rollup_nutrition_merge status=ok reason=%@ day=%@ has_fuel=%d body_mass_source=%@",
                      reason,
                      Self.localDayIdentifier(for: normalizedDay, calendar: calendar),
                      summary.fuelSummary == nil ? 0 : 1,
                      healthBodyMassKg == nil ? "profile_or_missing" : "health")
    }

    private func scheduleEveningNutritionRefreshIfNeeded(now: Date = Date(),
                                                         calendar: Calendar = .current) {
        guard UserDefaults.standard.bool(forKey: AtriaNutritionContext.healthReadNutritionKey) else {
            return
        }
        let minutes = calendar.component(.hour, from: now) * 60 + calendar.component(.minute, from: now)
        guard minutes >= 21 * 60 else {
            return
        }
        let today = calendar.startOfDay(for: now)
        let dayID = Self.localDayIdentifier(for: today, calendar: calendar)
        let defaults = UserDefaults.standard
        guard defaults.string(forKey: Self.nutritionEveningRefreshLastDayKey) != dayID else {
            AtriaDebugLog("ATRIADBG healthkit_nutrition_evening_refresh status=skipped reason=already_refreshed day=%@",
                          dayID)
            return
        }
        defaults.set(dayID, forKey: Self.nutritionEveningRefreshLastDayKey)
        AtriaDebugLog("ATRIADBG healthkit_nutrition_evening_refresh status=requested day=%@",
                      dayID)
        refreshNutritionRollupFromHealthIfEnabled(for: today,
                                                  reason: "evening_21h",
                                                  calendar: calendar)
    }

    /// A background pass (BGProcessing) in the morning is the app's chance to
    /// deliver the morning summary WITHOUT the user opening the app. The rollup
    /// publish that calls `scheduleMorningSummaryIfNeeded` is not foreground-gated,
    /// but it only runs when something re-projects the snapshot. On a morning where
    /// today's sleep is ALREADY confirmed (so the background auto-confirm doesn't
    /// trigger a refresh) the summary would otherwise never get a background
    /// scheduling attempt. This re-projects to close exactly that gap — gated so it
    /// only fires inside the wake-anchored window, only when a real wake exists,
    /// and stops once the summary has been scheduled for the day.
    private func materializeMorningMetricForSummaryInBackgroundIfNeeded(
        now: Date,
        calendar: Calendar
    ) {
        let today = calendar.startOfDay(for: now)
        let dayID = Self.localDayIdentifier(for: today, calendar: calendar)
        guard UserDefaults.standard.string(forKey: Self.morningSummaryLastScheduledDayKey) != dayID else {
            return
        }
        // Wake = end of the most recent confirmed sleep the user woke from today.
        let wake = cachedConfirmedSleeps
            .filter { calendar.isDate($0.end, inSameDayAs: today) }
            .map(\.end)
            .max()
        guard let wake,
              Self.isWithinMorningSummaryWindow(now: now, wake: wake, calendar: calendar) else {
            return
        }
        AtriaDebugLog("ATRIADBG morning_summary_bg_materialize day=%@ action=reproject_so_rollup_publish_schedules_summary",
                      dayID)
        // Re-project off-main; the rollup publish that follows reaches
        // scheduleMorningSummaryIfNeeded with a freshly materialized today metric.
        refreshHistorySnapshotCache(deferred: true)
    }

    /// Whether `now` is inside the morning-summary window. Anchored to the
    /// confirmed WAKE (`wake`) rather than a fixed clock cutoff: the summary may
    /// fire up to `hoursAfterWake` after waking (generous, to absorb the drain +
    /// materialization lag that delivers the metric), but never in the
    /// afternoon/evening (a hard `latestHour` cap) and never before an
    /// `earliestHour` floor. With no confirmed wake it falls back to the original
    /// conservative 11:30 AM bound. Pure + unit-tested.
    nonisolated static func isWithinMorningSummaryWindow(
        now: Date,
        wake: Date?,
        calendar: Calendar,
        earliestHour: Int = 4,
        latestHour: Int = 14,
        hoursAfterWake: Double = 4
    ) -> Bool {
        let minutes = calendar.component(.hour, from: now) * 60
            + calendar.component(.minute, from: now)
        guard minutes >= earliestHour * 60, minutes <= latestHour * 60 else { return false }
        guard let wake, wake <= now else {
            return minutes <= 11 * 60 + 30
        }
        return now.timeIntervalSince(wake) <= hoursAfterWake * 3600
    }

    private func scheduleMorningSummaryIfNeeded(metrics: [SavedDailyMetric],
                                                now: Date = Date(),
                                                calendar: Calendar = .current) {
        let today = calendar.startOfDay(for: now)
        let dayID = Self.localDayIdentifier(for: today, calendar: calendar)
        let defaults = UserDefaults.standard
        guard defaults.string(forKey: Self.morningSummaryLastScheduledDayKey) != dayID else {
            AtriaDebugLog("ATRIADBG morning_summary_skip reason=already_scheduled day=%@", dayID)
            return
        }

        // THIS is the confirmed-boundary gate for the notification that asserts
        // measurements: sleepDuration only exists once a sleep has been
        // persisted into the day's metric, so the rich summary cannot fire on an
        // unconfirmed night. The plain journal check-in has no equivalent gate
        // on purpose -- it claims nothing, and gating it too would reproduce the
        // silent morning reported 2026-07-08.
        //
        // Recorded durably rather than only logged, so a morning with no rich
        // summary can say which input was missing instead of being silent about
        // its own silence. Checked BEFORE the time window so `metric.sleepEnd` is
        // available to anchor the window to the user's actual wake.
        guard let metric = metrics.first(where: { calendar.isDate($0.day, inSameDayAs: today) }),
              let recovery = metric.recoveryPercent,
              let hrv = metric.hrv,
              let sleepDuration = metric.sleepDuration else {
            AtriaDebugLog("ATRIADBG morning_summary_skip reason=missing_metric day=%@", dayID)
            AtriaNotificationAttemptStore.record(
                kind: LocalNotificationScheduler.morningSummaryKind,
                outcome: .deferred,
                reason: "awaiting_confirmed_sleep_metric",
                at: now
            )
            return
        }

        // The morning summary is a "just after you woke" nudge, so its window is
        // anchored to the confirmed WAKE (metric.sleepEnd), NOT a fixed 11:30 AM
        // cutoff. A late riser (wake ~10:50) has their sleep metric materialize
        // after 11:30, so the old fixed window silently dropped the summary every
        // time it was actually ready. Reported 2026-08-03: silent morning.
        guard Self.isWithinMorningSummaryWindow(now: now,
                                                wake: metric.sleepEnd,
                                                calendar: calendar) else {
            let minutes = calendar.component(.hour, from: now) * 60
                + calendar.component(.minute, from: now)
            AtriaDebugLog("ATRIADBG morning_summary_skip reason=outside_window local_minutes=%d wake_present=%d",
                          minutes,
                          metric.sleepEnd != nil ? 1 : 0)
            return
        }

        let sleepText = AtriaMetricFormat.sleepDuration(seconds: sleepDuration)
        let hrvText = "\(hrv) ms"
        guard AtriaNotificationSettings.load().allows(kind: "morning_summary") else {
            LocalNotificationScheduler.scheduleMorningSummary(recovery: recovery,
                                                              sleepText: sleepText,
                                                              hrvText: hrvText,
                                                              sleepDurationSeconds: sleepDuration,
                                                              now: now,
                                                              calendar: calendar)
            return
        }

        LocalNotificationScheduler.scheduleMorningSummary(recovery: recovery,
                                                          sleepText: sleepText,
                                                          hrvText: hrvText,
                                                          sleepDurationSeconds: sleepDuration,
                                                          now: now,
                                                          calendar: calendar)
        defaults.set(dayID, forKey: Self.morningSummaryLastScheduledDayKey)
        AtriaDebugLog("ATRIADBG morning_summary_request status=scheduled day=%@ recovery=%d hrv=%d sleep_s=%.0f",
                      dayID,
                      recovery,
                      hrv,
                      sleepDuration)
    }

    private static func localDayIdentifier(for date: Date, calendar: Calendar) -> String {
        let components = calendar.dateComponents([.year, .month, .day], from: date)
        return String(format: "%04d-%02d-%02d",
                      components.year ?? 0,
                      components.month ?? 0,
                      components.day ?? 0)
    }

    private func refreshOverviewTrendPointsCache(
        deferred: Bool = true,
        executionShouldContinue:
            @escaping @Sendable () -> Bool = { true },
        completion: ((Bool) -> Void)? = nil
    ) {
        guard executionShouldContinue() else {
            completion?(false)
            return
        }
        overviewTrendPointsRefreshRevision &+= 1
        let revision = overviewTrendPointsRefreshRevision
        let source = canonicalSessions()
        let rest = baseline.restingInt ?? 60
        let maxHR = profile.maxHR
        let confirmedSleeps = cachedConfirmedSleeps
        let workouts = cachedConfirmedWorkouts
        let delay: TimeInterval = deferred ? 0.12 : 0
        DispatchQueue.global(qos: .utility).asyncAfter(deadline: .now() + delay) { [weak self, source, rest, maxHR, confirmedSleeps, workouts, revision, executionShouldContinue] in
            guard executionShouldContinue() else {
                DispatchQueue.main.async { completion?(false) }
                return
            }
            // Dying thread (2026-08-05 climber-hunt runner-up hardening): the
            // whole-corpus trend walk's transient garbage must be reclaimed at
            // teardown, not retained by this long-lived GCD pool thread — the
            // in-repo note near the derived-lease renewals records this exact
            // trio jetsamming at ~700k points.
            let points = AtriaTransientWorkThread.run(
                name: "atria.overview-trends",
                qualityOfService: .utility
            ) {
                SessionStore.makeOverviewTrendPointsCancellable(
                    sessions: source,
                    rest: rest,
                    maxHR: maxHR,
                    confirmedSleeps: confirmedSleeps,
                    confirmedWorkouts: workouts,
                    shouldContinue: executionShouldContinue
                )
            }
            guard let points, executionShouldContinue() else {
                DispatchQueue.main.async { completion?(false) }
                return
            }
            DispatchQueue.main.async {
                guard executionShouldContinue(),
                      let self,
                      revision == self.overviewTrendPointsRefreshRevision else {
                    completion?(false)
                    return
                }
                if points != self.overviewTrendPoints {
                    self.overviewTrendPointsRevision &+= 1
                    self.overviewTrendPoints = points
                }
                completion?(true)
            }
        }
    }

    private func refreshTrainingLoadSummaryCache(
