    func refreshHistoricalArchiveStatus(
        reason: String = "manual",
        deferDerivedPublication: Bool = false,
        executionShouldContinue:
            @escaping @Sendable () -> Bool = { true },
        completion: ((Bool) -> Void)? = nil
    ) {
        guard executionShouldContinue() else {
            completion?(false)
            return
        }
        historicalArchiveStatusRevision &+= 1
        let revision = historicalArchiveStatusRevision
        let confirmedWorkouts = cachedConfirmedWorkouts
        DispatchQueue.global(qos: .utility).async { [weak self, reason, confirmedWorkouts, executionShouldContinue] in
            guard executionShouldContinue() else {
                DispatchQueue.main.async { completion?(false) }
                return
            }
            // Fresh dying thread for the archive walk: diagnostics() churns
            // transient allocations this long-lived GCD thread would retain
            // until jetsam (2026-08-04 thread-teardown reclaim law).
            let preparation = AtriaTransientWorkThread.run(
                name: "atria.archive-status",
                qualityOfService: .utility
            ) { () -> (HistoricalArchive.Diagnostics, HistoricalArchiveStatus, SessionStore.HistoricalRecoveryWindow?)? in
                guard let diagnostics = HistoricalArchive.diagnostics(
                    shouldContinue: executionShouldContinue
                ) else { return nil }
                let status = HistoricalArchiveStatus(diagnostics: diagnostics)
                let recoveryWindow = SessionStore.historicalRecoveryWindow(
                    confirmedWorkouts: confirmedWorkouts,
                    archiveLastUnix: diagnostics.correctedUnixLast ?? diagnostics.unixLast,
                    now: Date()
                )
                return (diagnostics, status, recoveryWindow)
            }
            guard let (diagnostics, status, recoveryWindow) = preparation,
                  executionShouldContinue() else {
                DispatchQueue.main.async { completion?(false) }
                return
            }
            DispatchQueue.main.async {
                guard executionShouldContinue(),
                      let self,
                      revision == self.historicalArchiveStatusRevision else {
                    completion?(false)
                    return
                }
                self.historicalArchiveStatus = status
                // Sync-progress footer frontier: display-only "synced through"
                // marker. Monotonic-max only — the durable-flush path in
                // HistoricalArchive advances this live during a drain, and the
                // archive diagnostics here can lag materialization by hours;
                // regressing the display made a working drain read as stuck.
                if let frontier = diagnostics.correctedUnixLast ?? diagnostics.unixLast,
                   frontier > 0 {
                    let key = AtriaBLEManager.OfflineSyncDefaults.drainedThroughUnix
                    let defaults = UserDefaults.standard
                    if Double(frontier) > defaults.double(forKey: key) {
                        defaults.set(Double(frontier), forKey: key)
                    }
                }
                guard !diagnostics.exists || diagnostics.parseOK else {
                    completion?(false)
                    return
                }
                self.refreshHistoricalTodayHeartRateCache(
                    reason: reason,
                    deferDerivedPublication: deferDerivedPublication,
                    completion: completion
                )
                if let recoveryWindow {
                    let archiveLast = diagnostics.correctedUnixLast ?? diagnostics.unixLast ?? 0
                    if let transactionTicket = self.recoveredDataMutationTransaction.activeTicket {
                        _ = self.recoveredDataMutationTransaction.registerCommit(
                            ticket: transactionTicket
                        ) { [weak self] in
                            self?.publishHistoricalRecoveryWindow(
                                recoveryWindow,
                                reason: reason,
                                archiveLast: archiveLast
                            )
                        }
                    } else {
                        self.publishHistoricalRecoveryWindow(
                            recoveryWindow,
                            reason: reason,
                            archiveLast: archiveLast
                        )
                    }
                }
                AtriaDebugLog("ATRIADBG historical_archive_status reason=%@ exists=%d parse_ok=%d rows=%d metric_usable=%d current_usable=%d metric_ready=%d fail_closed=%d status=%@ gate=%@ detail=%@",
                              reason,
                              diagnostics.exists ? 1 : 0,
                              diagnostics.parseOK ? 1 : 0,
                              diagnostics.rows,
                              diagnostics.metricUsableRows,
                              diagnostics.currentSessionUsableRows,
                              status.metricReady ? 1 : 0,
                              status.hasArchiveRows && !status.metricReady ? 1 : 0,
                              status.valueText,
                              status.metricGateText,
                              status.detailText)
            }
        }
    }

    private func publishHistoricalRecoveryWindow(
        _ recoveryWindow: HistoricalRecoveryWindow,
        reason: String,
        archiveLast: UInt32
    ) {
        let defaults = UserDefaults.standard
        let previousStart = defaults.double(
            forKey: AtriaBLEManager.OfflineSyncDefaults.recoveryWindowStart
        )
        let previousEnd = defaults.double(
            forKey: AtriaBLEManager.OfflineSyncDefaults.recoveryWindowEnd
        )
        let shouldNotify = !defaults.bool(
            forKey: AtriaBLEManager.OfflineSyncDefaults.rangeLossBackfillPending
        )
            || abs(previousStart - recoveryWindow.start.timeIntervalSince1970) > 1
            || abs(previousEnd - recoveryWindow.end.timeIntervalSince1970) > 1
        if !defaults.bool(forKey: AtriaBLEManager.OfflineSyncDefaults.rangeLossBackfillPending) {
            defaults.set(Date().timeIntervalSince1970,
                         forKey: AtriaBLEManager.OfflineSyncDefaults.rangeLossBackfillRequestedAt)
        }
        defaults.set(true, forKey: AtriaBLEManager.OfflineSyncDefaults.rangeLossBackfillPending)
        defaults.set("confirmed_workout_archive_gap",
                     forKey: AtriaBLEManager.OfflineSyncDefaults.rangeLossBackfillReason)
        defaults.set(recoveryWindow.start.timeIntervalSince1970,
                     forKey: AtriaBLEManager.OfflineSyncDefaults.recoveryWindowStart)
        defaults.set(recoveryWindow.end.timeIntervalSince1970,
                     forKey: AtriaBLEManager.OfflineSyncDefaults.recoveryWindowEnd)
        defaults.set("recovery_window_pending",
                     forKey: AtriaBLEManager.OfflineSyncDefaults.lastStatus)
        defaults.set(reason, forKey: AtriaBLEManager.OfflineSyncDefaults.lastReason)
        AtriaDebugLog("ATRIADBG offline_sync status=recovery_window_pending reason=%@ start_unix=%d end_unix=%d coverage=%d archive_last=%u action=retry_until_window_overlap",
                      reason,
                      Int(recoveryWindow.start.timeIntervalSince1970),
                      Int(recoveryWindow.end.timeIntervalSince1970),
                      recoveryWindow.coveragePercent,
                      archiveLast)
        if shouldNotify {
            NotificationCenter.default.post(name: SessionStore.historicalRecoveryNeededNotification,
                                            object: nil)
        }
    }

    private func refreshHistoricalTodayHeartRateCache(
        reason: String,
        deferDerivedPublication: Bool = false,
        completion: ((Bool) -> Void)? = nil
    ) {
        historicalTodayHeartRateRevision &+= 1
        let revision = historicalTodayHeartRateRevision
        let calendar = Calendar.current
        let now = Date()
        let cacheInterval = Self.historicalStrainCacheInterval(now: now,
                                                               confirmedSleeps: cachedConfirmedSleeps,
                                                               calendar: calendar)
        let cycleStart = cacheInterval.start
        let source = cachedRecoveredArchiveHeartRatePoints
        DispatchQueue.global(qos: .utility).async { [weak self, source] in
            let points = source.filter { $0.t >= cycleStart && $0.t < now }
            DispatchQueue.main.async {
                guard let self, revision == self.historicalTodayHeartRateRevision else {
                    completion?(false)
                    return
                }
                guard points != self.cachedHistoricalTodayHeartRatePoints
                        || self.cachedHistoricalCycleStart != cycleStart else {
                    completion?(true)
                    return
                }
                self.cachedHistoricalTodayHeartRatePoints = points
                self.cachedHistoricalCycleStart = cycleStart
                self.cachedHomeSavedAggregate = nil
                self.cachedTodayTRIMP = nil
                if !deferDerivedPublication {
                    self.refreshHistorySnapshotCache(deferred: true)
                    self.publishDashboardRevision()
                }
                AtriaDebugLog("ATRIADBG archive_cycle_strain status=refreshed reason=%@ start_unix=%d points=%d",
                              reason, Int(cycleStart.timeIntervalSince1970), points.count)
                completion?(true)
            }
        }
    }

    nonisolated static func historicalStrainCacheInterval(
        now: Date,
        confirmedSleeps: [UserConfirmedSleep],
        calendar: Calendar = .current
    ) -> DateInterval {
        let cycle = AtriaPhysiologicalCycle.current(now: now,
                                                    confirmedSleeps: confirmedSleeps,
                                                    calendar: calendar)
        return DateInterval(start: cycle.start, end: now)
    }

    struct HistoricalRecoveryWindow: Equatable {
        let start: Date
        let end: Date
        let coveragePercent: Int
    }

    nonisolated static func historicalRecoveryRequestIsSatisfied(
        original: UserConfirmedWorkout,
        replacement: UserConfirmedWorkout,
        requestedStart: Date,
        requestedEnd: Date,
        minimumCoveragePercent: Int = 100
    ) -> Bool {
        guard replacement.id == original.id,
              replacement.streamCoveragePercent > original.streamCoveragePercent,
              replacement.streamCoveragePercent >= minimumCoveragePercent else { return false }
        let boundaryTolerance: TimeInterval = 1
        return abs(original.start.timeIntervalSince(requestedStart)) <= boundaryTolerance
            && abs(original.end.timeIntervalSince(requestedEnd)) <= boundaryTolerance
    }

    @discardableResult
    static func resolveHistoricalRecoveryRequestIfSatisfied(
        by replacements: [(original: UserConfirmedWorkout, replacement: UserConfirmedWorkout)],
        defaults: UserDefaults = .standard
    ) -> Bool {
        guard defaults.bool(forKey: AtriaBLEManager.OfflineSyncDefaults.rangeLossBackfillPending),
              defaults.object(forKey: AtriaBLEManager.OfflineSyncDefaults.recoveryWindowStart) != nil,
              defaults.object(forKey: AtriaBLEManager.OfflineSyncDefaults.recoveryWindowEnd) != nil else { return false }
        let requestedStart = Date(timeIntervalSince1970: defaults.double(
            forKey: AtriaBLEManager.OfflineSyncDefaults.recoveryWindowStart
        ))
        let requestedEnd = Date(timeIntervalSince1970: defaults.double(
            forKey: AtriaBLEManager.OfflineSyncDefaults.recoveryWindowEnd
        ))
        guard replacements.contains(where: {
            Self.historicalRecoveryRequestIsSatisfied(
                original: $0.original,
                replacement: $0.replacement,
                requestedStart: requestedStart,
                requestedEnd: requestedEnd
            )
        }) else { return false }

        defaults.set(false, forKey: AtriaBLEManager.OfflineSyncDefaults.rangeLossBackfillPending)
        defaults.removeObject(forKey: AtriaBLEManager.OfflineSyncDefaults.recoveryWindowStart)
        defaults.removeObject(forKey: AtriaBLEManager.OfflineSyncDefaults.recoveryWindowEnd)
        defaults.set("confirmed_workout_rehydrated", forKey: AtriaBLEManager.OfflineSyncDefaults.lastStatus)
        defaults.set(Date().timeIntervalSince1970,
                     forKey: AtriaBLEManager.OfflineSyncDefaults.rangeLossBackfillStartedAt)
        AtriaDebugLog("ATRIADBG offline_sync status=confirmed_workout_rehydrated coverage_floor=100 action=exact_window_resolved")
        NotificationCenter.default.post(name: Self.historicalRecoveryResolvedNotification,
                                        object: nil)
        return true
    }

    nonisolated static func historicalRecoveryWindow(
        confirmedWorkouts: [UserConfirmedWorkout],
        archiveLastUnix: UInt32?,
        now: Date,
        maximumAge: TimeInterval = 7 * 24 * 60 * 60
    ) -> HistoricalRecoveryWindow? {
        let archiveLast = archiveLastUnix.map { Date(timeIntervalSince1970: TimeInterval($0)) }
        return confirmedWorkouts
            .filter { workout in
                workout.streamCoveragePercent < 100
                    && workout.duration >= 5 * 60
                    && workout.end <= now.addingTimeInterval(5 * 60)
                    && now.timeIntervalSince(workout.end) <= maximumAge
                    && (archiveLast == nil || archiveLast! < workout.end)
            }
            .max(by: { $0.end < $1.end })
            .map { HistoricalRecoveryWindow(start: $0.start,
                                            end: $0.end,
                                            coveragePercent: $0.streamCoveragePercent) }
    }

    private nonisolated static func prepareRecoveredProjectionInstall(
        incomingRecoveredSessions: [SavedSession],
        incomingArchiveHeartRatePoints: [HistoricalArchive.HeartRatePoint],
        recoveredSkinTemperatureProjection: RecoveredSkinTemperatureProjection,
        recoveredSkinTemperatureCandidateFrameCount: Int,
        recoveredAutomaticCacheAuthority:
            HistoricalArchive.AutomaticRecoveredDataCacheAuthority?,
        previousRecoveredSessions: [SavedSession],
        previousArchiveHeartRatePoints: [HistoricalArchive.HeartRatePoint],
        previousSkinTemperatureDeviationByDay: [Date: Double],
        previousSkinTemperatureBaselineNightCount: Int,
        previousSkinTemperatureCandidateFrameCount: Int,
        sourceSessions: [SavedSession],
        activeJournalSession: SavedSession?,
        sourceCanonicalRevision: Int,
        sourceConfirmedSleepsRevision: Int,
        previousBaseline: PersonalBaseline,
        profile: AthleteProfile,
        confirmedSleeps: [UserConfirmedSleep],
        automaticCurrentCycleCutoff: Date?,
        now: Date,
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> RecoveredProjectionInstallPreparation? {
        guard shouldContinue() else { return nil }
        let publishedRecoveredSessions: [SavedSession]
        if automaticCurrentCycleCutoff != nil {
            guard let merged = mergedAutomaticallyRecoveredSessionsCancellable(
                previous: previousRecoveredSessions,
                incoming: incomingRecoveredSessions,
                shouldContinue: shouldContinue
            ) else { return nil }
            publishedRecoveredSessions = merged
        } else {
            publishedRecoveredSessions = incomingRecoveredSessions
        }

        let publishedArchiveHeartRatePoints:
            [HistoricalArchive.HeartRatePoint]
        if automaticCurrentCycleCutoff != nil {
            guard let merged =
                    mergedAutomaticallyRecoveredHeartRatePointsCancellable(
                        previous: previousArchiveHeartRatePoints,
                        incoming: incomingArchiveHeartRatePoints,
                        shouldContinue: shouldContinue
                    ) else { return nil }
            publishedArchiveHeartRatePoints = merged
        } else {
            publishedArchiveHeartRatePoints = incomingArchiveHeartRatePoints
        }
        guard shouldContinue() else { return nil }

        let cacheInterval = historicalStrainCacheInterval(
            now: now,
            confirmedSleeps: confirmedSleeps,
            calendar: .current
        )
        var historicalTodayHeartRatePoints:
            [HistoricalArchive.HeartRatePoint] = []
        historicalTodayHeartRatePoints.reserveCapacity(
            min(publishedArchiveHeartRatePoints.count, 100_000)
        )
        for (index, point) in publishedArchiveHeartRatePoints.enumerated() {
            if index.isMultiple(of: 256), !shouldContinue() { return nil }
            if point.t >= cacheInterval.start, point.t < cacheInterval.end {
                historicalTodayHeartRatePoints.append(point)
            }
        }

        var canonicalInput: [SavedSession] = []
        canonicalInput.reserveCapacity(
            sourceSessions.count + publishedRecoveredSessions.count
        )
        for (index, session) in sourceSessions.enumerated() {
            if index.isMultiple(of: 256), !shouldContinue() { return nil }
            canonicalInput.append(session)
        }
        for (index, session) in publishedRecoveredSessions.enumerated() {
            if index.isMultiple(of: 256), !shouldContinue() { return nil }
            canonicalInput.append(session)
        }
        guard let canonicalSessions = makeCanonicalSessionsCancellable(
            from: canonicalInput,
            shouldContinue: shouldContinue
        ) else { return nil }
        var derivedCanonicalInput = canonicalSessions
        if let activeJournalSession {
            guard shouldContinue() else { return nil }
            derivedCanonicalInput.append(activeJournalSession)
        }
        guard let derivedCanonicalSessions = makeCanonicalSessionsCancellable(
            from: derivedCanonicalInput,
            shouldContinue: shouldContinue
        ) else { return nil }
        var derivedSessions: [SavedSession] = []
        derivedSessions.reserveCapacity(derivedCanonicalSessions.count)
        for (index, session) in derivedCanonicalSessions.enumerated() {
            if index.isMultiple(of: 256), !shouldContinue() { return nil }
            if automaticCurrentCycleCutoff.map({ session.end > $0 }) ?? true {
                derivedSessions.append(session)
            }
        }

        var referenceSource: LatestSessionMetricSource?
        var localSource: LatestSessionMetricSource?
        var rebuiltBaseline: PersonalBaseline?
        if automaticCurrentCycleCutoff == nil {
            guard let referenceResult =
                    latestReferenceValidatedHRVSourceCancellable(
                        in: canonicalSessions,
                        shouldContinue: shouldContinue
                    ),
                  let localResult = latestLocalRMSSDSourceCancellable(
                        in: canonicalSessions,
                        shouldContinue: shouldContinue
                  ) else { return nil }
            referenceSource = referenceResult
            localSource = localResult
            guard let rebuilt = rebuildBaselineCancellable(
                from: canonicalSessions,
                previousBaseline: previousBaseline,
                profile: profile,
                confirmedSleeps: confirmedSleeps,
                shouldContinue: shouldContinue
            ) else { return nil }
            rebuiltBaseline = rebuilt
        }

        var skinDeviations = automaticCurrentCycleCutoff == nil
            ? [Date: Double]() : previousSkinTemperatureDeviationByDay
        for (index, entry) in recoveredSkinTemperatureProjection.deviations
            .enumerated() {
            if index.isMultiple(of: 256), !shouldContinue() { return nil }
            skinDeviations[entry.key] = entry.value
        }
        let baselineNightCount = automaticCurrentCycleCutoff == nil
            ? recoveredSkinTemperatureProjection.baselineNightCount
            : max(previousSkinTemperatureBaselineNightCount,
                  recoveredSkinTemperatureProjection.baselineNightCount)
        let candidateFrameCount = automaticCurrentCycleCutoff == nil
            ? recoveredSkinTemperatureCandidateFrameCount
            : max(previousSkinTemperatureCandidateFrameCount,
                  recoveredSkinTemperatureCandidateFrameCount)

        guard shouldContinue() else { return nil }
        var invalidationDays = Set<Date>()
        let invalidationPrevious = automaticCurrentCycleCutoff == nil
            ? previousRecoveredSessions : []
        for (index, session) in invalidationPrevious.enumerated() {
            if index.isMultiple(of: 256), !shouldContinue() { return nil }
            invalidationDays.insert(EventCivilTime.day(
                containing: session.start,
                eventTimeZoneIdentifier: session.eventTimeZoneIdentifier,
                outputCalendar: .current
            ))
            invalidationDays.insert(morningMetricDay(
                for: session,
                calendar: .current
            ))
        }
        for (index, session) in incomingRecoveredSessions.enumerated() {
            if index.isMultiple(of: 256), !shouldContinue() { return nil }
            invalidationDays.insert(EventCivilTime.day(
                containing: session.start,
                eventTimeZoneIdentifier: session.eventTimeZoneIdentifier,
                outputCalendar: .current
            ))
            invalidationDays.insert(morningMetricDay(
                for: session,
                calendar: .current
            ))
        }
        return .init(
            incomingRecoveredSessions: incomingRecoveredSessions,
            invalidationDays: invalidationDays,
            publishedRecoveredSessions: publishedRecoveredSessions,
            publishedArchiveHeartRatePoints:
                publishedArchiveHeartRatePoints,
            historicalTodayHeartRatePoints:
                historicalTodayHeartRatePoints,
            historicalCycleStart: cacheInterval.start,
            canonicalSessions: canonicalSessions,
            derivedSessions: derivedSessions,
            latestReferenceValidatedHRVSource: referenceSource,
            latestLocalRMSSDSource: localSource,
            rebuiltBaseline: rebuiltBaseline,
            recoveredSkinTemperatureDeviationByDay: skinDeviations,
            recoveredSkinTemperatureBaselineNightCount: baselineNightCount,
            recoveredSkinTemperatureCandidateFrameCount: candidateFrameCount,
            recoveredAutomaticCacheAuthority:
                recoveredAutomaticCacheAuthority,
            sourceCanonicalRevision: sourceCanonicalRevision,
            sourceConfirmedSleepsRevision: sourceConfirmedSleepsRevision
        )
    }

    nonisolated static func recoveredProjectionSourceRevisionsAreCurrent(
        canonicalRevision: Int,
        expectedCanonicalRevision: Int,
        confirmedSleepsRevision: Int,
        expectedConfirmedSleepsRevision: Int
    ) -> Bool {
        canonicalRevision == expectedCanonicalRevision
            && confirmedSleepsRevision == expectedConfirmedSleepsRevision
    }

    /// Starts the projection owned by one coordinator ticket. Notifications
    /// arriving during this scan are registered with the coordinator at once;
    /// they suppress this ticket's publication and coalesce to one latest scan.
    private func runRecoveredHeartRateProjection(
        ticket: AtriaRecoveredDataRecomputeCoordinator.Ticket,
        authority: RecoveredDataExecutionAuthority
    ) {
        let automaticCurrentCycleCutoff: Date?
        switch ticket.scope {
        case .full:
            automaticCurrentCycleCutoff = nil
        case .automaticCurrentCycle(let since):
            automaticCurrentCycleCutoff = since
        }
        let cutoff = automaticCurrentCycleCutoff
            ?? Date().addingTimeInterval(-14 * 24 * 60 * 60)

        // Every archive-sized input below is a COW capture. The worker performs
        // all element walking; the MainActor install later swaps only prepared
        // values after exact ticket + authority validation.
        let sourceSessions = sessions
        let sourceCanonicalRevision = canonicalSessionsRevision
        let sourceConfirmedSleepsRevision = confirmedSleepsRevision
        let previousRecoveredSessions = cachedRecoveredHeartRateSessions
        let previousArchiveHeartRatePoints =
            cachedRecoveredArchiveHeartRatePoints
        let previousSkinTemperatureDeviationByDay =
            cachedRecoveredSkinTemperatureDeviationByDay
        let previousSkinTemperatureBaselineNightCount =
            cachedRecoveredSkinTemperatureBaselineNightCount
        let previousSkinTemperatureCandidateFrameCount =
            cachedRecoveredSkinTemperatureCandidateFrameCount
        let previousBaseline = baseline
        let capturedProfile = profile
        let confirmedSleeps = cachedConfirmedSleeps
        let preparationNow = Date()
        let backgroundProjectionLease:
            AtriaBackgroundProjectionThrottle.ActiveLease?
        switch authority {
        case .foreground:
            backgroundProjectionLease = nil
        case .background(let lease):
            backgroundProjectionLease = lease
        }
        let executionShouldContinue: @Sendable () -> Bool = {
            authority.cooperativeShouldContinue()
        }
        let snapshotAuthorityShouldContinue: @Sendable () -> Bool = {
            authority.shouldContinue()
        }

        let policy = AtriaRecoveredDataTimeoutPolicy.physicalSessionStore
        var lastOfferedProgressBytes = 0
        var lastOfferedProgressUptime = DispatchTime.now().uptimeNanoseconds
        let workItem = DispatchWorkItem {
            [weak self, ticket, authority, sourceSessions] in
            func deferForLostAuthority(_ stage: String, _ reason: String) {
                DispatchQueue.main.async { [weak self, ticket, authority] in
                    guard let self else { return }
                    self.deferRecoveredDataExecutionForLostAuthority(
                        ticket: ticket,
                        authority: authority,
                        stage: stage,
                        reason: reason
                    )
                }
            }

            func reserveForSafeBackground(_ stage: String) {
                DispatchQueue.main.async { [weak self, ticket, authority] in
                    guard let self else { return }
                    guard self.recoveredDataExecutionIsCurrent(
                        ticket: ticket,
                        authority: authority
                    ) else {
                        if self.recoveredDataExecutionIsCurrent(
                            ticket: ticket,
                            authority: authority,
                            requireRunnable: false
                        ) {
                            self.deferRecoveredDataExecutionForLostAuthority(
                                ticket: ticket,
                                authority: authority,
                                stage: stage,
                                reason: "execution_authority_revoked"
                            )
                        } else {
                            self.recordStaleRecoveredExecutionCompletion(
                                ticket: ticket,
                                authority: authority,
                                stage: stage
                            )
                        }
                        return
                    }
                    self.handleRecoveredDataRecomputeEffects(
                        self.recoveredDataRecompute
                            .projectionReservedForSafeBackground(ticket: ticket)
                    )
                }
            }

            func failProjection(_ reason: String, stage: String) {
                DispatchQueue.main.async {
                    [weak self, ticket, authority, reason] in
                    guard let self else { return }
                    guard self.recoveredDataExecutionIsCurrent(
                        ticket: ticket,
                        authority: authority
                    ) else {
                        if self.recoveredDataExecutionIsCurrent(
                            ticket: ticket,
                            authority: authority,
                            requireRunnable: false
                        ) {
                            self.deferRecoveredDataExecutionForLostAuthority(
                                ticket: ticket,
                                authority: authority,
                                stage: stage,
                                reason: "execution_authority_revoked"
                            )
                        } else {
                            self.recordStaleRecoveredExecutionCompletion(
                                ticket: ticket,
                                authority: authority,
                                stage: stage
                            )
                        }
                        return
                    }
                    self.handleRecoveredDataRecomputeEffects(
                        self.recoveredDataRecompute.projectionCompleted(
                            ticket: ticket,
                            failureReason: reason
                        )
                    )
                }
            }

            func completeStage(_ stage: String) {
                Task { @MainActor [weak self, ticket, authority] in
                    guard let self else { return }
                    guard self.recoveredDataExecutionIsCurrent(
                        ticket: ticket,
                        authority: authority
                    ) else { return }
                    self.recordRecoveredExecutionEdge(
                        ticket: ticket,
                        authority: authority,
                        stage: stage,
                        outcome: "completed"
                    )
                    self.renewRecoveredProjectionLease(
                        ticket: ticket,
                        completedStage: stage
                    )
                }
            }

            guard executionShouldContinue() else {
                deferForLostAuthority(
                    "worker_admission",
                    "execution_authority_revoked"
                )
                return
            }

            if automaticCurrentCycleCutoff == nil {
                guard let diagnostics = HistoricalArchive.diagnostics(
                    shouldContinue: executionShouldContinue
                ), executionShouldContinue() else {
                    deferForLostAuthority(
                        "archive_diagnostics",
                        "execution_authority_revoked"
                    )
                    return
                }
                guard !diagnostics.exists || diagnostics.parseOK else {
                    failProjection(
                        "archive_parse_failed",
                        stage: "archive_diagnostics"
                    )
                    return
                }
            }

            guard executionShouldContinue() else {
                deferForLostAuthority(
                    "archive_snapshot",
                    "execution_authority_revoked"
                )
                return
            }
            let recoveredSnapshot = AtriaTransientWorkThread.run(
                name: "atria.recompute-snapshot",
                qualityOfService: .userInitiated
            ) { () -> HistoricalArchive.RecoveredDataSnapshot? in
                guard snapshotAuthorityShouldContinue() else { return nil }
                let onScanProgress:
                    (AtriaHistoricalJSONLRecentScanner.Statistics) -> Void = {
                        [weak self] statistics in
                        guard snapshotAuthorityShouldContinue() else { return }
                        let now = DispatchTime.now().uptimeNanoseconds
                        let elapsed = Double(now - lastOfferedProgressUptime)
                            / 1_000_000_000
                        guard Self.shouldRenewRecoveredProjectionLease(
                            newByteCount: statistics.byteCount,
                            lastRenewedByteCount: lastOfferedProgressBytes,
                            secondsSinceLastRenewal: elapsed,
                            renewalsUsed: 0,
                            policy: policy
                        ) else { return }
                        lastOfferedProgressBytes = statistics.byteCount
                        lastOfferedProgressUptime = now
                        Task { @MainActor [weak self, ticket, authority] in
                            guard let self,
                                  self.recoveredDataExecutionIsCurrent(
                                    ticket: ticket,
                                    authority: authority
                                  ) else { return }
                            self.renewRecoveredProjectionLease(
                                ticket: ticket,
                                scannedByteCount: statistics.byteCount
                            )
                        }
                    }

                if ticket.reason.hasPrefix(
                    "bg_projection_current_window_bootstrap"
                ), let backgroundProjectionLease {
                    guard snapshotAuthorityShouldContinue() else { return nil }
                    let step = HistoricalArchive
                        .performAutomaticRecoveredDataBootstrapStep(
                            since: cutoff,
                            lease: backgroundProjectionLease,
                            maximumBytesPerStep:
                                HistoricalArchive
                                    .maximumAutomaticRecoveredDataIncrementalBytes
                        )
                    guard snapshotAuthorityShouldContinue() else { return nil }
                    switch step {
                    case .ready(let readBytes):
                        AtriaDebugLog(
                            "ATRIADBG recovered_bootstrap status=ready bytes=%d action=bounded_publication",
                            readBytes
                        )
                    case .progressed(let readBytes, let remainingBytes):
                        AtriaDebugLog(
                            "ATRIADBG recovered_bootstrap status=progress bytes=%d remaining=%llu action=retain_bg_intent",
                            readBytes,
                            remainingBytes
                        )
                        return nil
                    case .deferred(let reason):
                        AtriaDebugLog(
                            "ATRIADBG recovered_bootstrap status=deferred reason=%@ action=retain_bg_intent",
                            reason
                        )
                        return nil
                    case .invalidated(let reason):
                        AtriaDebugLog(
                            "ATRIADBG recovered_bootstrap status=invalidated reason=%@ action=restart_next_safe_bg_window",
                            reason
                        )
                        return nil
                    }
                }

                if let backgroundProjectionLease {
                    return HistoricalArchive
                        .makeBackgroundRecoveredDataSnapshot(
                            since: cutoff,
                            lease: backgroundProjectionLease,
                            onScanProgress: onScanProgress
                        )
                }
                if automaticCurrentCycleCutoff != nil {
                    return HistoricalArchive
                        .makeAutomaticallyAdmittedRecoveredDataSnapshot(
                            since: cutoff,
                            maximumIncrementalBytes:
                                HistoricalArchive
                                    .maximumAutomaticRecoveredDataIncrementalBytes,
                            executionShouldContinue:
                                snapshotAuthorityShouldContinue,
                            onScanProgress: onScanProgress
                        )
                }
                return HistoricalArchive.makeCancellableRecoveredDataSnapshot(
                    since: cutoff,
                    executionShouldContinue:
                        snapshotAuthorityShouldContinue,
                    onScanProgress: onScanProgress
                )
            }

            guard let recoveredSnapshot else {
                if executionShouldContinue() {
                    reserveForSafeBackground("archive_snapshot")
                } else {
                    deferForLostAuthority(
                        "archive_snapshot",
                        "execution_authority_revoked"
                    )
                }
                return
            }
            guard executionShouldContinue() else {
                deferForLostAuthority(
                    "archive_snapshot",
                    "execution_authority_revoked"
                )
                return
            }
            completeStage("archive_snapshot")

            guard recoveredSnapshot.physiologyCompleteness == .complete else {
                let failureReason =
                    recoveredSnapshot.physiologyCompleteness.failureReason
                        ?? "archive_projection_incomplete"
                AtriaDebugLog(
                    "ATRIADBG recovered_projection status=withheld reason=%@ generation=%llu failure=%@ archive_files=%d archive_bytes=%d archive_rows=%d",
                    ticket.reason,
                    ticket.generation,
                    failureReason,
                    recoveredSnapshot.scan.fileReadCount,
                    recoveredSnapshot.scan.byteCount,
                    recoveredSnapshot.scan.decodedRecordCount
                )
                failProjection(failureReason, stage: "archive_snapshot")
                return
            }

            // Archive/cache count admission is deliberately earlier than any
            // file-backed journal load or live point walk. The physical
            // million-row retained-cache case must refuse in O(1) without
            // touching either recovered or live elements.
            let activeJournalSession = Self.loadActiveJournalSessionIfFresh(
                now: preparationNow,
                shouldContinue: executionShouldContinue
            )
            guard executionShouldContinue() else {
                deferForLostAuthority(
                    "journal_projection",
                    "execution_authority_revoked"
                )
                return
            }
            var sourceLiveSessions = sourceSessions
            if let activeJournalSession {
                sourceLiveSessions.append(activeJournalSession)
            }
            if automaticCurrentCycleCutoff != nil {
                var livePointCount = 0
                let maximumLivePoints = HistoricalArchive
                    .RecoveredDecodedWorkBudget.automaticForeground
                    .maximumRetainedChannelElements
                for session in sourceLiveSessions {
                    let addition = livePointCount.addingReportingOverflow(
                        session.points.count
                    )
                    guard !addition.overflow,
                          addition.partialValue <= maximumLivePoints else {
                        reserveForSafeBackground("live_count_admission")
                        return
                    }
                    livePointCount = addition.partialValue
                }
            }

            let archivePoints = recoveredSnapshot.heartRatePoints
            var livePoints: [HistoricalArchive.HeartRatePoint] = []
            var visitedLivePoints = 0
            let maximumLivePoints = automaticCurrentCycleCutoff == nil
                ? Int.max
                : HistoricalArchive.RecoveredDecodedWorkBudget
                    .automaticForeground.maximumRetainedChannelElements
            for session in sourceLiveSessions {
                guard executionShouldContinue() else {
                    deferForLostAuthority(
                        "live_projection",
                        "execution_authority_revoked"
                    )
                    return
                }
                for point in session.points {
                    visitedLivePoints += 1
                    if visitedLivePoints > maximumLivePoints {
                        reserveForSafeBackground("live_materialization_budget")
                        return
                    }
                    if visitedLivePoints.isMultiple(of: 256),
                       !executionShouldContinue() {
                        deferForLostAuthority(
                            "live_projection",
                            "execution_authority_revoked"
                        )
                        return
                    }
                    let timestamp = session.start.addingTimeInterval(
                        max(0, point.t)
                    )
                    if timestamp >= cutoff, (25...240).contains(point.bpm) {
                        livePoints.append(.init(t: timestamp, bpm: point.bpm))
                    }
                }
            }
            guard executionShouldContinue() else {
                deferForLostAuthority(
                    "live_projection",
                    "execution_authority_revoked"
                )
                return
            }
            let rrProjection = recoveredSnapshot.rrProjection
            let configuration =
                AtriaRecoveredHeartRateProjection.Configuration(
                    maximumGap: SavedSession.workoutContinuityGapLimit,
                    expectedSampleInterval: 1
                )
            guard executionShouldContinue() else {
                deferForLostAuthority(
                    "heart_rate_projection",
                    "execution_authority_revoked"
                )
                return
            }
            let projection = AtriaTransientWorkThread.run(
                name: "atria.recompute-hr-projection",
                qualityOfService: .userInitiated
            ) {
                AtriaRecoveredHeartRateProjection.projectCancellable(
                    historical: archivePoints,
                    live: livePoints,
                    configuration: configuration,
                    shouldContinue: executionShouldContinue
                )
            }
            guard let projection, executionShouldContinue() else {
                deferForLostAuthority(
                    "heart_rate_projection",
                    "execution_authority_revoked"
                )
                return
            }
            completeStage("heart_rate_projection")

            guard executionShouldContinue() else {
                deferForLostAuthority(
                    "session_motion_skin_projection",
                    "execution_authority_revoked"
                )
                return
            }
            let sessionProjection = AtriaTransientWorkThread.run(
                name: "atria.recompute-sessions",
                qualityOfService: .userInitiated
            ) { () -> ([SavedSession],
                       SessionStore.RecoveredSkinTemperatureProjection,
                       Int)? in
                guard var recoveredSessions =
                        AtriaRecoveredHeartRateProjection
                            .recoveredSessionsCancellable(
                                from: projection,
                                maximumGap: configuration.maximumGap,
                                recoveredRRBeats: rrProjection.beats,
                                shouldContinue: executionShouldContinue
                            ) else { return nil }
                var motionWindows: [AtriaRecoveredMotionProjection.Window] = []
                motionWindows.reserveCapacity(recoveredSessions.count)
                for (index, session) in recoveredSessions.enumerated() {
                    if index.isMultiple(of: 32),
                       !executionShouldContinue() { return nil }
                    motionWindows.append(.init(
                        id: session.id.uuidString,
                        start: session.start,
                        end: session.end
                    ))
                }
                guard let motionEpochsBySessionID =
                        recoveredSnapshot.motion
                            .recoveredEpochsCancellable(
                                windows: motionWindows,
                                shouldContinue: executionShouldContinue
                            ) else { return nil }
                for index in recoveredSessions.indices {
                    if index.isMultiple(of: 32),
                       !executionShouldContinue() { return nil }
                    let session = recoveredSessions[index]
                    let epochs =
                        motionEpochsBySessionID[session.id.uuidString] ?? []
                    recoveredSessions[index].recoveredMotionEpochs = epochs
                    let fields =
                        AtriaRecoveredMotionAnalytics.savedSessionFields(
                            epochs: epochs,
                            start: session.start,
                            end: session.end
                        )
                    recoveredSessions[index].motionEvidenceSource =
                        fields.motionEvidenceSource
                    recoveredSessions[index].motionEvidenceValidated =
                        fields.motionEvidenceValidated
                    recoveredSessions[index].imuSampleCount =
                        fields.imuSampleCount
                    recoveredSessions[index].imuFrameCount =
                        fields.imuFrameCount
                    recoveredSessions[index].imuStillnessRatio =
                        fields.imuStillnessRatio
                    recoveredSessions[index].imuMovementIntensity =
                        fields.imuMovementIntensity
                    recoveredSessions[index].imuActivityBursts =
                        fields.imuActivityBursts
                    recoveredSessions[index].imuValidationState =
                        fields.imuValidationState
                    recoveredSessions[index].strapStepResearchCount =
                        fields.strapStepResearchCount
                }
                if recoveredSnapshot.skinTemperatureCompleteness == .complete {
                    guard let attached =
                            Self.attachRecoveredSkinTemperatureCancellable(
                                recoveredSnapshot
                                    .skinTemperatureRawPoints,
                                to: recoveredSessions,
                                shouldContinue: executionShouldContinue
                            ) else { return nil }
                    recoveredSessions = attached
                }
                let skinProjection:
                    SessionStore.RecoveredSkinTemperatureProjection
                if recoveredSnapshot.skinTemperatureCompleteness == .complete {
                    guard let projected =
                            Self.recoveredSkinTemperatureProjectionCancellable(
                                points: recoveredSnapshot
                                    .skinTemperatureRawPoints,
                                confirmedSleeps: confirmedSleeps,
                                calendar: .current,
                                shouldContinue: executionShouldContinue
                            ) else { return nil }
                    skinProjection = projected
                } else {
                    skinProjection = .empty
                }
                guard executionShouldContinue() else { return nil }
                let candidateCount =
                    recoveredSnapshot.skinTemperatureCompleteness == .complete
                        ? recoveredSnapshot.skinTemperatureRawPoints.count : 0
                return (recoveredSessions, skinProjection, candidateCount)
            }
            guard let sessionProjection, executionShouldContinue() else {
                deferForLostAuthority(
                    "session_motion_skin_projection",
                    "execution_authority_revoked"
                )
                return
            }
            completeStage("session_motion_skin_projection")

            // Handoff-8 CP3: experimental relative skin signal. Plan from the
            // same integrity-gated snapshot + confirmed sleeps, persist the
            // compact qualified-night summaries atomically, then install the
            // UI result via a bounded MainActor value swap behind the exact
            // ticket/authority/confirmed-sleeps rechecks. A revoked execution
            // returns before the store write, so the previous committed
            // result stands and no partial summary exists.
            if executionShouldContinue() {
                let relativeSkinStore = AtriaRelativeSkinNightStore.production
                let relativeSkinPlan = AtriaRelativeSkinProducer.plan(
                    sleeps: confirmedSleeps.map(
                        AtriaRelativeSkinSleepWindow.init(confirmedSleep:)
                    ),
                    rows: recoveredSnapshot.skinTemperatureRawPoints,
                    stored: relativeSkinStore.load(),
                    environment: .init(
                        snapshotChannelComplete:
                            recoveredSnapshot.skinTemperatureCompleteness
                                == .complete,
                        drainedThroughUnix: UserDefaults.standard.double(
                            forKey: AtriaBLEManager.OfflineSyncDefaults
                                .drainedThroughUnix
                        ),
                        now: Date()
                    )
                )
                if executionShouldContinue() {
                    relativeSkinStore.replaceAll(relativeSkinPlan.nightsToPersist)
                    let uiSummary = relativeSkinPlan.uiSummary
                    Task { @MainActor [weak self, ticket, authority] in
                        guard let self,
                              self.recoveredDataExecutionIsCurrent(
                                  ticket: ticket,
                                  authority: authority,
                                  requireRunnable: false
                              ),
                              self.confirmedSleepsRevision
                                  == sourceConfirmedSleepsRevision else { return }
                        AtriaRelativeSkinSignalCenter.shared.install(uiSummary)
                    }
                }
            }

            guard executionShouldContinue() else {
                deferForLostAuthority(
                    "install_preparation",
                    "execution_authority_revoked"
                )
                return
            }
            let installPreparation = AtriaTransientWorkThread.run(
                name: "atria.recompute-install-preparation",
                qualityOfService: .userInitiated
            ) {
                Self.prepareRecoveredProjectionInstall(
                    incomingRecoveredSessions: sessionProjection.0,
                    incomingArchiveHeartRatePoints: archivePoints,
                    recoveredSkinTemperatureProjection:
                        sessionProjection.1,
                    recoveredSkinTemperatureCandidateFrameCount:
                        sessionProjection.2,
                    recoveredAutomaticCacheAuthority:
                        recoveredSnapshot.automaticCacheAuthority,
                    previousRecoveredSessions: previousRecoveredSessions,
                    previousArchiveHeartRatePoints:
                        previousArchiveHeartRatePoints,
                    previousSkinTemperatureDeviationByDay:
                        previousSkinTemperatureDeviationByDay,
                    previousSkinTemperatureBaselineNightCount:
                        previousSkinTemperatureBaselineNightCount,
                    previousSkinTemperatureCandidateFrameCount:
                        previousSkinTemperatureCandidateFrameCount,
                    sourceSessions: sourceSessions,
                    activeJournalSession: activeJournalSession,
                    sourceCanonicalRevision: sourceCanonicalRevision,
                    sourceConfirmedSleepsRevision:
                        sourceConfirmedSleepsRevision,
                    previousBaseline: previousBaseline,
                    profile: capturedProfile,
                    confirmedSleeps: confirmedSleeps,
                    automaticCurrentCycleCutoff:
                        automaticCurrentCycleCutoff,
                    now: preparationNow,
                    shouldContinue: executionShouldContinue
                )
            }
            guard let installPreparation, executionShouldContinue() else {
                deferForLostAuthority(
                    "install_preparation",
                    "execution_authority_revoked"
                )
                return
            }
            completeStage("install_preparation")

            let projectionStatistics = projection.statistics
            let rrStatistics = rrProjection.statistics
            let scanDiagnostics = recoveredSnapshot.scan
            Task { @MainActor [
                weak self,
                ticket,
                authority,
                installPreparation,
                projectionStatistics,
                rrStatistics,
                scanDiagnostics
            ] in
                guard let self else { return }

                @MainActor
                func ensureCurrent(_ stage: String) -> Bool {
                    guard self.recoveredDataExecutionIsCurrent(
                        ticket: ticket,
                        authority: authority,
                        requireRunnable: false
                    ) else {
                        self.recordStaleRecoveredExecutionCompletion(
                            ticket: ticket,
                            authority: authority,
                            stage: stage
                        )
                        return false
                    }
                    guard authority.shouldContinueForMainActorMutation(
                        applicationIsActive:
                            UIApplication.shared.applicationState == .active
                    ) else {
                        self.deferRecoveredDataExecutionForLostAuthority(
                            ticket: ticket,
                            authority: authority,
                            stage: stage,
                            reason: "execution_authority_revoked"
                        )
                        return false
                    }
                    return true
                }

                guard ensureCurrent("main_install_admission"),
                      case let .projecting(active) =
                        self.recoveredDataRecompute.phase,
                      active == ticket else { return }
                guard !self.restoreInitializationBlocked else {
                    failProjection(
                        "restore_marker_retained",
                        stage: "main_install_admission"
                    )
                    return
                }
                guard Self.recoveredProjectionSourceRevisionsAreCurrent(
                    canonicalRevision: self.canonicalSessionsRevision,
                    expectedCanonicalRevision:
                        installPreparation.sourceCanonicalRevision,
                    confirmedSleepsRevision: self.confirmedSleepsRevision,
                    expectedConfirmedSleepsRevision:
                        installPreparation.sourceConfirmedSleepsRevision
                ) else {
                    failProjection(
                        "canonical_or_sleep_authority_changed",
                        stage: "main_install_admission"
                    )
                    return
                }
                guard self.registerRecoveredDataMutationSnapshot(
                    ticket: ticket
                ) else {
                    failProjection(
                        "mutation_snapshot_unavailable",
                        stage: "main_install_admission"
                    )
                    return
                }
                guard ensureCurrent("main_install_before_mutation") else {
                    return
                }

                self.cachedRecoveredHeartRateSessions =
                    installPreparation.publishedRecoveredSessions
                self.cachedRecoveredSkinTemperatureDeviationByDay =
                    installPreparation
                        .recoveredSkinTemperatureDeviationByDay
                self.cachedRecoveredSkinTemperatureBaselineNightCount =
                    installPreparation
                        .recoveredSkinTemperatureBaselineNightCount
                self.cachedRecoveredSkinTemperatureCandidateFrameCount =
                    installPreparation
                        .recoveredSkinTemperatureCandidateFrameCount
                self.cachedSkinTemperatureDeviationSummary = nil
                self.cachedRecoveredArchiveHeartRatePoints =
                    installPreparation.publishedArchiveHeartRatePoints
                self.cachedRecoveredAutomaticCacheAuthority =
                    installPreparation.recoveredAutomaticCacheAuthority
                self.cachedHistoricalTodayHeartRatePoints =
                    installPreparation.historicalTodayHeartRatePoints
                self.cachedHistoricalCycleStart =
                    installPreparation.historicalCycleStart
                self.pendingDailyDerivedInvalidationDays.formUnion(
                    installPreparation.invalidationDays
                )
                self.setCachedCanonicalSessions(
                    installPreparation.canonicalSessions
                )
                if automaticCurrentCycleCutoff == nil {
                    self.setLatestReferenceValidatedHRVSource(
                        installPreparation
                            .latestReferenceValidatedHRVSource
                    )
                    self.setLatestLocalRMSSDSource(
                        installPreparation.latestLocalRMSSDSource
                    )
                }
                self.recoveryProjectionCache.invalidate()
                self.cachedHomeSavedAggregate = nil
                self.cachedTodayTRIMP = nil
                self.invalidateHomeDashboardDiagnosticsCache()
                self.invalidateWorkoutReviewCache()

                guard ensureCurrent("motion_provenance_before_await") else {
                    return
                }
                guard await self
                    .rebuildConfirmedSleepRecoveredMotionProvenance(
                        reason:
                            "historical_projection_\(ticket.reason)",
                        deferDerivedPublication: true,
                        affectedSince: automaticCurrentCycleCutoff,
                        preparedSourceSessions:
                            installPreparation.derivedSessions,
                        executionShouldContinue: {
                            authority.cooperativeShouldContinue()
                        }
                    ) else {
                    if ensureCurrent("motion_provenance_after_await") {
                        failProjection(
                            "confirmed_sleep_motion_provenance_failed",
                            stage: "motion_provenance_after_await"
                        )
                    }
                    return
                }
                guard ensureCurrent("motion_provenance_after_await") else {
                    return
                }

                guard await self.backfillConfirmedSleepStagesFromSessions(
                    reason: "historical_projection_\(ticket.reason)",
                    deferDerivedPublication: true,
                    affectedSince: automaticCurrentCycleCutoff,
                    preparedSourceSessions:
                        installPreparation.derivedSessions,
                    executionShouldContinue: {
                        authority.cooperativeShouldContinue()
                    }
                ).succeeded else {
                    if ensureCurrent("sleep_stage_after_await") {
                        failProjection(
                            "confirmed_sleep_stage_backfill_failed",
                            stage: "sleep_stage_after_await"
                        )
                    }
                    return
                }
                guard ensureCurrent("sleep_stage_after_await") else {
                    return
                }

                let hrvRequalification = await self
                    .requalifyPersistedConfirmedSleepHRVFromSessionsIfNeeded(
                        installPreparation.derivedSessions,
                        reason:
                            "historical_projection_\(ticket.reason)",
                        deferDerivedPublication: true,
                        affectedSince: automaticCurrentCycleCutoff,
                        sessionsArePreFiltered: true,
                        executionShouldContinue: {
                            authority.cooperativeShouldContinue()
                        }
                    )
                guard ensureCurrent("hrv_requalification_after_await") else {
                    return
                }
                guard hrvRequalification.succeeded else {
                    failProjection(
                        "confirmed_sleep_hrv_requalification_failed",
                        stage: "hrv_requalification_after_await"
                    )
                    return
                }

                if automaticCurrentCycleCutoff == nil,
                   let rebuiltBaseline =
                        installPreparation.rebuiltBaseline {
                    self.baseline = rebuiltBaseline
                    if self.canonicalMutationAllowed {
                        self.baseline.save()
                    }
                    self.cachedHomeDashboardDiagnostics = nil
                }
                guard ensureCurrent("main_install_terminal") else {
                    return
                }
                self.handleRecoveredDataRecomputeEffects(
                    self.recoveredDataRecompute.projectionCompleted(
                        ticket: ticket
                    )
                )

                AtriaDebugLog(
                    "ATRIADBG recovered_projection status=applied reason=%@ generation=%llu archive=%d live=%d emitted=%d sessions=%d rr_beats=%d rr_records=%d duplicates=%d gaps=%d archive_files=%d archive_bytes=%d archive_rows=%d archive_scan_ms=%d",
                    ticket.reason,
                    ticket.generation,
                    projectionStatistics.historicalInputCount,
                    projectionStatistics.liveInputCount,
                    projectionStatistics.coverage.historicalSampleCount,
                    installPreparation.incomingRecoveredSessions.count,
                    rrStatistics.emittedBeatCount,
                    rrStatistics.acceptedRecordCount,
                    projectionStatistics.duplicateTimestampCount,
                    projectionStatistics.coverage.splitGapCount,
                    scanDiagnostics.fileReadCount,
                    scanDiagnostics.byteCount,
                    scanDiagnostics.decodedRecordCount,
                    scanDiagnostics.elapsedMilliseconds
                )
            }
        }
        Self.historySnapshotProjectionQueue.async {
            let recomputeDone = DispatchSemaphore(value: 0)
            let recomputeThread = Thread {
                workItem.perform()
                recomputeDone.signal()
            }
            recomputeThread.name = "atria.recovered-recompute"
            recomputeThread.qualityOfService = .userInitiated
            recomputeThread.start()
            recomputeDone.wait()
        }
    }

    nonisolated static func shouldRenewRecoveredProjectionLease(
        newByteCount: Int,
        lastRenewedByteCount: Int,
        secondsSinceLastRenewal: TimeInterval,
        renewalsUsed: Int,
        policy: AtriaRecoveredDataTimeoutPolicy =
            .physicalSessionStore
    ) -> Bool {
        guard renewalsUsed < policy.maximumProjectionLeaseRenewals,
              secondsSinceLastRenewal
                >= TimeInterval(
                    policy.projectionLeaseRenewalMinimumIntervalSeconds
                ),
              newByteCount >= lastRenewedByteCount,
              newByteCount - lastRenewedByteCount
                >= policy.projectionLeaseRenewalMinimumBytes else {
            return false
        }
        return true
    }

    nonisolated static func shouldRenewRecoveredProjectionLeaseForStage(
        stage: String,
        completedStages: Set<String>,
        renewalsUsed: Int,
        policy: AtriaRecoveredDataTimeoutPolicy =
            .physicalSessionStore
    ) -> Bool {
        !stage.isEmpty
            && !completedStages.contains(stage)
            && renewalsUsed < policy.maximumProjectionLeaseRenewals
    }

    private func renewRecoveredProjectionLease(
        ticket: AtriaRecoveredDataRecomputeCoordinator.Ticket,
        scannedByteCount: Int
    ) {
        guard case let .projecting(active) = recoveredDataRecompute.phase,
              active == ticket else { return }
        let policy = AtriaRecoveredDataTimeoutPolicy.physicalSessionStore
        let used = recoveredDataProjectionLeaseRenewals[ticket.generation] ?? 0
        guard Self.shouldRenewRecoveredProjectionLease(
            newByteCount: scannedByteCount,
            lastRenewedByteCount: 0,
            secondsSinceLastRenewal:
                TimeInterval(policy.projectionLeaseRenewalMinimumIntervalSeconds),
            renewalsUsed: used,
            policy: policy
        ) else { return }
        recoveredDataProjectionLeaseRenewals[ticket.generation] = used + 1
        armRecoveredDataRecomputeTimeout(
            ticket: ticket,
            phase: "projection",
            component: nil
        )
        AtriaDebugLog(
            "ATRIADBG recovered_derived status=lease_renewed phase=projection scanned_bytes=%d renewal=%d renewal_cap=%d lease_s=%d generation=%llu archive_revision=%llu",
            scannedByteCount,
            used + 1,
            policy.maximumProjectionLeaseRenewals,
            policy.projectionLeaseSeconds,
            ticket.generation,
            ticket.archiveRevision
        )
    }

    private func renewRecoveredProjectionLease(
        ticket: AtriaRecoveredDataRecomputeCoordinator.Ticket,
        completedStage stage: String
    ) {
        guard case let .projecting(active) = recoveredDataRecompute.phase,
              active == ticket else { return }
        let policy = AtriaRecoveredDataTimeoutPolicy.physicalSessionStore
        let used = recoveredDataProjectionLeaseRenewals[ticket.generation] ?? 0
        let completed =
            recoveredDataProjectionCompletedStages[ticket.generation] ?? []
        guard Self.shouldRenewRecoveredProjectionLeaseForStage(
            stage: stage,
            completedStages: completed,
            renewalsUsed: used,
            policy: policy
        ) else { return }
        recoveredDataProjectionCompletedStages[
            ticket.generation,
            default: []
        ].insert(stage)
        recoveredDataProjectionLeaseRenewals[ticket.generation] = used + 1
        armRecoveredDataRecomputeTimeout(
            ticket: ticket,
            phase: "projection",
            component: nil
        )
        AtriaDebugLog(
            "ATRIADBG recovered_derived status=lease_renewed phase=projection stage=%@ renewal=%d renewal_cap=%d lease_s=%d generation=%llu archive_revision=%llu",
            stage,
            used + 1,
            policy.maximumProjectionLeaseRenewals,
            policy.projectionLeaseSeconds,
            ticket.generation,
            ticket.archiveRevision
        )
    }

    /// Runs the archive-backed analytics cascade behind a revisioned,
    /// fail-closed completion fence. The history pass begins only after archive
    /// diagnostics/cycle HR and confirmed-workout rehydration have committed;
    /// consumers of daily rollups begin only after that nested persistence pass.
    nonisolated static func shouldDeferAutomaticRecoveredDataRecomputation(
        historyTransportOwnsLink: Bool,
        onboardingComplete: Bool,
        allowsIncompleteOnboarding: Bool
    ) -> Bool {
        historyTransportOwnsLink || (!onboardingComplete && !allowsIncompleteOnboarding)
    }

    enum AutomaticRecoveredArchiveProjectionTrigger: Equatable, Sendable {
        case archiveDidUpdate
        case transportIdle
        case terminalOrUserRefresh
    }

    /// Pure cadence/ownership fence for archive-backed derived work. Compact
    /// step receipts have their own bounded notification lane and do not pass
    /// through this gate. No trigger, including a five-minute raw frontier,
    /// may overlap BLE's raw-history or motion transport authority.
    nonisolated static func shouldOfferAutomaticRecoveredArchiveProjection(
        trigger: AutomaticRecoveredArchiveProjectionTrigger,
        historyTransportOwnsLink: Bool,
        observedFrontierUnix: TimeInterval?,
        lastOfferedFrontierUnix: TimeInterval?,
        materialFrontierInterval: TimeInterval =
            automaticRecoveredArchiveMaterialFrontierInterval
    ) -> Bool {
        guard !historyTransportOwnsLink,
              materialFrontierInterval > 0,
              materialFrontierInterval.isFinite else { return false }
        switch trigger {
        case .transportIdle, .terminalOrUserRefresh:
            return true
        case .archiveDidUpdate:
            guard let observedFrontierUnix,
                  let lastOfferedFrontierUnix,
                  observedFrontierUnix.isFinite,
                  lastOfferedFrontierUnix.isFinite else { return false }
            return observedFrontierUnix - lastOfferedFrontierUnix
                >= materialFrontierInterval
        }
    }

    private func automaticRecoveredArchiveObservedFrontierUnix()
        -> TimeInterval? {
        let defaults = UserDefaults.standard
        let key = AtriaBLEManager.OfflineSyncDefaults.drainedThroughUnix
        guard defaults.object(forKey: key) != nil else { return nil }
        let value = defaults.double(forKey: key)
        return value > 0 && value.isFinite ? value : nil
    }

    private func recordAutomaticRecoveredArchiveProjectionOffer() {
        guard let frontier = automaticRecoveredArchiveObservedFrontierUnix()
        else { return }
        automaticRecoveredArchiveLastOfferedFrontierUnix = max(
            automaticRecoveredArchiveLastOfferedFrontierUnix ?? frontier,
            frontier
        )
    }

    private func scheduleAutomaticRecoveredArchiveIdleOffer() {
        automaticRecoveredArchiveIdleGeneration &+= 1
        let generation = automaticRecoveredArchiveIdleGeneration
        automaticRecoveredArchiveIdleTask?.cancel()
        automaticRecoveredArchiveIdleTask = Task {
            @MainActor [weak self] in
            try? await Task.sleep(for: .seconds(
                Self.automaticRecoveredArchiveIdleInterval
            ))
            guard !Task.isCancelled,
                  let self,
                  generation == self.automaticRecoveredArchiveIdleGeneration
            else { return }
            self.automaticRecoveredArchiveIdleTask = nil
            let transportOwnsLink =
                self.recoveredDataRecomputationDeferralProvider?(false)
                    ?? false
            guard Self.shouldOfferAutomaticRecoveredArchiveProjection(
                trigger: .transportIdle,
                historyTransportOwnsLink: transportOwnsLink,
                observedFrontierUnix:
                    self.automaticRecoveredArchiveObservedFrontierUnix(),
                lastOfferedFrontierUnix:
                    self.automaticRecoveredArchiveLastOfferedFrontierUnix
            ) else {
                self.retainDeferredRecoveredDataRecomputation(
                    reason: "archive_did_update_transport_idle",
                    isExactRecoveryPublication: false
                )
                return
            }
            if self.requestRecoveredDataRecomputation(
                reason: "archive_did_update_transport_idle"
            ) {
                self.recordAutomaticRecoveredArchiveProjectionOffer()
            }
        }
    }

    private func handleAutomaticRecoveredArchiveDidUpdate() {
        let observedFrontier =
            automaticRecoveredArchiveObservedFrontierUnix()
        let transportOwnsLink =
            recoveredDataRecomputationDeferralProvider?(false) ?? false
        if Self.shouldOfferAutomaticRecoveredArchiveProjection(
            trigger: .archiveDidUpdate,
            historyTransportOwnsLink: transportOwnsLink,
            observedFrontierUnix: observedFrontier,
            lastOfferedFrontierUnix:
                automaticRecoveredArchiveLastOfferedFrontierUnix
        ) {
            automaticRecoveredArchiveIdleGeneration &+= 1
            automaticRecoveredArchiveIdleTask?.cancel()
            automaticRecoveredArchiveIdleTask = nil
            if requestRecoveredDataRecomputation(
                reason: "archive_did_update_material_frontier"
            ) {
                recordAutomaticRecoveredArchiveProjectionOffer()
            }
            return
        }
        if transportOwnsLink {
            automaticRecoveredArchiveIdleGeneration &+= 1
            automaticRecoveredArchiveIdleTask?.cancel()
            automaticRecoveredArchiveIdleTask = nil
            retainDeferredRecoveredDataRecomputation(
                reason: "archive_did_update",
                isExactRecoveryPublication: false
            )
            return
        }
        scheduleAutomaticRecoveredArchiveIdleOffer()
    }

    /// A durable exact-recovery authority owns the shared archive projection
    /// lane until its app-facing publication fence commits. Ordinary archive
    /// notifications and launch hydration may arrive while that authority is
    /// pending; admitting either one here creates an older projection ticket
    /// ahead of the required terminal ticket. The coordinator then correctly
    /// queues the terminal request as trailing, but its finite lease can expire
    /// while the older serial work item is still scanning.
    ///
    /// Only the explicit completion-fenced request may enter during this
    /// interval. It already projects the newest durable archive generation, so
    /// suppressing ordinary duplicates loses no input.
    nonisolated static func shouldDeferRecoveredDataRecomputationForExactRecovery(
        exactRecoveryOwnsPriority: Bool,
        isExactRecoveryPublication: Bool
    ) -> Bool {
        exactRecoveryOwnsPriority && !isExactRecoveryPublication
    }

    func installRecoveredDataRecomputationDeferralProvider(
        _ provider: @escaping (_ isExactRecoveryPublication: Bool) -> Bool
    ) {
        recoveredDataRecomputationDeferralProvider = provider
    }

    /// Releases the one coalesced automatic request after BLE's common history
    /// finalizer has restored live ownership. If another history generation has
    /// already started, the provider keeps the request pending for that finalizer.
    func resumeDeferredRecoveredDataRecomputation(reason: String) {
        guard let pendingReason = deferredRecoveredDataRecomputationReason else { return }
        let pendingIsExact = deferredRecoveredDataRecomputationIsExact
        deferredRecoveredDataRecomputationReason = nil
        deferredRecoveredDataRecomputationIsExact = false
        guard requestRecoveredDataRecomputation(
            reason: "\(pendingReason)_after_\(reason)",
            allowsIncompleteOnboarding: pendingIsExact,
            isExactRecoveryPublication: pendingIsExact
        ) else { return }
        if pendingReason.hasPrefix("archive_did_update") {
            recordAutomaticRecoveredArchiveProjectionOffer()
        }
        AtriaDebugLog(
            "ATRIADBG recovered_projection status=resumed reason=%@ exact=%d",
            reason,
            pendingIsExact ? 1 : 0
        )
    }

    private func reserveAutomaticRecoveredProjectionFreshness(
        reason: String
    ) {
        UserDefaults.standard.set(
            Date().timeIntervalSince1970,
            forKey: Self.automaticRecoveredDataBootstrapIntentKey
        )
        AtriaDebugLog(
            "ATRIADBG recovered_projection status=automatic_intent_reserved reason=%@ action=schedule_bounded_current_window_bootstrap",
            reason
        )
    }

    nonisolated static func recoveredCurrentCheckpointSourceIsReusable(
        previous: HistoricalArchive.ConsumerSourceFingerprint,
        current: HistoricalArchive.ConsumerSourceFingerprint
    ) -> Bool {
        guard !previous.sources.isEmpty else { return false }
        let currentByPath = Dictionary(
            uniqueKeysWithValues: current.sources.map { ($0.path, $0) }
        )
        return previous.sources.allSatisfy { old in
            guard let new = currentByPath[old.path],
                  old.resourceIdentifier == new.resourceIdentifier,
                  new.size >= old.size else { return false }
            if new.size == old.size {
                return new.modificationTimeMilliseconds
                    == old.modificationTimeMilliseconds
            }
            // A compressed artifact is immutable/all-or-nothing. Physical
            // growth can only be treated as append-only for ordinary JSONL with
            // a stable filesystem identity. A missing identifier cannot prove
            // the path was not atomically replaced by a larger file.
            return old.resourceIdentifier != nil
                && URL(fileURLWithPath: old.path).pathExtension
                    != AtriaHistoricalSealedJSONLCompression.artifactExtension
        }
    }

    nonisolated private static func readRecoveredCurrentCheckpoint(
        from url: URL,
        now: Date = Date()
    ) -> RecoveredCurrentCheckpoint? {
        guard let data = try? Data(contentsOf: url),
              let checkpoint = try? JSONDecoder().decode(
                RecoveredCurrentCheckpoint.self,
                from: data
              ),
              checkpoint.version == RecoveredCurrentCheckpoint.schema,
              checkpoint.generatedAt <= now.addingTimeInterval(5 * 60),
              now.timeIntervalSince(checkpoint.generatedAt)
                <= recoveredCurrentCheckpointMaximumAge,
              checkpoint.recoveredSessions.count
                <= recoveredCurrentCheckpointMaximumSessions,
              checkpoint.recoveredSessions.reduce(0, {
                  $0 + $1.points.count
              }) <= recoveredCurrentCheckpointMaximumHeartRatePoints,
              recoveredCurrentCheckpointPublicationIsCommitted(
                checkpointIdentity: checkpoint.publicationIdentity,
                committedIdentity: UserDefaults.standard.string(
                    forKey:
                        recoveredCurrentCheckpointPublicationIdentityKey
                )
              ),
              recoveredCurrentCheckpointSourceIsReusable(
                previous: checkpoint.sourceFingerprint,
                current: HistoricalArchive.consumerSourceFingerprint()
              ) else { return nil }
        return checkpoint
    }

    /// Legacy schema-2 checkpoints predate the activation marker and retain
    /// their compatibility behavior. New checkpoints are launch-readable only
    /// after their exact publication UUID has crossed the MainActor fence.
    nonisolated static func recoveredCurrentCheckpointPublicationIsCommitted(
        checkpointIdentity: String?,
        committedIdentity: String?
    ) -> Bool {
        guard let checkpointIdentity else { return true }
        return !checkpointIdentity.isEmpty
            && checkpointIdentity == committedIdentity
    }

    nonisolated static func boundedRecoveredCurrentCheckpointSessions(
        _ sessions: [SavedSession],
        cutoff: Date,
        maximumSessions: Int = recoveredCurrentCheckpointMaximumSessions,
        maximumHeartRatePoints: Int =
            recoveredCurrentCheckpointMaximumHeartRatePoints
    ) -> [SavedSession] {
        boundedRecoveredCurrentCheckpointSessionsCancellable(
            sessions,
            cutoff: cutoff,
            maximumSessions: maximumSessions,
            maximumHeartRatePoints: maximumHeartRatePoints,
            shouldContinue: { true }
        ) ?? []
    }

    nonisolated static func boundedRecoveredCurrentCheckpointSessionsCancellable(
        _ sessions: [SavedSession],
        cutoff: Date,
        maximumSessions: Int = recoveredCurrentCheckpointMaximumSessions,
        maximumHeartRatePoints: Int =
            recoveredCurrentCheckpointMaximumHeartRatePoints,
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> [SavedSession]? {
        guard maximumSessions > 0, maximumHeartRatePoints > 0 else {
            return []
        }
        guard shouldContinue() else { return nil }
        var eligible: [SavedSession] = []
        eligible.reserveCapacity(min(sessions.count, maximumSessions * 2))
        for (index, session) in sessions.enumerated() {
            if index.isMultiple(of: 64), !shouldContinue() { return nil }
            if session.end > cutoff { eligible.append(session) }
        }
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &eligible,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: { $0.end > $1.end }
        ) else { return nil }
        var remainingPoints = maximumHeartRatePoints
        var newest: [SavedSession] = []
        newest.reserveCapacity(min(eligible.count, maximumSessions))
        for (index, session) in eligible.enumerated() {
            if index.isMultiple(of: 64), !shouldContinue() { return nil }
            guard newest.count < maximumSessions,
                  session.points.count <= remainingPoints else { continue }
            newest.append(session)
            remainingPoints -= session.points.count
        }
        return makeCanonicalSessionsCancellable(
            from: newest,
            shouldContinue: shouldContinue
        )
    }

    /// A cold-restored scanner cache contains only the delta after the paired
    /// UI checkpoint. Automatic publication therefore unions that delta with
    /// the checkpoint image; replacing everything after the cutoff would erase
    /// sleep/HR/RR/motion evidence that was intentionally not serialized twice.
    nonisolated static func mergedAutomaticallyRecoveredSessions(
        previous: [SavedSession],
        incoming: [SavedSession]
    ) -> [SavedSession] {
        makeCanonicalSessions(from: previous + incoming)
    }

    nonisolated static func mergedAutomaticallyRecoveredSessionsCancellable(
        previous: [SavedSession],
        incoming: [SavedSession],
        shouldContinue: () -> Bool
    ) -> [SavedSession]? {
        guard shouldContinue() else { return nil }
        var combined: [SavedSession] = []
        combined.reserveCapacity(previous.count + incoming.count)
        for (index, session) in previous.enumerated() {
            if index.isMultiple(of: 256), !shouldContinue() { return nil }
            combined.append(session)
        }
        for (index, session) in incoming.enumerated() {
            if index.isMultiple(of: 256), !shouldContinue() { return nil }
            combined.append(session)
        }
        return makeCanonicalSessionsCancellable(
            from: combined,
            shouldContinue: shouldContinue
        )
    }

    /// Linear exact-timestamp merge for the sorted archive HR images. Incoming
    /// evidence wins at the same timestamp, matching incremental scanner
    /// semantics without an unbounded dictionary allocation.
    nonisolated static func mergedAutomaticallyRecoveredHeartRatePoints(
        previous: [HistoricalArchive.HeartRatePoint],
        incoming: [HistoricalArchive.HeartRatePoint]
    ) -> [HistoricalArchive.HeartRatePoint] {
        var result: [HistoricalArchive.HeartRatePoint] = []
        result.reserveCapacity(previous.count + incoming.count)
        var previousIndex = 0
        var incomingIndex = 0
        while previousIndex < previous.count
                || incomingIndex < incoming.count {
            let previousDate = previousIndex < previous.count
                ? previous[previousIndex].t
                : .distantFuture
            let incomingDate = incomingIndex < incoming.count
                ? incoming[incomingIndex].t
                : .distantFuture
            let timestamp = min(previousDate, incomingDate)
            var selected: HistoricalArchive.HeartRatePoint?
            while previousIndex < previous.count,
                  previous[previousIndex].t == timestamp {
                selected = previous[previousIndex]
                previousIndex += 1
            }
            while incomingIndex < incoming.count,
                  incoming[incomingIndex].t == timestamp {
                selected = incoming[incomingIndex]
                incomingIndex += 1
            }
            if let selected { result.append(selected) }
        }
        return result
    }

    nonisolated static func
        mergedAutomaticallyRecoveredHeartRatePointsCancellable(
            previous: [HistoricalArchive.HeartRatePoint],
            incoming: [HistoricalArchive.HeartRatePoint],
            shouldContinue: () -> Bool
        ) -> [HistoricalArchive.HeartRatePoint]? {
        guard shouldContinue() else { return nil }
        var result: [HistoricalArchive.HeartRatePoint] = []
        result.reserveCapacity(previous.count + incoming.count)
        var previousIndex = 0
        var incomingIndex = 0
        var visited = 0
        while previousIndex < previous.count || incomingIndex < incoming.count {
            visited += 1
            if visited.isMultiple(of: 256), !shouldContinue() { return nil }
            let previousDate = previousIndex < previous.count
                ? previous[previousIndex].t : .distantFuture
            let incomingDate = incomingIndex < incoming.count
                ? incoming[incomingIndex].t : .distantFuture
            let timestamp = min(previousDate, incomingDate)
            var selected: HistoricalArchive.HeartRatePoint?
            while previousIndex < previous.count,
                  previous[previousIndex].t == timestamp {
                selected = previous[previousIndex]
                previousIndex += 1
            }
            while incomingIndex < incoming.count,
                  incoming[incomingIndex].t == timestamp {
                selected = incoming[incomingIndex]
                incomingIndex += 1
            }
            if let selected { result.append(selected) }
        }
        return shouldContinue() ? result : nil
    }

    private func applyRecoveredCurrentCheckpoint(
        _ checkpoint: RecoveredCurrentCheckpoint,
        scannerAuthorityRestored: Bool
    ) {
        cachedRecoveredHeartRateSessions = checkpoint.recoveredSessions
        let recoveredArchiveHeartRatePoints = checkpoint.recoveredSessions
            .flatMap { session in
                session.points.map {
                    HistoricalArchive.HeartRatePoint(
                        t: session.start.addingTimeInterval(max(0, $0.t)),
                        bpm: $0.bpm
                    )
                }
            }
            .sorted { $0.t < $1.t }
        cachedRecoveredArchiveHeartRatePoints = recoveredArchiveHeartRatePoints
        let cacheInterval = Self.historicalStrainCacheInterval(
            now: Date(),
            confirmedSleeps: cachedConfirmedSleeps,
            calendar: .current
        )
        cachedHistoricalTodayHeartRatePoints = recoveredArchiveHeartRatePoints
            .filter {
                $0.t >= cacheInterval.start && $0.t < cacheInterval.end
            }
        cachedHistoricalCycleStart = cacheInterval.start
        cachedRecoveredSkinTemperatureDeviationByDay = Dictionary(
            uniqueKeysWithValues: checkpoint.temperatureDays.map {
                ($0.day, $0.deviationCelsius)
            }
        )
        cachedRecoveredSkinTemperatureBaselineNightCount =
            checkpoint.temperatureBaselineNightCount
        cachedRecoveredSkinTemperatureCandidateFrameCount =
            checkpoint.temperatureCandidateFrameCount
        cachedRecoveredAutomaticCacheAuthority = scannerAuthorityRestored
            ? checkpoint.automaticCacheAuthority
            : nil
        cachedSkinTemperatureDeviationSummary = nil
    }

    private enum RecoveredCurrentCheckpointPersistenceOutcome: Sendable {
        case notRequired
        case persisted(identity: String)
        case failed
    }

    /// Prepares and durably installs the bounded current-cycle checkpoint while
    /// the coordinator still owns its final derived component. The publication
    /// fence and diagnostic edge cannot advance until this completion returns
    /// on MainActor with the exact execution authority still live.
    private func persistRecoveredCurrentCheckpoint(
        ticket: AtriaRecoveredDataRecomputeCoordinator.Ticket,
        executionShouldContinue: @escaping @Sendable () -> Bool,
        completion: @escaping @MainActor @Sendable (
            RecoveredCurrentCheckpointPersistenceOutcome
        ) -> Void
    ) {
        let now = Date()
        let sourceSessions = cachedRecoveredHeartRateSessions
        let confirmedSleeps = cachedConfirmedSleeps
        let temperatureByDay =
            cachedRecoveredSkinTemperatureDeviationByDay
        let baselineNightCount =
            cachedRecoveredSkinTemperatureBaselineNightCount
        let candidateFrameCount =
            cachedRecoveredSkinTemperatureCandidateFrameCount
        let automaticCacheAuthority =
            cachedRecoveredAutomaticCacheAuthority
        let destination = recoveredCurrentCheckpointURL
        let publicationIdentity = UUID().uuidString
        Self.historySnapshotProjectionQueue.async {
            let outcome = AtriaTransientWorkThread.run(
                name: "atria.recovered-current-checkpoint",
                qualityOfService: .utility
            ) { () -> RecoveredCurrentCheckpointPersistenceOutcome in
                guard executionShouldContinue() else { return .failed }
                let calendar = Calendar.current
                let cutoff = Self.automaticRecoveredDataProjectionCutoff(
                    now: now,
                    confirmedSleeps: confirmedSleeps,
                    calendar: calendar
                )
                guard executionShouldContinue(),
                      let recoveredSessions = Self
                        .boundedRecoveredCurrentCheckpointSessionsCancellable(
                            sourceSessions,
                            cutoff: cutoff,
                            shouldContinue: executionShouldContinue
                        ) else { return .failed }
                guard !recoveredSessions.isEmpty,
                      let automaticCacheAuthority else {
                    return .notRequired
                }
                let cutoffDay = calendar.startOfDay(for: cutoff)
                var temperatureDays: [
                    RecoveredCurrentCheckpoint.TemperatureDay
                ] = []
                temperatureDays.reserveCapacity(temperatureByDay.count)
                for (index, entry) in temperatureByDay.enumerated() {
                    if index.isMultiple(of: 32),
                       !executionShouldContinue() {
                        return .failed
                    }
                    if entry.key >= cutoffDay {
                        temperatureDays.append(.init(
                            day: entry.key,
                            deviationCelsius: entry.value
                        ))
                    }
                }
                guard AtriaSleepCooperativeAlgorithms.stableSort(
                    &temperatureDays,
                    shouldContinue: executionShouldContinue,
                    areInIncreasingOrder: { $0.day < $1.day }
                ) else { return .failed }
                let sourceBefore = HistoricalArchive
                    .consumerSourceFingerprint()
                guard executionShouldContinue(),
                      !sourceBefore.sources.isEmpty,
                      HistoricalArchive
                        .automaticRecoveredDataCacheAuthorityHasBoundedCurrentPlan(
                            automaticCacheAuthority,
                            since: cutoff
                        ) else { return .failed }
                let checkpoint = RecoveredCurrentCheckpoint(
                    version: RecoveredCurrentCheckpoint.schema,
                    publicationGeneration: ticket.generation,
                    publicationIdentity: publicationIdentity,
                    generatedAt: now,
                    cutoff: cutoff,
                    sourceFingerprint: sourceBefore,
                    automaticCacheAuthority: automaticCacheAuthority,
                    recoveredSessions: recoveredSessions,
                    temperatureDays: temperatureDays,
                    temperatureBaselineNightCount: baselineNightCount,
                    temperatureCandidateFrameCount: candidateFrameCount
                )
                guard executionShouldContinue(),
                      let data = try? JSONEncoder().encode(checkpoint),
                      executionShouldContinue(),
                      HistoricalArchive.consumerSourceFingerprint()
                        == sourceBefore else { return .failed }
                Self.recoveredCurrentCheckpointPersistenceLock.lock()
                defer {
                    Self.recoveredCurrentCheckpointPersistenceLock.unlock()
                }
                do {
                    try FileManager.default.createDirectory(
                        at: destination.deletingLastPathComponent(),
                        withIntermediateDirectories: true
                    )
                    guard executionShouldContinue() else { return .failed }
                    try data.write(to: destination, options: .atomic)
                    guard executionShouldContinue() else {
                        Self
                            .removeRecoveredCurrentCheckpointIfOwnedWhileLocked(
                                generation: ticket.generation,
                                at: destination
                            )
                        return .failed
                    }
                    return .persisted(identity: publicationIdentity)
                } catch {
                    AtriaDebugLog(
                        "ATRIADBG recovered_projection checkpoint_write_failed error=%@",
                        error.localizedDescription
                    )
                    return .failed
                }
            }
            Task { @MainActor in completion(outcome) }
        }
    }

    nonisolated private static func
        removeRecoveredCurrentCheckpointIfOwnedWhileLocked(
            generation: UInt64,
            at url: URL
        ) {
        guard let data = try? Data(contentsOf: url),
              let checkpoint = try? JSONDecoder().decode(
                RecoveredCurrentCheckpoint.self,
                from: data
              ),
              checkpoint.publicationGeneration == generation else { return }
        try? FileManager.default.removeItem(at: url)
    }

    nonisolated private static func removeRecoveredCurrentCheckpointIfOwned(
        generation: UInt64,
        at url: URL
    ) {
        recoveredCurrentCheckpointPersistenceLock.lock()
        defer { recoveredCurrentCheckpointPersistenceLock.unlock() }
        removeRecoveredCurrentCheckpointIfOwnedWhileLocked(
            generation: generation,
            at: url
        )
    }

    private func retainDeferredRecoveredDataRecomputation(
        reason: String,
        isExactRecoveryPublication: Bool
    ) {
        // A later ordinary archive notification must not downgrade the exact
        // completion-fenced request that is waiting for radio ownership.
        guard isExactRecoveryPublication
                || !deferredRecoveredDataRecomputationIsExact else { return }
        deferredRecoveredDataRecomputationReason = reason
        deferredRecoveredDataRecomputationIsExact =
            isExactRecoveryPublication
    }

    @discardableResult
    private func requestRecoveredDataRecomputation(
        reason: String,
        allowsIncompleteOnboarding: Bool = false,
        isExactRecoveryPublication: Bool = false,
        backgroundProjectionAllowed: Bool = false,
        automaticCurrentCycleCutoff: Date? = nil
    ) -> Bool {
        guard !restoreInitializationBlocked else { return false }
        let shouldRetainDeferredRequest =
            Self.shouldRetainDeferredRecoveredDataRequest(
                reason: reason,
                backgroundProjectionAllowed: backgroundProjectionAllowed
            )
        if Self.shouldDeferRecoveredDataRecomputationForExactRecovery(
            exactRecoveryOwnsPriority:
                HistoricalArchive.exactRecoveryProjectionOwnsArchivePriority(),
            isExactRecoveryPublication: isExactRecoveryPublication
        ) {
            if shouldRetainDeferredRequest {
                retainDeferredRecoveredDataRecomputation(
                    reason: reason,
                    isExactRecoveryPublication: isExactRecoveryPublication
                )
            }
            AtriaDebugLog(
                "ATRIADBG recovered_projection status=deferred reason=%@ exact_recovery_priority=1 action=coalesce_until_required_publication",
                reason
            )
            return false
        }
        let isMetadataQualifiedAutomaticRequest =
            Self.isMetadataQualifiedAutomaticRecoveredDataProjectionReason(
                reason: reason,
                isExactRecoveryPublication: isExactRecoveryPublication,
                backgroundProjectionAllowed: backgroundProjectionAllowed
            )
        if !backgroundProjectionAllowed,
           !Self.shouldStartBoundedAutomaticRecoveredDataProjection(
                applicationIsActive:
                    UIApplication.shared.applicationState == .active,
                thermalState: ProcessInfo.processInfo.thermalState,
                isLowPowerModeEnabled:
                    ProcessInfo.processInfo.isLowPowerModeEnabled
           ) {
            retainDeferredRecoveredDataRecomputation(
                reason: reason,
                isExactRecoveryPublication: isExactRecoveryPublication
            )
            AtriaDebugLog(
                "ATRIADBG recovered_projection status=deferred reason=%@ app_active=0 action=coalesce_until_foreground",
                reason
            )
            return false
        }
        let historyTransportOwnsLink =
            recoveredDataRecomputationDeferralProvider?(
                isExactRecoveryPublication
            ) ?? false
        if Self.shouldDeferAutomaticRecoveredDataRecomputation(
            historyTransportOwnsLink: historyTransportOwnsLink,
            onboardingComplete: profile.hasCompletedOnboarding,
            allowsIncompleteOnboarding: allowsIncompleteOnboarding
        ) {
            if shouldRetainDeferredRequest {
                retainDeferredRecoveredDataRecomputation(
                    reason: reason,
                    isExactRecoveryPublication: isExactRecoveryPublication
                )
            }
            AtriaDebugLog("ATRIADBG recovered_projection status=deferred reason=%@ history_owner=%d onboarding_complete=%d action=coalesce_until_history_finalizer",
                          reason,
                          historyTransportOwnsLink ? 1 : 0,
                          profile.hasCompletedOnboarding ? 1 : 0)
            return false
        }
        if isMetadataQualifiedAutomaticRequest,
           automaticCurrentCycleCutoff == nil {
            return scheduleAutomaticRecoveredDataProjectionAdmission(
                reason: reason,
                allowsIncompleteOnboarding: allowsIncompleteOnboarding
            )
        }
        if isExactRecoveryPublication {
            // Invalidate a metadata result that was captured before this exact
            // authority arrived. Its callback must not mint an older ticket.
            automaticRecoveredProjectionAdmissionGeneration &+= 1
        }
        deferredRecoveredDataRecomputationReason = nil
        deferredRecoveredDataRecomputationIsExact = false
        let archiveRevision = recoveredDataPublicationFence.recordArchiveUpdate()
        if isExactRecoveryPublication {
            // Reserve the archive lane before the coordinator starts so
            // launch-time background consumers cannot queue ahead of the
            // terminal publication ticket.
            exactRecoveryArchivePriorityLeaseActive = true
            exactRecoveryProjectionArchiveRevisions.insert(archiveRevision)
            deferredRecoveredDataRecomputationReason = nil
            deferredRecoveredDataRecomputationIsExact = false
        }
        let effects = recoveredDataRecompute.request(
            archiveRevision: archiveRevision,
            reason: reason,
            scope: automaticCurrentCycleCutoff.map {
                .automaticCurrentCycle(since: $0)
            } ?? .full,
            executionDomain: backgroundProjectionAllowed
                ? .explicitBackground : .foreground
        )
        handleRecoveredDataRecomputeEffects(effects)
        // Establish the coordinator's projection ownership before offering
        // workout rehydration. With a cold recovered-HR cache, the automatic
        // archive-update consumer then waits for that exact projection instead
        // of racing it with a 1.5M-point raw archive scan.
        if reason.hasPrefix("archive_did_update"),
           automaticCurrentCycleCutoff == nil {
            scheduleConfirmedWorkoutArchiveRehydration(reason: reason)
        }
        if backgroundProjectionAllowed {
            return Self.explicitBackgroundProjectionDidStart(effects)
        }
        return true
    }

    nonisolated static func explicitBackgroundProjectionDidStart(
        _ effects: [AtriaRecoveredDataRecomputeCoordinator.Effect]
    ) -> Bool {
        effects.contains { effect in
            guard case let .startProjection(ticket) = effect else {
                return false
            }
            return ticket.executionDomain == .explicitBackground
        }
    }

    /// A leased resumable bootstrap cannot be replayed from the legacy
    /// reason-only deferred slot: replay would lose both its BG lease and
    /// automatic cutoff, laundering bounded work into `.full`. Its durable
    /// intent is the only retry authority and must acquire a fresh BG lease.
    nonisolated static func shouldRetainDeferredRecoveredDataRequest(
        reason: String,
        backgroundProjectionAllowed: Bool
    ) -> Bool {
        !(backgroundProjectionAllowed
            && reason.hasPrefix(
                "bg_projection_current_window_bootstrap"
            ))
    }

    /// These two ordinary reasons may enter only through a metadata preflight.
    /// Exact/manual and separately leased background work keep the full pipeline.
    nonisolated static func
        isMetadataQualifiedAutomaticRecoveredDataProjectionReason(
            reason: String,
            isExactRecoveryPublication: Bool,
            backgroundProjectionAllowed: Bool
        ) -> Bool {
        guard !isExactRecoveryPublication,
              !backgroundProjectionAllowed else { return false }
        return reason.hasPrefix("deferred_session_load")
            || reason.hasPrefix("archive_did_update")
    }

    nonisolated static func shouldStartBoundedAutomaticRecoveredDataProjection(
        applicationIsActive: Bool,
        thermalState: ProcessInfo.ThermalState,
        isLowPowerModeEnabled: Bool
    ) -> Bool {
        applicationIsActive
            && thermalState != .serious
            && thermalState != .critical
            && !isLowPowerModeEnabled
    }

    /// A productive same-link raw catch-up yield may publish only work whose
    /// inputs are already durable and whose archive read is byte-bounded. The
    /// BLE owner keeps its exact continuation token throughout this pause, so
    /// this guard is deliberately stricter than ordinary foreground refresh:
    /// heat or Low Power Mode returns the turn to raw transfer without opening
    /// any canonical JSONL source.
    nonisolated static func shouldStartConnectedRawCatchUpPublicationYield(
        applicationIsActive: Bool,
        thermalState: ProcessInfo.ThermalState,
        isLowPowerModeEnabled: Bool
    ) -> Bool {
        applicationIsActive
            && thermalState != .serious
            && thermalState != .critical
            && !isLowPowerModeEnabled
    }

    /// A local publication turn cannot advance the current physiological cycle
    /// until the fsynced raw frontier has actually reached that cycle. Keeping
    /// this check ahead of BLE's yield token prevents a deep chronological
    /// catch-up from pausing for a projection whose Gate-4/current-cycle inputs
    /// are still entirely in the future. The durable frontier is the authority;
    /// compact rows written ahead of it are a rebuildable derivative only.
    nonisolated static func connectedRawCatchUpPublicationYieldIsNeeded(
        bootstrapIntentPending: Bool,
        durableFrontierUnix: TimeInterval?,
        currentCycleStart: Date
    ) -> Bool {
        let cycleStartUnix = currentCycleStart.timeIntervalSince1970
        guard bootstrapIntentPending,
              let durableFrontierUnix,
              durableFrontierUnix.isFinite,
              durableFrontierUnix > 0,
              cycleStartUnix.isFinite else {
            return false
        }
        return durableFrontierUnix >= cycleStartUnix
    }

    /// Main-actor bridge used by the BLE fairness callback. Cycle ownership is
    /// resolved from the same confirmed-sleep image used by current Gate-4 and
    /// dashboard publication; no archive read or radio action occurs here.
    func connectedRawCatchUpPublicationYieldIsNeeded(
        now: Date = Date(),
        defaults: UserDefaults = .standard,
        calendar: Calendar = .current
    ) -> Bool {
        let frontierKey = AtriaBLEManager.OfflineSyncDefaults.drainedThroughUnix
        let frontier: TimeInterval? = defaults.object(forKey: frontierKey) != nil
            ? defaults.double(forKey: frontierKey)
            : nil
        let cycleStart = AtriaPhysiologicalCycle.current(
            now: now,
            confirmedSleeps: cachedConfirmedSleeps,
            calendar: calendar
        ).start
        return Self.connectedRawCatchUpPublicationYieldIsNeeded(
            bootstrapIntentPending:
                Self.automaticRecoveredDataBootstrapIntentIsPending,
            durableFrontierUnix: frontier,
            currentCycleStart: cycleStart
        )
    }

    nonisolated static func automaticRecoveredDataProjectionCutoff(
        now: Date,
        confirmedSleeps: [UserConfirmedSleep],
        calendar: Calendar = .current,
        maximumLookback: TimeInterval = 48 * 60 * 60
    ) -> Date {
        let cycleStart = AtriaPhysiologicalCycle.current(
            now: now,
            confirmedSleeps: confirmedSleeps,
            calendar: calendar
        ).start
        let latestMainSleepStart = confirmedSleeps
            .filter {
                !confirmedSleepSourceIsNap(
                    source: $0.source,
                    duration: $0.duration
                )
            }
            .max(by: { $0.end < $1.end })?
            .start
        // First-use/upgrade has no confirmed sleep yet. A 06:00 physiological
        // cycle floor would make an afternoon launch discard the preceding
        // night before the bounded auto-confirm step can evaluate it. Include
        // one bounded prior-night window without widening beyond the existing
        // 48-hour hard limit.
        let priorNightFloor = max(
            calendar.startOfDay(for: now).addingTimeInterval(-12 * 60 * 60),
            now.addingTimeInterval(-36 * 60 * 60)
        )
        let desired = latestMainSleepStart.map { min($0, cycleStart) }
            ?? min(cycleStart, priorNightFloor)
        return max(desired, now.addingTimeInterval(-maximumLookback))
    }

    @discardableResult
    private func scheduleAutomaticRecoveredDataProjectionAdmission(
        reason: String,
        allowsIncompleteOnboarding: Bool
    ) -> Bool {
        automaticRecoveredProjectionAdmissionGeneration &+= 1
        let generation = automaticRecoveredProjectionAdmissionGeneration
        let cutoff = Self.automaticRecoveredDataProjectionCutoff(
            now: Date(),
            confirmedSleeps: cachedConfirmedSleeps,
            calendar: .current
        )
        let maximumBytes =
            HistoricalArchive.maximumAutomaticRecoveredDataIncrementalBytes
        Self.historySnapshotProjectionQueue.async { [weak self] in
            let admitted = HistoricalArchive
                .automaticRecoveredDataProjectionHasBoundedIncrementalPlan(
                    since: cutoff,
                    maximumIncrementalBytes: maximumBytes
                )
            DispatchQueue.main.async { [weak self] in
                guard let self,
                      self.automaticRecoveredProjectionAdmissionGeneration
                        == generation else { return }
                guard admitted else {
                    self.reserveAutomaticRecoveredProjectionFreshness(
                        reason: reason
                    )
                    AtriaDebugLog(
                        "ATRIADBG recovered_projection status=reserved_metadata_plan reason=%@ detail=rebuild_compressed_replaced_or_oversize max_bytes=%llu action=retain_current_checkpoint",
                        reason,
                        maximumBytes
                    )
                    return
                }
                guard Self.shouldStartBoundedAutomaticRecoveredDataProjection(
                    applicationIsActive:
                        UIApplication.shared.applicationState == .active,
                    thermalState: ProcessInfo.processInfo.thermalState,
                    isLowPowerModeEnabled:
                        ProcessInfo.processInfo.isLowPowerModeEnabled
                ) else {
                    self.retainDeferredRecoveredDataRecomputation(
                        reason: reason,
                        isExactRecoveryPublication: false
                    )
                    return
                }
                _ = self.requestRecoveredDataRecomputation(
                    reason: reason,
                    allowsIncompleteOnboarding: allowsIncompleteOnboarding,
                    automaticCurrentCycleCutoff: cutoff
                )
            }
        }
        return true
    }

    /// Compatibility seam retained for existing callers that only need the
    /// active-app check. New automatic archive publication must use the stricter
    /// thermal/Low-Power guard above.
    nonisolated static func shouldStartAutomaticArchiveProjection(
        applicationIsActive: Bool
    ) -> Bool {
        applicationIsActive
    }

    /// Pure environmental guard for running one archive-projection cycle in the
    /// background (2026-08-08). Projection is freshness-only work over inputs
    /// that are already fsynced, so unlike the drain it is safe to skip under
    /// low-power/heat and lose no data. Blocks under real device heat
    /// (mirrors `shouldDeferDurableHistoryAdmissionForHeat`), under Low Power
    /// Mode, and unless the phone is charging or comfortably charged (unknown
    /// battery level fails closed). CPU is separately bounded by
    /// `AtriaBackgroundProjectionThrottle`; this only decides whether to start.
    nonisolated static func shouldStartBackgroundArchiveProjection(
        thermalState: ProcessInfo.ThermalState,
        isLowPowerModeEnabled: Bool,
        batteryState: UIDevice.BatteryState,
        batteryLevel: Float
    ) -> Bool {
        guard thermalState != .serious, thermalState != .critical else { return false }
        guard !isLowPowerModeEnabled else { return false }
        let charging = AtriaBLEManager.phoneStateIsCharging(batteryState)
        guard charging || batteryLevel >= 0.5 else { return false }
        return true
    }

    nonisolated static func shouldExecuteAutomaticFullBackgroundProjection()
        -> Bool {
        false
    }

    private static let backgroundRecoveredProjectionMaintenanceIntentKey =
        "atria.recoveredProjection.fullMaintenanceRequestedAt.v1"

    /// The full automatic BG projection is release-disabled before a ticket or
    /// throttle exists. The retained body documents the future guarded lane;
    /// exact/manual completion-fenced projection uses its separate entry point.
    @discardableResult
    func requestBackgroundArchiveProjectionIfSafe(
        reason: String,
        budgetSeconds: TimeInterval = 240
    ) -> AtriaBackgroundProjectionThrottle.ActiveLease? {
        let allowed = Self.shouldStartBackgroundArchiveProjection(
            thermalState: ProcessInfo.processInfo.thermalState,
            isLowPowerModeEnabled: ProcessInfo.processInfo.isLowPowerModeEnabled,
            batteryState: UIDevice.current.batteryState,
            batteryLevel: UIDevice.current.batteryLevel)
        guard allowed else {
            AtriaDebugLog("ATRIADBG bg_projection status=skipped reason=%@ action=guard_unsafe", reason)
            return nil
        }
        if !Self.shouldExecuteAutomaticFullBackgroundProjection() {
            // Real BGProcessing, after BLE/motion catch-up, is the only owner
            // of the resumable first-install/oversize current-window seed. The
            // durable intent keeps the scheduler at its tight cadence until a
            // paired UI+scanner checkpoint is atomically published.
            UserDefaults.standard.set(
                Date().timeIntervalSince1970,
                forKey: Self.automaticRecoveredDataBootstrapIntentKey
            )
            let cutoff = Self.automaticRecoveredDataProjectionCutoff(
                now: Date(),
                confirmedSleeps: cachedConfirmedSleeps,
                calendar: .current
            )
            let lease = AtriaBackgroundProjectionThrottle.shared.begin(
                budgetSeconds: budgetSeconds
            )
            let started = requestRecoveredDataRecomputation(
                reason: "bg_projection_current_window_bootstrap_\(reason)",
                allowsIncompleteOnboarding: false,
                isExactRecoveryPublication: false,
                backgroundProjectionAllowed: true,
                automaticCurrentCycleCutoff: cutoff
            )
            if !started {
                _ = AtriaBackgroundProjectionThrottle.shared.end(
                    lease: lease
                )
            }
            AtriaDebugLog(
                "ATRIADBG bg_projection status=%@ reason=%@ scope=current_window_bootstrap",
                started ? "started" : "deferred",
                reason
            )
            return started ? lease : nil
        }
        let lease = AtriaBackgroundProjectionThrottle.shared.begin(
            budgetSeconds: budgetSeconds
        )
        let started = requestRecoveredDataRecomputation(
            reason: reason,
            allowsIncompleteOnboarding: false,
            isExactRecoveryPublication: false,
            backgroundProjectionAllowed: true)
        if !started {
            _ = AtriaBackgroundProjectionThrottle.shared.end(lease: lease)
        }
        AtriaDebugLog("ATRIADBG bg_projection status=%@ reason=%@", started ? "started" : "deferred", reason)
        return started ? lease : nil
    }

    /// Starts one current-window bootstrap pass for the explicit BLE fairness
    /// yield. The caller has already required an active, cool, non-LPM phone;
    /// unlike unattended BGProcessing, this attended <=8 MiB pass does not
    /// impose an additional 50% battery threshold. Scope is supplied explicitly
    /// so the request can never degrade into the `.full` projection pipeline.
    @discardableResult
    private func requestConnectedRawCatchUpBoundedProjection(
        reason: String,
        budgetSeconds: TimeInterval
    ) -> AtriaBackgroundProjectionThrottle.ActiveLease? {
        UserDefaults.standard.set(
            Date().timeIntervalSince1970,
            forKey: Self.automaticRecoveredDataBootstrapIntentKey
        )
        let cutoff = Self.automaticRecoveredDataProjectionCutoff(
            now: Date(),
            confirmedSleeps: cachedConfirmedSleeps,
            calendar: .current
        )
        let lease = AtriaBackgroundProjectionThrottle.shared.begin(
            budgetSeconds: budgetSeconds
        )
        let started = requestRecoveredDataRecomputation(
            reason: "bg_projection_current_window_bootstrap_\(reason)",
            allowsIncompleteOnboarding: false,
            isExactRecoveryPublication: false,
            backgroundProjectionAllowed: true,
            automaticCurrentCycleCutoff: cutoff
        )
        if !started {
            _ = AtriaBackgroundProjectionThrottle.shared.end(lease: lease)
            return nil
        }
        connectedRawCatchUpProjectionLease = lease
        return lease
    }

    /// Gives app-facing current-cycle evidence one finite turn between exact
    /// connected raw-history slices. Gate-4 compact motion is refreshed first
    /// and is independent of archive projection. The only heavier admission is
    /// the dedicated resumable <=8 MiB current-window bootstrap above; its
    /// explicit cutoff cannot enter the automatic full projection pipeline.
    ///
    /// This method does not own BLE authority. The manager retains its exact
    /// continuation token while awaiting this result and resumes transport only
    /// from a later accepted 2A37 callback.
    func performConnectedRawCatchUpPublicationYield(
        reason: String,
        budgetSeconds: TimeInterval
    ) async -> Bool {
        refreshCurrentCycleStrapStepReceipt(
            reason: "connected_raw_publication_yield_\(reason)"
        )
        guard Self.automaticRecoveredDataBootstrapIntentIsPending else {
            AtriaDebugLog(
                "ATRIADBG recovered_projection status=connected_raw_yield_complete reason=%@ action=compact_refreshed_no_bootstrap_intent",
                reason
            )
            return true
        }
        guard Self.shouldStartConnectedRawCatchUpPublicationYield(
            applicationIsActive:
                UIApplication.shared.applicationState == .active,
            thermalState: ProcessInfo.processInfo.thermalState,
            isLowPowerModeEnabled:
                ProcessInfo.processInfo.isLowPowerModeEnabled
        ) else {
            AtriaDebugLog(
                "ATRIADBG recovered_projection status=connected_raw_yield_deferred reason=%@ action=compact_only_environment_unsafe",
                reason
            )
            return false
        }

        let finiteBudget = min(120, max(15, budgetSeconds))
        let priorRevision = recoveredDataPublicationFence.archiveRevision
        guard let lease = requestConnectedRawCatchUpBoundedProjection(
            reason: "connected_raw_publication_yield_\(reason)",
            budgetSeconds: finiteBudget
        ) else { return false }
        defer { endBackgroundArchiveProjectionThrottle(lease: lease) }

        // Unlike the public terminal-recovery waiter, this local fairness turn
        // must not clamp up to the full multi-component pipeline duration. A
        // bootstrap chunk that is incomplete fails its revision fence and
        // keeps durable intent; a ready chunk publishes the single bounded
        // current-cycle/latest-night component. Either result returns the BLE
        // turn within this exact finite budget.
        return await recoveredDataPublicationFence.awaitPublication(
            after: priorRevision,
            timeout: .seconds(Int(finiteBudget.rounded(.up)))
        )
    }

    /// Release the background projection throttle (call after the cycle's
    /// publication settles, and defensively on foreground so a leaked active
    /// state can never throttle a live scan).
    func endBackgroundArchiveProjectionThrottle() {
        guard let lease = connectedRawCatchUpProjectionLease else { return }
        endBackgroundArchiveProjectionThrottle(lease: lease)
    }

    func endBackgroundArchiveProjectionThrottle(
        lease: AtriaBackgroundProjectionThrottle.ActiveLease
    ) {
        _ = AtriaBackgroundProjectionThrottle.shared.end(lease: lease)
        if connectedRawCatchUpProjectionLease == lease {
            connectedRawCatchUpProjectionLease = nil
        }
    }

    private func beginRecoveredDataMutationTransaction(
        ticket: AtriaRecoveredDataRecomputeCoordinator.Ticket
    ) -> Bool {
        guard recoveredDataMutationTransaction.begin(ticket: ticket) else { return false }
        stressReplayTerminalPublicationGate.beginTransaction()
        recoveredStressReplayPreservedWorkoutAdditionIDs.removeAll(
            keepingCapacity: true
        )
        recoveredConcurrentConfirmedSleepUpserts.removeAll(
            keepingCapacity: true
        )
        recoveredConcurrentConfirmedSleepDeletedIDs.removeAll(
            keepingCapacity: true
        )
        return true
    }

    nonisolated static func recoveredMutationSnapshotCanRegister(
        confirmedRecordTransactionHasActiveOwner: Bool
    ) -> Bool {
        !confirmedRecordTransactionHasActiveOwner
    }

    /// Capture at the first actual recovered mutation, not when the archive
    /// worker starts. Deferred session loading and ordinary live checkpoints
    /// may legitimately settle while the archive is being scanned; an earlier
    /// snapshot would erase that newer canonical input on supersession.
    private func registerRecoveredDataMutationSnapshot(
        ticket: AtriaRecoveredDataRecomputeCoordinator.Ticket
    ) -> Bool {
        // Do not snapshot behind a confirmed-record writer that acquired the
        // process-global gate before this recovered ticket began. Waiting here
        // would block MainActor; admitting the snapshot would let rollback
        // erase the writer because its at-start transaction identity was nil.
        // Fail this generation before its first mutation and let the writer's
        // durable/cached result become the next generation's source image.
        guard Self.recoveredMutationSnapshotCanRegister(
                confirmedRecordTransactionHasActiveOwner:
                    Self.confirmedRecordTransactionGate.hasActiveOwner
              ),
              recoveredDataMutationTransaction.activeTicket == ticket,
              recoveredDataMutationTransaction.rollbackOperationCount == 0 else {
            return false
        }
        let defaults = UserDefaults.standard
        let snapshot = RecoveredDataMutationSnapshot(
            recoveredSessions: cachedRecoveredHeartRateSessions,
            canonicalSessions: cachedCanonicalSessions,
            latestReferenceValidatedHRVSource:
                cachedLatestReferenceValidatedHRVSource,
            latestLocalRMSSDSource: cachedLatestLocalRMSSDSource,
            confirmedWorkouts: cachedConfirmedWorkouts,
            confirmedSleeps: cachedConfirmedSleeps,
            baseline: baseline,
            history: historySnapshot,
            sleepHistory: sleepHistorySnapshot,
            dailyMetrics: dailyMetricHistory,
            dailyMetricSparklines: dailyMetricSparklines,
            dailyRollups: dailyRollupHistory,
            pendingDailyDerivedInvalidationDays: pendingDailyDerivedInvalidationDays,
            overviewTrendPoints: overviewTrendPoints,
            trainingLoad: trainingLoadSummarySnapshot,
            trainingLoadIsPrepared: trainingLoadSummaryIsPrepared,
            todayZones: todayHRZoneMinutesSnapshot,
            archiveStatus: historicalArchiveStatus,
            historicalTodayHeartRatePoints: cachedHistoricalTodayHeartRatePoints,
            recoveredArchiveHeartRatePoints: cachedRecoveredArchiveHeartRatePoints,
            recoveredAutomaticCacheAuthority:
                cachedRecoveredAutomaticCacheAuthority,
            historicalCycleStart: cachedHistoricalCycleStart,
            behaviorInsights: behaviorInsights,
            behaviorCorrelations: behaviorCorrelationSummariesCache,
            behaviorImpacts: behaviorImpactSummariesCache,
            journalInsights: journalInsightsCache,
            homeDiagnostics: cachedHomeDashboardDiagnostics,
            homeSavedAggregate: cachedHomeSavedAggregate,
            recoveryProjectionCache: recoveryProjectionCache,
            cachedTodayTRIMP: cachedTodayTRIMP,
            maxHRSuggestion: cachedMaxHRSuggestion,
            biologicalAge: cachedBiologicalAge,
            biologicalAgeWeeklySummary: cachedBiologicalAgeWeeklySummary,
            biologicalAgeSignatureMemo: cachedBiologicalAgeSignatureMemo,
            pendingBiologicalAgeRefreshKey: pendingBiologicalAgeRefreshKey,
            biologicalAgeSummaryRevision: biologicalAgeSummaryRevision,
            skinTemperatureDeviationSummary: cachedSkinTemperatureDeviationSummary,
            recoveredSkinTemperatureDeviationByDay:
                cachedRecoveredSkinTemperatureDeviationByDay,
            recoveredSkinTemperatureBaselineNightCount:
                cachedRecoveredSkinTemperatureBaselineNightCount,
            recoveredSkinTemperatureCandidateFrameCount:
                cachedRecoveredSkinTemperatureCandidateFrameCount,
            sessionBackupStatus: cachedSessionBackupStatus,
            autoSleepLoggedBanner: autoSleepLoggedBanner,
            lastForegroundSleepAutoConfirmAt: lastForegroundSleepAutoConfirmAt,
            backupCanonicalRevision: backupCanonicalRevision,
            confirmedSleepDefaultsData: defaults.data(forKey: ConfirmedSleepDefaults.key),
            confirmedWorkoutDefaultsData: defaults.data(forKey: ConfirmedWorkoutDefaults.key),
            baselineDefaultsData: defaults.data(forKey: PersonalBaseline.persistenceKey)
        )
        dailyRollupStore.beginRecoveredDataPublicationFence()
        let registered = recoveredDataMutationTransaction.registerRollback(ticket: ticket) { [weak self] in
            self?.restoreRecoveredDataMutationSnapshot(snapshot)
        }
        if !registered {
            dailyRollupStore.endRecoveredDataPublicationFence()
        } else {
            stressReplayTerminalPublicationGate.registerMutationSnapshot()
        }
        return registered
    }

    /// Rollback restores the pre-run image, but anything the live pipeline
    /// confirmed *during* the recovered run was never owned by that run and
    /// must survive it. Pre-run records win on id so a genuine recovered-run
    /// mutation is still undone; ids absent from the pre-run image are live
    /// additions and are kept.
    nonisolated static func mergeConfirmedWorkoutsPreservingLiveAdditions(
        preRun: [UserConfirmedWorkout],
        current: [UserConfirmedWorkout]
    ) -> [UserConfirmedWorkout] {
        let preRunIDs = Set(preRun.map(\.id))
        let liveAdditions = current.filter { !preRunIDs.contains($0.id) }
        guard !liveAdditions.isEmpty else { return preRun }
        return (preRun + liveAdditions).sorted { $0.start > $1.start }
    }

    nonisolated static func mergeConfirmedSleepsPreservingConcurrentAuthority(
        preRun: [UserConfirmedSleep],
        concurrentUpserts: [String: UserConfirmedSleep],
        concurrentDeletedIDs: Set<String>
    ) -> [UserConfirmedSleep] {
        var byID: [String: UserConfirmedSleep] = [:]
        byID.reserveCapacity(preRun.count + concurrentUpserts.count)
        for sleep in preRun where !concurrentDeletedIDs.contains(sleep.id) {
            byID[sleep.id] = sleep
        }
        for (id, sleep) in concurrentUpserts
        where !concurrentDeletedIDs.contains(id) {
            byID[id] = sleep
        }
        return byID.values.sorted {
            if $0.start != $1.start { return $0.start > $1.start }
            return $0.id < $1.id
        }
    }

    private func restoreRecoveredDataMutationSnapshot(
        _ snapshot: RecoveredDataMutationSnapshot
    ) {
        // Cancel/fence every utility callback that could otherwise arrive after
        // rollback and re-apply a fragment of the failed generation.
        pendingDailyMetricSaveWorkItem?.cancel()
        pendingDailyMetricSaveWorkItem = nil
        pendingDailyMetricPersistRevision = nil
        pendingConfirmedWorkoutRehydrationWorkItem?.cancel()
        pendingConfirmedWorkoutRehydrationWorkItem = nil
        pendingWorkoutStepEvidenceWorkItem?.cancel()
        pendingWorkoutStepEvidenceWorkItem = nil
        workoutStepEvidenceRescheduleRequested = false
        pendingForegroundSleepSettlementWorkItem?.cancel()
        pendingForegroundSleepSettlementWorkItem = nil
        pendingSleepReviewCacheWorkItem?.cancel()
        pendingSleepReviewCacheWorkItem = nil
        historySnapshotRevision &+= 1
        dailyRollupPreparationRevision &+= 1
        overviewTrendPointsRefreshRevision &+= 1
        trainingLoadSummaryRevision &+= 1
        todayHRZoneMinutesRevision &+= 1
        historicalArchiveStatusRevision &+= 1
        historicalTodayHeartRateRevision &+= 1
        confirmedWorkoutRehydrationGeneration &+= 1
        workoutStepEvidenceGeneration &+= 1
        foregroundSleepSettlementGeneration &+= 1
        pendingForegroundSleepSettlementOwner = nil
        drainForegroundSleepSettlementCompletions(succeeded: false)
        behaviorInsightsGeneration &+= 1
        biologicalAgeRefreshGeneration &+= 1
        sessionBackupStatusGeneration &+= 1
        // A confirmed-sleep write may already be awaiting its serial worker
        // when the scene edge arrives. Make its eventual result stale now; the
        // lifecycle restore below acquires the same transaction gate before
        // writing the captured durable image, so the rollback is guaranteed to
        // be the last writer without blocking this callback.
        confirmedRecordWriteGeneration &+= 1

        cachedRecoveredHeartRateSessions = snapshot.recoveredSessions
        if recoveredLifecycleRollbackUsesBoundedRestore {
            // Scene revocation has a watchdog-sized latency budget. Restore
            // the captured COW image and scalar HRV authorities directly;
            // foreground retry will fold any concurrently persisted raw/live
            // session into its fresh generation off-main.
            cachedCanonicalSessions = Self
                .boundedRecoveredLifecycleCanonicalRestore(
                    snapshot.canonicalSessions
                )
            setLatestReferenceValidatedHRVSource(
                snapshot.latestReferenceValidatedHRVSource
            )
            setLatestLocalRMSSDSource(snapshot.latestLocalRMSSDSource)
        } else {
            // Ordinary foreground failure keeps the historical behavior of
            // preserving a live session accepted during derivation.
            cachedCanonicalSessions = Self.makeCanonicalSessions(
                from: sessions + snapshot.recoveredSessions
            )
            refreshLatestHRVSourcesFromCanonicalSessions()
        }
        canonicalSessionsRevision &+= 1
        biologicalAgeSourceSessionsRevision &+= 1
        // Same hazard as the canonical sessions merged just above, and it cost
        // a real workout on 2026-07-25: a manual 6-minute walk was confirmed
        // and durably written (confirmed-workouts.json held 40 records,
        // `createdAt` 0.14s after `end`), and a relaunch brought the file back
        // to 39 with that id gone. A rollback must undo the recovered run, not
        // discard what the live pipeline confirmed while it was deriving —
        // especially a user-confirmed record, which no re-derivation will
        // reproduce when it fails automatic detection thresholds (this one
        // carried `duration_below_10m_and_hr_below_threshold`).
        let restoredConfirmedWorkouts = Self.mergeConfirmedWorkoutsPreservingLiveAdditions(
            preRun: snapshot.confirmedWorkouts,
            current: cachedConfirmedWorkouts
        )
        cachedConfirmedWorkouts = restoredConfirmedWorkouts
        confirmedWorkoutsRevision &+= 1
        let restoredConfirmedSleeps: [UserConfirmedSleep]
        if recoveredLifecycleRollbackUsesBoundedRestore {
            // The lifecycle edge only swaps the captured COW image. The FIFO
            // persistence task rebases concurrent user authority off-main
            // after every already-running confirmed writer has released the
            // transaction gate.
            restoredConfirmedSleeps = snapshot.confirmedSleeps
        } else {
            restoredConfirmedSleeps = Self
                .mergeConfirmedSleepsPreservingConcurrentAuthority(
                    preRun: snapshot.confirmedSleeps,
                    concurrentUpserts:
                        recoveredConcurrentConfirmedSleepUpserts,
                    concurrentDeletedIDs:
                        recoveredConcurrentConfirmedSleepDeletedIDs
                )
        }
        cachedConfirmedSleeps = restoredConfirmedSleeps
        confirmedSleepsRevision &+= 1
        reviewEvidenceRevision &+= 1
        invalidateSleepReviewCache(
            reason: "recovered_lifecycle_rollback",
            scheduleRefresh: false
        )
        baseline = snapshot.baseline
        historySnapshot = snapshot.history
        // Keep the scene-edge restore bounded. Confirmed records are newest
        // first and the resident presentation is capped at 84 nights, so a
        // small constant input prefix is sufficient while the next admitted
        // generation performs the complete cooperative rebuild off-main.
        let rollbackSleepInputLimit =
            SleepHistorySnapshot.maximumResidentNightCount * 3
        sleepHistorySnapshot = SleepHistorySnapshot(
            rollups: Array(snapshot.history.rollups.prefix(
                SleepHistorySnapshot.maximumResidentNightCount
            )),
            confirmedSleeps: Array(restoredConfirmedSleeps.prefix(
                rollbackSleepInputLimit
            )),
            dismissedCandidates: Array(dismissedSleepCandidates.prefix(
                rollbackSleepInputLimit
            )),
            calendar: .current
        )
        dailyMetricHistory = snapshot.dailyMetrics
        dailyMetricSparklines = snapshot.dailyMetricSparklines
        dailyRollupStore.replaceAll(snapshot.dailyRollups)
        dailyRollupHistory = snapshot.dailyRollups
        dailyRollupHistoryRevision &+= 1
        pendingDailyDerivedInvalidationDays = snapshot.pendingDailyDerivedInvalidationDays
        overviewTrendPoints = snapshot.overviewTrendPoints
        overviewTrendPointsRevision &+= 1
        trainingLoadSummarySnapshot = snapshot.trainingLoad
        trainingLoadSummaryIsPrepared = snapshot.trainingLoadIsPrepared
        todayHRZoneMinutesSnapshot = snapshot.todayZones
        historicalArchiveStatus = snapshot.archiveStatus
        cachedHistoricalTodayHeartRatePoints = snapshot.historicalTodayHeartRatePoints
        cachedRecoveredArchiveHeartRatePoints = snapshot.recoveredArchiveHeartRatePoints
        cachedRecoveredAutomaticCacheAuthority =
            snapshot.recoveredAutomaticCacheAuthority
        cachedHistoricalCycleStart = snapshot.historicalCycleStart
        behaviorInsights = snapshot.behaviorInsights
        behaviorCorrelationSummariesCache = snapshot.behaviorCorrelations
        behaviorImpactSummariesCache = snapshot.behaviorImpacts
        journalInsightsCache = snapshot.journalInsights
        behaviorInsightsRevision &+= 1
        // Concurrent sleep authority can move the physiological boundary even
        // when canonical sessions are byte-identical. Never restore caches
        // keyed to the pre-run boundary; their ordinary off-main consumers
        // will rebuild from the rebased confirmed image.
        cachedHomeDashboardDiagnostics = nil
        cachedHomeSavedAggregate = nil
        recoveryProjectionCache.invalidate()
        cachedTodayTRIMP = nil
        cachedMaxHRSuggestion = snapshot.maxHRSuggestion
        cachedBiologicalAge = snapshot.biologicalAge
        cachedBiologicalAgeWeeklySummary = snapshot.biologicalAgeWeeklySummary
        cachedBiologicalAgeSignatureMemo = snapshot.biologicalAgeSignatureMemo
        pendingBiologicalAgeRefreshKey = snapshot.pendingBiologicalAgeRefreshKey
        biologicalAgeSummaryRevision &+= 1
        cachedSkinTemperatureDeviationSummary = nil
        cachedRecoveredSkinTemperatureDeviationByDay =
            snapshot.recoveredSkinTemperatureDeviationByDay
        cachedRecoveredSkinTemperatureBaselineNightCount =
            snapshot.recoveredSkinTemperatureBaselineNightCount
        cachedRecoveredSkinTemperatureCandidateFrameCount =
            snapshot.recoveredSkinTemperatureCandidateFrameCount
        cachedSessionBackupStatus = snapshot.sessionBackupStatus
        autoSleepLoggedBanner = snapshot.autoSleepLoggedBanner
        lastForegroundSleepAutoConfirmAt = snapshot.lastForegroundSleepAutoConfirmAt
        backupCanonicalRevision = snapshot.backupCanonicalRevision

        let workoutURL = url.deletingLastPathComponent()
            .appendingPathComponent(ConfirmedWorkoutDefaults.fileName)
        if recoveredLifecycleRollbackUsesBoundedRestore {
            scheduleRecoveredLifecycleRollbackPersistence(
                snapshot: snapshot,
                restoredConfirmedWorkouts: restoredConfirmedWorkouts,
                workoutURL: workoutURL,
                dailyMetricsURL: dailyMetricsURL
            )
        } else {
            restoreRecoveredDefaultsData(
                try? JSONEncoder().encode(restoredConfirmedSleeps),
                key: ConfirmedSleepDefaults.key,
                fallback: try? JSONEncoder().encode(restoredConfirmedSleeps)
            )
            // Persist the same merged image published above. Writing the raw
            // pre-run snapshot here would silently remove a workout confirmed
            // while recovered-data derivation was in flight.
            let restoredConfirmedWorkoutData = try? JSONEncoder().encode(
                restoredConfirmedWorkouts
            )
            restoreRecoveredDefaultsData(
                restoredConfirmedWorkoutData,
                key: ConfirmedWorkoutDefaults.key,
                fallback: restoredConfirmedWorkoutData
            )
            restoreRecoveredDefaultsData(
                snapshot.baselineDefaultsData,
                key: PersonalBaseline.persistenceKey,
                fallback: try? JSONEncoder().encode(snapshot.baseline)
            )
            restoreRecoveredFileData(
                restoredConfirmedWorkoutData,
                fallback: restoredConfirmedWorkoutData,
                to: workoutURL
            )
            restoreRecoveredFileData(
                nil,
                fallback: try? JSONEncoder().encode(snapshot.dailyMetrics),
                to: dailyMetricsURL
            )
            invalidateSleepReviewCache(
                reason: "recovered_transaction_rollback"
            )
        }
        invalidateWorkoutReviewCache()
    }

    /// A lifecycle callback closes a provisional recovered image by swapping
    /// the captured COW authority. Keeping this tiny helper independently
    /// testable prevents a future "helpful" canonical rebuild from putting an
    /// archive-sized walk back on MainActor rollback.
    nonisolated static func boundedRecoveredLifecycleCanonicalRestore(
        _ captured: [SavedSession]
    ) -> [SavedSession] {
        captured
    }

    /// Lifecycle rollback closes coordinator + in-memory transaction state
    /// synchronously, then restores the few durable provisional files on a
    /// bounded utility task. Foreground retry waits for this exact generation,
    /// so an older restore can never overwrite a replacement projection.
    private func scheduleRecoveredLifecycleRollbackPersistence(
        snapshot: RecoveredDataMutationSnapshot,
        restoredConfirmedWorkouts: [UserConfirmedWorkout],
        workoutURL: URL,
        dailyMetricsURL: URL
    ) {
        recoveredLifecycleRollbackPersistenceGeneration &+= 1
        let generation = recoveredLifecycleRollbackPersistenceGeneration
        recoveredLifecycleRollbackPersistenceInFlight = true
        endRecoveredLifecycleRollbackBackgroundTask()
        recoveredLifecycleRollbackBackgroundTask =
            UIApplication.shared.beginBackgroundTask(
            withName: "recovered-lifecycle-rollback"
        ) { [weak self] in
            MainActor.assumeIsolated {
                self?.endRecoveredLifecycleRollbackBackgroundTask()
            }
        }
        let baselineSnapshot = snapshot.baseline
        let baselineDefaultsData = snapshot.baselineDefaultsData
        let dailyMetrics = snapshot.dailyMetrics
        Task { @MainActor [weak self] in
            await Self.confirmedRecordTransactionGate.acquire()
            guard let self else {
                Self.confirmedRecordTransactionGate.release()
                return
            }
            // The rollback task is FIFO behind any writer that already owned
            // the confirmed-record gate at the lifecycle edge. Capture its
            // delta only now, after that writer has durably completed and
            // recorded its ordinary/user authority despite generation loss.
            let concurrentSleepUpserts =
                self.recoveredConcurrentConfirmedSleepUpserts
            let concurrentSleepDeletedIDs =
                self.recoveredConcurrentConfirmedSleepDeletedIDs
            let boundedRollups = Array(snapshot.history.rollups.prefix(
                SleepHistorySnapshot.maximumResidentNightCount
            ))
            let rollbackSleepInputLimit =
                SleepHistorySnapshot.maximumResidentNightCount * 3
            let boundedDismissedCandidates = Array(
                self.dismissedSleepCandidates.prefix(
                    rollbackSleepInputLimit
                )
            )
            let prepared: (
                sleeps: [UserConfirmedSleep],
                sleepHistory: SleepHistorySnapshot,
                dutyCycleWindow: (start: Int, end: Int, count: Int)?
            ) = await withCheckedContinuation { continuation in
                DispatchQueue.global(qos: .utility).async {
                    let encoder = JSONEncoder()
                    let restoredConfirmedSleeps = Self
                        .mergeConfirmedSleepsPreservingConcurrentAuthority(
                            preRun: snapshot.confirmedSleeps,
                            concurrentUpserts: concurrentSleepUpserts,
                            concurrentDeletedIDs:
                                concurrentSleepDeletedIDs
                        )
                    let sleepHistory = SleepHistorySnapshot(
                        rollups: boundedRollups,
                        confirmedSleeps: Array(
                            restoredConfirmedSleeps.prefix(
                                rollbackSleepInputLimit
                            )
                        ),
                        dismissedCandidates: boundedDismissedCandidates,
                        calendar: .current
                    )
                    let dutyCycleWindow = Self
                        .recoveredDutyCycleSleepWindowCancellable(
                            from: restoredConfirmedSleeps,
                            calendar: .current,
                            shouldContinue: { true }
                        )
                    let sleepsData = try? encoder.encode(
                        restoredConfirmedSleeps
                    )
                    let workoutsData = try? encoder.encode(
                        restoredConfirmedWorkouts
                    )
                    let baselineData = baselineDefaultsData
                        ?? (try? encoder.encode(baselineSnapshot))
                    let dailyMetricsData = try? encoder.encode(dailyMetrics)
                    let defaults = UserDefaults.standard
                    if let sleepsData {
                        defaults.set(
                            sleepsData,
                            forKey: ConfirmedSleepDefaults.key
                        )
                    }
                    if let workoutsData {
                        defaults.set(
                            workoutsData,
                            forKey: ConfirmedWorkoutDefaults.key
                        )
                        try? workoutsData.write(
                            to: workoutURL,
                            options: .atomic
                        )
                    }
                    if let baselineData {
                        defaults.set(
                            baselineData,
                            forKey: PersonalBaseline.persistenceKey
                        )
                    }
                    if let dailyMetricsData {
                        try? dailyMetricsData.write(
                            to: dailyMetricsURL,
                            options: .atomic
                        )
                    }
                    continuation.resume(returning: (
                        sleeps: restoredConfirmedSleeps,
                        sleepHistory: sleepHistory,
                        dutyCycleWindow: dutyCycleWindow
                    ))
                }
            }
            if self.recoveredLifecycleRollbackPersistenceGeneration
                == generation {
                self.setCachedConfirmedSleeps(
                    prepared.sleeps,
                    refreshDerivedCaches: false
                )
                self.sleepHistorySnapshot = prepared.sleepHistory
                if let window = prepared.dutyCycleWindow {
                    self.writeDutyCycleSleepWindow(window)
                }
                self.recoveredConcurrentConfirmedSleepUpserts.removeAll(
                    keepingCapacity: true
                )
                self.recoveredConcurrentConfirmedSleepDeletedIDs.removeAll(
                    keepingCapacity: true
                )
                self.recoveredLifecycleRollbackPersistenceInFlight = false
                self.invalidateSleepReviewCache(
                    reason: "recovered_lifecycle_rollback"
                )
                Self.confirmedRecordTransactionGate.release()
                if UIApplication.shared.applicationState == .active {
                    self.resumeRecoveredDataPublicationLeaseForForeground(
                        reason: "lifecycle_rollback_persistence_complete"
                    )
                }
            } else {
                Self.confirmedRecordTransactionGate.release()
            }
            self.endRecoveredLifecycleRollbackBackgroundTask()
        }
    }

    private func endRecoveredLifecycleRollbackBackgroundTask() {
        guard recoveredLifecycleRollbackBackgroundTask != .invalid else {
            return
        }
        UIApplication.shared.endBackgroundTask(
            recoveredLifecycleRollbackBackgroundTask
        )
        recoveredLifecycleRollbackBackgroundTask = .invalid
    }

    private func restoreRecoveredDefaultsData(_ data: Data?, key: String, fallback: Data?) {
        if let data = data ?? fallback {
            UserDefaults.standard.set(data, forKey: key)
        }
    }

    private func restoreRecoveredFileData(_ data: Data?, fallback: Data?, to url: URL) {
        guard let data = data ?? fallback else { return }
        do {
            try data.write(to: url, options: .atomic)
        } catch {
            AtriaDebugLog("ATRIADBG recovered_transaction status=rollback_file_failed file=%@ error=%@",
                          url.lastPathComponent,
                          error.localizedDescription)
        }
    }

    private func commitRecoveredDataMutationTransaction(
        ticket: AtriaRecoveredDataRecomputeCoordinator.Ticket
    ) -> Bool {
        guard recoveredDataMutationTransaction.rollbackOperationCount > 0,
              recoveredDataMutationTransaction.commit(ticket: ticket) else { return false }
        stressReplayTerminalPublicationGate.commitTransaction()
        recoveredStressReplayPreservedWorkoutAdditionIDs.removeAll(
            keepingCapacity: true
        )
        recoveredConcurrentConfirmedSleepUpserts.removeAll(
            keepingCapacity: true
        )
        recoveredConcurrentConfirmedSleepDeletedIDs.removeAll(
            keepingCapacity: true
        )
        dailyRollupStore.endRecoveredDataPublicationFence()
        scheduleDailyMetricPersist(reason: "recovered_transaction_commit", delay: 0)
        flushPendingDeferredStageBackfillPublicationAfterRecoveredTerminal()
        return true
    }

    private func rollbackRecoveredDataMutationTransaction(
        ticket: AtriaRecoveredDataRecomputeCoordinator.Ticket,
        replayDeferredWork: Bool = true
    ) -> Bool {
        let hadPreparedMutation = recoveredDataMutationTransaction.rollbackOperationCount > 0
        recoveredLifecycleRollbackUsesBoundedRestore = !replayDeferredWork
        defer { recoveredLifecycleRollbackUsesBoundedRestore = false }
        guard recoveredDataMutationTransaction.rollback(ticket: ticket) else { return false }
        if replayDeferredWork {
            recoveredConcurrentConfirmedSleepUpserts.removeAll(
                keepingCapacity: true
            )
            recoveredConcurrentConfirmedSleepDeletedIDs.removeAll(
                keepingCapacity: true
            )
        }
        let stressReplayOutcome = stressReplayTerminalPublicationGate
            .rollbackTransaction()
        recoveredStressReplayPreservedWorkoutAdditionIDs.removeAll(
            keepingCapacity: true
        )
        if hadPreparedMutation {
            dailyRollupStore.endRecoveredDataPublicationFence()
        }
        // A launch-time card rebuild may have completed while this recovered
        // image was provisional. Rollback restored the prior canonical image;
        // rerun the required refresh rather than publishing either intermediate.
        if replayDeferredWork {
            refreshRequiredHistorySnapshotIfPending()
            if stressReplayOutcome.requiresSessionAuthorityPublication {
                publishHistoricalStressSessionAuthority()
            }
            if stressReplayOutcome.shouldPublish {
                publishStressReplayTerminalEdge(
                    reason: "recovered_rollback_preserved_live_mutation"
                )
            }
            publishStressCalibrationFenceDidRelease(
                reason: "recovered_rollback_final_state"
            )
        } else {
            recoveredLifecycleRollbackCleanupPending = true
            recoveredLifecycleRollbackNeedsSessionAuthority =
                recoveredLifecycleRollbackNeedsSessionAuthority
                    || stressReplayOutcome
                        .requiresSessionAuthorityPublication
            recoveredLifecycleRollbackNeedsStressEdge =
                recoveredLifecycleRollbackNeedsStressEdge
                    || stressReplayOutcome.shouldPublish
        }
        flushPendingDeferredStageBackfillPublicationAfterRecoveredTerminal()
        return true
    }

    private func finishDeferredRecoveredLifecycleRollbackCleanupIfSafe() {
        guard recoveredLifecycleRollbackCleanupPending,
              activeRecoveredDataExecution == nil,
              !recoveredLifecycleRollbackPersistenceInFlight,
              UIApplication.shared.applicationState == .active else { return }
        recoveredLifecycleRollbackCleanupPending = false
        refreshRequiredHistorySnapshotIfPending()
        if recoveredLifecycleRollbackNeedsSessionAuthority {
            publishHistoricalStressSessionAuthority()
        }
        if recoveredLifecycleRollbackNeedsStressEdge {
            publishStressReplayTerminalEdge(
                reason: "recovered_lifecycle_rollback_preserved_live_mutation"
            )
        }
        recoveredLifecycleRollbackNeedsSessionAuthority = false
        recoveredLifecycleRollbackNeedsStressEdge = false
        publishStressCalibrationFenceDidRelease(
            reason: "recovered_lifecycle_rollback_final_state"
        )
    }

    var recoveredDataArchiveRevisionSnapshot: UInt64 {
        recoveredDataPublicationFence.archiveRevision
    }

    /// O(1), exact-store guard for consumers with their own coalesced replay
    /// triggers. An active mutation ticket spans the entire provisional
    /// recovered image and is cleared only by commit/rollback; callers should
    /// wait for `recoveredDataRecomputeDidPublishNotification` instead of
    /// consuming baseline/context publishers while this is true.
    var stressReplayPublicationIsDeferred: Bool {
        recoveredDataMutationTransaction.activeTicket != nil
            || restorePersistenceFenceActive
    }

    nonisolated static var recoveredDataMaximumPipelineWaitSeconds: Int {
        AtriaRecoveredDataTimeoutPolicy.physicalSessionStore.maximumPipelineSeconds(
            requiredDerivedComponentCount: AtriaRecoveredDataRecomputeCoordinator
                .sessionStoreComponents.count
        )
    }

    nonisolated static func recoveredDataPublicationWaitDuration(
        requested: Duration
    ) -> Duration {
        max(requested, .seconds(recoveredDataMaximumPipelineWaitSeconds))
    }

    /// Waits for the newest archive revision observed since `priorRevision` to
    /// cross the full publication fence. If no durable archive update arrived,
    /// there is nothing new to wait for.
    func awaitRecoveredDataPublication(
        after priorRevision: UInt64,
        timeout: Duration = .seconds(120)
    ) async -> Bool {
        // A caller may ask for more time, but not less than the finite internal
        // pipeline bound. Otherwise the public fence can report failure while
        // its coordinator is still legitimately inside a component lease.
        let effectiveTimeout = Self.recoveredDataPublicationWaitDuration(
            requested: timeout
        )
        return await recoveredDataPublicationFence.awaitPublication(
            after: priorRevision,
            timeout: effectiveTimeout
        )
    }

    func requestAndAwaitRecoveredDataPublication(
        reason: String,
        timeout: Duration = .seconds(120)
    ) async -> Bool {
        let priorRevision = recoveredDataPublicationFence.archiveRevision
        guard requestRecoveredDataRecomputation(
            reason: reason,
            allowsIncompleteOnboarding: true,
            isExactRecoveryPublication: true
        ) else { return false }
        return await awaitRecoveredDataPublication(after: priorRevision,
                                                   timeout: timeout)
    }

    /// Compatibility seam for the original anti-starvation scheduler tests.
    /// The coordinator now owns this policy and coalesces every pending update
    /// to its newest archive revision.
    nonisolated static func historicalArchiveRefreshNeedsTrailingRun(
        hasPendingRefresh: Bool
    ) -> Bool {
        hasPendingRefresh
    }

    private func recoveredDataExecutionIsCurrent(
        ticket: AtriaRecoveredDataRecomputeCoordinator.Ticket,
        authority: RecoveredDataExecutionAuthority,
        requireRunnable: Bool = true
    ) -> Bool {
        guard let active = activeRecoveredDataExecution,
              active.ticket == ticket,
              active.authority.matches(authority) else { return false }
        guard requireRunnable else { return true }
        return authority.shouldContinue()
    }

    private func requireRecoveredDataExecutionAuthority(
        ticket: AtriaRecoveredDataRecomputeCoordinator.Ticket,
        stage: String
    ) -> RecoveredDataExecutionAuthority? {
        guard let execution = activeRecoveredDataExecution,
              execution.ticket == ticket else { return nil }
        guard execution.authority.shouldContinueForMainActorMutation(
            applicationIsActive:
                UIApplication.shared.applicationState == .active
        ) else {
            deferRecoveredDataExecutionForLostAuthority(
                ticket: ticket,
                authority: execution.authority,
                stage: stage,
                reason: "execution_authority_revoked"
            )
            return nil
        }
        return execution.authority
    }

    private func recordRecoveredExecutionEdge(
        ticket: AtriaRecoveredDataRecomputeCoordinator.Ticket,
        authority: RecoveredDataExecutionAuthority?,
        stage: String,
        outcome: String,
        reason: String? = nil
    ) {
        let scope: String
        switch ticket.scope {
        case .full: scope = "full"
        case .automaticCurrentCycle: scope = "automatic_current_cycle"
        }
        let revokeCount = recoveredExecutionRevocationCountByGeneration[
            ticket.generation,
            default: 0
        ]
        let staleCount = recoveredExecutionStaleCountByGeneration[
            ticket.generation,
            default: 0
        ]
        let defaults = UserDefaults.standard
        let prior = defaults.dictionary(
            forKey: Self.recoveredExecutionDiagnosticDefaultsKey
        )

        var event: [String: Any] = [
            "generation": Int(clamping: ticket.generation),
            "revision": Int(clamping: ticket.archiveRevision),
            "scope": scope,
            "cutoff_unix_ms": 0,
            "has_cutoff": false,
            "authority": authority?.label ?? "none",
            "authority_kind": authority?.label ?? "none",
            "authority_id": 0,
            "edge": stage == "admission" && outcome == "started"
                ? "admit"
                : (outcome == "revoked"
                    ? "revoke"
                    : (outcome == "published"
                        ? "publish"
                        : (stage == "terminal" ? "terminal" : "stage"))),
            "stage": stage,
            "outcome": outcome,
            "revoke_count": revokeCount,
            "stale_rejection_count": staleCount,
            "stale": outcome == "stale_rejected",
            "published": outcome == "published",
            "reason": reason ?? "none",
            "request_reason": ticket.reason,
            "at_unix_ms": Int((Date().timeIntervalSince1970 * 1_000).rounded()),
            "event_uptime_ms": Int((ProcessInfo.processInfo.systemUptime
                * 1_000).rounded()),
        ]
        if case .automaticCurrentCycle(let cutoff) = ticket.scope {
            event["cutoff_unix_ms"] = Int(
                (cutoff.timeIntervalSince1970 * 1_000).rounded()
            )
            event["has_cutoff"] = true
        }
        if let authority {
            switch authority {
            case .foreground(let lease):
                event["authority_id"] = Int(clamping: lease.identity.generation)
                event["foreground_token_generation"] = Int(
                    clamping: lease.identity.generation
                )
            case .background(let lease):
                event["authority_id"] = Int(clamping: lease.generation)
                event["background_lease_generation"] = Int(
                    clamping: lease.generation
                )
                event["background_deadline_uptime_ms"] = Int(
                    (lease.deadlineUptime * 1_000).rounded()
                )
            }
        }
        defaults.set(
            Self.appendingRecoveredExecutionDiagnosticEvent(event, to: prior),
            forKey: Self.recoveredExecutionDiagnosticDefaultsKey
        )
    }

    private func recordStaleRecoveredExecutionCompletion(
        ticket: AtriaRecoveredDataRecomputeCoordinator.Ticket,
        authority: RecoveredDataExecutionAuthority,
        stage: String
    ) {
        recoveredExecutionStaleCountByGeneration[
            ticket.generation,
            default: 0
        ] &+= 1
        recordRecoveredExecutionEdge(
            ticket: ticket,
            authority: authority,
            stage: stage,
            outcome: "stale_rejected"
        )
    }

    private func retireRecoveredDataExecutionIfCurrent(
        ticket: AtriaRecoveredDataRecomputeCoordinator.Ticket,
        outcome: String,
        reason: String
    ) {
        guard let active = activeRecoveredDataExecution,
              active.ticket == ticket else { return }
        pendingRecoveredSleepReadinessRetryGeneration &+= 1
        pendingRecoveredSleepReadinessRetry?.cancel()
        pendingRecoveredSleepReadinessRetry = nil
        switch active.authority {
        case .foreground(let lease):
            _ = lease.revoke(reason: reason)
        case .background(let lease):
            _ = AtriaBackgroundProjectionThrottle.shared.cancel(
                lease: lease
            )
        }
        recoveredDataPublicationCheckpointInFlightGenerations.remove(
            ticket.generation
        )
        recoveredDataPreparedCheckpointIdentityByGeneration.removeValue(
            forKey: ticket.generation
        )
        if outcome != "published" {
            let checkpointDestination = recoveredCurrentCheckpointURL
            Self.historySnapshotProjectionQueue.async {
                Self.removeRecoveredCurrentCheckpointIfOwned(
                    generation: ticket.generation,
                    at: checkpointDestination
                )
            }
        }
        recordRecoveredExecutionEdge(
            ticket: ticket,
            authority: active.authority,
            stage: "terminal",
            outcome: outcome,
            reason: reason
        )
        activeRecoveredDataExecution = nil
    }

    private func deferRecoveredDataExecutionForLostAuthority(
        ticket: AtriaRecoveredDataRecomputeCoordinator.Ticket,
        authority: RecoveredDataExecutionAuthority,
        stage: String,
        reason: String
    ) {
        guard recoveredDataExecutionIsCurrent(
            ticket: ticket,
            authority: authority,
            requireRunnable: false
        ) else {
            recordStaleRecoveredExecutionCompletion(
                ticket: ticket,
                authority: authority,
                stage: stage
            )
            return
        }
        recoveredExecutionRevocationCountByGeneration[
            ticket.generation,
            default: 0
        ] &+= 1
        if case .foreground(let lease) = authority {
            _ = lease.revoke(reason: reason)
            recordRecoveredExecutionEdge(
                ticket: ticket,
                authority: authority,
                stage: stage,
                outcome: "revoked",
                reason: reason
            )
            handleRecoveredDataRecomputeEffects(
                recoveredDataRecompute.deferActiveUntilForeground(
                    ticket: ticket
                )
            )
        } else {
            recordRecoveredExecutionEdge(
                ticket: ticket,
                authority: authority,
                stage: stage,
                outcome: "revoked",
                reason: reason
            )
            handleRecoveredDataRecomputeEffects(
                recoveredDataRecompute.cancelActiveForSafeBackground(
                    ticket: ticket
                )
            )
        }
    }

    private func handleRecoveredDataRecomputeEffects(
        _ effects: [AtriaRecoveredDataRecomputeCoordinator.Effect]
    ) {
        for effect in effects {
            switch effect {
            case .startProjection(let ticket):
                recoveredExecutionRevocationCountByGeneration[
                    ticket.generation
                ] = 0
                recoveredExecutionStaleCountByGeneration[
                    ticket.generation
                ] = 0
                if ticket.generation > 8 {
                    let floor = ticket.generation - 8
                    recoveredExecutionRevocationCountByGeneration =
                        recoveredExecutionRevocationCountByGeneration.filter {
                            $0.key >= floor
                        }
                    recoveredExecutionStaleCountByGeneration =
                        recoveredExecutionStaleCountByGeneration.filter {
                            $0.key >= floor
                        }
                }
                if exactRecoveryProjectionArchiveRevisions.contains(
                    ticket.archiveRevision
                ) {
                    exactRecoveryArchivePriorityLeaseActive = true
                }
                recoveredDataProjectionLeaseRenewals[ticket.generation] = 0
                recoveredDataProjectionCompletedStages[ticket.generation] = []
                recoveredDataDerivedLeaseRenewals[ticket.generation] = 0
                recoveredDataDerivedCompletedStages[ticket.generation] = []
                guard beginRecoveredDataMutationTransaction(ticket: ticket) else {
                    handleRecoveredDataRecomputeEffects(
                        recoveredDataRecompute.projectionCompleted(
                            ticket: ticket,
                            failureReason: "mutation_transaction_unavailable"
                        )
                    )
                    continue
                }
                let authority: RecoveredDataExecutionAuthority
                if ticket.executionDomain == .explicitBackground {
                    guard let lease = AtriaBackgroundProjectionThrottle.shared
                        .captureActiveLease() else {
                        handleRecoveredDataRecomputeEffects(
                            recoveredDataRecompute
                                .projectionReservedForSafeBackground(
                                    ticket: ticket
                                )
                        )
                        continue
                    }
                    authority = .background(lease)
                } else {
                    authority = .foreground(
                        AtriaRecoveredDataExecutionLease(
                            generation: ticket.generation,
                            archiveRevision: ticket.archiveRevision
                        )
                    )
                }
                guard activeRecoveredDataExecution == nil else {
                    handleRecoveredDataRecomputeEffects(
                        recoveredDataRecompute.projectionCompleted(
                            ticket: ticket,
                            failureReason: "execution_authority_unavailable"
                        )
                    )
                    continue
                }
                activeRecoveredDataExecution = .init(
                    ticket: ticket,
                    authority: authority
                )
                if case .foreground = authority,
                   (UIApplication.shared.applicationState != .active
                        || !authority.shouldContinue()) {
                    deferRecoveredDataExecutionForLostAuthority(
                        ticket: ticket,
                        authority: authority,
                        stage: "admission",
                        reason: "foreground_environment_unavailable"
                    )
                    continue
                }
                guard authority.shouldContinue() else {
                    deferRecoveredDataExecutionForLostAuthority(
                        ticket: ticket,
                        authority: authority,
                        stage: "admission",
                        reason: "background_lease_unavailable"
                    )
                    continue
                }
                armRecoveredDataRecomputeTimeout(ticket: ticket,
                                                 phase: "projection",
                                                 component: nil)
                AtriaDebugLog(
                    "ATRIADBG recovered_projection status=started reason=%@ generation=%llu archive_revision=%llu",
                    ticket.reason,
                    ticket.generation,
                    ticket.archiveRevision
                )
                recordRecoveredExecutionEdge(
                    ticket: ticket,
                    authority: authority,
                    stage: "admission",
                    outcome: "started"
                )
                runRecoveredHeartRateProjection(
                    ticket: ticket,
                    authority: authority
                )

            case .startDerived(let ticket, let components):
                // Projection and derived fan-out are separate bounded phases.
                // Sharing one 30-second clock caused a valid 207 MB physical
                // archive scan to leave only a few seconds for eight derived
                // consumers, which then failed despite real forward progress.
                guard let execution = activeRecoveredDataExecution,
                      execution.ticket == ticket else {
                    continue
                }
                guard execution.authority.shouldContinueForMainActorMutation(
                    applicationIsActive:
                        UIApplication.shared.applicationState == .active
                ) else {
                    deferRecoveredDataExecutionForLostAuthority(
                        ticket: ticket,
                        authority: execution.authority,
                        stage: "derived_admission",
                        reason: "execution_authority_revoked"
                    )
                    continue
                }
                if case .automaticCurrentCycle = ticket.scope {
                    guard components.contains(
                        .currentCycleAndLatestNight
                    ) else {
                        _ = completeRecoveredDataComponent(
                            ticket: ticket,
                            component: .currentCycleAndLatestNight,
                            succeeded: false
                        )
                        continue
                    }
                    armRecoveredDataRecomputeTimeout(
                        ticket: ticket,
                        phase: "derived",
                        component: .currentCycleAndLatestNight
                    )
                    runRecoveredCurrentCyclePublicationStep(ticket: ticket)
                } else {
                    armRecoveredDataRecomputeTimeout(ticket: ticket,
                                                     phase: "derived",
                                                     component: .archiveStatusAndCycleHeartRate)
                    runRecoveredArchiveStatusStep(ticket: ticket)
                }

            case .superseded(let ticket):
                recoveredDataProjectionLeaseRenewals.removeValue(
                    forKey: ticket.generation
                )
                recoveredDataProjectionCompletedStages.removeValue(
                    forKey: ticket.generation
                )
                recoveredDataDerivedLeaseRenewals.removeValue(
                    forKey: ticket.generation
                )
                recoveredDataDerivedCompletedStages.removeValue(
                    forKey: ticket.generation
                )
                retireRecoveredDataExecutionIfCurrent(
                    ticket: ticket,
                    outcome: "superseded",
                    reason: "newer_archive_revision"
                )
                guard rollbackRecoveredDataMutationTransaction(ticket: ticket) else {
                    AtriaDebugLog("ATRIADBG recovered_transaction status=rollback_rejected reason=superseded generation=%llu archive_revision=%llu",
                                  ticket.generation,
                                  ticket.archiveRevision)
                    continue
                }
                releaseExactRecoveryArchivePriority(
                    for: ticket,
                    reason: "superseded"
                )
                AtriaDebugLog("ATRIADBG recovered_derived status=superseded generation=%llu archive_revision=%llu",
                              ticket.generation,
                              ticket.archiveRevision)

            case .deferredUntilForeground(let ticket):
                recoveredDataRecomputeTimeoutTask?.cancel()
                recoveredDataRecomputeTimeoutTask = nil
                recoveredDataRecomputeTimeoutContext = nil
                recoveredDataRecomputeLeaseSuspendedForBackground = true
                recoveredDataProjectionLeaseRenewals.removeValue(
                    forKey: ticket.generation
                )
                recoveredDataProjectionCompletedStages.removeValue(
                    forKey: ticket.generation
                )
                recoveredDataDerivedLeaseRenewals.removeValue(
                    forKey: ticket.generation
                )
                recoveredDataDerivedCompletedStages.removeValue(
                    forKey: ticket.generation
                )
                retireRecoveredDataExecutionIfCurrent(
                    ticket: ticket,
                    outcome: "deferred_until_foreground",
                    reason: "foreground_authority_revoked"
                )
                let rolledBack = rollbackRecoveredDataMutationTransaction(
                    ticket: ticket,
                    replayDeferredWork: false
                )
                AtriaDebugLog(
                    "ATRIADBG recovered_execution status=deferred_until_foreground generation=%llu archive_revision=%llu rollback=%d action=retain_exact_ticket",
                    ticket.generation,
                    ticket.archiveRevision,
                    rolledBack ? 1 : 0
                )

            case .cancelledForSafeBackground(let ticket):
                recoveredDataRecomputeTimeoutTask?.cancel()
                recoveredDataRecomputeTimeoutTask = nil
                recoveredDataRecomputeTimeoutContext = nil
                recoveredDataRecomputeLeaseSuspendedForBackground = false
                recoveredDataProjectionLeaseRenewals.removeValue(
                    forKey: ticket.generation
                )
                recoveredDataProjectionCompletedStages.removeValue(
                    forKey: ticket.generation
                )
                recoveredDataDerivedLeaseRenewals.removeValue(
                    forKey: ticket.generation
                )
                recoveredDataDerivedCompletedStages.removeValue(
                    forKey: ticket.generation
                )
                retireRecoveredDataExecutionIfCurrent(
                    ticket: ticket,
                    outcome: "background_lease_ended",
                    reason: "exact_background_lease_revoked"
                )
                let rolledBack = rollbackRecoveredDataMutationTransaction(
                    ticket: ticket,
                    replayDeferredWork: false
                )
                reserveAutomaticRecoveredProjectionFreshness(
                    reason: "background_lease_ended"
                )
                recoveredDataPublicationFence.fail(
                    through: ticket.archiveRevision
                )
                AtriaDebugLog(
                    "ATRIADBG recovered_execution status=background_lease_ended generation=%llu archive_revision=%llu rollback=%d action=retain_bootstrap_intent",
                    ticket.generation,
                    ticket.archiveRevision,
                    rolledBack ? 1 : 0
                )

            case .reservedForSafeBackground(let ticket):
                recoveredDataRecomputeTimeoutTask?.cancel()
                recoveredDataRecomputeTimeoutTask = nil
                recoveredDataRecomputeTimeoutContext = nil
                recoveredDataRecomputeLeaseSuspendedForBackground = false
                recoveredDataProjectionLeaseRenewals.removeValue(
                    forKey: ticket.generation
                )
                recoveredDataProjectionCompletedStages.removeValue(
                    forKey: ticket.generation
                )
                recoveredDataDerivedLeaseRenewals.removeValue(
                    forKey: ticket.generation
                )
                recoveredDataDerivedCompletedStages.removeValue(
                    forKey: ticket.generation
                )
                retireRecoveredDataExecutionIfCurrent(
                    ticket: ticket,
                    outcome: "reserved_for_safe_background",
                    reason: "automatic_budget_or_plan"
                )
                // Authoritative admission runs before the first recovered
                // mutation is registered. Discard the empty transaction
                // directly: the general rollback helper intentionally replays
                // pending history work, which would defeat this no-scan exit.
                let rolledBack = recoveredDataMutationTransaction.rollback(
                    ticket: ticket
                )
                if rolledBack {
                    let stressReplayOutcome =
                        stressReplayTerminalPublicationGate
                            .rollbackTransaction()
                    recoveredStressReplayPreservedWorkoutAdditionIDs.removeAll(
                        keepingCapacity: true
                    )
                    if stressReplayOutcome.requiresSessionAuthorityPublication {
                        publishHistoricalStressSessionAuthority()
                    }
                    if stressReplayOutcome.shouldPublish {
                        publishStressReplayTerminalEdge(
                            reason:
                                "recovered_reservation_rollback_preserved_live_mutation"
                        )
                    }
                    publishStressCalibrationFenceDidRelease(
                        reason: "recovered_reservation_rollback_final_state"
                    )
                    flushPendingDeferredStageBackfillPublicationAfterRecoveredTerminal()
                }
                if ticket.reason.hasPrefix(
                    "bg_projection_current_window_bootstrap"
                ) {
                    // Wake the BGTask waiter after one bounded chunk. No
                    // publication occurred, so this revision fails closed;
                    // the durable bootstrap intent schedules the next chunk.
                    recoveredDataPublicationFence.fail(
                        through: ticket.archiveRevision
                    )
                }
                if case .automaticCurrentCycle = ticket.scope {
                    reserveAutomaticRecoveredProjectionFreshness(
                        reason: "automatic_budget_or_plan"
                    )
                }
                AtriaDebugLog(
                    "ATRIADBG recovered_projection status=reserved_for_safe_background reason=%@ generation=%llu archive_revision=%llu rollback=%d action=reuse_persisted_projection",
                    ticket.reason,
                    ticket.generation,
                    ticket.archiveRevision,
                    rolledBack ? 1 : 0
                )

            case .failed(let ticket, let failure):
                recoveredDataRecomputeTimeoutTask?.cancel()
                recoveredDataRecomputeTimeoutTask = nil
                recoveredDataRecomputeTimeoutContext = nil
                recoveredDataRecomputeLeaseSuspendedForBackground = false
                recoveredDataProjectionLeaseRenewals.removeValue(
                    forKey: ticket.generation
                )
                recoveredDataProjectionCompletedStages.removeValue(
                    forKey: ticket.generation
                )
                recoveredDataDerivedLeaseRenewals.removeValue(
                    forKey: ticket.generation
                )
                recoveredDataDerivedCompletedStages.removeValue(
                    forKey: ticket.generation
                )
                retireRecoveredDataExecutionIfCurrent(
                    ticket: ticket,
                    outcome: "failed",
                    reason: failure.reason
                )
                let rolledBack = rollbackRecoveredDataMutationTransaction(ticket: ticket)
                AtriaDebugLog("ATRIADBG recovered_derived status=failed generation=%llu archive_revision=%llu component=%@ reason=%@ action=retain_previous_publication",
                              ticket.generation,
                              ticket.archiveRevision,
                              failure.component?.rawValue ?? "projection",
                              failure.reason)
                AtriaDebugLog("ATRIADBG recovered_transaction status=%@ generation=%llu archive_revision=%llu",
                              rolledBack ? "rolled_back" : "rollback_rejected",
                              ticket.generation,
                              ticket.archiveRevision)
                if case .failed = recoveredDataRecompute.phase {
                    recoveredDataPublicationFence.fail(
                        through: ticket.archiveRevision
                    )
                }
                releaseExactRecoveryArchivePriority(
                    for: ticket,
                    reason: failure.reason
                )
                // Single heavy lane (2026-08-05): a failed projection cannot
                // strand the history cache an external refresh wanted fresh.
                if pendingHistoryRefreshDeferredByProjectionScan {
                    pendingHistoryRefreshDeferredByProjectionScan = false
                    refreshHistorySnapshotCache(deferred: true)
                }
                finishDeferredRecoveredLifecycleRollbackCleanupIfSafe()

            case .scheduleTrailingStart(let afterSeconds):
                // Inter-cycle rest wake (2026-08-04): the coordinator queues
                // trailing recompute requests through a rest window so
                // drain-triggered cycles never run back-to-back (the beta
                // allocator reclaims each cycle's transient garbage only at
                // thread teardown; uninterrupted cycles crept into the
                // jetsam ceiling). Idempotent on the coordinator side.
                DispatchQueue.main.asyncAfter(
                    deadline: .now() + afterSeconds
                ) { [weak self] in
                    guard let self else { return }
                    guard Self.recoveredExecutionEnvironmentAction(
                        applicationIsActive:
                            UIApplication.shared.applicationState == .active,
                        thermalState: ProcessInfo.processInfo.thermalState,
                        isLowPowerModeEnabled:
                            ProcessInfo.processInfo.isLowPowerModeEnabled
                    ) == .resume else {
                        self.recoveredDataRecompute
                            .parkTrailingUntilForeground()
                        return
                    }
                    self.handleRecoveredDataRecomputeEffects(
                        self.recoveredDataRecompute.startPendingTrailing()
                    )
                }

            case .publish(let ticket):
                recoveredDataRecomputeTimeoutTask?.cancel()
                recoveredDataRecomputeTimeoutTask = nil
                recoveredDataRecomputeTimeoutContext = nil
                recoveredDataRecomputeLeaseSuspendedForBackground = false
                recoveredDataProjectionLeaseRenewals.removeValue(
                    forKey: ticket.generation
                )
                recoveredDataProjectionCompletedStages.removeValue(
                    forKey: ticket.generation
                )
                recoveredDataDerivedLeaseRenewals.removeValue(
                    forKey: ticket.generation
                )
                recoveredDataDerivedCompletedStages.removeValue(
                    forKey: ticket.generation
                )
                guard let execution = activeRecoveredDataExecution,
                      execution.ticket == ticket else {
                    continue
                }
                guard execution.authority.shouldContinueForMainActorMutation(
                    applicationIsActive:
                        UIApplication.shared.applicationState == .active
                ) else {
                    deferRecoveredDataExecutionForLostAuthority(
                        ticket: ticket,
                        authority: execution.authority,
                        stage: "publish",
                        reason: "execution_authority_revoked"
                    )
                    continue
                }
                guard commitRecoveredDataMutationTransaction(ticket: ticket) else {
                    // A publish with no registered recovered mutation cannot
                    // commit, but its active ticket still fenced calibration
                    // observations. Roll it back through the ordinary terminal
                    // helper so pending profile/fallback state cannot strand.
                    let terminalCleanupSucceeded =
                        rollbackRecoveredDataMutationTransaction(ticket: ticket)
                    recoveredDataPublicationFence.fail(through: ticket.archiveRevision)
                    retireRecoveredDataExecutionIfCurrent(
                        ticket: ticket,
                        outcome: "failed",
                        reason: "commit_rejected"
                    )
                    releaseExactRecoveryArchivePriority(
                        for: ticket,
                        reason: "commit_rejected"
                    )
                    AtriaDebugLog("ATRIADBG recovered_transaction status=commit_rejected generation=%llu archive_revision=%llu terminal_cleanup=%d",
                                  ticket.generation,
                                  ticket.archiveRevision,
                                  terminalCleanupSucceeded ? 1 : 0)
                    continue
                }
                // Publication must remain a bounded MainActor edge. Rebuilding
                // this optional diagnostics cache can decode the active journal
                // and walk recovered session evidence; leave it invalidated so
                // its ordinary demand-driven refresh cannot delay lifecycle
                // revocation or the exact publication fence below.
                cachedHomeDashboardDiagnostics = nil
                publishDashboardRevision()
                recoveredDataPublicationFence.publish(
                    through: ticket.archiveRevision
                )
                if let checkpointIdentity =
                    recoveredDataPreparedCheckpointIdentityByGeneration[
                        ticket.generation
                    ] {
                    // Activating the already-durable checkpoint after the real
                    // dashboard + fence mutation prevents crash restore of a
                    // provisional generation. These bounded defaults writes
                    // are part of the same MainActor publication edge.
                    let defaults = UserDefaults.standard
                    defaults.set(
                        checkpointIdentity,
                        forKey: Self
                            .recoveredCurrentCheckpointPublicationIdentityKey
                    )
                    defaults.removeObject(
                        forKey: Self.automaticRecoveredDataBootstrapIntentKey
                    )
                    defaults.removeObject(
                        forKey: Self
                            .automaticRecoveredProjectionFreshnessIntentKey
                    )
                    Self.historySnapshotProjectionQueue.async {
                        HistoricalArchive
                            .removeAutomaticRecoveredDataBootstrapCheckpoint()
                    }
                }
                // The persisted diagnostic `publish` edge is truthful only
                // after the dashboard/checkpoint and exact publication fence
                // have all advanced. Retiring earlier made an interrupted
                // publication indistinguishable from a completed one.
                retireRecoveredDataExecutionIfCurrent(
                    ticket: ticket,
                    outcome: "published",
                    reason: "publication_committed"
                )
                NotificationCenter.default.post(
                    name: Self.recoveredDataRecomputeDidPublishNotification,
                    object: self,
                    userInfo: ["archiveRevision": ticket.archiveRevision,
                               "reason": ticket.reason]
                )
                onRecoveredDataRecomputePublished?(ticket.archiveRevision, ticket.reason)
                resumeDeferredLaunchCardSettlementIfNeeded(
                    reason: "recovered_publication_\(ticket.reason)"
                )
                AtriaDebugLog("ATRIADBG recovered_derived status=published generation=%llu archive_revision=%llu",
                              ticket.generation,
                              ticket.archiveRevision)
                releaseExactRecoveryArchivePriority(
                    for: ticket,
                    reason: "published"
                )
                // Single heavy lane (2026-08-05): the pipeline's own history
                // component just refreshed — the deferred external intent is
                // satisfied, not stranded.
                pendingHistoryRefreshDeferredByProjectionScan = false
                finishDeferredRecoveredLifecycleRollbackCleanupIfSafe()
            }
        }
    }

    private func armRecoveredDataRecomputeTimeout(
        ticket: AtriaRecoveredDataRecomputeCoordinator.Ticket,
        phase: String,
        component: AtriaRecoveredDataRecomputeCoordinator.Component?
    ) {
        recoveredDataRecomputeTimeoutTask?.cancel()
        recoveredDataRecomputeTimeoutContext = .init(
            ticket: ticket,
            phase: phase,
            component: component
        )
        guard UIApplication.shared.applicationState == .active else {
            recoveredDataRecomputeTimeoutTask = nil
            recoveredDataRecomputeLeaseSuspendedForBackground = true
            AtriaDebugLog(
                "ATRIADBG recovered_derived status=lease_suspended phase=%@ component=%@ generation=%llu archive_revision=%llu reason=application_not_active",
                phase,
                component?.rawValue ?? "pipeline",
                ticket.generation,
                ticket.archiveRevision
            )
            return
        }
        recoveredDataRecomputeLeaseSuspendedForBackground = false
        let policy = AtriaRecoveredDataTimeoutPolicy.physicalSessionStore
        let leaseSeconds = phase == "projection"
            ? policy.projectionLeaseSeconds
            : policy.derivedComponentLeaseSeconds
        recoveredDataRecomputeTimeoutTask = Task { @MainActor [weak self] in
            try? await Task.sleep(for: .seconds(leaseSeconds))
            guard !Task.isCancelled, let self else { return }
            AtriaDebugLog("ATRIADBG recovered_derived status=timeout phase=%@ component=%@ lease_s=%d generation=%llu archive_revision=%llu",
                          phase,
                          component?.rawValue ?? "pipeline",
                          leaseSeconds,
                          ticket.generation,
                          ticket.archiveRevision)
            self.handleRecoveredDataRecomputeEffects(
                self.recoveredDataRecompute.timedOut(ticket: ticket,
                                                     component: component)
            )
        }
    }

    func suspendRecoveredDataPublicationLeaseForBackground(reason: String) {
        // Invalidate queued metadata admission as well as already-running work.
        // A callback captured before this edge may reserve durable intent, but it
        // may not mint a ticket after foreground authority is gone.
        automaticRecoveredProjectionAdmissionGeneration &+= 1
        automaticRecoveredArchiveIdleGeneration &+= 1
        automaticRecoveredArchiveIdleTask?.cancel()
        automaticRecoveredArchiveIdleTask = nil
        pendingRecoveredSleepReadinessRetryGeneration &+= 1
        pendingRecoveredSleepReadinessRetry?.cancel()
        pendingRecoveredSleepReadinessRetry = nil
        // A rest-window timer owns no execution token yet. Move its exact
        // request/cutoff into the same foreground-only slot before inspecting
        // active work, so the timer cannot mint a background generation.
        recoveredDataRecompute.parkTrailingUntilForeground()
        guard let execution = activeRecoveredDataExecution else {
            recoveredDataRecomputeTimeoutTask?.cancel()
            recoveredDataRecomputeTimeoutTask = nil
            return
        }
        if case .background = execution.authority,
           execution.authority.shouldContinue() {
            // A real BGProcessing ticket owns its exact throttle generation. A
            // scene transition cannot revoke or replace that independent lease.
            return
        }
        recoveredDataRecomputeTimeoutTask?.cancel()
        recoveredDataRecomputeTimeoutTask = nil
        recoveredDataRecomputeLeaseSuspendedForBackground = true
        deferRecoveredDataExecutionForLostAuthority(
            ticket: execution.ticket,
            authority: execution.authority,
            stage: "lifecycle",
            reason: reason
        )
        AtriaDebugLog(
            "ATRIADBG recovered_derived status=execution_revoked reason=%@",
            reason
        )
    }

    func resumeRecoveredDataPublicationLeaseForForeground(reason: String) {
        guard UIApplication.shared.applicationState == .active,
              !AtriaHistoricalProjectionForegroundGate.isBackgrounded,
              ProcessInfo.processInfo.thermalState != .serious,
              ProcessInfo.processInfo.thermalState != .critical,
              !ProcessInfo.processInfo.isLowPowerModeEnabled else { return }
        if invalidateRecoveredDataBackgroundExecutionLeaseForForeground(
            reason: reason
        ) {
            return
        }
        if let execution = activeRecoveredDataExecution,
           !execution.authority.shouldContinue() {
            deferRecoveredDataExecutionForLostAuthority(
                ticket: execution.ticket,
                authority: execution.authority,
                stage: "foreground_resume",
                reason: "execution_authority_revoked"
            )
            // A safe notification can race ahead of the worker's queued defer.
            // Continue on this same edge after synchronously retiring it; a
            // prepared rollback is still held by the persistence guard below.
        }
        guard !restoreInitializationBlocked,
              !recoveredLifecycleRollbackPersistenceInFlight else { return }
        let effects = recoveredDataRecompute.startDeferredForegroundRetry()
        recoveredDataRecomputeLeaseSuspendedForBackground = false
        recoveredDataRecomputeTimeoutContext = nil
        handleRecoveredDataRecomputeEffects(effects)
        if effects.isEmpty {
            finishDeferredRecoveredLifecycleRollbackCleanupIfSafe()
        }
        AtriaDebugLog(
            "ATRIADBG recovered_derived status=foreground_retry_offered reason=%@ started=%d",
            reason,
            effects.isEmpty ? 0 : 1
        )
    }

    /// Scene activation ends the shared throttle before ordinary resume work.
    /// Retire an exact BG ticket synchronously at that edge; waiting for its
    /// worker callback could strand the coordinator behind a stale generation
    /// until another lifecycle transition.
    @discardableResult
    func invalidateRecoveredDataBackgroundExecutionLeaseForForeground(
        reason: String
    ) -> Bool {
        guard let execution = activeRecoveredDataExecution,
              case .background = execution.authority,
              !execution.authority.shouldContinue() else { return false }
        deferRecoveredDataExecutionForLostAuthority(
            ticket: execution.ticket,
            authority: execution.authority,
            stage: "foreground_background_lease_end",
            reason: reason
        )
        return true
    }

    /// The automatic lane publishes only data whose inputs were already
    /// constrained to the captured current-cycle/latest-night cutoff. It never
    /// calls archive diagnostics, lifetime HistorySnapshot construction,
    /// workout rehydration, trends, training load, or behavior fan-out.
    private func runRecoveredCurrentCyclePublicationStep(
        ticket: AtriaRecoveredDataRecomputeCoordinator.Ticket
    ) {
        guard let authority = requireRecoveredDataExecutionAuthority(
            ticket: ticket,
            stage: "current_cycle_start"
        ) else { return }
        guard case .automaticCurrentCycle = ticket.scope else {
            _ = completeRecoveredDataComponent(
                ticket: ticket,
                component: .currentCycleAndLatestNight,
                succeeded: false
            )
            return
        }
        autoConfirmSleepOnForegroundIfUseful(
            reason: "bounded_recovered_\(ticket.reason)",
            force: true,
            deferDerivedPublication: true,
            evaluationLookbackDays: 2,
            maximumEvaluationSessions: 192,
            autoConfirmLimit: 1,
            settlementAuthority: .init(
                domain: ticket.executionDomain == .foreground
                    ? .recoveredForeground
                    : .recoveredExplicitBackground,
                generation: ticket.generation,
                archiveRevision: ticket.archiveRevision
            ),
            executionShouldContinue: {
                authority.cooperativeShouldContinue()
            }
        ) { [weak self] succeeded in
            guard let self else { return }
            guard self.requireRecoveredDataExecutionAuthority(
                ticket: ticket,
                stage: "current_cycle_completion"
            ) != nil else { return }
            guard succeeded else {
                _ = self.completeRecoveredDataComponent(
                    ticket: ticket,
                    component: .currentCycleAndLatestNight,
                    succeeded: false
                )
                return
            }
            // MainActor captures only COW authorities. Even a nominally compact
            // 84-night result must first search all confirmed/rollup inputs, so
            // construct it off-main under the exact ticket duty cycle.
            let rollups = self.historySnapshot.rollups
            let confirmedSleeps = self.cachedConfirmedSleeps
            let dismissedCandidates = self.dismissedSleepCandidates
            let sourceCanonicalRevision = self.canonicalSessionsRevision
            let sourceConfirmedSleepsRevision =
                self.confirmedSleepsRevision
            Self.historySnapshotProjectionQueue.async { [weak self] in
                guard authority.cooperativeShouldContinue() else { return }
                let prepared = AtriaTransientWorkThread.run(
                    name: "atria.recovered-current-sleep-history",
                    qualityOfService: .utility
                ) {
                    SleepHistorySnapshot(
                        rollups: rollups,
                        confirmedSleeps: confirmedSleeps,
                        dismissedCandidates: dismissedCandidates,
                        shouldContinue: {
                            authority.cooperativeShouldContinue()
                        }
                    )
                }
                DispatchQueue.main.async { [weak self] in
                    guard let self,
                          self.requireRecoveredDataExecutionAuthority(
                            ticket: ticket,
                            stage: "current_cycle_sleep_history_install"
                          ) != nil,
                          authority.shouldContinue() else { return }
                    guard Self.recoveredProjectionSourceRevisionsAreCurrent(
                        canonicalRevision:
                            self.canonicalSessionsRevision,
                        expectedCanonicalRevision:
                            sourceCanonicalRevision,
                        confirmedSleepsRevision:
                            self.confirmedSleepsRevision,
                        expectedConfirmedSleepsRevision:
                            sourceConfirmedSleepsRevision
                    ) else {
                        _ = self.completeRecoveredDataComponent(
                            ticket: ticket,
                            component: .currentCycleAndLatestNight,
                            succeeded: false
                        )
                        return
                    }
                    self.sleepHistorySnapshot = prepared
                    self.cachedHomeSavedAggregate = nil
                    self.cachedTodayTRIMP = nil
                    self.cachedSkinTemperatureDeviationSummary = nil
                    self.recoveryProjectionCache.invalidate()
                    _ = self.completeRecoveredDataComponent(
                        ticket: ticket,
                        component: .currentCycleAndLatestNight,
                        succeeded: true
                    )
                }
            }
        }
    }

    private func runRecoveredArchiveStatusStep(
        ticket: AtriaRecoveredDataRecomputeCoordinator.Ticket
    ) {
        guard let authority = requireRecoveredDataExecutionAuthority(
            ticket: ticket,
            stage: "archive_status_start"
        ) else { return }
        refreshHistoricalArchiveStatus(
            reason: "recovered_fence_\(ticket.reason)",
            deferDerivedPublication: true,
            executionShouldContinue: {
                authority.cooperativeShouldContinue()
            }
        ) { [weak self] succeeded in
            guard let self else { return }
            guard self.requireRecoveredDataExecutionAuthority(
                ticket: ticket,
                stage: "archive_status_completion"
            ) != nil else { return }
            guard self.completeRecoveredDataComponent(
                ticket: ticket,
                component: .archiveStatusAndCycleHeartRate,
                succeeded: succeeded
            ) else { return }
            self.runRecoveredVerifiedActivityShadowStep(ticket: ticket)
        }
    }

    /// Applies no canonical state. This bounded pass records only a durable
    /// comparison between verified typed Activity candidates and the existing
    /// raw-session detector. Missing/deferred artifacts retain the last shadow
    /// generation; store failures are diagnostic and cannot blank current UI.
    private func runRecoveredVerifiedActivityShadowStep(
        ticket: AtriaRecoveredDataRecomputeCoordinator.Ticket
    ) {
        guard let authority = requireRecoveredDataExecutionAuthority(
            ticket: ticket,
            stage: "activity_shadow_start"
        ) else { return }
        let recoveredSessions = cachedRecoveredHeartRateSessions
        let restingHeartRate = baseline.restingInt ?? 60
        let maximumHeartRate = profile.maxHR
        let timeZoneIdentifier = TimeZone.current.identifier
        let configuration = AtriaHistoricalConsumerProjectionConfiguration.production(
            restingHeartRate: restingHeartRate,
            maximumHeartRate: maximumHeartRate,
            timeZoneIdentifier: timeZoneIdentifier
        )
        let destination = HistoricalArchive.verifiedActivityConsumerShadowDirectory

        // Cold-launch guard (2026-08-05): with the projection scan serialized,
        // the +80s jetsam moved HERE — readVerifiedConsumerSources decodes at
        // whole-archive scale even for one source (fp 955→3202MB inside this
        // step on-device) and the reclaim law holds that garbage until the
        // stretch ends. Shadow parity applies no canonical state, so it has
        // no business inside the launch recompute: skip during the first 10
        // minutes and let any later cycle run it. The proper bounded-read fix
        // for the reader stays on the backlog.
        if Date().timeIntervalSince(storeCreatedAt) < 600 {
            AtriaDebugLog("ATRIADBG verified_activity_consumer_shadow status=skipped_cold_launch action=run_on_later_cycle")
            guard recoveredDataRecompute.pendingComponents(ticket: ticket)?
                .contains(.confirmedWorkouts) == true else { return }
            runRecoveredWorkoutStep(ticket: ticket)
            return
        }

        if case .background = authority {
            // This is a non-canonical comparison-only sweep with no checkpoint
            // inside its aggregate reader. Leased BG work advances the actual
            // recovered publication and skips this optional 100%-CPU shadow.
            runRecoveredWorkoutStep(ticket: ticket)
            return
        }
        Task.detached(priority: .utility) {
            [recoveredSessions, configuration, destination, authority] in
            guard authority.cooperativeShouldContinue() else { return }
            // Fresh dying thread: this sweep's verified-consumer reads churn
            // transient allocations the cooperative pool's long-lived thread
            // would otherwise retain until jetsam (2026-08-04 law: reclaim
            // happens at thread teardown).
            AtriaTransientWorkThread.run(name: "atria.shadow-step",
                                         qualityOfService: .utility) {
            guard authority.cooperativeShouldContinue() else { return }
            let store = AtriaHistoricalVerifiedActivityConsumerApplicationStore(
                directoryURL: destination
            )
            var applied = 0
            var retained = 0
            var failed = 0
            let report = HistoricalArchive.readVerifiedConsumerSources(
                configuration: configuration,
                maximumSourceCount: 1
            ) { source in
                let sourceStart = source.verificationIdentity?.source.firstTimestamp
                let sourceEnd = source.verificationIdentity?.source.lastTimestamp
                let rawCandidates: [AtriaHistoricalVerifiedActivityConsumerApplicationStore.Candidate]
                if let sourceStart, let sourceEnd {
                    rawCandidates = recoveredSessions.enumerated().compactMap {
                        index, session in
                        guard !index.isMultiple(of: 32)
                                || authority.cooperativeShouldContinue() else {
                            return nil
                        }
                        guard session.end > sourceStart, session.start < sourceEnd,
                              let detection = session.detectedActivity(
                                rest: restingHeartRate,
                                maxHR: maximumHeartRate
                              ),
                              detection.kind == .activityCandidate else { return nil }
                        return try? .init(identifier: detection.id.uuidString.lowercased(),
                                          start: detection.start,
                                          end: detection.end,
                                          origin: .rawSessionDetector)
                    }
                } else {
                    rawCandidates = []
                }

                switch AtriaHistoricalVerifiedActivityShadowPlanner.prepare(
                    source: source,
                    rawCandidates: rawCandidates
                ) {
                case .retainPrevious:
                    retained += 1
                case .apply(let input):
                    do {
                        let current = try store.loadCurrent(
                            sourceChunkID: input.verificationIdentity.source.chunkID
                        )
                        _ = try store.apply(
                            input,
                            expectedCurrentIdentitySHA256: current?.verificationIdentitySHA256
                        )
                        applied += 1
                    } catch {
                        failed += 1
                    }
                }
            }
            guard authority.cooperativeShouldContinue() else { return }
            AtriaDebugLog("ATRIADBG verified_activity_consumer_shadow status=complete committed=%d attempted=%d delivered=%d bounded=%d rejected=%d applied=%d retained=%d failed=%d app_mutations=0 raw_retained=1",
                          report.committedSourceCount,
                          report.attemptedSourceCount,
                          report.deliveredSourceCount,
                          report.wasBounded ? 1 : 0,
                          report.rejectedManifestCount,
                          applied,
                          retained,
                          failed)
            }
            await MainActor.run { [weak self] in
                guard let self else { return }
                guard self.requireRecoveredDataExecutionAuthority(
                    ticket: ticket,
                    stage: "activity_shadow_completion"
                ) != nil else { return }
                // Shadow parity is intentionally outside the publication
                // authority set. It may not extend or fail the app-facing
                // recovered-data fence; reject only a stale ticket here.
                guard self.recoveredDataRecompute.pendingComponents(ticket: ticket)?
                    .contains(.confirmedWorkouts) == true else { return }
                self.runRecoveredWorkoutStep(ticket: ticket)
            }
        }
    }

    private func runRecoveredWorkoutStep(
        ticket: AtriaRecoveredDataRecomputeCoordinator.Ticket
    ) {
        guard let authority = requireRecoveredDataExecutionAuthority(
            ticket: ticket,
            stage: "workout_start"
        ) else { return }
        // The immediately preceding projection already streamed and verified
        // the complete 14-day physiology image. Re-reading the same 553 MB raw
        // corpus here delayed the confirmed-workout callback past its finite
        // lease on the physical phone. Reuse that immutable image for workouts
        // fully contained by its proven window; older incomplete workouts stay
        // untouched and remain eligible for the ordinary deferred repair pass.
        let recoveredArchiveCoverageStart =
            Date().addingTimeInterval(-14 * 24 * 60 * 60)
        scheduleConfirmedWorkoutArchiveRehydration(
            reason: "recovered_fence_\(ticket.reason)",
            recoveredArchiveHeartRatePoints:
            cachedRecoveredArchiveHeartRatePoints,
            recoveredArchiveCoverageStart:
                recoveredArchiveCoverageStart,
            executionShouldContinue: {
                authority.cooperativeShouldContinue()
            }
        ) { [weak self] succeeded in
            guard let self else { return }
            guard self.requireRecoveredDataExecutionAuthority(
                ticket: ticket,
                stage: "workout_completion"
            ) != nil else { return }
            guard self.completeRecoveredDataComponent(
                ticket: ticket,
                component: .confirmedWorkouts,
                succeeded: succeeded
            ) else { return }
            self.runRecoveredSleepSettlementStep(ticket: ticket)
        }
    }

    private func runRecoveredSleepSettlementStep(
        ticket: AtriaRecoveredDataRecomputeCoordinator.Ticket
    ) {
        guard let authority = requireRecoveredDataExecutionAuthority(
            ticket: ticket,
            stage: "sleep_settlement_start"
        ) else { return }
        autoConfirmSleepOnForegroundIfUseful(
            reason: "recovered_fence_\(ticket.reason)",
            force: true,
            deferDerivedPublication: true,
            evaluationLookbackDays: 14,
            maximumEvaluationSessions: 4_096,
            autoConfirmLimit: 14,
            settlementAuthority: .init(
                domain: ticket.executionDomain == .foreground
                    ? .recoveredForeground
                    : .recoveredExplicitBackground,
                generation: ticket.generation,
                archiveRevision: ticket.archiveRevision
            ),
            executionShouldContinue: {
                authority.cooperativeShouldContinue()
            }
        ) { [weak self] succeeded in
            guard let self else { return }
            guard self.requireRecoveredDataExecutionAuthority(
                ticket: ticket,
                stage: "sleep_settlement_completion"
            ) != nil else { return }
            guard self.completeRecoveredDataComponent(
                ticket: ticket,
                component: .sleepSettlement,
                succeeded: succeeded
            ) else { return }
            self.runRecoveredHistoryStep(ticket: ticket)
        }
    }

    private func runRecoveredHistoryStep(
        ticket: AtriaRecoveredDataRecomputeCoordinator.Ticket
    ) {
        guard let authority = requireRecoveredDataExecutionAuthority(
            ticket: ticket,
            stage: "history_start"
        ) else { return }
        let affectedDays = Self.currentExactRecoveryAffectedDays()
        if let affectedDays {
            pendingDailyDerivedInvalidationDays.formUnion(affectedDays)
        }
        refreshHistorySnapshotCache(
            deferred: true,
            isRecoveredPublication: true,
            reuseLoadedCanonicalHistory: true,
            recoveredAffectedDays: affectedDays,
            executionShouldContinue: {
                authority.cooperativeShouldContinue()
            },
            progress: { [weak self] stage in
                guard let self,
                      self.requireRecoveredDataExecutionAuthority(
                        ticket: ticket,
                        stage: "history_\(stage)"
                      ) != nil else { return }
                self.renewRecoveredDerivedLease(
                    ticket: ticket,
                    component: .historySleepAndDailyRollups,
                    completedStage: stage
                )
            }
        ) { [weak self] succeeded in
            guard let self else { return }
            guard self.requireRecoveredDataExecutionAuthority(
                ticket: ticket,
                stage: "history_completion"
            ) != nil else { return }
            guard self.completeRecoveredDataComponent(
                ticket: ticket,
                component: .historySleepAndDailyRollups,
                succeeded: succeeded
            ) else { return }
            self.runRecoveredIndependentDerivedSteps(ticket: ticket)
        }
    }

    nonisolated static func currentExactRecoveryAffectedDays(
        calendar: Calendar = .current
    ) -> Set<Date>? {
        let root = FileManager.default.urls(
            for: .documentDirectory,
            in: .userDomainMask
        )[0].appendingPathComponent(
            "atria-historical/full-drain-authority-v1",
            isDirectory: true
        )
        guard let authority = try? AtriaHistoricalFullDrainCoverageStore(
            directoryURL: root
        ).load(),
        authority.gap.pending else { return nil }
        let start = Date(timeIntervalSince1970: authority.gap.startUnix)
        let end = Date(timeIntervalSince1970: authority.gap.endUnix)
        guard end > start else { return nil }
        var day = calendar.startOfDay(for: start)
        let finalDay = calendar.startOfDay(
            for: end.addingTimeInterval(-0.001)
        )
        var result = Set<Date>()
        while day <= finalDay {
            result.insert(day)
            guard let next = calendar.date(
                byAdding: .day,
                value: 1,
                to: day
            ), next > day else { break }
            day = next
        }
        return result.isEmpty ? nil : result
    }

    private func renewRecoveredDerivedLease(
        ticket: AtriaRecoveredDataRecomputeCoordinator.Ticket,
        component: AtriaRecoveredDataRecomputeCoordinator.Component,
        completedStage stage: String
    ) {
        guard requireRecoveredDataExecutionAuthority(
            ticket: ticket,
            stage: "derived_lease_\(stage)"
        ) != nil else { return }
        guard case let .deriving(active, pending) =
                recoveredDataRecompute.phase,
              active == ticket,
              pending.contains(component) else { return }
        let policy = AtriaRecoveredDataTimeoutPolicy.physicalSessionStore
        let used =
            recoveredDataDerivedLeaseRenewals[ticket.generation] ?? 0
        let completed =
            recoveredDataDerivedCompletedStages[ticket.generation] ?? []
        guard !stage.isEmpty,
              !completed.contains(stage),
              used < policy.maximumDerivedStageLeaseRenewals else { return }
        recoveredDataDerivedCompletedStages[
            ticket.generation,
            default: []
        ].insert(stage)
        recoveredDataDerivedLeaseRenewals[ticket.generation] = used + 1
        armRecoveredDataRecomputeTimeout(
            ticket: ticket,
            phase: "derived",
            component: component
        )
        AtriaDebugLog(
            "ATRIADBG recovered_derived status=lease_renewed phase=derived component=%@ stage=%@ renewal=%d renewal_cap=%d lease_s=%d generation=%llu archive_revision=%llu",
            component.rawValue,
            stage,
            used + 1,
            policy.maximumDerivedStageLeaseRenewals,
            policy.derivedComponentLeaseSeconds,
            ticket.generation,
            ticket.archiveRevision
        )
    }

    private func runRecoveredIndependentDerivedSteps(
        ticket: AtriaRecoveredDataRecomputeCoordinator.Ticket
    ) {
        guard let authority = requireRecoveredDataExecutionAuthority(
            ticket: ticket,
            stage: "overview_start"
        ) else { return }
        // SEQUENTIAL, not parallel (2026-08-04): these four refreshes are
        // logically independent, but launched together their transient
        // allocation bursts STACK — with ~700k recovered points installed
        // the pile-up crossed the jetsam ceiling ~48s after the history
        // snapshots finished. Chained completions bound the peak to one
        // step's burst; the per-step probe notes name any step that still
        // overruns alone. Failure of one step still lets the rest complete
        // (matching the old parallel behavior — completion rejection is
        // handled per-component by the coordinator).
        refreshOverviewTrendPointsCache(
            deferred: false,
            executionShouldContinue: {
                authority.cooperativeShouldContinue()
            }
        ) { [weak self] succeeded in
            guard let self,
                  self.requireRecoveredDataExecutionAuthority(
                    ticket: ticket,
                    stage: "overview_completion"
                  ) != nil,
                  self.completeRecoveredDataComponent(
                    ticket: ticket,
                    component: .overviewTrends,
                    succeeded: succeeded
                  ) else { return }
            guard self.requireRecoveredDataExecutionAuthority(
                ticket: ticket,
                stage: "training_start"
            ) != nil else { return }
            self.refreshTrainingLoadSummaryCache(
                deferred: false,
                executionShouldContinue: {
                    authority.cooperativeShouldContinue()
                }
            ) {
                [weak self] succeeded in
                guard let self,
                      self.requireRecoveredDataExecutionAuthority(
                        ticket: ticket,
                        stage: "training_completion"
                      ) != nil,
                      self.completeRecoveredDataComponent(
                        ticket: ticket,
                        component: .trainingLoad,
                        succeeded: succeeded
                      ) else { return }
                guard self.requireRecoveredDataExecutionAuthority(
                    ticket: ticket,
                    stage: "zones_start"
                ) != nil else { return }
                self.refreshTodayHRZoneMinutesCache(
                    deferred: false,
                    executionShouldContinue: {
                        authority.cooperativeShouldContinue()
                    }
                ) {
                    [weak self] succeeded in
                    guard let self,
                          self.requireRecoveredDataExecutionAuthority(
                            ticket: ticket,
                            stage: "zones_completion"
                          ) != nil,
                          self.completeRecoveredDataComponent(
                            ticket: ticket,
                            component: .todayHeartRateZones,
                            succeeded: succeeded
                          ) else { return }
                    guard self.requireRecoveredDataExecutionAuthority(
                        ticket: ticket,
                        stage: "behavior_start"
                    ) != nil else { return }
                    self.recomputeBehaviorInsights(
                        executionShouldContinue: {
                            authority.cooperativeShouldContinue()
                        }
                    ) { [weak self] succeeded in
                        guard let self,
                              self.requireRecoveredDataExecutionAuthority(
                                ticket: ticket,
                                stage: "behavior_completion"
                              ) != nil else { return }
                        _ = self.completeRecoveredDataComponent(
                            ticket: ticket,
                            component: .behaviorInsights,
                            succeeded: succeeded
                        )
                    }
                }
            }
        }
    }

    nonisolated static func recoveredComponentRequiresCheckpointPersistence(
        succeeded: Bool,
        pendingComponentCount: Int,
        checkpointPersistenceCompleted: Bool
    ) -> Bool {
        succeeded
            && pendingComponentCount == 1
            && !checkpointPersistenceCompleted
    }

    @discardableResult
    private func completeRecoveredDataComponent(
        ticket: AtriaRecoveredDataRecomputeCoordinator.Ticket,
        component: AtriaRecoveredDataRecomputeCoordinator.Component,
        succeeded: Bool,
        checkpointPersistenceCompleted: Bool = false
    ) -> Bool {
        guard let authority = requireRecoveredDataExecutionAuthority(
            ticket: ticket,
            stage: "component_\(component.rawValue)_completion"
        ) else { return false }
        guard let pending = recoveredDataRecompute.pendingComponents(
                ticket: ticket
              ), pending.contains(component) else {
            return false
        }
        if Self.recoveredComponentRequiresCheckpointPersistence(
            succeeded: succeeded,
            pendingComponentCount: pending.count,
            checkpointPersistenceCompleted: checkpointPersistenceCompleted
        ) {
            let inserted = recoveredDataPublicationCheckpointInFlightGenerations
                .insert(ticket.generation).inserted
            guard inserted else { return true }
            armRecoveredDataRecomputeTimeout(
                ticket: ticket,
                phase: "derived_checkpoint",
                component: component
            )
            let checkpointDestination = recoveredCurrentCheckpointURL
            persistRecoveredCurrentCheckpoint(
                ticket: ticket,
                executionShouldContinue: {
                    authority.cooperativeShouldContinue()
                }
            ) { [weak self] outcome in
                guard let self else {
                    if case .persisted = outcome {
                        Self.historySnapshotProjectionQueue.async {
                            Self.removeRecoveredCurrentCheckpointIfOwned(
                                generation: ticket.generation,
                                at: checkpointDestination
                            )
                        }
                    }
                    return
                }
                self.recoveredDataPublicationCheckpointInFlightGenerations
                    .remove(ticket.generation)
                guard self.requireRecoveredDataExecutionAuthority(
                    ticket: ticket,
                    stage: "publication_checkpoint_completion"
                ) != nil else {
                    if case .persisted = outcome {
                        Self.historySnapshotProjectionQueue.async {
                            Self.removeRecoveredCurrentCheckpointIfOwned(
                                generation: ticket.generation,
                                at: checkpointDestination
                            )
                        }
                    }
                    return
                }
                let persistenceSucceeded: Bool
                switch outcome {
                case .notRequired:
                    self.recoveredDataPreparedCheckpointIdentityByGeneration
                        .removeValue(forKey: ticket.generation)
                    persistenceSucceeded = true
                case .persisted(let identity):
                    self.recoveredDataPreparedCheckpointIdentityByGeneration[
                        ticket.generation
                    ] = identity
                    persistenceSucceeded = true
                case .failed:
                    self.recoveredDataPreparedCheckpointIdentityByGeneration
                        .removeValue(forKey: ticket.generation)
                    persistenceSucceeded = false
                }
                _ = self.completeRecoveredDataComponent(
                    ticket: ticket,
                    component: component,
                    succeeded: persistenceSucceeded,
                    checkpointPersistenceCompleted: true
                )
            }
            return true
        }
        let effects = recoveredDataRecompute.componentCompleted(
            ticket: ticket,
            component: component,
            failureReason: succeeded ? nil : "revision_superseded_or_persistence_failed"
        )
        handleRecoveredDataRecomputeEffects(effects)
        guard succeeded else { return false }
        if case let .deriving(active, pending) = recoveredDataRecompute.phase,
           active == ticket {
            let nextComponent: AtriaRecoveredDataRecomputeCoordinator.Component?
            switch component {
            case .archiveStatusAndCycleHeartRate:
                nextComponent = .confirmedWorkouts
            case .confirmedWorkouts:
                nextComponent = .sleepSettlement
            case .sleepSettlement:
                nextComponent = .historySleepAndDailyRollups
            case .historySleepAndDailyRollups,
                 .overviewTrends,
                 .trainingLoad,
                 .todayHeartRateZones,
                 .behaviorInsights,
                 .currentCycleAndLatestNight:
                nextComponent = nil
            }
            AtriaDebugLog("ATRIADBG recovered_derived status=progress generation=%llu archive_revision=%llu completed=%@ remaining=%d next=%@ lease_reset_s=%d",
                          ticket.generation,
                          ticket.archiveRevision,
                          component.rawValue,
                          pending.count,
                          nextComponent?.rawValue ?? "parallel_or_publish",
                          AtriaRecoveredDataTimeoutPolicy.physicalSessionStore
                              .derivedComponentLeaseSeconds)
            armRecoveredDataRecomputeTimeout(ticket: ticket,
                                             phase: "derived",
                                             component: nextComponent)
            return true
        }
        return false
    }

    /// Re-evaluates only confirmed workouts whose saved HR coverage is incomplete.
    /// Archive parsing and metric derivation stay off the main actor; the final
    /// compare-and-swap is one atomic confirmed-workout persistence revision.
    nonisolated static func
        shouldDeferAutomaticWorkoutRehydrationUntilRecoveredProjection(
            reason: String,
            isRequiredRecoveredPublication: Bool,
            recoveredProjectionWasSupplied: Bool,
            cachedRecoveredProjectionAvailable: Bool
        ) -> Bool {
        !isRequiredRecoveredPublication
            && reason.hasPrefix("archive_did_update")
            && !recoveredProjectionWasSupplied
            && !cachedRecoveredProjectionAvailable
    }

    private func scheduleConfirmedWorkoutArchiveRehydration(
        reason: String,
        recoveredArchiveHeartRatePoints:
            [HistoricalArchive.HeartRatePoint]? = nil,
        recoveredArchiveCoverageStart: Date? = nil,
        executionShouldContinue:
            @escaping @Sendable () -> Bool = { true },
        completion: ((Bool) -> Void)? = nil
    ) {
        guard executionShouldContinue() else {
            completion?(false)
            return
        }
        let isRequiredRecoveredPublication = completion != nil
        if Self
            .shouldDeferAutomaticWorkoutRehydrationUntilRecoveredProjection(
                reason: reason,
                isRequiredRecoveredPublication:
                    isRequiredRecoveredPublication,
                recoveredProjectionWasSupplied:
                    recoveredArchiveHeartRatePoints != nil,
                cachedRecoveredProjectionAvailable:
                    !cachedRecoveredArchiveHeartRatePoints.isEmpty
            ) {
            workoutRehydrationDeferredUntilForeground = true
            AtriaDebugLog(
                "ATRIADBG confirmed_workout_rehydration status=deferred reason=%@ detail=automatic_archive_update_awaiting_bounded_projection action=never_raw_fallback",
                reason
            )
            return
        }
        if !isRequiredRecoveredPublication,
           nonExactArchiveConsumerShouldDefer {
            workoutRehydrationDeferredUntilForeground = true
            AtriaDebugLog(
                "ATRIADBG confirmed_workout_rehydration status=deferred reason=%@ detail=exact_recovery_archive_priority action=coalesce_until_terminal_projection",
                reason
            )
            return
        }
        if completion == nil,
           !Self.shouldStartAutomaticArchiveProjection(
                applicationIsActive:
                    UIApplication.shared.applicationState == .active
           ) {
            workoutRehydrationDeferredUntilForeground = true
            AtriaDebugLog(
                "ATRIADBG confirmed_workout_rehydration status=deferred reason=%@ app_active=0 action=wait_for_foreground",
                reason
            )
            return
        }
        // Projection-first rule (2026-08-05, final raw-scan closure): when no
        // projection was handed in, substitute the warm cache; when the cache
        // is cold BECAUSE a recompute is still building it, stand down — the
        // recompute's confirmedWorkouts component re-runs this pass with real
        // points, and an early raw 1.5M-point window scan racing that
        // recompute is exactly the stack that kept crossing the ceiling.
        var recoveredArchiveHeartRatePoints = recoveredArchiveHeartRatePoints
        var recoveredArchiveCoverageStart = recoveredArchiveCoverageStart
        if recoveredArchiveHeartRatePoints == nil {
            if !cachedRecoveredArchiveHeartRatePoints.isEmpty {
                recoveredArchiveHeartRatePoints = cachedRecoveredArchiveHeartRatePoints
                recoveredArchiveCoverageStart = recoveredArchiveCoverageStart
                    ?? Date().addingTimeInterval(-14 * 24 * 60 * 60)
            } else if completion == nil {
                switch recoveredDataRecompute.phase {
                case .projecting, .deriving:
                    workoutRehydrationDeferredUntilForeground = true
                    AtriaDebugLog(
                        "ATRIADBG confirmed_workout_rehydration status=deferred reason=%@ detail=awaiting_recovered_projection",
                        reason
                    )
                    return
                case .idle, .failed:
                    break
                }
            }
        }
        if let completion {
            confirmedWorkoutRehydrationCompletions.append(completion)
        }
        // HistoricalArchive posts once per appended frame. A debounce that
        // cancels on every post starves forever while the strap is streaming;
        // keep one bounded scan in flight and remember one trailing refresh.
        if pendingConfirmedWorkoutRehydrationWorkItem != nil {
            confirmedWorkoutRehydrationRescheduleRequested = true
            return
        }
        confirmedWorkoutRehydrationGeneration &+= 1
        let generation = confirmedWorkoutRehydrationGeneration
        let candidates = cachedConfirmedWorkouts.filter(
            Self.confirmedWorkoutNeedsArchiveRehydration
        )
        let originals: [UserConfirmedWorkout]
        if recoveredArchiveHeartRatePoints != nil,
           let recoveredArchiveCoverageStart {
            originals = candidates.filter {
                Self.confirmedWorkoutFallsWithinRecoveredArchive(
                    workoutStart: $0.start,
                    coverageStart: recoveredArchiveCoverageStart
                )
            }
        } else {
            originals = candidates
        }
        guard !originals.isEmpty else {
            finishConfirmedWorkoutRehydrationCompletions(succeeded: true)
            return
        }

        let sourceSessions = canonicalSessions(includeActiveJournal: true)
        let currentRest = baseline.restingInt ?? 60
        let currentMaxHR = profile.maxHR
        let currentProfile = profile
        let workItem = DispatchWorkItem { [weak self, originals, sourceSessions,
                                           currentRest, currentMaxHR, currentProfile,
                                           reason, recoveredArchiveHeartRatePoints,
                                           executionShouldContinue] in
            guard executionShouldContinue() else { return }
            let heartRateOriginals = originals.filter(
                Self.confirmedWorkoutNeedsHeartRateArchiveRehydration
            )
            let fingerprintBefore =
                HistoricalArchive.consumerSourceFingerprint()
            let attemptSignature =
                Self.confirmedWorkoutHRRehydrationAttemptSignature(
                    workouts: heartRateOriginals,
                    sessions: sourceSessions,
                    rest: currentRest,
                    maxHR: currentMaxHR,
                    profile: currentProfile,
                    sourceFingerprint: fingerprintBefore
                )
            if let attemptSignature,
               UserDefaults.standard.string(
                    forKey: Self.workoutHRRehydrationAttemptKey
               ) == attemptSignature {
                Task { @MainActor [weak self, reason] in
                    guard let self,
                          executionShouldContinue(),
                          generation
                            == self.confirmedWorkoutRehydrationGeneration else {
                        return
                    }
                    self.pendingConfirmedWorkoutRehydrationWorkItem = nil
                    let needsTrailingRefresh =
                        self.confirmedWorkoutRehydrationRescheduleRequested
                    self.confirmedWorkoutRehydrationRescheduleRequested = false
                    AtriaDebugLog(
                        "ATRIADBG confirmed_workout_rehydration status=unchanged_attempt_skipped reason=%@ generation=%d",
                        reason,
                        generation
                    )
                    if needsTrailingRefresh {
                        // Reuse the recovered projection (2026-08-05): a
                        // trailing refresh without it fell into the raw
                        // 1.5M-point archive window scan — the last
                        // stress-cycle killer (40 un-noted seconds after
                        // the confirmedWorkouts component note).
                        self.scheduleConfirmedWorkoutArchiveRehydration(
                            reason: "archive_trailing_refresh",
                            recoveredArchiveHeartRatePoints:
                                self.cachedRecoveredArchiveHeartRatePoints,
                            recoveredArchiveCoverageStart:
                                Date().addingTimeInterval(-14 * 24 * 60 * 60),
                            executionShouldContinue:
                                executionShouldContinue
                        )
                    } else {
                        self.finishConfirmedWorkoutRehydrationCompletions(
                            succeeded: true
                        )
                    }
                }
                return
            }
            let archiveHeartRateWindow: HistoricalArchive.HeartRateWindowRead?
            guard executionShouldContinue() else { return }
            if let union = Self.confirmedWorkoutArchiveUnionWindow(
                heartRateOriginals
            ) {
                if let recoveredArchiveHeartRatePoints {
                    archiveHeartRateWindow = .init(
                        points: recoveredArchiveHeartRatePoints.filter {
                            $0.t >= union.start && $0.t <= union.end
                        },
                        scannedFileCount: 0,
                        scannedByteCount: 0
                    )
                    AtriaDebugLog(
                        "ATRIADBG confirmed_workout_rehydration status=reusing_recovered_projection reason=%@ generation=%d points=%d action=avoid_duplicate_raw_archive_scan",
                        reason,
                        generation,
                        archiveHeartRateWindow?.points.count ?? 0
                    )
                } else {
                    // Scan immutable history once for the complete set of
                    // eligible workouts. The global ceiling remains
                    // fail-closed: overflow withholds every HR replacement
                    // instead of publishing a partial prefix.
                    archiveHeartRateWindow = AtriaTransientWorkThread.run(
                        name: "atria.rehydration-window-scan",
                        qualityOfService: .utility
                    ) {
                        HistoricalArchive.metricHeartRatePoints(
                            start: union.start,
                            end: union.end.addingTimeInterval(0.001),
                            maximumPoints: 1_500_000
                        )
                    }
                }
            } else {
                archiveHeartRateWindow = nil
            }
            let replacements = originals.compactMap { old -> (UserConfirmedWorkout, UserConfirmedWorkout)? in
                guard executionShouldContinue() else { return nil }
                var replacement = old
                let existingPoints = sourceSessions.flatMap { session -> [HistoricalArchive.HeartRatePoint] in
                    guard session.end >= old.start, session.start <= old.end else { return [] }
                    return session.points.compactMap { point in
                        let time = session.start.addingTimeInterval(max(0, point.t))
                        guard time >= old.start, time <= old.end, (35...240).contains(point.bpm) else { return nil }
                        return HistoricalArchive.HeartRatePoint(t: time, bpm: point.bpm)
                    }
                }
                if Self.confirmedWorkoutNeedsHeartRateArchiveRehydration(old),
                   let archiveHeartRateWindow {
                    // Per-workout dying thread (2026-08-05): each rehydration
                    // is a bounded archive read whose garbage must die before
                    // the next workout's read begins.
                    let rehydrated = AtriaTransientWorkThread.run(
                        name: "atria.workout-rehydration-one",
                        qualityOfService: .utility
                    ) { () -> UserConfirmedWorkout? in
                        guard executionShouldContinue() else { return nil }
                        return SessionStore.rehydratedConfirmedWorkout(
                            old,
                            existingPoints: existingPoints,
                            archivePoints: archiveHeartRateWindow.points.filter {
                                $0.t >= old.start && $0.t <= old.end
                            },
                            rest: currentRest,
                            maxHR: currentMaxHR,
                            profile: currentProfile
                        )
                    }
                    if let rehydrated {
                        replacement = rehydrated
                    }
                }
                return replacement == old ? nil : (old, replacement)
            }
            let fingerprintAfter =
                HistoricalArchive.consumerSourceFingerprint()
            guard executionShouldContinue() else { return }
            let completedNegativeSignature =
                archiveHeartRateWindow != nil
                    && replacements.isEmpty
                    && fingerprintBefore == fingerprintAfter
                ? attemptSignature
                : nil

            Task { @MainActor [weak self, replacements, reason,
                               completedNegativeSignature] in
                guard let self else { return }
                guard executionShouldContinue(),
                      generation == self.confirmedWorkoutRehydrationGeneration else {
                    self.finishConfirmedWorkoutRehydrationCompletions(succeeded: false)
                    return
                }
                self.pendingConfirmedWorkoutRehydrationWorkItem = nil
                let needsTrailingRefresh = self.confirmedWorkoutRehydrationRescheduleRequested
                self.confirmedWorkoutRehydrationRescheduleRequested = false
                var updated = self.cachedConfirmedWorkouts
                var applied = 0
                var persistenceSucceeded = true
                var appliedReplacements: [(original: UserConfirmedWorkout, replacement: UserConfirmedWorkout)] = []
                for (original, replacement) in replacements {
                    guard let index = updated.firstIndex(where: { $0.id == original.id }),
                          updated[index] == original,
                          Self.recoveredWorkoutEvidenceIsStronger(replacement, than: original) else { continue }
                    updated[index] = replacement
                    applied += 1
                    appliedReplacements.append((original: original, replacement: replacement))
                }
                if applied > 0 {
                    persistenceSucceeded = await self.saveConfirmedWorkouts(
                        updated,
                        deferDerivedPublication: !self.confirmedWorkoutRehydrationCompletions.isEmpty
                    )
                    guard executionShouldContinue(),
                          generation
                            == self.confirmedWorkoutRehydrationGeneration else {
                        self.finishConfirmedWorkoutRehydrationCompletions(
                            succeeded: false
                        )
                        return
                    }
                    if persistenceSucceeded {
                        if let transactionTicket = self.recoveredDataMutationTransaction.activeTicket {
                            _ = self.recoveredDataMutationTransaction.registerCommit(
                                ticket: transactionTicket
                            ) {
                                Self.resolveHistoricalRecoveryRequestIfSatisfied(
                                    by: appliedReplacements
                                )
                            }
                        } else {
                            Self.resolveHistoricalRecoveryRequestIfSatisfied(by: appliedReplacements)
                        }
                        AtriaDebugLog("ATRIADBG confirmed_workout_rehydration status=applied reason=%@ workouts=%d generation=%d",
                                      reason, applied, generation)
                    }
                }
                if applied == 0, let completedNegativeSignature {
                    UserDefaults.standard.set(
                        completedNegativeSignature,
                        forKey: Self.workoutHRRehydrationAttemptKey
                    )
                    AtriaDebugLog(
                        "ATRIADBG confirmed_workout_rehydration status=complete_no_stronger_evidence_cached reason=%@ generation=%d",
                        reason,
                        generation
                    )
                }
                if needsTrailingRefresh {
                    self.scheduleConfirmedWorkoutArchiveRehydration(
                        reason: "archive_trailing_refresh",
                        recoveredArchiveHeartRatePoints:
                            self.cachedRecoveredArchiveHeartRatePoints,
                        recoveredArchiveCoverageStart:
                            Date().addingTimeInterval(-14 * 24 * 60 * 60),
                        executionShouldContinue:
                            executionShouldContinue
                    )
                } else {
                    self.finishConfirmedWorkoutRehydrationCompletions(
                        succeeded: persistenceSucceeded
                    )
                }
            }
        }
        pendingConfirmedWorkoutRehydrationWorkItem = workItem
        // Fresh dying thread (2026-08-05, the LAST balloon lane): both
        // stress-cycle deaths landed inside this rehydration pass — bounded
        // per-workout archive reads whose transient garbage summed on a
        // long-lived global-pool thread (reclaim happens only at thread
        // teardown on this beta).
        DispatchQueue.global(qos: .utility).asyncAfter(deadline: .now() + 0.75) {
            AtriaTransientWorkThread.run(name: "atria.workout-rehydration",
                                         qualityOfService: .utility) {
                workItem.perform()
            }
        }
    }

    /// Publishes qualified WHOOP/R10 steps independently of the broader
    /// workout HR repair. The combined pass can legitimately spend minutes
    /// repairing lifetime HR before it reaches a fully recovered current walk.
    private func scheduleConfirmedWorkoutStepEvidencePublication(
        reason: String
    ) {
        guard AtriaWhoop4GravityCadenceStepModel
                .releaseDailyAuthorityQualified else {
            return
        }
        guard pendingWorkoutStepEvidenceWorkItem == nil else {
            workoutStepEvidenceRescheduleRequested = true
            return
        }
        let originals = cachedConfirmedWorkouts.filter {
            ($0.workoutSteps == nil
                || $0.workoutStepsAreEstimated == true)
                && AtriaWorkoutActivityType.resolved(
                    activityType: $0.activityType,
                    subtype: $0.activitySubtype,
                    label: $0.label
                ) == .walking
        }.sorted { $0.end > $1.end }
        guard !originals.isEmpty,
              let strapIdentifier = UserDefaults.standard.string(
                forKey: AtriaBLEManager.OfflineSyncDefaults
                    .verifiedHistoryPeripheralID
              ) else { return }
        workoutStepEvidenceGeneration &+= 1
        let generation = workoutStepEvidenceGeneration
        let workItem = DispatchWorkItem { [weak self, originals,
                                           strapIdentifier, reason] in
            let cachedNegatives =
                Self.readWorkoutStepNegativeAttempts()
            var eligible: (
                workout: UserConfirmedWorkout,
                fingerprint: String?
            )?
            for workout in originals {
                let compactFingerprint =
                    AtriaWhoop4MotionTickCompactStore.shared
                        .sourceFingerprint(
                            start: workout.start,
                            end: workout.end,
                            strapIdentifier: strapIdentifier
                        )
                        .map { "compact:\($0)" }
                let key = Self.workoutStepNegativeAttemptKey(
                    workout: workout,
                    strapIdentifier: strapIdentifier
                )
                guard Self.shouldScanWorkoutStepEvidence(
                    cachedFingerprint: cachedNegatives[key],
                    currentFingerprint: compactFingerprint
                ) else { continue }
                // This pass scans exactly ONE workout, so a candidate with no
                // stored rows burns the whole pass and the real walk behind it
                // is never reached. Device 2026-08-25:
                // `walk_counter_fallback status=unreached reason=window_guard
                // rows=0 window_s=55` — a 55-second walking workout with no
                // compact rows was starving the 21-minute walk that did have
                // 1,308 of them. This probe is stat-only (one per day bucket),
                // so skipping is far cheaper than the decode it avoids.
                guard AtriaWhoop4MotionTickCompactStore.shared.hasStoredRows(
                    start: workout.start,
                    end: workout.end,
                    strapIdentifier: strapIdentifier
                ) else { continue }
                eligible = (workout, compactFingerprint)
                break
            }

            var attempted = 0
            var cacheRecorded = false
            var replacements:
                [(UserConfirmedWorkout, UserConfirmedWorkout)] = []
            if let eligible {
                let old = eligible.workout
                attempted = 1
                let read = AtriaWhoop4MotionTickCompactStore.shared
                    .motionTickWindowRead(
                        start: old.start,
                        end: old.end,
                        strapIdentifier: strapIdentifier,
                        // `originals` is filtered to
                        // `AtriaWorkoutActivityType.resolved(...) == .walking`
                        // above, so this window is a walk the user labelled.
                        // That label is what licenses the counter fallback.
                        allowCounterFallbackForConfirmedWalk: true
                    )
                switch read {
                case .qualified(let tickWindow):
                    let replacement =
                    SessionStore.workoutByMergingUserEditsAndStepEvidence(
                        old,
                        activityLabel: nil,
                        activityType: nil,
                        activitySubtype: nil,
                        reviewSource: nil,
                        reviewCandidateID: nil,
                        activityCalibrationEvidence: nil,
                        workoutSteps: tickWindow.steps,
                        workoutStepsAreEstimated: true,
                        workoutStepsCapturedAt: tickWindow.endCapturedAt
                    )
                    replacements = [(old, replacement)]
                case .completeNoQualifiedEvidence, .incomplete:
                    let fingerprintAfter =
                        AtriaWhoop4MotionTickCompactStore.shared
                            .sourceFingerprint(
                                start: old.start,
                                end: old.end,
                                strapIdentifier: strapIdentifier
                            )
                            .map { "compact:\($0)" }
                    // This is only an attempt lease, never negative evidence.
                    // A compact append changes the shard-size fingerprint and
                    // immediately makes the workout eligible again.
                    if eligible.fingerprint == fingerprintAfter,
                       let fingerprintAfter {
                        Self.recordWorkoutStepNegativeAttempt(
                            key: Self.workoutStepNegativeAttemptKey(
                                workout: old,
                                strapIdentifier: strapIdentifier
                            ),
                            fingerprint: fingerprintAfter
                        )
                        cacheRecorded = true
                    }
                }
            }
            Task { @MainActor [weak self, replacements, reason,
                               attempted, cacheRecorded] in
                guard let self,
                      generation == self.workoutStepEvidenceGeneration else {
                    return
                }
                self.pendingWorkoutStepEvidenceWorkItem = nil
                let needsTrailingRefresh =
                    self.workoutStepEvidenceRescheduleRequested
                self.workoutStepEvidenceRescheduleRequested = false
                var updated = self.cachedConfirmedWorkouts
                var applied = 0
                for (original, replacement) in replacements {
                    guard let index = updated.firstIndex(
                        where: { $0.id == original.id }
                    ) else {
                        AtriaDebugLog(
                            "ATRIADBG workout_step_apply status=rejected reason=id_not_found id=%@",
                            original.id
                        )
                        continue
                    }
                    guard updated[index] == original else {
                        AtriaDebugLog(
                            "ATRIADBG workout_step_apply status=rejected reason=workout_changed_since_scan id=%@",
                            original.id
                        )
                        continue
                    }
                    guard Self.recoveredWorkoutEvidenceIsStronger(
                        replacement,
                        than: original
                    ) else {
                        AtriaDebugLog(
                            "ATRIADBG workout_step_apply status=rejected reason=not_stronger id=%@ old_steps=%d new_steps=%d old_samples=%d new_samples=%d",
                            original.id,
                            original.workoutSteps ?? -1,
                            replacement.workoutSteps ?? -1,
                            original.samples,
                            replacement.samples
                        )
                        continue
                    }
                    updated[index] = replacement
                    applied += 1
                }
                guard applied > 0 else {
                    AtriaDebugLog(
                        "ATRIADBG confirmed_workout_steps status=%@ reason=%@ attempted=%d cached_compact_attempt=%d action=wait_for_compact_checkpoint_or_safe_bounded_migration",
                        attempted == 0
                            ? "unchanged_compact_skipped"
                            : "no_qualified_window",
                        reason,
                        attempted,
                        cacheRecorded ? 1 : 0
                    )
                    if needsTrailingRefresh {
                        self.scheduleConfirmedWorkoutStepEvidencePublication(
                            reason: "compact_trailing_refresh"
                        )
                    }
                    return
                }
                let saved = await self.saveConfirmedWorkouts(updated)
                AtriaDebugLog(
                    "ATRIADBG confirmed_workout_steps status=%@ reason=%@ applied=%d",
                    saved ? "published" : "store_failed",
                    reason,
                    applied
                )
                if needsTrailingRefresh {
                    self.scheduleConfirmedWorkoutStepEvidencePublication(
                        reason: "compact_trailing_refresh"
                    )
                }
            }
        }
        pendingWorkoutStepEvidenceWorkItem = workItem
        Self.workoutStepEvidenceQueue.async(execute: workItem)
    }

    nonisolated static func workoutStepNegativeAttemptKey(
        workout: UserConfirmedWorkout,
        strapIdentifier: String
    ) -> String {
        workoutStepNegativeAttemptKey(
            workoutID: workout.id,
            start: workout.start,
            end: workout.end,
            strapIdentifier: strapIdentifier
        )
    }

    nonisolated static func workoutStepNegativeAttemptKey(
        workoutID: String,
        start: Date,
        end: Date,
        strapIdentifier: String
    ) -> String {
        [
            workoutID,
            String(Int64(
                (start.timeIntervalSince1970 * 1_000).rounded()
            )),
            String(Int64(
                (end.timeIntervalSince1970 * 1_000).rounded()
            )),
            strapIdentifier.uppercased(),
            AtriaWhoop4GravityCadenceStepModel.algorithmVersion,
            workoutStepScoringRevision,
        ].joined(separator: "|")
    }

    /// Scoring-CONFIGURATION revision, deliberately separate from
    /// `AtriaWhoop4GravityCadenceStepModel.algorithmVersion`.
    ///
    /// That version is a release AUTHORIZATION — its own comment says v17 "is
    /// authorized only after the provenance-bound physical corpus passes all
    /// twelve counted walks and four planted-feet controls" — so bumping it to
    /// flush a cache would assert a re-validation that did not happen.
    ///
    /// This key exists for changes that alter what a scan can CONCLUDE without
    /// touching the authorized model. r2 adds the confirmed-walk counter
    /// fallback: workouts that cached a negative under r1 were skipped forever
    /// even though the same rows now resolve, because the cache keys on the
    /// data fingerprint and the fingerprint had not changed.
    nonisolated static let workoutStepScoringRevision =
        "workout-step-scoring-r2-confirmed-walk-counter-fallback"

    nonisolated static func shouldScanWorkoutStepEvidence(
        cachedFingerprint: String?,
        currentFingerprint: String?
    ) -> Bool {
        guard let currentFingerprint else { return true }
        return cachedFingerprint != currentFingerprint
    }

    nonisolated static func shouldCacheWorkoutStepNegative(
        read: HistoricalArchive.MotionTickWindowRead,
        fingerprintBefore: HistoricalArchive.ConsumerSourceFingerprint,
        fingerprintAfter: HistoricalArchive.ConsumerSourceFingerprint
    ) -> Bool {
        read == .completeNoQualifiedEvidence
            && fingerprintBefore == fingerprintAfter
    }

    nonisolated private static func readWorkoutStepNegativeAttempts(
        defaults: UserDefaults = .standard
    ) -> [String: String] {
        guard let data = defaults.data(
            forKey: workoutStepNegativeAttemptsKey
        ) else { return [:] }
        return (try? JSONDecoder().decode(
            [String: String].self,
            from: data
        )) ?? [:]
    }

    nonisolated private static func recordWorkoutStepNegativeAttempt(
        key: String,
        fingerprint: String,
        defaults: UserDefaults = .standard
    ) {
        var values = readWorkoutStepNegativeAttempts(defaults: defaults)
        values[key] = fingerprint
        if values.count > maximumWorkoutStepNegativeAttempts {
            let retainedOtherKeys = values.keys
                .filter { $0 != key }
                .sorted()
                .suffix(maximumWorkoutStepNegativeAttempts - 1)
            values = Dictionary(
                uniqueKeysWithValues:
                    retainedOtherKeys.compactMap { candidate in
                        values[candidate].map { (candidate, $0) }
                    } + [(key, fingerprint)]
            )
        }
        guard let data = try? JSONEncoder().encode(values) else { return }
        defaults.set(data, forKey: workoutStepNegativeAttemptsKey)
    }

    func resumeDeferredForegroundArchiveWork(reason: String) {
        guard Self.shouldStartAutomaticArchiveProjection(
            applicationIsActive:
                UIApplication.shared.applicationState == .active
        ) else { return }
        if workoutRehydrationDeferredUntilForeground {
            workoutRehydrationDeferredUntilForeground = false
            // Reuse the recovered projection here too (2026-08-05): this
            // foreground replay was the third raw-scan entry point — it fired
            // at +29s of a cold launch and its 1.5M-point window scan stacked
            // with the recompute to cross the ceiling at +52s.
            scheduleConfirmedWorkoutArchiveRehydration(
                reason: "foreground_\(reason)",
                recoveredArchiveHeartRatePoints:
                    cachedRecoveredArchiveHeartRatePoints,
                recoveredArchiveCoverageStart:
                    Date().addingTimeInterval(-14 * 24 * 60 * 60)
            )
        }
        if currentCycleStepReceiptDeferredUntilForeground {
            refreshCurrentCycleStrapStepReceipt(
                reason: "foreground_\(reason)"
            )
        }
        // 2026-07-31: Task sleeps do not run while suspended; if the no-sleep
        // boundary passed in the background, roll the cycle now, otherwise
        // re-arm against the current confirmed-sleep state.
        if let rolloverBoundary = scheduledPhysiologicalCycleRolloverBoundary,
           rolloverBoundary <= Date() {
            handlePhysiologicalCycleRollover(reason: "foreground_\(reason)")
        } else {
            schedulePhysiologicalCycleRolloverCheck(
                reason: "foreground_\(reason)"
            )
        }
        resumeDeferredRecoveredDataRecomputation(
            reason: "foreground_\(reason)"
        )
        // #1 auto-upgrade: once foreground archive work has replayed newly-drained
        // history, recompute HR/strain for any workout saved metadata-only during a
        // strap drop so it stops showing without readings.
        upgradeMetadataOnlyWorkoutsFromHistoryInBackground()
    }

    private func finishConfirmedWorkoutRehydrationCompletions(succeeded: Bool) {
        let completions = confirmedWorkoutRehydrationCompletions
        confirmedWorkoutRehydrationCompletions.removeAll(keepingCapacity: true)
        completions.forEach { $0(succeeded) }
    }

    nonisolated static func makeOverviewTrendPoints(sessions: [SavedSession],
                                                    rest: Int,
                                                    maxHR: Int,
                                                    confirmedSleeps: [UserConfirmedSleep] = [],
                                                    now: Date = Date(),
                                                    calendar: Calendar = .current,
                                                    confirmedWorkouts: [UserConfirmedWorkout] = []) -> [AtriaTrendPoint] {
        makeOverviewTrendPointsCancellable(
            sessions: sessions,
            rest: rest,
            maxHR: maxHR,
            confirmedSleeps: confirmedSleeps,
            confirmedWorkouts: confirmedWorkouts,
            now: now,
            calendar: calendar,
            shouldContinue: { true }
        ) ?? []
    }

    nonisolated static func makeOverviewTrendPointsCancellable(
        sessions: [SavedSession],
        rest: Int,
        maxHR: Int,
        confirmedSleeps: [UserConfirmedSleep] = [],
        confirmedWorkouts: [UserConfirmedWorkout] = [],
        now: Date = Date(),
        calendar: Calendar = .current,
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> [AtriaTrendPoint]? {
        guard shouldContinue() else { return nil }
        let cutoff = now.addingTimeInterval(-92 * 86_400)
        var meaningful: [SavedSession] = []
        for (index, session) in sessions.enumerated() {
            if index.isMultiple(of: 64), !shouldContinue() { return nil }
            if session.points.count >= 8, session.start >= cutoff {
                meaningful.append(session)
            }
        }
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &meaningful,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: {
            if $0.start != $1.start { return $0.start < $1.start }
            return $0.id.uuidString < $1.id.uuidString
            }
        ) else { return nil }
        let recent = Array(meaningful.suffix(200))
        var rows: [TrendSessionMetricRow] = []
        rows.reserveCapacity(recent.count)
        for session in recent {
            guard shouldContinue() else { return nil }
            guard let sessionRows = trendSessionRowsCancellable(
                sessions: [session],
                rest: rest,
                maxHR: maxHR,
                calendar: calendar,
                shouldContinue: shouldContinue
            ) else { return nil }
            rows.append(contentsOf: sessionRows)
        }
        let rowsByDay = Dictionary(grouping: rows, by: \.day)
        var dailyLoadByDay: [Date: (trimp: Double, sourceID: UUID)] = [:]
        for (sessionIndex, session) in recent.enumerated() {
            if sessionIndex.isMultiple(of: 8), !shouldContinue() { return nil }
            for day in EventCivilTime.days(
                overlappedBy: session.start,
                end: session.end,
                eventTimeZoneIdentifier: session.eventTimeZoneIdentifier,
                outputCalendar: calendar
            ) {
                guard let interval = EventCivilTime.interval(
                    forCivilDay: day,
                    eventTimeZoneIdentifier: session.eventTimeZoneIdentifier,
                    outputCalendar: calendar
                ) else { continue }
                guard let load = session.dailyLoadTRIMPCancellable(
                    rest: rest,
                    max: maxHR,
                    within: interval,
                    shouldContinue: shouldContinue
                ) else { return nil }
                let existing = dailyLoadByDay[day]
                let stableID = existing.map {
                    $0.sourceID.uuidString <= session.id.uuidString
                        ? $0.sourceID
                        : session.id
                } ?? session.id
                dailyLoadByDay[day] = (
                    trimp: (existing?.trimp ?? 0) + load,
                    sourceID: stableID
                )
            }
        }

        // Overview charts and their "days" labels require one point per event-
        // aware civil day, not one point per reconnect-fragmented session.
        // Aggregate load in TRIMP space before applying the nonlinear strain
        // scale. RHR uses only baseline-qualified rest evidence; HRV uses only
        // locally qualified RMSSD, so persisted-but-unproven values stay absent.
        var days = Array(Set(rowsByDay.keys).union(dailyLoadByDay.keys))
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &days,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: <
        ) else { return nil }
        var result: [AtriaTrendPoint] = []
        for day in days {
            guard shouldContinue() else { return nil }
            let dayRows = rowsByDay[day] ?? []
            var orderedRows = dayRows
            guard AtriaSleepCooperativeAlgorithms.stableSort(
                &orderedRows,
                shouldContinue: shouldContinue,
                areInIncreasingOrder: {
                if $0.session.start != $1.session.start {
                    return $0.session.start < $1.session.start
                }
                return $0.session.id.uuidString < $1.session.id.uuidString
                }
            ) else { return nil }
            // HRV nightly trend points must be qualified same-cycle sleep RMSSD,
            // not a whole-session `localRMSSD` that a daytime/live reading can
            // satisfy. Gate on confirmed-main-sleep exact-window evidence so a day
            // with only non-sleep RMSSD yields no HRV point (identical to the
            // nightly rollup/recovery surfaces). Without confirmed sleeps this
            // yields none rather than promoting an unqualified value.
            var qualifiedHRVs: [Int] = []
            for row in orderedRows {
                guard shouldContinue() else { return nil }
                if let evidence = confirmedMainSleepHRVEvidenceCancellable(
                    for: row.session,
                    confirmedSleeps: confirmedSleeps,
                    shouldContinue: shouldContinue
                ), evidence.value > 0 {
                    qualifiedHRVs.append(evidence.value)
                }
            }
            let acceptedRestingHRs = orderedRows.compactMap(\.acceptedRestingHR).filter { $0 > 0 }
            guard let sourceID = orderedRows.first?.session.id
                    ?? dailyLoadByDay[day]?.sourceID else { continue }
            // GAP-09: trend days fuse the same logged muscular equivalents as
            // today's aggregate and the frozen rollups — the chart must agree
            // with the day numbers it summarizes. (A day whose only evidence
            // is a logged workout with no HR sessions keeps no trend point;
            // trend rows require session evidence for their identity.)
            let muscularTRIMP = muscularTRIMPEquivalentTotal(
                confirmedWorkouts.filter { workout in
                    calendar.isDate(EventCivilTime.day(
                        containing: workout.end,
                        eventTimeZoneIdentifier: workout.eventTimeZoneIdentifier,
                        outputCalendar: calendar
                    ), inSameDayAs: day)
                }
            )
            let dayTRIMP = (dailyLoadByDay[day]?.trimp ?? 0) + muscularTRIMP
            result.append(AtriaTrendPoint(
                id: sourceID,
                date: day,
                restingHR: acceptedRestingHRs.min(),
                strain: Metrics.strain(fromTRIMP: dayTRIMP),
                hrv: averageIntSnapshot(qualifiedHRVs)
            ))
        }
        return shouldContinue() ? result : nil
    }

    private nonisolated static func makeTrainingLoadSummary(sessions: [SavedSession],
                                                            rest: Int,
                                                            maxHR: Int,
                                                            calendar: Calendar = .current) -> TrainingLoadSummary {
        makeTrainingLoadSummaryCancellable(
            sessions: sessions,
            rest: rest,
            maxHR: maxHR,
            calendar: calendar,
            shouldContinue: { true }
        ) ?? .learning
    }

    nonisolated static func makeTrainingLoadSummaryCancellable(
        sessions: [SavedSession],
        rest: Int,
        maxHR: Int,
        calendar: Calendar = .current,
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> TrainingLoadSummary? {
        guard shouldContinue(), maxHR > rest else {
            return shouldContinue() ? .learning : nil
        }
        var trimpByDay: [Date: Double] = [:]
        for (index, session) in sessions.enumerated() where session.points.count >= 2 {
            if index.isMultiple(of: 8), !shouldContinue() { return nil }
            for day in EventCivilTime.days(
                overlappedBy: session.start,
                end: session.end,
                eventTimeZoneIdentifier: session.eventTimeZoneIdentifier,
                outputCalendar: calendar
            ) {
                guard let interval = EventCivilTime.interval(
                    forCivilDay: day,
                    eventTimeZoneIdentifier: session.eventTimeZoneIdentifier,
                    outputCalendar: calendar
                ) else { continue }
                guard let load = session.dailyLoadTRIMPCancellable(
                    rest: rest,
                    max: maxHR,
                    within: interval,
                    shouldContinue: shouldContinue
                ) else { return nil }
                trimpByDay[day, default: 0] += load
            }
        }
        var daily = Array(trimpByDay)
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &daily,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: { $0.key > $1.key }
        ) else { return nil }
        return shouldContinue()
            ? AtriaAnalytics.TrainingLoad.summary(
                dailyStrains: daily.map {
                    AtriaAnalytics.Strain.score(fromTRIMP: $0.value)
                }
            )
            : nil
    }

    /// Today's HR zone minutes, same day-grouping as `homeSavedAggregate`'s
    /// `savedTodayTRIMP` (walks `sessions` newest-first, stopping at the
    /// first session that isn't today). Excludes logged strength-log
    /// intervals from each session the same way `trimp(rest:max:)` and
    /// `timeInZone(maxHR:)` do, so the zone split matches the strain figure.
    nonisolated static func makeTodayHRZoneMinutes(sessions: [SavedSession],
                                                   rest: Int,
                                                   maxHR: Int,
                                                   now: Date = Date(),
                                                   cycleStart: Date? = nil,
                                                   calendar: Calendar = .current) -> TodayHRZoneMinutes {
        makeTodayHRZoneMinutesCancellable(
            sessions: sessions,
            rest: rest,
            maxHR: maxHR,
            now: now,
            cycleStart: cycleStart,
            calendar: calendar,
            shouldContinue: { true }
        ) ?? .empty
    }

    nonisolated static func makeTodayHRZoneMinutesCancellable(
        sessions: [SavedSession],
        rest: Int,
        maxHR: Int,
        now: Date = Date(),
        cycleStart: Date? = nil,
        calendar: Calendar = .current,
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> TodayHRZoneMinutes? {
        guard shouldContinue() else { return nil }
        var totals = AtriaAnalytics.Strain.MaxHeartRateZoneSeconds.empty
        var hasSamples = false
        let dayStart = cycleStart ?? calendar.startOfDay(for: now)
        let dayEnd = now
        for (sessionIndex, session) in sessions.enumerated() {
            if sessionIndex.isMultiple(of: 8), !shouldContinue() { return nil }
            guard session.end > dayStart, session.start < dayEnd, !session.points.isEmpty else { continue }
            var samples: [HRSample] = []
            for (pointIndex, point) in session.points.enumerated() {
                if pointIndex.isMultiple(of: 256), !shouldContinue() {
                    return nil
                }
                let timestamp = session.start.addingTimeInterval(point.t)
                if timestamp >= dayStart, timestamp < dayEnd {
                    samples.append(.init(t: timestamp, bpm: point.bpm))
                }
            }
            guard !samples.isEmpty else { continue }
            hasSamples = true
            var clippedExclusions: [ExcludedInterval] = []
            for interval in session.excludedIntervals ?? [] {
                guard shouldContinue() else { return nil }
                let start = max(interval.start, dayStart)
                let end = min(interval.end, dayEnd)
                if end > start {
                    clippedExclusions.append(.init(start: start, end: end))
                }
            }
            guard let segments = AtriaAnalytics.Strain.contiguousSegments(
                samples,
                excluding: clippedExclusions,
                shouldContinue: shouldContinue
            ) else { return nil }
            var summary = AtriaAnalytics.Strain.MaxHeartRateZoneSeconds.empty
            for segment in segments {
                var series: [(t: Double, bpm: Int)] = []
                series.reserveCapacity(segment.count)
                for (index, point) in segment.enumerated() {
                    if index.isMultiple(of: 256), !shouldContinue() {
                        return nil
                    }
                    series.append((
                        point.t.timeIntervalSince(dayStart),
                        point.bpm
                    ))
                }
                guard let part = AtriaAnalytics.Strain
                    .maxHeartRateZoneSeconds(
                        series,
                        maxHR: maxHR,
                        restingHR: rest,
                        shouldContinue: shouldContinue
                    ) else { return nil }
                summary = summary + part
            }
            totals = AtriaAnalytics.Strain.MaxHeartRateZoneSeconds(rest: totals.rest + summary.rest,
                                                                   warmup: totals.warmup + summary.warmup,
                                                                   fatBurn: totals.fatBurn + summary.fatBurn,
                                                                   aerobic: totals.aerobic + summary.aerobic,
                                                                   anaerobic: totals.anaerobic + summary.anaerobic,
                                                                   max: totals.max + summary.max,
                                                                   droppedGapSeconds: totals.droppedGapSeconds + summary.droppedGapSeconds)
        }

        guard shouldContinue() else { return nil }
        guard hasSamples else { return .empty }
        func minutes(_ seconds: TimeInterval) -> Int {
            Int((seconds / 60).rounded())
        }
        return TodayHRZoneMinutes(restMinutes: minutes(totals.rest),
                                  warmupMinutes: minutes(totals.warmup),
                                  fatBurnMinutes: minutes(totals.fatBurn),
                                  aerobicMinutes: minutes(totals.aerobic),
                                  anaerobicMinutes: minutes(totals.anaerobic),
                                  maxMinutes: minutes(totals.max),
                                  hasSamples: true)
    }

    private nonisolated static func makeHistorySnapshots(sessions: [SavedSession],
                                                         confirmedWorkouts: [UserConfirmedWorkout],
                                                         confirmedSleeps: [UserConfirmedSleep],
                                                         dismissedSleepCandidates: [AtriaDismissedSleepCandidate] = [],
                                                         archiveHeartRatePoints: [HistoricalArchive.HeartRatePoint] = [],
                                                         canonicalHistory: [HistoricalArchive.VerifiedCanonicalConsumerSource] = [],
                                                         additionalStepEvidenceDays: [AtriaHistoricalDailyConsumerProjection.StepDay] = [],
                                                         motionTickDayEvidence: HistoricalArchive.MotionTickDayEvidence? = nil,
                                                         priorMotionTickDayEvidence: [HistoricalArchive.MotionTickDayEvidence] = [],
                                                         canonicalPageCursor: AtriaHistoricalAggregateReader.PageCursor? = nil,
                                                         canonicalHistoryHasMore: Bool = false,
                                                         biologicalSex: AthleteProfile.BiologicalSex = .unspecified,
                                                         baseline: PersonalBaseline,
                                                         rest: Int,
                                                         maxHR: Int,
                                                         calendar: Calendar = .current) -> (history: HistorySnapshot, sleep: SleepHistorySnapshot) {
        let presentation = HistorySnapshot(
            sessions: sessions,
            detections: [],
            trends: [],
            rollups: [],
            rest: rest,
            maxHR: maxHR
        )
        return makeHistorySnapshotsCancellable(
            sessions: sessions,
            confirmedWorkouts: confirmedWorkouts,
            confirmedSleeps: confirmedSleeps,
            dismissedSleepCandidates: dismissedSleepCandidates,
            archiveHeartRatePoints: archiveHeartRatePoints,
            canonicalHistory: canonicalHistory,
            additionalStepEvidenceDays: additionalStepEvidenceDays,
            motionTickDayEvidence: motionTickDayEvidence,
            priorMotionTickDayEvidence: priorMotionTickDayEvidence,
