    nonisolated static func makeHistorySnapshotsCancellable(
        sessions: [SavedSession],
        confirmedWorkouts: [UserConfirmedWorkout],
        confirmedSleeps: [UserConfirmedSleep],
        dismissedSleepCandidates: [AtriaDismissedSleepCandidate] = [],
        archiveHeartRatePoints: [HistoricalArchive.HeartRatePoint] = [],
        canonicalHistory: [HistoricalArchive.VerifiedCanonicalConsumerSource] = [],
        additionalStepEvidenceDays: [AtriaHistoricalDailyConsumerProjection.StepDay] = [],
        motionTickDayEvidence: HistoricalArchive.MotionTickDayEvidence? = nil,
        priorMotionTickDayEvidence: [HistoricalArchive.MotionTickDayEvidence] = [],
        canonicalPageCursor: AtriaHistoricalAggregateReader.PageCursor? = nil,
        canonicalHistoryHasMore: Bool = false,
        biologicalSex: AthleteProfile.BiologicalSex = .unspecified,
        baseline: PersonalBaseline,
        rest: Int,
        maxHR: Int,
        calendar: Calendar = .current,
        preservingPresentationFrom presentation: HistorySnapshot = .empty,
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> (history: HistorySnapshot, sleep: SleepHistorySnapshot)? {
        guard shouldContinue() else { return nil }
        // Per-stage dying threads (2026-08-04): the full rebuild generated
        // ~2.4GB of transient garbage in one continuous stretch once ~700k
        // recovered archive points existed. Splitting the pipeline bounds the
        // peak to the worst single stage AND the per-stage probe notes name
        // that stage if it alone still overruns.
        let canonical = AtriaTransientWorkThread.run(name: "atria.hist-canonical",
                                                     qualityOfService: .utility) {
            makeCanonicalSessionsCancellable(
                from: sessions,
                shouldContinue: shouldContinue
            )
        }
        guard let canonical, shouldContinue() else { return nil }
        let detections = AtriaTransientWorkThread.run(name: "atria.hist-detections",
                                                      qualityOfService: .utility) {
            makeHistoryDetectionsCancellable(
                sessions: canonical,
                confirmedWorkouts: confirmedWorkouts,
                rest: rest,
                maxHR: maxHR,
                calendar: calendar,
                shouldContinue: shouldContinue
            ).flatMap {
                mergeCanonicalHistoricalDetectionsCancellable(
                    live: $0,
                    sources: canonicalHistory,
                    shouldContinue: shouldContinue
                )
            }
        }
        guard let detections, shouldContinue() else { return nil }
        let rollups = AtriaTransientWorkThread.run(name: "atria.hist-rollups",
                                                   qualityOfService: .utility) {
            makeHistoryDailyRollupsCancellable(
                sessions: canonical,
                detections: detections,
                confirmedWorkouts: confirmedWorkouts,
                archiveHeartRatePoints: archiveHeartRatePoints,
                biologicalSex: biologicalSex,
                baselineRestingIsTrusted:
                    baseline.hasTrustedRestingBaseline(now: Date()),
                rest: rest,
                maxHR: maxHR,
                calendar: calendar,
                shouldContinue: shouldContinue
            ).flatMap {
                mergeCanonicalHistoricalRollupsCancellable(
                    live: $0,
                    sources: canonicalHistory,
                    rest: rest,
                    maxHR: maxHR,
                    biologicalSex: biologicalSex,
                    calendar: calendar,
                    shouldContinue: shouldContinue
                )
            }
        }
        guard let rollups, shouldContinue() else { return nil }
        let trends = AtriaTransientWorkThread.run(name: "atria.hist-trends",
                                                  qualityOfService: .utility) {
            makeHistoryTrendSummariesCancellable(
                sessions: canonical,
                rollups: rollups,
                baseline: baseline,
                rest: rest,
                maxHR: maxHR,
                calendar: calendar,
                shouldContinue: shouldContinue
            )
        }
        guard let trends, shouldContinue() else { return nil }
        guard var stepEvidenceDays = verifiedCanonicalStepEvidenceDaysCancellable(
            sources: canonicalHistory,
            calendar: calendar,
            shouldContinue: shouldContinue
        ) else { return nil }
        stepEvidenceDays.append(contentsOf: additionalStepEvidenceDays)
        if let motionTickDayEvidence {
            stepEvidenceDays.removeAll {
                abs($0.dayStart.timeIntervalSince(
                    motionTickDayEvidence.windowStart
                )) < 1
            }
            stepEvidenceDays.append(
                motionTickStepDay(
                    evidence: motionTickDayEvidence,
                    calendar: calendar
                )
            )
        }
        // 2026-07-31: closed prior-cycle receipts stay in History across a
        // relaunch. An exact canonical day remains authoritative; a rehydrated
        // receipt may only fill a missing day or replace weaker partial
        // coverage, using the daily store's own weaker-record rule.
        for (index, priorEvidence) in priorMotionTickDayEvidence.enumerated() {
            if index.isMultiple(of: 16), !shouldContinue() { return nil }
            let matching = stepEvidenceDays.filter {
                abs($0.dayStart.timeIntervalSince(
                    priorEvidence.windowStart
                )) < 1
            }
            if matching.contains(where: {
                ($0.state == .available || $0.state == .knownEmpty)
                    && $0.stepCount != nil
            }) {
                continue
            }
            let receiptDay = motionTickStepDay(
                evidence: priorEvidence,
                calendar: calendar
            )
            if let strongestExisting = matching.max(by: {
                AtriaWhoop4MotionTickDailyStore.isWeaker($0, $1)
            }), !AtriaWhoop4MotionTickDailyStore.isWeaker(
                strongestExisting,
                receiptDay
            ) {
                continue
            }
            stepEvidenceDays.removeAll {
                abs($0.dayStart.timeIntervalSince(
                    priorEvidence.windowStart
                )) < 1
            }
            stepEvidenceDays.append(receiptDay)
        }
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &stepEvidenceDays,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: { $0.dayStart > $1.dayStart }
        ) else { return nil }
        guard let verifiedStepDays = verifiedCanonicalStepDaysCancellable(
            sources: canonicalHistory,
            calendar: calendar,
            shouldContinue: shouldContinue
        ) else { return nil }
        var replayIdentityRowCount = 0
        for (index, source) in canonicalHistory.enumerated() {
            if index.isMultiple(of: 16), !shouldContinue() { return nil }
            replayIdentityRowCount += source.replayPayloadRetired
                ? source.identity.replayReceipt.recordCount
                : source.replayIdentity.entries.count
        }
        let history = HistorySnapshot(
            recoveredSessions: canonical,
            detections: detections,
            trends: trends,
            rollups: rollups,
            verifiedHistoricalStepDays: verifiedStepDays,
            verifiedHistoricalStepEvidenceDays: stepEvidenceDays,
            verifiedReplayIdentityRowCount: replayIdentityRowCount,
            verifiedCanonicalSources: canonicalHistory,
            verifiedCanonicalPageCursor: canonicalPageCursor,
            replaceVerifiedCanonicalPageCursor: true,
            verifiedCanonicalHistoryHasMore: canonicalHistoryHasMore,
            preservingPresentationFrom: presentation
        )
        let sleep = SleepHistorySnapshot(rollups: rollups,
                                         confirmedSleeps: confirmedSleeps,
                                         dismissedCandidates: dismissedSleepCandidates,
                                         calendar: calendar,
                                         shouldContinue: shouldContinue)
        return shouldContinue() ? (history, sleep) : nil
    }

    /// Rebuilds only civil days whose durable inputs changed during one exact
    /// recovery transaction. Untouched rows remain the previously published
    /// verified values; the full path remains the fail-closed fallback when no
    /// usable prior snapshot exists.
    nonisolated static func makeIncrementalRecoveredHistorySnapshots(
        previous: HistorySnapshot,
        previousSleep: SleepHistorySnapshot,
        affectedDays: Set<Date>,
        sessions: [SavedSession],
        confirmedWorkouts: [UserConfirmedWorkout],
        confirmedSleeps: [UserConfirmedSleep],
        dismissedSleepCandidates: [AtriaDismissedSleepCandidate],
        archiveHeartRatePoints: [HistoricalArchive.HeartRatePoint],
        biologicalSex: AthleteProfile.BiologicalSex,
        baseline: PersonalBaseline,
        rest: Int,
        maxHR: Int,
        calendar: Calendar = .current,
        shouldContinue: @escaping @Sendable () -> Bool = { true }
    ) -> (history: HistorySnapshot, sleep: SleepHistorySnapshot)? {
        guard shouldContinue() else { return nil }
        let normalizedAffectedDays = Set(affectedDays.map {
            calendar.startOfDay(for: $0)
        })
        guard !normalizedAffectedDays.isEmpty,
              !previous.rollups.isEmpty else { return nil }

        func overlapsAffectedDay(_ session: SavedSession) -> Bool {
            EventCivilTime.days(
                overlappedBy: session.start,
                end: session.end,
                eventTimeZoneIdentifier: session.eventTimeZoneIdentifier,
                outputCalendar: calendar
            ).contains { normalizedAffectedDays.contains($0) }
        }
        var affectedSessions: [SavedSession] = []
        for (index, session) in sessions.enumerated() {
            if index.isMultiple(of: 64), !shouldContinue() { return nil }
            if overlapsAffectedDay(session) { affectedSessions.append(session) }
        }
        var affectedWorkouts: [UserConfirmedWorkout] = []
        for (index, workout) in confirmedWorkouts.enumerated() {
            if index.isMultiple(of: 64), !shouldContinue() { return nil }
            if normalizedAffectedDays.contains(
                EventCivilTime.day(
                    containing: workout.start,
                    eventTimeZoneIdentifier: workout.eventTimeZoneIdentifier,
                    outputCalendar: calendar
                )
            ) {
                affectedWorkouts.append(workout)
            }
        }
        var affectedArchivePoints: [HistoricalArchive.HeartRatePoint] = []
        for (index, point) in archiveHeartRatePoints.enumerated() {
            if index.isMultiple(of: 256), !shouldContinue() { return nil }
            if normalizedAffectedDays.contains(calendar.startOfDay(for: point.t)) {
                affectedArchivePoints.append(point)
            }
        }
        guard let partial = makeHistorySnapshotsCancellable(
            sessions: affectedSessions,
            confirmedWorkouts: affectedWorkouts,
            confirmedSleeps: confirmedSleeps,
            dismissedSleepCandidates: dismissedSleepCandidates,
            archiveHeartRatePoints: affectedArchivePoints,
            biologicalSex: biologicalSex,
            baseline: baseline,
            rest: rest,
            maxHR: maxHR,
            calendar: calendar,
            preservingPresentationFrom: previous,
            shouldContinue: shouldContinue
        ) else { return nil }
        var retainedDetections: [ActivityDetection] = []
        for (index, detection) in previous.detections.enumerated() {
            if index.isMultiple(of: 64), !shouldContinue() { return nil }
            if !normalizedAffectedDays.contains(
                calendar.startOfDay(for: detection.start)
            ) {
                retainedDetections.append(detection)
            }
        }
        var mergedDetections = retainedDetections + partial.history.detections
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &mergedDetections,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: { $0.start > $1.start }
        ) else { return nil }
        var retainedRollups: [DailyRollup] = []
        for (index, rollup) in previous.rollups.enumerated() {
            if index.isMultiple(of: 64), !shouldContinue() { return nil }
            if !normalizedAffectedDays.contains(
                calendar.startOfDay(for: rollup.day)
            ) {
                retainedRollups.append(rollup)
            }
        }
        var mergedRollups = retainedRollups + partial.history.rollups
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &mergedRollups,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: { $0.day > $1.day }
        ) else { return nil }
        let history = HistorySnapshot(
            recoveredSessions: sessions,
            detections: mergedDetections,
            trends: previous.trends,
            rollups: mergedRollups,
            preservingPresentationFrom: previous
        )
        let sleep = SleepHistorySnapshot(
            rollups: mergedRollups,
            confirmedSleeps: confirmedSleeps,
            dismissedCandidates: dismissedSleepCandidates,
            calendar: calendar,
            shouldContinue: shouldContinue
        )
        _ = previousSleep
        return shouldContinue() ? (history, sleep) : nil
    }

    nonisolated static func recoveredDailyPreparationSessions(
        sessions: [SavedSession],
        affectedDays: Set<Date>,
        physiologicalDayStart: Date,
        now: Date = Date(),
        calendar: Calendar = .current,
        shouldContinue: @escaping @Sendable () -> Bool = { true }
    ) -> [SavedSession]? {
        guard shouldContinue() else { return nil }
        var normalizedAffectedDays = Set<Date>()
        normalizedAffectedDays.reserveCapacity(affectedDays.count)
        for (index, day) in affectedDays.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            normalizedAffectedDays.insert(calendar.startOfDay(for: day))
        }

        var selected: [SavedSession] = []
        selected.reserveCapacity(min(sessions.count, 512))
        for (sessionIndex, session) in sessions.enumerated() {
            if sessionIndex.isMultiple(of: 32), !shouldContinue() { return nil }
            if session.end > physiologicalDayStart && session.start < now {
                selected.append(session)
                continue
            }

            guard session.end > session.start else { continue }
            let eventCalendar = EventCivilTime.eventCalendar(
                timeZoneIdentifier: session.eventTimeZoneIdentifier,
                fallback: calendar
            )
            var cursor = eventCalendar.startOfDay(for: session.start)
            let finalInstant = session.end.addingTimeInterval(-0.001)
            var dayIndex = 0
            var overlapsAffectedDay = false
            while cursor <= finalInstant {
                if dayIndex.isMultiple(of: 32), !shouldContinue() { return nil }
                let components = eventCalendar.dateComponents(
                    [.year, .month, .day],
                    from: cursor
                )
                if let materialized = calendar.date(from: components),
                   normalizedAffectedDays.contains(
                    calendar.startOfDay(for: materialized)
                   ) {
                    overlapsAffectedDay = true
                    break
                }
                guard let next = eventCalendar.date(
                    byAdding: .day,
                    value: 1,
                    to: cursor
                ), next > cursor else { break }
                cursor = next
                dayIndex += 1
            }
            if overlapsAffectedDay { selected.append(session) }
        }
        return shouldContinue() ? selected : nil
    }

    private nonisolated static func motionTickStepDay(
        evidence: HistoricalArchive.MotionTickDayEvidence,
        calendar: Calendar
    ) -> AtriaHistoricalDailyConsumerProjection.StepDay {
        let components = calendar.dateComponents(
            [.year, .month, .day],
            from: evidence.windowStart
        )
        let localDay = String(
            format: "%04d-%02d-%02d",
            components.year ?? 0,
            components.month ?? 0,
            components.day ?? 0
        )
        return .init(
            localDay: localDay,
            dayStart: evidence.windowStart,
            dayEnd: evidence.capturedThrough,
            state: .missing,
            stepCount: nil,
            knownStepDeltaSum: evidence.steps,
            knownEpochCount: evidence.decodedRows > 0 ? 1 : 0,
            rejectedOrUnknownEpochCount: 0,
            knownCoverageSeconds: evidence.knownCoverageSeconds,
            missingCoverageSeconds: evidence.missingCoverageSeconds
        )
    }

    /// Canonical history fills disconnected windows but never replaces a
    /// live/session-derived detection covering the same event.
    nonisolated static func mergeCanonicalHistoricalDetections(
        live: [ActivityDetection],
        sources: [HistoricalArchive.VerifiedCanonicalConsumerSource]
    ) -> [ActivityDetection] {
        func overlaps(_ lhs: ActivityDetection, _ rhs: ActivityDetection) -> Bool {
            let overlap = min(lhs.end, rhs.end).timeIntervalSince(max(lhs.start, rhs.start))
            let shortest = min(lhs.duration, rhs.duration)
            return overlap > 0 && shortest > 0 && overlap / shortest >= 0.70
        }
        var result = live
        let workoutDetections = sources.flatMap(\.workout.candidates).map { candidate in
            ActivityDetection(id: stableDetectionID("canonical-workout:\(candidate.identifier)"),
                              kind: .workout,
                              confidence: candidate.confidence == .high ? .high : .medium,
                              start: candidate.start,
                              end: candidate.end,
                              duration: candidate.end.timeIntervalSince(candidate.start),
                              avgHR: Int(candidate.averageHeartRate.rounded()),
                              peakHR: candidate.maximumHeartRate,
                              reason: "verified_canonical_history")
        }
        let activityDetections = sources.flatMap(\.activity.candidates).map { candidate in
            ActivityDetection(id: stableDetectionID("canonical-activity:\(candidate.identifier)"),
                              kind: .activityCandidate,
                              confidence: candidate.confidence == .high ? .high
                                : (candidate.confidence == .medium ? .medium : .low),
                              start: candidate.start,
                              end: candidate.end,
                              duration: candidate.end.timeIntervalSince(candidate.start),
                              avgHR: Int((candidate.averageHeartRate ?? 0).rounded()),
                              peakHR: candidate.maximumHeartRate ?? 0,
                              reason: "verified_canonical_history")
        }
        for candidate in workoutDetections + activityDetections {
            guard !result.contains(where: { overlaps($0, candidate) }) else { continue }
            result.append(candidate)
        }
        return result.sorted { $0.start > $1.start }
    }

    nonisolated static func mergeCanonicalHistoricalDetectionsCancellable(
        live: [ActivityDetection],
        sources: [HistoricalArchive.VerifiedCanonicalConsumerSource],
        shouldContinue: () -> Bool
    ) -> [ActivityDetection]? {
        func overlaps(_ lhs: ActivityDetection, _ rhs: ActivityDetection) -> Bool {
            let overlap = min(lhs.end, rhs.end)
                .timeIntervalSince(max(lhs.start, rhs.start))
            let shortest = min(lhs.duration, rhs.duration)
            return overlap > 0 && shortest > 0 && overlap / shortest >= 0.70
        }
        var result = live
        for (sourceIndex, source) in sources.enumerated() {
            if sourceIndex.isMultiple(of: 4), !shouldContinue() { return nil }
            for (index, candidate) in source.workout.candidates.enumerated() {
                if index.isMultiple(of: 64), !shouldContinue() { return nil }
                let detection = ActivityDetection(
                    id: stableDetectionID(
                        "canonical-workout:\(candidate.identifier)"
                    ),
                    kind: .workout,
                    confidence: candidate.confidence == .high ? .high : .medium,
                    start: candidate.start,
                    end: candidate.end,
                    duration: candidate.end.timeIntervalSince(candidate.start),
                    avgHR: Int(candidate.averageHeartRate.rounded()),
                    peakHR: candidate.maximumHeartRate,
                    reason: "verified_canonical_history"
                )
                var duplicate = false
                for (existingIndex, existing) in result.enumerated() {
                    if existingIndex.isMultiple(of: 64), !shouldContinue() {
                        return nil
                    }
                    if overlaps(existing, detection) {
                        duplicate = true
                        break
                    }
                }
                if !duplicate { result.append(detection) }
            }
            for (index, candidate) in source.activity.candidates.enumerated() {
                if index.isMultiple(of: 64), !shouldContinue() { return nil }
                let detection = ActivityDetection(
                    id: stableDetectionID(
                        "canonical-activity:\(candidate.identifier)"
                    ),
                    kind: .activityCandidate,
                    confidence: candidate.confidence == .high ? .high
                        : (candidate.confidence == .medium ? .medium : .low),
                    start: candidate.start,
                    end: candidate.end,
                    duration: candidate.end.timeIntervalSince(candidate.start),
                    avgHR: Int((candidate.averageHeartRate ?? 0).rounded()),
                    peakHR: candidate.maximumHeartRate ?? 0,
                    reason: "verified_canonical_history"
                )
                var duplicate = false
                for (existingIndex, existing) in result.enumerated() {
                    if existingIndex.isMultiple(of: 64), !shouldContinue() {
                        return nil
                    }
                    if overlaps(existing, detection) {
                        duplicate = true
                        break
                    }
                }
                if !duplicate { result.append(detection) }
            }
        }
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &result,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: { $0.start > $1.start }
        ) else { return nil }
        return result
    }

    /// Deterministic UUIDs keep detector rows stable across cache rebuilds and
    /// app launches without persisting a second identity ledger.
    private nonisolated static func stableDetectionID(_ value: String) -> UUID {
        let digest = Array(SHA256.hash(data: Data(value.utf8)).prefix(16))
        var bytes = digest
        bytes[6] = (bytes[6] & 0x0f) | 0x50
        bytes[8] = (bytes[8] & 0x3f) | 0x80
        return UUID(uuid: (bytes[0], bytes[1], bytes[2], bytes[3],
                          bytes[4], bytes[5], bytes[6], bytes[7],
                          bytes[8], bytes[9], bytes[10], bytes[11],
                          bytes[12], bytes[13], bytes[14], bytes[15]))
    }

    /// Replays already-qualified compact HR transitions through the same
    /// profile-specific continuous-day kernel used by raw/live projections.
    nonisolated static func canonicalHistoricalStrain(
        transitionHalfBPMSeconds: [Int: Double],
        rest: Int,
        maxHR: Int,
        biologicalSex: AthleteProfile.BiologicalSex
    ) -> Double {
        let parameters = AtriaAnalytics.Strain.banisterParameters(for: biologicalSex)
        let configuration = AtriaStrainLoadModel.Configuration(
            restingBPM: Double(rest),
            maximumBPM: Double(maxHR),
            intensityMultiplier: parameters.multiplier,
            intensityCoefficient: parameters.coefficient,
            mode: .continuousDay,
            maximumGap: AtriaAnalytics.Strain.maximumLoadEvidenceGap
        )
        let load = transitionHalfBPMSeconds.reduce(0.0) { total, pair in
            total + AtriaStrainLoadModel.load(
                forQualifiedMeanBPM: Double(pair.key) / 2,
                duration: pair.value,
                configuration: configuration
            )
        }
        return Metrics.strain(fromTRIMP: load)
    }

    /// Merges only evidence the canonical artifact can fully support. Existing
    /// nonzero/live values and detected sleep always win. A partial HR day never
    /// becomes a full-day strain, and unavailable steps never become zero.
    nonisolated static func mergeCanonicalHistoricalRollups(
        live: [DailyRollup],
        sources: [HistoricalArchive.VerifiedCanonicalConsumerSource],
        rest: Int,
        maxHR: Int,
        biologicalSex: AthleteProfile.BiologicalSex = .unspecified,
        calendar: Calendar
    ) -> [DailyRollup] {
        var byDay = Dictionary(uniqueKeysWithValues: live.map {
            (calendar.startOfDay(for: $0.day), $0)
        })
        let activityByDay = Dictionary(grouping: sources.flatMap(\.activity.candidates)) {
            calendar.startOfDay(for: $0.start)
        }
        let workoutByDay = Dictionary(grouping: sources.flatMap(\.workout.candidates)) {
            calendar.startOfDay(for: $0.start)
        }
        let sleepByDay = Dictionary(grouping: sources.flatMap(\.sleep.candidates)) {
            calendar.startOfDay(for: $0.end)
        }.mapValues { values in
            values.sorted {
                if $0.confidence != $1.confidence { return $0.confidence == .high }
                return $0.end.timeIntervalSince($0.start) > $1.end.timeIntervalSince($1.start)
            }.first!
        }
        var metricsByDay: [Date: AtriaHistoricalDailyConsumerProjection.DailyMetric] = [:]
        for metric in sources.flatMap(\.dailyMetrics.days) {
            let day = calendar.startOfDay(for: metric.dayStart)
            if metricsByDay[day] == nil { metricsByDay[day] = metric }
        }
        let days = Set(byDay.keys)
            .union(activityByDay.keys)
            .union(workoutByDay.keys)
            .union(sleepByDay.keys)
            .union(metricsByDay.keys)
        for day in days {
            let existing = byDay[day]
            let sleep = sleepByDay[day]
            let useCanonicalSleep = existing?.sleepStart == nil && sleep != nil
            let metric = metricsByDay[day]
            let canonicalStrain: Double? = metric.flatMap { metric in
                guard metric.heartRateState == .available,
                      metric.missingMinuteCount == 0,
                      let distribution = metric.observedHeartRate,
                      maxHR > rest else { return nil }
                return canonicalHistoricalStrain(
                    transitionHalfBPMSeconds: distribution.transitionHalfBPMSeconds,
                    rest: rest,
                    maxHR: maxHR,
                    biologicalSex: biologicalSex
                )
            }
            byDay[day] = DailyRollup(
                day: day,
                sessions: existing?.sessions ?? 0,
                activityCandidates: max(existing?.activityCandidates ?? 0,
                                        activityByDay[day]?.count ?? 0),
                workouts: max(existing?.workouts ?? 0, workoutByDay[day]?.count ?? 0),
                confirmedWorkouts: existing?.confirmedWorkouts ?? 0,
                restCandidates: existing?.restCandidates ?? 0,
                sleepReady: max(existing?.sleepReady ?? 0, useCanonicalSleep ? 1 : 0),
                sleepCandidates: max(existing?.sleepCandidates ?? 0, sleep == nil ? 0 : 1),
                duration: existing?.duration ?? 0,
                sleepDuration: useCanonicalSleep
                    ? sleep.map { $0.end.timeIntervalSince($0.start) }
                    : existing?.sleepDuration,
                sleepSpan: useCanonicalSleep
                    ? sleep.map { $0.end.timeIntervalSince($0.start) }
                    : existing?.sleepSpan,
                sleepStart: useCanonicalSleep ? sleep?.start : existing?.sleepStart,
                sleepEnd: useCanonicalSleep ? sleep?.end : existing?.sleepEnd,
                sleepSource: useCanonicalSleep ? "verified_canonical_history" : existing?.sleepSource,
                sleepStageSegments: existing?.sleepStageSegments ?? [],
                strain: (existing?.strain ?? 0) > 0
                    ? existing!.strain : (canonicalStrain ?? existing?.strain ?? 0),
                avgHRV: existing?.avgHRV,
                hrvWindowCount: existing?.hrvWindowCount ?? 0,
                restingHR: existing?.restingHR,
                avgRespiratoryRate: existing?.avgRespiratoryRate
            )
        }
        return byDay.values.sorted { $0.day > $1.day }
    }

    nonisolated static func mergeCanonicalHistoricalRollupsCancellable(
        live: [DailyRollup],
        sources: [HistoricalArchive.VerifiedCanonicalConsumerSource],
        rest: Int,
        maxHR: Int,
        biologicalSex: AthleteProfile.BiologicalSex = .unspecified,
        calendar: Calendar,
        shouldContinue: () -> Bool
    ) -> [DailyRollup]? {
        // Canonical sources are page-bounded, but each payload may carry many
        // daily rows. Visit every nested collection under the exact authority
        // before entering the small day merge and revalidate immediately after.
        for (sourceIndex, source) in sources.enumerated() {
            if sourceIndex.isMultiple(of: 4), !shouldContinue() { return nil }
            let counts = [
                source.activity.candidates.count,
                source.workout.candidates.count,
                source.sleep.candidates.count,
                source.dailyMetrics.days.count,
            ]
            for count in counts where count > 0 {
                var index = 0
                while index < count {
                    if !shouldContinue() { return nil }
                    index += 64
                }
            }
        }
        guard shouldContinue() else { return nil }
        let result = mergeCanonicalHistoricalRollups(
            live: live,
            sources: sources,
            rest: rest,
            maxHR: maxHR,
            biologicalSex: biologicalSex,
            calendar: calendar
        )
        return shouldContinue() ? result : nil
    }

    nonisolated static func verifiedCanonicalStepDays(
        sources: [HistoricalArchive.VerifiedCanonicalConsumerSource],
        calendar: Calendar
    ) -> [AtriaHistoricalDailyConsumerProjection.StepDay] {
        verifiedCanonicalStepEvidenceDays(sources: sources, calendar: calendar).filter {
            ($0.state == .available || $0.state == .knownEmpty) && $0.stepCount != nil
        }
    }

    nonisolated static func verifiedCanonicalStepEvidenceDays(
        sources: [HistoricalArchive.VerifiedCanonicalConsumerSource],
        calendar: Calendar
    ) -> [AtriaHistoricalDailyConsumerProjection.StepDay] {
        let grouped = Dictionary(grouping: sources.flatMap(\.steps.days)) {
            calendar.startOfDay(for: $0.dayStart)
        }
        var byDay: [Date: AtriaHistoricalDailyConsumerProjection.StepDay] = [:]
        for (key, candidates) in grouped {
            let exact = candidates.filter {
                ($0.state == .available || $0.state == .knownEmpty) && $0.stepCount != nil
            }
            let exactCounts = Set(exact.compactMap(\.stepCount))
            if exactCounts.count == 1, let selected = exact.first {
                byDay[key] = selected
                continue
            }
            // Conflicting exact totals fail closed for that day. Otherwise the
            // strongest partial subtotal is retained with its missing-coverage
            // state and can only be labelled as partial by presentation code.
            guard exact.isEmpty else { continue }
            byDay[key] = candidates
                .filter { $0.state == .missing && $0.knownCoverageSeconds > 0 }
                .max {
                    if $0.knownCoverageSeconds != $1.knownCoverageSeconds {
                        return $0.knownCoverageSeconds < $1.knownCoverageSeconds
                    }
                    return $0.knownEpochCount < $1.knownEpochCount
                }
        }
        return byDay.values.sorted { $0.dayStart > $1.dayStart }
    }

    nonisolated static func verifiedCanonicalStepEvidenceDaysCancellable(
        sources: [HistoricalArchive.VerifiedCanonicalConsumerSource],
        calendar: Calendar,
        shouldContinue: () -> Bool
    ) -> [AtriaHistoricalDailyConsumerProjection.StepDay]? {
        var grouped: [Date: [AtriaHistoricalDailyConsumerProjection.StepDay]] = [:]
        for (sourceIndex, source) in sources.enumerated() {
            if sourceIndex.isMultiple(of: 8), !shouldContinue() { return nil }
            for (dayIndex, day) in source.steps.days.enumerated() {
                if dayIndex.isMultiple(of: 64), !shouldContinue() { return nil }
                grouped[calendar.startOfDay(for: day.dayStart), default: []]
                    .append(day)
            }
        }
        var byDay: [Date: AtriaHistoricalDailyConsumerProjection.StepDay] = [:]
        for (key, candidates) in grouped {
            guard shouldContinue() else { return nil }
            let exact = candidates.filter {
                ($0.state == .available || $0.state == .knownEmpty)
                    && $0.stepCount != nil
            }
            let exactCounts = Set(exact.compactMap(\.stepCount))
            if exactCounts.count == 1, let selected = exact.first {
                byDay[key] = selected
                continue
            }
            guard exact.isEmpty else { continue }
            byDay[key] = candidates
                .filter {
                    $0.state == .missing && $0.knownCoverageSeconds > 0
                }
                .max {
                    if $0.knownCoverageSeconds != $1.knownCoverageSeconds {
                        return $0.knownCoverageSeconds < $1.knownCoverageSeconds
                    }
                    return $0.knownEpochCount < $1.knownEpochCount
                }
        }
        var result = Array(byDay.values)
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &result,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: { $0.dayStart > $1.dayStart }
        ) else { return nil }
        return result
    }

    nonisolated static func verifiedCanonicalStepDaysCancellable(
        sources: [HistoricalArchive.VerifiedCanonicalConsumerSource],
        calendar: Calendar,
        shouldContinue: () -> Bool
    ) -> [AtriaHistoricalDailyConsumerProjection.StepDay]? {
        guard let evidence = verifiedCanonicalStepEvidenceDaysCancellable(
            sources: sources,
            calendar: calendar,
            shouldContinue: shouldContinue
        ) else { return nil }
        var result: [AtriaHistoricalDailyConsumerProjection.StepDay] = []
        for (index, day) in evidence.enumerated() {
            if index.isMultiple(of: 64), !shouldContinue() { return nil }
            if (day.state == .available || day.state == .knownEmpty),
               day.stepCount != nil {
                result.append(day)
            }
        }
        return shouldContinue() ? result : nil
    }

    nonisolated static func makeHistoryDetections(sessions: [SavedSession],
                                                  confirmedWorkouts: [UserConfirmedWorkout],
                                                  rest: Int,
                                                  maxHR: Int,
                                                  calendar: Calendar) -> [ActivityDetection] {
        // Sleep/rest detections describe the saved session itself. Exertion
        // does not: a live journal can span hours around one short effort, so
        // History and Activity must use the same bounded replay authority as
        // Home/review instead of publishing the raw journal envelope.
        let preservedSleepAndRest = sessions.compactMap { session -> ActivityDetection? in
            AtriaTransientWorkThread.run(name: "atria.hist-detected-activity") { () -> ActivityDetection? in
                session.detectedActivity(rest: rest, maxHR: maxHR, calendar: calendar)
            }
        }.filter {
            $0.kind == .sleepCandidate || $0.kind == .restCandidate
        }
        let boundedActivity = makeWorkoutReviewCandidatesForCache(
            sessions: sessions,
            confirmedWorkouts: confirmedWorkouts,
            rest: rest,
            maxHR: maxHR
        ).map { candidate in
            ActivityDetection(
                id: stableDetectionID("bounded-workout-review:\(candidate.id)"),
                kind: candidate.kind,
                confidence: candidate.confidence,
                start: candidate.start,
                end: candidate.end,
                duration: candidate.duration,
                avgHR: candidate.avgHR,
                peakHR: candidate.peakHR,
                reason: candidate.reason,
                suggestedActivityType: candidate.suggestedActivityType
            )
        }
        return (preservedSleepAndRest + boundedActivity)
            .sorted { $0.start > $1.start }
    }

    nonisolated static func makeHistoryDetectionsCancellable(
        sessions: [SavedSession],
        confirmedWorkouts: [UserConfirmedWorkout],
        rest: Int,
        maxHR: Int,
        calendar: Calendar,
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> [ActivityDetection]? {
        let deadline = AtriaSleepSettlementDeadline(
            uptimeNanoseconds: .max,
            monotonicNow: { shouldContinue() ? 0 : .max }
        )
        var preserved: [ActivityDetection] = []
        for (index, session) in sessions.enumerated() {
            if index.isMultiple(of: 4), !shouldContinue() { return nil }
            let detectionResult = AtriaTransientWorkThread.run(
                name: "atria.hist-detected-activity"
            ) {
                try? session.detectedSleepOrRestActivityCancellable(
                    rest: rest,
                    maxHR: maxHR,
                    calendar: calendar,
                    cooperativeDeadline: deadline
                )
            }
            guard shouldContinue() else { return nil }
            if let detection = detectionResult,
               detection.kind == .sleepCandidate
                    || detection.kind == .restCandidate {
                preserved.append(detection)
            }
        }
        // Aggregate/window workout review is independently regenerated by its
        // bounded review cache. Running that O(points × candidate windows)
        // replay inside recovered history made lifecycle cancellation
        // impossible to bound. History retains only cooperatively derived
        // sleep/rest evidence here; confirmed workouts remain authoritative in
        // the rollup input and no unconfirmed activity is fabricated.
        _ = confirmedWorkouts
        var result = preserved
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &result,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: { $0.start > $1.start }
        ) else { return nil }
        return result
    }

    private nonisolated static func sleepSpan(duration: TimeInterval,
                                              start: Date?,
                                              end: Date?) -> TimeInterval? {
        guard duration > 0 else { return nil }
        if let start, let end, end > start {
            return max(duration, end.timeIntervalSince(start))
        }
        return duration
    }

    nonisolated static func makeHistoryDailyRollups(sessions: [SavedSession],
                                                    detections: [ActivityDetection],
                                                    confirmedWorkouts: [UserConfirmedWorkout],
                                                    archiveHeartRatePoints: [HistoricalArchive.HeartRatePoint] = [],
                                                    biologicalSex: AthleteProfile.BiologicalSex = .unspecified,
                                                    baselineRestingIsTrusted: Bool = false,
                                                    rest: Int,
                                                    maxHR: Int,
                                                    calendar: Calendar,
                                                    precomputedAggregateSleeps:
                                                        [Date: AggregateSleepCandidate]? = nil,
                                                    shouldContinue:
                                                        (() -> Bool)? = nil) -> [DailyRollup] {
        guard shouldContinue?() ?? true else { return [] }
        let grouped = Dictionary(grouping: sessions) { session in
            EventCivilTime.day(containing: session.start,
                               eventTimeZoneIdentifier: session.eventTimeZoneIdentifier,
                               outputCalendar: calendar)
        }
        var loadSessionsByDay: [Date: [SavedSession]] = [:]
        for (index, session) in sessions.enumerated() {
            if index.isMultiple(of: 16), !(shouldContinue?() ?? true) {
                return []
            }
            for day in EventCivilTime.days(overlappedBy: session.start,
                                           end: session.end,
                                           eventTimeZoneIdentifier: session.eventTimeZoneIdentifier,
                                           outputCalendar: calendar) {
                loadSessionsByDay[day, default: []].append(session)
            }
        }
        let sessionsByID = Dictionary(sessions.map { ($0.id, $0) }, uniquingKeysWith: { first, _ in first })
        let detectionsByDay = Dictionary(grouping: detections) { detection in
            EventCivilTime.day(containing: detection.start,
                               eventTimeZoneIdentifier: sessionsByID[detection.id]?.eventTimeZoneIdentifier,
                               outputCalendar: calendar)
        }
        let confirmedWorkoutsByDay = Dictionary(grouping: confirmedWorkouts) { workout in
            EventCivilTime.day(containing: workout.start,
                               eventTimeZoneIdentifier: workout.eventTimeZoneIdentifier,
                               outputCalendar: calendar)
        }
        let archiveDays = Set(archiveHeartRatePoints.map {
            calendar.startOfDay(for: $0.t)
        })
        // Daily rollups feed Activity Center and the Home review card, so only
        // user-facing review candidates belong in this projection. The raw
        // aggregate detector intentionally retains ambiguous quiet/rest windows
        // for diagnostics, but projecting every diagnostic aggregate here used
        // to resurrect the physically-disproved 22:18–02:05 false sleep even
        // after the dedicated review cache had rejected it.
        let aggregateSleeps = precomputedAggregateSleeps
            ?? Self.preferredSleepCandidatesByDay(
                Self.aggregateSleepCandidates(in: sessions,
                                              rest: rest,
                                              maxHR: maxHR,
                                              calendar: calendar,
                                              historicalMotionPolicy: .boundedRecent)
                    .filter(Self.isReviewWorthySleepCandidate)
            )
        // A manually declared/recovered workout is durable activity evidence
        // even when BLE produced no canonical HR session for its window. Keep
        // that civil day in the projection so the saved workout cannot exist in
        // Activity while disappearing from history graphs and day counters.
        let rollupDays = Set(grouped.keys)
            .union(loadSessionsByDay.keys)
            .union(aggregateSleeps.keys)
            .union(confirmedWorkoutsByDay.keys)
            .union(archiveDays)
        return rollupDays.compactMap { day -> DailyRollup? in
            guard shouldContinue?() ?? true else { return nil }
            let daySessions = grouped[day] ?? []
            let dayLoadSessions = loadSessionsByDay[day] ?? []
            let dayDetections = detectionsByDay[day] ?? []
            let aggregateSleep = aggregateSleeps[day]
            // A rollup is ready only when either the motion-backed gate or the
            // narrow physiological HR-only main-sleep gate can persist it.
            let aggregateSleepReady = (aggregateSleep.map {
                Self.isAutoConfirmableMainSleepCandidate(
                    $0,
                    baselineRestingIsTrusted: baselineRestingIsTrusted
                )
            } == true) ? 1 : 0
            let sleepStart = aggregateSleep?.start
            let sleepEnd = aggregateSleep?.end
            let sleepStageSegments = aggregateSleep.map { candidate in
                Self.sleepStageResearchSegments(from: daySessions,
                                                start: candidate.start,
                                                end: candidate.end,
                                                restingHR: candidate.restingHR,
                                                isNap: candidate.kind == "nap_candidate",
                                                motionValidated: candidate.motionEvidenceValidated)
            } ?? []
            let dayIntervals = dayLoadSessions.compactMap { session in
                EventCivilTime.interval(forCivilDay: day,
                                        eventTimeZoneIdentifier: session.eventTimeZoneIdentifier,
                                        outputCalendar: calendar).map { (session, $0) }
            }
            let duration = dayIntervals.reduce(0.0) { total, pair in
                let (session, interval) = pair
                return total + max(0, min(session.end, interval.end)
                    .timeIntervalSince(max(session.start, interval.start)))
            }
            let strainTRIMP: Double
            if let shouldContinue {
                var total = 0.0
                for pair in dayIntervals {
                    guard let load = pair.0.dailyLoadTRIMPCancellable(
                        rest: rest,
                        max: maxHR,
                        within: pair.1,
                        shouldContinue: shouldContinue
                    ) else { return nil }
                    total += load
                }
                strainTRIMP = total
            } else {
                strainTRIMP = dayIntervals.reduce(0.0) { total, pair in
                    total + pair.0.dailyLoadTRIMP(
                        rest: rest,
                        max: maxHR,
                        within: pair.1
                    )
                }
            }
            let localDayEnd = calendar.date(byAdding: .day, value: 1, to: day) ?? day
            let archiveTRIMP: Double
            if let shouldContinue {
                guard let value = archiveOnlyTRIMPCancellable(
                    archiveHeartRatePoints,
                    excludingCoverageFrom: dayLoadSessions,
                    within: DateInterval(start: day, end: localDayEnd),
                    rest: rest,
                    maxHR: maxHR,
                    biologicalSex: biologicalSex,
                    shouldContinue: shouldContinue
                ) else { return nil }
                archiveTRIMP = value
            } else {
                archiveTRIMP = archiveOnlyTRIMP(
                    archiveHeartRatePoints,
                    excludingCoverageFrom: dayLoadSessions,
                    within: DateInterval(start: day, end: localDayEnd),
                    rest: rest,
                    maxHR: maxHR,
                    biologicalSex: biologicalSex
                )
            }
            let strainWindowEnd = min(localDayEnd, Date())
            let strainElapsed = max(0, strainWindowEnd.timeIntervalSince(day))
            let strainObserved = AtriaHomeModel.observedHeartRateUnionSeconds(
                sessions: dayLoadSessions,
                windowStart: day,
                windowEnd: strainWindowEnd
            )
            let strainCoverage = strainElapsed > 0
                ? min(1, max(0, strainObserved / strainElapsed))
                : nil
            // GAP-09: logged muscular work fuses into the same day total in
            // TRIMP space, before the one saturating 0–21 display map. It is
            // logged evidence, so it does not change HR coverage accounting.
            let muscularTRIMP = muscularTRIMPEquivalentTotal(confirmedWorkoutsByDay[day] ?? [])
            // Assessment P1.7: keep the raw fused day TRIMP as truth; the 0–21
            // value below is its versioned display skin.
            let dayTRIMP = strainTRIMP + archiveTRIMP + muscularTRIMP
            let strainValue = Metrics.strain(fromTRIMP: dayTRIMP)
            let strainPresentation = Metrics.StrainPresentation.resolve(
                value: strainValue,
                coverageFraction: strainCoverage,
                baseConfidence: "local"
            )
            let hrvs = daySessions.compactMap(\.localRMSSD).filter { $0 > 0 }
            let hrvWindowCount = daySessions.reduce(0) {
                $0 + $1.localHRVWindowCount
            }
            let respiratoryRates = daySessions.compactMap {
                $0.sleepRespiratoryRate(rest: rest, maxHR: maxHR, calendar: calendar)
            }
            let fallbackRHRs = daySessions.map(\.restingStable).filter { $0 > 0 }
            return DailyRollup(day: day,
                               sessions: dayLoadSessions.count,
                               activityCandidates: dayDetections.filter { $0.kind == .activityCandidate }.count,
                               workouts: dayDetections.filter { $0.kind == .workout }.count,
                               confirmedWorkouts: confirmedWorkoutsByDay[day]?.count ?? 0,
                               restCandidates: dayDetections.filter { $0.kind == .restCandidate }.count,
                               sleepReady: aggregateSleepReady,
                               sleepCandidates: aggregateSleep == nil ? 0 : 1,
                               duration: duration,
                               sleepDuration: aggregateSleep?.duration,
                               sleepSpan: aggregateSleep?.span,
                               sleepStart: sleepStart,
                               sleepEnd: sleepEnd,
                               sleepSource: aggregateSleep?.kind,
                               sleepStageSegments: sleepStageSegments,
                               strain: strainValue,
                               strainCoverageFraction: strainCoverage,
                               strainEvidenceQuality: strainPresentation.quality,
                               trimp: dayTRIMP > 0 ? dayTRIMP : nil,
                               avgHRV: averageIntSnapshot(hrvs),
                               hrvWindowCount: hrvWindowCount,
                               restingHR: aggregateSleep?.restingHR ?? fallbackRHRs.min(),
                               avgRespiratoryRate: averageDoubleSnapshot(respiratoryRates))
        }
        .sorted { $0.day > $1.day }
    }

    nonisolated static func makeHistoryDailyRollupsCancellable(
        sessions: [SavedSession],
        detections: [ActivityDetection],
        confirmedWorkouts: [UserConfirmedWorkout],
        archiveHeartRatePoints: [HistoricalArchive.HeartRatePoint] = [],
        biologicalSex: AthleteProfile.BiologicalSex = .unspecified,
        baselineRestingIsTrusted: Bool = false,
        rest: Int,
        maxHR: Int,
        calendar: Calendar,
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> [DailyRollup]? {
        guard shouldContinue() else { return nil }
        let deadline = AtriaSleepSettlementDeadline(
            uptimeNanoseconds: .max,
            monotonicNow: { shouldContinue() ? 0 : .max }
        )
        guard let candidates = try? aggregateSleepCandidates(
            in: sessions,
            rest: rest,
            maxHR: maxHR,
            calendar: calendar,
            historicalMotionPolicy: .boundedRecent,
            cooperativeDeadline: deadline,
            includeResumedReviewCandidates: true
        ), shouldContinue() else { return nil }
        let aggregateSleeps = preferredSleepCandidatesByDay(
            candidates.filter(isReviewWorthySleepCandidate)
        )
        guard shouldContinue() else { return nil }
        let result = makeHistoryDailyRollups(
            sessions: sessions,
            detections: detections,
            confirmedWorkouts: confirmedWorkouts,
            archiveHeartRatePoints: archiveHeartRatePoints,
            biologicalSex: biologicalSex,
            baselineRestingIsTrusted: baselineRestingIsTrusted,
            rest: rest,
            maxHR: maxHR,
            calendar: calendar,
            precomputedAggregateSleeps: aggregateSleeps,
            shouldContinue: shouldContinue
        )
        return shouldContinue() ? result : nil
    }

    /// Per-DAY strain values (day-summed TRIMP → score), NOT per-session
    /// scores. score() saturates, so averaging per-session scores under-reports
    /// a day's strain ~2x versus the day-summed strain every other surface
    /// shows — trend charts must use this (2026-07-08 calc-consistency audit).
    /// GAP-09 fusion, day side: the summed muscular TRIMP-equivalent of a
    /// day's logged strength receipts. Only effort-complete receipts (a
    /// non-nil muscularInputScore, i.e. every load-qualified set carried an
    /// explicit RPE) contribute; an unlogged or partially logged session adds
    /// exactly zero — muscular load is never inferred from HR or duration.
    nonisolated static func muscularTRIMPEquivalentTotal(_ workouts: [UserConfirmedWorkout]) -> Double {
        workouts.reduce(0) {
            $0 + AtriaStrainLoadModel.muscularTRIMPEquivalent(
                inputScore: $1.muscularLoadReceipt?.muscularInputScore)
        }
    }

    nonisolated static func perDayStrains(_ sessions: [SavedSession],
                                          rest: Int,
                                          maxHR: Int,
                                          calendar: Calendar = .current) -> [Double] {
        var trimpByDay: [Date: Double] = [:]
        for session in sessions {
            let days = EventCivilTime.days(overlappedBy: session.start,
                                                   end: session.end,
                                                   eventTimeZoneIdentifier: session.eventTimeZoneIdentifier,
                                                   outputCalendar: calendar)
            for day in days {
                guard let interval = EventCivilTime.interval(
                    forCivilDay: day,
                    eventTimeZoneIdentifier: session.eventTimeZoneIdentifier,
                    outputCalendar: calendar
                ) else { continue }
                trimpByDay[day, default: 0] += session.dailyLoadTRIMP(
                    rest: rest,
                    max: maxHR,
                    within: interval
                )
            }
        }
        return trimpByDay.values.map { Metrics.strain(fromTRIMP: $0) }
    }

    struct TrendSessionMetricRow {
        let session: SavedSession
        let day: Date
        let localRMSSD: Int?
        let referenceValidatedHRV: Int?
        let sleepRespiratoryRate: Double?
        let acceptedRestingHR: Int?
    }

    nonisolated static func trendSessionRows(sessions: [SavedSession],
                                             rest: Int,
                                             maxHR: Int,
                                             calendar: Calendar = .current) -> [TrendSessionMetricRow] {
        sessions.map { session in
            let localRMSSD = session.localRMSSD
            let evidence = session.baselineLearningEvidence(rest: rest,
                                                            maxHR: maxHR,
                                                            calendar: calendar,
                                                            localRMSSD: localRMSSD)
            return TrendSessionMetricRow(session: session,
                                         day: EventCivilTime.day(
                                            containing: session.start,
                                            eventTimeZoneIdentifier: session.eventTimeZoneIdentifier,
                                            outputCalendar: calendar
                                         ),
                                         localRMSSD: localRMSSD,
                                         referenceValidatedHRV: session.referenceValidatedHRV,
                                         sleepRespiratoryRate: session.sleepRespiratoryRate(rest: rest,
                                                                                           maxHR: maxHR,
                                                                                           calendar: calendar),
                                         acceptedRestingHR: evidence.accepted ? evidence.value : nil)
        }
    }

    nonisolated static func trendSessionRowsCancellable(
        sessions: [SavedSession],
        rest: Int,
        maxHR: Int,
        calendar: Calendar = .current,
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> [TrendSessionMetricRow]? {
        var rows: [TrendSessionMetricRow] = []
        rows.reserveCapacity(sessions.count)
        for (index, session) in sessions.enumerated() {
            if index.isMultiple(of: 4), !shouldContinue() { return nil }
            let localRMSSD = session.localRMSSDCancellable(
                shouldContinue: shouldContinue
            )
            guard shouldContinue(),
                  let evidence = session.baselineLearningEvidenceCancellable(
                    rest: rest,
                    maxHR: maxHR,
                    localRMSSD: localRMSSD,
                    shouldContinue: shouldContinue
                  ) else { return nil }
            let respiratory = session.sleepRespiratoryRateCancellable(
                rest: rest,
                maxHR: maxHR,
                calendar: calendar,
                shouldContinue: shouldContinue
            )
            guard shouldContinue() else { return nil }
            rows.append(TrendSessionMetricRow(
                session: session,
                day: EventCivilTime.day(
                    containing: session.start,
                    eventTimeZoneIdentifier:
                        session.eventTimeZoneIdentifier,
                    outputCalendar: calendar
                ),
                localRMSSD: localRMSSD,
                referenceValidatedHRV:
                    session.referenceValidatedHRVCancellable(
                        shouldContinue: shouldContinue
                    ),
                sleepRespiratoryRate: respiratory,
                acceptedRestingHR: evidence.accepted ? evidence.value : nil
            ))
        }
        return shouldContinue() ? rows : nil
    }

    /// User-facing trends are one point per physiological (wake) day. Raw
    /// sessions can be fragmented by checkpoints, reconnects, or an overnight
    /// civil-day boundary, so averaging `TrendSessionMetricRow` values weights
    /// whichever day happened to contain more fragments. `SavedDailyMetric`
    /// rows are the frozen, resolved morning/day summaries and are therefore
    /// the only source of metric values here. Session count remains diagnostic.
    nonisolated static func dailyMetricTrendSummary(
        metrics: [SavedDailyMetric],
        rollups: [DailyRollup],
        days: Int,
        now: Date,
        diagnosticSessionCount: Int = 0,
        calendar: Calendar = .current
    ) -> TrendSummary {
        let today = calendar.startOfDay(for: now)
        let cutoff = calendar.date(byAdding: .day,
                                  value: -(max(days, 1) - 1),
                                  to: today) ?? today
        let byDay = Dictionary(
            metrics
                .filter { metric in
                    let day = calendar.startOfDay(for: metric.day)
                    return day >= cutoff && day <= today
                }
                .map { (calendar.startOfDay(for: $0.day), $0) },
            uniquingKeysWith: { existing, candidate in
                if existing.recoverySummary == nil,
                   candidate.recoverySummary != nil {
                    return candidate
                }
                return existing
            }
        )
        let recentMetrics = byDay.values.sorted { $0.day < $1.day }
        let recentRollups = rollups.filter {
            let day = calendar.startOfDay(for: $0.day)
            return day >= cutoff && day <= today
        }
        let coverageDays = recentMetrics.count
        let requiredCoverageDays = trendRequiredCoverageDaysSnapshot(windowDays: days)
        let coveragePercent = Int((Double(coverageDays) / Double(max(days, 1)) * 100).rounded())
        let recoveries = recentMetrics.compactMap {
            $0.recoverySummary?.score ?? $0.recoveryPercent
        }
        let hrvs = recentMetrics.compactMap(\.hrv).filter { $0 > 0 }
        let rhrs = recentMetrics.compactMap(\.restingHR).filter { $0 > 0 }
        let strains = recentMetrics.compactMap(\.strain).filter { $0 > 0 }
        let respiratoryRates = recentMetrics.compactMap(\.respiratoryRate).filter { $0 > 0 }
        let hrvState = hrvs.isEmpty
            ? "learning"
            : "frozen_daily_samples_\(hrvs.count)"
        let anomalies = trendAnomaliesSnapshot(rollups: recentRollups)
        let avgRecovery = averageIntSnapshot(recoveries)
        let avgHRV = averageIntSnapshot(hrvs)
        return TrendSummary(
            id: days,
            days: days,
            sessions: diagnosticSessionCount,
            coverageDays: coverageDays,
            requiredCoverageDays: requiredCoverageDays,
            coveragePercent: coveragePercent,
            confidence: trendConfidenceSnapshot(coverageDays: coverageDays,
                                                windowDays: days),
            avgRecovery: avgRecovery,
            avgHRV: avgHRV,
            avgRHR: averageIntSnapshot(rhrs),
            avgStrain: averageDoubleSnapshot(strains),
            avgRespiratoryRate: averageDoubleSnapshot(respiratoryRates),
            anomalies: anomalies,
            anomalySource: "frozen_daily_metrics",
            anomalySampleDays: recentRollups.count,
            hrvState: hrvState,
            detail: trendDetailSnapshot(coverageDays: coverageDays,
                                        windowDays: days,
                                        hrvState: hrvState,
                                        rhrSamples: rhrs.count,
                                        strainSamples: strains.count,
                                        anomalySampleDays: recentRollups.count,
                                        anomalies: anomalies),
            blockers: trendSummaryBlockersSnapshot(coverageDays: coverageDays,
                                                   requiredCoverageDays: requiredCoverageDays,
                                                   avgRecovery: avgRecovery,
                                                   avgHRV: avgHRV,
                                                   hrvState: hrvState)
        )
    }

    private nonisolated static func makeHistoryTrendSummaries(sessions: [SavedSession],
                                                              rollups: [DailyRollup],
                                                              baseline: PersonalBaseline,
                                                              rest: Int,
                                                              maxHR: Int,
                                                              calendar: Calendar) -> [TrendSummary] {
        let now = Date()
        let maximumWindowDays = TrendSummary.Window.allCases.map(\.rawValue).max() ?? 0
        let oldestCutoff = now.addingTimeInterval(-Double(maximumWindowDays) * 24 * 60 * 60)
        let trendSessions = sessions.filter { $0.start >= oldestCutoff }
        let rows = Self.trendSessionRows(sessions: trendSessions, rest: rest, maxHR: maxHR, calendar: calendar)
        return TrendSummary.Window.allCases.map { window in
            let cutoff = now.addingTimeInterval(-Double(window.rawValue) * 24 * 60 * 60)
            let recentRows = rows.filter { $0.session.start >= cutoff }
            let recent = recentRows.map(\.session)
            let recentRollups = rollups.filter { $0.day >= calendar.startOfDay(for: cutoff) }
            let coverageDays = Set(recentRows.map(\.day))
                .union(recentRollups.filter { $0.strain > 0 }.map(\.day))
                .count
            let requiredCoverageDays = trendRequiredCoverageDaysSnapshot(windowDays: window.rawValue)
            let coveragePercent = Int((Double(coverageDays) / Double(window.rawValue) * 100).rounded())
            let rhrs = recentRows.compactMap(\.acceptedRestingHR)
            let strains = recentRollups.map(\.strain).filter { $0 > 0 }
            let hrvs = recentRows.compactMap(\.localRMSSD).filter { $0 > 0 }
            let respiratoryRates = recentRows.compactMap(\.sleepRespiratoryRate)
            let respiratoryBaseline = respiratoryBaselineStatsSnapshot(respiratoryRates)
            let rollupsByDay = Dictionary(uniqueKeysWithValues: recentRollups.map { (calendar.startOfDay(for: $0.day), $0) })
            let recoveries: [Int] = recentRows.compactMap { row in
                let session = row.session
                let sleepRollup = rollupsByDay[row.day]
                let recovery = Metrics.recoveryV2(hrvSnapshot: nil,
                                                  fallbackRMSSD: row.localRMSSD,
                                                  restingNow: session.restingStable,
                                                  baseline: baseline,
                                                  hrvReferenceValidated: session.hrvReferenceValidated == true,
                                                  // DailyRollup has no durable
                                                  // motion-validation provenance.
                                                  // Its duration/span ratio is
                                                  // coverage, not sleep efficiency;
                                                  // use duration alone in this
                                                  // legacy history fallback.
                                                  sleepEfficiency: nil,
                                                  sleepDurationHours: sleepRollup?.sleepDuration.map { $0 / 3_600 },
                                                  respiratoryRate: row.sleepRespiratoryRate,
                                                  respiratoryBaseline: respiratoryBaseline)
                return recovery.percent
            }
            let validatedHRVs = recentRows.compactMap(\.referenceValidatedHRV).filter { $0 > 0 }
            let hrvState = hrvs.isEmpty
                ? "learning"
                : (validatedHRVs.count == hrvs.count
                   ? "validated_samples_\(hrvs.count)"
                   : "personal_baseline_samples_\(hrvs.count)")
            let avgRecovery = averageIntSnapshot(recoveries)
            let avgHRV = averageIntSnapshot(hrvs)
            let anomalies = trendAnomaliesSnapshot(rollups: recentRollups)
            return TrendSummary(id: window.rawValue,
                                days: window.rawValue,
                                sessions: recent.count,
                                coverageDays: coverageDays,
                                requiredCoverageDays: requiredCoverageDays,
                                coveragePercent: coveragePercent,
                                confidence: trendConfidenceSnapshot(coverageDays: coverageDays, windowDays: window.rawValue),
                                avgRecovery: avgRecovery,
                                avgHRV: avgHRV,
                                avgRHR: averageIntSnapshot(rhrs),
                                avgStrain: averageDoubleSnapshot(strains),
                                avgRespiratoryRate: averageDoubleSnapshot(respiratoryRates),
                                anomalies: anomalies,
                                anomalySource: "bounded_history_rollups",
                                anomalySampleDays: recentRollups.count,
                                hrvState: hrvState,
                                detail: trendDetailSnapshot(coverageDays: coverageDays,
                                                            windowDays: window.rawValue,
                                                            hrvState: hrvState,
                                                            rhrSamples: rhrs.count,
                                                            strainSamples: strains.count,
                                                            anomalySampleDays: recentRollups.count,
                                                            anomalies: anomalies),
                                blockers: trendSummaryBlockersSnapshot(coverageDays: coverageDays,
                                                                       requiredCoverageDays: requiredCoverageDays,
                                                                       avgRecovery: avgRecovery,
                                                                       avgHRV: avgHRV,
                                                                       hrvState: hrvState))
        }
    }

    nonisolated static func makeHistoryTrendSummariesCancellable(
        sessions: [SavedSession],
        rollups: [DailyRollup],
        baseline: PersonalBaseline,
        rest: Int,
        maxHR: Int,
        calendar: Calendar,
        shouldContinue: () -> Bool
    ) -> [TrendSummary]? {
        guard shouldContinue() else { return nil }
        let now = Date()
        let maximumWindowDays = TrendSummary.Window.allCases
            .map(\.rawValue).max() ?? 0
        let oldestCutoff = now.addingTimeInterval(
            -Double(maximumWindowDays) * 86_400
        )
        var rows: [TrendSessionMetricRow] = []
        for (index, session) in sessions.enumerated() {
            if index.isMultiple(of: 4), !shouldContinue() { return nil }
            guard session.start >= oldestCutoff else { continue }
            rows.append(contentsOf: trendSessionRows(
                sessions: [session],
                rest: rest,
                maxHR: maxHR,
                calendar: calendar
            ))
            guard shouldContinue() else { return nil }
        }
        var result: [TrendSummary] = []
        for window in TrendSummary.Window.allCases {
            guard shouldContinue() else { return nil }
            let cutoff = now.addingTimeInterval(
                -Double(window.rawValue) * 86_400
            )
            var recentRows: [TrendSessionMetricRow] = []
            for (index, row) in rows.enumerated() {
                if index.isMultiple(of: 64), !shouldContinue() { return nil }
                if row.session.start >= cutoff { recentRows.append(row) }
            }
            var recentRollups: [DailyRollup] = []
            let rollupCutoff = calendar.startOfDay(for: cutoff)
            for (index, rollup) in rollups.enumerated() {
                if index.isMultiple(of: 64), !shouldContinue() { return nil }
                if rollup.day >= rollupCutoff { recentRollups.append(rollup) }
            }
            let coverageDays = Set(recentRows.map(\.day))
                .union(recentRollups.filter { $0.strain > 0 }.map(\.day))
                .count
            let requiredCoverageDays = trendRequiredCoverageDaysSnapshot(
                windowDays: window.rawValue
            )
            let coveragePercent = Int((Double(coverageDays)
                / Double(window.rawValue) * 100).rounded())
            let rhrs = recentRows.compactMap(\.acceptedRestingHR)
            let strains = recentRollups.map(\.strain).filter { $0 > 0 }
            let hrvs = recentRows.compactMap(\.localRMSSD).filter { $0 > 0 }
            let respiratoryRates = recentRows.compactMap(\.sleepRespiratoryRate)
            let respiratoryBaseline = respiratoryBaselineStatsSnapshot(
                respiratoryRates
            )
            let rollupsByDay = Dictionary(uniqueKeysWithValues:
                recentRollups.map {
                    (calendar.startOfDay(for: $0.day), $0)
                }
            )
            var recoveries: [Int] = []
            for (index, row) in recentRows.enumerated() {
                if index.isMultiple(of: 16), !shouldContinue() { return nil }
                let session = row.session
                let sleepRollup = rollupsByDay[row.day]
                let recovery = Metrics.recoveryV2(
                    hrvSnapshot: nil,
                    fallbackRMSSD: row.localRMSSD,
                    restingNow: session.restingStable,
                    baseline: baseline,
                    hrvReferenceValidated:
                        session.hrvReferenceValidated == true,
                    sleepEfficiency: nil,
                    sleepDurationHours:
                        sleepRollup?.sleepDuration.map { $0 / 3_600 },
                    respiratoryRate: row.sleepRespiratoryRate,
                    respiratoryBaseline: respiratoryBaseline
                )
                if let percent = recovery.percent {
                    recoveries.append(percent)
                }
                guard shouldContinue() else { return nil }
            }
            let validatedHRVs = recentRows
                .compactMap(\.referenceValidatedHRV).filter { $0 > 0 }
            let hrvState = hrvs.isEmpty
                ? "learning"
                : (validatedHRVs.count == hrvs.count
                    ? "validated_samples_\(hrvs.count)"
                    : "personal_baseline_samples_\(hrvs.count)")
            let avgRecovery = averageIntSnapshot(recoveries)
            let avgHRV = averageIntSnapshot(hrvs)
            let anomalies = trendAnomaliesSnapshot(rollups: recentRollups)
            result.append(TrendSummary(
                id: window.rawValue,
                days: window.rawValue,
                sessions: recentRows.count,
                coverageDays: coverageDays,
                requiredCoverageDays: requiredCoverageDays,
                coveragePercent: coveragePercent,
                confidence: trendConfidenceSnapshot(
                    coverageDays: coverageDays,
                    windowDays: window.rawValue
                ),
                avgRecovery: avgRecovery,
                avgHRV: avgHRV,
                avgRHR: averageIntSnapshot(rhrs),
                avgStrain: averageDoubleSnapshot(strains),
                avgRespiratoryRate: averageDoubleSnapshot(respiratoryRates),
                anomalies: anomalies,
                anomalySource: "bounded_history_rollups",
                anomalySampleDays: recentRollups.count,
                hrvState: hrvState,
                detail: trendDetailSnapshot(
                    coverageDays: coverageDays,
                    windowDays: window.rawValue,
                    hrvState: hrvState,
                    rhrSamples: rhrs.count,
                    strainSamples: strains.count,
                    anomalySampleDays: recentRollups.count,
                    anomalies: anomalies
                ),
                blockers: trendSummaryBlockersSnapshot(
                    coverageDays: coverageDays,
                    requiredCoverageDays: requiredCoverageDays,
                    avgRecovery: avgRecovery,
                    avgHRV: avgHRV,
                    hrvState: hrvState
                )
            ))
        }
        return shouldContinue() ? result : nil
    }

    private nonisolated static func preferredSleepCandidatesByDay(_ candidates: [AggregateSleepCandidate]) -> [Date: AggregateSleepCandidate] {
        let grouped = Dictionary(grouping: candidates, by: \.day)
        return Dictionary(uniqueKeysWithValues: grouped.compactMap { day, dayCandidates in
            guard let preferred = preferredDailySleepCandidate(from: dayCandidates) else { return nil }
            return (day, preferred)
        })
    }

    private nonisolated static func preferredSleepCandidateForReview(from candidates: [AggregateSleepCandidate]) -> AggregateSleepCandidate? {
        let grouped = Dictionary(grouping: candidates.filter(isReviewWorthySleepCandidate), by: \.day)
        for day in grouped.keys.sorted(by: >) {
            guard let preferred = preferredDailySleepCandidate(from: grouped[day] ?? []) else { continue }
            return preferred
        }
        return nil
    }

    /// Review cards are user-facing detection claims. A fragmented 2.5-hour
    /// low-HR window with no motion is equally compatible with quiet awake time
    /// (the physically disproven 2026-07-12 22:18–02:05 case), so it must not
    /// surface as “Sleep detected.” Naps remain review-only, while main sleep
    /// needs motion or the existing high-specificity HR-only gates.
    nonisolated static func isReviewWorthySleepCandidate(_ candidate: AggregateSleepCandidate) -> Bool {
        if candidate.kind == "resumed_sleep_candidate" { return true }
        if candidate.kind == "nap_candidate" { return true }
        if candidate.denseMorningHROnlyReviewQualified { return true }
        if candidate.denseLongHROnlyReviewQualified { return true }
        if candidate.motionEvidenceValidated {
            // Low motion is necessary evidence, not proof of sleep. For a
            // shorter night, require the robust HR shape and majority overlap
            // with the overnight core; otherwise quiet TV/reading can still be
            // labelled “Sleep detected.” A main-sleep-sized window may remain
            // reviewable with the existing 90-minute core-overlap guard.
            guard candidate.duration >= AggregateSleepCandidate.strictMinimumDuration,
                  candidate.medianHR <= candidate.baselineRestingHR + 10,
                  candidate.hrP90 <= candidate.baselineRestingHR + 22,
                  candidate.elevatedSampleFraction < 0.10,
                  candidate.elevatedSampleFraction * candidate.duration < 20 * 60,
                  candidate.maxGap <= 2 * 60 * 60 else {
                return false
            }
            let eventCalendar = EventCivilTime.eventCalendar(
                timeZoneIdentifier: candidate.eventTimeZoneIdentifier,
                fallback: .current
            )
            if candidate.duration >= AggregateSleepCandidate.minimumAutoConfirmMainSleepDuration {
                return mainSleepAutoConfirmWindowReady(candidate, calendar: eventCalendar)
            }
            return sleepCoreOverlapFraction(start: candidate.start,
                                            end: candidate.end,
                                            calendar: eventCalendar) >= 0.60
        }
        return isUnambiguousHROnlyMainSleepCandidate(candidate)
            || isHighSpecificityFragmentedHROnlyMainSleepCandidate(candidate)
            || isDegradedHROnlyOvernightSleepCandidate(candidate)
    }

    private nonisolated static func preferredDailySleepCandidate(from candidates: [AggregateSleepCandidate]) -> AggregateSleepCandidate? {
        candidates.sorted { lhs, rhs in
            if sleepCandidateMainSleepRank(lhs) != sleepCandidateMainSleepRank(rhs) {
                return sleepCandidateMainSleepRank(lhs) > sleepCandidateMainSleepRank(rhs)
            }
            if sleepCandidateConfidenceRank(lhs) != sleepCandidateConfidenceRank(rhs) {
                return sleepCandidateConfidenceRank(lhs) > sleepCandidateConfidenceRank(rhs)
            }
            if lhs.duration != rhs.duration { return lhs.duration > rhs.duration }
            if lhs.span != rhs.span { return lhs.span > rhs.span }
            return lhs.start < rhs.start
        }
        .first
    }

    private nonisolated static func sleepCandidateMainSleepRank(_ candidate: AggregateSleepCandidate) -> Int {
        // A resumed segment is intentionally queued behind the primary main
        // review for the day. Once that primary window is settled, candidate
        // filtering exposes this lower-ranked, separate review.
        if candidate.kind == "resumed_sleep_candidate" { return 2 }
        guard candidate.kind != "nap_candidate" else { return 1 }
        if candidate.duration >= AggregateSleepCandidate.strictMinimumDuration {
            return 4
        }
        if candidate.duration >= AggregateSleepCandidate.fragmentedMinimumDuration
            && candidate.span >= AggregateSleepCandidate.fragmentedMinimumSpan {
            return 3
        }
        return 2
    }

    private nonisolated static func sleepCandidateConfidenceRank(_ candidate: AggregateSleepCandidate) -> Int {
        if candidate.motionEvidenceValidated { return 3 }
        if isStrapOnlyMainSleepReviewCandidate(candidate) { return 2 }
        switch candidate.confidence {
        case .high: return 2
        case .medium: return 1
        case .low: return 0
        }
    }

    private nonisolated static func isStrapOnlyMainSleepReviewCandidate(_ candidate: AggregateSleepCandidate) -> Bool {
        candidate.kind != "nap_candidate"
            && candidate.kind != "resumed_sleep_candidate"
            && !candidate.motionEvidenceValidated
            && (candidate.denseLongHROnlyReviewQualified
                || candidate.duration >= AggregateSleepCandidate.strictMinimumDuration
                || (candidate.duration >= AggregateSleepCandidate.fragmentedMinimumDuration
                    && candidate.span >= AggregateSleepCandidate.fragmentedMinimumSpan))
    }

    private nonisolated static func averageIntSnapshot(_ values: [Int]) -> Int? {
        guard !values.isEmpty else { return nil }
        return Int((Double(values.reduce(0, +)) / Double(values.count)).rounded())
    }

    private nonisolated static func respiratoryBaselineStatsSnapshot(_ values: [Double]) -> (mean: Double, sd: Double, count: Int)? {
        guard values.count >= PersonalBaseline.trustedMinimumSamples else { return nil }
        let mean = values.reduce(0, +) / Double(values.count)
        guard values.count > 1 else { return (mean, 0, values.count) }
        let variance = values.reduce(0) { $0 + pow($1 - mean, 2) } / Double(values.count - 1)
        return (mean, sqrt(variance), values.count)
    }

    // Internal (was private) so the honesty rule below is unit-testable.
    nonisolated static func sleepEfficiency(duration: TimeInterval?, span: TimeInterval?) -> Double? {
        // Honesty (2026-07-08 audit): when the in-bed span is unknown we do NOT
        // know efficiency — return nil so recovery skips the sleep signal,
        // instead of `max(span ?? duration, duration)` which made an unknown
        // span read as a fabricated 100% and inflated the recovery score.
        guard let duration, duration > 0, let span, span > 0 else { return nil }
        let denominator = max(span, duration)
        return min(max(duration / denominator, 0), 1)
    }

    private nonisolated static func trendRequiredCoverageDaysSnapshot(windowDays: Int) -> Int {
        max(1, Int((Double(windowDays) * 0.70).rounded(.up)))
    }

    private nonisolated static func trendConfidenceSnapshot(coverageDays: Int, windowDays: Int) -> String {
        guard coverageDays > 0 else { return "learning" }
        if coverageDays >= trendRequiredCoverageDaysSnapshot(windowDays: windowDays) { return "high" }
        let coverage = Double(coverageDays) / Double(windowDays)
        if coverage >= 0.25 || coverageDays >= 7 { return "partial" }
        return "learning"
    }

    private nonisolated static func trendAnomaliesSnapshot(rollups recent: [DailyRollup]) -> [String] {
        let ordered = recent.sorted { $0.day < $1.day }
        guard let latest = ordered.last else { return [] }
        let rhrs = ordered.compactMap(\.restingHR).filter { $0 > 0 }
        let strains = ordered.map(\.strain).filter { $0 > 0 }
        var out: [String] = []
        if let latestRHR = latest.restingHR,
           isHighOutlierSnapshot(Double(latestRHR), in: rhrs.map(Double.init)) {
            out.append("RHR elevated")
        }
        if latest.strain > 0,
           isHighOutlierSnapshot(latest.strain, in: strains) {
            out.append("Strain spike")
        }
        return out
    }

    nonisolated static func attachRecoveredSkinTemperature(
        _ points: [HistoricalArchive.SkinTemperatureRawPoint],
        to sessions: [SavedSession]
    ) -> [SavedSession] {
        attachRecoveredSkinTemperatureCancellable(
            points,
            to: sessions,
            shouldContinue: { true }
        ) ?? sessions
    }

    nonisolated static func attachRecoveredSkinTemperatureCancellable(
        _ points: [HistoricalArchive.SkinTemperatureRawPoint],
        to sessions: [SavedSession],
        shouldContinue: () -> Bool
    ) -> [SavedSession]? {
        guard !points.isEmpty, !sessions.isEmpty else { return sessions }
        let unknownDevice = "<unknown>"
        func deviceKey(_ identifier: String?) -> String {
            let normalized = identifier?
                .trimmingCharacters(in: .whitespacesAndNewlines)
                .lowercased() ?? ""
            return normalized.isEmpty ? unknownDevice : normalized
        }

        guard shouldContinue() else { return nil }
        var pointsByDevice: [String: [HistoricalArchive.SkinTemperatureRawPoint]] = [:]
        for (index, point) in points.enumerated() {
            if index.isMultiple(of: 256), !shouldContinue() { return nil }
            pointsByDevice[deviceKey(point.strapIdentifier), default: []]
                .append(point)
        }
        for key in Array(pointsByDevice.keys) {
            guard shouldContinue() else { return nil }
            guard var values = pointsByDevice[key],
                  AtriaSleepCooperativeAlgorithms.stableSort(
                    &values,
                    shouldContinue: shouldContinue,
                    areInIncreasingOrder: { $0.t < $1.t }
                  ) else { return nil }
            pointsByDevice[key] = values
        }
        var rawByDevice: [String: [Int]] = [:]
        for (key, values) in pointsByDevice {
            var raw: [Int] = []
            raw.reserveCapacity(values.count)
            for (index, value) in values.enumerated() {
                if index.isMultiple(of: 256), !shouldContinue() { return nil }
                raw.append(value.raw)
            }
            rawByDevice[key] = raw
        }
        guard shouldContinue() else { return nil }
        var anchors: [String: Double] = [:]
        for (key, raw) in rawByDevice {
            guard shouldContinue() else { return nil }
            if let anchor = AtriaResearchProbe
                .whoop4SkinTemperatureAnchorRawCancellable(
                    raw,
                    shouldContinue: shouldContinue
                ) {
                anchors[key] = anchor
            }
            guard shouldContinue() else { return nil }
        }
        guard !anchors.isEmpty else { return sessions }

        func lowerBound(
            _ values: [HistoricalArchive.SkinTemperatureRawPoint],
            _ target: Date
        ) -> Int {
            var low = 0
            var high = values.count
            while low < high {
                let middle = low + (high - low) / 2
                if values[middle].t < target {
                    low = middle + 1
                } else {
                    high = middle
                }
            }
            return low
        }

        var result: [SavedSession] = []
        result.reserveCapacity(sessions.count)
        for (sessionIndex, source) in sessions.enumerated() {
            if sessionIndex.isMultiple(of: 32), !shouldContinue() { return nil }
            let candidates = pointsByDevice.compactMap { key, values
                -> (key: String, value: ArraySlice<HistoricalArchive.SkinTemperatureRawPoint>)? in
                let start = lowerBound(values, source.start)
                let end = lowerBound(values, source.end.addingTimeInterval(0.001))
                guard end > start else { return nil }
                return (key, values[start..<end])
            }
            guard let selected = candidates
                .sorted(by: {
                    if $0.value.count != $1.value.count {
                        return $0.value.count > $1.value.count
                    }
                    return $0.key < $1.key
                })
                .first,
                let anchor = anchors[selected.key] else {
                result.append(source)
                continue
            }

            // Persist minute means, not every 1 Hz ADC row. This preserves the
            // sleep-baseline signal while keeping session JSON bounded.
            var minuteBuckets: [Int: [HistoricalArchive.SkinTemperatureRawPoint]] = [:]
            for (index, value) in selected.value.enumerated() {
                if index.isMultiple(of: 256), !shouldContinue() { return nil }
                minuteBuckets[Int(value.t.timeIntervalSince1970 / 60), default: []]
                    .append(value)
            }
            guard shouldContinue() else { return nil }
            var orderedMinutes = Array(minuteBuckets.keys)
            guard AtriaSleepCooperativeAlgorithms.stableSort(
                &orderedMinutes,
                shouldContinue: shouldContinue,
                areInIncreasingOrder: <
            ) else { return nil }
            var decoded: [AtriaResearchProbe.DecodedSkinTemperatureCelsius] = []
            decoded.reserveCapacity(orderedMinutes.count)
            for minute in orderedMinutes {
                guard let bucket = minuteBuckets[minute], !bucket.isEmpty else {
                    continue
                }
                var rawSum = 0
                for (index, value) in bucket.enumerated() {
                    if index.isMultiple(of: 256), !shouldContinue() { return nil }
                    rawSum += value.raw
                }
                let meanRaw = Double(rawSum) / Double(bucket.count)
                if let value = AtriaResearchProbe.decodeWhoop4SkinTemperatureRaw(
                    Int(meanRaw.rounded()),
                    sameDeviceAnchorRaw: anchor
                ) {
                    decoded.append(value)
                }
            }
            guard !decoded.isEmpty else {
                result.append(source)
                continue
            }
            var updated = source
            updated.skinTempResearchCandidateFrames = selected.value.count
            var candidateValueSum = 0
            for (index, value) in selected.value.enumerated() {
                if index.isMultiple(of: 256), !shouldContinue() { return nil }
                candidateValueSum += value.raw
            }
            updated.skinTempResearchCandidateValueSum = candidateValueSum
            updated.skinTempResearchCandidateValueCount = selected.value.count
            updated.decodedSkinTemperatureCelsius = decoded
            result.append(updated)
        }
        return shouldContinue() ? result : nil
    }

    nonisolated static func finalizedSkinTemperatureDeviationByMorningDay(sessions: [SavedSession],
                                                                          activeSessionID: UUID? = nil,
                                                                          calendar: Calendar = .current) -> [Date: Double] {
        var temperatureByDay: [Date: (sum: Double, count: Int)] = [:]
        for session in sessions {
            if let activeSessionID, session.id == activeSessionID { continue }
            let samples = session.decodedSkinTemperatureCelsius?.filter(\.isAggregationEligible)
            guard session.sleepWakeResearchState == "sleep_research",
                  let samples,
                  !samples.isEmpty else { continue }
            let day = morningMetricDay(for: session, calendar: calendar)
            var bucket = temperatureByDay[day] ?? (sum: 0, count: 0)
            bucket.sum += samples.reduce(0) { $0 + $1.celsius }
            bucket.count += samples.count
            temperatureByDay[day] = bucket
        }

        let dayMeans = temperatureByDay
            .compactMap { day, bucket -> (day: Date, meanCelsius: Double)? in
                guard bucket.count > 0 else { return nil }
                return (day: day, meanCelsius: bucket.sum / Double(bucket.count))
            }
            .sorted { $0.day < $1.day }

        var deviations: [Date: Double] = [:]
        var baselineMeanSum = 0.0
        var baselineDayCount = 0
        for dayMean in dayMeans {
            if baselineDayCount >= 3 {
                let baselineMean = baselineMeanSum / Double(baselineDayCount)
                deviations[dayMean.day] = dayMean.meanCelsius - baselineMean
            }
            baselineMeanSum += dayMean.meanCelsius
            baselineDayCount += 1
        }
        return deviations
    }

    nonisolated static func finalizedSkinTemperatureDeviationByMorningDayCancellable(
        sessions: [SavedSession],
        activeSessionID: UUID? = nil,
        calendar: Calendar = .current,
        shouldContinue: () -> Bool
    ) -> [Date: Double]? {
        var temperatureByDay: [Date: (sum: Double, count: Int)] = [:]
        for (sessionIndex, session) in sessions.enumerated() {
            if sessionIndex.isMultiple(of: 32), !shouldContinue() { return nil }
            if let activeSessionID, session.id == activeSessionID { continue }
            guard session.sleepWakeResearchState == "sleep_research",
                  let samples = session.decodedSkinTemperatureCelsius else {
                continue
            }
            var sum = 0.0
            var count = 0
            for (index, sample) in samples.enumerated() {
                if index.isMultiple(of: 256), !shouldContinue() { return nil }
                if sample.isAggregationEligible {
                    sum += sample.celsius
                    count += 1
                }
            }
            guard count > 0 else { continue }
            let day = morningMetricDay(for: session, calendar: calendar)
            let prior = temperatureByDay[day] ?? (0, 0)
            temperatureByDay[day] = (prior.sum + sum, prior.count + count)
        }
        var dayMeans: [(day: Date, meanCelsius: Double)] = []
        for (day, bucket) in temperatureByDay where bucket.count > 0 {
            guard shouldContinue() else { return nil }
            dayMeans.append((day, bucket.sum / Double(bucket.count)))
        }
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &dayMeans,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: { $0.day < $1.day }
        ) else { return nil }
        var deviations: [Date: Double] = [:]
        var baselineMeanSum = 0.0
        var baselineDayCount = 0
        for dayMean in dayMeans {
            guard shouldContinue() else { return nil }
            if baselineDayCount >= 3 {
                deviations[dayMean.day] = dayMean.meanCelsius
                    - baselineMeanSum / Double(baselineDayCount)
            }
            baselineMeanSum += dayMean.meanCelsius
            baselineDayCount += 1
        }
        return shouldContinue() ? deviations : nil
    }

    /// Recovered WHOOP rows are stored in all-day wear sessions, while sleep
    /// confirmation is durable in `UserConfirmedSleep`. Join those two
    /// authorities directly so a confirmed night does not lose valid
    /// temperature merely because the containing session is not itself tagged
    /// as a sleep-research session.
    struct RecoveredSkinTemperatureProjection: Equatable {
        let deviations: [Date: Double]
        let baselineNightCount: Int

        static let empty = RecoveredSkinTemperatureProjection(
            deviations: [:],
            baselineNightCount: 0
        )
    }

    nonisolated static func recoveredSkinTemperatureProjection(
        points: [HistoricalArchive.SkinTemperatureRawPoint],
        confirmedSleeps: [UserConfirmedSleep],
        calendar: Calendar = .current
    ) -> RecoveredSkinTemperatureProjection {
        recoveredSkinTemperatureProjectionCancellable(
            points: points,
            confirmedSleeps: confirmedSleeps,
            calendar: calendar,
            shouldContinue: { true }
        ) ?? .empty
    }

    nonisolated static func recoveredSkinTemperatureProjectionCancellable(
        points: [HistoricalArchive.SkinTemperatureRawPoint],
        confirmedSleeps: [UserConfirmedSleep],
        calendar: Calendar = .current,
        shouldContinue: () -> Bool
    ) -> RecoveredSkinTemperatureProjection? {
        guard !points.isEmpty, !confirmedSleeps.isEmpty else { return .empty }
        let unknownDevice = "<unknown>"
        func deviceKey(_ identifier: String?) -> String {
            let normalized = identifier?
                .trimmingCharacters(in: .whitespacesAndNewlines)
                .lowercased() ?? ""
            return normalized.isEmpty ? unknownDevice : normalized
        }
        guard shouldContinue() else { return nil }
        var pointsByDevice: [String: [HistoricalArchive.SkinTemperatureRawPoint]] = [:]
        for (index, point) in points.enumerated() {
            if index.isMultiple(of: 256), !shouldContinue() { return nil }
            pointsByDevice[deviceKey(point.strapIdentifier), default: []]
                .append(point)
        }
        for key in Array(pointsByDevice.keys) {
            guard shouldContinue() else { return nil }
            guard var values = pointsByDevice[key],
                  AtriaSleepCooperativeAlgorithms.stableSort(
                    &values,
                    shouldContinue: shouldContinue,
                    areInIncreasingOrder: { $0.t < $1.t }
                  ) else { return nil }
            pointsByDevice[key] = values
        }
        var anchors: [String: Double] = [:]
        for (key, values) in pointsByDevice {
            var raw: [Int] = []
            raw.reserveCapacity(values.count)
            for (index, value) in values.enumerated() {
                if index.isMultiple(of: 256), !shouldContinue() { return nil }
                raw.append(value.raw)
            }
            if let anchor = AtriaResearchProbe
                .whoop4SkinTemperatureAnchorRawCancellable(
                    raw,
                    shouldContinue: shouldContinue
                ) {
                anchors[key] = anchor
            }
            guard shouldContinue() else { return nil }
        }
        guard !anchors.isEmpty else { return .empty }

        func lowerBound(
            _ values: [HistoricalArchive.SkinTemperatureRawPoint],
            _ target: Date
        ) -> Int {
            var low = 0
            var high = values.count
            while low < high {
                let middle = low + (high - low) / 2
                if values[middle].t < target {
                    low = middle + 1
                } else {
                    high = middle
                }
            }
            return low
        }

        var temperatureByDay: [Date: (sum: Double, count: Int)] = [:]
        for (sleepIndex, sleep) in confirmedSleeps.enumerated()
        where sleep.end > sleep.start
            && !sleep.source.lowercased().contains("nap") {
            if sleepIndex.isMultiple(of: 16), !shouldContinue() { return nil }
            let candidates = pointsByDevice.compactMap { key, values
                -> (key: String, value: ArraySlice<HistoricalArchive.SkinTemperatureRawPoint>)? in
                let start = lowerBound(values, sleep.start)
                let end = lowerBound(values, sleep.end.addingTimeInterval(0.001))
                guard end > start, anchors[key] != nil else { return nil }
                return (key, values[start..<end])
            }
            guard let selected = candidates.sorted(by: {
                if $0.value.count != $1.value.count {
                    return $0.value.count > $1.value.count
                }
                return $0.key < $1.key
            }).first,
            let anchor = anchors[selected.key] else { continue }

            var decoded: [AtriaResearchProbe.DecodedSkinTemperatureCelsius] = []
            decoded.reserveCapacity(selected.value.count)
            for (index, value) in selected.value.enumerated() {
                if index.isMultiple(of: 256), !shouldContinue() { return nil }
                if let temperature = AtriaResearchProbe.decodeWhoop4SkinTemperatureRaw(
                    value.raw,
                    sameDeviceAnchorRaw: anchor
                ), temperature.isAggregationEligible {
                    decoded.append(temperature)
                }
            }
            guard !decoded.isEmpty else { continue }
            let day = calendar.startOfDay(for: sleep.end)
            var bucket = temperatureByDay[day] ?? (sum: 0, count: 0)
            for (index, value) in decoded.enumerated() {
                if index.isMultiple(of: 256), !shouldContinue() { return nil }
                bucket.sum += value.celsius
            }
            bucket.count += decoded.count
            temperatureByDay[day] = bucket
        }

        guard shouldContinue() else { return nil }
        let dayMeans = temperatureByDay.compactMap {
            day, bucket -> (day: Date, meanCelsius: Double)? in
            guard bucket.count > 0 else { return nil }
            return (day, bucket.sum / Double(bucket.count))
        }.sorted { $0.day < $1.day }
        guard shouldContinue() else { return nil }
        var deviations: [Date: Double] = [:]
        var baselineMeanSum = 0.0
        var baselineDayCount = 0
        for (index, dayMean) in dayMeans.enumerated() {
            if index.isMultiple(of: 64), !shouldContinue() { return nil }
            if baselineDayCount >= 3 {
                deviations[dayMean.day] =
                    dayMean.meanCelsius - baselineMeanSum / Double(baselineDayCount)
            }
            baselineMeanSum += dayMean.meanCelsius
            baselineDayCount += 1
        }
        guard shouldContinue() else { return nil }
        return RecoveredSkinTemperatureProjection(
            deviations: deviations,
            baselineNightCount: dayMeans.count
        )
    }

    nonisolated static func finalizedSkinTemperatureDeviationByMorningDay(
        points: [HistoricalArchive.SkinTemperatureRawPoint],
        confirmedSleeps: [UserConfirmedSleep],
        calendar: Calendar = .current
    ) -> [Date: Double] {
        recoveredSkinTemperatureProjection(
            points: points,
            confirmedSleeps: confirmedSleeps,
            calendar: calendar
        ).deviations
    }

    /// Recovery and Sleep presentation share one evidence authority. The raw
    /// value on an HR-only night is capture/span coverage and must never enter
    /// a score, preview, cache fingerprint, or frozen receipt as if motion had
    /// established time asleep.
    nonisolated static func recoverySleepEfficiency(
        from night: SleepHistorySnapshot.Night?
    ) -> Double? {
        night?.displaySleepEfficiency
    }

    nonisolated static func makeSavedDailyMetrics(rollups: [DailyRollup],
                                                          sleep: SleepHistorySnapshot,
                                                          baseline: PersonalBaseline,
                                                          sessions: [SavedSession] = [],
                                                          activeSessionID: UUID? = nil,
                                                          skinTemperatureDeviationByDay: [Date: Double]? = nil,
                                                          calendar: Calendar = .current) -> [SavedDailyMetric] {
        // Overnight recovery must never be sourced from a nap or an
        // unqualified short rest. Use the exact shared source/bounds/coverage
        // gate as the physiological cycle, then key the night by its canonical
        // final wake in the event time zone. A linked resumed segment may move
        // that final wake across civil midnight while `Night.day` intentionally
        // retains the original main record's Activity identity.
        var sleepByDay: [Date: SleepHistorySnapshot.Night] = [:]
        for night in sleep.nights {
            guard confirmedSleepIsPhysiologicalMainSleep(night) else { continue }
            let day = morningMetricDay(for: night, calendar: calendar)
            if let existing = sleepByDay[day] {
                if physiologicalMainSleepNight(
                    night,
                    isPreferredTo: existing
                ) {
                    sleepByDay[day] = night
                }
            } else {
                sleepByDay[day] = night
            }
        }
        // A day can hold more than one distinct main sleep — a user who slept
        // twice (a short overnight plus a long, fragmented daytime sleep) has a
        // second confirmed main that lost the single-canonical-per-day race and
        // now lives in `additionalMainNights`. Its effective hours must still be
        // credited to the day's TOTAL sleep, even though recovery/HRV/stages stay
        // sourced from the one canonical night. Resumed segments are already
        // folded into the canonical night's duration, so exclude them here to
        // avoid double-counting; apply the same physiological-main gate the
        // canonical loop uses so only durable mains contribute.
        var additionalMainSecondsByDay: [Date: TimeInterval] = [:]
        for extra in sleep.additionalMainNights {
            guard extra.source != "resumed_sleep",
                  confirmedSleepIsPhysiologicalMainSleep(extra) else { continue }
            let day = morningMetricDay(for: extra, calendar: calendar)
            additionalMainSecondsByDay[day, default: 0] += extra.duration
        }
        let resolvedSkinTemperatureDeviationByDay = skinTemperatureDeviationByDay
            ?? finalizedSkinTemperatureDeviationByMorningDay(sessions: sessions,
                                                             activeSessionID: activeSessionID,
                                                             calendar: calendar)
        // Preserve the first authoritative row for a normalized civil day,
        // matching mergeDailyMetricHistory's existing duplicate-day contract.
        // This also prevents two travel-rematerialized rows from emitting two
        // persisted metrics with the same daily identity.
        var rollupByDay: [Date: DailyRollup] = [:]
        for rollup in rollups {
            let day = calendar.startOfDay(for: rollup.day)
            if rollupByDay[day] == nil {
                rollupByDay[day] = rollup
            }
        }
        let projectionDays = Set(rollupByDay.keys)
            .union(sleepByDay.keys)

        // A confirmed main sleep is independently durable physiological
        // evidence. Do not require a session-derived activity rollup to exist
        // for the same civil day before publishing its frozen sleep, RHR, HRV,
        // respiration and recovery fields. A sleep-only day keeps activity
        // fields nil; no strain or coverage is inferred from the sleep record.
        return projectionDays
            .sorted(by: >)
            .map { day in
                let rollup = rollupByDay[day]
                let night = sleepByDay[day]
                // Confirmed main sleep is the authoritative historical source.
                // DailyRollup is session-start-day based and can legitimately
                // lack the sleep/HRV fields for an overnight session whose wake
                // belongs to this morning. Project the confirmed record onto its
                // morning day before scoring and persistence; candidates and naps
                // remain evidence-only and can never mint recovery history.
                let hrv = night?.hrv.flatMap { $0 > 0 ? $0 : nil }
                let restingHR = night?.restingHR.flatMap { $0 > 0 ? $0 : nil }
                let respiratoryRate = night?.respiratoryRate.flatMap { $0 > 0 ? $0 : nil }
                // Recovery is a single-main physiological score — keep its sleep
                // duration on the canonical night. The persisted/displayed total
                // additionally credits every other same-day main's effective hours.
                let canonicalSleepDuration = night.map(\.duration)
                let additionalMainSeconds = additionalMainSecondsByDay[day] ?? 0
                let totalSleepDuration: TimeInterval? = {
                    let combined = (canonicalSleepDuration ?? 0) + additionalMainSeconds
                    return combined > 0 ? combined : nil
                }()
                let sleepSpan = night.flatMap { night -> TimeInterval? in
                    guard let start = night.start, let end = night.end, end > start else { return nil }
                    return end.timeIntervalSince(start)
                }
                let recovery = Metrics.recoveryV2(hrvSnapshot: nil,
                                                  fallbackRMSSD: hrv,
                                                  restingNow: restingHR,
                                                  baseline: baseline,
                                                  hrvReferenceValidated: false,
                                                  // Stored HR-only "efficiency" is capture/span
                                                  // coverage, not measured sleep efficiency. The
                                                  // same motion authority that controls the Sleep UI
                                                  // must control Recovery; otherwise an honest "--"
                                                  // tile can still silently boost the score as 100%.
                                                  sleepEfficiency: recoverySleepEfficiency(from: night),
                                                  sleepDurationHours: canonicalSleepDuration.map { $0 / 3_600 },
                                                  sleepBaseline: sleep.sleepBaselineStats,
                                                  respiratoryRate: respiratoryRate,
                                                  respiratoryBaseline: sleep.respiratoryBaselineStats)
                return SavedDailyMetric(day: day,
                                        recoveryPercent: recovery.percent,
                                        recoveryConfidence: recovery.confidence.rawValue,
                                        hrv: hrv,
                                        restingHR: restingHR,
                                        respiratoryRate: respiratoryRate,
                                        sleepDuration: totalSleepDuration,
                                        sleepSpan: sleepSpan,
                                        sleepStart: night?.start,
                                        sleepEnd: night?.end,
                                        sleepSource: night?.source,
                                        sleepStageSegments: night?.stageSegmentsForStorage ?? [],
                                        sleepConsistencyPercent: sleep.sleepConsistencyPercent(
                                            asOf: day,
                                            calendar: calendar
                                        ),
                                        strain: rollup.flatMap { $0.strain > 0 ? $0.strain : nil },
                                        strainCoverageFraction: rollup?.strainCoverageFraction,
                                        strainEvidenceQuality: rollup?.strainEvidenceQuality,
                                        dayTRIMP: rollup?.trimp,
                                        skinTemperatureDeviationCelsius: resolvedSkinTemperatureDeviationByDay[day],
                                        // This bulk historical rebuild may run
                                        // after the personal baseline has
                                        // changed. Keep its derived summary
                                        // inspectable, but do not mint a new
                                        // versioned receipt for an older night.
                                        recoverySummary: FrozenRecoverySummary(estimate: recovery, scoredDay: day))
            }
    }

    nonisolated static func makeSavedDailyMetricsCancellable(
        rollups: [DailyRollup],
        sleep: SleepHistorySnapshot,
        baseline: PersonalBaseline,
        sessions: [SavedSession] = [],
        activeSessionID: UUID? = nil,
        skinTemperatureDeviationByDay: [Date: Double]? = nil,
        calendar: Calendar = .current,
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> [SavedDailyMetric]? {
        guard shouldContinue() else { return nil }
        var sleepByDay: [Date: SleepHistorySnapshot.Night] = [:]
        for (index, night) in sleep.nights.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            guard confirmedSleepIsPhysiologicalMainSleep(night) else {
                continue
            }
            let day = morningMetricDay(for: night, calendar: calendar)
            if let existing = sleepByDay[day] {
                if physiologicalMainSleepNight(night, isPreferredTo: existing) {
                    sleepByDay[day] = night
                }
            } else {
                sleepByDay[day] = night
            }
        }
        let resolvedSkin: [Date: Double]
        if let skinTemperatureDeviationByDay {
            resolvedSkin = skinTemperatureDeviationByDay
        } else {
            guard let prepared =
                    finalizedSkinTemperatureDeviationByMorningDayCancellable(
                        sessions: sessions,
                        activeSessionID: activeSessionID,
                        calendar: calendar,
                        shouldContinue: shouldContinue
                    ) else { return nil }
            resolvedSkin = prepared
        }
        var rollupByDay: [Date: DailyRollup] = [:]
        for (index, rollup) in rollups.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            let day = calendar.startOfDay(for: rollup.day)
            if rollupByDay[day] == nil { rollupByDay[day] = rollup }
        }
        var days = Array(Set(rollupByDay.keys).union(sleepByDay.keys))
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &days,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: >
        ) else { return nil }
        var metrics: [SavedDailyMetric] = []
        metrics.reserveCapacity(days.count)
        for (index, day) in days.enumerated() {
            if index.isMultiple(of: 16), !shouldContinue() { return nil }
            let rollup = rollupByDay[day]
            let night = sleepByDay[day]
            let hrv = night?.hrv.flatMap { $0 > 0 ? $0 : nil }
            let restingHR = night?.restingHR.flatMap { $0 > 0 ? $0 : nil }
            let respiratoryRate = night?.respiratoryRate.flatMap {
                $0 > 0 ? $0 : nil
            }
            let sleepDuration = night.map(\.duration)
            let sleepSpan = night.flatMap { night -> TimeInterval? in
                guard let start = night.start,
                      let end = night.end,
                      end > start else { return nil }
                return end.timeIntervalSince(start)
            }
            let recovery = Metrics.recoveryV2(
                hrvSnapshot: nil,
                fallbackRMSSD: hrv,
                restingNow: restingHR,
                baseline: baseline,
                hrvReferenceValidated: false,
                sleepEfficiency: recoverySleepEfficiency(from: night),
                sleepDurationHours: sleepDuration.map { $0 / 3_600 },
                sleepBaseline: sleep.sleepBaselineStats,
                respiratoryRate: respiratoryRate,
                respiratoryBaseline: sleep.respiratoryBaselineStats
            )
            guard shouldContinue() else { return nil }
            metrics.append(SavedDailyMetric(
                day: day,
                recoveryPercent: recovery.percent,
                recoveryConfidence: recovery.confidence.rawValue,
                hrv: hrv,
                restingHR: restingHR,
                respiratoryRate: respiratoryRate,
                sleepDuration: sleepDuration,
                sleepSpan: sleepSpan,
                sleepStart: night?.start,
                sleepEnd: night?.end,
                sleepSource: night?.source,
                sleepStageSegments: night?.stageSegmentsForStorage ?? [],
                sleepConsistencyPercent: sleep.sleepConsistencyPercent(
                    asOf: day,
                    calendar: calendar
                ),
                strain: rollup.flatMap { $0.strain > 0 ? $0.strain : nil },
                strainCoverageFraction: rollup?.strainCoverageFraction,
                strainEvidenceQuality: rollup?.strainEvidenceQuality,
                dayTRIMP: rollup?.trimp,
                skinTemperatureDeviationCelsius: resolvedSkin[day],
                recoverySummary: FrozenRecoverySummary(
                    estimate: recovery,
                    scoredDay: day
                )
            ))
        }
        return shouldContinue() ? metrics : nil
    }

    /// Restores measured facts a recompute could not observe.
    ///
    /// Only ever fills a nil — it can never overwrite a value the rebuild
    /// derived, and it can never invent one neither row holds.
    nonisolated static func dailyMetricPreservingMeasuredFacts(
        rebuilt: SavedDailyMetric,
        existing: SavedDailyMetric
    ) -> SavedDailyMetric {
        guard rebuilt.restingHR == nil, existing.restingHR != nil else {
            return rebuilt
        }
        var preserved = rebuilt
        preserved.restingHR = existing.restingHR
        return preserved
    }

    /// Whether the scored night's recovery inputs differ between the preserved
    /// frozen daily row and a fresh recompute — i.e. a sleep confirm / EXTEND /
    /// adjust re-derived today's overnight readiness, so the preserved recovery
    /// would go stale (2026-07-08). Compares ONLY the frozen overnight inputs to
    /// recovery (the sleep window + HRV/RHR/respiratory), never live/drifting
    /// values, so intra-day drift can't trigger a re-mint.
    nonisolated static func dailyRecoveryInputsChanged(frozen: SavedDailyMetric,
                                                       fresh: SavedDailyMetric) -> Bool {
        frozen.sleepEnd != fresh.sleepEnd
            || frozen.sleepDuration != fresh.sleepDuration
            || frozen.sleepSpan != fresh.sleepSpan
            || frozen.hrv != fresh.hrv
            || frozen.restingHR != fresh.restingHR
            || frozen.respiratoryRate != fresh.respiratoryRate
    }

    /// A confirmed night is the authoritative source for the frozen morning
    /// inputs. When it still matches the persisted row exactly, rebuilding the
    /// same recovery would only rescan long-wear sessions and RR archives.
    nonisolated static func frozenRecoveryMatchesConfirmedNight(
        frozen: SavedDailyMetric,
        night: SleepHistorySnapshot.Night
    ) -> Bool {
        DailyRecoveryResolver.metricMatchesConfirmedNight(frozen, night: night)
    }

    nonisolated static func mergeDailyMetricHistory(existing: [SavedDailyMetric],
                                                            computed: [SavedDailyMetric],
                                                            sessions: [SavedSession],
                                                            sleep: SleepHistorySnapshot,
                                                            baseline: PersonalBaseline,
                                                            maxHR: Int,
                                                            now: Date,
                                                            skinTemperatureDeviationByDay: [Date: Double]? = nil,
                                                            skinTemperatureSourceValidated: Bool = AtriaResearchProbe.validatedSkinTemperatureDecoderAvailable,
                                                            authoritativeDays: Set<Date> = [],
                                                            calendar: Calendar = .current) -> [SavedDailyMetric] {
        let today = calendar.startOfDay(for: now)
        let normalizedAuthoritativeDays = Set(authoritativeDays.map { calendar.startOfDay(for: $0) })
        // A history rebuild can temporarily contain more than one timestamp for
        // the same civil day (for example after a time-zone migration or while
        // incremental and retained rollups overlap). This boundary owns the
        // day-normalization, so it must also make that normalization safe.
        // Preserve the pipeline's first computed row rather than trapping or
        // inventing a hybrid recovery snapshot from two competing records.
        var merged = Dictionary(
            computed.map { (calendar.startOfDay(for: $0.day), $0) },
            uniquingKeysWith: { existing, _ in existing }
        )

        for metric in existing {
            let day = calendar.startOfDay(for: metric.day)
            guard merged[day] == nil, !normalizedAuthoritativeDays.contains(day) else { continue }
            merged[day] = metric
        }

        if let frozenToday = existing.first(where: { calendar.isDate($0.day, inSameDayAs: today) }) {
            // Once today's morning reading settles, preserve that frozen readiness
            // snapshot (HRV/RHR/sleep → recovery) for the rest of the day instead of
            // recomputing on refresh. Strain is a cumulative, all-day total (not an
            // overnight readiness reading) and must keep accruing as later sessions
            // land, or the displayed number silently stops climbing after the first
            // refresh of the day — recompute it fresh each time from the same-day
            // computed rollup.
            let freshToday = computed.first { calendar.isDate($0.day, inSameDayAs: today) }
            // BUT if the scored NIGHT itself changed (a sleep confirm / EXTEND / adjust
            // re-derives today's overnight inputs — e.g. the 2026-07-08 sleep-expand
            // path moving the night's end), the preserved recovery would go STALE.
            // Re-mint the frozen readiness from the CURRENT night via the same stable
            // minter so the persisted recovery + trend point never outlive the night
            // they describe.
            let todayIsAuthoritative = normalizedAuthoritativeDays.contains(today)
            let confirmedNight = canonicalPhysiologicalMainSleepNight(
                for: today,
                in: sleep.nights,
                completedBy: now,
                calendar: calendar
            )
            let confirmedNightStillMatches = confirmedNight.map {
                frozenRecoveryMatchesConfirmedNight(frozen: frozenToday, night: $0)
            } ?? false
            let frozenLimitedFallbackIsAuthoritative = confirmedNight == nil
                && DailyRecoveryResolver.limitedFallbackMetricIsStructurallyAuthoritative(
                    frozenToday,
                    day: today,
                    calendar: calendar
                )
            // Model upgrades must repair a previously blank morning without
            // requiring the user to edit an otherwise identical sleep. Also
            // repair the short-lived recovery_v2 persistence bug that could
            // freeze `usesHRV = true` even though the same row had no current
            // HRV measurement. Keep the repair narrow: it requires a matching
            // confirmed main sleep and contradictory persisted provenance. A
            // valid existing score remains frozen for the physiological day.
            let blankRecoveryNeedsMint = frozenToday.recoveryPercent == nil
                && confirmedNight?.confirmed == true
            let missingHRVProvenanceNeedsMint = frozenToday.hrv == nil
                && frozenToday.recoverySummary?.usesHRV == true
                && confirmedNight?.confirmed == true
            let freshMorning = todayIsAuthoritative
                    || (!frozenLimitedFallbackIsAuthoritative
                        && (!confirmedNightStillMatches
                            || blankRecoveryNeedsMint
                            || missingHRVProvenanceNeedsMint))
                ? makeMorningFrozenDailyMetric(for: today,
                                               computed: computed,
                                               sessions: sessions,
                                               sleep: sleep,
                                               baseline: baseline,
                                               maxHR: maxHR,
                                               now: now,
                                               skinTemperatureDeviationByDay: skinTemperatureDeviationByDay,
                                               skinTemperatureSourceValidated: skinTemperatureSourceValidated,
                                               calendar: calendar)
                : nil
            if todayIsAuthoritative, freshMorning == nil {
                merged.removeValue(forKey: today)
                return merged.values.sorted { $0.day > $1.day }
            }
            let base: SavedDailyMetric = if todayIsAuthoritative {
                freshMorning ?? frozenToday
            } else if let freshMorning,
                      blankRecoveryNeedsMint
                        || missingHRVProvenanceNeedsMint
                        || dailyRecoveryInputsChanged(frozen: frozenToday, fresh: freshMorning) {
                freshMorning
            } else {
                frozenToday
            }
            merged[today] = SavedDailyMetric(day: base.day,
                                             recoveryPercent: base.recoveryPercent,
                                             recoveryConfidence: base.recoveryConfidence,
                                             hrv: base.hrv,
                                             restingHR: base.restingHR,
                                             respiratoryRate: base.respiratoryRate,
                                             sleepDuration: base.sleepDuration,
                                             sleepNeedSeconds: base.sleepNeedSeconds,
                                             sleepSpan: base.sleepSpan,
                                             sleepStart: base.sleepStart,
                                             sleepEnd: base.sleepEnd,
                                             sleepSource: base.sleepSource,
                                             sleepStageSegments: base.sleepStageSegments,
                                             sleepConsistencyPercent: base.sleepConsistencyPercent,
                                             strain: freshToday?.strain ?? base.strain,
                                             strainCoverageFraction: freshToday?.strainCoverageFraction
                                                ?? base.strainCoverageFraction,
                                             strainEvidenceQuality: freshToday?.strainEvidenceQuality
                                                ?? base.strainEvidenceQuality,
                                             dayTRIMP: freshToday?.dayTRIMP ?? base.dayTRIMP,
                                             skinTemperatureDeviationCelsius: todayIsAuthoritative
                                                ? freshMorning?.skinTemperatureDeviationCelsius
                                                : (freshToday?.skinTemperatureDeviationCelsius ?? base.skinTemperatureDeviationCelsius),
                                             recoverySummary: base.recoverySummary)
        } else if let settledMorning = makeMorningFrozenDailyMetric(for: today,
                                                                    computed: computed,
                                                                    sessions: sessions,
                                                                    sleep: sleep,
                                                                    baseline: baseline,
                                                                    maxHR: maxHR,
                                                                    now: now,
                                                                    skinTemperatureDeviationByDay: skinTemperatureDeviationByDay,
                                                                    skinTemperatureSourceValidated: skinTemperatureSourceValidated,
                                                                    calendar: calendar) {
            merged[today] = settledMorning
        } else {
            // Never write today's chart point before the overnight/morning reading
            // exists; otherwise the detail charts drift from the WHOOP-like freeze.
            merged.removeValue(forKey: today)
        }

        return merged.values.sorted { $0.day > $1.day }
    }

    nonisolated static func mergeDailyMetricHistoryCancellable(
        existing: [SavedDailyMetric],
        computed: [SavedDailyMetric],
        sessions: [SavedSession],
        sleep: SleepHistorySnapshot,
        baseline: PersonalBaseline,
        maxHR: Int,
        now: Date,
        skinTemperatureDeviationByDay: [Date: Double]? = nil,
        skinTemperatureSourceValidated: Bool =
            AtriaResearchProbe.validatedSkinTemperatureDecoderAvailable,
        authoritativeDays: Set<Date> = [],
        calendar: Calendar = .current,
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> [SavedDailyMetric]? {
        guard shouldContinue() else { return nil }
        let today = calendar.startOfDay(for: now)
        var normalizedAuthoritativeDays = Set<Date>()
        for day in authoritativeDays {
            guard shouldContinue() else { return nil }
            normalizedAuthoritativeDays.insert(calendar.startOfDay(for: day))
        }
        var merged: [Date: SavedDailyMetric] = [:]
        for (index, metric) in computed.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            let day = calendar.startOfDay(for: metric.day)
            if merged[day] == nil { merged[day] = metric }
        }
        var frozenToday: SavedDailyMetric?
        for (index, metric) in existing.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            let day = calendar.startOfDay(for: metric.day)
            if merged[day] == nil,
               !normalizedAuthoritativeDays.contains(day) {
                merged[day] = metric
            } else if let rebuilt = merged[day],
                      !normalizedAuthoritativeDays.contains(day) {
                // A rebuild that cannot OBSERVE a measured fact must not assert
                // its absence.
                //
                // `preparedDailyMetricHistory` derives `restingHR` from the
                // confirmed main-sleep night alone (`night?.restingHR`), but it
                // emits a row for every day carrying any session rollup. So on a
                // day with wear but no confirmed night — an HR-only night, or a
                // night still behind the drain frontier — the recompute produces
                // a row whose `restingHR` is nil, and seeding `merged` from
                // `computed` first then discarded the existing row that held a
                // real `wearRestingHR` measurement.
                //
                // Measured on device 2026-08-19: restingHR was present on only
                // 27 of 43 days (63 %), and 08-19 still carried `rhr = 68` with
                // no confirmed sleep — a wear-derived value the next rebuild
                // would have erased. That starves the whole measured-HR insight
                // chain (`DailyRollupVitals.rhr` trailing-28-day Welford ->
                // `AtriaHighlights.lowerRestingHeartRate` and
                // `healthDeviationDecision`, both of which need a minimum n),
                // which is the real mechanism behind field report item 13.
                //
                // Carry forward only facts the recompute left nil, and only for
                // non-authoritative days. A day the caller declared
                // authoritative still replaces wholesale, and any value the
                // rebuild DID derive still wins.
                merged[day] = Self.dailyMetricPreservingMeasuredFacts(
                    rebuilt: rebuilt,
                    existing: metric
                )
            }
            if frozenToday == nil,
               calendar.isDate(metric.day, inSameDayAs: today) {
                frozenToday = metric
            }
        }

        if let frozenToday {
            let freshToday = computed.first {
                calendar.isDate($0.day, inSameDayAs: today)
            }
            guard shouldContinue() else { return nil }
            let todayIsAuthoritative = normalizedAuthoritativeDays
                .contains(today)
            let confirmedNight = canonicalPhysiologicalMainSleepNight(
                for: today,
                in: sleep.nights,
                completedBy: now,
                calendar: calendar
            )
            let confirmedNightStillMatches = confirmedNight.map {
                frozenRecoveryMatchesConfirmedNight(
                    frozen: frozenToday,
                    night: $0
                )
            } ?? false
            let frozenLimitedFallbackIsAuthoritative = confirmedNight == nil
                && DailyRecoveryResolver
                    .limitedFallbackMetricIsStructurallyAuthoritative(
                        frozenToday,
                        day: today,
                        calendar: calendar
                    )
            let blankRecoveryNeedsMint = frozenToday.recoveryPercent == nil
                && confirmedNight?.confirmed == true
            let missingHRVProvenanceNeedsMint = frozenToday.hrv == nil
                && frozenToday.recoverySummary?.usesHRV == true
                && confirmedNight?.confirmed == true
            let needsFreshMorning = todayIsAuthoritative
                || (!frozenLimitedFallbackIsAuthoritative
                    && (!confirmedNightStillMatches
                        || blankRecoveryNeedsMint
                        || missingHRVProvenanceNeedsMint))
            let freshMorning = needsFreshMorning
                ? makeMorningFrozenDailyMetric(
                    for: today,
                    computed: computed,
                    sessions: sessions,
                    sleep: sleep,
                    baseline: baseline,
                    maxHR: maxHR,
                    now: now,
                    skinTemperatureDeviationByDay:
                        skinTemperatureDeviationByDay,
                    skinTemperatureSourceValidated:
                        skinTemperatureSourceValidated,
                    calendar: calendar,
                    shouldContinue: shouldContinue
                )
                : nil
            guard shouldContinue() else { return nil }
            if todayIsAuthoritative, freshMorning == nil {
                merged.removeValue(forKey: today)
            } else {
                let base: SavedDailyMetric
                if todayIsAuthoritative {
                    base = freshMorning ?? frozenToday
                } else if let freshMorning,
                          blankRecoveryNeedsMint
                            || missingHRVProvenanceNeedsMint
                            || dailyRecoveryInputsChanged(
                                frozen: frozenToday,
                                fresh: freshMorning
                            ) {
                    base = freshMorning
                } else {
                    base = frozenToday
                }
                merged[today] = SavedDailyMetric(
                    day: base.day,
                    recoveryPercent: base.recoveryPercent,
                    recoveryConfidence: base.recoveryConfidence,
                    hrv: base.hrv,
                    restingHR: base.restingHR,
                    respiratoryRate: base.respiratoryRate,
                    sleepDuration: base.sleepDuration,
                    sleepNeedSeconds: base.sleepNeedSeconds,
                    sleepSpan: base.sleepSpan,
                    sleepStart: base.sleepStart,
                    sleepEnd: base.sleepEnd,
                    sleepSource: base.sleepSource,
                    sleepStageSegments: base.sleepStageSegments,
                    sleepConsistencyPercent: base.sleepConsistencyPercent,
                    strain: freshToday?.strain ?? base.strain,
                    strainCoverageFraction: freshToday?.strainCoverageFraction
                        ?? base.strainCoverageFraction,
                    strainEvidenceQuality: freshToday?.strainEvidenceQuality
                        ?? base.strainEvidenceQuality,
                    dayTRIMP: freshToday?.dayTRIMP ?? base.dayTRIMP,
                    skinTemperatureDeviationCelsius: todayIsAuthoritative
                        ? freshMorning?.skinTemperatureDeviationCelsius
                        : (freshToday?.skinTemperatureDeviationCelsius
                            ?? base.skinTemperatureDeviationCelsius),
                    recoverySummary: base.recoverySummary
                )
            }
        } else if let settledMorning = makeMorningFrozenDailyMetric(
            for: today,
            computed: computed,
            sessions: sessions,
            sleep: sleep,
            baseline: baseline,
            maxHR: maxHR,
            now: now,
            skinTemperatureDeviationByDay: skinTemperatureDeviationByDay,
            skinTemperatureSourceValidated: skinTemperatureSourceValidated,
            calendar: calendar,
            shouldContinue: shouldContinue
        ) {
            merged[today] = settledMorning
        } else {
            guard shouldContinue() else { return nil }
            merged.removeValue(forKey: today)
        }
        var result = Array(merged.values)
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &result,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: { $0.day > $1.day }
        ) else { return nil }
        return shouldContinue() ? result : nil
    }

    /// GAP-06: the motion-qualified display efficiency per morning day, from
    /// the snapshot's confirmed main-sleep nights. Only qualified values are
    /// present — an HR-only night simply has no efficiency component.
    nonisolated static func displaySleepEfficiencyByMorningDay(
        sleep: SleepHistorySnapshot,
        calendar: Calendar = .current
    ) -> [Date: Double] {
        sleep.nights.reduce(into: [:]) { result, night in
            guard night.confirmed,
                  !night.isNapEvidence,
                  let efficiency = night.displaySleepEfficiency else { return }
            result[calendar.startOfDay(for: night.day)] = efficiency
        }
    }

    nonisolated static func makeDailyRollupStoreEntries(metrics: [SavedDailyMetric],
                                                                sessions: [SavedSession] = [],
                                                                rest: Int = 60,
                                                                maxHR: Int = 190,
                                                                napHoursByDay: [Date: Double] = [:],
                                                                respiratoryRateByMorningDay: [Date: Double]? = nil,
                                                                displaySleepEfficiencyByDay: [Date: Double] = [:],
                                                                calendar: Calendar = .current) -> [DailyRollupStoreEntry] {
        let sorted = metrics.sorted { $0.day < $1.day }
        let fallbackRespiratoryRates = respiratoryRateByMorningDay
            ?? makeDailyRespiratoryRatePreparation(sessions: sessions,
                                                   rest: rest,
                                                   maxHR: maxHR,
                                                   calendar: calendar).respiratoryRateByMorningDay
        let resolvedRespiratoryRates = sorted.map { metric -> Double? in
            if let respiratoryRate = metric.respiratoryRate, respiratoryRate > 0 {
                return respiratoryRate
            }
            guard let sleepDuration = metric.sleepDuration,
                  sleepDuration > 0,
                  let sleepStart = metric.sleepStart,
                  let sleepEnd = metric.sleepEnd,
                  sleepEnd > sleepStart,
                  metric.sleepSource?.isEmpty == false else {
                return nil
            }
            let day = calendar.startOfDay(for: metric.day)
            return fallbackRespiratoryRates[day]
        }
        return sorted.enumerated().map { index, metric in
            let priorAndCurrent = Array(sorted[max(0, index - 27)...index])
            let priorAndCurrentRespiratoryRates = resolvedRespiratoryRates[max(0, index - 27)...index].compactMap { $0 }
            let hrvMilliseconds = metric.hrv.flatMap { $0 > 0 ? Double($0) : nil }
            let resolvedRespRate = resolvedRespiratoryRates[index]
            let sleepPerformance = metric.sleepNeedSeconds.flatMap { need -> Int? in
                guard let duration = metric.sleepDuration,
                      duration > 0,
                      need > 0 else { return nil }
                return AtriaSleepBudget.performancePercent(
                    slept: duration / 3_600,
                    needed: need / 3_600
                )
            }
            // GAP-06: the night's composite receipt, derived ONLY from frozen
            // inputs — Sufficiency from the frozen need receipt, Consistency
            // exactly as persisted on this day's metric (as-of that morning,
            // never today's rolling window), and motion-qualified efficiency.
            // Re-minting from the same inputs is deterministic, so a settled
            // night's stored score can only change through legitimate new
            // evidence (a user edit, or motion validating an HR-only night).
            let sleepScore = AtriaSleepScore.provisional(
                sufficiencyPercent: sleepPerformance.map(Double.init),
                consistencyPercent: metric.sleepConsistencyPercent.map(Double.init),
                efficiencyPercent: displaySleepEfficiencyByDay[calendar.startOfDay(for: metric.day)]
                    .map { $0 * 100 }
            )
            return DailyRollupStoreEntry(day: metric.day,
                                         recovery: metric.recoveryPercent,
                                         recoverySummary: metric.recoverySummary,
                                         lnRMSSD: hrvMilliseconds.map(log),
                                         rhr: metric.restingHR,
                                         sleepSeconds: metric.sleepDuration,
                                         sleepNeedSeconds: metric.sleepNeedSeconds,
                                         sleepPerformance: sleepPerformance,
                                         bedtimeMinutes: metric.sleepStart.map { bedtimeMinutes(from: $0, calendar: calendar) },
                                         strain: metric.strain,
                                         strainCoverageFraction: metric.strainCoverageFraction,
                                         strainEvidenceQuality: metric.strainEvidenceQuality,
                                         trimp: metric.dayTRIMP,
                                         respiratoryRate: resolvedRespRate,
                                         skinTemperatureDeviationCelsius: metric.skinTemperatureDeviationCelsius,
                                         vitals: DailyRollupVitals(
                                            rhr: welfordStat(priorAndCurrent.compactMap { $0.restingHR.map(Double.init) }),
                                            hrv: welfordStat(priorAndCurrent.compactMap { $0.hrv.map(Double.init) }),
                                            resp: welfordStat(priorAndCurrentRespiratoryRates)
                                         ),
                                         sleepScore: sleepScore,
                                         calendar: calendar)
        }
    }

    nonisolated static func makeDailyRollupStoreEntriesCancellable(
        metrics: [SavedDailyMetric],
        sessions: [SavedSession] = [],
        rest: Int = 60,
        maxHR: Int = 190,
        napHoursByDay: [Date: Double] = [:],
        respiratoryRateByMorningDay: [Date: Double]? = nil,
        displaySleepEfficiencyByDay: [Date: Double] = [:],
        calendar: Calendar = .current,
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> [DailyRollupStoreEntry]? {
        var sorted = metrics
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &sorted,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: { $0.day < $1.day }
        ) else { return nil }
        let fallbackRespiratoryRates: [Date: Double]
        if let respiratoryRateByMorningDay {
            fallbackRespiratoryRates = respiratoryRateByMorningDay
        } else {
            guard let prepared = makeDailyRespiratoryRatePreparationCancellable(
                sessions: sessions,
                rest: rest,
                maxHR: maxHR,
                calendar: calendar,
                shouldContinue: shouldContinue
            ) else { return nil }
            fallbackRespiratoryRates = prepared.respiratoryRateByMorningDay
        }
        var resolvedRates: [Double?] = []
        resolvedRates.reserveCapacity(sorted.count)
        for (index, metric) in sorted.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            if let rate = metric.respiratoryRate, rate > 0 {
                resolvedRates.append(rate)
                continue
            }
            guard let duration = metric.sleepDuration,
                  duration > 0,
                  let start = metric.sleepStart,
                  let end = metric.sleepEnd,
                  end > start,
                  metric.sleepSource?.isEmpty == false else {
                resolvedRates.append(nil)
                continue
            }
            resolvedRates.append(
                fallbackRespiratoryRates[
                    calendar.startOfDay(for: metric.day)
                ]
            )
        }
        var entries: [DailyRollupStoreEntry] = []
        entries.reserveCapacity(sorted.count)
        for (index, metric) in sorted.enumerated() {
            if index.isMultiple(of: 16), !shouldContinue() { return nil }
            let lower = max(0, index - 27)
            let priorAndCurrent = Array(sorted[lower...index])
            let priorRates = resolvedRates[lower...index].compactMap { $0 }
            let hrvMilliseconds = metric.hrv.flatMap {
                $0 > 0 ? Double($0) : nil
            }
            let sleepPerformance = metric.sleepNeedSeconds.flatMap { need -> Int? in
                guard let duration = metric.sleepDuration,
                      duration > 0,
                      need > 0 else { return nil }
                return AtriaSleepBudget.performancePercent(
                    slept: duration / 3_600,
                    needed: need / 3_600
                )
            }
            // GAP-06: the night's composite receipt, derived ONLY from frozen
            // inputs — identical to the non-cancellable entries builder.
            let sleepScore = AtriaSleepScore.provisional(
                sufficiencyPercent: sleepPerformance.map(Double.init),
                consistencyPercent: metric.sleepConsistencyPercent.map(Double.init),
                efficiencyPercent: displaySleepEfficiencyByDay[calendar.startOfDay(for: metric.day)]
                    .map { $0 * 100 }
            )
            entries.append(DailyRollupStoreEntry(
                day: metric.day,
                recovery: metric.recoveryPercent,
                recoverySummary: metric.recoverySummary,
                lnRMSSD: hrvMilliseconds.map(log),
                rhr: metric.restingHR,
                sleepSeconds: metric.sleepDuration,
                sleepNeedSeconds: metric.sleepNeedSeconds,
                sleepPerformance: sleepPerformance,
                bedtimeMinutes: metric.sleepStart.map {
                    bedtimeMinutes(from: $0, calendar: calendar)
                },
                strain: metric.strain,
                strainCoverageFraction: metric.strainCoverageFraction,
                strainEvidenceQuality: metric.strainEvidenceQuality,
                trimp: metric.dayTRIMP,
                respiratoryRate: resolvedRates[index],
                skinTemperatureDeviationCelsius:
                    metric.skinTemperatureDeviationCelsius,
                vitals: DailyRollupVitals(
                    rhr: welfordStat(priorAndCurrent.compactMap {
                        $0.restingHR.map(Double.init)
                    }),
                    hrv: welfordStat(priorAndCurrent.compactMap {
                        $0.hrv.map(Double.init)
                    }),
                    resp: welfordStat(priorRates)
                ),
                sleepScore: sleepScore,
                calendar: calendar
            ))
        }
        return shouldContinue() ? entries : nil
    }

    nonisolated static func makeDailyRespiratoryRatePreparation(sessions: [SavedSession],
                                                                rest: Int = 60,
                                                                maxHR: Int = 190,
                                                                calendar: Calendar = .current) -> DailyRespiratoryRatePreparation {
        var candidateCount = 0
        var ratesByMorningDay: [Date: [Double]] = [:]
        for session in sessions {
            guard let rate = session.sleepRespiratoryRate(rest: rest,
                                                          maxHR: maxHR,
                                                          calendar: calendar) else {
                continue
            }
            let day = morningMetricDay(for: session, calendar: calendar)
            ratesByMorningDay[day, default: []].append(rate)
            if session.rrPoints?.isEmpty == false {
                candidateCount += 1
            }
        }
        var averagedByMorningDay: [Date: Double] = [:]
        averagedByMorningDay.reserveCapacity(ratesByMorningDay.count)
        for (day, rates) in ratesByMorningDay {
            if let average = averageDoubleSnapshot(rates) {
                averagedByMorningDay[day] = average
            }
        }
        return DailyRespiratoryRatePreparation(respiratoryRateByMorningDay: averagedByMorningDay,
                                               candidateCount: candidateCount)
    }

    nonisolated static func makeDailyRespiratoryRatePreparationCancellable(
        sessions: [SavedSession],
        rest: Int = 60,
        maxHR: Int = 190,
        calendar: Calendar = .current,
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> DailyRespiratoryRatePreparation? {
        var candidateCount = 0
        var ratesByMorningDay: [Date: [Double]] = [:]
        for (index, session) in sessions.enumerated() {
            if index.isMultiple(of: 4), !shouldContinue() { return nil }
            let rate = session.sleepRespiratoryRateCancellable(
                rest: rest,
                maxHR: maxHR,
                calendar: calendar,
                shouldContinue: shouldContinue
            )
            guard shouldContinue() else { return nil }
            guard let rate else { continue }
            ratesByMorningDay[
                morningMetricDay(for: session, calendar: calendar),
                default: []
            ].append(rate)
            if session.rrPoints?.isEmpty == false { candidateCount += 1 }
        }
        var averaged: [Date: Double] = [:]
        for (day, rates) in ratesByMorningDay {
            guard shouldContinue() else { return nil }
            if let average = averageDoubleSnapshot(rates) {
                averaged[day] = average
            }
        }
        return shouldContinue() ? .init(
            respiratoryRateByMorningDay: averaged,
            candidateCount: candidateCount
        ) : nil
    }

    /// The sole no-confirmed-sleep recovery exception. It accepts only a
    /// settled, unambiguous five-hour low-HR aggregate backed by a mature
    /// personal RHR+HRV baseline and all-standard-2A37 RR in every contributing
    /// session. This does not create a sleep boundary or sleep duration; it only
    /// supplies today's reproducible HRV/RHR inputs to Recovery v2, whose
    /// sleep-missing path is explicitly capped at `.unverified`.
    nonisolated static func reducedConfidenceUnconfirmedRecoveryInput(
        for day: Date,
        sessions: [SavedSession],
        baseline: PersonalBaseline,
        maxHR: Int,
        now: Date,
        calendar: Calendar = .current,
        shouldContinue: (@Sendable () -> Bool)? = nil
    ) -> (hrv: Int, restingHR: Int, respiratoryRate: Double?)? {
        let continueWork = shouldContinue ?? { true }
        guard continueWork() else { return nil }
        guard baseline.hasTrustedRestingBaseline(now: now),
              baseline.hasTrustedHRVBaseline(now: now) else { return nil }
        let rest = baseline.restingInt ?? 60
        let deadline = AtriaSleepSettlementDeadline(
            uptimeNanoseconds: .max,
            monotonicNow: { continueWork() ? 0 : .max }
        )
        guard let allCandidates = try? aggregateSleepCandidates(
            in: sessions,
            rest: rest,
            maxHR: maxHR,
            calendar: calendar,
            historicalMotionPolicy: .sessionOnly,
            cooperativeDeadline: deadline,
            includeResumedReviewCandidates: true
        ) else { return nil }
        var candidates: [AggregateSleepCandidate] = []
        for (index, candidate) in allCandidates.enumerated() {
            if index.isMultiple(of: 16), !continueWork() { return nil }
            if calendar.isDate(candidate.day, inSameDayAs: day),
               candidate.end <= now,
               sleepCandidateIsSettledForClosedAutoConfirmation(
                    candidateEnd: candidate.end,
                    now: now
               ),
               isUnambiguousHROnlyMainSleepCandidate(
                    candidate,
                    calendar: calendar
               ) {
                candidates.append(candidate)
            }
        }
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &candidates,
            shouldContinue: continueWork,
            areInIncreasingOrder: { $0.end > $1.end }
        ) else { return nil }
        guard let candidate = candidates.first else { return nil }

        var contributing: [SavedSession] = []
        for (index, session) in sessions.enumerated() {
            if index.isMultiple(of: 16), !continueWork() { return nil }
            if session.end > candidate.start,
               session.start < candidate.end {
                contributing.append(session)
            }
        }
        guard !contributing.isEmpty,
              contributing.allSatisfy(\.hasQualifiedRRProvenance) else { return nil }
        guard let metrics = try? confirmedSleepWindowMetrics(
            from: contributing,
            start: candidate.start,
            end: candidate.end,
            rest: rest,
            cooperativeDeadline: deadline
        ) else { return nil }
        guard metrics.hrvWindowCount >= 3,
              let hrv = metrics.hrv,
              hrv > 0 else { return nil }
        var rates: [Double] = []
        for session in contributing {
            guard continueWork() else { return nil }
            if let rate = session.sleepRespiratoryRateCancellable(
                rest: rest,
                maxHR: maxHR,
                calendar: calendar,
                shouldContinue: continueWork
            ) {
                rates.append(rate)
            }
        }
        guard continueWork() else { return nil }
        let respiratoryRate = rates.isEmpty
            ? nil
            : rates.reduce(0, +) / Double(rates.count)
        return (hrv: hrv,
                restingHR: metrics.restingHR,
                respiratoryRate: respiratoryRate)
    }

    // Internal since 2026-07-07: sleep-review evidence cards need the same
    // configured base need the rollup path uses.
    nonisolated static func configuredSleepBaseNeedHours(userDefaults: UserDefaults = .standard) -> Double {
        let stored = userDefaults.object(forKey: "atria.sleep.baseNeedHours") as? Double
        return min(max(stored ?? 8.0, 6.0), 10.0)
    }

    private nonisolated static func welfordStat(_ values: [Double]) -> DailyRollupVitals.Stat? {
        guard values.count >= 3 else { return nil }
        var count = 0
        var mean = 0.0
        var m2 = 0.0
        for value in values {
            count += 1
            let delta = value - mean
            mean += delta / Double(count)
            m2 += delta * (value - mean)
        }
        return DailyRollupVitals.Stat(mean: mean,
                                      sd: sqrt(m2 / Double(max(count - 1, 1))),
                                      n: count)
    }

    private nonisolated static func bedtimeMinutes(from date: Date, calendar: Calendar = .current) -> Int {
        let components = calendar.dateComponents([.hour, .minute], from: date)
        let minutes = (components.hour ?? 0) * 60 + (components.minute ?? 0)
        return minutes < 12 * 60 ? minutes + 24 * 60 : minutes
    }

    nonisolated static func observedHeartRateUnionSecondsCancellable(
        sessions: [SavedSession],
        windowStart: Date,
        windowEnd: Date,
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> TimeInterval? {
        var intervals: [(start: Date, end: Date)] = []
        for (sessionIndex, session) in sessions.enumerated() {
            if sessionIndex.isMultiple(of: 4), !shouldContinue() { return nil }
            guard session.end > windowStart,
                  session.start < windowEnd else { continue }
            var dates: [Date] = []
            dates.reserveCapacity(session.points.count)
            for (pointIndex, point) in session.points.enumerated() {
                if pointIndex.isMultiple(of: 256), !shouldContinue() {
                    return nil
                }
                let date = session.start.addingTimeInterval(max(0, point.t))
                guard date >= windowStart,
                      date < windowEnd,
                      (35...240).contains(point.bpm) else { continue }
                if session.excludedIntervals?.contains(where: {
                    date >= $0.start && date <= $0.end
                }) == true {
                    continue
                }
                dates.append(date)
            }
            guard AtriaSleepCooperativeAlgorithms.stableSort(
                &dates,
                shouldContinue: shouldContinue,
                areInIncreasingOrder: <
            ) else { return nil }
            for (index, date) in dates.enumerated() {
                if index.isMultiple(of: 256), !shouldContinue() { return nil }
                intervals.append((
                    start: max(windowStart, date.addingTimeInterval(-0.5)),
                    end: min(windowEnd, date.addingTimeInterval(0.5))
                ))
                guard index > 0 else { continue }
                let previous = dates[index - 1]
                let gap = date.timeIntervalSince(previous)
                if gap > 0,
                   gap <= AtriaAnalytics.Strain.maximumLoadEvidenceGap {
                    intervals.append((start: previous, end: date))
                }
            }
        }
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &intervals,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: {
                if $0.start != $1.start { return $0.start < $1.start }
                return $0.end < $1.end
            }
        ) else { return nil }
        var total = 0.0
        var openStart: Date?
        var openEnd = Date.distantPast
        for (index, interval) in intervals.enumerated() {
            if index.isMultiple(of: 256), !shouldContinue() { return nil }
            if openStart != nil, interval.start <= openEnd {
                openEnd = max(openEnd, interval.end)
                continue
            }
            if let openStart { total += openEnd.timeIntervalSince(openStart) }
            openStart = interval.start
            openEnd = interval.end
        }
        if let openStart { total += openEnd.timeIntervalSince(openStart) }
        return shouldContinue() ? total : nil
    }

    nonisolated static func makeMorningFrozenDailyMetric(for day: Date,
                                                                 computed: [SavedDailyMetric],
                                                                 sessions: [SavedSession],
                                                                 sleep: SleepHistorySnapshot,
                                                                 baseline: PersonalBaseline,
                                                                 maxHR: Int,
                                                                 now: Date,
                                                                 skinTemperatureDeviationByDay: [Date: Double]? = nil,
                                                                 skinTemperatureSourceValidated: Bool = AtriaResearchProbe.validatedSkinTemperatureDecoderAvailable,
                                                                 calendar: Calendar = .current,
                                                                 shouldContinue: (@Sendable () -> Bool)? = nil) -> SavedDailyMetric? {
        let continueWork = shouldContinue ?? { true }
        guard continueWork() else { return nil }
        let hour = calendar.component(.hour, from: now)
        let confirmedMainSleep = canonicalPhysiologicalMainSleepNight(
            for: day,
            in: sleep.nights,
            completedBy: now,
            calendar: calendar
        )
        // A confirmed wake is the boundary, regardless of wall-clock hour. This
        // lets a shift worker's 02:00 wake settle recovery. The legacy 04:00 gate
        // remains only for first-run wear fallback when no confirmed main sleep
        // exists anywhere yet; it cannot mint a second civil-day recovery while
        // the previous physiological cycle is still active.
        let hasAnyConfirmedMainSleep = sleep.nights.contains {
            confirmedSleepIsPhysiologicalMainSleep($0)
                && ($0.end ?? .distantFuture) <= now
        }
        guard continueWork() else { return nil }
        guard confirmedMainSleep != nil || hasAnyConfirmedMainSleep || hour >= 4 else { return nil }

        let sleepAnchoredSession = confirmedMainSleep.flatMap { confirmedSleep in
            sessions.first {
                $0.start < (confirmedSleep.end ?? confirmedSleep.day)
                    && $0.end > (confirmedSleep.start ?? confirmedSleep.day)
            }
        }
        let overnightSession = sleepAnchoredSession ?? sessions.first {
            guard $0.isOvernightHRVWindow(calendar: calendar) else { return false }
            return calendar.isDate(morningMetricDay(for: $0, calendar: calendar), inSameDayAs: day)
        }
        guard continueWork() else { return nil }
        let computedToday = computed.first { calendar.isDate($0.day, inSameDayAs: day) }

        // Same-day WEAR fallback: `computed` rollups bucket a session by its
        // *start* day (dailyRollups groups by calendar.startOfDay(session.start)),
        // so an overnight session that starts yesterday and ends this morning has
        // no same-day `computedToday` entry even though the strap was worn all
        // night into today. Attribute sessions to today by their *end* day
        // (morningMetricDay) instead, so today's rollup can exist from wear alone
        // even when there is no confirmed sleep and no RR-bearing overnight HRV
        // window (rrPoints absent). This is independent of sleep confirmation —
        // sleepDuration stays nil here unless one of the sleep-bearing sources
        // above already set it.
        var wearSessionsToday: [SavedSession] = []
        for (index, session) in sessions.enumerated() {
            if index.isMultiple(of: 8), !continueWork() { return nil }
            if calendar.isDate(
                morningMetricDay(for: session, calendar: calendar),
                inSameDayAs: day
            ) {
                wearSessionsToday.append(session)
            }
        }
        let daySessionsExist = !wearSessionsToday.isEmpty
        var wearRestingHR: Int?
        var wearStrainTRIMP = 0.0
        for (index, session) in wearSessionsToday.enumerated() {
            if index.isMultiple(of: 4), !continueWork() { return nil }
            let resting = if shouldContinue != nil {
                session.percentileHRCancellable(
                    0.10,
                    shouldContinue: continueWork
                ) ?? 0
            } else {
                session.restingStable
            }
            if resting > 0 { wearRestingHR = min(wearRestingHR ?? resting, resting) }
            guard let interval = EventCivilTime.interval(
                forCivilDay: day,
                eventTimeZoneIdentifier: session.eventTimeZoneIdentifier,
                outputCalendar: calendar
            ) else { continue }
            guard let load = session.dailyLoadTRIMPCancellable(
                rest: baseline.restingInt ?? 60,
                max: maxHR,
                within: interval,
                shouldContinue: continueWork
            ) else { return nil }
            wearStrainTRIMP += load
        }
        // Same rest anchor as the primary rollup strain (2026-07-08 audit #14:
        // baseline.restingInt ?? 60), so today's strain is identical whether it
        // comes from computedToday or this wear fallback. Previously this branch
        // added `?? wearRestingHR`, diverging when no baseline exists yet.
        let wearStrain = wearStrainTRIMP > 0 ? Metrics.strain(fromTRIMP: wearStrainTRIMP) : nil
        let reducedConfidenceInput = confirmedMainSleep == nil && hasAnyConfirmedMainSleep
            ? reducedConfidenceUnconfirmedRecoveryInput(for: day,
                                                         sessions: sessions,
                                                         baseline: baseline,
                                                         maxHR: maxHR,
                                                         now: now,
                                                         calendar: calendar,
                                                         shouldContinue: continueWork)
            : nil
        guard continueWork() else { return nil }

        // A confirmed main sleep owns this cycle's overnight HRV. If that exact
        // sleep window did not produce a qualified value, fail closed instead of
        // borrowing a whole-session/computed-day aggregate that may include RR
        // evidence from outside the scored sleep. This matches
        // `latestLocalRecoveryHRV`: missing sleep-window HRV stays missing.
        let overnightLocalHRV = shouldContinue != nil
            ? overnightSession?.localRMSSDCancellable(
                shouldContinue: continueWork
            )
            : overnightSession?.localRMSSD
        let overnightRestingHR = shouldContinue != nil
            ? overnightSession?.percentileHRCancellable(
                0.05,
                shouldContinue: continueWork
            )
            : overnightSession?.sleepCandidateRestingHR
        let overnightStableHR = shouldContinue != nil
            ? overnightSession?.percentileHRCancellable(
                0.10,
                shouldContinue: continueWork
            )
            : overnightSession?.restingStable
        let overnightRespiratoryRate = shouldContinue != nil
            ? overnightSession?.sleepRespiratoryRateCancellable(
                rest: baseline.restingInt ?? overnightStableHR ?? 60,
                maxHR: maxHR,
                calendar: calendar,
                shouldContinue: continueWork
            )
            : overnightSession?.sleepRespiratoryRate(
                rest: baseline.restingInt ?? overnightStableHR ?? 60,
                maxHR: maxHR,
                calendar: calendar
            )
        guard continueWork() else { return nil }
        let hrv: Int? = if let confirmedMainSleep {
            confirmedMainSleep.hrv.flatMap { $0 > 0 ? $0 : nil }
        } else if !hasAnyConfirmedMainSleep {
            overnightLocalHRV ?? computedToday?.hrv
        } else {
            reducedConfidenceInput?.hrv
        }
        let restingHR = confirmedMainSleep?.restingHR
            ?? reducedConfidenceInput?.restingHR
            ?? overnightRestingHR
            ?? overnightStableHR
            ?? computedToday?.restingHR
            ?? wearRestingHR
        let respiratoryRate = confirmedMainSleep?.respiratoryRate
            ?? reducedConfidenceInput?.respiratoryRate
            ?? overnightRespiratoryRate
            ?? computedToday?.respiratoryRate
        let sleepDuration = confirmedMainSleep?.duration
        let sleepSpan = confirmedMainSleep.flatMap { night -> TimeInterval? in
            guard let start = night.start, let end = night.end, end > start else { return nil }
            return end.timeIntervalSince(start)
        }
        let sleepStart = confirmedMainSleep?.start
        let sleepEnd = confirmedMainSleep?.end
        let sleepSource = confirmedMainSleep?.source
        let sleepSegments = confirmedMainSleep?.stageSegmentsForStorage ?? []
        // Consistency is a historical as-of-day metric. Reusing the current
        // snapshot's aggregate here copied today's value backward onto every
        // older daily row (including days before two nights existed). Rebuild
        // it from only sleep evidence that was available by this morning.
        let sleepConsistencyPercent = sleep.sleepConsistencyPercent(
            asOf: day,
            calendar: calendar
        )
        // The confirmed night is the single authority for the adaptive target
        // that was frozen when this physiological cycle settled. Re-deriving a
        // target here from today's profile/debt/strain made the daily rollup
        // disagree with the Sleep detail shown for the very same night. Older
        // records without a durable receipt remain unknown rather than being
        // assigned a retroactive target.
        let frozenSleepNeedSeconds = confirmedMainSleep?.frozenSleepNeed?.seconds
        let strain = computedToday?.strain ?? wearStrain
        let strainDayEnd = min(
            now,
            calendar.date(byAdding: .day, value: 1, to: day)
                ?? day.addingTimeInterval(24 * 60 * 60)
        )
        let strainElapsed = max(0, strainDayEnd.timeIntervalSince(day))
        let strainObserved: TimeInterval
        if shouldContinue != nil {
            guard let observed = observedHeartRateUnionSecondsCancellable(
                sessions: sessions,
                windowStart: day,
                windowEnd: strainDayEnd,
                shouldContinue: continueWork
            ) else { return nil }
            strainObserved = observed
        } else {
            strainObserved = AtriaHomeModel.observedHeartRateUnionSeconds(
                sessions: sessions,
                windowStart: day,
                windowEnd: strainDayEnd
            )
        }
        let strainCoverage = computedToday?.strainCoverageFraction
            ?? (strainElapsed > 0 ? min(1, max(0, strainObserved / strainElapsed)) : nil)
        let strainPresentation = Metrics.StrainPresentation.resolve(
            value: strain,
            coverageFraction: strainCoverage,
            baseConfidence: strain == nil ? "learning" : "local",
            persistedQuality: computedToday?.strainEvidenceQuality
        )
        let skinTemperatureDeviation = morningSkinTemperatureDeviation(
            for: day,
            computedToday: computedToday,
            skinTemperatureDeviationByDay: skinTemperatureDeviationByDay,
            sessions: sessions,
            activeSessionID: nil,
            calendar: calendar,
            validatedSource: skinTemperatureSourceValidated
        )
        guard continueWork() else { return nil }

        guard hrv != nil
                || restingHR != nil
                || sleepDuration != nil
                || skinTemperatureDeviation != nil
                || (daySessionsExist && (restingHR != nil || strain != nil)) else {
            return nil
        }

        let recovery = Metrics.recoveryV2(hrvSnapshot: nil,
                                          fallbackRMSSD: hrv,
                                          restingNow: restingHR,
                                          baseline: baseline,
                                          hrvReferenceValidated: false,
                                          sleepEfficiency: recoverySleepEfficiency(from: confirmedMainSleep),
                                          sleepDurationHours: sleepDuration.map { $0 / 3_600 },
                                          // Recovery v4: the wearer's own
                                          // robust sleep baseline; nil while
                                          // calibrating (tier caps itself).
                                          sleepBaseline: sleep.sleepBaselineStats,
                                          respiratoryRate: respiratoryRate,
                                          respiratoryBaseline: sleep.respiratoryBaselineStats,
                                          now: now)

        return SavedDailyMetric(day: day,
                                recoveryPercent: recovery.percent,
                                recoveryConfidence: recovery.confidence.rawValue,
                                hrv: hrv,
                                restingHR: restingHR,
                                respiratoryRate: respiratoryRate,
                                sleepDuration: sleepDuration,
                                sleepNeedSeconds: frozenSleepNeedSeconds,
                                sleepSpan: sleepSpan,
                                sleepStart: sleepStart,
                                sleepEnd: sleepEnd,
                                sleepSource: sleepSource,
                                sleepStageSegments: sleepSegments,
                                sleepConsistencyPercent: sleepConsistencyPercent,
                                strain: strain,
                                strainCoverageFraction: strainCoverage,
                                strainEvidenceQuality: strainPresentation.quality,
                                // Assessment P1.7: persist the raw TRIMP truth
                                // beside its display skin. The wear fallback
                                // freezes the exact integral it displayed.
                                dayTRIMP: computedToday?.dayTRIMP
                                    ?? (wearStrainTRIMP > 0 ? wearStrainTRIMP : nil),
                                skinTemperatureDeviationCelsius: skinTemperatureDeviation,
                                recoverySummary: FrozenRecoverySummary(
                                    estimate: recovery,
                                    scoredDay: day,
                                    inputSnapshot: FrozenRecoverySummary.InputSnapshot(
                                        hrvRMSSD: hrv.map(Double.init),
                                        restingHeartRateBPM: restingHR.map(Double.init),
                                        sleepDurationSeconds: sleepDuration,
                                        sleepEfficiency: recoverySleepEfficiency(from: confirmedMainSleep),
                                        respiratoryRate: respiratoryRate,
                                        baseline: baseline,
                                        respiratoryBaseline: sleep.respiratoryBaselineStats,
                                        now: now,
                                        calendar: calendar
                                    )
                                ))
    }

    private nonisolated static func morningMetricDay(for night: SleepHistorySnapshot.Night,
                                                     calendar: Calendar = .current) -> Date {
        if let end = night.end {
            return EventCivilTime.day(containing: end,
                                      eventTimeZoneIdentifier: night.eventTimeZoneIdentifier,
                                      outputCalendar: calendar)
        }
        if let start = night.start, night.duration > 0 {
            return EventCivilTime.day(containing: start.addingTimeInterval(night.duration),
                                      eventTimeZoneIdentifier: night.eventTimeZoneIdentifier,
                                      outputCalendar: calendar)
        }
        return calendar.startOfDay(for: night.day)
    }

    nonisolated static func morningMetricDay(for session: SavedSession,
                                             calendar: Calendar = .current) -> Date {
        EventCivilTime.day(containing: session.start.addingTimeInterval(max(session.duration, 0)),
                           eventTimeZoneIdentifier: session.eventTimeZoneIdentifier,
                           outputCalendar: calendar)
    }

    private nonisolated static func makeDailyMetricSparklines(from history: [SavedDailyMetric]) -> DailyMetricSparklineCache {
        let recent = Array(history.prefix(7).reversed())

        func compact<T>(_ values: [T]) -> [T]? {
            values.count >= 2 ? values : nil
        }

        return DailyMetricSparklineCache(
            recovery: compact(recent.compactMap(\.recoveryPercent)),
            hrv: compact(recent.compactMap(\.hrv)),
            restingHeartRate: compact(recent.compactMap(\.restingHR)),
            sleep: compact(recent.compactMap { metric in
                guard let duration = metric.sleepDuration, duration > 0 else { return nil }
                return Int((duration / 3_600).rounded())
            }),
            strain: compact(recent.compactMap { $0.strain.map { Int(($0 * 10).rounded()) } })
        )
    }

    private nonisolated static func isHighOutlierSnapshot(_ value: Double, in values: [Double]) -> Bool {
        guard values.count >= 5 else { return false }
        let mean = values.reduce(0, +) / Double(values.count)
        let variance = values.reduce(0) { $0 + pow($1 - mean, 2) } / Double(values.count)
        let sd = sqrt(variance)
        return sd > 0.1 && value > mean + 2 * sd
    }

    private nonisolated static func trendDetailSnapshot(coverageDays: Int,
                                                        windowDays: Int,
                                                        hrvState: String,
                                                        rhrSamples: Int,
                                                        strainSamples: Int,
                                                        anomalySampleDays: Int,
                                                        anomalies: [String]) -> String {
        var parts: [String] = []
        if coverageDays == 0 {
            parts.append("no saved history")
        } else if Double(coverageDays) / Double(windowDays) >= 0.70 {
            parts.append("coverage high")
        } else {
            parts.append("coverage sparse")
        }
        parts.append(hrvState == "learning" ? "HRV learning" : "HRV \(hrvState)")
        parts.append(rhrSamples > 0 ? "RHR accepted evidence \(rhrSamples)" : "RHR learning")
        parts.append(strainSamples > 0 ? "strain saved TRIMP \(strainSamples)" : "strain learning")
        parts.append("anomaly source bounded_history_rollups days \(anomalySampleDays)")
        if !anomalies.isEmpty {
            parts.append("flags \(anomalies.joined(separator: ","))")
        }
        return parts.joined(separator: " · ")
    }

    private nonisolated static func trendSummaryBlockersSnapshot(coverageDays: Int,
                                                                 requiredCoverageDays: Int,
                                                                 avgRecovery: Int?,
                                                                 avgHRV: Int?,
                                                                 hrvState: String) -> String {
        var blockers: [String] = []
        if coverageDays <= 0 {
            blockers.append("no_saved_history")
        } else if coverageDays < requiredCoverageDays {
            blockers.append("coverage_below_70pct")
        }
        if hrvState == "learning" {
            blockers.append("hrv_learning")
        }
        if avgRecovery == nil {
            blockers.append("recovery_points_missing")
        }
        if avgHRV == nil {
            blockers.append("hrv_points_missing")
        }
        return blockers.isEmpty ? "none" : blockers.joined(separator: "+")
    }

    /// EXPENSIVE: behavior insights via dailyRollups → the canonical-session cache.
    /// MUST be called only after `cachedCanonicalSessions` + `baseline` are
    /// consistent (load / add / delete / journal change) — never from the hot
    /// checkpoint path. See findings 1–3/5 in docs review.
    func recomputeBehaviorInsights(
        executionShouldContinue:
            @escaping @Sendable () -> Bool = { true },
        completion: ((Bool) -> Void)? = nil
    ) {
        guard executionShouldContinue() else {
            completion?(false)
            return
        }
        // PRODUCT DECISION: derived metrics (insights/correlations) are NOT
        // real-time — only live BPM is. Compute off the main thread (mirrors the
        // diagnostics background pass) and publish the result on main when ready,
        // so this can never block launch, scrolling, or the workout screen.
        let rest = baseline.restingInt ?? 60
        let maxHR = profile.maxHR
        let sourceSessions = cachedCanonicalSessions
        let journalEntries = cachedBehaviorJournalEntries
        let metricDays = dailyMetricHistory.map {
            AtriaBehaviorImpact.Day(day: $0.day, recoveryPercent: $0.recoveryPercent)
        }
        // Assessment P1.9: measured RHR days ride along so tags pair to
        // signals that survive Recovery model bumps.
        let vitalDays = dailyMetricHistory.map {
            (day: $0.day, restingHR: $0.restingHR)
        }
        let sourceDailyMetricRevision = dailyMetricHistoryRevision
        behaviorInsightsLastStartedDailyMetricRevision = sourceDailyMetricRevision
        if pendingDailyMetricInsightRevision == sourceDailyMetricRevision {
            pendingDailyMetricInsightRefreshTask?.cancel()
            pendingDailyMetricInsightRefreshTask = nil
            pendingDailyMetricInsightRevision = nil
        }
        journalAnswers.loadIfNeeded()
        let typedAnswers = journalAnswers.answers
        behaviorInsightsGeneration &+= 1
        let generation = behaviorInsightsGeneration
        DispatchQueue.global(qos: .utility).async { [weak self, sourceSessions, journalEntries, rest, maxHR, metricDays, vitalDays, typedAnswers, generation, executionShouldContinue] in
            guard executionShouldContinue() else {
                DispatchQueue.main.async { completion?(false) }
                return
            }
            guard let summaries = SessionStore
                .makeBehaviorCorrelationSummariesCancellable(
                    sessions: sourceSessions,
                    journalEntries: journalEntries,
                    rest: rest,
                    maxHR: maxHR,
                    dailyVitals: vitalDays,
                    shouldContinue: executionShouldContinue
                ), let impacts = AtriaBehaviorImpact.summariesCancellable(
                    days: metricDays,
                    journalEntries: journalEntries,
                    shouldContinue: executionShouldContinue
                ), let groupedAnswers = SessionStore
                    .groupJournalAnswersByQuestionCancellable(
                        typedAnswers,
                        shouldContinue: executionShouldContinue
                    ), let journalInsights = AtriaJournalInsights
                    .insightsCancellable(
                        questionAnswers: groupedAnswers,
                        labels: SessionStore.journalQuestionLabels,
                        days: metricDays,
                        shouldContinue: executionShouldContinue
                    ) else {
                DispatchQueue.main.async { completion?(false) }
                return
            }
            let sortedSummaries = SessionStore
                .sortedBehaviorCorrelationSummaries(summaries)
            guard let insights = SessionStore.deriveInsightsCancellable(
                from: sortedSummaries,
                shouldContinue: executionShouldContinue
            ) else {
                DispatchQueue.main.async { completion?(false) }
                return
            }
            guard executionShouldContinue() else {
                DispatchQueue.main.async { completion?(false) }
                return
            }
            DispatchQueue.main.async {
                guard executionShouldContinue(),
                      let self,
                      Self.behaviorInsightPublicationIsCurrent(
                        generation: generation,
                        currentGeneration: self.behaviorInsightsGeneration,
                        sourceDailyMetricRevision: sourceDailyMetricRevision,
                        currentDailyMetricRevision: self.dailyMetricHistoryRevision
                      ) else {
                    completion?(false)
                    return
                }
                self.behaviorInsightsLastPublishedDailyMetricRevision = sourceDailyMetricRevision
                self.behaviorInsightsRevision &+= 1
                self.behaviorCorrelationSummariesCache = sortedSummaries
                self.behaviorImpactSummariesCache = impacts
                self.behaviorInsights = insights
                self.journalInsightsCache = journalInsights
                completion?(true)
            }
        }
    }

    /// Daily metrics are slow-moving, authoritative values. Their history worker
    /// can finish after an earlier session-boundary insight computation, so one
    /// short coalescing lease recomputes from the accepted revision. The engine
    /// itself remains on the utility queue inside `recomputeBehaviorInsights`.
    private func scheduleBehaviorInsightsAfterDailyMetricPublication() {
        guard hasCompletedDeferredSessionLoad,
              canonicalMutationAllowed else { return }
        let revision = dailyMetricHistoryRevision
        guard revision != behaviorInsightsLastStartedDailyMetricRevision,
              revision != behaviorInsightsLastPublishedDailyMetricRevision,
              revision != pendingDailyMetricInsightRevision else { return }

        pendingDailyMetricInsightRefreshTask?.cancel()
        pendingDailyMetricInsightRevision = revision
        pendingDailyMetricInsightRefreshTask = Task { @MainActor [weak self] in
            try? await Task.sleep(for: .milliseconds(250))
            guard !Task.isCancelled,
                  let self,
                  self.pendingDailyMetricInsightRevision == revision else { return }
            self.pendingDailyMetricInsightRefreshTask = nil
            self.pendingDailyMetricInsightRevision = nil
            guard self.hasCompletedDeferredSessionLoad,
                  self.canonicalMutationAllowed,
                  self.dailyMetricHistoryRevision == revision else { return }
            self.recomputeBehaviorInsights()
        }
    }

    nonisolated static func behaviorInsightPublicationIsCurrent(
        generation: Int,
        currentGeneration: Int,
        sourceDailyMetricRevision: Int,
        currentDailyMetricRevision: Int
    ) -> Bool {
        generation == currentGeneration
            && sourceDailyMetricRevision == currentDailyMetricRevision
    }

