    private struct RecoveredCurrentCheckpoint: Codable, @unchecked Sendable {
        nonisolated static let schema = 2

        struct TemperatureDay: Codable, Sendable {
            let day: Date
            let deviationCelsius: Double
        }

        let version: Int
        /// Process-ticket ownership for stale async-write cleanup. Optional so
        /// existing schema-2 checkpoints remain decodable.
        let publicationGeneration: UInt64?
        /// Crash-safe activation identity. A newly written checkpoint is not
        /// launch-readable until the real dashboard/revision publication turn
        /// stores this exact UUID in UserDefaults. Older schema-2 images have
        /// no identity and preserve their prior compatibility semantics.
        let publicationIdentity: String?
        let generatedAt: Date
        let cutoff: Date
        let sourceFingerprint:
            HistoricalArchive.ConsumerSourceFingerprint
        let automaticCacheAuthority:
            HistoricalArchive.AutomaticRecoveredDataCacheAuthority
        let recoveredSessions: [SavedSession]
        let temperatureDays: [TemperatureDay]
        let temperatureBaselineNightCount: Int
        let temperatureCandidateFrameCount: Int
    }

    nonisolated private static let recoveredCurrentCheckpointMaximumAge:
        TimeInterval = 72 * 60 * 60
    nonisolated private static let recoveredCurrentCheckpointMaximumSessions = 256
    nonisolated private static let recoveredCurrentCheckpointMaximumHeartRatePoints =
        200_000
    nonisolated private static let recoveredCurrentCheckpointPublicationIdentityKey =
        "atria.recoveredProjection.currentCheckpointPublicationIdentity.v1"
    nonisolated private static let recoveredCurrentCheckpointPersistenceLock =
        NSLock()

    init(restoreInitialization: RestoreInitialization = .live,
         journalAnswers: AtriaJournalAnswerStore = AtriaJournalAnswerStore()) {
        self.journalAnswers = journalAnswers
        // Resolve an interrupted multi-destination restore before baseline,
        // profile, rollups, or any cached canonical array touches persistence.
        let recovery = restoreInitialization.recover()
        let recoveryBlocked = recovery == .retainedMarker
        self.restoreInitializationBlocked = recoveryBlocked
        self.restorePersistenceFenceActive = recoveryBlocked
        if !recoveryBlocked {
            self.baseline = restoreInitialization.loadBaseline()
            self.profile = restoreInitialization.loadProfile()
            self.dailyRollupStore = restoreInitialization.loadDailyRollups()
        }
        self.cachedConfirmedWorkouts = recoveryBlocked ? [] : Self.readConfirmedWorkouts()
        self.cachedConfirmedSleeps = recoveryBlocked ? [] : Self.readConfirmedSleeps()
        self.cachedBehaviorJournalEntries = recoveryBlocked ? [] : Self.readBehaviorJournalEntries()
        self.cachedResearchManeuverMarkers = recoveryBlocked ? [] : Self.readResearchManeuverMarkers()
        self.cachedSessionBackupStatus = .missing
        self.cachedLatestReferenceValidatedHRV = nil
        self.cachedLatestReferenceValidatedHRVSource = nil
        self.cachedLatestLocalRMSSD = nil
        self.cachedLatestLocalRMSSDSource = nil
        self.cachedCanonicalSessions = []
        self.cachedRecoveredHeartRateSessions = []
        self.cachedWorkoutReviewCandidate = nil
        self.cachedWorkoutReviewCandidates = []
        self.cachedHomeDashboardDiagnostics = nil
        self.cachedHomeSavedAggregate = nil
        self.cachedCurrentCollectionStatus = nil
        self.cachedMaxHRSuggestion = nil
        self.cachedBiologicalAge = nil
        self.cachedBiologicalAgeWeeklySummary = nil
        self.cachedBiologicalAgeSignatureMemo = nil
        self.cachedSkinTemperatureDeviationSummary = nil
        self.cachedRecoveredSkinTemperatureDeviationByDay = [:]
        self.cachedRecoveredSkinTemperatureBaselineNightCount = 0
        self.cachedRecoveredSkinTemperatureCandidateFrameCount = 0
        self.lastLiveHRVCheckpointRefreshAt = Self.readLiveHRVCheckpointRefreshDate()
        self.pendingSleepReviewNightForUI = nil
        // Detect an already-saved "slept twice" day on launch so the choice
        // prompt appears without waiting for a new save. Empty when recovery is
        // blocked (cachedConfirmedSleeps is []).
        self.pendingSameDayMainSleepChoiceForUI = Self.pendingSameDayMainSleepChoice(
            confirmedSleeps: cachedConfirmedSleeps,
            calendar: .current)
        self.dailyRollupHistory = recoveryBlocked ? [] : dailyRollupStore.rollups(last: 400)
        self.cachedBiologicalAge = recoveryBlocked ? nil : Self.readBiologicalAgeCache(from: biologicalAgeCacheURL)
        guard !recoveryBlocked else {
            AtriaDebugLog("ATRIADBG session_store_init status=blocked reason=restore_marker_retained")
            return
        }
        self.historicalArchiveStatusObserver = NotificationCenter.default.addObserver(forName: HistoricalArchive.didUpdateNotification,
                                                                                      object: nil,
                                                                                      queue: .main) { [weak self] _ in
            Task { @MainActor in
                guard let self else { return }
                self.handleAutomaticRecoveredArchiveDidUpdate()
                // A terminal history drain can seal a raw chunk while the app
                // stays in the foreground for days. Retain that maintenance
                // intent, but never let this live/archive callback enumerate
                // the archive for pressure accounting. Only a guarded
                // BGProcessing call can mint the worker authority below.
                self.reserveArchiveCompactionForSafeBackground()
                AtriaDebugLog(
                    "ATRIADBG archive_compaction_driver status=reserved_for_safe_background reason=archive_did_update action=wait_for_guarded_bg_processing"
                )
            }
        }
        self.motionBankOffloadObserver = NotificationCenter.default.addObserver(
            forName: AtriaWhoop4MotionBankCoverageLedger
                .didFinalizeOffloadNotification,
            object: nil,
            queue: .main
        ) { [weak self] _ in
            Task { @MainActor in
                // Exact verification and honest bounded exhaustion both change
                // the transport queue. Publish from the bounded compact shard;
                // this hot same-link callback can never enumerate JSONL.
                self?.refreshCurrentCycleStrapStepReceipt(
                    reason: "finalized_bank_offload"
                )
            }
        }
        self.motionCompactStoreObserver =
            NotificationCenter.default.addObserver(
                forName: AtriaWhoop4MotionTickCompactStore
                    .didSynchronizeNotification,
                object: nil,
                queue: .main
            ) { [weak self] _ in
                Task { @MainActor in
                    // A drain may add truthful current-cycle rows without
                    // bringing any one exact ticket to 90%. Publish that
                    // stronger lower bound once at the durable compact
                    // boundary instead of waiting for full ticket resolution.
                    self?.refreshCurrentCycleStrapStepReceipt(
                        reason: "compact_generation_durable"
                    )
                    self?.scheduleConfirmedWorkoutStepEvidencePublication(
                        reason: "compact_generation_durable"
                    )
                }
            }
        self.systemTimeZoneObserver = NotificationCenter.default.addObserver(forName: NSNotification.Name.NSSystemTimeZoneDidChange,
                                                                              object: nil,
                                                                              queue: .main) { [weak self] _ in
            Task { @MainActor in
                self?.handleSystemTimeZoneChange()
            }
        }
        self.recoveredThermalStateObserver = NotificationCenter.default
            .addObserver(
                forName: ProcessInfo.thermalStateDidChangeNotification,
                object: nil,
                queue: .main
            ) { [weak self] _ in
                Task { @MainActor in
                    self?.handleRecoveredExecutionEnvironmentChange(
                        reason: "thermal_state_changed"
                    )
                }
            }
        self.recoveredPowerStateObserver = NotificationCenter.default.addObserver(
            forName: .NSProcessInfoPowerStateDidChange,
            object: nil,
            queue: .main
        ) { [weak self] _ in
            Task { @MainActor in
                self?.handleRecoveredExecutionEnvironmentChange(
                    reason: "power_state_changed"
                )
            }
        }
        self.activeJournalSleepReviewObserver = NotificationCenter.default.addObserver(
            forName: ActiveSessionJournal.didPersistSleepReviewEvidenceNotification,
            object: nil,
            queue: .main
        ) { [weak self] notification in
            guard let identity = notification.object as? ActiveSessionJournal.SleepReviewCacheIdentity else {
                return
            }
            Task { @MainActor in
                self?.handleActiveJournalSleepReviewIdentity(identity)
            }
        }
        self.activeJournalSleepReviewCacheWarmObserver =
            NotificationCenter.default.addObserver(
                forName: ActiveSessionJournal
                    .didWarmSleepReviewCacheNotification,
                object: nil,
                queue: nil
            ) { [weak self] notification in
                guard let event = notification.object
                    as? ActiveSessionJournal.SleepReviewCacheWarmEvent else {
                    return
                }
                Task { @MainActor in
                    self?.handleActiveJournalSleepReviewCacheWarm(event)
                }
            }
        let documentsDirectory = url.deletingLastPathComponent()
        Task.detached(priority: .utility) {
            AtriaGeneratedArtifactRetention.prune(
                in: documentsDirectory.appendingPathComponent("atria-raw-exports", isDirectory: true),
                policy: AtriaGeneratedArtifactRetention.rawExports
            )
            AtriaGeneratedArtifactRetention.prune(
                in: documentsDirectory.appendingPathComponent("atria-captures", isDirectory: true),
                policy: AtriaGeneratedArtifactRetention.diagnosticCaptures
            )
        }
        loadPersistedSessionsDeferred()
        loadPersistedDailyMetrics()
        refreshSessionDerivedCaches()
        Task { @MainActor [weak self] in
            await self?.rescorePersistedConfirmedWorkoutStrainIfVerified()
        }
        refreshMaxHRSuggestion(reason: "init", force: true)
        recomputeCollectionResearchSummaries()
        sleepHistorySnapshot = SleepHistorySnapshot(rollups: [],
                                                    confirmedSleeps: cachedConfirmedSleeps,
                                                    dismissedCandidates: dismissedSleepCandidates)
        // Defer one MainActor turn so the initial bounded compact receipt read
        // does not share the store initializer's render turn. Legacy JSONL
        // migration is admitted only by safe BGProcessing maintenance.
        Task { @MainActor [weak self] in
            guard let self else { return }
            self.scheduleConfirmedWorkoutStepEvidencePublication(
                reason: "session_store_init_workout_evidence"
            )
            self.refreshCurrentCycleStrapStepReceipt(
                reason: "session_store_init"
            )
            // 2026-07-31: arm the no-sleep rollover boundary check; nothing
            // else fires when the fallback silently moves the cycle start.
            self.schedulePhysiologicalCycleRolloverCheck(
                reason: "session_store_init"
            )
        }
        refreshHistorySnapshotCache(deferred: true)
        refreshOverviewTrendPointsCache(deferred: true)
        refreshTrainingLoadSummaryCache(deferred: true)
        refreshTodayHRZoneMinutesCache(deferred: true)
        #if DEBUG
        if Self.shouldSeedDebugStrengthWorkoutProof(arguments: ProcessInfo.processInfo.arguments) {
            UserDefaults.standard.set("scheduled", forKey: Self.debugStrengthWorkoutProofStatusKey)
            UserDefaults.standard.set("session_store_init", forKey: Self.debugStrengthWorkoutProofReasonKey)
            Task { @MainActor [weak self] in
                try? await Task.sleep(for: .milliseconds(700))
                await self?.seedDebugStrengthWorkoutProofIfRequested(arguments: ProcessInfo.processInfo.arguments)
            }
        }
        #endif
    }

    private func handleSystemTimeZoneChange() {
        let changed = dailyRollupStore.updateCalendar(.current)
        if changed {
            dailyRollupHistory = dailyRollupStore.rollups(last: 400)
            dailyRollupHistoryRevision &+= 1
            cachedWeeklyPlanRevision = nil
            cachedWeeklyPlanWeekStart = nil
            cachedWeeklyPlanValue = nil
            cachedSkinTemperatureDeviationSummary = nil
            cachedRecoveredSkinTemperatureDeviationByDay = [:]
            cachedRecoveredSkinTemperatureBaselineNightCount = 0
            cachedRecoveredSkinTemperatureCandidateFrameCount = 0
        }
        invalidateSleepReviewCache(reason: "system_timezone")
    }

    private func handleRecoveredExecutionEnvironmentChange(reason: String) {
        switch Self.recoveredExecutionEnvironmentAction(
            applicationIsActive:
                UIApplication.shared.applicationState == .active,
            thermalState: ProcessInfo.processInfo.thermalState,
            isLowPowerModeEnabled:
                ProcessInfo.processInfo.isLowPowerModeEnabled
        ) {
        case .suspend:
            suspendRecoveredDataPublicationLeaseForBackground(reason: reason)
        case .resume:
            resumeRecoveredDataPublicationLeaseForForeground(reason: reason)
        case .none:
            break
        }
    }

    enum RecoveredExecutionEnvironmentAction: Equatable, Sendable {
        case suspend
        case resume
        case none
    }

    nonisolated static func recoveredExecutionEnvironmentAction(
        applicationIsActive: Bool,
        thermalState: ProcessInfo.ThermalState,
        isLowPowerModeEnabled: Bool
    ) -> RecoveredExecutionEnvironmentAction {
        if thermalState == .serious
            || thermalState == .critical
            || isLowPowerModeEnabled {
            return .suspend
        }
        return applicationIsActive ? .resume : .none
    }

    nonisolated static func recoveredMainActorMutationEnvironmentAllows(
        applicationIsActive: Bool,
        isExplicitBackgroundAuthority: Bool
    ) -> Bool {
        isExplicitBackgroundAuthority || applicationIsActive
    }

    private func handleActiveJournalSleepReviewIdentity(
        _ identity: ActiveSessionJournal.SleepReviewCacheIdentity
    ) {
        guard identity != activeJournalSleepReviewIdentity else { return }
        activeJournalSleepReviewIdentity = identity
        invalidateSleepReviewCache(
            reason: "active_journal_five_minute_bucket",
            scheduleRefresh: true
        )
        // The same fsynced HR evidence is also authoritative for automatic
        // activity review. In thermal pressure the BLE owner deliberately
        // keeps journaling while skipping the heavier canonical checkpoint;
        // without this invalidation a complete effort could remain invisible
        // to workout review until some unrelated later session mutation.
        invalidateWorkoutReviewCache()
        dashboardRevision &+= 1
    }

    private func handleActiveJournalSleepReviewCacheWarm(
        _ event: ActiveSessionJournal.SleepReviewCacheWarmEvent
    ) {
        handleActiveJournalSleepReviewCacheWarm(
            event,
            applicationIsActive:
                UIApplication.shared.applicationState == .active
        ) { [weak self] in
            guard let self else { return }
            self.scheduleSleepReviewCacheRefresh(
                rest: self.baseline.restingInt ?? 60,
                calendar: .current,
                reason: "active_journal_cache_warmed"
            )
        }
    }

    private func handleActiveJournalSleepReviewCacheWarm(
        _ event: ActiveSessionJournal.SleepReviewCacheWarmEvent,
        applicationIsActive: Bool,
        scheduleRefresh: () -> Void
    ) {
        guard event.generation
                > activeJournalSleepReviewCacheWarmGeneration else {
            return
        }
        activeJournalSleepReviewCacheWarmGeneration = event.generation
        // Supersede a cold-failing generation even when this event lands
        // between its cache read and its MainActor catch. The old completion
        // can no longer publish or clear the replacement request.
        invalidateSleepReviewCache(
            reason: "active_journal_cache_warmed",
            scheduleRefresh: false
        )
        guard sleepReviewProjectionForegroundAuthority,
              applicationIsActive,
              !restoreInitializationBlocked else {
            sleepReviewRefreshDeferredUntilForeground = true
            AtriaDebugLog(
                "ATRIADBG sleep_review_projection reason=active_journal_cache_warmed app_state=%@ generation=%d outcome=deferred duration_ms=0 published=0",
                Self.sleepReviewApplicationStateLabel(
                    UIApplication.shared.applicationState
                ),
                sleepReviewCacheGeneration
            )
            return
        }
        sleepReviewRefreshDeferredUntilForeground = false
        scheduleRefresh()
    }

    #if DEBUG
    func handleActiveJournalSleepReviewCacheWarmForTesting(
        _ event: ActiveSessionJournal.SleepReviewCacheWarmEvent,
        applicationIsActive: Bool,
        scheduleRefresh: () -> Void
    ) {
        handleActiveJournalSleepReviewCacheWarm(
            event,
            applicationIsActive: applicationIsActive,
            scheduleRefresh: scheduleRefresh
        )
    }
    #endif

