    var latestReferenceValidatedHRV: Int? {
        cachedLatestReferenceValidatedHRV
    }

    var latestLocalRMSSD: Int? {
        cachedLatestLocalRMSSD
    }

    /// Saved HRV can support longitudinal baselines indefinitely, but the
    /// dashboard must not present an old session as today's measurement.
    /// Keep display freshness separate from recovery's stricter morning gate.
    nonisolated static let hrvDisplayMaximumAge: TimeInterval = 24 * 60 * 60

    var latestReferenceValidatedHRVForDisplay: LatestSessionMetricSource? {
        Self.displayEligibleHRVSource(cachedLatestReferenceValidatedHRVSource)
    }

    var latestLocalRMSSDForDisplay: LatestSessionMetricSource? {
        Self.displayEligibleHRVSource(cachedLatestLocalRMSSDSource)
    }

    func latestReferenceValidatedRecoveryHRV(on now: Date = Date(),
                                             calendar: Calendar = .current) -> Int? {
        let cycle = AtriaPhysiologicalCycle.current(now: now,
                                                    confirmedSleeps: cachedConfirmedSleeps,
                                                    calendar: calendar)
        if cycle.boundaryKind == .mainSleep,
           let anchor = AtriaPhysiologicalCycle.latestCompletedMainSleep(
                now: now,
                confirmedSleeps: cachedConfirmedSleeps,
                calendar: calendar
            ) {
            return cachedCanonicalSessions.lazy
                .filter {
                    $0.start >= anchor.start.addingTimeInterval(-5 * 60)
                        && $0.end <= anchor.end.addingTimeInterval(5 * 60)
                }
                .compactMap { Self.referenceValidatedHRVSource(for: $0) }
                .max { $0.end < $1.end }?
                .value
        }
        guard cycle.boundaryKind == .initialFallback else { return nil }
        return Self.recoveryEligibleHRVSource(cachedLatestReferenceValidatedHRVSource,
                                              on: now,
                                              calendar: calendar)?.value
    }

    func latestLocalRecoveryHRV(on now: Date = Date(),
                                calendar: Calendar = .current) -> Int? {
        let cycle = AtriaPhysiologicalCycle.current(now: now,
                                                    confirmedSleeps: cachedConfirmedSleeps,
                                                    calendar: calendar)
        if cycle.boundaryKind == .mainSleep,
           let anchor = AtriaPhysiologicalCycle.latestCompletedMainSleep(
                now: now,
                confirmedSleeps: cachedConfirmedSleeps,
                calendar: calendar
           ) {
            if let hrv = anchor.hrv, hrv > 0 { return hrv }
            // The confirmed sleep's HRV is computed from that exact window. If
            // it has no qualifying RR window, a whole-session aggregate must not
            // be substituted and mislabeled as this cycle's overnight HRV.
            return nil
        }
        guard cycle.boundaryKind == .initialFallback else { return nil }
        return Self.recoveryEligibleHRVSource(cachedLatestLocalRMSSDSource,
                                              on: now,
                                              calendar: calendar)?.value
    }

    var confirmedWorkouts: [UserConfirmedWorkout] {
        cachedConfirmedWorkouts
    }

    var confirmedSleeps: [UserConfirmedSleep] {
        cachedConfirmedSleeps
    }

    /// The confirmed main sleep that owns the active physiological cycle.
    /// Candidates and naps deliberately return nil: neither may replace the
    /// readiness inputs established by a confirmed wake boundary.
    func currentPhysiologicalMainSleep(on now: Date = Date(),
                                       calendar: Calendar = .current) -> SleepHistorySnapshot.Night? {
        let cycle = AtriaPhysiologicalCycle.current(now: now,
                                                    confirmedSleeps: cachedConfirmedSleeps,
                                                    calendar: calendar)
        guard cycle.boundaryKind == .mainSleep,
              let anchorSleepID = cycle.anchorSleepID else { return nil }
        return sleepHistorySnapshot.nights.first {
            $0.id == anchorSleepID && $0.confirmed && !$0.isNapEvidence
        }
    }

    /// One authority for the RHR number shown to the user during the active
    /// physiological cycle. A learned baseline remains the stable anchor for
    /// zones, TRIMP, strain and VO2 calculations, but it is not today's RHR.
    /// Prefer the exact confirmed sleep, then the durable current-cycle metric,
    /// then current-cycle wear evidence. This prevents Home/widgets from
    /// showing the baseline beside a different recovery-driving RHR in Vitals.
    func currentCycleRestingHeartRateForPresentation(
        on now: Date = Date(),
        calendar: Calendar = .current
    ) -> Int? {
        let cycle = AtriaPhysiologicalCycle.current(now: now,
                                                    confirmedSleeps: cachedConfirmedSleeps,
                                                    calendar: calendar)
        let sleepResting = currentPhysiologicalMainSleep(on: now, calendar: calendar)?.restingHR
        let metricResting = dailyMetricHistory.first {
            calendar.isDate($0.day, inSameDayAs: cycle.start)
        }?.restingHR
        let rollupResting = dailyRollupHistory.first {
            calendar.isDate($0.day, inSameDayAs: cycle.start)
        }?.rhr
        return Self.presentationRestingHeartRate(
            sleepRestingHeartRate: sleepResting,
            metricRestingHeartRate: metricResting,
            rollupRestingHeartRate: rollupResting
        )
    }

    /// Sleep-cycle authorities ONLY (2026-08-04 provenance decision): the
    /// number labeled "Resting" must come from sleep evidence — the main
    /// sleep's measured RHR, or the persisted daily metric/rollup derived
    /// from it. The old daytime fallbacks (live low-HR window, a saved wear
    /// session's restingStable) could surface an awake-day estimate as
    /// "Resting 119" with no source label; until the first night lands the
    /// rail now shows the honest no-value token instead. Recovery math is
    /// unaffected — it reads restingContext.currentForRecovery, not this.
    nonisolated static func presentationRestingHeartRate(
        sleepRestingHeartRate: Int?,
        metricRestingHeartRate: Int?,
        rollupRestingHeartRate: Int?
    ) -> Int? {
        [
            sleepRestingHeartRate,
            metricRestingHeartRate,
            rollupRestingHeartRate,
        ]
        .compactMap { value in
            guard let value, value > 0 else { return nil }
            return value
        }
        .first
    }

    /// Canonical recovery projection for interactive and background surfaces.
    ///
    /// A frozen morning value always wins and an all-nighter cycle always fails
    /// closed. Only the short pre-freeze/initial-wear interval can evaluate
    /// Recovery v2, and an unchanged overnight input set is evaluated at most
    /// once every four hours. This keeps Home, widgets and notifications on one
    /// score without turning every heart-rate publish into a baseline scan.
    func recoveryProjection(now: Date = Date(),
                            calendar: Calendar = .current,
                            initialFallbackHRVSnapshot: HRVSnapshot?,
                            liveRestingHeartRate: Int?) -> Metrics.RecoveryEstimate {
        let cycle = AtriaPhysiologicalCycle.current(now: now,
                                                    confirmedSleeps: cachedConfirmedSleeps,
                                                    calendar: calendar)
        let latestSleep = currentPhysiologicalMainSleep(on: now, calendar: calendar)
        let frozen = Self.numericFrozenRecovery(
            DailyRecoveryResolver.summary(rollups: dailyRollupHistory,
                                          metrics: dailyMetricHistory,
                                          physiologicalCycle: cycle,
                                          anchorSleep: latestSleep,
                                          calendar: calendar)?.recoveryEstimate
        )
        // Preserve lazy semantics even for the terminal paths. The cache's
        // autoclosure contract is covered by counter tests so future refactors
        // cannot accidentally run Recovery v2 before checking frozen recovery.
        if frozen != nil {
            return recoveryProjectionCache.resolve(
                frozen: frozen,
                cycle: cycle,
                fingerprint: RecoveryProjectionFingerprint(),
                confirmedSleepsRevision: confirmedSleepsRevision,
                now: now,
                ttl: Self.provisionalRecoveryProjectionTTL,
                provisional: DailyRecoveryResolver.noSleepEstimate
            )
        }

        let validatedHRV = latestReferenceValidatedRecoveryHRV(on: now, calendar: calendar)
        let fallbackHRV = validatedHRV ?? latestLocalRecoveryHRV(on: now, calendar: calendar)
        let respiratoryBaseline = sleepHistorySnapshot.respiratoryBaselineStats
        let restingStats = baseline.restingStats(now: now)
        let lnRMSSDStats = baseline.lnRMSSDStats(now: now)
        // The confirmed overnight RHR owns a main-sleep recovery. Before that
        // exists, every consumer supplies the same BLE-derived resting reading;
        // a saved session is the last honest fallback. A learned baseline is a
        // comparator, never a fabricated current-cycle measurement.
        let restingHeartRate = Self.recoveryRestingHeartRate(
            sleepRestingHeartRate: latestSleep?.restingHR,
            liveRestingHeartRate: liveRestingHeartRate,
            canonicalSessions: cachedCanonicalSessions
        )
        let liveSnapshot = cycle.boundaryKind == .initialFallback
            ? initialFallbackHRVSnapshot
            : nil
        let fingerprint = RecoveryProjectionFingerprint(
            liveHRVRMSSD: liveSnapshot?.isReady == true ? liveSnapshot?.rmssd : nil,
            liveHRVIsReady: liveSnapshot?.isReady == true,
            fallbackRMSSD: fallbackHRV,
            restingHeartRate: restingHeartRate,
            hrvReferenceValidated: validatedHRV != nil,
            sleepID: latestSleep?.id,
            sleepEfficiency: Self.recoverySleepEfficiency(from: latestSleep),
            sleepDurationHours: latestSleep?.durationHours,
            respiratoryRate: latestSleep?.respiratoryRate,
            respiratoryBaselineMean: respiratoryBaseline?.mean,
            respiratoryBaselineSD: respiratoryBaseline?.sd,
            respiratoryBaselineCount: respiratoryBaseline?.count ?? 0,
            baselineRestingMean: restingStats?.mean,
            baselineRestingSD: restingStats?.sd,
            baselineRestingCount: restingStats?.count ?? 0,
            baselineLnRMSSDMean: lnRMSSDStats?.mean,
            baselineLnRMSSDSD: lnRMSSDStats?.sd,
            baselineLnRMSSDCount: lnRMSSDStats?.count ?? 0,
            baselineRestingIsTrusted: baseline.hasTrustedRestingBaseline(now: now),
            baselineHRVIsTrusted: baseline.hasTrustedHRVBaseline(now: now),
            baselineRestingEMA: baseline.restingHR,
            baselineHRVEMA: baseline.hrvEMA,
            baselineUpdatedAt: baseline.updated
        )
        return recoveryProjectionCache.resolve(
            frozen: nil,
            cycle: cycle,
            fingerprint: fingerprint,
            confirmedSleepsRevision: confirmedSleepsRevision,
            now: now,
            ttl: Self.provisionalRecoveryProjectionTTL,
            provisional: Metrics.recoveryV2(
                hrvSnapshot: liveSnapshot,
                fallbackRMSSD: fallbackHRV,
                restingNow: restingHeartRate,
                baseline: baseline,
                hrvReferenceValidated: validatedHRV != nil,
                sleepEfficiency: Self.recoverySleepEfficiency(from: latestSleep),
                sleepDurationHours: latestSleep?.durationHours,
                // Recovery v4: cache invalidation is already covered — the
                // sleep baseline derives from confirmedSleepsRevision and the
                // robust comparator from the fingerprinted baseline stats.
                sleepBaseline: sleepHistorySnapshot.sleepBaselineStats,
                respiratoryRate: latestSleep?.respiratoryRate,
                respiratoryBaseline: respiratoryBaseline,
                now: now
            )
        )
    }

    /// A persisted recovery summary with no score is useful audit context, but
    /// it is not a morning score. Treating it as an immutable freeze made an
    /// old "Learning" row keep the Recovery card grey even after a measured
    /// sleep supplied enough evidence for the conservative, no-HRV estimate.
    ///
    /// Numeric frozen scores still win exactly as before. This only reopens the
    /// projection for a scoreless legacy/partial summary; the projection itself
    /// still fails closed when it has no real sleep, RHR, or HRV evidence.
    nonisolated static func numericFrozenRecovery(
        _ candidate: Metrics.RecoveryEstimate?
    ) -> Metrics.RecoveryEstimate? {
        guard let candidate, candidate.percent != nil else { return nil }
        return candidate
    }

    /// Presentation-only recovery for Home's live rings and cards.
    ///
    /// A real, current main-sleep review may provide a useful first-night number
    /// before the user confirms it, but only while canonical Recovery has no
    /// numeric result. That number is deliberately computed outside
    /// `recoveryProjection`: it never enters the four-hour canonical cache, daily
    /// metric freeze/remint, HealthKit, notifications, or baseline learning. Any
    /// canonical number, including a limited RHR-only day-one estimate, remains
    /// authoritative so Home and Recovery detail cannot show different scores.
    func recoveryProjectionForPresentation(
        now: Date = Date(),
        calendar: Calendar = .current,
        initialFallbackHRVSnapshot: HRVSnapshot?,
        liveRestingHeartRate: Int?,
        pendingSleepReview: SleepHistorySnapshot.Night?
    ) -> Metrics.RecoveryEstimate {
        let authoritative = recoveryProjection(
            now: now,
            calendar: calendar,
            initialFallbackHRVSnapshot: initialFallbackHRVSnapshot,
            liveRestingHeartRate: liveRestingHeartRate
        )
        let cycle = AtriaPhysiologicalCycle.current(
            now: now,
            confirmedSleeps: cachedConfirmedSleeps,
            calendar: calendar
        )
        let confirmedMainSleep = currentPhysiologicalMainSleep(on: now, calendar: calendar)
        let hasFrozenRecovery = DailyRecoveryResolver.summary(
            rollups: dailyRollupHistory,
            metrics: dailyMetricHistory,
            physiologicalCycle: cycle,
            anchorSleep: confirmedMainSleep,
            calendar: calendar
        ) != nil
        return Self.presentationRecoveryEstimate(
            authoritative: authoritative,
            hasConfirmedMainSleep: confirmedMainSleep != nil,
            hasFrozenRecovery: hasFrozenRecovery,
            pendingSleepReview: pendingSleepReview,
            baseline: baseline,
            respiratoryBaseline: sleepHistorySnapshot.respiratoryBaselineStats,
            now: now,
            physiologicalCycle: cycle,
            calendar: calendar
        )
    }

    /// Pure authority boundary used by the production Home projection. Pending
    /// review evidence can only fill an unfrozen, pre-confirmation presentation
    /// absence and is confidence-capped to `.unverified` even if mature baselines
    /// would otherwise make Recovery v2 return a stronger tier.
    nonisolated static func presentationRecoveryEstimate(
        authoritative: Metrics.RecoveryEstimate,
        hasConfirmedMainSleep: Bool,
        hasFrozenRecovery: Bool,
        pendingSleepReview: SleepHistorySnapshot.Night?,
        baseline: PersonalBaseline,
        respiratoryBaseline: (mean: Double, sd: Double, count: Int)?,
        now: Date,
        physiologicalCycle: AtriaPhysiologicalCycle,
        calendar: Calendar = .current,
        maximumPendingAge: TimeInterval = 24 * 60 * 60
    ) -> Metrics.RecoveryEstimate {
        // A pending detector review is weaker than every numeric canonical
        // Recovery result. It may provide a transparent day-one preview only
        // when canonical Recovery is still scoreless; otherwise substituting it
        // makes Home disagree with the frozen detail/history authority.
        guard authoritative.percent == nil,
              authoritative.confidence == .learning,
              !hasConfirmedMainSleep, !hasFrozenRecovery,
              let pending = pendingSleepRecoveryEstimate(
                pendingSleepReview,
                baseline: baseline,
                respiratoryBaseline: respiratoryBaseline,
                now: now,
                physiologicalCycle: physiologicalCycle,
                calendar: calendar,
                maximumAge: maximumPendingAge
              ) else {
            return authoritative
        }
        return pending
    }

    /// Converts a detector-owned review into a display-only estimate. This gate
    /// accepts only a recent, well-formed main-sleep review; naps, confirmed rows,
    /// future/stale windows and malformed physiology fail closed.
    nonisolated static func pendingSleepRecoveryEstimate(
        _ night: SleepHistorySnapshot.Night?,
        baseline: PersonalBaseline,
        respiratoryBaseline: (mean: Double, sd: Double, count: Int)?,
        now: Date,
        physiologicalCycle: AtriaPhysiologicalCycle,
        calendar: Calendar = .current,
        maximumAge: TimeInterval = 24 * 60 * 60,
        maximumFutureSkew: TimeInterval = 5 * 60
    ) -> Metrics.RecoveryEstimate? {
        guard let night,
              !night.confirmed,
              !night.isNapEvidence,
              let start = night.start,
              let end = night.end,
              end > start,
              night.duration >= AggregateSleepCandidate.strictMinimumDuration
                - AggregateSleepCandidate.nearStrictMorningReviewTolerance,
              night.duration <= end.timeIntervalSince(start) + 60,
              end <= now.addingTimeInterval(maximumFutureSkew),
              now.timeIntervalSince(end) <= maximumAge,
              now.timeIntervalSince(end) >= -maximumFutureSkew,
              pendingSleepReviewBelongsToCurrentCycle(
                night,
                physiologicalCycle: physiologicalCycle,
                calendar: calendar
              ),
              maximumAge > 0 else {
            return nil
        }
        if let efficiency = recoverySleepEfficiency(from: night),
           !efficiency.isFinite || !(0...1).contains(efficiency) {
            return nil
        }
        if let resting = night.restingHR, !(35...240).contains(resting) {
            return nil
        }
        if let hrv = night.hrv, !(5...500).contains(hrv) {
            return nil
        }
        if let respiration = night.respiratoryRate,
           !respiration.isFinite || !(5...40).contains(respiration) {
            return nil
        }

        // Match canonical sleep truth: fewer than three qualified windows is too
        // sparse to let HRV control a recovery number. A bare integer from
        // legacy/projected data is not a measurement.
        let pendingHRV = night.hrvWindowCount >= AtriaSleepBudget.minimumQualifiedHRVWindows
            ? night.hrv
            : nil
        let estimate = Metrics.recoveryV2(
            hrvSnapshot: nil,
            fallbackRMSSD: pendingHRV,
            restingNow: night.restingHR,
            baseline: baseline,
            hrvReferenceValidated: false,
            sleepEfficiency: recoverySleepEfficiency(from: night),
            sleepDurationHours: night.durationHours,
            respiratoryRate: night.respiratoryRate,
            respiratoryBaseline: respiratoryBaseline
        )
        guard estimate.percent != nil else { return nil }
        return Metrics.RecoveryEstimate(
            percent: estimate.percent,
            confidence: .unverified,
            usesHRV: estimate.usesHRV,
            detail: "Today · pending sleep review · limited confidence · \(estimate.detail)",
            contributors: estimate.contributors
        )
    }

    /// A review normally belongs to the active cycle when it wakes after the
    /// current boundary. The one exception is an overnight episode that ends
    /// shortly before the deterministic morning fallback (06:00 for initial
    /// wear, or the learned wake fallback thereafter). It must end on the same
    /// civil day as that boundary and contain real sleep-core overlap; a prior
    /// day's afternoon/evening candidate can therefore never leak through a
    /// rollover merely because it is less than 24 hours old.
    nonisolated static func pendingSleepReviewBelongsToCurrentCycle(
        _ night: SleepHistorySnapshot.Night,
        physiologicalCycle: AtriaPhysiologicalCycle,
        calendar: Calendar = .current
    ) -> Bool {
        guard let start = night.start,
              let end = night.end,
              end > start else { return false }
        if end >= physiologicalCycle.start { return true }
        guard calendar.isDate(end, inSameDayAs: physiologicalCycle.start),
              end <= physiologicalCycle.start,
              calendar.component(.hour, from: end) <= 11 else {
            return false
        }
        return sleepCoreOverlapDuration(start: start, end: end, calendar: calendar)
            >= AggregateSleepCandidate.minimumAutoConfirmSleepCoreOverlap
    }

    /// Resolve the current-cycle RHR without letting a transport sentinel or a
    /// stale duplicate session enter Recovery v2. A confirmed sleep owns the
    /// metric when present; otherwise a physiologically plausible live sample
    /// wins, followed by the newest durable canonical session. The learned
    /// baseline remains a comparator and is never substituted as today's value.
    nonisolated static func recoveryRestingHeartRate(
        sleepRestingHeartRate: Int?,
        liveRestingHeartRate: Int?,
        canonicalSessions: [SavedSession]
    ) -> Int? {
        if let sleepRestingHeartRate, (35...240).contains(sleepRestingHeartRate) {
            return sleepRestingHeartRate
        }
        if let liveRestingHeartRate, (35...240).contains(liveRestingHeartRate) {
            return liveRestingHeartRate
        }
        return canonicalSessions.lazy
            .map(\.restingStable)
            .first { (35...240).contains($0) }
    }

    var behaviorJournalEntries: [BehaviorJournalEntry] {
        cachedBehaviorJournalEntries
    }

    /// Shared plan snapshot for Today-adjacent planning surfaces. The weekly
    /// plan store may synchronously read/write its cache file; keeping this
    /// memo on SessionStore prevents Plan and Overview from each doing the same
    /// disk + rollup work after a single rollup/week change.
    func currentWeeklyPlan(now: Date = Date()) -> WeeklyPlan {
        let calendar = Self.currentWeeklyPlanCalendar()
        let weekStart = calendar.dateInterval(of: .weekOfYear, for: now)?.start ?? calendar.startOfDay(for: now)
        let revision = dailyRollupHistoryRevision
        if cachedWeeklyPlanRevision == revision,
           cachedWeeklyPlanWeekStart == weekStart,
           let cachedWeeklyPlanValue {
            return cachedWeeklyPlanValue
        }

        let plan = weeklyPlanStore.currentPlan(rollups: dailyRollupHistory,
                                               now: now,
                                               calendar: calendar)
        cachedWeeklyPlanRevision = revision
        cachedWeeklyPlanWeekStart = weekStart
        cachedWeeklyPlanValue = plan
        return plan
    }

    /// Settings and other secondary surfaces should never rebuild a weekly
    /// report while their presentation transaction is committing. Rollups are
    /// immutable between revision bumps, so this reduces the gear-open path to
    /// an O(1) cache read while still rolling over at the ISO week boundary.
    func currentWeeklyRecovery(now: Date = Date()) -> Int? {
        let calendar = Self.currentWeeklyPlanCalendar()
        let weekStart = calendar.dateInterval(of: .weekOfYear, for: now)?.start
            ?? calendar.startOfDay(for: now)
        let revision = dailyRollupHistoryRevision
        if hasCachedWeeklyRecovery,
           cachedWeeklyRecoveryRevision == revision,
           cachedWeeklyRecoveryWeekStart == weekStart {
            return cachedWeeklyRecoveryValue
        }

        let recovery = WeeklyReport(rollups: dailyRollupHistory,
                                    now: now,
                                    calendar: calendar).recoveryAvg
        cachedWeeklyRecoveryRevision = revision
        cachedWeeklyRecoveryWeekStart = weekStart
        cachedWeeklyRecoveryValue = recovery
        hasCachedWeeklyRecovery = true
        return recovery
    }

    var researchManeuverMarkers: [ResearchManeuverMarker] {
        cachedResearchManeuverMarkers
    }

    private static func currentWeeklyPlanCalendar() -> Calendar {
        var calendar = Calendar(identifier: .iso8601)
        calendar.timeZone = .current
        return calendar
    }

    private func refreshSessionDerivedCaches() {
        setCachedCanonicalSessions(Self.makeCanonicalSessions(
            from: sessions + cachedRecoveredHeartRateSessions
        ))
        refreshLatestHRVSourcesFromCanonicalSessions()
        cachedHomeSavedAggregate = nil
        cachedTodayTRIMP = nil
        cachedCurrentCollectionStatus = nil
        refreshMaxHRSuggestion(reason: "session_cache", force: false)
    }

    /// HRV consumers must follow the same canonical session authority as
    /// sleep, recovery and history. In particular, recovered Whoop 4 archive
    /// RR is absent from the raw `sessions` array by design.
    private func refreshLatestHRVSourcesFromCanonicalSessions() {
        setLatestReferenceValidatedHRVSource(
            Self.latestReferenceValidatedHRVSource(in: cachedCanonicalSessions)
        )
        setLatestLocalRMSSDSource(
            Self.latestLocalRMSSDSource(in: cachedCanonicalSessions)
        )
    }

    private func refreshSessionDerivedCachesAfterUpsert(
        _ session: SavedSession,
        advancesBiologicalAgeSourceGeneration: Bool = true,
        replacesCanonicalSessionWithSameID: Bool = false,
        refreshHRV: Bool = true,
        scheduleSleepReviewRefresh: Bool = true
    ) {
        if refreshHRV {
            setLatestReferenceValidatedHRVSource(Self.latestReferenceValidatedHRVSourceAfterUpsert(
                session,
                cached: cachedLatestReferenceValidatedHRVSource,
                sessions: sessions
            ))
            setLatestLocalRMSSDSource(Self.latestLocalRMSSDSourceAfterUpsert(
                session,
                cached: cachedLatestLocalRMSSDSource,
                sessions: sessions
            ))
        }
        setCachedCanonicalSessions(Self.canonicalSessionsAfterUpsert(
            session,
            into: cachedCanonicalSessions,
            preferredSession: preferredSession,
            replacesSameID: replacesCanonicalSessionWithSameID
        ),
        advancesBiologicalAgeSourceGeneration: advancesBiologicalAgeSourceGeneration,
        scheduleSleepReviewRefresh: scheduleSleepReviewRefresh)
        cachedHomeSavedAggregate = nil
        cachedTodayTRIMP = nil
        cachedCurrentCollectionStatus = nil
        refreshMaxHRSuggestion(reason: "session_upsert", force: false)
    }

    private func setCachedCanonicalSessions(
        _ sessions: [SavedSession],
        advancesBiologicalAgeSourceGeneration: Bool = true,
        scheduleSleepReviewRefresh: Bool = true
    ) {
        cachedCanonicalSessions = sessions
        // A checkpoint commonly replaces one canonical session in place. Count
        // equality therefore says nothing about whether sleep evidence changed.
        canonicalSessionsRevision &+= 1
        if advancesBiologicalAgeSourceGeneration {
            biologicalAgeSourceSessionsRevision &+= 1
        }
        if scheduleSleepReviewRefresh {
            reviewEvidenceRevision &+= 1
            invalidateSleepReviewCache(reason: "canonical_sessions")
        }
    }

    private func setCachedConfirmedSleeps(
        _ sleeps: [UserConfirmedSleep],
        refreshDerivedCaches: Bool = true
    ) {
        cachedConfirmedSleeps = sleeps
        backupCanonicalRevision &+= 1
        confirmedSleepsRevision &+= 1
        // A main-sleep edit/delete can move the physiological-day boundary.
        // Never retain aggregates or zone minutes computed for the old cycle.
        cachedHomeSavedAggregate = nil
        cachedTodayTRIMP = nil
        lastTodayHRZoneMinutesCheckpointRefreshAt = nil
        if refreshDerivedCaches {
            refreshTodayHRZoneMinutesCache(deferred: true)
        }
        invalidateSleepReviewCache(
            reason: "confirmed_sleeps",
            scheduleRefresh: refreshDerivedCaches
        )
    }

    private func setLatestReferenceValidatedHRVSource(_ source: LatestSessionMetricSource?) {
        cachedLatestReferenceValidatedHRVSource = source
        cachedLatestReferenceValidatedHRV = source?.value
    }

    private func setLatestLocalRMSSDSource(_ source: LatestSessionMetricSource?) {
        cachedLatestLocalRMSSDSource = source
        cachedLatestLocalRMSSD = source?.value
    }

    private func refreshBackupStatusCache() {
        cachedSessionBackupStatus = computeSessionBackupStatus()
    }

    nonisolated static func latestLocalRMSSD(in sessions: [SavedSession]) -> Int? {
        // Recovery freezes to the overnight/morning reading like WHOOP: prefer the
        // most recent overnight-window session's HRV; only fall back to any session
        // if no overnight HRV exists yet (so the baseline never starves).
        latestLocalRMSSDSource(in: sessions)?.value
    }

    nonisolated static func latestReferenceValidatedHRVSource(in sessions: [SavedSession]) -> LatestSessionMetricSource? {
        for session in sessions {
            if let source = referenceValidatedHRVSource(for: session) {
                return source
            }
        }
        return nil
    }

    nonisolated static func latestLocalRMSSDSource(in sessions: [SavedSession]) -> LatestSessionMetricSource? {
        for session in sessions {
            if session.isOvernightHRVWindow(), let source = localRMSSDSource(for: session, priority: 1) {
                return source
            }
        }
        for session in sessions {
            if let source = localRMSSDSource(for: session) {
                return source
            }
        }
        return nil
    }

    nonisolated static func latestReferenceValidatedHRVSourceCancellable(
        in sessions: [SavedSession],
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> LatestSessionMetricSource?? {
        for (sessionIndex, session) in sessions.enumerated() {
            if sessionIndex.isMultiple(of: 32), !shouldContinue() {
                return nil
            }
            guard session.hrvReferenceValidated == true,
                  let hrv = session.hrv,
                  hrv > 0,
                  let rrPoints = session.rrPoints,
                  !rrPoints.isEmpty else { continue }
            var qualified = true
            for (index, point) in rrPoints.enumerated() {
                if index.isMultiple(of: 256), !shouldContinue() {
                    return nil
                }
                if point.source != .standardHeartRateMeasurement2A37 {
                    qualified = false
                    break
                }
            }
            if qualified {
                return .some(.init(
                    sessionID: session.id,
                    start: session.start,
                    end: session.end,
                    value: hrv,
                    priority: 0
                ))
            }
        }
        return shouldContinue() ? .some(nil) : nil
    }

    nonisolated static func latestLocalRMSSDSourceCancellable(
        in sessions: [SavedSession],
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> LatestSessionMetricSource?? {
        func firstSource(overnightOnly: Bool) -> LatestSessionMetricSource?? {
            for (index, session) in sessions.enumerated() {
                if index.isMultiple(of: 32), !shouldContinue() { return nil }
                if overnightOnly, !session.isOvernightHRVWindow() { continue }
                if let value = session.localRMSSDCancellable(
                    shouldContinue: shouldContinue
                ) {
                    return .some(.init(
                        sessionID: session.id,
                        start: session.start,
                        end: session.end,
                        value: value,
                        priority: overnightOnly ? 1 : 0
                    ))
                }
                guard shouldContinue() else { return nil }
            }
            return .some(nil)
        }
        guard let overnight = firstSource(overnightOnly: true) else {
            return nil
        }
        if let overnight { return .some(overnight) }
        return firstSource(overnightOnly: false)
    }

    nonisolated static func recoveryEligibleHRVSource(
        _ source: LatestSessionMetricSource?,
        on now: Date,
        calendar: Calendar = .current
    ) -> LatestSessionMetricSource? {
        guard let source,
              source.end <= now.addingTimeInterval(5 * 60),
              now.timeIntervalSince(source.end) <= 24 * 60 * 60,
              calendar.isDate(source.end, inSameDayAs: now) else { return nil }
        let hour = calendar.component(.hour, from: source.end)
        guard (4...11).contains(hour) else { return nil }
        return source
    }

    nonisolated static func displayEligibleHRVSource(
        _ source: LatestSessionMetricSource?,
        on now: Date = Date(),
        maximumAge: TimeInterval = hrvDisplayMaximumAge
    ) -> LatestSessionMetricSource? {
        guard let source else { return nil }
        let age = now.timeIntervalSince(source.end)
        guard age >= -5 * 60, age <= maximumAge else { return nil }
        return source
    }

    nonisolated static func latestReferenceValidatedHRVSourceAfterUpsert(
        _ session: SavedSession,
        cached: LatestSessionMetricSource?,
        sessions: [SavedSession]
    ) -> LatestSessionMetricSource? {
        latestSessionMetricSourceAfterUpsert(
            referenceValidatedHRVSource(for: session),
            replacing: session.id,
            cached: cached,
            sessions: sessions,
            recompute: latestReferenceValidatedHRVSource(in:)
        )
    }

    nonisolated static func latestLocalRMSSDSourceAfterUpsert(
        _ session: SavedSession,
        cached: LatestSessionMetricSource?,
        sessions: [SavedSession]
    ) -> LatestSessionMetricSource? {
        if let cached,
           cached.sessionID != session.id,
           cached.priority > 0,
           !session.isOvernightHRVWindow() {
            return cached
        }
        return latestSessionMetricSourceAfterUpsert(
            localRMSSDSource(for: session),
            replacing: session.id,
            cached: cached,
            sessions: sessions,
            recompute: latestLocalRMSSDSource(in:)
        )
    }

    private nonisolated static func latestSessionMetricSourceAfterUpsert(
        _ incoming: LatestSessionMetricSource?,
        replacing sessionID: UUID,
        cached: LatestSessionMetricSource?,
        sessions: [SavedSession],
        recompute: ([SavedSession]) -> LatestSessionMetricSource?
    ) -> LatestSessionMetricSource? {
        guard let cached else { return incoming }
        guard let incoming else {
            return cached.sessionID == sessionID ? recompute(sessions) : cached
        }
        guard cached.sessionID == sessionID else {
            return prefersLatestMetricSource(incoming, over: cached) ? incoming : cached
        }
        if incoming.priority < cached.priority
            || (incoming.priority == cached.priority && incoming.start < cached.start) {
            return recompute(sessions)
        }
        return incoming
    }

    private nonisolated static func referenceValidatedHRVSource(for session: SavedSession) -> LatestSessionMetricSource? {
        guard let hrv = session.referenceValidatedHRV else { return nil }
        return LatestSessionMetricSource(sessionID: session.id,
                                         start: session.start,
                                         end: session.end,
                                         value: hrv,
                                         priority: 0)
    }

    private nonisolated static func localRMSSDSource(
        for session: SavedSession,
        priority: Int? = nil
    ) -> LatestSessionMetricSource? {
        guard let hrv = session.localRMSSD else { return nil }
        return LatestSessionMetricSource(sessionID: session.id,
                                         start: session.start,
                                         end: session.end,
                                         value: hrv,
                                         priority: priority ?? (session.isOvernightHRVWindow() ? 1 : 0))
    }

    private nonisolated static func prefersLatestMetricSource(
        _ candidate: LatestSessionMetricSource,
        over current: LatestSessionMetricSource
    ) -> Bool {
        if candidate.priority != current.priority {
            return candidate.priority > current.priority
        }
        return candidate.start >= current.start
    }

    private func refreshBackupStatusCacheDeferred(reason: String,
                                                  expectedAutomaticGeneration: Int? = nil,
                                                  expectedStatusGeneration: UInt64? = nil) {
        let publicationGeneration: UInt64
        if let expectedStatusGeneration {
            publicationGeneration = expectedStatusGeneration
        } else {
            sessionBackupStatusGeneration &+= 1
            publicationGeneration = sessionBackupStatusGeneration
        }
        let currentSessions = sessions
        let currentBaseline = baseline
        let currentProfile = profile
        let currentDailyMetrics = dailyMetricHistory
        let currentDailyRollups = dailyRollupHistory.isEmpty
            ? dailyRollupStore.rollups(last: 400)
            : dailyRollupHistory
        let currentConfirmedSleeps = cachedConfirmedSleeps
        let currentConfirmedWorkouts = cachedConfirmedWorkouts
        let sessionFileURL = url
        Task.detached(priority: .utility) { [currentSessions, currentBaseline, currentProfile, currentDailyMetrics, currentDailyRollups, currentConfirmedSleeps, currentConfirmedWorkouts, sessionFileURL] in
            let startedAt = CFAbsoluteTimeGetCurrent()
            let status = Self.computeSessionBackupStatus(currentSessions: currentSessions,
                                                         baseline: currentBaseline,
                                                         profile: currentProfile,
                                                         dailyMetrics: currentDailyMetrics,
                                                         dailyRollups: currentDailyRollups,
                                                         confirmedSleeps: currentConfirmedSleeps,
                                                         confirmedWorkouts: currentConfirmedWorkouts,
                                                         sessionFileURL: sessionFileURL)
            let elapsedMS = Int(((CFAbsoluteTimeGetCurrent() - startedAt) * 1000).rounded())
            await MainActor.run { [weak self] in
                guard let self else { return }
                guard Self.backupStatusGenerationIsCurrent(
                    resultGeneration: publicationGeneration,
                    currentGeneration: self.sessionBackupStatusGeneration
                ) else {
                    AtriaDebugLog("ATRIADBG session_backup_status_deferred status=superseded reason=%@ generation=%llu current_generation=%llu",
                                  reason,
                                  publicationGeneration,
                                  self.sessionBackupStatusGeneration)
                    return
                }
                if let expectedAutomaticGeneration,
                   expectedAutomaticGeneration != self.automaticBackupGeneration {
                    AtriaDebugLog("ATRIADBG session_backup_status_deferred status=superseded reason=%@ generation=%d current_generation=%d",
                                  reason,
                                  expectedAutomaticGeneration,
                                  self.automaticBackupGeneration)
                    return
                }
                self.cachedSessionBackupStatus = status
                self.cachedHomeDashboardDiagnostics = nil
                self.publishDashboardRevision()
                AtriaDebugLog("ATRIADBG session_backup_status_deferred status=%@ reason=%@ elapsed_ms=%d sessions=%d",
                              status.reason,
                              reason,
                              elapsedMS,
                              currentSessions.count)
            }
        }
    }

    nonisolated static func backupStatusGenerationIsCurrent(resultGeneration: UInt64,
                                                             currentGeneration: UInt64) -> Bool {
        resultGeneration == currentGeneration
    }

    private func refreshHomeDashboardDiagnosticsCache() {
        let rest = baseline.restingInt ?? sessions.first?.restingStable ?? 60
        let maxHR = profile.maxHR
        cachedHomeDashboardDiagnostics = HomeDashboardDiagnostics(rest: rest,
                                                                 rrPackage: rrPackageStatusFast(),
                                                                 sleep: sleepEvidenceStatusFast(rest: rest),
                                                                 workout: savedWorkoutAttemptStatusFast(rest: rest, maxHR: maxHR),
                                                                 collection: currentCollectionStatus(),
                                                                 backup: cachedSessionBackupStatus,
                                                                 trend90: trendSummaryFast(rest: rest, maxHR: maxHR, days: 90))
    }

    private func publishDashboardRevision() {
        dashboardRevision &+= 1
    }

    private func invalidateHomeDashboardDiagnosticsCache() {
        cachedHomeDashboardDiagnostics = nil
        cachedCurrentCollectionStatus = nil
    }

    private func markSessionPersistenceDirty(affectedSessions: [SavedSession]? = nil) {
        sessionPersistenceRevision &+= 1
        guard let affectedSessions else {
            coldSessionFullRewriteGeneration = sessionPersistenceRevision
            return
        }
        let cutoff = Self.coldSessionCutoff()
        for session in affectedSessions where session.start < cutoff {
            coldSessionDirtyGenerations[session.id] = sessionPersistenceRevision
        }
    }

    private func coldSessionPersistenceDelta(upTo revision: Int)
        -> AtriaFullFidelityColdSessionStore.Delta {
        .init(
            requiresFullRewrite: coldSessionFullRewriteGeneration > 0
                && coldSessionFullRewriteGeneration <= revision,
            changedSessionIDs: Set(coldSessionDirtyGenerations.compactMap { id, generation in
                generation <= revision ? id : nil
            })
        )
    }

    private func finishColdSessionPersistence(upTo revision: Int) {
        if coldSessionFullRewriteGeneration > 0,
           coldSessionFullRewriteGeneration <= revision {
            coldSessionFullRewriteGeneration = 0
        }
        coldSessionDirtyGenerations = coldSessionDirtyGenerations.filter { $0.value > revision }
    }

    /// Additive pre-boundary slice of the SAME continuous wear period, for
    /// folding into the cumulative Today metrics across an unconfirmed no-sleep
    /// fallback (see `AtriaHomeModel.continuousTodayAccumulationStart`). The
    /// window [accumulationStart, cycleStart] is DISJOINT from the current
    /// [cycleStart, now] aggregate and the load is window-bounded, so folding
    /// never double-counts. Returns zeros when there is nothing to fold. Keeps
    /// the widget in lockstep with the Home hero's off-MainActor fold.
    struct ContinuousTodayFold: Equatable {
        let addedTRIMP: Double
        let addedMuscularTRIMP: Double
        let addedActiveCalories: Double?
        let addedObservedSeconds: TimeInterval
        static let none = ContinuousTodayFold(
            addedTRIMP: 0, addedMuscularTRIMP: 0,
            addedActiveCalories: nil, addedObservedSeconds: 0
        )
    }

    func continuousTodayPreBoundaryFold(accumulationStart: Date,
                                        cycleStart: Date,
                                        rest: Int,
                                        maxHR: Int) -> ContinuousTodayFold {
        guard accumulationStart < cycleStart else { return .none }
        let pre = Self.homeSavedAggregate(
            from: canonicalSessions(),
            archiveHeartRatePoints: cachedHistoricalTodayHeartRatePoints,
            rest: rest,
            maxHR: maxHR,
            biologicalSex: profile.biologicalSex,
            profile: profile,
            activeSessionID: nil,
            calendar: .current,
            now: cycleStart,
            cycleStart: accumulationStart,
            excludedLoadIntervals: cachedConfirmedSleeps.map {
                DateInterval(start: $0.start, end: $0.end)
            },
            confirmedWorkouts: confirmedWorkouts
        )
        let observed = AtriaHomeModel.observedHeartRateUnionSeconds(
            sessions: sessions,
            windowStart: accumulationStart,
            windowEnd: cycleStart
        )
        return ContinuousTodayFold(
            addedTRIMP: pre.savedTodayTRIMP,
            addedMuscularTRIMP: pre.savedTodayMuscularTRIMP,
            addedActiveCalories: pre.savedTodayActiveCalories,
            addedObservedSeconds: observed
        )
    }

    func homeSavedAggregate(rest: Int,
                            maxHR: Int,
                            activeSessionID: UUID? = nil,
                            calendar: Calendar = .current,
                            now: Date = Date()) -> HomeSavedAggregate {
        let cycle = AtriaPhysiologicalCycle.current(now: now,
                                                    confirmedSleeps: cachedConfirmedSleeps,
                                                    calendar: calendar)
        let day = cycle.start
        if let cachedHomeSavedAggregate,
           cachedHomeSavedAggregate.rest == rest,
           cachedHomeSavedAggregate.maxHR == maxHR,
           cachedHomeSavedAggregate.biologicalSex == profile.biologicalSex,
           cachedHomeSavedAggregate.activeSessionID == activeSessionID,
           cachedHomeSavedAggregate.confirmedSleepsRevision ==
                confirmedSleepsRevision,
           cachedHomeSavedAggregate.day == day {
            return cachedHomeSavedAggregate
        }

        // Deduped, today-filtered (2026-07-08 consistency audit): the hero
        // ring's day strain must sum the SAME session set as the widget's
        // todayTRIMP — canonicalSessions() (deduped), not the raw `sessions`
        // array with a break, which double-counted BLE-reconnect fragments and
        // assumed the today rows were strictly sorted contiguously at the front.
        let aggregate = Self.homeSavedAggregate(from: canonicalSessions(),
                                                archiveHeartRatePoints: cachedHistoricalTodayHeartRatePoints,
                                                rest: rest,
                                                maxHR: maxHR,
                                                biologicalSex: profile.biologicalSex,
                                                profile: profile,
                                                activeSessionID: activeSessionID,
                                                calendar: calendar,
                                                now: now,
                                                cycleStart: day,
                                                excludedLoadIntervals: cachedConfirmedSleeps.map {
                                                    DateInterval(start: $0.start, end: $0.end)
                                                },
                                                rawSessionCount: sessions.count,
                                                confirmedSleepsRevision:
                                                    confirmedSleepsRevision,
                                                confirmedWorkouts: cachedConfirmedWorkouts)
        cachedHomeSavedAggregate = aggregate
        return aggregate
    }

    /// O(1) MainActor capture: no filtering, sorting, HR integration, or array
    /// element walk is performed here. Callers own staleness rejection for the
    /// worker result (Home uses its generation/latest-wins gate).
    func homeSavedAggregateSourceSnapshot() -> HomeSavedAggregateSourceSnapshot {
        HomeSavedAggregateSourceSnapshot(
            canonicalSessions: cachedCanonicalSessions,
            archiveHeartRatePoints: cachedHistoricalTodayHeartRatePoints,
            confirmedSleeps: cachedConfirmedSleeps,
            confirmedWorkouts: cachedConfirmedWorkouts,
            profile: profile,
            rawSessions: sessions,
            rawSessionCount: sessions.count,
            latestRawSession: sessions.first
        )
    }

    func workoutSavedStepPrefix(activeSessionID: UUID? = nil,
                                calendar: Calendar = .current,
                                now: Date = Date()) -> WorkoutSavedStepPrefix {
        Self.workoutSavedStepPrefix(
            from: canonicalSessions(),
            activeSessionID: activeSessionID,
            calendar: calendar,
            now: now
        )
    }

    nonisolated static func workoutSavedStepPrefix(
        from canonicalSessions: [SavedSession],
        activeSessionID: UUID? = nil,
        calendar: Calendar = .current,
        now: Date = Date()
    ) -> WorkoutSavedStepPrefix {
        let day = calendar.startOfDay(for: now)
        let interval = DateInterval(start: day, end: now)
        let todaySessions = canonicalSessions.filter { $0.end > day && $0.start < now }
        let savedToday = todaySessions.reduce(0) { total, session in
            total + session.attributedStrapSteps(within: interval)
        }
        let active = activeSessionID.flatMap { activeID in
            todaySessions.first(where: { $0.id == activeID })
        }
        return WorkoutSavedStepPrefix(
            day: day,
            savedTodayStrapSteps: savedToday,
            savedActiveSessionStrapSteps: active?.attributedStrapSteps(within: interval) ?? 0,
            savedActiveSessionTotalStrapSteps: max(0, active?.strapStepResearchCount ?? 0)
        )
    }

    nonisolated static func homeSavedAggregate(from canonicalSessions: [SavedSession],
                                               archiveHeartRatePoints: [HistoricalArchive.HeartRatePoint] = [],
                                               rest: Int,
                                               maxHR: Int,
                                               biologicalSex: AthleteProfile.BiologicalSex,
                                               profile: AthleteProfile? = nil,
                                               activeSessionID: UUID? = nil,
                                               calendar: Calendar = .current,
                                               now: Date = Date(),
                                               cycleStart: Date? = nil,
                                               excludedLoadIntervals: [DateInterval] = [],
                                               rawSessionCount: Int? = nil,
                                               confirmedSleepsRevision: Int = 0,
                                               confirmedWorkouts: [UserConfirmedWorkout] = [])
        -> HomeSavedAggregate {
        let day = cycleStart ?? calendar.startOfDay(for: now)
        let dayEnd = now
        let dayInterval = DateInterval(start: day, end: dayEnd)
        let loadIntervals = includedLoadIntervals(
            within: dayInterval,
            excluding: excludedLoadIntervals
        )
        let todaySessions = canonicalSessions.filter { $0.end > day && $0.start < dayEnd }
        let canonicalSavedTRIMP = todaySessions.reduce(0) { total, session in
            total + loadIntervals.reduce(0) { subtotal, interval in
                subtotal + session.dailyLoadTRIMP(rest: rest, max: maxHR, within: interval)
            }
        }
        // GAP-09: logged muscular work from workouts completed inside this
        // cycle fuses into the same day total in TRIMP space, before the one
        // saturating 0–21 display map — so today's number and the frozen
        // rollup agree on what a strength-heavy day costs.
        let muscularTRIMP = muscularTRIMPEquivalentTotal(
            confirmedWorkouts.filter { $0.end > day && $0.end <= dayEnd }
        )
        let savedTodayTRIMP = canonicalSavedTRIMP + muscularTRIMP + loadIntervals.reduce(0) {
            $0 + archiveOnlyTRIMP(
                archiveHeartRatePoints,
                excludingCoverageFrom: todaySessions,
                within: $1,
                rest: rest,
                maxHR: maxHR,
                biologicalSex: biologicalSex
            )
        }
        let savedActiveSessionTRIMP = activeSessionID.flatMap { activeID in
            todaySessions.first(where: { $0.id == activeID }).map { session in
                loadIntervals.reduce(0) {
                    $0 + session.dailyLoadTRIMP(rest: rest, max: maxHR, within: $1)
                }
            }
        } ?? 0
        let savedTodayActiveCalories: Double?
        let savedActiveSessionActiveCalories: Double?
        if let profile, profile.hasEnergyProfile {
            let canonicalCalorieValues = todaySessions.compactMap { session -> Double? in
                let values = loadIntervals.compactMap {
                    session.activeCalories(rest: rest, profile: profile, within: $0)
                }
                return values.isEmpty ? nil : values.reduce(0, +)
            }
            let archiveCalorieValues = loadIntervals.compactMap {
                archiveOnlyActiveCalories(
                    archiveHeartRatePoints,
                    excludingCoverageFrom: todaySessions,
                    within: $0,
                    rest: rest,
                    profile: profile
                )
            }
            let archiveCalories = archiveCalorieValues.isEmpty
                ? nil : archiveCalorieValues.reduce(0, +)
            savedTodayActiveCalories = canonicalCalorieValues.isEmpty && archiveCalories == nil
                ? nil
                : canonicalCalorieValues.reduce(0, +) + (archiveCalories ?? 0)
            savedActiveSessionActiveCalories = activeSessionID.flatMap { activeID in
                todaySessions.first(where: { $0.id == activeID }).flatMap { session in
                    let values = loadIntervals.compactMap {
                        session.activeCalories(rest: rest, profile: profile, within: $0)
                    }
                    return values.isEmpty ? nil : values.reduce(0, +)
                }
            }
        } else {
            savedTodayActiveCalories = nil
            savedActiveSessionActiveCalories = nil
        }
        let savedTodayStrapSteps = todaySessions.reduce(0) {
            $0 + $1.attributedStrapSteps(within: dayInterval)
        }
        let savedActiveSessionStrapSteps = activeSessionID.flatMap { activeID in
            todaySessions.first(where: { $0.id == activeID })?.attributedStrapSteps(within: dayInterval)
        } ?? 0
        let savedActiveSessionTotalStrapSteps = activeSessionID.flatMap { activeID in
            todaySessions.first(where: { $0.id == activeID })?.strapStepResearchCount
        } ?? 0
        return HomeSavedAggregate(day: day,
                                  rest: rest,
                                  maxHR: maxHR,
                                  biologicalSex: biologicalSex,
                                  savedTodayTRIMP: savedTodayTRIMP,
                                  savedActiveSessionTRIMP: savedActiveSessionTRIMP,
                                  savedTodayMuscularTRIMP: muscularTRIMP,
                                  savedTodayActiveCalories: savedTodayActiveCalories,
                                  savedActiveSessionActiveCalories: savedActiveSessionActiveCalories,
                                  savedTodayStrapSteps: savedTodayStrapSteps,
                                  savedActiveSessionStrapSteps: savedActiveSessionStrapSteps,
                                  savedActiveSessionTotalStrapSteps: max(0, savedActiveSessionTotalStrapSteps),
                                  activeSessionID: activeSessionID,
                                  hasSavedToday: !todaySessions.isEmpty || savedTodayTRIMP > 0,
                                  sessionsCount: rawSessionCount ?? canonicalSessions.count,
                                  confirmedSleepsRevision:
                                    confirmedSleepsRevision)
    }

    nonisolated static func homeSavedAggregateCancellable(
        from canonicalSessions: [SavedSession],
        archiveHeartRatePoints: [HistoricalArchive.HeartRatePoint] = [],
        rest: Int,
        maxHR: Int,
        biologicalSex: AthleteProfile.BiologicalSex,
        activeSessionID: UUID? = nil,
        calendar: Calendar = .current,
        now: Date = Date(),
        cycleStart: Date? = nil,
        excludedLoadIntervals: [DateInterval] = [],
        rawSessionCount: Int? = nil,
        confirmedSleepsRevision: Int = 0,
        confirmedWorkouts: [UserConfirmedWorkout] = [],
        shouldContinue: () -> Bool
    ) -> HomeSavedAggregate? {
        guard shouldContinue() else { return nil }
        let day = cycleStart ?? calendar.startOfDay(for: now)
        let dayInterval = DateInterval(start: day, end: now)
        let loadIntervals = includedLoadIntervals(
            within: dayInterval,
            excluding: excludedLoadIntervals
        )
        var todaySessions: [SavedSession] = []
        for (index, session) in canonicalSessions.enumerated() {
            if index.isMultiple(of: 64), !shouldContinue() { return nil }
            if session.end > day, session.start < now {
                todaySessions.append(session)
            }
        }
        var canonicalTRIMP = 0.0
        for (sessionIndex, session) in todaySessions.enumerated() {
            if sessionIndex.isMultiple(of: 4), !shouldContinue() { return nil }
            for interval in loadIntervals {
                guard let value = session.dailyLoadTRIMPCancellable(
                    rest: rest,
                    max: maxHR,
                    within: interval,
                    shouldContinue: shouldContinue
                ) else { return nil }
                canonicalTRIMP += value
            }
        }
        var archiveTRIMP = 0.0
        for interval in loadIntervals {
            guard let value = archiveOnlyTRIMPCancellable(
                archiveHeartRatePoints,
                excludingCoverageFrom: todaySessions,
                within: interval,
                rest: rest,
                maxHR: maxHR,
                biologicalSex: biologicalSex,
                shouldContinue: shouldContinue
            ) else { return nil }
            archiveTRIMP += value
        }
        var activeTRIMP = 0.0
        if let activeSessionID,
           let active = todaySessions.first(where: { $0.id == activeSessionID }) {
            for interval in loadIntervals {
                guard let value = active.dailyLoadTRIMPCancellable(
                    rest: rest,
                    max: maxHR,
                    within: interval,
                    shouldContinue: shouldContinue
                ) else { return nil }
                activeTRIMP += value
            }
        }
        var savedTodayStrapSteps = 0
        var activeSteps = 0
        var activeTotal = 0
        for (index, session) in todaySessions.enumerated() {
            if index.isMultiple(of: 64), !shouldContinue() { return nil }
            let steps = session.attributedStrapSteps(within: dayInterval)
            savedTodayStrapSteps += steps
            if session.id == activeSessionID {
                activeSteps = steps
                activeTotal = max(0, session.strapStepResearchCount ?? 0)
            }
        }
        // GAP-09: logged muscular work from workouts completed inside this
        // cycle fuses into the same day total in TRIMP space, before the one
        // saturating 0–21 display map — identical to the non-cancellable path.
        let muscularTRIMP = muscularTRIMPEquivalentTotal(
            confirmedWorkouts.filter { $0.end > day && $0.end <= now }
        )
        let savedTodayTRIMP = canonicalTRIMP + archiveTRIMP + muscularTRIMP
        return shouldContinue() ? HomeSavedAggregate(
            day: day,
            rest: rest,
            maxHR: maxHR,
            biologicalSex: biologicalSex,
            savedTodayTRIMP: savedTodayTRIMP,
            savedActiveSessionTRIMP: activeTRIMP,
            savedTodayMuscularTRIMP: muscularTRIMP,
            savedTodayActiveCalories: nil,
            savedActiveSessionActiveCalories: nil,
            savedTodayStrapSteps: savedTodayStrapSteps,
            savedActiveSessionStrapSteps: activeSteps,
            savedActiveSessionTotalStrapSteps: activeTotal,
            activeSessionID: activeSessionID,
            hasSavedToday: !todaySessions.isEmpty || savedTodayTRIMP > 0,
            sessionsCount: rawSessionCount ?? canonicalSessions.count,
            confirmedSleepsRevision: confirmedSleepsRevision
        ) : nil
    }

    nonisolated static func includedLoadIntervals(
        within interval: DateInterval,
        excluding exclusions: [DateInterval]
    ) -> [DateInterval] {
        var included = [interval]
        for exclusion in exclusions where exclusion.end > interval.start
            && exclusion.start < interval.end {
            included = included.flatMap { candidate in
                guard exclusion.end > candidate.start,
                      exclusion.start < candidate.end else { return [candidate] }
                var pieces: [DateInterval] = []
                if exclusion.start > candidate.start {
                    pieces.append(DateInterval(
                        start: candidate.start,
                        end: min(exclusion.start, candidate.end)
                    ))
                }
                if exclusion.end < candidate.end {
                    pieces.append(DateInterval(
                        start: max(exclusion.end, candidate.start),
                        end: candidate.end
                    ))
                }
                return pieces
            }
        }
        return included
    }

    /// Adds only historical HR time that canonical sessions do not already
    /// integrate. A SavedSession owns every continuous span between adjacent
    /// samples (up to the canonical evidence-gap limit), not merely its exact
    /// timestamps. This is what prevents a 1 Hz archive from multiplying load
    /// beneath a sparse 10-second SavedSession while still recovering genuine
    /// holes and archive-only periods.
    nonisolated static func archiveOnlyTRIMP(
        _ archivePoints: [HistoricalArchive.HeartRatePoint],
        excludingCoverageFrom sessions: [SavedSession],
        within interval: DateInterval,
        rest: Int,
        maxHR: Int,
        biologicalSex: AthleteProfile.BiologicalSex
    ) -> Double {
        guard maxHR > rest, !archivePoints.isEmpty else { return 0 }
        let segments = archiveOnlyHeartRateSegments(archivePoints,
                                                    excludingCoverageFrom: sessions,
                                                    within: interval)
        return segments.reduce(0) { total, segment in
            guard let origin = segment.first?.t else { return total }
            return total + Metrics.dailyLoadTRIMP(
                segment.map { ($0.t.timeIntervalSince(origin), $0.bpm) },
                rest: rest,
                max: maxHR,
                sex: biologicalSex
            )
        }
    }

    nonisolated static func archiveOnlyTRIMPCancellable(
        _ archivePoints: [HistoricalArchive.HeartRatePoint],
        excludingCoverageFrom sessions: [SavedSession],
        within interval: DateInterval,
        rest: Int,
        maxHR: Int,
        biologicalSex: AthleteProfile.BiologicalSex,
        shouldContinue: () -> Bool
    ) -> Double? {
        guard shouldContinue() else { return nil }
        guard maxHR > rest, !archivePoints.isEmpty else { return 0 }
        guard let segments = archiveOnlyHeartRateSegmentsCancellable(
            archivePoints,
            excludingCoverageFrom: sessions,
            within: interval,
            shouldContinue: shouldContinue
        ) else { return nil }
        let parameters = AtriaAnalytics.Strain.banisterParameters(
            for: biologicalSex
        )
        let configuration = AtriaStrainLoadModel.Configuration(
            restingBPM: Double(rest),
            maximumBPM: Double(maxHR),
            intensityMultiplier: parameters.multiplier,
            intensityCoefficient: parameters.coefficient,
            mode: .continuousDay,
            maximumGap: AtriaAnalytics.Strain.maximumLoadEvidenceGap
        )
        var total = 0.0
        for (segmentIndex, segment) in segments.enumerated() {
            if segmentIndex.isMultiple(of: 8), !shouldContinue() { return nil }
            guard let origin = segment.first?.t else { continue }
            var accumulator = AtriaStrainLoadModel.Accumulator(
                configuration: configuration
            )
            for (index, point) in segment.enumerated() {
                if index.isMultiple(of: 256), !shouldContinue() { return nil }
                accumulator.append(.init(
                    timestamp: point.t.timeIntervalSince(origin),
                    bpm: Double(point.bpm)
                ))
            }
            total += accumulator.result.load
        }
        return shouldContinue() ? total : nil
    }

    private nonisolated static func archiveOnlyHeartRateSegmentsCancellable(
        _ archivePoints: [HistoricalArchive.HeartRatePoint],
        excludingCoverageFrom sessions: [SavedSession],
        within interval: DateInterval,
        shouldContinue: () -> Bool
    ) -> [[HistoricalArchive.HeartRatePoint]]? {
        guard shouldContinue() else { return nil }
        guard !archivePoints.isEmpty else { return [] }
        var coverage: [DateInterval] = []
        for (sessionIndex, session) in sessions.enumerated()
        where session.end > interval.start && session.start < interval.end {
            if sessionIndex.isMultiple(of: 8), !shouldContinue() { return nil }
            let source = AtriaStrengthLog.pointsExcludingIntervals(
                session.points,
                sessionStart: session.start,
                excludedIntervals: session.excludedIntervals
            )
            guard shouldContinue() else { return nil }
            var active: [(t: Date, bpm: Int)] = []
            for (index, point) in source.enumerated() {
                if index.isMultiple(of: 256), !shouldContinue() { return nil }
                let date = session.start.addingTimeInterval(max(0, point.t))
                if date >= interval.start,
                   date < interval.end,
                   (35...240).contains(point.bpm) {
                    active.append((date, point.bpm))
                }
            }
            guard AtriaSleepCooperativeAlgorithms.stableSort(
                &active,
                shouldContinue: shouldContinue,
                areInIncreasingOrder: { $0.t < $1.t }
            ) else { return nil }
            for (index, point) in active.enumerated() {
                if index.isMultiple(of: 256), !shouldContinue() { return nil }
                let start = max(interval.start, point.t.addingTimeInterval(-0.5))
                let end = min(interval.end, point.t.addingTimeInterval(0.5))
                if end > start { coverage.append(.init(start: start, end: end)) }
                if index > 0 {
                    let previous = active[index - 1]
                    let gap = point.t.timeIntervalSince(previous.t)
                    if gap > 0, gap <= SavedSession.workoutContinuityGapLimit {
                        coverage.append(.init(start: previous.t, end: point.t))
                    }
                }
            }
        }
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &coverage,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: { $0.start < $1.start }
        ) else { return nil }
        var merged: [DateInterval] = []
        for (index, item) in coverage.enumerated() {
            if index.isMultiple(of: 256), !shouldContinue() { return nil }
            if let last = merged.last, item.start <= last.end {
                merged[merged.count - 1] = .init(
                    start: last.start,
                    end: max(last.end, item.end)
                )
            } else {
                merged.append(item)
            }
        }
        var candidates: [HistoricalArchive.HeartRatePoint] = []
        for (index, point) in archivePoints.enumerated() {
            if index.isMultiple(of: 256), !shouldContinue() { return nil }
            if point.t >= interval.start,
               point.t < interval.end,
               (35...240).contains(point.bpm) {
                candidates.append(point)
            }
        }
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &candidates,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: { $0.t < $1.t }
        ) else { return nil }
        var unique: [Int64: HistoricalArchive.HeartRatePoint] = [:]
        var coverageIndex = 0
        for (index, point) in candidates.enumerated() {
            if index.isMultiple(of: 256), !shouldContinue() { return nil }
            while coverageIndex < merged.count,
                  merged[coverageIndex].end < point.t {
                coverageIndex += 1
            }
            if coverageIndex < merged.count,
               merged[coverageIndex].contains(point.t) {
                continue
            }
            unique[Int64((point.t.timeIntervalSince1970 * 1_000).rounded())]
                = point
        }
        var remaining = Array(unique.values)
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &remaining,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: { $0.t < $1.t }
        ) else { return nil }
        guard remaining.count > 1 else { return [] }
        var segments: [[HistoricalArchive.HeartRatePoint]] = []
        var current: [HistoricalArchive.HeartRatePoint] = []
        coverageIndex = 0
        for (index, point) in remaining.enumerated() {
            if index.isMultiple(of: 256), !shouldContinue() { return nil }
            if let previous = current.last {
                while coverageIndex < merged.count,
                      merged[coverageIndex].end <= previous.t {
                    coverageIndex += 1
                }
                let crossesOwnedSpan = coverageIndex < merged.count
                    && merged[coverageIndex].start < point.t
                    && merged[coverageIndex].end > previous.t
                if crossesOwnedSpan
                    || point.t.timeIntervalSince(previous.t)
                        > SavedSession.workoutContinuityGapLimit {
                    if current.count > 1 { segments.append(current) }
                    current = []
                }
            }
            current.append(point)
        }
        if current.count > 1 { segments.append(current) }
        return shouldContinue() ? segments : nil
    }

    /// Active-energy counterpart to `archiveOnlyTRIMP`. Both scorers consume
    /// the exact same deduplicated archive-only segments, keeping daily strain
    /// and calorie coverage aligned while preserving their distinct formulas.
    nonisolated static func archiveOnlyActiveCalories(
        _ archivePoints: [HistoricalArchive.HeartRatePoint],
        excludingCoverageFrom sessions: [SavedSession],
        within interval: DateInterval,
        rest: Int,
        profile: AthleteProfile
    ) -> Double? {
        guard profile.hasEnergyProfile, !archivePoints.isEmpty else { return nil }
        let segments = archiveOnlyHeartRateSegments(archivePoints,
                                                    excludingCoverageFrom: sessions,
                                                    within: interval)
        guard !segments.isEmpty else { return nil }
        return segments.reduce(0) { total, segment in
            total + (Metrics.dayCalories(segment.map {
                Metrics.HeartRateEnergySample(t: $0.t, bpm: $0.bpm)
            }, rest: rest, profile: profile) ?? 0)
        }
    }

    private nonisolated static func archiveOnlyHeartRateSegments(
        _ archivePoints: [HistoricalArchive.HeartRatePoint],
        excludingCoverageFrom sessions: [SavedSession],
        within interval: DateInterval
    ) -> [[HistoricalArchive.HeartRatePoint]] {
        guard !archivePoints.isEmpty else { return [] }
        var coverage: [DateInterval] = []
        for session in sessions where session.end > interval.start && session.start < interval.end {
            let active = AtriaStrengthLog.pointsExcludingIntervals(session.points,
                                                                    sessionStart: session.start,
                                                                    excludedIntervals: session.excludedIntervals)
                .map { (t: session.start.addingTimeInterval(max(0, $0.t)), bpm: $0.bpm) }
                // DateInterval.contains includes its end. Civil-day load uses
                // half-open [start, end) intervals so a midnight archive row
                // belongs to the following day only.
                .filter {
                    $0.t >= interval.start && $0.t < interval.end
                        && (35...240).contains($0.bpm)
                }
                .sorted { $0.t < $1.t }
            for point in active {
                let start = max(interval.start, point.t.addingTimeInterval(-0.5))
                let end = min(interval.end, point.t.addingTimeInterval(0.5))
                if end > start { coverage.append(DateInterval(start: start, end: end)) }
            }
            for pair in zip(active, active.dropFirst()) {
                let gap = pair.1.t.timeIntervalSince(pair.0.t)
                if gap > 0, gap <= SavedSession.workoutContinuityGapLimit {
                    coverage.append(DateInterval(start: pair.0.t, end: pair.1.t))
                }
            }
        }
        coverage.sort { $0.start < $1.start }
        var merged: [DateInterval] = []
        for item in coverage {
            if let last = merged.last, item.start <= last.end {
                merged[merged.count - 1] = DateInterval(start: last.start, end: max(last.end, item.end))
            } else {
                merged.append(item)
            }
        }

        var unique: [Int64: HistoricalArchive.HeartRatePoint] = [:]
        for point in archivePoints
        where point.t >= interval.start
            && point.t < interval.end
            && (35...240).contains(point.bpm) {
            let covered = merged.contains { $0.contains(point.t) }
            guard !covered else { continue }
            unique[Int64((point.t.timeIntervalSince1970 * 1_000).rounded())] = point
        }
        let remaining = unique.values.sorted { $0.t < $1.t }
        guard remaining.count > 1 else { return [] }

        var segments: [[HistoricalArchive.HeartRatePoint]] = []
        var current: [HistoricalArchive.HeartRatePoint] = []
        for point in remaining {
            if let previous = current.last {
                let crossesOwnedSpan = merged.contains {
                    $0.start < point.t && $0.end > previous.t
                }
                if crossesOwnedSpan || point.t.timeIntervalSince(previous.t) > SavedSession.workoutContinuityGapLimit {
                    if current.count > 1 { segments.append(current) }
                    current = []
                }
            }
            current.append(point)
        }
        if current.count > 1 { segments.append(current) }
        return segments
    }

    /// Replace the checkpointed prefix of the current live session with the
    /// newest full live accumulator. `max` prevents a transient drop while a
    /// just-restored journal is catching up to its last durable checkpoint.
    nonisolated static func mergedTodayTRIMP(savedToday: Double,
                                             savedActiveSession: Double,
                                             liveActiveSession: Double) -> Double {
        let saved = max(0, savedToday)
        let savedActive = min(saved, max(0, savedActiveSession))
        return saved - savedActive + max(savedActive, max(0, liveActiveSession))
    }

    /// Replace the checkpointed prefix of the current live session without
    /// resetting the physiological-day active-energy estimate on reconnect.
    /// Optionality is provenance: no complete age/sex/weight profile means no
    /// calorie number, rather than a fabricated zero.
    nonisolated static func mergedTodayActiveCalories(savedToday: Double?,
                                                      savedActiveSession: Double?,
                                                      liveActiveSession: Double?) -> Double? {
        guard savedToday != nil || savedActiveSession != nil || liveActiveSession != nil else {
            return nil
        }
        let saved = max(0, savedToday ?? 0)
        let savedActive = min(saved, max(0, savedActiveSession ?? 0))
        return saved - savedActive + max(savedActive, max(0, liveActiveSession ?? 0))
    }

    private var sessionPersistenceWriter: SessionPersistenceWriter {
        #if DEBUG
        if let sessionPersistenceWriterForTesting {
            return sessionPersistenceWriterForTesting
        }
        #endif
        return { sessions, hotURL, coldURL, allowColdWrite, coldDelta, reason in
            Self.persistPartitionedSessionsSnapshot(sessions,
                                                    hotURL: hotURL,
                                                    coldURL: coldURL,
                                                    allowColdWrite: allowColdWrite,
                                                    coldDelta: coldDelta,
                                                    reason: reason)
        }
    }

    private func finishSessionPersistence(revision: Int, succeeded: Bool) {
        if succeeded {
            lastCompletedSessionPersistenceRevision = max(
                lastCompletedSessionPersistenceRevision,
                revision
            )
            finishColdSessionPersistence(upTo: revision)
        }
        if pendingSessionPersistenceRevision == revision {
            pendingSessionPersistenceRevision = 0
        }
    }

    private func scheduleSessionFilePersist(reason: String, delay: TimeInterval) {
        guard !restorePersistenceFenceActive,
              hasCompletedDeferredSessionLoad,
              !sessionSourcePreservationFenceActive else { return }
        guard sessionPersistenceRevision > lastCompletedSessionPersistenceRevision else { return }
        let snapshot = sessions
        let sourceURL = url
        let coldURL = coldSessionsURL
        let coldWriteReady = hasCompletedDeferredSessionLoad
        let revision = sessionPersistenceRevision
        let coldDelta = coldSessionPersistenceDelta(upTo: revision)
        let persist = sessionPersistenceWriter

        pendingSessionSaveWorkItem?.cancel()
        pendingSessionPersistenceRevision = revision
        let workItem = DispatchWorkItem { [weak self] in
            let succeeded = persist(snapshot, sourceURL, coldURL, coldWriteReady, coldDelta, reason)
            DispatchQueue.main.async { [weak self] in
                guard let self else { return }
                self.finishSessionPersistence(revision: revision, succeeded: succeeded)
            }
        }
        pendingSessionSaveWorkItem = workItem
        persistenceQueue.asyncAfter(deadline: .now() + delay, execute: workItem)
    }

    private func loadPersistedDailyMetrics() {
        let sourceURL = dailyMetricsURL
        let loadGeneration = dailyMetricHistoryGeneration
        Task.detached(priority: .utility) { [sourceURL, loadGeneration] in
            let decoded: [SavedDailyMetric]?
            if let data = try? Data(contentsOf: sourceURL) {
                decoded = try? JSONDecoder().decode([SavedDailyMetric].self, from: data)
            } else {
                decoded = []
            }
            await Task { @MainActor in
                guard let decoded else {
                    AtriaDebugLog("ATRIADBG daily_metric_load status=failed action=retain_widget_authority")
                    return
                }
                if Self.shouldPublishPersistedDailyMetricHistory(
                       loadGeneration: loadGeneration,
                       currentGeneration: self.dailyMetricHistoryGeneration
                   ) {
                    self.dailyMetricHistory = decoded.sorted { $0.day > $1.day }
                }
                self.hasCompletedPersistedDailyMetricLoad = true

                // Session settlement may have completed while this much
                // smaller file was still decoding. Re-open the widget gate and
                // publish once from the fully loaded authority. If settlement
                // is still pending, its existing verified callback owns the
                // eventual publication.
                guard self.hasCompletedDeferredSessionLoad else { return }
                if self.deferredLaunchCardSettlementPending {
                    self.resumeDeferredLaunchCardSettlementIfNeeded(
                        reason: "daily_metrics_loaded"
                    )
                } else {
                    self.publishDashboardRevision()
                    self.onDeferredLaunchCardSettlementPublished?(
                        "daily_metrics_loaded"
                    )
                }
            }.value
        }
    }

    nonisolated static func shouldPublishPersistedDailyMetricHistory(
        loadGeneration: Int,
        currentGeneration: Int
    ) -> Bool {
        loadGeneration == currentGeneration
    }

    private func scheduleDailyMetricPersist(reason: String, delay: TimeInterval = 0.35) {
        guard !restorePersistenceFenceActive,
              recoveredDataMutationTransaction.activeTicket == nil
                || recoveredDataMutationTransaction.rollbackOperationCount == 0 else { return }
        let snapshot = dailyMetricHistory
        let sourceURL = dailyMetricsURL
        let revision = dailyMetricHistoryRevision

        if let pending = pendingDailyMetricSaveWorkItem,
           pendingDailyMetricPersistRevision != nil,
           Self.shouldKeepPendingDailyMetricPersist(
               pendingIsCancelled: pending.isCancelled,
               requestedDelay: delay
           ) {
            AtriaDebugLog(
                "ATRIADBG daily_metric_history_save status=coalesced op=%@ pending_revision=%d newest_revision=%d",
                reason,
                pendingDailyMetricPersistRevision ?? -1,
                revision
            )
            return
        }
        pendingDailyMetricSaveWorkItem?.cancel()
        pendingDailyMetricPersistRevision = revision
        let workItem = DispatchWorkItem { [weak self] in
            let succeeded = Self.persistDailyMetricsSnapshot(
                snapshot,
                to: sourceURL,
                reason: reason
            )
            DispatchQueue.main.async { [weak self] in
                guard let self,
                      self.pendingDailyMetricPersistRevision == revision else {
                    return
                }
                self.pendingDailyMetricSaveWorkItem = nil
                self.pendingDailyMetricPersistRevision = nil
                if Self.dailyMetricPersistNeedsCatchUp(
                    completedRevision: revision,
                    currentRevision: self.dailyMetricHistoryRevision,
                    writeSucceeded: succeeded
                ) {
                    self.scheduleDailyMetricPersist(
                        reason: "coalesced_after_\(reason)",
                        delay: 0
                    )
                }
            }
        }
        pendingDailyMetricSaveWorkItem = workItem
        persistenceQueue.asyncAfter(deadline: .now() + delay, execute: workItem)
    }

    nonisolated static func shouldKeepPendingDailyMetricPersist(
        pendingIsCancelled: Bool,
        requestedDelay: TimeInterval
    ) -> Bool {
        !pendingIsCancelled && requestedDelay > 0
    }

    nonisolated static func dailyMetricPersistNeedsCatchUp(
        completedRevision: Int,
        currentRevision: Int,
        writeSucceeded: Bool
    ) -> Bool {
        writeSucceeded && completedRevision != currentRevision
    }

    func requestPersistenceFlush(reason: String) {
        guard !restorePersistenceFenceActive,
              hasCompletedDeferredSessionLoad,
              !sessionSourcePreservationFenceActive else { return }
        guard sessionPersistenceRevision > lastCompletedSessionPersistenceRevision else { return }
        let snapshot = sessions
        let sourceURL = url
        let coldURL = coldSessionsURL
        let coldWriteReady = hasCompletedDeferredSessionLoad
        let revision = sessionPersistenceRevision
        let coldDelta = coldSessionPersistenceDelta(upTo: revision)
        let persist = sessionPersistenceWriter

        pendingSessionSaveWorkItem?.cancel()
        pendingSessionPersistenceRevision = revision
        let workItem = DispatchWorkItem { [weak self] in
            let succeeded = persist(snapshot, sourceURL, coldURL, coldWriteReady, coldDelta, reason)
            DispatchQueue.main.async { [weak self] in
                guard let self else { return }
                self.finishSessionPersistence(revision: revision, succeeded: succeeded)
            }
        }
        pendingSessionSaveWorkItem = workItem
        persistenceQueue.async(execute: workItem)
    }

    @discardableResult
    func flushScheduledPersistence(reason: String) -> Bool {
        guard !restorePersistenceFenceActive,
              hasCompletedDeferredSessionLoad,
              !sessionSourcePreservationFenceActive else { return false }
        guard sessionPersistenceRevision > lastCompletedSessionPersistenceRevision else { return true }
        let snapshot = sessions
        let sourceURL = url
        let coldURL = coldSessionsURL
        let coldWriteReady = hasCompletedDeferredSessionLoad
        let revision = sessionPersistenceRevision
        let coldDelta = coldSessionPersistenceDelta(upTo: revision)
        let persist = sessionPersistenceWriter
        pendingSessionSaveWorkItem?.cancel()
        pendingSessionSaveWorkItem = nil
        pendingSessionPersistenceRevision = revision
        let succeeded = persistenceQueue.sync {
            persist(snapshot, sourceURL, coldURL, coldWriteReady, coldDelta, reason)
        }
        finishSessionPersistence(revision: revision, succeeded: succeeded)
        return succeeded
    }

    /// Completion-aware durability boundary for scene backgrounding. The
    /// immutable snapshot is captured on MainActor, while encoding and atomic
    /// writes stay on the persistence queue. Unlike `flushScheduledPersistence`,
    /// this never synchronously waits from a lifecycle callback.
    func flushScheduledPersistenceAsync(reason: String,
                                        completion: @escaping @MainActor (Bool) -> Void) {
        guard !restorePersistenceFenceActive,
              hasCompletedDeferredSessionLoad,
              !sessionSourcePreservationFenceActive else {
            completion(false)
            return
        }
        guard sessionPersistenceRevision > lastCompletedSessionPersistenceRevision else {
            completion(true)
            return
        }
        let snapshot = sessions
        let sourceURL = url
        let coldURL = coldSessionsURL
        let coldWriteReady = hasCompletedDeferredSessionLoad
        let revision = sessionPersistenceRevision
        let coldDelta = coldSessionPersistenceDelta(upTo: revision)
        let persist = sessionPersistenceWriter
        pendingSessionSaveWorkItem?.cancel()
        pendingSessionPersistenceRevision = revision
        let workItem = DispatchWorkItem { [weak self] in
            let succeeded = persist(snapshot, sourceURL, coldURL, coldWriteReady, coldDelta, reason)
            DispatchQueue.main.async { [weak self] in
                if let self {
                    self.finishSessionPersistence(revision: revision, succeeded: succeeded)
                }
                completion(succeeded)
            }
        }
        pendingSessionSaveWorkItem = workItem
        persistenceQueue.async(execute: workItem)
    }

    /// Compatibility facade for UI/lifecycle callers that only need to know
    /// when the attempt has finished. Durability-sensitive callers must use the
    /// Bool completion above and retain their recovery intent when it is false.
    func flushScheduledPersistenceAsync(reason: String,
                                        completion: @escaping @MainActor () -> Void) {
        flushScheduledPersistenceAsync(reason: reason) { _ in
            completion()
        }
    }

    func performBackgroundMaintenance(reason: String) {
        performBackgroundMaintenance(reason: reason, now: Date(), calendar: .current)
    }

    /// Completion-aware variant used by BGTask. The task may finish only after
    /// the coalesced backup worker has durably written this snapshot (or a newer
    /// one that superseded it).
    func performBackgroundMaintenance(reason: String,
                                      backupCompletion: @escaping @MainActor (Bool) -> Void) {
        performBackgroundMaintenance(reason: reason,
                                     now: Date(),
                                     calendar: .current,
                                     backupCompletion: backupCompletion)
    }

    /// BGTask-safe entry point. It never waits synchronously on the persistence
    /// queue from MainActor, so expiration can complete the system task even
    /// while an already-started atomic save finishes in the background.
    func performBackgroundMaintenanceAsynchronously(
        reason: String,
        completion: @escaping @MainActor (Bool) -> Void
    ) {
        flushScheduledPersistenceAsync(reason: "\(reason)_persistence") {
            [weak self] persistenceSucceeded in
            guard let self else {
                completion(false)
                return
            }
            self.performBackgroundMaintenance(
                reason: reason,
                now: Date(),
                calendar: .current,
                backupCompletion: { backupSucceeded in
                    completion(persistenceSucceeded && backupSucceeded)
                },
                persistenceAlreadyFlushed: true
            )
        }
    }

    /// Evaluates the production 30-day / 512-MiB high-volume policy. One
    /// transaction still retires at most one raw chunk, but the off-main driver
    /// starts fresh verified transactions within a bounded work slice until the
    /// cap is satisfied (or only the active writer prevents it). Deferred and
    /// yielded runs are retried soon and never consume the once-daily success
    /// lease.
    private static let archiveCompactionLastRunKey = "atria.archiveCompaction.lastRunAt"
    private static var archiveCompactionInFlight = false
    private static var archiveCompactionPressureProbeInFlight = false

    /// Unforgeable outside `SessionStore`: AtriaApp receives this only from the
    /// real BGProcessing handler after the BLE drain has settled. Normal task
    /// completion and expiration revoke it, so merely remaining in
    /// `UIApplication.State.background` is never enough authority to start a
    /// later retention scan.
    final class ArchiveCompactionCancellationToken: @unchecked Sendable {
        private let lock = NSLock()
        private var revoked = false

        func revoke() {
            lock.lock()
            revoked = true
            lock.unlock()
        }

        func shouldContinue(
            thermalState: ProcessInfo.ThermalState,
            isLowPowerModeEnabled: Bool
        ) -> Bool {
            lock.lock()
            let isRevoked = revoked
            lock.unlock()
            return !isRevoked
                && thermalState != .serious
                && thermalState != .critical
                && !isLowPowerModeEnabled
        }
    }

    struct ArchiveCompactionBGProcessingLease: Sendable {
        fileprivate let generation: Int
        fileprivate let expiresAt: Date
        fileprivate let cancellationToken:
            ArchiveCompactionCancellationToken
    }

    private struct ArchiveCompactionSafeBackgroundAdmission {
        let generation: Int
        let intentRevision: Int
        let reason: String
        let expiresAt: Date
        let explicitDebugOverride: Bool
        let backgroundLease: ArchiveCompactionBGProcessingLease?
    }

    private enum ArchiveCompactionSafeBackgroundOperation {
        case pressureProbe
        case compaction
    }

    /// Retention accounting itself walks the complete archive, even when the
    /// resulting plan says there is nothing to compact. Automatic callers may
    /// therefore enter only from the real BGProcessing handler under the same
    /// power/thermal fence as background projection. The cap-pressure
    /// continuation must retain the same live lease; yielded work is reserved
    /// for a future task instead of arming a timer. Foreground archive
    /// notifications can never manufacture this authority.
    nonisolated static func shouldAdmitAutomaticArchiveCompaction(
        reason: String,
        applicationIsBackground: Bool,
        thermalState: ProcessInfo.ThermalState,
        isLowPowerModeEnabled: Bool,
        batteryState: UIDevice.BatteryState,
        batteryLevel: Float,
        exactRecoveryOwnsPriority: Bool,
        recoveredCycleEngaged: Bool
    ) -> Bool {
        let isBackgroundProcessingReason = reason == "bg_processing"
            || reason == "bg_processing_cap_pressure"
        return isBackgroundProcessingReason
            && applicationIsBackground
            && !exactRecoveryOwnsPriority
            && !recoveredCycleEngaged
            && shouldStartBackgroundArchiveProjection(
                thermalState: thermalState,
                isLowPowerModeEnabled: isLowPowerModeEnabled,
                batteryState: batteryState,
                batteryLevel: batteryLevel
            )
    }

    /// Release fence for the archive-wide graph.
    ///
    /// This used to be `{ explicitDebugOverride }` — a hard kill switch. Its
    /// comment said automatic work stayed disabled "until every composite reader
    /// and publisher is cooperatively cancellable". That proof is in fact
    /// complete, and has been for some time; the fence outlived it.
    ///
    /// `HistoricalArchive` carries 132 `shouldContinue` references across 20+
    /// functions with 28 `guard shouldContinue()` sites and inner-loop checks
    /// every 16-32 iterations. The token those calls consume is
    /// `archiveCompactionWorkerShouldContinue`, which revokes on lease expiry,
    /// thermal pressure and Low Power Mode, and `shouldContinueArchiveCompactionWork`
    /// additionally requires the app to still be backgrounded on the current
    /// lease generation. Revocation is cooperative, threaded, and checked deep.
    ///
    /// The consequence of leaving it closed was measured on 2026-08-19: the
    /// production 30-day/512 MiB retention policy had **never once been
    /// evaluated** on a real device, and the container had grown to 5.45 GB with
    /// 2.99 GB of raw segments spanning five weeks. The user asked for exactly
    /// what this graph already implements — raw kept for a bounded window,
    /// insights kept forever.
    ///
    /// Retirement remains fail-closed independently of this gate:
    /// `AtriaHistoricalRawRetirementExecutor.retire` unlinks a raw chunk only
    /// after proving a committed aggregate AND manifest match its `contentSHA256`,
    /// byte count, row count and both timestamps, with a semantic-parity receipt.
    /// So this fence controls only whether the graph RUNS, never whether an
    /// unverified deletion can happen.
    nonisolated static func shouldExecuteArchiveWideMaintenance(
        explicitDebugOverride: Bool,
        automaticAdmission: Bool = false
    ) -> Bool {
        explicitDebugOverride || automaticAdmission
    }

    nonisolated static func archiveCompactionWorkerLeaseIsCurrent(
        leaseGeneration: Int,
        activeLeaseGeneration: Int?,
        now: Date,
        leaseExpiresAt: Date
    ) -> Bool {
        activeLeaseGeneration == leaseGeneration
            && now <= leaseExpiresAt
    }

    nonisolated static func archiveCompactionWorkerShouldContinue(
        _ lease: ArchiveCompactionBGProcessingLease?
    ) -> Bool {
        guard let lease, Date() <= lease.expiresAt else { return false }
        return lease.cancellationToken.shouldContinue(
            thermalState: ProcessInfo.processInfo.thermalState,
            isLowPowerModeEnabled:
                ProcessInfo.processInfo.isLowPowerModeEnabled
        )
    }

    nonisolated static func shouldConsumeArchiveCompactionLeaseCompletion(
        pendingGeneration: Int?,
        requestedGeneration: Int
    ) -> Bool {
        pendingGeneration == requestedGeneration
    }

    /// Minted only by the live BGProcessing task after motion/HR recovery has
    /// finished. The environment is checked again for the operation admission
    /// and once more on the archive worker; this lease supplies the missing
    /// system-task lifetime authority that app state alone cannot prove.
    func beginArchiveCompactionBGProcessingLeaseIfSafe(
        reason: String
    ) -> ArchiveCompactionBGProcessingLease? {
        guard reason == "bg_processing" else {
            reserveArchiveCompactionForSafeBackground()
            return nil
        }
        if let active = activeArchiveCompactionBGProcessingLease {
            if Date() <= active.expiresAt { return nil }
            active.cancellationToken.revoke()
            activeArchiveCompactionBGProcessingLease = nil
            finishArchiveCompactionLeaseCompletion(
                lease: active,
                fallback: nil,
                succeeded: false
            )
            reserveArchiveCompactionForSafeBackground()
        }
        let exactRecoveryOwnsPriority = exactRecoveryArchivePriorityLeaseActive
            || HistoricalArchive.exactRecoveryProjectionOwnsArchivePriority()
        guard Self.shouldAdmitAutomaticArchiveCompaction(
            reason: reason,
            applicationIsBackground:
                UIApplication.shared.applicationState == .background,
            thermalState: ProcessInfo.processInfo.thermalState,
            isLowPowerModeEnabled:
                ProcessInfo.processInfo.isLowPowerModeEnabled,
            batteryState: UIDevice.current.batteryState,
            batteryLevel: UIDevice.current.batteryLevel,
            exactRecoveryOwnsPriority: exactRecoveryOwnsPriority,
            recoveredCycleEngaged: recoveredProjectionScanActive
        ) else {
            reserveArchiveCompactionForSafeBackground()
            return nil
        }
        archiveCompactionBGProcessingLeaseGeneration &+= 1
        let lease = ArchiveCompactionBGProcessingLease(
            generation: archiveCompactionBGProcessingLeaseGeneration,
            expiresAt: Date().addingTimeInterval(10 * 60),
            cancellationToken: ArchiveCompactionCancellationToken()
        )
        activeArchiveCompactionBGProcessingLease = lease
        return lease
    }

    func endArchiveCompactionBGProcessingLease(
        _ lease: ArchiveCompactionBGProcessingLease,
        reason: String
    ) {
        guard activeArchiveCompactionBGProcessingLease?.generation
                == lease.generation else { return }
        lease.cancellationToken.revoke()
        activeArchiveCompactionBGProcessingLease = nil
        finishArchiveCompactionLeaseCompletion(
            lease: lease,
            fallback: nil,
            succeeded: false
        )
        if Self.archiveCompactionInFlight
            || Self.archiveCompactionPressureProbeInFlight {
            reserveArchiveCompactionForSafeBackground()
        }
        AtriaDebugLog(
            "ATRIADBG archive_compaction_lease status=ended reason=%@ generation=%d",
            reason,
            lease.generation
        )
    }

    /// Expiration may arrive while the task body is suspended in another
    /// await. Revoke the one live lease immediately; queued worker tickets then
    /// fail closed even if the process remains in the background.
    func invalidateArchiveCompactionBGProcessingLease(reason: String) {
        guard let active = activeArchiveCompactionBGProcessingLease else {
            return
        }
        active.cancellationToken.revoke()
        activeArchiveCompactionBGProcessingLease = nil
        finishArchiveCompactionLeaseCompletion(
            lease: active,
            fallback: nil,
            succeeded: false
        )
        reserveArchiveCompactionForSafeBackground()
        AtriaDebugLog(
            "ATRIADBG archive_compaction_lease status=invalidated reason=%@ generation=%d",
            reason,
            active.generation
        )
    }

    private func archiveCompactionBGProcessingLeaseIsCurrent(
        _ lease: ArchiveCompactionBGProcessingLease
    ) -> Bool {
        UIApplication.shared.applicationState == .background
            && Self.archiveCompactionWorkerLeaseIsCurrent(
            leaseGeneration: lease.generation,
            activeLeaseGeneration:
                activeArchiveCompactionBGProcessingLease?.generation,
            now: Date(),
            leaseExpiresAt: lease.expiresAt
        )
            && lease.cancellationToken.shouldContinue(
                thermalState: ProcessInfo.processInfo.thermalState,
                isLowPowerModeEnabled:
                    ProcessInfo.processInfo.isLowPowerModeEnabled
            )
    }

    private func installArchiveCompactionLeaseCompletionIfNeeded(
        lease: ArchiveCompactionBGProcessingLease?,
        completion: ((Bool) -> Void)?
    ) {
        guard let lease, let completion else { return }
        if pendingArchiveCompactionLeaseCompletion?.generation
            == lease.generation {
            return
        }
        pendingArchiveCompactionLeaseCompletion = (
            generation: lease.generation,
            handler: completion
        )
    }

    private func finishArchiveCompactionLeaseCompletion(
        lease: ArchiveCompactionBGProcessingLease?,
        fallback: ((Bool) -> Void)?,
        succeeded: Bool
    ) {
        guard let lease else {
            fallback?(succeeded)
            return
        }
        guard Self.shouldConsumeArchiveCompactionLeaseCompletion(
            pendingGeneration:
                pendingArchiveCompactionLeaseCompletion?.generation,
            requestedGeneration: lease.generation
        ) else { return }
        let handler = pendingArchiveCompactionLeaseCompletion?.handler
        pendingArchiveCompactionLeaseCompletion = nil
        handler?(succeeded)
    }

    private func reserveArchiveCompactionForSafeBackground() {
        archiveCompactionReservedForSafeBackground = true
        archiveCompactionSafeBackgroundIntentRevision &+= 1
    }

    private func makeArchiveCompactionSafeBackgroundAdmission(
        reason: String,
        explicitDebugOverride: Bool,
        backgroundLease: ArchiveCompactionBGProcessingLease?
    ) -> ArchiveCompactionSafeBackgroundAdmission {
        archiveCompactionSafeBackgroundGeneration &+= 1
        return .init(
            generation: archiveCompactionSafeBackgroundGeneration,
            intentRevision: archiveCompactionSafeBackgroundIntentRevision,
            reason: reason,
            expiresAt: Date().addingTimeInterval(30),
            explicitDebugOverride: explicitDebugOverride,
            backgroundLease: backgroundLease
        )
    }

    /// Revalidated on MainActor from the serial archive worker immediately
    /// before its first archive-wide read. A queued ticket cannot retain a
    /// stale background/power/owner decision after the app foregrounds, heats
    /// up, or an exact/recovered publication takes the shared heavy lane.
    private func archiveCompactionAdmissionRemainsValidAtWorkerBoundary(
        _ admission: ArchiveCompactionSafeBackgroundAdmission,
        operation: ArchiveCompactionSafeBackgroundOperation
    ) -> Bool {
        guard archiveCompactionSafeBackgroundGeneration
                == admission.generation,
              Date() <= admission.expiresAt else { return false }
        switch operation {
        case .pressureProbe:
            guard Self.archiveCompactionPressureProbeInFlight else {
                return false
            }
        case .compaction:
            guard Self.archiveCompactionInFlight else { return false }
        }
        let exactRecoveryOwnsPriority = exactRecoveryArchivePriorityLeaseActive
            || HistoricalArchive.exactRecoveryProjectionOwnsArchivePriority()
        if admission.explicitDebugOverride {
            return !exactRecoveryOwnsPriority && !recoveredProjectionScanActive
        }
        guard let backgroundLease = admission.backgroundLease,
              archiveCompactionBGProcessingLeaseIsCurrent(
                backgroundLease
              ) else { return false }
        return Self.shouldAdmitAutomaticArchiveCompaction(
            reason: admission.reason,
            applicationIsBackground:
                UIApplication.shared.applicationState == .background,
            thermalState: ProcessInfo.processInfo.thermalState,
            isLowPowerModeEnabled:
                ProcessInfo.processInfo.isLowPowerModeEnabled,
            batteryState: UIDevice.current.batteryState,
            batteryLevel: UIDevice.current.batteryLevel,
            exactRecoveryOwnsPriority: exactRecoveryOwnsPriority,
            recoveredCycleEngaged: recoveredProjectionScanActive
        )
    }

    private func retireArchiveCompactionAdmissionAsReserved(
        _ admission: ArchiveCompactionSafeBackgroundAdmission,
        operation: ArchiveCompactionSafeBackgroundOperation
    ) {
        guard archiveCompactionSafeBackgroundGeneration
                == admission.generation else { return }
        switch operation {
        case .pressureProbe:
            Self.archiveCompactionPressureProbeInFlight = false
        case .compaction:
            Self.archiveCompactionInFlight = false
        }
        reserveArchiveCompactionForSafeBackground()
    }

    func compactHistoricalArchiveIfUseful(
        reason: String,
        backgroundLease: ArchiveCompactionBGProcessingLease? = nil,
        now: Date = Date(),
        bypassDailyLease: Bool = false,
        completion: ((Bool) -> Void)? = nil
    ) {
        installArchiveCompactionLeaseCompletionIfNeeded(
            lease: backgroundLease,
            completion: completion
        )
        let explicitDebugOverride = reason == "debug_launch_arg"
            && ProcessInfo.processInfo.arguments.contains(
                "--atria-compact-archive"
            )
        // Release fail-closed fence: the archive-wide retention graph still
        // contains composite readers/publishers whose individual inner loops
        // cannot all be revoked atomically when a BGProcessing task expires or
        // the app becomes active. Keep the durable maintenance intent, but do
        // not enter that graph from any automatic BG/scene/BLE/archive-update
        // path. The explicit developer launch argument remains the sole
        // execution authority until every composite stage is cooperative.
        // `shouldAdmitAutomaticArchiveCompaction` models the full environmental
        // gate — BGProcessing reason, backgrounded app, no exact-recovery or
        // recovered-cycle owner, and the shared thermal/battery/Low-Power
        // admission. It was written for this and then left unreachable behind
        // the fence above.
        let automaticAdmission = Self.shouldAdmitAutomaticArchiveCompaction(
            reason: reason,
            applicationIsBackground: UIApplication.shared.applicationState == .background,
            thermalState: ProcessInfo.processInfo.thermalState,
            isLowPowerModeEnabled: ProcessInfo.processInfo.isLowPowerModeEnabled,
            batteryState: UIDevice.current.batteryState,
            batteryLevel: UIDevice.current.batteryLevel,
            exactRecoveryOwnsPriority: exactRecoveryArchivePriorityLeaseActive
                || HistoricalArchive.exactRecoveryProjectionOwnsArchivePriority(),
            recoveredCycleEngaged: recoveredProjectionScanActive
        )
        guard Self.shouldExecuteArchiveWideMaintenance(
            explicitDebugOverride: explicitDebugOverride,
            automaticAdmission: automaticAdmission
        ) else {
            reserveArchiveCompactionForSafeBackground()
            AtriaDebugLog(
                "ATRIADBG archive_compaction_driver status=reserved_automatic_execution_disabled reason=%@ action=preserve_durable_archive_for_explicit_maintenance",
                reason
            )
            finishArchiveCompactionLeaseCompletion(
                lease: backgroundLease,
                fallback: completion,
                succeeded: false
            )
            return
        }
        let exactRecoveryOwnsPriority = exactRecoveryArchivePriorityLeaseActive
            || HistoricalArchive.exactRecoveryProjectionOwnsArchivePriority()
        guard !exactRecoveryOwnsPriority,
              !recoveredProjectionScanActive else {
            reserveArchiveCompactionForSafeBackground()
            AtriaDebugLog(
                "ATRIADBG archive_compaction_driver status=reserved_for_safe_background reason=%@ action=preserve_shared_archive_owner",
                reason
            )
            finishArchiveCompactionLeaseCompletion(
                lease: backgroundLease,
                fallback: completion,
                succeeded: false
            )
            return
        }
        guard !Self.archiveCompactionInFlight,
              !Self.archiveCompactionPressureProbeInFlight else {
            finishArchiveCompactionLeaseCompletion(
                lease: backgroundLease,
                fallback: completion,
                succeeded: false
            )
            return
        }
        let admission = makeArchiveCompactionSafeBackgroundAdmission(
            reason: reason,
            explicitDebugOverride: explicitDebugOverride,
            backgroundLease: backgroundLease
        )
        Self.archiveCompactionInFlight = true
        var pinned: [(start: Date, end: Date)] = confirmedSleeps.map { ($0.start, $0.end) }
        pinned.append(contentsOf: confirmedWorkouts.map { ($0.start, $0.end) })
        let pinnedWindows = pinned
        let historicalConsumerConfiguration = AtriaHistoricalConsumerProjectionConfiguration
            .production(
                restingHeartRate: baseline.restingInt ?? 60,
                maximumHeartRate: profile.maxHR,
                timeZoneIdentifier: TimeZone.current.identifier
            )
        Self.historySnapshotProjectionQueue.async { [weak self] in
            let shouldContinue = {
                admission.explicitDebugOverride
                    || Self.archiveCompactionWorkerShouldContinue(
                        admission.backgroundLease
                    )
            }
            let workerAdmissionAllowed = DispatchQueue.main.sync {
                guard let self else {
                    Self.archiveCompactionInFlight = false
                    return false
                }
                guard self
                        .archiveCompactionAdmissionRemainsValidAtWorkerBoundary(
                            admission,
                            operation: .compaction
                        ) else {
                    self.retireArchiveCompactionAdmissionAsReserved(
                        admission,
                        operation: .compaction
                    )
                    return false
                }
                return true
            }
            guard workerAdmissionAllowed else {
                AtriaDebugLog(
                    "ATRIADBG archive_compaction_driver status=reserved_worker_boundary reason=%@ action=wait_for_next_guarded_bg_processing",
                    admission.reason
                )
                DispatchQueue.main.async { [weak self] in
                    guard let self else {
                        completion?(false)
                        return
                    }
                    self.finishArchiveCompactionLeaseCompletion(
                        lease: admission.backgroundLease,
                        fallback: completion,
                        succeeded: false
                    )
                }
                return
            }
            let result = HistoricalArchive.compactArchiveConverging(
                pinnedWindows: pinnedWindows,
                reason: admission.reason,
                configuration: historicalConsumerConfiguration,
                now: now,
                shouldContinue: shouldContinue
            )
            AtriaDebugLog("ATRIADBG archive_compaction_driver status=%@ reason=%@ scanned=%d kept=%d compacted=%d summaries=%d bytes_before=%d bytes_after=%d",
                          result.status,
                          admission.reason,
                          result.scannedRows,
                          result.keptRows,
                          result.compactedRows,
                          result.summaryRows,
                          result.bytesBefore,
                          result.bytesAfter)
            DispatchQueue.main.async {
                Self.archiveCompactionInFlight = false
                // Only measured stable states earn the daily lease. In
                // particular, a consumer-cutover deferral or bounded yield must
                // not leave an over-cap install untouched for another day.
                let reachedStableState = result.status == "noop_nothing_to_compact"
                    || result.status == "noop_retention_within_bounds"
                    || result.status == "noop_retention_protected_active_exception"
                if reachedStableState {
                    UserDefaults.standard.set(now.timeIntervalSince1970, forKey: Self.archiveCompactionLastRunKey)
                }
                guard let self else {
                    completion?(false)
                    return
                }
                if reachedStableState,
                   self.archiveCompactionSafeBackgroundIntentRevision
                    == admission.intentRevision {
                    self.archiveCompactionReservedForSafeBackground = false
                } else if !reachedStableState {
                    self.reserveArchiveCompactionForSafeBackground()
                }
                // `refreshHistoricalArchiveStatus` is another whole-archive
                // diagnostics walk on a separate queue. Do not chain it from
                // retention: the BG task may have expired or the app may have
                // foregrounded while this transaction was in flight. The
                // independently guarded background projection owns eventual
                // app-facing status/metric freshness.
                // A delayed timer is not a BGProcessing authority: after 60s
                // the app may merely be backgrounded for BLE delivery, or the
                // original system task may have expired. Any yielded/deferred
                // result remains reserved and is re-offered by the next real
                // BGProcessing lease instead.
                self.finishArchiveCompactionLeaseCompletion(
                    lease: admission.backgroundLease,
                    fallback: completion,
                    succeeded: true
                )
            }
        }
    }

    nonisolated static func shouldBypassDailyArchiveCompactionLease(
        highVolumeBytes: UInt64,
        maximumHighVolumeBytes: UInt64,
        state: AtriaHistoricalHighVolumeStoragePlanner.State
    ) -> Bool {
        highVolumeBytes > maximumHighVolumeBytes
            && state != .protectedActiveException
    }

    /// Builds the >90-day compact session tier from a legacy source only before
    /// manifested full-fidelity adoption. Once the manifest is authoritative,
    /// never feed the compact builder a stale legacy monolith. Direct manifest
    /// compaction stays fail-closed until it has the same digest/parity receipt.
    private func compactColdSessionsInShadowIfUseful(reason: String, now: Date) {
        guard hasCompletedDeferredSessionLoad,
              !restorePersistenceFenceActive else { return }
        let fullStore = AtriaFullFidelityColdSessionStore(
            rootURL: AtriaFullFidelityColdSessionStore.rootURL(nextTo: coldSessionsURL)
        )
        let destination = coldSessionsURL.deletingLastPathComponent()
            .appendingPathComponent(AtriaColdSessionStore.directoryName, isDirectory: true)
        if FileManager.default.fileExists(atPath: fullStore.manifestURL.path) {
            AtriaManifestedColdSessionCompactionCoordinator.schedule(
                fullStore: fullStore,
                destinationRootURL: destination,
                now: now,
                confirmedSleeps: cachedConfirmedSleeps,
                confirmedWorkouts: cachedConfirmedWorkouts,
                restingHeartRate: baseline.restingInt ?? 60,
                maximumHeartRate: profile.maxHR,
                reason: reason
            )
            return
        }
        let context = AtriaColdSessionFactBuilder.Context(
            confirmedSleeps: cachedConfirmedSleeps,
            confirmedWorkouts: cachedConfirmedWorkouts
        )
        AtriaColdSessionShadowCoordinator.schedule(sourceURL: coldSessionsURL,
                                                   destinationRootURL: destination,
                                                   now: now,
                                                   context: context,
                                                   reason: reason)
    }

    func performBackgroundMaintenance(reason: String,
                                      now: Date,
                                      calendar: Calendar,
                                      backupCompletion: (@MainActor (Bool) -> Void)? = nil,
                                      persistenceAlreadyFlushed: Bool = false) {
        if !persistenceAlreadyFlushed {
            flushScheduledPersistence(reason: "\(reason)_persistence")
        }
        if let backupCompletion {
            // The BGTask's completion gate must cover both the off-main sleep
            // proposal and the durable backup. This preserves the original
            // settlement-before-widget contract after moving journal work off
            // the MainActor.
            autoConfirmSleepOnForegroundIfUseful(
                reason: "\(reason)_overnight_settlement",
                now: now
            ) { [weak self] _ in
                guard let self else {
                    backupCompletion(false)
                    return
                }
                self.writeAutomaticSessionBackup(reason: reason,
                                                 completion: backupCompletion)
            }
        } else {
            autoConfirmSleepOnForegroundIfUseful(reason: "\(reason)_overnight_settlement", now: now)
            writeAutomaticSessionBackup(reason: reason)
        }
        generateWeeklyReportIfNeeded(now: now, calendar: calendar, reason: reason)
        generateWeeklyPlanIfNeeded(now: now, calendar: calendar, reason: reason)
        compactColdSessionsInShadowIfUseful(reason: reason, now: now)
        materializeMorningMetricForSummaryInBackgroundIfNeeded(now: now, calendar: calendar)
        let healthSessions = sessions
        let healthRest = baseline.restingInt ?? 60
        let healthMaxHR = profile.maxHR
        let healthWorkouts = confirmedWorkouts
        let healthSleeps = confirmedSleeps
        DispatchQueue.global(qos: .utility).async {
            let health = HealthKitExporter.diagnostics(
                for: healthSessions,
                rest: healthRest,
                maxHR: healthMaxHR,
                confirmedWorkouts: healthWorkouts,
                confirmedSleeps: healthSleeps
            )
            AtriaDebugLog("ATRIADBG bg_maintenance status=ok reason=%@ sessions=%d healthkit_hr_samples=%d healthkit_resting_hr_samples=%d healthkit_hrv_samples=%d healthkit_respiratory_rate_samples=%d healthkit_workouts=%d healthkit_sleeps=%d",
                  reason,
                  healthSessions.count,
                  health.planned.hrSamples,
                  health.planned.restingHRSamples,
                  health.planned.hrvSamples,
                  health.planned.respiratoryRateSamples,
                  health.planned.workouts,
                  health.planned.sleeps)
        }
    }

    func generateWeeklyReportProductionFixtureFromLaunchIfRequested(arguments: [String] = ProcessInfo.processInfo.arguments) {
        // DEBUG-only: this forges the maintenance clock (2026-07-13) and
        // persists a weekly report under the forged ISO week. The sibling
        // notification fixtures already stub to no-ops in Release; a shipped
        // binary must have a compile-time barrier here too, not just the
        // launch-argument gate.
        #if DEBUG
        guard arguments.contains("--atria-test-weekly-report-production-maintenance") else { return }
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = .current
        let forcedMonday = calendar.date(from: DateComponents(year: 2026, month: 7, day: 13, hour: 9, minute: 0, second: 0)) ?? Date()
        performBackgroundMaintenance(reason: "debug_forced_monday_background_maintenance",
                                     now: forcedMonday,
                                     calendar: calendar)
        #else
        _ = arguments
        #endif
    }

    private func generateWeeklyReportIfNeeded(now: Date = Date(),
                                              calendar: Calendar = .current,
                                              reason: String) {
        let weekday = calendar.component(.weekday, from: now)
        guard weekday == 2 else {
            AtriaDebugLog("ATRIADBG weekly_report_generation status=skipped reason=not_monday weekday=%d source=%@",
                          weekday,
                          reason)
            return
        }

        let report = WeeklyReport(rollups: dailyRollupStore.rollups(last: 14),
                                  sleepNights: sleepHistorySnapshot.nights,
                                  now: now,
                                  calendar: calendar)
        guard report.recoveryAvg != nil else {
            AtriaDebugLog("ATRIADBG weekly_report_generation status=skipped reason=no_recovery_average source=%@ isoYear=%d isoWeek=%d",
                          reason,
                          report.isoYear,
                          report.isoWeek)
            return
        }
        guard weeklyReportStore.report(isoYear: report.isoYear, isoWeek: report.isoWeek) == nil else {
            AtriaDebugLog("ATRIADBG weekly_report_generation status=skipped reason=already_exists source=%@ isoYear=%d isoWeek=%d",
                          reason,
                          report.isoYear,
                          report.isoWeek)
            return
        }

        weeklyReportStore.save(report)
        LocalNotificationScheduler.scheduleWeeklyReport(report)
        AtriaDebugLog("ATRIADBG weekly_report_generation status=generated source=%@ isoYear=%d isoWeek=%d recovery_avg=%d sleep_consistency=%d notification_requested=1",
                      reason,
                      report.isoYear,
                      report.isoWeek,
                      report.recoveryAvg ?? -1,
                      report.sleepConsistencyPct ?? -1)
    }

    private func generateWeeklyPlanIfNeeded(now: Date = Date(),
                                            calendar: Calendar = .current,
                                            reason: String) {
        let weekday = calendar.component(.weekday, from: now)
        guard weekday == 2 else {
            AtriaDebugLog("ATRIADBG weekly_plan_generation status=skipped reason=not_monday weekday=%d source=%@",
                          weekday,
                          reason)
            return
        }

        let plan = WeeklyPlan(rollups: dailyRollupStore.rollups(last: 28),
                              now: now,
                              calendar: calendar)
        guard !plan.targets.isEmpty else {
            AtriaDebugLog("ATRIADBG weekly_plan_generation status=skipped reason=no_targets source=%@ isoYear=%d isoWeek=%d",
                          reason,
                          plan.isoYear,
                          plan.isoWeek)
            return
        }
        guard weeklyPlanStore.plan(isoYear: plan.isoYear, isoWeek: plan.isoWeek) == nil else {
            AtriaDebugLog("ATRIADBG weekly_plan_generation status=skipped reason=already_exists source=%@ isoYear=%d isoWeek=%d",
                          reason,
                          plan.isoYear,
                          plan.isoWeek)
            return
        }

        weeklyPlanStore.save(plan)
        AtriaDebugLog("ATRIADBG weekly_plan_generation status=generated source=%@ isoYear=%d isoWeek=%d targets=%d",
                      reason,
                      plan.isoYear,
                      plan.isoWeek,
                      plan.targets.count)
    }

    @discardableResult
    private nonisolated static func persistSessionsSnapshot(_ sessions: [SavedSession],
                                                            to url: URL,
                                                            reason: String) -> Bool {
        do {
            let data = try JSONEncoder().encode(sessions)
            try data.write(to: url, options: .atomic)
            AtriaDebugLog("ATRIADBG session_store_save status=ok op=%@ sessions=%d bytes=%d",
                  reason,
                  sessions.count,
                  data.count)
            return true
        } catch {
            AtriaDebugLog("ATRIADBG session_store_save status=failed op=%@ error=%@",
                  reason,
                  error.localizedDescription)
            return false
        }
    }

    // MARK: - Hot/cold session file split (docs/24 §14.1 step 1)
    //
    // sessions.json holds only RECENT sessions (start within the last
    // `coldSessionAgeDays`); older sessions live full-fidelity in
    // Legacy installs may still have sessions-cold.json. New writes publish
    // individually compressed, content-addressed full-fidelity sessions behind
    // an atomic manifest. A normal live checkpoint touches only sessions.json.

    nonisolated static let coldSessionAgeDays = 30

    /// Full-fidelity session objects are needed for recent 90-day charts and
    /// editing, but lifetime raw point/RR arrays must not remain resident. The
    /// two-day overlap avoids a civil-time boundary hole around the 90-day tier.
    nonisolated static let residentSessionHistoryDays = 92
    nonisolated static let maximumResidentSessionCount = 2_048
    /// Launch should retain enough full-fidelity evidence for several recent
    /// days without decoding the lifetime sensor store. Older sessions remain
    /// byte-for-byte available through the verified, content-addressed cold
    /// manifest and `archivedSessions(overlapping:)`.
    ///
    /// The previous 192 MiB ceiling let a 31 MiB `sessions.json` remain wholly
    /// resident and made every cold launch spend 7-10 seconds decoding sensor
    /// arrays. Twelve MiB covers the newest five days in the preserved July 22
    /// corpus (including both requested workout days) while bounding future
    /// launch work independently of lifetime history.
    nonisolated static let maximumResidentColdDecodedBytes: UInt64 = 12 * 1_024 * 1_024

    private nonisolated static func coldSessionCutoff(now: Date = Date()) -> Date {
        now.addingTimeInterval(-TimeInterval(coldSessionAgeDays) * 24 * 60 * 60)
    }

    private nonisolated static func residentSessionCutoff(now: Date = Date()) -> Date {
        now.addingTimeInterval(-TimeInterval(residentSessionHistoryDays) * 24 * 60 * 60)
    }

    nonisolated static func boundedResidentSessions(_ sessions: [SavedSession],
                                                    now: Date = Date(),
                                                    maximumCount: Int = maximumResidentSessionCount)
        -> [SavedSession] {
        guard maximumCount > 0 else { return [] }
        let cutoff = residentSessionCutoff(now: now)
        return Array(sessions
            .filter { $0.start >= cutoff }
            .sorted { lhs, rhs in
                if lhs.start != rhs.start { return lhs.start > rhs.start }
                return lhs.id.uuidString < rhs.id.uuidString
            }
            .prefix(maximumCount))
    }

    nonisolated static func partitionSessionsForPersist(_ sessions: [SavedSession],
                                                        now: Date = Date()) -> (hot: [SavedSession], cold: [SavedSession]) {
        let cutoff = coldSessionCutoff(now: now)
        var hot: [SavedSession] = []
        var cold: [SavedSession] = []
        for session in sessions {
            if session.start >= cutoff {
                hot.append(session)
            } else {
                cold.append(session)
            }
        }
        return (hot, cold)
    }

    /// Forces the next successful manifested publication to re-encode every
    /// cold session. The durable marker survives a crash during restore.
    nonisolated static func invalidateColdSessionsFingerprint(nextTo hotURL: URL) {
        let legacyColdURL = hotURL.deletingLastPathComponent()
            .appendingPathComponent("sessions-cold.json")
        let store = AtriaFullFidelityColdSessionStore(
            rootURL: AtriaFullFidelityColdSessionStore.rootURL(nextTo: legacyColdURL)
        )
        try? store.requestFullRewrite()
    }

    /// Writes the bounded hot tier on every requested revision. Cold persistence
    /// reuses verified manifest entries and encodes only IDs in `coldDelta` (or
    /// sessions newly crossing the age boundary). No ordinary save constructs,
    /// encodes, or hashes a complete cold array.
    private nonisolated static func persistPartitionedSessionsSnapshot(_ sessions: [SavedSession],
                                                                       hotURL: URL,
                                                                       coldURL: URL,
                                                                       allowColdWrite: Bool,
                                                                       coldDelta: AtriaFullFidelityColdSessionStore.Delta,
                                                                       reason: String) -> Bool {
        let cutoff = coldSessionCutoff()
        let hot = sessions.filter { $0.start >= cutoff }
        guard persistSessionsSnapshot(hot, to: hotURL, reason: reason) else {
            return false
        }
        // A persist before the deferred load has read sessions-cold.json would
        // partition an incomplete in-memory set and overwrite real cold data
        // with an empty array. Cold writes wait for load completion.
        guard allowColdWrite else { return true }
        let store = AtriaFullFidelityColdSessionStore(
            rootURL: AtriaFullFidelityColdSessionStore.rootURL(nextTo: coldURL)
        )
        do {
            let result = try store.persist(sessions: sessions,
                                           cutoff: cutoff,
                                           delta: coldDelta,
                                           preservingUnspecifiedExistingSessions: !coldDelta.requiresFullRewrite)
            AtriaDebugLog("ATRIADBG session_store_save status=ok op=%@_cold_manifest publication=%@ sessions=%d encoded_sessions=%d largest_encoded_bytes=%d",
                          reason,
                          result.status.rawValue,
                          result.coldSessionCount,
                          result.encodedSessionCount,
                          result.largestEncodedSessionBytes)
            return true
        } catch {
            AtriaDebugLog("ATRIADBG session_store_save status=failed op=%@_cold_manifest error=%@",
                  reason,
                  error.localizedDescription)
            return false
        }
    }

    #if DEBUG
    nonisolated static func persistPartitionedSessionsSnapshotForTesting(
        _ sessions: [SavedSession],
        hotURL: URL,
        coldURL: URL,
        allowColdWrite: Bool,
        coldDelta: AtriaFullFidelityColdSessionStore.Delta = .full,
        reason: String
    ) -> Bool {
        persistPartitionedSessionsSnapshot(sessions,
                                           hotURL: hotURL,
                                           coldURL: coldURL,
                                           allowColdWrite: allowColdWrite,
                                           coldDelta: coldDelta,
                                           reason: reason)
    }
    #endif

    @discardableResult
    private nonisolated static func persistDailyMetricsSnapshot(_ metrics: [SavedDailyMetric],
                                                                to url: URL,
                                                                reason: String) -> Bool {
        do {
            let data = try JSONEncoder().encode(metrics)
            try data.write(to: url, options: .atomic)
            AtriaDebugLog("ATRIADBG daily_metric_history_save status=ok op=%@ days=%d bytes=%d",
                  reason,
                  metrics.count,
                  data.count)
            return true
        } catch {
            AtriaDebugLog("ATRIADBG daily_metric_history_save status=failed op=%@ error=%@",
                  reason,
                  error.localizedDescription)
            return false
        }
    }

    private func insertionIndex(for start: Date) -> Int {
        insertionIndex(in: sessions, for: start)
    }

    private func insertionIndex(in orderedSessions: [SavedSession], for start: Date) -> Int {
        var low = 0
        var high = orderedSessions.count
        while low < high {
            let mid = (low + high) / 2
            if orderedSessions[mid].start > start {
                low = mid + 1
            } else {
                high = mid
            }
        }
        return low
    }

    private func upsertSession(_ incomingSession: SavedSession, isLiveCheckpoint: Bool = false) -> String {
        var session = incomingSession
        if session.eventTimeZoneIdentifier == nil {
            session.eventTimeZoneIdentifier = sessions.first(where: { $0.id == session.id })?.eventTimeZoneIdentifier
                ?? TimeZone.current.identifier
        }
        var next = sessions
        if let existingIndex = sessions.firstIndex(where: { $0.id == session.id }) {
            let previous = sessions[existingIndex]
            session = Self.preservingMonotonicResearchAggregates(incoming: session,
                                                                  existing: previous)
            next.remove(at: existingIndex)
            let destination = insertionIndex(in: next, for: session.start)
            next.insert(session, at: destination)
            if isLiveCheckpoint {
                pendingRestingTrendCheckpointHint = RestingTrendCheckpointHint(previous: previous,
                                                                               replacementID: session.id)
            }
            sessions = next
            pendingRestingTrendCheckpointHint = nil
            return "replace"
        }

        let destination = insertionIndex(in: next, for: session.start)
        next.insert(session, at: destination)
        if isLiveCheckpoint {
            pendingRestingTrendCheckpointHint = RestingTrendCheckpointHint(previous: nil,
                                                                           replacementID: session.id)
        }
        sessions = next
        pendingRestingTrendCheckpointHint = nil
        return "insert"
    }

    nonisolated static func preservingMonotonicResearchAggregates(
        incoming: SavedSession,
        existing: SavedSession
    ) -> SavedSession {
        var merged = incoming
        merged.sensorResearchProbeFrames = monotonicOptionalCount(incoming.sensorResearchProbeFrames,
                                                                   existing.sensorResearchProbeFrames)
        merged.spo2ResearchCandidateFrames = monotonicOptionalCount(incoming.spo2ResearchCandidateFrames,
                                                                     existing.spo2ResearchCandidateFrames)
        merged.skinTempResearchCandidateFrames = monotonicOptionalCount(incoming.skinTempResearchCandidateFrames,
                                                                          existing.skinTempResearchCandidateFrames)

        let incomingTemperature = validResearchTemperatureTuple(sum: incoming.skinTempResearchCandidateValueSum,
                                                                 count: incoming.skinTempResearchCandidateValueCount)
        let existingTemperature = validResearchTemperatureTuple(sum: existing.skinTempResearchCandidateValueSum,
                                                                 count: existing.skinTempResearchCandidateValueCount)
        let selectedTemperature: (sum: Int, count: Int)?
        switch (incomingTemperature, existingTemperature) {
        case let (incoming?, existing?):
            selectedTemperature = incoming.count > existing.count
                || (incoming.count == existing.count && incoming.sum >= existing.sum)
                ? incoming
                : existing
        case let (incoming?, nil):
            selectedTemperature = incoming
        case let (nil, existing?):
            selectedTemperature = existing
        case (nil, nil):
            selectedTemperature = nil
        }
        merged.skinTempResearchCandidateValueSum = selectedTemperature?.sum
        merged.skinTempResearchCandidateValueCount = selectedTemperature?.count

        let selectedOxygenOffset64 = Self.preferredResearchValueTuple(
            incomingSum: incoming.spo2ResearchCandidateOffset64ValueSum,
            incomingCount: incoming.spo2ResearchCandidateOffset64ValueCount,
            existingSum: existing.spo2ResearchCandidateOffset64ValueSum,
            existingCount: existing.spo2ResearchCandidateOffset64ValueCount
        )
        merged.spo2ResearchCandidateOffset64ValueSum = selectedOxygenOffset64?.sum
        merged.spo2ResearchCandidateOffset64ValueCount = selectedOxygenOffset64?.count

        let selectedOxygenOffset66 = Self.preferredResearchValueTuple(
            incomingSum: incoming.spo2ResearchCandidateOffset66ValueSum,
            incomingCount: incoming.spo2ResearchCandidateOffset66ValueCount,
            existingSum: existing.spo2ResearchCandidateOffset66ValueSum,
            existingCount: existing.spo2ResearchCandidateOffset66ValueCount
        )
        merged.spo2ResearchCandidateOffset66ValueSum = selectedOxygenOffset66?.sum
        merged.spo2ResearchCandidateOffset66ValueCount = selectedOxygenOffset66?.count
        let incomingStrapSteps = incoming.strapStepResearchCount.flatMap { $0 >= 0 ? $0 : nil }
        let existingStrapSteps = existing.strapStepResearchCount.flatMap { $0 >= 0 ? $0 : nil }
        merged.strapStepResearchCount = monotonicOptionalCount(incomingStrapSteps,
                                                               existingStrapSteps)
        let incomingCheckpointIsWeaker = incomingStrapSteps.map { incoming in
            existingStrapSteps.map { incoming < $0 } ?? false
        } ?? (existingStrapSteps != nil)
        if incomingCheckpointIsWeaker {
            // The count and its validation/provenance state are one checkpoint.
            // If a delayed same-ID write loses to the existing cumulative count,
            // retain the state that described that stronger checkpoint as well.
            merged.strapStepResearchState = existing.strapStepResearchState
        }
        let incomingDecoded = incoming.decodedSkinTemperatureCelsius?
            .filter(\.isAggregationEligible) ?? []
        let existingDecoded = existing.decodedSkinTemperatureCelsius?
            .filter(\.isAggregationEligible) ?? []
        if incomingDecoded.isEmpty {
            merged.decodedSkinTemperatureCelsius = existingDecoded.isEmpty ? nil : existingDecoded
        } else if existingDecoded.isEmpty || incomingDecoded.count >= existingDecoded.count {
            merged.decodedSkinTemperatureCelsius = incomingDecoded
        } else {
            merged.decodedSkinTemperatureCelsius = existingDecoded
        }
        return merged
    }

    private nonisolated static func monotonicOptionalCount(_ incoming: Int?, _ existing: Int?) -> Int? {
        let validIncoming = incoming.flatMap { $0 >= 0 ? $0 : nil }
        let validExisting = existing.flatMap { $0 >= 0 ? $0 : nil }
        switch (validIncoming, validExisting) {
        case let (incoming?, existing?): return max(incoming, existing)
        case let (incoming?, nil): return incoming
        case let (nil, existing?): return existing
        case (nil, nil): return nil
        }
    }

    private nonisolated static func validResearchTemperatureTuple(sum: Int?, count: Int?) -> (sum: Int, count: Int)? {
        guard let sum, let count, sum >= 0, count >= 0, count > 0 || sum == 0 else { return nil }
        return (sum, count)
    }

    /// RESEARCH-ONLY: pick the higher-evidence sum/count capture between two
    /// segments, mirroring the skin-temperature value-tuple selection. Prefers
    /// the larger sample count, then the larger sum. Used for the SpO2
    /// candidate byte-value captures at offsets 64/66; never an SpO2 value.
    private nonisolated static func preferredResearchValueTuple(
        incomingSum: Int?, incomingCount: Int?,
        existingSum: Int?, existingCount: Int?
    ) -> (sum: Int, count: Int)? {
        let incoming = validResearchTemperatureTuple(sum: incomingSum, count: incomingCount)
        let existing = validResearchTemperatureTuple(sum: existingSum, count: existingCount)
        switch (incoming, existing) {
        case let (incoming?, existing?):
            return incoming.count > existing.count
                || (incoming.count == existing.count && incoming.sum >= existing.sum)
                ? incoming
                : existing
        case let (incoming?, nil):
            return incoming
        case let (nil, existing?):
            return existing
        case (nil, nil):
            return nil
        }
    }

