    /// Latency-safe explicit workout confirmation. Only immutable snapshots
    /// cross the actor boundary; the utility task owns journal stat/read/decode,
    /// canonicalization, sample slicing/sorting and metric calculation. The
    /// main actor publishes only a revision-checked canonical result.
    func confirmWorkoutWindowForUIAsync(
        start: Date,
        end: Date,
        rest: Int,
        maxHR: Int,
        source: String = "ui_window",
        preserveUserDeclaredActivityWithoutHeartRate: Bool = false,
        activityLabel: String? = nil,
        activityType: String? = nil,
        activitySubtype: String? = nil,
        exerciseNames: [String] = [],
        strengthSets: [LoggedSet] = [],
        excludedIntervals: [ExcludedInterval] = [],
        reviewSource: String? = nil,
        reviewCandidateID: String? = nil,
        settlingCandidateWindow: (start: Date, end: Date)? = nil,
        workoutSteps: Int? = nil,
        workoutStepsAreEstimated: Bool? = nil,
        workoutStepsCapturedAt: Date? = nil
    ) async -> UserConfirmedWorkout? {
        // Workout completion stops the live session before entering this API,
        // so canonical revision churn should settle immediately. Retry if a
        // final checkpoint wins the race; never commit metrics prepared from a
        // superseded session/profile snapshot.
        for _ in 0..<3 {
            let currentProfile = profile
            let request = WorkoutWindowConfirmationRequest(
                start: start,
                end: end,
                rest: rest,
                maxHR: maxHR,
                source: source,
                allowManualSave: true,
                preserveUserDeclaredActivityWithoutHeartRate: preserveUserDeclaredActivityWithoutHeartRate,
                activityLabel: activityLabel,
                activityType: activityType,
                activitySubtype: activitySubtype,
                exerciseNames: exerciseNames,
                strengthSets: strengthSets,
                excludedIntervals: excludedIntervals,
                reviewSource: reviewSource,
                reviewCandidateID: reviewCandidateID,
                settlingCandidateWindow: settlingCandidateWindow,
                workoutSteps: workoutSteps,
                workoutStepsAreEstimated: workoutStepsAreEstimated,
                workoutStepsCapturedAt: workoutStepsCapturedAt,
                profile: currentProfile,
                eventTimeZoneIdentifier: TimeZone.current.identifier
            )
            let fingerprint = WorkoutWindowConfirmationFingerprint(
                canonicalSessionsRevision: canonicalSessionsRevision,
                profile: currentProfile
            )
            let snapshot = WorkoutWindowPreparationSnapshot(
                fingerprint: fingerprint,
                request: request,
                canonicalSessions: cachedCanonicalSessions,
                preparedAt: Date()
            )
            let prepared = await Task.detached(priority: .utility) {
                let activeJournalSession = Self.loadActiveJournalSessionIfFresh(now: snapshot.preparedAt)
                return Self.prepareWorkoutWindowConfirmation(
                    snapshot: snapshot,
                    activeJournalSession: activeJournalSession
                )
            }.value
            guard prepared.fingerprint == WorkoutWindowConfirmationFingerprint(
                canonicalSessionsRevision: canonicalSessionsRevision,
                profile: profile
            ) else {
                await Task.yield()
                continue
            }
            return await commitPreparedWorkoutWindowConfirmation(prepared)
        }

        AtriaDebugLog("ATRIADBG workout_confirm status=deferred reason=source_changed_during_off_main_prepare source=%@",
                      source)
        return nil
    }

    nonisolated static func explicitWorkoutSaveIsConfirmable(sampleCount: Int,
                                                              requestedDuration: TimeInterval) -> Bool {
        sampleCount >= 2 && requestedDuration > 0
    }

    nonisolated static func metadataOnlyWorkoutSaveIsConfirmable(
        isExplicitUserActivity: Bool,
        requestedDuration: TimeInterval
    ) -> Bool {
        isExplicitUserActivity && requestedDuration > 0
    }

    func confirmBestWorkoutCandidateFromLaunchIfRequested(arguments: [String] = ProcessInfo.processInfo.arguments) {
        guard arguments.contains("--atria-confirm-best-workout-candidate") else { return }
        Task { @MainActor [weak self] in
            guard let self else { return }
            let rest = self.baseline.restingInt ?? 60
            _ = await self.confirmBestWorkoutCandidate(
                rest: rest,
                maxHR: self.profile.maxHR,
                source: "launch_arg"
            )
        }
    }

    /// #1 auto-upgrade (2026-08-22): the user asked that when the strap "comes back
    /// online" the app should "flush the missing portion and reliably recalculate
    /// the readings" rather than leave a workout stuck without HR. A segment saved
    /// metadata-only while the link was dropped (confidence `user_confirmed_no_hr`,
    /// samples 0) is re-run through the SAME production confirm pipeline; once its
    /// window's HR/motion has drained, `commitPreparedWorkoutWindowConfirmation`
    /// upgrades it in place (see `workoutByUpgradingHeartRateMetrics`). A window that
    /// still has no HR re-saves unchanged, so this is safe to run repeatedly (no
    /// churn) and never fabricates evidence.
    func upgradeMetadataOnlyWorkoutsFromHistoryIfNeeded() async {
        let candidates = cachedConfirmedWorkouts.filter {
            $0.confidence == "user_confirmed_no_hr" && $0.samples == 0
        }
        guard !candidates.isEmpty else { return }
        let rest = baseline.restingInt ?? 60
        let maxHR = profile.maxHR
        AtriaDebugLog("ATRIADBG workout_confirm status=metadata_only_upgrade_sweep candidates=%d",
                      candidates.count)
        for workout in candidates {
            _ = await confirmWorkoutWindowForUIAsync(
                start: workout.start,
                end: workout.end,
                rest: rest,
                maxHR: maxHR,
                source: "metadata_only_upgrade_sweep",
                preserveUserDeclaredActivityWithoutHeartRate: true,
                activityLabel: workout.label,
                activityType: workout.activityType,
                activitySubtype: workout.activitySubtype,
                exerciseNames: workout.exerciseNames ?? [],
                strengthSets: workout.strengthSets ?? [],
                excludedIntervals: workout.excludedIntervals ?? [],
                reviewSource: workout.reviewSource,
                reviewCandidateID: workout.reviewCandidateID,
                workoutSteps: workout.workoutSteps,
                workoutStepsAreEstimated: workout.workoutStepsAreEstimated,
                workoutStepsCapturedAt: workout.workoutStepsCapturedAt
            )
        }
    }

    /// Fire-and-forget launch/foreground wrapper for the metadata-only upgrade
    /// sweep — production reconciliation, not a launch-arg diagnostic.
    func upgradeMetadataOnlyWorkoutsFromHistoryInBackground() {
        Task { @MainActor [weak self] in
            await self?.upgradeMetadataOnlyWorkoutsFromHistoryIfNeeded()
        }
    }

    /// Device-recovery hook for an exact user-supplied window. Arguments are
    /// `--atria-confirm-workout-window <start-unix> <end-unix> <activity-type>`.
    /// It uses the same production confirmation path as Add Activity and waits
    /// for deferred session loading, so no evidence is injected or fabricated.
    func confirmWorkoutWindowFromLaunchIfRequested(arguments: [String] = ProcessInfo.processInfo.arguments) {
        guard let flag = arguments.firstIndex(of: "--atria-confirm-workout-window") else { return }
        let startIndex = flag + 1
        let endIndex = flag + 2
        let typeIndex = flag + 3
        guard typeIndex < arguments.count,
              let startUnix = TimeInterval(arguments[startIndex]),
              let endUnix = TimeInterval(arguments[endIndex]),
              endUnix > startUnix else {
            AtriaDebugLog("ATRIADBG workout_window_recovery status=invalid_arguments")
            return
        }
        let activityType = arguments[typeIndex]
        Task { @MainActor [weak self] in
            try? await Task.sleep(for: .seconds(2))
            guard let self else { return }
            let confirmed = await self.confirmWorkoutWindowForUI(
                start: Date(timeIntervalSince1970: startUnix),
                end: Date(timeIntervalSince1970: endUnix),
                rest: self.baseline.restingInt ?? 60,
                maxHR: self.profile.maxHR,
                source: "exact_window_recovery",
                activityType: activityType
            )
            UserDefaults.standard.set(confirmed == nil ? "failed" : "confirmed",
                                      forKey: "atria.workoutWindowRecovery.status")
            UserDefaults.standard.set(confirmed?.id ?? "none",
                                      forKey: "atria.workoutWindowRecovery.id")
            UserDefaults.standard.set(Date().timeIntervalSince1970,
                                      forKey: "atria.workoutWindowRecovery.at")
            AtriaDebugLog("ATRIADBG workout_window_recovery status=%@ start_unix=%d end_unix=%d type=%@ id=%@",
                          confirmed == nil ? "failed" : "confirmed",
                          Int(startUnix),
                          Int(endUnix),
                          activityType,
                          confirmed?.id ?? "none")
        }
    }

    private func confirmBestWorkoutCandidate(rest: Int,
                                             maxHR: Int,
                                             source: String,
                                             now: Date = Date()) async -> UserConfirmedWorkout? {
        let summary = replaySavedWorkoutReadiness(rest: rest, maxHR: maxHR)
        guard let bestStart = summary.bestStart,
              let bestEnd = summary.bestEnd else {
            AtriaDebugLog("ATRIADBG workout_confirm status=learning reason=no_confirmable_window source=%@ rest_hr=%d max_hr=%d metric_promotions=0",
                  source,
                  rest,
                  maxHR)
            return nil
        }
        guard summary.sessionsEvaluated > 0,
              summary.bestSource != "none",
              bestEnd > bestStart else {
            AtriaDebugLog("ATRIADBG workout_confirm status=learning reason=no_confirmable_candidate source=%@ rest_hr=%d max_hr=%d metric_promotions=0",
                  source,
                  rest,
                  maxHR)
            return nil
        }
        // Permanent ghost-killer, mirrored from latestWorkoutReviewCandidate:
        // never confirm a candidate whose window ended over a day ago.
        guard now.timeIntervalSince(bestEnd) <= Self.workoutReviewStaleAfter else {
            AtriaDebugLog("ATRIADBG workout_confirm status=stale reason=window_ended_over_24h_ago source=%@ candidate_source=%@ metric_promotions=0",
                  source,
                  summary.bestSource)
            DetectionEventLog.append(DetectionEvent(kind: "workoutSuppressed",
                                                     reason: "window_ended_over_24h_ago",
                                                     detail: "candidate_source=\(summary.bestSource)"))
            return nil
        }
        let confirmable = (summary.readySessions > 0 || summary.bestReviewWorthyCandidate)
            && !summary.bestContactCompromised
        guard confirmable else {
            AtriaDebugLog("ATRIADBG workout_confirm status=learning reason=candidate_not_review_worthy source=%@ candidate_source=%@ observed_s=%.0f stream_coverage_percent=%d peak_over_rest=%d near_miss=%d strength_candidate=%d auto_ready=%d metric_promotions=0",
                  source,
                  summary.bestSource,
                  summary.bestObservedDuration,
                  summary.bestStreamCoveragePercent,
                  summary.bestPeakHR - rest,
                  summary.nearMiss ? 1 : 0,
                  summary.strengthCandidate ? 1 : 0,
                  summary.readySessions > 0 ? 1 : 0)
            return nil
        }
        var existing = cachedConfirmedWorkouts
        let id = confirmedWorkoutID(start: bestStart, end: bestEnd, source: summary.bestSource)
        if let already = existing.first(where: { $0.id == id }) {
            AtriaDebugLog("ATRIADBG workout_confirm status=already_confirmed id=%@ source=%@ candidate_source=%@ start=%@ end=%@ confidence=%@ metric_promotions=0 auto_gate_e_unchanged=1",
                  already.id,
                  source,
                  already.source,
                  isoString(already.start),
                  isoString(already.end),
                  already.confidence)
            return already
        }
        let confidence = summary.readySessions > 0 ? "auto_ready_user_confirmed" :
            (summary.nearMiss ? "user_confirmed_near_miss" : "user_confirmed_candidate")
        // Sharpen the displayed start to the real effort onset (getting-ready
        // trimmed off). `id` above stays on the untrimmed bestStart so identity
        // is stable (no dismissed/confirmed workout resurfaces), and readiness
        // was already decided from the untrimmed window; only start + strain
        // tighten. Fails closed to bestStart when there's no honest onset.
        // Same end-bound as the review cache (2026-07-31): close the saved
        // window at the last sustained elevated bout plus the recovery tail
        // instead of the session boundary hours later. Fails closed to bestEnd.
        let displayEnd = sustainedWorkoutEndBound(start: bestStart, end: bestEnd, rest: rest, maxHR: maxHR) ?? bestEnd
        let displayStart = sustainedWorkoutOnsetStart(start: bestStart, end: displayEnd, rest: rest, maxHR: maxHR) ?? bestStart
        // When either boundary was trimmed, recompute the DISPLAYED HR stats
        // over the trimmed window so avg/coverage/observed/percentiles match
        // the shown start+duration+strain (honesty rule). nil = no trim ->
        // summary values.
        let trimmedStats = (displayStart != bestStart || displayEnd != bestEnd)
            ? workoutWindowHRStats(start: displayStart, end: displayEnd)
            : nil
        let enriched = confirmedWorkoutMetrics(start: displayStart,
                                               end: displayEnd,
                                               rest: rest,
                                               maxHR: maxHR,
                                               biologicalSex: profile.biologicalSex,
                                               excludedIntervals: [])
        let confirmed = UserConfirmedWorkout(id: id,
                                             createdAt: Date(),
                                             start: displayStart,
                                             end: displayEnd,
                                             label: summary.bestLabel,
                                             source: summary.bestSource,
                                             confidence: confidence,
                                             sessions: summary.bestChunkCount,
                                             samples: trimmedStats?.samples ?? summary.bestSamples,
                                             avgHR: trimmedStats?.avgHR ?? summary.bestAvgHR,
                                             peakHR: trimmedStats?.peakHR ?? summary.bestPeakHR,
                                             p95HR: trimmedStats?.p95HR ?? summary.bestP95HR,
                                             p99HR: trimmedStats?.p99HR ?? summary.bestP99HR,
                                             thresholdHR: summary.bestThresholdHR,
                                             streamCoveragePercent: trimmedStats?.streamCoveragePercent ?? summary.bestStreamCoveragePercent,
                                             observedDuration: trimmedStats?.observedDuration ?? summary.bestObservedDuration,
                                             reason: summary.bestReason,
                                             strain: enriched.strain,
                                             strainCalibrationVersion: enriched.strain == nil
                                                ? nil
                                                : AtriaAnalytics.Strain.displayCalibrationVersion,
                                             activeEnergyKilocalories: enriched.activeEnergyKilocalories,
                                             activeEnergyConfidence: enriched.activeEnergyConfidence,
                                             zoneSeconds: enriched.zoneSeconds,
                                             eventTimeZoneIdentifier: TimeZone.current.identifier)
        existing.append(confirmed)
        guard await saveConfirmedWorkouts(
            existing,
            stressContextMutation: .init(previous: nil, next: confirmed)
        ) else {
            AtriaDebugLog("ATRIADBG workout_confirm status=store_failed id=%@ source=%@ start=%@ end=%@ action=retain_pending_intent",
                          confirmed.id,
                          source,
                          isoString(confirmed.start),
                          isoString(confirmed.end))
            return nil
        }
        let auditSamples = canonicalSessions(includeActiveJournal: true).flatMap { session in
            session.points.compactMap { point -> HRSample? in
                let sample = HRSample(t: session.start.addingTimeInterval(max(0, point.t)), bpm: point.bpm)
                return sample.t >= confirmed.start && sample.t <= confirmed.end && sample.bpm > 0
                    ? sample : nil
            }
        }
        Self.persistStrainConfirmationAudit(
            confirmed: confirmed,
            samples: auditSamples,
            rest: rest,
            maxHR: maxHR,
            biologicalSex: profile.biologicalSex,
            excludedIntervals: []
        )
        clearDismissedWorkoutCandidates(overlappingStart: confirmed.start, end: confirmed.end)
        AtriaDebugLog("ATRIADBG workout_confirm status=confirmed id=%@ source=%@ candidate_source=%@ label=%@ start=%@ end=%@ duration_s=%.0f observed_s=%.0f chunks=%d samples=%d avg_hr=%d peak_hr=%d p95_hr=%d p99_hr=%d threshold_hr=%d stream_coverage_percent=%d confidence=%@ strain=%.2f active_energy_kcal=%.0f active_energy_confidence=%@ zone_rest_s=%.0f zone_warmup_s=%.0f zone_fat_burn_s=%.0f zone_aerobic_s=%.0f zone_anaerobic_s=%.0f zone_max_s=%.0f auto_gate_e_unchanged=1 healthkit_source=user_confirmed",
              confirmed.id,
              source,
              confirmed.source,
              confirmed.label,
              isoString(confirmed.start),
              isoString(confirmed.end),
              confirmed.duration,
              confirmed.observedDuration,
              confirmed.sessions,
              confirmed.samples,
              confirmed.avgHR,
              confirmed.peakHR,
              confirmed.p95HR,
              confirmed.p99HR,
              confirmed.thresholdHR,
              confirmed.streamCoveragePercent,
              confirmed.confidence,
              confirmed.strain ?? 0,
              confirmed.activeEnergyKilocalories ?? 0,
              confirmed.activeEnergyConfidence ?? "none",
              confirmed.zoneSeconds?["rest"] ?? 0,
              confirmed.zoneSeconds?["warmup"] ?? 0,
              confirmed.zoneSeconds?["fatBurn"] ?? 0,
              confirmed.zoneSeconds?["aerobic"] ?? 0,
              confirmed.zoneSeconds?["anaerobic"] ?? 0,
              confirmed.zoneSeconds?["max"] ?? 0)
        DetectionEventLog.append(DetectionEvent(kind: "workoutDetected",
                                                 reason: "confirmed",
                                                 detail: "\(confirmed.label), \(Int(confirmed.duration))s",
                                                 windowStart: confirmed.start,
                                                 windowEnd: confirmed.end))
        return confirmed
    }

    nonisolated static func prepareWorkoutWindowConfirmation(
        snapshot: WorkoutWindowPreparationSnapshot,
        activeJournalSession: SavedSession?
    ) -> PreparedWorkoutWindowConfirmation {
        let request = snapshot.request
        let sourceSessions = makeCanonicalSessions(
            from: snapshot.canonicalSessions + (activeJournalSession.map { [$0] } ?? []),
            preferredSession: preferredSession
        )
        let overlappingEvidence = sourceSessions.filter { session in
            session.end > request.start && session.start < request.end
        }
        let overlapping = overlappingEvidence.filter { !$0.points.isEmpty }
        let calibrationEvidence = request.reviewSource == "detected_activity_review"
            && !(request.reviewCandidateID?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ?? true)
            ? activityCalibrationEvidence(sessions: overlappingEvidence,
                                          start: request.start,
                                          end: request.end)
            : nil
        var points: [SavedSession.Point] = []
        points.reserveCapacity(overlapping.reduce(0) { $0 + $1.points.count })
        for session in overlapping {
            for point in session.points {
                let absoluteTime = session.start.addingTimeInterval(max(0, point.t))
                guard absoluteTime >= request.start,
                      absoluteTime <= request.end,
                      point.bpm > 0 else { continue }
                points.append(SavedSession.Point(
                    t: absoluteTime.timeIntervalSince(request.start),
                    bpm: point.bpm
                ))
            }
        }
        points.sort { $0.t < $1.t }

        guard request.end > request.start, points.count >= 2 else {
            return PreparedWorkoutWindowConfirmation(
                fingerprint: snapshot.fingerprint,
                request: request,
                overlappingSessionCount: overlapping.count,
                points: points,
                readiness: nil,
                strain: nil,
                activeEnergyKilocalories: nil,
                activeEnergyConfidence: nil,
                zoneSeconds: nil,
                activityCalibrationEvidence: calibrationEvidence
            )
        }

        let window = SavedSession(
            id: UUID(),
            start: request.start,
            end: request.end,
            label: "Live workout",
            points: points,
            hrv: nil,
            eventTimeZoneIdentifier: request.eventTimeZoneIdentifier
        )
        let readiness = window.workoutReadiness(rest: request.rest, maxHR: request.maxHR)
        let metrics = preparedWorkoutMetrics(
            overlappingSessions: overlapping,
            start: request.start,
            end: request.end,
            rest: request.rest,
            maxHR: request.maxHR,
            profile: request.profile,
            excludedIntervals: request.excludedIntervals
        )
        return PreparedWorkoutWindowConfirmation(
            fingerprint: snapshot.fingerprint,
            request: request,
            overlappingSessionCount: overlapping.count,
            points: points,
            readiness: readiness,
            strain: metrics.strain,
            activeEnergyKilocalories: metrics.activeEnergyKilocalories,
            activeEnergyConfidence: metrics.activeEnergyConfidence,
            zoneSeconds: metrics.zoneSeconds,
            activityCalibrationEvidence: calibrationEvidence
        )
    }

    private nonisolated static func preparedWorkoutMetrics(
        overlappingSessions: [SavedSession],
        start: Date,
        end: Date,
        rest: Int,
        maxHR: Int,
        profile: AthleteProfile,
        excludedIntervals: [ExcludedInterval]
    ) -> (strain: Double?,
          activeEnergyKilocalories: Double?,
          activeEnergyConfidence: String?,
          zoneSeconds: [String: TimeInterval]?) {
        var samples: [HRSample] = []
        samples.reserveCapacity(overlappingSessions.reduce(0) { $0 + $1.points.count })
        for session in overlappingSessions {
            for point in session.points {
                let sample = HRSample(
                    t: session.start.addingTimeInterval(max(0, point.t)),
                    bpm: point.bpm
                )
                if sample.t >= start, sample.t <= end {
                    samples.append(sample)
                }
            }
        }
        samples.sort { $0.t < $1.t }
        let segments = AtriaAnalytics.Strain.contiguousSegments(
            samples,
            excluding: excludedIntervals
        )
        guard segments.contains(where: { $0.count > 1 }) else {
            return (nil, nil, nil, nil)
        }
        let trimp = confirmedWorkoutTRIMP(
            segments: segments,
            start: start,
            rest: rest,
            maxHR: maxHR,
            biologicalSex: profile.biologicalSex
        )
        let zoneSummary = segments.reduce(AtriaAnalytics.Strain.MaxHeartRateZoneSeconds.empty) { total, segment in
            total + AtriaAnalytics.Strain.maxHeartRateZoneSeconds(
                segment.map { (t: $0.t.timeIntervalSince(start), bpm: $0.bpm) },
                maxHR: maxHR,
                restingHR: rest
            )
        }
        let energyParts = segments.compactMap { segment in
            Metrics.activeCalories(segment, rest: rest, profile: profile)
        }
        let activeEnergy = energyParts.isEmpty ? nil : energyParts.reduce(0, +)
        return (
            Metrics.strain(fromTRIMP: trimp),
            activeEnergy,
            activeEnergy == nil ? (profile.hasEnergyProfile ? nil : "needs_profile") : "estimate",
            zoneSummary.isEmpty ? nil : zoneSummary.storage
        )
    }

    private func commitPreparedWorkoutWindowConfirmation(
        _ prepared: PreparedWorkoutWindowConfirmation
    ) async -> UserConfirmedWorkout? {
        let request = prepared.request
        guard request.end > request.start else {
            AtriaDebugLog("ATRIADBG workout_confirm status=learning reason=invalid_window source=%@ start=%@ end=%@ metric_promotions=0",
                          request.source,
                          isoString(request.start),
                          isoString(request.end))
            return nil
        }

        guard let readiness = prepared.readiness, prepared.points.count >= 2 else {
            if Self.metadataOnlyWorkoutSaveIsConfirmable(
                isExplicitUserActivity: request.preserveUserDeclaredActivityWithoutHeartRate,
                requestedDuration: request.end.timeIntervalSince(request.start)
            ) {
                return await confirmMetadataOnlyWorkout(
                    start: request.start,
                    end: request.end,
                    rest: request.rest,
                    maxHR: request.maxHR,
                    source: request.source,
                    overlappingSessionCount: prepared.overlappingSessionCount,
                    activityLabel: request.activityLabel,
                    activityType: request.activityType,
                    activitySubtype: request.activitySubtype,
                    exerciseNames: request.exerciseNames,
                    strengthSets: request.strengthSets,
                    excludedIntervals: request.excludedIntervals,
                    reviewSource: request.reviewSource,
                    reviewCandidateID: request.reviewCandidateID,
                    activityCalibrationEvidence: prepared.activityCalibrationEvidence,
                    settlingCandidateWindow: request.settlingCandidateWindow,
                    workoutSteps: request.workoutSteps,
                    workoutStepsAreEstimated: request.workoutStepsAreEstimated,
                    workoutStepsCapturedAt: request.workoutStepsCapturedAt
                )
            }
            AtriaDebugLog("ATRIADBG workout_confirm status=learning reason=window_too_few_samples source=%@ start=%@ end=%@ samples=%d metric_promotions=0",
                          request.source,
                          isoString(request.start),
                          isoString(request.end),
                          prepared.points.count)
            return nil
        }

        let requestedDuration = request.end.timeIntervalSince(request.start)
        let manualConfirmable = request.allowManualSave
            && Self.explicitWorkoutSaveIsConfirmable(
                sampleCount: prepared.points.count,
                requestedDuration: requestedDuration
            )
        let confirmable = (readiness.ready
            || (readiness.observedDuration >= 15 * 60
                && readiness.streamCoveragePercent >= 60
                && (readiness.nearMiss || readiness.strengthCandidate)))
            || manualConfirmable
        guard confirmable else {
            AtriaDebugLog("ATRIADBG workout_confirm status=learning reason=window_candidate_too_weak source=%@ observed_s=%.0f stream_coverage_percent=%d ready=%d near_miss=%d strength_candidate=%d primary_blocker=%@ metric_promotions=0",
                          request.source,
                          readiness.observedDuration,
                          readiness.streamCoveragePercent,
                          readiness.ready ? 1 : 0,
                          readiness.nearMiss ? 1 : 0,
                          readiness.strengthCandidate ? 1 : 0,
                          readiness.primaryBlocker)
            return nil
        }

        var existing = cachedConfirmedWorkouts
        let workoutSource = "live_workout_window"
        let id = confirmedWorkoutID(start: request.start, end: request.end, source: workoutSource)

        // Build the freshly computed record up front so it can either UPGRADE an
        // existing weaker record in place — e.g. a metadata-only save made while the
        // strap link was dropped, once its window's HR/motion has since drained
        // (#1 auto-upgrade, 2026-08-22) — or be appended when the window is new.
        let confidence = readiness.ready ? "live_window_user_confirmed" :
            (readiness.nearMiss ? "live_window_near_miss" :
                (manualConfirmable
                    ? (readiness.streamCoveragePercent < 5
                        ? "live_window_manual_sparse_hr"
                        : "live_window_manual_confirmed")
                    : "live_window_candidate"))
        let typeValue = request.activityType?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let labelValue = request.activityLabel?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let subtypeValue = request.activitySubtype?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let reviewValue = request.reviewSource?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let reviewCandidateValue = request.reviewCandidateID?
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let cleanedType = typeValue.isEmpty ? nil : typeValue
        let cleanedLabel = labelValue.isEmpty ? nil : labelValue
        let cleanedSubtype = subtypeValue.isEmpty ? nil : subtypeValue
        let cleanedExercises = request.exerciseNames
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
        let cleanedReview = reviewValue.isEmpty ? nil : reviewValue
        let cleanedReviewCandidateID = reviewCandidateValue.isEmpty ? nil : reviewCandidateValue
        let confirmed = UserConfirmedWorkout(
            id: id,
            createdAt: Date(),
            start: request.start,
            end: request.end,
            label: cleanedLabel ?? cleanedType ?? "Live workout",
            source: workoutSource,
            confidence: confidence,
            sessions: prepared.overlappingSessionCount,
            samples: prepared.points.count,
            avgHR: readiness.avgHR,
            peakHR: readiness.peakHR,
            p95HR: readiness.p95HR,
            p99HR: readiness.p99HR,
            thresholdHR: readiness.thresholdHR,
            streamCoveragePercent: readiness.streamCoveragePercent,
            observedDuration: readiness.observedDuration,
            reason: readiness.ready ? readiness.reason : readiness.primaryBlocker,
            activityType: cleanedType,
            activitySubtype: cleanedSubtype,
            exerciseNames: cleanedExercises.isEmpty ? nil : cleanedExercises,
            strengthSets: request.strengthSets.isEmpty ? nil : request.strengthSets,
            muscularLoadReceipt: AtriaStrengthLog.muscularLoadReceipt(for: request.strengthSets),
            excludedIntervals: request.excludedIntervals.isEmpty ? nil : request.excludedIntervals,
            reviewSource: cleanedReview,
            reviewCandidateID: cleanedReviewCandidateID,
            activityCalibrationEvidence: prepared.activityCalibrationEvidence,
            strain: prepared.strain,
            strainCalibrationVersion: prepared.strain == nil
                ? nil
                : AtriaAnalytics.Strain.displayCalibrationVersion,
            activeEnergyKilocalories: prepared.activeEnergyKilocalories,
            activeEnergyConfidence: prepared.activeEnergyConfidence,
            zoneSeconds: prepared.zoneSeconds,
            eventTimeZoneIdentifier: request.eventTimeZoneIdentifier,
            workoutSteps: request.workoutSteps.map { max(0, $0) },
            workoutStepsAreEstimated: request.workoutSteps == nil ? nil : (request.workoutStepsAreEstimated ?? true),
            workoutStepsCapturedAt: request.workoutSteps == nil ? nil : request.workoutStepsCapturedAt
        )
        if let index = existing.firstIndex(where: { $0.id == id }) {
            let already = existing[index]
            // #1 auto-upgrade: the window now yields strictly more HR samples than
            // the saved record (e.g. a metadata-only save during a strap drop, whose
            // HR/motion has since drained). Rebuild it in place from the stronger
            // computation, preserving user edits. Guarded on MORE samples so it can
            // only upgrade, never regress a good record; a later equal pass no-ops.
            if confirmed.samples > already.samples {
                let upgraded = Self.workoutByUpgradingHeartRateMetrics(
                    existing: already,
                    recomputed: confirmed
                )
                if upgraded != already {
                    existing[index] = upgraded
                    guard await saveConfirmedWorkouts(
                        existing,
                        stressContextMutation: .init(previous: already, next: upgraded)
                    ) else { return nil }
                    AtriaDebugLog("ATRIADBG workout_confirm status=upgraded_from_history id=%@ prev_samples=%d new_samples=%d prev_avg_hr=%d new_avg_hr=%d new_strain=%.2f",
                                  already.id,
                                  already.samples,
                                  upgraded.samples,
                                  already.avgHR,
                                  upgraded.avgHR,
                                  upgraded.strain ?? 0)
                    let auditSamples = prepared.points.map {
                        HRSample(t: request.start.addingTimeInterval(max(0, $0.t)), bpm: $0.bpm)
                    }
                    let auditUpgraded = upgraded
                    let auditRest = request.rest
                    let auditMaxHR = request.maxHR
                    let auditSex = request.profile.biologicalSex
                    let auditExclusions = request.excludedIntervals
                    Task.detached(priority: .utility) {
                        Self.persistStrainConfirmationAudit(
                            confirmed: auditUpgraded,
                            samples: auditSamples,
                            rest: auditRest,
                            maxHR: auditMaxHR,
                            biologicalSex: auditSex,
                            excludedIntervals: auditExclusions
                        )
                    }
                }
                settleWorkoutCandidateAfterCanonicalSave(
                    confirmed: upgraded,
                    originalCandidateWindow: request.settlingCandidateWindow
                )
                return upgraded
            }
            let merged = Self.workoutByMergingUserEditsAndStepEvidence(
                already,
                activityLabel: request.activityLabel,
                activityType: request.activityType,
                activitySubtype: request.activitySubtype,
                reviewSource: request.reviewSource,
                reviewCandidateID: request.reviewCandidateID,
                activityCalibrationEvidence: prepared.activityCalibrationEvidence,
                workoutSteps: request.workoutSteps,
                workoutStepsAreEstimated: request.workoutStepsAreEstimated,
                workoutStepsCapturedAt: request.workoutStepsCapturedAt
            )
            if merged != already {
                existing[index] = merged
                guard await saveConfirmedWorkouts(
                    existing,
                    stressContextMutation: .init(previous: already, next: merged)
                ) else { return nil }
            }
            settleWorkoutCandidateAfterCanonicalSave(
                confirmed: merged,
                originalCandidateWindow: request.settlingCandidateWindow
            )
            return merged
        }
        if !request.strengthSets.isEmpty || !request.excludedIntervals.isEmpty {
            try? ActiveSessionJournal.mirrorStrengthState(
                strengthSets: request.strengthSets,
                excludedIntervals: request.excludedIntervals
            )
        }
        existing.append(confirmed)
        guard await saveConfirmedWorkouts(
            existing,
            stressContextMutation: .init(previous: nil, next: confirmed)
        ) else {
            AtriaDebugLog("ATRIADBG workout_confirm status=store_failed id=%@ source=%@ start=%@ end=%@ action=retain_pending_intent",
                          confirmed.id,
                          request.source,
                          isoString(confirmed.start),
                          isoString(confirmed.end))
            return nil
        }
        // The canonical workout has already been atomically saved above.  The
        // audit is diagnostics-only, so sorting/integrating its samples on the
        // main actor can only make the End transition feel frozen; it must not
        // share that interaction frame.
        let auditSamples = prepared.points.map {
            HRSample(t: request.start.addingTimeInterval(max(0, $0.t)), bpm: $0.bpm)
        }
        let auditConfirmed = confirmed
        let auditRest = request.rest
        let auditMaxHR = request.maxHR
        let auditSex = request.profile.biologicalSex
        let auditExclusions = request.excludedIntervals
        Task.detached(priority: .utility) {
            Self.persistStrainConfirmationAudit(
                confirmed: auditConfirmed,
                samples: auditSamples,
                rest: auditRest,
                maxHR: auditMaxHR,
                biologicalSex: auditSex,
                excludedIntervals: auditExclusions
            )
        }
        settleWorkoutCandidateAfterCanonicalSave(
            confirmed: confirmed,
            originalCandidateWindow: request.settlingCandidateWindow
        )
        AtriaDebugLog("ATRIADBG workout_confirm status=confirmed id=%@ source=%@ candidate_source=%@ label=%@ start=%@ end=%@ duration_s=%.0f observed_s=%.0f chunks=%d samples=%d avg_hr=%d peak_hr=%d p95_hr=%d p99_hr=%d threshold_hr=%d stream_coverage_percent=%d confidence=%@ strain=%.2f active_energy_kcal=%.0f active_energy_confidence=%@ metric_promotions=0 healthkit_source=user_confirmed",
                      confirmed.id,
                      request.source,
                      confirmed.source,
                      confirmed.label,
                      isoString(confirmed.start),
                      isoString(confirmed.end),
                      confirmed.duration,
                      confirmed.observedDuration,
                      confirmed.sessions,
                      confirmed.samples,
                      confirmed.avgHR,
                      confirmed.peakHR,
                      confirmed.p95HR,
                      confirmed.p99HR,
                      confirmed.thresholdHR,
                      confirmed.streamCoveragePercent,
                      confirmed.confidence,
                      confirmed.strain ?? 0,
                      confirmed.activeEnergyKilocalories ?? 0,
                      confirmed.activeEnergyConfidence ?? "none")
        DetectionEventLog.append(DetectionEvent(
            kind: "workoutDetected",
            reason: "confirmed",
            detail: "\(confirmed.label), \(Int(confirmed.duration))s",
            windowStart: confirmed.start,
            windowEnd: confirmed.end
        ))
        return confirmed
    }

    private func confirmWorkoutWindow(start requestedStart: Date,
                                      end requestedEnd: Date,
                                      rest: Int,
                                      maxHR: Int,
                                      source: String,
                                      allowManualSave: Bool = false,
                                      preserveUserDeclaredActivityWithoutHeartRate: Bool = false,
                                      activityLabel: String? = nil,
                                      activityType: String? = nil,
                                      activitySubtype: String? = nil,
                                      exerciseNames: [String] = [],
                                      strengthSets: [LoggedSet] = [],
                                      excludedIntervals: [ExcludedInterval] = [],
                                      reviewSource: String? = nil,
                                      reviewCandidateID: String? = nil,
                                      settlingCandidateWindow: (start: Date, end: Date)? = nil,
                                      workoutSteps: Int? = nil,
                                      workoutStepsAreEstimated: Bool? = nil,
                                      workoutStepsCapturedAt: Date? = nil) async -> UserConfirmedWorkout? {
        guard requestedEnd > requestedStart else {
            AtriaDebugLog("ATRIADBG workout_confirm status=learning reason=invalid_window source=%@ start=%@ end=%@ metric_promotions=0",
                  source,
                  isoString(requestedStart),
                  isoString(requestedEnd))
            return nil
        }

        let overlappingEvidence = canonicalSessions(includeActiveJournal: true).filter { session in
            session.end > requestedStart && session.start < requestedEnd
        }
        let overlapping = overlappingEvidence.filter { !$0.points.isEmpty }
        let calibrationEvidence = reviewSource == "detected_activity_review"
            && !(reviewCandidateID?.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ?? true)
            ? Self.activityCalibrationEvidence(sessions: overlappingEvidence,
                                               start: requestedStart,
                                               end: requestedEnd)
            : nil
        var points: [SavedSession.Point] = []
        for session in overlapping {
            for point in session.points {
                let absoluteTime = session.start.addingTimeInterval(max(0, point.t))
                guard absoluteTime >= requestedStart,
                      absoluteTime <= requestedEnd,
                      point.bpm > 0 else { continue }
                points.append(SavedSession.Point(t: absoluteTime.timeIntervalSince(requestedStart),
                                                 bpm: point.bpm))
            }
        }
        points.sort { $0.t < $1.t }

        guard points.count >= 2 else {
            if Self.metadataOnlyWorkoutSaveIsConfirmable(
                isExplicitUserActivity: preserveUserDeclaredActivityWithoutHeartRate,
                requestedDuration: requestedEnd.timeIntervalSince(requestedStart)
            ) {
                return await confirmMetadataOnlyWorkout(
                    start: requestedStart,
                    end: requestedEnd,
                    rest: rest,
                    maxHR: maxHR,
                    source: source,
                    overlappingSessionCount: overlapping.count,
                    activityLabel: activityLabel,
                    activityType: activityType,
                    activitySubtype: activitySubtype,
                    exerciseNames: exerciseNames,
                    strengthSets: strengthSets,
                    excludedIntervals: excludedIntervals,
                    reviewSource: reviewSource,
                    reviewCandidateID: reviewCandidateID,
                    activityCalibrationEvidence: calibrationEvidence,
                    settlingCandidateWindow: settlingCandidateWindow,
                    workoutSteps: workoutSteps,
                    workoutStepsAreEstimated: workoutStepsAreEstimated,
                    workoutStepsCapturedAt: workoutStepsCapturedAt
                )
            }
            AtriaDebugLog("ATRIADBG workout_confirm status=learning reason=window_too_few_samples source=%@ start=%@ end=%@ samples=%d metric_promotions=0",
                  source,
                  isoString(requestedStart),
                  isoString(requestedEnd),
                  points.count)
            return nil
        }

        let window = SavedSession(id: UUID(),
                                  start: requestedStart,
                                  end: requestedEnd,
                                  label: "Live workout",
                                  points: points,
                                  hrv: nil,
                                  eventTimeZoneIdentifier: TimeZone.current.identifier)
        let readiness = window.workoutReadiness(rest: rest, maxHR: maxHR)
        let requestedDuration = requestedEnd.timeIntervalSince(requestedStart)
        // An explicit user Save is authoritative about the activity window, not
        // about sensor continuity. Background BLE reconnects can leave genuine
        // HR in short islands (the 2026-07-11 gym pull had 60 real samples but
        // only 2.84% coverage). Preserve the workout whenever at least two real
        // samples exist; coverage and metrics remain measured and visibly partial.
        let manualConfirmable = allowManualSave
            && Self.explicitWorkoutSaveIsConfirmable(sampleCount: points.count,
                                                      requestedDuration: requestedDuration)
        let confirmable = (readiness.ready
            || (readiness.observedDuration >= 15 * 60
                && readiness.streamCoveragePercent >= 60
                && (readiness.nearMiss || readiness.strengthCandidate))
        ) || manualConfirmable
        guard confirmable else {
            AtriaDebugLog("ATRIADBG workout_confirm status=learning reason=window_candidate_too_weak source=%@ observed_s=%.0f stream_coverage_percent=%d ready=%d near_miss=%d strength_candidate=%d primary_blocker=%@ metric_promotions=0",
                  source,
                  readiness.observedDuration,
                  readiness.streamCoveragePercent,
                  readiness.ready ? 1 : 0,
                  readiness.nearMiss ? 1 : 0,
                  readiness.strengthCandidate ? 1 : 0,
                  readiness.primaryBlocker)
            return nil
        }

        var existing = cachedConfirmedWorkouts
        let workoutSource = "live_workout_window"
        let id = confirmedWorkoutID(start: requestedStart, end: requestedEnd, source: workoutSource)
        if let index = existing.firstIndex(where: { $0.id == id }) {
            let already = existing[index]
            let merged = Self.workoutByMergingUserEditsAndStepEvidence(
                already,
                activityLabel: activityLabel,
                activityType: activityType,
                activitySubtype: activitySubtype,
                reviewSource: reviewSource,
                reviewCandidateID: reviewCandidateID,
                activityCalibrationEvidence: calibrationEvidence,
                workoutSteps: workoutSteps,
                workoutStepsAreEstimated: workoutStepsAreEstimated,
                workoutStepsCapturedAt: workoutStepsCapturedAt
            )
            if merged != already {
                existing[index] = merged
                guard await saveConfirmedWorkouts(
                    existing,
                    stressContextMutation: .init(
                        previous: already,
                        next: merged
                    )
                ) else { return nil }
            }
            settleWorkoutCandidateAfterCanonicalSave(
                confirmed: merged,
                originalCandidateWindow: settlingCandidateWindow
            )
            AtriaDebugLog("ATRIADBG workout_confirm status=already_confirmed id=%@ source=%@ candidate_source=%@ start=%@ end=%@ confidence=%@ metric_promotions=0 auto_gate_e_unchanged=1",
                  merged.id,
                  source,
                  merged.source,
                  isoString(merged.start),
                  isoString(merged.end),
                  merged.confidence)
            return merged
        }

        let confidence = readiness.ready ? "live_window_user_confirmed" :
            (readiness.nearMiss ? "live_window_near_miss" :
                (manualConfirmable
                    ? (readiness.streamCoveragePercent < 5
                        ? "live_window_manual_sparse_hr"
                        : "live_window_manual_confirmed")
                    : "live_window_candidate"))
        let enriched = confirmedWorkoutMetrics(start: requestedStart,
                                               end: requestedEnd,
                                               rest: rest,
                                               maxHR: maxHR,
                                               biologicalSex: profile.biologicalSex,
                                               excludedIntervals: excludedIntervals)
        let activityTypeValue = activityType?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let activityLabelValue = activityLabel?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let activitySubtypeValue = activitySubtype?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let reviewSourceValue = reviewSource?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let reviewCandidateValue = reviewCandidateID?
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        let cleanedActivityType = activityTypeValue.isEmpty ? nil : activityTypeValue
        let cleanedActivityLabel = activityLabelValue.isEmpty ? nil : activityLabelValue
        let cleanedActivitySubtype = activitySubtypeValue.isEmpty ? nil : activitySubtypeValue
        let cleanedExercises = exerciseNames
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
        let cleanedReviewSource = reviewSourceValue.isEmpty ? nil : reviewSourceValue
        let cleanedReviewCandidateID = reviewCandidateValue.isEmpty ? nil : reviewCandidateValue
        if !strengthSets.isEmpty || !excludedIntervals.isEmpty {
            try? ActiveSessionJournal.mirrorStrengthState(strengthSets: strengthSets,
                                                          excludedIntervals: excludedIntervals)
        }
        let confirmed = UserConfirmedWorkout(id: id,
                                             createdAt: Date(),
                                             start: requestedStart,
                                             end: requestedEnd,
                                             label: cleanedActivityLabel ?? cleanedActivityType ?? "Live workout",
                                             source: workoutSource,
                                             confidence: confidence,
                                             sessions: overlapping.count,
                                             samples: points.count,
                                             avgHR: readiness.avgHR,
                                             peakHR: readiness.peakHR,
                                             p95HR: readiness.p95HR,
                                             p99HR: readiness.p99HR,
                                             thresholdHR: readiness.thresholdHR,
                                             streamCoveragePercent: readiness.streamCoveragePercent,
                                             observedDuration: readiness.observedDuration,
                                             reason: readiness.ready ? readiness.reason : readiness.primaryBlocker,
                                             activityType: cleanedActivityType,
                                             activitySubtype: cleanedActivitySubtype,
                                             exerciseNames: cleanedExercises.isEmpty ? nil : cleanedExercises,
                                             strengthSets: strengthSets.isEmpty ? nil : strengthSets,
                                             muscularLoadReceipt: AtriaStrengthLog.muscularLoadReceipt(for: strengthSets),
                                             excludedIntervals: excludedIntervals.isEmpty ? nil : excludedIntervals,
                                             reviewSource: cleanedReviewSource,
                                             reviewCandidateID: cleanedReviewCandidateID,
                                             activityCalibrationEvidence: calibrationEvidence,
                                             strain: enriched.strain,
                                             strainCalibrationVersion: enriched.strain == nil
                                                ? nil
                                                : AtriaAnalytics.Strain.displayCalibrationVersion,
                                             activeEnergyKilocalories: enriched.activeEnergyKilocalories,
                                             activeEnergyConfidence: enriched.activeEnergyConfidence,
                                             zoneSeconds: enriched.zoneSeconds,
                                             eventTimeZoneIdentifier: TimeZone.current.identifier,
                                             workoutSteps: workoutSteps.map { max(0, $0) },
                                             workoutStepsAreEstimated: workoutSteps == nil ? nil : (workoutStepsAreEstimated ?? true),
                                             workoutStepsCapturedAt: workoutSteps == nil ? nil : workoutStepsCapturedAt)
        existing.append(confirmed)
        guard await saveConfirmedWorkouts(
            existing,
            stressContextMutation: .init(previous: nil, next: confirmed)
        ) else {
            AtriaDebugLog("ATRIADBG workout_confirm status=store_failed id=%@ source=%@ start=%@ end=%@ action=retain_pending_intent",
                          confirmed.id,
                          source,
                          isoString(confirmed.start),
                          isoString(confirmed.end))
            return nil
        }
        Self.persistStrainConfirmationAudit(
            confirmed: confirmed,
            samples: points.map {
                HRSample(t: requestedStart.addingTimeInterval(max(0, $0.t)), bpm: $0.bpm)
            },
            rest: rest,
            maxHR: maxHR,
            biologicalSex: profile.biologicalSex,
            excludedIntervals: excludedIntervals
        )
        settleWorkoutCandidateAfterCanonicalSave(
            confirmed: confirmed,
            originalCandidateWindow: settlingCandidateWindow
        )
        AtriaDebugLog("ATRIADBG workout_confirm status=confirmed id=%@ source=%@ candidate_source=%@ label=%@ start=%@ end=%@ duration_s=%.0f observed_s=%.0f chunks=%d samples=%d avg_hr=%d peak_hr=%d p95_hr=%d p99_hr=%d threshold_hr=%d stream_coverage_percent=%d confidence=%@ strain=%.2f active_energy_kcal=%.0f active_energy_confidence=%@ zone_rest_s=%.0f zone_warmup_s=%.0f zone_fat_burn_s=%.0f zone_aerobic_s=%.0f zone_anaerobic_s=%.0f zone_max_s=%.0f auto_gate_e_unchanged=1 healthkit_source=user_confirmed",
              confirmed.id,
              source,
              confirmed.source,
              confirmed.label,
              isoString(confirmed.start),
              isoString(confirmed.end),
              confirmed.duration,
              confirmed.observedDuration,
              confirmed.sessions,
              confirmed.samples,
              confirmed.avgHR,
              confirmed.peakHR,
              confirmed.p95HR,
              confirmed.p99HR,
              confirmed.thresholdHR,
              confirmed.streamCoveragePercent,
              confirmed.confidence,
              confirmed.strain ?? 0,
              confirmed.activeEnergyKilocalories ?? 0,
              confirmed.activeEnergyConfidence ?? "none",
              confirmed.zoneSeconds?["rest"] ?? 0,
              confirmed.zoneSeconds?["warmup"] ?? 0,
              confirmed.zoneSeconds?["fatBurn"] ?? 0,
              confirmed.zoneSeconds?["aerobic"] ?? 0,
              confirmed.zoneSeconds?["anaerobic"] ?? 0,
              confirmed.zoneSeconds?["max"] ?? 0)
        DetectionEventLog.append(DetectionEvent(kind: "workoutDetected",
                                                 reason: "confirmed",
                                                 detail: "\(confirmed.label), \(Int(confirmed.duration))s",
                                                 windowStart: confirmed.start,
                                                 windowEnd: confirmed.end))
        return confirmed
    }

    /// Preserve an activity the user explicitly started or added even when a
    /// BLE failure left no usable heart-rate samples. This stores only identity,
    /// type and time; every sensor-derived field remains empty/zero so Atria
    /// never turns an app transport failure into invented HR, strain or energy.
    private func confirmMetadataOnlyWorkout(
        start: Date,
        end: Date,
        rest: Int,
        maxHR: Int,
        source: String,
        overlappingSessionCount: Int,
        activityLabel: String?,
        activityType: String?,
        activitySubtype: String?,
        exerciseNames: [String],
        strengthSets: [LoggedSet],
        excludedIntervals: [ExcludedInterval],
        reviewSource: String?,
        reviewCandidateID: String?,
        activityCalibrationEvidence: AtriaActivityCalibrationEvidence?,
        settlingCandidateWindow: (start: Date, end: Date)?,
        workoutSteps: Int?,
        workoutStepsAreEstimated: Bool?,
        workoutStepsCapturedAt: Date?
    ) async -> UserConfirmedWorkout? {
        let workoutSource = "live_workout_window"
        let id = confirmedWorkoutID(start: start, end: end, source: workoutSource)
        if let index = cachedConfirmedWorkouts.firstIndex(where: { $0.id == id }) {
            let existing = cachedConfirmedWorkouts[index]
            let merged = Self.workoutByMergingUserEditsAndStepEvidence(
                existing,
                activityLabel: activityLabel,
                activityType: activityType,
                activitySubtype: activitySubtype,
                reviewSource: reviewSource,
                reviewCandidateID: reviewCandidateID,
                activityCalibrationEvidence: activityCalibrationEvidence,
                workoutSteps: workoutSteps,
                workoutStepsAreEstimated: workoutStepsAreEstimated,
                workoutStepsCapturedAt: workoutStepsCapturedAt
            )
            if merged != existing {
                var workouts = cachedConfirmedWorkouts
                workouts[index] = merged
                guard await saveConfirmedWorkouts(
                    workouts,
                    stressContextMutation: .init(
                        previous: existing,
                        next: merged
                    )
                ) else { return nil }
            }
            settleWorkoutCandidateAfterCanonicalSave(
                confirmed: merged,
                originalCandidateWindow: settlingCandidateWindow
            )
            return merged
        }

        let cleanedType = activityType?
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanedLabel = activityLabel?
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanedSubtype = activitySubtype?
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanedExercises = exerciseNames
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
        let cleanedReviewSource = reviewSource?
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let cleanedReviewCandidateID = reviewCandidateID?
            .trimmingCharacters(in: .whitespacesAndNewlines)
        let type = cleanedType.flatMap { $0.isEmpty ? nil : $0 }
        let label = cleanedLabel.flatMap { $0.isEmpty ? nil : $0 }
        let subtype = cleanedSubtype.flatMap { $0.isEmpty ? nil : $0 }
        let review = cleanedReviewSource.flatMap { $0.isEmpty ? nil : $0 }
        let candidateID = cleanedReviewCandidateID.flatMap { $0.isEmpty ? nil : $0 }

        if !strengthSets.isEmpty || !excludedIntervals.isEmpty {
            try? ActiveSessionJournal.mirrorStrengthState(
                strengthSets: strengthSets,
                excludedIntervals: excludedIntervals
            )
        }

        let confirmed = UserConfirmedWorkout(
            id: id,
            createdAt: Date(),
            start: start,
            end: end,
            label: label ?? type ?? "Workout",
            source: workoutSource,
            confidence: "user_confirmed_no_hr",
            sessions: overlappingSessionCount,
            samples: 0,
            avgHR: 0,
            peakHR: 0,
            p95HR: 0,
            p99HR: 0,
            thresholdHR: SavedSession.workoutElevatedThreshold(rest: rest, maxHR: maxHR),
            streamCoveragePercent: 0,
            observedDuration: 0,
            reason: "no_strap_hr_samples",
            activityType: type,
            activitySubtype: subtype,
            exerciseNames: cleanedExercises.isEmpty ? nil : cleanedExercises,
            strengthSets: strengthSets.isEmpty ? nil : strengthSets,
            muscularLoadReceipt: AtriaStrengthLog.muscularLoadReceipt(for: strengthSets),
            excludedIntervals: excludedIntervals.isEmpty ? nil : excludedIntervals,
            reviewSource: review,
            reviewCandidateID: candidateID,
            activityCalibrationEvidence: activityCalibrationEvidence,
            strain: nil,
            activeEnergyKilocalories: nil,
            activeEnergyConfidence: nil,
            zoneSeconds: nil,
            eventTimeZoneIdentifier: TimeZone.current.identifier,
            workoutSteps: workoutSteps.map { max(0, $0) },
            workoutStepsAreEstimated: workoutSteps == nil ? nil : (workoutStepsAreEstimated ?? true),
            workoutStepsCapturedAt: workoutSteps == nil ? nil : workoutStepsCapturedAt
        )
        var workouts = cachedConfirmedWorkouts
        workouts.append(confirmed)
        guard await saveConfirmedWorkouts(
            workouts,
            stressContextMutation: .init(previous: nil, next: confirmed)
        ) else {
            AtriaDebugLog("ATRIADBG workout_confirm status=store_failed reason=metadata_only source=%@ id=%@",
                          source,
                          id)
            return nil
        }
        settleWorkoutCandidateAfterCanonicalSave(
            confirmed: confirmed,
            originalCandidateWindow: settlingCandidateWindow
        )
        AtriaDebugLog("ATRIADBG workout_confirm status=confirmed reason=metadata_only source=%@ id=%@ activity=%@ duration_s=%.0f metric_promotions=0",
                      source,
                      id,
                      type ?? "Workout",
                      end.timeIntervalSince(start))
        DetectionEventLog.append(DetectionEvent(kind: "workoutDetected",
                                                 reason: "user_confirmed_no_hr",
                                                 detail: "\(type ?? "Workout"), \(Int(end.timeIntervalSince(start)))s",
                                                 windowStart: start,
                                                 windowEnd: end))
        return confirmed
    }

    /// Completion recovery or a repeated review can arrive after the physiological
    /// workout record. Merge explicit user metadata and motion evidence so Save
    /// remains one transaction and an evidence-free retry never erases a count.
    nonisolated private static func workoutByMergingUserEditsAndStepEvidence(
        _ workout: UserConfirmedWorkout,
        activityLabel: String?,
        activityType: String?,
        activitySubtype: String?,
        reviewSource: String?,
        reviewCandidateID: String?,
        activityCalibrationEvidence: AtriaActivityCalibrationEvidence?,
        workoutSteps: Int?,
        workoutStepsAreEstimated: Bool?,
        workoutStepsCapturedAt: Date?
    ) -> UserConfirmedWorkout {
        let cleanedLabel = activityLabel?.trimmingCharacters(in: .whitespacesAndNewlines)
        var merged = UserConfirmedWorkout(
            id: workout.id,
            createdAt: workout.createdAt,
            start: workout.start,
            end: workout.end,
            label: cleanedLabel.flatMap { $0.isEmpty ? nil : $0 } ?? workout.label,
            source: workout.source,
            confidence: workout.confidence,
            sessions: workout.sessions,
            samples: workout.samples,
            avgHR: workout.avgHR,
            peakHR: workout.peakHR,
            p95HR: workout.p95HR,
            p99HR: workout.p99HR,
            thresholdHR: workout.thresholdHR,
            streamCoveragePercent: workout.streamCoveragePercent,
            observedDuration: workout.observedDuration,
            reason: workout.reason,
            eventTimeZoneIdentifier: workout.eventTimeZoneIdentifier
        )
        merged.activityType = workout.activityType
        merged.activitySubtype = workout.activitySubtype
        merged.exerciseNames = workout.exerciseNames
        merged.strengthSets = workout.strengthSets
        merged.muscularLoadReceipt = workout.muscularLoadReceipt
        merged.excludedIntervals = workout.excludedIntervals
        merged.reviewSource = workout.reviewSource
        merged.reviewCandidateID = workout.reviewCandidateID
        merged.activityCalibrationEvidence = workout.activityCalibrationEvidence
        merged.strain = workout.strain
        merged.activeEnergyKilocalories = workout.activeEnergyKilocalories
        merged.activeEnergyConfidence = workout.activeEnergyConfidence
        merged.zoneSeconds = workout.zoneSeconds
        // GAP-03: the frozen per-workout zone boundaries are part of the
        // completed record's identity — a step-evidence merge or type edit
        // must never drop them, or a later profile change silently rewrites
        // the workout's zone ranges.
        merged.zoneBoundaries = workout.zoneBoundaries
        merged.workoutSteps = workout.workoutSteps
        merged.workoutStepsAreEstimated = workout.workoutStepsAreEstimated
        merged.workoutStepsCapturedAt = workout.workoutStepsCapturedAt
        if let cleanedType = activityType?.trimmingCharacters(in: .whitespacesAndNewlines),
           !cleanedType.isEmpty {
            merged.activityType = cleanedType
            merged.activitySubtype = AtriaWorkoutActivityType(rawValue: cleanedType)?
                .normalizedSubtype(activitySubtype)
        }
        if let cleanedReviewSource = reviewSource?.trimmingCharacters(in: .whitespacesAndNewlines),
           !cleanedReviewSource.isEmpty {
            merged.reviewSource = cleanedReviewSource
        }
        if let cleanedCandidateID = reviewCandidateID?.trimmingCharacters(in: .whitespacesAndNewlines),
           !cleanedCandidateID.isEmpty {
            merged.reviewCandidateID = cleanedCandidateID
        }
        if let activityCalibrationEvidence {
            merged.activityCalibrationEvidence = activityCalibrationEvidence
        }
        if let workoutSteps {
            merged.workoutSteps = max(0, workoutSteps)
            merged.workoutStepsAreEstimated = workoutStepsAreEstimated ?? true
            merged.workoutStepsCapturedAt = workoutStepsCapturedAt
        }
        return merged
    }

    /// #1 auto-upgrade (2026-08-22): rebuild a previously weaker / metadata-only
    /// workout in place from a stronger recompute once its window's HR/motion has
    /// drained (the user asked that a reconnect "flush the missing portion and
    /// reliably recalculate the readings"). Identity and every user-edited field are
    /// preserved from `existing`; only the HR / effort / strain metrics come from
    /// `recomputed`. The caller guards on `recomputed.samples > existing.samples`,
    /// so this can only ever UPGRADE — it never regresses a good record, and a later
    /// equal-sample pass produces an identical struct (idempotent, no churn).
    nonisolated static func workoutByUpgradingHeartRateMetrics(
        existing: UserConfirmedWorkout,
        recomputed: UserConfirmedWorkout
    ) -> UserConfirmedWorkout {
        var upgraded = UserConfirmedWorkout(
            id: existing.id,
            createdAt: existing.createdAt,
            start: existing.start,
            end: existing.end,
            label: existing.label,
            source: existing.source,
            confidence: recomputed.confidence,
            sessions: recomputed.sessions,
            samples: recomputed.samples,
            avgHR: recomputed.avgHR,
            peakHR: recomputed.peakHR,
            p95HR: recomputed.p95HR,
            p99HR: recomputed.p99HR,
            thresholdHR: recomputed.thresholdHR,
            streamCoveragePercent: recomputed.streamCoveragePercent,
            observedDuration: recomputed.observedDuration,
            reason: recomputed.reason,
            eventTimeZoneIdentifier: existing.eventTimeZoneIdentifier
        )
        // User-edited / identity fields survive untouched.
        upgraded.activityType = existing.activityType
        upgraded.activitySubtype = existing.activitySubtype
        upgraded.exerciseNames = existing.exerciseNames
        upgraded.strengthSets = existing.strengthSets
        upgraded.muscularLoadReceipt = existing.muscularLoadReceipt
        upgraded.excludedIntervals = existing.excludedIntervals
        upgraded.reviewSource = existing.reviewSource
        upgraded.reviewCandidateID = existing.reviewCandidateID
        // Freshly computed effort-derived metrics replace the weaker placeholders.
        upgraded.activityCalibrationEvidence =
            recomputed.activityCalibrationEvidence ?? existing.activityCalibrationEvidence
        upgraded.strain = recomputed.strain
        upgraded.strainCalibrationVersion = recomputed.strainCalibrationVersion
        upgraded.activeEnergyKilocalories = recomputed.activeEnergyKilocalories
        upgraded.activeEnergyConfidence = recomputed.activeEnergyConfidence
        upgraded.zoneSeconds = recomputed.zoneSeconds
        upgraded.zoneBoundaries = recomputed.zoneBoundaries
        // Steps: keep the user's / earlier-captured value when present; otherwise
        // adopt whatever the recompute produced for the window.
        if existing.workoutSteps != nil {
            upgraded.workoutSteps = existing.workoutSteps
            upgraded.workoutStepsAreEstimated = existing.workoutStepsAreEstimated
            upgraded.workoutStepsCapturedAt = existing.workoutStepsCapturedAt
        } else {
            upgraded.workoutSteps = recomputed.workoutSteps
            upgraded.workoutStepsAreEstimated = recomputed.workoutStepsAreEstimated
            upgraded.workoutStepsCapturedAt = recomputed.workoutStepsCapturedAt
        }
        return upgraded
    }

    /// The trimmed workout start (2026-07-07, user-reported early boundary):
    /// the first sustained-elevated onset within [start, end], from the REAL
    /// overlapping HR samples — so the getting-ready/walking-out lead-in is
    /// not swept into the workout. Fails closed to nil (caller keeps the
    /// untrimmed start) unless the trim removes >= 60s AND still leaves >= 5
    /// min of workout, so a ready workout stays ready and no real effort is
    /// dropped. Identity/readiness are computed from the untrimmed window by
    /// the caller; this only sharpens the displayed start.
    private func sustainedWorkoutOnsetStart(start: Date, end: Date, rest: Int, maxHR: Int) -> Date? {
        // includeActiveJournal: true to match the save gate (2026-07-08 audit):
        // confirmWorkoutWindow admits a workout on active-journal (live) HR, so
        // the onset/stats/strain must see the SAME samples, not exclude them.
        Self.sustainedWorkoutOnsetStart(in: canonicalSessions(includeActiveJournal: true),
                                       start: start,
                                       end: end,
                                       rest: rest,
                                       maxHR: maxHR)
    }

    private nonisolated static func sustainedWorkoutOnsetStart(in sessions: [SavedSession],
                                                               start: Date,
                                                               end: Date,
                                                               rest: Int,
                                                               maxHR: Int) -> Date? {
        let overlapping = sessions.filter { session in
            session.end > start && session.start < end && !session.points.isEmpty
        }
        guard !overlapping.isEmpty else { return nil }
        var samples: [(t: Date, bpm: Int)] = []
        for session in overlapping {
            for point in session.points where point.bpm > 0 {
                let t = session.start.addingTimeInterval(max(0, point.t))
                if t >= start, t <= end { samples.append((t, point.bpm)) }
            }
        }
        samples.sort { $0.t < $1.t }
        guard let onset = AtriaWorkoutOnset.firstSustainedElevatedOnset(samples: samples, rest: rest, maxHR: maxHR),
              onset > start.addingTimeInterval(60),
              end.timeIntervalSince(onset) >= 5 * 60
        else { return nil }
        return onset
    }

    /// Short honest recovery tail kept after the last sustained elevated bout
    /// when bounding a candidate's displayed end (see below).
    nonisolated static let workoutReviewEndRecoveryTail: TimeInterval = 10 * 60

    private func sustainedWorkoutEndBound(start: Date, end: Date, rest: Int, maxHR: Int) -> Date? {
        // includeActiveJournal: true — same sample set as the save gate and
        // the onset trim (audit #9).
        Self.sustainedWorkoutEndBound(in: canonicalSessions(includeActiveJournal: true),
                                      start: start,
                                      end: end,
                                      rest: rest,
                                      maxHR: maxHR)
    }

    /// End-side counterpart of `sustainedWorkoutOnsetStart` (physical case
    /// 2026-07-31): the replay window's end is a session/aggregate boundary,
    /// so a real 75-minute lift followed by an ordinary mildly-elevated
    /// evening surfaced as one 21:38->02:32 (4h53m) candidate that only
    /// closed at sleep-onset HR decay. The displayed end is bounded to the
    /// end of the LAST sustained elevated bout plus a short recovery tail.
    /// Identity stays on the untrimmed window; readiness was already decided
    /// from the untrimmed evidence. Fails closed (nil = keep the untrimmed
    /// end) when there is no honest sustained bout, when the trim would not
    /// be material (>60 s), or when it would leave less than five minutes of
    /// displayed effort.
    private nonisolated static func sustainedWorkoutEndBound(in sessions: [SavedSession],
                                                             start: Date,
                                                             end: Date,
                                                             rest: Int,
                                                             maxHR: Int) -> Date? {
        let overlapping = sessions.filter { session in
            session.end > start && session.start < end && !session.points.isEmpty
        }
        guard !overlapping.isEmpty else { return nil }
        var samples: [(t: Date, bpm: Int)] = []
        for session in overlapping {
            for point in session.points where point.bpm > 0 {
                let t = session.start.addingTimeInterval(max(0, point.t))
                if t >= start, t <= end { samples.append((t, point.bpm)) }
            }
        }
        samples.sort { $0.t < $1.t }
        guard let boutEnd = AtriaWorkoutOnset.lastSustainedElevatedBoutEnd(samples: samples,
                                                                           rest: rest,
                                                                           maxHR: maxHR) else { return nil }
        let bound = boutEnd.addingTimeInterval(workoutReviewEndRecoveryTail)
        guard bound < end.addingTimeInterval(-60),
              bound.timeIntervalSince(start) >= 5 * 60
        else { return nil }
        return bound
    }

    /// Displayed HR stats recomputed over an (onset-trimmed) window from the
    /// REAL samples, so avgHR/coverage/observed/percentiles match the trimmed
    /// start + duration + strain instead of the old untrimmed summary values
    /// (honesty rule: a 39-min effort must not show an average diluted by the
    /// trimmed-off getting-ready lead-in). nil if the window has no samples.
    private func workoutWindowHRStats(start: Date, end: Date)
        -> (avgHR: Int, peakHR: Int, p95HR: Int, p99HR: Int,
            observedDuration: TimeInterval, streamCoveragePercent: Int, samples: Int)? {
        // includeActiveJournal: true — same sample set as the save gate (audit #9).
        Self.workoutWindowHRStats(in: canonicalSessions(includeActiveJournal: true),
                                  start: start,
                                  end: end)
    }

    private nonisolated static func workoutWindowHRStats(in sessions: [SavedSession],
                                                         start: Date,
                                                         end: Date)
        -> (avgHR: Int, peakHR: Int, p95HR: Int, p99HR: Int,
            observedDuration: TimeInterval, streamCoveragePercent: Int, samples: Int)? {
        let overlapping = sessions.filter { session in
            session.end > start && session.start < end && !session.points.isEmpty
        }
        guard !overlapping.isEmpty else { return nil }
        var points: [(t: Date, bpm: Int)] = []
        for session in overlapping {
            for point in session.points where point.bpm > 0 {
                let t = session.start.addingTimeInterval(max(0, point.t))
                if t >= start, t <= end { points.append((t, point.bpm)) }
            }
        }
        guard points.count > 1 else { return nil }
        points.sort { $0.t < $1.t }
        return AtriaWorkoutOnset.windowStats(samples: points,
                                             windowSeconds: end.timeIntervalSince(start),
                                             continuityGapLimit: SavedSession.workoutContinuityGapLimit)
    }

    private func confirmedWorkoutMetrics(start: Date,
                                         end: Date,
                                         rest: Int,
                                         maxHR: Int,
                                         biologicalSex: AthleteProfile.BiologicalSex,
                                         excludedIntervals: [ExcludedInterval] = []) -> (strain: Double?,
                                                        activeEnergyKilocalories: Double?,
                                                        activeEnergyConfidence: String?,
                                                        zoneSeconds: [String: TimeInterval]?) {
        // includeActiveJournal: true — same sample set as the save gate (audit #9).
        let overlapping = canonicalSessions(includeActiveJournal: true).filter { session in
            session.end > start && session.start < end && !session.points.isEmpty
        }
        guard !overlapping.isEmpty else { return (nil, nil, nil, nil) }

        var samples: [HRSample] = []
        for session in overlapping {
            samples.append(contentsOf: session.points.map { point in
                HRSample(t: session.start.addingTimeInterval(max(0, point.t)),
                         bpm: point.bpm)
            }.filter { sample in
                sample.t >= start && sample.t <= end
            })
        }
        samples.sort { $0.t < $1.t }
        let segments = AtriaAnalytics.Strain.contiguousSegments(samples,
                                                                excluding: excludedIntervals)
        guard segments.contains(where: { $0.count > 1 }) else { return (nil, nil, nil, nil) }

        let trimp = Self.confirmedWorkoutTRIMP(segments: segments,
                                               start: start,
                                               rest: rest,
                                               maxHR: maxHR,
                                               biologicalSex: biologicalSex)
        let zoneSummary = segments.reduce(AtriaAnalytics.Strain.MaxHeartRateZoneSeconds.empty) { total, samples in
            total + AtriaAnalytics.Strain.maxHeartRateZoneSeconds(samples.map {
                (t: $0.t.timeIntervalSince(start), bpm: $0.bpm)
            }, maxHR: maxHR, restingHR: rest)
        }
        let energyParts = segments.compactMap { samples in
            Metrics.activeCalories(samples, rest: rest, profile: profile)
        }
        let activeEnergy = energyParts.isEmpty ? nil : energyParts.reduce(0, +)
        return (Metrics.strain(fromTRIMP: trimp),
                activeEnergy,
                activeEnergy == nil ? (profile.hasEnergyProfile ? nil : "needs_profile") : "estimate",
                zoneSummary.isEmpty ? nil : zoneSummary.storage)
    }

    /// Canonical load calculation used while materializing a confirmed workout.
    /// Sex is deliberately explicit: recovered/archive HR and a SavedSession
    /// containing the same evidence must never silently select different
    /// Banister coefficients.
    nonisolated static func confirmedWorkoutTRIMP(
        segments: [[HRSample]],
        start: Date,
        rest: Int,
        maxHR: Int,
        biologicalSex: AthleteProfile.BiologicalSex
    ) -> Double {
        segments.reduce(0.0) { total, segment in
            total + Metrics.trimp(segment.map { (t: $0.t.timeIntervalSince(start), bpm: $0.bpm) },
                                  rest: rest,
                                  max: maxHR,
                                  sex: biologicalSex)
        }
    }

    /// Migrates only a persisted detail score whose original workout window can
    /// still be re-integrated from real strap HR.  A card saved without enough
    /// HR remains exactly as it was: the migration never derives strain from
    /// duration, activity type, steps, or a later all-day average.
    ///
    /// The per-record version makes this idempotent and intentionally leaves
    /// unavailable legacy windows eligible for a later pass if their raw source
    /// becomes resident or is recovered from the archive.
    nonisolated static func rescoredConfirmedWorkoutsForCurrentStrainCalibration(
        _ workouts: [UserConfirmedWorkout],
        sourceSessions: [SavedSession],
        rest: Int,
        maxHR: Int,
        biologicalSex: AthleteProfile.BiologicalSex
    ) -> [UserConfirmedWorkout] {
        guard maxHR > rest else { return workouts }
        let targetVersion = AtriaAnalytics.Strain.displayCalibrationVersion
        let canonical = makeCanonicalSessions(from: sourceSessions)
        guard !canonical.isEmpty else { return workouts }

        return workouts.map { workout in
            guard workout.strain != nil,
                  workout.strainCalibrationVersion != targetVersion,
                  workout.end > workout.start else {
                return workout
            }
            var samples: [HRSample] = []
            for session in canonical where session.end > workout.start && session.start < workout.end {
                for point in session.points where point.bpm > 0 {
                    let timestamp = session.start.addingTimeInterval(max(0, point.t))
                    guard timestamp >= workout.start, timestamp <= workout.end else { continue }
                    samples.append(HRSample(t: timestamp, bpm: point.bpm))
                }
            }
            samples.sort { $0.t < $1.t }
            let segments = AtriaAnalytics.Strain.contiguousSegments(
                samples,
                excluding: workout.excludedIntervals
            )
            guard segments.contains(where: { $0.count > 1 }) else { return workout }

            let trimp = confirmedWorkoutTRIMP(
                segments: segments,
                start: workout.start,
                rest: rest,
                maxHR: maxHR,
                biologicalSex: biologicalSex
            )
            guard trimp.isFinite, trimp > 0 else { return workout }
            let score = Metrics.strain(fromTRIMP: trimp)
            guard score.isFinite, (0...21).contains(score) else { return workout }

            var rescored = workout
            rescored.strain = score
            rescored.strainCalibrationVersion = targetVersion
            return rescored
        }
    }

    /// Captures the measured inputs used by the already-confirmed strain
    /// result. This audit is deliberately post-save and diagnostics-only: it
    /// never recalculates, replaces, or gates the workout's stored score.
    private nonisolated static func persistStrainConfirmationAudit(
        confirmed: UserConfirmedWorkout,
        samples: [HRSample],
        rest: Int,
        maxHR: Int,
        biologicalSex: AthleteProfile.BiologicalSex,
        excludedIntervals: [ExcludedInterval]
    ) {
        let segments = AtriaAnalytics.Strain.contiguousSegments(
            samples.sorted { $0.t < $1.t },
            excluding: excludedIntervals
        )
        let rawTRIMP = confirmedWorkoutTRIMP(
            segments: segments,
            start: confirmed.start,
            rest: rest,
            maxHR: maxHR,
            biologicalSex: biologicalSex
        )
        let gapAudit = segments.reduce(AtriaAnalytics.Strain.MaxHeartRateZoneSeconds.empty) {
            total, segment in
            total + AtriaAnalytics.Strain.maxHeartRateZoneSeconds(
                segment.map { (t: $0.t.timeIntervalSince(confirmed.start), bpm: $0.bpm) },
                maxHR: maxHR,
                restingHR: rest
            )
        }
        let observed = gapAudit.storage.values.reduce(0, +)
        let dropped = gapAudit.droppedGapSeconds
        let result = confirmed.strain == nil ? "no_strain_from_available_hr" : "score_persisted"
        let record = AtriaStrainConfirmationAuditRecord(
            workoutID: confirmed.id,
            recordedAt: Date(),
            rawTRIMP: rawTRIMP,
            integratedObservedSeconds: observed,
            droppedGapSeconds: dropped,
            restingHR: rest,
            maxHR: maxHR,
            strainScore: confirmed.strain,
            result: result,
            coveragePercent: confirmed.streamCoveragePercent
        )
        AtriaStrainConfirmationAuditLog.append(record)
        AtriaDebugLog("ATRIADBG strain_confirmation_audit id=%@ raw_trimp=%.4f integrated_observed_s=%.0f dropped_gap_s=%.0f rest_hr=%d max_hr=%d strain=%.2f result=%@ coverage_percent=%d",
                      record.workoutID,
                      record.rawTRIMP,
                      record.integratedObservedSeconds,
                      record.droppedGapSeconds,
                      record.restingHR,
                      record.maxHR,
                      record.strainScore ?? 0,
                      record.result,
                      record.coveragePercent)
    }

    private static func readConfirmedWorkouts() -> [UserConfirmedWorkout] {
        let fileURL = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
            .appendingPathComponent(ConfirmedWorkoutDefaults.fileName)
        let data = (try? Data(contentsOf: fileURL))
            ?? UserDefaults.standard.data(forKey: ConfirmedWorkoutDefaults.key)
        guard let data,
              let decoded = try? JSONDecoder().decode([UserConfirmedWorkout].self, from: data) else {
            return []
        }
        return decoded.sorted { $0.start > $1.start }
    }

    /// The strain display curve can be calibrated without changing the raw
    /// Banister/TRIMP evidence. Re-score only records with an exact persisted
    /// confirmation audit; summaries or current live HR are never substituted
    /// for missing historical evidence.
    private func rescorePersistedConfirmedWorkoutStrainIfVerified() async {
        let result = AtriaPersistedWorkoutStrainRescorer.rescore(
            workouts: cachedConfirmedWorkouts,
            audits: AtriaStrainConfirmationAuditLog.load()
        )
        guard result.changed else { return }
        guard await saveConfirmedWorkouts(result.workouts, deferDerivedPublication: true) else {
            AtriaDebugLog("ATRIADBG confirmed_workout_strain_rescore status=store_failed verified=%d",
                          result.rescoredWorkoutIDs.count)
            return
        }
        AtriaDebugLog("ATRIADBG confirmed_workout_strain_rescore status=applied verified=%d",
                      result.rescoredWorkoutIDs.count)
    }

    nonisolated static func rebasedConfirmedWorkouts(
        base: [UserConfirmedWorkout],
        desired: [UserConfirmedWorkout],
        current: [UserConfirmedWorkout]
    ) -> [UserConfirmedWorkout] {
        var baseByID: [String: UserConfirmedWorkout] = [:]
        for record in base { baseByID[record.id] = record }
        var desiredByID: [String: UserConfirmedWorkout] = [:]
        var desiredLastIndex: [String: Int] = [:]
        for (index, record) in desired.enumerated() {
            desiredByID[record.id] = record
            desiredLastIndex[record.id] = index
        }
        let removedIDs = Set(baseByID.keys).subtracting(desiredByID.keys)
        let changed: [UserConfirmedWorkout] = desired.enumerated().compactMap { index, record in
            guard desiredLastIndex[record.id] == index,
                  baseByID[record.id] != record else { return nil }
            return record
        }
        var currentOrder: [String] = []
        var currentByID: [String: UserConfirmedWorkout] = [:]
        for record in current {
            if currentByID[record.id] == nil { currentOrder.append(record.id) }
            currentByID[record.id] = record
        }
        var result = currentOrder.compactMap { id in
            removedIDs.contains(id) ? nil : currentByID[id]
        }
        for record in changed {
            if let index = result.firstIndex(where: { $0.id == record.id }) {
                result[index] = record
            } else {
                result.append(record)
            }
        }
        return result
    }

    @discardableResult
    private func saveConfirmedWorkouts(
        _ workouts: [UserConfirmedWorkout],
        deferDerivedPublication: Bool = false,
        stressContextMutation: WorkoutStressContextMutation? = nil
    ) async -> Bool {
        let base = cachedConfirmedWorkouts
        await Self.confirmedRecordTransactionGate.acquire()
        defer { Self.confirmedRecordTransactionGate.release() }
        guard canonicalMutationAllowed else {
            AtriaDebugLog("ATRIADBG confirmed_workout_store status=blocked reason=restore_in_progress")
            return false
        }
        let fileURL = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
            .appendingPathComponent(ConfirmedWorkoutDefaults.fileName)
        let loaded = await Self.confirmedRecordWorker.performAsync(.loadWorkouts(
            fileURL: fileURL,
            defaultsKey: ConfirmedWorkoutDefaults.key
        ))
        guard case .loadedWorkouts(let authoritativeCurrent) = loaded else {
            AtriaDebugLog("ATRIADBG confirmed_workout_store status=failed reason=authoritative_load_failed")
            return false
        }
        let rebased = Self.rebasedConfirmedWorkouts(
            base: base,
            desired: workouts,
            current: authoritativeCurrent
        )
        let existingByID = Dictionary(uniqueKeysWithValues: authoritativeCurrent.map { ($0.id, $0) })
        let settledWorkouts = rebased.map { workout -> UserConfirmedWorkout in
            guard workout.zoneBoundaries == nil,
                  existingByID[workout.id] == nil,
                  workout.zoneSeconds != nil,
                  let boundaries = AtriaHRRZoneBoundaries(
                    restingHR: baseline.restingInt ?? 60,
                    maxHR: profile.maxHR
                  ) else { return workout }
            var frozen = workout
            frozen.zoneBoundaries = boundaries
            return frozen
        }
        confirmedRecordWriteGeneration &+= 1
        let generation = confirmedRecordWriteGeneration
        let result = await Self.confirmedRecordWorker.performAsync(.workouts(
            generation: generation,
            records: settledWorkouts,
            fileURL: fileURL,
            defaultsKey: ConfirmedWorkoutDefaults.key
        ))
        guard case .workouts(let completedGeneration,
                             let sorted,
                             let bytes,
                             let mirrorSucceeded) = result,
              completedGeneration == generation else {
            let reason: String
            if case .failure(_, _, let failureReason) = result {
                reason = failureReason
            } else {
                reason = "generation_or_domain_mismatch"
            }
            AtriaDebugLog("ATRIADBG confirmed_workout_store status=failed reason=%@",
                          reason)
            return false
        }
        cachedConfirmedWorkouts = sorted
        backupCanonicalRevision &+= 1
        confirmedWorkoutsRevision &+= 1
        // GAP-09: workouts now contribute muscular load to the day aggregate,
        // so a workout mutation must invalidate the cached aggregate — a
        // freshly logged strength session has to reach today's Strain without
        // waiting for an unrelated invalidation.
        cachedHomeSavedAggregate = nil
        cachedTodayTRIMP = nil
        // This is the authoritative mutation boundary. Every caller—including
        // live-workout completion and review confirmation—must publish Activity
        // immediately after the atomic write, not wait for an unrelated metric.
        if !deferDerivedPublication {
            dashboardRevision &+= 1
            refreshHistorySnapshotCache(deferred: true)
        }
        // Schema-4 integrity includes confirmed workouts. Re-evaluate the
        // cached "current" badge after every successful workout mutation so a
        // newly added/edited/deleted workout cannot leave an older backup
        // incorrectly presented as current.
        refreshBackupStatusCacheDeferred(reason: "confirmed_workouts")
        AtriaDebugLog("ATRIADBG confirmed_workout_store status=ok workouts=%d bytes=%d mirror_succeeded=%d",
                      sorted.count,
                      bytes,
                      mirrorSucceeded ? 1 : 0)
        publishStressContextIfNeeded(
            deferDerivedPublication: deferDerivedPublication,
            publicationRequested:
                stressContextMutation?.changesAuthority ?? false,
            rollbackWorkoutMutation: stressContextMutation
        )
        return true
    }

    private func confirmedWorkoutID(start: Date, end: Date, source: String) -> String {
        let startSeconds = Int(start.timeIntervalSince1970.rounded())
        let endSeconds = Int(end.timeIntervalSince1970.rounded())
        return "\(startSeconds)-\(endSeconds)-\(source)"
    }

    /// Remove a confirmed workout from history — e.g. a wrong auto-detection the
    /// user wants gone. Returns false if no workout with that id exists.
    /// Bumps `dashboardRevision` (the @Published trigger) so the UI refreshes;
    /// `cachedConfirmedWorkouts` itself is not @Published.
    @discardableResult
    func deleteConfirmedWorkout(id: String) async -> Bool {
        guard let removed = cachedConfirmedWorkouts.first(where: { $0.id == id }) else { return false }
        let filtered = cachedConfirmedWorkouts.filter { $0.id != id }
        guard await saveConfirmedWorkouts(
            filtered,
            stressContextMutation: .init(previous: removed, next: nil)
        ) else { return false }
        addDismissedWorkoutCandidate(start: removed.start, end: removed.end)
        invalidateWorkoutReviewCache()
        dashboardRevision &+= 1
        return true
    }

    /// Dismisses an unsaved activity suggestion by its physiological window.
    /// Detector UUIDs are derived from source sessions and can change after an
    /// archive rebuild, so the durable overlap tombstone is authoritative.
    /// This is deliberately separate from deleting a saved workout: no sensor
    /// evidence or daily strain is removed, only the review suggestion.
    @discardableResult
    func dismissWorkoutCandidate(start: Date, end: Date) -> Bool {
        guard end > start else { return false }
        addDismissedWorkoutCandidate(start: start, end: end)
        invalidateWorkoutReviewCache()
        dashboardRevision &+= 1
        return true
    }

    /// Dismissed detector windows, newest first, for the history surface's
    /// "Dismissed detections" affordance. A read-only projection of the
    /// durable tombstone store — rendering it never mutates suppression.
    var dismissedWorkoutCandidatesForUI: [AtriaDismissedWorkoutCandidate] {
        dismissedWorkoutCandidates.sorted { $0.end > $1.end }
    }

    /// Undo for `dismissWorkoutCandidate` (2026-07-17): removes the
    /// overlapping tombstone(s) so the deterministic generator may offer the
    /// window again. Also clears the Home banner's candidate-ID suppression
    /// for the same window; without that, a restored candidate would reappear
    /// in history yet stay silently hidden on the Home surface.
    @discardableResult
    func restoreDismissedWorkoutCandidate(start: Date, end: Date) -> Bool {
        guard end > start else { return false }
        let previousCount = dismissedWorkoutCandidates.count
        dismissedWorkoutCandidates.removeAll { $0.overlaps(start: start, end: end) }
        guard dismissedWorkoutCandidates.count != previousCount else { return false }
        AtriaDismissedWorkoutCandidateStore.save(dismissedWorkoutCandidates)
        Self.purgeWorkoutReviewDismissedIDSuppression(overlappingStart: start, end: end)
        invalidateWorkoutReviewCache()
        dashboardRevision &+= 1
        AtriaDebugLog("ATRIADBG workout_review_candidate restored start=%.0f end=%.0f retained_tombstones=%d",
                      start.timeIntervalSince1970,
                      end.timeIntervalSince1970,
                      dismissedWorkoutCandidates.count)
        return true
    }

    /// Review-candidate IDs encode their untrimmed window as
    /// "<startSeconds>-<endSeconds>-<source>" (see
    /// `confirmedWorkoutIDForReview`). Restoring a window must drop IDs whose
    /// encoded window overlaps the restored interval; IDs that do not parse
    /// are kept untouched (fail closed — never widen an unrelated dismissal).
    nonisolated static func workoutReviewDismissedIDs(_ ids: [String],
                                                      removingOverlapWithStart start: Date,
                                                      end: Date) -> [String] {
        ids.filter { id in
            let parts = id.split(separator: "-", maxSplits: 2, omittingEmptySubsequences: false)
            guard parts.count >= 2,
                  let startSeconds = TimeInterval(parts[0]),
                  let endSeconds = TimeInterval(parts[1]),
                  endSeconds > startSeconds else { return true }
            let window = AtriaDismissedWorkoutCandidate(start: Date(timeIntervalSince1970: startSeconds),
                                                        end: Date(timeIntervalSince1970: endSeconds))
            return !window.overlaps(start: start, end: end)
        }
    }

    /// Keys owned by AtriaHomeView's banner-level ID suppression. The window
    /// tombstone (above) is the authoritative suppression; these IDs are the
    /// belt-and-braces same-frame guard the banner keeps, so restore has to
    /// clear both or the undo is only half real.
    private nonisolated static func purgeWorkoutReviewDismissedIDSuppression(overlappingStart start: Date,
                                                                             end: Date,
                                                                             defaults: UserDefaults = .standard) {
        let idsKey = "atria.workoutReview.dismissedIDs"
        let legacyIDKey = "atria.workoutReview.dismissedID"
        let ids = defaults.stringArray(forKey: idsKey) ?? []
        let kept = workoutReviewDismissedIDs(ids, removingOverlapWithStart: start, end: end)
        if kept.count != ids.count {
            defaults.set(kept, forKey: idsKey)
        }
        if let legacyID = defaults.string(forKey: legacyIDKey),
           workoutReviewDismissedIDs([legacyID], removingOverlapWithStart: start, end: end).isEmpty {
            defaults.removeObject(forKey: legacyIDKey)
        }
    }

    /// UI projection for the generic detector inbox. Keep the underlying
    /// history snapshot intact because its detections also contribute to
    /// physiological rollups; dismissal is a presentation/lifecycle choice,
    /// not permission to rewrite recorded load.
    var activityDetectionsForUI: [ActivityDetection] {
        Self.activityDetectionsForUI(historySnapshot.detections,
                                     dismissedCandidates: dismissedWorkoutCandidates)
    }

    nonisolated static func activityDetectionsForUI(
        _ detections: [ActivityDetection],
        dismissedCandidates: [AtriaDismissedWorkoutCandidate]
    ) -> [ActivityDetection] {
        detections.filter { detection in
            guard detection.kind == .workout || detection.kind == .activityCandidate else {
                return true
            }
            return !dismissedCandidates.contains {
                $0.overlaps(start: detection.start, end: detection.end)
            }
        }
    }

    private func addDismissedWorkoutCandidate(start: Date, end: Date) {
        guard end > start else { return }
        dismissedWorkoutCandidates.removeAll { $0.overlaps(start: start, end: end) }
        dismissedWorkoutCandidates.append(AtriaDismissedWorkoutCandidate(start: start, end: end))
        AtriaDismissedWorkoutCandidateStore.save(dismissedWorkoutCandidates)
    }

    private func clearDismissedWorkoutCandidates(overlappingStart start: Date, end: Date) {
        let previousCount = dismissedWorkoutCandidates.count
        dismissedWorkoutCandidates.removeAll { $0.overlaps(start: start, end: end) }
        if dismissedWorkoutCandidates.count != previousCount {
            AtriaDismissedWorkoutCandidateStore.save(dismissedWorkoutCandidates)
        }
    }

    /// A guided detector review can be adjusted far enough that its saved
    /// window no longer overlaps the detector's original interval. Settle that
    /// original interval only after a canonical workout is already durable;
    /// otherwise a failed Save would make the still-actionable evidence vanish.
    private func settleWorkoutCandidateAfterCanonicalSave(
        confirmed: UserConfirmedWorkout,
        originalCandidateWindow: (start: Date, end: Date)?
    ) {
        clearDismissedWorkoutCandidates(overlappingStart: confirmed.start,
                                        end: confirmed.end)
        guard let originalCandidateWindow,
              originalCandidateWindow.end > originalCandidateWindow.start else { return }
        addDismissedWorkoutCandidate(start: originalCandidateWindow.start,
                                     end: originalCandidateWindow.end)
        invalidateWorkoutReviewCache()
        dashboardRevision &+= 1
    }

    private func invalidateWorkoutReviewCache() {
        workoutReviewCacheGeneration &+= 1
        // DispatchWorkItem cancellation cannot interrupt an aggregate replay.
        // Preserve the running sentinel so a consumer can only replace the one
        // trailing request; completion will release the slot before launching
        // that latest request.
        workoutReviewRefreshGate.invalidate()
        cachedWorkoutReviewCandidate = nil
        cachedWorkoutReviewCandidates = []
        workoutReviewCacheKey = nil
    }

    /// Relabel a confirmed workout without touching any of its measured metrics
    /// (times, HR, strain, calories are all preserved). Returns false if the id
    /// is unknown or the new label is blank.
    @discardableResult
    func renameConfirmedWorkout(id: String, label newLabel: String) async -> Bool {
        let trimmed = newLabel.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty,
              let index = cachedConfirmedWorkouts.firstIndex(where: { $0.id == id }),
              cachedConfirmedWorkouts[index].label != trimmed else { return false }
        let old = cachedConfirmedWorkouts[index]
        var renamed = UserConfirmedWorkout(id: old.id,
                                           createdAt: old.createdAt,
                                           start: old.start,
                                           end: old.end,
                                           label: trimmed,
                                           source: old.source,
                                           confidence: old.confidence,
                                           sessions: old.sessions,
                                           samples: old.samples,
                                           avgHR: old.avgHR,
                                           peakHR: old.peakHR,
                                           p95HR: old.p95HR,
                                           p99HR: old.p99HR,
                                           thresholdHR: old.thresholdHR,
                                           streamCoveragePercent: old.streamCoveragePercent,
                                           observedDuration: old.observedDuration,
                                           reason: old.reason,
                                           eventTimeZoneIdentifier: old.eventTimeZoneIdentifier)
        renamed.activityType = old.activityType
        renamed.activitySubtype = old.activitySubtype
        renamed.exerciseNames = old.exerciseNames
        renamed.strengthSets = old.strengthSets
        renamed.muscularLoadReceipt = old.muscularLoadReceipt
        renamed.excludedIntervals = old.excludedIntervals
        renamed.reviewSource = old.reviewSource
        renamed.reviewCandidateID = old.reviewCandidateID
        renamed.activityCalibrationEvidence = old.activityCalibrationEvidence
        renamed.strain = old.strain
        renamed.activeEnergyKilocalories = old.activeEnergyKilocalories
        renamed.activeEnergyConfidence = old.activeEnergyConfidence
        renamed.zoneSeconds = old.zoneSeconds
        // GAP-03: a rename must never drop the frozen zone boundaries (and a
        // relabel of a strength workout must never drop its muscular receipt).
        renamed.zoneBoundaries = old.zoneBoundaries
        renamed.workoutSteps = old.workoutSteps
        renamed.workoutStepsAreEstimated = old.workoutStepsAreEstimated
        renamed.workoutStepsCapturedAt = old.workoutStepsCapturedAt
        var updated = cachedConfirmedWorkouts
        updated[index] = renamed
        guard await saveConfirmedWorkouts(updated) else { return false }
        dashboardRevision &+= 1
        return true
    }

    /// Set (or clear) a confirmed workout's activity type -- e.g. relabel a
    /// generic effort as "Run", "Walk", "Dance". Measured metrics are untouched.
    @discardableResult
    func setConfirmedWorkoutActivityType(id: String, activityType: String) async -> Bool {
        let trimmed = activityType.trimmingCharacters(in: .whitespacesAndNewlines)
        let newType = trimmed.isEmpty ? nil : trimmed
        guard let index = cachedConfirmedWorkouts.firstIndex(where: { $0.id == id }),
              cachedConfirmedWorkouts[index].activityType != newType else { return false }
        var updated = cachedConfirmedWorkouts
        updated[index].activityType = newType
        guard await saveConfirmedWorkouts(updated) else { return false }
        dashboardRevision &+= 1
        return true
    }

    enum ConfirmedWorkoutEditError: Error, Equatable {
        case workoutNotFound
        case emptyLabel
        case invalidWindow
        case insufficientStrapData
        case conflictingWorkout
        case persistenceFailed

        var userMessage: String {
            switch self {
            case .workoutNotFound:
                return "That workout is no longer available. Reopen Activity and try again."
            case .emptyLabel:
                return "Enter a workout name."
            case .invalidWindow:
                return "The end time must be after the start time."
            case .insufficientStrapData:
                return "Atria could not find enough recorded strap data in that time range. Your original workout is unchanged."
            case .conflictingWorkout:
                return "Another saved workout already uses that exact time range. Your original workout is unchanged."
            case .persistenceFailed:
                return "Atria could not save those changes. Your original workout is unchanged."
            }
        }
    }

    /// Removes saved pause intervals from both the sample population and the
    /// elapsed-time axis used by workout readiness. Merely dropping paused
    /// samples leaves a wall-clock hole and divides coverage by paused time;
    /// compressing that known gap makes samples, percentiles, observed duration
    /// and coverage all describe the same active portion of the workout.
    nonisolated static func activeWorkoutPointProjection(
        points: [SavedSession.Point],
        windowStart: Date,
        windowEnd: Date,
        excludedIntervals: [ExcludedInterval]
    ) -> (points: [SavedSession.Point], activeDuration: TimeInterval) {
        let wallDuration = max(0, windowEnd.timeIntervalSince(windowStart))
        guard wallDuration > 0 else { return ([], 0) }

        let clipped = excludedIntervals.compactMap { interval -> ExcludedInterval? in
            let start = max(interval.start, windowStart)
            let end = min(interval.end, windowEnd)
            guard end > start else { return nil }
            return ExcludedInterval(start: start, end: end)
        }
        .sorted { lhs, rhs in
            lhs.start == rhs.start ? lhs.end < rhs.end : lhs.start < rhs.start
        }

        var merged: [ExcludedInterval] = []
        for interval in clipped {
            if let last = merged.last, interval.start <= last.end {
                merged[merged.count - 1] = ExcludedInterval(start: last.start,
                                                             end: max(last.end, interval.end))
            } else {
                merged.append(interval)
            }
        }
        // A completed journal can briefly overlap its persisted session during
        // foreground recovery. Both rows describe the same strap observation;
        // counting them twice inflates samples and can make a conflicting
        // replay artifact win a percentile. Keep the caller's canonical-source
        // precedence while making the projection deterministic for unsorted
        // inputs, then accept at most one observation per millisecond.
        let orderedPoints = points.enumerated().sorted { lhs, rhs in
            if lhs.element.t != rhs.element.t { return lhs.element.t < rhs.element.t }
            return lhs.offset < rhs.offset
        }
        var acceptedAbsoluteMilliseconds = Set<Int64>()
        let uniquePoints = orderedPoints.compactMap { indexedPoint -> SavedSession.Point? in
            let point = indexedPoint.element
            let absoluteTime = windowStart.addingTimeInterval(max(0, point.t))
            let absoluteMillisecond = Int64((absoluteTime.timeIntervalSince1970 * 1_000).rounded())
            guard acceptedAbsoluteMilliseconds.insert(absoluteMillisecond).inserted else {
                return nil
            }
            return point
        }
        guard !merged.isEmpty else { return (uniquePoints, wallDuration) }

        let excludedDuration = merged.reduce(0.0) {
            $0 + $1.end.timeIntervalSince($1.start)
        }
        let activeDuration = max(0, wallDuration - excludedDuration)
        let activePoints = uniquePoints.compactMap { point -> SavedSession.Point? in
            let absoluteTime = windowStart.addingTimeInterval(max(0, point.t))
            var elapsedBeforeSample: TimeInterval = 0
            for interval in merged {
                if absoluteTime >= interval.start, absoluteTime <= interval.end {
                    return nil
                }
                if absoluteTime > interval.end {
                    elapsedBeforeSample += interval.end.timeIntervalSince(interval.start)
                } else {
                    break
                }
            }
            return SavedSession.Point(t: max(0, point.t - elapsedBeforeSample), bpm: point.bpm)
        }
        return (activePoints, activeDuration)
    }

    /// Losslessly enriches a sparse, already-confirmed workout from timestamped
    /// strap HR. The archive boundary has already rejected unvalidated rows; this
    /// function still rejects impossible BPMs, values outside the saved window,
    /// and samples inside user-recorded pauses. It never reconstructs samples
    /// from old averages and only returns a replacement when the complete
    /// monotonic evidence tuple becomes stronger.
    nonisolated static func rehydratedConfirmedWorkout(
        _ old: UserConfirmedWorkout,
        existingPoints: [HistoricalArchive.HeartRatePoint],
        archivePoints: [HistoricalArchive.HeartRatePoint],
        rest: Int,
        maxHR: Int,
        profile: AthleteProfile
    ) -> UserConfirmedWorkout? {
        guard old.end > old.start else { return nil }

        // Millisecond identity removes replay/archive duplicates while preserving
        // the canonical-session value when both stores contain the same sample.
        var byMillisecond: [Int64: HistoricalArchive.HeartRatePoint] = [:]
        for point in archivePoints + existingPoints {
            guard point.t >= old.start, point.t <= old.end, (35...240).contains(point.bpm) else { continue }
            let key = Int64((point.t.timeIntervalSince1970 * 1_000).rounded())
            byMillisecond[key] = point
        }
        let wallPoints = byMillisecond.values.sorted { lhs, rhs in
            lhs.t == rhs.t ? lhs.bpm < rhs.bpm : lhs.t < rhs.t
        }.map {
            SavedSession.Point(t: $0.t.timeIntervalSince(old.start), bpm: $0.bpm)
        }
        let active = activeWorkoutPointProjection(points: wallPoints,
                                                  windowStart: old.start,
                                                  windowEnd: old.end,
                                                  excludedIntervals: old.excludedIntervals ?? [])
        guard explicitWorkoutSaveIsConfirmable(sampleCount: active.points.count,
                                               requestedDuration: active.activeDuration) else { return nil }

        let window = SavedSession(id: UUID(),
                                  start: old.start,
                                  end: old.start.addingTimeInterval(active.activeDuration),
                                  label: old.label,
                                  points: active.points,
                                  hrv: nil,
                                  biologicalSex: profile.biologicalSex,
                                  eventTimeZoneIdentifier: old.eventTimeZoneIdentifier)
        let readiness = window.workoutReadiness(rest: rest, maxHR: maxHR)
        guard active.points.count >= old.samples else { return nil }

        let strain = Metrics.strain(fromTRIMP: window.trimp(rest: rest, max: maxHR))
        let activeEnergy = window.activeCalories(rest: rest, profile: profile)
        // GAP-03: recovered HR evidence repairs the trace, not the zone
        // identity. When the workout froze its boundaries at completion, the
        // rehydrated zone seconds are computed with those same values; only a
        // legacy record (no freeze) falls back to the current profile, and
        // then the freeze is minted from the values actually used.
        let zoneRest = old.zoneBoundaries?.restingHR ?? rest
        let zoneMax = old.zoneBoundaries?.maxHR ?? maxHR
        let zoneSummary = Metrics.maxHeartRateZoneSeconds(
            active.points.map { (t: $0.t, bpm: $0.bpm) },
            maxHR: zoneMax,
            restingHR: zoneRest
        )

        let replacement = UserConfirmedWorkout(
            id: old.id,
            createdAt: old.createdAt,
            start: old.start,
            end: old.end,
            label: old.label,
            source: old.source,
            confidence: old.confidence == "user_confirmed_no_hr"
                ? "user_confirmed_recovered_hr"
                : old.confidence,
            sessions: old.sessions,
            samples: active.points.count,
            avgHR: readiness.avgHR,
            peakHR: readiness.peakHR,
            p95HR: readiness.p95HR,
            p99HR: readiness.p99HR,
            thresholdHR: readiness.thresholdHR,
            streamCoveragePercent: readiness.streamCoveragePercent,
            observedDuration: readiness.observedDuration,
            reason: "historical_archive_real_hr",
            activityType: old.activityType,
            activitySubtype: old.activitySubtype,
            exerciseNames: old.exerciseNames,
            strengthSets: old.strengthSets,
            muscularLoadReceipt: old.muscularLoadReceipt,
            excludedIntervals: old.excludedIntervals,
            reviewSource: old.reviewSource,
            reviewCandidateID: old.reviewCandidateID,
            activityCalibrationEvidence: old.activityCalibrationEvidence,
            strain: strain,
            activeEnergyKilocalories: activeEnergy,
            activeEnergyConfidence: activeEnergy == nil
                ? (profile.hasEnergyProfile ? nil : "needs_profile")
                : "estimate",
            zoneSeconds: zoneSummary.isEmpty ? nil : zoneSummary.storage,
            zoneBoundaries: old.zoneBoundaries
                ?? (zoneSummary.isEmpty ? nil : AtriaHRRZoneBoundaries(restingHR: zoneRest,
                                                                       maxHR: zoneMax)),
            eventTimeZoneIdentifier: old.eventTimeZoneIdentifier,
            workoutSteps: old.workoutSteps,
            workoutStepsAreEstimated: old.workoutStepsAreEstimated,
            workoutStepsCapturedAt: old.workoutStepsCapturedAt
        )
        return recoveredWorkoutEvidenceIsStronger(replacement, than: old)
            ? replacement
            : nil
    }

    /// The recovered-data fence repairs only HR/load evidence. WHOOP/R10
    /// motion decoding has its own bounded publication lane; keeping it out of
    /// this predicate prevents repeated whole-archive motion scans from
    /// blocking exact historical-gap publication.
    nonisolated static func confirmedWorkoutNeedsArchiveRehydration(
        _ workout: UserConfirmedWorkout
    ) -> Bool {
        confirmedWorkoutNeedsHeartRateArchiveRehydration(workout)
    }

    nonisolated static func confirmedWorkoutArchiveUnionWindow(
        _ workouts: [UserConfirmedWorkout]
    ) -> DateInterval? {
        guard let start = workouts.map(\.start).min(),
              let end = workouts.map(\.end).max(),
              end > start else { return nil }
        return DateInterval(start: start, end: end)
    }

    nonisolated static func confirmedWorkoutFallsWithinRecoveredArchive(
        workoutStart: Date,
        coverageStart: Date
    ) -> Bool {
        workoutStart >= coverageStart
    }

    /// Durable identity of every input that can change confirmed-workout HR
    /// repair. Hashing the bounded overlapping sessions is much cheaper than
    /// reopening the retained raw archive, while still invalidating for a
    /// changed workout, canonical HR point, profile, resting/max HR, archive
    /// generation, append, truncation, replacement, addition, or removal.
    nonisolated static func confirmedWorkoutHRRehydrationAttemptSignature(
        workouts: [UserConfirmedWorkout],
        sessions: [SavedSession],
        rest: Int,
        maxHR: Int,
        profile: AthleteProfile,
        sourceFingerprint: HistoricalArchive.ConsumerSourceFingerprint
    ) -> String? {
        guard let union = confirmedWorkoutArchiveUnionWindow(workouts) else {
            return nil
        }
        let relevantSessions = sessions.filter {
            $0.end >= union.start && $0.start <= union.end
        }
        let payload = ConfirmedWorkoutHRRehydrationAttemptPayload(
            algorithmVersion: workoutHRRehydrationAlgorithmVersion,
            workouts: workouts.sorted {
                if $0.start != $1.start { return $0.start < $1.start }
                if $0.end != $1.end { return $0.end < $1.end }
                return $0.id < $1.id
            },
            sessions: relevantSessions.sorted {
                if $0.start != $1.start { return $0.start < $1.start }
                if $0.end != $1.end { return $0.end < $1.end }
                return $0.id.uuidString < $1.id.uuidString
            },
            restingHR: rest,
            maxHR: maxHR,
            profile: profile,
            sourceFingerprint: sourceFingerprint
        )
        let encoder = JSONEncoder()
        encoder.outputFormatting = [.sortedKeys]
        encoder.dateEncodingStrategy = .millisecondsSince1970
        guard let data = try? encoder.encode(payload) else { return nil }
        return SHA256.hash(data: data)
            .map { String(format: "%02x", $0) }
            .joined()
    }

    nonisolated static func confirmedWorkoutNeedsHeartRateArchiveRehydration(
        _ workout: UserConfirmedWorkout
    ) -> Bool {
        workout.streamCoveragePercent < 100
            || workout.samples < 2
            || workout.avgHR <= 0
            || workout.peakHR <= 0
            || workout.strain == nil
            || workout.zoneSeconds == nil
    }

    /// Coverage is stored as an integer, so a recovered sample can materially
    /// expand the observed interval without changing its rounded percentage.
    /// Compare the full monotonic evidence tuple instead of dropping that
    /// recovery. No replacement may reduce sample count, coverage, or observed
    /// duration; this keeps repeated archive notifications idempotent.
    nonisolated static func recoveredWorkoutEvidenceIsStronger(
        _ candidate: UserConfirmedWorkout,
        than current: UserConfirmedWorkout
    ) -> Bool {
        guard candidate.id == current.id,
              candidate.start == current.start,
              candidate.end == current.end,
              candidate.samples >= current.samples,
              candidate.streamCoveragePercent >= current.streamCoveragePercent,
              candidate.observedDuration + 0.001 >= current.observedDuration else {
            return false
        }
        return candidate.streamCoveragePercent > current.streamCoveragePercent
            || candidate.observedDuration > current.observedDuration + 0.001
            || candidate.samples > current.samples
            || (current.strain == nil && candidate.strain != nil)
            || (current.zoneSeconds == nil && candidate.zoneSeconds != nil)
            || (current.activeEnergyKilocalories == nil
                && candidate.activeEnergyKilocalories != nil)
            || (current.workoutSteps == nil
                && candidate.workoutSteps != nil)
            || (current.workoutStepsAreEstimated == true
                && candidate.workoutStepsAreEstimated == true
                && candidate.workoutSteps != current.workoutSteps
                && candidate.workoutStepsCapturedAt
                    == current.workoutStepsCapturedAt)
    }

    /// Commits every field exposed by the Activity editor in one durable write.
    /// The replacement is fully validated and derived in memory first; neither
    /// `cachedConfirmedWorkouts` nor its on-disk snapshot changes unless the
    /// complete replacement can be persisted atomically.
    @discardableResult
    func editConfirmedWorkout(id: String,
                              label newLabel: String,
                              activityType newActivityType: String,
                              activitySubtype newActivitySubtype: String?,
                              start newStart: Date,
                              end newEnd: Date,
                              rest: Int,
                              maxHR: Int) async -> Result<UserConfirmedWorkout, ConfirmedWorkoutEditError> {
        let trimmedLabel = newLabel.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmedLabel.isEmpty else { return .failure(.emptyLabel) }
        guard newEnd > newStart else { return .failure(.invalidWindow) }
        guard let oldIndex = cachedConfirmedWorkouts.firstIndex(where: { $0.id == id }) else {
            return .failure(.workoutNotFound)
        }

        let old = cachedConfirmedWorkouts[oldIndex]
        let trimmedType = newActivityType.trimmingCharacters(in: .whitespacesAndNewlines)
        let activityType = trimmedType.isEmpty ? nil : trimmedType
        let resolvedType = activityType.flatMap(AtriaWorkoutActivityType.init(rawValue:))
        let activitySubtype = resolvedType?.normalizedSubtype(newActivitySubtype)
        let windowChanged = abs(newStart.timeIntervalSince(old.start)) >= 0.5
            || abs(newEnd.timeIntervalSince(old.end)) >= 0.5

        let replacement: UserConfirmedWorkout
        if windowChanged {
            let overlapping = canonicalSessions(includeActiveJournal: true).filter { session in
                session.end > newStart && session.start < newEnd && !session.points.isEmpty
            }
            var points: [SavedSession.Point] = []
            for session in overlapping {
                for point in session.points where point.bpm > 0 {
                    let absoluteTime = session.start.addingTimeInterval(max(0, point.t))
                    guard absoluteTime >= newStart, absoluteTime <= newEnd else { continue }
                    points.append(SavedSession.Point(t: absoluteTime.timeIntervalSince(newStart),
                                                     bpm: point.bpm))
                }
            }
            points.sort { $0.t < $1.t }
            let activeProjection = Self.activeWorkoutPointProjection(
                points: points,
                windowStart: newStart,
                windowEnd: newEnd,
                excludedIntervals: old.excludedIntervals ?? []
            )
            let replacementID = confirmedWorkoutID(start: newStart,
                                                    end: newEnd,
                                                    source: "live_workout_window")
            if cachedConfirmedWorkouts.contains(where: { $0.id == replacementID && $0.id != old.id }) {
                return .failure(.conflictingWorkout)
            }

            if !Self.explicitWorkoutSaveIsConfirmable(sampleCount: activeProjection.points.count,
                                                       requestedDuration: activeProjection.activeDuration) {
                // A metadata-only workout is already an explicit declaration
                // that the activity happened despite missing BLE evidence. Its
                // time/name/type must remain editable as one atomic Save, while
                // every sensor-derived value stays absent. HR-backed workouts
                // still fail closed rather than silently losing their metrics.
                guard old.confidence == "user_confirmed_no_hr",
                      Self.metadataOnlyWorkoutSaveIsConfirmable(
                        isExplicitUserActivity: true,
                        requestedDuration: activeProjection.activeDuration
                      ) else {
                    return .failure(.insufficientStrapData)
                }
                replacement = UserConfirmedWorkout(
                    id: replacementID,
                    createdAt: old.createdAt,
                    start: newStart,
                    end: newEnd,
                    label: trimmedLabel,
                    source: "live_workout_window",
                    confidence: "user_confirmed_no_hr",
                    sessions: overlapping.count,
                    samples: 0,
                    avgHR: 0,
                    peakHR: 0,
                    p95HR: 0,
                    p99HR: 0,
                    thresholdHR: SavedSession.workoutElevatedThreshold(rest: rest, maxHR: maxHR),
                    streamCoveragePercent: 0,
                    observedDuration: 0,
                    reason: "no_strap_hr_samples",
                    activityType: activityType,
                    activitySubtype: activitySubtype,
                    exerciseNames: old.exerciseNames,
                    strengthSets: old.strengthSets,
                    muscularLoadReceipt: old.muscularLoadReceipt,
                    excludedIntervals: old.excludedIntervals,
                    reviewSource: old.reviewSource,
                    reviewCandidateID: old.reviewCandidateID,
                    activityCalibrationEvidence: old.activityCalibrationEvidence == nil
                        ? nil
                        : Self.activityCalibrationEvidence(sessions: overlapping,
                                                           start: newStart,
                                                           end: newEnd),
                    strain: nil,
                    activeEnergyKilocalories: nil,
                    activeEnergyConfidence: nil,
                    zoneSeconds: nil,
                    eventTimeZoneIdentifier: old.eventTimeZoneIdentifier ?? TimeZone.current.identifier,
                    // The stored count belongs to the original absolute window.
                    // Until exact timestamped step evidence can be reprojected,
                    // a time edit must fail closed instead of attaching the old
                    // count to a different workout interval.
                    workoutSteps: nil,
                    workoutStepsAreEstimated: nil,
                    workoutStepsCapturedAt: nil
                )
            } else {
                let window = SavedSession(id: UUID(),
                                      start: newStart,
                                      end: newStart.addingTimeInterval(activeProjection.activeDuration),
                                      label: "Live workout",
                                      points: activeProjection.points,
                                      hrv: nil,
                                      eventTimeZoneIdentifier: old.eventTimeZoneIdentifier
                                          ?? TimeZone.current.identifier)
                let readiness = window.workoutReadiness(rest: rest, maxHR: maxHR)
                // Derive every edited metric from the exact same de-duplicated,
                // pause-filtered population as readiness. A second pass over
                // canonical sessions can race a journal flush and, more
                // importantly, risks reintroducing rows the projection already
                // excluded. The compressed active axis intentionally contains
                // no pause gap, so no further exclusions are needed here.
                let editTRIMP = window.trimp(rest: rest, max: maxHR)
                let editStrain = Metrics.strain(fromTRIMP: editTRIMP)
                let editActiveEnergy = window.activeCalories(rest: rest, profile: profile)
                // GAP-03: recomputing an edited window's zone seconds must use
                // the workout's frozen boundaries when they exist — a bound
                // edit is not permission to rewrite the zone identity with
                // today's profile values.
                let editZoneRest = old.zoneBoundaries?.restingHR ?? rest
                let editZoneMax = old.zoneBoundaries?.maxHR ?? maxHR
                let editZoneSummary = Metrics.maxHeartRateZoneSeconds(
                    activeProjection.points.map { (t: $0.t, bpm: $0.bpm) },
                    maxHR: editZoneMax,
                    restingHR: editZoneRest
                )
                let workoutSource = "live_workout_window"
                let confidence = readiness.ready ? "live_window_user_confirmed" :
                (readiness.nearMiss ? "live_window_near_miss" :
                    (readiness.streamCoveragePercent < 5
                        ? "live_window_manual_sparse_hr"
                        : "live_window_manual_confirmed"))
                replacement = UserConfirmedWorkout(
                id: replacementID,
                createdAt: old.createdAt,
                start: newStart,
                end: newEnd,
                label: trimmedLabel,
                source: workoutSource,
                confidence: confidence,
                sessions: overlapping.count,
                samples: activeProjection.points.count,
                avgHR: readiness.avgHR,
                peakHR: readiness.peakHR,
                p95HR: readiness.p95HR,
                p99HR: readiness.p99HR,
                thresholdHR: readiness.thresholdHR,
                streamCoveragePercent: readiness.streamCoveragePercent,
                observedDuration: readiness.observedDuration,
                reason: readiness.ready ? readiness.reason : readiness.primaryBlocker,
                activityType: activityType,
                activitySubtype: activitySubtype,
                exerciseNames: old.exerciseNames,
                strengthSets: old.strengthSets,
                muscularLoadReceipt: old.muscularLoadReceipt,
                excludedIntervals: old.excludedIntervals,
                reviewSource: old.reviewSource,
                reviewCandidateID: old.reviewCandidateID,
                activityCalibrationEvidence: old.activityCalibrationEvidence == nil
                    ? nil
                    : Self.activityCalibrationEvidence(sessions: overlapping,
                                                       start: newStart,
                                                       end: newEnd),
                strain: editStrain,
                activeEnergyKilocalories: editActiveEnergy,
                activeEnergyConfidence: editActiveEnergy == nil
                    ? (profile.hasEnergyProfile ? nil : "needs_profile")
                    : "estimate",
                zoneSeconds: editZoneSummary.isEmpty ? nil : editZoneSummary.storage,
                    zoneBoundaries: editZoneSummary.isEmpty
                        ? nil
                        : (old.zoneBoundaries
                            ?? AtriaHRRZoneBoundaries(restingHR: editZoneRest, maxHR: editZoneMax)),
                    eventTimeZoneIdentifier: old.eventTimeZoneIdentifier ?? TimeZone.current.identifier,
                    workoutSteps: nil,
                    workoutStepsAreEstimated: nil,
                    workoutStepsCapturedAt: nil
                )
            }
        } else {
            replacement = UserConfirmedWorkout(
                id: old.id,
                createdAt: old.createdAt,
                start: old.start,
                end: old.end,
                label: trimmedLabel,
                source: old.source,
                confidence: old.confidence,
                sessions: old.sessions,
                samples: old.samples,
                avgHR: old.avgHR,
                peakHR: old.peakHR,
                p95HR: old.p95HR,
                p99HR: old.p99HR,
                thresholdHR: old.thresholdHR,
                streamCoveragePercent: old.streamCoveragePercent,
                observedDuration: old.observedDuration,
                reason: old.reason,
                activityType: activityType,
                activitySubtype: activitySubtype,
                exerciseNames: old.exerciseNames,
                strengthSets: old.strengthSets,
                muscularLoadReceipt: old.muscularLoadReceipt,
                excludedIntervals: old.excludedIntervals,
                reviewSource: old.reviewSource,
                reviewCandidateID: old.reviewCandidateID,
                activityCalibrationEvidence: old.activityCalibrationEvidence,
                strain: old.strain,
                activeEnergyKilocalories: old.activeEnergyKilocalories,
                activeEnergyConfidence: old.activeEnergyConfidence,
                zoneSeconds: old.zoneSeconds,
                zoneBoundaries: old.zoneBoundaries,
                eventTimeZoneIdentifier: old.eventTimeZoneIdentifier,
                workoutSteps: old.workoutSteps,
                workoutStepsAreEstimated: old.workoutStepsAreEstimated,
                workoutStepsCapturedAt: old.workoutStepsCapturedAt
            )
        }

        guard replacement != old else { return .success(old) }
        var updated = cachedConfirmedWorkouts
        updated[oldIndex] = replacement
        guard await saveConfirmedWorkouts(
            updated,
            // This guided editor owns bounds and pause exclusions in one
            // transaction. A successful replacement is therefore the bounded
            // authority edge; never rescan all workout history here.
            stressContextMutation: .init(previous: old, next: replacement)
        ) else {
            return .failure(.persistenceFailed)
        }
        dashboardRevision &+= 1
        // Persistence may settle canonical fields such as a newly frozen HRR
        // boundary receipt. Return the exact record that crossed the atomic
        // store boundary instead of the pre-commit constructor.
        return .success(
            cachedConfirmedWorkouts.first(where: { $0.id == replacement.id })
                ?? replacement
        )
    }

    /// Source-compatible metadata/window editor for callers that do not expose
    /// subtype UI. It preserves the subtype only when it is valid for the chosen
    /// activity type; changing type therefore cannot retain an incompatible one.
    @discardableResult
    func editConfirmedWorkout(id: String,
                              label newLabel: String,
                              activityType newActivityType: String,
                              start newStart: Date,
                              end newEnd: Date,
                              rest: Int,
                              maxHR: Int) async -> Result<UserConfirmedWorkout, ConfirmedWorkoutEditError> {
        let oldSubtype = cachedConfirmedWorkouts.first(where: { $0.id == id })?.activitySubtype
        return await editConfirmedWorkout(id: id,
                                    label: newLabel,
                                    activityType: newActivityType,
                                    activitySubtype: oldSubtype,
                                    start: newStart,
                                    end: newEnd,
                                    rest: rest,
                                    maxHR: maxHR)
    }

    /// Change a confirmed workout's time window. Re-derives every metric (HR,
    /// strain, calories, zones) from the strap samples inside the new window --
    /// no fabrication -- by re-confirming it exactly, preserving the label/type/
    /// exercises. Returns the updated workout, or nil while leaving the original
    /// unchanged when the new window has too little strap data to save.
    @discardableResult
    func updateConfirmedWorkoutWindow(id: String,
                                      newStart: Date,
                                      newEnd: Date,
                                      rest: Int,
                                      maxHR: Int) async -> UserConfirmedWorkout? {
        guard let old = cachedConfirmedWorkouts.first(where: { $0.id == id }) else { return nil }
        switch await editConfirmedWorkout(id: id,
                                    label: old.label,
                                    activityType: old.activityType ?? "",
                                    start: newStart,
                                    end: newEnd,
                                    rest: rest,
                                    maxHR: maxHR) {
        case .success(let updated):
            return updated
        case .failure:
            return nil
        }
    }

    func confirmBestSleepCandidateForUI(rest: Int, source: String = "ui") async -> UserConfirmedSleep? {
        await confirmBestSleepCandidate(rest: rest, source: source)
    }

    func confirmSleepHistoryNightForUI(_ night: SleepHistorySnapshot.Night,
                                       rest: Int,
                                       source: String = "ui") async -> UserConfirmedSleep? {
        await confirmSleepHistoryNight(night, rest: rest, source: source)
    }

    enum SleepReviewResolution: Equatable {
        case loading
        case ready(SleepHistorySnapshot.Night?)
    }

    /// One transactional entry point for every review/edit sheet. Pressing
    /// Save on an unchanged detector suggestion confirms the evidence already
    /// prepared off-main. Save on an unchanged canonical sleep returns that
    /// exact record. Neither path re-reads the growing journal or applies the
    /// stricter adjustment-coverage gate; only an actual boundary/type edit is
    /// re-derived. Thus a no-longer-loaded sensor window cannot make an already
    /// saved sleep fail or silently acquire different metrics/provenance.
    @discardableResult
    /// Recompute the pending "which is your main sleep?" prompt from the current
    /// confirmed-sleep set. Cheap and idempotent; call after any confirmed-sleep
    /// change and once on load so an already-saved double-sleep day still asks.
    func refreshPendingSameDayMainSleepChoice() {
        let next = Self.pendingSameDayMainSleepChoice(
            confirmedSleeps: cachedConfirmedSleeps,
            calendar: .current)
        if pendingSameDayMainSleepChoiceForUI != next {
            pendingSameDayMainSleepChoiceForUI = next
            // Notification entry point for the same prompt: schedules when a
            // new unresolved double-sleep day appears while the app is not
            // active, and cancels the pending notification once resolved.
            LocalNotificationScheduler.refreshSameDayPrimarySleepPrompt(choice: next)
        }
    }

    /// Record the user's answer: `primaryID` becomes the day's primary main
    /// (drives Recovery and the physiological-cycle boundary), every other
    /// same-day main is marked a real second sleep, and the day never prompts
    /// again. Passing the recommended (longest) id applies the automatic default
    /// explicitly. The second sleep keeps counting and now shares one cycle so it
    /// also shows as its own Activity row.
    func resolveSameDayMainSleepChoice(_ choice: AtriaSameDayMainSleepChoice,
                                       primaryID: String) {
        let dayIDs = Set(choice.options.map(\.id))
        guard dayIDs.contains(primaryID) else { return }
        let updated = cachedConfirmedSleeps.map { sleep -> UserConfirmedSleep in
            guard dayIDs.contains(sleep.id) else { return sleep }
            return sleep.replacingDayPrimaryChoice(sleep.id == primaryID)
        }
        // Clear the prompt up front so the sheet dismisses immediately; the save
        // re-derives the physiological cycle/recovery/Activity projections, then
        // the refresh recomputes the (now resolved) pending state — surfacing the
        // next unresolved double-sleep day, if any.
        pendingSameDayMainSleepChoiceForUI = nil
        Task { @MainActor in
            await saveConfirmedSleeps(updated)
            refreshPendingSameDayMainSleepChoice()
        }
    }

    func saveSleepReviewNightForUI(_ night: SleepHistorySnapshot.Night,
                                   start: Date,
                                   end: Date,
                                   isNap: Bool,
                                   rest: Int,
                                   source: String = "ui") async -> UserConfirmedSleep? {
        if night.confirmed {
            guard let existing = cachedConfirmedSleeps.first(where: { $0.id == night.id }) else {
                return nil
            }
            // Save is idempotent for an unchanged canonical sleep. In
            // particular, do not send the record back through the sensor-
            // coverage editor: the live journal may already have rotated or
            // been finalized, and an unchanged Save must not fail, replace
            // provenance, or perturb the recovery inputs the user just saw.
            if Self.sleepReviewSaveIsUnchanged(night: night,
                                               start: start,
                                               end: end,
                                               isNap: isNap) {
                return existing
            }
            // A type-only edit (sleep <-> nap, identical window) is a label
            // decision, not new evidence. Routing it through the sensor-
            // coverage editor re-derives everything from RESIDENT sessions and
            // fails closed once the window's raw sessions rotate out — the user
            // saw "Couldn't save … less than 20 minutes of data" on a window
            // whose duration was already proven. Reclassify by cloning the
            // durable record instead; the window gate never applies.
            if Self.sleepReviewWindowIsUnchanged(night: night, start: start, end: end),
               isNap != night.isNapEvidence {
                return await reclassifyConfirmedSleepType(existing: existing, isNap: isNap)
            }
            return await adjustConfirmedSleepWindow(existing: existing,
                                              start: start,
                                              end: end,
                                              isNap: isNap,
                                              rest: rest)
        }
        if Self.sleepReviewSaveIsUnchanged(night: night,
                                           start: start,
                                           end: end,
                                           isNap: isNap) {
            return await confirmSleepHistoryNight(night, rest: rest, source: source)
        }
        return await adjustSleepNight(originalStart: night.start,
                                originalEnd: night.end,
                                newStart: start,
                                newEnd: end,
                                isNap: isNap,
                                rest: rest,
                                source: source)
    }

    nonisolated static func sleepReviewSaveIsUnchanged(
        night: SleepHistorySnapshot.Night,
        start: Date,
        end: Date,
        isNap: Bool,
        tolerance: TimeInterval = 1
    ) -> Bool {
        sleepReviewWindowIsUnchanged(night: night,
                                     start: start,
                                     end: end,
                                     tolerance: tolerance)
            && isNap == night.isNapEvidence
    }

    nonisolated static func sleepReviewWindowIsUnchanged(
        night: SleepHistorySnapshot.Night,
        start: Date,
        end: Date,
        tolerance: TimeInterval = 1
    ) -> Bool {
        guard let originalStart = night.start, let originalEnd = night.end else { return false }
        return abs(start.timeIntervalSince(originalStart)) <= tolerance
            && abs(end.timeIntervalSince(originalEnd)) <= tolerance
    }

    /// Reclassifies a confirmed record between sleep and nap without touching
    /// its window. The durable evidence (duration, span, stages, metrics,
    /// frozen need, time zone) is cloned verbatim — only the source (and
    /// therefore the derived ID) changes, so the sensor-coverage editor and its
    /// resident-session gate never run for a label-only decision.
    @discardableResult
    func reclassifyConfirmedSleepType(existing: UserConfirmedSleep,
                                      isNap: Bool) async -> UserConfirmedSleep? {
        let newSource = isNap ? "user_adjusted_nap" : "user_adjusted_sleep"
        guard newSource != existing.source else { return existing }
        let id = confirmedSleepID(start: existing.start,
                                  end: existing.end,
                                  source: newSource)
        let staged = UserConfirmedSleep(id: id,
                                        createdAt: Date(),
                                        start: existing.start,
                                        end: existing.end,
                                        source: newSource,
                                        confidence: existing.confidence,
                                        sessions: existing.sessions,
                                        samples: existing.samples,
                                        avgHR: existing.avgHR,
                                        peakHR: existing.peakHR,
                                        restingHR: existing.restingHR,
                                        hrv: existing.hrv,
                                        hrvWindowCount: existing.hrvWindowCount,
                                        respiratoryRate: existing.respiratoryRate,
                                        duration: existing.duration,
                                        span: existing.span,
                                        reason: "user_reclassified from \(existing.source)",
                                        motionSource: existing.motionSource,
                                        motionValidated: existing.motionValidated,
                                        stageSegments: existing.stageSegments,
                                        eventTimeZoneIdentifier: existing.eventTimeZoneIdentifier,
                                        sleepNeedSeconds: isNap ? nil : existing.sleepNeedSeconds,
                                        frozenSleepNeed: isNap ? nil : existing.frozenSleepNeed,
                                        // A nap can never be a day primary, and a
                                        // record newly promoted to a main must not
                                        // inherit a stale answer — the per-day
                                        // normalization and the choice prompt own
                                        // that decision.
                                        dayPrimaryChoice: nil)
        var remaining = cachedConfirmedSleeps.filter { $0.id != id && $0.id != existing.id }
        remaining.append(staged)
        guard await saveConfirmedSleeps(
            remaining,
            publishStressContext:
                Self.sleepStressContextAuthority(existing)
                    != Self.sleepStressContextAuthority(staged)
        ) else { return nil }
        refreshSleepSnapshotAfterCandidateSettlement()
        if autoSleepLoggedBanner?.sleepID == existing.id { autoSleepLoggedBanner = nil }
        AtriaDebugLog("ATRIADBG sleep_adjust status=reclassified id=%@ from=%@ to=%@ duration_s=%.0f",
                      staged.id,
                      existing.source,
                      newSource,
                      staged.duration)
        return staged
    }

    func latestSleepReviewNightForUI(rest: Int,
                                     calendar: Calendar = .current,
                                     source: String = "ui") -> SleepHistorySnapshot.Night? {
        guard case .ready(let night) = sleepReviewResolutionForUI(rest: rest,
                                                                 calendar: calendar,
                                                                 source: source) else {
            return nil
        }
        return night
    }

    /// Distinguishes a genuinely empty review result from a cache miss that is
    /// still being prepared. Notification routing needs this third state: a
    /// cold launch must not turn a pending sleep review into the generic Add
    /// Sleep sheet merely because the utility-worker projection has not
    /// published yet.
    func sleepReviewResolutionForUI(rest: Int,
                                    calendar: Calendar = .current,
                                    source: String = "ui") -> SleepReviewResolution {
        let requestedInputKey = makeSleepReviewCacheInputKey(rest: rest,
                                                             calendar: calendar)
        guard sleepReviewCacheInputKey == requestedInputKey else {
            scheduleSleepReviewCacheRefresh(rest: rest,
                                            calendar: calendar,
                                            reason: source)
            return .loading
        }
        return .ready(pendingSleepReviewNightForUI)
    }

    private func makeSleepReviewCacheInputKey(rest: Int,
                                              calendar: Calendar) -> SleepReviewCacheInputKey {
        SleepReviewCacheInputKey(canonicalSessionsRevision: reviewEvidenceRevision,
                                 confirmedSleepsRevision: confirmedSleepsRevision,
                                 sleepHistorySnapshotRevision: sleepHistorySnapshotRevision,
                                 activeJournalID: activeJournalSleepReviewIdentity.id,
                                 activeJournalEndFiveMinuteBucket: activeJournalSleepReviewIdentity.endFiveMinuteBucket,
                                 restingHR: rest,
                                 maxHR: profile.maxHR,
                                 calendarIdentifier: String(describing: calendar.identifier),
                                 timeZoneIdentifier: calendar.timeZone.identifier,
                                 secondsFromGMT: calendar.timeZone.secondsFromGMT())
    }

    private nonisolated static func makeSleepReviewCacheKey(
        input: SleepReviewCacheInputKey,
        activeJournalSession: SavedSession?
    ) -> SleepReviewCacheKey {
        SleepReviewCacheKey(canonicalSessionsRevision: input.canonicalSessionsRevision,
                            confirmedSleepsRevision: input.confirmedSleepsRevision,
                            sleepHistorySnapshotRevision: input.sleepHistorySnapshotRevision,
                            activeJournalID:
                                activeJournalSession?.id
                                    ?? input.activeJournalID,
                            activeJournalEndFiveMinuteBucket: activeJournalSession.map {
                                Int($0.end.timeIntervalSince1970 / (5 * 60))
                            } ?? input.activeJournalEndFiveMinuteBucket,
                            restingHR: input.restingHR,
                            maxHR: input.maxHR,
                            calendarIdentifier: input.calendarIdentifier,
                            timeZoneIdentifier: input.timeZoneIdentifier,
                            secondsFromGMT: input.secondsFromGMT)
    }

    private func invalidateSleepReviewCache(
        reason: String,
        scheduleRefresh: Bool = true
    ) {
        sleepReviewCacheGeneration &+= 1
        sleepReviewCacheKey = nil
        sleepReviewCacheInputKey = nil
        pendingSleepReviewCacheInputKey = nil
        pendingSleepReviewCacheGeneration = nil
        pendingSleepReviewProjectionCancellation?.cancel()
        pendingSleepReviewProjectionCancellation = nil
        pendingSleepReviewCacheWorkItem?.cancel()
        pendingSleepReviewCacheWorkItem = nil
        // Review actions must fail closed while the replacement is prepared.
        // Keeping the prior value visible could leave a just-confirmed or newly
        // overlapping sleep actionable for another frame.
        pendingSleepReviewNightForUI = nil
        napReviewCandidateNightsForUI = []
        if scheduleRefresh {
            scheduleSleepReviewCacheRefresh(
                rest: baseline.restingInt ?? 60,
                calendar: .current,
                reason: reason
            )
        }
    }

    /// Pure admission rule used by both production scheduling and exact tests.
    /// A matching published or pending input coalesces duplicate UI requests;
    /// an inactive process never starts this user-initiated projection.
    /// `backgroundResidentAdmission` is the throttled resident checkpoint's own
    /// authority, and the ONLY way this pipeline runs unattended.
    ///
    /// `runResidentSleepReviewRefreshIfUseful` was written specifically to catch
    /// a daytime nap while the app stays backgrounded — its own comment cites the
    /// on-device 2026-08-01 case of a 14:05-16:40 nap that "produced no detection
    /// at all while the app stayed backgrounded". It then routed into this gate,
    /// which requires BOTH the store-owned foreground authority and UIKit
    /// `.active`, neither of which a background checkpoint can satisfy. So the
    /// nap-catcher was a no-op in exactly the scenario it exists for, and the
    /// notification could not fire until the user opened the app (field report
    /// 2026-08-19, item 11 defect 2).
    ///
    /// The two foreground gates are kept for every UI-driven path: they close a
    /// real SwiftUI-scene/UIKit-state ABA race between an active UI request and a
    /// lifecycle callback. A throttled resident checkpoint is not a participant in
    /// that race — it has no UI request to interleave with — so admitting it does
    /// not reopen the race the authority was built to close.
    ///
    /// Unattended CPU stays bounded by the caller: the resident lane runs at most
    /// once per 15 minutes (`shouldAttemptResidentSleepReviewRefresh`), and the
    /// input-key dedupe below still refuses work when nothing changed.
    nonisolated static func shouldEnqueueSleepReviewProjection(
        hasForegroundAuthority: Bool,
        applicationIsActive: Bool,
        restoreInitializationBlocked: Bool,
        cacheMatchesInput: Bool,
        pendingMatchesInput: Bool,
        backgroundResidentAdmission: Bool = false
    ) -> Bool {
        let admitted = (hasForegroundAuthority && applicationIsActive)
            || backgroundResidentAdmission
        return admitted
            && !restoreInitializationBlocked
            && !cacheMatchesInput
            && !pendingMatchesInput
    }

    /// Only the throttled resident checkpoint may run this pipeline unattended.
    nonisolated static let residentSleepReviewRefreshReason = "resident_review_checkpoint"

    nonisolated static func sleepReviewProjectionBackgroundAdmission(
        reason: String,
        restoreInitializationBlocked: Bool
    ) -> Bool {
        reason == residentSleepReviewRefreshReason && !restoreInitializationBlocked
    }

    private static func sleepReviewApplicationStateLabel(
        _ state: UIApplication.State
    ) -> String {
        switch state {
        case .active: return "active"
        case .inactive: return "inactive"
        case .background: return "background"
        @unknown default: return "unknown"
        }
    }

    private func revokeSleepReviewProjection(
        reason: String,
        forceGenerationSupersession: Bool
    ) {
        // Revoke before inspecting pending state. A same-turn invalidation must
        // not start new work even if there was nothing to cancel.
        sleepReviewProjectionForegroundAuthority = false
        let hadPendingProjection = pendingSleepReviewCacheGeneration != nil
            || pendingSleepReviewCacheWorkItem != nil
            || pendingSleepReviewProjectionCancellation != nil
        guard hadPendingProjection || forceGenerationSupersession else {
            return
        }
        sleepReviewCacheGeneration &+= 1
        pendingSleepReviewProjectionCancellation?.cancel()
        pendingSleepReviewProjectionCancellation = nil
        pendingSleepReviewCacheWorkItem?.cancel()
        pendingSleepReviewCacheWorkItem = nil
        pendingSleepReviewCacheInputKey = nil
        pendingSleepReviewCacheGeneration = nil
        sleepReviewRefreshDeferredUntilForeground = true
        AtriaDebugLog(
            "ATRIADBG sleep_review_projection reason=%@ app_state=%@ generation=%d outcome=cancelled duration_ms=0 published=0",
            reason,
            Self.sleepReviewApplicationStateLabel(
                UIApplication.shared.applicationState
            ),
            sleepReviewCacheGeneration
        )
    }

    /// Revokes a projection before background maintenance starts. Generation
    /// supersession prevents a block already past its last cooperative check
    /// from publishing, while the cancellation token stops checked work at its
    /// next bounded checkpoint.
    func suspendSleepReviewProjectionForBackground(reason: String) {
        revokeSleepReviewProjection(
            reason: reason,
            forceGenerationSupersession: false
        )
    }

    /// Consumes one coalesced background invalidation. The scheduler's input
    /// key dedupe is the final authority, so an active UI request racing this
    /// lifecycle callback still produces exactly one latest-generation build.
    func resumeDeferredSleepReviewProjectionIfNeeded(reason: String) {
        guard !restoreInitializationBlocked,
              UIApplication.shared.applicationState == .active else { return }
        sleepReviewProjectionForegroundAuthority = true
        guard sleepReviewRefreshDeferredUntilForeground else { return }
        // A deadline records this exact input as fail-closed ready(nil) to stop
        // 20 ms/UI retry storms. A new active lifecycle is the authority to
        // clear that dedupe once and attempt the latest generation again.
        sleepReviewCacheKey = nil
        sleepReviewCacheInputKey = nil
        sleepReviewRefreshDeferredUntilForeground = false
        scheduleSleepReviewCacheRefresh(
            rest: baseline.restingInt ?? 60,
            calendar: .current,
            reason: reason
        )
    }

    /// Read-only notification lookup. In particular, a BGTask or a foreground
    /// notification task that outlives its scene may consume prepared truth but
    /// cannot start the UI projection lane.
    func preparedSleepReviewResolution(
        rest: Int,
        calendar: Calendar = .current
    ) -> SleepReviewResolution {
        let requestedInputKey = makeSleepReviewCacheInputKey(
            rest: rest,
            calendar: calendar
        )
        guard sleepReviewCacheInputKey == requestedInputKey else {
            return .loading
        }
        return .ready(pendingSleepReviewNightForUI)
    }

    /// Cold-launch/BG notification fallback for one already-qualified durable
    /// receipt. It never schedules projection work. A corrupt/implausibly huge
    /// authority archive fails closed before `load` can scan it unbounded.
    func persistedPendingSleepReviewForNotification(
        now: Date = Date(),
        defaults: UserDefaults = .standard
    ) -> SleepHistorySnapshot.Night? {
        guard !restoreInitializationBlocked,
              !Task.isCancelled,
              cachedConfirmedSleeps.count
                <= Self.sleepReviewMaximumNotificationAuthorityScanRows,
              dismissedSleepCandidates.count
                <= Self.sleepReviewMaximumNotificationAuthorityScanRows else {
            return nil
        }
        return AtriaPendingSleepReviewStore.load(
            now: now,
            confirmedSleeps: cachedConfirmedSleeps,
            dismissedCandidates: dismissedSleepCandidates,
            defaults: defaults
        )
    }

    private func scheduleSleepReviewCacheRefresh(rest: Int,
                                                 calendar: Calendar,
                                                 reason: String) {
        let requestedInputKey = makeSleepReviewCacheInputKey(rest: rest,
                                                             calendar: calendar)
        let applicationState = UIApplication.shared.applicationState
        let applicationIsActive = applicationState == .active
        let applicationStateLabel = Self.sleepReviewApplicationStateLabel(
            applicationState
        )
        let backgroundResidentAdmission = Self.sleepReviewProjectionBackgroundAdmission(
            reason: reason,
            restoreInitializationBlocked: restoreInitializationBlocked
        )
        guard Self.shouldEnqueueSleepReviewProjection(
            hasForegroundAuthority:
                sleepReviewProjectionForegroundAuthority,
            applicationIsActive: applicationIsActive,
            restoreInitializationBlocked: restoreInitializationBlocked,
            cacheMatchesInput: sleepReviewCacheInputKey == requestedInputKey,
            pendingMatchesInput:
                pendingSleepReviewCacheInputKey == requestedInputKey,
            backgroundResidentAdmission: backgroundResidentAdmission
        ) else {
            if (!sleepReviewProjectionForegroundAuthority
                || !applicationIsActive
                || restoreInitializationBlocked),
               !backgroundResidentAdmission,
               sleepReviewCacheInputKey != requestedInputKey {
                sleepReviewRefreshDeferredUntilForeground = true
                AtriaDebugLog(
                    "ATRIADBG sleep_review_projection reason=%@ app_state=%@ generation=%d outcome=deferred duration_ms=0 published=0",
                    reason,
                    applicationStateLabel,
                    sleepReviewCacheGeneration
                )
            }
            return
        }

        sleepReviewCacheGeneration &+= 1
        sleepReviewRefreshDeferredUntilForeground = false
        let generation = sleepReviewCacheGeneration
        pendingSleepReviewProjectionCancellation?.cancel()
        pendingSleepReviewCacheWorkItem?.cancel()
        let cancellation = AtriaSleepReviewProjectionCancellation()
        let canonicalSessions = cachedCanonicalSessions
        let confirmedSleeps = cachedConfirmedSleeps
        let dismissedCandidates = dismissedSleepCandidates
        let snapshot = sleepHistorySnapshot
        let maxHR = profile.maxHR
        // Handoff-11: durable pending-review records name their source strap;
        // a re-pair must invalidate them at load. Identity only — no BLE work.
        let persistedStrapIdentifier = AtriaWhoop4MotionTickDailyStore
            .persistedStrapIdentifiers()
            .first
        let preparedAt = Date()
        let startedAt = DispatchTime.now().uptimeNanoseconds
        let budgetNanoseconds = UInt64(
            Self.sleepReviewProjectionDeadlineSeconds * 1_000_000_000
        )
        let deadlineUptime = startedAt.addingReportingOverflow(
            budgetNanoseconds
        ).partialValue
        let cooperativeDeadline = AtriaSleepSettlementDeadline(
            uptimeNanoseconds: deadlineUptime,
            monotonicNow: {
                cancellation.isCancelled
                    ? UInt64.max
                    : DispatchTime.now().uptimeNanoseconds
            }
        )
        let workItem = DispatchWorkItem { [weak self] in
            let requestedKey: SleepReviewCacheKey
            let freshlyQualified: SleepHistorySnapshot.Night?
            let result: SleepHistorySnapshot.Night?
            let napReviewNights: [SleepHistorySnapshot.Night]
            do {
                try cooperativeDeadline.checkpoint()
                // Never reconstruct the resident journal from its potentially
                // 24 MiB segment chain here. The incremental writer maintains
                // an exact same-process COW cache; consume that value through
                // the checked latest-night row caps, or fail closed if cold.
                let activeJournalSession = try SessionStore
                    .loadCachedResidentJournalSessionForSleepReview(
                        now: preparedAt,
                        cooperativeDeadline: cooperativeDeadline
                    )
                requestedKey = SessionStore.makeSleepReviewCacheKey(
                    input: requestedInputKey,
                    activeJournalSession: activeJournalSession
                )
                let residentSources = try SessionStore
                    .sleepReviewSourceSessions(
                        canonicalSessions: canonicalSessions,
                        activeJournalSession: activeJournalSession,
                        cooperativeDeadline: cooperativeDeadline
                    )
                let sourceSessions: [SavedSession]
                switch SessionStore.compactLatestNightSessionSlice(
                    from: residentSources,
                    now: preparedAt,
                    deadlineUptimeNanoseconds: deadlineUptime,
                    cooperativeDeadline: cooperativeDeadline,
                    preserveAttachedMotion: true
                ) {
                case .success(let slice):
                    sourceSessions = slice.sessions
                case .failure(.noRecentSessions):
                    sourceSessions = []
                case .failure:
                    throw AtriaSleepSettlementAbort.deadlineExceeded
                }
                try cooperativeDeadline.checkpoint()
                let projection = try SessionStore
                    .makeBoundedSleepReviewCacheProjection(
                        snapshot: snapshot,
                        canonicalSessions: sourceSessions,
                        confirmedSleeps: confirmedSleeps,
                        dismissedCandidates: dismissedCandidates,
                        rest: rest,
                        maxHR: maxHR,
                        calendar: calendar,
                        cooperativeDeadline: cooperativeDeadline
                )
                freshlyQualified = projection.main
                try cooperativeDeadline.checkpoint()
                let durablePending: SleepHistorySnapshot.Night?
                if projection.main == nil,
                   confirmedSleeps.count
                        <= SessionStore
                            .sleepReviewMaximumNotificationAuthorityScanRows,
                   dismissedCandidates.count
                        <= SessionStore
                            .sleepReviewMaximumNotificationAuthorityScanRows {
                    durablePending = AtriaPendingSleepReviewStore.load(
                        now: preparedAt,
                        confirmedSleeps: confirmedSleeps,
                        dismissedCandidates: dismissedCandidates,
                        currentStrapIdentifier: persistedStrapIdentifier
                    )
                } else {
                    durablePending = nil
                }
                result = projection.main ?? durablePending
                napReviewNights = projection.naps
                try cooperativeDeadline.checkpoint()
            } catch {
                let wasCancelled = cancellation.isCancelled
                let durationMilliseconds = Int(
                    (DispatchTime.now().uptimeNanoseconds - startedAt)
                        / 1_000_000
                )
                DispatchQueue.main.async { [weak self] in
                    let outcome = wasCancelled ? "cancelled" : "deadline"
                    AtriaDebugLog(
                        "ATRIADBG sleep_review_projection reason=%@ app_state=%@ generation=%d outcome=%@ duration_ms=%d published=0",
                        reason,
                        Self.sleepReviewApplicationStateLabel(
                            UIApplication.shared.applicationState
                        ),
                        generation,
                        outcome,
                        durationMilliseconds
                    )
                    guard let self,
                          self.pendingSleepReviewCacheGeneration == generation,
                          self.sleepReviewCacheGeneration == generation else {
                        return
                    }
                    self.pendingSleepReviewCacheInputKey = nil
                    self.pendingSleepReviewCacheGeneration = nil
                    self.pendingSleepReviewCacheWorkItem = nil
                    self.pendingSleepReviewProjectionCancellation = nil
                    guard !wasCancelled else { return }
                    // A deadline is uncertainty, never permission to surface or
                    // notify. Resolve this exact input as fail-closed until new
                    // evidence or an explicit invalidation advances the key.
                    self.sleepReviewCacheKey = nil
                    self.sleepReviewCacheInputKey = requestedInputKey
                    self.pendingSleepReviewNightForUI = nil
                    self.napReviewCandidateNightsForUI = []
                    // No immediate retry loop: one future active lifecycle edge
                    // (or an explicit invalidation that advances truth) may try
                    // this latest input again.
                    self.sleepReviewRefreshDeferredUntilForeground = true
                    AtriaDebugLog(
                        "ATRIADBG sleep_review_cache status=withheld reason=deadline generation=%d",
                        generation
                    )
                }
                return
            }
            let durationMilliseconds = Int(
                (DispatchTime.now().uptimeNanoseconds - startedAt) / 1_000_000
            )
            DispatchQueue.main.async { [weak self] in
                guard let self else { return }
                let applicationIsActive =
                    UIApplication.shared.applicationState == .active
                guard SessionStore.shouldPublishSleepReviewProjection(
                    isCancelled: cancellation.isCancelled,
                    completedGeneration: generation,
                    currentGeneration: self.sleepReviewCacheGeneration,
                    pendingGenerationMatches:
                        self.pendingSleepReviewCacheGeneration == generation,
                    hasForegroundAuthority:
                        self.sleepReviewProjectionForegroundAuthority,
                    applicationIsActive: applicationIsActive,
                    restoreInitializationBlocked:
                        self.restoreInitializationBlocked
                ) else {
                    // Never self-reschedule a stale/cancelled completion. A
                    // newer foreground request or the deferred lifecycle edge
                    // is the sole authority for another build.
                    if self.pendingSleepReviewCacheGeneration == generation {
                        self.pendingSleepReviewCacheInputKey = nil
                        self.pendingSleepReviewCacheGeneration = nil
                        self.pendingSleepReviewCacheWorkItem = nil
                        self.pendingSleepReviewProjectionCancellation = nil
                    }
                    if !self.sleepReviewProjectionForegroundAuthority
                        || !applicationIsActive
                        || self.restoreInitializationBlocked {
                        self.sleepReviewRefreshDeferredUntilForeground = true
                    }
                    AtriaDebugLog(
                        "ATRIADBG sleep_review_projection reason=%@ app_state=%@ generation=%d outcome=cancelled duration_ms=%d published=0",
                        reason,
                        Self.sleepReviewApplicationStateLabel(
                            UIApplication.shared.applicationState
                        ),
                        generation,
                        durationMilliseconds
                    )
                    return
                }
                if let freshlyQualified {
                    AtriaPendingSleepReviewStore.save(
                        freshlyQualified,
                        now: preparedAt
                    )
                }
                self.sleepReviewCacheKey = requestedKey
                self.sleepReviewCacheInputKey = requestedInputKey
                self.pendingSleepReviewNightForUI = result
                self.refreshPendingSameDayMainSleepChoice()
                self.napReviewCandidateNightsForUI = napReviewNights
                self.pendingSleepReviewCacheInputKey = nil
                self.pendingSleepReviewCacheGeneration = nil
                self.pendingSleepReviewCacheWorkItem = nil
                self.pendingSleepReviewProjectionCancellation = nil
                AtriaDebugLog("ATRIADBG sleep_review_cache status=published reason=%@ generation=%d has_candidate=%d",
                              reason,
                              generation,
                              result == nil ? 0 : 1)
                AtriaDebugLog(
                    "ATRIADBG sleep_review_projection reason=%@ app_state=%@ generation=%d outcome=completed duration_ms=%d published=1",
                    reason,
                    Self.sleepReviewApplicationStateLabel(
                        UIApplication.shared.applicationState
                    ),
                    generation,
                    durationMilliseconds
                )
            }
        }
        pendingSleepReviewCacheInputKey = requestedInputKey
        pendingSleepReviewCacheGeneration = generation
        pendingSleepReviewCacheWorkItem = workItem
        pendingSleepReviewProjectionCancellation = cancellation
        AtriaDebugLog(
            "ATRIADBG sleep_review_projection reason=%@ app_state=%@ generation=%d outcome=started duration_ms=0 published=0",
            reason,
            applicationStateLabel,
            generation
        )
        sleepReviewProjectionQueue.async(execute: workItem)
    }

    /// One checked candidate aggregation feeds both the main review card and
    /// nap rows. The entire projection shares the caller's absolute deadline;
    /// no second aggregate replay can restart the budget.
    nonisolated static func makeBoundedSleepReviewCacheProjection(
        snapshot: SleepHistorySnapshot,
        canonicalSessions: [SavedSession],
        confirmedSleeps: [UserConfirmedSleep],
        dismissedCandidates: [AtriaDismissedSleepCandidate] = [],
        rest: Int,
        maxHR: Int,
        calendar: Calendar = .current,
        cooperativeDeadline: AtriaSleepSettlementDeadline,
        mainStageInvocationCounter:
            AtriaSleepReviewStageInvocationCounter? = nil
    ) throws -> (
        main: SleepHistorySnapshot.Night?,
        naps: [SleepHistorySnapshot.Night]
    ) {
        try cooperativeDeadline.checkpoint()
        let candidates = try aggregateSleepCandidates(
            in: canonicalSessions,
            rest: rest,
            maxHR: maxHR,
            calendar: calendar,
            // `.boundedRecent` may synchronously decode an 8 MiB JSONL motion
            // shard outside the cooperative deadline. The bounded review lane
            // uses only motion already attached to/session-summarized in its
            // immutable input; full archive settlement remains separately
            // leased and receipt-bound.
            historicalMotionPolicy: .attachedCompactOnly,
            cooperativeDeadline: cooperativeDeadline,
            includeResumedReviewCandidates: true
        )
        try cooperativeDeadline.checkpoint()
        let authorities = try boundedSleepReviewAuthorities(
            snapshot: snapshot,
            canonicalSessions: canonicalSessions,
            candidates: candidates,
            confirmedSleeps: confirmedSleeps,
            dismissedCandidates: dismissedCandidates,
            cooperativeDeadline: cooperativeDeadline
        )
        let main = try makeSleepReviewNightForCacheCore(
            snapshot: snapshot,
            canonicalSessions: canonicalSessions,
            confirmedSleeps: authorities.confirmedSleeps,
            dismissedCandidates: authorities.dismissedCandidates,
            rest: rest,
            maxHR: maxHR,
            calendar: calendar,
            precomputedCandidates: candidates,
            cooperativeDeadline: cooperativeDeadline,
            stageInvocationCounter: mainStageInvocationCounter
        )
        let naps = try makeNapReviewNightsForCacheCore(
            canonicalSessions: canonicalSessions,
            confirmedSleeps: authorities.confirmedSleeps,
            dismissedCandidates: authorities.dismissedCandidates,
            rest: rest,
            maxHR: maxHR,
            calendar: calendar,
            precomputedCandidates: candidates,
            cooperativeDeadline: cooperativeDeadline
        )
        try cooperativeDeadline.checkpoint()
        return (main, naps)
    }

    /// Confirmations and dismissals are durable authority, so an overlap may
    /// never be silently truncated. Filter them to the already-bounded review
    /// horizon with cooperative checks; an implausibly dense authority set
    /// fails closed rather than entering repeated unbounded `contains` scans.
    nonisolated static func boundedSleepReviewAuthorities(
        snapshot: SleepHistorySnapshot,
        canonicalSessions: [SavedSession],
        candidates: [AggregateSleepCandidate],
        confirmedSleeps: [UserConfirmedSleep],
        dismissedCandidates: [AtriaDismissedSleepCandidate],
        cooperativeDeadline: AtriaSleepSettlementDeadline
    ) throws -> (
        confirmedSleeps: [UserConfirmedSleep],
        dismissedCandidates: [AtriaDismissedSleepCandidate]
    ) {
        var reviewStart: Date?
        var reviewEnd: Date?
        func include(start: Date, end: Date) {
            guard end > start else { return }
            reviewStart = min(reviewStart ?? start, start)
            reviewEnd = max(reviewEnd ?? end, end)
        }
        for (index, session) in canonicalSessions.enumerated() {
            if index.isMultiple(of: 64) {
                try cooperativeDeadline.checkpoint()
            }
            include(start: session.start, end: session.end)
        }
        for (index, candidate) in candidates.enumerated() {
            if index.isMultiple(of: 64) {
                try cooperativeDeadline.checkpoint()
            }
            include(start: candidate.start, end: candidate.end)
        }
        for (index, night) in snapshot.nights.enumerated() {
            if index.isMultiple(of: 16) {
                try cooperativeDeadline.checkpoint()
            }
            if !night.confirmed, let start = night.start, let end = night.end {
                include(start: start, end: end)
            }
        }
        guard let reviewStart, let reviewEnd else {
            return ([], [])
        }

        var boundedConfirmed: [UserConfirmedSleep] = []
        boundedConfirmed.reserveCapacity(min(
            confirmedSleeps.count,
            sleepReviewMaximumRelevantAuthorityRows
        ))
        for (index, sleep) in confirmedSleeps.enumerated() {
            if index.isMultiple(of: 64) {
                try cooperativeDeadline.checkpoint()
            }
            guard sleep.end > reviewStart, sleep.start < reviewEnd else {
                continue
            }
            guard boundedConfirmed.count
                    < sleepReviewMaximumRelevantAuthorityRows else {
                throw AtriaSleepSettlementAbort.deadlineExceeded
            }
            boundedConfirmed.append(sleep)
        }

        var boundedDismissed: [AtriaDismissedSleepCandidate] = []
        boundedDismissed.reserveCapacity(min(
            dismissedCandidates.count,
            sleepReviewMaximumRelevantAuthorityRows
        ))
        for (index, dismissal) in dismissedCandidates.enumerated() {
            if index.isMultiple(of: 64) {
                try cooperativeDeadline.checkpoint()
            }
            guard dismissal.end > reviewStart,
                  dismissal.start < reviewEnd else { continue }
            guard boundedDismissed.count
                    < sleepReviewMaximumRelevantAuthorityRows else {
                throw AtriaSleepSettlementAbort.deadlineExceeded
            }
            boundedDismissed.append(dismissal)
        }
        try cooperativeDeadline.checkpoint()
        return (boundedConfirmed, boundedDismissed)
    }

    nonisolated static func makeSleepReviewNightForCache(snapshot: SleepHistorySnapshot,
                                                         canonicalSessions: [SavedSession],
                                                         confirmedSleeps: [UserConfirmedSleep],
                                                         dismissedCandidates: [AtriaDismissedSleepCandidate] = [],
                                                         rest: Int,
                                                         maxHR: Int,
                                                         calendar: Calendar = .current) -> SleepHistorySnapshot.Night? {
        try? makeSleepReviewNightForCacheCore(
            snapshot: snapshot,
            canonicalSessions: canonicalSessions,
            confirmedSleeps: confirmedSleeps,
            dismissedCandidates: dismissedCandidates,
            rest: rest,
            maxHR: maxHR,
            calendar: calendar,
            precomputedCandidates: nil,
            cooperativeDeadline: nil,
            stageInvocationCounter: nil
        )
    }

    private nonisolated static func makeSleepReviewNightForCacheCore(
        snapshot: SleepHistorySnapshot,
        canonicalSessions: [SavedSession],
        confirmedSleeps: [UserConfirmedSleep],
        dismissedCandidates: [AtriaDismissedSleepCandidate],
        rest: Int,
        maxHR: Int,
        calendar: Calendar,
        precomputedCandidates: [AggregateSleepCandidate]?,
        cooperativeDeadline: AtriaSleepSettlementDeadline?,
        stageInvocationCounter: AtriaSleepReviewStageInvocationCounter?
    ) throws -> SleepHistorySnapshot.Night? {
        try cooperativeDeadline?.checkpoint()
        let physiologicalDraft = try physiologicalSleepReviewNightDraftCore(
            in: canonicalSessions,
            confirmedSleeps: confirmedSleeps,
            dismissedCandidates: dismissedCandidates,
            rest: rest,
            calendar: calendar,
            cooperativeDeadline: cooperativeDeadline
        )
        if physiologicalDraft != nil {
            stageInvocationCounter?.recordPhysiologicalDraft()
        }
        let candidates: [AggregateSleepCandidate]
        if let precomputedCandidates {
            candidates = precomputedCandidates
        } else if let cooperativeDeadline {
            candidates = try aggregateSleepCandidates(
                in: canonicalSessions,
                rest: rest,
                maxHR: maxHR,
                calendar: calendar,
                historicalMotionPolicy: .boundedRecent,
                cooperativeDeadline: cooperativeDeadline,
                includeResumedReviewCandidates: true
            )
        } else {
            candidates = aggregateSleepCandidates(
                in: canonicalSessions,
                rest: rest,
                maxHR: maxHR,
                calendar: calendar,
                historicalMotionPolicy: .boundedRecent
            )
        }
        try cooperativeDeadline?.checkpoint()
        func isUnsettled(_ candidate: AggregateSleepCandidate) -> Bool {
            let overlapsConfirmed = confirmedSleeps.contains {
                sleepWindowsOverlap($0, candidate: candidate)
            }
            let isReviewableExtension = sleepReviewExtensionTarget(
                existing: confirmedSleeps,
                candidateStart: candidate.start,
                candidateEnd: candidate.end,
                candidateDuration: candidate.duration,
                isNap: candidate.kind == "nap_candidate"
            ) != nil
            let dismissed = dismissedCandidates.contains {
                $0.suppresses(start: candidate.start, end: candidate.end)
            }
            return (!overlapsConfirmed || isReviewableExtension) && !dismissed
        }
        let preferredCandidate = preferredSleepCandidateForReview(from: candidates)
        let aggregateCandidate: AggregateSleepCandidate?
        if let preferredCandidate, isUnsettled(preferredCandidate) {
            aggregateCandidate = preferredCandidate
        } else if let preferredCandidate,
                  confirmedSleeps.contains(where: {
                      sleepWindowsOverlap($0, candidate: preferredCandidate)
                  }) {
            // A settled main must suppress ordinary older fallbacks, but it
            // may unlock exactly one distinct, same-cycle later review — for
            // example a dense-morning HR-only sleep whose kind is
            // "overnight_sleep", not just a "resumed_sleep_candidate". This
            // preserves the one-card ordering contract (still one candidate via
            // preferredSleepCandidateForReview) without allowing a confirmed
            // newest night to reveal stale older nights. Confirmation
            // deliberately dismisses the main detector window, so that
            // dismissal is proof of settlement here, not a reason to hide a
            // separate later segment. `isUnsettled` below already excludes any
            // candidate overlapping a confirmed sleep (except a reviewable
            // extension), so the confirmed primary's own window cannot resurface
            // and each candidate still honors its own dismissal. Match the
            // dismissed-main branch below exactly, dropping the kind restriction.
            aggregateCandidate = preferredSleepCandidateForReview(
                from: candidates.filter {
                    $0.day == preferredCandidate.day
                        && isUnsettled($0)
                }
            )
        } else if let preferredCandidate {
            // The preferred main was settled by DISMISSAL alone — no
            // confirmed sleep overlaps it. A dismissal is the user's verdict
            // on that exact window, not on the whole day: physical 2026-07-31
            // evidence showed an HR-only overnight aggregate whose start was
            // pinned to strap re-wear (20:47) being dismissed as mis-bounded,
            // after which this branch hid the genuinely distinct late-morning
            // resumed sleep and the day lost all sleep, HRV and recovery
            // evidence. Fall back to the best still-unsettled candidate of
            // the same day. Every candidate here re-passes `isUnsettled`, so
            // the rejected window itself (or anything ≥70% overlapping it)
            // cannot resurface, and older days stay hidden.
            aggregateCandidate = preferredSleepCandidateForReview(
                from: candidates.filter {
                    $0.day == preferredCandidate.day && isUnsettled($0)
                }
            )
        } else {
            aggregateCandidate = nil
        }
        let aggregateDraft: AtriaSleepReviewDraft?
        if let candidate = aggregateCandidate {
            try cooperativeDeadline?.checkpoint()
            let source = sleepReviewCandidateSource(for: candidate)
            let metrics: (sessions: Int, samples: Int, avgHR: Int,
                          peakHR: Int, restingHR: Int, hrv: Int?,
                          hrvWindowCount: Int)
            if let cooperativeDeadline {
                metrics = try confirmedSleepWindowMetrics(
                    from: canonicalSessions,
                    start: candidate.start,
                    end: candidate.end,
                    rest: candidate.restingHR,
                    cooperativeDeadline: cooperativeDeadline
                )
            } else {
                metrics = confirmedSleepWindowMetrics(
                    from: canonicalSessions,
                    start: candidate.start,
                    end: candidate.end,
                    rest: candidate.restingHR
                )
            }
            let respiratoryRate: Double?
            if let cooperativeDeadline {
                let respiratoryDeadline = cooperativeDeadline.capped(
                    afterNanoseconds:
                        sleepReviewRespiratoryBudgetNanoseconds
                )
                respiratoryRate = try? confirmedSleepRespiratoryRate(
                    from: canonicalSessions,
                    start: candidate.start,
                    end: candidate.end,
                    cooperativeDeadline: respiratoryDeadline
                )
                try cooperativeDeadline.checkpoint()
            } else {
                respiratoryRate = confirmedSleepRespiratoryRate(
                    from: canonicalSessions,
                    start: candidate.start,
                    end: candidate.end
                )
            }
            let sleepEfficiency = candidate.span > 0
                ? min(max(candidate.duration / candidate.span, 0), 1)
                : nil
            aggregateDraft = AtriaSleepReviewDraft(
                night: SleepHistorySnapshot.Night(
                    id: "sleep-review-\(Int(candidate.start.timeIntervalSince1970))-\(Int(candidate.end.timeIntervalSince1970))-\(source)",
                    day: candidate.day,
                    start: candidate.start,
                    end: candidate.end,
                    duration: candidate.duration,
                    restingHR: candidate.restingHR > 0
                        ? candidate.restingHR
                        : nil,
                    hrv: metrics.hrv,
                    hrvWindowCount: metrics.hrvWindowCount,
                    respiratoryRate: respiratoryRate,
                    sleepEfficiency: sleepEfficiency,
                    confidence: candidate.motionEvidenceValidated
                        ? candidate.confidence.rawValue
                        : "review_needed",
                    source: source,
                    confirmed: false,
                    stageSegments: [],
                    motionValidated: candidate.motionEvidenceValidated
                ),
                stageRecipe: AtriaSleepReviewStageRecipe(
                    start: candidate.start,
                    end: candidate.end,
                    restingHR: candidate.restingHR,
                    isNap: candidate.kind == "nap_candidate",
                    motionValidated: candidate.motionEvidenceValidated
                )
            )
        } else {
            aggregateDraft = nil
        }
        let aggregateReview = aggregateDraft?.night
        let physiologicalReview = physiologicalDraft?.night

        func materializeFreshReview(
            _ draft: AtriaSleepReviewDraft
        ) throws -> SleepHistorySnapshot.Night {
            try materializeSleepReviewDraft(
                draft,
                from: canonicalSessions,
                maximumRows: cooperativeDeadline == nil
                    ? nil
                    : sleepReviewMaximumStagingRows,
                cooperativeDeadline: cooperativeDeadline,
                invocationCounter: stageInvocationCounter
            )
        }

        func materializePreferredFreshReview() throws
            -> SleepHistorySnapshot.Night? {
            if let aggregateDraft {
                return try materializeFreshReview(aggregateDraft)
            }
            if let physiologicalDraft {
                return try materializeFreshReview(physiologicalDraft)
            }
            return nil
        }
        if let latest = snapshot.latest,
           latest.confirmed == false,
           let start = latest.start,
           let end = latest.end,
           (!confirmedSleeps.contains(where: { $0.end > start && $0.start < end })
            || sleepReviewExtensionTarget(existing: confirmedSleeps,
                                          candidateStart: start,
                                          candidateEnd: end,
                                          candidateDuration: latest.duration,
                                          isNap: latest.isNapEvidence) != nil),
           !dismissedCandidates.contains(where: { $0.suppresses(start: start, end: end) }) {
            // Daily rollups are intentionally cheap and can include a long,
            // quiet awake lead-in or stop at a BLE gap. Prefer the robust
            // five-minute physiological bout when it materially trims or
            // extends that provisional window. This remains review-only.
            if let replacement = preferredGrowingSleepReview(
                replacing: latest,
                with: [aggregateReview, physiologicalReview].compactMap { $0 },
                calendar: calendar
            ) {
                if let aggregateDraft,
                   replacement.id == aggregateDraft.night.id {
                    return try materializeFreshReview(aggregateDraft)
                }
                if let physiologicalDraft,
                   replacement.id == physiologicalDraft.night.id {
                    return try materializeFreshReview(physiologicalDraft)
                }
                return replacement
            }
            // A cached main-sleep review remains useful until newer evidence
            // refines its boundary. A cached nap is different: it is a short,
            // daytime claim that can be indistinguishable from quiet awake
            // time after a cache survives a reconnect or aggregate refresh.
            // Only carry it forward when this fresh pass independently finds
            // an overlapping, motion-validated nap from the strap evidence.
            // Do not treat HR-only aggregate candidates or an old snapshot's
            // own confidence/source as that confirmation.
            if latest.isNapEvidence {
                let freshValidatedNapOverlaps = candidates.contains { candidate in
                    candidate.kind == "nap_candidate"
                        && candidate.motionEvidenceValidated
                        && candidate.start < end
                        && candidate.end > start
                }
                guard freshValidatedNapOverlaps else {
                    return try materializePreferredFreshReview()
                }
            }
            return latest
        }
        try cooperativeDeadline?.checkpoint()
        return try materializePreferredFreshReview()
    }

    /// Every review-worthy daytime nap candidate, as unconfirmed nap `Night`s
    /// for the detections list (2026-08-01). Unlike `makeSleepReviewNightForCache`
    /// — which surfaces exactly one main-sleep-biased card — a genuine nap must
    /// keep its own reviewable row even when a same-day main sleep is already
    /// confirmed. Real data only: sourced from the same aggregate detector, not
    /// fabricated. HR-only naps (no validated motion) still surface because naps
    /// are review-only; they carry a `review_needed` confidence and read as a
    /// nap. Confirmed/dismissed windows are excluded so a dismissed nap stays
    /// gone and a confirmed nap never duplicates. These rows never auto-confirm.
    nonisolated static func makeNapReviewNightsForCache(
        canonicalSessions: [SavedSession],
        confirmedSleeps: [UserConfirmedSleep],
        dismissedCandidates: [AtriaDismissedSleepCandidate] = [],
        rest: Int,
        maxHR: Int,
        calendar: Calendar = .current
    ) -> [SleepHistorySnapshot.Night] {
        (try? makeNapReviewNightsForCacheCore(
            canonicalSessions: canonicalSessions,
            confirmedSleeps: confirmedSleeps,
            dismissedCandidates: dismissedCandidates,
            rest: rest,
            maxHR: maxHR,
            calendar: calendar,
            precomputedCandidates: nil,
            cooperativeDeadline: nil
        )) ?? []
    }

    private nonisolated static func makeNapReviewNightsForCacheCore(
        canonicalSessions: [SavedSession],
        confirmedSleeps: [UserConfirmedSleep],
        dismissedCandidates: [AtriaDismissedSleepCandidate],
        rest: Int,
        maxHR: Int,
        calendar: Calendar,
        precomputedCandidates: [AggregateSleepCandidate]?,
        cooperativeDeadline: AtriaSleepSettlementDeadline?
    ) throws -> [SleepHistorySnapshot.Night] {
        let candidates: [AggregateSleepCandidate]
        if let precomputedCandidates {
            candidates = precomputedCandidates
        } else if let cooperativeDeadline {
            candidates = try aggregateSleepCandidates(
                in: canonicalSessions,
                rest: rest,
                maxHR: maxHR,
                calendar: calendar,
                historicalMotionPolicy: .boundedRecent,
                cooperativeDeadline: cooperativeDeadline,
                includeResumedReviewCandidates: true
            )
        } else {
            candidates = aggregateSleepCandidates(
                in: canonicalSessions,
                rest: rest,
                maxHR: maxHR,
                calendar: calendar,
                historicalMotionPolicy: .boundedRecent
            )
        }
        var nights: [SleepHistorySnapshot.Night] = []
        for candidate in candidates {
            try cooperativeDeadline?.checkpoint()
            guard candidate.kind == "nap_candidate",
                  isReviewWorthySleepCandidate(candidate) else { continue }
            let overlapsConfirmed = confirmedSleeps.contains {
                sleepWindowsOverlap($0, candidate: candidate)
            }
            let dismissed = dismissedCandidates.contains {
                $0.suppresses(start: candidate.start, end: candidate.end)
            }
            guard !overlapsConfirmed, !dismissed else { continue }
            let metrics: (sessions: Int, samples: Int, avgHR: Int,
                          peakHR: Int, restingHR: Int, hrv: Int?,
                          hrvWindowCount: Int)
            if let cooperativeDeadline {
                metrics = try confirmedSleepWindowMetrics(
                    from: canonicalSessions,
                    start: candidate.start,
                    end: candidate.end,
                    rest: candidate.restingHR,
                    cooperativeDeadline: cooperativeDeadline
                )
            } else {
                metrics = confirmedSleepWindowMetrics(
                    from: canonicalSessions,
                    start: candidate.start,
                    end: candidate.end,
                    rest: candidate.restingHR
                )
            }
            let respiratoryRate: Double?
            let stageSegments: [SleepStageSegment]
            if let cooperativeDeadline {
                let respiratoryDeadline = cooperativeDeadline.capped(
                    afterNanoseconds:
                        sleepReviewRespiratoryBudgetNanoseconds
                )
                respiratoryRate = try? confirmedSleepRespiratoryRate(
                    from: canonicalSessions,
                    start: candidate.start,
                    end: candidate.end,
                    cooperativeDeadline: respiratoryDeadline
                )
                try cooperativeDeadline.checkpoint()
                stageSegments = try sleepStageResearchSegments(
                    from: canonicalSessions,
                    start: candidate.start,
                    end: candidate.end,
                    restingHR: candidate.restingHR,
                    isNap: true,
                    motionValidated: candidate.motionEvidenceValidated,
                    maximumRows: sleepReviewMaximumStagingRows,
                    cooperativeDeadline: cooperativeDeadline
                )
            } else {
                respiratoryRate = confirmedSleepRespiratoryRate(
                    from: canonicalSessions,
                    start: candidate.start,
                    end: candidate.end
                )
                stageSegments = sleepStageResearchSegments(
                    from: canonicalSessions,
                    start: candidate.start,
                    end: candidate.end,
                    restingHR: candidate.restingHR,
                    isNap: true,
                    motionValidated: candidate.motionEvidenceValidated
                )
            }
            let sleepEfficiency = candidate.span > 0
                ? min(max(candidate.duration / candidate.span, 0), 1)
                : nil
            nights.append(SleepHistorySnapshot.Night(
                id: "nap-review-\(Int(candidate.start.timeIntervalSince1970))-\(Int(candidate.end.timeIntervalSince1970))",
                day: candidate.day,
                start: candidate.start,
                end: candidate.end,
                duration: candidate.duration,
                restingHR: candidate.restingHR > 0 ? candidate.restingHR : nil,
                hrv: metrics.hrv,
                hrvWindowCount: metrics.hrvWindowCount,
                respiratoryRate: respiratoryRate,
                sleepEfficiency: sleepEfficiency,
                confidence: candidate.motionEvidenceValidated ? candidate.confidence.rawValue : "review_needed",
                source: "nap_candidate",
                confirmed: false,
                stageSegments: stageSegments,
                motionValidated: candidate.motionEvidenceValidated
            ))
        }
        try cooperativeDeadline?.checkpoint()
        return nights.sorted { ($0.start ?? $0.day) > ($1.start ?? $1.day) }
    }

    /// A provisional daily-rollup candidate is a snapshot, not an immutable
    /// wake boundary. Replace it only with overlapping/same-day evidence that
    /// materially trims a quiet-awake lead-in or extends at least 30 minutes
    /// past the first wake. This changes review presentation only; the returned
    /// night remains unconfirmed and still traverses the existing save gates.
    nonisolated static func preferredGrowingSleepReview(
        replacing current: SleepHistorySnapshot.Night,
        with replacements: [SleepHistorySnapshot.Night],
        calendar: Calendar = .current,
        materialBoundaryChange: TimeInterval = 30 * 60,
        maximumSameEpisodeGap: TimeInterval = 2 * 60 * 60
    ) -> SleepHistorySnapshot.Night? {
        _ = calendar
        guard !current.confirmed,
              let currentStart = current.start,
              let currentEnd = current.end else { return nil }
        return replacements
            .filter { replacement in
                guard !replacement.confirmed,
                      let start = replacement.start,
                      let end = replacement.end,
                      end > start,
                      start <= currentEnd.addingTimeInterval(maximumSameEpisodeGap),
                      currentStart <= end.addingTimeInterval(maximumSameEpisodeGap) else {
                    return false
                }
                return start.timeIntervalSince(currentStart) >= materialBoundaryChange
                    || end.timeIntervalSince(currentEnd) >= materialBoundaryChange
            }
            .max { lhs, rhs in
                let lhsEnd = lhs.end ?? .distantPast
                let rhsEnd = rhs.end ?? .distantPast
                if lhsEnd != rhsEnd { return lhsEnd < rhsEnd }
                return (lhs.start ?? .distantPast) < (rhs.start ?? .distantPast)
            }
    }

    /// Builds a conservative review-only sleep episode from sustained
    /// five-minute low-HR bins. It deliberately does not auto-confirm: the
    /// purpose is to keep a fragmented/open journal visible for review when
    /// whole-session averages are polluted by quiet awake time or one contact
    /// spike. Gaps up to two hours remain inside one sleep-to-sleep episode,
    /// matching the existing fragmented-sleep cluster bound; later episodes
    /// are offered as naps instead of silently generating a second recovery.
    nonisolated static func physiologicalSleepReviewNight(
        in sessions: [SavedSession],
        confirmedSleeps: [UserConfirmedSleep] = [],
        dismissedCandidates: [AtriaDismissedSleepCandidate] = [],
        rest: Int,
        calendar: Calendar = .current
    ) -> SleepHistorySnapshot.Night? {
        do {
            guard let draft = try physiologicalSleepReviewNightDraftCore(
                in: sessions,
                confirmedSleeps: confirmedSleeps,
                dismissedCandidates: dismissedCandidates,
                rest: rest,
                calendar: calendar,
                cooperativeDeadline: nil
            ) else { return nil }
            return try materializeSleepReviewDraft(
                draft,
                from: sessions,
                maximumRows: nil,
                cooperativeDeadline: nil,
                invocationCounter: nil
            )
        } catch {
            return nil
        }
    }

    /// Handoff-13 CP1: the single frozen positive-awake-evidence primitive.
    /// Awake bins are five-minute physiology bins whose median sits at or
    /// above resting + 8 — clearly outside the sleep band this user's core
    /// bins occupy (≤ resting + 4). Evidence exists on a side only when a
    /// SUSTAINED run of near-adjacent awake bins (≥ 25 minutes, matching the
    /// wake-boundary lane's sustained-wake lookback) lies within the two-hour
    /// search window beside the boundary. A single spike bin can never brace
    /// an episode; neither can silence.
    enum SustainedAwakeEvidenceSide { case before, after }

    nonisolated static func sustainedAwakeEvidenceExists(
        awakeBinStarts: [Date],
        boundary: Date,
        side: SustainedAwakeEvidenceSide,
        binSeconds: TimeInterval = 5 * 60,
        searchWindow: TimeInterval = 2 * 60 * 60,
        minimumRun: TimeInterval = 25 * 60
    ) -> Bool {
        let windowStart: Date
        let windowEnd: Date
        switch side {
        case .before:
            windowStart = boundary.addingTimeInterval(-searchWindow)
            windowEnd = boundary
        case .after:
            windowStart = boundary
            windowEnd = boundary.addingTimeInterval(searchWindow)
        }
        var runStart: Date?
        var previous: Date?
        for binStart in awakeBinStarts {
            guard binStart >= windowStart.addingTimeInterval(-binSeconds),
                  binStart <= windowEnd else {
                if binStart > windowEnd { break }
                continue
            }
            if let last = previous,
               binStart.timeIntervalSince(last) <= binSeconds * 1.5 {
                if runStart == nil { runStart = last }
            } else {
                runStart = binStart
            }
            previous = binStart
            if let runStart,
               binStart.addingTimeInterval(binSeconds)
                   .timeIntervalSince(runStart) >= minimumRun {
                return true
            }
        }
        return false
    }

    private nonisolated static func physiologicalSleepReviewNightDraftCore(
        in sessions: [SavedSession],
        confirmedSleeps: [UserConfirmedSleep],
        dismissedCandidates: [AtriaDismissedSleepCandidate],
        rest: Int,
        calendar: Calendar,
        cooperativeDeadline: AtriaSleepSettlementDeadline?
    ) throws -> AtriaSleepReviewDraft? {
        struct Bin {
            let start: Date
            let median: Int
            let sampleCount: Int
        }
        try cooperativeDeadline?.checkpoint()
        let newestEnd = sessions.map(\.end).max()
        guard let newestEnd else { return nil }
        let cutoff = newestEnd.addingTimeInterval(-36 * 60 * 60)
        let binSeconds: TimeInterval = 5 * 60
        var valuesByBucket: [Int: [Int]] = [:]
        var awakeBinStarts: [Date] = []
        for (sessionIndex, session) in sessions.enumerated()
        where session.end >= cutoff {
            if sessionIndex.isMultiple(of: 8) {
                try cooperativeDeadline?.checkpoint()
            }
            for (pointIndex, point) in session.points.enumerated() {
                if pointIndex.isMultiple(of: 256) {
                    try cooperativeDeadline?.checkpoint()
                }
                let date = session.start.addingTimeInterval(point.t)
                guard date >= cutoff else { continue }
                let bucket = Int(floor(date.timeIntervalSince1970 / binSeconds))
                valuesByBucket[bucket, default: []].append(point.bpm)
            }
        }
        var bins: [Bin] = []
        bins.reserveCapacity(valuesByBucket.count)
        for (bucket, values) in valuesByBucket {
            try cooperativeDeadline?.checkpoint()
            // Three samples is enough for sparse/offline-restored streams;
            // production live bins normally contain hundreds.
            guard values.count >= 3 else { continue }
            var ordered = values
            try cooperativeStableSort(
                &ordered,
                cooperativeDeadline: cooperativeDeadline,
                areInIncreasingOrder: <
            )
            let middle = ordered.count / 2
            let median = ordered.count.isMultiple(of: 2)
                ? (ordered[middle - 1] + ordered[middle]) / 2
                : ordered[middle]
            if median <= rest + 4 {
                bins.append(Bin(
                    start: Date(
                        timeIntervalSince1970:
                            Double(bucket) * binSeconds
                    ),
                    median: median,
                    sampleCount: values.count
                ))
            } else if median >= rest + 8 {
                // Handoff-13 CP1: positive awake evidence. Bins clearly above
                // the sleep band brace a shifted daytime episode — absence of
                // low-HR bins alone never proves wakefulness.
                awakeBinStarts.append(Date(
                    timeIntervalSince1970: Double(bucket) * binSeconds
                ))
            }
        }
        try cooperativeStableSort(
            &awakeBinStarts,
            cooperativeDeadline: cooperativeDeadline,
            areInIncreasingOrder: <
        )
        try cooperativeStableSort(
            &bins,
            cooperativeDeadline: cooperativeDeadline,
            areInIncreasingOrder: { $0.start < $1.start }
        )
        guard !bins.isEmpty else { return nil }

        var episodes: [[Bin]] = []
        var current: [Bin] = []
        for bin in bins {
            try cooperativeDeadline?.checkpoint()
            if let previous = current.last,
               bin.start.timeIntervalSince(previous.start) > 2 * 60 * 60 {
                episodes.append(current)
                current = []
            }
            current.append(bin)
        }
        if !current.isEmpty { episodes.append(current) }

        AtriaDebugLog(
            "ATRIADBG sleep_physio_draft sessions=%d sleep_bins=%d awake_bins=%d episodes=%d rest=%d",
            sessions.count,
            bins.count,
            awakeBinStarts.count,
            episodes.count,
            rest
        )

        var reviewDrafts: [AtriaSleepReviewDraft] = []
        for episode in episodes {
            try cooperativeDeadline?.checkpoint()
            guard let first = episode.first, let last = episode.last else {
                continue
            }
            let start = first.start
            let end = min(newestEnd, last.start.addingTimeInterval(binSeconds))
            let span = end.timeIntervalSince(start)
            let captured = TimeInterval(episode.count) * binSeconds
            let endHour = calendar.component(.hour, from: end)
            let coreOverlap = sleepCoreOverlapDuration(start: start,
                                                       end: end,
                                                       calendar: calendar)
            let coreOverlapFraction = span > 0 ? coreOverlap / span : 0
            // Five-minute physiology bins are a recovery path for fragmented
            // sensor data, not a weaker sleep classifier. A sub-five-hour
            // episode must spend most of its span inside the 00:00–06:00 sleep
            // core; this prevents the 22:18–02:05 quiet-awake window from being
            // recreated after the aggregate gate rejected it. Longer, clearly
            // main-sleep-sized episodes (including a resumed 03:50–11:38 sleep)
            // remain reviewable with at least 90 minutes in the core.
            let mainSleep = captured >= 150 * 60
                && span >= AggregateSleepCandidate.strictMinimumDuration
                && coreOverlap >= AggregateSleepCandidate.minimumAutoConfirmSleepCoreOverlap
                && (captured >= AggregateSleepCandidate.minimumAutoConfirmMainSleepDuration
                    || coreOverlapFraction >= 0.60)
            // Handoff-13 CP1: a SHIFTED daytime sleep has zero 00:00–06:00 core
            // overlap by definition, so the night-core gate can never admit it
            // (the physical Aug-13 candidate). It is admitted only as a review
            // candidate braced by POSITIVE sustained awake evidence — see the
            // 2026-08-22 refinement at the `shiftedDaytimeReview` definition below
            // for why the gate is the WAKING transition (awake_after) plus a
            // sleep-band, main-sleep-sized episode, not the former 5h cap /
            // two-sided bracing. Ambient quiet or absence of motion is never
            // enough, and this remains review-only (no auto-confirm gate).
            let awakeBefore = Self.sustainedAwakeEvidenceExists(
                awakeBinStarts: awakeBinStarts,
                boundary: start,
                side: .before
            )
            let awakeAfter = Self.sustainedAwakeEvidenceExists(
                awakeBinStarts: awakeBinStarts,
                boundary: end,
                side: .after
            )
            // 2026-08-22 (device-confirmed): require the WAKING transition
            // (sustained awake activity AFTER the episode) rather than bracing on
            // BOTH sides. A real 12:00–16:00/155-min shifted sleep had core=0,
            // awake_after=1, awake_before=0 — the pre-sleep window was a data
            // gap / sedentary wind-down, so demanding awake_before wrongly
            // rejected a genuine main sleep. awake_after is the definitive main-
            // sleep signal and still excludes the documented 22:18–02:05
            // quiet-awake case (which is FOLLOWED by actual sleep → awake_after
            // false); an early-morning sleep also wakes into activity, unaffected.
            // Review-only; episode already requires >=150min of sleep-band HR.
            let shiftedDaytimeReview = !mainSleep
                && captured >= 150 * 60
                && span >= AggregateSleepCandidate.strictMinimumDuration
                && awakeAfter
            // 2026-08-22 diagnostic: surface every physiological-episode gate so
            // the field can see exactly why a shifted/afternoon sleep is or isn't
            // admitted (episode detected? which gate fails?). Read-only.
            AtriaDebugLog(
                "ATRIADBG sleep_physio_episode start_h=%d end_h=%d captured_min=%.0f span_min=%.0f core_min=%.0f core_frac=%.2f awake_before=%d awake_after=%d awake_bins=%d main_sleep=%d shifted_review=%d",
                calendar.component(.hour, from: start),
                endHour,
                captured / 60,
                span / 60,
                coreOverlap / 60,
                coreOverlapFraction,
                awakeBefore ? 1 : 0,
                awakeAfter ? 1 : 0,
                awakeBinStarts.count,
                mainSleep ? 1 : 0,
                shiftedDaytimeReview ? 1 : 0
            )
            // This fallback has HR bins only. During the day, low HR is not
            // specific to sleep: active wear can contain long low-HR stretches
            // between brief exertion (the physical 2026-07-22 false nap had a
            // 105 bpm peak but enough <= resting+4 bins to reach this branch).
            // Do not turn that ambiguous physiology into a nap prompt. Naps are
            // admitted by aggregateSleepCandidates only when independently
            // validated low-motion evidence covers the same window.
            let nap = false
            let overlapsConfirmed = confirmedSleeps.contains { $0.end > start && $0.start < end }
            let extendsConfirmed = sleepReviewExtensionTarget(existing: confirmedSleeps,
                                                               candidateStart: start,
                                                               candidateEnd: end,
                                                               candidateDuration: min(captured, span),
                                                               isNap: nap) != nil
            guard mainSleep || shiftedDaytimeReview || nap,
                  !overlapsConfirmed || extendsConfirmed,
                  !dismissedCandidates.contains(where: {
                      $0.suppresses(start: start, end: end)
                  }) else { continue }
            let source = (mainSleep || shiftedDaytimeReview)
                ? "sleep_episode_review" : "nap_candidate"
            let day = endHour <= 11 ? calendar.startOfDay(for: end) : calendar.startOfDay(for: start)
            let weightedCount = episode.reduce(0) { $0 + $1.sampleCount }
            let weightedMedian = weightedCount > 0
                ? episode.reduce(0) { $0 + ($1.median * $1.sampleCount) } / weightedCount
                : rest
            let metrics: (sessions: Int, samples: Int, avgHR: Int,
                          peakHR: Int, restingHR: Int, hrv: Int?,
                          hrvWindowCount: Int)
            let respiratoryRate: Double?
            if let cooperativeDeadline {
                metrics = try confirmedSleepWindowMetrics(
                    from: sessions,
                    start: start,
                    end: end,
                    rest: weightedMedian,
                    cooperativeDeadline: cooperativeDeadline
                )
                let respiratoryDeadline = cooperativeDeadline.capped(
                    afterNanoseconds:
                        sleepReviewRespiratoryBudgetNanoseconds
                )
                respiratoryRate = try? confirmedSleepRespiratoryRate(
                    from: sessions,
                    start: start,
                    end: end,
                    cooperativeDeadline: respiratoryDeadline
                )
                try cooperativeDeadline.checkpoint()
            } else {
                metrics = confirmedSleepWindowMetrics(
                    from: sessions,
                    start: start,
                    end: end,
                    rest: weightedMedian
                )
                respiratoryRate = confirmedSleepRespiratoryRate(
                    from: sessions,
                    start: start,
                    end: end
                )
            }
            reviewDrafts.append(AtriaSleepReviewDraft(
                night: SleepHistorySnapshot.Night(
                    id: "sleep-physiology-review-\(Int(start.timeIntervalSince1970))-\(Int(end.timeIntervalSince1970))-\(source)",
                    day: day,
                    start: start,
                    end: end,
                    duration: min(captured, span),
                    restingHR: weightedMedian,
                    hrv: metrics.hrv,
                    hrvWindowCount: metrics.hrvWindowCount,
                    respiratoryRate: respiratoryRate,
                    sleepEfficiency: span > 0
                        ? min(1, captured / span)
                        : nil,
                    confidence: "review_needed",
                    source: source,
                    confirmed: false,
                    stageSegments: [],
                    motionValidated: false
                ),
                stageRecipe: AtriaSleepReviewStageRecipe(
                    start: start,
                    end: end,
                    restingHR: weightedMedian,
                    isNap: nap,
                    motionValidated: false
                )
            ))
        }
        try cooperativeDeadline?.checkpoint()
        return reviewDrafts.max { lhs, rhs in
            (lhs.night.end ?? .distantPast)
                < (rhs.night.end ?? .distantPast)
        }
    }

    /// Runs optional staging only after the existing review-selection policy
    /// has chosen a fresh draft. A cached snapshot bypasses this helper and is
    /// returned byte-for-byte unchanged.
    private nonisolated static func materializeSleepReviewDraft(
        _ draft: AtriaSleepReviewDraft,
        from sessions: [SavedSession],
        maximumRows: Int?,
        cooperativeDeadline: AtriaSleepSettlementDeadline?,
        invocationCounter: AtriaSleepReviewStageInvocationCounter?
    ) throws -> SleepHistorySnapshot.Night {
        try cooperativeDeadline?.checkpoint()
        let recipe = draft.stageRecipe
        let stageSegments: [SleepStageSegment]
        if let cooperativeDeadline {
            guard let maximumRows else {
                throw AtriaSleepSettlementAbort.deadlineExceeded
            }
            invocationCounter?.recordInvocation()
            stageSegments = try sleepStageResearchSegments(
                from: sessions,
                start: recipe.start,
                end: recipe.end,
                restingHR: recipe.restingHR,
                isNap: recipe.isNap,
                motionValidated: recipe.motionValidated,
                maximumRows: maximumRows,
                cooperativeDeadline: cooperativeDeadline
            )
        } else {
            invocationCounter?.recordInvocation()
            stageSegments = sleepStageResearchSegments(
                from: sessions,
                start: recipe.start,
                end: recipe.end,
                restingHR: recipe.restingHR,
                isNap: recipe.isNap,
                motionValidated: recipe.motionValidated
            )
        }
        let night = draft.night
        return SleepHistorySnapshot.Night(
            id: night.id,
            day: night.day,
            savedAt: night.savedAt,
            start: night.start,
            end: night.end,
            duration: night.duration,
            observedDuration: night.observedDuration,
            restingHR: night.restingHR,
            hrv: night.hrv,
            hrvWindowCount: night.hrvWindowCount,
            respiratoryRate: night.respiratoryRate,
            sleepEfficiency: night.sleepEfficiency,
            confidence: night.confidence,
            source: night.source,
            confirmed: night.confirmed,
            stageSegments: stageSegments,
            eventTimeZoneIdentifier: night.eventTimeZoneIdentifier,
            motionValidated: night.motionValidated,
            sleepNeedSeconds: night.sleepNeedSeconds,
            frozenSleepNeed: night.frozenSleepNeed
        )
    }

    nonisolated static func shouldPublishSleepReviewCache(completedGeneration: Int,
                                                          currentGeneration: Int) -> Bool {
        completedGeneration == currentGeneration
    }

    nonisolated static func shouldPublishSleepReviewProjection(
        isCancelled: Bool,
        completedGeneration: Int,
        currentGeneration: Int,
        pendingGenerationMatches: Bool,
        hasForegroundAuthority: Bool,
        applicationIsActive: Bool,
        restoreInitializationBlocked: Bool
    ) -> Bool {
        !isCancelled
            && completedGeneration == currentGeneration
            && pendingGenerationMatches
            && hasForegroundAuthority
            && applicationIsActive
            && !restoreInitializationBlocked
    }

    private nonisolated static func sleepReviewCandidateSource(for candidate: AggregateSleepCandidate) -> String {
        if candidate.kind == "resumed_sleep_candidate" { return "resumed_sleep_candidate" }
        if candidate.kind == "nap_candidate" { return "nap_candidate" }
        return candidate.sessions > 1 ? "aggregate_sleep" : "sleep_window"
    }

    private func confirmSleepHistoryNight(_ night: SleepHistorySnapshot.Night,
                                          rest: Int,
                                          source: String) async -> UserConfirmedSleep? {
        guard let start = night.start, let end = night.end, end > start else {
            AtriaDebugLog("ATRIADBG sleep_confirm status=learning reason=invalid_review_window source=%@ candidate_source=%@ metric_promotions=0 auto_gate_e_unchanged=1",
                          source,
                          night.source)
            return nil
        }

        let windowSpan = max(0, end.timeIntervalSince(start))
        let observedDuration = night.observedDuration > 0
            ? night.observedDuration
            : windowSpan
        let span = max(observedDuration, windowSpan)
        let isNap = night.isNapEvidence
        let isResumedSleep = night.source == "resumed_sleep_candidate"
        let confirmable = isResumedSleep
            ? observedDuration >= AggregateSleepCandidate.resumedSleepMinimumDuration
                && observedDuration <= AggregateSleepCandidate.resumedSleepMaximumDuration
                && span <= AggregateSleepCandidate.resumedSleepMaximumDuration
            : isNap
            ? observedDuration >= AggregateSleepCandidate.napMinimumDuration && span <= AggregateSleepCandidate.napMaximumSpan
            : observedDuration >= AggregateSleepCandidate.fragmentedMinimumDuration
        guard confirmable else {
            AtriaDebugLog("ATRIADBG sleep_confirm status=learning reason=candidate_too_short_specific source=%@ candidate_source=%@ kind=%@ duration_s=%.0f span_s=%.0f metric_promotions=0 auto_gate_e_unchanged=1",
                          source,
                          night.source,
                          isNap ? "nap" : "sleep",
                          observedDuration,
                          span)
            return nil
        }
        // A resumed-sleep review is a second observed segment after a real
        // awake interval, never an extension of the first sleep. Persisting it
        // independently is what keeps that interval at zero sleep credit.
        let extensionTarget = isResumedSleep ? nil : Self.sleepReviewExtensionTarget(
            existing: cachedConfirmedSleeps,
            candidateStart: start,
            candidateEnd: end,
            candidateDuration: observedDuration,
            isNap: isNap
        )
        // A five-minute physiology bucket may start just after the already
        // saved automatic night. Preserve the earlier durable boundary when
        // the review is an approved continuation; Save must only grow sleep.
        let confirmedStart = isResumedSleep
            ? start
            : min(start, extensionTarget?.start ?? start)
        let confirmedSpan = max(observedDuration, end.timeIntervalSince(confirmedStart))
        let sleepSource = reviewedSleepSource(for: night)
        let id = confirmedSleepID(start: confirmedStart, end: end, source: sleepSource)
        var existing = cachedConfirmedSleeps
        if let already = existing.first(where: { $0.id == id }) {
            // Repair older saved reviews that predate durable candidate
            // settlement. Re-confirming must remove the actionable candidate
            // immediately even though the confirmed record itself is unchanged.
            addDismissedSleepCandidate(start: start, end: end)
            sleepHistorySnapshot = SleepHistorySnapshot(
                rollups: historySnapshot.rollups,
                confirmedSleeps: cachedConfirmedSleeps,
                dismissedCandidates: dismissedSleepCandidates
            )
            refreshHistorySnapshotCache(deferred: true)
            dashboardRevision &+= 1
            AtriaDebugLog("ATRIADBG sleep_confirm status=already_confirmed_specific id=%@ source=%@ candidate_source=%@ start=%@ end=%@ confidence=%@ motion_source=%@ motion_validated=%d metric_promotions=0 auto_gate_e_unchanged=1",
                          already.id,
                          source,
                          already.source,
                          isoString(already.start),
                          isoString(already.end),
                          already.confidence,
                          already.motionSource,
                          already.motionValidated ? 1 : 0)
            return already
        }

        // The candidate builder already included the fresh active journal on a
        // utility worker. Prefer its exact-window HRV so confirming does not
        // discard that evidence and visibly change recovery color. Finished
        // canonical sessions remain the fallback for older review records.
        let metrics = confirmedSleepWindowMetrics(start: confirmedStart, end: end, rest: rest)
        let motionValidated = night.hasValidatedMotionEvidence
        let stageSegments = night.stageSegmentsForStorage.isEmpty ? nil : night.stageSegmentsForStorage
        let creditedDuration = UserConfirmedSleep.effectiveSleepDuration(
            source: sleepSource,
            observedDuration: observedDuration,
            start: confirmedStart,
            end: end,
            span: confirmedSpan,
            stageSegments: stageSegments
        )
        guard creditedDuration > 0 else {
            AtriaDebugLog(
                "ATRIADBG sleep_confirm status=learning reason=no_classified_sleep_credit source=%@ candidate_source=%@ observed_s=%.0f span_s=%.0f metric_promotions=0",
                source,
                night.source,
                observedDuration,
                confirmedSpan
            )
            return nil
        }
        let confirmed = UserConfirmedSleep(id: id,
                                           createdAt: Date(),
                                           start: confirmedStart,
                                           end: end,
                                           source: sleepSource,
                                           confidence: motionValidated ? "user_confirmed_motion_validated" : "user_confirmed_hr_only",
                                           sessions: metrics.sessions,
                                           samples: metrics.samples,
                                           avgHR: metrics.avgHR,
                                           peakHR: metrics.peakHR,
                                           restingHR: night.restingHR ?? metrics.restingHR,
                                           hrv: night.hrv ?? metrics.hrv,
                                           hrvWindowCount: max(night.hrvWindowCount,
                                                               metrics.hrvWindowCount),
                                           respiratoryRate: night.respiratoryRate
                                            ?? confirmedSleepRespiratoryRate(start: confirmedStart,
                                                                            end: end),
                                           duration: creditedDuration,
                                           span: confirmedSpan,
                                           reason: "\(source); \(night.confirmationText); \(night.confidenceText)",
                                           motionSource: motionValidated ? "user_review_validated" : "user_review",
                                           motionValidated: motionValidated,
                                           stageSegments: stageSegments,
                                           eventTimeZoneIdentifier: night.eventTimeZoneIdentifier
                                            ?? extensionTarget?.eventTimeZoneIdentifier
                                            ?? TimeZone.current.identifier)
        if extensionTarget != nil {
            // A continuation can cover more than one legacy automatic fragment.
            // Remove every auto main-sleep record it subsumes so Activity and
            // recovery receive one canonical major sleep, never duplicates.
            existing = Self.sleepReviewInsertionBase(existing: existing,
                                                     extensionTarget: extensionTarget,
                                                     candidateStart: confirmedStart,
                                                     candidateEnd: end)
        }
        existing.append(confirmed)
        guard await saveConfirmedSleeps(
            existing,
            publishStressContext:
                Self.sleepStressContextAuthority(confirmed) != nil
        ) else { return nil }
        // Confirm permanently settles the detector suggestion only after the
        // canonical record is durable. A failed write must never dismiss the
        // sole actionable candidate and leave Activity empty.
        clearDismissedSleepCandidates(overlappingStart: start, end: end)
        addDismissedSleepCandidate(start: start, end: end)
        refreshSleepSnapshotAfterCandidateSettlement()
        AtriaDebugLog("ATRIADBG sleep_confirm status=confirmed_specific id=%@ source=%@ candidate_source=%@ start=%@ end=%@ duration_s=%.0f span_s=%.0f sessions=%d samples=%d avg_hr=%d peak_hr=%d rest_hr=%d sleep_rhr=%d confidence=%@ motion_source=%@ motion_validated=%d stage_research_segments=%d reason=%@ metric_promotions=0 auto_gate_e_unchanged=1 healthkit_source=none local_only=1",
                      confirmed.id,
                      source,
                      confirmed.source,
                      isoString(confirmed.start),
                      isoString(confirmed.end),
                      confirmed.duration,
                      confirmed.span,
                      confirmed.sessions,
                      confirmed.samples,
                      confirmed.avgHR,
                      confirmed.peakHR,
                      rest,
                      confirmed.restingHR,
                      confirmed.confidence,
                      confirmed.motionSource,
                      confirmed.motionValidated ? 1 : 0,
                      confirmed.stageSegments?.count ?? 0,
                      confirmed.reason)
        // Persistence may freeze a new adaptive sleep-need receipt. Return
        // the settled canonical image, not the pre-settlement constructor, so
        // an immediate unchanged Save is genuinely idempotent.
        return cachedConfirmedSleeps.first(where: { $0.id == confirmed.id })
            ?? confirmed
    }

    private func reviewedSleepSource(for night: SleepHistorySnapshot.Night) -> String {
        if night.source == "resumed_sleep_candidate" { return "resumed_sleep" }
        if night.isNapEvidence { return "nap_candidate" }
        if SleepHistorySnapshot.Night.explicitSleepSources.contains(night.source) {
            return night.source
        }
        return "sleep_window"
    }

    private func scheduleSleepReadinessRetryIfUseful(reason: String) {
        let readiness = sleepReadinessRetryState()
        guard readiness.shouldRetry else { return }
        pendingSleepReadinessRetry?.cancel()
        let delays = Self.sleepReadinessRetryDelays
        let delaySummary = delays.map { String(Int($0.rounded())) }.joined(separator: ",")
        AtriaDebugLog("ATRIADBG sleep_auto_confirm_retry schedule reason=%@ attempts=%d delays_s=%@ state=%@ blocker=%@ candidates=%d ready_candidates=%d pending_backfill=%d",
                      reason,
                      delays.count,
                      delaySummary,
                      readiness.evidence.state,
                      readiness.evidence.blocker,
                      readiness.evidence.candidates,
                      readiness.evidence.readyCandidates,
                      readiness.pendingBackfill ? 1 : 0)
        pendingSleepReadinessRetry = Task { @MainActor [weak self] in
            for (index, delay) in delays.enumerated() {
                try? await Task.sleep(for: .seconds(delay))
                guard !Task.isCancelled, let self else { return }
                let attempt = index + 1
                let retryState = self.sleepReadinessRetryState()
                AtriaDebugLog("ATRIADBG sleep_auto_confirm_retry attempt=%d reason=%@ delay_s=%.0f state=%@ blocker=%@ candidates=%d ready_candidates=%d pending_backfill=%d action=recheck_existing_gates",
                              attempt,
                              reason,
                              delay,
                              retryState.evidence.state,
                              retryState.evidence.blocker,
                              retryState.evidence.candidates,
                              retryState.evidence.readyCandidates,
                              retryState.pendingBackfill ? 1 : 0)
                self.refreshHistoricalArchiveStatus(reason: "sleep_auto_confirm_retry")
                let saved = await self.autoConfirmStrongSleepCandidates(reason: "retry_\(reason)_attempt_\(attempt)")
                self.refreshHistorySnapshotCache(deferred: true)
                if saved || !self.sleepReadinessRetryState().shouldRetry {
                    self.pendingSleepReadinessRetry = nil
                    return
                }
            }
            self?.pendingSleepReadinessRetry = nil
        }
    }

    private func sleepReadinessRetryState() -> (shouldRetry: Bool, evidence: SleepEvidenceStatus, pendingBackfill: Bool) {
        let rest = baseline.restingInt ?? 60
        let evidence = sleepEvidenceStatusFast(rest: rest)
        let pendingBackfill = UserDefaults.standard.bool(forKey: AtriaBLEManager.OfflineSyncDefaults.rangeLossBackfillPending)
        guard !evidence.ready else {
            return (false, evidence, pendingBackfill)
        }
        let blockerCanImproveWithBackfill = evidence.blocker.hasPrefix("sleep_motion_unvalidated")
            || evidence.blocker == "sleep_fragmented_below_minimum"
        let shouldRetry = pendingBackfill || (evidence.fallbackAvailable && blockerCanImproveWithBackfill)
        return (shouldRetry, evidence, pendingBackfill)
    }

    private func scheduleSleepSettlementRetry(for candidates: [AggregateSleepCandidate],
                                              reason: String,
                                              now: Date = Date(),
                                              settlementAuthority:
                                                ForegroundSleepSettlementAuthority,
                                              executionShouldContinue:
                                                @escaping @Sendable () -> Bool) {
        let candidateEnds = candidates.map(\.end)
        guard let delay = Self.sleepSettlementRetryDelay(candidateEnds: candidateEnds, now: now) else { return }
        pendingSleepSettlementRetry?.cancel()
        pendingSleepSettlementRetry = Task { @MainActor [weak self] in
            try? await Task.sleep(for: .seconds(delay))
            guard !Task.isCancelled, let self else { return }
            guard executionShouldContinue() else {
                self.pendingSleepSettlementRetry = nil
                self.lastForegroundSleepAutoConfirmAt = nil
                return
            }
            self.pendingSleepSettlementRetry = nil
            // This retry can inherit the same growing all-day journal as a
            // normal foreground edge. Route it through the off-main proposal
            // builder instead of performing aggregation on the MainActor.
            self.lastForegroundSleepAutoConfirmAt = nil
            self.autoConfirmSleepOnForegroundIfUseful(
                reason: "settled_\(reason)",
                settlementAuthority: settlementAuthority,
                executionShouldContinue: executionShouldContinue
            )
        }
        AtriaDebugLog("ATRIADBG sleep_auto_confirm_retry schedule reason=%@ kind=settlement delay_s=%.0f candidates=%d",
                      reason,
                      delay,
                      candidates.count)
    }

    nonisolated static func sleepSettlementRetryDelay(
        candidateEnds: [Date],
        now: Date,
        settlementDelay: TimeInterval = 30 * 60
    ) -> TimeInterval? {
        let unsettledDelays = candidateEnds
            .map { $0.addingTimeInterval(settlementDelay).timeIntervalSince(now) }
            .filter { $0 > 0 }
        guard let earliest = unsettledDelays.min() else { return nil }
        // A small margin avoids firing on the same clock tick as the boundary.
        return max(1, earliest + 1)
    }

    private var lastForegroundSleepAutoConfirmAt: Date?

    private func foregroundSleepSettlementWorkerIsCurrent(
        _ generation: Int
    ) -> Bool {
        generation == foregroundSleepSettlementGeneration
            && Self.foregroundSleepSettlementCompletionIsCurrent(
                completedGeneration: generation,
                pending: pendingForegroundSleepSettlementOwner
            )
    }

    /// A revoked foreground/recovered authority may stop the utility worker at
    /// any cooperative checkpoint. Retire only that exact generation and clear
    /// its cadence stamp so the next authorized edge can retry immediately.
    /// A newer ordinary or recovered settlement is never canceled by a stale
    /// cleanup callback.
    private func retireForegroundSleepSettlementAfterAuthorityLoss(
        generation: Int
    ) {
        guard foregroundSleepSettlementWorkerIsCurrent(generation) else {
            return
        }
        foregroundSleepSettlementGeneration &+= 1
        pendingForegroundSleepSettlementWorkItem?.cancel()
        pendingForegroundSleepSettlementWorkItem = nil
        pendingForegroundSleepSettlementOwner = nil
        lastForegroundSleepAutoConfirmAt = nil
        drainForegroundSleepSettlementCompletions(succeeded: false)
    }

    /// Mismatch replacement is permitted only for an unfenced owner. Advance
    /// the worker generation before releasing its sentinel so no queued G1
    /// callback can observe or drain a later G2 completion array.
    private func supersedeForegroundSleepSettlement(
        workerGeneration: Int
    ) {
        guard let owner = pendingForegroundSleepSettlementOwner,
              owner.workerGeneration == workerGeneration,
              !owner.hasCompletionFence else { return }
        foregroundSleepSettlementGeneration &+= 1
        pendingForegroundSleepSettlementWorkItem?.cancel()
        pendingForegroundSleepSettlementWorkItem = nil
        pendingForegroundSleepSettlementOwner = nil
        lastForegroundSleepAutoConfirmAt = nil
        if !pendingForegroundSleepSettlementCompletions.isEmpty {
            drainForegroundSleepSettlementCompletions(succeeded: false)
        }
    }

    /// An exact worker may retry its own stale source while retaining an
    /// already-attached completion fence. Retire the old generation first, but
    /// leave its completion array for the replacement owner to adopt.
    private func prepareForegroundSleepSettlementReplacement(
        workerGeneration: Int
    ) -> Bool {
        guard foregroundSleepSettlementWorkerIsCurrent(workerGeneration) else {
            return false
        }
        foregroundSleepSettlementGeneration &+= 1
        pendingForegroundSleepSettlementWorkItem?.cancel()
        pendingForegroundSleepSettlementWorkItem = nil
        pendingForegroundSleepSettlementOwner = nil
        return true
    }

    /// Foreground settlement is latency-sensitive: it runs shortly after the
    /// return animation on the main actor. Sleep that can still be newly saved
    /// or extended is recent evidence, so do not rebuild/sort and then scan the
    /// wearer's unbounded lifetime archive on every eligible app switch.
    /// Background diagnostics retain their explicit full-archive paths.
    nonisolated static let foregroundSleepEvaluationLookbackDays = 7
    nonisolated static let foregroundSleepEvaluationMaximumSessions = 512

    /// Hard ceilings for the archive-free latest-night publisher. The motion
    /// side owns its independent 2-shard/10 MiB/200k-row limits; these cap the
    /// already-decoded physiology carried into the existing sleep gates.
    nonisolated static let compactLatestNightMaximumSessions = 64
    nonisolated static let compactLatestNightMaximumHeartRateRows = 80_000
    nonisolated static let compactLatestNightMaximumRRRows = 80_000
    nonisolated static let compactLatestNightMaximumRecoveredMotionEpochs =
        4_096
    /// The research stage engine is optional presentation evidence, not a
    /// sleep-save gate. Compact settlement deliberately retains its original
    /// small ceiling even though a checked engine exists; its physiology and
    /// receipt-bound commit have a stricter physical-work budget than review UI.
    nonisolated static let compactLatestNightMaximumStagingRows = 4_096
    nonisolated static let compactLatestNightMaximumRespirationWindowRows = 4_096
    nonisolated static let compactLatestNightDeadlineSeconds: TimeInterval = 2

    /// Latest-night horizon: the detector's 14-hour maximum sleep span plus a
    /// six-hour wake/settlement allowance. A rolling 20 hours can intersect at
    /// most two UTC compact shards and structurally keeps ~1 Hz physiology
    /// below the independent 80k-row ceilings.
    nonisolated static func compactLatestNightWindow(
        now: Date
    ) -> DateInterval? {
        let unix = now.timeIntervalSince1970
        guard unix.isFinite, unix > 20 * 60 * 60 else { return nil }
        let start = now.addingTimeInterval(-20 * 60 * 60)
        guard now > start else { return nil }
        return DateInterval(start: start, end: now)
    }

    nonisolated static func compactLatestNightSessionSlice(
        from canonicalSessions: [SavedSession],
        now: Date,
        deadlineUptimeNanoseconds: UInt64,
        cooperativeDeadline: AtriaSleepSettlementDeadline? = nil,
        preserveAttachedMotion: Bool = false
    ) -> Result<
        CompactLatestNightSessionSlice,
        CompactLatestNightSettlementFailure
    > {
        guard let window = compactLatestNightWindow(now: now) else {
            return .failure(.invalidWindow)
        }
        var sessions: [SavedSession] = []
        sessions.reserveCapacity(min(
            canonicalSessions.count,
            compactLatestNightMaximumSessions
        ))
        var heartRateRows = 0
        var rrRows = 0
        var recoveredMotionEpochRows = 0
        var seenRecoveredMotionEpochs =
            Set<CompactLatestNightMotionEpochKey>()
        func deadlineExceeded() -> Bool {
            if let cooperativeDeadline {
                do {
                    try cooperativeDeadline.checkpoint()
                } catch {
                    return true
                }
            }
            return DispatchTime.now().uptimeNanoseconds
                >= deadlineUptimeNanoseconds
        }
        for (index, source) in canonicalSessions.enumerated() {
            if index.isMultiple(of: 64), deadlineExceeded() {
                return .failure(.deadlineExceeded)
            }
            guard source.end > window.start,
                  source.start < window.end else {
                continue
            }
            guard source.start.timeIntervalSince1970.isFinite,
                  source.end.timeIntervalSince1970.isFinite,
                  source.end > source.start else {
                return .failure(.sessionIntegrityFailure)
            }
            guard sessions.count < compactLatestNightMaximumSessions else {
                return .failure(.sessionCapExceeded)
            }
            let clippedStart = max(source.start, window.start)
            let clippedEnd = min(source.end, window.end)
            guard clippedEnd > clippedStart else { continue }

            // This is a rolling evidence horizon, not a pair of adjacent
            // ownership buckets. Keep the end inclusive to match legacy
            // confirmed-window physiology and the compact motion reader; a
            // connection UUID remains the de-duplication authority.
            var points: [SavedSession.Point] = []
            points.reserveCapacity(min(
                source.points.count,
                compactLatestNightMaximumHeartRateRows - heartRateRows
            ))
            for (pointIndex, point) in source.points.enumerated() {
                if pointIndex.isMultiple(of: 256), deadlineExceeded() {
                    return .failure(.deadlineExceeded)
                }
                guard point.t.isFinite else {
                    return .failure(.sessionIntegrityFailure)
                }
                let timestamp = source.start.addingTimeInterval(max(0, point.t))
                guard timestamp >= clippedStart,
                      timestamp <= clippedEnd else { continue }
                guard heartRateRows + points.count
                        < compactLatestNightMaximumHeartRateRows else {
                    return .failure(.heartRateCapExceeded)
                }
                points.append(.init(
                    t: timestamp.timeIntervalSince(clippedStart),
                    bpm: point.bpm
                ))
            }

            var boundedRR: [SavedSession.RRPoint] = []
            if let sourceRR = source.rrPoints {
                var wholeSessionRRProvenanceQualified = true
                var qualifiedRRWouldExceedCap = false
                boundedRR.reserveCapacity(min(
                    sourceRR.count,
                    compactLatestNightMaximumRRRows - rrRows
                ))
                for (rrIndex, point) in sourceRR.enumerated() {
                    if rrIndex.isMultiple(of: 256), deadlineExceeded() {
                        return .failure(.deadlineExceeded)
                    }
                    guard point.t.isFinite else {
                        return .failure(.sessionIntegrityFailure)
                    }
                    if point.source != .standardHeartRateMeasurement2A37,
                       point.source != .verifiedWhoop4HistoricalV24 {
                        wholeSessionRRProvenanceQualified = false
                    }
                    let timestamp = source.start.addingTimeInterval(
                        max(0, point.t)
                    )
                    guard timestamp >= clippedStart,
                          timestamp <= clippedEnd else { continue }
                    if rrRows + boundedRR.count
                        >= compactLatestNightMaximumRRRows {
                        qualifiedRRWouldExceedCap = true
                        continue
                    }
                    boundedRR.append(.init(
                        t: timestamp.timeIntervalSince(clippedStart),
                        ms: point.ms,
                        source: point.source
                    ))
                }
                if !wholeSessionRRProvenanceQualified {
                    // Legacy local HRV/respiration first qualifies the entire
                    // connection before range filtering. Preserve that exact
                    // no-upgrade rule: clipping cannot discard a mixed-source
                    // row and turn the remaining RR into qualified evidence.
                    boundedRR.removeAll(keepingCapacity: false)
                } else if qualifiedRRWouldExceedCap {
                    return .failure(.rrCapExceeded)
                }
            }
            // A session with no in-window HR cannot source a latest-night
            // sleep candidate. Ignore it before reserving attached-motion
            // identity so a duplicate epoch on a valid session remains usable.
            guard !points.isEmpty else { continue }
            var boundedMotionEpochs: [AtriaRecoveredMotionEpoch]? = nil
            if preserveAttachedMotion,
               let sourceEpochs = source.recoveredMotionEpochs {
                var retained: [AtriaRecoveredMotionEpoch] = []
                retained.reserveCapacity(min(
                    sourceEpochs.count,
                    compactLatestNightMaximumRecoveredMotionEpochs
                        - recoveredMotionEpochRows
                ))
                for (epochIndex, epoch) in sourceEpochs.enumerated() {
                    if epochIndex.isMultiple(of: 256), deadlineExceeded() {
                        return .failure(.deadlineExceeded)
                    }
                    guard epoch.start.timeIntervalSince1970.isFinite,
                          epoch.end.timeIntervalSince1970.isFinite,
                          epoch.end > epoch.start else {
                        return .failure(.sessionIntegrityFailure)
                    }
                    guard epoch.end > clippedStart,
                          epoch.start < clippedEnd else { continue }
                    let key = CompactLatestNightMotionEpochKey(epoch)
                    guard seenRecoveredMotionEpochs.insert(key).inserted else {
                        continue
                    }
                    guard recoveredMotionEpochRows + retained.count
                            < compactLatestNightMaximumRecoveredMotionEpochs else {
                        return .failure(.recoveredMotionEpochCapExceeded)
                    }
                    retained.append(epoch)
                }
                boundedMotionEpochs = retained.isEmpty ? nil : retained
            }
            let session = compactLatestNightClippedSession(
                source,
                start: clippedStart,
                end: clippedEnd,
                points: points,
                rrPoints: boundedRR.isEmpty ? nil : boundedRR,
                recoveredMotionEpochs: boundedMotionEpochs
            )
            sessions.append(session)
            heartRateRows += points.count
            rrRows += boundedRR.count
            recoveredMotionEpochRows += boundedMotionEpochs?.count ?? 0
        }
        guard !sessions.isEmpty else {
            return .failure(.noRecentSessions)
        }
        guard !deadlineExceeded() else {
            return .failure(.deadlineExceeded)
        }
        return .success(.init(
            start: window.start,
            end: window.end,
            sessions: sessions,
            heartRateRows: heartRateRows,
            rrRows: rrRows
        ))
    }

    /// Value-semantic window projection used only by the bounded compact
    /// publisher. Absolute sample times are retained while offsets are rebased
    /// to the clipped start. Full-session physiology summaries are cleared so
    /// only the retained, provenance-qualified RR rows can derive HRV/resp.
    private nonisolated static func compactLatestNightClippedSession(
        _ source: SavedSession,
        start: Date,
        end: Date,
        points: [SavedSession.Point],
        rrPoints: [SavedSession.RRPoint]?,
        recoveredMotionEpochs: [AtriaRecoveredMotionEpoch]?
    ) -> SavedSession {
        var clipped = SavedSession(
            id: source.id,
            start: start,
            end: end,
            label: source.label,
            points: points
        )
        clipped.hrv = nil
        clipped.hrvSDNN = nil
        clipped.respiratoryRate = nil
        clipped.rrPoints = rrPoints
        clipped.hrvReferenceValidated = false
        clipped.motionHintCount = source.motionHintCount
        clipped.motionHintKinds = source.motionHintKinds
        clipped.motionEvidenceSource = source.motionEvidenceSource
        clipped.motionEvidenceValidated = source.motionEvidenceValidated
        clipped.motionShortCount = source.motionShortCount
        clipped.motionShortMean = source.motionShortMean
        clipped.motionShortMin = source.motionShortMin
        clipped.motionShortMax = source.motionShortMax
        clipped.motionShortOverOneCount = source.motionShortOverOneCount
        clipped.imuSampleCount = source.imuSampleCount
        clipped.imuFrameCount = source.imuFrameCount
        clipped.imuSampleRateHz = source.imuSampleRateHz
        clipped.imuScale = source.imuScale
        clipped.imuEndian = source.imuEndian
        clipped.imuStillnessRatio = source.imuStillnessRatio
        clipped.imuMovementIntensity = source.imuMovementIntensity
        clipped.imuActivityBursts = source.imuActivityBursts
        clipped.imuValidationState = source.imuValidationState
        // Compact settlement passes nil and attaches epochs from its receipt
        // after this slice succeeds. The review lane may instead preserve its
        // already-attached, checked in-window evidence without any disk read.
        clipped.recoveredMotionEpochs = recoveredMotionEpochs
        clipped.strapStepResearchCount = source.strapStepResearchCount
        clipped.strapStepResearchAgreement = source.strapStepResearchAgreement
        clipped.strapStepResearchState = source.strapStepResearchState
        clipped.sleepWakeResearchState = source.sleepWakeResearchState
        clipped.sleepWakeResearchConfidence = source.sleepWakeResearchConfidence
        clipped.sleepWakeResearchReason = source.sleepWakeResearchReason
        clipped.sensorResearchProbeFrames = source.sensorResearchProbeFrames
        clipped.spo2ResearchCandidateFrames = source.spo2ResearchCandidateFrames
        clipped.skinTempResearchCandidateFrames = source.skinTempResearchCandidateFrames
        clipped.skinTempResearchCandidateValueSum = source.skinTempResearchCandidateValueSum
        clipped.skinTempResearchCandidateValueCount = source.skinTempResearchCandidateValueCount
        clipped.spo2ResearchCandidateOffset64ValueSum =
            source.spo2ResearchCandidateOffset64ValueSum
        clipped.spo2ResearchCandidateOffset64ValueCount =
            source.spo2ResearchCandidateOffset64ValueCount
        clipped.spo2ResearchCandidateOffset66ValueSum =
            source.spo2ResearchCandidateOffset66ValueSum
        clipped.spo2ResearchCandidateOffset66ValueCount =
            source.spo2ResearchCandidateOffset66ValueCount
        // Temperature has no validated decoder and must never cross this lane.
        clipped.decodedSkinTemperatureCelsius = nil
        clipped.biologicalSex = source.biologicalSex
        clipped.activeCalories = source.activeCalories
        clipped.caloriesConfidence = source.caloriesConfidence
        // Preserve conservative source audit counters. They cover the original
        // connection and may reject a clipped candidate, but can never relax a
        // contact-artifact gate.
        clipped.hrRaw2A37 = source.hrRaw2A37
        clipped.hrAccepted = source.hrAccepted
        clipped.hrZero = source.hrZero
        clipped.hrArtifactHeld = source.hrArtifactHeld
        clipped.hrArtifactDropped = source.hrArtifactDropped
        clipped.hrRawGaps = source.hrRawGaps
        clipped.hrAcceptedGaps = source.hrAcceptedGaps
        clipped.hrMaxRawGap = source.hrMaxRawGap
        clipped.hrMaxAcceptedGap = source.hrMaxAcceptedGap
        clipped.hrRRMismatch = source.hrRRMismatch
        clipped.strengthSets = source.strengthSets
        clipped.kind = source.kind
        clipped.excludedIntervals = source.excludedIntervals
        clipped.eventTimeZoneIdentifier = source.eventTimeZoneIdentifier
        return clipped
    }

    /// Builds a proposal entirely from resident saved sessions and the compact
    /// fixed-width motion derivative. It invokes the existing candidate,
    /// staging, respiratory-rate, and HRV math without changing any gate.
    nonisolated static func makeCompactLatestNightSettlementPreparation(
        fingerprint: ForegroundSleepSettlementFingerprint,
        canonicalSessions: [SavedSession],
        // Handoff-10 CP2A: the durable resident live-journal session, so the
        // current sleep's evidence through wake + tail is visible to the
        // settlement lane without waiting for the archive frontier. Nil keeps
        // the previous canonical-only behavior.
        activeJournalSession: SavedSession? = nil,
        now: Date,
        rest: Int,
        maxHR: Int,
        learnedWindow: (start: Int, end: Int)?,
        strapIdentifier: String?,
        thermalState: ProcessInfo.ThermalState,
        compactStore: AtriaWhoop4MotionTickCompactStore = .shared,
        autoConfirmLimit: Int = 2,
        // Handoff-11: when supplied, a review-eligible motion read failure
        // (missing/cap-bounded — motion unverifiable, not impugned) may yield
        // one degraded HR/RR review-only candidate instead of a withhold.
        degradedReviewContext: CompactLatestNightReviewContext? = nil,
        deadlineUptimeNanoseconds suppliedDeadline: UInt64? = nil
    ) -> CompactLatestNightSettlementPreparation {
        precondition(!Thread.isMainThread)
        guard thermalState != .critical else {
            return .withheld(.thermalCritical)
        }
        guard let strapIdentifier,
              let sourceStrapIdentifier = UUID(uuidString: strapIdentifier)
        else {
            return .withheld(.missingStrapIdentity)
        }
        let startedAt = DispatchTime.now().uptimeNanoseconds
        let localBudget = UInt64(
            compactLatestNightDeadlineSeconds * 1_000_000_000
        )
        let localDeadline = startedAt.addingReportingOverflow(
            localBudget
        ).partialValue
        let deadline = min(suppliedDeadline ?? localDeadline, localDeadline)
        let cooperativeDeadline = AtriaSleepSettlementDeadline(
            uptimeNanoseconds: deadline
        )
        let slice: CompactLatestNightSessionSlice
        switch compactLatestNightSessionSlice(
            from: canonicalSessions,
            now: now,
            deadlineUptimeNanoseconds: deadline
        ) {
        case .success(let prepared):
            slice = prepared
        case .failure(let failure):
            return .withheld(failure)
        }
        let motionRead = compactStore.latestNightMotionRead(
            start: slice.start,
            end: slice.end,
            strapIdentifier: strapIdentifier,
            thermalState: thermalState,
            deadlineUptimeNanoseconds: deadline
        )
        let compactEvidence: AtriaWhoop4MotionTickCompactStore
            .LatestNightMotionEvidence
        switch motionRead {
        case .qualified(let evidence):
            compactEvidence = evidence
        case .incomplete(let failure):
            return makeCompactLatestNightDegradedReviewPreparation(
                motionFailure: failure,
                slice: slice,
                degradedReviewContext: degradedReviewContext,
                activeJournalSession: activeJournalSession,
                now: now,
                rest: rest,
                maxHR: maxHR,
                sourceStrapIdentifier: sourceStrapIdentifier,
                cooperativeDeadline: cooperativeDeadline
            )
        }
        var sessions: [SavedSession] = []
        sessions.reserveCapacity(slice.sessions.count)
        do {
            for source in slice.sessions {
                try cooperativeDeadline.checkpoint()
                var attachedEpochs: [AtriaRecoveredMotionEpoch] = []
                attachedEpochs.reserveCapacity(min(
                    compactEvidence.epochs.count,
                    2_000
                ))
                for (index, epoch) in compactEvidence.epochs.enumerated() {
                    if index.isMultiple(of: 256) {
                        try cooperativeDeadline.checkpoint()
                    }
                    if epoch.end > source.start,
                       epoch.start < source.end {
                        attachedEpochs.append(epoch)
                    }
                }
                var session = source
                session.recoveredMotionEpochs = attachedEpochs.isEmpty
                    ? nil : attachedEpochs
                session.decodedSkinTemperatureCelsius = nil
                sessions.append(session)
            }
        } catch {
            return .withheld(.deadlineExceeded)
        }
        // Keep newest-first semantics expected by foreground evaluation after
        // attaching epochs. Sorting at most 64 session headers is bounded.
        sessions.sort { $0.start > $1.start }
        guard DispatchTime.now().uptimeNanoseconds < deadline else {
            return .withheld(.deadlineExceeded)
        }
        let settlement: ForegroundSleepSettlementProposal
        do {
            settlement = try makeForegroundSleepSettlementProposal(
                fingerprint: fingerprint,
                canonicalSessions: sessions,
                activeJournalSession: activeJournalSession,
                now: now,
                rest: rest,
                maxHR: maxHR,
                learnedWindow: learnedWindow,
                lookbackDays: 2,
                maximumSessions: compactLatestNightMaximumSessions,
                historicalMotionPolicy: .attachedCompactOnly,
                cooperativeDeadline: cooperativeDeadline,
                autoConfirmLimit: min(max(0, autoConfirmLimit), 2)
            )
        } catch {
            return .withheld(.deadlineExceeded)
        }
        guard let commitAuthority = compactStore
            .mintLatestNightCommitAuthority(
                for: compactEvidence.receipt,
                strapIdentifier: strapIdentifier,
                deadlineUptimeNanoseconds: deadline
        ) else {
            return .withheld(.compactSourceChanged)
        }
        return .ready(.init(
            settlement: settlement,
            sourceStrapIdentifier: sourceStrapIdentifier,
            compactReceipt: compactEvidence.receipt,
            commitAuthority: commitAuthority,
            sessionCount: sessions.count,
            heartRateRows: slice.heartRateRows,
            rrRows: slice.rrRows
        ))
    }

    /// Handoff-11 Checkpoint 2: which compact motion read failures may enter
    /// the degraded HR/RR review lane. A missing or cap-bounded read means
    /// motion could not be VERIFIED — the resident HR/RR evidence is still
    /// real. Identity, integrity, thermal and deadline failures veto instead:
    /// they impugn the read (or the system state) rather than merely bounding
    /// it, so the entire settlement stays withheld. Exhaustive on purpose —
    /// a future failure case must be classified here consciously.
    nonisolated static func compactMotionFailurePermitsHRRRReview(
        _ failure: AtriaWhoop4MotionTickCompactStore.LatestNightReadFailure
    ) -> Bool {
        switch failure {
        case .missingShard, .shardCapExceeded, .byteCapExceeded,
             .rowCapExceeded:
            return true
        case .invalidRequest, .thermalCritical, .integrityFailure,
             .deadlineExceeded, .sourceChanged:
            return false
        }
    }

    /// Durable identity for one degraded review's evidence. Built only from
    /// values that survive relaunch (candidate window, strap, resident row
    /// counts, blocker) — never process-local generations, in-memory revision
    /// counters or file timestamps — so an identical re-preparation after a
    /// relaunch deduplicates instead of re-arming.
    nonisolated static func degradedSleepReviewEvidenceFingerprint(
        nightStart: Date?,
        nightEnd: Date?,
        sourceStrapIdentifier: UUID,
        heartRateRows: Int,
        rrRows: Int,
        motionBlocker: AtriaWhoop4MotionTickCompactStore.LatestNightReadFailure
    ) -> String {
        let start = nightStart.map {
            Int($0.timeIntervalSince1970.rounded())
        } ?? -1
        let end = nightEnd.map {
            Int($0.timeIntervalSince1970.rounded())
        } ?? -1
        return "v1|\(start)|\(end)|\(sourceStrapIdentifier.uuidString)"
            + "|hr:\(heartRateRows)|rr:\(rrRows)|blk:\(motionBlocker.rawValue)"
    }

    /// Handoff-11 Checkpoints 1+3: resolve an incomplete compact motion read
    /// into exactly one of three truthful outcomes — a review-only candidate
    /// built through the existing bounded review gates, the named
    /// `hrRRReviewNotQualified` terminal, or the pre-H11 withhold. The
    /// review-only value can never reach the canonical commit path: it holds
    /// no compact receipt and no commit authority, and this builder never
    /// mints one.
    nonisolated static func makeCompactLatestNightDegradedReviewPreparation(
        motionFailure:
            AtriaWhoop4MotionTickCompactStore.LatestNightReadFailure,
        slice: CompactLatestNightSessionSlice,
        degradedReviewContext: CompactLatestNightReviewContext?,
        activeJournalSession: SavedSession?,
        now: Date,
        rest: Int,
        maxHR: Int,
        sourceStrapIdentifier: UUID,
        cooperativeDeadline: AtriaSleepSettlementDeadline
    ) -> CompactLatestNightSettlementPreparation {
        guard let degradedReviewContext,
              compactMotionFailurePermitsHRRRReview(motionFailure) else {
            return .withheld(.compactMotion(motionFailure))
        }
        // The compact read produced no epochs, so sessions enter the bounded
        // review gates exactly as sliced: HR/RR only, skin evidence already
        // cleared by the slice, newest-first as the evaluation union expects.
        var sessions = slice.sessions
        sessions.sort { $0.start > $1.start }
        let evaluationSessions = foregroundSleepEvaluationSessions(
            from: sessions,
            activeJournalSession: activeJournalSession,
            now: now
        )
        let projection: (
            main: SleepHistorySnapshot.Night?,
            naps: [SleepHistorySnapshot.Night]
        )
        do {
            projection = try makeBoundedSleepReviewCacheProjection(
                snapshot: degradedReviewContext.snapshot,
                canonicalSessions: evaluationSessions,
                confirmedSleeps: degradedReviewContext.confirmedSleeps,
                dismissedCandidates:
                    degradedReviewContext.dismissedCandidates,
                rest: rest,
                maxHR: maxHR,
                calendar: degradedReviewContext.calendar,
                cooperativeDeadline: cooperativeDeadline
            )
        } catch {
            return .withheld(.deadlineExceeded)
        }
        guard let night = projection.main, !night.confirmed else {
            return .withheld(.hrRRReviewNotQualified(motionFailure))
        }
        return .reviewOnly(.init(
            night: night,
            motionBlocker: motionFailure,
            evidenceFingerprint: degradedSleepReviewEvidenceFingerprint(
                nightStart: night.start,
                nightEnd: night.end,
                sourceStrapIdentifier: sourceStrapIdentifier,
                heartRateRows: slice.heartRateRows,
                rrRows: slice.rrRows,
                motionBlocker: motionFailure
            ),
            preparedAt: now,
            sourceStrapIdentifier: sourceStrapIdentifier,
            sessionCount: evaluationSessions.count,
            heartRateRows: slice.heartRateRows,
            rrRows: slice.rrRows
        ))
    }

    nonisolated static func foregroundSleepEvaluationSessions(
        from newestFirstCanonicalSessions: [SavedSession],
        activeJournalSession: SavedSession?,
        now: Date,
        lookbackDays: Int = foregroundSleepEvaluationLookbackDays,
        maximumSessions: Int = foregroundSleepEvaluationMaximumSessions
    ) -> [SavedSession] {
        guard lookbackDays > 0, maximumSessions > 0 else { return [] }
        let cutoff = now.addingTimeInterval(-TimeInterval(lookbackDays) * 24 * 60 * 60)
        var recent = Array(newestFirstCanonicalSessions
            .prefix { $0.start >= cutoff }
            .prefix(maximumSessions))
        guard let activeJournalSession,
              activeJournalSession.end >= cutoff else { return recent }
        recent = canonicalSessionsAfterUpsert(activeJournalSession,
                                              into: recent,
                                              replacesSameID: true)
        if recent.count > maximumSessions {
            recent.removeLast(recent.count - maximumSessions)
        }
        return recent
    }

    /// How long after a confirmed night's end a wake-then-sleep-again can still
    /// extend it. Past this, the night is treated as settled (2026-07-08).
    private static let sleepReExtendMorningWindow: TimeInterval = 5 * 60 * 60

    /// Legacy shape predicate retained for pure policy callers. Production
    /// admission additionally requires exact authority and configuration
    /// compatibility through `foregroundSleepSettlementAdmission` below.
    nonisolated static func shouldJoinPendingForegroundSleepSettlement(
        hasPendingWork: Bool,
        hasPendingCompletionFence: Bool,
        requestHasCompletionFence: Bool
    ) -> Bool {
        hasPendingWork
            && (hasPendingCompletionFence || requestHasCompletionFence)
    }

    /// Foreground (morning-flow) auto-confirm: launch-time auto-confirm never fires
    /// while the app stays resident overnight, so the first foreground of the day
    /// re-runs it. Rate-limited, and skipped while the newest confirmed sleep is
    /// recent enough that there is nothing new to confirm.
    func autoConfirmSleepOnForegroundIfUseful(
        reason: String,
        now: Date = Date(),
        force: Bool = false,
        deferDerivedPublication: Bool = false,
        evaluationLookbackDays: Int = foregroundSleepEvaluationLookbackDays,
        maximumEvaluationSessions: Int = foregroundSleepEvaluationMaximumSessions,
        autoConfirmLimit: Int = 2,
        compactRetryRemainingAttempts: Int = 1,
        staleRetryRemainingAttempts: Int = 1,
        settlementAuthority: ForegroundSleepSettlementAuthority? = nil,
        executionShouldContinue:
            @escaping @Sendable () -> Bool = { true },
        completion: ((Bool) -> Void)? = nil
    ) {
        guard executionShouldContinue() else {
            completion?(false)
            return
        }
        guard hasCompletedDeferredSessionLoad else {
            completion?(false)
            return
        }
        let rest = baseline.restingInt ?? 60
        let baselineRestingIsTrusted = baseline.restingInt != nil
            && baseline.hasTrustedRestingBaseline(now: now)
        let baselineRestingIsNearTrusted = baseline.restingInt != nil
            && baseline.hasNearTrustedRestingBaselineForFragmentedSleep(now: now)
        let maxHR = profile.maxHR
        let fingerprint = foregroundSleepSettlementFingerprint(
            rest: rest,
            baselineRestingIsTrusted: baselineRestingIsTrusted,
            baselineRestingIsNearTrusted: baselineRestingIsNearTrusted,
            maxHR: maxHR
        )
        let requestAuthority = settlementAuthority ?? .processForeground(
            generation: AtriaHistoricalProjectionForegroundGate
                .currentGeneration
        )
        let requestConfiguration = ForegroundSleepSettlementConfiguration(
            fingerprint: fingerprint,
            force: force,
            deferDerivedPublication: deferDerivedPublication,
            evaluationLookbackDays: evaluationLookbackDays,
            maximumEvaluationSessions: maximumEvaluationSessions,
            autoConfirmLimit: autoConfirmLimit,
            compactRetryRemainingAttempts: compactRetryRemainingAttempts,
            staleRetryRemainingAttempts: staleRetryRemainingAttempts
        )
        switch Self.foregroundSleepSettlementAdmission(
            pending: pendingForegroundSleepSettlementOwner,
            requestAuthority: requestAuthority,
            requestConfiguration: requestConfiguration,
            requestHasCompletionFence: completion != nil
        ) {
        case .start:
            break
        case .join(let workerGeneration):
            guard pendingForegroundSleepSettlementOwner?.workerGeneration
                    == workerGeneration else {
                completion?(false)
                return
            }
            if let completion {
                pendingForegroundSleepSettlementCompletions.append(completion)
                pendingForegroundSleepSettlementOwner?
                    .hasCompletionFence = true
            }
            AtriaDebugLog("ATRIADBG sleep_foreground_settlement status=joined_inflight reason=%@ force=%d request_completion_fence=%d owner_completion_fence=%d",
                          reason,
                          force ? 1 : 0,
                          completion == nil ? 0 : 1,
                          pendingForegroundSleepSettlementCompletions.isEmpty ? 0 : 1)
            return
        case .supersede(let workerGeneration):
            supersedeForegroundSleepSettlement(
                workerGeneration: workerGeneration
            )
        case .blockedByIncompatibleFencedOwner(let workerGeneration):
            AtriaDebugLog(
                "ATRIADBG sleep_foreground_settlement status=blocked_incompatible_fenced_owner reason=%@ owner_generation=%d",
                reason,
                workerGeneration
            )
            completion?(false)
            return
        }
        if !force,
           let last = lastForegroundSleepAutoConfirmAt,
           now.timeIntervalSince(last) < 30 * 60 {
            completion?(true)
            return
        }
        let latestOvernightEnd = cachedConfirmedSleeps
            .filter { !Self.confirmedSleepSourceIsNap(source: $0.source, duration: $0.duration) }
            .map(\.end)
            .max()
        // Re-evaluate in the first few hours after a night's end so a wake-then-
        // sleep-again can EXTEND it (user 2026-07-08), and again after 16h for a
        // genuinely new night. Between those, the night is settled — skip.
        let inExtendReCheckWindow: Bool
        if let latestOvernightEnd {
            let sinceEnd = now.timeIntervalSince(latestOvernightEnd)
            if !force,
               sinceEnd >= Self.sleepReExtendMorningWindow,
               sinceEnd < 16 * 60 * 60 {
                completion?(true)
                return
            }
            inExtendReCheckWindow = sinceEnd < Self.sleepReExtendMorningWindow
        } else {
            inExtendReCheckWindow = false
        }
        if let completion {
            pendingForegroundSleepSettlementCompletions.append(completion)
        }
        lastForegroundSleepAutoConfirmAt = now
        foregroundSleepSettlementGeneration &+= 1
        let generation = foregroundSleepSettlementGeneration
        pendingForegroundSleepSettlementWorkItem?.cancel()
        pendingForegroundSleepSettlementOwner = .init(
            workerGeneration: generation,
            authority: requestAuthority,
            configuration: requestConfiguration,
            hasCompletionFence:
                !pendingForegroundSleepSettlementCompletions.isEmpty
        )
        let canonicalSessions = cachedCanonicalSessions
        let learnedWindow = Self.learnedDutyCycleSleepWindow(defaults: .standard)
        // Read only the persisted strap identity. This publisher never asks the
        // BLE manager to connect, request history, pause HR, or change cadence.
        let compactStrapIdentifier = AtriaWhoop4MotionTickDailyStore
            .persistedStrapIdentifiers()
            .first
        let preparationThermalState = ProcessInfo.processInfo.thermalState
        // Handoff-11: immutable captures for the degraded HR/RR review lane,
        // taken on the main actor with the other inputs so the worker never
        // touches live store state.
        let degradedReviewContext = CompactLatestNightReviewContext(
            snapshot: sleepHistorySnapshot,
            confirmedSleeps: cachedConfirmedSleeps,
            dismissedCandidates: dismissedSleepCandidates,
            calendar: Calendar.current
        )
        let workItem = DispatchWorkItem { [weak self] in
            guard executionShouldContinue() else {
                Task { @MainActor [weak self] in
                    self?.retireForegroundSleepSettlementAfterAuthorityLoss(
                        generation: generation
                    )
                }
                return
            }
            guard !Thread.isMainThread else {
                assertionFailure("Foreground sleep settlement must not build on the main thread")
                return
            }
            // Handoff-10 CP2A: the durable resident journal is already
            // row-capped and busy/cold-safe; a cold cache defers to the
            // previous canonical-only behavior rather than blocking.
            let residentJournalSession = (try? SessionStore
                .loadCachedResidentJournalSessionForSleepReview(
                    now: now,
                    cooperativeDeadline: .init(
                        uptimeNanoseconds: DispatchTime.now().uptimeNanoseconds
                            + UInt64(SessionStore.compactLatestNightDeadlineSeconds
                                     * 1_000_000_000)
                    )
                )) ?? nil
            let preparation = SessionStore
                .makeCompactLatestNightSettlementPreparation(
                fingerprint: fingerprint,
                canonicalSessions: canonicalSessions,
                activeJournalSession: residentJournalSession,
                now: now,
                rest: rest,
                maxHR: maxHR,
                learnedWindow: learnedWindow,
                strapIdentifier: compactStrapIdentifier,
                thermalState: preparationThermalState,
                autoConfirmLimit: autoConfirmLimit,
                degradedReviewContext: degradedReviewContext
            )
            guard executionShouldContinue() else {
                Task { @MainActor [weak self] in
                    self?.retireForegroundSleepSettlementAfterAuthorityLoss(
                        generation: generation
                    )
                }
                return
            }
            guard case .ready(let prepared) = preparation else {
                let failure: CompactLatestNightSettlementFailure
                let degradedReview:
                    CompactLatestNightDegradedReviewProposal?
                switch preparation {
                case .withheld(let reason):
                    failure = reason
                    degradedReview = nil
                case .reviewOnly(let review):
                    // A persisted review still finishes as "not settled": the
                    // compact retry below may yet verify motion, and a later
                    // qualified settlement enriches or replaces the review.
                    failure = .compactMotion(review.motionBlocker)
                    degradedReview = review
                case .ready:
                    failure = .compactSourceChanged
                    degradedReview = nil
                }
                Task { @MainActor [weak self] in
                    guard let self,
                          self.foregroundSleepSettlementWorkerIsCurrent(
                            generation
                          ) else {
                        return
                    }
                    guard executionShouldContinue() else {
                        self.retireForegroundSleepSettlementAfterAuthorityLoss(
                            generation: generation
                        )
                        return
                    }
                    self.pendingForegroundSleepSettlementWorkItem = nil
                    self.lastForegroundSleepAutoConfirmAt = now
                        .addingTimeInterval(-20 * 60)
                    if let degradedReview {
                        self.persistCompactLatestNightDegradedReview(
                            degradedReview,
                            rest: rest,
                            source: reason
                        )
                    } else {
                        AtriaDebugLog(
                            "ATRIADBG sleep_foreground_compact status=withheld reason=%@ source=%@",
                            String(describing: failure),
                            reason
                        )
                        switch failure {
                        case .compactMotion(let motionFailure):
                            SessionStore.recordDegradedSleepReviewDiagnostic(
                                preparedAt: now,
                                motionBlocker: motionFailure.rawValue,
                                reviewEligible: SessionStore
                                    .compactMotionFailurePermitsHRRRReview(
                                        motionFailure
                                    ),
                                reviewQualified: false,
                                persistence: "none",
                                fingerprint: nil,
                                source: reason
                            )
                        case .hrRRReviewNotQualified(let motionFailure):
                            SessionStore.recordDegradedSleepReviewDiagnostic(
                                preparedAt: now,
                                motionBlocker: motionFailure.rawValue,
                                reviewEligible: true,
                                reviewQualified: false,
                                persistence: "none",
                                fingerprint: nil,
                                source: reason
                            )
                        default:
                            break
                        }
                    }
                    self.scheduleCompactLatestNightSettlementRetry(
                        reason: reason,
                        remainingAttempts: compactRetryRemainingAttempts,
                        deferDerivedPublication: deferDerivedPublication,
                        evaluationLookbackDays: evaluationLookbackDays,
                        maximumEvaluationSessions:
                            maximumEvaluationSessions,
                        autoConfirmLimit: autoConfirmLimit,
                        settlementAuthority: requestAuthority,
                        executionShouldContinue:
                            executionShouldContinue
                    )
                    self.finishForegroundSleepSettlementCompletions(
                        generation: generation,
                        succeeded: false
                    )
                    // Handoff-12 CP1: a withheld or review-only settlement no
                    // longer ends in silence — the admission lane leaves one
                    // terminal decision receipt and can persist the review.
                    self.scheduleCurrentCycleSleepReviewAdmission(
                        reason: "settlement_withheld_\(reason)",
                        compactMotionOutcome: String(describing: failure)
                    )
                }
                return
            }
            let proposal = prepared.settlement
            Task { @MainActor [weak self] in
                guard let self else { return }
                guard executionShouldContinue() else {
                    self.retireForegroundSleepSettlementAfterAuthorityLoss(
                        generation: generation
                    )
                    return
                }
                guard self.foregroundSleepSettlementWorkerIsCurrent(
                    generation
                ) else { return }
                // The saved link owns replacement. A preparation from the
                // former strap must never survive a re-pair even when no
                // compact row mutation occurred between mint and commit.
                let currentCompactStrapIdentifier =
                    AtriaWhoop4MotionTickDailyStore
                        .persistedStrapIdentifiers()
                        .first
                let compactSourceIsCurrent: Bool
                if let currentCompactStrapIdentifier,
                   UUID(uuidString: currentCompactStrapIdentifier)
                    == prepared.sourceStrapIdentifier,
                   prepared.commitAuthority.sourceStrapIdentifier
                    == prepared.sourceStrapIdentifier {
                    compactSourceIsCurrent =
                        AtriaWhoop4MotionTickCompactStore.shared
                        .consumeLatestNightCommitAuthority(
                            prepared.commitAuthority,
                            currentStrapIdentifier:
                                currentCompactStrapIdentifier
                        )
                } else {
                    compactSourceIsCurrent = false
                }
                let commitThermalIsCritical =
                    ProcessInfo.processInfo.thermalState == .critical
                guard !commitThermalIsCritical,
                      compactSourceIsCurrent,
                      Self.shouldCommitForegroundSleepSettlement(
                    completedGeneration: generation,
                    currentGeneration: self.foregroundSleepSettlementGeneration,
                    preparedFingerprint: proposal.fingerprint,
                    currentFingerprint: self.foregroundSleepSettlementFingerprint(
                        rest: self.baseline.restingInt ?? 60,
                        baselineRestingIsTrusted: self.baseline.restingInt != nil
                            && self.baseline.hasTrustedRestingBaseline(now: Date()),
                        baselineRestingIsNearTrusted: self.baseline.restingInt != nil
                            && self.baseline.hasNearTrustedRestingBaselineForFragmentedSleep(now: Date()),
                        maxHR: self.profile.maxHR
                    )
                ) else {
                    if generation == self.foregroundSleepSettlementGeneration {
                        self.pendingForegroundSleepSettlementWorkItem = nil
                        if commitThermalIsCritical {
                            AtriaDebugLog(
                                "ATRIADBG sleep_foreground_compact status=withheld reason=thermal_critical_at_commit source=%@",
                                reason
                            )
                            self.finishForegroundSleepSettlementCompletions(
                                generation: generation,
                                succeeded: false
                            )
                            return
                        }
                        // The source changed while this worker was building.
                        // Retry immediately from the newer immutable snapshot;
                        // do not let the ordinary 30-minute cadence turn safe
                        // stale-result rejection into a missed morning settle.
                        if staleRetryRemainingAttempts > 0 {
                            self.lastForegroundSleepAutoConfirmAt = nil
                            if self.prepareForegroundSleepSettlementReplacement(
                                workerGeneration: generation
                            ) {
                                self.autoConfirmSleepOnForegroundIfUseful(
                                    reason: "stale_\(reason)",
                                    now: Date(),
                                    force: force,
                                    deferDerivedPublication:
                                        deferDerivedPublication,
                                    evaluationLookbackDays:
                                        evaluationLookbackDays,
                                    maximumEvaluationSessions:
                                        maximumEvaluationSessions,
                                    autoConfirmLimit: autoConfirmLimit,
                                    compactRetryRemainingAttempts:
                                        compactRetryRemainingAttempts,
                                    staleRetryRemainingAttempts:
                                        staleRetryRemainingAttempts - 1,
                                    settlementAuthority: requestAuthority,
                                    executionShouldContinue:
                                        executionShouldContinue
                                )
                            }
                        } else {
                            // One immediate CAS retry is enough to absorb a
                            // normal append race. Continued churn waits for a
                            // later source/scene edge instead of hot-looping.
                            self.lastForegroundSleepAutoConfirmAt = nil
                            self.finishForegroundSleepSettlementCompletions(
                                generation: generation,
                                succeeded: false
                            )
                        }
                    }
                    AtriaDebugLog("ATRIADBG sleep_foreground_settlement status=discarded_stale reason=%@ generation=%d current_generation=%d",
                                  reason,
                                  generation,
                                  self.foregroundSleepSettlementGeneration)
                    return
                }
                AtriaDebugLog(
                    "ATRIADBG sleep_foreground_compact status=prepared source=%@ sessions=%d hr=%d rr=%d shards=%d bytes=%d motion_rows=%d fingerprint=%@ thermal=%d",
                    reason,
                    prepared.sessionCount,
                    prepared.heartRateRows,
                    prepared.rrRows,
                    prepared.compactReceipt.shardCount,
                    prepared.compactReceipt.mappedBytes,
                    prepared.compactReceipt.rowCount,
                    prepared.compactReceipt.sourceFingerprint,
                    preparationThermalState.rawValue
                )
                self.pendingForegroundSleepSettlementWorkItem = nil
                var persistenceSucceeded = true
                guard executionShouldContinue() else {
                    self.retireForegroundSleepSettlementAfterAuthorityLoss(
                        generation: generation
                    )
                    return
                }
                var saved = await self.autoConfirmStrongSleepCandidates(
                    reason: reason,
                    limit: autoConfirmLimit,
                    sourceSessions: proposal.sourceSessions,
                    precomputedStrongCandidates: proposal.strongCandidates,
                    precomputedMaterializations:
                        proposal.preparedStrongCandidates,
                    evaluationNow: proposal.preparedAt,
                    deferDerivedPublication: deferDerivedPublication,
                    archiveFreeLatestNightSettlement: true,
                    persistenceFailure: { persistenceSucceeded = false },
                    settlementAuthority: requestAuthority,
                    executionShouldContinue: executionShouldContinue
                )
                guard executionShouldContinue(),
                      self.foregroundSleepSettlementWorkerIsCurrent(
                        generation
                      ) else {
                    if self.foregroundSleepSettlementWorkerIsCurrent(
                        generation
                    ) {
                        self.retireForegroundSleepSettlementAfterAuthorityLoss(
                            generation: generation
                        )
                    }
                    return
                }
                if !saved && persistenceSucceeded {
                    saved = await self.commitPreparedWakeBoundarySleepIfUseful(
                        proposal.wakeBoundary,
                        reason: reason,
                        sourceSessions: proposal.sourceSessions,
                        deferDerivedPublication: deferDerivedPublication,
                        archiveFreeLatestNightSettlement: true,
                        persistenceFailure: { persistenceSucceeded = false },
                        executionShouldContinue: executionShouldContinue
                    )
                }
                guard executionShouldContinue(),
                      self.foregroundSleepSettlementWorkerIsCurrent(
                        generation
                      ) else {
                    if self.foregroundSleepSettlementWorkerIsCurrent(
                        generation
                    ) {
                        self.retireForegroundSleepSettlementAfterAuthorityLoss(
                            generation: generation
                        )
                    }
                    return
                }
                if !saved && persistenceSucceeded && !inExtendReCheckWindow {
                    // Back the rate limit off to ~10 min on failure so a
                    // transient blocker does not cost the whole 30-minute window.
                    self.lastForegroundSleepAutoConfirmAt = now.addingTimeInterval(-20 * 60)
                    self.scheduleCompactLatestNightSettlementRetry(
                        reason: reason,
                        remainingAttempts: compactRetryRemainingAttempts,
                        deferDerivedPublication: deferDerivedPublication,
                        evaluationLookbackDays: evaluationLookbackDays,
                        maximumEvaluationSessions:
                            maximumEvaluationSessions,
                        autoConfirmLimit: autoConfirmLimit,
                        settlementAuthority: requestAuthority,
                        executionShouldContinue:
                            executionShouldContinue
                    )
                }
                self.finishForegroundSleepSettlementCompletions(
                    generation: generation,
                    succeeded: persistenceSucceeded
                )
                // Handoff-12 CP1: even a completed canonical settlement pass
                // must leave a terminal admission decision — a shifted HR-only
                // review candidate is invisible to the auto-confirm path and
                // previously vanished without any record when nothing saved.
                self.scheduleCurrentCycleSleepReviewAdmission(
                    reason: "settlement_completed_\(reason)",
                    compactMotionOutcome: saved
                        ? "qualified_saved" : "qualified_not_saved"
                )
            }
        }
        pendingForegroundSleepSettlementWorkItem = workItem
        DispatchQueue.global(qos: .utility).async(execute: workItem)
    }

    private func finishForegroundSleepSettlementCompletions(
        generation: Int,
        succeeded: Bool
    ) {
        guard foregroundSleepSettlementWorkerIsCurrent(generation) else {
            return
        }
        pendingForegroundSleepSettlementWorkItem = nil
        pendingForegroundSleepSettlementOwner = nil
        drainForegroundSleepSettlementCompletions(succeeded: succeeded)
    }

    private func drainForegroundSleepSettlementCompletions(succeeded: Bool) {
        let completions = pendingForegroundSleepSettlementCompletions
        pendingForegroundSleepSettlementCompletions.removeAll(keepingCapacity: true)
        completions.forEach { $0(succeeded) }
    }

    /// Handoff-11 Checkpoint 4: persist one degraded review-only candidate
    /// durably. Runs on the main actor from the settlement completion path in
    /// ANY application state, and deliberately mutates no `@Published`
    /// projection, widget snapshot, HealthKit record or notification: in the
    /// background the record simply waits, and the foreground projection lane
    /// (which already consults the durable store) reconciles it exactly once
    /// on the next active edge. The strap identity is re-checked here so a
    /// preparation that outlived a re-pair cannot persist a stale claim.
    private func persistCompactLatestNightDegradedReview(
        _ review: CompactLatestNightDegradedReviewProposal,
        rest: Int,
        source: String
    ) {
        let currentStrapIdentifier = AtriaWhoop4MotionTickDailyStore
            .persistedStrapIdentifiers()
            .first
        let outcome: AtriaPendingSleepReviewStore.DegradedSaveOutcome
        if let currentStrapIdentifier,
           UUID(uuidString: currentStrapIdentifier)
            == review.sourceStrapIdentifier {
            outcome = AtriaPendingSleepReviewStore.saveDegradedReview(
                review.night,
                motionBlocker: review.motionBlocker.rawValue,
                evidenceFingerprint: review.evidenceFingerprint,
                sourceStrapIdentifier:
                    review.sourceStrapIdentifier.uuidString
            )
        } else {
            outcome = .rejectedStrapChanged
        }
        AtriaDebugLog(
            "ATRIADBG sleep_foreground_compact status=review_only blocker=%@ persistence=%@ fingerprint=%@ source=%@",
            review.motionBlocker.rawValue,
            outcome.rawValue,
            review.evidenceFingerprint,
            source
        )
        SessionStore.recordDegradedSleepReviewDiagnostic(
            preparedAt: review.preparedAt,
            motionBlocker: review.motionBlocker.rawValue,
            reviewEligible: true,
            reviewQualified: true,
            persistence: outcome.rawValue,
            fingerprint: review.evidenceFingerprint,
            source: source
        )
        guard outcome == .saved || outcome == .deduplicated else { return }
        // Durable dirty signal: the next projection build must rebuild from
        // live inputs (whose durable fallback consults the store). When the
        // scene is already active, run it now; otherwise the deferred flag
        // hands the record to the existing foreground edge untouched.
        sleepReviewCacheInputKey = nil
        sleepReviewRefreshDeferredUntilForeground = true
        if UIApplication.shared.applicationState == .active {
            scheduleSleepReviewCacheRefresh(
                rest: rest,
                calendar: .current,
                reason: "degraded_review_persisted"
            )
        }
    }

    /// Handoff-11 bounded diagnostic receipt: the single latest degraded-path
    /// settlement attempt, for physical acceptance and field forensics. Debug
    /// evidence only — no product surface reads this key.
    nonisolated static func recordDegradedSleepReviewDiagnostic(
        preparedAt: Date,
        motionBlocker: String?,
        reviewEligible: Bool,
        reviewQualified: Bool,
        persistence: String,
        fingerprint: String?,
        source: String,
        defaults: UserDefaults = .standard
    ) {
        struct Receipt: Codable {
            let schema: Int
            let preparedAtUnix: TimeInterval
            let recordedAtUnix: TimeInterval
            let motionBlocker: String?
            let reviewEligible: Bool
            let reviewQualified: Bool
            let persistence: String
            let fingerprint: String?
            let source: String
            /// Structural marker: the degraded lane can never mint or consume
            /// a latest-night commit authority, so canonical sleep, Recovery
            /// and their derived surfaces are unreachable from this attempt.
            let canonicalCommitBlocked: Bool
        }
        let receipt = Receipt(
            schema: 1,
            preparedAtUnix: preparedAt.timeIntervalSince1970,
            recordedAtUnix: Date().timeIntervalSince1970,
            motionBlocker: motionBlocker,
            reviewEligible: reviewEligible,
            reviewQualified: reviewQualified,
            persistence: persistence,
            fingerprint: fingerprint,
            source: source,
            canonicalCommitBlocked: true
        )
        guard let data = try? JSONEncoder().encode(receipt) else { return }
        defaults.set(
            data,
            forKey: "atria.debug.sleepCompactReviewReceipt.v1"
        )
    }

    /// Handoff-12 Checkpoint 1: one terminal decision record per current-cycle
    /// review admission attempt. The Aug-13 incident produced NOTHING when the
    /// candidate failed a review gate — silence is indistinguishable from
    /// never-attempted, so every attempt now ends in exactly one of these.
    /// Debug evidence only; no product surface reads this key. Bounded to the
    /// eight most recent attempts.
    struct SleepReviewAdmissionReceipt: Codable {
        var schema: Int = 1
        var attemptedAtUnix: TimeInterval
        var source: String
        var sourceRevisionKey: String
        var strapPseudonymousID: String?
        var candidateStartUnix: TimeInterval?
        var candidateEndUnix: TimeInterval?
        var candidateDuration: TimeInterval?
        var heartRateRows: Int
        var rrRows: Int
        var gateResult: String
        var compactMotionOutcome: String
        var frontierUnix: TimeInterval
        var pendingStoreOutcome: String
        /// saved_review | duplicate | already_confirmed | dismissed |
        /// source_not_ready | not_qualified(<gate>) | stale_generation |
        /// authority_revoked | deadline | integrity_failure
        var finalOutcome: String
    }

    nonisolated static let sleepReviewAdmissionReceiptKey =
        "atria.debug.sleepReviewAdmissionReceipts.v1"
    nonisolated static let sleepReviewAdmissionReceiptCapacity = 8

    nonisolated static func recordSleepReviewAdmissionReceipt(
        _ receipt: SleepReviewAdmissionReceipt,
        defaults: UserDefaults = .standard
    ) {
        var ring = loadSleepReviewAdmissionReceipts(defaults: defaults)
        ring.append(receipt)
        if ring.count > sleepReviewAdmissionReceiptCapacity {
            ring.removeFirst(ring.count - sleepReviewAdmissionReceiptCapacity)
        }
        guard let data = try? JSONEncoder().encode(ring) else { return }
        defaults.set(data, forKey: sleepReviewAdmissionReceiptKey)
    }

    nonisolated static func loadSleepReviewAdmissionReceipts(
        defaults: UserDefaults = .standard
    ) -> [SleepReviewAdmissionReceipt] {
        guard let data = defaults.data(
            forKey: sleepReviewAdmissionReceiptKey
        ), let ring = try? JSONDecoder().decode(
            [SleepReviewAdmissionReceipt].self,
            from: data
        ) else { return [] }
        return ring
    }

    /// Names the first failing review-tier clause for a no-candidate attempt.
    /// Diagnostic only — the bounded review builder remains the sole
    /// qualification authority; this mirrors its dense morning/long tier
    /// clause tables over the largest cluster, formed at the engine's own
    /// two-hour cluster gap, so the decision receipt describes the cluster
    /// the aggregator actually judged. (Physically measured Aug-13: 8 h of
    /// continuous post-sleep wear merges a shifted daytime sleep into one
    /// mega-cluster whose mean HR honestly fails the sleep band — the
    /// receipt must name that reality, not a differently-clustered one.)
    nonisolated static func sleepReviewAdmissionDiagnosis(
        sessions: [SavedSession],
        rest: Int,
        calendar: Calendar = .current
    ) -> String {
        let ordered = sessions.sorted { $0.start < $1.start }
        guard !ordered.isEmpty else { return "no_recent_sessions" }
        var clusters: [[SavedSession]] = []
        for session in ordered {
            if var current = clusters.last,
               let previous = current.last,
               session.start.timeIntervalSince(previous.end) <= 2 * 60 * 60 {
                current.append(session)
                clusters[clusters.count - 1] = current
            } else {
                clusters.append([session])
            }
        }
        func totalDuration(_ cluster: [SavedSession]) -> TimeInterval {
            cluster.reduce(0) { $0 + $1.end.timeIntervalSince($1.start) }
        }
        guard let cluster = clusters.max(by: {
            totalDuration($0) < totalDuration($1)
        }), let first = cluster.first, let last = cluster.last else {
            return "no_recent_sessions"
        }
        let duration = totalDuration(cluster)
        let span = last.end.timeIntervalSince(first.start)
        let bpms = cluster.flatMap { session in
            session.points.map { Double($0.bpm) }
        }
        guard !bpms.isEmpty else { return "no_heart_rate_rows" }
        let avg = bpms.reduce(0, +) / Double(bpms.count)
        let restDouble = Double(rest)
        let startHour = calendar.component(.hour, from: first.start)
        let endHour = calendar.component(.hour, from: last.end)
        let morningClock = (startHour >= 3 && startHour <= 8 && endHour <= 11)
            || (startHour >= 8 && startHour <= 13 && endHour <= 16)
        if duration < AggregateSleepCandidate.strictMinimumDuration
            - AggregateSleepCandidate.nearStrictMorningReviewTolerance {
            return "duration_below_review_floor"
        }
        if duration >= AggregateSleepCandidate.minimumAutoConfirmMainSleepDuration {
            // Long-tier shapes fail elsewhere; name the seam if it exceeds
            // the long tier's own allowance.
            if span > duration + 10 * 60 { return "long_tier_span_seam_exceeded" }
        } else {
            if span > duration
                + AggregateSleepCandidate.morningReviewSeamTolerance {
                return "morning_tier_span_seam_exceeded"
            }
            if !morningClock { return "outside_shifted_morning_clock_window" }
        }
        if avg > restDouble + 18 { return "mean_hr_above_sleep_band" }
        return "review_builder_gate"
    }

    /// Handoff-12 Checkpoint 1: evaluate current-cycle review evidence exactly
    /// once per stable source revision and end in one terminal decision
    /// receipt — even when the canonical settlement was withheld, already
    /// finished, or a downstream consumer dependency stayed parked. Uses the
    /// existing bounded review builder (never a second classifier), persists
    /// at most one unconfirmed candidate through the pending store, and
    /// mutates no `@Published` state so background execution stays legal.
    private func scheduleCurrentCycleSleepReviewAdmission(
        reason: String,
        compactMotionOutcome: String
    ) {
        let revisionKey = [
            String(reviewEvidenceRevision),
            String(confirmedSleepsRevision),
            String(sleepHistorySnapshotRevision),
            activeJournalSleepReviewIdentity.id?.uuidString ?? "-",
            activeJournalSleepReviewIdentity.endFiveMinuteBucket
                .map(String.init) ?? "-",
        ].joined(separator: "|")
        if let last = Self.loadSleepReviewAdmissionReceipts().last,
           last.sourceRevisionKey == revisionKey {
            // Once per stable source revision: identical evidence must stay
            // byte-stable and must not notify twice.
            return
        }
        let canonicalSessions = cachedCanonicalSessions
        let confirmedSleeps = cachedConfirmedSleeps
        let dismissedCandidates = dismissedSleepCandidates
        let snapshot = sleepHistorySnapshot
        let rest = baseline.restingInt ?? 60
        let maxHR = profile.maxHR
        let strapIdentifier = AtriaWhoop4MotionTickDailyStore
            .persistedStrapIdentifiers()
            .first
        let frontierUnix = UserDefaults.standard.double(
            forKey: AtriaBLEManager.OfflineSyncDefaults.drainedThroughUnix
        )
        let now = Date()
        DispatchQueue.global(qos: .utility).async { [weak self] in
            var receipt = SleepReviewAdmissionReceipt(
                attemptedAtUnix: now.timeIntervalSince1970,
                source: reason,
                sourceRevisionKey: revisionKey,
                strapPseudonymousID: strapIdentifier,
                candidateStartUnix: nil,
                candidateEndUnix: nil,
                candidateDuration: nil,
                heartRateRows: 0,
                rrRows: 0,
                gateResult: "unevaluated",
                compactMotionOutcome: compactMotionOutcome,
                frontierUnix: frontierUnix,
                pendingStoreOutcome: "none",
                finalOutcome: "integrity_failure"
            )
            var night: SleepHistorySnapshot.Night?
            do {
                let deadline = AtriaSleepSettlementDeadline(
                    uptimeNanoseconds: DispatchTime.now().uptimeNanoseconds
                        + UInt64(SessionStore.sleepReviewProjectionDeadlineSeconds
                                 * 1_000_000_000)
                )
                let journal = try? SessionStore
                    .loadCachedResidentJournalSessionForSleepReview(
                        now: now,
                        cooperativeDeadline: deadline
                    )
                let residentSources = try SessionStore.sleepReviewSourceSessions(
                    canonicalSessions: canonicalSessions,
                    activeJournalSession: journal ?? nil,
                    cooperativeDeadline: deadline
                )
                let slice: CompactLatestNightSessionSlice
                switch SessionStore.compactLatestNightSessionSlice(
                    from: residentSources,
                    now: now,
                    deadlineUptimeNanoseconds: .max,
                    cooperativeDeadline: deadline,
                    preserveAttachedMotion: true
                ) {
                case .success(let prepared):
                    slice = prepared
                case .failure(.noRecentSessions):
                    receipt.gateResult = "no_recent_sessions"
                    receipt.finalOutcome = "source_not_ready"
                    SessionStore.recordSleepReviewAdmissionReceipt(receipt)
                    return
                case .failure(let failure):
                    receipt.gateResult = String(describing: failure)
                    receipt.finalOutcome = "deadline"
                    SessionStore.recordSleepReviewAdmissionReceipt(receipt)
                    return
                }
                receipt.heartRateRows = slice.heartRateRows
                receipt.rrRows = slice.rrRows
                let projection = try SessionStore
                    .makeBoundedSleepReviewCacheProjection(
                        snapshot: snapshot,
                        canonicalSessions: slice.sessions,
                        confirmedSleeps: confirmedSleeps,
                        dismissedCandidates: dismissedCandidates,
                        rest: rest,
                        maxHR: maxHR,
                        cooperativeDeadline: deadline
                    )
                night = projection.main
                if let main = projection.main {
                    receipt.candidateStartUnix =
                        main.start?.timeIntervalSince1970
                    receipt.candidateEndUnix = main.end?.timeIntervalSince1970
                    receipt.candidateDuration = main.duration
                    receipt.gateResult = "qualified"
                } else {
                    receipt.gateResult = SessionStore
                        .sleepReviewAdmissionDiagnosis(
                            sessions: slice.sessions,
                            rest: rest
                        )
                    receipt.finalOutcome = receipt.gateResult
                        == "no_recent_sessions"
                        ? "source_not_ready"
                        : "not_qualified(\(receipt.gateResult))"
                }
            } catch {
                receipt.gateResult = "deadline_or_cancelled"
                receipt.finalOutcome = "deadline"
                SessionStore.recordSleepReviewAdmissionReceipt(receipt)
                return
            }
            Task { @MainActor [weak self] in
                guard let self else {
                    receipt.finalOutcome = "authority_revoked"
                    SessionStore.recordSleepReviewAdmissionReceipt(receipt)
                    return
                }
                let currentRevisionKey = [
                    String(self.reviewEvidenceRevision),
                    String(self.confirmedSleepsRevision),
                    String(self.sleepHistorySnapshotRevision),
                    self.activeJournalSleepReviewIdentity.id?.uuidString
                        ?? "-",
                    self.activeJournalSleepReviewIdentity.endFiveMinuteBucket
                        .map(String.init) ?? "-",
                ].joined(separator: "|")
                guard currentRevisionKey == revisionKey else {
                    receipt.finalOutcome = "stale_generation"
                    SessionStore.recordSleepReviewAdmissionReceipt(receipt)
                    return
                }
                guard let night else {
                    SessionStore.recordSleepReviewAdmissionReceipt(receipt)
                    return
                }
                if night.confirmed {
                    receipt.finalOutcome = "already_confirmed"
                    SessionStore.recordSleepReviewAdmissionReceipt(receipt)
                    return
                }
                let persisted = AtriaPendingSleepReviewStore.save(night)
                receipt.pendingStoreOutcome = persisted
                    ? "saved" : "rejected"
                receipt.finalOutcome = persisted
                    ? "saved_review"
                    : "not_qualified(pending_store_validity)"
                SessionStore.recordSleepReviewAdmissionReceipt(receipt)
                guard persisted else { return }
                // Event-bound delivery (field report item 11 defect 1). Admission
                // is the physiological moment the app knows there is a night or
                // nap to review; before this the prompt waited for the next
                // launch / scene-active / BGTask pass. Reachable while
                // backgrounded only because the resident checkpoint can now run
                // unattended (defect 2). Runs the same gate stack, so every
                // existing cap, debounce and cooldown still applies.
                Task { @MainActor [weak self] in
                    guard let self else { return }
                    await LocalNotificationScheduler.scheduleAdmittedSleepReview(store: self)
                }
                AtriaDebugLog(
                    "ATRIADBG sleep_review_admission status=saved_review source=%@ start=%.0f end=%.0f",
                    reason,
                    receipt.candidateStartUnix ?? -1,
                    receipt.candidateEndUnix ?? -1
                )
                // Durable dirty signal, exactly like the degraded lane: no
                // @Published mutation here; the foreground projection lane's
                // durable fallback surfaces the record on the next active edge.
                self.sleepReviewCacheInputKey = nil
                self.sleepReviewRefreshDeferredUntilForeground = true
                if UIApplication.shared.applicationState == .active {
                    self.scheduleSleepReviewCacheRefresh(
                        rest: rest,
                        calendar: .current,
                        reason: "sleep_review_admission"
                    )
                }
            }
        }
    }

    nonisolated static func compactLatestNightRetryAction(
        remainingAttempts: Int,
        delaySeconds: TimeInterval = 10 * 60
    ) -> CompactLatestNightRetryAction {
        guard remainingAttempts > 0,
              delaySeconds.isFinite,
              delaySeconds > 0 else {
            return .awaitSourceOrSceneEdge
        }
        return .retry(
            delaySeconds: delaySeconds,
            nextRemainingAttempts: remainingAttempts - 1
        )
    }

    nonisolated static func recoveredCompactRetryShouldRun(
        taskIsCancelled: Bool,
        authorityShouldContinue: Bool,
        scheduledGeneration: UInt64,
        currentGeneration: UInt64
    ) -> Bool {
        !taskIsCancelled
            && authorityShouldContinue
            && scheduledGeneration == currentGeneration
    }

    /// Compact failures never enter the legacy readiness scheduler: that path
    /// performs bounded-recent HistoricalArchive work immediately and again on
    /// every retry. One delayed compact attempt is enough; continued failure
    /// waits for a new durable-source or scene edge.
    private func scheduleCompactLatestNightSettlementRetry(
        reason: String,
        remainingAttempts: Int,
        deferDerivedPublication: Bool,
        evaluationLookbackDays: Int,
        maximumEvaluationSessions: Int,
        autoConfirmLimit: Int,
        settlementAuthority: ForegroundSleepSettlementAuthority,
        executionShouldContinue:
            @escaping @Sendable () -> Bool
    ) {
        switch Self.compactLatestNightRetryAction(
            remainingAttempts: remainingAttempts
        ) {
        case .awaitSourceOrSceneEdge:
            if deferDerivedPublication {
                pendingRecoveredSleepReadinessRetryGeneration &+= 1
                pendingRecoveredSleepReadinessRetry?.cancel()
                pendingRecoveredSleepReadinessRetry = nil
            } else {
                pendingSleepReadinessRetry?.cancel()
                pendingSleepReadinessRetry = nil
            }
        case .retry(let delaySeconds, let nextRemainingAttempts):
            if deferDerivedPublication {
                pendingRecoveredSleepReadinessRetryGeneration &+= 1
                let retryGeneration =
                    pendingRecoveredSleepReadinessRetryGeneration
                pendingRecoveredSleepReadinessRetry?.cancel()
                pendingRecoveredSleepReadinessRetry = Task {
                    @MainActor [weak self] in
                    try? await Task.sleep(for: .seconds(delaySeconds))
                    guard let self,
                          Self.recoveredCompactRetryShouldRun(
                            taskIsCancelled: Task.isCancelled,
                            authorityShouldContinue:
                                executionShouldContinue(),
                            scheduledGeneration: retryGeneration,
                            currentGeneration: self
                                .pendingRecoveredSleepReadinessRetryGeneration
                          ) else {
                        return
                    }
                    self.pendingRecoveredSleepReadinessRetry = nil
                    self.lastForegroundSleepAutoConfirmAt = nil
                    self.autoConfirmSleepOnForegroundIfUseful(
                        reason: "compact_retry_\(reason)",
                        now: Date(),
                        force: true,
                        deferDerivedPublication: true,
                        evaluationLookbackDays: evaluationLookbackDays,
                        maximumEvaluationSessions:
                            maximumEvaluationSessions,
                        autoConfirmLimit: autoConfirmLimit,
                        compactRetryRemainingAttempts:
                            nextRemainingAttempts,
                        settlementAuthority: settlementAuthority,
                        executionShouldContinue:
                            executionShouldContinue
                    )
                }
            } else {
                pendingSleepReadinessRetry?.cancel()
                pendingSleepReadinessRetry = Task { @MainActor [weak self] in
                    try? await Task.sleep(for: .seconds(delaySeconds))
                    guard !Task.isCancelled,
                          executionShouldContinue(),
                          let self else { return }
                    self.pendingSleepReadinessRetry = nil
                    self.lastForegroundSleepAutoConfirmAt = nil
                    self.autoConfirmSleepOnForegroundIfUseful(
                        reason: "compact_retry_\(reason)",
                        now: Date(),
                        force: true,
                        deferDerivedPublication: false,
                        evaluationLookbackDays: evaluationLookbackDays,
                        maximumEvaluationSessions:
                            maximumEvaluationSessions,
                        autoConfirmLimit: autoConfirmLimit,
                        compactRetryRemainingAttempts:
                            nextRemainingAttempts,
                        settlementAuthority: settlementAuthority,
                        executionShouldContinue:
                            executionShouldContinue
                    )
                }
            }
        }
    }

    private func foregroundSleepSettlementFingerprint(
        rest: Int,
        baselineRestingIsTrusted: Bool,
        baselineRestingIsNearTrusted: Bool,
        maxHR: Int
    ) -> ForegroundSleepSettlementFingerprint {
        ForegroundSleepSettlementFingerprint(
            canonicalSessionsRevision: canonicalSessionsRevision,
            confirmedSleepsRevision: confirmedSleepsRevision,
            restingHR: rest,
            baselineRestingIsTrusted: baselineRestingIsTrusted,
            baselineRestingIsNearTrusted: baselineRestingIsNearTrusted,
            maxHR: maxHR
        )
    }

    nonisolated static func shouldCommitForegroundSleepSettlement(
        completedGeneration: Int,
        currentGeneration: Int,
        preparedFingerprint: ForegroundSleepSettlementFingerprint,
        currentFingerprint: ForegroundSleepSettlementFingerprint
    ) -> Bool {
        completedGeneration == currentGeneration
            && preparedFingerprint == currentFingerprint
    }

    nonisolated static func makeForegroundSleepSettlementProposal(
        fingerprint: ForegroundSleepSettlementFingerprint,
        canonicalSessions: [SavedSession],
        activeJournalSession: SavedSession?,
        now: Date,
        rest: Int,
        maxHR: Int,
        learnedWindow: (start: Int, end: Int)?,
        lookbackDays: Int = foregroundSleepEvaluationLookbackDays,
        maximumSessions: Int = foregroundSleepEvaluationMaximumSessions,
        historicalMotionPolicy: HistoricalSleepMotionPolicy = .boundedRecent
    ) -> ForegroundSleepSettlementProposal {
        let foregroundSessions = foregroundSleepEvaluationSessions(
            from: canonicalSessions,
            activeJournalSession: activeJournalSession,
            now: now,
            lookbackDays: lookbackDays,
            maximumSessions: maximumSessions
        )
        let strongCandidates = aggregateSleepCandidates(
            in: foregroundSessions,
            rest: rest,
            maxHR: maxHR,
            calendar: .current,
            historicalMotionPolicy: historicalMotionPolicy
        ).filter {
            isAutoConfirmableMainSleepCandidate(
                $0,
                baselineRestingIsTrusted: fingerprint.baselineRestingIsTrusted,
                baselineRestingIsNearTrusted: fingerprint.baselineRestingIsNearTrusted
            )
        }
        let wakeBoundary = prepareWakeBoundarySleep(
            sourceSessions: foregroundSessions,
            rest: rest,
            maxHR: maxHR,
            now: now,
            learnedWindow: learnedWindow,
            baselineRestingIsTrusted: fingerprint.baselineRestingIsTrusted,
            baselineRestingIsNearTrusted: fingerprint.baselineRestingIsNearTrusted,
            historicalMotionPolicy: historicalMotionPolicy
        )
        return ForegroundSleepSettlementProposal(
            fingerprint: fingerprint,
            preparedAt: now,
            sourceSessions: foregroundSessions,
            strongCandidates: strongCandidates,
            wakeBoundary: wakeBoundary
        )
    }

    /// Checked latest-night variant. It shares one absolute deadline across
    /// candidate aggregation, wake detection, and every derived physiology
    /// materialization that the MainActor will later commit.
    nonisolated static func makeForegroundSleepSettlementProposal(
        fingerprint: ForegroundSleepSettlementFingerprint,
        canonicalSessions: [SavedSession],
        activeJournalSession: SavedSession?,
        now: Date,
        rest: Int,
        maxHR: Int,
        learnedWindow: (start: Int, end: Int)?,
        lookbackDays: Int = foregroundSleepEvaluationLookbackDays,
        maximumSessions: Int = foregroundSleepEvaluationMaximumSessions,
        historicalMotionPolicy: HistoricalSleepMotionPolicy = .boundedRecent,
        cooperativeDeadline: AtriaSleepSettlementDeadline,
        autoConfirmLimit: Int = 2
    ) throws -> ForegroundSleepSettlementProposal {
        try cooperativeDeadline.checkpoint()
        let foregroundSessions = foregroundSleepEvaluationSessions(
            from: canonicalSessions,
            activeJournalSession: activeJournalSession,
            now: now,
            lookbackDays: lookbackDays,
            maximumSessions: maximumSessions
        )
        try cooperativeDeadline.checkpoint()
        let aggregated = try aggregateSleepCandidates(
            in: foregroundSessions,
            rest: rest,
            maxHR: maxHR,
            calendar: .current,
            historicalMotionPolicy: historicalMotionPolicy,
            cooperativeDeadline: cooperativeDeadline,
            includeResumedReviewCandidates: false
        )
        var strongCandidates: [AggregateSleepCandidate] = []
        strongCandidates.reserveCapacity(aggregated.count)
        for candidate in aggregated {
            try cooperativeDeadline.checkpoint()
            if isAutoConfirmableMainSleepCandidate(
                candidate,
                baselineRestingIsTrusted:
                    fingerprint.baselineRestingIsTrusted,
                baselineRestingIsNearTrusted:
                    fingerprint.baselineRestingIsNearTrusted
            ) {
                strongCandidates.append(candidate)
            }
        }
        var wakeBoundary = try prepareWakeBoundarySleep(
            sourceSessions: foregroundSessions,
            rest: rest,
            maxHR: maxHR,
            now: now,
            learnedWindow: learnedWindow,
            baselineRestingIsTrusted:
                fingerprint.baselineRestingIsTrusted,
            baselineRestingIsNearTrusted:
                fingerprint.baselineRestingIsNearTrusted,
            historicalMotionPolicy: historicalMotionPolicy,
            cooperativeDeadline: cooperativeDeadline
        )
        var preparedStrong: [ForegroundSleepSettlementProposal
            .PreparedAutoSleepMaterialization] = []
        let boundedLimit = min(max(0, autoConfirmLimit), 2)
        if boundedLimit > 0 {
            for candidate in strongCandidates where preparedStrong.count < boundedLimit {
                try cooperativeDeadline.checkpoint()
                guard sleepCandidateIsSettledForClosedAutoConfirmation(
                    candidateEnd: candidate.end,
                    now: now
                ) else { continue }
                if let prepared = try preparedAutoSleepMaterialization(
                    candidate: candidate,
                    sourceSessions: foregroundSessions,
                    fingerprint: fingerprint,
                    preparedAt: now,
                    cooperativeDeadline: cooperativeDeadline
                ) {
                    preparedStrong.append(prepared)
                }
            }
        }
        if let wakeCandidate = wakeBoundary.candidate {
            let preparedWake = try preparedAutoSleepMaterialization(
                candidate: wakeCandidate,
                sourceSessions: foregroundSessions,
                fingerprint: fingerprint,
                preparedAt: now,
                cooperativeDeadline: cooperativeDeadline
            )
            wakeBoundary = .init(
                candidate: wakeCandidate,
                preparedCandidate: preparedWake,
                blocker: preparedWake == nil
                    ? "candidate_materialization_withheld"
                    : wakeBoundary.blocker,
                windowEndMinute: wakeBoundary.windowEndMinute,
                nowMinute: wakeBoundary.nowMinute,
                learnedWindow: wakeBoundary.learnedWindow
            )
        }
        try cooperativeDeadline.checkpoint()
        return .init(
            fingerprint: fingerprint,
            preparedAt: now,
            sourceSessions: foregroundSessions,
            strongCandidates: strongCandidates,
            preparedStrongCandidates: preparedStrong,
            wakeBoundary: wakeBoundary
        )
    }

    private nonisolated static func preparedAutoSleepMaterialization(
        candidate: AggregateSleepCandidate,
        sourceSessions: [SavedSession],
        fingerprint: ForegroundSleepSettlementFingerprint,
        preparedAt: Date,
        cooperativeDeadline: AtriaSleepSettlementDeadline
    ) throws -> ForegroundSleepSettlementProposal
        .PreparedAutoSleepMaterialization? {
        try cooperativeDeadline.checkpoint()
        let classification = autoSleepClassification(
            for: candidate,
            baselineRestingIsTrusted:
                fingerprint.baselineRestingIsTrusted,
            baselineRestingIsNearTrusted:
                fingerprint.baselineRestingIsNearTrusted
        )
        guard classification.allowsAutomaticPersistence else { return nil }
        let metrics = try confirmedSleepWindowMetrics(
            from: sourceSessions,
            start: candidate.start,
            end: candidate.end,
            rest: candidate.restingHR,
            cooperativeDeadline: cooperativeDeadline
        )
        let respiratoryRate = try confirmedSleepRespiratoryRate(
            from: sourceSessions,
            start: candidate.start,
            end: candidate.end,
            cooperativeDeadline: cooperativeDeadline
        )
        var stageSegments = try sleepStageResearchSegments(
            from: sourceSessions,
            start: candidate.start,
            end: candidate.end,
            restingHR: candidate.restingHR,
            isNap: candidate.kind == "nap_candidate",
            motionValidated: classification.motionValidated,
            maximumRows: compactLatestNightMaximumStagingRows,
            cooperativeDeadline: cooperativeDeadline
        )
        if !stageSegments.isEmpty,
           !AtriaSleepStageIntegrity.validates(
                stageSegments,
                start: candidate.start,
                end: candidate.end,
                duration: candidate.duration,
                span: candidate.span
           ) {
            stageSegments.removeAll(keepingCapacity: false)
        }
        try cooperativeDeadline.checkpoint()
        return .init(
            key: .init(candidate),
            candidate: candidate,
            classification: classification,
            metrics: .init(
                sessions: metrics.sessions,
                samples: metrics.samples,
                avgHR: metrics.avgHR,
                peakHR: metrics.peakHR,
                restingHR: metrics.restingHR,
                hrv: metrics.hrv,
                hrvWindowCount: metrics.hrvWindowCount
            ),
            respiratoryRate: respiratoryRate,
            stageSegments: stageSegments.isEmpty ? nil : stageSegments,
            preparedAt: preparedAt
        )
    }

    @discardableResult
    private func autoConfirmStrongSleepCandidates(reason: String,
                                                   limit: Int = 2,
                                                   sourceSessions: [SavedSession]? = nil,
                                                   precomputedStrongCandidates: [AggregateSleepCandidate]? = nil,
                                                   precomputedMaterializations: [ForegroundSleepSettlementProposal.PreparedAutoSleepMaterialization] = [],
                                                   evaluationNow: Date = Date(),
                                                   deferDerivedPublication: Bool = false,
                                                   archiveFreeLatestNightSettlement: Bool = false,
                                                   persistenceFailure: (() -> Void)? = nil,
                                                   settlementAuthority:
                                                    ForegroundSleepSettlementAuthority? = nil,
                                                   executionShouldContinue:
                                                    @escaping @Sendable () -> Bool = { true }) async -> Bool {
        let rest = baseline.restingInt ?? 60
        let now = evaluationNow
        let baselineRestingIsTrusted = baseline.restingInt != nil
            && baseline.hasTrustedRestingBaseline(now: now)
        let baselineRestingIsNearTrusted = baseline.restingInt != nil
            && baseline.hasNearTrustedRestingBaselineForFragmentedSleep(now: now)
        let candidatePool = precomputedStrongCandidates ?? Self.aggregateSleepCandidates(
            in: sourceSessions ?? canonicalSessions(includeActiveJournal: true),
            rest: rest,
            maxHR: profile.maxHR,
            calendar: .current,
            historicalMotionPolicy: .boundedRecent
        )
        let strongCandidates = candidatePool.filter {
            Self.isAutoConfirmableMainSleepCandidate(
                $0,
                baselineRestingIsTrusted: baselineRestingIsTrusted,
                baselineRestingIsNearTrusted: baselineRestingIsNearTrusted
            )
        }
        let candidates = strongCandidates.filter {
            Self.sleepCandidateIsSettledForClosedAutoConfirmation(candidateEnd: $0.end, now: now)
        }
        let unsettledCandidates = strongCandidates.filter {
            !Self.sleepCandidateIsSettledForClosedAutoConfirmation(candidateEnd: $0.end, now: now)
        }
        if !unsettledCandidates.isEmpty {
            let retryAuthority = settlementAuthority ?? .processForeground(
                generation: AtriaHistoricalProjectionForegroundGate
                    .currentGeneration
            )
            scheduleSleepSettlementRetry(
                for: unsettledCandidates,
                reason: reason,
                now: now,
                settlementAuthority: retryAuthority,
                executionShouldContinue: executionShouldContinue
            )
        }
        guard !candidates.isEmpty else {
            let skipReason = strongCandidates.isEmpty ? "no_strong_candidate" : "candidate_not_settled"
            // Distinguish "nothing was proposed" from "things were proposed and
            // none can auto-confirm". `strongCandidates` is the AUTO-CONFIRMABLE
            // subset of `candidatePool`, so the old single message — "No sleep
            // candidates found" — was reported for both, and they are different
            // problems with different fixes: an empty POOL means the generator
            // refused the night, while a full pool with no strong members means
            // the auto-confirm predicate did.
            //
            // This is not hypothetical. Reading that message on 2026-08-27 I
            // concluded the owner's 13:00-20:30 sleep produced no candidate at
            // all and spent several passes on the candidate LANES, when the
            // pool size was never in evidence either way.
            let detail: String
            if strongCandidates.isEmpty {
                if candidatePool.isEmpty {
                    detail = "No sleep candidates proposed at all (source: \(reason))"
                } else {
                    // Name the near-miss. The longest proposed candidate is the
                    // one most likely to have been the real night, and its HR
                    // coverage is the gate that most often decides: both
                    // auto-confirm lanes require
                    // `minimumAutoConfirmHRCoverageFraction`.
                    //
                    // Device 2026-08-27: this owner's real five-hour sleep
                    // measured 0.789 coverage against a 0.80 floor, missing by
                    // roughly five minutes of undrained history, and NOTHING
                    // anywhere said so — the app reported only that no sleep
                    // was found. A near-miss the user can see is a different
                    // product from a silent one.
                    let best = candidatePool.max(by: { $0.duration < $1.duration })
                    let coverage = best.map {
                        Int(($0.hrObservedCoverageFraction * 100).rounded())
                    }
                    let hours = best.map { $0.duration / 3600 }
                    let floor = Int(
                        (AggregateSleepCandidate
                            .minimumAutoConfirmHRCoverageFraction * 100).rounded()
                    )
                    if let coverage, let hours {
                        detail = String(
                            format: "%d sleep candidate(s) proposed, none auto-confirmable. "
                                + "Longest is %.1f h with %d%% heart-rate coverage "
                                + "(needs %d%%) (source: %@)",
                            candidatePool.count, hours, coverage, floor, reason
                        )
                    } else {
                        detail = "\(candidatePool.count) sleep candidate(s) proposed, "
                            + "none auto-confirmable (source: \(reason))"
                    }
                }
            } else {
                detail = "Sleep candidate is still settling so later low-motion "
                    + "fragments can join it (source: \(reason))"
            }
            AtriaDebugLog("ATRIADBG sleep_auto_confirm status=skipped reason=%@ source=%@ pool=%d strong=%d",
                          skipReason,
                          reason,
                          candidatePool.count,
                          strongCandidates.count)
            DetectionEventLog.append(DetectionEvent(kind: "sleepCandidateSkipped",
                                                     reason: skipReason,
                                                     detail: detail))
            return false
        }

        var existing = cachedConfirmedSleeps
        var saved = 0
        var firstSavedOvernight: UserConfirmedSleep?
        var stressContextChanged = false
        // Records this pass mints or extends, re-checked against freshly
        // loaded dismissal tombstones immediately before the persist writes —
        // the loop check below cannot see a "not sleep" tap that lands during
        // the save's own suspension points.
        var saveTimeRecheckIDs: Set<String> = []
        for candidate in candidates.prefix(limit) {
            guard !dismissedSleepCandidates.contains(where: {
                $0.suppresses(start: candidate.start, end: candidate.end)
            }) else { continue }
            let classification = Self.autoSleepClassification(
                for: candidate,
                baselineRestingIsTrusted: baselineRestingIsTrusted,
                baselineRestingIsNearTrusted: baselineRestingIsNearTrusted
            )
            guard classification.allowsAutomaticPersistence else {
                // A candidate predicate and its source classifier previously
                // diverged here: the strict fragmented HR-only tier cleared
                // the baseline-aware gate, then was persisted with
                // source=sleep_review_hr_only/confidence=low. Review evidence
                // must remain actionable, never silently saved.
                AtriaDebugLog("ATRIADBG sleep_auto_confirm status=skipped reason=review_only_classification source=%@ candidate_source=%@ confidence=%@",
                              reason,
                              classification.source,
                              classification.confidence)
                DetectionEventLog.append(DetectionEvent(
                    kind: "sleepCandidateSkipped",
                    reason: "review_only_classification",
                    detail: "Automatic persistence rejected \(classification.source) (source: \(reason))"
                ))
                continue
            }
            let preparedMaterialization = precomputedMaterializations.first {
                $0.key == .init(candidate)
            }
            if archiveFreeLatestNightSettlement {
                guard let preparedMaterialization,
                      preparedMaterialization.classification
                        == classification else {
                    DetectionEventLog.append(DetectionEvent(
                        kind: "sleepCandidateSkipped",
                        reason: "compact_materialization_stale_or_missing",
                        detail: "Prepared sleep physiology no longer matches the current classification (source: \(reason))"
                    ))
                    continue
                }
            }
            let id = confirmedSleepID(start: candidate.start,
                                     end: candidate.end,
                                     source: classification.source)
            // Wake-then-sleep-again grew the night: extend the confirmed auto night
            // in place instead of skipping the candidate as a duplicate (user
            // 2026-07-08). applySleepExtend is extend-only and never touches a
            // manual/adjusted night, so it can't clobber a user override.
            if let extended = applySleepExtend(
                to: &existing,
                candidate: candidate,
                classification: classification,
                reason: "\(reason)_extend",
                sourceSessions: sourceSessions,
                precomputedMaterialization: preparedMaterialization
            ) {
                stressContextChanged = stressContextChanged
                    || Self.sleepStressContextAuthority(extended) != nil
                saveTimeRecheckIDs.insert(extended.id)
                saved += 1
                continue
            }
            if existing.contains(where: { $0.id == id }) {
                continue
            }
            guard let insertionBase = Self.sleepInsertionBase(existing: existing, candidate: candidate) else { continue }

            let confirmed: UserConfirmedSleep
            if let preparedMaterialization {
                confirmed = buildAutoConfirmedSleep(
                    from: preparedMaterialization,
                    reason: reason
                )
            } else {
                confirmed = buildAutoConfirmedSleep(
                    from: candidate,
                    classification: classification,
                    reason: reason,
                    sourceSessions: sourceSessions
                )
            }
            existing = insertionBase
            existing.append(confirmed)
            saveTimeRecheckIDs.insert(confirmed.id)
            if candidate.kind != "nap_candidate", firstSavedOvernight == nil {
                firstSavedOvernight = confirmed
            }
            stressContextChanged = stressContextChanged
                || Self.sleepStressContextAuthority(confirmed) != nil
            saved += 1
        }

        guard saved > 0 else {
            AtriaDebugLog("ATRIADBG sleep_auto_confirm status=skipped reason=already_saved_or_overlapping source=%@ candidates=%d",
                          reason,
                          candidates.count)
            DetectionEventLog.append(DetectionEvent(kind: "sleepCandidateSkipped",
                                                     reason: "already_saved_or_overlapping",
                                                     detail: "\(candidates.count) candidate(s), all already saved or overlapping"))
            return false
        }
        if unsettledCandidates.isEmpty {
            pendingSleepSettlementRetry?.cancel()
            pendingSleepSettlementRetry = nil
        }
        let dismissalRecheck = AutoConfirmSaveTimeDismissalRecheck(
            recordIDs: saveTimeRecheckIDs
        )
        guard await saveConfirmedSleeps(existing,
                                  deferDerivedPublication: deferDerivedPublication,
                                  archiveFreeLatestNightSettlement:
                                    archiveFreeLatestNightSettlement,
                                  publishStressContext:
                                    stressContextChanged,
                                  autoConfirmDismissalRecheck: dismissalRecheck,
                                  executionShouldContinue:
                                    executionShouldContinue) else {
            persistenceFailure?()
            AtriaDebugLog("ATRIADBG sleep_auto_confirm status=store_failed source=%@ saved=%d", reason, saved)
            return false
        }
        // A record dropped by the save-time re-check honored a dismissal that
        // landed mid-flight: never banner or notify it as logged sleep, and
        // retract an extend-path banner that already points at a dropped id.
        if let banner = autoSleepLoggedBanner,
           dismissalRecheck.suppressedIDs.contains(banner.sleepID) {
            autoSleepLoggedBanner = nil
        }
        if let firstSavedOvernight,
           !dismissalRecheck.suppressedIDs.contains(firstSavedOvernight.id) {
            autoSleepLoggedBanner = AutoSleepLoggedBanner(id: firstSavedOvernight.id,
                                                          start: firstSavedOvernight.start,
                                                          end: firstSavedOvernight.end,
                                                          duration: firstSavedOvernight.duration,
                                                          sleepID: firstSavedOvernight.id)
            LocalNotificationScheduler.scheduleSleepLogged(firstSavedOvernight)
        }
        AtriaDebugLog("ATRIADBG sleep_auto_confirm status=saved source=%@ saved=%d candidates=%d save_time_suppressed=%d policy=motion_or_unambiguous_hr_only",
                      reason,
                      saved,
                      candidates.count,
                      dismissalRecheck.suppressedIDs.count)
        if let firstSavedOvernight,
           !dismissalRecheck.suppressedIDs.contains(firstSavedOvernight.id) {
            DetectionEventLog.append(DetectionEvent(kind: "sleepAutoConfirmed",
                                                     detail: "\(isoString(firstSavedOvernight.start))–\(isoString(firstSavedOvernight.end)), \(SleepHistorySnapshot.formatDuration(firstSavedOvernight.duration))"))
        }
        return true
    }

    /// Closed-session auto-confirm waits long enough for a brief rollover or
    /// connectivity gap to reveal a continuing sleep fragment. Wake-boundary
    /// confirmation has its own sustained-wake gate and does not use this delay.
    nonisolated static func sleepCandidateIsSettledForClosedAutoConfirmation(
        candidateEnd: Date,
        now: Date,
        settlementDelay: TimeInterval = 30 * 60
    ) -> Bool {
        now.timeIntervalSince(candidateEnd) >= settlementDelay
    }

    func dismissAutoSleepLoggedBanner(id: String) {
        guard autoSleepLoggedBanner?.id == id else { return }
        autoSleepLoggedBanner = nil
    }

    /// Single build path for a `UserConfirmedSleep` from an already-gated
    /// `AggregateSleepCandidate`, shared by the closed-session strong-candidate
    /// path (`autoConfirmStrongSleepCandidates`) and the wake-boundary path
    /// (`commitPreparedWakeBoundarySleepIfUseful`) so both go through exactly the same
    /// classification/stage-segment/metrics/save shape.
    private func buildAutoConfirmedSleep(from candidate: AggregateSleepCandidate,
                                         classification: AutoSleepClassification,
                                         reason: String,
                                         sourceSessions: [SavedSession]? = nil,
                                         existingEventTimeZoneIdentifier: String? = nil) -> UserConfirmedSleep {
        precondition(classification.allowsAutomaticPersistence,
                     "Review-only sleep classification cannot build an automatic persisted sleep")
        let id = confirmedSleepID(start: candidate.start, end: candidate.end, source: classification.source)
        let constructionSessions = sourceSessions ?? canonicalSessions(includeActiveJournal: true)
        let stageSegments = Self.sleepStageResearchSegments(from: constructionSessions,
                                                            start: candidate.start,
                                                            end: candidate.end,
                                                            restingHR: candidate.restingHR,
                                                            isNap: candidate.kind == "nap_candidate",
                                                            motionValidated: classification.motionValidated)
        let metrics = Self.confirmedSleepWindowMetrics(from: constructionSessions,
                                                       start: candidate.start,
                                                       end: candidate.end,
                                                       rest: candidate.restingHR)
        let sleep = UserConfirmedSleep(id: id,
                                       createdAt: Date(),
                                       start: candidate.start,
                                       end: candidate.end,
                                       source: classification.source,
                                       confidence: classification.confidence,
                                       sessions: candidate.sessions,
                                       samples: candidate.samples,
                                       avgHR: candidate.avgHR,
                                       peakHR: candidate.peakHR,
                                       restingHR: candidate.restingHR,
                                       hrv: metrics.hrv,
                                       hrvWindowCount: metrics.hrvWindowCount,
                                       respiratoryRate: Self.confirmedSleepRespiratoryRate(
                                        from: constructionSessions,
                                        start: candidate.start,
                                        end: candidate.end
                                       ),
                                       duration: candidate.duration,
                                       span: candidate.span,
                                       reason: "\(reason); \(candidate.reason)",
                                       motionSource: classification.motionSource,
                                       motionValidated: classification.motionValidated,
                                       stageSegments: stageSegments.isEmpty ? nil : stageSegments,
                                       eventTimeZoneIdentifier: Self.autoSleepEventTimeZoneIdentifier(
                                        for: candidate,
                                        existingEventTimeZoneIdentifier: existingEventTimeZoneIdentifier
                                       ))
        guard !stageSegments.isEmpty else { return sleep }
        guard !AtriaSleepStageIntegrity.validates(stageSegments, for: sleep) else { return sleep }
        AtriaDebugLog("ATRIADBG sleep_stage_integrity status=suppressed source=%@ sleep_s=%.0f span_s=%.0f segments=%d",
                      classification.source,
                      candidate.duration,
                      candidate.span,
                      stageSegments.count)
        return Self.copyConfirmedSleep(sleep, stageSegments: nil)
    }

    /// Scalar-only materialization for the compact lane. Stage/HRV/respiration
    /// were derived and integrity-checked on the utility worker; this method
    /// performs no session scan and no model work on the MainActor.
    private func buildAutoConfirmedSleep(
        from prepared: ForegroundSleepSettlementProposal
            .PreparedAutoSleepMaterialization,
        reason: String,
        existingEventTimeZoneIdentifier: String? = nil
    ) -> UserConfirmedSleep {
        let candidate = prepared.candidate
        let classification = prepared.classification
        precondition(classification.allowsAutomaticPersistence)
        return UserConfirmedSleep(
            id: confirmedSleepID(
                start: candidate.start,
                end: candidate.end,
                source: classification.source
            ),
            createdAt: Date(),
            start: candidate.start,
            end: candidate.end,
            source: classification.source,
            confidence: classification.confidence,
            sessions: candidate.sessions,
            samples: candidate.samples,
            avgHR: candidate.avgHR,
            peakHR: candidate.peakHR,
            restingHR: candidate.restingHR,
            hrv: prepared.metrics.hrv,
            hrvWindowCount: prepared.metrics.hrvWindowCount,
            respiratoryRate: prepared.respiratoryRate,
            duration: candidate.duration,
            span: candidate.span,
            reason: "\(reason); \(candidate.reason)",
            motionSource: classification.motionSource,
            motionValidated: classification.motionValidated,
            stageSegments: prepared.stageSegments,
            eventTimeZoneIdentifier: Self.autoSleepEventTimeZoneIdentifier(
                for: candidate,
                existingEventTimeZoneIdentifier:
                    existingEventTimeZoneIdentifier
            )
        )
    }

    // MARK: - Wake-boundary sleep confirm (WHOOP-parity finalize-at-wake)

    /// Constants for the wake-boundary evaluation path: confirms the still-open
    /// overnight session at the detected/learned wake point instead of waiting
    /// for a closed session that continuous checkpointed recording never
    /// produces. See `prepareWakeBoundarySleep`.
    private enum WakeBoundaryDefaults {
        /// Mirrors `AtriaBLEManager.DutyCycleDefaults`'s own fallback window so
        /// the two subsystems agree on "night" before any confirmed sleep has
        /// been learned (n<3).
        static let fallbackWindowStartMin = 23 * 60 + 30
        static let fallbackWindowEndMin = 10 * 60 + 30
        /// The fallback (no learned window yet) path only ever fires inside
        /// this morning core, even though `now >= fallbackWindowEndMin` would
        /// otherwise hold for most of the day — bounds the unlearned path to a
        /// narrow, safe morning slot.
        static let fallbackMorningCoreStartMin = 9 * 60
        static let fallbackMorningCoreEndMin = 11 * 60
        static let sustainedWakeHRDelta = 15
        static let sustainedWakeLookback: TimeInterval = 25 * 60
        static let minNightAnchorAge: TimeInterval = 3 * 60 * 60
    }

    private nonisolated static func minutesOfDay(_ date: Date, calendar: Calendar) -> Int {
        let components = calendar.dateComponents([.hour, .minute], from: date)
        return (components.hour ?? 0) * 60 + (components.minute ?? 0)
    }

    private nonisolated static func minuteInsideWindow(_ minute: Int, start: Int, end: Int) -> Bool {
        start <= end ? (minute >= start && minute <= end) : (minute >= start || minute <= end)
    }

    /// Learned duty-cycle sleep window (docs/24 §13), read back for the wake
    /// boundary. `nil` when fewer than 3 overnights have been learned yet —
    /// `writeDutyCycleSleepWindow` never writes either key until then — so this
    /// distinguishes "no learned window" from a legitimately-zero minute-of-day.
    private nonisolated static func learnedDutyCycleSleepWindow(defaults: UserDefaults) -> (start: Int, end: Int)? {
        guard defaults.object(forKey: AtriaBLEManager.DutyCycleDefaults.sleepWindowStartMin) != nil,
              defaults.object(forKey: AtriaBLEManager.DutyCycleDefaults.sleepWindowEndMin) != nil else {
            return nil
        }
        let start = defaults.integer(forKey: AtriaBLEManager.DutyCycleDefaults.sleepWindowStartMin)
        let end = defaults.integer(forKey: AtriaBLEManager.DutyCycleDefaults.sleepWindowEndMin)
        return (min(max(start, 0), 1439), min(max(end, 0), 1439))
    }

    /// The nearest instant of day `minuteOfDay` that falls after `start` and
    /// at/before `upperBound`, checked up to two days out so a window that
    /// starts before midnight still resolves to the following morning.
    private nonisolated static func nearestMinuteOfDayInstant(after start: Date,
                                                              minuteOfDay: Int,
                                                              calendar: Calendar,
                                                              upperBound: Date) -> Date? {
        let startDay = calendar.startOfDay(for: start)
        var best: Date?
        for offset in 0...2 {
            guard let day = calendar.date(byAdding: .day, value: offset, to: startDay),
                  let candidate = calendar.date(bySettingHour: minuteOfDay / 60,
                                                minute: minuteOfDay % 60,
                                                second: 0,
                                                of: day),
                  candidate > start, candidate <= upperBound else { continue }
            if best == nil || candidate < best! { best = candidate }
        }
        return best
    }

    /// First sample where the trailing rolling-median HR (over `lookback`,
    /// 20-30min) crosses `restingHR + delta` and stays there through the end of
    /// `session` — the onset of a sustained wake run, not a transient artifact
    /// spike. `nil` when no such sustained run exists in the tail.
    ///
    /// Exposed (not `private`) so unit tests can exercise the wake detector
    /// directly against constructed `SavedSession` fixtures, matching the
    /// `isStrongAutoConfirmableSleepCandidate` pure-static-testing pattern.
    nonisolated static func sustainedWakeOnset(in session: SavedSession,
                                                       restingHR: Int,
                                                       delta: Int = WakeBoundaryDefaults.sustainedWakeHRDelta,
                                                       lookback: TimeInterval = WakeBoundaryDefaults.sustainedWakeLookback) -> Date? {
        try? sustainedWakeOnsetCore(
            in: session,
            restingHR: restingHR,
            delta: delta,
            lookback: lookback,
            cooperativeDeadline: nil
        )
    }

    nonisolated static func sustainedWakeOnset(
        in session: SavedSession,
        restingHR: Int,
        delta: Int = WakeBoundaryDefaults.sustainedWakeHRDelta,
        lookback: TimeInterval = WakeBoundaryDefaults.sustainedWakeLookback,
        cooperativeDeadline: AtriaSleepSettlementDeadline
    ) throws -> Date? {
        try sustainedWakeOnsetCore(
            in: session,
            restingHR: restingHR,
            delta: delta,
            lookback: lookback,
            cooperativeDeadline: cooperativeDeadline
        )
    }

    private nonisolated static func sustainedWakeOnsetCore(
        in session: SavedSession,
        restingHR: Int,
        delta: Int,
        lookback: TimeInterval,
        cooperativeDeadline: AtriaSleepSettlementDeadline?
    ) throws -> Date? {
        try cooperativeDeadline?.checkpoint()
        var points = session.points
        try cooperativeStableSort(
            &points,
            cooperativeDeadline: cooperativeDeadline,
            areInIncreasingOrder: { $0.t < $1.t }
        )
        guard points.count >= 3 else { return nil }
        let threshold = restingHR + delta
        var uniqueBPMSet = Set<Int>()
        var uniqueBPM: [Int] = []
        for (index, point) in points.enumerated() {
            if index.isMultiple(of: 256) {
                try cooperativeDeadline?.checkpoint()
            }
            if uniqueBPMSet.insert(point.bpm).inserted {
                uniqueBPM.append(point.bpm)
            }
        }
        try cooperativeStableSort(
            &uniqueBPM,
            cooperativeDeadline: cooperativeDeadline,
            areInIncreasingOrder: <
        )
        var bpmIndices: [Int: Int] = [:]
        bpmIndices.reserveCapacity(uniqueBPM.count)
        for (index, bpm) in uniqueBPM.enumerated() {
            if index.isMultiple(of: 256) {
                try cooperativeDeadline?.checkpoint()
            }
            bpmIndices[bpm] = index
        }
        struct FenwickTree {
            var values: [Int]

            init(count: Int) {
                values = Array(repeating: 0, count: count + 1)
            }

            mutating func add(index: Int, delta: Int) {
                var position = index + 1
                while position < values.count {
                    values[position] += delta
                    position += position & -position
                }
            }

            func value(atZeroBasedRank rank: Int) -> Int {
                var position = 0
                var bit = 1
                while bit < values.count { bit <<= 1 }
                var remaining = rank + 1
                var step = bit
                while step > 0 {
                    let next = position + step
                    if next < values.count,
                       values[next] < remaining {
                        position = next
                        remaining -= values[next]
                    }
                    step >>= 1
                }
                return position
            }
        }

        var rollingMedians: [Int] = []
        rollingMedians.reserveCapacity(points.count)
        var windowStart = 0
        var counts = FenwickTree(count: uniqueBPM.count)
        for i in 0..<points.count {
            if i.isMultiple(of: 256) {
                try cooperativeDeadline?.checkpoint()
            }
            guard let currentIndex = bpmIndices[points[i].bpm] else {
                return nil
            }
            counts.add(index: currentIndex, delta: 1)
            while points[windowStart].t < points[i].t - lookback {
                guard let removedIndex = bpmIndices[points[windowStart].bpm]
                else { return nil }
                counts.add(index: removedIndex, delta: -1)
                windowStart += 1
            }
            let windowCount = i - windowStart + 1
            let mid = windowCount / 2
            let upperBPM = uniqueBPM[counts.value(atZeroBasedRank: mid)]
            let median: Int
            if windowCount.isMultiple(of: 2) {
                let lowerBPM = uniqueBPM[
                    counts.value(atZeroBasedRank: mid - 1)
                ]
                median = (lowerBPM + upperBPM) / 2
            } else {
                median = upperBPM
            }
            rollingMedians.append(median)
        }
        try cooperativeDeadline?.checkpoint()
        guard let lastMedian = rollingMedians.last, lastMedian >= threshold else { return nil }
        var onsetIndex = rollingMedians.count - 1
        while onsetIndex > 0, rollingMedians[onsetIndex - 1] >= threshold {
            onsetIndex -= 1
            if onsetIndex.isMultiple(of: 256) {
                try cooperativeDeadline?.checkpoint()
            }
        }
        return session.start.addingTimeInterval(points[onsetIndex].t)
    }

    /// Trims `session` to only the samples at/before `wakePoint`, so the
    /// existing cluster -> `AggregateSleepCandidate` math in
    /// `aggregateSleepCandidates(in:...)` computes avgHR/SD/median/P90/
    /// elevatedFraction over the sleep portion only, with `end == wakePoint`.
    private nonisolated static func sessionTrimmedAtWakePoint(_ session: SavedSession, wakePoint: Date) -> SavedSession? {
        try? sessionTrimmedAtWakePointCore(
            session,
            wakePoint: wakePoint,
            cooperativeDeadline: nil
        )
    }

    private nonisolated static func sessionTrimmedAtWakePointCore(
        _ session: SavedSession,
        wakePoint: Date,
        cooperativeDeadline: AtriaSleepSettlementDeadline?
    ) throws -> SavedSession? {
        try cooperativeDeadline?.checkpoint()
        guard wakePoint > session.start else { return nil }
        let cutoff = wakePoint.timeIntervalSince(session.start)
        var trimmedPoints: [SavedSession.Point] = []
        trimmedPoints.reserveCapacity(session.points.count)
        for (index, point) in session.points.enumerated() {
            if index.isMultiple(of: 512) {
                try cooperativeDeadline?.checkpoint()
            }
            if point.t <= cutoff {
                trimmedPoints.append(point)
            }
        }
        guard trimmedPoints.count >= 2 else { return nil }
        return SavedSession(id: session.id,
                           start: session.start,
                           end: wakePoint,
                           label: session.label,
                           points: trimmedPoints,
                           eventTimeZoneIdentifier: session.eventTimeZoneIdentifier)
    }

    /// Synthesizes a clean, ended overnight `AggregateSleepCandidate` from a
    /// still-open (or long-running) night `session` by trimming its awake
    /// morning tail at the detected/learned wake point, then routing the
    /// trimmed session through the exact same eligibility + clustering math
    /// every other sleep candidate goes through (never a new/weaker gate).
    /// Returns `nil` when the wake point can't be resolved or the trim leaves
    /// too little data to cluster.
    ///
    /// Exposed (not `private`) so unit tests can exercise the wake-boundary
    /// synthesis directly against constructed `SavedSession` fixtures.
    nonisolated static func wakeBoundarySleepCandidate(session: SavedSession,
                                                               windowEndMinute: Int,
                                                               rest: Int,
                                                               maxHR: Int,
                                                               calendar: Calendar,
                                                               now: Date,
                                                               historicalMotionPolicy: HistoricalSleepMotionPolicy = .boundedRecent) -> AggregateSleepCandidate? {
        try? wakeBoundarySleepCandidateCore(
            session: session,
            windowEndMinute: windowEndMinute,
            rest: rest,
            maxHR: maxHR,
            calendar: calendar,
            now: now,
            historicalMotionPolicy: historicalMotionPolicy,
            resolvedWakeOnset: nil,
            shouldComputeWakeOnset: true,
            cooperativeDeadline: nil
        )
    }

    private nonisolated static func wakeBoundarySleepCandidate(
        session: SavedSession,
        windowEndMinute: Int,
        rest: Int,
        maxHR: Int,
        calendar: Calendar,
        now: Date,
        historicalMotionPolicy: HistoricalSleepMotionPolicy,
        resolvedWakeOnset: Date?,
        cooperativeDeadline: AtriaSleepSettlementDeadline
    ) throws -> AggregateSleepCandidate? {
        try wakeBoundarySleepCandidateCore(
            session: session,
            windowEndMinute: windowEndMinute,
            rest: rest,
            maxHR: maxHR,
            calendar: calendar,
            now: now,
            historicalMotionPolicy: historicalMotionPolicy,
            resolvedWakeOnset: resolvedWakeOnset,
            shouldComputeWakeOnset: false,
            cooperativeDeadline: cooperativeDeadline
        )
    }

    private nonisolated static func wakeBoundarySleepCandidateCore(
        session: SavedSession,
        windowEndMinute: Int,
        rest: Int,
        maxHR: Int,
        calendar: Calendar,
        now: Date,
        historicalMotionPolicy: HistoricalSleepMotionPolicy,
        resolvedWakeOnset: Date?,
        shouldComputeWakeOnset: Bool,
        cooperativeDeadline: AtriaSleepSettlementDeadline?
    ) throws -> AggregateSleepCandidate? {
        try cooperativeDeadline?.checkpoint()
        let detectedWakeOnset = shouldComputeWakeOnset
            ? try sustainedWakeOnsetCore(
                in: session,
                restingHR: rest,
                delta: WakeBoundaryDefaults.sustainedWakeHRDelta,
                lookback: WakeBoundaryDefaults.sustainedWakeLookback,
                cooperativeDeadline: cooperativeDeadline
            ) : resolvedWakeOnset
        let wakePoint = detectedWakeOnset
            ?? nearestMinuteOfDayInstant(after: session.start,
                                         minuteOfDay: windowEndMinute,
                                         calendar: calendar,
                                         upperBound: now)
        guard let wakePoint,
              let trimmed = try sessionTrimmedAtWakePointCore(
                session,
                wakePoint: wakePoint,
                cooperativeDeadline: cooperativeDeadline
              ) else { return nil }
        let candidates = try aggregateSleepCandidatesCore(
            in: [trimmed],
            rest: rest,
            maxHR: maxHR,
            calendar: calendar,
            historicalMotionPolicy: historicalMotionPolicy,
            cooperativeDeadline: cooperativeDeadline,
            includeResumedReviewCandidates: false
        )
        // Never enter the nap_candidate branch here: the night anchor is only
        // ever a session whose start fell inside the sleep window, so the
        // trimmed candidate stays "overnight_sleep"; a nap-shaped result would
        // mean the trim collapsed the window below the overnight thresholds,
        // which should not auto-confirm through this path.
        return candidates.first { $0.kind == "overnight_sleep" }
    }

    /// Builds the WHOOP-parity wake-boundary candidate without touching actor
    /// state. This contains every O(n) session scan, rolling-median calculation
    /// and candidate aggregation required by morning settlement.
    private nonisolated static func prepareWakeBoundarySleep(
        sourceSessions: [SavedSession],
        rest: Int,
        maxHR: Int,
        now: Date,
        learnedWindow: (start: Int, end: Int)?,
        baselineRestingIsTrusted: Bool,
        baselineRestingIsNearTrusted: Bool = false,
        historicalMotionPolicy: HistoricalSleepMotionPolicy = .boundedRecent
    ) -> ForegroundSleepSettlementProposal.WakeBoundary {
        let calendar = Calendar.current
        let windowStart = learnedWindow?.start ?? WakeBoundaryDefaults.fallbackWindowStartMin
        let windowEnd = learnedWindow?.end ?? WakeBoundaryDefaults.fallbackWindowEndMin
        let nowMinute = minutesOfDay(now, calendar: calendar)

        // Precondition 1: never evaluate before/during the (learned or
        // fallback) sleep window. The fallback additionally only ever fires in
        // the morning core so an unlearned device can't drift into evaluating
        // at arbitrary hours just because `now >= fallbackWindowEndMin`.
        let pastWindowEnd = nowMinute >= windowEnd
        let fallbackMorningCoreOK = learnedWindow != nil
            || (nowMinute >= WakeBoundaryDefaults.fallbackMorningCoreStartMin
                && nowMinute <= WakeBoundaryDefaults.fallbackMorningCoreEndMin)
        guard pastWindowEnd, fallbackMorningCoreOK else {
            return .init(candidate: nil,
                         blocker: "before_window_end",
                         windowEndMinute: windowEnd,
                         nowMinute: nowMinute,
                         learnedWindow: learnedWindow != nil)
        }

        // Precondition 2: the night-session anchor — latest session (live
        // journal tail included) that started inside the sleep window at
        // least 3h ago. Nap logic is untouched: any session whose start falls
        // outside the sleep window is never eligible here.
        let nightSessions = sourceSessions.filter { session in
            minuteInsideWindow(minutesOfDay(session.start, calendar: calendar), start: windowStart, end: windowEnd)
                && now.timeIntervalSince(session.start) >= WakeBoundaryDefaults.minNightAnchorAge
        }
        guard let nightSession = nightSessions.max(by: { $0.start < $1.start }) else {
            return .init(candidate: nil,
                         blocker: "no_night_anchor",
                         windowEndMinute: windowEnd,
                         nowMinute: nowMinute,
                         learnedWindow: learnedWindow != nil)
        }

        // Precondition 3: some evidence of being awake right now — either a
        // genuinely elevated tail, or simply being past the learned wake
        // boundary already (precondition 1 already guarantees the latter in
        // practice; kept explicit here as the named wake detector per spec).
        let tailAwake = sustainedWakeOnset(in: nightSession, restingHR: rest) != nil || nowMinute > windowEnd
        guard tailAwake else {
            return .init(candidate: nil,
                         blocker: "tail_not_awake",
                         windowEndMinute: windowEnd,
                         nowMinute: nowMinute,
                         learnedWindow: learnedWindow != nil)
        }

        guard let candidate = wakeBoundarySleepCandidate(session: nightSession,
                                                         windowEndMinute: windowEnd,
                                                         rest: rest,
                                                         maxHR: maxHR,
                                                         calendar: calendar,
                                                         now: now,
                                                         historicalMotionPolicy: historicalMotionPolicy),
              isAutoConfirmableMainSleepCandidate(
                candidate,
                baselineRestingIsTrusted: baselineRestingIsTrusted,
                baselineRestingIsNearTrusted: baselineRestingIsNearTrusted
              ) else {
            return .init(candidate: nil,
                         blocker: "candidate_did_not_clear_gates",
                         windowEndMinute: windowEnd,
                         nowMinute: nowMinute,
                         learnedWindow: learnedWindow != nil)
        }
        return .init(candidate: candidate,
                     blocker: "none",
                     windowEndMinute: windowEnd,
                     nowMinute: nowMinute,
                     learnedWindow: learnedWindow != nil)
    }

    private nonisolated static func prepareWakeBoundarySleep(
        sourceSessions: [SavedSession],
        rest: Int,
        maxHR: Int,
        now: Date,
        learnedWindow: (start: Int, end: Int)?,
        baselineRestingIsTrusted: Bool,
        baselineRestingIsNearTrusted: Bool = false,
        historicalMotionPolicy: HistoricalSleepMotionPolicy = .boundedRecent,
        cooperativeDeadline: AtriaSleepSettlementDeadline
    ) throws -> ForegroundSleepSettlementProposal.WakeBoundary {
        try cooperativeDeadline.checkpoint()
        let calendar = Calendar.current
        let windowStart = learnedWindow?.start
            ?? WakeBoundaryDefaults.fallbackWindowStartMin
        let windowEnd = learnedWindow?.end
            ?? WakeBoundaryDefaults.fallbackWindowEndMin
        let nowMinute = minutesOfDay(now, calendar: calendar)
        let pastWindowEnd = nowMinute >= windowEnd
        let fallbackMorningCoreOK = learnedWindow != nil
            || (nowMinute >= WakeBoundaryDefaults.fallbackMorningCoreStartMin
                && nowMinute <= WakeBoundaryDefaults.fallbackMorningCoreEndMin)
        guard pastWindowEnd, fallbackMorningCoreOK else {
            return .init(
                candidate: nil,
                blocker: "before_window_end",
                windowEndMinute: windowEnd,
                nowMinute: nowMinute,
                learnedWindow: learnedWindow != nil
            )
        }

        var nightSession: SavedSession?
        for (index, session) in sourceSessions.enumerated() {
            if index.isMultiple(of: 8) {
                try cooperativeDeadline.checkpoint()
            }
            let inside = minuteInsideWindow(
                minutesOfDay(session.start, calendar: calendar),
                start: windowStart,
                end: windowEnd
            )
            guard inside,
                  now.timeIntervalSince(session.start)
                    >= WakeBoundaryDefaults.minNightAnchorAge else { continue }
            if nightSession == nil || session.start > nightSession!.start {
                nightSession = session
            }
        }
        guard let nightSession else {
            return .init(
                candidate: nil,
                blocker: "no_night_anchor",
                windowEndMinute: windowEnd,
                nowMinute: nowMinute,
                learnedWindow: learnedWindow != nil
            )
        }
        let wakeOnset = try sustainedWakeOnset(
            in: nightSession,
            restingHR: rest,
            cooperativeDeadline: cooperativeDeadline
        )
        guard wakeOnset != nil || nowMinute > windowEnd else {
            return .init(
                candidate: nil,
                blocker: "tail_not_awake",
                windowEndMinute: windowEnd,
                nowMinute: nowMinute,
                learnedWindow: learnedWindow != nil
            )
        }
        guard let candidate = try wakeBoundarySleepCandidate(
            session: nightSession,
            windowEndMinute: windowEnd,
            rest: rest,
            maxHR: maxHR,
            calendar: calendar,
            now: now,
            historicalMotionPolicy: historicalMotionPolicy,
            resolvedWakeOnset: wakeOnset,
            cooperativeDeadline: cooperativeDeadline
        ),
        isAutoConfirmableMainSleepCandidate(
            candidate,
            baselineRestingIsTrusted: baselineRestingIsTrusted,
            baselineRestingIsNearTrusted: baselineRestingIsNearTrusted
        ) else {
            return .init(
                candidate: nil,
                blocker: "candidate_did_not_clear_gates",
                windowEndMinute: windowEnd,
                nowMinute: nowMinute,
                learnedWindow: learnedWindow != nil
            )
        }
        try cooperativeDeadline.checkpoint()
        return .init(
            candidate: candidate,
            blocker: "none",
            windowEndMinute: windowEnd,
            nowMinute: nowMinute,
            learnedWindow: learnedWindow != nil
        )
    }

    /// Applies a precomputed wake-boundary result. Only bounded overlap checks,
    /// persistence and published-state mutations remain on the MainActor.
    @discardableResult
    private func commitPreparedWakeBoundarySleepIfUseful(
        _ preparation: ForegroundSleepSettlementProposal.WakeBoundary,
        reason: String,
        sourceSessions: [SavedSession]? = nil,
        deferDerivedPublication: Bool = false,
        archiveFreeLatestNightSettlement: Bool = false,
        persistenceFailure: (() -> Void)? = nil,
        executionShouldContinue:
            @escaping @Sendable () -> Bool = { true }
    ) async -> Bool {
        guard let candidate = preparation.candidate else {
            if preparation.blocker == "before_window_end" {
                AtriaDebugLog("ATRIADBG sleep_wake_boundary status=before_window_end reason=%@ window_end_min=%d now_min=%d learned=%d",
                              reason,
                              preparation.windowEndMinute,
                              preparation.nowMinute,
                              preparation.learnedWindow ? 1 : 0)
            } else {
                AtriaDebugLog("ATRIADBG sleep_wake_boundary status=no_wake_detected reason=%@ blocker=%@",
                              reason,
                              preparation.blocker)
            }
            let detail: String
            switch preparation.blocker {
            case "before_window_end":
                detail = "Before the learned/fallback wake boundary (source: \(reason))"
            case "no_night_anchor":
                detail = "No overnight-started session found for the wake-boundary check (source: \(reason))"
            case "tail_not_awake":
                detail = "No sustained wake HR detected yet (source: \(reason))"
            case "sleep_fragmented_below_minimum":
                detail = "Sleep too fragmented to clear the minimum (source: \(reason))"
            case "sleep_learning":
                detail = "Sleep model still learning this schedule (source: \(reason))"
            case "no_active_or_saved_tail":
                detail = "No active or saved tail session to check (source: \(reason))"
            case "candidate_did_not_clear_gates":
                detail = "Trimmed wake-boundary candidate did not clear the "
                    + "strong-confirm gates (source: \(reason))"
            default:
                // Name the blocker rather than hiding it. Device pull
                // 2026-08-27 showed six consecutive skips across five hours,
                // every one of them landing in this default with the generic
                // "did not clear the strong-confirm gates" text — which does
                // not say WHICH gate, so neither the owner nor a later reader
                // can tell why a real 5-hour sleep went undetected. Every
                // known blocker is now spelled out above; anything new says so
                // instead of impersonating the gate-failure case.
                detail = "Wake boundary blocked by \(preparation.blocker) "
                    + "(source: \(reason))"
            }
            DetectionEventLog.append(DetectionEvent(kind: "sleepCandidateSkipped",
                                                     reason: "wake_boundary_no_wake_detected",
                                                     detail: detail))
            return false
        }

        let baselineRestingIsTrusted = baseline.restingInt != nil
            && baseline.hasTrustedRestingBaseline(now: Date())
        let baselineRestingIsNearTrusted = baseline.restingInt != nil
            && baseline.hasNearTrustedRestingBaselineForFragmentedSleep(now: Date())
        guard Self.isAutoConfirmableMainSleepCandidate(
            candidate,
            baselineRestingIsTrusted: baselineRestingIsTrusted,
            baselineRestingIsNearTrusted: baselineRestingIsNearTrusted
        ) else {
            DetectionEventLog.append(DetectionEvent(
                kind: "sleepCandidateSkipped",
                reason: "baseline_trust_changed",
                detail: "Prepared sleep candidate no longer clears the current evidence gates (source: \(reason))"
            ))
            return false
        }
        let classification = Self.autoSleepClassification(
            for: candidate,
            baselineRestingIsTrusted: baselineRestingIsTrusted,
            baselineRestingIsNearTrusted: baselineRestingIsNearTrusted
        )
        guard classification.allowsAutomaticPersistence else {
            DetectionEventLog.append(DetectionEvent(
                kind: "sleepCandidateSkipped",
                reason: "wake_boundary_review_only_classification",
                detail: "Wake-boundary evidence remains review-only (source: \(reason))"
            ))
            return false
        }
        let preparedMaterialization = preparation.preparedCandidate
        if archiveFreeLatestNightSettlement {
            guard let preparedMaterialization,
                  preparedMaterialization.key == .init(candidate),
                  preparedMaterialization.classification
                    == classification else {
                DetectionEventLog.append(DetectionEvent(
                    kind: "sleepCandidateSkipped",
                    reason: "compact_wake_materialization_stale_or_missing",
                    detail: "Prepared wake physiology no longer matches the current classification (source: \(reason))"
                ))
                return false
            }
        }

        guard !dismissedSleepCandidates.contains(where: {
            $0.suppresses(start: candidate.start, end: candidate.end)
        }) else {
            DetectionEventLog.append(DetectionEvent(kind: "sleepCandidateSkipped",
                                                     reason: "wake_boundary_dismissed",
                                                     detail: "Wake-boundary candidate matches a durable user dismissal"))
            return false
        }

        // Same saved-window overlap guardrail as the closed-candidate path —
        // checked only against already-persisted records (`cachedConfirmedSleeps`),
        // never the in-flight candidate itself, so this can't self-match.
        var existing = cachedConfirmedSleeps
        // Wake-then-sleep-again on a continuous (all-day-wear) recording: the live
        // night session's wake boundary moved later, so grow the confirmed night in
        // place rather than skip it as an overlap (user 2026-07-08). This is the
        // path the resident-app case actually takes — the closed-candidate path
        // never sees a still-open night.
        if let extended = applySleepExtend(to: &existing,
                                           candidate: candidate,
                                           classification: classification,
                                           reason: "\(reason)_wake_boundary_extend",
                                           sourceSessions: sourceSessions,
                                           precomputedMaterialization:
                                            preparedMaterialization) {
            let dismissalRecheck = AutoConfirmSaveTimeDismissalRecheck(
                recordIDs: [extended.id]
            )
            guard await saveConfirmedSleeps(existing,
                                      deferDerivedPublication: deferDerivedPublication,
                                      archiveFreeLatestNightSettlement:
                                        archiveFreeLatestNightSettlement,
                                      publishStressContext:
                                        Self.sleepStressContextAuthority(extended)
                                            != nil,
                                      autoConfirmDismissalRecheck:
                                        dismissalRecheck,
                                      executionShouldContinue:
                                        executionShouldContinue) else {
                persistenceFailure?()
                return false
            }
            if dismissalRecheck.suppressedIDs.contains(extended.id) {
                // The save-time re-check honored a dismissal that landed while
                // this persist was in flight; the extended night was dropped.
                if autoSleepLoggedBanner?.sleepID == extended.id {
                    autoSleepLoggedBanner = nil
                }
                return true
            }
            AtriaDebugLog("ATRIADBG sleep_wake_boundary status=extended reason=%@ id=%@ end=%@",
                          reason, extended.id, isoString(extended.end))
            DetectionEventLog.append(DetectionEvent(kind: "sleepAutoConfirmed",
                                                     detail: "extended to \(isoString(extended.end)) (wake boundary)"))
            return true
        }
        let confirmed: UserConfirmedSleep
        if let preparedMaterialization {
            confirmed = buildAutoConfirmedSleep(
                from: preparedMaterialization,
                reason: "\(reason)_wake_boundary"
            )
        } else {
            confirmed = buildAutoConfirmedSleep(
                from: candidate,
                classification: classification,
                reason: "\(reason)_wake_boundary",
                sourceSessions: sourceSessions
            )
        }
        guard !existing.contains(where: { $0.id == confirmed.id }),
              let insertionBase = Self.sleepInsertionBase(existing: existing, candidate: candidate) else {
            AtriaDebugLog("ATRIADBG sleep_wake_boundary status=overlaps_saved reason=%@ id=%@", reason, confirmed.id)
            DetectionEventLog.append(DetectionEvent(kind: "sleepCandidateSkipped",
                                                     reason: "wake_boundary_overlaps_saved",
                                                     detail: "Wake-boundary candidate overlaps an already-saved sleep (source: \(reason))"))
            return false
        }

        existing = insertionBase
        existing.append(confirmed)
        let dismissalRecheck = AutoConfirmSaveTimeDismissalRecheck(
            recordIDs: [confirmed.id]
        )
        guard await saveConfirmedSleeps(existing,
                                  deferDerivedPublication: deferDerivedPublication,
                                  archiveFreeLatestNightSettlement:
                                    archiveFreeLatestNightSettlement,
                                  publishStressContext:
                                    Self.sleepStressContextAuthority(confirmed)
                                        != nil,
                                  autoConfirmDismissalRecheck: dismissalRecheck,
                                  executionShouldContinue:
                                    executionShouldContinue) else {
            persistenceFailure?()
            return false
        }
        guard !dismissalRecheck.suppressedIDs.contains(confirmed.id) else {
            // The save-time re-check honored a dismissal that landed while
            // this persist was in flight; nothing was logged for the user.
            return true
        }
        autoSleepLoggedBanner = AutoSleepLoggedBanner(id: confirmed.id,
                                                      start: confirmed.start,
                                                      end: confirmed.end,
                                                      duration: confirmed.duration,
                                                      sleepID: confirmed.id)
        LocalNotificationScheduler.scheduleSleepLogged(confirmed)
        AtriaDebugLog("ATRIADBG sleep_wake_boundary status=saved reason=%@ id=%@ source=%@ wake_point=%@",
                      reason, confirmed.id, confirmed.source, isoString(confirmed.end))
        DetectionEventLog.append(DetectionEvent(kind: "sleepAutoConfirmed",
                                                 detail: "\(isoString(confirmed.start))–\(isoString(confirmed.end)), \(SleepHistorySnapshot.formatDuration(confirmed.duration)) (wake boundary)"))
        return true
    }

    /// Extend an existing confirmed auto night in place when `candidate` grows it
    /// (wake-then-sleep-again). Mutates `existing`, returns the extended record
    /// (nil = no extend). Shared by the closed-candidate and wake-boundary paths.
    /// Keeps the transient auto-logged banner in sync but never re-notifies.
    @discardableResult
    private func applySleepExtend(to existing: inout [UserConfirmedSleep],
                                  candidate: AggregateSleepCandidate,
                                  classification: AutoSleepClassification,
                                  reason: String,
                                  sourceSessions: [SavedSession]? = nil,
                                  precomputedMaterialization: ForegroundSleepSettlementProposal.PreparedAutoSleepMaterialization? = nil) -> UserConfirmedSleep? {
        guard classification.allowsAutomaticPersistence else { return nil }
        guard Self.sleepExtendReplacement(existing: existing, candidate: candidate) else { return nil }
        let eventTimeZoneIdentifier = existing.first {
            Self.isExtendableAutoNight($0) && Self.sleepWindowsOverlap($0, candidate: candidate)
        }?.eventTimeZoneIdentifier
        existing.removeAll { Self.isExtendableAutoNight($0) && Self.sleepWindowsOverlap($0, candidate: candidate) }
        let extended: UserConfirmedSleep
        if let precomputedMaterialization {
            extended = buildAutoConfirmedSleep(
                from: precomputedMaterialization,
                reason: reason,
                existingEventTimeZoneIdentifier:
                    eventTimeZoneIdentifier
            )
        } else {
            extended = buildAutoConfirmedSleep(
                from: candidate,
                classification: classification,
                reason: reason,
                sourceSessions: sourceSessions,
                existingEventTimeZoneIdentifier:
                    eventTimeZoneIdentifier
            )
        }
        existing.append(extended)
        if let banner = autoSleepLoggedBanner, banner.start < candidate.end, banner.end > candidate.start {
            autoSleepLoggedBanner = AutoSleepLoggedBanner(id: extended.id,
                                                          start: extended.start,
                                                          end: extended.end,
                                                          duration: extended.duration,
                                                          sleepID: extended.id)
        }
        return extended
    }

    /// Exposed (not `private`) so unit tests can exercise the auto-confirm gate
    /// directly against constructed `AggregateSleepCandidate` fixtures, matching
    /// the existing `partitionSessionsForPersist` pure-static-testing pattern.
    nonisolated static func isStrongAutoConfirmableSleepCandidate(_ candidate: AggregateSleepCandidate) -> Bool {
        // Daytime low-motion is not specific enough to sleep: desk work,
        // meditation, reading, and TV can all satisfy the current motion gate.
        // Keep naps visible for review, but never auto-confirm them until the
        // strap decoder has a separately validated nap classifier.
        guard candidate.kind != "nap_candidate",
              candidate.kind != "resumed_sleep_candidate",
              candidate.motionEvidenceValidated,
              candidate.confidence != .low,
              candidate.duration >= AggregateSleepCandidate.minimumAutoConfirmMainSleepDuration,
              candidate.hrObservedCoverageFraction >= AggregateSleepCandidate.minimumAutoConfirmHRCoverageFraction,
              // Assessment P1.10: silent confirmation needs the full
              // high-agreement stack — qualified RR must corroborate the HR
              // density and already-qualified stillness; anything less stays
              // a review card.
              candidate.qualifiedRRCoverageFraction
                  >= AggregateSleepCandidate.minimumAutoConfirmQualifiedRRCoverageFraction,
              candidate.maximumHRSampleGap <= 60 * 60,
              mainSleepAutoConfirmWindowReady(candidate, calendar: .current) else {
            return false
        }
        // Validated low motion is necessary but not sufficient: a motionless
        // awake window can still pass it. Use a deliberately wider whole-night
        // HR envelope than the HR-only tier (restless sleep can sit above the
        // long-term baseline), but retain robust distribution and total
        // elevated-duration bounds before advancing the physiological day.
        guard candidate.avgHR <= candidate.baselineRestingHR + 25,
              candidate.hrStandardDeviation <= 15,
              candidate.medianHR <= candidate.baselineRestingHR + 22,
              candidate.hrP90 <= candidate.baselineRestingHR + 40,
              candidate.elevatedSampleFraction < 0.20,
              candidate.elevatedSampleFraction * candidate.duration < 45 * 60 else {
            return false
        }
        return candidate.maxGap <= 2 * 60 * 60
    }

    /// The only two paths allowed to persist sensor-derived main sleep. The
    /// degraded HR-only tier intentionally never reaches this predicate.
    nonisolated static func isAutoConfirmableMainSleepCandidate(_ candidate: AggregateSleepCandidate) -> Bool {
        isAutoConfirmableMainSleepCandidate(candidate, baselineRestingIsTrusted: false)
    }

    nonisolated static func isAutoConfirmableMainSleepCandidate(
        _ candidate: AggregateSleepCandidate,
        baselineRestingIsTrusted: Bool,
        baselineRestingIsNearTrusted: Bool = false
    ) -> Bool {
        isStrongAutoConfirmableSleepCandidate(candidate)
            || (baselineRestingIsTrusted
                && isUnambiguousHROnlyMainSleepCandidate(candidate))
            || ((baselineRestingIsTrusted || baselineRestingIsNearTrusted)
                && isHighSpecificityFragmentedHROnlyMainSleepCandidate(candidate))
    }

    /// A long, densely observed main-sleep window may be split into several
    /// saved journals before recovered R10 stillness is projected back into the
    /// sessions. Do not make the physiological day wait on that asynchronous
    /// projection when the independent HR shape is unusually specific. This is
    /// deliberately narrower than the motion-backed gate: it needs a trusted
    /// personal baseline, at least three fragments, five observed hours, high
    /// temporal coverage, a real low-HR tail near baseline, and bounded robust
    /// whole-night physiology. Short quiet-awake windows and daytime naps cannot
    /// enter this path.
    nonisolated static func isHighSpecificityFragmentedHROnlyMainSleepCandidate(
        _ candidate: AggregateSleepCandidate,
        calendar: Calendar = .current
    ) -> Bool {
        guard candidate.kind != "nap_candidate",
              candidate.kind != "resumed_sleep_candidate",
              candidate.sessions >= 3,
              candidate.duration >= AggregateSleepCandidate.minimumAutoConfirmMainSleepDuration,
              candidate.span <= candidate.duration * 1.35,
              candidate.span <= AggregateSleepCandidate.maximumAutoConfirmMainSleepSpan,
              candidate.maxGap <= 60 * 60,
              candidate.hrObservedCoverageFraction >= AggregateSleepCandidate.minimumAutoConfirmHRCoverageFraction,
              candidate.maximumHRSampleGap <= 60 * 60,
              candidate.restingHR <= candidate.baselineRestingHR + 12,
              candidate.avgHR <= candidate.baselineRestingHR + 25,
              candidate.hrStandardDeviation <= 15,
              candidate.medianHR <= candidate.baselineRestingHR + 22,
              candidate.hrP90 <= candidate.baselineRestingHR + 40,
              candidate.elevatedSampleFraction < 0.20,
              candidate.elevatedSampleFraction * candidate.duration < 45 * 60 else {
            return false
        }
        let eventCalendar = EventCivilTime.eventCalendar(
            timeZoneIdentifier: candidate.eventTimeZoneIdentifier,
            fallback: calendar
        )
        return mainSleepAutoConfirmWindowReady(candidate, calendar: eventCalendar)
    }

    nonisolated static func isUnambiguousHROnlyMainSleepCandidate(_ candidate: AggregateSleepCandidate,
                                                                   calendar: Calendar = .current) -> Bool {
        _ = calendar
        guard candidate.kind != "nap_candidate",
              candidate.kind != "resumed_sleep_candidate",
              candidate.duration >= 5 * 60 * 60,
              candidate.span <= candidate.duration * 1.20,
              candidate.span <= AggregateSleepCandidate.maximumAutoConfirmMainSleepSpan,
              candidate.maxGap <= AggregateSleepCandidate.briefSleepGapCreditMax,
              Double(candidate.samples) >= candidate.duration / 90,
              candidate.hrObservedCoverageFraction >= AggregateSleepCandidate.minimumAutoConfirmHRCoverageFraction,
              candidate.maximumHRSampleGap <= AggregateSleepCandidate.briefSleepGapCreditMax,
              candidate.avgHR <= candidate.baselineRestingHR + 12,
              candidate.hrStandardDeviation <= 9.5,
              candidate.medianHR <= candidate.baselineRestingHR + 8,
              candidate.hrP90 <= candidate.baselineRestingHR + 18,
              candidate.elevatedSampleFraction < 0.05,
              candidate.elevatedSampleFraction * candidate.duration < 10 * 60 else { return false }
        // This tier is deliberately clock-independent. Trusted personal resting
        // physiology plus five hours of dense, stable low-HR wear is the
        // discriminator, so shift-work sleep is treated identically to the same
        // biological signal at night. Ambiguous HR-only candidates still stop at
        // the separate review-only tier below. (2026-07-18 P1 truth fix)
        return true
    }

    /// High-specificity HR-only overnight review tier for a fragmented or
    /// artifact-inflated night that fails the unambiguous single-session gate.
    /// This can surface a review card but is never sufficient for automatic
    /// promotion. Every gate below is required:
    /// duration, learned/fallback sleep-core window overlap, fragmentation bound,
    /// and artifact-robust median/percentile HR (not mean/SD, which a sustained
    /// loose-contact drift can drag past the strict gate).
    nonisolated static func isDegradedHROnlyOvernightSleepCandidate(_ candidate: AggregateSleepCandidate,
                                                                     calendar: Calendar = .current) -> Bool {
        guard candidate.kind != "nap_candidate" else { return false }
        guard candidate.duration >= AggregateSleepCandidate.strictMinimumDuration else { return false }
        let eventCalendar = EventCivilTime.eventCalendar(timeZoneIdentifier: candidate.eventTimeZoneIdentifier,
                                                         fallback: calendar)
        guard mainSleepAutoConfirmWindowReady(candidate, calendar: eventCalendar),
              sleepCoreOverlapFraction(start: candidate.start, end: candidate.end, calendar: eventCalendar) >= 0.60
        else { return false }
        guard candidate.sessions >= 1,
              candidate.maxGap <= 90 * 60,
              candidate.span <= candidate.duration * 1.8 else { return false }
        // With no validated stillness, a short overnight window needs a
        // materially tighter HR shape than the motion-backed review tier.
        // The 2026-07-23 physical false positive (02:11–05:19) had a
        // baseline of 71, median 78 and P90 92: low enough for the previous
        // broad review gate, but not a credible sleep signature while awake.
        // Keep the looser path available when strap stillness is actually
        // validated; this HR-only exception must fail closed instead.
        // The candidate builder already bounds degraded review physiology at
        // resting+10 median. Keep that same robust median allowance here while
        // retaining the tighter P90 guard: the July 28 physical sleep was
        // median +10 / P90 +17, whereas the disproven July 23 quiet-awake
        // window still fails decisively at P90 +21.
        // Base envelope: a tight P90 (<=base+18) surfaces for review with no
        // further corroboration, exactly as before. Corroborated exception
        // (2026-08-22): a motion-starved shifted sleeper's real overnight low-HR
        // window can sit at P90 up to +22 — the device night was base56/med66/
        // P90 78(=+22)/rest58/SD8.5/cov1.0/qRR0.93, a genuine 3h sleep that on
        // confirm yields hrv 52ms over 10 qualified RMSSD windows. Admit +22 ONLY
        // with a real parasympathetic TROUGH (5th-pct resting near baseline AND a
        // descent well below the night's own median), a smooth envelope, trustworthy
        // sample density, and dense provenance-qualified RR (a data-quality
        // precondition, NOT the sleep discriminator). This tier is REVIEW-ONLY —
        // it never reaches isAutoConfirmableMainSleepCandidate — so a mis-admission
        // costs exactly one dismissible "Possible sleep · HR/RR estimate" card the
        // user decides on, never a silent record/HRV/strain write. The 2026-07-23
        // quiet-awake FP (base71/med78=+7/P90 92=+21, flat floor resting==median)
        // fails the trough on two axes and stays hidden.
        let p90WithinBaseEnvelope =
            candidate.hrP90 <= candidate.baselineRestingHR + 18
        let p90WithinTroughCorroboratedEnvelope =
            candidate.hrP90 <= candidate.baselineRestingHR + 22
            && candidate.restingHR <= candidate.baselineRestingHR + 4
            && (candidate.medianHR - candidate.restingHR) >= 6
            && candidate.hrStandardDeviation <= 9.5
            && candidate.hrObservedCoverageFraction >= AggregateSleepCandidate.minimumAutoConfirmHRCoverageFraction
            && candidate.qualifiedRRCoverageFraction >= 0.80
        guard candidate.medianHR <= candidate.baselineRestingHR + 10,
              p90WithinBaseEnvelope || p90WithinTroughCorroboratedEnvelope,
              candidate.elevatedSampleFraction < 0.10 else { return false }
        // Wake/false-night guard: an active evening cannot masquerade as sleep just
        // because a bounded fraction of samples were elevated — bound the total
        // elevated time too (approximated from the elevated fraction over the
        // candidate's total duration, since raw per-sample timestamps aren't kept
        // on the aggregate).
        let approxElevatedSeconds = candidate.elevatedSampleFraction * candidate.duration
        guard approxElevatedSeconds < 20 * 60 else { return false }
        return true
    }

    private nonisolated static func mainSleepAutoConfirmWindowReady(_ candidate: AggregateSleepCandidate,
                                                                    calendar: Calendar) -> Bool {
        guard candidate.span > 0,
              candidate.span <= AggregateSleepCandidate.maximumAutoConfirmMainSleepSpan else { return false }
        let eventCalendar = EventCivilTime.eventCalendar(timeZoneIdentifier: candidate.eventTimeZoneIdentifier,
                                                         fallback: calendar)
        return sleepCoreOverlapDuration(start: candidate.start,
                                        end: candidate.end,
                                        calendar: eventCalendar)
            >= AggregateSleepCandidate.minimumAutoConfirmSleepCoreOverlap
    }

    /// Fraction of `[start, end)` that overlaps the sleep-core window (00:00-06:00,
    /// checked against the day before/of/after `start` the same way
    /// `windowOverlapsSleepCore` does). A same-day core-overlap fraction is used
    /// rather than a fixed learned-window lookup so this stays a pure, deterministic
    /// function of the candidate's own start/end for unit testing; the 0-6am core
    /// is the same fallback window `windowOverlapsSleepCore` already uses.
    private nonisolated static func sleepCoreOverlapFraction(start: Date, end: Date, calendar: Calendar) -> Double {
        let span = end.timeIntervalSince(start)
        guard span > 0 else { return 0 }
        return sleepCoreOverlapDuration(start: start, end: end, calendar: calendar) / span
    }

    private nonisolated static func sleepCoreOverlapDuration(start: Date,
                                                             end: Date,
                                                             calendar: Calendar) -> TimeInterval {
        guard end > start else { return 0 }
        let startDay = calendar.startOfDay(for: start)
        var overlap: TimeInterval = 0
        for offset in -1...1 {
            guard let day = calendar.date(byAdding: .day, value: offset, to: startDay),
                  let coreStart = calendar.date(bySettingHour: 0, minute: 0, second: 0, of: day),
                  let coreEnd = calendar.date(bySettingHour: 6, minute: 0, second: 0, of: day) else { continue }
            let overlapStart = max(start, coreStart)
            let overlapEnd = min(end, coreEnd)
            if overlapEnd > overlapStart {
                overlap += overlapEnd.timeIntervalSince(overlapStart)
            }
        }
        return overlap
    }

    /// Single source of truth for persisted automatic sleep classification. It
    /// also labels rejected fixtures explicitly as review-only so HR-only evidence
    /// can never acquire an auto-confirmed source through a secondary call site.
    struct AutoSleepClassification: Equatable {
        let source: String
        let confidence: String
        let motionValidated: Bool
        let motionSource: String
        let isHROnly: Bool

        /// A review label is never a persistence authorization. Keep this
        /// explicit so every automatic-save caller can fail closed even if a
        /// future candidate gate and its source classification drift apart.
        var allowsAutomaticPersistence: Bool {
            source.hasPrefix("auto_confirmed_sleep")
                && confidence.caseInsensitiveCompare("low") != .orderedSame
        }
    }

    nonisolated static func autoSleepEventTimeZoneIdentifier(
        for candidate: AggregateSleepCandidate,
        existingEventTimeZoneIdentifier: String? = nil,
        fallbackIdentifier: String? = TimeZone.current.identifier
    ) -> String? {
        candidate.eventTimeZoneIdentifier ?? existingEventTimeZoneIdentifier ?? fallbackIdentifier
    }

    /// Context-free classification retained for diagnostic/replay callers.
    /// It recognizes the independently specific single-session HR-only tier,
    /// but deliberately does not infer the baseline maturity required by the
    /// fragmented tier.
    nonisolated static func autoSleepClassification(for candidate: AggregateSleepCandidate) -> AutoSleepClassification {
        autoSleepClassification(
            for: candidate,
            baselineRestingIsTrusted: true,
            baselineRestingIsNearTrusted: false,
            admitsBaselineQualifiedFragmentedTier: false
        )
    }

    /// Persistence classification paired with the exact baseline inputs used
    /// by `isAutoConfirmableMainSleepCandidate`. Automatic save callers must
    /// use this overload and then check `allowsAutomaticPersistence`.
    nonisolated static func autoSleepClassification(
        for candidate: AggregateSleepCandidate,
        baselineRestingIsTrusted: Bool,
        baselineRestingIsNearTrusted: Bool = false
    ) -> AutoSleepClassification {
        autoSleepClassification(
            for: candidate,
            baselineRestingIsTrusted: baselineRestingIsTrusted,
            baselineRestingIsNearTrusted: baselineRestingIsNearTrusted,
            admitsBaselineQualifiedFragmentedTier: true
        )
    }

    private nonisolated static func autoSleepClassification(
        for candidate: AggregateSleepCandidate,
        baselineRestingIsTrusted: Bool,
        baselineRestingIsNearTrusted: Bool,
        admitsBaselineQualifiedFragmentedTier: Bool
    ) -> AutoSleepClassification {
        let motionReady = candidate.motionEvidenceValidated && candidate.confidence != .low
        let strongMotionAutoConfirmable = motionReady && isStrongAutoConfirmableSleepCandidate(candidate)
        let unambiguousHROnlyAutoConfirmable = !candidate.motionEvidenceValidated
            && baselineRestingIsTrusted
            && isUnambiguousHROnlyMainSleepCandidate(candidate)
        let fragmentedHROnlyAutoConfirmable = !candidate.motionEvidenceValidated
            && admitsBaselineQualifiedFragmentedTier
            && (baselineRestingIsTrusted || baselineRestingIsNearTrusted)
            && isHighSpecificityFragmentedHROnlyMainSleepCandidate(candidate)
        let autoConfirmable = strongMotionAutoConfirmable
            || unambiguousHROnlyAutoConfirmable
            || fragmentedHROnlyAutoConfirmable
        guard autoConfirmable else {
            let source: String
            if candidate.kind == "nap_candidate" {
                source = "sleep_review_nap"
            } else if motionReady {
                source = "sleep_review_motion_validated"
            } else if candidate.motionEvidenceValidated {
                source = "sleep_review_motion_low_confidence"
            } else {
                source = "sleep_review_hr_only"
            }
            return AutoSleepClassification(source: source,
                                           confidence: "low",
                                           motionValidated: false,
                                           motionSource: candidate.motionEvidenceValidated
                                            ? candidate.motionEvidenceSource
                                            : "strap_hr_only",
                                           isHROnly: !candidate.motionEvidenceValidated)
        }
        if unambiguousHROnlyAutoConfirmable || fragmentedHROnlyAutoConfirmable {
            return AutoSleepClassification(source: "auto_confirmed_sleep_hr_only",
                                           confidence: "provisional",
                                           motionValidated: false,
                                           motionSource: "strap_hr_only",
                                           isHROnly: true)
        }
        return AutoSleepClassification(source: "auto_confirmed_sleep",
                                       confidence: candidate.confidence.rawValue,
                                       motionValidated: true,
                                       motionSource: candidate.motionEvidenceSource,
                                       isHROnly: false)
    }

    private nonisolated static func windowOverlapsSleepCore(start: Date,
                                                            end: Date,
                                                            calendar: Calendar) -> Bool {
        let startDay = calendar.startOfDay(for: start)
        for offset in -1...1 {
            guard let day = calendar.date(byAdding: .day, value: offset, to: startDay),
                  let coreStart = calendar.date(bySettingHour: 0, minute: 0, second: 0, of: day),
                  let coreEnd = calendar.date(bySettingHour: 6, minute: 0, second: 0, of: day) else { continue }
            if start < coreEnd && end > coreStart {
                return true
            }
        }
        return false
    }

    private nonisolated static func sleepWindowsOverlap(_ sleep: UserConfirmedSleep, candidate: AggregateSleepCandidate) -> Bool {
        sleep.start < candidate.end && sleep.end > candidate.start
    }

    /// A low-HR review episode may legitimately grow the automatic main sleep
    /// that was saved at the first wake. Without this exception, the generic
    /// overlap suppression hides the resumed portion forever whenever low
    /// battery or a transport gap leaves motion evidence unavailable.
    ///
    /// This is deliberately review-only and extend-only: it never touches a
    /// manual/adjusted record, never absorbs a nap or separate later episode,
    /// never trims the saved head, and requires meaningful new sensor-credited
    /// sleep as well as a later wake. Automatic settlement keeps its stricter
    /// motion gate; this helper only decides whether the user may review/save a
    /// conservative continuation.
    nonisolated static func sleepReviewExtensionTarget(
        existing: [UserConfirmedSleep],
        candidateStart: Date,
        candidateEnd: Date,
        candidateDuration: TimeInterval,
        isNap: Bool,
        maximumStartLead: TimeInterval = 30 * 60,
        startTolerance: TimeInterval = 5 * 60,
        minimumEndGain: TimeInterval = 30 * 60,
        minimumDurationGain: TimeInterval = 20 * 60
    ) -> UserConfirmedSleep? {
        guard !isNap,
              candidateEnd > candidateStart,
              candidateDuration > 0 else { return nil }
        let overlapping = existing.filter {
            $0.start < candidateEnd && $0.end > candidateStart
        }
        guard !overlapping.isEmpty,
              !overlapping.contains(where: { sleepRecordIsUserAuthored($0) }),
              overlapping.allSatisfy({ isExtendableAutoNight($0) }),
              let target = overlapping.max(by: { $0.duration < $1.duration }) else {
            return nil
        }
        // Five-minute physiology bins can begin at the next bucket after the
        // persisted boundary. Permit only that rounding error; anything later
        // is a separate episode and must not replace the original night.
        guard candidateStart >= target.start.addingTimeInterval(-maximumStartLead),
              candidateStart <= target.start.addingTimeInterval(startTolerance),
              candidateEnd >= target.end.addingTimeInterval(minimumEndGain),
              candidateDuration >= target.duration + minimumDurationGain else {
            return nil
        }
        return target
    }

    /// Produces the persistence base for an explicitly reviewed continuation.
    /// Factored as a pure function so the transaction's duplicate-removal rule
    /// is testable independently of UserDefaults.
    nonisolated static func sleepReviewInsertionBase(
        existing: [UserConfirmedSleep],
        extensionTarget: UserConfirmedSleep?,
        candidateStart: Date,
        candidateEnd: Date
    ) -> [UserConfirmedSleep] {
        guard extensionTarget != nil else { return existing }
        return existing.filter {
            !isExtendableAutoNight($0)
                || $0.start >= candidateEnd
                || $0.end <= candidateStart
        }
    }

    /// Returns the records an auto-confirmed candidate may be inserted beside.
    /// A strong overnight can replace overlapping `auto_nap` records, but every
    /// other overlap remains authoritative, including manual and adjusted sleep.
    nonisolated static func sleepInsertionBase(existing: [UserConfirmedSleep],
                                                candidate: AggregateSleepCandidate) -> [UserConfirmedSleep]? {
        let overlapping = existing.filter { sleepWindowsOverlap($0, candidate: candidate) }
        if candidate.kind == "nap_candidate" {
            return overlapping.isEmpty ? existing : nil
        }
        guard overlapping.allSatisfy({ $0.source == "auto_nap" }) else { return nil }
        return existing.filter { sleep in
            sleep.source != "auto_nap" || !sleepWindowsOverlap(sleep, candidate: candidate)
        }
    }

    /// A source the user authored or hand-edited — never touched by the auto
    /// extend path (2026-07-08). Covers manual_sleep/manual_nap and the
    /// user_adjusted_* sources produced by the Adjust sheet.
    nonisolated static func isUserAuthoredSleepSource(_ source: String) -> Bool {
        source.hasPrefix("manual_") || source.hasPrefix("user_adjusted_")
    }

    /// The full authorship test: SOURCE alone is not sufficient evidence that
    /// the user left a night alone.
    ///
    /// The plain Confirm button does not rewrite the source. `reviewedSleepSource`
    /// returns the detector's own string verbatim whenever it is in
    /// `explicitSleepSources` — `overnight_sleep`, `aggregate_sleep`,
    /// `resumed_sleep`, `nap_candidate`, … — none of which carry a `manual_` or
    /// `user_adjusted_` prefix. Only the Adjust -> Save path mints those. So a
    /// night the user explicitly confirmed still looked like an untouched auto
    /// night to `isExtendableAutoNight`, and the auto-extend path kept growing
    /// it and re-offering it for review. That is field report 2026-08-19 item 5:
    /// "even if you save it, there's another sleep recommendation that keeps on
    /// going after it has been stopped."
    ///
    /// The 2026-08-19 device ledger measures it: of 38 confirmed sleeps, 21 had
    /// a non-authored SOURCE, but 19 of those 21 carried
    /// `confidence == user_confirmed_hr_only`. Only two were genuinely automatic
    /// (`sleep_review_hr_only`/`low` and `auto_confirmed_sleep`/`medium`), and
    /// those two must stay extendable.
    ///
    /// `confidence` already carries the missing signal, and the codebase already
    /// reads it this way in `explicitUserSleepCorrection` and the sleep-stress
    /// context authority. Reuse that idiom rather than rewriting the persisted
    /// source string, which other code parses for nap/display classification.
    nonisolated static func sleepRecordIsUserAuthored(_ sleep: UserConfirmedSleep) -> Bool {
        isUserAuthoredSleepSource(sleep.source)
            || sleep.confidence.hasPrefix("user_confirmed_")
            || sleep.confidence.hasPrefix("manual_")
    }

    /// Whether a "not sleep" dismissal for this window is entitled to retract
    /// an already-persisted confirmed record. Automatic settlement and the
    /// dismissal tap can race in either order; once the tombstone exists, a
    /// machine-authored record for the same window must not survive on timing
    /// alone (device 2026-08-20: the dismissed 13:15-16:15 afternoon window
    /// kept its `aggregate_sleep` auto-confirmation). Reuses the candidate
    /// ≥0.70-overlap suppression rule so retraction and suppression agree on
    /// "the same window", and never claims user work: authored records (per
    /// `sleepRecordIsUserAuthored`) and any record carrying the day-primary
    /// answer stay authoritative — dismissal is not deletion for those.
    nonisolated static func dismissalRetractsConfirmedSleep(
        _ sleep: UserConfirmedSleep,
        dismissalStart: Date,
        dismissalEnd: Date
    ) -> Bool {
        AtriaDismissedSleepCandidate(start: dismissalStart, end: dismissalEnd)
            .suppresses(start: sleep.start, end: sleep.end)
            && !sleepRecordIsUserAuthored(sleep)
            && sleep.dayPrimaryChoice == nil
    }

    /// Save-time selection for the auto-confirm dismissal re-check: of the
    /// records an in-flight auto-confirm pass minted or extended
    /// (`recheckIDs`), those a tombstone retracts under the canonical
    /// `dismissalRetractsConfirmedSleep` rule. Scoped to `recheckIDs` so a
    /// pre-existing record awaiting its own retraction sweep is never
    /// silently filtered out of an unrelated save. Exposed (not `private`)
    /// so unit tests can exercise the selection matrix directly.
    nonisolated static func saveTimeDismissalSuppressedSleepIDs(
        in settled: [UserConfirmedSleep],
        recheckIDs: Set<String>,
        tombstones: [AtriaDismissedSleepCandidate]
    ) -> Set<String> {
        guard !recheckIDs.isEmpty, !tombstones.isEmpty else { return [] }
        return Set(settled.filter { record in
            recheckIDs.contains(record.id)
                && tombstones.contains {
                    dismissalRetractsConfirmedSleep(record,
                                                    dismissalStart: $0.start,
                                                    dismissalEnd: $0.end)
                }
        }.map(\.id))
    }

    /// Strict record atomicity (2026-08-12 user decision): two saved sleep
    /// activities can never overlap. A user save whose window intersects an
    /// existing confirmed record — other than the one it explicitly replaces —
    /// is rejected so overlapping duplicates (a nap saved inside a sleep, two
    /// sleeps stacked by repeated edits) can no longer be created. Returns the
    /// first conflicting record so callers can name it.
    nonisolated static func firstOverlappingConfirmedSleep(
        in existing: [UserConfirmedSleep],
        start: Date,
        end: Date,
        excludingIDs: Set<String> = []
    ) -> UserConfirmedSleep? {
        guard end > start else { return nil }
        return existing.first {
            !excludingIDs.contains($0.id)
                && $0.start < end
                && $0.end > start
        }
    }

    /// A confirmed night the auto extend may grow in place: a real overnight sleep
    /// (not a nap) that the user did not author/edit.
    nonisolated static func isExtendableAutoNight(_ sleep: UserConfirmedSleep) -> Bool {
        !confirmedSleepSourceIsNap(source: sleep.source, duration: sleep.duration)
            && !sleepRecordIsUserAuthored(sleep)
    }

    /// Whether `candidate` should EXTEND the confirmed overnight night(s) it
    /// overlaps rather than be skipped as a duplicate — "wake, then sleep again"
    /// (user 2026-07-08). Extend-ONLY and safe:
    ///  - never for a nap candidate;
    ///  - never when it overlaps a USER-authored/edited night (left strictly alone);
    ///  - only as a TAIL-superset of the auto night(s) it overlaps: it starts no
    ///    later than their earliest start (so it can't trim the head, and a
    ///    later-starting cluster split off by a >2h strap-dead gap is refused
    ///    rather than fabricating sleep across the gap) AND ends meaningfully
    ///    later than their latest end.
    /// So it can only GROW an auto night — never shrink, split, or clobber a manual one.
    nonisolated static func sleepExtendReplacement(existing: [UserConfirmedSleep],
                                                   candidate: AggregateSleepCandidate,
                                                   minGain: TimeInterval = 5 * 60) -> Bool {
        guard candidate.kind != "nap_candidate" else { return false }
        if existing.contains(where: { sleepRecordIsUserAuthored($0) && sleepWindowsOverlap($0, candidate: candidate) }) {
            return false
        }
        let overlappingNights = existing.filter { isExtendableAutoNight($0) && sleepWindowsOverlap($0, candidate: candidate) }
        guard let latestEnd = overlappingNights.map(\.end).max(),
              let earliestStart = overlappingNights.map(\.start).min(),
              let creditedDuration = overlappingNights.map(\.duration).max(),
              candidate.duration >= creditedDuration else { return false }
        return candidate.start <= earliestStart
            && candidate.end > latestEnd.addingTimeInterval(minGain)
    }

    func addManualSleep(start: Date,
                        end: Date,
                        isNap: Bool,
                        rest: Int,
                        source: String = "manual_ui") async -> UserConfirmedSleep? {
        guard end > start else { return nil }
        let sleepSource = isNap ? "manual_nap" : "manual_sleep"
        let id = confirmedSleepID(start: start, end: end, source: sleepSource)
        let previouslySaved = cachedConfirmedSleeps.first { $0.id == id }
        var existing = cachedConfirmedSleeps.filter { $0.id != id }
        // Strict record atomicity: two saved activities can never overlap.
        if let conflict = Self.firstOverlappingConfirmedSleep(
            in: existing, start: start, end: end
        ) {
            AtriaDebugLog("ATRIADBG sleep_manual status=rejected reason=overlaps_existing conflict=%@",
                          conflict.id)
            return nil
        }
        let duration = end.timeIntervalSince(start)
        let metrics = confirmedSleepWindowMetrics(start: start, end: end, rest: rest)
        let confirmed = UserConfirmedSleep(id: id,
                                           createdAt: Date(),
                                           start: start,
                                           end: end,
                                           source: sleepSource,
                                           confidence: "manual_user_entered",
                                           sessions: metrics.sessions,
                                           samples: metrics.samples,
                                           avgHR: metrics.avgHR,
                                           peakHR: metrics.peakHR,
                                           restingHR: metrics.restingHR,
                                           hrv: metrics.hrv,
                                           hrvWindowCount: metrics.hrvWindowCount,
                                           respiratoryRate: confirmedSleepRespiratoryRate(start: start,
                                                                                           end: end),
                                           duration: duration,
                                           span: duration,
                                           reason: source,
                                           motionSource: "manual",
                                           motionValidated: false,
                                           stageSegments: nil,
                                           eventTimeZoneIdentifier: TimeZone.current.identifier)
        existing.append(confirmed)
        // A user may legitimately re-add a window they previously dismissed
        // or deleted. Their explicit save supersedes that detector tombstone.
        guard await saveConfirmedSleeps(
            existing,
            publishStressContext:
                Self.sleepStressContextAuthority(previouslySaved)
                    != Self.sleepStressContextAuthority(confirmed)
        ) else { return nil }
        clearDismissedSleepCandidates(overlappingStart: start, end: end)
        refreshSleepSnapshotAfterCandidateSettlement()
        AtriaDebugLog("ATRIADBG sleep_manual status=saved id=%@ source=%@ start=%@ end=%@ duration_s=%.0f kind=%@ stages=%d",
                      confirmed.id,
                      source,
                      isoString(confirmed.start),
                      isoString(confirmed.end),
                      confirmed.duration,
                      confirmed.source,
                      confirmed.stageSegments?.count ?? 0)
        return confirmed
    }

    /// Confirm (or re-confirm) a sleep over an explicit user-chosen window with
    /// sensor-derived stages and honest metrics. This is the shared core of the
    /// "adjust" flows and the honest alternative to `addManualSleep`: instead of
    /// downgrading the night to a manual entry (dropping the sensor stage
    /// timeline and collapsing `span` to `duration` so efficiency reads a fake
    /// 100%), it re-derives the stage timeline and HR/HRV metrics over the NEW
    /// `[start,end]` from the stored sensor sessions — the "adjust the
    /// boundaries, keep the science" edit users expect from WHOOP.
    ///
    /// Honesty: stages come only from real samples inside the window, and
    /// `duration` counts only sensor-covered time (never the whole in-bed span),
    /// so efficiency (`duration / span`) stays truthful even if the user drags
    /// the window over a stretch the strap did not record. Pass `replacing` to
    /// remove a prior record for the same night (an edit rather than an add).
    @discardableResult
    func confirmSleepWindow(start: Date,
                            end: Date,
                            isNap: Bool,
                            rest: Int,
                            replacing existingID: String? = nil,
                            motionValidated: Bool = false,
                            motionSource: String = "user_adjusted",
                            fromSource: String = "user",
                            settlingCandidateWindow: (start: Date, end: Date)? = nil) async -> UserConfirmedSleep? {
        guard end > start else { return nil }
        let adjustedSource = isNap ? "user_adjusted_nap" : "user_adjusted_sleep"
        let id = confirmedSleepID(start: start, end: end, source: adjustedSource)
        // Include the fresh active journal when a user adjusts immediately after
        // waking; the final tail may not have reached persisted sessions yet.
        let sourceSessions = canonicalSessions(includeActiveJournal: true)
        let metrics = Self.confirmedSleepWindowMetrics(from: sourceSessions,
                                                       start: start,
                                                       end: end,
                                                       rest: rest)
        let stageSegments = Self.sleepStageResearchSegments(from: sourceSessions,
                                                            start: start,
                                                            end: end,
                                                            restingHR: metrics.restingHR,
                                                            isNap: isNap,
                                                            motionValidated: motionValidated,
                                                            // User-initiated save: the deliberate
                                                            // lane that may pay for HR-only
                                                            // ESTIMATE staging (2026-08-12).
                                                            allowHROnlyEstimate: true)
        let span = end.timeIntervalSince(start)
        // Sensor-covered time inside the window (sum of overlapping session spans
        // clipped to [start,end]); mirrors how an AggregateSleepCandidate's
        // `duration` excludes gaps the strap did not record.
        let sensorCovered = Self.confirmedSleepSensorCoverage(from: sourceSessions,
                                                              start: start,
                                                              end: end)
        let duration = Swift.min(span, sensorCovered)
        // Fail closed instead of silently saving a zero-length sleep: a
        // user-adjusted window with less than the nap-minimum of sensor
        // coverage used to persist duration=0 with no error (2026-07-07).
        guard duration >= AggregateSleepCandidate.napMinimumDuration else {
            AtriaDebugLog("ATRIADBG sleep_adjust status=rejected reason=insufficient_sensor_coverage covered_s=%.0f span_s=%.0f",
                          sensorCovered,
                          span)
            return nil
        }
        // Keep the re-derived sensor stages: a non-manual source plus an
        // hr_only / motion-validated confidence marks the timeline as
        // sensor-research rather than a manual estimate (see
        // `shouldPreserveConfirmedSleepStageSegments`).
        let confidence = motionValidated ? "user_adjusted_motion_validated" : "user_adjusted_hr_only"
        let previouslySaved = existingID
            .flatMap { existingID in
                cachedConfirmedSleeps.first { $0.id == existingID }
            }
            ?? cachedConfirmedSleeps.first { $0.id == id }
        var remaining = cachedConfirmedSleeps.filter { $0.id != id && (existingID == nil || $0.id != existingID) }
        // Strict record atomicity: two saved activities can never overlap. The
        // record being replaced is already out of `remaining`, so an edit that
        // keeps its own window always passes; only a window intruding on a
        // DIFFERENT saved record is rejected.
        if let conflict = Self.firstOverlappingConfirmedSleep(
            in: remaining, start: start, end: end
        ) {
            AtriaDebugLog("ATRIADBG sleep_adjust status=rejected reason=overlaps_existing conflict=%@ from_source=%@",
                          conflict.id,
                          fromSource)
            return nil
        }
        let eventTimeZoneIdentifier = previouslySaved?.eventTimeZoneIdentifier
            ?? TimeZone.current.identifier
        // A bound edit mints a new record id, so the id-keyed carry in
        // saveConfirmedSleeps can never see the original frozen Sleep Need.
        // Editing a window must preserve the already-frozen receipt — only a
        // genuinely new main sleep may mint one at settlement. Converting a
        // sleep to a nap drops the night receipt on purpose: a nap does not
        // own a nightly need.
        let carriedNeedSeconds: TimeInterval?
        let carriedFrozenNeed: AtriaSleepBudget.FrozenNeed?
        if !isNap,
           let previouslySaved,
           Self.confirmedSleepIsPhysiologicalMainSleep(previouslySaved) {
            carriedNeedSeconds = previouslySaved.sleepNeedSeconds
            carriedFrozenNeed = previouslySaved.frozenSleepNeed
        } else {
            carriedNeedSeconds = nil
            carriedFrozenNeed = nil
        }
        let staged = UserConfirmedSleep(id: id,
                                        createdAt: Date(),
                                        start: start,
                                        end: end,
                                        source: adjustedSource,
                                        confidence: confidence,
                                        sessions: metrics.sessions,
                                        samples: metrics.samples,
                                        avgHR: metrics.avgHR,
                                        peakHR: metrics.peakHR,
                                        restingHR: metrics.restingHR,
                                        hrv: metrics.hrv,
                                        hrvWindowCount: metrics.hrvWindowCount,
                                        respiratoryRate: Self.confirmedSleepRespiratoryRate(
                                            from: sourceSessions,
                                            start: start,
                                            end: end
                                        ),
                                        duration: duration,
                                        span: span,
                                        reason: "user_adjusted_window from \(fromSource)",
                                        motionSource: motionSource,
                                        motionValidated: motionValidated,
                                        stageSegments: stageSegments.isEmpty ? nil : stageSegments,
                                        eventTimeZoneIdentifier: eventTimeZoneIdentifier,
                                        sleepNeedSeconds: carriedNeedSeconds,
                                        frozenSleepNeed: carriedFrozenNeed,
                                        // An edit re-mints the ID, so the answered "which is your
                                        // main sleep?" choice must ride along or the day silently
                                        // re-prompts. A nap can never be a day primary; the save
                                        // path's per-day normalization clears survivors when the
                                        // collision itself dissolves.
                                        dayPrimaryChoice: isNap ? nil : previouslySaved?.dayPrimaryChoice)
        let confirmed: UserConfirmedSleep
        if !stageSegments.isEmpty, !AtriaSleepStageIntegrity.validates(stageSegments, for: staged) {
            AtriaDebugLog("ATRIADBG sleep_stage_integrity status=suppressed source=%@ sleep_s=%.0f span_s=%.0f segments=%d",
                          adjustedSource,
                          duration,
                          span,
                          stageSegments.count)
            confirmed = Self.copyConfirmedSleep(staged, stageSegments: nil)
        } else {
            confirmed = staged
        }
        remaining.append(confirmed)
        // Saving a review is the terminal state for the detector suggestion
        // that opened the editor. The user may legitimately move the saved
        // sleep/nap far enough that it no longer overlaps the original sensor
        // window; without this tombstone that original window reappears as a
        // candidate immediately after a successful Save. Keep the original
        // suggestion settled while the newly confirmed record remains the
        // authoritative, editable Activity item.
        guard await saveConfirmedSleeps(
            remaining,
            publishStressContext:
                Self.sleepStressContextAuthority(previouslySaved)
                    != Self.sleepStressContextAuthority(confirmed)
        ) else { return nil }
        clearDismissedSleepCandidates(overlappingStart: start, end: end)
        if let settlingCandidateWindow,
           settlingCandidateWindow.end > settlingCandidateWindow.start {
            addDismissedSleepCandidate(start: settlingCandidateWindow.start,
                                       end: settlingCandidateWindow.end)
        }
        refreshSleepSnapshotAfterCandidateSettlement()
        AtriaDebugLog("ATRIADBG sleep_adjust status=saved id=%@ from_source=%@ start=%@ end=%@ duration_s=%.0f span_s=%.0f stages=%d",
                      confirmed.id,
                      fromSource,
                      isoString(confirmed.start),
                      isoString(confirmed.end),
                      confirmed.duration,
                      confirmed.span,
                      confirmed.stageSegments?.count ?? 0)
        return confirmed
    }

    /// Non-destructive edit of an already-confirmed sleep: replaces `existing`
    /// with a re-derived confirmation over the new window, preserving its motion
    /// lineage. See `confirmSleepWindow`.
    @discardableResult
    func adjustConfirmedSleepWindow(existing: UserConfirmedSleep,
                                    start: Date,
                                    end: Date,
                                    isNap: Bool,
                                    rest: Int) async -> UserConfirmedSleep? {
        let result = await confirmSleepWindow(start: start,
                                        end: end,
                                        isNap: isNap,
                                        rest: rest,
                                        replacing: existing.id,
                                        motionValidated: existing.motionValidated,
                                        motionSource: existing.motionSource,
                                        fromSource: existing.source,
                                        settlingCandidateWindow: (existing.start, existing.end))
        if result != nil, autoSleepLoggedBanner?.sleepID == existing.id {
            autoSleepLoggedBanner = nil
        }
        return result
    }

    /// UI entry point for the "Adjust" affordances. Given the night's ORIGINAL
    /// window and the user's NEW window, it edits the existing confirmed sleep
    /// for that night non-destructively, or — for a still-pending review night
    /// with no confirmed record yet — confirms the new window with re-derived
    /// sensor stages (never a blank-stage manual entry, which is what the old
    /// `addManualSleep`-based adjust did).
    @discardableResult
    func adjustSleepNight(originalStart: Date?,
                          originalEnd: Date?,
                          newStart: Date,
                          newEnd: Date,
                          isNap: Bool,
                          rest: Int,
                          source: String = "review_adjust") async -> UserConfirmedSleep? {
        // The night's own window locates the record to edit; if the review night
        // carried no bounds yet, fall back to the user's chosen window.
        let lookupStart = originalStart ?? newStart
        let lookupEnd = originalEnd ?? newEnd
        if let existing = cachedConfirmedSleeps.first(where: { $0.start < lookupEnd && $0.end > lookupStart }) {
            return await adjustConfirmedSleepWindow(existing: existing,
                                              start: newStart,
                                              end: newEnd,
                                              isNap: isNap,
                                              rest: rest)
        }
        let candidateWindow: (start: Date, end: Date)?
        if let originalStart, let originalEnd, originalEnd > originalStart {
            candidateWindow = (originalStart, originalEnd)
        } else {
            candidateWindow = nil
        }
        return await confirmSleepWindow(start: newStart,
                                  end: newEnd,
                                  isNap: isNap,
                                  rest: rest,
                                  fromSource: source,
                                  settlingCandidateWindow: candidateWindow)
    }

    /// Removes a saved sleep or nap and prevents the underlying detector window
    /// from immediately recreating it as a review candidate.
    @discardableResult
    func deleteConfirmedSleep(id: String) async -> Bool {
        guard let removed = cachedConfirmedSleeps.first(where: { $0.id == id }) else { return false }
        guard await saveConfirmedSleeps(
            cachedConfirmedSleeps.filter { $0.id != id },
            publishStressContext:
                Self.sleepStressContextAuthority(removed) != nil
        ) else { return false }
        addDismissedSleepCandidate(start: removed.start, end: removed.end)
        refreshSleepSnapshotAfterCandidateSettlement()
        if autoSleepLoggedBanner?.sleepID == id { autoSleepLoggedBanner = nil }
        dashboardRevision &+= 1
        return true
    }

    /// Marks a sensor suggestion as not sleep. The time-window tombstone is
    /// durable because regenerated rollups do not retain stable candidate IDs.
    /// When automatic settlement already persisted the window — it raced ahead
    /// of the tap, or the presented snapshot was stale — the tombstone alone
    /// left the machine-authored record standing (device 2026-08-20), so the
    /// dismissal also retracts those records through the normal deletion path.
    /// A confirmed night the user authored keeps the old guard instead:
    /// dismissal is not deletion for a record the user created or edited.
    @discardableResult
    func dismissSleepCandidate(_ night: SleepHistorySnapshot.Night) -> Bool {
        guard let start = night.start, let end = night.end, end > start else { return false }
        let retractableIDs = cachedConfirmedSleeps
            .filter { Self.dismissalRetractsConfirmedSleep($0, dismissalStart: start, dismissalEnd: end) }
            .map(\.id)
        if night.confirmed, retractableIDs.isEmpty { return false }
        addDismissedSleepCandidate(start: start, end: end)
        if !retractableIDs.isEmpty {
            Task { @MainActor [weak self] in
                _ = await self?.retractConfirmedSleeps(ids: retractableIDs)
            }
        }
        sleepHistorySnapshot = SleepHistorySnapshot(rollups: historySnapshot.rollups,
                                                    confirmedSleeps: cachedConfirmedSleeps,
                                                    dismissedCandidates: dismissedSleepCandidates)
        refreshHistorySnapshotCache(deferred: true)
        dashboardRevision &+= 1
        return true
    }

    /// Applies durable "not sleep" tombstones to machine-authored confirmed
    /// records once at launch. Both auto-save paths consult tombstones before
    /// persisting and plain Confirm mints user-authored (predicate-protected)
    /// records, so a machine-authored record that a stored tombstone
    /// suppresses can only be the dismissal/auto-confirm race — including
    /// records raced before dismissal-time retraction shipped (device
    /// 2026-08-20: a 13:15–16:15 aggregate_sleep survived its own tombstone).
    /// Returns the scheduled retraction ids so callers (and deterministic
    /// tests) can observe the selection without racing the async sweep.
    @discardableResult
    func reconcileDismissalTombstonesOnLaunch() -> [String] {
        let tombstones = dismissedSleepCandidates
        guard !tombstones.isEmpty else { return [] }
        let retractableIDs = cachedConfirmedSleeps.filter { record in
            tombstones.contains {
                Self.dismissalRetractsConfirmedSleep(
                    record,
                    dismissalStart: $0.start,
                    dismissalEnd: $0.end
                )
            }
        }.map(\.id)
        guard !retractableIDs.isEmpty else { return [] }
        AtriaDebugLog("ATRIADBG sleep_dismissal_reconcile status=launch_sweep retractable=%d tombstones=%d",
                      retractableIDs.count,
                      tombstones.count)
        Task { @MainActor [weak self] in
            _ = await self?.retractConfirmedSleeps(ids: retractableIDs)
        }
        return retractableIDs
    }

    /// Retracts each record through `deleteConfirmedSleep` so tombstoning, day
    /// invalidation, and the settlement snapshot refresh fire exactly as a
    /// manual delete does. Idempotent — an already-removed id is a no-op — and
    /// bounded: the id list is a fixed snapshot, never re-derived while
    /// deleting, and the delete path records tombstones without re-entering
    /// this sweep.
    @discardableResult
    func retractConfirmedSleeps(ids: [String]) async -> Int {
        var retracted = 0
        for id in ids {
            if await deleteConfirmedSleep(id: id) { retracted += 1 }
        }
        return retracted
    }

    private func addDismissedSleepCandidate(start: Date, end: Date) {
        guard end > start else { return }
        dismissedSleepCandidates.removeAll { $0.overlaps(start: start, end: end) }
        dismissedSleepCandidates.append(AtriaDismissedSleepCandidate(start: start, end: end))
        AtriaDismissedSleepCandidateStore.save(dismissedSleepCandidates)
        AtriaPendingSleepReviewStore.clear(
            overlappingStart: start,
            end: end
        )
    }

    private func clearDismissedSleepCandidates(overlappingStart start: Date, end: Date) {
        let previousCount = dismissedSleepCandidates.count
        dismissedSleepCandidates.removeAll { $0.overlaps(start: start, end: end) }
        if dismissedSleepCandidates.count != previousCount {
            AtriaDismissedSleepCandidateStore.save(dismissedSleepCandidates)
        }
    }

    private func refreshSleepSnapshotAfterCandidateSettlement() {
        sleepHistorySnapshot = SleepHistorySnapshot(rollups: historySnapshot.rollups,
                                                    confirmedSleeps: cachedConfirmedSleeps,
                                                    dismissedCandidates: dismissedSleepCandidates)
        refreshHistorySnapshotCache(deferred: true)
        dashboardRevision &+= 1
    }

    func confirmBestSleepCandidateFromLaunchIfRequested(arguments: [String] = ProcessInfo.processInfo.arguments) {
        guard arguments.contains("--atria-confirm-best-sleep-candidate") else { return }
        Task { @MainActor [weak self] in
            guard let self else { return }
            let rest = self.baseline.restingInt ?? 60
            _ = await self.confirmBestSleepCandidate(rest: rest, source: "launch_arg")
        }
    }

    private func confirmBestSleepCandidate(rest: Int, source: String) async -> UserConfirmedSleep? {
        guard let best = Self.preferredSleepCandidateForReview(from: aggregateSleepCandidates(rest: rest, calendar: .current)) else {
            AtriaDebugLog("ATRIADBG sleep_confirm status=learning reason=no_confirmable_candidate source=%@ rest_hr=%d metric_promotions=0 auto_gate_e_unchanged=1",
                  source,
                  rest)
            return nil
        }
        let confirmable = best.kind == "nap_candidate"
            ? best.duration >= AggregateSleepCandidate.napMinimumDuration
            : (best.duration >= AggregateSleepCandidate.fragmentedMinimumDuration
               && best.span >= AggregateSleepCandidate.fragmentedMinimumSpan)
        guard confirmable else {
            AtriaDebugLog("ATRIADBG sleep_confirm status=learning reason=candidate_too_short source=%@ duration_s=%.0f span_s=%.0f sessions=%d metric_promotions=0 auto_gate_e_unchanged=1",
                  source,
                  best.duration,
                  best.span,
                  best.sessions)
            return nil
        }
        var existing = cachedConfirmedSleeps
        let sleepSource = best.kind == "nap_candidate"
            ? "nap_candidate"
            : sleepCandidateSource(for: best)
        let id = confirmedSleepID(start: best.start, end: best.end, source: sleepSource)
        if let already = existing.first(where: { $0.id == id }) {
            AtriaDebugLog("ATRIADBG sleep_confirm status=already_confirmed id=%@ source=%@ candidate_source=%@ start=%@ end=%@ confidence=%@ motion_source=%@ motion_validated=%d metric_promotions=0 auto_gate_e_unchanged=1",
                  already.id,
                  source,
                  already.source,
                  isoString(already.start),
                  isoString(already.end),
                  already.confidence,
                  already.motionSource,
                  already.motionValidated ? 1 : 0)
            return already
        }
        let confidence = best.motionEvidenceValidated ? "user_confirmed_motion_validated" : "user_confirmed_hr_only"
        // ITEM-3 2026-08-15: a user-tapped confirm is a "deliberate lane"
        // that may pay for HR-only staging (the AtriaSleepWakeResearch
        // opt-in doctrine — symmetric with confirmSleepWindow). The engine
        // stays fail-closed on sparse HR, and estimate-provenance segments
        // can never add duration credit (effectiveSleepDuration's
        // allHREstimateProvenance bypass). Previously an HR-only confirm
        // stored no segments at all, so the hypnogram stayed blank until
        // the next launch backfill.
        let stageSegments = Self.sleepStageResearchSegments(from: canonicalSessions(),
                                                            start: best.start,
                                                            end: best.end,
                                                            restingHR: best.restingHR,
                                                            isNap: best.kind == "nap_candidate",
                                                            motionValidated: best.motionEvidenceValidated,
                                                            allowHROnlyEstimate: true)
        let metrics = confirmedSleepWindowMetrics(start: best.start,
                                                  end: best.end,
                                                  rest: best.restingHR)
        let confirmed = UserConfirmedSleep(id: id,
                                           createdAt: Date(),
                                           start: best.start,
                                           end: best.end,
                                           source: sleepSource,
                                           confidence: confidence,
                                           sessions: best.sessions,
                                           samples: best.samples,
                                           avgHR: best.avgHR,
                                           peakHR: best.peakHR,
                                           restingHR: best.restingHR,
                                           hrv: metrics.hrv,
                                           hrvWindowCount: metrics.hrvWindowCount,
                                           respiratoryRate: confirmedSleepRespiratoryRate(start: best.start,
                                                                                           end: best.end),
                                           duration: best.duration,
                                           span: best.span,
                                           reason: best.reason,
                                           motionSource: best.motionEvidenceSource,
                                           motionValidated: best.motionEvidenceValidated,
                                           stageSegments: stageSegments.isEmpty ? nil : stageSegments,
                                           eventTimeZoneIdentifier: TimeZone.current.identifier)
        existing.append(confirmed)
        guard await saveConfirmedSleeps(
            existing,
            publishStressContext:
                Self.sleepStressContextAuthority(confirmed) != nil
        ) else { return nil }
        AtriaDebugLog("ATRIADBG sleep_confirm status=confirmed id=%@ source=%@ candidate_source=%@ start=%@ end=%@ duration_s=%.0f span_s=%.0f sessions=%d samples=%d avg_hr=%d peak_hr=%d rest_hr=%d sleep_rhr=%d confidence=%@ motion_source=%@ motion_validated=%d stage_research_segments=%d reason=%@ metric_promotions=0 auto_gate_e_unchanged=1 healthkit_source=none local_only=1",
              confirmed.id,
              source,
              confirmed.source,
              isoString(confirmed.start),
              isoString(confirmed.end),
              confirmed.duration,
              confirmed.span,
              confirmed.sessions,
              confirmed.samples,
              confirmed.avgHR,
              confirmed.peakHR,
              rest,
              confirmed.restingHR,
              confirmed.confidence,
              confirmed.motionSource,
              confirmed.motionValidated ? 1 : 0,
              confirmed.stageSegments?.count ?? 0,
              confirmed.reason)
        return confirmed
    }

    private func confirmedSleepWindowMetrics(start: Date,
                                             end: Date,
                                             rest: Int) -> (sessions: Int, samples: Int, avgHR: Int, peakHR: Int, restingHR: Int, hrv: Int?, hrvWindowCount: Int) {
        Self.confirmedSleepWindowMetrics(from: canonicalSessions(),
                                         start: start,
                                         end: end,
                                         rest: rest)
    }

    nonisolated static func confirmedSleepWindowMetrics(
        from sessions: [SavedSession],
        start: Date,
        end: Date,
        rest: Int
    ) -> (sessions: Int, samples: Int, avgHR: Int, peakHR: Int, restingHR: Int, hrv: Int?, hrvWindowCount: Int) {
        (try? confirmedSleepWindowMetricsCore(
            from: sessions,
            start: start,
            end: end,
            rest: rest,
            cooperativeDeadline: nil
        )) ?? (0, 0, 0, 0, rest, nil, 0)
    }

    nonisolated static func confirmedSleepWindowMetrics(
        from sessions: [SavedSession],
        start: Date,
        end: Date,
        rest: Int,
        cooperativeDeadline: AtriaSleepSettlementDeadline
    ) throws -> (sessions: Int, samples: Int, avgHR: Int, peakHR: Int, restingHR: Int, hrv: Int?, hrvWindowCount: Int) {
        try confirmedSleepWindowMetricsCore(
            from: sessions,
            start: start,
            end: end,
            rest: rest,
            cooperativeDeadline: cooperativeDeadline
        )
    }

    private nonisolated static func confirmedSleepWindowMetricsCore(
        from sessions: [SavedSession],
        start: Date,
        end: Date,
        rest: Int,
        cooperativeDeadline: AtriaSleepSettlementDeadline?
    ) throws -> (sessions: Int, samples: Int, avgHR: Int, peakHR: Int, restingHR: Int, hrv: Int?, hrvWindowCount: Int) {
        try cooperativeDeadline?.checkpoint()
        var overlapping: [SavedSession] = []
        overlapping.reserveCapacity(sessions.count)
        for (index, session) in sessions.enumerated() {
            if index.isMultiple(of: 16) {
                try cooperativeDeadline?.checkpoint()
            }
            if session.end > start,
               session.start < end,
               (!session.points.isEmpty || session.rrPoints?.isEmpty == false) {
                overlapping.append(session)
            }
        }
        var values: [Int] = []
        for (sessionIndex, session) in overlapping.enumerated() {
            try cooperativeDeadline?.checkpoint()
            for (pointIndex, point) in session.points.enumerated() {
                if pointIndex.isMultiple(of: 256) {
                    try cooperativeDeadline?.checkpoint()
                }
                let sampleTime = session.start.addingTimeInterval(max(0, point.t))
                if sampleTime >= start && sampleTime <= end && point.bpm > 0 {
                    values.append(point.bpm)
                }
            }
            if sessionIndex.isMultiple(of: 8) {
                try cooperativeDeadline?.checkpoint()
            }
        }
        var sum = 0
        var peak = 0
        for (index, value) in values.enumerated() {
            if index.isMultiple(of: 256) {
                try cooperativeDeadline?.checkpoint()
            }
            sum += value
            peak = max(peak, value)
        }
        let avg = values.isEmpty ? 0 : sum / values.count
        var orderedValues = values
        try cooperativeStableSort(
            &orderedValues,
            cooperativeDeadline: cooperativeDeadline,
            areInIncreasingOrder: <
        )
        let resting = values.isEmpty
            ? rest
            : Self.percentileHR(0.05, presorted: orderedValues)
        // A confirmed sleep commonly spans several connection-bounded
        // sessions. Qualify every five-minute window inside its own session so
        // no RR continuity is invented across reconnects, then combine the
        // already-qualified window scalars for the exact sleep interval.
        var qualifiedLnRMSSDWindows: [Double] = []
        for session in overlapping {
            try cooperativeDeadline?.checkpoint()
            if let cooperativeDeadline {
                qualifiedLnRMSSDWindows.append(contentsOf:
                    try session.qualifiedLnRMSSDWindows(
                        in: start,
                        end: end,
                        cooperativeDeadline: cooperativeDeadline
                    )
                )
            } else {
                qualifiedLnRMSSDWindows.append(contentsOf:
                    session.qualifiedLnRMSSDWindows(in: start, end: end)
                )
            }
        }
        let hrvWindowCount = qualifiedLnRMSSDWindows.count
        let hrv: Int?
        if hrvWindowCount < 3 {
            hrv = nil
        } else {
            var sorted = qualifiedLnRMSSDWindows
            try cooperativeStableSort(
                &sorted,
                cooperativeDeadline: cooperativeDeadline,
                areInIncreasingOrder: <
            )
            let middle = sorted.count / 2
            let median = sorted.count.isMultiple(of: 2)
                ? (sorted[middle - 1] + sorted[middle]) / 2
                : sorted[middle]
            let value = Int(exp(median).rounded())
            hrv = value > 0 ? value : nil
        }
        try cooperativeDeadline?.checkpoint()
        return (overlapping.count, values.count, avg, peak, resting, hrv, hrvWindowCount)
    }

    /// Derives one robust sleep-window respiratory scalar without ever joining
    /// raw RR intervals across a reconnect or a greater-than-three-second hole.
    /// Each independently continuous run yields bounded RSA estimates; their
    /// median lets fragmented/overlapping saved sessions contribute without a
    /// long or duplicated fragment dominating the result.
    nonisolated static func confirmedSleepRespiratoryRate(
        from sessions: [SavedSession],
        start: Date,
        end: Date,
        maximumRRGap: TimeInterval = 3
    ) -> Double? {
        try? confirmedSleepRespiratoryRateCore(
            from: sessions,
            start: start,
            end: end,
            maximumRRGap: maximumRRGap,
            cooperativeDeadline: nil
        )
    }

    nonisolated static func confirmedSleepRespiratoryRate(
        from sessions: [SavedSession],
        start: Date,
        end: Date,
        maximumRRGap: TimeInterval = 3,
        cooperativeDeadline: AtriaSleepSettlementDeadline
    ) throws -> Double? {
        try confirmedSleepRespiratoryRateCore(
            from: sessions,
            start: start,
            end: end,
            maximumRRGap: maximumRRGap,
            cooperativeDeadline: cooperativeDeadline
        )
    }

    /// Deadline-aware, result-equivalent compact form of
    /// `AtriaAnalytics.RespRateRsa.estimate(samples:now:lookback:)`. The only
    /// optimization is reuse of the exact trigonometric kernels for repeated
    /// resampled lengths during one settlement proposal.
    private nonisolated static func compactRespiratoryRateEstimate(
        samples: [(t: Date, ms: Double)],
        now: Date,
        lookback: TimeInterval,
        kernelBank: inout AtriaCompactRespiratoryKernelBank,
        cooperativeDeadline: AtriaSleepSettlementDeadline
    ) throws -> Double? {
        try cooperativeDeadline.checkpoint()
        let lowerBound = now.addingTimeInterval(-lookback)
        var recentStartIndex: Int?
        for index in samples.indices {
            if index.isMultiple(of: 256) {
                try cooperativeDeadline.checkpoint()
            }
            if samples[index].t >= lowerBound {
                recentStartIndex = index
                break
            }
        }
        guard let recentStartIndex else { return nil }
        var recentEndIndex = recentStartIndex
        while recentEndIndex < samples.count,
              samples[recentEndIndex].t <= now {
            if recentEndIndex.isMultiple(of: 256) {
                try cooperativeDeadline.checkpoint()
            }
            recentEndIndex += 1
        }
        let recentCount = recentEndIndex - recentStartIndex
        guard recentCount >= 20 else { return nil }
        let first = samples[recentStartIndex].t
        let last = samples[recentEndIndex - 1].t
        let duration = last.timeIntervalSince(first)
        guard duration >= 45 else { return nil }

        let referenceStart = first.timeIntervalSinceReferenceDate
        var relative: [(t: TimeInterval, ms: Double)] = []
        relative.reserveCapacity(recentCount)
        for index in recentStartIndex..<recentEndIndex {
            if index.isMultiple(of: 256) {
                try cooperativeDeadline.checkpoint()
            }
            relative.append((
                samples[index].t.timeIntervalSinceReferenceDate
                    - referenceStart,
                samples[index].ms
            ))
        }
        for index in 1..<relative.count {
            if index.isMultiple(of: 256) {
                try cooperativeDeadline.checkpoint()
            }
            if relative[index].t - relative[index - 1].t > 5.0 {
                return nil
            }
        }

        let sampleRate = 4.0
        let step = 1.0 / sampleRate
        let expectedCount = Int(duration / step) + 1
        guard expectedCount >= Int(45 * sampleRate) else { return nil }
        var resampled: [Double] = []
        resampled.reserveCapacity(expectedCount)
        var sourceIndex = 0
        for index in 0..<expectedCount {
            if index.isMultiple(of: 256) {
                try cooperativeDeadline.checkpoint()
            }
            let time = Double(index) * step
            while sourceIndex + 1 < relative.count,
                  relative[sourceIndex + 1].t < time {
                sourceIndex += 1
                if sourceIndex.isMultiple(of: 256) {
                    try cooperativeDeadline.checkpoint()
                }
            }
            guard sourceIndex + 1 < relative.count else { break }
            let a = relative[sourceIndex]
            let b = relative[sourceIndex + 1]
            let span = b.t - a.t
            guard span > 0 else { continue }
            let fraction = (time - a.t) / span
            resampled.append(a.ms + (b.ms - a.ms) * fraction)
        }
        guard resampled.count >= Int(45 * sampleRate) else { return nil }
        guard resampled.count
                <= AtriaCompactRespiratoryKernelBank.maximumSampleCount else {
            return nil
        }

        var sum = 0.0
        for (index, value) in resampled.enumerated() {
            if index.isMultiple(of: 256) {
                try cooperativeDeadline.checkpoint()
            }
            sum += value
        }
        let mean = sum / Double(resampled.count)
        var centered: [Double] = []
        centered.reserveCapacity(resampled.count)
        var totalPower = 0.0
        for (index, value) in resampled.enumerated() {
            if index.isMultiple(of: 256) {
                try cooperativeDeadline.checkpoint()
            }
            let centeredValue = value - mean
            centered.append(centeredValue)
            totalPower += centeredValue * centeredValue
        }
        guard totalPower > 0 else { return nil }

        let kernels = try kernelBank.kernels(
            cooperativeDeadline: cooperativeDeadline
        )
        var bestRate = 0.0
        var bestPower = 0.0
        var bandPower = 0.0
        var rateIndex = 0
        for breathsPerMinute in stride(
            from: 9.0,
            through: 30.0,
            by: 0.5
        ) {
            try cooperativeDeadline.checkpoint()
            let cosine = kernels.cosines[rateIndex]
            let sine = kernels.sines[rateIndex]
            var real = 0.0
            var sineProjection = 0.0
            // `centered` is structurally capped at 361 values by the fixed
            // 90-second/4-Hz resampling above. Accelerate evaluates the same
            // two dot products without an uninterruptible full-row operation.
            vDSP_dotprD(
                centered,
                1,
                cosine,
                1,
                &real,
                vDSP_Length(centered.count)
            )
            vDSP_dotprD(
                centered,
                1,
                sine,
                1,
                &sineProjection,
                vDSP_Length(centered.count)
            )
            let imaginary = -sineProjection
            try cooperativeDeadline.checkpoint()
            let power = real * real + imaginary * imaginary
            bandPower += power
            if power > bestPower {
                bestPower = power
                bestRate = breathsPerMinute
            }
            rateIndex += 1
        }
        guard bestPower > 0,
              bestPower / max(bandPower, bestPower) >= 0.18 else {
            return nil
        }
        try cooperativeDeadline.checkpoint()
        return bestRate
    }

    private nonisolated static func confirmedSleepRespiratoryRateCore(
        from sessions: [SavedSession],
        start: Date,
        end: Date,
        maximumRRGap: TimeInterval,
        cooperativeDeadline: AtriaSleepSettlementDeadline?
    ) throws -> Double? {
        try cooperativeDeadline?.checkpoint()
        guard end > start, maximumRRGap > 0 else { return nil }
        var estimates: [Double] = []
        var compactKernelBank = AtriaCompactRespiratoryKernelBank()

        for (sessionIndex, session) in sessions.enumerated()
            where session.end > start && session.start < end {
            if sessionIndex.isMultiple(of: 8) {
                try cooperativeDeadline?.checkpoint()
            }
            let provenanceQualified: Bool
            if let cooperativeDeadline {
                provenanceQualified = try session.hasQualifiedRRProvenance(
                    cooperativeDeadline: cooperativeDeadline
                )
            } else {
                provenanceQualified = session.hasQualifiedRRProvenance
            }
            guard provenanceQualified,
                  let rrPoints = session.rrPoints else { continue }
            var samples: [(t: Date, ms: Double)] = []
            samples.reserveCapacity(rrPoints.count)
            for (pointIndex, point) in rrPoints.enumerated() {
                if pointIndex.isMultiple(of: 256) {
                    try cooperativeDeadline?.checkpoint()
                }
                let timestamp = session.start.addingTimeInterval(max(0, point.t))
                if timestamp >= start,
                   timestamp <= end,
                   (300...2_000).contains(point.ms) {
                    samples.append((timestamp, Double(point.ms)))
                }
            }
            try cooperativeStableSort(
                &samples,
                cooperativeDeadline: cooperativeDeadline,
                areInIncreasingOrder: { $0.t < $1.t }
            )

            var run: [(t: Date, ms: Double)] = []
            func finishRun() throws {
                try cooperativeDeadline?.checkpoint()
                guard run.count >= 20,
                      let first = run.first?.t,
                      let last = run.last?.t,
                      last.timeIntervalSince(first) >= 45 else {
                    run.removeAll(keepingCapacity: true)
                    return
                }
                func checkedEstimate(at evaluation: Date) throws -> Double? {
                    guard let cooperativeDeadline else {
                        return AtriaAnalytics.RespRateRsa.estimate(
                            samples: run,
                            now: evaluation,
                            lookback: 90
                        )
                    }
                    try cooperativeDeadline.checkpoint()
                    let lowerDate = evaluation.addingTimeInterval(-90)
                    var lower = 0
                    var upper = run.count
                    while lower < upper {
                        let middle = (lower + upper) / 2
                        if run[middle].t < lowerDate {
                            lower = middle + 1
                        } else {
                            upper = middle
                        }
                    }
                    let firstIndex = lower
                    lower = firstIndex
                    upper = run.count
                    while lower < upper {
                        let middle = (lower + upper) / 2
                        if run[middle].t <= evaluation {
                            lower = middle + 1
                        } else {
                            upper = middle
                        }
                    }
                    let endIndex = lower
                    let count = max(0, endIndex - firstIndex)
                    guard count
                            <= compactLatestNightMaximumRespirationWindowRows else {
                        return nil
                    }
                    var bounded: [(t: Date, ms: Double)] = []
                    bounded.reserveCapacity(count)
                    if firstIndex < endIndex {
                        for index in firstIndex..<endIndex {
                            if index.isMultiple(of: 256) {
                                try cooperativeDeadline.checkpoint()
                            }
                            bounded.append(run[index])
                        }
                    }
                    try cooperativeDeadline.checkpoint()
                    return try compactRespiratoryRateEstimate(
                        samples: bounded,
                        now: evaluation,
                        lookback: 90,
                        kernelBank: &compactKernelBank,
                        cooperativeDeadline: cooperativeDeadline
                    )
                }
                var evaluation = first.addingTimeInterval(60)
                while evaluation <= last {
                    try cooperativeDeadline?.checkpoint()
                    if let rate = try checkedEstimate(at: evaluation) {
                        estimates.append(rate)
                    }
                    evaluation = evaluation.addingTimeInterval(30)
                }
                try cooperativeDeadline?.checkpoint()
                if let rate = try checkedEstimate(at: last) {
                    estimates.append(rate)
                }
                run.removeAll(keepingCapacity: true)
            }

            for (sampleIndex, sample) in samples.enumerated() {
                if sampleIndex.isMultiple(of: 256) {
                    try cooperativeDeadline?.checkpoint()
                }
                if let previous = run.last {
                    let gap = sample.t.timeIntervalSince(previous.t)
                    if gap <= 0 || gap > maximumRRGap {
                        try finishRun()
                    }
                }
                run.append(sample)
            }
            try finishRun()
        }

        guard !estimates.isEmpty else { return nil }
        var ordered = estimates
        try cooperativeStableSort(
            &ordered,
            cooperativeDeadline: cooperativeDeadline,
            areInIncreasingOrder: <
        )
        let middle = ordered.count / 2
        return ordered.count.isMultiple(of: 2)
            ? (ordered[middle - 1] + ordered[middle]) / 2
            : ordered[middle]
    }

    private func confirmedSleepRespiratoryRate(start: Date, end: Date) -> Double? {
        Self.confirmedSleepRespiratoryRate(from: canonicalSessions(),
                                           start: start,
                                           end: end)
    }

    nonisolated static func confirmedSleepSensorCoverage(from sessions: [SavedSession],
                                                         start: Date,
                                                         end: Date) -> TimeInterval {
        let intervals = sessions.compactMap { session -> (start: Date, end: Date)? in
            let overlapStart = Swift.max(session.start, start)
            let overlapEnd = Swift.min(session.end, end)
            guard overlapEnd > overlapStart else { return nil }
            return (overlapStart, overlapEnd)
        }.sorted { $0.start < $1.start }
        guard var current = intervals.first else { return 0 }

        var covered: TimeInterval = 0
        for interval in intervals.dropFirst() {
            if interval.start <= current.end {
                current.end = Swift.max(current.end, interval.end)
            } else {
                covered += current.end.timeIntervalSince(current.start)
                current = interval
            }
        }
        return covered + current.end.timeIntervalSince(current.start)
    }

    private nonisolated static func confirmedSleepSensorCoverage(
        from sessions: [SavedSession],
        start: Date,
        end: Date,
        cooperativeDeadline: AtriaSleepSettlementDeadline
    ) throws -> TimeInterval {
        try cooperativeDeadline.checkpoint()
        var intervals: [(start: Date, end: Date)] = []
        intervals.reserveCapacity(sessions.count)
        for (index, session) in sessions.enumerated() {
            if index.isMultiple(of: 32) {
                try cooperativeDeadline.checkpoint()
            }
            let overlapStart = Swift.max(session.start, start)
            let overlapEnd = Swift.min(session.end, end)
            if overlapEnd > overlapStart {
                intervals.append((overlapStart, overlapEnd))
            }
        }
        try AtriaSleepCooperativeAlgorithms.stableSort(
            &intervals,
            cooperativeDeadline: cooperativeDeadline,
            areInIncreasingOrder: { $0.start < $1.start }
        )
        guard var current = intervals.first else { return 0 }
        var covered: TimeInterval = 0
        for (index, interval) in intervals.dropFirst().enumerated() {
            if index.isMultiple(of: 32) {
                try cooperativeDeadline.checkpoint()
            }
            if interval.start <= current.end {
                current.end = Swift.max(current.end, interval.end)
            } else {
                covered += current.end.timeIntervalSince(current.start)
                current = interval
            }
        }
        try cooperativeDeadline.checkpoint()
        return covered + current.end.timeIntervalSince(current.start)
    }

    private nonisolated static func sleepStageResearchSegments(from sessions: [SavedSession],
                                                               start: Date,
                                                               end: Date,
                                                               restingHR: Int,
                                                               isNap: Bool,
                                                               motionValidated: Bool,
                                                               allowHROnlyEstimate: Bool = false) -> [SleepStageSegment] {
        (try? sleepStageResearchSegmentsCore(
            from: sessions,
            start: start,
            end: end,
            restingHR: restingHR,
            isNap: isNap,
            motionValidated: motionValidated,
            allowHROnlyEstimate: allowHROnlyEstimate,
            maximumRows: nil,
            cooperativeDeadline: nil
        )) ?? []
    }

