        from sessions: [SavedSession],
        start: Date,
        end: Date,
        restingHR: Int,
        isNap: Bool,
        motionValidated: Bool,
        allowHROnlyEstimate: Bool = false,
        maximumRows: Int,
        cooperativeDeadline: AtriaSleepSettlementDeadline
    ) throws -> [SleepStageSegment] {
        try sleepStageResearchSegmentsCore(
            from: sessions,
            start: start,
            end: end,
            restingHR: restingHR,
            isNap: isNap,
            motionValidated: motionValidated,
            allowHROnlyEstimate: allowHROnlyEstimate,
            maximumRows: maximumRows,
            cooperativeDeadline: cooperativeDeadline
        )
    }

    private nonisolated static func sleepStageResearchSegmentsCore(
        from sessions: [SavedSession],
        start: Date,
        end: Date,
        restingHR: Int,
        isNap: Bool,
        motionValidated: Bool,
        allowHROnlyEstimate: Bool = false,
        maximumRows: Int?,
        cooperativeDeadline: AtriaSleepSettlementDeadline?
    ) throws -> [SleepStageSegment] {
        try cooperativeDeadline?.checkpoint()
        var samples: [AtriaSleepWakeResearch.HeartSample] = []
        var recoveredMotionEpochs: [AtriaRecoveredMotionEpoch] = []
        for (sessionIndex, session) in sessions.enumerated() {
            if sessionIndex.isMultiple(of: 8) {
                try cooperativeDeadline?.checkpoint()
            }
            if session.end >= start,
               session.start <= end,
               !session.points.isEmpty {
                for (pointIndex, point) in session.points.enumerated() {
                    if pointIndex.isMultiple(of: 256) {
                        try cooperativeDeadline?.checkpoint()
                    }
                    let t = session.start.addingTimeInterval(max(0, point.t))
                    if t >= start, t <= end {
                        samples.append(.init(t: t, bpm: point.bpm))
                        if let maximumRows, samples.count > maximumRows {
                            // Stages are optional; never let the unchecked
                            // research engine consume an unbounded input.
                            return []
                        }
                    }
                }
            }
            for (epochIndex, epoch) in (session.recoveredMotionEpochs ?? []).enumerated() {
                if epochIndex.isMultiple(of: 256) {
                    try cooperativeDeadline?.checkpoint()
                }
                if epoch.end > start, epoch.start < end {
                    recoveredMotionEpochs.append(epoch)
                    if let maximumRows,
                       recoveredMotionEpochs.count > maximumRows {
                        return []
                    }
                }
            }
        }
        let rrInputs = try sleepStageQualifiedRRInputs(
            from: sessions,
            start: start,
            end: end,
            maximumRows: maximumRows,
            cooperativeDeadline: cooperativeDeadline
        )
        try cooperativeDeadline?.checkpoint()
        if let cooperativeDeadline {
            return try AtriaSleepWakeResearch.stageSegments(
                samples: samples,
                start: start,
                end: end,
                restingHR: restingHR,
                isNap: isNap,
                motionValidated: motionValidated,
                motionEpochs: recoveredMotionEpochs,
                rrSamples: rrInputs.rrSamples,
                qualifiedRRCoverageFraction: rrInputs.qualifiedRRCoverageFraction,
                allowHROnlyEstimate: allowHROnlyEstimate,
                cooperativeDeadline: cooperativeDeadline
            )
        }
        return AtriaSleepWakeResearch.stageSegments(
            samples: samples,
            start: start,
            end: end,
            restingHR: restingHR,
            isNap: isNap,
            motionValidated: motionValidated,
            motionEpochs: recoveredMotionEpochs,
            rrSamples: rrInputs.rrSamples,
            qualifiedRRCoverageFraction: rrInputs.qualifiedRRCoverageFraction,
            allowHROnlyEstimate: allowHROnlyEstimate
        )
    }

    /// Test-visible pure RR gather for the stage engine (2026-08-20, P1).
    /// Sessions must be provenance-qualified as a whole — standard 2A37 and
    /// verified WHOOP4 historical V24 beats only (`hasQualifiedRRProvenance`;
    /// V24 is never promoted), a mixed or unlabeled stream contributes
    /// nothing — and each beat is clamped to the same 300–2000 ms physiologic
    /// bound as `confirmedSleepRespiratoryRateCore`. The window coverage
    /// fraction uses the auto-confirm gate's samples-per-second convention.
    /// RR is a refinement input, never admission evidence: an over-budget RR
    /// stream is dropped whole (empty samples, zero coverage) so the night
    /// still stages under its HR-only rules, in contrast to the HR/motion
    /// bounds above, which must abandon the projection.
    nonisolated static func sleepStageQualifiedRRInputs(
        from sessions: [SavedSession],
        start: Date,
        end: Date,
        maximumRows: Int?,
        cooperativeDeadline: AtriaSleepSettlementDeadline?
    ) throws -> (rrSamples: [AtriaSleepWakeResearch.RRSample],
                 qualifiedRRCoverageFraction: Double) {
        try cooperativeDeadline?.checkpoint()
        guard end > start else { return ([], 0) }
        var rrSamples: [AtriaSleepWakeResearch.RRSample] = []
        for (sessionIndex, session) in sessions.enumerated() {
            if sessionIndex.isMultiple(of: 8) {
                try cooperativeDeadline?.checkpoint()
            }
            guard session.end >= start,
                  session.start <= end,
                  let rrPoints = session.rrPoints,
                  !rrPoints.isEmpty else { continue }
            let provenanceQualified: Bool
            if let cooperativeDeadline {
                provenanceQualified = try session.hasQualifiedRRProvenance(
                    cooperativeDeadline: cooperativeDeadline
                )
            } else {
                provenanceQualified = session.hasQualifiedRRProvenance
            }
            guard provenanceQualified else { continue }
            for (pointIndex, point) in rrPoints.enumerated() {
                if pointIndex.isMultiple(of: 256) {
                    try cooperativeDeadline?.checkpoint()
                }
                let t = session.start.addingTimeInterval(max(0, point.t))
                if t >= start, t <= end, (300...2_000).contains(point.ms) {
                    rrSamples.append(.init(t: t, ms: Double(point.ms)))
                    if let maximumRows, rrSamples.count > maximumRows {
                        return ([], 0)
                    }
                }
            }
        }
        try cooperativeDeadline?.checkpoint()
        let qualifiedRRCoverageFraction = min(
            1,
            Double(rrSamples.count) / max(1, end.timeIntervalSince(start))
        )
        return (rrSamples, qualifiedRRCoverageFraction)
    }

    private nonisolated static func sleepStageResearchSampleCount(from sessions: [SavedSession],
                                                                  start: Date,
                                                                  end: Date) -> Int {
        sessions.reduce(0) { total, session in
            guard session.end >= start,
                  session.start <= end,
                  !session.points.isEmpty else { return total }
            let count = session.points.reduce(0) { pointTotal, point in
                let t = session.start.addingTimeInterval(max(0, point.t))
                return t >= start && t <= end && point.bpm > 0 ? pointTotal + 1 : pointTotal
            }
            return total + count
        }
    }

    private nonisolated static func sleepStageResearchSampleCount(
        from sessions: [SavedSession],
        start: Date,
        end: Date,
        cooperativeDeadline: AtriaSleepSettlementDeadline
    ) throws -> Int {
        try cooperativeDeadline.checkpoint()
        var count = 0
        for (sessionIndex, session) in sessions.enumerated() {
            if sessionIndex.isMultiple(of: 16) {
                try cooperativeDeadline.checkpoint()
            }
            guard session.end >= start,
                  session.start <= end,
                  !session.points.isEmpty else { continue }
            for (pointIndex, point) in session.points.enumerated() {
                if pointIndex.isMultiple(of: 256) {
                    try cooperativeDeadline.checkpoint()
                }
                let timestamp = session.start.addingTimeInterval(
                    max(0, point.t)
                )
                if timestamp >= start,
                   timestamp <= end,
                   point.bpm > 0 {
                    count += 1
                }
            }
        }
        try cooperativeDeadline.checkpoint()
        return count
    }

    private static func readConfirmedSleeps() -> [UserConfirmedSleep] {
        guard let data = UserDefaults.standard.data(forKey: ConfirmedSleepDefaults.key),
              let decoded = try? JSONDecoder().decode([UserConfirmedSleep].self, from: data) else {
            return []
        }
        let sorted = decoded.sorted { $0.start > $1.start }
        let migrated = sorted.map(Self.migratingConfirmedSleepStagesIfNeeded)
        if migrated != sorted, let data = try? JSONEncoder().encode(migrated) {
            UserDefaults.standard.set(data, forKey: ConfirmedSleepDefaults.key)
            let migratedCount = zip(sorted, migrated).filter { $0.stageSegments != $1.stageSegments }.count
            AtriaDebugLog("ATRIADBG sleep_confirmed_migration status=updated records=%d reason=legacy_missing_stage_segments",
                          migratedCount)
        }
        return migrated
    }

    private static func migratingConfirmedSleepStagesIfNeeded(_ sleep: UserConfirmedSleep) -> UserConfirmedSleep {
        if Self.shouldPreserveConfirmedSleepStageSegments(sleep) {
            return sleep
        }
        if sleep.stageSegments?.isEmpty == false {
            return Self.copyConfirmedSleep(sleep, stageSegments: nil)
        }
        let migratedStages = Self.legacyConfirmedSleepStageCompatibility(start: sleep.start,
                                                                         end: sleep.end,
                                                                         source: sleep.source)
        guard !migratedStages.isEmpty else { return sleep }
        return Self.copyConfirmedSleep(sleep, stageSegments: migratedStages)
    }

    // Internal (not private) so the backfill-hygiene behavior is directly
    // testable — same seam pattern as `fragmentedAggregateHRStagesAreUnsupported`.
    nonisolated static func
        shouldPreserveConfirmedSleepStageSegments(
            _ sleep: UserConfirmedSleep
        ) -> Bool {
        guard let stageSegments = sleep.stageSegments, !stageSegments.isEmpty else { return false }
        if sleep.source == "manual_sleep" || sleep.source == "manual_nap" { return false }
        guard AtriaSleepStageIntegrity.validates(stageSegments, for: sleep) else { return false }
        if sleep.source == "validated_sleep_stages" { return true }
        // These versioned IDs are bounded migration receipts: only the fail-
        // closed engine emits them — `research-motion-v2-` when dense, local
        // HR plus actual recovered motion epochs backed the night, and the
        // estimate-lane prefixes (`research-hr-estimate-v1-`, and its
        // strong-RR tier `research-hr-estimate-rr90-v1-` via the
        // `allHREstimateProvenance` choke point) when dense HR alone staged
        // a labeled ESTIMATE (2026-08-12; renders only through the estimate
        // lane). Legacy `research-*` segments have neither provenance and
        // are stripped until source sessions reconstruct them.
        guard stageSegments.allSatisfy({ $0.id.hasPrefix(SleepStageSegment.motionReceiptIDPrefix) })
                || SleepStageSegment.allHREstimateProvenance(stageSegments) else {
            return false
        }
        let hasSleepStageEstimate = stageSegments.contains { $0.stage != .awake }
        return hasSleepStageEstimate
    }

    nonisolated static func aggregateHRStageFallbackHasDenseCoverage(
        duration: TimeInterval,
        span: TimeInterval,
        minimumCoverageFraction: Double = 0.80
    ) -> Bool {
        guard duration > 0, span > 0 else { return false }
        return min(1, duration / span) >= minimumCoverageFraction
    }

    nonisolated static func fragmentedAggregateHRStagesAreUnsupported(_ sleep: UserConfirmedSleep) -> Bool {
        guard sleep.stageSegments?.contains(where: { $0.id.hasPrefix("aggregate-hr-") }) == true else {
            return false
        }
        return !aggregateHRStageFallbackHasDenseCoverage(duration: sleep.duration,
                                                         span: sleep.span)
    }

    nonisolated private static func copyConfirmedSleep(
        _ sleep: UserConfirmedSleep,
        stageSegments: [SleepStageSegment]?,
        motionSource: String? = nil,
        motionValidated: Bool? = nil
    ) -> UserConfirmedSleep {
        return UserConfirmedSleep(id: sleep.id,
                                  createdAt: sleep.createdAt,
                                  start: sleep.start,
                                  end: sleep.end,
                                  source: sleep.source,
                                  confidence: sleep.confidence,
                                  sessions: sleep.sessions,
                                  samples: sleep.samples,
                                  avgHR: sleep.avgHR,
                                  peakHR: sleep.peakHR,
                                  restingHR: sleep.restingHR,
                                  hrv: sleep.hrv,
                                  hrvWindowCount: sleep.hrvWindowCount,
                                  respiratoryRate: sleep.respiratoryRate,
                                  duration: sleep.duration,
                                  span: sleep.span,
                                  reason: sleep.reason,
                                  motionSource: motionSource ?? sleep.motionSource,
                                  motionValidated: motionValidated ?? sleep.motionValidated,
                                  stageSegments: stageSegments,
                                  eventTimeZoneIdentifier: sleep.eventTimeZoneIdentifier,
                                  sleepNeedSeconds: sleep.sleepNeedSeconds,
                                  frozenSleepNeed: sleep.frozenSleepNeed,
                                  dayPrimaryChoice: sleep.dayPrimaryChoice)
    }

    private static func legacyConfirmedSleepStageCompatibility(start: Date,
                                                               end: Date,
                                                               source: String) -> [SleepStageSegment] {
        // A label and duration do not contain stage evidence. Legacy records
        // stay stage-unavailable until the HR/motion stager can reconstruct
        // them from real timestamped samples.
        _ = start
        _ = end
        _ = source
        return []
    }

    nonisolated static func confirmedSleepSourceIsNap(source: String, duration: TimeInterval) -> Bool {
        if SleepHistorySnapshot.Night.explicitNapSources.contains(source) {
            return true
        }
        if SleepHistorySnapshot.Night.explicitSleepSources.contains(source) {
            return false
        }
        return duration <= AggregateSleepCandidate.napMaximumSpan
    }

    /// `user_adjusted_sleep` is produced only by `confirmSleepWindow`, which
    /// re-derives metrics from stored sensor sessions and stores `duration` as
    /// measured coverage inside the chosen bounds. Once the user explicitly
    /// says that evidence is Sleep, requiring the automatic detector's three-
    /// hour floor contradicts the saved record and leaves Recovery on the prior
    /// cycle. The exception still requires a bounded, densely observed chosen
    /// span: an arbitrary all-day edit containing only twenty minutes of strap
    /// data cannot move the physiological boundary. Automatic detections, blank
    /// `manual_sleep` records, and every nap source retain the normal main-sleep
    /// policy.
    nonisolated private static func confirmedSleepMeetsPhysiologicalMainSleepPolicy(
        source: String,
        start: Date,
        end: Date,
        measuredDuration: TimeInterval
    ) -> Bool {
        guard start.timeIntervalSinceReferenceDate.isFinite,
              end.timeIntervalSinceReferenceDate.isFinite,
              measuredDuration.isFinite,
              end > start,
              !confirmedSleepSourceIsNap(
                source: source,
                duration: measuredDuration
              ) else { return false }
        let isUserAdjustedSleep = source == "user_adjusted_sleep"
        if isUserAdjustedSleep {
            let span = end.timeIntervalSince(start)
            guard span <= AggregateSleepCandidate.maximumAutoConfirmMainSleepSpan,
                  measuredDuration / span
                    >= AggregateSleepCandidate.minimumAutoConfirmHRCoverageFraction else {
                return false
            }
        }
        let minimumDuration = isUserAdjustedSleep
            ? AggregateSleepCandidate.napMinimumDuration
            : AtriaPhysiologicalCycle.minimumMainSleepDuration
        return measuredDuration >= minimumDuration
    }

    nonisolated static func confirmedSleepIsPhysiologicalMainSleep(_ sleep: UserConfirmedSleep) -> Bool {
        confirmedSleepMeetsPhysiologicalMainSleepPolicy(
            source: sleep.source,
            start: sleep.start,
            end: sleep.end,
            measuredDuration: sleep.duration
        )
    }

    /// SleepHistorySnapshot is the common publication source for both the
    /// bulk daily rebuild and the current-morning freeze. Keep their definition
    /// of a physiological main sleep identical so a short confirmed rest cannot
    /// enter one path after being rejected by the other.
    nonisolated static func confirmedSleepIsPhysiologicalMainSleep(
        _ night: SleepHistorySnapshot.Night
    ) -> Bool {
        guard night.confirmed,
              let start = night.start,
              let end = night.end else { return false }
        return confirmedSleepMeetsPhysiologicalMainSleepPolicy(
            source: night.source,
            start: start,
            end: end,
            measuredDuration: night.observedDuration
        )
    }

    /// The most recent wake civil day carrying two or more confirmed
    /// physiological main sleeps with NO "which is your main sleep?" answer yet.
    /// Pure and testable. Resumed continuations and naps are excluded; a day is
    /// considered answered the moment any of its mains carries a non-nil
    /// `dayPrimaryChoice`, so a resolved day never prompts again.
    nonisolated static func pendingSameDayMainSleepChoice(
        confirmedSleeps: [UserConfirmedSleep],
        calendar: Calendar
    ) -> AtriaSameDayMainSleepChoice? {
        var mainsByDay: [Date: [UserConfirmedSleep]] = [:]
        for sleep in confirmedSleeps
        where sleep.source != "resumed_sleep"
            && confirmedSleepIsPhysiologicalMainSleep(sleep) {
            let day = EventCivilTime.day(
                containing: sleep.end,
                eventTimeZoneIdentifier: sleep.eventTimeZoneIdentifier,
                outputCalendar: calendar)
            mainsByDay[day, default: []].append(sleep)
        }
        let unresolved = mainsByDay
            .filter { entry in
                entry.value.count >= 2
                    && entry.value.allSatisfy { $0.dayPrimaryChoice == nil }
            }
            .sorted { $0.key > $1.key }
        guard let (day, mains) = unresolved.first else { return nil }
        let ordered = mains.sorted { lhs, rhs in
            if lhs.effectiveSleepDuration != rhs.effectiveSleepDuration {
                return lhs.effectiveSleepDuration > rhs.effectiveSleepDuration
            }
            return lhs.end > rhs.end
        }
        return AtriaSameDayMainSleepChoice(morningDay: day, options: ordered)
    }

    nonisolated private static func physiologicalMainSleepNight(
        _ candidate: SleepHistorySnapshot.Night,
        isPreferredTo existing: SleepHistorySnapshot.Night
    ) -> Bool {
        let candidateEnd = candidate.end ?? candidate.day
        let existingEnd = existing.end ?? existing.day
        return candidate.duration > existing.duration
            || (candidate.duration == existing.duration
                && candidateEnd > existingEnd)
            || (candidate.duration == existing.duration
                && candidateEnd == existingEnd
                && candidate.id < existing.id)
    }

    /// Canonical morning authority is keyed by the final wake in the event time
    /// zone, including a linked resumed segment whose wake crosses civil
    /// midnight. The tie-break is the same deterministic one used by the bulk
    /// saved-daily-metric union.
    nonisolated private static func canonicalPhysiologicalMainSleepNight(
        for day: Date,
        in nights: [SleepHistorySnapshot.Night],
        completedBy now: Date,
        calendar: Calendar
    ) -> SleepHistorySnapshot.Night? {
        nights.reduce(nil) { selected, candidate in
            guard confirmedSleepIsPhysiologicalMainSleep(candidate),
                  let end = candidate.end,
                  end <= now,
                  calendar.isDate(
                    morningMetricDay(for: candidate, calendar: calendar),
                    inSameDayAs: day
                  ) else { return selected }
            guard let selected else { return candidate }
            return physiologicalMainSleepNight(
                candidate,
                isPreferredTo: selected
            ) ? candidate : selected
        }
    }

    /// Mints the adaptive target once, at the persistence boundary for a new
    /// main-sleep record.  It deliberately accepts an eligibility set rather
    /// than filling every missing value: historical records that predate this
    /// field are unknown, not invitations to recreate an old target using
    /// today's profile or strain.
    nonisolated static func freezingAdaptiveSleepNeed(
        in sleeps: [UserConfirmedSleep],
        freezableSleepIDs: Set<String>,
        dailyMetrics: [SavedDailyMetric],
        baseNeedHours: Double,
        calendar: Calendar,
        shouldContinue: @escaping @Sendable () -> Bool = { true }
    ) -> [UserConfirmedSleep]? {
        guard shouldContinue() else { return nil }
        var ordered = sleeps
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &ordered,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: {
                if $0.end != $1.end { return $0.end < $1.end }
                return $0.start < $1.start
            }
        ) else { return nil }
        var settled: [UserConfirmedSleep] = []

        for (sleepIndex, sleep) in ordered.enumerated() {
            if sleepIndex.isMultiple(of: 16), !shouldContinue() { return nil }
            guard freezableSleepIDs.contains(sleep.id),
                  sleep.sleepNeedSeconds == nil,
                  confirmedSleepIsPhysiologicalMainSleep(sleep) else {
                settled.append(sleep)
                continue
            }

            let sleepDay = EventCivilTime.day(
                containing: sleep.end,
                eventTimeZoneIdentifier: sleep.eventTimeZoneIdentifier,
                outputCalendar: calendar
            )
            let sleepDayStart = calendar.startOfDay(for: sleepDay)
            var latestPriorMetric: SavedDailyMetric?
            for (index, metric) in dailyMetrics.enumerated() {
                if index.isMultiple(of: 32), !shouldContinue() { return nil }
                guard calendar.startOfDay(for: metric.day) < sleepDayStart else {
                    continue
                }
                if latestPriorMetric.map({ $0.day < metric.day }) ?? true {
                    latestPriorMetric = metric
                }
            }
            var priorFrozenNights: [(needed: Double, slept: Double)] = []
            var previousMainWake: Date?
            for (index, prior) in settled.enumerated() {
                if index.isMultiple(of: 32), !shouldContinue() { return nil }
                guard confirmedSleepIsPhysiologicalMainSleep(prior) else {
                    continue
                }
                if prior.end <= sleep.start,
                   previousMainWake.map({ $0 < prior.end }) ?? true {
                    previousMainWake = prior.end
                }
                guard let need = prior.sleepNeedSeconds, need > 0,
                      prior.effectiveSleepDuration > 0 else { continue }
                priorFrozenNights.append((
                    needed: need / 3_600,
                    slept: prior.effectiveSleepDuration / 3_600
                ))
                if priorFrozenNights.count > 7 {
                    priorFrozenNights.removeFirst()
                }
            }
            let napSearchStart = previousMainWake
                ?? sleep.start.addingTimeInterval(-24 * 60 * 60)
            var napHours = 0.0
            for (index, candidate) in ordered.enumerated() {
                if index.isMultiple(of: 32), !shouldContinue() { return nil }
                if confirmedSleepSourceIsNap(
                    source: candidate.source,
                    duration: candidate.duration
                ), candidate.end > napSearchStart,
                   candidate.end <= sleep.start {
                    napHours += candidate.effectiveSleepDuration / 3_600
                }
            }
            // Assessment P1.8: yesterday's persisted TRIMP is the truth-first
            // input; the 0–21 value is only a fallback for legacy rows that
            // predate dayTRIMP persistence.
            let components = AtriaSleepBudget.sleepNeedComponents(
                baseHours: baseNeedHours,
                yesterdayTRIMP: latestPriorMetric?.dayTRIMP,
                yesterdayStrainFallback: latestPriorMetric?.strain,
                debtHours: AtriaSleepBudget.sleepDebt(nights: priorFrozenNights),
                sameDayNapHours: napHours
            )
            settled.append(sleep.replacingFrozenSleepNeed(.init(components)))
        }
        return shouldContinue() ? settled : nil
    }

    struct ConfirmedMainSleepHRVEvidence: Equatable {
        let value: Int
        let windowCount: Int
        let sleepID: String
        let sleepEnd: Date
    }

    /// Measurement provenance and physiological provenance are separate gates:
    /// `localRMSSD(in:end:)` requires one uniformly verified RR transport and
    /// at least three qualified five-minute windows, while this wrapper additionally
    /// requires those exact RR samples to fall inside a confirmed main sleep.
    nonisolated static func confirmedMainSleepHRVEvidence(
        for session: SavedSession,
        confirmedSleeps: [UserConfirmedSleep]
    ) -> ConfirmedMainSleepHRVEvidence? {
        confirmedMainSleepHRVEvidenceCancellable(
            for: session,
            confirmedSleeps: confirmedSleeps,
            shouldContinue: { true }
        )
    }

    nonisolated static func confirmedMainSleepHRVEvidenceCancellable(
        for session: SavedSession,
        confirmedSleeps: [UserConfirmedSleep],
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> ConfirmedMainSleepHRVEvidence? {
        guard shouldContinue() else { return nil }
        var latest: ConfirmedMainSleepHRVEvidence?
        for (index, sleep) in confirmedSleeps.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            guard confirmedSleepIsPhysiologicalMainSleep(sleep),
                  session.start < sleep.end,
                  session.end > sleep.start else { continue }
            guard let summary = session.localHRVSummaryCancellable(
                in: sleep.start,
                end: sleep.end,
                shouldContinue: shouldContinue
            ) else { return nil }
            guard shouldContinue() else { return nil }
            guard summary.windowCount >= 3,
                  let value = summary.rmssd,
                  value > 0 else { continue }
            let evidence = ConfirmedMainSleepHRVEvidence(
                value: value,
                windowCount: summary.windowCount,
                sleepID: sleep.id,
                sleepEnd: sleep.end
            )
            if latest == nil || evidence.sleepEnd > latest!.sleepEnd {
                latest = evidence
            }
        }
        return shouldContinue() ? latest : nil
    }

    /// Re-derives persisted sleep HRV from exact-window, transport-verified RR
    /// evidence available today. Older confirmed records may carry a scalar
    /// HRV written before provenance was persisted; retaining that scalar after
    /// the current trust gate rejects its source would make historical recovery
    /// look more certain than the underlying record. Keep the user's sleep
    /// boundary and every non-HRV field, but clear or replace HRV strictly from
    /// reproducible raw evidence. (2026-07-18 truth migration)
    nonisolated static func requalifiedConfirmedSleepHRVRecords(
        _ sleeps: [UserConfirmedSleep],
        sessions: [SavedSession]
    ) -> [UserConfirmedSleep] {
        sleeps.map { sleep in
            let metrics = confirmedSleepWindowMetrics(from: sessions,
                                                       start: sleep.start,
                                                       end: sleep.end,
                                                       rest: sleep.restingHR)
            let qualifiedHRV = metrics.hrvWindowCount >= 3 ? metrics.hrv : nil
            // HRV's historical migration intentionally clears scalar-only
            // values that cannot be requalified. Respiration is already stored
            // only after the stricter continuous-run gate above; session
            // pruning must not erase that durable accepted result.
            let respiratoryRate = confirmedSleepRespiratoryRate(from: sessions,
                                                                start: sleep.start,
                                                                end: sleep.end)
                ?? sleep.respiratoryRate
            guard sleep.hrv != qualifiedHRV
                    || sleep.hrvWindowCount != metrics.hrvWindowCount
                    || sleep.respiratoryRate != respiratoryRate else {
                return sleep
            }
            return UserConfirmedSleep(id: sleep.id,
                                      createdAt: sleep.createdAt,
                                      start: sleep.start,
                                      end: sleep.end,
                                      source: sleep.source,
                                      confidence: sleep.confidence,
                                      sessions: sleep.sessions,
                                      samples: sleep.samples,
                                      avgHR: sleep.avgHR,
                                      peakHR: sleep.peakHR,
                                      restingHR: sleep.restingHR,
                                      hrv: qualifiedHRV,
                                      hrvWindowCount: metrics.hrvWindowCount,
                                      respiratoryRate: respiratoryRate,
                                      duration: sleep.duration,
                                      span: sleep.span,
                                      reason: sleep.reason,
                                      motionSource: sleep.motionSource,
                                      motionValidated: sleep.motionValidated,
                                      stageSegments: sleep.stageSegments,
                                      eventTimeZoneIdentifier: sleep.eventTimeZoneIdentifier,
                                      sleepNeedSeconds: sleep.sleepNeedSeconds,
                                      frozenSleepNeed: sleep.frozenSleepNeed)
        }
    }

    nonisolated static func requalifiedConfirmedSleepHRVRecordsCancellable(
        _ sleeps: [UserConfirmedSleep],
        sessions: [SavedSession],
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> [UserConfirmedSleep]? {
        let deadline = recoveredDataExecutionDeadline(
            shouldContinue: shouldContinue
        )
        do {
            var result: [UserConfirmedSleep] = []
            result.reserveCapacity(sleeps.count)
            for (index, sleep) in sleeps.enumerated() {
                if index.isMultiple(of: 8) {
                    try deadline.checkpoint()
                }
                let metrics = try confirmedSleepWindowMetrics(
                    from: sessions,
                    start: sleep.start,
                    end: sleep.end,
                    rest: sleep.restingHR,
                    cooperativeDeadline: deadline
                )
                let qualifiedHRV = metrics.hrvWindowCount >= 3
                    ? metrics.hrv : nil
                let respiratoryRate = try confirmedSleepRespiratoryRate(
                    from: sessions,
                    start: sleep.start,
                    end: sleep.end,
                    cooperativeDeadline: deadline
                ) ?? sleep.respiratoryRate
                guard sleep.hrv != qualifiedHRV
                        || sleep.hrvWindowCount != metrics.hrvWindowCount
                        || sleep.respiratoryRate != respiratoryRate else {
                    result.append(sleep)
                    continue
                }
                result.append(UserConfirmedSleep(
                    id: sleep.id,
                    createdAt: sleep.createdAt,
                    start: sleep.start,
                    end: sleep.end,
                    source: sleep.source,
                    confidence: sleep.confidence,
                    sessions: sleep.sessions,
                    samples: sleep.samples,
                    avgHR: sleep.avgHR,
                    peakHR: sleep.peakHR,
                    restingHR: sleep.restingHR,
                    hrv: qualifiedHRV,
                    hrvWindowCount: metrics.hrvWindowCount,
                    respiratoryRate: respiratoryRate,
                    duration: sleep.duration,
                    span: sleep.span,
                    reason: sleep.reason,
                    motionSource: sleep.motionSource,
                    motionValidated: sleep.motionValidated,
                    stageSegments: sleep.stageSegments,
                    eventTimeZoneIdentifier:
                        sleep.eventTimeZoneIdentifier,
                    sleepNeedSeconds: sleep.sleepNeedSeconds,
                    frozenSleepNeed: sleep.frozenSleepNeed
                ))
            }
            try deadline.checkpoint()
            return result
        } catch {
            return nil
        }
    }

    /// Typed result of a confirmed-sleep stage backfill so the caller can
    /// publish (or decline to publish) the exact commit it produced instead
    /// of guessing from a Bool. `committedConfirmedSleepsRevision` is the
    /// store's confirmed-sleep revision immediately after the durable save
    /// this run performed; nil when nothing was saved.
    struct ConfirmedSleepStageBackfillOutcome {
        let changed: Bool
        let succeeded: Bool
        let affectedSleepIDs: [String]
        let committedConfirmedSleepsRevision: Int?
    }

    private struct ConfirmedSleepHRVRequalificationOutcome {
        let changed: Bool
        let succeeded: Bool
    }

    /// Exact-window HRV and respiration are persisted together by the
    /// requalification pass. A respiration-only migration must invalidate the
    /// wake day just like an HRV change; otherwise the new value is computed in
    /// memory and then silently discarded before `saveConfirmedSleeps`.
    nonisolated static func confirmedSleepQualifiedMetricsChanged(
        previous: UserConfirmedSleep,
        next: UserConfirmedSleep
    ) -> Bool {
        previous.hrv != next.hrv
            || previous.hrvWindowCount != next.hrvWindowCount
            || previous.respiratoryRate != next.respiratoryRate
    }

    private struct ConfirmedSleepBaselineWindow: Equatable {
        let start: Date
        let end: Date
        let isPhysiologicalMainSleep: Bool
    }

    /// Baseline learning depends on the confirmed main-sleep windows, not on
    /// presentation-only fields such as stage labels or motion provenance.
    /// Keeping this comparison explicit prevents a stage repair from replaying
    /// every saved RR window on the main actor during launch/backgrounding.
    nonisolated static func confirmedSleepMutationAffectsBaseline(
        previous: [UserConfirmedSleep],
        next: [UserConfirmedSleep]
    ) -> Bool {
        confirmedSleepMutationAffectsBaselineCancellable(
            previous: previous,
            next: next,
            shouldContinue: { true }
        ) ?? true
    }

    nonisolated static func confirmedSleepMutationAffectsBaselineCancellable(
        previous: [UserConfirmedSleep],
        next: [UserConfirmedSleep],
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> Bool? {
        func windows(
            _ sleeps: [UserConfirmedSleep]
        ) -> [ConfirmedSleepBaselineWindow]? {
            var result: [ConfirmedSleepBaselineWindow] = []
            result.reserveCapacity(sleeps.count)
            for (index, sleep) in sleeps.enumerated() {
                if index.isMultiple(of: 32), !shouldContinue() { return nil }
                result.append(.init(
                    start: sleep.start,
                    end: sleep.end,
                    isPhysiologicalMainSleep:
                        confirmedSleepIsPhysiologicalMainSleep(sleep)
                ))
            }
            guard AtriaSleepCooperativeAlgorithms.stableSort(
                &result,
                shouldContinue: shouldContinue,
                areInIncreasingOrder: {
                    if $0.start != $1.start { return $0.start < $1.start }
                    if $0.end != $1.end { return $0.end < $1.end }
                    return !$0.isPhysiologicalMainSleep
                        && $1.isPhysiologicalMainSleep
                }
            ) else { return nil }
            return result
        }

        guard let previousWindows = windows(previous),
              let nextWindows = windows(next),
              shouldContinue() else { return nil }
        return previousWindows != nextWindows
    }

    nonisolated static func rebasedConfirmedSleeps(
        base: [UserConfirmedSleep],
        desired: [UserConfirmedSleep],
        current: [UserConfirmedSleep]
    ) -> [UserConfirmedSleep] {
        rebasedConfirmedSleepsCancellable(
            base: base,
            desired: desired,
            current: current,
            shouldContinue: { true }
        )!
    }

    nonisolated static func rebasedConfirmedSleepsCancellable(
        base: [UserConfirmedSleep],
        desired: [UserConfirmedSleep],
        current: [UserConfirmedSleep],
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> [UserConfirmedSleep]? {
        guard shouldContinue() else { return nil }
        var baseByID: [String: UserConfirmedSleep] = [:]
        for (index, record) in base.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            baseByID[record.id] = record
        }
        var desiredByID: [String: UserConfirmedSleep] = [:]
        var desiredLastIndex: [String: Int] = [:]
        for (index, record) in desired.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            desiredByID[record.id] = record
            desiredLastIndex[record.id] = index
        }
        let removedIDs = Set(baseByID.keys).subtracting(desiredByID.keys)
        var changed: [UserConfirmedSleep] = []
        for (index, record) in desired.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            guard desiredLastIndex[record.id] == index,
                  baseByID[record.id] != record else { continue }
            changed.append(record)
        }
        var currentOrder: [String] = []
        var currentByID: [String: UserConfirmedSleep] = [:]
        for (index, record) in current.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            if currentByID[record.id] == nil { currentOrder.append(record.id) }
            currentByID[record.id] = record
        }
        var result: [UserConfirmedSleep] = []
        var resultIndexByID: [String: Int] = [:]
        result.reserveCapacity(currentOrder.count + changed.count)
        for (index, id) in currentOrder.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            guard !removedIDs.contains(id), let record = currentByID[id] else {
                continue
            }
            resultIndexByID[id] = result.count
            result.append(record)
        }
        for (index, record) in changed.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            if let index = resultIndexByID[record.id] {
                result[index] = record
            } else {
                resultIndexByID[record.id] = result.count
                result.append(record)
            }
        }
        return shouldContinue() ? result : nil
    }

    /// A recovered repair owns only the delta it prepared from `base`. If a
    /// user/live writer changed or deleted the same id while that preparation
    /// was off-main, the newer authority wins wholesale and the recovered
    /// field repair waits for a fresh generation. Independent ids still merge.
    nonisolated static func rebasedRecoveredConfirmedSleeps(
        base: [UserConfirmedSleep],
        desired: [UserConfirmedSleep],
        current: [UserConfirmedSleep]
    ) -> [UserConfirmedSleep] {
        rebasedRecoveredConfirmedSleepsCancellable(
            base: base,
            desired: desired,
            current: current,
            shouldContinue: { true }
        )!
    }

    nonisolated static func rebasedRecoveredConfirmedSleepsCancellable(
        base: [UserConfirmedSleep],
        desired: [UserConfirmedSleep],
        current: [UserConfirmedSleep],
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> [UserConfirmedSleep]? {
        guard shouldContinue() else { return nil }
        var baseByID: [String: UserConfirmedSleep] = [:]
        for (index, sleep) in base.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            baseByID[sleep.id] = sleep
        }
        var desiredByID: [String: UserConfirmedSleep] = [:]
        for (index, sleep) in desired.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            desiredByID[sleep.id] = sleep
        }
        var result = current
        var resultIndexByID: [String: Int] = [:]
        for (index, sleep) in result.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            resultIndexByID[sleep.id] = index
        }

        for (index, entry) in baseByID.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            let (id, baseSleep) = entry
            guard desiredByID[id] == nil else { continue }
            guard let currentIndex = resultIndexByID[id],
                  result[currentIndex] == baseSleep else { continue }
            result.remove(at: currentIndex)
            resultIndexByID.removeAll(keepingCapacity: true)
            for (index, sleep) in result.enumerated() {
                if index.isMultiple(of: 32), !shouldContinue() { return nil }
                resultIndexByID[sleep.id] = index
            }
        }
        for (index, desiredSleep) in desired.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            let id = desiredSleep.id
            if let baseSleep = baseByID[id] {
                guard desiredSleep != baseSleep,
                      let currentIndex = resultIndexByID[id],
                      result[currentIndex] == baseSleep else { continue }
                result[currentIndex] = desiredSleep
            } else if resultIndexByID[id] == nil {
                resultIndexByID[id] = result.count
                result.append(desiredSleep)
            }
        }
        return shouldContinue() ? result : nil
    }

    nonisolated static func confirmedSleepMutationDelta(
        base: [UserConfirmedSleep],
        desired: [UserConfirmedSleep]
    ) -> (upserts: [String: UserConfirmedSleep], deletedIDs: Set<String>) {
        confirmedSleepMutationDeltaCancellable(
            base: base,
            desired: desired,
            shouldContinue: { true }
        )!
    }

    nonisolated static func confirmedSleepMutationDeltaCancellable(
        base: [UserConfirmedSleep],
        desired: [UserConfirmedSleep],
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> (upserts: [String: UserConfirmedSleep], deletedIDs: Set<String>)? {
        guard shouldContinue() else { return nil }
        var baseByID: [String: UserConfirmedSleep] = [:]
        for (index, record) in base.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            baseByID[record.id] = record
        }
        var desiredByID: [String: UserConfirmedSleep] = [:]
        for (index, record) in desired.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            desiredByID[record.id] = record
        }
        var upserts: [String: UserConfirmedSleep] = [:]
        for (index, entry) in desiredByID.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            let (id, record) = entry
            guard baseByID[id] != record else { continue }
            upserts[id] = record
        }
        guard shouldContinue() else { return nil }
        return (
            upserts,
            Set(baseByID.keys).subtracting(desiredByID.keys)
        )
    }

    /// A process-global writer can finish after lifecycle rollback has already
    /// superseded the store-local generation. Its durable result is still
    /// ordinary user/live authority when the write began under the recovered
    /// transaction but was not owned by that transaction. Deliberately do not
    /// compare `currentGeneration` here: the exact purpose of this decision is
    /// to retain the delta across that generation loss.
    nonisolated static func confirmedSleepWriteMustRecordConcurrentAuthority(
        transactionOrRollbackWasActiveAtStart: Bool,
        transactionOrRollbackIsActiveAtCompletion: Bool,
        recoveredOwnedMutation: Bool,
        completedGeneration: UInt64,
        requestedGeneration: UInt64,
        currentGeneration: UInt64
    ) -> Bool {
        _ = currentGeneration
        return (transactionOrRollbackWasActiveAtStart
                || transactionOrRollbackIsActiveAtCompletion)
            && !recoveredOwnedMutation
            && completedGeneration == requestedGeneration
    }

    struct ConfirmedSleepSavePreparation: @unchecked Sendable {
        let settledSleeps: [UserConfirmedSleep]
        let baselineInputsChanged: Bool
        let concurrentDelta: (
            upserts: [String: UserConfirmedSleep],
            deletedIDs: Set<String>
        )
        let rebuiltBaseline: PersonalBaseline?
        let dutyCycleWindow: (start: Int, end: Int, count: Int)?
        let stepReceiptCycleChanged: Bool
        let nextRolloverBoundary: Date?
    }

    /// A "which is your main sleep?" answer is only meaningful while its day
    /// actually holds two or more physiological main sleeps. Reclassifying a
    /// main to a nap (or deleting one) dissolves the collision, and a stale
    /// `dayPrimaryChoice == false` on the survivor would silently exclude it
    /// from boundary eligibility forever — de-anchoring the physiological day,
    /// freezing the Today ring on the old rollup, and never re-prompting. Every
    /// durable save therefore re-derives flag validity for the final image:
    /// days that no longer collide have their flags cleared, and a record that
    /// is not a physiological main can never carry one.
    nonisolated static func normalizingDayPrimaryChoices(
        in sleeps: [UserConfirmedSleep],
        calendar: Calendar,
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> [UserConfirmedSleep]? {
        guard shouldContinue() else { return nil }
        var mainCountByDay: [Date: Int] = [:]
        for (index, sleep) in sleeps.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            guard sleep.source != "resumed_sleep",
                  confirmedSleepIsPhysiologicalMainSleep(sleep) else { continue }
            let day = EventCivilTime.day(
                containing: sleep.end,
                eventTimeZoneIdentifier: sleep.eventTimeZoneIdentifier,
                outputCalendar: calendar)
            mainCountByDay[day, default: 0] += 1
        }
        var normalized: [UserConfirmedSleep] = []
        normalized.reserveCapacity(sleeps.count)
        for (index, sleep) in sleeps.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            guard sleep.dayPrimaryChoice != nil else {
                normalized.append(sleep)
                continue
            }
            let isMain = sleep.source != "resumed_sleep"
                && confirmedSleepIsPhysiologicalMainSleep(sleep)
            if !isMain {
                normalized.append(sleep.replacingDayPrimaryChoice(nil))
                continue
            }
            let day = EventCivilTime.day(
                containing: sleep.end,
                eventTimeZoneIdentifier: sleep.eventTimeZoneIdentifier,
                outputCalendar: calendar)
            if (mainCountByDay[day] ?? 0) < 2 {
                normalized.append(sleep.replacingDayPrimaryChoice(nil))
            } else {
                normalized.append(sleep)
            }
        }
        return normalized
    }

    /// W3-A P0-1 (recovery settlement at the cycle flip): the boundary the
    /// save transaction arms for `handlePhysiologicalCycleRollover`. A confirm
    /// whose measured wake is still slightly in the future — the shifted
    /// sleeper's daily ~19:15 reality — is invisible to `nextNoSleepRollover`
    /// because `boundaryEligibleMainSleeps` honestly filters `end <= now`, so
    /// without an armed edge at the sleep's own end the new wake day's frozen
    /// metric stays unminted until the next launch while widgets, trend and
    /// HealthKit wait. Arm the existing rollover timer at end+1s instead: the
    /// handler re-checks settlement there, after the honesty gates'
    /// precondition has become true. The `completedBy: now` and `end <= now`
    /// gates themselves are never loosened — this re-triggers the minter; it
    /// never mints from an unfinished night.
    nonisolated static func settlementArmedRolloverBoundary(
        noSleepRollover: Date?,
        newestSettledMainSleepEnd: Date?,
        preparationNow: Date
    ) -> Date? {
        guard let end = newestSettledMainSleepEnd,
              end > preparationNow else {
            return noSleepRollover
        }
        let settlementEdge = end.addingTimeInterval(1)
        guard let noSleepRollover else { return settlementEdge }
        return min(noSleepRollover, settlementEdge)
    }

    nonisolated static func prepareConfirmedSleepSave(
        base: [UserConfirmedSleep],
        desired: [UserConfirmedSleep],
        authoritativeCurrent: [UserConfirmedSleep],
        previous: [UserConfirmedSleep],
        dailyMetrics: [SavedDailyMetric],
        baseNeedHours: Double,
        calendar: Calendar,
        usesRecoveredRebase: Bool,
        rebuildsBaselineOffMain: Bool,
        baselineSessions: [SavedSession],
        previousBaseline: PersonalBaseline,
        profile: AthleteProfile,
        preparationNow: Date,
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> ConfirmedSleepSavePreparation? {
        guard shouldContinue() else { return nil }
        let rebasedRaw: [UserConfirmedSleep]?
        if usesRecoveredRebase {
            rebasedRaw = rebasedRecoveredConfirmedSleepsCancellable(
                base: base,
                desired: desired,
                current: authoritativeCurrent,
                shouldContinue: shouldContinue
            )
        } else {
            rebasedRaw = rebasedConfirmedSleepsCancellable(
                base: base,
                desired: desired,
                current: authoritativeCurrent,
                shouldContinue: shouldContinue
            )
        }
        guard let rebasedUnnormalized = rebasedRaw,
              let rebased = normalizingDayPrimaryChoices(
                in: rebasedUnnormalized,
                calendar: calendar,
                shouldContinue: shouldContinue
              ) else { return nil }

        // GAP-01: the carry preserves the full itemized FrozenNeed receipt
        // when the stored record has one — a same-id rebuild must never
        // downgrade a receipt to a bare scalar, or receipt-only surfaces
        // (Sufficiency, ledger, day history) go blank while the chart still
        // plots the line.
        var existingNeedByID: [String: (need: TimeInterval, receipt: AtriaSleepBudget.FrozenNeed?)] = [:]
        var existingSleepIDs = Set<String>()
        existingNeedByID.reserveCapacity(authoritativeCurrent.count)
        existingSleepIDs.reserveCapacity(authoritativeCurrent.count)
        for (index, sleep) in authoritativeCurrent.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            existingSleepIDs.insert(sleep.id)
            if let need = sleep.sleepNeedSeconds, need > 0 {
                existingNeedByID[sleep.id] = (need: need, receipt: sleep.frozenSleepNeed)
            }
        }
        var needPreservingRebase: [UserConfirmedSleep] = []
        var freezableSleepIDs = Set<String>()
        needPreservingRebase.reserveCapacity(rebased.count)
        for (index, sleep) in rebased.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            let preserved: UserConfirmedSleep
            if sleep.frozenSleepNeed == nil,
               let receipt = existingNeedByID[sleep.id]?.receipt {
                preserved = sleep.replacingFrozenSleepNeed(receipt)
            } else if sleep.sleepNeedSeconds == nil,
               let existing = existingNeedByID[sleep.id] {
                preserved = sleep.replacingSleepNeedSeconds(existing.need)
            } else {
                preserved = sleep
            }
            needPreservingRebase.append(preserved)
            if !existingSleepIDs.contains(preserved.id) {
                freezableSleepIDs.insert(preserved.id)
            }
        }
        guard let settledSleeps = freezingAdaptiveSleepNeed(
            in: needPreservingRebase,
            freezableSleepIDs: freezableSleepIDs,
            dailyMetrics: dailyMetrics,
            baseNeedHours: baseNeedHours,
            calendar: calendar,
            shouldContinue: shouldContinue
        ), let baselineInputsChanged =
            confirmedSleepMutationAffectsBaselineCancellable(
                previous: previous,
                next: settledSleeps,
                shouldContinue: shouldContinue
            ), let concurrentDelta = confirmedSleepMutationDeltaCancellable(
                base: authoritativeCurrent,
                desired: settledSleeps,
                shouldContinue: shouldContinue
            ) else { return nil }

        let rebuiltBaseline: PersonalBaseline?
        if rebuildsBaselineOffMain && baselineInputsChanged {
            guard let rebuilt = rebuildBaselineCancellable(
                from: baselineSessions,
                previousBaseline: previousBaseline,
                profile: profile,
                confirmedSleeps: settledSleeps,
                shouldContinue: shouldContinue
            ) else { return nil }
            rebuiltBaseline = rebuilt
        } else {
            rebuiltBaseline = nil
        }
        let dutyCycleWindow = recoveredDutyCycleSleepWindowCancellable(
            from: settledSleeps,
            calendar: calendar,
            shouldContinue: shouldContinue
        )
        guard shouldContinue() else { return nil }
        let previousCycleStart = AtriaPhysiologicalCycle.current(
            now: preparationNow,
            confirmedSleeps: previous,
            calendar: calendar
        ).start
        guard shouldContinue() else { return nil }
        let nextCycleStart = AtriaPhysiologicalCycle.current(
            now: preparationNow,
            confirmedSleeps: settledSleeps,
            calendar: calendar
        ).start
        guard shouldContinue() else { return nil }
        let nextNoSleepRolloverBoundary = AtriaPhysiologicalCycle
            .nextNoSleepRollover(
                now: preparationNow,
                confirmedSleeps: settledSleeps,
                calendar: calendar
            )
        guard shouldContinue() else { return nil }
        // W3-A P0-1: a future-end confirm arms the settlement edge at the
        // confirmed sleep's own end (+1s) so the cycle flip settles the new
        // wake day's frozen metric without waiting for the next launch.
        guard let settledCanonicalMains = AtriaPhysiologicalCycle
            .canonicalMainSleepsCancellable(
                from: settledSleeps,
                shouldContinue: shouldContinue
            ) else { return nil }
        let nextRolloverBoundary = settlementArmedRolloverBoundary(
            noSleepRollover: nextNoSleepRolloverBoundary,
            newestSettledMainSleepEnd: settledCanonicalMains
                .map(\.end)
                .max(),
            preparationNow: preparationNow
        )
        guard shouldContinue() else { return nil }
        return .init(
            settledSleeps: settledSleeps,
            baselineInputsChanged: baselineInputsChanged,
            concurrentDelta: concurrentDelta,
            rebuiltBaseline: rebuiltBaseline,
            dutyCycleWindow: dutyCycleWindow,
            stepReceiptCycleChanged:
                abs(previousCycleStart.timeIntervalSince(nextCycleStart)) >= 1,
            nextRolloverBoundary: nextRolloverBoundary
        )
    }

    nonisolated private static func recoveredDutyCycleSleepWindowCancellable(
        from sleeps: [UserConfirmedSleep],
        calendar: Calendar,
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> (start: Int, end: Int, count: Int)? {
        var overnights: [UserConfirmedSleep] = []
        overnights.reserveCapacity(14)
        for (index, sleep) in sleeps.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            if !confirmedSleepSourceIsNap(
                source: sleep.source,
                duration: sleep.duration
            ) {
                overnights.append(sleep)
            }
        }
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &overnights,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: {
                if $0.end != $1.end { return $0.end > $1.end }
                return $0.id < $1.id
            }
        ) else { return nil }
        if overnights.count > 14 {
            overnights.removeSubrange(14..<overnights.count)
        }
        guard shouldContinue(), overnights.count >= 3 else { return nil }
        func minutesOfDay(_ date: Date) -> Int {
            let components = calendar.dateComponents([.hour, .minute], from: date)
            return (components.hour ?? 0) * 60 + (components.minute ?? 0)
        }
        var startMinutes: [Int] = []
        var endMinutes: [Int] = []
        startMinutes.reserveCapacity(overnights.count)
        endMinutes.reserveCapacity(overnights.count)
        for (index, sleep) in overnights.enumerated() {
            if index.isMultiple(of: 8), !shouldContinue() { return nil }
            startMinutes.append((minutesOfDay(sleep.start) + 720) % 1_440)
            endMinutes.append(minutesOfDay(sleep.end))
        }
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &startMinutes,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: <
        ), AtriaSleepCooperativeAlgorithms.stableSort(
            &endMinutes,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: <
        ) else { return nil }
        let medianStart = (startMinutes[startMinutes.count / 2] + 720) % 1_440
        let medianEnd = endMinutes[endMinutes.count / 2]
        return (
            start: (medianStart + 1_440 - 60) % 1_440,
            end: (medianEnd + 60) % 1_440,
            count: overnights.count
        )
    }

    /// Identity carrier for the save-time dismissal re-check (follow-up to the
    /// 2026-08-20 dismissal/auto-confirm race fix): an auto-confirm pass hands
    /// `saveConfirmedSleeps` the ids of the records it minted or extended in
    /// this pass, the save re-checks exactly those against freshly loaded
    /// dismissal tombstones immediately before the write, and the ids it
    /// dropped are reported back so the caller never banners or notifies a
    /// record the user dismissed while the persist was in flight.
    @MainActor
    final class AutoConfirmSaveTimeDismissalRecheck {
        let recordIDs: Set<String>
        private(set) var suppressedIDs: Set<String> = []
        init(recordIDs: Set<String>) { self.recordIDs = recordIDs }
        func markSuppressed(_ ids: Set<String>) { suppressedIDs.formUnion(ids) }
    }

    @discardableResult
    private func saveConfirmedSleeps(
        _ sleeps: [UserConfirmedSleep],
        deferDerivedPublication: Bool = false,
        archiveFreeLatestNightSettlement: Bool = false,
        publishStressContext: Bool = false,
        recoveredMutationBase: [UserConfirmedSleep]? = nil,
        autoConfirmDismissalRecheck: AutoConfirmSaveTimeDismissalRecheck? = nil,
        executionShouldContinue:
            @escaping @Sendable () -> Bool = { true }
    ) async -> Bool {
        await Self.confirmedRecordTransactionGate.acquire()
        defer { Self.confirmedRecordTransactionGate.release() }
        guard canonicalMutationAllowed, executionShouldContinue() else {
            AtriaDebugLog("ATRIADBG confirmed_sleep_store status=blocked reason=restore_in_progress")
            return false
        }
        let transactionTicketAtStart =
            recoveredDataMutationTransaction.activeTicket
        let rollbackPersistenceWasActiveAtStart =
            recoveredLifecycleRollbackPersistenceInFlight
        let recoveredOwnedMutationAtStart = deferDerivedPublication
            && transactionTicketAtStart != nil
        let base = recoveredMutationBase ?? cachedConfirmedSleeps
        let previous = cachedConfirmedSleeps
        let dailyMetrics = dailyMetricHistory
        let baselineSessions = cachedCanonicalSessions
        let previousBaseline = baseline
        let profileSnapshot = profile
        let calendar = Calendar.current
        let preparationNow = Date()
        let loaded = await Self.confirmedRecordWorker.performAsync(.loadSleeps(
            defaultsKey: ConfirmedSleepDefaults.key
        ))
        guard executionShouldContinue(),
              case .loadedSleeps(let authoritativeCurrent) = loaded else {
            AtriaDebugLog("ATRIADBG confirmed_sleep_store status=failed reason=authoritative_load_failed")
            return false
        }
        let preparation: ConfirmedSleepSavePreparation? =
            await withCheckedContinuation { continuation in
                DispatchQueue.global(qos: .utility).async {
                    let prepared = AtriaTransientWorkThread.run(
                        name: "atria.confirmed-sleep-save-prepare",
                        qualityOfService: .utility
                    ) {
                        Self.prepareConfirmedSleepSave(
                            base: base,
                            desired: sleeps,
                            authoritativeCurrent: authoritativeCurrent,
                            previous: previous,
                            dailyMetrics: dailyMetrics,
                            baseNeedHours:
                                Self.configuredSleepBaseNeedHours(),
                            calendar: calendar,
                            usesRecoveredRebase:
                                recoveredMutationBase != nil,
                            rebuildsBaselineOffMain:
                                deferDerivedPublication
                                    && !archiveFreeLatestNightSettlement,
                            baselineSessions: baselineSessions,
                            previousBaseline: previousBaseline,
                            profile: profileSnapshot,
                            preparationNow: preparationNow,
                            shouldContinue: executionShouldContinue
                        )
                    }
                    continuation.resume(returning: prepared)
                }
            }
        guard let preparation, executionShouldContinue() else {
            AtriaDebugLog(
                "ATRIADBG confirmed_sleep_store status=deferred reason=execution_authority_revoked_during_prepare"
            )
            return false
        }
        // Save-time dismissal re-check: the auto-confirm loop's tombstone
        // check and this write are separated by suspension points (the
        // transaction gate, the authoritative load, the off-main save
        // preparation), and a "not sleep" tap handled on the MainActor inside
        // any of them lands too late for that check yet too early for
        // dismissal-time retraction to see the record. Re-check the freshly
        // loaded tombstones here — after the last suspension before the write
        // — and drop the suppressed auto-confirmations from the written set.
        // Scoped to the ids this pass minted or extended so an unrelated save
        // never silently filters a pre-existing record out from under its own
        // retraction sweep.
        var settledSleeps = preparation.settledSleeps
        var saveTimeSuppressedIDs: Set<String> = []
        if let autoConfirmDismissalRecheck,
           !autoConfirmDismissalRecheck.recordIDs.isEmpty {
            saveTimeSuppressedIDs = Self.saveTimeDismissalSuppressedSleepIDs(
                in: settledSleeps,
                recheckIDs: autoConfirmDismissalRecheck.recordIDs,
                tombstones: AtriaDismissedSleepCandidateStore.load()
            )
            if !saveTimeSuppressedIDs.isEmpty {
                settledSleeps.removeAll { saveTimeSuppressedIDs.contains($0.id) }
                autoConfirmDismissalRecheck.markSuppressed(saveTimeSuppressedIDs)
                AtriaDebugLog("ATRIADBG sleep_auto_confirm status=save_time_dismissal_suppressed records=%d",
                              saveTimeSuppressedIDs.count)
                DetectionEventLog.append(DetectionEvent(
                    kind: "sleepCandidateSkipped",
                    reason: "save_time_dismissal_suppressed",
                    detail: "\(saveTimeSuppressedIDs.count) auto-confirmation(s) dropped at save time after a mid-flight dismissal"
                ))
            }
        }
        confirmedRecordWriteGeneration &+= 1
        let generation = confirmedRecordWriteGeneration
        let result = await Self.confirmedRecordWorker.performAsync(.sleeps(
            generation: generation,
            records: settledSleeps,
            defaultsKey: ConfirmedSleepDefaults.key
        ))
        guard case .sleeps(let completedGeneration, let sorted, _) = result,
              completedGeneration == generation else {
            let reason: String
            if case .failure(_, _, let failureReason) = result {
                reason = failureReason
            } else {
                reason = "generation_or_domain_mismatch"
            }
            AtriaDebugLog("ATRIADBG confirmed_sleep_store status=failed reason=%@",
                          reason)
            return false
        }

        // The writer owns the process-global confirmed-sleep file and may
        // finish after a lifecycle callback has already retired its recovered
        // transaction. Preserve an ordinary user/live write using the ticket
        // identity captured while this save held the gate. This logging must
        // precede the generation rejection below: rollback persistence waits
        // on the same gate and will rebase this exact delta over the pre-run
        // image after the stale writer releases it.
        if Self.confirmedSleepWriteMustRecordConcurrentAuthority(
            transactionOrRollbackWasActiveAtStart:
                transactionTicketAtStart != nil
                    || rollbackPersistenceWasActiveAtStart,
            transactionOrRollbackIsActiveAtCompletion:
                recoveredDataMutationTransaction.activeTicket != nil
                    || recoveredLifecycleRollbackPersistenceInFlight,
            recoveredOwnedMutation: recoveredOwnedMutationAtStart,
            completedGeneration: completedGeneration,
            requestedGeneration: generation,
            currentGeneration: confirmedRecordWriteGeneration
        ) {
            for id in preparation.concurrentDelta.deletedIDs {
                recoveredConcurrentConfirmedSleepUpserts.removeValue(
                    forKey: id
                )
                recoveredConcurrentConfirmedSleepDeletedIDs.insert(id)
            }
            for (id, sleep) in preparation.concurrentDelta.upserts
            where !saveTimeSuppressedIDs.contains(id) {
                recoveredConcurrentConfirmedSleepDeletedIDs.remove(id)
                recoveredConcurrentConfirmedSleepUpserts[id] = sleep
            }
        }
        guard generation == confirmedRecordWriteGeneration,
              executionShouldContinue() else {
            AtriaDebugLog(
                "ATRIADBG confirmed_sleep_store status=deferred reason=generation_or_execution_authority_mismatch"
            )
            return false
        }

        setCachedConfirmedSleeps(
            sorted,
            refreshDerivedCaches: !archiveFreeLatestNightSettlement
                && !deferDerivedPublication
        )
        if preparation.baselineInputsChanged
            && !archiveFreeLatestNightSettlement {
            // Confirmed main sleep is the only safe first baseline anchor when
            // no external resting reference exists. Rebuild when its actual
            // time/classification inputs changed, but never perform the much
            // heavier dashboard RR replay inside this persistence transaction.
            if deferDerivedPublication,
               let rebuiltBaseline = preparation.rebuiltBaseline {
                baseline = rebuiltBaseline
                if canonicalMutationAllowed { baseline.save() }
                cachedHomeDashboardDiagnostics = nil
            } else {
                rebuildBaselineFromEligibleSessions(
                    reason: "confirmed-sleep-window-change",
                    refreshDiagnosticsCache: false,
                    refreshDerivedCaches: true
                )
            }
        } else {
            cachedHomeDashboardDiagnostics = nil
            AtriaDebugLog("ATRIADBG baseline_rebuild status=skipped reason=confirmed_sleep_projection_only")
        }
        // User actions should update Activity/Overview immediately. The full
        // history rebuild still runs off-main below and restores candidates,
        // trends, and session-derived detail when ready.
        if !deferDerivedPublication {
            sleepHistorySnapshot = SleepHistorySnapshot(
                rollups: historySnapshot.rollups,
                confirmedSleeps: sorted,
                dismissedCandidates: dismissedSleepCandidates
            )
            _ = settleConfirmedMorningAuthority(
                reason: archiveFreeLatestNightSettlement
                    ? "compact_latest_night_sleep_save"
                    : "confirmed_sleep_save",
                now: Date(),
                preserveExistingSkinTemperature:
                    !archiveFreeLatestNightSettlement
            )
        }
        if !deferDerivedPublication
            && !archiveFreeLatestNightSettlement {
            refreshHistorySnapshotCache(deferred: true)
        }
        if preparation.stepReceiptCycleChanged {
            if deferDerivedPublication {
                currentCycleStepReceiptDeferredUntilForeground = true
            } else if archiveFreeLatestNightSettlement {
                // Compact settlement has just changed the physiological
                // boundary. Recompute the compact-only current-cycle receipt
                // now; deferring would leave Home on the prior sleep cycle
                // until an unrelated foreground or BLE event arrived.
                refreshCurrentCycleStrapStepReceipt(
                    reason: "compact_latest_night_sleep_cycle_changed"
                )
            } else {
                refreshCurrentCycleStrapStepReceipt(
                    reason: "confirmed_sleep_cycle_changed"
                )
            }
        }
        let commitPreparedEdges = { [weak self] in
            guard let self else { return }
            if let window = preparation.dutyCycleWindow {
                self.writeDutyCycleSleepWindow(window)
            }
            self.schedulePhysiologicalCycleRolloverCheck(
                at: preparation.nextRolloverBoundary,
                now: preparationNow,
                reason: "confirmed_sleep_change"
            )
        }
        if let transactionTicket = transactionTicketAtStart,
           recoveredDataMutationTransaction.activeTicket
                == transactionTicket {
            _ = recoveredDataMutationTransaction.registerCommit(
                ticket: transactionTicket,
                commitPreparedEdges
            )
        } else {
            commitPreparedEdges()
        }
        publishStressContextIfNeeded(
            deferDerivedPublication: deferDerivedPublication,
            publicationRequested: publishStressContext
        )
        return true
    }

    /// Learned sleep window for the capture duty cycle (docs/24 §13): median
    /// bedtime −1h to median wake +1h across recent overnight confirmed sleeps,
    /// written to the UserDefaults bridge the BLE manager reads.
    private func writeDutyCycleSleepWindow(from sleeps: [UserConfirmedSleep],
                                           calendar: Calendar = .current) {
        let overnights = sleeps
            .filter { !Self.confirmedSleepSourceIsNap(source: $0.source, duration: $0.duration) }
            .prefix(14)
        guard overnights.count >= 3 else { return }
        func minutesOfDay(_ date: Date) -> Int {
            let components = calendar.dateComponents([.hour, .minute], from: date)
            return (components.hour ?? 0) * 60 + (components.minute ?? 0)
        }
        // Shift starts by 12h so bedtimes around midnight sort contiguously.
        let startMinutes = overnights.map { (minutesOfDay($0.start) + 720) % 1440 }.sorted()
        let endMinutes = overnights.map { minutesOfDay($0.end) }.sorted()
        let medianStartShifted = startMinutes[startMinutes.count / 2]
        let medianStart = (medianStartShifted + 720) % 1440
        let medianEnd = endMinutes[endMinutes.count / 2]
        writeDutyCycleSleepWindow((
            start: (medianStart + 1440 - 60) % 1440,
            end: (medianEnd + 60) % 1440,
            count: overnights.count
        ))
    }

    /// Bounded commit edge for a sleep-window value prepared off-main.
    private func writeDutyCycleSleepWindow(
        _ window: (start: Int, end: Int, count: Int)
    ) {
        let defaults = UserDefaults.standard
        defaults.set(
            window.start,
            forKey: AtriaBLEManager.DutyCycleDefaults.sleepWindowStartMin
        )
        defaults.set(
            window.end,
            forKey: AtriaBLEManager.DutyCycleDefaults.sleepWindowEndMin
        )
        AtriaDebugLog("ATRIADBG duty_cycle sleep_window_start_min=%d sleep_window_end_min=%d source=confirmed_sleeps n=%d",
                      window.start,
                      window.end,
                      window.count)
    }

    nonisolated static func shouldRefreshUserAdjustedSleepEvidence(
        source: String,
        existingSamples: Int,
        candidateSamples: Int,
        existingDuration: TimeInterval,
        candidateCoverage: TimeInterval,
        hasTimeAlignedMotionEpochs: Bool = false,
        hasStoredStageSegments: Bool = true
    ) -> Bool {
        guard source.hasPrefix("user_adjusted_") else { return false }
        return hasTimeAlignedMotionEpochs
            || candidateSamples > existingSamples
            || candidateCoverage > existingDuration + 1
            // A stage-less record with real HR evidence stays refresh-eligible
            // even without sample growth: records saved before the HR-only
            // estimate lane existed (2026-08-12) have `stageSegments == nil`
            // that no growth trigger would ever revisit. The stager remains
            // fail-closed, so this converges the first time it can stage —
            // and no-change re-derivations return nil (never a save loop).
            || (!hasStoredStageSegments && candidateSamples >= 12)
    }

    private nonisolated static func recoveredDataExecutionDeadline(
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> AtriaSleepSettlementDeadline {
        AtriaSleepSettlementDeadline(
            uptimeNanoseconds: .max,
            monotonicNow: {
                shouldContinue() ? 0 : UInt64.max
            }
        )
    }

    private nonisolated static func refreshedUserAdjustedSleepEvidenceIfNeeded(
        _ sleep: UserConfirmedSleep,
        sourceSessions: [SavedSession],
        reason: String,
        cooperativeDeadline: AtriaSleepSettlementDeadline
    ) throws -> UserConfirmedSleep? {
        let sensorCovered = try Self.confirmedSleepSensorCoverage(
            from: sourceSessions,
            start: sleep.start,
            end: sleep.end,
            cooperativeDeadline: cooperativeDeadline
        )
        let candidateSamples = try Self.sleepStageResearchSampleCount(
            from: sourceSessions,
            start: sleep.start,
            end: sleep.end,
            cooperativeDeadline: cooperativeDeadline
        )
        let motionProvenance = try Self.recoveredMotionProvenance(
            for: sleep,
            sessions: sourceSessions,
            cooperativeDeadline: cooperativeDeadline
        )
        guard Self.shouldRefreshUserAdjustedSleepEvidence(source: sleep.source,
                                                          existingSamples: sleep.samples,
                                                          candidateSamples: candidateSamples,
                                                          existingDuration: sleep.duration,
                                                          candidateCoverage: sensorCovered,
                                                          hasTimeAlignedMotionEpochs:
                                                            motionProvenance.hasRecoveredEpochs,
                                                          hasStoredStageSegments:
                                                            sleep.stageSegments?.isEmpty == false) else {
            return nil
        }

        let metrics = try Self.confirmedSleepWindowMetrics(
            from: sourceSessions,
            start: sleep.start,
            end: sleep.end,
            rest: sleep.restingHR,
            cooperativeDeadline: cooperativeDeadline
        )
        let duration = min(sleep.span, sensorCovered)
        guard duration >= AggregateSleepCandidate.napMinimumDuration,
              metrics.samples >= 12 else {
            guard sleep.stageSegments?.isEmpty == false else { return nil }
            return Self.copyConfirmedSleep(
                sleep,
                stageSegments: nil,
                motionSource: motionProvenance.source,
                motionValidated: motionProvenance.lowMotionValidated
            )
        }
        let isNap = Self.confirmedSleepSourceIsNap(source: sleep.source,
                                                   duration: duration)
        let stages = try Self.sleepStageResearchSegments(
            from: sourceSessions,
            start: sleep.start,
            end: sleep.end,
            restingHR: metrics.restingHR,
            isNap: isNap,
            motionValidated: motionProvenance.lowMotionValidated,
            // Cooperative backfill lane: allowed to pay for HR-only
            // ESTIMATE staging so stage-less records converge (2026-08-12).
            allowHROnlyEstimate: true,
            maximumRows: Int.max,
            cooperativeDeadline: cooperativeDeadline
        )
        let motionSource = motionProvenance.hasRecoveredEpochs
            ? motionProvenance.source
            : sleep.motionSource
        let motionValidated = motionProvenance.hasRecoveredEpochs
            ? motionProvenance.lowMotionValidated
            : sleep.motionValidated
        let refreshed = UserConfirmedSleep(id: sleep.id,
                                           createdAt: sleep.createdAt,
                                           start: sleep.start,
                                           end: sleep.end,
                                           source: sleep.source,
                                           confidence: sleep.confidence,
                                           sessions: metrics.sessions,
                                           samples: metrics.samples,
                                           avgHR: metrics.avgHR,
                                           peakHR: metrics.peakHR,
                                           restingHR: metrics.restingHR,
                                           hrv: metrics.hrv,
                                           hrvWindowCount: metrics.hrvWindowCount,
                                           respiratoryRate: try Self
                                            .confirmedSleepRespiratoryRate(
                                                from: sourceSessions,
                                                start: sleep.start,
                                                end: sleep.end,
                                                cooperativeDeadline:
                                                    cooperativeDeadline
                                            ),
                                           duration: duration,
                                           span: sleep.span,
                                           reason: sleep.reason,
                                           motionSource: motionSource,
                                           motionValidated: motionValidated,
                                           stageSegments: stages.isEmpty ? nil : stages,
                                           eventTimeZoneIdentifier: sleep.eventTimeZoneIdentifier,
                                           sleepNeedSeconds: sleep.sleepNeedSeconds,
                                           frozenSleepNeed: sleep.frozenSleepNeed,
                                           // Evidence refresh rewrites the same
                                           // record id; dropping the user's
                                           // "which is your main sleep?" answer
                                           // here would silently re-prompt the
                                           // day and re-anchor its cycle.
                                           dayPrimaryChoice: sleep.dayPrimaryChoice)
        // Never invent REM/deep/light from aggregate HR or clock position. A
        // recovered sleep keeps stages only when timestamped HR/motion evidence
        // produced a complete, integrity-valid segmentation.
        let final = !stages.isEmpty && AtriaSleepStageIntegrity.validates(stages, for: refreshed)
            ? refreshed
            : Self.copyConfirmedSleep(refreshed, stageSegments: nil)
        try cooperativeDeadline.checkpoint()
        guard final != sleep else { return nil }
        AtriaDebugLog("ATRIADBG sleep_adjust_evidence_refresh status=updated source=%@ sleep_source=%@ old_samples=%d new_samples=%d old_duration_s=%.0f new_duration_s=%.0f stages=%d bounds_preserved=1",
                      reason,
                      sleep.source,
                      sleep.samples,
                      final.samples,
                      sleep.duration,
                      final.duration,
                      final.stageSegments?.count ?? 0)
        return final
    }

    @discardableResult
    private func backfillConfirmedSleepStagesFromSessions(
        reason: String,
        deferDerivedPublication: Bool = false,
        narrowPublicationAfterCommit: Bool = false,
        affectedSince: Date? = nil,
        preparedSourceSessions: [SavedSession]? = nil,
        executionShouldContinue:
            @escaping @Sendable () -> Bool = { true }
    ) async -> ConfirmedSleepStageBackfillOutcome {
        let sourceSessions = preparedSourceSessions
            ?? canonicalSessions(includeActiveJournal: true).filter {
                session in
                affectedSince.map { session.end > $0 } ?? true
            }
        let sourceSleeps = cachedConfirmedSleeps
        guard executionShouldContinue(),
              !sourceSessions.isEmpty,
              !sourceSleeps.isEmpty else {
            return ConfirmedSleepStageBackfillOutcome(
                changed: false,
                succeeded: executionShouldContinue(),
                affectedSleepIDs: [],
                committedConfirmedSleepsRevision: nil
            )
        }
        let preparation: (updated: [UserConfirmedSleep], repaired: Int,
                          totalSegments: Int,
                          affectedSleepIDs: [String])? = await withCheckedContinuation {
            continuation in
            DispatchQueue.global(qos: .utility).async {
                let prepared = AtriaTransientWorkThread.run(
                    name: "atria.recovered-sleep-stage-prepare",
                    qualityOfService: .utility
                ) { () -> (updated: [UserConfirmedSleep], repaired: Int,
                           totalSegments: Int,
                           affectedSleepIDs: [String])? in
                    let deadline = Self.recoveredDataExecutionDeadline(
                        shouldContinue: executionShouldContinue
                    )
                    do {
                        try deadline.checkpoint()
                        var repaired = 0
                        var updated: [UserConfirmedSleep] = []
                        updated.reserveCapacity(sourceSleeps.count)
                        for (sleepIndex, sleep) in sourceSleeps.enumerated() {
                            if sleepIndex.isMultiple(of: 8) {
                                try deadline.checkpoint()
                            }
                            if let affectedSince,
                               sleep.end <= affectedSince {
                                updated.append(sleep)
                                continue
                            }
                            var hasRecoveredEpochOverlap = false
                            epochSearch: for (sessionIndex, session) in
                                sourceSessions.enumerated() {
                                if sessionIndex.isMultiple(of: 16) {
                                    try deadline.checkpoint()
                                }
                                for (epochIndex, epoch) in
                                    (session.recoveredMotionEpochs ?? [])
                                        .enumerated() {
                                    if epochIndex.isMultiple(of: 256) {
                                        try deadline.checkpoint()
                                    }
                                    if epoch.end > sleep.start,
                                       epoch.start < sleep.end {
                                        hasRecoveredEpochOverlap = true
                                        break epochSearch
                                    }
                                }
                            }
                            if let refreshed = try Self
                                .refreshedUserAdjustedSleepEvidenceIfNeeded(
                                    sleep,
                                    sourceSessions: sourceSessions,
                                    reason: reason,
                                    cooperativeDeadline: deadline
                                ) {
                                repaired += 1
                                updated.append(refreshed)
                                continue
                            }
                            if Self.fragmentedAggregateHRStagesAreUnsupported(
                                sleep
                            ) {
                                repaired += 1
                                updated.append(Self.copyConfirmedSleep(
                                    sleep,
                                    stageSegments: nil
                                ))
                                continue
                            }
                            if sleep.source.hasPrefix("user_adjusted_") {
                                if !hasRecoveredEpochOverlap,
                                   sleep.stageSegments?.isEmpty == false,
                                   // HR-only ESTIMATE segments are backed by
                                   // dense HR, not motion epochs — the epoch
                                   // hygiene strip must not erase them.
                                   !SleepStageSegment.allHREstimateProvenance(
                                    sleep.stageSegments
                                   ) {
                                    repaired += 1
                                    updated.append(Self.copyConfirmedSleep(
                                        sleep,
                                        stageSegments: nil
                                    ))
                                } else {
                                    updated.append(sleep)
                                }
                                continue
                            }
                            if sleep.source.hasPrefix("manual_")
                                || (!hasRecoveredEpochOverlap
                                    && Self
                                        .shouldPreserveConfirmedSleepStageSegments(
                                            sleep
                                        )) {
                                updated.append(sleep)
                                continue
                            }
                            let sampleCount = try Self
                                .sleepStageResearchSampleCount(
                                    from: sourceSessions,
                                    start: sleep.start,
                                    end: sleep.end,
                                    cooperativeDeadline: deadline
                                )
                            let provenance = try Self
                                .recoveredMotionProvenance(
                                    for: sleep,
                                    sessions: sourceSessions,
                                    cooperativeDeadline: deadline
                                )
                            let stages = try Self.sleepStageResearchSegments(
                                from: sourceSessions,
                                start: sleep.start,
                                end: sleep.end,
                                restingHR: sleep.restingHR,
                                isNap: Self.confirmedSleepSourceIsNap(
                                    source: sleep.source,
                                    duration: sleep.duration
                                ),
                                motionValidated:
                                    provenance.lowMotionValidated,
                                // Cooperative backfill lane (2026-08-12):
                                // may pay for HR-only ESTIMATE staging.
                                allowHROnlyEstimate: true,
                                maximumRows: Int.max,
                                cooperativeDeadline: deadline
                            )
                            guard Self.confirmedSleepStagesCoverSleep(
                                stages,
                                sleep: sleep
                            ) else {
                                if sleep.stageSegments?.isEmpty == false {
                                    repaired += 1
                                    updated.append(Self.copyConfirmedSleep(
                                        sleep,
                                        stageSegments: nil
                                    ))
                                } else {
                                    updated.append(sleep)
                                }
                                continue
                            }
                            let regenerated = Self.copyConfirmedSleep(
                                sleep,
                                stageSegments: stages,
                                motionSource: provenance.source,
                                motionValidated:
                                    provenance.lowMotionValidated
                            )
                            if regenerated.stageSegments != sleep.stageSegments {
                                repaired += 1
                                AtriaDebugLog(
                                    "ATRIADBG sleep_stage_backfill_record status=updated source=%@ sleep_source=%@ samples=%d segments=%d sleep_s=%.0f",
                                    reason,
                                    sleep.source,
                                    sampleCount,
                                    stages.count,
                                    sleep.duration
                                )
                                updated.append(regenerated)
                            } else {
                                updated.append(sleep)
                            }
                        }
                        try deadline.checkpoint()
                        var totalSegments = 0
                        // `updated` is strictly parallel to `sourceSleeps` —
                        // every branch above appends exactly one record per
                        // input — so the affected set is a pairwise diff.
                        var affectedSleepIDs: [String] = []
                        for (index, sleep) in updated.enumerated() {
                            if index.isMultiple(of: 32) {
                                try deadline.checkpoint()
                            }
                            totalSegments += sleep.stageSegments?.count ?? 0
                            if sleep != sourceSleeps[index] {
                                affectedSleepIDs.append(sleep.id)
                            }
                        }
                        try deadline.checkpoint()
                        return (updated, repaired, totalSegments, affectedSleepIDs)
                    } catch {
                        return nil
                    }
                }
                continuation.resume(returning: prepared)
            }
        }
        guard let preparation, executionShouldContinue() else {
            return ConfirmedSleepStageBackfillOutcome(
                changed: false,
                succeeded: false,
                affectedSleepIDs: [],
                committedConfirmedSleepsRevision: nil
            )
        }
        guard preparation.repaired > 0 else {
            return ConfirmedSleepStageBackfillOutcome(
                changed: false,
                succeeded: true,
                affectedSleepIDs: [],
                committedConfirmedSleepsRevision: nil
            )
        }
        let saved = await saveConfirmedSleeps(
            preparation.updated,
            deferDerivedPublication: deferDerivedPublication,
            recoveredMutationBase: deferDerivedPublication
                ? sourceSleeps : nil,
            executionShouldContinue: executionShouldContinue
        )
        guard saved, executionShouldContinue() else {
            return ConfirmedSleepStageBackfillOutcome(
                changed: false,
                succeeded: false,
                affectedSleepIDs: [],
                committedConfirmedSleepsRevision: nil
            )
        }
        AtriaDebugLog("ATRIADBG sleep_stage_backfill status=updated source=%@ records=%d total_segments=%d policy=hr_samples_labeled_estimate",
                      reason,
                      preparation.repaired,
                      preparation.totalSegments)
        // The launch follow-up defers per-save publication (this backfill is
        // off the first-frame path), but the user must not need a relaunch to
        // see stages the save just committed. Republish narrowly, exactly
        // once, from post-commit truth — synchronously on the actor, so a
        // newer user edit can only land after (and republish over) us.
        if narrowPublicationAfterCommit {
            publishDeferredConfirmedSleepStageBackfill(reason: reason)
        }
        return ConfirmedSleepStageBackfillOutcome(
            changed: true,
            succeeded: true,
            affectedSleepIDs: preparation.affectedSleepIDs,
            committedConfirmedSleepsRevision: confirmedSleepsRevision
        )
    }

    /// One narrow, current-generation derived publication after a deferred
    /// stage-backfill commit. Rebuilds the compact sleep snapshot from the
    /// CURRENT confirmed-sleep cache (never the backfill's stale input array),
    /// so any user edit that raced the off-main stage build wins by
    /// construction. The heavy full-history rebuild stays off-main behind
    /// `refreshHistorySnapshotCache`'s own revision fences. This method never
    /// touches archive recovery, BLE history, or a synchronous dashboard
    /// rebuild.
    private func publishDeferredConfirmedSleepStageBackfill(reason: String) {
        guard canonicalMutationAllowed else {
            AtriaDebugLog("ATRIADBG sleep_stage_backfill_publication status=skipped reason=%@ guard=restore_in_progress",
                          reason)
            return
        }
        // A live recovered-data transaction that has already journaled a
        // canonical mutation owns its own terminal publication edge;
        // publishing under it could expose a mid-transaction image. An
        // admitted-but-unmutated transaction has no intermediate image to
        // expose, and the launch projection's admission is timing-driven:
        // treating bare admission as a publication fence silently swallowed
        // committed stages until relaunch whenever the projection happened to
        // be in flight (2026-08-20). When a prepared mutation does exist, the
        // publication is parked and flushed at the transaction's terminal
        // edges — commit and rollback — so it can only be delayed, never lost.
        if recoveredDataMutationTransaction.activeTicket != nil {
            guard recoveredDataMutationTransaction.rollbackOperationCount == 0 else {
                pendingDeferredStageBackfillPublicationReason = reason
                AtriaDebugLog("ATRIADBG sleep_stage_backfill_publication status=deferred_until_recovered_terminal reason=%@ guard=recovered_transaction_mutated",
                              reason)
                return
            }
        }
        sleepHistorySnapshot = SleepHistorySnapshot(
            rollups: historySnapshot.rollups,
            confirmedSleeps: cachedConfirmedSleeps,
            dismissedCandidates: dismissedSleepCandidates
        )
        invalidateSleepReviewCache(
            reason: "sleep_stage_backfill_publication",
            scheduleRefresh: true
        )
        refreshHistorySnapshotCache(deferred: true)
        AtriaDebugLog("ATRIADBG sleep_stage_backfill_publication status=published reason=%@",
                      reason)
    }

    /// A narrow stage-backfill publication that arrived while a recovered-data
    /// transaction held a prepared mutation. Flushed at BOTH terminal edges
    /// (commit and rollback) so an in-flight projection can only delay the
    /// committed stages, never swallow them — the swallow is exactly the
    /// recovery-state defect class this codebase keeps refinding: state
    /// cleared only by an edge that may never run.
    private var pendingDeferredStageBackfillPublicationReason: String?

    private func flushPendingDeferredStageBackfillPublicationAfterRecoveredTerminal() {
        guard let reason = pendingDeferredStageBackfillPublicationReason else {
            return
        }
        pendingDeferredStageBackfillPublicationReason = nil
        publishDeferredConfirmedSleepStageBackfill(
            reason: reason + "_after_recovered_terminal"
        )
    }

    nonisolated static func recoveredMotionProvenance(
        for sleep: UserConfirmedSleep,
        sessions: [SavedSession]
    ) -> AtriaRecoveredMotionAnalytics.SleepProvenance {
        AtriaRecoveredMotionAnalytics.sleepProvenance(
            epochs: sessions.flatMap { $0.recoveredMotionEpochs ?? [] },
            start: sleep.start,
            end: sleep.end
        )
    }

    private nonisolated static func recoveredMotionProvenance(
        for sleep: UserConfirmedSleep,
        sessions: [SavedSession],
        cooperativeDeadline: AtriaSleepSettlementDeadline
    ) throws -> AtriaRecoveredMotionAnalytics.SleepProvenance {
        try cooperativeDeadline.checkpoint()
        var epochs: [AtriaRecoveredMotionEpoch] = []
        for (sessionIndex, session) in sessions.enumerated() {
            if sessionIndex.isMultiple(of: 16) {
                try cooperativeDeadline.checkpoint()
            }
            for (epochIndex, epoch) in
                (session.recoveredMotionEpochs ?? []).enumerated() {
                if epochIndex.isMultiple(of: 256) {
                    try cooperativeDeadline.checkpoint()
                }
                epochs.append(epoch)
            }
        }
        return try AtriaRecoveredMotionAnalytics.sleepProvenance(
            epochs: epochs,
            start: sleep.start,
            end: sleep.end,
            cooperativeDeadline: cooperativeDeadline
        )
    }

    /// Rebuilds sensor provenance before stage backfill. Any recovered epoch
    /// gap or active-motion interval removes the old whole-window low-motion
    /// claim. The following backfill pass always regenerates stages for an
    /// overlapping recovered epoch set, even when these aggregate fields did
    /// not change, so changed epoch timing cannot leave stale stages behind.
    private func rebuildConfirmedSleepRecoveredMotionProvenance(
        reason: String,
        deferDerivedPublication: Bool,
        affectedSince: Date? = nil,
        preparedSourceSessions: [SavedSession]? = nil,
        executionShouldContinue:
            @escaping @Sendable () -> Bool = { true }
    ) async -> Bool {
        let sourceSessions = preparedSourceSessions
            ?? canonicalSessions(includeActiveJournal: true).filter {
                session in
                affectedSince.map { session.end > $0 } ?? true
            }
        let sourceSleeps = cachedConfirmedSleeps
        guard executionShouldContinue() else { return false }
        let preparation: (updated: [UserConfirmedSleep], changed: Int)? =
            await withCheckedContinuation { continuation in
                DispatchQueue.global(qos: .utility).async {
                    let prepared = AtriaTransientWorkThread.run(
                        name: "atria.recovered-sleep-motion-prepare",
                        qualityOfService: .utility
                    ) { () -> (updated: [UserConfirmedSleep], changed: Int)? in
                        let deadline = Self.recoveredDataExecutionDeadline(
                            shouldContinue: executionShouldContinue
                        )
                        do {
                            var changed = 0
                            var updated: [UserConfirmedSleep] = []
                            updated.reserveCapacity(sourceSleeps.count)
                            for (index, sleep) in sourceSleeps.enumerated() {
                                if index.isMultiple(of: 8) {
                                    try deadline.checkpoint()
                                }
                                if let affectedSince,
                                   sleep.end <= affectedSince {
                                    updated.append(sleep)
                                    continue
                                }
                                let provenance = try Self
                                    .recoveredMotionProvenance(
                                        for: sleep,
                                        sessions: sourceSessions,
                                        cooperativeDeadline: deadline
                                    )
                                let motionSource = provenance.source
                                let motionValidated =
                                    provenance.lowMotionValidated
                                guard provenance.hasRecoveredEpochs,
                                      sleep.motionSource != motionSource
                                        || sleep.motionValidated
                                            != motionValidated
                                        || sleep.stageSegments?.isEmpty
                                            == false else {
                                    updated.append(sleep)
                                    continue
                                }
                                changed += 1
                                updated.append(UserConfirmedSleep(
                                    id: sleep.id,
                                    createdAt: sleep.createdAt,
                                    start: sleep.start,
                                    end: sleep.end,
                                    source: sleep.source,
                                    confidence: sleep.confidence,
                                    sessions: sleep.sessions,
                                    samples: sleep.samples,
                                    avgHR: sleep.avgHR,
                                    peakHR: sleep.peakHR,
                                    restingHR: sleep.restingHR,
                                    hrv: sleep.hrv,
                                    hrvWindowCount: sleep.hrvWindowCount,
                                    respiratoryRate: sleep.respiratoryRate,
                                    duration: sleep.duration,
                                    span: sleep.span,
                                    reason: sleep.reason,
                                    motionSource: motionSource,
                                    motionValidated: motionValidated,
                                    stageSegments: nil,
                                    eventTimeZoneIdentifier:
                                        sleep.eventTimeZoneIdentifier,
                                    sleepNeedSeconds: sleep.sleepNeedSeconds,
                                    frozenSleepNeed: sleep.frozenSleepNeed
                                ))
                            }
                            try deadline.checkpoint()
                            return (updated, changed)
                        } catch {
                            return nil
                        }
                    }
                    continuation.resume(returning: prepared)
                }
            }
        guard let preparation, executionShouldContinue() else { return false }
        guard preparation.changed > 0 else { return true }
        guard await saveConfirmedSleeps(
            preparation.updated,
            deferDerivedPublication: deferDerivedPublication,
            recoveredMutationBase: deferDerivedPublication
                ? sourceSleeps : nil,
            executionShouldContinue: executionShouldContinue
        ), executionShouldContinue() else {
            AtriaDebugLog("ATRIADBG recovered_sleep_motion status=store_failed reason=%@ records=%d",
                          reason,
                          preparation.changed)
            return false
        }
        AtriaDebugLog("ATRIADBG recovered_sleep_motion status=updated reason=%@ records=%d policy=time_aligned_epochs",
                      reason,
                      preparation.changed)
        return true
    }

    nonisolated private static func confirmedSleepStagesCoverSleep(
        _ stages: [SleepStageSegment],
        sleep: UserConfirmedSleep
    ) -> Bool {
        AtriaSleepStageIntegrity.validates(stages, for: sleep)
    }

    func behaviorJournalEntry(for day: Date = Date(), calendar: Calendar = .current) -> BehaviorJournalEntry {
        let start = calendar.startOfDay(for: day)
        if let entry = cachedBehaviorJournalEntries.first(where: { calendar.isDate($0.day, inSameDayAs: start) }) {
            return entry
        }
        return BehaviorJournalEntry(id: behaviorJournalID(for: start),
                                    day: start,
                                    createdAt: Date(),
                                    tags: [])
    }

    func toggleBehaviorTag(_ tag: BehaviorJournalEntry.Tag, day: Date = Date(), calendar: Calendar = .current) {
        var entry = behaviorJournalEntry(for: day, calendar: calendar)
        if entry.tags.contains(tag) {
            entry.tags.removeAll { $0 == tag }
            if entry.healthAutoTags.contains(tag) {
                entry.healthAutoTags.removeAll { $0 == tag }
                rememberRemovedNutritionAutoTag(tag, day: entry.day, calendar: calendar)
            }
        } else {
            entry.tags.append(tag)
            entry.healthAutoTags.removeAll { $0 == tag }
            forgetRemovedNutritionAutoTag(tag, day: entry.day, calendar: calendar)
        }
        entry.tags.sort { $0.rawValue < $1.rawValue }
        entry.healthAutoTags.sort { $0.rawValue < $1.rawValue }

        var entries = cachedBehaviorJournalEntries.filter { !calendar.isDate($0.day, inSameDayAs: entry.day) }
        if !entry.tags.isEmpty {
            entries.append(entry)
        }
        saveBehaviorJournalEntries(entries)
        dashboardRevision += 1
        AtriaDebugLog("ATRIADBG behavior_journal status=updated day=%@ tag=%@ active=%d tags=%@ local_only=1",
              isoString(entry.day),
              tag.rawValue,
              entry.tags.contains(tag) ? 1 : 0,
              entry.tags.map(\.rawValue).joined(separator: ","))
    }

    private func applyNutritionAutoTags(_ tags: Set<BehaviorJournalEntry.Tag>,
                                        day: Date,
                                        calendar: Calendar = .current) {
        guard !tags.isEmpty else { return }
        var entry = behaviorJournalEntry(for: day, calendar: calendar)
        let removed = removedNutritionAutoTags(for: entry.day, calendar: calendar)
        var changed = false
        for tag in tags where !removed.contains(tag) {
            if !entry.tags.contains(tag) {
                entry.tags.append(tag)
                changed = true
            }
            if !entry.healthAutoTags.contains(tag) {
                entry.healthAutoTags.append(tag)
                changed = true
            }
        }
        guard changed else { return }
        entry.tags.sort { $0.rawValue < $1.rawValue }
        entry.healthAutoTags.sort { $0.rawValue < $1.rawValue }
        var entries = cachedBehaviorJournalEntries.filter { !calendar.isDate($0.day, inSameDayAs: entry.day) }
        entries.append(entry)
        saveBehaviorJournalEntries(entries)
        dashboardRevision += 1
        AtriaDebugLog("ATRIADBG behavior_journal_auto_tags status=applied source=health day=%@ tags=%@ removed=%@",
                      isoString(entry.day),
                      entry.healthAutoTags.map(\.rawValue).joined(separator: ","),
                      removed.map(\.rawValue).sorted().joined(separator: ","))
    }

    private func removedNutritionAutoTags(for day: Date,
                                          calendar: Calendar = .current) -> Set<BehaviorJournalEntry.Tag> {
        let key = Self.localDayIdentifier(for: day, calendar: calendar)
        let raw = UserDefaults.standard.dictionary(forKey: BehaviorJournalDefaults.autoTagRemovalsKey) as? [String: [String]] ?? [:]
        return Set((raw[key] ?? []).compactMap(BehaviorJournalEntry.Tag.init(rawValue:)))
    }

    private func rememberRemovedNutritionAutoTag(_ tag: BehaviorJournalEntry.Tag,
                                                 day: Date,
                                                 calendar: Calendar = .current) {
        updateRemovedNutritionAutoTags(day: day, calendar: calendar) { tags in
            tags.insert(tag)
        }
    }

    private func forgetRemovedNutritionAutoTag(_ tag: BehaviorJournalEntry.Tag,
                                               day: Date,
                                               calendar: Calendar = .current) {
        updateRemovedNutritionAutoTags(day: day, calendar: calendar) { tags in
            tags.remove(tag)
        }
    }

    private func updateRemovedNutritionAutoTags(day: Date,
                                                calendar: Calendar = .current,
                                                mutate: (inout Set<BehaviorJournalEntry.Tag>) -> Void) {
        let key = Self.localDayIdentifier(for: day, calendar: calendar)
        var raw = UserDefaults.standard.dictionary(forKey: BehaviorJournalDefaults.autoTagRemovalsKey) as? [String: [String]] ?? [:]
        var tags = Set((raw[key] ?? []).compactMap(BehaviorJournalEntry.Tag.init(rawValue:)))
        mutate(&tags)
        if tags.isEmpty {
            raw.removeValue(forKey: key)
        } else {
            raw[key] = tags.map(\.rawValue).sorted()
        }
        UserDefaults.standard.set(raw, forKey: BehaviorJournalDefaults.autoTagRemovalsKey)
    }

    private struct InsightDayMetrics { let recovery: Double?; let hrv: Double?; let rhr: Double? }

    func behaviorCorrelationSummaries(rest: Int,
                                      maxHR: Int,
                                      calendar: Calendar = .current) -> [BehaviorCorrelationSummary] {
        Self.sortedBehaviorCorrelationSummaries(
            Self.makeBehaviorCorrelationSummaries(sessions: canonicalSessions(),
                                                  journalEntries: cachedBehaviorJournalEntries,
                                                  rest: rest,
                                                  maxHR: maxHR,
                                                  dailyVitals: dailyMetricHistory.map {
                                                      (day: $0.day, restingHR: $0.restingHR)
                                                  },
                                                  calendar: calendar)
        )
    }

    private nonisolated static func makeBehaviorCorrelationSummaries(sessions: [SavedSession],
                                                                     journalEntries: [BehaviorJournalEntry],
                                                                     rest: Int,
                                                                     maxHR: Int,
                                                                     dailyVitals: [(day: Date, restingHR: Int?)] = [],
                                                                     calendar: Calendar = .current) -> [BehaviorCorrelationSummary] {
        // LIGHT per-day rollup: only externally validated recovery + avg HRV. This
        // deliberately does NOT call dailyRollups(), which runs workout/sleep
        // clustering + detectedActivity twice per session and was blocking the
        // main thread (SessionStore is @MainActor) — the cause of the launch /
        // workout hang + watchdog crash. Insights never needed that detection.
        // Recovery correlations stay fail-closed until they can use real
        // baseline-gated Recovery inputs; strain-derived recovery proxies would
        // violate the honest-metrics tiering in docs/21.
        let referenceDate = (sessions.map(\.start) + journalEntries.map(\.day)).max() ?? Date()
        let windowStart = calendar.date(byAdding: .day,
                                        value: -behaviorCorrelationWindowDays,
                                        to: calendar.startOfDay(for: referenceDate))
            ?? referenceDate.addingTimeInterval(TimeInterval(-behaviorCorrelationWindowDays * 24 * 60 * 60))
        let recentSessions = sessions.filter { $0.start >= windowStart }
        let recentJournalEntries = journalEntries.filter { $0.day >= windowStart }
        let grouped = Dictionary(grouping: recentSessions) { session in
            EventCivilTime.day(containing: session.start,
                               eventTimeZoneIdentifier: session.eventTimeZoneIdentifier,
                               outputCalendar: calendar)
        }
        guard !grouped.isEmpty else {
            return BehaviorJournalEntry.Tag.allCases.map {
                BehaviorCorrelationSummary(tag: $0, days: 0, recoveryDelta: nil, hrvDelta: nil, rhrDelta: nil)
            }
        }
        // Assessment P1.9: RHR comes from the frozen daily metrics — a
        // measured signal that survives Recovery model bumps.
        var rhrByDay: [Date: Double] = [:]
        for vital in dailyVitals where vital.day >= windowStart {
            if let restingHR = vital.restingHR, restingHR > 0 {
                rhrByDay[calendar.startOfDay(for: vital.day)] = Double(restingHR)
            }
        }
        let metricsByDay: [Date: InsightDayMetrics] = grouped.reduce(into: [:]) { result, pair in
            let hrvs = pair.value.compactMap(\.localRMSSD).filter { $0 > 0 }
            let hrv = hrvs.isEmpty ? nil : Double(hrvs.reduce(0, +)) / Double(hrvs.count)
            result[pair.key] = InsightDayMetrics(recovery: nil,
                                                 hrv: hrv,
                                                 rhr: rhrByDay[calendar.startOfDay(for: pair.key)])
        }

        return BehaviorJournalEntry.Tag.allCases.map { tag in
            // Genuine tagged-vs-UNtagged contrast: the baseline excludes the tag's
            // own days, otherwise the delta is diluted by the days being measured.
            let taggedDayKeys = Set(recentJournalEntries
                .filter { $0.tags.contains(tag) }
                .map { calendar.startOfDay(for: $0.day) })
            let tagged = metricsByDay.filter { taggedDayKeys.contains($0.key) }.map(\.value)
            let untagged = metricsByDay.filter { !taggedDayKeys.contains($0.key) }.map(\.value)

            let taggedRecovery = averageDoubleSnapshot(tagged.compactMap(\.recovery))
            let untaggedRecovery = averageDoubleSnapshot(untagged.compactMap(\.recovery))
            let taggedHRV = averageDoubleSnapshot(tagged.compactMap(\.hrv))
            let untaggedHRV = averageDoubleSnapshot(untagged.compactMap(\.hrv))

            let recoveryDelta: Double?
            if tagged.count >= 3, let taggedRecovery, let untaggedRecovery {
                recoveryDelta = taggedRecovery - untaggedRecovery
            } else {
                recoveryDelta = nil
            }
            let hrvDelta: Double?
            if tagged.count >= 3, let taggedHRV, let untaggedHRV {
                hrvDelta = taggedHRV - untaggedHRV
            } else {
                hrvDelta = nil
            }
            let taggedRHR = averageDoubleSnapshot(tagged.compactMap(\.rhr))
            let untaggedRHR = averageDoubleSnapshot(untagged.compactMap(\.rhr))
            let rhrDelta: Double?
            if tagged.count >= 3, let taggedRHR, let untaggedRHR {
                rhrDelta = taggedRHR - untaggedRHR
            } else {
                rhrDelta = nil
            }
            return BehaviorCorrelationSummary(tag: tag,
                                              days: tagged.count,
                                              recoveryDelta: recoveryDelta,
                                              hrvDelta: hrvDelta,
                                              rhrDelta: rhrDelta)
        }
    }

    nonisolated static func makeBehaviorCorrelationSummariesCancellable(
        sessions: [SavedSession],
        journalEntries: [BehaviorJournalEntry],
        rest: Int,
        maxHR: Int,
        dailyVitals: [(day: Date, restingHR: Int?)] = [],
        calendar: Calendar = .current,
        shouldContinue: () -> Bool
    ) -> [BehaviorCorrelationSummary]? {
        guard shouldContinue() else { return nil }
        var referenceDate = Date.distantPast
        for (index, session) in sessions.enumerated() {
            if index.isMultiple(of: 64), !shouldContinue() { return nil }
            referenceDate = max(referenceDate, session.start)
        }
        for (index, entry) in journalEntries.enumerated() {
            if index.isMultiple(of: 64), !shouldContinue() { return nil }
            referenceDate = max(referenceDate, entry.day)
        }
        if referenceDate == .distantPast { referenceDate = Date() }
        let windowStart = calendar.date(
            byAdding: .day,
            value: -behaviorCorrelationWindowDays,
            to: calendar.startOfDay(for: referenceDate)
        ) ?? referenceDate.addingTimeInterval(
            TimeInterval(-behaviorCorrelationWindowDays * 86_400)
        )
        var grouped: [Date: [SavedSession]] = [:]
        for (index, session) in sessions.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            guard session.start >= windowStart else { continue }
            let day = EventCivilTime.day(
                containing: session.start,
                eventTimeZoneIdentifier: session.eventTimeZoneIdentifier,
                outputCalendar: calendar
            )
            grouped[day, default: []].append(session)
        }
        var recentJournalEntries: [BehaviorJournalEntry] = []
        for (index, entry) in journalEntries.enumerated() {
            if index.isMultiple(of: 64), !shouldContinue() { return nil }
            if entry.day >= windowStart { recentJournalEntries.append(entry) }
        }
        guard !grouped.isEmpty else {
            return shouldContinue()
                ? BehaviorJournalEntry.Tag.allCases.map {
                    BehaviorCorrelationSummary(
                        tag: $0,
                        days: 0,
                        recoveryDelta: nil,
                        hrvDelta: nil,
                        rhrDelta: nil
                    )
                }
                : nil
        }
        // Assessment P1.9: RHR comes from the frozen daily metrics — a
        // measured signal that survives Recovery model bumps.
        var rhrByDay: [Date: Double] = [:]
        for (index, vital) in dailyVitals.enumerated() {
            if index.isMultiple(of: 64), !shouldContinue() { return nil }
            guard vital.day >= windowStart,
                  let restingHR = vital.restingHR,
                  restingHR > 0 else { continue }
            rhrByDay[calendar.startOfDay(for: vital.day)] = Double(restingHR)
        }
        var metricsByDay: [Date: InsightDayMetrics] = [:]
        for (day, daySessions) in grouped {
            guard shouldContinue() else { return nil }
            var sum = 0.0
            var count = 0
            for (index, session) in daySessions.enumerated() {
                if index.isMultiple(of: 8), !shouldContinue() { return nil }
                if let value = session.localRMSSD, value > 0 {
                    sum += Double(value)
                    count += 1
                }
                guard shouldContinue() else { return nil }
            }
            metricsByDay[day] = .init(
                recovery: nil,
                hrv: count > 0 ? sum / Double(count) : nil,
                rhr: rhrByDay[calendar.startOfDay(for: day)]
            )
        }
        var result: [BehaviorCorrelationSummary] = []
        for tag in BehaviorJournalEntry.Tag.allCases {
            guard shouldContinue() else { return nil }
            var taggedDayKeys = Set<Date>()
            for (index, entry) in recentJournalEntries.enumerated() {
                if index.isMultiple(of: 64), !shouldContinue() { return nil }
                if entry.tags.contains(tag) {
                    taggedDayKeys.insert(calendar.startOfDay(for: entry.day))
                }
            }
            var tagged: [InsightDayMetrics] = []
            var untagged: [InsightDayMetrics] = []
            for (index, pair) in metricsByDay.enumerated() {
                if index.isMultiple(of: 64), !shouldContinue() { return nil }
                if taggedDayKeys.contains(pair.key) {
                    tagged.append(pair.value)
                } else {
                    untagged.append(pair.value)
                }
            }
            let taggedRecovery = averageDoubleSnapshot(
                tagged.compactMap(\.recovery)
            )
            let untaggedRecovery = averageDoubleSnapshot(
                untagged.compactMap(\.recovery)
            )
            let taggedHRV = averageDoubleSnapshot(tagged.compactMap(\.hrv))
            let untaggedHRV = averageDoubleSnapshot(untagged.compactMap(\.hrv))
            let taggedRHR = averageDoubleSnapshot(tagged.compactMap(\.rhr))
            let untaggedRHR = averageDoubleSnapshot(untagged.compactMap(\.rhr))
            result.append(.init(
                tag: tag,
                days: tagged.count,
                recoveryDelta: tagged.count >= 3
                    ? taggedRecovery.flatMap { taggedValue in
                        untaggedRecovery.map { taggedValue - $0 }
                    } : nil,
                hrvDelta: tagged.count >= 3
                    ? taggedHRV.flatMap { taggedValue in
                        untaggedHRV.map { taggedValue - $0 }
                    } : nil,
                rhrDelta: tagged.count >= 3
                    ? taggedRHR.flatMap { taggedValue in
                        untaggedRHR.map { taggedValue - $0 }
                    } : nil
            ))
        }
        return shouldContinue() ? result : nil
    }

    private nonisolated static func averageDoubleSnapshot(_ values: [Double]) -> Double? {
        guard !values.isEmpty else { return nil }
        return values.reduce(0, +) / Double(values.count)
    }

    private nonisolated static func sortedBehaviorCorrelationSummaries(_ summaries: [BehaviorCorrelationSummary]) -> [BehaviorCorrelationSummary] {
        summaries.sorted { lhs, rhs in
            if (lhs.impactDelta != nil) != (rhs.impactDelta != nil) {
                return lhs.impactDelta != nil
            }
            if lhs.impactMagnitude != rhs.impactMagnitude {
                return lhs.impactMagnitude > rhs.impactMagnitude
            }
            if lhs.days != rhs.days { return lhs.days > rhs.days }
            return lhs.tag.rawValue < rhs.tag.rawValue
        }
    }

    private static func readBehaviorJournalEntries() -> [BehaviorJournalEntry] {
        guard let data = UserDefaults.standard.data(forKey: BehaviorJournalDefaults.key),
              let decoded = try? JSONDecoder().decode([BehaviorJournalEntry].self, from: data) else {
            return []
        }
        return decoded.sorted { $0.day > $1.day }
    }

    private func saveBehaviorJournalEntries(_ entries: [BehaviorJournalEntry]) {
        let sorted = entries.sorted(by: { $0.day > $1.day })
        guard let data = try? JSONEncoder().encode(sorted) else { return }
        UserDefaults.standard.set(data, forKey: BehaviorJournalDefaults.key)
        cachedBehaviorJournalEntries = sorted
        behaviorJournalRevision &+= 1
        recomputeBehaviorInsights()   // refresh insights when a day is tagged
    }

    func markResearchManeuver(_ kind: ResearchManeuverMarker.Kind, at timestamp: Date = Date()) {
        let marker = ResearchManeuverMarker(id: "research-\(kind.rawValue)-\(Int(timestamp.timeIntervalSince1970 * 1000))",
                                            kind: kind,
                                            timestamp: timestamp,
                                            createdAt: Date())
        saveResearchManeuverMarkers(([marker] + cachedResearchManeuverMarkers).prefix(ResearchManeuverDefaults.maxMarkers).map { $0 })
        dashboardRevision += 1
        AtriaDebugLog("ATRIADBG research_maneuver_marker status=marked kind=%@ timestamp=%@ local_only=1 research_only=1 metric_promotions=0 healthkit_write=0 raw_storage=0",
              kind.rawValue,
              isoString(timestamp))
    }

    private static func readResearchManeuverMarkers() -> [ResearchManeuverMarker] {
        guard let data = UserDefaults.standard.data(forKey: ResearchManeuverDefaults.key),
              let decoded = try? JSONDecoder().decode([ResearchManeuverMarker].self, from: data) else {
            return []
        }
        return decoded.sorted { $0.timestamp > $1.timestamp }
    }

    private func saveResearchManeuverMarkers(_ markers: [ResearchManeuverMarker]) {
        let sorted = markers.sorted(by: { $0.timestamp > $1.timestamp })
        guard let data = try? JSONEncoder().encode(sorted) else { return }
        UserDefaults.standard.set(data, forKey: ResearchManeuverDefaults.key)
        cachedResearchManeuverMarkers = sorted
        recomputeCollectionResearchSummaries()
    }

    private func behaviorJournalID(for day: Date) -> String {
        "\(Int(day.timeIntervalSince1970.rounded()))-behavior"
    }

    private func confirmedSleepID(start: Date, end: Date, source: String) -> String {
        let startSeconds = Int(start.timeIntervalSince1970.rounded())
        let endSeconds = Int(end.timeIntervalSince1970.rounded())
        return "\(startSeconds)-\(endSeconds)-\(source)"
    }

    private func isoString(_ date: Date) -> String {
        ISO8601DateFormatter().string(from: date)
    }

    func historicalGapRepairStatus(rest: Int, maxHR: Int) -> HistoricalGapRepairSummary {
        historicalGapRepairSummary(workoutReplay: replaySavedWorkoutReadiness(rest: rest, maxHR: maxHR),
                                   archive: HistoricalArchive.diagnostics())
    }

    private func logWorkoutThresholdSensitivity(rest: Int, maxHR: Int) {
        let fractions = [0.35, 0.40, 0.45, 0.50]
        var readyFractions: [String] = []
        for fraction in fractions {
            let summary = replaySavedWorkoutReadiness(rest: rest, maxHR: maxHR, thresholdFraction: fraction)
            let fractionPercent = Int((fraction * 100).rounded())
            if summary.readySessions > 0 {
                readyFractions.append("hrr\(fractionPercent)")
            }
            AtriaDebugLog("ATRIADBG workout_threshold_sensitivity hrr_percent=%d rest_hr=%d max_hr=%d threshold_hr=%d ready=%d ready_candidates=%d best_source=%@ best_chunks=%d best_label=%@ status=%@ reason=%@ primary_blocker=%@ stream_coverage_percent=%d duration_s=%.0f observed_duration_s=%.0f dropped_gap_s=%.0f max_gap_s=%.1f samples=%d peak_hr=%d threshold_gap_bpm=%d elevated_s=%.0f required_elevated_s=%.0f longest_bout_s=%.0f required_bout_s=%.0f borderline_threshold_hr=%d borderline_elevated_s=%.0f borderline_longest_bout_s=%.0f diagnostic_only=1 detector_threshold_hrr50_unchanged=1",
                  fractionPercent,
                  rest,
                  maxHR,
                  summary.bestThresholdHR,
                  summary.readySessions > 0 ? 1 : 0,
                  summary.readySessions,
                  summary.bestSource,
                  summary.bestChunkCount,
                  summary.bestLabel,
                  summary.bestStatus,
                  summary.bestReason,
                  summary.bestPrimaryBlocker,
                  summary.bestStreamCoveragePercent,
                  summary.bestDuration,
                  summary.bestObservedDuration,
                  summary.bestDroppedGapSeconds,
                  summary.bestMaxSampleGap,
                  summary.bestSamples,
                  summary.bestPeakHR,
                  summary.bestThresholdGapBPM,
                  summary.bestElevatedSeconds,
                  summary.bestRequiredElevatedSeconds,
                  summary.bestLongestBout,
                  summary.bestRequiredBout,
                  summary.bestBorderlineThresholdHR,
                  summary.bestBorderlineElevatedSeconds,
                  summary.bestBorderlineLongestBout)
        }
        AtriaDebugLog("ATRIADBG workout_threshold_sensitivity_summary fractions=%@ ready_fractions=%@ diagnostic_only=1 detector_threshold_hrr50_unchanged=1",
              fractions.map { "hrr\(Int(($0 * 100).rounded()))" }.joined(separator: ","),
              readyFractions.isEmpty ? "none" : readyFractions.joined(separator: ","))
    }

    private func replaySavedWorkoutReadiness(rest: Int,
                                             maxHR: Int,
                                             thresholdFraction: Double = 0.50,
                                             limitSessions: Int? = nil,
                                             includeAggregates: Bool = true,
                                             includeActiveJournal: Bool = false) -> WorkoutReplaySummary {
        let replaySessions = canonicalSessions(includeActiveJournal: includeActiveJournal)
        let rawSessions = sessions.count + (includeActiveJournal && activeJournalSessionIfFresh() != nil ? 1 : 0)
        return Self.replaySavedWorkoutReadiness(in: replaySessions,
                                                rawSessionCount: rawSessions,
                                                rest: rest,
                                                maxHR: maxHR,
                                                thresholdFraction: thresholdFraction,
                                                limitSessions: limitSessions,
                                                includeAggregates: includeAggregates)
    }

    private nonisolated static func replaySavedWorkoutReadiness(in sourceSessions: [SavedSession],
                                                                rawSessionCount: Int,
                                                                rest: Int,
                                                                maxHR: Int,
                                                                thresholdFraction: Double = 0.50,
                                                                limitSessions: Int? = nil,
                                                                includeAggregates: Bool = true) -> WorkoutReplaySummary {
        let windowSummaries = workoutReplayWindowSummaries(in: sourceSessions,
                                                           rawSessionCount: rawSessionCount,
                                                           rest: rest,
                                                           maxHR: maxHR,
                                                           thresholdFraction: thresholdFraction,
                                                           limitSessions: limitSessions,
                                                           includeAggregates: includeAggregates)
        guard !windowSummaries.isEmpty else {
            return .empty(rest: rest, maxHR: maxHR)
        }
        var best = WorkoutReplaySummary.empty(rest: rest, maxHR: maxHR)
        for candidate in windowSummaries where isBetterWorkoutReplaySummary(candidate, than: best) {
            best = candidate
        }
        return best
    }

    /// One `WorkoutReplaySummary` per evaluated window: each single session
    /// plus each stitched aggregate candidate, in evaluation order. The
    /// single-best replay above reduces over exactly this list, so a
    /// per-window consumer (the multi-candidate review list) can never
    /// disagree with the aggregated summary about which windows exist.
    /// Extracted 2026-07-17 to lift the single-candidate ceiling without
    /// duplicating the replay logic.
    private nonisolated static func workoutReplayWindowSummaries(in sourceSessions: [SavedSession],
                                                                 rawSessionCount: Int,
                                                                 rest: Int,
                                                                 maxHR: Int,
                                                                 thresholdFraction: Double = 0.50,
                                                                 limitSessions: Int? = nil,
                                                                 includeAggregates: Bool = true) -> [WorkoutReplaySummary] {
        var replaySessions = sourceSessions
        if let limitSessions {
            replaySessions.sort {
                if $0.points.count != $1.points.count {
                    return $0.points.count > $1.points.count
                }
                if $0.duration != $1.duration {
                    return $0.duration > $1.duration
                }
                return $0.end > $1.end
            }
            replaySessions = Array(replaySessions.prefix(max(1, limitSessions)))
        }
        let aggregateCandidates = includeAggregates
            ? AtriaTransientWorkThread.run(name: "atria.replay-aggregates") {
                aggregateWorkoutCandidates(in: replaySessions,
                                           rest: rest,
                                           maxHR: maxHR,
                                           calendar: Calendar.current,
                                           thresholdFraction: thresholdFraction)
            }
            : []
        // Perf: workoutReadiness walks a session's whole points array, so compute
        // it ONCE per session and reuse it for both the ready-count and the
        // per-session loop below (previously evaluated twice per session per call,
        // which ran every ~3s on the overview tab as saved sessions accumulated).
        let sessionReadiness = replaySessions.map { session in
            // Per-session dying thread (2026-08-04 balloon): a readiness
            // replay walks the session's whole points array; across ~50
            // canonical sessions with recovered archives attached, the
            // summed transient garbage inside ONE thread stretch crossed
            // 2GB (the hist_stage=detections kill). Each session's garbage
            // now dies before the next replay starts.
            (session: session,
             readiness: AtriaTransientWorkThread.run(name: "atria.replay-readiness") {
                 session.workoutReadiness(rest: rest,
                                          maxHR: maxHR,
                                          thresholdFraction: thresholdFraction)
             })
        }
        let readySessions = sessionReadiness.filter { $0.readiness.ready }.count
            + aggregateCandidates.filter { $0.readiness.ready }.count
        let evaluated = replaySessions.count + aggregateCandidates.count
        var windowSummaries: [WorkoutReplaySummary] = []
        windowSummaries.reserveCapacity(evaluated)
        for (session, readiness) in sessionReadiness {
            let candidate = WorkoutReplaySummary(rawSessions: rawSessionCount,
                                                 canonicalSessions: replaySessions.count,
                                                 sessionsEvaluated: evaluated,
                                                 readySessions: readySessions,
                                                 bestSource: "single_session",
                                                 bestChunkCount: 1,
                                                 bestStart: session.start,
                                                 bestEnd: session.end,
                                                 bestSpan: session.duration,
                                                 bestLabel: session.label,
                                                 bestStatus: readiness.status,
                                                 bestReason: readiness.reason,
                                                 bestDuration: readiness.duration,
                                                 bestObservedDuration: readiness.observedDuration,
                                                 bestSamples: session.points.count,
                                                 bestAvgHR: readiness.avgHR,
                                                 bestPeakHR: readiness.peakHR,
                                                 bestP95HR: readiness.p95HR,
                                                 bestP99HR: readiness.p99HR,
                                                 bestThresholdHR: readiness.thresholdHR,
                                                 bestThresholdGapBPM: readiness.thresholdGapBPM,
                                                 bestSamplesAboveThreshold: readiness.samplesAboveThreshold,
                                                 bestSamplesAboveBorderline: readiness.samplesAboveBorderline,
                                                 bestElevatedSeconds: readiness.elevatedSeconds,
                                                 bestRequiredElevatedSeconds: readiness.requiredElevatedSeconds,
                                                 bestLongestBout: readiness.longestElevatedBout,
                                                 bestRequiredBout: readiness.requiredElevatedBout,
                                                 bestElevatedFraction: readiness.elevatedFraction,
                                                 bestBorderlineThresholdHR: readiness.borderlineThresholdHR,
                                                 bestBorderlineElevatedSeconds: readiness.borderlineElevatedSeconds,
                                                 bestBorderlineLongestBout: readiness.borderlineLongestBout,
                                                 bestDroppedGapSeconds: readiness.droppedGapSeconds,
                                                 bestMaxSampleGap: readiness.maxSampleGap,
                                                 bestGapCount: readiness.gapCount,
                                                 bestStreamCoveragePercent: readiness.streamCoveragePercent,
                                                 bestPrimaryBlocker: readiness.primaryBlocker,
                                                 bestHRRaw2A37: session.hrRaw2A37Value,
                                                 bestHRAccepted: session.hrAcceptedValue,
                                                 bestHRZero: session.hrZeroValue,
                                                 bestHRArtifactHeld: session.hrArtifactHeldValue,
                                                 bestHRArtifactDropped: session.hrArtifactDroppedValue,
                                                 bestHRRawGaps: session.hrRawGapsValue,
                                                 bestHRAcceptedGaps: session.hrAcceptedGapsValue,
                                                 bestHRMaxRawGap: session.hrMaxRawGapValue,
                                                 bestHRMaxAcceptedGap: session.hrMaxAcceptedGapValue,
                                                 bestHRRRMismatch: session.hrRRMismatchValue,
                                                 bestContactQualifiedElevatedSeconds: readiness.contactQualifiedElevatedSeconds,
                                                 bestContactQualifiedLongestBout: readiness.contactQualifiedLongestBout,
                                                 bestContactCompromised: readiness.contactCompromised,
                                                 bestRRDisagreement: readiness.rrDisagreement,
                                                 restHR: rest,
                                                 maxHR: maxHR)
            windowSummaries.append(candidate)
        }
        for aggregate in aggregateCandidates {
            let readiness = aggregate.readiness
            let candidate = WorkoutReplaySummary(rawSessions: rawSessionCount,
                                                 canonicalSessions: replaySessions.count,
                                                 sessionsEvaluated: evaluated,
                                                 readySessions: readySessions,
                                                 bestSource: aggregate.source,
                                                 bestChunkCount: aggregate.sessions,
                                                 bestStart: aggregate.start,
                                                 bestEnd: aggregate.end,
                                                 bestSpan: aggregate.span,
                                                 bestLabel: aggregate.label,
                                                 bestStatus: readiness.status,
                                                 bestReason: readiness.reason,
                                                 bestDuration: readiness.duration,
                                                 bestObservedDuration: readiness.observedDuration,
                                                 bestSamples: aggregate.samples,
                                                 bestAvgHR: readiness.avgHR,
                                                 bestPeakHR: readiness.peakHR,
                                                 bestP95HR: readiness.p95HR,
                                                 bestP99HR: readiness.p99HR,
                                                 bestThresholdHR: readiness.thresholdHR,
                                                 bestThresholdGapBPM: readiness.thresholdGapBPM,
                                                 bestSamplesAboveThreshold: readiness.samplesAboveThreshold,
                                                 bestSamplesAboveBorderline: readiness.samplesAboveBorderline,
                                                 bestElevatedSeconds: readiness.elevatedSeconds,
                                                 bestRequiredElevatedSeconds: readiness.requiredElevatedSeconds,
                                                 bestLongestBout: readiness.longestElevatedBout,
                                                 bestRequiredBout: readiness.requiredElevatedBout,
                                                 bestElevatedFraction: readiness.elevatedFraction,
                                                 bestBorderlineThresholdHR: readiness.borderlineThresholdHR,
                                                 bestBorderlineElevatedSeconds: readiness.borderlineElevatedSeconds,
                                                 bestBorderlineLongestBout: readiness.borderlineLongestBout,
                                                 bestDroppedGapSeconds: readiness.droppedGapSeconds,
                                                 bestMaxSampleGap: readiness.maxSampleGap,
                                                 bestGapCount: readiness.gapCount,
                                                 bestStreamCoveragePercent: readiness.streamCoveragePercent,
                                                 bestPrimaryBlocker: readiness.primaryBlocker,
                                                 bestHRRaw2A37: aggregate.hrRaw2A37,
                                                 bestHRAccepted: aggregate.hrAccepted,
                                                 bestHRZero: aggregate.hrZero,
                                                 bestHRArtifactHeld: aggregate.hrArtifactHeld,
                                                 bestHRArtifactDropped: aggregate.hrArtifactDropped,
                                                 bestHRRawGaps: aggregate.hrRawGaps,
                                                 bestHRAcceptedGaps: aggregate.hrAcceptedGaps,
                                                 bestHRMaxRawGap: aggregate.hrMaxRawGap,
                                                 bestHRMaxAcceptedGap: aggregate.hrMaxAcceptedGap,
                                                 bestHRRRMismatch: aggregate.hrRRMismatch,
                                                 bestContactQualifiedElevatedSeconds: readiness.contactQualifiedElevatedSeconds,
                                                 bestContactQualifiedLongestBout: readiness.contactQualifiedLongestBout,
                                                 bestContactCompromised: readiness.contactCompromised,
                                                 bestRRDisagreement: readiness.rrDisagreement,
                                                 restHR: rest,
                                                 maxHR: maxHR)
            windowSummaries.append(candidate)
        }
        return windowSummaries
    }

    private nonisolated static func isBetterWorkoutReplaySummary(_ lhs: WorkoutReplaySummary, than rhs: WorkoutReplaySummary) -> Bool {
        if rhs.sessionsEvaluated == 0 { return true }
        if lhs.bestStatus != rhs.bestStatus { return lhs.bestStatus == "ready" }
        if lhs.nearMiss != rhs.nearMiss { return lhs.nearMiss }
        let lhsLongEnough = lhs.bestObservedDuration >= 15 * 60
        let rhsLongEnough = rhs.bestObservedDuration >= 15 * 60
        if lhsLongEnough != rhsLongEnough { return lhsLongEnough }
        let lhsHasElevatedEvidence = lhs.bestElevatedSeconds > 0 || lhs.bestPeakHR >= lhs.bestThresholdHR
        let rhsHasElevatedEvidence = rhs.bestElevatedSeconds > 0 || rhs.bestPeakHR >= rhs.bestThresholdHR
        if lhsHasElevatedEvidence != rhsHasElevatedEvidence { return lhsHasElevatedEvidence }
        if lhs.bestLongestBout != rhs.bestLongestBout {
            return lhs.bestLongestBout > rhs.bestLongestBout
        }
        if lhs.bestElevatedSeconds != rhs.bestElevatedSeconds {
            return lhs.bestElevatedSeconds > rhs.bestElevatedSeconds
        }
        if lhs.bestBorderlineLongestBout != rhs.bestBorderlineLongestBout {
            return lhs.bestBorderlineLongestBout > rhs.bestBorderlineLongestBout
        }
        if lhs.bestBorderlineElevatedSeconds != rhs.bestBorderlineElevatedSeconds {
            return lhs.bestBorderlineElevatedSeconds > rhs.bestBorderlineElevatedSeconds
        }
        if lhs.bestPeakHR != rhs.bestPeakHR {
            return lhs.bestPeakHR > rhs.bestPeakHR
        }
        if lhs.bestStreamCoveragePercent != rhs.bestStreamCoveragePercent {
            return lhs.bestStreamCoveragePercent > rhs.bestStreamCoveragePercent
        }
        if lhs.bestObservedDuration != rhs.bestObservedDuration {
            return lhs.bestObservedDuration > rhs.bestObservedDuration
        }
        return lhs.bestMaxSampleGap < rhs.bestMaxSampleGap
    }

    private func latestBackupMatchesCurrentStore(_ latest: URL) -> Bool {
        guard let envelope = try? Self.decodeSessionBackupEnvelope(at: latest),
              Self.supportedBackupSchemas.contains(envelope.schema),
              envelope.sessions.count == sessions.count else {
            return false
        }
        let rollups = dailyRollupHistory.isEmpty ? dailyRollupStore.rollups(last: 400) : dailyRollupHistory
        let backupDigest = backupContentDigest(sessions: envelope.sessions,
                                               baseline: envelope.baseline,
                                               profile: envelope.profile,
                                               dailyMetrics: envelope.dailyMetrics,
                                               dailyRollups: envelope.dailyRollups,
                                               confirmedSleeps: envelope.confirmedSleeps,
                                               confirmedWorkouts: envelope.confirmedWorkouts)
        let currentDigest = backupContentDigest(sessions: sessions,
                                                baseline: baseline,
                                                profile: profile,
                                                dailyMetrics: envelope.schema >= 2 ? dailyMetricHistory : nil,
                                                dailyRollups: envelope.schema >= 2 ? rollups : nil,
                                                confirmedSleeps: envelope.schema >= 2 ? cachedConfirmedSleeps : nil,
                                                confirmedWorkouts: envelope.schema >= 4 ? cachedConfirmedWorkouts : nil)
        return backupDigest != nil && backupDigest == currentDigest
    }

    private nonisolated static func computeSessionBackupStatus(currentSessions: [SavedSession],
                                                               baseline: PersonalBaseline,
                                                               profile: AthleteProfile,
                                                               dailyMetrics: [SavedDailyMetric],
                                                               dailyRollups: [DailyRollupStoreEntry],
                                                               confirmedSleeps: [UserConfirmedSleep],
                                                               confirmedWorkouts: [UserConfirmedWorkout],
                                                               sessionFileURL: URL) -> SessionBackupStatus {
        guard let latest = latestSessionBackupURL(sessionFileURL: sessionFileURL,
                                                  includeSafetyBackups: false) else {
            return .missing
        }
        let rrSamples = { (sessions: [SavedSession]) in
            sessions.reduce(0) { $0 + ($1.rrPoints?.count ?? 0) }
        }
        do {
            let data = try Self.sessionBackupPayloadData(at: latest)
            let envelope = try Self.decodeSessionBackupEnvelope(from: data)
            guard Self.supportedBackupSchemas.contains(envelope.schema) else {
                return SessionBackupStatus(available: true,
                                           current: false,
                                           path: backupRelativePath(for: latest),
                                           sessions: envelope.sessions.count,
                                           rrSamples: rrSamples(envelope.sessions),
                                           bytes: data.count,
                                           reason: "unsupported_schema_\(envelope.schema)")
            }
            let current = latestBackupMatchesCurrentStore(latest,
                                                          currentSessions: currentSessions,
                                                          baseline: baseline,
                                                          profile: profile,
                                                          dailyMetrics: dailyMetrics,
                                                          dailyRollups: dailyRollups,
                                                          confirmedSleeps: confirmedSleeps,
                                                          confirmedWorkouts: confirmedWorkouts)
            return SessionBackupStatus(available: true,
                                       current: current,
                                       path: backupRelativePath(for: latest),
                                       sessions: envelope.sessions.count,
                                       rrSamples: rrSamples(envelope.sessions),
                                       bytes: data.count,
                                       reason: current ? "current" : "digest_mismatch")
        } catch {
            return SessionBackupStatus(available: true,
                                       current: false,
                                       path: backupRelativePath(for: latest),
                                       sessions: 0,
                                       rrSamples: 0,
                                       bytes: 0,
                                       reason: "decode_error")
        }
    }

    private nonisolated static func latestBackupMatchesCurrentStore(_ latest: URL,
                                                                    currentSessions: [SavedSession],
                                                                    baseline: PersonalBaseline,
                                                                    profile: AthleteProfile,
                                                                    dailyMetrics: [SavedDailyMetric],
                                                                    dailyRollups: [DailyRollupStoreEntry],
                                                                    confirmedSleeps: [UserConfirmedSleep],
                                                                    confirmedWorkouts: [UserConfirmedWorkout]) -> Bool {
        guard let envelope = try? decodeSessionBackupEnvelope(at: latest),
              supportedBackupSchemas.contains(envelope.schema),
              envelope.sessions.count == currentSessions.count else {
            return false
        }
        let backupDigest = makeBackupContentDigest(sessions: envelope.sessions,
                                                   baseline: envelope.baseline,
                                                   profile: envelope.profile,
                                                   dailyMetrics: envelope.dailyMetrics,
                                                   dailyRollups: envelope.dailyRollups,
                                                   confirmedSleeps: envelope.confirmedSleeps,
                                                   confirmedWorkouts: envelope.confirmedWorkouts)
        let currentDigest = makeBackupContentDigest(sessions: currentSessions,
                                                    baseline: baseline,
                                                    profile: profile,
                                                    dailyMetrics: envelope.schema >= 2 ? dailyMetrics : nil,
                                                    dailyRollups: envelope.schema >= 2 ? dailyRollups : nil,
                                                    confirmedSleeps: envelope.schema >= 2 ? confirmedSleeps : nil,
                                                    confirmedWorkouts: envelope.schema >= 4 ? confirmedWorkouts : nil)
        return backupDigest != nil && backupDigest == currentDigest
    }

    private nonisolated static func latestSessionBackupURL(sessionFileURL: URL,
                                                           includeSafetyBackups: Bool) -> URL? {
        var allFiles: [URL] = []
        for backupDir in sessionBackupDirectoriesForReading(sessionFileURL: sessionFileURL) {
            guard let files = try? FileManager.default.contentsOfDirectory(at: backupDir,
                                                                           includingPropertiesForKeys: nil,
                                                                           options: [.skipsHiddenFiles])
                .filter({ isSessionBackupFile($0, includeSafetyBackups: includeSafetyBackups) }) else {
                continue
            }
            allFiles.append(contentsOf: files)
        }
        return Self.latestDecodableSessionBackupURL(from: allFiles)
    }

    private nonisolated static func sessionBackupDirectoriesForReading(sessionFileURL: URL) -> [URL] {
        let documentsURL = sessionFileURL.deletingLastPathComponent()
        return [
            documentsURL.appendingPathComponent("atria-backups"),
            documentsURL.appendingPathComponent("whoop-backups")
        ]
    }

    private nonisolated static func latestDecodableSessionBackupURL(from files: [URL]) -> URL? {
        files
            .sorted { backupSortDate($0) > backupSortDate($1) }
            .first { url in
                guard let envelope = try? decodeSessionBackupEnvelope(at: url) else {
                    return false
                }
                return supportedBackupSchemas.contains(envelope.schema)
            }
    }

    private nonisolated static func bestRestorableSessionBackupURL(from files: [URL]) -> URL? {
        let candidates = files
            .compactMap { url -> (url: URL, isComplete: Bool, sessions: Int, date: Date)? in
                guard let envelope = try? decodeSessionBackupEnvelope(at: url),
                      supportedBackupSchemas.contains(envelope.schema),
                      envelope.schema >= 2 else {
                    return nil
                }
                let hasProductState = !(envelope.dailyRollups ?? []).isEmpty
                    && !(envelope.confirmedSleeps ?? []).isEmpty
                return (url, hasProductState, envelope.sessions.count, backupSortDate(url))
            }
        let productComplete = candidates.filter(\.isComplete)
        let ranked = productComplete.isEmpty ? candidates : productComplete
        return ranked
            .sorted {
                if $0.sessions != $1.sessions {
                    return $0.sessions > $1.sessions
                }
                return $0.date > $1.date
            }
            .first?
            .url
    }

    private nonisolated static func backupRelativePath(for backupURL: URL) -> String {
        let directory = backupURL.deletingLastPathComponent().lastPathComponent
        return "Documents/\(directory)/\(backupURL.lastPathComponent)"
    }

    private nonisolated static func backupSortDate(_ backupURL: URL) -> Date {
        if let date = (try? FileManager.default.attributesOfItem(atPath: backupURL.path)[.modificationDate]) as? Date {
            return date
        }
        return .distantPast
    }

    private nonisolated static let supportedBackupSchemas: Set<Int> = [1, 2, 3, 4]

    enum SessionBackupImportError: Error, Equatable {
        case archiveTooLarge
        case invalidApp
        case recordLimitExceeded
        case invalidDomain
        case duplicateIdentity
        case inconsistentRawExport
    }

    private nonisolated static let maximumBackupSessions = 100_000
    private nonisolated static let maximumBackupRecords = 5_000_000
    private nonisolated static let maximumBackupDailyRecords = 10_000

    /// Validation is intentionally independent from product interpretation.
    /// It only admits bounded Atria-shaped records with finite time/value
    /// domains; unsupported schemas are handled by the caller so their reason
    /// remains visible to Settings diagnostics.
    nonisolated static func validateSessionBackupEnvelopeForImport(
        _ envelope: SessionBackupEnvelope
    ) throws {
        guard envelope.app == "Atria.local" else {
            throw SessionBackupImportError.invalidApp
        }
        guard envelope.sessions.count <= maximumBackupSessions,
              (envelope.dailyMetrics?.count ?? 0) <= maximumBackupDailyRecords,
              (envelope.dailyRollups?.count ?? 0) <= maximumBackupDailyRecords,
              (envelope.confirmedSleeps?.count ?? 0) <= maximumBackupSessions,
              (envelope.confirmedWorkouts?.count ?? 0) <= maximumBackupSessions else {
            throw SessionBackupImportError.recordLimitExceeded
        }

        var records = envelope.sessions.count
            + (envelope.dailyMetrics?.count ?? 0)
            + (envelope.dailyRollups?.count ?? 0)
            + (envelope.confirmedSleeps?.count ?? 0)
            + (envelope.confirmedWorkouts?.count ?? 0)
        let earliestDate = Date(timeIntervalSince1970: 946_684_800) // 2000-01-01
        let latestDate = Date(timeIntervalSince1970: 4_102_444_800) // 2100-01-01
        func validDate(_ date: Date) -> Bool {
            date.timeIntervalSince1970.isFinite && date >= earliestDate && date <= latestDate
        }
        func validString(_ value: String, maximumBytes: Int = 16 * 1024) -> Bool {
            !value.isEmpty && value.utf8.count <= maximumBytes
        }
        func validOptionalString(_ value: String?, maximumBytes: Int = 16 * 1024) -> Bool {
            value.map { $0.utf8.count <= maximumBytes } ?? true
        }
        func validTimeZone(_ value: String?) -> Bool {
            value.map { TimeZone(identifier: $0) != nil } ?? true
        }
        func chronologicallyOrdered<T>(_ values: [T], time: (T) -> Double) -> Bool {
            zip(values, values.dropFirst()).allSatisfy { time($0) <= time($1) }
        }
        func allUnique<T: Hashable>(_ values: [T]) -> Bool {
            Set(values).count == values.count
        }
        func validExcludedInterval(_ interval: ExcludedInterval,
                                   within start: Date,
                                   _ end: Date) -> Bool {
            validDate(interval.start) && validDate(interval.end)
                && interval.start < interval.end
                && interval.start >= start && interval.end <= end
        }
        func validSet(_ set: LoggedSet, within start: Date, _ end: Date) -> Bool {
            validDate(set.t) && set.t >= start && set.t <= end
                && validString(set.exercise, maximumBytes: 4 * 1024)
                && (set.weightKg.map { $0.isFinite && (0...2_000).contains($0) } ?? true)
                && (set.reps.map { (0...10_000).contains($0) } ?? true)
                && (set.rpe.map { $0.isFinite && (0...10).contains($0) } ?? true)
        }
        func validCalibrationEvidence(_ evidence: AtriaActivityCalibrationEvidence,
                                      for workout: UserConfirmedWorkout) -> Bool {
            let candidateID = workout.reviewCandidateID?
                .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
            let duration = workout.end.timeIntervalSince(workout.start)
            let requestedBins = duration > 0
                ? Int(ceil(duration / AtriaActivityCalibrationEvidence.binSeconds)) : 0
            let expectedBinCount = min(AtriaActivityCalibrationEvidence.maximumBins,
                                       max(0, requestedBins))
            let sourceIDsAreConsistent = evidence.sourceSessionIDsTruncated
                ? evidence.sourceSessionCount > evidence.sourceSessionIDs.count
                : evidence.sourceSessionCount == evidence.sourceSessionIDs.count
            let validOptionalMotionValue: (Double?) -> Bool = { value in
                value.map { $0.isFinite && $0 >= 0 && $0 <= 1_000_000 } ?? true
            }
            let binsAreCanonical = evidence.bins.enumerated().allSatisfy { index, bin in
                let expectedOffset = index * Int(AtriaActivityCalibrationEvidence.binSeconds)
                let expectedDuration = Int(min(
                    AtriaActivityCalibrationEvidence.binSeconds,
                    max(0, duration - Double(expectedOffset))
                ).rounded())
                let heartRateIsConsistent: Bool
                if bin.hrSampleCount == 0 {
                    heartRateIsConsistent = bin.averageHR == nil
                        && bin.minimumHR == nil
                        && bin.maximumHR == nil
                } else if let average = bin.averageHR,
                          let minimum = bin.minimumHR,
                          let maximum = bin.maximumHR {
                    heartRateIsConsistent = minimum <= average && average <= maximum
                } else {
                    heartRateIsConsistent = false
                }
                return bin.startOffsetSeconds == expectedOffset
                    && bin.durationSeconds == expectedDuration
                    && bin.durationSeconds > 0
                    && bin.hrSampleCount >= 0
                    && (bin.averageHR.map({ (25...240).contains($0) }) ?? true)
                    && (bin.minimumHR.map({ (25...240).contains($0) }) ?? true)
                    && (bin.maximumHR.map({ (25...240).contains($0) }) ?? true)
                    && heartRateIsConsistent
                    && bin.validatedMotionEpochs >= 0
                    && bin.validatedMotionCoverageFraction.isFinite
                    && (0...1).contains(bin.validatedMotionCoverageFraction)
                    && (bin.meanStillnessRatio.map({ $0.isFinite && (0...1).contains($0) }) ?? true)
                    && validOptionalMotionValue(bin.meanMovementIntensity)
                    && validOptionalMotionValue(bin.meanP95VectorDelta)
            }
            let provenanceIsConsistent = evidence.motion.validatedEpochCount == 0
                ? evidence.motion.provenance == "none"
                : evidence.motion.provenance == AtriaRecoveredMotionEpoch.source
            return workout.reviewSource == "detected_activity_review"
                && !candidateID.isEmpty
                && candidateID.utf8.count <= 4 * 1_024
                && evidence.schemaVersion == AtriaActivityCalibrationEvidence.schemaVersion
                && evidence.algorithmVersion == AtriaActivityCalibrationEvidence.algorithmVersion
                && AtriaActivityCalibrationEvidence.allowedStatuses.contains(evidence.status)
                && validDate(evidence.windowStart)
                && validDate(evidence.windowEnd)
                && evidence.windowStart == workout.start
                && evidence.windowEnd == workout.end
                && evidence.sourceSessionIDs.count <= AtriaActivityCalibrationEvidence.maximumSourceSessions
                && allUnique(evidence.sourceSessionIDs)
                && (0...maximumBackupRecords).contains(evidence.sourceSessionCount)
                && sourceIDsAreConsistent
                && evidence.bins.count == expectedBinCount
                && binsAreCanonical
                && AtriaActivityCalibrationEvidence.allowedMotionProvenance.contains(evidence.motion.provenance)
                && provenanceIsConsistent
                && evidence.motion.epochCount >= evidence.motion.validatedEpochCount
                && (0...maximumBackupRecords).contains(evidence.motion.epochCount)
                && evidence.motion.validatedEpochCount >= 0
                && evidence.motion.validatedCoverageFraction.isFinite
                && (0...1).contains(evidence.motion.validatedCoverageFraction)
                && (evidence.motion.meanStillnessRatio.map({ $0.isFinite && (0...1).contains($0) }) ?? true)
                && validOptionalMotionValue(evidence.motion.meanMovementIntensity)
                && validOptionalMotionValue(evidence.motion.meanP95VectorDelta)
        }
        guard validDate(envelope.createdAt),
              (13...120).contains(envelope.profile.age),
              (100...250).contains(envelope.profile.measuredMaxHR),
              (100...250).contains(envelope.profile.maxHR),
              envelope.profile.weightKg.isFinite,
              envelope.profile.heightCm.isFinite,
              (0...1_000).contains(envelope.profile.weightKg),
              (0...300).contains(envelope.profile.heightCm),
              envelope.profile.updated.map(validDate) ?? true,
              envelope.baseline.sessions >= 0,
              envelope.baseline.sessions <= maximumBackupRecords,
              envelope.baseline.restingHR.map({ $0.isFinite && (20...300).contains($0) }) ?? true,
              envelope.baseline.hrvEMA.map({ $0.isFinite && (1...5_000).contains($0) }) ?? true,
              envelope.baseline.updated.map(validDate) ?? true,
              envelope.baseline.samples.count <= maximumBackupDailyRecords,
              envelope.baseline.samples.allSatisfy({ sample in
                  validDate(sample.date)
                      && sample.restingHR.isFinite && (20...300).contains(sample.restingHR)
                      && (sample.rmssd == nil || (sample.rmssd!.isFinite && (1...5_000).contains(sample.rmssd!)))
              }) else {
            throw SessionBackupImportError.invalidDomain
        }

        // Restore merge keys are durable identities. Duplicates make the
        // archive ambiguous and used to reach Dictionary(uniqueKeysWithValues:),
        // which traps instead of returning a recoverable import error.
        guard allUnique(envelope.sessions.map(\.id)),
              allUnique((envelope.confirmedWorkouts ?? []).map(\.id)),
              allUnique((envelope.confirmedSleeps ?? []).map(\.id)),
              allUnique((envelope.dailyMetrics ?? []).map(\.day)),
              allUnique((envelope.dailyRollups ?? []).map(\.day)) else {
            throw SessionBackupImportError.duplicateIdentity
        }

        for session in envelope.sessions {
            let duration = session.end.timeIntervalSince(session.start)
            let rr = session.rrPoints ?? []
            let sets = session.strengthSets ?? []
            let exclusions = session.excludedIntervals ?? []
            let temperatures = session.decodedSkinTemperatureCelsius ?? []
            let recoveredMotionEpochs = session.recoveredMotionEpochs ?? []
            records += session.points.count + rr.count + sets.count + exclusions.count
                + temperatures.count + recoveredMotionEpochs.count
            let counters = [session.motionHintCount, session.motionShortCount,
                            session.motionShortOverOneCount, session.imuSampleCount,
                            session.imuFrameCount, session.imuActivityBursts,
                            session.strapStepResearchCount, session.sensorResearchProbeFrames,
                            session.spo2ResearchCandidateFrames, session.skinTempResearchCandidateFrames,
                            session.skinTempResearchCandidateValueCount,
                            session.spo2ResearchCandidateOffset64ValueCount,
                            session.spo2ResearchCandidateOffset66ValueCount, session.hrRaw2A37,
                            session.hrAccepted, session.hrZero, session.hrArtifactHeld,
                            session.hrArtifactDropped, session.hrRawGaps, session.hrAcceptedGaps,
                            session.hrRRMismatch].compactMap { $0 }
            let finiteNonnegative = [session.motionShortMean, session.motionShortMin,
                                     session.motionShortMax, session.imuSampleRateHz,
                                     session.imuScale, session.imuStillnessRatio,
                                     session.imuMovementIntensity, session.strapStepResearchAgreement,
                                     session.activeCalories, session.hrMaxRawGap,
                                     session.hrMaxAcceptedGap].compactMap { $0 }
            guard records <= maximumBackupRecords,
                  validDate(session.start), validDate(session.end),
                  duration >= 0, duration <= 10 * 365 * 24 * 60 * 60,
                  validString(session.label), validTimeZone(session.eventTimeZoneIdentifier),
                  validOptionalString(session.kind, maximumBytes: 256),
                  validOptionalString(session.motionHintKinds),
                  validOptionalString(session.motionEvidenceSource),
                  validOptionalString(session.imuEndian, maximumBytes: 128),
                  validOptionalString(session.imuValidationState, maximumBytes: 512),
                  validOptionalString(session.strapStepResearchState, maximumBytes: 512),
                  validOptionalString(session.sleepWakeResearchState, maximumBytes: 512),
                  validOptionalString(session.sleepWakeResearchConfidence, maximumBytes: 512),
                  validOptionalString(session.sleepWakeResearchReason),
                  validOptionalString(session.caloriesConfidence, maximumBytes: 512),
                  session.hrv.map({ (1...5_000).contains($0) }) ?? true,
                  session.hrvSDNN.map({ $0.isFinite && (0...5_000).contains($0) }) ?? true,
                  session.respiratoryRate.map({ $0.isFinite && (1...80).contains($0) }) ?? true,
                  session.points.count <= 1_000_000,
                  rr.count <= 1_000_000,
                  recoveredMotionEpochs.count <= 1_000_000,
                  sets.count <= 100_000, exclusions.count <= 100_000,
                  temperatures.count <= 100_000,
                  counters.allSatisfy({ (0...maximumBackupRecords).contains($0) }),
                  finiteNonnegative.allSatisfy({ $0.isFinite && $0 >= 0 && $0 <= 10_000_000 }),
                  session.imuStillnessRatio.map({ (0...1).contains($0) }) ?? true,
                  session.strapStepResearchAgreement.map({ (0...1).contains($0) }) ?? true,
                  temperatures.allSatisfy({ $0.celsius.isFinite && (-100...100).contains($0.celsius) }),
                  chronologicallyOrdered(session.points, time: { $0.t }),
                  chronologicallyOrdered(rr, time: { $0.t }),
                  chronologicallyOrdered(recoveredMotionEpochs,
                                         time: { $0.start.timeIntervalSince1970 }),
                  zip(recoveredMotionEpochs, recoveredMotionEpochs.dropFirst()).allSatisfy({
                      $0.0.end <= $0.1.start
                  }),
                  session.points.allSatisfy({ point in
                      point.t.isFinite && point.t >= 0 && point.t <= duration + 60
                          && (1...300).contains(point.bpm)
                  }),
                  rr.allSatisfy({ point in
                      point.t.isFinite && point.t >= 0 && point.t <= duration + 60
                          && (200...3_000).contains(point.ms)
                  }),
                  recoveredMotionEpochs.allSatisfy({ epoch in
                      validDate(epoch.start) && validDate(epoch.end)
                          && epoch.start >= session.start && epoch.end <= session.end
                          && epoch.end > epoch.start
                          && epoch.rows >= 0 && epoch.rows <= maximumBackupRecords
                          && epoch.validatedRows >= 0 && epoch.validatedRows <= epoch.rows
                          && epoch.maximumGapSeconds >= 0
                          && epoch.maximumGapSeconds <= Int(duration.rounded(.up))
                          && epoch.stillnessRatio.map({ $0.isFinite && (0...1).contains($0) }) ?? true
                          && epoch.movementIntensity.map({ $0.isFinite && $0 >= 0 && $0 <= 10 }) ?? true
                          && epoch.p95VectorDelta.map({ $0.isFinite && $0 >= 0 && $0 <= 10 }) ?? true
                          && validString(epoch.reason, maximumBytes: 1_024)
                  }),
                  sets.allSatisfy({ validSet($0, within: session.start, session.end) }),
                  exclusions.allSatisfy({ validExcludedInterval($0, within: session.start, session.end) }) else {
                throw SessionBackupImportError.invalidDomain
            }
        }

        for metric in envelope.dailyMetrics ?? [] {
            let stageSegments = metric.sleepStageSegments
            records += stageSegments.count
            let hasBothSleepBounds = (metric.sleepStart == nil) == (metric.sleepEnd == nil)
            guard validDate(metric.day),
                  records <= maximumBackupRecords,
                  validString(metric.recoveryConfidence, maximumBytes: 1_024),
                  validOptionalString(metric.sleepSource, maximumBytes: 4 * 1024),
                  metric.recoveryPercent.map({ (0...100).contains($0) }) ?? true,
                  metric.hrv.map({ (1...5_000).contains($0) }) ?? true,
                  metric.restingHR.map({ (20...300).contains($0) }) ?? true,
                  metric.respiratoryRate.map({ $0.isFinite && (1...80).contains($0) }) ?? true,
                  metric.sleepDuration.map({ $0.isFinite && $0 >= 0 && $0 <= 7 * 24 * 60 * 60 }) ?? true,
                  metric.sleepSpan.map({ $0.isFinite && $0 >= 0 && $0 <= 7 * 24 * 60 * 60 }) ?? true,
                  hasBothSleepBounds,
                  metric.sleepStart.map(validDate) ?? true,
                  metric.sleepEnd.map(validDate) ?? true,
                  (metric.sleepStart == nil || metric.sleepEnd! > metric.sleepStart!),
                  metric.sleepConsistencyPercent.map({ (0...100).contains($0) }) ?? true,
                  metric.strain.map({ $0.isFinite && (0...21).contains($0) }) ?? true,
                  metric.skinTemperatureDeviationCelsius.map({ $0.isFinite && (-20...20).contains($0) }) ?? true,
                  stageSegments.count <= 100_000,
                  allUnique(stageSegments.map(\.id)),
                  chronologicallyOrdered(stageSegments, time: { $0.start.timeIntervalSince1970 }),
                  zip(stageSegments, stageSegments.dropFirst()).allSatisfy({ pair in
                      pair.0.end <= pair.1.start
                  }),
                  stageSegments.allSatisfy({ segment in
                      validString(segment.id, maximumBytes: 4 * 1_024)
                          && validDate(segment.start) && validDate(segment.end)
                          && segment.start < segment.end
                          && (metric.sleepStart.map { segment.start >= $0 } ?? true)
                          && (metric.sleepEnd.map { segment.end <= $0 } ?? true)
                  }) else {
                throw SessionBackupImportError.invalidDomain
            }
        }

        for rollup in envelope.dailyRollups ?? [] {
            let contributors = rollup.recoverySummary?.contributors ?? []
            records += contributors.count
            let vitalStats = [rollup.vitals?.rhr, rollup.vitals?.hrv, rollup.vitals?.resp].compactMap { $0 }
            let nutritionValues = [rollup.nutrition?.kcal, rollup.nutrition?.proteinG,
                                   rollup.nutrition?.carbsG, rollup.nutrition?.fatG,
                                   rollup.nutrition?.waterMl, rollup.nutrition?.caffeineMg,
                                   rollup.nutrition?.alcoholDrinks].compactMap { $0 }
            guard validDate(rollup.day),
                  records <= maximumBackupRecords,
                  (-24 * 60...24 * 60).contains(rollup.tzOffsetMinutes),
                  rollup.recovery.map({ (0...100).contains($0) }) ?? true,
                  rollup.lnRMSSD.map({ $0.isFinite && (-10...10).contains($0) }) ?? true,
                  rollup.rhr.map({ (20...300).contains($0) }) ?? true,
                  rollup.sleepSeconds.map({ $0.isFinite && $0 >= 0 && $0 <= 7 * 24 * 60 * 60 }) ?? true,
                  rollup.sleepPerformance.map({ (0...100).contains($0) }) ?? true,
                  rollup.bedtimeMinutes.map({ (-48 * 60...48 * 60).contains($0) }) ?? true,
                  rollup.strain.map({ $0.isFinite && (0...21).contains($0) }) ?? true,
                  rollup.respiratoryRate.map({ $0.isFinite && (1...80).contains($0) }) ?? true,
                  rollup.skinTemperatureDeviationCelsius.map({ $0.isFinite && (-20...20).contains($0) }) ?? true,
                  rollup.fitnessAgeDelta.map({ (-100...100).contains($0) }) ?? true,
                  rollup.recoverySummary.map({ summary in
                      (0...100).contains(summary.score)
                          && summary.score == rollup.recovery
                          && validString(summary.confidence, maximumBytes: 1_024)
                          && validString(summary.source, maximumBytes: 1_024)
                          && validOptionalString(summary.model, maximumBytes: 1_024)
                          && (summary.scoredDay.map(validDate) ?? true)
                          && summary.detail.utf8.count <= 16 * 1024
                          && summary.contributors.count <= 1_000
                          && summary.contributors.allSatisfy { contributor in
                              validString(contributor.kind, maximumBytes: 1_024)
                                  && validOptionalString(contributor.unit, maximumBytes: 1_024)
                                  && validOptionalString(contributor.detail)
                                  && validOptionalString(contributor.displayValue, maximumBytes: 4 * 1024)
                                  && (contributor.value.map { $0.isFinite } ?? true)
                                  && (contributor.zScore.map { $0.isFinite && (-100...100).contains($0) } ?? true)
                                  && (contributor.weight.map { $0.isFinite && (-10...10).contains($0) } ?? true)
                                  && (contributor.direction.map { (-1...1).contains($0) } ?? true)
                          }
                  }) ?? true,
                  vitalStats.allSatisfy({ stat in
                      stat.mean.isFinite && stat.sd.isFinite && stat.sd >= 0
                          && (0...maximumBackupRecords).contains(stat.n)
                  }),
                  nutritionValues.allSatisfy({ $0.isFinite && $0 >= 0 && $0 <= 10_000_000 }),
                  (rollup.nutrition?.lastCaffeineHour.map({ (0...23).contains($0) }) ?? true) else {
                throw SessionBackupImportError.invalidDomain
            }
        }

        if let sleeps = envelope.confirmedSleeps {
            for sleep in sleeps {
                let stageSegments = sleep.stageSegments ?? []
                records += stageSegments.count
                guard records <= maximumBackupRecords,
                      validDate(sleep.createdAt), validDate(sleep.start), validDate(sleep.end),
                      validString(sleep.id, maximumBytes: 4 * 1024),
                      validString(sleep.source, maximumBytes: 4 * 1024),
                      validString(sleep.confidence, maximumBytes: 1_024),
                      validString(sleep.reason),
                      validString(sleep.motionSource, maximumBytes: 4 * 1024),
                      validTimeZone(sleep.eventTimeZoneIdentifier),
                      sleep.end > sleep.start,
                      sleep.duration.isFinite, sleep.duration >= 0,
                      sleep.span.isFinite, sleep.span >= 0,
                      sleep.duration <= sleep.span + 60,
                      sleep.span <= sleep.end.timeIntervalSince(sleep.start) + 60,
                      (0...maximumBackupRecords).contains(sleep.sessions),
                      (0...maximumBackupRecords).contains(sleep.samples),
                      (0...300).contains(sleep.avgHR),
                      (0...300).contains(sleep.peakHR),
                      (0...300).contains(sleep.restingHR),
                      sleep.hrv.map({ (1...5_000).contains($0) }) ?? true,
                      sleep.hrvWindowCount.map({ (0...maximumBackupRecords).contains($0) }) ?? true,
                      stageSegments.count <= 100_000,
                      allUnique(stageSegments.map(\.id)),
                      chronologicallyOrdered(stageSegments, time: { $0.start.timeIntervalSince1970 }),
                      zip(stageSegments, stageSegments.dropFirst()).allSatisfy({ pair in
                          pair.0.end <= pair.1.start
                      }),
                      stageSegments.allSatisfy({ segment in
                          validString(segment.id, maximumBytes: 4 * 1024)
                              &&
                          validDate(segment.start) && validDate(segment.end)
                              && segment.end > segment.start
                              && segment.start >= sleep.start.addingTimeInterval(-60)
                              && segment.end <= sleep.end.addingTimeInterval(60)
                      }),
                      (stageSegments.isEmpty
                          || AtriaSleepStageIntegrity.validates(stageSegments, for: sleep)
                      ) else {
                    throw SessionBackupImportError.invalidDomain
                }
            }
        }

        if let workouts = envelope.confirmedWorkouts {
            for workout in workouts {
                let sets = workout.strengthSets ?? []
                let exclusions = workout.excludedIntervals ?? []
                let exercises = workout.exerciseNames ?? []
                let zones = workout.zoneSeconds ?? [:]
                let calibration = workout.activityCalibrationEvidence
                records += sets.count + exclusions.count + exercises.count + zones.count
                    + (calibration?.bins.count ?? 0) + (calibration?.sourceSessionIDs.count ?? 0)
                let duration = workout.end.timeIntervalSince(workout.start)
                guard records <= maximumBackupRecords,
                      validDate(workout.createdAt), validDate(workout.start), validDate(workout.end),
                      validString(workout.id, maximumBytes: 4 * 1024),
                      validString(workout.label, maximumBytes: 4 * 1024),
                      validString(workout.source, maximumBytes: 4 * 1024),
                      validString(workout.confidence, maximumBytes: 1_024),
                      validString(workout.reason),
                      validOptionalString(workout.activityType, maximumBytes: 1_024),
                      validOptionalString(workout.activitySubtype, maximumBytes: 1_024),
                      validOptionalString(workout.reviewSource, maximumBytes: 4 * 1024),
                      validOptionalString(workout.reviewCandidateID, maximumBytes: 4 * 1024),
                      validOptionalString(workout.activeEnergyConfidence, maximumBytes: 1_024),
                      validTimeZone(workout.eventTimeZoneIdentifier),
                      workout.end > workout.start,
                      workout.observedDuration.isFinite, workout.observedDuration >= 0,
                      workout.observedDuration <= duration + 24 * 60 * 60,
                      (0...maximumBackupRecords).contains(workout.sessions),
                      (0...maximumBackupRecords).contains(workout.samples),
                      (0...300).contains(workout.avgHR),
                      (0...300).contains(workout.peakHR),
                      (0...300).contains(workout.p95HR),
                      (0...300).contains(workout.p99HR),
                      (0...300).contains(workout.thresholdHR),
                      (0...100).contains(workout.streamCoveragePercent),
                      workout.strain.map({ $0.isFinite && (0...21).contains($0) }) ?? true,
                      workout.activeEnergyKilocalories.map({ $0.isFinite && (0...10_000_000).contains($0) }) ?? true,
                      workout.workoutSteps.map({ $0 >= 0 && $0 <= 10_000_000 }) ?? true,
                      workout.workoutStepsCapturedAt.map(validDate) ?? true,
                      sets.count <= 100_000, exclusions.count <= 100_000,
                      exercises.count <= 100_000, zones.count <= 64,
                      exercises.allSatisfy({ validString($0, maximumBytes: 4 * 1024) }),
                      sets.allSatisfy({ validSet($0, within: workout.start, workout.end) }),
                      exclusions.allSatisfy({ validExcludedInterval($0, within: workout.start, workout.end) }),
                      zones.allSatisfy({ key, seconds in
                          validString(key, maximumBytes: 256)
                              && seconds.isFinite && seconds >= 0 && seconds <= duration + 60
                      }),
                      calibration.map({ validCalibrationEvidence($0, for: workout) }) ?? true else {
                    throw SessionBackupImportError.invalidDomain
                }
            }
        }

        if let raw = envelope.rawExport {
            let rawRows = raw.hrRows.count + raw.rrRows.count
            records += rawRows
            guard records <= maximumBackupRecords,
                  raw.schemaVersion > 0,
                  raw.schemaHeader.utf8.count <= 64 * 1024,
                  raw.schemaDocument.utf8.count <= 4 * 1024 * 1024,
                  raw.hrRows.allSatisfy({ $0.utf8.count <= 64 * 1024 }),
                  raw.rrRows.allSatisfy({ $0.utf8.count <= 64 * 1024 }),
                  raw.hrSamples >= 0, raw.rrSamples >= 0,
                  raw.sleeps >= 0, raw.workouts >= 0, raw.rollups >= 0,
                  raw.hrRows.count == raw.hrSamples,
                  raw.rrRows.count == raw.rrSamples,
                  raw.hrSamples == envelope.sessions.reduce(0, { $0 + $1.points.count }),
                  raw.rrSamples == envelope.sessions.reduce(0, { $0 + $1.rrSampleCount }),
                  raw.sleeps == (envelope.confirmedSleeps?.count ?? 0),
                  raw.workouts == (envelope.confirmedWorkouts?.count ?? 0),
                  raw.rollups == (envelope.dailyRollups?.count ?? 0) else {
                throw SessionBackupImportError.inconsistentRawExport
            }
        }
    }

    private nonisolated static func decodeSessionBackupEnvelope(at url: URL) throws -> SessionBackupEnvelope {
        try decodeSessionBackupEnvelope(from: sessionBackupPayloadData(at: url))
    }

    private nonisolated static func decodeSessionBackupEnvelope(from data: Data) throws -> SessionBackupEnvelope {
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        return try decoder.decode(SessionBackupEnvelope.self, from: data)
    }

    private nonisolated static func sessionBackupPayloadData(at url: URL) throws -> Data {
        let values = try url.resourceValues(forKeys: [.fileSizeKey, .isRegularFileKey])
        guard values.isRegularFile == true, let fileSize = values.fileSize else {
            throw CocoaError(.fileReadInvalidFileName)
        }
        let limit = url.pathExtension == "gz"
            ? AtriaBackupCompression.maximumCompressedArchiveBytes
            : AtriaBackupCompression.maximumDecodedArchiveBytes
        guard fileSize <= limit else { throw SessionBackupImportError.archiveTooLarge }
        let data = try Data(contentsOf: url)
        return try AtriaBackupCompression.archivePayloadData(from: data, fileExtension: url.pathExtension)
    }

    private nonisolated static func isSessionBackupFile(_ url: URL, includeSafetyBackups: Bool) -> Bool {
        let ext = url.pathExtension
        guard ext == "json" || ext == "gz" else { return false }
        let name = url.deletingPathExtension().deletingPathExtension().lastPathComponent
        return includeSafetyBackups || !name.hasSuffix("-pre-restore")
    }

    func sessionBackupStatus() -> SessionBackupStatus {
        cachedSessionBackupStatus
    }

    private func computeSessionBackupStatus() -> SessionBackupStatus {
        guard let latest = latestSessionBackupURL() else {
            return .missing
        }
        do {
            let data = try Self.sessionBackupPayloadData(at: latest)
            let envelope = try Self.decodeSessionBackupEnvelope(from: data)
            guard Self.supportedBackupSchemas.contains(envelope.schema) else {
                return SessionBackupStatus(available: true,
                                           current: false,
                                           path: backupRelativePath(for: latest),
                                           sessions: envelope.sessions.count,
                                           rrSamples: totalRRSamples(in: envelope.sessions),
                                           bytes: data.count,
                                           reason: "unsupported_schema_\(envelope.schema)")
            }
            let current = latestBackupMatchesCurrentStore(latest)
            return SessionBackupStatus(available: true,
                                       current: current,
                                       path: backupRelativePath(for: latest),
                                       sessions: envelope.sessions.count,
                                       rrSamples: totalRRSamples(in: envelope.sessions),
                                       bytes: data.count,
                                       reason: current ? "current" : "digest_mismatch")
        } catch {
            return SessionBackupStatus(available: true,
                                       current: false,
                                       path: backupRelativePath(for: latest),
                                       sessions: 0,
                                       rrSamples: 0,
                                       bytes: 0,
                                       reason: "decode_error")
        }
    }

    func logActivityDetectionsFromLaunchIfRequested(arguments: [String] = ProcessInfo.processInfo.arguments) {
        guard arguments.contains("--atria-log-activity-detections") else { return }
        let sourceSessions = sessions
        let confirmedWorkouts = cachedConfirmedWorkouts
        let confirmedSleeps = cachedConfirmedSleeps
        let baselineSnapshot = baseline
        let rest = baseline.restingInt ?? 60
        let maxHR = profile.maxHR
        DispatchQueue.global(qos: .utility).async {
            let snapshots = Self.makeHistorySnapshots(sessions: sourceSessions,
                                                      confirmedWorkouts: confirmedWorkouts,
                                                      confirmedSleeps: confirmedSleeps,
                                                      baseline: baselineSnapshot,
                                                      rest: rest,
                                                      maxHR: maxHR)
            Self.logActivityDetections(detections: snapshots.history.detections,
                                       sessionsCount: sourceSessions.count,
                                       rest: rest,
                                       maxHR: maxHR)
        }
    }

    private nonisolated static func logActivityDetections(detections: [ActivityDetection],
                                                          sessionsCount: Int,
                                                          rest: Int,
                                                          maxHR: Int) {
        let maxRows = 12
        let kindCounts = Dictionary(grouping: detections, by: \.kind).mapValues(\.count)
        let rankedDetections = detections.sorted { lhs, rhs in
            if confidenceRankSnapshot(lhs.confidence) != confidenceRankSnapshot(rhs.confidence) {
                return confidenceRankSnapshot(lhs.confidence) > confidenceRankSnapshot(rhs.confidence)
            }
            if kindRankSnapshot(lhs.kind) != kindRankSnapshot(rhs.kind) {
                return kindRankSnapshot(lhs.kind) > kindRankSnapshot(rhs.kind)
            }
            if lhs.duration != rhs.duration {
                return lhs.duration > rhs.duration
            }
            return lhs.peakHR > rhs.peakHR
        }
        AtriaDebugLog("ATRIADBG activity_detect_summary sessions=%d detections=%d emitted=%d suppressed=%d workouts=%d activity_candidates=%d sleep_candidates=%d rest_candidates=%d rest_hr=%d max_hr=%d",
              sessionsCount,
              detections.count,
              min(maxRows, detections.count),
              max(0, detections.count - maxRows),
              kindCounts[.workout, default: 0],
              kindCounts[.activityCandidate, default: 0],
              kindCounts[.sleepCandidate, default: 0],
              kindCounts[.restCandidate, default: 0],
              rest,
              maxHR)
        for detection in rankedDetections.prefix(maxRows) {
            AtriaDebugLog("ATRIADBG activity_detect kind=%@ confidence=%@ duration_s=%.0f avg_hr=%d peak_hr=%d reason=%@",
                  detection.kind.rawValue,
                  detection.confidence.rawValue,
                  detection.duration,
                  detection.avgHR,
                  detection.peakHR,
                  detection.reason)
        }
    }

    private nonisolated static func kindRankSnapshot(_ kind: ActivityDetection.Kind) -> Int {
        switch kind {
        case .workout: return 4
        case .sleepCandidate: return 3
        case .activityCandidate: return 2
        case .restCandidate: return 1
        }
    }

    private nonisolated static func confidenceRankSnapshot(_ confidence: ActivityDetection.Confidence) -> Int {
        switch confidence {
        case .high: return 3
        case .medium: return 2
        case .low: return 1
        }
    }

    func logWorkoutPreflightFromLaunchIfRequested(arguments: [String] = ProcessInfo.processInfo.arguments) {
        guard arguments.contains("--atria-log-workout-preflight") else { return }
        let rest = baseline.restingInt ?? 60
        let maxHR = profile.maxHR
        let reserve = max(0, maxHR - rest)
        let hrr50Threshold = SavedSession.workoutElevatedThreshold(rest: rest, maxHR: maxHR)
        let elevatedThreshold = hrr50Threshold
        let minDuration = 10 * 60
        let minElevated = min(max(Double(minDuration) * 0.35, 5 * 60), 20 * 60)
        let minBout = min(max(Double(minDuration) * 0.20, 3 * 60), 8 * 60)
        AtriaDebugLog("ATRIADBG workout_preflight rest_hr=%d max_hr=%d reserve_hr=%d threshold_hr=%d hrr50_hr=%d threshold_method=hrr50 min_duration_s=%d min_elevated_s=%.0f min_bout_s=%.0f elevated_rule=max(duration*0.35,5m)_cap20m bout_rule=max(duration*0.20,3m)_cap8m saved_sessions=%d",
              rest,
              maxHR,
              reserve,
              elevatedThreshold,
              hrr50Threshold,
              minDuration,
              minElevated,
              minBout,
              sessions.count)
    }

    func logStrainValidationFromLaunchIfRequested(arguments: [String] = ProcessInfo.processInfo.arguments) {
        guard arguments.contains("--atria-log-strain-validation") else { return }
        let rest = baseline.restingInt ?? 60
        logStrainValidation(strainValidationSummary(rest: rest, maxHR: profile.maxHR))
    }

    func strainValidationStatus(rest: Int,
                                maxHR: Int,
                                calendar: Calendar = .current) -> StrainValidationSummary {
        strainValidationSummary(rest: rest, maxHR: maxHR, calendar: calendar)
    }

    private func logStrainValidation(_ summary: StrainValidationSummary) {
        AtriaDebugLog("ATRIADBG strain_validation ready=%d rest_to_max_ready=%d primary_blocker=%@ external_hr_reference_validated=%d days=%d sessions=%d best_day=%@ best_day_sessions=%d rest_hr=%d max_hr=%d reserve_hr=%d samples=%d total_s=%.0f dropped_gap_s=%.0f stream_coverage_percent=%d z0_lt30_s=%.0f z1_30_50_s=%.0f z2_50_70_s=%.0f z3_70_85_s=%.0f z4_85_100_s=%.0f high_z3_z4_s=%.0f min_hrr=%.2f max_hrr=%.2f max_hrr_percent=%d trimp=%.2f strain=%.2f criteria=total>=600_low_z0>=60_high_z3_z4>=60_max_hrr>=0.85_stream_coverage>=75_external_hr_reference_required source=saved_sessions_grouped_by_day_no_hr_estimation",
              summary.ready ? 1 : 0,
              summary.restToMaxReady ? 1 : 0,
              summary.primaryBlocker,
              summary.externalHRReferenceValidated ? 1 : 0,
              summary.daysEvaluated,
              summary.sessionsEvaluated,
              formatDate(summary.bestDay),
              summary.bestSessions,
              summary.restHR,
              summary.maxHR,
              summary.reserveHR,
              summary.samples,
              summary.totalSeconds,
              summary.droppedGapSeconds,
              summary.streamCoveragePercent,
              summary.secondsZ0,
              summary.secondsZ1,
              summary.secondsZ2,
              summary.secondsZ3,
              summary.secondsZ4,
              summary.highZoneSeconds,
              summary.minHRReserve,
              summary.maxHRReserve,
              Int((summary.maxHRReserve * 100).rounded()),
              summary.trimp,
              summary.strain)
    }

    private func strainValidationSummary(rest: Int, maxHR: Int,
                                         calendar: Calendar = .current) -> StrainValidationSummary {
        let healthReference = HealthKitExporter.diagnostics(for: sessions,
                                                            rest: rest,
                                                            maxHR: maxHR).referenceAudit
        return Self.strainValidationSummary(sessions: sessions,
                                            rest: rest,
                                            maxHR: maxHR,
                                            externalHRReferenceValidated: externalHRReferenceValidated
                                                || healthReference.externalReferenceReady,
                                            calendar: calendar)
    }

    nonisolated static func strainValidationSummary(sessions: [SavedSession],
                                                    rest: Int,
                                                    maxHR: Int,
                                                    externalHRReferenceValidated: Bool,
                                                    calendar: Calendar = .current) -> StrainValidationSummary {
        let eligible = sessions.filter { !$0.points.isEmpty }
        guard !eligible.isEmpty, maxHR > rest else {
            return .empty(rest: rest, maxHR: maxHR, sessions: sessions.count)
        }

        var sessionsByDay: [Date: [SavedSession]] = [:]
        for session in eligible {
            for day in EventCivilTime.days(overlappedBy: session.start,
                                           end: session.end,
                                           eventTimeZoneIdentifier: session.eventTimeZoneIdentifier,
                                           outputCalendar: calendar) {
                sessionsByDay[day, default: []].append(session)
            }
        }
        let summaries = sessionsByDay.compactMap { day, daySessions -> StrainValidationSummary? in
            let loads = daySessions.compactMap { session in
                EventCivilTime.interval(forCivilDay: day,
                                        eventTimeZoneIdentifier: session.eventTimeZoneIdentifier,
                                        outputCalendar: calendar).map {
                    session.strainValidationLoad(rest: rest, max: maxHR, within: $0)
                }
            }
            let zones = loads.reduce(Metrics.StrainZoneSummary.empty) { $0 + $1.zones }
            let trimp = loads.reduce(0.0) { $0 + $1.trimp }
            let totalWithGaps = zones.totalSeconds + zones.droppedGapSeconds
            let streamCoverage = totalWithGaps > 0
                ? min(100, max(0, Int(((zones.totalSeconds / totalWithGaps) * 100).rounded())))
                : 0
            let restToMaxReady = zones.totalSeconds >= 10 * 60
                && zones.secondsZ0 >= 60
                && zones.secondsZ3 + zones.secondsZ4 >= 60
                && zones.maxHRReserve >= 0.85
                && streamCoverage >= 75
            let externalValidated = externalHRReferenceValidated
            let blocker = strainValidationBlocker(zones: zones,
                                                  streamCoveragePercent: streamCoverage,
                                                  restToMaxReady: restToMaxReady,
                                                  externalHRReferenceValidated: externalValidated)
            return StrainValidationSummary(daysEvaluated: sessionsByDay.count,
                                           sessionsEvaluated: eligible.count,
                                           bestDay: day,
                                           bestSessions: daySessions.count,
                                           restHR: rest,
                                           maxHR: maxHR,
                                           reserveHR: max(0, maxHR - rest),
                                           samples: zones.samples,
                                           totalSeconds: zones.totalSeconds,
                                           droppedGapSeconds: zones.droppedGapSeconds,
                                           streamCoveragePercent: streamCoverage,
                                           secondsZ0: zones.secondsZ0,
                                           secondsZ1: zones.secondsZ1,
                                           secondsZ2: zones.secondsZ2,
                                           secondsZ3: zones.secondsZ3,
                                           secondsZ4: zones.secondsZ4,
                                           minHRReserve: zones.minHRReserve,
                                           maxHRReserve: zones.maxHRReserve,
                                           trimp: trimp,
                                           strain: Metrics.strain(fromTRIMP: trimp),
                                           restToMaxReady: restToMaxReady,
                                           externalHRReferenceValidated: externalValidated,
                                           ready: restToMaxReady && externalValidated,
                                           primaryBlocker: blocker)
        }
        return summaries.max(by: isBetterStrainValidationSummary) ?? .empty(rest: rest, maxHR: maxHR, sessions: sessions.count)
    }

    private nonisolated static func strainValidationBlocker(zones: Metrics.StrainZoneSummary,
                                                            streamCoveragePercent: Int,
                                                            restToMaxReady: Bool,
                                                            externalHRReferenceValidated: Bool) -> String {
        if zones.samples == 0 { return "no_saved_hr_sessions" }
        var blockers: [String] = []
        if zones.totalSeconds < 10 * 60 { blockers.append("duration_below_10m") }
        if streamCoveragePercent < 75 { blockers.append("stream_coverage_below_75_percent") }
        if zones.secondsZ0 < 60 { blockers.append("missing_rest_zone_exposure") }
        if zones.secondsZ3 + zones.secondsZ4 < 60 { blockers.append("missing_high_zone_exposure") }
        if zones.maxHRReserve < 0.85 { blockers.append("max_hrr_below_85_percent") }
        if !restToMaxReady && blockers.isEmpty { blockers.append("rest_to_max_validation_missing") }
        if !externalHRReferenceValidated { blockers.append("external_hr_reference_missing") }
        return blockers.isEmpty ? "none" : blockers.joined(separator: "+")
    }

    private nonisolated static func isBetterStrainValidationSummary(_ lhs: StrainValidationSummary,
                                                                    _ rhs: StrainValidationSummary) -> Bool {
        if lhs.restToMaxReady != rhs.restToMaxReady { return !lhs.restToMaxReady && rhs.restToMaxReady }
        if lhs.highZoneSeconds != rhs.highZoneSeconds { return lhs.highZoneSeconds < rhs.highZoneSeconds }
        if lhs.maxHRReserve != rhs.maxHRReserve { return lhs.maxHRReserve < rhs.maxHRReserve }
        if lhs.totalSeconds != rhs.totalSeconds { return lhs.totalSeconds < rhs.totalSeconds }
        return lhs.droppedGapSeconds > rhs.droppedGapSeconds
    }

    private func formatDate(_ date: Date?) -> String {
        guard let date else { return "none" }
        let formatter = DateFormatter()
        formatter.calendar = Calendar.current
        formatter.dateFormat = "yyyy-MM-dd"
        return formatter.string(from: date)
    }

    /// Sum of today's saved sessions' TRIMP — combine with the live session to
    /// get day strain (strain accumulates across the whole day).
    func todayTRIMP(rest: Int,
                    max: Int,
                    calendar: Calendar = .current,
                    now: Date = Date()) -> Double {
        // Cached because the widget/day-strain publish path calls this on the ~3s
        // dashboard tick; invalidated alongside cachedHomeSavedAggregate whenever
        // the session caches refresh (refreshSessionDerivedCaches[AfterUpsert]).
        // The local day is part of the key so an always-awake phone rolls the
        // saved strain/strap-step contribution at midnight without waiting for
        // another session write.
        let day = calendar.startOfDay(for: now)
        if let cachedTodayTRIMP,
           cachedTodayTRIMP.rest == rest,
           cachedTodayTRIMP.maxHR == max,
           calendar.isDate(cachedTodayTRIMP.day, inSameDayAs: day) {
            return cachedTodayTRIMP.value
        }
        let dayEnd = calendar.date(byAdding: .day, value: 1, to: day) ?? day
        let interval = DateInterval(start: day, end: dayEnd)
        let cardio = canonicalSessions()
            .filter { $0.end > day && $0.start < dayEnd }
            .reduce(0) {
                $0 + $1.dailyLoadTRIMP(rest: rest, max: max, within: interval)
            }
        // GAP-09: the widget's day TRIMP fuses logged muscular work exactly
        // like the hero aggregate, so both surfaces show one day Strain.
        let value = cardio + Self.muscularTRIMPEquivalentTotal(
            cachedConfirmedWorkouts.filter { $0.end > day && $0.end < dayEnd }
        )
        cachedTodayTRIMP = (rest: rest, maxHR: max, day: day, value: value)
        return value
    }

    func detectedActivities(rest: Int, maxHR: Int) -> [ActivityDetection] {
        let replaySessions = canonicalSessions()
        let single = replaySessions.compactMap { $0.detectedActivity(rest: rest, maxHR: maxHR) }
        let aggregateWorkouts = aggregateWorkoutCandidates(rest: rest, maxHR: maxHR, calendar: Calendar.current)
            .filter { $0.readiness.ready || $0.readiness.reviewWorthyCandidate }
            .map { aggregate in
                let confidence: ActivityDetection.Confidence = aggregate.readiness.ready ? .medium : .low
                let reason = aggregate.readiness.ready
                    ? "Sustained HR-only effort across saved chunks; activity context unconfirmed; not counted as workout"
                    : "HR-only workout-like signal across saved chunks; \(aggregate.readiness.nearMiss ? aggregate.readiness.nearMissReason : aggregate.readiness.strengthCandidateReason); not counted as workout"
                return ActivityDetection(id: aggregate.id,
                                         kind: .activityCandidate,
                                         confidence: confidence,
                                         start: aggregate.start,
                                         end: aggregate.end,
                                         duration: aggregate.duration,
                                         avgHR: aggregate.avgHR,
                                         peakHR: aggregate.peakHR,
                                         reason: reason)
            }
        return (single + aggregateWorkouts).sorted { $0.start > $1.start }
    }

    func dailyRollups(rest: Int, maxHR: Int, calendar: Calendar = .current) -> [DailyRollup] {
        let replaySessions = canonicalSessions()
        let baselineRestingIsTrusted = baseline.restingInt != nil
            && baseline.hasTrustedRestingBaseline(now: Date())
        let grouped = Dictionary(grouping: replaySessions) { session in
            EventCivilTime.day(containing: session.start,
                               eventTimeZoneIdentifier: session.eventTimeZoneIdentifier,
                               outputCalendar: calendar)
        }
        var loadSessionsByDay: [Date: [SavedSession]] = [:]
        for session in replaySessions {
            for day in EventCivilTime.days(overlappedBy: session.start,
                                           end: session.end,
                                           eventTimeZoneIdentifier: session.eventTimeZoneIdentifier,
                                           outputCalendar: calendar) {
                loadSessionsByDay[day, default: []].append(session)
            }
        }
        // Live and historical projections must apply the identical user-facing
        // sleep review gate. Raw aggregation deliberately retains ambiguous
        // quiet/rest windows for diagnostics; letting that raw set reach the
        // live rollup could resurrect a candidate the history view correctly
        // rejected as not review-worthy.
        let aggregateSleeps = Self.preferredSleepCandidatesByDay(
            aggregateSleepCandidates(rest: rest,
                                     calendar: calendar,
                                     historicalMotionPolicy: .boundedRecent)
                .filter(Self.isReviewWorthySleepCandidate)
        )
        let aggregateCandidatesByDay = Dictionary(grouping: aggregateWorkoutCandidates(rest: rest, maxHR: maxHR, calendar: calendar).filter {
            $0.readiness.ready || $0.readiness.reviewWorthyCandidate
        }) { candidate in
            candidate.day
        }
        let confirmedWorkoutsByDay = Dictionary(grouping: cachedConfirmedWorkouts) { workout in
            EventCivilTime.day(containing: workout.start,
                               eventTimeZoneIdentifier: workout.eventTimeZoneIdentifier,
                               outputCalendar: calendar)
        }
        // Confirmed workouts may intentionally be metadata-only after a strap
        // dropout. Their day must still exist in the live rollup projection;
        // otherwise Activity and the day-level surfaces disagree about whether
        // the saved workout happened.
        let rollupDays = Set(grouped.keys)
            .union(loadSessionsByDay.keys)
            .union(aggregateSleeps.keys)
            .union(confirmedWorkoutsByDay.keys)
        return rollupDays.map { day in
            let daySessions = grouped[day] ?? []
            let dayLoadSessions = loadSessionsByDay[day] ?? []
            let detections = daySessions.compactMap { $0.detectedActivity(rest: rest, maxHR: maxHR, calendar: calendar) }
            let detectionsBySessionID = Dictionary(detections.map { ($0.id, $0) },
                                                   uniquingKeysWith: { first, _ in first })
            let aggregateCandidates = aggregateCandidatesByDay[day] ?? []
            // Sensor-only readiness remains a review candidate. Confirmed
            // workouts have their own durable counter below and are the only
            // activity rows allowed to claim that a workout happened.
            let workouts = 0
            let singleActivityCandidates = detections.filter { $0.kind == .activityCandidate }.count
            let aggregateActivityDay = aggregateCandidates.isEmpty ? 0 : 1
            let activityCandidates = max(singleActivityCandidates, aggregateActivityDay)
            let restCandidates = detections.filter { $0.kind == .restCandidate }.count
            let singleSessionSleepCandidates = detections.filter { $0.kind == .sleepCandidate }.count
            let aggregateSleep = aggregateSleeps[day]
            // A rollup is ready only when either the motion-backed gate or the
            // narrow physiological HR-only main-sleep gate can persist it.
            let aggregateSleepReady = (aggregateSleep.map {
                Self.isAutoConfirmableMainSleepCandidate(
                    $0,
                    baselineRestingIsTrusted: baselineRestingIsTrusted
                )
            } == true) ? 1 : 0
            let sleepCandidates = max(singleSessionSleepCandidates, aggregateSleep == nil ? 0 : 1)
            let singleSessionSleepDuration = detections
                .filter { $0.kind == .sleepCandidate }
                .reduce(0) { $0 + $1.duration }
            let sleepDetections = detections.filter { $0.kind == .sleepCandidate }
            let sleepStart = aggregateSleep?.start ?? sleepDetections.map(\.start).min()
            let sleepEnd = aggregateSleep?.end ?? sleepDetections.map(\.end).max()
            let singleSessionSleepSpan = Self.sleepSpan(duration: singleSessionSleepDuration,
                                                        start: sleepDetections.map(\.start).min(),
                                                        end: sleepDetections.map(\.end).max())
            let sleepStageSegments = aggregateSleep.map { candidate in
                Self.sleepStageResearchSegments(from: daySessions,
                                                start: candidate.start,
                                                end: candidate.end,
                                                restingHR: candidate.restingHR,
                                                isNap: candidate.kind == "nap_candidate",
                                                motionValidated: candidate.motionEvidenceValidated)
            } ?? []
            let dayIntervals = dayLoadSessions.compactMap { session in
                EventCivilTime.interval(forCivilDay: day,
                                        eventTimeZoneIdentifier: session.eventTimeZoneIdentifier,
                                        outputCalendar: calendar).map { (session, $0) }
            }
            let duration = dayIntervals.reduce(0.0) { total, pair in
                let (session, interval) = pair
                return total + max(0, min(session.end, interval.end)
                    .timeIntervalSince(max(session.start, interval.start)))
            }
            let strainTRIMP = dayIntervals.reduce(0.0) { total, pair in
                total + pair.0.dailyLoadTRIMP(rest: rest, max: maxHR, within: pair.1)
            }
            let hrvs = daySessions.compactMap(\.localRMSSD).filter { $0 > 0 }
            let hrvWindowCount = daySessions.reduce(0) {
                $0 + $1.localHRVWindowCount
            }
            let respiratoryRates = daySessions.compactMap {
                $0.sleepRespiratoryRate(rest: rest, maxHR: maxHR, calendar: calendar)
            }
            let sleepRHRs = daySessions.compactMap { session -> Int? in
                guard detectionsBySessionID[session.id]?.kind == .sleepCandidate else {
                    return nil
                }
                return session.sleepCandidateRestingHR
            }.filter { $0 > 0 }
            let fallbackRHRs = daySessions.map(\.restingStable).filter { $0 > 0 }
            return DailyRollup(day: day,
                               sessions: dayLoadSessions.count,
                               activityCandidates: activityCandidates,
                               workouts: workouts,
                               confirmedWorkouts: confirmedWorkoutsByDay[day]?.count ?? 0,
                               restCandidates: restCandidates,
                               sleepReady: aggregateSleepReady,
                               sleepCandidates: sleepCandidates,
                               duration: duration,
                               sleepDuration: aggregateSleep?.duration ?? (singleSessionSleepDuration > 0 ? singleSessionSleepDuration : nil),
                               sleepSpan: aggregateSleep?.span ?? singleSessionSleepSpan,
                               sleepStart: sleepStart,
                               sleepEnd: sleepEnd,
                               sleepSource: aggregateSleep?.kind ?? (singleSessionSleepDuration > 0 ? "single_session_sleep_candidate" : nil),
                               sleepStageSegments: sleepStageSegments,
                               strain: Metrics.strain(fromTRIMP: strainTRIMP),
                               avgHRV: averageInt(hrvs),
                               hrvWindowCount: hrvWindowCount,
                               restingHR: aggregateSleep?.restingHR ?? sleepRHRs.min() ?? fallbackRHRs.min(),
                               avgRespiratoryRate: averageDouble(respiratoryRates))
        }
        .sorted { $0.day > $1.day }
    }

    func aggregateWorkoutCandidates(rest: Int,
                                    maxHR: Int,
                                    calendar: Calendar = .current,
                                    thresholdFraction: Double = 0.50) -> [AggregateWorkoutCandidate] {
        Self.aggregateWorkoutCandidates(in: canonicalSessions(),
                                        rest: rest,
                                        maxHR: maxHR,
                                        calendar: calendar,
                                        thresholdFraction: thresholdFraction)
    }

    private nonisolated static func aggregateWorkoutCandidates(in sessions: [SavedSession],
                                                               rest: Int,
                                                               maxHR: Int,
                                                               calendar: Calendar = .current,
                                                               thresholdFraction: Double = 0.50) -> [AggregateWorkoutCandidate] {
        // Key exactly the corpus the operation consumes. In particular, the
        // independently reconstructed >6 h active journal is intentionally
        // outside workout-chunk aggregation; including its fresh array address
        // made History and review miss the launch rendezvous even though both
        // performed identical useful work.
        let eligible = sessions.filter {
            !$0.points.isEmpty && $0.duration >= 60 && $0.duration <= 6 * 3600
        }
        let key = AtriaWorkoutAggregateFlightKey(
            sessions: eligible.map(
                AtriaWorkoutAggregateSessionFlightIdentity.init
            ),
            rest: rest,
            maxHR: maxHR,
            thresholdFractionBitPattern: thresholdFraction.bitPattern,
            calendarIdentifier: String(describing: calendar.identifier),
            calendarTimeZoneIdentifier: calendar.timeZone.identifier,
            calendarLocaleIdentifier: calendar.locale?.identifier,
            firstWeekday: calendar.firstWeekday,
            minimumDaysInFirstWeek: calendar.minimumDaysInFirstWeek
        )
        return workoutAggregateSingleFlight.run(
            key: key,
            retaining: eligible
        ) {
            aggregateWorkoutCandidatesUnshared(
                in: eligible,
                rest: rest,
                maxHR: maxHR,
                calendar: calendar,
                thresholdFraction: thresholdFraction
            )
        }
    }

    private nonisolated static func aggregateWorkoutCandidatesUnshared(
        in sessions: [SavedSession],
        rest: Int,
        maxHR: Int,
        calendar: Calendar,
        thresholdFraction: Double
    ) -> [AggregateWorkoutCandidate] {
        // Upper bound (2026-08-05, cold-launch burst root): aggregation
        // exists to stitch SHORT chunks into one workout. An all-day
        // recovered wear session is not a workout chunk — clustering it
        // copied+sorted ~a day of points three ways per cluster and was the
        // ignition inside hist_stage=detections. Single-session readiness
        // still evaluates long sessions on their own path.
        let grouped = Dictionary(grouping: sessions) { session in
            EventCivilTime.day(containing: session.start,
                               eventTimeZoneIdentifier: session.eventTimeZoneIdentifier,
                               outputCalendar: calendar)
        }
        let clusterPlans: [(day: Date, ordered: [SavedSession])] =
            grouped.flatMap { day, daySessions in
                workoutClusters(from: daySessions, maxGap: 30 * 60).map {
                    (day: day, ordered: $0.sorted(
                        by: AtriaWorkoutAggregateSessionFlightIdentity.canonicalOrder
                    ))
                }
            }
            // Evaluate newest common work first so History's superset and the
            // 24-hour review slice rendezvous before History continues through
            // its older, independently retained detections.
            .sorted { lhs, rhs in
                if lhs.day != rhs.day { return lhs.day > rhs.day }
                let lhsStart = lhs.ordered.first?.start ?? .distantPast
                let rhsStart = rhs.ordered.first?.start ?? .distantPast
                if lhsStart != rhsStart { return lhsStart > rhsStart }
                let lhsEnd = lhs.ordered.last?.end ?? .distantPast
                let rhsEnd = rhs.ordered.last?.end ?? .distantPast
                return lhsEnd > rhsEnd
            }

        return clusterPlans.flatMap { plan -> [AggregateWorkoutCandidate] in
            let day = plan.day
            let ordered = plan.ordered
            let clusterKey = AtriaWorkoutAggregateClusterFlightKey(
                orderedSessions: ordered.map(
                    AtriaWorkoutAggregateSessionFlightIdentity.init
                ),
                dayBitPattern: day.timeIntervalSinceReferenceDate.bitPattern,
                rest: rest,
                maxHR: maxHR,
                thresholdFractionBitPattern: thresholdFraction.bitPattern,
                calendarIdentifier: String(describing: calendar.identifier),
                calendarTimeZoneIdentifier: calendar.timeZone.identifier,
                calendarLocaleIdentifier: calendar.locale?.identifier,
                firstWeekday: calendar.firstWeekday,
                minimumDaysInFirstWeek: calendar.minimumDaysInFirstWeek
            )
            return workoutAggregateClusterSingleFlight.run(
                key: clusterKey,
                retaining: ordered
            ) {
              // Per-cluster dying thread (2026-08-05, THE cold-launch burst):
              // an all-day recovered cluster copies + sorts its whole day of
              // points and replays readiness up to three ways; ~14 day
              // clusters summed in one thread stretch was the ~2GB ignition
              // inside hist_stage=detections. Each cluster's garbage now dies
              // before the next cluster starts.
              AtriaTransientWorkThread.run(name: "atria.aggregate-cluster") { () -> [AggregateWorkoutCandidate] in
                guard let start = ordered.map(\.start).min(),
                      let end = ordered.map(\.end).max() else { return [] }
                let points = ordered.flatMap { session in
                    session.points.map { point in
                        SavedSession.Point(t: session.start.addingTimeInterval(point.t).timeIntervalSince(start),
                                           bpm: point.bpm)
                    }
                }.sorted { lhs, rhs in
                    if lhs.t != rhs.t { return lhs.t < rhs.t }
                    return lhs.bpm < rhs.bpm
                }
                guard points.count >= 2 else { return [] }
                let labels = Array(Set(ordered.map(\.label))).sorted()
                let label: String
                if labels.count == 1 {
                    label = ordered.count == 1 ? labels[0] : "\(labels[0]) aggregate"
                } else if let first = labels.first {
                    label = "\(first) + \(labels.count - 1) chunks"
                } else {
                    label = "Workout aggregate"
                }
                var candidates: [AggregateWorkoutCandidate] = []
                if ordered.count > 1,
                   let wholeCluster = makeAggregateWorkoutCandidate(source: "aggregate_chunks",
                                                                    day: day,
                                                                    ordered: ordered,
                                                                    labels: labels,
                                                                    label: label,
                                                                    start: start,
                                                                    end: end,
                                                                    points: points,
                                                                    rest: rest,
                                                                    maxHR: maxHR,
                                                                    thresholdFraction: thresholdFraction) {
                    candidates.append(wholeCluster)
                }
                if ordered.count > 1,
                   let stitchedPoints = stitchedObservedWorkoutPoints(from: ordered),
                   let stitchedCluster = makeAggregateWorkoutCandidate(source: "stitched_observed_chunks",
                                                                       day: day,
                                                                       ordered: ordered,
                                                                       labels: labels,
                                                                       label: "\(label) observed",
                                                                       start: start,
                                                                       end: start.addingTimeInterval(stitchedPoints.duration),
                                                                       points: stitchedPoints.points,
                                                                       rest: rest,
                                                                       maxHR: maxHR,
                                                                       thresholdFraction: thresholdFraction) {
                    candidates.append(AggregateWorkoutCandidate(id: stitchedCluster.id,
                                                               source: stitchedCluster.source,
                                                               day: stitchedCluster.day,
                                                               sessions: stitchedCluster.sessions,
                                                               labels: stitchedCluster.labels,
                                                               label: stitchedCluster.label,
                                                               start: start,
                                                               end: end,
                                                               duration: stitchedCluster.duration,
                                                               span: end.timeIntervalSince(start),
                                                               samples: stitchedCluster.samples,
                                                               avgHR: stitchedCluster.avgHR,
                                                               peakHR: stitchedCluster.peakHR,
                                                               hrRaw2A37: stitchedCluster.hrRaw2A37,
                                                               hrAccepted: stitchedCluster.hrAccepted,
                                                               hrZero: stitchedCluster.hrZero,
                                                               hrArtifactHeld: stitchedCluster.hrArtifactHeld,
                                                               hrArtifactDropped: stitchedCluster.hrArtifactDropped,
                                                               hrRawGaps: stitchedCluster.hrRawGaps,
                                                               hrAcceptedGaps: stitchedCluster.hrAcceptedGaps,
                                                               hrMaxRawGap: stitchedCluster.hrMaxRawGap,
                                                               hrMaxAcceptedGap: stitchedCluster.hrMaxAcceptedGap,
                                                               hrRRMismatch: stitchedCluster.hrRRMismatch,
                                                               readiness: stitchedCluster.readiness))
                }
                candidates.append(contentsOf: windowedWorkoutCandidates(day: day,
                                                                        ordered: ordered,
                                                                        labels: labels,
                                                                        clusterLabel: label,
                                                                        rest: rest,
                                                                        maxHR: maxHR,
                                                                        thresholdFraction: thresholdFraction))
                return candidates
              }
            }
        }
        .sorted { lhs, rhs in
            if lhs.readiness.ready != rhs.readiness.ready { return lhs.readiness.ready }
            if lhs.readiness.longestElevatedBout != rhs.readiness.longestElevatedBout {
                return lhs.readiness.longestElevatedBout > rhs.readiness.longestElevatedBout
            }
            if lhs.readiness.elevatedSeconds != rhs.readiness.elevatedSeconds {
                return lhs.readiness.elevatedSeconds > rhs.readiness.elevatedSeconds
            }
            if lhs.readiness.borderlineLongestBout != rhs.readiness.borderlineLongestBout {
                return lhs.readiness.borderlineLongestBout > rhs.readiness.borderlineLongestBout
            }
            if lhs.readiness.borderlineElevatedSeconds != rhs.readiness.borderlineElevatedSeconds {
                return lhs.readiness.borderlineElevatedSeconds > rhs.readiness.borderlineElevatedSeconds
            }
            if lhs.peakHR != rhs.peakHR {
                return lhs.peakHR > rhs.peakHR
            }
            if lhs.readiness.streamCoveragePercent != rhs.readiness.streamCoveragePercent {
                return lhs.readiness.streamCoveragePercent > rhs.readiness.streamCoveragePercent
            }
            return lhs.start > rhs.start
        }
    }

