    private nonisolated static func stitchedObservedWorkoutPoints(from sessions: [SavedSession]) -> (points: [SavedSession.Point], duration: TimeInterval)? {
        var stitched: [SavedSession.Point] = []
        var cursor: TimeInterval = 0
        let resetGap = SavedSession.workoutContinuityGapLimit + 1
        for session in sessions.sorted(
            by: AtriaWorkoutAggregateSessionFlightIdentity.canonicalOrder
        ) {
            let points = session.points.sorted { lhs, rhs in
                if lhs.t != rhs.t { return lhs.t < rhs.t }
                return lhs.bpm < rhs.bpm
            }
            guard let first = points.first else { continue }
            var previous = first
            stitched.append(SavedSession.Point(t: cursor, bpm: first.bpm))
            for point in points.dropFirst() {
                let dt = max(0, point.t - previous.t)
                cursor += dt > SavedSession.workoutContinuityGapLimit ? resetGap : dt
                stitched.append(SavedSession.Point(t: cursor, bpm: point.bpm))
                previous = point
            }
            cursor += resetGap
        }
        guard stitched.count >= 2, let last = stitched.last else { return nil }
        return (stitched, last.t)
    }

    private nonisolated static func makeAggregateWorkoutCandidate(source: String,
                                               day: Date,
                                               ordered: [SavedSession],
                                               labels: [String],
                                               label: String,
                                               start: Date,
                                               end: Date,
                                               points: [SavedSession.Point],
                                               rest: Int,
                                               maxHR: Int,
                                               thresholdFraction: Double) -> AggregateWorkoutCandidate? {
        guard points.count >= 2, end > start else { return nil }
        let aggregate = SavedSession(id: ordered.first?.id ?? UUID(),
                                     start: start,
                                     end: end,
                                     label: label,
                                     points: points,
                                     hrv: nil,
                                     rrPoints: nil,
                                     hrvReferenceValidated: false,
                                     motionHintCount: ordered.reduce(0) { $0 + $1.motionHintCountValue },
                                     motionHintKinds: Self.motionHintKindsSummary(for: ordered),
                                     motionEvidenceSource: ordered.contains { $0.motionHintCountValue > 0 } ? "diagnostic_observe_only" : "unavailable",
                                     motionEvidenceValidated: false,
                                     motionShortCount: nil,
                                     motionShortMean: nil,
                                     motionShortMin: nil,
                                     motionShortMax: nil,
                                     motionShortOverOneCount: nil,
                                     hrRaw2A37: ordered.reduce(0) { $0 + $1.hrRaw2A37Value },
                                     hrAccepted: ordered.reduce(0) { $0 + $1.hrAcceptedValue },
                                     hrZero: ordered.reduce(0) { $0 + $1.hrZeroValue },
                                     hrArtifactHeld: ordered.reduce(0) { $0 + $1.hrArtifactHeldValue },
                                     hrArtifactDropped: ordered.reduce(0) { $0 + $1.hrArtifactDroppedValue },
                                     hrRawGaps: ordered.reduce(0) { $0 + $1.hrRawGapsValue },
                                     hrAcceptedGaps: ordered.reduce(0) { $0 + $1.hrAcceptedGapsValue },
                                     hrMaxRawGap: ordered.map(\.hrMaxRawGapValue).max() ?? 0,
                                     hrMaxAcceptedGap: ordered.map(\.hrMaxAcceptedGapValue).max() ?? 0,
                                     hrRRMismatch: ordered.reduce(0) { $0 + $1.hrRRMismatchValue },
                                     eventTimeZoneIdentifier: ordered.first?.eventTimeZoneIdentifier)
        // Contact-artifact hardening (2026-07-05): judge the WORST source
        // chunk, not the diluted/summed aggregate -- stitching keeps only the
        // contact-present chunks, so summed artifact/zero shares can dilute
        // below the ceilings even when one source chunk was compromised. Also
        // restore an RR gate for aggregates: the synthetic `aggregate` session
        // above always carries `rrPoints: nil`, so its own rrSampleCount/
        // hrRRDisagreesWithReportedHR are structurally blind; substitute the
        // sum/OR of the real source sessions.
        let anyChunkContactCompromised = ordered.contains { $0.hrContactCompromised }
        let anyChunkRRDisagreement = ordered.contains { $0.hrRRDisagreesWithReportedHR }
        let sourceRRSampleCount = ordered.reduce(0) { $0 + $1.rrSampleCount }
        let readiness = aggregate.workoutReadiness(rest: rest,
                                                   maxHR: maxHR,
                                                   thresholdFraction: thresholdFraction,
                                                   contactCompromisedOverride: anyChunkContactCompromised || aggregate.hrContactCompromised,
                                                   rrDisagreementOverride: anyChunkRRDisagreement || aggregate.hrRRDisagreesWithReportedHR,
                                                   rrSampleCountOverride: sourceRRSampleCount)
        return AggregateWorkoutCandidate(id: aggregate.id,
                                         source: source,
                                         day: day,
                                         sessions: ordered.count,
                                         labels: labels,
                                         label: label,
                                         start: start,
                                         end: end,
                                         duration: aggregate.duration,
                                         span: end.timeIntervalSince(start),
                                         samples: points.count,
                                         avgHR: aggregate.avg,
                                         peakHR: aggregate.peak,
                                         hrRaw2A37: aggregate.hrRaw2A37Value,
                                         hrAccepted: aggregate.hrAcceptedValue,
                                         hrZero: aggregate.hrZeroValue,
                                         hrArtifactHeld: aggregate.hrArtifactHeldValue,
                                         hrArtifactDropped: aggregate.hrArtifactDroppedValue,
                                         hrRawGaps: aggregate.hrRawGapsValue,
                                         hrAcceptedGaps: aggregate.hrAcceptedGapsValue,
                                         hrMaxRawGap: aggregate.hrMaxRawGapValue,
                                         hrMaxAcceptedGap: aggregate.hrMaxAcceptedGapValue,
                                         hrRRMismatch: aggregate.hrRRMismatchValue,
                                         readiness: readiness)
    }

    private nonisolated static func windowedWorkoutCandidates(day: Date,
                                           ordered: [SavedSession],
                                           labels: [String],
                                           clusterLabel: String,
                                           rest: Int,
                                           maxHR: Int,
                                           thresholdFraction: Double) -> [AggregateWorkoutCandidate] {
        let absolutePoints = ordered.flatMap { session in
            session.points.map { point in
                (date: session.start.addingTimeInterval(point.t), bpm: point.bpm)
            }
        }
        .sorted { lhs, rhs in
            if lhs.date != rhs.date { return lhs.date < rhs.date }
            return lhs.bpm < rhs.bpm
        }
        guard let clusterStart = absolutePoints.first?.date,
              let clusterEnd = absolutePoints.last?.date,
              clusterEnd.timeIntervalSince(clusterStart) >= 10 * 60 else { return [] }
        // Span SLICING (2026-08-05, replaces the blanket span ceiling from the
        // allocation audit): the ceiling's `return []` for >6h clusters erased
        // real detections — the captured July-27 physical walk sat inside a
        // 17-hour all-day wear cluster and its bounded ready review vanished
        // (AtriaDetectedActivityReviewTests pinned it; bisect-proven). The
        // memory concern the ceiling fixed (per-window point copies × ~3k
        // windows over an unbounded span) is preserved by sweeping ≤6h time
        // slices instead: each slice's copy cost is exactly the old ceiling's
        // bound, slices step by 4.5h so the 90-minute maximum window can
        // never straddle two boundaries unseen, and the dedupe set spans
        // slices so overlap regions yield one candidate.
        let durations: [TimeInterval] = [10, 20, 30, 45, 60, 90].map { $0 * 60 }
        let minimumDuration = 10 * 60.0
        let coarseStep: TimeInterval = 5 * 60
        let fineStep: TimeInterval = 60
        let sliceSpan: TimeInterval = 6 * 3600
        let sliceStride: TimeInterval = sliceSpan - (durations.last ?? 5_400)
        var sliceRanges: [(start: Date, end: Date)] = []
        if clusterEnd.timeIntervalSince(clusterStart) <= sliceSpan {
            sliceRanges = [(clusterStart, clusterEnd)]
        } else {
            var sliceStart = clusterStart
            while sliceStart < clusterEnd {
                sliceRanges.append((sliceStart,
                                    min(sliceStart.addingTimeInterval(sliceSpan),
                                        clusterEnd)))
                sliceStart = sliceStart.addingTimeInterval(sliceStride)
            }
        }
        var candidates: [AggregateWorkoutCandidate] = []
        var seenActual = Set<String>()
        for slice in sliceRanges {
        let slicePoints = absolutePoints.filter {
            $0.date >= slice.start && $0.date <= slice.end
        }
        guard let sliceFirst = slicePoints.first?.date,
              let sliceLast = slicePoints.last?.date,
              sliceLast.timeIntervalSince(sliceFirst) >= 10 * 60 else { continue }
        let absolutePoints = slicePoints
        let clusterStart = sliceFirst
        let clusterEnd = sliceLast
        _ = clusterStart
        let absoluteDates = absolutePoints.map(\.date)
        // A short effort can begin between the legacy five-minute anchors.
        // Search only the minimum detector window at one-minute resolution;
        // longer windows keep the coarser cadence so all-day journals do not
        // multiply replay cost. A bounded ready window then outranks the
        // overlapping low-confidence all-day journal without weakening the
        // separate strength-review gate.
        let coarseStartIndices = Set(workoutWindowStartIndices(from: absoluteDates,
                                                               step: coarseStep))
        let fineStartIndices = Set(workoutWindowStartIndices(from: absoluteDates,
                                                             step: fineStep))
        let startIndices = coarseStartIndices.union(fineStartIndices).sorted()
        for startIndex in startIndices {
            let nominalStart = absoluteDates[startIndex]
            let allowedDurations = coarseStartIndices.contains(startIndex)
                ? durations
                : [minimumDuration]
            for duration in allowedDurations where duration <= clusterEnd.timeIntervalSince(clusterStart) {
                let nominalEnd = nominalStart.addingTimeInterval(duration)
                if nominalEnd > clusterEnd { break }
                guard let endIndex = firstWorkoutWindowIndex(atOrAfter: nominalEnd,
                                                             in: absoluteDates,
                                                             lowerBound: startIndex + 1) else { break }
                let actualStart = absolutePoints[startIndex].date
                let actualEnd = absolutePoints[endIndex].date
                let span = actualEnd.timeIntervalSince(actualStart)
                if span < 10 * 60 { continue }
                if span > durations.last ?? duration { break }
                let key = "\(Int(actualStart.timeIntervalSince1970.rounded())):\(Int(actualEnd.timeIntervalSince1970.rounded()))"
                guard seenActual.insert(key).inserted else { continue }
                let points = absolutePoints[startIndex...endIndex].map {
                    SavedSession.Point(t: $0.date.timeIntervalSince(actualStart), bpm: $0.bpm)
                }
                let windowSessions = ordered.filter { session in
                    session.end >= actualStart && session.start <= actualEnd
                }
                let windowLabel = "\(clusterLabel) window"
                if let candidate = makeAggregateWorkoutCandidate(source: "windowed_workout",
                                                                 day: day,
                                                                 ordered: windowSessions.isEmpty ? ordered : windowSessions,
                                                                 labels: labels,
                                                                 label: windowLabel,
                                                                 start: actualStart,
                                                                 end: actualEnd,
                                                                 points: points,
                                                                 rest: rest,
                                                                 maxHR: maxHR,
                                                                 thresholdFraction: thresholdFraction) {
                    candidates.append(candidate)
                }
            }
        }
        }
        return candidates
    }

    private nonisolated static func workoutWindowStartIndices(from dates: [Date], step: TimeInterval) -> [Int] {
        guard let first = dates.first else { return [] }
        var indices: [Int] = []
        var nextStart = first
        for (index, date) in dates.enumerated() {
            if date >= nextStart {
                indices.append(index)
                nextStart = date.addingTimeInterval(step)
            }
        }
        return indices
    }

    private nonisolated static func firstWorkoutWindowIndex(atOrAfter target: Date,
                                         in dates: [Date],
                                         lowerBound: Int) -> Int? {
        var left = max(0, lowerBound)
        var right = dates.count
        while left < right {
            let middle = (left + right) / 2
            if dates[middle] < target {
                left = middle + 1
            } else {
                right = middle
            }
        }
        return left < dates.count ? left : nil
    }

    enum HistoricalSleepMotionPolicy {
        case fullArchive
        case boundedRecent
        /// External motion reads are forbidden, but timestamped compact epochs
        /// already attached to each bounded session remain authoritative.
        /// Unlike deterministic replay, the small device-use journal may still
        /// clamp a provably awake leading edge.
        case attachedCompactOnly
        /// Deterministic saved-record replay. Only motion provenance embedded in
        /// the decoded sessions may participate; mutable on-device archives are
        /// deliberately excluded from the result.
        case sessionOnly
    }

    func aggregateSleepCandidates(rest: Int,
                                  calendar: Calendar = .current,
                                  historicalMotionPolicy: HistoricalSleepMotionPolicy = .boundedRecent) -> [AggregateSleepCandidate] {
        Self.aggregateSleepCandidates(in: canonicalSessions(),
                                      rest: rest,
                                      maxHR: profile.maxHR,
                                      calendar: calendar,
                                      historicalMotionPolicy: historicalMotionPolicy)
    }

    /// 2026-08-06 sleep-onset device-use clamp (user-caught): the detector
    /// claimed a 12:53am onset while the wearer was demonstrably awake using
    /// the unlocked phone until well after 2am — low-HR still time in bed
    /// passes every HR gate. The device being unlocked and in use is
    /// near-certain wakefulness, so a sustained-use interval overlapping the
    /// candidate's LEADING edge moves onset to that use's end plus a settle
    /// margin. Leading edge only: trailing/middle use is left to the existing
    /// wake detection. Pure logic; the caller supplies journal intervals, and
    /// an empty `sustainedUse` (no journal data / no coverage) is exact
    /// identity — absence of journal data is never evidence of sleep.
    nonisolated static let sleepOnsetClampSettleMargin: TimeInterval = 5 * 60
    nonisolated static let sleepOnsetClampMinimumSustainedUse: TimeInterval = 180

    nonisolated static func clampedSleepOnset(start: Date,
                                              end: Date,
                                              sustainedUse: [DateInterval],
                                              minimumRetainedDuration: TimeInterval,
                                              settleMargin: TimeInterval = SessionStore.sleepOnsetClampSettleMargin) -> Date {
        guard end > start, !sustainedUse.isEmpty else { return start }
        var clamped = start
        for use in sustainedUse.sorted(by: { $0.start < $1.start }) {
            // Leading-edge chain: an interval clamps only when it covers the
            // current onset point (including the settle margin already applied
            // by a previous interval). Use strictly after the settled onset is
            // middle-of-night use and is deliberately left alone.
            guard use.start <= clamped, use.end > clamped else { continue }
            clamped = use.end.addingTimeInterval(settleMargin)
        }
        // Never clamp past (end - minimum sleep duration): the clamp bounds
        // the claimed onset, it never erases an entire qualifying sleep.
        let latestAllowed = end.addingTimeInterval(-minimumRetainedDuration)
        clamped = min(clamped, latestAllowed)
        return clamped > start ? clamped : start
    }

    nonisolated static func aggregateSleepCandidates(
        in sourceSessions: [SavedSession],
        rest: Int,
        maxHR: Int,
        calendar: Calendar = .current,
        historicalMotionPolicy: HistoricalSleepMotionPolicy = .boundedRecent
    ) -> [AggregateSleepCandidate] {
        // An absent deadline preserves the legacy result exactly.
        (try? aggregateSleepCandidatesCore(
            in: sourceSessions,
            rest: rest,
            maxHR: maxHR,
            calendar: calendar,
            historicalMotionPolicy: historicalMotionPolicy,
            cooperativeDeadline: nil,
            includeResumedReviewCandidates: true
        )) ?? []
    }

    nonisolated static func aggregateSleepCandidates(
        in sourceSessions: [SavedSession],
        rest: Int,
        maxHR: Int,
        calendar: Calendar = .current,
        historicalMotionPolicy: HistoricalSleepMotionPolicy,
        cooperativeDeadline: AtriaSleepSettlementDeadline,
        includeResumedReviewCandidates: Bool = false
    ) throws -> [AggregateSleepCandidate] {
        try aggregateSleepCandidatesCore(
            in: sourceSessions,
            rest: rest,
            maxHR: maxHR,
            calendar: calendar,
            historicalMotionPolicy: historicalMotionPolicy,
            cooperativeDeadline: cooperativeDeadline,
            includeResumedReviewCandidates: includeResumedReviewCandidates
        )
    }

    private nonisolated static func aggregateSleepCandidatesCore(
        in sourceSessions: [SavedSession],
        rest: Int,
        maxHR: Int,
        calendar: Calendar,
        historicalMotionPolicy: HistoricalSleepMotionPolicy,
        cooperativeDeadline: AtriaSleepSettlementDeadline?,
        includeResumedReviewCandidates: Bool
    ) throws -> [AggregateSleepCandidate] {
        try cooperativeDeadline?.checkpoint()
        var fullArchiveMotionSnapshot: HistoricalArchive.MotionArchiveSnapshot?
        func historicalMotionDiagnostics(start: Date, end: Date) -> HistoricalArchive.MotionWindowDiagnostics {
            switch historicalMotionPolicy {
            case .fullArchive:
                guard !Thread.isMainThread else {
                    return HistoricalArchive.motionWindowDiagnostics(start: start, end: end)
                }
                if fullArchiveMotionSnapshot == nil {
                    fullArchiveMotionSnapshot = HistoricalArchive.makeMotionArchiveSnapshot()
                }
                return fullArchiveMotionSnapshot!.diagnostics(start: start, end: end)
            case .boundedRecent:
                return HistoricalArchive.boundedMotionWindowDiagnostics(start: start, end: end)
            case .attachedCompactOnly, .sessionOnly:
                return HistoricalArchive.MotionWindowDiagnostics(
                    status: historicalMotionPolicy == .sessionOnly
                        ? "session_only" : "attached_compact_only",
                    reason: "external motion archive excluded from deterministic replay",
                    rows: 0,
                    validatedRows: 0,
                    coverageSeconds: 0,
                    spanSeconds: max(0, Int(end.timeIntervalSince(start))),
                    meanVectorDelta: nil,
                    p95VectorDelta: nil,
                    magnitudeMean: nil,
                    magnitudeStdDev: nil,
                    archiveFirstUnix: 0,
                    archiveLastUnix: 0,
                    nearestSeparationSeconds: 0,
                    lowMotionReady: false
                )
            }
        }
        var eligible: [SavedSession] = []
        eligible.reserveCapacity(sourceSessions.count)
        var sessionHRStats: [UUID: CooperativeBPMStats] = [:]
        sessionHRStats.reserveCapacity(sourceSessions.count)
        for session in sourceSessions {
            try cooperativeDeadline?.checkpoint()
            let isEligible: Bool = try {
            () throws -> Bool in
            guard session.duration >= AggregateSleepCandidate.minimumFragmentDuration,
                  !session.points.isEmpty else { return false }
            // Eligibility must be robust to an isolated optical/contact spike.
            // Using the raw maximum here used to discard an entire otherwise
            // low-HR sleep fragment before the cluster-level median/P90 and
            // elevated-fraction checks ever had a chance to evaluate it.
            let bpmStats = try session.cooperativeBPMStats(
                cooperativeDeadline: cooperativeDeadline
            )
            sessionHRStats[session.id] = bpmStats
            let sessionHR = bpmStats.values
            let sessionP05 = Self.percentileHR(
                0.05,
                presorted: bpmStats.sortedValues
            )
            let sessionP90 = Self.percentileHR(
                0.90,
                presorted: bpmStats.sortedValues
            )
            var elevatedCount = 0
            for (index, bpm) in sessionHR.enumerated() {
                if index.isMultiple(of: 256) {
                    try cooperativeDeadline?.checkpoint()
                }
                if bpm >= rest + 35 { elevatedCount += 1 }
            }
            let elevatedFraction = Double(elevatedCount)
                / Double(max(1, sessionHR.count))
            let sessionAverage = bpmStats.roundedAverage
            let sessionStandardDeviation = try cooperativeStandardDeviation(
                sessionHR,
                cooperativeDeadline: cooperativeDeadline
            )
            let eventCalendar = EventCivilTime.eventCalendar(timeZoneIdentifier: session.eventTimeZoneIdentifier,
                                                             fallback: calendar)
            let startHour = eventCalendar.component(.hour, from: session.start)
            let endHour = eventCalendar.component(.hour, from: session.end)
            let overnight = startHour >= 20 || startHour <= 5 || endHour <= 11
            let daytimeNapWindow = !overnight && startHour >= 11 && endHour <= 20
            let shortLowHRNapLike = session.duration >= AggregateSleepCandidate.napMinimumDuration
                && session.duration <= AggregateSleepCandidate.napMaximumSpan
                && sessionAverage <= rest + 12
                && sessionP90 <= rest + 30
                && elevatedFraction <= 0.08
            let napLike = daytimeNapWindow && shortLowHRNapLike
            let lowHR = sessionAverage <= rest + 18
                && sessionP90 <= rest + 35
                && elevatedFraction <= 0.12
            // Motion is resolved only after the eligible fragments have been
            // clustered, so this first pass must not discard an otherwise
            // plausible overnight fragment solely because a poor/restless
            // night sits modestly above the long-term resting baseline. The
            // candidate still cannot become sleep unless the whole cluster
            // later proves validated low motion and clears the bounded robust
            // HR gate below. Keep this admission path overnight-only so it
            // cannot revive the daytime quiet-awake/false-nap failure.
            let motionEligibleOvernightFragment = overnight
                // Anchor the allowance to a real low-HR tail that remains
                // close to the trusted baseline. A uniformly elevated active
                // interval cannot define its own convenient sleep baseline.
                && sessionP05 <= rest + 12
                && sessionAverage <= sessionP05 + 15
                && sessionP90 <= sessionP05 + 30
                && elevatedFraction <= 0.18
            let longOvernightReviewLike = overnight
                && session.duration >= AggregateSleepCandidate.strictMinimumDuration
                && sessionAverage <= rest + 22
                && sessionP90 <= rest + 45
                && elevatedFraction <= 0.18
            // A trusted-baseline auto-confirm decision is made later, but the
            // candidate builder must not discard the same unmistakably stable
            // physiology solely because it occurred outside conventional sleep
            // hours. Keep this admission gate at least as strict as the final
            // HR-only predicate; dense coverage and span are checked on the
            // resulting aggregate. (2026-07-18 shift-work truth fix)
            let longStableHROnlyMainSleepLike = session.duration >= AggregateSleepCandidate.minimumAutoConfirmMainSleepDuration
                && session.duration <= AggregateSleepCandidate.maximumAutoConfirmMainSleepSpan
                && sessionAverage <= rest + 12
                && sessionStandardDeviation <= 9.5
                && sessionP90 <= rest + 18
                && elevatedFraction < 0.05
            // A full shift-work sleep can arrive in several one-to-three-hour
            // journal chunks. The aggregate still demands five dense hours and
            // is review-only; this only admits independently dense fragments.
            let denseLongHROnlyReviewFragment = session.duration >= 60 * 60
                && sessionAverage <= rest + 18
                && sessionStandardDeviation <= 9.5
                && sessionP90 <= rest + 35
                && elevatedFraction < 0.12
                && Double(session.rrPoints?.count ?? 0) / max(1, session.duration) >= 0.60
            let workoutReadiness: WorkoutReadiness
            if let cooperativeDeadline {
                workoutReadiness = try session.workoutReadiness(
                    rest: rest,
                    maxHR: maxHR,
                    cooperativeDeadline: cooperativeDeadline,
                    preparedBPMStats: bpmStats
                )
            } else {
                workoutReadiness = session.workoutReadiness(
                    rest: rest,
                    maxHR: maxHR
                )
            }
            let notWorkout = !workoutReadiness.ready
            return ((overnight && lowHR)
                || motionEligibleOvernightFragment
                || longOvernightReviewLike
                || longStableHROnlyMainSleepLike
                || denseLongHROnlyReviewFragment
                || napLike
                || shortLowHRNapLike) && notWorkout
            }()
            try cooperativeDeadline?.checkpoint()
            if isEligible {
                eligible.append(session)
            }
        }
        // Cluster first, then assign the wake-day. Bucketing each fragment first
        // splits a single night when one fragment ends before midnight and the
        // next begins just after it.
        let clusters: [[SavedSession]]
        if let cooperativeDeadline {
            var orderedEligible = eligible
            try cooperativeStableSort(
                &orderedEligible,
                cooperativeDeadline: cooperativeDeadline,
                areInIncreasingOrder: { $0.start < $1.start }
            )
            let initial = try sleepClusters(
                fromPresorted: orderedEligible,
                maxGap: 2 * 60 * 60,
                rest: rest,
                calendar: calendar,
                sessionHRStats: sessionHRStats,
                cooperativeDeadline: cooperativeDeadline
            )
            var split: [[SavedSession]] = []
            split.reserveCapacity(initial.count)
            for cluster in initial {
                try cooperativeDeadline.checkpoint()
                split.append(contentsOf:
                    try splitShortPreludeFromDenseSleepCluster(
                        cluster,
                        sessionHRStats: sessionHRStats,
                        cooperativeDeadline: cooperativeDeadline
                    )
                )
            }
            clusters = split
        } else {
            clusters = Self.sleepClusters(
                from: eligible.sorted { $0.start < $1.start },
                maxGap: 2 * 60 * 60,
                rest: rest,
                calendar: calendar
            ).flatMap(Self.splitShortPreludeFromDenseSleepCluster)
        }
        try cooperativeDeadline?.checkpoint()
        var candidates: [AggregateSleepCandidate] = []
        candidates.reserveCapacity(clusters.count)
        for cluster in clusters {
            try cooperativeDeadline?.checkpoint()
            let candidate: AggregateSleepCandidate? = try {
                () throws -> AggregateSleepCandidate? in
                try cooperativeDeadline?.checkpoint()
                var capturedDuration = 0.0
                var gaps: [TimeInterval] = []
                gaps.reserveCapacity(max(0, cluster.count - 1))
                var previousSession: SavedSession?
                for session in cluster {
                    try cooperativeDeadline?.checkpoint()
                    capturedDuration += session.duration
                    if let previousSession {
                        gaps.append(max(
                            0,
                            session.start.timeIntervalSince(
                                previousSession.end
                            )
                        ))
                    }
                    previousSession = session
                }
                var maxGap = 0.0
                var briefGapCredit = 0.0
                for gap in gaps {
                    try cooperativeDeadline?.checkpoint()
                    maxGap = max(maxGap, gap)
                    if gap
                        <= AggregateSleepCandidate.briefSleepGapCreditMax {
                        briefGapCredit += gap
                    }
                }
                // Credit brief between-session dropouts (<= 20 min) toward sleep:
                // these sit between two clearly-asleep low-HR sessions in the
                // overnight window, so they were almost certainly still-asleep
                // time lost to a momentary strap blip. Long gaps stay excluded.
                let totalDuration = capturedDuration + briefGapCredit

                var allHR: [Int] = []
                var sampleDates: [Date] = []
                allHR.reserveCapacity(cluster.reduce(0) {
                    $0 + $1.points.count
                })
                sampleDates.reserveCapacity(allHR.capacity)
                var hrSum = 0
                var peak = 0
                var elevatedCount = 0
                for session in cluster {
                    try cooperativeDeadline?.checkpoint()
                    guard let stats = sessionHRStats[session.id] else {
                        return nil
                    }
                    for (index, bpm) in stats.values.enumerated() {
                        if index.isMultiple(of: 256) {
                            try cooperativeDeadline?.checkpoint()
                        }
                        allHR.append(bpm)
                        hrSum += bpm
                        peak = max(peak, bpm)
                        if bpm >= rest + 35 { elevatedCount += 1 }
                    }
                    for (index, point) in session.points.enumerated() {
                        if index.isMultiple(of: 256) {
                            try cooperativeDeadline?.checkpoint()
                        }
                        sampleDates.append(
                            session.start.addingTimeInterval(
                                min(max(0, point.t), session.duration)
                            )
                        )
                    }
                }
                guard !allHR.isEmpty, let start = cluster.first?.start, let end = cluster.last?.end else { return nil }
                let span = end.timeIntervalSince(start)
                let hrStandardDeviation = try cooperativeStandardDeviation(
                    allHR,
                    cooperativeDeadline: cooperativeDeadline
                )
                try cooperativeStableSort(
                    &allHR,
                    cooperativeDeadline: cooperativeDeadline,
                    areInIncreasingOrder: <
                )
                try cooperativeStableSort(
                    &sampleDates,
                    cooperativeDeadline: cooperativeDeadline,
                    areInIncreasingOrder: <
                )
                let binSeconds: TimeInterval = 5 * 60
                let expectedHRBins = max(1, Int(ceil(span / binSeconds)))
                var observedHRBinSet = Set<Int>()
                observedHRBinSet.reserveCapacity(expectedHRBins)
                var maximumHRSampleGap = 0.0
                var previousDate = start
                for (index, sample) in sampleDates.enumerated() {
                    if index.isMultiple(of: 256) {
                        try cooperativeDeadline?.checkpoint()
                    }
                    observedHRBinSet.insert(
                        min(
                            expectedHRBins - 1,
                            max(
                                0,
                                Int(sample.timeIntervalSince(start)
                                    / binSeconds)
                            )
                        )
                    )
                    maximumHRSampleGap = max(
                        maximumHRSampleGap,
                        max(0, sample.timeIntervalSince(previousDate))
                    )
                    previousDate = sample
                }
                maximumHRSampleGap = max(
                    maximumHRSampleGap,
                    max(0, end.timeIntervalSince(previousDate))
                )
                let observedHRBins = observedHRBinSet.count
                let hrObservedCoverageFraction = Double(observedHRBins) / Double(expectedHRBins)
                let avg = hrSum / allHR.count
                let resting = Self.percentileHR(
                    0.05,
                    presorted: allHR
                )
                let medianHR = Self.percentileHR(
                    0.50,
                    presorted: allHR
                )
                let hrP90 = Self.percentileHR(
                    0.90,
                    presorted: allHR
                )
                let elevatedSampleFraction = Double(elevatedCount)
                    / Double(allHR.count)
                try cooperativeDeadline?.checkpoint()
                let strictDurationReady = totalDuration >= AggregateSleepCandidate.strictMinimumDuration
                let fragmentedFallbackReady = cluster.count > 1
                    && span >= AggregateSleepCandidate.fragmentedMinimumSpan
                    && totalDuration >= AggregateSleepCandidate.fragmentedMinimumDuration
                    && maxGap <= 2 * 60 * 60
                let eventTimeZoneIdentifier = Self.aggregateSleepTimeZoneIdentifier(for: cluster)
                let day = Self.aggregateSleepDay(for: cluster,
                                                 eventTimeZoneIdentifier: eventTimeZoneIdentifier,
                                                 calendar: calendar)
                let eventCalendar = EventCivilTime.eventCalendar(timeZoneIdentifier: eventTimeZoneIdentifier,
                                                                 fallback: calendar)
                let clusterStartHour = eventCalendar.component(.hour, from: start)
                let clusterEndHour = eventCalendar.component(.hour, from: end)
                let clusterOvernightReviewWindow = clusterStartHour >= 20
                    || clusterStartHour <= 5
                    || clusterEndHour <= 11
                let clusterDaytimeNapWindow = !clusterOvernightReviewWindow
                    && clusterStartHour >= 11
                    && clusterEndHour <= 20
                let daytimeNapCandidateReady = clusterDaytimeNapWindow
                    && span <= AggregateSleepCandidate.napMaximumSpan
                    && totalDuration >= AggregateSleepCandidate.napMinimumDuration
                let shortLowHRNapCandidateReady = cluster.count == 1
                    && clusterDaytimeNapWindow
                    && span <= AggregateSleepCandidate.napMaximumSpan
                    && totalDuration >= AggregateSleepCandidate.napMinimumDuration
                    && avg <= rest + 12
                    && peak <= rest + 35
                // A daytime low-HR window can be desk work, reading, or active
                // wear between brief exertion. It is not a nap without an
                // independent stillness signal; HR-only candidates previously
                // produced false prompts despite explicitly reporting motion as
                // unavailable. Compute the physiology shape here, then apply
                // the validated-motion requirement once motion provenance has
                // been resolved below.
                let napPhysiologyReady = daytimeNapCandidateReady || shortLowHRNapCandidateReady
                let hrSampleCoverageFraction = min(1, Double(allHR.count) / max(1, totalDuration))
                var rrSampleCount = 0
                var qualifiedRRSampleCount = 0
                var maximumAcceptedHRGap = 0.0
                for session in cluster {
                    try cooperativeDeadline?.checkpoint()
                    rrSampleCount += session.rrPoints?.count ?? 0
                    // Assessment P1.10: the auto-confirm gate needs the
                    // provenance-QUALIFIED subset, mirroring the RR rules the
                    // dense review tiers already apply.
                    if session.hasQualifiedRRProvenance {
                        qualifiedRRSampleCount += session.rrPoints?.count ?? 0
                    }
                    maximumAcceptedHRGap = max(
                        maximumAcceptedHRGap,
                        session.hrMaxAcceptedGapValue
                    )
                }
                let rrSampleCoverageFraction = min(1, Double(rrSampleCount) / max(1, totalDuration))
                let qualifiedRRCoverageFraction = min(1, Double(qualifiedRRSampleCount) / max(1, totalDuration))
                // Dense independent HR + RR can support a truthful sleep
                // review prompt before the stricter five-hour HR-only automatic
                // confirmation floor. Previously this exception stopped at the
                // exact three-hour boundary: a 2h59m window appeared, then the
                // same uninterrupted evidence disappeared from 3h00m through
                // 4h59m. Keep eligibility monotonic while remaining review-only.
                // Reconnect fragments are allowed only when the actual sample
                // timeline is still dense; a missing interval cannot be hidden
                // merely because every individual chunk reports a small gap.
                // A sleep can be shifted well into the day. Keep this narrow:
                // broadening this to all daytime quietness would recreate the
                // false nap/quiet-awake prompts we explicitly reject below.
                // This remains review-only until the wearer confirms it.
                let denseReviewClockWindow = (clusterStartHour >= 3
                                               && clusterStartHour <= 8
                                               && clusterEndHour <= 11)
                    || (clusterStartHour >= 8
                        && clusterStartHour <= 13
                        && clusterEndHour <= 16)
                let denseMorningHROnlyReviewReady = !napPhysiologyReady
                    && totalDuration >= AggregateSleepCandidate.strictMinimumDuration
                        - AggregateSleepCandidate.nearStrictMorningReviewTolerance
                    && totalDuration < AggregateSleepCandidate.minimumAutoConfirmMainSleepDuration
                    && span <= totalDuration + AggregateSleepCandidate.morningReviewSeamTolerance
                    && denseReviewClockWindow
                    && avg <= rest + 12
                    && hrStandardDeviation <= 9.5
                    && medianHR <= rest + 10
                    && hrP90 <= rest + 22
                    && elevatedSampleFraction < 0.10
                    && elevatedSampleFraction * totalDuration < 20 * 60
                    && hrSampleCoverageFraction >= 0.60
                    && rrSampleCoverageFraction >= 0.60
                    && hrObservedCoverageFraction >= AggregateSleepCandidate.minimumAutoConfirmHRCoverageFraction
                    // This is a review-only shifted-sleep path, never an
                    // automatic confirmation path. A short reconnect seam is
                    // real missing observation and stays visible in the card,
                    // but must not make an otherwise dense 3–5h sleep vanish.
                    // Keep the allowance deliberately below the 20-minute
                    // sleep-duration gap-credit ceiling and narrow it to this
                    // already strict HR+RR/clock/physiology qualification.
                    && maximumHRSampleGap <= AggregateSleepCandidate.briefSleepGapCreditMax
                    // This remains a wearer-reviewed inference. A single
                    // bounded reconnect gap up to 90 seconds must stay visible
                    // rather than erase four dense hours; longer outages remain
                    // insufficient evidence.
                    && maximumAcceptedHRGap <= 90
                // A complete sleep window can have short journal seams after
                // reconnect, including shift-work sleep outside conventional
                // hours. Preserve it for a *user review* when both HR and RR
                // remain dense across the entire span. It is never automatic:
                // there is no validated motion.
                let denseLongHROnlyReviewReady = !napPhysiologyReady
                    && totalDuration >= AggregateSleepCandidate.minimumAutoConfirmMainSleepDuration
                    && span <= totalDuration + 10 * 60
                    && avg <= rest + 18
                    && hrStandardDeviation <= 9.5
                    && medianHR <= rest + 12
                    && hrP90 <= rest + 35
                    && elevatedSampleFraction < 0.10
                    && elevatedSampleFraction * totalDuration < 20 * 60
                    && hrSampleCoverageFraction >= 0.60
                    && rrSampleCoverageFraction >= 0.60
                    && hrObservedCoverageFraction >= AggregateSleepCandidate.minimumAutoConfirmHRCoverageFraction
                    && maximumHRSampleGap <= 10 * 60
                    && maximumAcceptedHRGap <= 60
                guard strictDurationReady
                        || fragmentedFallbackReady
                        || napPhysiologyReady
                        || denseMorningHROnlyReviewReady
                        || denseLongHROnlyReviewReady else { return nil }
                var motionHintCount = 0
                var recoveredEpochs: [AtriaRecoveredMotionEpoch] = []
                for session in cluster {
                    try cooperativeDeadline?.checkpoint()
                    motionHintCount += session.motionHintCountValue
                    let epochs = session.recoveredMotionEpochs ?? []
                    recoveredEpochs.reserveCapacity(
                        recoveredEpochs.count + epochs.count
                    )
                    for (index, epoch) in epochs.enumerated() {
                        if index.isMultiple(of: 256) {
                            try cooperativeDeadline?.checkpoint()
                        }
                        recoveredEpochs.append(epoch)
                    }
                }
                let motionHintKinds = Self.motionHintKindsSummary(for: cluster)
                let recoveredMotion = try cooperativeRecoveredMotionSleepProvenance(
                    epochs: recoveredEpochs,
                    start: start,
                    end: end,
                    cooperativeDeadline: cooperativeDeadline
                )
                try cooperativeDeadline?.checkpoint()
                let historicalMotion: HistoricalArchive.MotionWindowDiagnostics
                if recoveredMotion.hasRecoveredEpochs {
                    var bounded: [AtriaRecoveredMotionEpoch] = []
                    var validated: [AtriaRecoveredMotionEpoch] = []
                    var p95: [Double] = []
                    var boundedRows = 0
                    var validatedRows = 0
                    var firstEpochStart: Date?
                    var lastEpochEnd: Date?
                    for (index, epoch) in recoveredEpochs.enumerated() {
                        if index.isMultiple(of: 256) {
                            try cooperativeDeadline?.checkpoint()
                        }
                        guard epoch.end > start,
                              epoch.start < end else { continue }
                        bounded.append(epoch)
                        boundedRows += epoch.rows
                        firstEpochStart = min(
                            firstEpochStart ?? epoch.start,
                            epoch.start
                        )
                        lastEpochEnd = max(
                            lastEpochEnd ?? epoch.end,
                            epoch.end
                        )
                        if epoch.measurementValidated {
                            validated.append(epoch)
                            validatedRows += epoch.validatedRows
                            if let value = epoch.p95VectorDelta {
                                p95.append(value)
                            }
                        }
                    }
                    var p95Sum = 0.0
                    for (index, value) in p95.enumerated() {
                        if index.isMultiple(of: 256) {
                            try cooperativeDeadline?.checkpoint()
                        }
                        p95Sum += value
                    }
                    historicalMotion = .init(
                        status: recoveredMotion.measurementSufficient ? "ready" : "learning",
                        reason: recoveredMotion.measurementSufficient
                            ? "recovered_epoch_measurement_validated"
                            : "recovered_epoch_coverage_insufficient",
                        rows: boundedRows,
                        validatedRows: validatedRows,
                        coverageSeconds: Int((recoveredMotion.validatedCoverageFraction * span).rounded()),
                        spanSeconds: Int(span.rounded()),
                        meanVectorDelta: recoveredMotion.meanMovementIntensity,
                        p95VectorDelta: p95.isEmpty
                            ? nil : p95Sum / Double(p95.count),
                        magnitudeMean: nil,
                        magnitudeStdDev: nil,
                        archiveFirstUnix: Int(
                            (firstEpochStart ?? start).timeIntervalSince1970
                        ),
                        archiveLastUnix: Int(
                            (lastEpochEnd ?? end).timeIntervalSince1970
                        ),
                        nearestSeparationSeconds: Int(recoveredMotion.maximumGapSeconds.rounded()),
                        lowMotionReady: recoveredMotion.lowMotionValidated
                    )
                } else {
                    historicalMotion = historicalMotionDiagnostics(start: start, end: end)
                }
                // Legacy whole-session booleans are trustworthy only when the
                // entire clustered window carries the claim. One still fragment
                // must never validate a disconnected night.
                var sessionMotionValidated = !cluster.isEmpty
                for session in cluster {
                    try cooperativeDeadline?.checkpoint()
                    if !session.motionEvidenceValidatedValue {
                        sessionMotionValidated = false
                        break
                    }
                }
                let motionValidated = recoveredMotion.hasRecoveredEpochs
                    ? recoveredMotion.lowMotionValidated
                    : (historicalMotion.lowMotionReady || sessionMotionValidated)
                let napCandidateReady = napPhysiologyReady && motionValidated
                let motionSource = recoveredMotion.hasRecoveredEpochs
                    ? recoveredMotion.source
                    : (historicalMotion.lowMotionReady
                       ? "historical_gravity"
                       : (sessionMotionValidated
                          ? (cluster.first?.motionEvidenceSourceValue ?? "validated_strap_motion")
                          : (motionHintCount > 0 ? "diagnostic_observe_only" : "unavailable")))
                let motionStats = Self.motionShortSummary(for: cluster)
                let motionClause = motionHintCount > 0
                    ? "diagnostic motion observed unvalidated"
                    : "motion not decoded"
                // Medium confidence is reserved for validated strap
                // motion/stillness. HR-only remains low-confidence in the raw
                // candidate; only the later trusted-personal-baseline predicate
                // can promote an unambiguous five-hour physiological window.
                let confidence: ActivityDetection.Confidence = motionValidated ? .medium : .low
                let motionValidatedMainSleepReady = !napCandidateReady
                    && motionValidated
                    && (strictDurationReady || fragmentedFallbackReady)
                let stableHROnlyMainSleepReady = !napCandidateReady
                    && totalDuration >= AggregateSleepCandidate.minimumHROnlyMainSleepReviewDuration
                    && maxGap <= 60
                    && avg <= rest + 12
                    && hrStandardDeviation <= 9.5
                // A physical night can be split by journal/reconnect seams
                // before asynchronous R10 motion projection reaches the saved
                // sessions. Preserve only the long, dense, multi-fragment shape
                // that the trusted-baseline auto-confirm predicate can
                // independently verify. RR density is required here even though
                // it is not a presentation field on AggregateSleepCandidate.
                let highSpecificityFragmentedHROnlyMainSleepReady = !napCandidateReady
                    && cluster.count >= 3
                    && totalDuration >= AggregateSleepCandidate.minimumAutoConfirmMainSleepDuration
                    && span <= totalDuration * 1.35
                    && span <= AggregateSleepCandidate.maximumAutoConfirmMainSleepSpan
                    && maxGap <= 60 * 60
                    && hrObservedCoverageFraction >= AggregateSleepCandidate.minimumAutoConfirmHRCoverageFraction
                    && maximumHRSampleGap <= 60 * 60
                    && rrSampleCoverageFraction >= 0.60
                    && resting <= rest + 12
                    && avg <= rest + 25
                    && hrStandardDeviation <= 15
                    && medianHR <= rest + 22
                    && hrP90 <= rest + 40
                    && elevatedSampleFraction < 0.20
                    && elevatedSampleFraction * totalDuration < 45 * 60
                    && Self.sleepCoreOverlapFraction(start: start,
                                                     end: end,
                                                     calendar: eventCalendar) >= 0.60
                // Reconnect-fragmented nights can still be offered for review
                // when robust HR statistics and sleep-core overlap are unusually
                // specific. This preserves split/resumed sleep clustering while
                // confidence remains .low and the auto-confirm gate still
                // requires validated motion/stillness.
                let degradedHROnlyMainSleepReviewReady = !napCandidateReady
                    && cluster.count > 1
                    && totalDuration >= AggregateSleepCandidate.strictMinimumDuration
                    && maxGap <= 90 * 60
                    && span <= totalDuration * 1.8
                    && Self.sleepCoreOverlapFraction(start: start,
                                                     end: end,
                                                     calendar: eventCalendar) >= 0.60
                    && medianHR <= rest + 10
                    && hrP90 <= rest + 22
                    && elevatedSampleFraction < 0.10
                    && elevatedSampleFraction * totalDuration < 20 * 60
                guard napCandidateReady
                        || motionValidatedMainSleepReady
                        || stableHROnlyMainSleepReady
                        || highSpecificityFragmentedHROnlyMainSleepReady
                        || degradedHROnlyMainSleepReviewReady
                        || denseMorningHROnlyReviewReady
                        || denseLongHROnlyReviewReady else {
                    return nil
                }
                let motionReason = motionValidated
                    ? "historical gravity low-motion validated"
                    : "\(motionClause); historical gravity \(historicalMotion.reason)"
                let reason: String
                if napPhysiologyReady && !napCandidateReady {
                    // Fail closed: the HR shape is retained in diagnostics but
                    // must not become a user-visible nap review.
                    return nil
                } else if fragmentedFallbackReady && !strictDurationReady {
                    reason = "HR-only interrupted overnight low-HR aggregate; below strict 3h low-HR total but span supports broken sleep fallback; \(motionReason)"
                } else if shortLowHRNapCandidateReady {
                    reason = "HR-only short low-HR nap/rest candidate; user confirmation required; \(motionReason)"
                } else if napCandidateReady {
                    reason = "HR-only daytime nap candidate; user confirmation required; \(motionReason)"
                } else if denseMorningHROnlyReviewReady {
                    reason = "HR+RR dense morning sleep candidate below the 5h automatic-confirmation floor; user confirmation required; \(motionReason)"
                } else if denseLongHROnlyReviewReady {
                    reason = "HR+RR dense sleep candidate with short reconnect seams; user confirmation required; \(motionReason)"
                } else if cluster.count > 1 {
                    reason = "HR-only broken overnight review aggregate; user confirmation required; \(motionReason)"
                } else {
                    reason = "HR-only overnight review window; user confirmation required; \(motionReason)"
                }
                let kind = napCandidateReady ? "nap_candidate" : "overnight_sleep"
                // Duration honesty (2026-08-04, user-caught): deduct SUSTAINED
                // validated wake movement from the reported duration so a
                // candidate can never claim duration == span across a stretch
                // the wearer was demonstrably awake (typing showed 110-596mg
                // vs a ≤6mg still baseline in the drained archive). Deduction
                // only trusts measurement-validated recovered epochs and only
                // blocks ≥10 min — brief rollovers are normal sleep movement.
                // Flows into downstream review/auto-confirm gates fail-closed
                // (net duration is smaller, never larger).
                let motionAwakeSeconds = try cooperativeSustainedAwakeSeconds(
                    epochs: recoveredEpochs,
                    start: start,
                    end: end,
                    cooperativeDeadline: cooperativeDeadline
                )
                // 2026-08-06 sleep-onset device-use clamp (user-caught 12:53am
                // false onset while the phone was in active use past 2am; see
                // `clampedSleepOnset`). Deterministic replay (`.sessionOnly`)
                // excludes the journal exactly as it excludes the external
                // motion archive; an empty journal or a window with no journal
                // coverage is exact identity with today's behavior.
                let clampedStart: Date
                if historicalMotionPolicy == .sessionOnly {
                    clampedStart = start
                } else {
                    try cooperativeDeadline?.checkpoint()
                    clampedStart = Self.clampedSleepOnset(
                        start: start,
                        end: end,
                        sustainedUse: AtriaDeviceUseJournal.intervalsOfSustainedUse(
                            in: DateInterval(start: start, end: end),
                            minimumDuration: Self.sleepOnsetClampMinimumSustainedUse
                        ),
                        minimumRetainedDuration: napCandidateReady
                            ? AggregateSleepCandidate.napMinimumDuration
                            : AggregateSleepCandidate.strictMinimumDuration
                    )
                    try cooperativeDeadline?.checkpoint()
                }
                let onsetClampSeconds = max(0, clampedStart.timeIntervalSince(start))
                if onsetClampSeconds > 0 {
                    // Field-verification breadcrumb: last applied onset clamp.
                    let iso = ISO8601DateFormatter()
                    UserDefaults.standard.set(
                        "\(iso.string(from: start))→\(iso.string(from: clampedStart))",
                        forKey: "atria.debug.sleepOnsetClamp.v1"
                    )
                }
                return AggregateSleepCandidate(kind: kind,
                                               day: day,
                                               eventTimeZoneIdentifier: eventTimeZoneIdentifier,
                                               sessions: cluster.count,
                                               start: clampedStart,
                                               end: end,
                                               duration: max(0, totalDuration - motionAwakeSeconds - onsetClampSeconds),
                                               span: end.timeIntervalSince(clampedStart),
                                               maxGap: maxGap,
                                               samples: allHR.count,
                                               hrObservedCoverageFraction: hrObservedCoverageFraction,
                                               maximumHRSampleGap: maximumHRSampleGap,
                                               avgHR: avg,
                                               peakHR: peak,
                                               hrStandardDeviation: hrStandardDeviation,
                                               medianHR: medianHR,
                                               hrP90: hrP90,
                                               elevatedSampleFraction: elevatedSampleFraction,
                                               baselineRestingHR: rest,
                                               restingHR: resting,
                                               confidence: confidence,
                                               reason: reason,
                                               motionHintCount: motionHintCount,
                                               motionHintKinds: motionHintKinds,
                                               motionEvidenceSource: motionSource,
                                               motionEvidenceValidated: motionValidated,
                                               motionShortCount: motionStats.count,
                                               motionShortMean: motionStats.mean,
                                               motionShortMin: motionStats.min,
                                               motionShortMax: motionStats.max,
                                               motionShortOverOneCount: motionStats.overOne,
                                               historicalMotionStatus: historicalMotion.status,
                                               historicalMotionReason: historicalMotion.reason,
                                               historicalMotionRows: historicalMotion.rows,
                                               historicalMotionValidatedRows: historicalMotion.validatedRows,
                                               historicalMotionCoverageSeconds: historicalMotion.coverageSeconds,
                                               historicalMotionMeanVectorDelta: historicalMotion.meanVectorDelta,
                                               historicalMotionP95VectorDelta: historicalMotion.p95VectorDelta,
                                               historicalMotionMagnitudeStdDev: historicalMotion.magnitudeStdDev,
                                               historicalMotionArchiveFirstUnix: historicalMotion.archiveFirstUnix,
                                               historicalMotionArchiveLastUnix: historicalMotion.archiveLastUnix,
                                               historicalMotionNearestSeparationSeconds: historicalMotion.nearestSeparationSeconds,
                                               historicalMotionValidated: historicalMotion.lowMotionReady,
                                               denseMorningHROnlyReviewQualified: denseMorningHROnlyReviewReady,
                                               denseLongHROnlyReviewQualified: denseLongHROnlyReviewReady,
                                               qualifiedRRCoverageFraction: qualifiedRRCoverageFraction)
            }()
            try cooperativeDeadline?.checkpoint()
            if let candidate {
                candidates.append(candidate)
            }
        }
        let resumed: [AggregateSleepCandidate]
        if includeResumedReviewCandidates {
            if let cooperativeDeadline {
                resumed = try resumedSleepReviewCandidatesCore(
                    in: sourceSessions,
                    after: candidates,
                    rest: rest,
                    maxHR: maxHR,
                    calendar: calendar,
                    cooperativeDeadline: cooperativeDeadline
                )
            } else {
                resumed = resumedSleepReviewCandidates(
                    in: sourceSessions,
                    after: candidates,
                    rest: rest,
                    maxHR: maxHR,
                    calendar: calendar
                )
            }
        } else {
            resumed = []
        }
        try cooperativeDeadline?.checkpoint()
        var result = candidates + resumed
        let ordering: (AggregateSleepCandidate, AggregateSleepCandidate)
            -> Bool = {
                if $0.day != $1.day { return $0.day > $1.day }
                if $0.start != $1.start { return $0.start < $1.start }
                return $0.duration > $1.duration
            }
        if let cooperativeDeadline {
            try cooperativeStableSort(
                &result,
                cooperativeDeadline: cooperativeDeadline,
                areInIncreasingOrder: ordering
            )
        } else {
            result.sort(by: ordering)
        }
        return result
    }

    private nonisolated static func cooperativeRecoveredMotionSleepProvenance(
        epochs: [AtriaRecoveredMotionEpoch],
        start: Date,
        end: Date,
        cooperativeDeadline: AtriaSleepSettlementDeadline?
    ) throws -> AtriaRecoveredMotionAnalytics.SleepProvenance {
        try cooperativeDeadline?.checkpoint()
        var bounded: [AtriaRecoveredMotionEpoch] = []
        bounded.reserveCapacity(epochs.count)
        for (index, epoch) in epochs.enumerated() {
            if index.isMultiple(of: 256) {
                try cooperativeDeadline?.checkpoint()
            }
            if epoch.end > start, epoch.start < end {
                bounded.append(epoch)
            }
        }
        try cooperativeStableSort(
            &bounded,
            cooperativeDeadline: cooperativeDeadline,
            areInIncreasingOrder: { $0.start < $1.start }
        )
        guard end > start, !bounded.isEmpty else {
            return .init(
                hasRecoveredEpochs: false,
                measurementSufficient: false,
                lowMotionValidated: false,
                validatedCoverageFraction: 0,
                lowMotionCoverageFraction: 0,
                meanMovementIntensity: nil,
                maximumGapSeconds: max(0, end.timeIntervalSince(start)),
                source: "\(AtriaRecoveredMotionEpoch.source)_missing"
            )
        }
        var validated: [AtriaRecoveredMotionEpoch] = []
        var lowMotion: [AtriaRecoveredMotionEpoch] = []
        var intensitySum = 0.0
        var intensityCount = 0
        validated.reserveCapacity(bounded.count)
        lowMotion.reserveCapacity(bounded.count)
        for (index, epoch) in bounded.enumerated() {
            if index.isMultiple(of: 256) {
                try cooperativeDeadline?.checkpoint()
            }
            guard epoch.measurementValidated else { continue }
            validated.append(epoch)
            if epoch.lowMotionQualified { lowMotion.append(epoch) }
            if let value = epoch.movementIntensity {
                intensitySum += value
                intensityCount += 1
            }
        }
        let duration = end.timeIntervalSince(start)
        let validatedCoverage = try cooperativeRecoveredMotionCoveredDuration(
            validated,
            start: start,
            end: end,
            cooperativeDeadline: cooperativeDeadline
        )
        let lowMotionCoverage = try cooperativeRecoveredMotionCoveredDuration(
            lowMotion,
            start: start,
            end: end,
            cooperativeDeadline: cooperativeDeadline
        )
        let validatedFraction = min(1, validatedCoverage / duration)
        let lowMotionFraction = validatedCoverage > 0
            ? min(1, lowMotionCoverage / validatedCoverage)
            : 0
        var cursor = start
        var maximumGap = 0.0
        for (index, epoch) in validated.enumerated() {
            if index.isMultiple(of: 256) {
                try cooperativeDeadline?.checkpoint()
            }
            let lower = max(start, epoch.start)
            let upper = min(end, epoch.end)
            guard upper > lower else { continue }
            maximumGap = max(
                maximumGap,
                lower.timeIntervalSince(cursor)
            )
            cursor = max(cursor, upper)
        }
        maximumGap = max(maximumGap, end.timeIntervalSince(cursor))
        let meanIntensity = intensityCount == 0
            ? nil : intensitySum / Double(intensityCount)
        let sufficient = duration >= 20 * 60
            && validatedFraction >= 0.80
            && maximumGap <= 90
            && intensityCount > 0
        let lowMotionValidated = sufficient
            && lowMotionFraction >= 0.72
            && (meanIntensity ?? .infinity) <= 0.18
        try cooperativeDeadline?.checkpoint()
        return .init(
            hasRecoveredEpochs: true,
            measurementSufficient: sufficient,
            lowMotionValidated: lowMotionValidated,
            validatedCoverageFraction: validatedFraction,
            lowMotionCoverageFraction: lowMotionFraction,
            meanMovementIntensity: meanIntensity,
            maximumGapSeconds: maximumGap,
            source: sufficient
                ? AtriaRecoveredMotionEpoch.source
                : "\(AtriaRecoveredMotionEpoch.source)_insufficient"
        )
    }

    private nonisolated static func cooperativeRecoveredMotionCoveredDuration(
        _ epochs: [AtriaRecoveredMotionEpoch],
        start: Date,
        end: Date,
        cooperativeDeadline: AtriaSleepSettlementDeadline?
    ) throws -> TimeInterval {
        var currentStart: Date?
        var currentEnd: Date?
        var total = 0.0
        for (index, epoch) in epochs.enumerated() {
            if index.isMultiple(of: 256) {
                try cooperativeDeadline?.checkpoint()
            }
            let lower = max(start, epoch.start)
            let upper = min(end, epoch.end)
            guard upper > lower else { continue }
            guard let existingEnd = currentEnd else {
                currentStart = lower
                currentEnd = upper
                continue
            }
            if lower <= existingEnd {
                currentEnd = max(existingEnd, upper)
            } else {
                total += existingEnd.timeIntervalSince(currentStart ?? lower)
                currentStart = lower
                currentEnd = upper
            }
        }
        if let currentStart, let currentEnd {
            total += currentEnd.timeIntervalSince(currentStart)
        }
        return total
    }

    private nonisolated static func cooperativeSustainedAwakeSeconds(
        epochs: [AtriaRecoveredMotionEpoch],
        start: Date,
        end: Date,
        minimumBlock: TimeInterval = 10 * 60,
        cooperativeDeadline: AtriaSleepSettlementDeadline?
    ) throws -> TimeInterval {
        var wakeEpochs: [AtriaRecoveredMotionEpoch] = []
        wakeEpochs.reserveCapacity(epochs.count)
        for (index, epoch) in epochs.enumerated() {
            if index.isMultiple(of: 256) {
                try cooperativeDeadline?.checkpoint()
            }
            if epoch.end > start,
               epoch.start < end,
               epoch.measurementValidated,
               !epoch.lowMotionQualified {
                wakeEpochs.append(epoch)
            }
        }
        try cooperativeStableSort(
            &wakeEpochs,
            cooperativeDeadline: cooperativeDeadline,
            areInIncreasingOrder: { $0.start < $1.start }
        )
        guard let first = wakeEpochs.first else { return 0 }
        var total = 0.0
        var blockStart = max(first.start, start)
        var blockEnd = min(first.end, end)
        for (index, epoch) in wakeEpochs.dropFirst().enumerated() {
            if index.isMultiple(of: 256) {
                try cooperativeDeadline?.checkpoint()
            }
            let lower = max(epoch.start, start)
            let upper = min(epoch.end, end)
            if lower.timeIntervalSince(blockEnd) <= 60 {
                blockEnd = max(blockEnd, upper)
            } else {
                let length = blockEnd.timeIntervalSince(blockStart)
                if length >= minimumBlock { total += length }
                blockStart = lower
                blockEnd = upper
            }
        }
        let finalLength = blockEnd.timeIntervalSince(blockStart)
        if finalLength >= minimumBlock { total += finalLength }
        try cooperativeDeadline?.checkpoint()
        return total
    }

    /// Isolates a substantial later-morning sleep-shaped segment from tiny
    /// intervening journals. It is deliberately contextual: the same two-hour
    /// quiet-wear trace is not a sleep claim unless a review-worthy main episode
    /// already exists in the same physiological morning. The returned candidate
    /// is always review-only (`isAutoConfirmableMainSleepCandidate` rejects its
    /// kind) and never credits the awake separation from the main episode.
    nonisolated static func resumedSleepReviewCandidates(
        in sourceSessions: [SavedSession],
        after ordinaryCandidates: [AggregateSleepCandidate],
        rest: Int,
        maxHR: Int,
        calendar: Calendar = .current
    ) -> [AggregateSleepCandidate] {
        (try? resumedSleepReviewCandidatesCore(
            in: sourceSessions,
            after: ordinaryCandidates,
            rest: rest,
            maxHR: maxHR,
            calendar: calendar,
            cooperativeDeadline: nil
        )) ?? []
    }

    private nonisolated static func resumedSleepReviewCandidatesCore(
        in sourceSessions: [SavedSession],
        after ordinaryCandidates: [AggregateSleepCandidate],
        rest: Int,
        maxHR: Int,
        calendar: Calendar,
        cooperativeDeadline: AtriaSleepSettlementDeadline?
    ) throws -> [AggregateSleepCandidate] {
        _ = maxHR
        try cooperativeDeadline?.checkpoint()
        var mainCandidates: [AggregateSleepCandidate] = []
        for candidate in ordinaryCandidates {
            try cooperativeDeadline?.checkpoint()
            if candidate.kind != "nap_candidate",
               candidate.kind != "resumed_sleep_candidate",
               candidate.duration
                    >= AggregateSleepCandidate.strictMinimumDuration,
               isReviewWorthySleepCandidate(candidate) {
                mainCandidates.append(candidate)
            }
        }
        guard !mainCandidates.isEmpty else { return [] }

        var orderedSessions = sourceSessions.filter { !$0.points.isEmpty }
        try cooperativeStableSort(
            &orderedSessions,
            cooperativeDeadline: cooperativeDeadline,
            areInIncreasingOrder: { $0.start < $1.start }
        )
        var result: [AggregateSleepCandidate] = []
        var consumedSessionIDs = Set<UUID>()

        for (sessionIndex, session) in orderedSessions.enumerated() {
            try cooperativeDeadline?.checkpoint()
            guard !consumedSessionIDs.contains(session.id),
                  session.duration >= AggregateSleepCandidate.resumedSleepMinimumDuration else {
                continue
            }

            var matchingMain: AggregateSleepCandidate?
            for main in mainCandidates {
                try cooperativeDeadline?.checkpoint()
                let matches = main.day == aggregateSleepDay(
                        for: [session],
                        eventTimeZoneIdentifier: session.eventTimeZoneIdentifier,
                        calendar: calendar
                    )
                        && session.start.timeIntervalSince(main.end)
                            >= AggregateSleepCandidate.resumedSleepMinimumSeparation
                        && session.start.timeIntervalSince(main.end)
                            <= AggregateSleepCandidate.resumedSleepMaximumSeparationFromMain
                if matches,
                   matchingMain == nil || main.end > matchingMain!.end {
                    matchingMain = main
                }
            }
            guard let matchingMain else { continue }

            // Tiny/ambiguous journals between the main wake and this tail stay
            // separate. A fresh >90-minute wake boundary immediately before the
            // substantial tail is required; no duration is credited across it.
            //
            // 2026-07-31 note: continuous background capture removes the wear
            // gaps this rule relies on, and an HR-only replacement anchor was
            // physically measured to be unbuildable — this wearer's quiet
            // pre-sleep descent (median ~65) passes every sleep-physiology
            // bar, so any HR-anchored candidate swallows the drowsy-awake
            // lead-in and recreates the mis-bounded window the user dismissed.
            // Continuous-wear resumed detection therefore requires validated
            // low-motion evidence for onset and remains deliberately absent
            // until that evidence exists.
            var nearestPriorEnd = matchingMain.end
            for prior in orderedSessions {
                try cooperativeDeadline?.checkpoint()
                if prior.id != session.id,
                   prior.end <= session.start,
                   prior.end > nearestPriorEnd {
                    nearestPriorEnd = prior.end
                }
            }
            guard session.start.timeIntervalSince(nearestPriorEnd)
                    >= AggregateSleepCandidate.resumedSleepMinimumSeparation else {
                continue
            }

            // All-day journals normally close and reopen around reconnects.
            // Treat a short seam as one review source, while retaining the seam
            // as zero-credit time in `duration`. The physical July 29 episode
            // was split by 6m28s; requiring one uninterrupted SavedSession made
            // both halves disappear.
            var cluster = [session]
            var clusterEnd = session.end
            for next in orderedSessions.dropFirst(sessionIndex + 1) {
                try cooperativeDeadline?.checkpoint()
                let separation = max(0, next.start.timeIntervalSince(clusterEnd))
                guard separation <= AggregateSleepCandidate.briefSleepGapCreditMax,
                      next.end.timeIntervalSince(session.start)
                        <= AggregateSleepCandidate.resumedSleepMaximumSourceSpan else {
                    break
                }
                cluster.append(next)
                clusterEnd = max(clusterEnd, next.end)
            }

            // A journal can remain open after the wearer wakes. Detect only a
            // sustained, three-bin wake transition; isolated elevated bins are
            // retained because broken sleep/brief bathroom wakes are expected.
            // This trims the physical 14:38 wake transition without treating
            // the later quiet-awake tail as more sleep.
            struct WakeBin {
                let start: Date
                let median: Int
                let elevatedFraction: Double
            }
            let wakeBinSeconds: TimeInterval = 5 * 60
            var valuesByWakeBucket: [Int: [Int]] = [:]
            for member in cluster {
                try cooperativeDeadline?.checkpoint()
                for (pointIndex, point) in member.points.enumerated() {
                    if pointIndex.isMultiple(of: 256) {
                        try cooperativeDeadline?.checkpoint()
                    }
                    let sampleDate = member.start.addingTimeInterval(
                        min(max(0, point.t), member.duration)
                    )
                    let bucket = Int(floor(sampleDate.timeIntervalSince1970 / wakeBinSeconds))
                    valuesByWakeBucket[bucket, default: []].append(point.bpm)
                }
            }
            var wakeBins: [WakeBin] = []
            wakeBins.reserveCapacity(valuesByWakeBucket.count)
            for (bucket, values) in valuesByWakeBucket {
                try cooperativeDeadline?.checkpoint()
                guard values.count >= 3 else { continue }
                var elevatedCount = 0
                for (index, value) in values.enumerated() {
                    if index.isMultiple(of: 256) {
                        try cooperativeDeadline?.checkpoint()
                    }
                    if value >= rest + 35 { elevatedCount += 1 }
                }
                var orderedValues = values
                try cooperativeStableSort(
                    &orderedValues,
                    cooperativeDeadline: cooperativeDeadline,
                    areInIncreasingOrder: <
                )
                wakeBins.append(WakeBin(
                    start: Date(timeIntervalSince1970: Double(bucket) * wakeBinSeconds),
                    median: percentileHR(0.50, presorted: orderedValues),
                    elevatedFraction: Double(elevatedCount)
                        / Double(values.count)
                ))
            }
            try cooperativeStableSort(
                &wakeBins,
                cooperativeDeadline: cooperativeDeadline,
                areInIncreasingOrder: { $0.start < $1.start }
            )
            var sustainedWakeRun: [WakeBin] = []
            var sustainedWakeStart: Date?
            for bin in wakeBins
            where bin.start >= session.start.addingTimeInterval(
                AggregateSleepCandidate.resumedSleepMinimumDuration
            ) {
                try cooperativeDeadline?.checkpoint()
                let wakeLike = bin.median >= rest + 20 || bin.elevatedFraction >= 0.15
                guard wakeLike else {
                    sustainedWakeRun.removeAll(keepingCapacity: true)
                    continue
                }
                if let previous = sustainedWakeRun.last,
                   bin.start.timeIntervalSince(previous.start) <= wakeBinSeconds + 5 {
                    sustainedWakeRun.append(bin)
                } else {
                    sustainedWakeRun = [bin]
                }
                if sustainedWakeRun.count >= 3 {
                    sustainedWakeStart = sustainedWakeRun.first?.start
                    break
                }
            }

            let candidateStart = session.start
            let candidateEnd = min(clusterEnd, sustainedWakeStart ?? clusterEnd)
            var includedSessions: [SavedSession] = []
            var capturedDuration = 0.0
            for member in cluster {
                try cooperativeDeadline?.checkpoint()
                guard member.start < candidateEnd,
                      member.end > candidateStart else { continue }
                includedSessions.append(member)
                capturedDuration += max(
                    0,
                    min(member.end, candidateEnd)
                        .timeIntervalSince(max(member.start, candidateStart))
                )
            }
            let span = candidateEnd.timeIntervalSince(candidateStart)
            guard capturedDuration >= AggregateSleepCandidate.resumedSleepMinimumDuration,
                  capturedDuration <= AggregateSleepCandidate.resumedSleepMaximumDuration,
                  span <= AggregateSleepCandidate.resumedSleepMaximumDuration else {
                continue
            }

            var sampleDatesAndValues: [(Date, Int)] = []
            for member in includedSessions {
                try cooperativeDeadline?.checkpoint()
                for (pointIndex, point) in member.points.enumerated() {
                    if pointIndex.isMultiple(of: 256) {
                        try cooperativeDeadline?.checkpoint()
                    }
                    let date = member.start.addingTimeInterval(
                        min(max(0, point.t), member.duration)
                    )
                    if date >= candidateStart, date <= candidateEnd {
                        sampleDatesAndValues.append((date, point.bpm))
                    }
                }
            }
            try cooperativeStableSort(
                &sampleDatesAndValues,
                cooperativeDeadline: cooperativeDeadline,
                areInIncreasingOrder: { $0.0 < $1.0 }
            )
            var values: [Int] = []
            var sampleDates: [Date] = []
            var valueSum = 0
            var elevatedCount = 0
            values.reserveCapacity(sampleDatesAndValues.count)
            sampleDates.reserveCapacity(sampleDatesAndValues.count)
            for (index, pair) in sampleDatesAndValues.enumerated() {
                if index.isMultiple(of: 256) {
                    try cooperativeDeadline?.checkpoint()
                }
                sampleDates.append(pair.0)
                values.append(pair.1)
                valueSum += pair.1
                if pair.1 >= rest + 35 { elevatedCount += 1 }
            }
            guard !values.isEmpty else { continue }
            var orderedValues = values
            try cooperativeStableSort(
                &orderedValues,
                cooperativeDeadline: cooperativeDeadline,
                areInIncreasingOrder: <
            )
            let medianHR = percentileHR(0.50, presorted: orderedValues)
            let hrP90 = percentileHR(0.90, presorted: orderedValues)
            let avgHR = valueSum / values.count
            let elevatedFraction = Double(elevatedCount)
                / Double(values.count)
            guard avgHR <= rest + 12,
                  medianHR <= rest + 8,
                  hrP90 <= rest + 25,
                  elevatedFraction < 0.10,
                  elevatedFraction * capturedDuration < 15 * 60 else {
                continue
            }

            let binSeconds: TimeInterval = 5 * 60
            let expectedBins = max(1, Int(ceil(span / binSeconds)))
            func observedBinFraction(_ dates: [Date]) throws -> Double {
                var bins = Set<Int>()
                for (index, date) in dates.enumerated() {
                    if index.isMultiple(of: 256) {
                        try cooperativeDeadline?.checkpoint()
                    }
                    bins.insert(min(
                        expectedBins - 1,
                        max(
                            0,
                            Int(date.timeIntervalSince(candidateStart)
                                / binSeconds)
                        )
                    ))
                }
                return Double(bins.count) / Double(expectedBins)
            }
            let hrCoverage = min(1, Double(values.count) / max(1, capturedDuration))
            var maximumAcceptedHRGap = 0.0
            for member in includedSessions {
                try cooperativeDeadline?.checkpoint()
                maximumAcceptedHRGap = max(
                    maximumAcceptedHRGap,
                    member.hrMaxAcceptedGapValue
                )
            }
            guard hrCoverage >= 0.60,
                  try observedBinFraction(sampleDates)
                    >= AggregateSleepCandidate.minimumAutoConfirmHRCoverageFraction,
                  maximumAcceptedHRGap
                    <= AggregateSleepCandidate.resumedSleepMaximumAcceptedHRGap else {
                continue
            }
            var qualifiedRRDates: [Date] = []
            for member in includedSessions {
                try cooperativeDeadline?.checkpoint()
                let qualified: Bool
                if let cooperativeDeadline {
                    qualified = try member.hasQualifiedRRProvenance(
                        cooperativeDeadline: cooperativeDeadline
                    )
                } else {
                    qualified = member.hasQualifiedRRProvenance
                }
                guard qualified else { continue }
                for (rrIndex, point) in (member.rrPoints ?? []).enumerated() {
                    if rrIndex.isMultiple(of: 256) {
                        try cooperativeDeadline?.checkpoint()
                    }
                    let date = member.start.addingTimeInterval(
                        min(max(0, point.t), member.duration)
                    )
                    if date >= candidateStart, date <= candidateEnd {
                        qualifiedRRDates.append(date)
                    }
                }
            }
            if !qualifiedRRDates.isEmpty {
                let rrCoverage = min(
                    1,
                    Double(qualifiedRRDates.count) / max(1, capturedDuration)
                )
                guard rrCoverage >= 0.60,
                      try observedBinFraction(qualifiedRRDates)
                        >= AggregateSleepCandidate.minimumAutoConfirmHRCoverageFraction else {
                    continue
                }
            }

            let boundaries = [candidateStart] + sampleDates + [candidateEnd]
            var maximumHRSampleGap = 0.0
            if boundaries.count > 1 {
                for index in 1..<boundaries.count {
                    if index.isMultiple(of: 256) {
                        try cooperativeDeadline?.checkpoint()
                    }
                    maximumHRSampleGap = max(
                        maximumHRSampleGap,
                        max(
                            0,
                            boundaries[index].timeIntervalSince(
                                boundaries[index - 1]
                            )
                        )
                    )
                }
            } else {
                maximumHRSampleGap = span
            }
            guard maximumHRSampleGap
                    <= AggregateSleepCandidate.briefSleepGapCreditMax else {
                continue
            }
            var maxGap = 0.0
            if includedSessions.count > 1 {
                for index in 1..<includedSessions.count {
                    try cooperativeDeadline?.checkpoint()
                    maxGap = max(
                        maxGap,
                        max(
                            0,
                            includedSessions[index].start.timeIntervalSince(
                                includedSessions[index - 1].end
                            )
                        )
                    )
                }
            }
            let eventTimeZoneIdentifier = aggregateSleepTimeZoneIdentifier(
                for: includedSessions
            )
            // Only suppress the clustered members after the cluster has
            // actually qualified. A rejected leading fragment must not make a
            // later independently valid resumed-sleep source invisible.
            for member in includedSessions {
                consumedSessionIDs.insert(member.id)
            }

            var doubleValues: [Double] = []
            doubleValues.reserveCapacity(values.count)
            for (index, value) in values.enumerated() {
                if index.isMultiple(of: 256) {
                    try cooperativeDeadline?.checkpoint()
                }
                doubleValues.append(Double(value))
            }
            let hrStandardDeviation: Double
            if cooperativeDeadline != nil {
                hrStandardDeviation = try cooperativeStandardDeviation(
                    values,
                    cooperativeDeadline: cooperativeDeadline
                )
            } else {
                hrStandardDeviation = standardDeviation(doubleValues)
            }
            let observedHRBinFraction = try observedBinFraction(sampleDates)
            try cooperativeDeadline?.checkpoint()

            result.append(AggregateSleepCandidate(
                kind: "resumed_sleep_candidate",
                day: matchingMain.day,
                eventTimeZoneIdentifier: eventTimeZoneIdentifier,
                sessions: includedSessions.count,
                start: candidateStart,
                end: candidateEnd,
                duration: capturedDuration,
                span: span,
                maxGap: maxGap,
                samples: values.count,
                hrObservedCoverageFraction: observedHRBinFraction,
                maximumHRSampleGap: maximumHRSampleGap,
                avgHR: avgHR,
                peakHR: orderedValues.last ?? 0,
                hrStandardDeviation: hrStandardDeviation,
                medianHR: medianHR,
                hrP90: hrP90,
                elevatedSampleFraction: elevatedFraction,
                baselineRestingHR: rest,
                restingHR: percentileHR(0.05, presorted: orderedValues),
                confidence: .low,
                reason: qualifiedRRDates.isEmpty
                    ? "Dense HR-only post-wake segment after a separate main sleep; review required; awake and reconnect gaps excluded"
                    : "Dense HR+qualified RR post-wake segment after a separate main sleep; review required; awake and reconnect gaps excluded",
                motionHintCount: includedSessions.reduce(0) {
                    $0 + $1.motionHintCountValue
                },
                motionHintKinds: motionHintKindsSummary(for: includedSessions),
                motionEvidenceSource: qualifiedRRDates.isEmpty
                    ? "strap_hr_review_only"
                    : "strap_hr_rr_review_only",
                motionEvidenceValidated: false,
                motionShortCount: includedSessions.reduce(0) {
                    $0 + $1.motionShortCountValue
                },
                motionShortMean: nil,
                motionShortMin: includedSessions.compactMap(\.motionShortMinValue).min(),
                motionShortMax: includedSessions.compactMap(\.motionShortMaxValue).max(),
                motionShortOverOneCount: includedSessions.reduce(0) {
                    $0 + $1.motionShortOverOneCountValue
                },
                historicalMotionStatus: "not_required_review_only",
                historicalMotionReason: "resumed_sleep_requires_user_confirmation",
                historicalMotionRows: 0,
                historicalMotionValidatedRows: 0,
                historicalMotionCoverageSeconds: 0,
                historicalMotionMeanVectorDelta: nil,
                historicalMotionP95VectorDelta: nil,
                historicalMotionMagnitudeStdDev: nil,
                historicalMotionArchiveFirstUnix: 0,
                historicalMotionArchiveLastUnix: 0,
                historicalMotionNearestSeparationSeconds: 0,
                historicalMotionValidated: false,
                denseMorningHROnlyReviewQualified: false,
                denseLongHROnlyReviewQualified: false
            ))
        }
        try cooperativeDeadline?.checkpoint()
        return result
    }

    func sleepEvidenceStatusFast(rest: Int,
                                 calendar: Calendar = .current,
                                 windowDays: Int = 45,
                                 limitSessions: Int = 48) -> SleepEvidenceStatus {
        let recent = recentCanonicalSessions(windowDays: windowDays, limitSessions: limitSessions)
        let candidates = Self.aggregateSleepCandidates(in: recent,
                                                       rest: rest,
                                                       maxHR: profile.maxHR,
                                                       calendar: calendar,
                                                       historicalMotionPolicy: .boundedRecent)
        let ready = candidates.filter { candidate in
            candidate.motionEvidenceValidated && candidate.confidence != .low
        }
        if let best = Self.preferredSleepCandidateForReview(from: ready) {
            return SleepEvidenceStatus(ready: true,
                                       state: "ready",
                                       blocker: "none",
                                       confidence: best.confidence.rawValue,
                                       candidates: candidates.count,
                                       readyCandidates: ready.count,
                                       motionSource: best.motionEvidenceSource,
                                       motionValidated: true,
                                       fallbackAvailable: false,
                                       fallbackSource: "none",
                                       fallbackReason: "none",
                                       fallbackDuration: 0,
                                       fallbackSpan: 0,
                                       fallbackSessions: 0)
        }

        if let best = Self.preferredSleepCandidateForReview(from: candidates) {
            return SleepEvidenceStatus(ready: false,
                                       state: "low_confidence",
                                       blocker: sleepEvidenceBlocker(for: best),
                                       confidence: best.confidence.rawValue,
                                       candidates: candidates.count,
                                       readyCandidates: 0,
                                       motionSource: best.motionEvidenceSource,
                                       motionValidated: best.motionEvidenceValidated,
                                       fallbackAvailable: true,
                                       fallbackSource: sleepFallbackSource(for: best),
                                       fallbackReason: best.reason,
                                       fallbackDuration: best.duration,
                                       fallbackSpan: best.span,
                                       fallbackSessions: best.sessions)
        }

        if let incomplete = incompleteSleepFallback(in: recent,
                                                    rest: rest,
                                                    maxHR: profile.maxHR,
                                                    calendar: calendar) {
            return SleepEvidenceStatus(ready: false,
                                       state: "low_confidence",
                                       blocker: "sleep_fragmented_below_minimum",
                                       confidence: "low",
                                       candidates: 0,
                                       readyCandidates: 0,
                                       motionSource: "unavailable",
                                       motionValidated: false,
                                       fallbackAvailable: true,
                                       fallbackSource: "incomplete_fragmented_sleep",
                                       fallbackReason: incomplete.reason,
                                       fallbackDuration: incomplete.duration,
                                       fallbackSpan: incomplete.span,
                                       fallbackSessions: incomplete.sessions)
        }

        let observedSleepDays = Set(recent.map { calendar.startOfDay(for: $0.start) }).count
        return SleepEvidenceStatus(ready: false,
                                   state: observedSleepDays > 0 ? "low_confidence" : "learning",
                                   blocker: observedSleepDays > 0 ? "sleep_low_confidence" : "sleep_learning",
                                   confidence: observedSleepDays > 0 ? "low" : "none",
                                   candidates: 0,
                                   readyCandidates: 0,
                                   motionSource: "unavailable",
                                   motionValidated: false,
                                   fallbackAvailable: false,
                                   fallbackSource: "none",
                                   fallbackReason: "none",
                                   fallbackDuration: 0,
                                   fallbackSpan: 0,
                                   fallbackSessions: 0)
    }

    func sleepEvidenceStatus(rest: Int,
                             calendar: Calendar = .current,
                             sleepDays: Int? = nil) -> SleepEvidenceStatus {
        let candidates = aggregateSleepCandidates(rest: rest,
                                                   calendar: calendar,
                                                   historicalMotionPolicy: .boundedRecent)
        let ready = candidates.filter { candidate in
            candidate.motionEvidenceValidated && candidate.confidence != .low
        }
        if let best = Self.preferredSleepCandidateForReview(from: ready) {
            return SleepEvidenceStatus(ready: true,
                                       state: "ready",
                                       blocker: "none",
                                       confidence: best.confidence.rawValue,
                                       candidates: candidates.count,
                                       readyCandidates: ready.count,
                                       motionSource: best.motionEvidenceSource,
                                       motionValidated: true,
                                       fallbackAvailable: false,
                                       fallbackSource: "none",
                                       fallbackReason: "none",
                                       fallbackDuration: 0,
                                       fallbackSpan: 0,
                                       fallbackSessions: 0)
        }

        let observedSleepDays = sleepDays ?? (candidates.isEmpty ? 0 : candidates.count)
        if let best = Self.preferredSleepCandidateForReview(from: candidates) {
            return SleepEvidenceStatus(ready: false,
                                       state: "low_confidence",
                                       blocker: sleepEvidenceBlocker(for: best),
                                       confidence: best.confidence.rawValue,
                                       candidates: candidates.count,
                                       readyCandidates: 0,
                                       motionSource: best.motionEvidenceSource,
                                       motionValidated: best.motionEvidenceValidated,
                                       fallbackAvailable: true,
                                       fallbackSource: sleepFallbackSource(for: best),
                                       fallbackReason: best.reason,
                                       fallbackDuration: best.duration,
                                       fallbackSpan: best.span,
                                       fallbackSessions: best.sessions)
        }

        if let incomplete = incompleteSleepFallback(in: canonicalSessions(),
                                                    rest: rest,
                                                    maxHR: profile.maxHR,
                                                    calendar: calendar) {
            return SleepEvidenceStatus(ready: false,
                                       state: "low_confidence",
                                       blocker: "sleep_fragmented_below_minimum",
                                       confidence: "low",
                                       candidates: 0,
                                       readyCandidates: 0,
                                       motionSource: "unavailable",
                                       motionValidated: false,
                                       fallbackAvailable: true,
                                       fallbackSource: "incomplete_fragmented_sleep",
                                       fallbackReason: incomplete.reason,
                                       fallbackDuration: incomplete.duration,
                                       fallbackSpan: incomplete.span,
                                       fallbackSessions: incomplete.sessions)
        }

        return SleepEvidenceStatus(ready: false,
                                   state: observedSleepDays > 0 ? "low_confidence" : "learning",
                                   blocker: observedSleepDays > 0 ? "sleep_low_confidence" : "sleep_learning",
                                   confidence: observedSleepDays > 0 ? "low" : "none",
                                   candidates: 0,
                                   readyCandidates: 0,
                                   motionSource: "unavailable",
                                   motionValidated: false,
                                   fallbackAvailable: false,
                                   fallbackSource: "none",
                                   fallbackReason: "none",
                                   fallbackDuration: 0,
                                   fallbackSpan: 0,
                                   fallbackSessions: 0)
    }

    private func sleepEvidenceBlocker(for candidate: AggregateSleepCandidate) -> String {
        if Self.isStrapOnlyMainSleepReviewCandidate(candidate) {
            return "sleep_review_pending_user_confirmation"
        }
        if candidate.motionEvidenceValidated && candidate.confidence == .low {
            return "sleep_low_confidence_threshold"
        }
        if !candidate.motionEvidenceValidated {
            switch candidate.historicalMotionReason {
            case "no_historical_gravity":
                return "sleep_motion_unvalidated_no_historical_gravity"
            case "no_timestamp_overlap":
                return "sleep_motion_unvalidated_no_historical_overlap"
            case "historical_archive_stale":
                return "sleep_motion_unvalidated_historical_stale"
            case "historical_archive_future_or_misaligned":
                return "sleep_motion_unvalidated_historical_misaligned"
            case "insufficient_validated_gravity":
                return "sleep_motion_unvalidated_insufficient_gravity"
            case "insufficient_overlap_coverage":
                return "sleep_motion_unvalidated_insufficient_coverage"
            case "vector_delta_high":
                return "sleep_motion_unvalidated_motion_too_high"
            case "magnitude_variance_high":
                return "sleep_motion_unvalidated_variance_too_high"
            default:
                return candidate.motionHintCount > 0
                    ? "sleep_motion_hint_observe_only"
                    : "sleep_motion_unvalidated"
            }
        }
        return "sleep_low_confidence"
    }

    private func sleepFallbackSource(for candidate: AggregateSleepCandidate) -> String {
        if candidate.kind == "resumed_sleep_candidate" { return "hr_only_resumed_sleep" }
        if candidate.kind == "nap_candidate" { return "hr_only_nap" }
        return candidate.sessions > 1 ? "hr_only_fragmented_sleep" : "hr_only_sleep"
    }

    private func sleepCandidateSource(for candidate: AggregateSleepCandidate) -> String {
        if candidate.kind == "resumed_sleep_candidate" { return "resumed_sleep_candidate" }
        if candidate.kind == "nap_candidate" { return "nap_candidate" }
        return candidate.sessions > 1 ? "aggregate_sleep" : "sleep_window"
    }

    private func incompleteSleepFallback(in sourceSessions: [SavedSession],
                                         rest: Int,
                                         maxHR: Int,
                                         calendar: Calendar = .current) -> IncompleteSleepFallback? {
        let fragments = sourceSessions.filter { session in
            guard session.duration >= 60, !session.points.isEmpty else { return false }
            let eventCalendar = EventCivilTime.eventCalendar(timeZoneIdentifier: session.eventTimeZoneIdentifier,
                                                             fallback: calendar)
            let startHour = eventCalendar.component(.hour, from: session.start)
            let endHour = eventCalendar.component(.hour, from: session.end)
            let overnight = startHour >= 20 || startHour <= 5 || endHour <= 11
            let plausibleRestHR = session.avg <= rest + 40 && session.peak <= rest + 65
            return overnight
                && plausibleRestHR
                && !session.workoutReadiness(rest: rest, maxHR: maxHR).ready
        }
        let clusters = Self.sleepClusters(from: fragments.sorted { $0.start < $1.start },
                                          maxGap: 2 * 60 * 60,
                                          rest: rest,
                                          calendar: calendar)
        return clusters.compactMap { cluster -> IncompleteSleepFallback? in
            guard let start = cluster.first?.start, let end = cluster.last?.end else { return nil }
            let duration = cluster.reduce(0) { $0 + $1.duration }
            let span = end.timeIntervalSince(start)
            guard duration >= 5 * 60 || span >= 30 * 60 else { return nil }
            let reason = "Fragmented overnight HR persisted below the sleep minimum; historical backfill or steadier overnight capture is needed before Atria counts it as sleep."
            return IncompleteSleepFallback(duration: duration,
                                           span: span,
                                           sessions: cluster.count,
                                           reason: reason)
        }
        .sorted { lhs, rhs in
            if lhs.span != rhs.span { return lhs.span > rhs.span }
            return lhs.duration > rhs.duration
        }
        .first
    }

    func aggregateSleepDiagnostics(rest: Int, calendar: Calendar = .current) -> (evaluated: Int, eligible: Int, tooShort: Int, notOvernight: Int, hrTooHigh: Int, workoutLike: Int, candidates: Int) {
        Self.aggregateSleepDiagnostics(in: canonicalSessions(),
                                       rest: rest,
                                       maxHR: profile.maxHR,
                                       calendar: calendar)
    }

    private nonisolated static func aggregateSleepDiagnostics(in sourceSessions: [SavedSession],
                                                              rest: Int,
                                                              maxHR: Int,
                                                              calendar: Calendar = .current,
                                                              candidateCount: Int? = nil) -> (evaluated: Int, eligible: Int, tooShort: Int, notOvernight: Int, hrTooHigh: Int, workoutLike: Int, candidates: Int) {
        var evaluated = 0
        var eligible = 0
        var tooShort = 0
        var notOvernight = 0
        var hrTooHigh = 0
        var workoutLike = 0
        for session in sourceSessions {
            guard !session.points.isEmpty else { continue }
            evaluated += 1
            if session.duration < 20 * 60 {
                tooShort += 1
                continue
            }
            let eventCalendar = EventCivilTime.eventCalendar(timeZoneIdentifier: session.eventTimeZoneIdentifier,
                                                             fallback: calendar)
            let startHour = eventCalendar.component(.hour, from: session.start)
            let endHour = eventCalendar.component(.hour, from: session.end)
            let overnight = startHour >= 20 || startHour <= 5 || endHour <= 11
            let napLike = !overnight
                && startHour >= 11
                && endHour <= 20
                && session.duration >= AggregateSleepCandidate.napMinimumDuration
                && session.duration <= AggregateSleepCandidate.napMaximumSpan
                && session.avg <= rest + 12
                && session.peak <= rest + 35
            if !overnight && !napLike {
                notOvernight += 1
                continue
            }
            let lowHR = napLike || (session.avg <= rest + 18 && session.peak <= rest + 55)
            if !lowHR {
                hrTooHigh += 1
                continue
            }
            if session.workoutReadiness(rest: rest, maxHR: maxHR).ready {
                workoutLike += 1
                continue
            }
            eligible += 1
        }
        let candidates = candidateCount ?? aggregateSleepCandidates(in: sourceSessions,
                                                                     rest: rest,
                                                                     maxHR: maxHR,
                                                                     calendar: calendar,
                                                                     historicalMotionPolicy: .boundedRecent).count
        return (evaluated, eligible, tooShort, notOvernight, hrTooHigh, workoutLike, candidates)
    }

    private nonisolated static func motionHintKindsSummary(for sessions: [SavedSession]) -> String {
        let kinds = sessions
            .map(\.motionHintKindsValue)
            .filter { $0 != "none" }
        return kinds.isEmpty ? "none" : kinds.joined(separator: "+")
    }

    private nonisolated static func motionShortSummary(for sessions: [SavedSession]) -> (count: Int, mean: Double?, min: Double?, max: Double?, overOne: Int) {
        let count = sessions.reduce(0) { $0 + $1.motionShortCountValue }
        guard count > 0 else { return (0, nil, nil, nil, 0) }
        let weightedSum = sessions.reduce(0.0) { total, session in
            total + ((session.motionShortMeanValue ?? 0) * Double(session.motionShortCountValue))
        }
        let valuesWithMin = sessions.compactMap(\.motionShortMinValue)
        let valuesWithMax = sessions.compactMap(\.motionShortMaxValue)
        let overOne = sessions.reduce(0) { $0 + $1.motionShortOverOneCountValue }
        return (count,
                weightedSum / Double(count),
                valuesWithMin.min(),
                valuesWithMax.max(),
                overOne)
    }

    func trendSummaries(rest: Int, maxHR: Int) -> [TrendSummary] {
        let now = Date()
        let calendar = Calendar.current
        let rollups = dailyRollups(rest: rest, maxHR: maxHR)
        let maximumWindowDays = TrendSummary.Window.allCases.map(\.rawValue).max() ?? 0
        let oldestCutoff = now.addingTimeInterval(-Double(maximumWindowDays) * 24 * 60 * 60)
        let trendSessions = sessions.filter { $0.start >= oldestCutoff }
        return TrendSummary.Window.allCases.map { window in
            let diagnosticCutoff = calendar.date(byAdding: .day,
                                                 value: -(window.rawValue - 1),
                                                 to: calendar.startOfDay(for: now))
                ?? calendar.startOfDay(for: now)
            return Self.dailyMetricTrendSummary(
                metrics: dailyMetricHistory,
                rollups: rollups,
                days: window.rawValue,
                now: now,
                diagnosticSessionCount: trendSessions.filter {
                    $0.start >= diagnosticCutoff
                }.count,
                calendar: calendar
            )
        }
    }

    func trainingLoadSummary(rest: Int, maxHR: Int) -> TrainingLoadSummary {
        trainingLoadSummarySnapshot
    }

    func vo2MaxEstimateSummary(rest: Int, maxHR: Int) -> VO2MaxEstimateSummary {
        AtriaAnalytics.VO2Max.summary(rest: rest,
                                      maxHR: maxHR,
                                      restingSamples: baseline.freshRestingSampleCount(),
                                      maxHRMeasured: profile.maxHRSource == .measured,
                                      restingTrend: restingTrend14)
    }

    /// Fitness age is a weekly, slow-moving metric. A valid persisted result is
    /// returned immediately; cold or expired work is coalesced and computed away
    /// from the main actor. Both ready and calibrating outcomes are persisted so
    /// opening the screen never becomes the trigger for another history scan.
    func biologicalAgeSummary(vo2MaxEstimate: VO2MaxEstimateSummary) -> BiologicalAgeSummary {
        let now = Date()
        let cadenceKey = Self.biologicalAgeWeeklyCadenceKey(profile: profile,
                                                            sessionsLoaded: hasCompletedDeferredSessionLoad,
                                                            now: now)
        let prerequisitesReady = biologicalAgePrerequisitesReady(
            vo2MaxEstimate: vo2MaxEstimate,
            now: now
        )
        let cachedLearningProgressChanged = cachedBiologicalAge.map {
            !$0.summary.isReady
                && Self.biologicalAgeLearningProgressChanged(
                    cached: $0.signature,
                    vo2MaxEstimate: vo2MaxEstimate,
                    dailyMetricCount: dailyMetricHistory.count,
                    confirmedSleeps: cachedConfirmedSleeps,
                    baseline: baseline,
                    trainingLoadSummary: trainingLoadSummarySnapshot,
                    now: now
                )
        } ?? false
        let weeklyLearningProgressChanged = cachedBiologicalAgeWeeklySummary.map {
            !$0.summary.isReady
                && Self.biologicalAgeLearningProgressChanged(
                    cached: $0.signature,
                    vo2MaxEstimate: vo2MaxEstimate,
                    dailyMetricCount: dailyMetricHistory.count,
                    confirmedSleeps: cachedConfirmedSleeps,
                    baseline: baseline,
                    trainingLoadSummary: trainingLoadSummarySnapshot,
                    now: now
                )
        } ?? false
        if let cached = cachedBiologicalAge,
           Self.isBiologicalAgeCacheCadenceFresh(cached,
                                                 profile: profile,
                                                 sessionsLoaded: hasCompletedDeferredSessionLoad,
                                                 now: now),
           !cachedLearningProgressChanged,
           Self.shouldReuseBiologicalAgeCadenceSummary(
               cached.summary,
               prerequisitesReady: prerequisitesReady
           ) {
            return cached.summary
        }
        if let weekly = cachedBiologicalAgeWeeklySummary,
           Self.isBiologicalAgeWeeklyCadenceFresh(weekly, cadenceKey: cadenceKey),
           !weeklyLearningProgressChanged,
           Self.shouldReuseBiologicalAgeCadenceSummary(
               weekly.summary,
               prerequisitesReady: prerequisitesReady
           ) {
            return weekly.summary
        }
        // Ordinary source/signature churn stays on the one-computation-per-week
        // cadence. An explicit cadence/profile change is exceptional: the old
        // result no longer describes this athlete, so allow one replacement in
        // the same week instead of leaving Fitness Age blank until Monday.
        if cachedBiologicalAge.map({
            $0.schema == Self.biologicalAgeCacheSchema && Self.shouldDeferBiologicalAgeRefreshUntilNextWeek(
                recordWeekStart: Self.biologicalAgeCacheWeekStart(for: $0.computedAt),
                recordCadenceKey: $0.cadenceKey,
                requestedCadenceKey: cadenceKey
            ) && !cachedLearningProgressChanged
        }) == true || cachedBiologicalAgeWeeklySummary.map({
            $0.schema == Self.biologicalAgeCacheSchema && Self.shouldDeferBiologicalAgeRefreshUntilNextWeek(
                recordWeekStart: $0.weekStart,
                recordCadenceKey: $0.cadenceKey,
                requestedCadenceKey: cadenceKey
            ) && !weeklyLearningProgressChanged
        }) == true {
            return BiologicalAgeSummary.refreshing(chronologicalAge: profile.age)
        }
        // A cold install waits for the deferred archive load so its one allowed
        // computation for this week includes the complete session history.
        guard hasCompletedDeferredSessionLoad else {
            return BiologicalAgeSummary.refreshing(chronologicalAge: profile.age)
        }
        scheduleBiologicalAgeRefresh(vo2MaxEstimate: vo2MaxEstimate,
                                     cadenceKey: cadenceKey,
                                     now: now)

        // A same-week calibrating record may have been written before the last
        // prerequisite became qualified. Once the inputs are ready, never keep
        // presenting that stale blocker while its bounded off-main replacement
        // is running.
        if prerequisitesReady {
            return BiologicalAgeSummary.refreshing(chronologicalAge: profile.age)
        }
        if let cached = cachedBiologicalAge,
           Self.biologicalAgeCacheMatchesProfile(cached, profile: profile) {
            return cached.summary
        }
        if let weekly = cachedBiologicalAgeWeeklySummary,
           weekly.cadenceKey?.profileAge == profile.age,
           weekly.cadenceKey?.biologicalSex == profile.biologicalSex,
           weekly.cadenceKey?.maxHR == profile.maxHR,
           weekly.cadenceKey?.maxHRSource == profile.maxHRSource {
            return weekly.summary
        }
        return BiologicalAgeSummary.refreshing(chronologicalAge: profile.age)
    }

    private func biologicalAgePrerequisitesReady(
        vo2MaxEstimate: VO2MaxEstimateSummary,
        now: Date
    ) -> Bool {
        guard vo2MaxEstimate.value != nil,
              baseline.hasTrustedRestingBaseline(now: now),
              baseline.hasTrustedHRVBaseline(now: now),
              trainingLoadSummarySnapshot.confidence == "local" else {
            return false
        }
        let overnightSleepCount = cachedConfirmedSleeps.reduce(into: 0) { count, sleep in
            if !Self.confirmedSleepSourceIsNap(source: sleep.source, duration: sleep.duration) {
                count += 1
            }
        }
        return overnightSleepCount >= 3
    }

    nonisolated static func shouldReuseBiologicalAgeCadenceSummary(
        _ summary: BiologicalAgeSummary,
        prerequisitesReady: Bool
    ) -> Bool {
        summary.isReady || !prerequisitesReady
    }

    /// A weekly ready Fitness Age remains intentionally stable. A not-ready
    /// cache is different: it is progress UI, and must not keep saying 0/14
    /// after confirmed nights have populated the baseline. This comparison is
    /// deliberately count-only so foreground reads never rescan session rows.
    nonisolated static func biologicalAgeLearningProgressChanged(
        cached: BiologicalAgeCacheSignature,
        vo2MaxEstimate: VO2MaxEstimateSummary,
        dailyMetricCount: Int,
        confirmedSleeps: [UserConfirmedSleep],
        baseline: PersonalBaseline,
        trainingLoadSummary: TrainingLoadSummary,
        now: Date = Date()
    ) -> Bool {
        let confirmedOvernightSleepCount = confirmedSleeps.reduce(0) { count, sleep in
            count + (confirmedSleepSourceIsNap(source: sleep.source, duration: sleep.duration) ? 0 : 1)
        }
        return cached.vo2MaxValueTenth != scaledInt(vo2MaxEstimate.value, scale: 10)
            || cached.vo2MaxConfidence != vo2MaxEstimate.confidence
            || cached.dailyMetricCount != dailyMetricCount
            || cached.confirmedOvernightSleepCount != confirmedOvernightSleepCount
            || cached.baselineRestingHR != baseline.restingInt
            || cached.baselineHRV != baseline.hrvInt
            || cached.baselineFreshRestingDays != baseline.freshRestingSampleCount(now: now)
            || cached.baselineFreshHRVDays != baseline.freshHRVSampleCount(now: now)
            || cached.trainingLoadConfidence != trainingLoadSummary.confidence
    }

    /// The Healthspan detail history prepared with the current weekly
    /// biological-age cache. A stale week/profile never leaks into the detail
    /// view, and reading this property performs no rollup scan or regression.
    var biologicalAgeHealthspanDetailProjection: AtriaFitnessAge.DetailProjection? {
        let cadenceKey = Self.biologicalAgeWeeklyCadenceKey(profile: profile,
                                                            sessionsLoaded: hasCompletedDeferredSessionLoad)
        if let cached = cachedBiologicalAge,
           Self.isBiologicalAgeCacheCadenceFresh(cached,
                                                 profile: profile,
                                                 sessionsLoaded: hasCompletedDeferredSessionLoad),
           cached.cadenceKey == cadenceKey {
            return cached.detailProjection
        }
        if let weekly = cachedBiologicalAgeWeeklySummary,
           Self.isBiologicalAgeWeeklyCadenceFresh(weekly, cadenceKey: cadenceKey) {
            return weekly.detailProjection
        }
        return nil
    }

    private func scheduleBiologicalAgeRefresh(vo2MaxEstimate: VO2MaxEstimateSummary,
                                              cadenceKey: BiologicalAgeWeeklyCadenceKey,
                                              now: Date) {
        let memoKey = Self.biologicalAgeSignatureMemoKey(profile: profile,
                                                         vo2MaxEstimate: vo2MaxEstimate,
                                                         dailyMetricHistoryRevision: dailyMetricHistoryRevision,
                                                         sleepHistorySnapshotRevision: sleepHistorySnapshotRevision,
                                                         confirmedSleepsRevision: confirmedSleepsRevision,
                                                         canonicalSessionsRevision: canonicalSessionsRevision,
                                                         sourceSessionsRevision: biologicalAgeSourceSessionsRevision,
                                                         canonicalSessionCount: cachedCanonicalSessions.count,
                                                         sessionsLoaded: hasCompletedDeferredSessionLoad,
                                                         baseline: baseline,
                                                         trainingLoadSummary: trainingLoadSummarySnapshot,
                                                         now: now)
        // Input revisions may advance while a calculation is in flight. Coalesce
        // ordinary churn by the full weekly cadence key. A profile-key change may
        // supersede the old request and compute one replacement for this week.
        let requestKey = BiologicalAgeRefreshRequestKey(cadenceKey: cadenceKey)
        guard pendingBiologicalAgeRefreshKey != requestKey else { return }
        biologicalAgeRefreshGeneration &+= 1
        let generation = biologicalAgeRefreshGeneration
        pendingBiologicalAgeRefreshKey = requestKey
        let input = BiologicalAgeComputationInput(profile: profile,
                                                  vo2MaxEstimate: vo2MaxEstimate,
                                                  dailyMetricHistory: dailyMetricHistory,
                                                  dailyRollupHistory: dailyRollupHistory,
                                                  sleepHistorySnapshot: sleepHistorySnapshot,
                                                  confirmedSleeps: cachedConfirmedSleeps,
                                                  confirmedWorkouts: cachedConfirmedWorkouts,
                                                  canonicalSessions: cachedCanonicalSessions,
                                                  baseline: baseline,
                                                  trainingLoadSummary: trainingLoadSummarySnapshot,
                                                  todayHRZoneMinutes: todayHRZoneMinutesSnapshot,
                                                  now: now)
        DispatchQueue.global(qos: .utility).async { [weak self] in
            let output = Self.computeBiologicalAgeOutput(input)
            DispatchQueue.main.async { [weak self] in
                guard let self,
                      generation == self.biologicalAgeRefreshGeneration,
                      self.pendingBiologicalAgeRefreshKey == requestKey else { return }
                self.pendingBiologicalAgeRefreshKey = nil
                self.cachedBiologicalAgeSignatureMemo = (memoKey, output.signature)
                let weekly = BiologicalAgeWeeklySummaryRecord(schema: Self.biologicalAgeCacheSchema,
                                                               weekStart: cadenceKey.weekStart,
                                                               cadenceKey: cadenceKey,
                                                               signature: output.signature,
                                                               summary: output.summary,
                                                               detailProjection: output.detailProjection)
                let persisted = BiologicalAgeCacheRecord(schema: Self.biologicalAgeCacheSchema,
                                                         computedAt: now,
                                                         cadenceKey: cadenceKey,
                                                         signature: output.signature,
                                                         summary: output.summary,
                                                         detailProjection: output.detailProjection)
                self.cachedBiologicalAgeWeeklySummary = weekly
                self.cachedBiologicalAge = persisted
                self.persistBiologicalAgeCache(persisted)
                self.biologicalAgeSummaryRevision &+= 1
                self.dashboardRevision &+= 1
            }
        }
    }

    private nonisolated static func computeBiologicalAgeOutput(_ input: BiologicalAgeComputationInput) -> BiologicalAgeComputationOutput {
        let signature = biologicalAgeCacheSignature(profile: input.profile,
                                                     vo2MaxEstimate: input.vo2MaxEstimate,
                                                     dailyMetricHistory: input.dailyMetricHistory,
                                                     sleepHistorySnapshot: input.sleepHistorySnapshot,
                                                     confirmedSleeps: input.confirmedSleeps,
                                                     canonicalSessions: input.canonicalSessions,
                                                     baseline: input.baseline,
                                                     trainingLoadSummary: input.trainingLoadSummary,
                                                     todayHRZoneMinutes: input.todayHRZoneMinutes,
                                                     now: input.now)
        let summary = computeBiologicalAgeSummary(input)
        let dailyDeltas = input.dailyRollupHistory.compactMap { entry in
            entry.fitnessAgeDelta.map {
                AtriaFitnessAge.DailyDelta(day: entry.day, delta: $0)
            }
        }
        return BiologicalAgeComputationOutput(
            signature: signature,
            summary: summary,
            detailProjection: AtriaFitnessAge.detailProjection(deltas: dailyDeltas)
        )
    }

    nonisolated static func biologicalAgeWeeklyCadenceKey(profile: AthleteProfile,
                                                          sessionsLoaded: Bool = false,
                                                          now: Date = Date(),
                                                          calendar: Calendar = .current) -> BiologicalAgeWeeklyCadenceKey {
        BiologicalAgeWeeklyCadenceKey(weekStart: biologicalAgeCacheWeekStart(for: now, calendar: calendar),
                                      profileAge: profile.age,
                                      maxHR: profile.maxHR,
                                      maxHRSource: profile.maxHRSource,
                                      biologicalSex: profile.biologicalSex,
                                      sessionsLoaded: sessionsLoaded)
    }

    private func biologicalAgeCacheSignature(vo2MaxEstimate: VO2MaxEstimateSummary,
                                             now: Date) -> BiologicalAgeCacheSignature {
        let key = Self.biologicalAgeSignatureMemoKey(profile: profile,
                                                     vo2MaxEstimate: vo2MaxEstimate,
                                                     dailyMetricHistoryRevision: dailyMetricHistoryRevision,
                                                     sleepHistorySnapshotRevision: sleepHistorySnapshotRevision,
                                                     confirmedSleepsRevision: confirmedSleepsRevision,
                                                     canonicalSessionsRevision: canonicalSessionsRevision,
                                                     sourceSessionsRevision: biologicalAgeSourceSessionsRevision,
                                                     canonicalSessionCount: cachedCanonicalSessions.count,
                                                     sessionsLoaded: hasCompletedDeferredSessionLoad,
                                                     baseline: baseline,
                                                     trainingLoadSummary: trainingLoadSummarySnapshot,
                                                     now: now)
        if let memo = cachedBiologicalAgeSignatureMemo,
           memo.key == key {
            return memo.signature
        }

        let signature = Self.biologicalAgeCacheSignature(profile: profile,
                                                         vo2MaxEstimate: vo2MaxEstimate,
                                                         dailyMetricHistory: dailyMetricHistory,
                                                         sleepHistorySnapshot: sleepHistorySnapshot,
                                                         confirmedSleeps: cachedConfirmedSleeps,
                                                         canonicalSessions: cachedCanonicalSessions,
                                                         baseline: baseline,
                                                         trainingLoadSummary: trainingLoadSummarySnapshot,
                                                         todayHRZoneMinutes: todayHRZoneMinutesSnapshot,
                                                         now: now)
        cachedBiologicalAgeSignatureMemo = (key, signature)
        return signature
    }

    nonisolated static func biologicalAgeSignatureMemoKey(profile: AthleteProfile,
                                                          vo2MaxEstimate: VO2MaxEstimateSummary? = nil,
                                                          dailyMetricHistoryRevision: Int,
                                                          sleepHistorySnapshotRevision: Int,
                                                          confirmedSleepsRevision: Int,
                                                          canonicalSessionsRevision: Int,
                                                          sourceSessionsRevision: Int = 0,
                                                          canonicalSessionCount: Int,
                                                          sessionsLoaded: Bool,
                                                          baseline: PersonalBaseline = PersonalBaseline(),
                                                          trainingLoadSummary: TrainingLoadSummary = .learning,
                                                          now: Date = Date(),
                                                          calendar: Calendar = .current) -> BiologicalAgeSignatureMemoKey {
        // The full signature still fingerprints historical rows, but this key
        // decides when that expensive scan is allowed to happen. Same-week live
        // checkpoints replace points inside an existing canonical session often;
        // biological age is a weekly metric, so those checkpoint edits should not
        // rescan the whole archive before returning the weekly cache.
        _ = canonicalSessionsRevision
        return BiologicalAgeSignatureMemoKey(weekStart: biologicalAgeCacheWeekStart(for: now, calendar: calendar),
                                      profileAge: profile.age,
                                      biologicalSex: profile.biologicalSex,
                                      maxHR: profile.maxHR,
                                      maxHRSource: profile.maxHRSource,
                                      vo2MaxValueTenth: scaledInt(vo2MaxEstimate?.value, scale: 10),
                                      vo2MaxConfidence: vo2MaxEstimate?.confidence ?? "",
                                      vo2MaxTrendDeltaTenth: scaledInt(vo2MaxEstimate?.trendDelta, scale: 10),
                                      dailyMetricHistoryRevision: dailyMetricHistoryRevision,
                                      sleepHistorySnapshotRevision: sleepHistorySnapshotRevision,
                                      confirmedSleepsRevision: confirmedSleepsRevision,
                                      sourceSessionsRevision: sourceSessionsRevision,
                                      canonicalSessionCount: canonicalSessionCount,
                                      sessionsLoaded: sessionsLoaded,
                                      baselineRestingHR: baseline.restingInt,
                                      baselineHRV: baseline.hrvInt,
                                      baselineFreshRestingDays: baseline.freshRestingSampleCount(now: now),
                                      baselineFreshHRVDays: baseline.freshHRVSampleCount(now: now),
                                      baselineUpdatedAt: baseline.updated,
                                      trainingLoadConfidence: trainingLoadSummary.confidence)
    }

    nonisolated static func biologicalAgeCacheSignature(profile: AthleteProfile,
                                                        vo2MaxEstimate: VO2MaxEstimateSummary? = nil,
                                                        dailyMetricHistory: [SavedDailyMetric] = [],
                                                        sleepHistorySnapshot: SleepHistorySnapshot = .empty,
                                                        confirmedSleeps: [UserConfirmedSleep] = [],
                                                        canonicalSessions: [SavedSession] = [],
                                                        baseline: PersonalBaseline = PersonalBaseline(),
                                                        trainingLoadSummary: TrainingLoadSummary = .learning,
                                                        todayHRZoneMinutes: TodayHRZoneMinutes = .empty,
                                                        now: Date = Date()) -> BiologicalAgeCacheSignature {
        let confirmedOvernightSleepCount = confirmedSleeps.reduce(0) { count, sleep in
            count + (confirmedSleepSourceIsNap(source: sleep.source, duration: sleep.duration) ? 0 : 1)
        }
        return BiologicalAgeCacheSignature(profileAge: profile.age,
                                           biologicalSex: profile.biologicalSex,
                                           maxHR: profile.maxHR,
                                           maxHRSource: profile.maxHRSource,
                                           vo2MaxValueTenth: scaledInt(vo2MaxEstimate?.value, scale: 10),
                                           vo2MaxConfidence: vo2MaxEstimate?.confidence ?? "",
                                           vo2MaxTrendDeltaTenth: scaledInt(vo2MaxEstimate?.trendDelta, scale: 10),
                                           dailyMetricCount: dailyMetricHistory.count,
                                           dailyMetricFingerprint: biologicalAgeDailyMetricFingerprint(dailyMetricHistory),
                                           sleepHistoryNightCount: sleepHistorySnapshot.nights.count,
                                           sleepHistoryFingerprint: biologicalAgeSleepHistoryFingerprint(sleepHistorySnapshot),
                                           confirmedOvernightSleepCount: confirmedOvernightSleepCount,
                                           confirmedSleepFingerprint: biologicalAgeConfirmedSleepFingerprint(confirmedSleeps),
                                           canonicalSessionCount: canonicalSessions.count,
                                           latestCanonicalSessionEnd: latestCanonicalSessionEnd(in: canonicalSessions),
                                           canonicalSessionFingerprint: biologicalAgeCanonicalSessionFingerprint(canonicalSessions),
                                           baselineRestingHR: baseline.restingInt,
                                           baselineHRV: baseline.hrvInt,
                                           baselineFreshRestingDays: baseline.freshRestingSampleCount(now: now),
                                           baselineFreshHRVDays: baseline.freshHRVSampleCount(now: now),
                                           baselineUpdatedAt: baseline.updated,
                                           trainingLoadConfidence: trainingLoadSummary.confidence,
                                           todayZone2PlusMinutes: todayHRZoneMinutes.activeMinutes)
    }

    private nonisolated static let biologicalAgeFingerprintSeed: UInt64 = 14_695_981_039_346_656_037
    private nonisolated static let biologicalAgeFingerprintPrime: UInt64 = 1_099_511_628_211

    private nonisolated static func scaledInt(_ value: Double?,
                                              scale: Double) -> Int? {
        value.map { Int(($0 * scale).rounded()) }
    }

    private nonisolated static func latestCanonicalSessionEnd(in sessions: [SavedSession]) -> Date? {
        sessions.reduce(nil as Date?) { latest, session in
            guard let latest else { return session.end }
            return max(latest, session.end)
        }
    }

    private nonisolated static func biologicalAgeDailyMetricFingerprint(_ metrics: [SavedDailyMetric]) -> UInt64 {
        var fingerprint = biologicalAgeFingerprintSeed
        for metric in metrics {
            var row = biologicalAgeFingerprintSeed
            mixBiologicalAgeFingerprint(&row, secondsSinceReference(metric.day))
            mixOptionalInt(&row, metric.restingHR)
            mixOptionalInt(&row, metric.hrv)
            mixOptionalInt(&row, metric.sleepConsistencyPercent)
            mixOptionalDouble(&row, metric.strain, scale: 10)
            mixBiologicalAgeFingerprint(&fingerprint, Int64(bitPattern: row))
        }
        mixBiologicalAgeFingerprint(&fingerprint, Int64(metrics.count))
        return fingerprint
    }

    private nonisolated static func biologicalAgeSleepHistoryFingerprint(_ snapshot: SleepHistorySnapshot) -> UInt64 {
        var fingerprint = biologicalAgeFingerprintSeed
        mixOptionalInt(&fingerprint, snapshot.sleepConsistencyPercent)
        mixBiologicalAgeFingerprint(&fingerprint, Int64(snapshot.confirmedCount))
        mixBiologicalAgeFingerprint(&fingerprint, Int64(snapshot.candidateCount))
        for night in snapshot.nights {
            var row = biologicalAgeFingerprintSeed
            mixBiologicalAgeFingerprint(&row, secondsSinceReference(night.day))
            mixOptionalDate(&row, night.start)
            mixOptionalDate(&row, night.end)
            mixBiologicalAgeFingerprint(&row, Int64(night.duration.rounded()))
            mixOptionalInt(&row, night.restingHR)
            mixOptionalInt(&row, night.hrv)
            mixOptionalDouble(&row, night.sleepEfficiency, scale: 100)
            mixStableString(&row, night.source)
            mixBiologicalAgeFingerprint(&row, night.confirmed ? 1 : 0)
            mixBiologicalAgeFingerprint(&fingerprint, Int64(bitPattern: row))
        }
        mixBiologicalAgeFingerprint(&fingerprint, Int64(snapshot.nights.count))
        return fingerprint
    }

    private nonisolated static func biologicalAgeConfirmedSleepFingerprint(_ sleeps: [UserConfirmedSleep]) -> UInt64 {
        var fingerprint = biologicalAgeFingerprintSeed
        for sleep in sleeps {
            var row = biologicalAgeFingerprintSeed
            mixStableString(&row, sleep.id)
            mixBiologicalAgeFingerprint(&row, secondsSinceReference(sleep.start))
            mixBiologicalAgeFingerprint(&row, secondsSinceReference(sleep.end))
            mixBiologicalAgeFingerprint(&row, Int64(sleep.duration.rounded()))
            mixBiologicalAgeFingerprint(&row, Int64(sleep.span.rounded()))
            mixStableString(&row, sleep.source)
            mixOptionalInt(&row, sleep.hrv)
            mixBiologicalAgeFingerprint(&row, Int64(sleep.restingHR))
            mixBiologicalAgeFingerprint(&fingerprint, Int64(bitPattern: row))
        }
        mixBiologicalAgeFingerprint(&fingerprint, Int64(sleeps.count))
        return fingerprint
    }

    private nonisolated static func biologicalAgeCanonicalSessionFingerprint(_ sessions: [SavedSession]) -> UInt64 {
        var fingerprint = biologicalAgeFingerprintSeed
        for session in sessions {
            var row = biologicalAgeFingerprintSeed
            mixStableString(&row, session.id.uuidString)
            mixBiologicalAgeFingerprint(&row, secondsSinceReference(session.start))
            mixBiologicalAgeFingerprint(&row, secondsSinceReference(session.end))
            mixBiologicalAgeFingerprint(&row, Int64(session.duration.rounded()))
            mixBiologicalAgeFingerprint(&row, Int64(session.points.count))
            if let first = session.points.first {
                mixOptionalDouble(&row, first.t, scale: 10)
                mixBiologicalAgeFingerprint(&row, Int64(first.bpm))
            }
            if let last = session.points.last {
                mixOptionalDouble(&row, last.t, scale: 10)
                mixBiologicalAgeFingerprint(&row, Int64(last.bpm))
            }
            mixOptionalInt(&row, session.hrv)
            mixOptionalDouble(&row, session.hrvSDNN, scale: 10)
            mixStableString(&row, session.kind ?? "")
            mixBiologicalAgeFingerprint(&fingerprint, Int64(bitPattern: row))
        }
        mixBiologicalAgeFingerprint(&fingerprint, Int64(sessions.count))
        return fingerprint
    }

    private nonisolated static func mixOptionalDate(_ fingerprint: inout UInt64,
                                                    _ value: Date?) {
        guard let value else {
            mixBiologicalAgeFingerprint(&fingerprint, Int64.min)
            return
        }
        mixBiologicalAgeFingerprint(&fingerprint, secondsSinceReference(value))
    }

    private nonisolated static func mixOptionalInt(_ fingerprint: inout UInt64,
                                                   _ value: Int?) {
        guard let value else {
            mixBiologicalAgeFingerprint(&fingerprint, Int64.min)
            return
        }
        mixBiologicalAgeFingerprint(&fingerprint, Int64(value))
    }

    private nonisolated static func mixOptionalDouble(_ fingerprint: inout UInt64,
                                                      _ value: Double?,
                                                      scale: Double) {
        guard let value else {
            mixBiologicalAgeFingerprint(&fingerprint, Int64.min)
            return
        }
        mixBiologicalAgeFingerprint(&fingerprint, Int64((value * scale).rounded()))
    }

    private nonisolated static func mixStableString(_ fingerprint: inout UInt64,
                                                    _ value: String) {
        for byte in value.utf8 {
            mixBiologicalAgeFingerprint(&fingerprint, Int64(byte))
        }
        mixBiologicalAgeFingerprint(&fingerprint, -17)
    }

    private nonisolated static func secondsSinceReference(_ date: Date) -> Int64 {
        Int64(date.timeIntervalSince1970.rounded())
    }

    private nonisolated static func mixBiologicalAgeFingerprint(_ fingerprint: inout UInt64,
                                                                _ value: Int64) {
        fingerprint ^= UInt64(bitPattern: value)
        fingerprint &*= biologicalAgeFingerprintPrime
    }

    nonisolated static func biologicalAgeCacheWeekStart(for date: Date,
                                                        calendar: Calendar = .current) -> Date {
        calendar.dateInterval(of: .weekOfYear, for: date)?.start
            ?? calendar.startOfDay(for: date)
    }

    nonisolated static func isBiologicalAgeWeeklySummaryFresh(_ record: BiologicalAgeWeeklySummaryRecord,
                                                             signature: BiologicalAgeCacheSignature,
                                                             now: Date = Date(),
                                                             calendar: Calendar = .current) -> Bool {
        record.schema == biologicalAgeCacheSchema
            && record.signature == signature
            && record.weekStart == biologicalAgeCacheWeekStart(for: now, calendar: calendar)
    }

    nonisolated static func isBiologicalAgeWeeklyCadenceFresh(_ record: BiologicalAgeWeeklySummaryRecord,
                                                             cadenceKey: BiologicalAgeWeeklyCadenceKey) -> Bool {
        record.schema == biologicalAgeCacheSchema
            && record.weekStart == cadenceKey.weekStart
            && record.cadenceKey == cadenceKey
    }

    /// A same-week result suppresses ordinary source/signature churn only when it
    /// was computed for the cadence currently being requested. Legacy records
    /// without a cadence key remain weekly to avoid an uncontrolled migration-time
    /// recompute; a known profile/cadence mismatch is an explicit invalidation.
    nonisolated static func shouldDeferBiologicalAgeRefreshUntilNextWeek(
        recordWeekStart: Date,
        recordCadenceKey: BiologicalAgeWeeklyCadenceKey?,
        requestedCadenceKey: BiologicalAgeWeeklyCadenceKey
    ) -> Bool {
        guard recordWeekStart == requestedCadenceKey.weekStart else { return false }
        guard let recordCadenceKey else { return true }
        return recordCadenceKey == requestedCadenceKey
    }

    nonisolated static func isBiologicalAgeCacheCadenceFresh(_ record: BiologicalAgeCacheRecord,
                                                            profile: AthleteProfile,
                                                            sessionsLoaded: Bool = false,
                                                            now: Date = Date(),
                                                            calendar: Calendar = .current) -> Bool {
        let computedWeek = biologicalAgeCacheWeekStart(for: record.computedAt, calendar: calendar)
        let currentWeek = biologicalAgeCacheWeekStart(for: now, calendar: calendar)
        let cadenceKey = biologicalAgeWeeklyCadenceKey(profile: profile,
                                                       sessionsLoaded: sessionsLoaded,
                                                       now: now,
                                                       calendar: calendar)
        return record.schema == biologicalAgeCacheSchema
            && computedWeek == currentWeek
            && record.cadenceKey == cadenceKey
            && biologicalAgeCacheMatchesProfile(record, profile: profile)
    }

    private nonisolated static func biologicalAgeCacheMatchesProfile(_ record: BiologicalAgeCacheRecord,
                                                                     profile: AthleteProfile) -> Bool {
        record.schema == biologicalAgeCacheSchema
            && record.signature.profileAge == profile.age
            && record.signature.biologicalSex == profile.biologicalSex
            && record.signature.maxHR == profile.maxHR
            && record.signature.maxHRSource == profile.maxHRSource
    }

    nonisolated static func isBiologicalAgeCacheFresh(_ record: BiologicalAgeCacheRecord,
                                                      signature: BiologicalAgeCacheSignature,
                                                      now: Date = Date()) -> Bool {
        let age = now.timeIntervalSince(record.computedAt)
        return record.schema == biologicalAgeCacheSchema
            && record.summary.isReady
            && record.signature == signature
            && age >= 0
            && age < biologicalAgeCacheTTL
    }

    private func persistBiologicalAgeCache(_ record: BiologicalAgeCacheRecord) {
        let targetURL = biologicalAgeCacheURL
        persistenceQueue.async {
            Self.persistBiologicalAgeCacheSnapshot(record, to: targetURL)
        }
    }

    nonisolated static func readBiologicalAgeCache(from url: URL) -> BiologicalAgeCacheRecord? {
        guard let data = try? Data(contentsOf: url),
              let decoded = try? JSONDecoder().decode(BiologicalAgeCacheRecord.self, from: data) else {
            return nil
        }
        return decoded
    }

    nonisolated static func persistBiologicalAgeCacheSnapshot(_ record: BiologicalAgeCacheRecord, to url: URL) {
        do {
            let encoder = JSONEncoder()
            encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
            let data = try encoder.encode(record)
            try data.write(to: url, options: .atomic)
        } catch {
            AtriaDebugLog("ATRIADBG biological_age_cache status=error error=%@", String(describing: error))
        }
    }

    private nonisolated static func computeBiologicalAgeSummary(_ input: BiologicalAgeComputationInput) -> BiologicalAgeSummary {
        let chronologicalAge = input.profile.age
        // 2026-08-21 user directive: show an early fitness-age estimate from the
        // best available inputs rather than gating it behind five simultaneously
        // trusted 14-day baselines (which were essentially never all satisfied).
        // Only the VO2 max estimate is a hard requirement now — and it is itself
        // best-effort since 2026-08-21. Resting HR, HRV, sleep consistency and
        // Zone-2+ are passed through as best-available values below; the pure
        // model omits any that are missing and marks the result as early.
        var blockers: [String] = []
        if input.vo2MaxEstimate.value == nil { blockers.append("vo2max_learning") }
        guard blockers.isEmpty, let vo2Max = input.vo2MaxEstimate.value else {
            return BiologicalAgeSummary.building(chronologicalAge: chronologicalAge, blockers: blockers)
        }

        let calendar = Calendar.current
        let recentMetrics = Array(input.dailyMetricHistory
            .sorted { $0.day > $1.day }
            .prefix(28))
        let metricDays = Set(input.dailyMetricHistory.map { calendar.startOfDay(for: $0.day) })
        let sessionDays = Set(input.canonicalSessions.map { calendar.startOfDay(for: $0.start) })
        let historyDays = metricDays.union(sessionDays).count
        let restingHR = averageIntSnapshot(recentMetrics.compactMap(\.restingHR)) ?? input.baseline.restingInt
        let hrv = averageIntSnapshot(recentMetrics.compactMap(\.hrv)) ?? input.baseline.hrvInt
        let sleepConsistency = recentMetrics.compactMap(\.sleepConsistencyPercent).first
            ?? input.sleepHistorySnapshot.sleepConsistencyPercent
        let weeklyZone2PlusMinutes = confirmedWorkoutZone2PlusMinutes(
            workouts: input.confirmedWorkouts,
            now: input.now
        )

        return AtriaFitnessAge.summary(inputs: AtriaFitnessAge.Inputs(chronologicalAge: chronologicalAge,
                                                                      biologicalSex: input.profile.biologicalSex,
                                                                      vo2Max: vo2Max,
                                                                      restingHeartRate: restingHR,
                                                                      hrvRMSSD: hrv,
                                                                      weeklyZone2PlusMinutes: weeklyZone2PlusMinutes,
                                                                      sleepConsistencyPercent: sleepConsistency,
                                                                      historyDays: historyDays))
    }

    /// Fitness age must not turn ordinary elevated strap sessions, driving,
    /// stress, or an unconfirmed detector candidate into aerobic training.
    /// Only a user-confirmed workout with a persisted zone breakdown can earn
    /// Zone 2+ credit. Missing/invalid zone evidence fails closed to learning.
    nonisolated static func confirmedWorkoutZone2PlusMinutes(
        workouts: [UserConfirmedWorkout],
        now: Date
    ) -> Double? {
        let cutoff = now.addingTimeInterval(-7 * 24 * 60 * 60)
        let eligible = workouts.filter {
            $0.end > $0.start
                && $0.start >= cutoff
                && $0.end <= now
        }
        var sawZoneEvidence = false
        var seconds: TimeInterval = 0
        let allZoneKeys = ["rest", "warmup", "fatBurn", "aerobic", "anaerobic", "max"]
        let zoneTwoPlusKeys = Set(["fatBurn", "aerobic", "anaerobic", "max"])
        for workout in eligible {
            guard let zones = workout.zoneSeconds, !zones.isEmpty else { continue }
            for key in allZoneKeys {
                guard let value = zones[key], value.isFinite, value >= 0 else { continue }
                sawZoneEvidence = true
                if zoneTwoPlusKeys.contains(key) {
                    seconds += value
                }
            }
        }
        return sawZoneEvidence ? seconds / 60 : nil
    }

    func trendSummaryFast(rest: Int,
                          maxHR: Int,
                          days: Int = 90,
                                              limitSessions: Int = 120,
                                              now: Date = Date()) -> TrendSummary {
        let recent = recentCanonicalSessions(windowDays: days,
                                             limitSessions: limitSessions,
                                             now: now)
        return Self.dailyMetricTrendSummary(metrics: dailyMetricHistory,
                                            rollups: historySnapshot.rollups,
                                            days: days,
                                            now: now,
                                            diagnosticSessionCount: recent.count)
    }

    func logTrendSummariesFromLaunchIfRequested(arguments: [String] = ProcessInfo.processInfo.arguments) {
        guard arguments.contains("--atria-log-trends")
                || arguments.contains("--atria-log-trend-summaries") else { return }
        let sourceSessions = sessions
        let confirmedWorkouts = cachedConfirmedWorkouts
        let confirmedSleeps = cachedConfirmedSleeps
        let baselineSnapshot = baseline
        let rest = baseline.restingInt ?? 60
        let maxHR = profile.maxHR
        let snapshots = Self.makeHistorySnapshots(sessions: sourceSessions,
                                                  confirmedWorkouts: confirmedWorkouts,
                                                  confirmedSleeps: confirmedSleeps,
                                                  baseline: baselineSnapshot,
                                                  rest: rest,
                                                  maxHR: maxHR)
        Self.logTrendSummaries(summaries: snapshots.history.trends,
                               sessionsCount: sourceSessions.count,
                               rest: rest,
                               maxHR: maxHR)
    }

    private nonisolated static func logTrendSummaries(summaries: [TrendSummary],
                                                      sessionsCount: Int,
                                                      rest: Int,
                                                      maxHR: Int) {
        AtriaDebugLog("ATRIADBG trend_summary sessions=%d rest_hr=%d max_hr=%d windows=%d",
              sessionsCount, rest, maxHR, summaries.count)
        for summary in summaries {
            let anomalyFlags = trendAnomalyFlagsSnapshot(summary.anomalies)
            let detail = summary.detail.replacingOccurrences(of: " ", with: "_")
            AtriaDebugLog("ATRIADBG trend_window days=%d sessions=%d coverage_days=%d required_coverage_days=%d required_coverage_percent=70 coverage_percent=%d confidence=%@ recovery=%@ hrv=%@ hrv_state=%@ rhr=%@ strain=%@ respiratory_rate=%@ anomalies=%d anomaly_flags=%@ anomaly_source=%@ anomaly_days=%d detail=%@ blockers=%@",
                  summary.days,
                  summary.sessions,
                  summary.coverageDays,
                  summary.requiredCoverageDays,
                  summary.coveragePercent,
                  summary.confidence,
                  formatIntSnapshot(summary.avgRecovery),
                  formatIntSnapshot(summary.avgHRV),
                  summary.hrvState,
                  formatIntSnapshot(summary.avgRHR),
                  formatDoubleSnapshot(summary.avgStrain),
                  formatDoubleSnapshot(summary.avgRespiratoryRate),
                  summary.anomalies.count,
                  anomalyFlags,
                  summary.anomalySource,
                  summary.anomalySampleDays,
                  detail,
                  summary.blockers)
        }
    }

    func logDailyRollupsFromLaunchIfRequested(arguments: [String] = ProcessInfo.processInfo.arguments) {
        let deepDiagnosticsRequested = arguments.contains("--atria-log-daily-rollups-deep")
        guard arguments.contains("--atria-log-daily-rollups") || deepDiagnosticsRequested else { return }
        let sourceSessions = sessions
        let confirmedWorkouts = cachedConfirmedWorkouts
        let confirmedSleeps = cachedConfirmedSleeps
        let baselineSnapshot = baseline
        let rest = baseline.restingInt ?? 60
        let maxHR = profile.maxHR
        DispatchQueue.global(qos: .utility).async {
            let snapshots = Self.makeHistorySnapshots(sessions: sourceSessions,
                                                      confirmedWorkouts: confirmedWorkouts,
                                                      confirmedSleeps: confirmedSleeps,
                                                      baseline: baselineSnapshot,
                                                      rest: rest,
                                                      maxHR: maxHR)
            Self.logDailyRollups(rollups: snapshots.history.rollups,
                                 sessionsCount: sourceSessions.count,
                                 rest: rest,
                                 maxHR: maxHR)
            guard deepDiagnosticsRequested else { return }
            let formatter = DateFormatter()
            formatter.calendar = Calendar.current
            formatter.dateFormat = "yyyy-MM-dd"
            Self.logDeepDailyRollupDiagnostics(formatter: formatter,
                                               rest: rest,
                                               maxHR: maxHR,
                                               sourceSessions: sourceSessions)
        }
    }

    private nonisolated static func logDailyRollups(rollups: [DailyRollup],
                                                    sessionsCount: Int,
                                                    rest: Int,
                                                    maxHR: Int) {
        let sleepReadyDays = rollups.filter { $0.sleepReady > 0 }.count
        let sleepCandidateDays = rollups.filter { $0.sleepCandidates > 0 }.count
        let workoutDays = rollups.filter { $0.workouts > 0 }.count
        let confirmedWorkoutDays = rollups.filter { $0.confirmedWorkouts > 0 }.count
        let confirmedWorkoutCount = rollups.reduce(0) { $0 + $1.confirmedWorkouts }
        let restCandidateDays = rollups.filter { $0.restCandidates > 0 }.count
        let restCandidateCount = rollups.reduce(0) { $0 + $1.restCandidates }
        AtriaDebugLog("ATRIADBG daily_rollup_summary sessions=%d days=%d sleep_ready_days=%d sleep_candidate_days=%d rest_candidate_days=%d rest_candidates=%d workout_days=%d confirmed_workout_days=%d confirmed_workouts=%d rest_hr=%d max_hr=%d",
              sessionsCount, rollups.count, sleepReadyDays, sleepCandidateDays, restCandidateDays, restCandidateCount, workoutDays, confirmedWorkoutDays, confirmedWorkoutCount, rest, maxHR)
        let formatter = DateFormatter()
        formatter.calendar = Calendar.current
        formatter.dateFormat = "yyyy-MM-dd"
        for rollup in rollups.prefix(14) {
            AtriaDebugLog("ATRIADBG daily_rollup day=%@ sessions=%d activity_candidates=%d workouts=%d confirmed_workouts=%d rest_candidates=%d sleep_ready=%d sleep_candidates=%d duration_s=%.0f strain=%.2f hrv=%@ rhr=%@ respiratory_rate=%@ workout_gate_strict=1 sleep_gate_strict=1 rest_diagnostic_only=1",
                  formatter.string(from: rollup.day),
                  rollup.sessions,
                  rollup.activityCandidates,
                  rollup.workouts,
                  rollup.confirmedWorkouts,
                  rollup.restCandidates,
                  rollup.sleepReady,
                  rollup.sleepCandidates,
                  rollup.duration,
                  rollup.strain,
                  formatIntSnapshot(rollup.avgHRV),
                  formatIntSnapshot(rollup.restingHR),
                  formatDoubleSnapshot(rollup.avgRespiratoryRate))
        }
    }

    private nonisolated static func logDeepDailyRollupDiagnostics(formatter: DateFormatter,
                                                                 rest: Int,
                                                                 maxHR: Int,
                                                                 sourceSessions: [SavedSession]) {
        let aggregateWorkouts = aggregateWorkoutCandidates(in: sourceSessions,
                                                           rest: rest,
                                                           maxHR: maxHR,
                                                           calendar: Calendar.current)
        let readyAggregateWorkouts = aggregateWorkouts.filter { $0.readiness.ready }.count
        let bestAggregateWorkout = aggregateWorkouts.first
        AtriaDebugLog("ATRIADBG aggregate_workout_summary candidates=%d ready=%d best_source=%@ best_status=%@ best_reason=%@ best_blocker=%@ best_strength_candidate=%d best_strength_candidate_reason=%@ strength_diagnostic_only=1 best_next_action=%@ best_stream_coverage_percent=%d best_chunks=%d best_duration_s=%.0f best_observed_duration_s=%.0f best_dropped_gap_s=%.0f best_max_gap_s=%.1f best_p90_hr=%d best_p95_hr=%d best_p99_hr=%d best_threshold_gap_bpm=%d best_samples_above_threshold=%d best_samples_above_borderline=%d best_elevated_s=%.0f best_required_elevated_s=%.0f best_longest_bout_s=%.0f best_required_bout_s=%.0f best_borderline_threshold_hr=%d best_borderline_elevated_s=%.0f best_borderline_longest_bout_s=%.0f borderline_diagnostic_only=1 best_hr_raw_2a37=%d best_hr_accepted=%d best_hr_zero=%d best_hr_artifact_held=%d best_hr_artifact_dropped=%d best_hr_raw_gaps=%d best_hr_accepted_gaps=%d best_hr_max_raw_gap_s=%.1f best_hr_max_accepted_gap_s=%.1f cluster_gap_limit_s=1800 window_min_s=600 window_max_s=5400 sample_gap_limit_s=5 source=saved_session_chunks",
              aggregateWorkouts.count,
              readyAggregateWorkouts,
              bestAggregateWorkout?.source ?? "none",
              bestAggregateWorkout?.readiness.status ?? "learning",
              bestAggregateWorkout?.readiness.reason ?? "no_aggregate_candidate",
              bestAggregateWorkout?.readiness.primaryBlocker ?? "no_aggregate_candidate",
              bestAggregateWorkout?.readiness.strengthCandidate == true ? 1 : 0,
              bestAggregateWorkout?.readiness.strengthCandidateReason ?? "none",
              bestAggregateWorkout?.readiness.nextAction ?? "none",
              bestAggregateWorkout?.readiness.streamCoveragePercent ?? 0,
