    @discardableResult
    private func exportRRReferencePackage() -> (csv: URL, manifest: URL)? {
        let rrSamples = totalRRSamples(in: sessions)
        guard let best = bestSavedRRReferenceWindow() else {
            let reason = rrSamples > 0 ? "no_300s_window" : "no_saved_rr"
            AtriaDebugLog("ATRIADBG rr_reference_package status=learning reason=%@ sessions=%d rr_samples=%d external_reference_required=1 reference_validated=0",
                  reason,
                  sessions.count,
                  rrSamples)
            return nil
        }

        guard best.ready else {
            AtriaDebugLog("ATRIADBG rr_reference_package status=learning reason=%@ session_label=%@ raw=%d kept=%d conf=%d window_s=300 max_rr_gap_s=%.1f external_reference_required=1 reference_validated=0",
                  best.reason,
                  best.session.label,
                  best.snapshot.raw,
                  best.snapshot.kept,
                  best.snapshot.confidencePercent,
                  best.strictGap)
            return nil
        }

        let relativeDir = "Documents/atria-rr-reference-packages"
        let exportDir = url.deletingLastPathComponent().appendingPathComponent("atria-rr-reference-packages")
        let timestamp = SessionStore.backupTimestamp()
        let safeLabel = safeFileStem(best.session.label)
        let base = "atria-rr-reference-\(timestamp)-\(safeLabel)"
        let csvURL = exportDir.appendingPathComponent("\(base).csv")
        let manifestURL = exportDir.appendingPathComponent("\(base)-manifest.json")
        let iso = ISO8601DateFormatter()

        do {
            try FileManager.default.createDirectory(at: exportDir, withIntermediateDirectories: true)
            let csv = rrReferenceCSV(for: best, isoFormatter: iso)
            try csv.write(to: csvURL, atomically: true, encoding: .utf8)

            let validationContract: [String: Any] = [
                "externalReferencePath": "Documents/atria-reference/rr-reference.csv",
                "externalReferenceRequired": true,
                "mustBeIndependent": true,
                "selfComparisonRejected": true,
                "acceptedRRColumns": ["rr_ms", "rr", "ibi_ms", "ibi", "interval_ms", "interval", "nn_ms", "nn", "value"],
                "acceptedTimeColumns": ["elapsed_ms", "time_ms", "timestamp_ms", "t_ms", "seconds", "time_s", "timestamp", "t"],
                "timeColumnUnits": "columns containing ms are milliseconds; seconds/time_s/timestamp/t are seconds",
                "missingTimeColumnPolicy": "cumulative_rr_ms",
                "windowAlignment": "reference file must cover the same uninterrupted 300-second physiological window as windowStart/windowEnd",
                "windowSeconds": 300,
                "minCorrectedBeats": 240,
                "minConfidencePercent": 75,
                "maxRRGapSeconds": HRVSnapshot.maxReadyRRGapSeconds,
                "rrMinMs": 300,
                "rrMaxMs": 2000,
                "maxDeltaRRPercent": 20,
                "rmssdToleranceMs": 5.0,
                "validationCommand": "./reference_validate.sh <label> --rr <independent-rr.csv> --require-rr-pass"
            ]

            let manifest: [String: Any] = [
                "schema": 2,
                "createdAt": iso.string(from: Date()),
                "source": "saved_rr_points",
                "csv": "\(relativeDir)/\(csvURL.lastPathComponent)",
                "sessionLabel": best.session.label,
                "sessionStart": iso.string(from: best.session.start),
                "sessionEnd": iso.string(from: best.session.end),
                "windowStart": iso.string(from: best.windowStart),
                "windowEnd": iso.string(from: best.windowEnd),
                "windowSeconds": 300,
                "raw": best.snapshot.raw,
                "kept": best.snapshot.kept,
                "confidencePercent": best.snapshot.confidencePercent,
                "maxRRGapSeconds": best.strictGap,
                "rejectedOutOfRange": best.snapshot.rejectedOutOfRange,
                "rejectedDeltaOver20Percent": best.snapshot.rejectedDeltaOver20Percent,
                "interpolated": best.snapshot.interpolated,
                "rmssdMs": best.snapshot.rmssd,
                "sdnnMs": best.snapshot.sdnn,
                "pnn50Percent": best.snapshot.pnn50,
                "lnRmssd": best.snapshot.lnRMSSD,
                "respiratoryRateBPM": best.snapshot.respiratoryRate ?? NSNull(),
                "externalReferenceRequired": true,
                "referenceValidated": false,
                "readyForExternalReference": true,
                "gateBPassed": false,
                "validation": validationContract
            ]
            let data = try JSONSerialization.data(withJSONObject: manifest, options: [.prettyPrinted, .sortedKeys])
            try data.write(to: manifestURL, options: .atomic)

            AtriaDebugLog("ATRIADBG rr_reference_package status=ok csv=%@ manifest=%@ session_label=%@ raw=%d kept=%d conf=%d window_s=300 max_rr_gap_s=%.1f rmssd=%.1f sdnn=%.1f pnn50=%.1f lnrmssd=%.2f external_reference_required=1 reference_validated=0 reference_path=Documents/atria-reference/rr-reference.csv tolerance_ms=5 self_compare_rejected=1 schema=2",
                  "\(relativeDir)/\(csvURL.lastPathComponent)",
                  "\(relativeDir)/\(manifestURL.lastPathComponent)",
                  best.session.label,
                  best.snapshot.raw,
                  best.snapshot.kept,
                  best.snapshot.confidencePercent,
                  best.strictGap,
                  best.snapshot.rmssd,
                  best.snapshot.sdnn,
                  best.snapshot.pnn50,
                  best.snapshot.lnRMSSD)
            return (csvURL, manifestURL)
        } catch {
            AtriaDebugLog("ATRIADBG rr_reference_package status=error reason=write_failed error=%@", String(describing: error))
            return nil
        }
    }

    @discardableResult
    private func validateRRReferenceFromDocuments() -> Bool {
        guard let best = bestSavedRRReferenceWindow(), best.ready else {
            let reason = totalRRSamples(in: sessions) > 0 ? "no_ready_strap_rr_window" : "no_saved_rr"
            AtriaDebugLog("ATRIADBG rr_reference_validation status=learning reason=%@ gate_b_pass=0 external_reference=0 reference_validated=0",
                  reason)
            return false
        }

        let reference = resolveReferenceCSV(kind: "rr", preferredFileName: "rr-reference.csv")
        guard let referenceURL = reference.url else {
            AtriaDebugLog("ATRIADBG rr_reference_validation status=missing reason=%@ path=Documents/atria-reference/rr-reference.csv candidate_count=%d candidates=%@ strap_ready=1 strap_raw=%d strap_kept=%d strap_conf=%d strap_rmssd=%.1f gate_b_pass=0 external_reference=0 reference_validated=0 action=place_exactly_one_independent_rr_csv_in_Documents/atria-reference_or_push_rr-reference.csv",
                  reference.reason,
                  reference.candidateCount,
                  reference.candidates.isEmpty ? "none" : reference.candidates.joined(separator: "|"),
                  best.snapshot.raw,
                  best.snapshot.kept,
                  best.snapshot.confidencePercent,
                  best.snapshot.rmssd)
            return false
        }
        if reference.autoSelected {
            AtriaDebugLog("ATRIADBG rr_reference_validation_reference status=auto_selected preferred=rr-reference.csv selected=%@ candidate_count=%d external_reference_required=1",
                  referenceURL.lastPathComponent,
                  reference.candidateCount)
        }

        do {
            let referenceText = try String(contentsOf: referenceURL, encoding: .utf8)
            let selfCSV = rrReferenceCSV(for: best, isoFormatter: ISO8601DateFormatter())
            if normalizeReferenceCSV(referenceText) == normalizeReferenceCSV(selfCSV) {
                AtriaDebugLog("ATRIADBG rr_reference_validation status=fail reason=same_content_not_external_reference source=Documents/atria-reference/%@ gate_b_pass=0 external_reference=0 reference_validated=0 action=provide_independent_rr_ibi_recording",
                      referenceURL.lastPathComponent)
                return false
            }
            let reference = try parseExternalRRReferenceCSV(at: referenceURL)
            let referenceScore = scoreExternalRR(reference, windowSeconds: 300)
            let delta = referenceScore.rmssd.map { abs(best.snapshot.rmssd - $0) }
            let metricPassed = best.ready
                && referenceScore.ready
                && delta.map { $0 <= 5.0 } == true
            AtriaDebugLog("ATRIADBG rr_reference_validation status=%@ reason=%@ strap_ready=%d strap_raw=%d strap_kept=%d strap_conf=%d strap_gap_s=%.1f strap_rmssd=%.1f reference_ready=%d reference_raw=%d reference_kept=%d reference_conf=%d reference_gap_s=%.1f reference_rmssd=%.1f rmssd_delta_ms=%.1f tolerance_ms=5 gate_b_pass=%d external_reference=1 reference_validated=%d source=Documents/atria-reference/%@",
                  metricPassed ? "pass" : "fail",
                  metricPassed ? "ready" : rrReferenceFailureReason(strap: best, reference: referenceScore, delta: delta),
                  best.ready ? 1 : 0,
                  best.snapshot.raw,
                  best.snapshot.kept,
                  best.snapshot.confidencePercent,
                  best.strictGap,
                  best.snapshot.rmssd,
                  referenceScore.ready ? 1 : 0,
                  referenceScore.raw,
                  referenceScore.kept,
                  referenceScore.confidencePercent,
                  referenceScore.maxGap,
                  referenceScore.rmssd ?? 0,
                  delta ?? -1,
                  metricPassed ? 1 : 0,
                  metricPassed ? 1 : 0,
                  referenceURL.lastPathComponent)
            if metricPassed {
                persistRRReferenceValidation(for: best.session,
                                             rmssd: best.snapshot.rmssd,
                                             sdnn: best.snapshot.sdnn,
                                             delta: delta ?? 0)
            }
            return metricPassed
        } catch {
            AtriaDebugLog("ATRIADBG rr_reference_validation status=error reason=parse_failed error=%@ gate_b_pass=0 external_reference=1 reference_validated=0",
                  String(describing: error))
            return false
        }
    }

    @discardableResult
    private func validateHRReferenceFromDocuments() -> Bool {
        let hrSamples = sessions.reduce(0) { $0 + $1.points.count }
        guard let best = bestSavedHRReferenceSession() else {
            let reason = hrSamples > 0 ? "no_60s_saved_hr_window" : "no_saved_hr"
            recordHRReferenceAttempt(status: "learning",
                                     reason: reason,
                                     source: "missing",
                                     referenceSamples: 0,
                                     comparison: nil,
                                     session: nil,
                                     invalidateExistingValidation: false)
            AtriaDebugLog("ATRIADBG hr_reference_validation status=learning reason=%@ gate_d_pass=0 external_reference=0 reference_validated=0",
                  reason)
            return false
        }

        let bpms = best.samples.map(\.bpm)
        let avg = bpms.isEmpty ? 0 : Double(bpms.reduce(0, +)) / Double(bpms.count)
        let peak = bpms.max() ?? 0
        let resting = bpms.min() ?? 0
        let reference = resolveReferenceCSV(kind: "hr", preferredFileName: "hr-reference.csv")
        guard let referenceURL = reference.url else {
            recordHRReferenceAttempt(status: "missing",
                                     reason: reference.reason,
                                     source: "missing",
                                     referenceSamples: 0,
                                     comparison: nil,
                                     session: best.session,
                                     invalidateExistingValidation: false)
            AtriaDebugLog("ATRIADBG hr_reference_validation status=missing reason=%@ path=Documents/atria-reference/hr-reference.csv candidate_count=%d candidates=%@ strap_ready=1 strap_samples=%d strap_duration_s=%.0f strap_avg_hr=%.1f strap_peak_hr=%d strap_resting_hr=%d tolerance_bpm=2 gate_d_pass=0 external_reference=0 reference_validated=0 action=place_exactly_one_independent_hr_csv_in_Documents/atria-reference_or_push_hr-reference.csv",
                  reference.reason,
                  reference.candidateCount,
                  reference.candidates.isEmpty ? "none" : reference.candidates.joined(separator: "|"),
                  best.samples.count,
                  best.session.duration,
                  avg,
                  peak,
                  resting)
            return false
        }
        if reference.autoSelected {
            AtriaDebugLog("ATRIADBG hr_reference_validation_reference status=auto_selected preferred=hr-reference.csv selected=%@ candidate_count=%d external_reference_required=1",
                  referenceURL.lastPathComponent,
                  reference.candidateCount)
        }

        do {
            let referenceText = try String(contentsOf: referenceURL, encoding: .utf8)
            let selfCSV = hrReferenceCSV(for: best, isoFormatter: ISO8601DateFormatter())
            if normalizeReferenceCSV(referenceText) == normalizeReferenceCSV(selfCSV) {
                recordHRReferenceAttempt(status: "fail",
                                         reason: "same_content_not_external_reference",
                                         source: "self_compare_rejected",
                                         referenceSamples: 0,
                                         comparison: nil,
                                         session: best.session,
                                         invalidateExistingValidation: true)
                AtriaDebugLog("ATRIADBG hr_reference_validation status=fail reason=same_content_not_external_reference source=Documents/atria-reference/%@ gate_d_pass=0 external_reference=0 reference_validated=0 action=provide_independent_chest_strap_hr_recording",
                      referenceURL.lastPathComponent)
                return false
            }
            let reference = try parseExternalHRReferenceCSV(at: referenceURL)
            let strap = best.samples.sorted { $0.t < $1.t }.map { ExternalHRSample(t: $0.t, bpm: Double($0.bpm)) }
            let comparison = compareHRReference(strap: strap,
                                                reference: reference,
                                                toleranceBPM: 2,
                                                maxPairAge: 5)
            recordHRReferenceAttempt(status: comparison.ready ? "pass" : "fail",
                                     reason: comparison.reason,
                                     source: "csv",
                                     referenceSamples: reference.count,
                                     comparison: comparison,
                                     session: best.session,
                                     invalidateExistingValidation: !comparison.ready)
            AtriaDebugLog("ATRIADBG hr_reference_validation status=%@ reason=%@ strap_samples=%d reference_samples=%d pairs=%d duration_s=%.0f mean_delta_bpm=%.2f median_delta_bpm=%.2f max_delta_bpm=%.2f within_tolerance_percent=%d tolerance_bpm=2 max_pair_age_s=5 gate_d_pass=%d external_reference=1 reference_validated=%d source=Documents/atria-reference/%@",
                  comparison.ready ? "pass" : "fail",
                  comparison.reason,
                  strap.count,
                  reference.count,
                  comparison.pairs,
                  comparison.duration,
                  comparison.meanDelta ?? -1,
                  comparison.medianDelta ?? -1,
                  comparison.maxDelta ?? -1,
                  comparison.withinTolerancePercent,
                  comparison.ready ? 1 : 0,
                  comparison.ready ? 1 : 0,
                  referenceURL.lastPathComponent)
            if comparison.ready {
                persistHRReferenceValidation(session: best.session,
                                             pairs: comparison.pairs,
                                             meanDelta: comparison.meanDelta,
                                             maxDelta: comparison.maxDelta)
            }
            return comparison.ready
        } catch {
            recordHRReferenceAttempt(status: "error",
                                     reason: "parse_failed",
                                     source: "csv",
                                     referenceSamples: 0,
                                     comparison: nil,
                                     session: best.session,
                                     invalidateExistingValidation: true)
            AtriaDebugLog("ATRIADBG hr_reference_validation status=error reason=parse_failed error=%@ gate_d_pass=0 external_reference=1 reference_validated=0",
                  String(describing: error))
            return false
        }
    }

    private struct ReferenceCSVResolution {
        let url: URL?
        let reason: String
        let candidateCount: Int
        let candidates: [String]
        let autoSelected: Bool
    }

    private func resolveReferenceCSV(kind: String, preferredFileName: String) -> ReferenceCSVResolution {
        let referenceDir = url.deletingLastPathComponent().appendingPathComponent("atria-reference")
        let preferred = referenceDir.appendingPathComponent(preferredFileName)
        if FileManager.default.fileExists(atPath: preferred.path) {
            return ReferenceCSVResolution(url: preferred,
                                          reason: "preferred_file",
                                          candidateCount: 1,
                                          candidates: [preferred.lastPathComponent],
                                          autoSelected: false)
        }

        let contents = (try? FileManager.default.contentsOfDirectory(at: referenceDir,
                                                                     includingPropertiesForKeys: [.isRegularFileKey],
                                                                     options: [.skipsHiddenFiles])) ?? []
        let candidates = contents
            .filter { $0.pathExtension.lowercased() == "csv" }
            .filter { isPlausibleReferenceCSVFileName($0.lastPathComponent, kind: kind) }
            .sorted { $0.lastPathComponent.localizedStandardCompare($1.lastPathComponent) == .orderedAscending }
        if candidates.count == 1, let candidate = candidates.first {
            return ReferenceCSVResolution(url: candidate,
                                          reason: "auto_selected_single_candidate",
                                          candidateCount: 1,
                                          candidates: [candidate.lastPathComponent],
                                          autoSelected: true)
        }
        return ReferenceCSVResolution(url: nil,
                                      reason: candidates.isEmpty ? "missing_external_reference_file" : "ambiguous_external_reference_files",
                                      candidateCount: candidates.count,
                                      candidates: candidates.map(\.lastPathComponent),
                                      autoSelected: false)
    }

    private func isPlausibleReferenceCSVFileName(_ name: String, kind: String) -> Bool {
        let lower = name.lowercased()
        guard lower.hasSuffix(".csv") else { return false }
        if kind == "rr" {
            return lower.contains("rr")
                || lower.contains("ibi")
                || lower.contains("interval")
                || lower.contains("nn")
        }
        return lower.contains("hr")
            || lower.contains("heart")
            || lower.contains("bpm")
    }

    private func persistRRReferenceValidation(for session: SavedSession,
                                              rmssd: Double,
                                              sdnn: Double,
                                              delta: Double) {
        guard let index = sessions.firstIndex(where: { $0.id == session.id }) else {
            AtriaDebugLog("ATRIADBG rr_reference_validation_persist status=failed reason=session_not_found session_id=%@ reference_validated=0",
                  session.id.uuidString)
            return
        }
        sessions[index].hrv = Int(rmssd.rounded())
        sessions[index].hrvSDNN = sdnn
        sessions[index].hrvReferenceValidated = true
        markSessionPersistenceDirty(affectedSessions: [sessions[index]])
        guard flushScheduledPersistence(reason: "rr-reference-validation") else {
            AtriaDebugLog("ATRIADBG rr_reference_validation_persist status=failed reason=session_store_save session_id=%@ reference_validated=0",
                  session.id.uuidString)
            return
        }
        rebuildBaselineFromEligibleSessions(reason: "rr-reference-validation")
        refreshSessionDerivedCaches()
        refreshHomeDashboardDiagnosticsCache()
        publishDashboardRevision()
        AtriaDebugLog("ATRIADBG rr_reference_validation_persist status=ok session_id=%@ label=%@ rmssd=%d sdnn=%.1f rmssd_delta_ms=%.1f reference_validated=1",
              session.id.uuidString,
              session.label,
              sessions[index].referenceValidatedHRV ?? 0,
              sessions[index].referenceValidatedSDNN ?? 0,
              delta)
    }

    private func persistHRReferenceValidation(session: SavedSession,
                                              pairs: Int,
                                              meanDelta: Double?,
                                              maxDelta: Double?) {
        let defaults = UserDefaults.standard
        defaults.set(true, forKey: ExternalReferenceDefaults.hrValidated)
        defaults.set(Date(), forKey: ExternalReferenceDefaults.hrValidatedAt)
        defaults.set("csv", forKey: ExternalReferenceDefaults.hrSource)
        defaults.set(pairs, forKey: ExternalReferenceDefaults.hrPairs)
        defaults.set(meanDelta ?? -1, forKey: ExternalReferenceDefaults.hrMeanDelta)
        defaults.set(maxDelta ?? -1, forKey: ExternalReferenceDefaults.hrMaxDelta)
        defaults.set(session.id.uuidString, forKey: ExternalReferenceDefaults.hrSessionID)
        defaults.set(session.label, forKey: ExternalReferenceDefaults.hrSessionLabel)
        refreshHomeDashboardDiagnosticsCache()
        publishDashboardRevision()
        AtriaDebugLog("ATRIADBG hr_reference_validation_persist status=ok session_id=%@ label=%@ source=csv pairs=%d mean_delta_bpm=%.2f max_delta_bpm=%.2f reference_validated=1",
              session.id.uuidString,
              session.label,
              pairs,
              meanDelta ?? -1,
              maxDelta ?? -1)
    }

    private func recordHRReferenceAttempt(status: String,
                                          reason: String,
                                          source: String,
                                          referenceSamples: Int,
                                          comparison: HRReferenceComparison?,
                                          session: SavedSession?,
                                          invalidateExistingValidation: Bool) {
        let defaults = UserDefaults.standard
        defaults.set(status, forKey: ExternalReferenceDefaults.hrStatus)
        defaults.set(reason, forKey: ExternalReferenceDefaults.hrReason)
        if status == "pass" || invalidateExistingValidation {
            defaults.set(source, forKey: ExternalReferenceDefaults.hrSource)
        }
        defaults.set(referenceSamples, forKey: ExternalReferenceDefaults.hrReferenceSamples)
        defaults.set(comparison?.pairs ?? 0, forKey: ExternalReferenceDefaults.hrPairs)
        defaults.set(comparison?.duration ?? 0, forKey: ExternalReferenceDefaults.hrDuration)
        defaults.set(comparison?.meanDelta ?? -1, forKey: ExternalReferenceDefaults.hrMeanDelta)
        defaults.set(comparison?.medianDelta ?? -1, forKey: ExternalReferenceDefaults.hrMedianDelta)
        defaults.set(comparison?.maxDelta ?? -1, forKey: ExternalReferenceDefaults.hrMaxDelta)
        defaults.set(comparison?.withinTolerancePercent ?? 0, forKey: ExternalReferenceDefaults.hrWithinTolerancePercent)
        if let session {
            defaults.set(session.id.uuidString, forKey: ExternalReferenceDefaults.hrSessionID)
            defaults.set(session.label, forKey: ExternalReferenceDefaults.hrSessionLabel)
        }
        if status == "pass" {
            defaults.set(true, forKey: ExternalReferenceDefaults.hrValidated)
            defaults.set(Date(), forKey: ExternalReferenceDefaults.hrValidatedAt)
        } else if invalidateExistingValidation {
            defaults.set(false, forKey: ExternalReferenceDefaults.hrValidated)
        }
        refreshHomeDashboardDiagnosticsCache()
        publishDashboardRevision()
        AtriaDebugLog("ATRIADBG hr_reference_validation_record status=%@ reason=%@ source=%@ reference_samples=%d pairs=%d duration_s=%.0f mean_delta_bpm=%.2f median_delta_bpm=%.2f max_delta_bpm=%.2f within_tolerance_percent=%d reference_validated=%d invalidated=%d",
              status,
              reason,
              source,
              referenceSamples,
              comparison?.pairs ?? 0,
              comparison?.duration ?? 0,
              comparison?.meanDelta ?? -1,
              comparison?.medianDelta ?? -1,
              comparison?.maxDelta ?? -1,
              comparison?.withinTolerancePercent ?? 0,
              defaults.bool(forKey: ExternalReferenceDefaults.hrValidated) ? 1 : 0,
              invalidateExistingValidation ? 1 : 0)
    }

    private func clearHRReferenceValidation(reason: String) {
        let defaults = UserDefaults.standard
        defaults.set(false, forKey: ExternalReferenceDefaults.hrValidated)
        defaults.set("cleared", forKey: ExternalReferenceDefaults.hrStatus)
        defaults.set(reason, forKey: ExternalReferenceDefaults.hrReason)
        defaults.set("missing", forKey: ExternalReferenceDefaults.hrSource)
        defaults.set(0, forKey: ExternalReferenceDefaults.hrPairs)
        defaults.set(0, forKey: ExternalReferenceDefaults.hrReferenceSamples)
        defaults.set(0, forKey: ExternalReferenceDefaults.hrDuration)
        defaults.set(-1, forKey: ExternalReferenceDefaults.hrMeanDelta)
        defaults.set(-1, forKey: ExternalReferenceDefaults.hrMedianDelta)
        defaults.set(-1, forKey: ExternalReferenceDefaults.hrMaxDelta)
        defaults.set(0, forKey: ExternalReferenceDefaults.hrWithinTolerancePercent)
        refreshHomeDashboardDiagnosticsCache()
        publishDashboardRevision()
        AtriaDebugLog("ATRIADBG hr_reference_validation_clear status=ok reason=%@ reference_validated=0",
              reason)
    }

    @discardableResult
    private func exportHRReferencePackage() -> (csv: URL, manifest: URL)? {
        let hrSamples = sessions.reduce(0) { $0 + $1.points.count }
        guard let best = bestSavedHRReferenceSession() else {
            let reason = hrSamples > 0 ? "no_60s_saved_hr_window" : "no_saved_hr"
            AtriaDebugLog("ATRIADBG hr_reference_package status=learning reason=%@ sessions=%d hr_samples=%d external_reference_required=1 reference_validated=0 gate_d_pass=0",
                  reason,
                  sessions.count,
                  hrSamples)
            return nil
        }

        let relativeDir = "Documents/atria-hr-reference-packages"
        let exportDir = url.deletingLastPathComponent().appendingPathComponent("atria-hr-reference-packages")
        let timestamp = SessionStore.backupTimestamp()
        let safeLabel = safeFileStem(best.session.label)
        let base = "atria-hr-reference-\(timestamp)-\(safeLabel)"
        let csvURL = exportDir.appendingPathComponent("\(base).csv")
        let manifestURL = exportDir.appendingPathComponent("\(base)-manifest.json")
        let iso = ISO8601DateFormatter()
        let bpms = best.samples.map(\.bpm)
        let avg = bpms.isEmpty ? 0 : Double(bpms.reduce(0, +)) / Double(bpms.count)
        let peak = bpms.max() ?? 0
        let resting = bpms.min() ?? 0
        let duration = best.session.duration
        let observed = observedHRSeconds(best.samples)
        let coverage = duration > 0 ? min(1.0, observed / duration) : 0.0

        do {
            try FileManager.default.createDirectory(at: exportDir, withIntermediateDirectories: true)
            let csv = hrReferenceCSV(for: best, isoFormatter: iso)
            try csv.write(to: csvURL, atomically: true, encoding: .utf8)

            let manifest: [String: Any] = [
                "schema": 1,
                "createdAt": iso.string(from: Date()),
                "source": "saved_2a37_hr_points",
                "csv": "\(relativeDir)/\(csvURL.lastPathComponent)",
                "sessionLabel": best.session.label,
                "sessionStart": iso.string(from: best.session.start),
                "sessionEnd": iso.string(from: best.session.end),
                "durationSeconds": duration,
                "observedSeconds": observed,
                "streamCoveragePercent": Int((coverage * 100).rounded()),
                "hrSamples": best.samples.count,
                "avgHR": avg,
                "peakHR": peak,
                "restingHR": resting,
                "raw2A37Notifications": best.session.hrRaw2A37Value,
                "acceptedHRSamples": best.session.hrAcceptedValue,
                "acceptedHRGaps": best.session.hrAcceptedGapsValue,
                "maxAcceptedHRGapSeconds": best.session.hrMaxAcceptedGapValue,
                "externalReferenceRequired": true,
                "referenceValidated": false,
                "readyForExternalReference": true,
                "gateDPassed": false
            ]
            let data = try JSONSerialization.data(withJSONObject: manifest, options: [.prettyPrinted, .sortedKeys])
            try data.write(to: manifestURL, options: .atomic)

            AtriaDebugLog("ATRIADBG hr_reference_package status=ok csv=%@ manifest=%@ session_label=%@ samples=%d duration_s=%.0f observed_s=%.0f coverage_percent=%d avg_hr=%.1f peak_hr=%d resting_hr=%d source=2a37 external_reference_required=1 reference_validated=0 gate_d_pass=0",
                  "\(relativeDir)/\(csvURL.lastPathComponent)",
                  "\(relativeDir)/\(manifestURL.lastPathComponent)",
                  best.session.label,
                  best.samples.count,
                  duration,
                  observed,
                  Int((coverage * 100).rounded()),
                  avg,
                  peak,
                  resting)
            return (csvURL, manifestURL)
        } catch {
            AtriaDebugLog("ATRIADBG hr_reference_package status=error reason=write_failed error=%@", String(describing: error))
            return nil
        }
    }

    private func rrReferenceCSV(for window: RRSavedReferenceWindow, isoFormatter: ISO8601DateFormatter) -> String {
        var rows = ["elapsed_ms,kind,value,source,iso_time,session_label"]
        for sample in window.samples.sorted(by: { $0.t < $1.t }) {
            let elapsedMs = Int((sample.t.timeIntervalSince(window.windowStart) * 1000).rounded())
            let value = Int(sample.ms.rounded())
            rows.append("\(elapsedMs),rr,\(value),saved_rr_points,\(csvEscape(isoFormatter.string(from: sample.t))),\(csvEscape(window.session.label))")
        }
        return rows.joined(separator: "\n") + "\n"
    }

    private func parseExternalRRReferenceCSV(at referenceURL: URL) throws -> [ExternalRRPoint] {
        let text = try String(contentsOf: referenceURL, encoding: .utf8)
        let lines = text.split(whereSeparator: \.isNewline).map(String.init)
        guard let header = lines.first else { return [] }
        let headers = csvFields(header).map { $0.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() }
        let rrIndex = firstHeaderIndex(in: headers,
                                       names: ["rr_ms", "rr", "ibi_ms", "ibi", "interval_ms", "interval", "nn_ms", "nn", "value"])
        let timeIndex = firstHeaderIndex(in: headers,
                                         names: ["elapsed_ms", "time_ms", "timestamp_ms", "t_ms", "seconds", "time_s", "timestamp", "t"])
        var points: [ExternalRRPoint] = []
        var elapsed: TimeInterval = 0
        for line in lines.dropFirst() {
            let fields = csvFields(line)
            guard let rrIndex, rrIndex < fields.count,
                  let ms = Double(fields[rrIndex].trimmingCharacters(in: .whitespacesAndNewlines)) else { continue }
            let t: TimeInterval
            if let timeIndex, timeIndex < fields.count,
               let parsedTime = Double(fields[timeIndex].trimmingCharacters(in: .whitespacesAndNewlines)) {
                t = headers[timeIndex].contains("ms") ? parsedTime / 1000.0 : parsedTime
            } else {
                elapsed += ms / 1000.0
                t = elapsed
            }
            points.append(ExternalRRPoint(t: t, ms: ms))
        }
        return points
    }

    private func parseExternalHRReferenceCSV(at referenceURL: URL) throws -> [ExternalHRSample] {
        let text = try String(contentsOf: referenceURL, encoding: .utf8)
        let lines = text.split(whereSeparator: \.isNewline).map(String.init)
        guard let header = lines.first else { return [] }
        let headers = csvFields(header).map { $0.trimmingCharacters(in: .whitespacesAndNewlines).lowercased() }
        let hrIndex = firstHeaderIndex(in: headers,
                                       names: ["hr", "heart_rate", "bpm", "value"])
        let timeIndex = firstHeaderIndex(in: headers,
                                         names: ["elapsed_ms", "time_ms", "timestamp_ms", "t_ms", "seconds", "time_s", "timestamp", "t"])
        var points: [ExternalHRSample] = []
        var elapsed: TimeInterval = 0
        for line in lines.dropFirst() {
            let fields = csvFields(line)
            guard let hrIndex, hrIndex < fields.count,
                  let bpm = Double(fields[hrIndex].trimmingCharacters(in: .whitespacesAndNewlines)),
                  bpm > 0 else { continue }
            let t: TimeInterval
            if let timeIndex, timeIndex < fields.count,
               let parsedTime = Double(fields[timeIndex].trimmingCharacters(in: .whitespacesAndNewlines)) {
                t = headers[timeIndex].contains("ms") ? parsedTime / 1000.0 : parsedTime
            } else {
                t = elapsed
                elapsed += 1
            }
            points.append(ExternalHRSample(t: t, bpm: bpm))
        }
        return points
    }

    private func normalizeReferenceCSV(_ text: String) -> String {
        text.split(whereSeparator: \.isNewline)
            .map { $0.trimmingCharacters(in: .whitespacesAndNewlines) }
            .filter { !$0.isEmpty }
            .joined(separator: "\n")
    }

    private func firstHeaderIndex(in headers: [String], names: [String]) -> Int? {
        for name in names {
            if let index = headers.firstIndex(of: name) { return index }
        }
        return nil
    }

    private func csvFields(_ line: String) -> [String] {
        var fields: [String] = []
        var current = ""
        var quoted = false
        for char in line {
            if char == "\"" {
                quoted.toggle()
            } else if char == "," && !quoted {
                fields.append(current)
                current.removeAll()
            } else {
                current.append(char)
            }
        }
        fields.append(current)
        return fields
    }

    private func scoreExternalRR(_ points: [ExternalRRPoint], windowSeconds: TimeInterval) -> RRReferenceScore {
        let ordered = points.sorted { $0.t < $1.t }
        guard let first = ordered.first else {
            return RRReferenceScore(raw: 0, kept: 0, confidencePercent: 0,
                                    duration: 0, maxGap: 0, rmssd: nil,
                                    ready: false, reason: "reference_empty")
        }
        let end = first.t + windowSeconds
        let window = ordered.filter { $0.t >= first.t && $0.t <= end }
        var kept: [(ordinal: Int, value: Double)] = []
        var rejectedRange = 0
        var rejectedDelta = 0
        for index in window.indices {
            let point = window[index]
            guard 300...2000 ~= point.ms else {
                rejectedRange += 1
                continue
            }
            if let localMedian = Self.localMedianExternalRR(points: window, around: index),
               localMedian > 0,
               abs(point.ms - localMedian) / localMedian > 0.20 {
                rejectedDelta += 1
                continue
            }
            kept.append((ordinal: index, value: point.ms))
        }
        let duration = (window.last?.t ?? first.t) - first.t
        let maxGap = zip(window, window.dropFirst()).map { $1.t - $0.t }.max() ?? 0
        let confidence = window.isEmpty ? 0 : Int((Double(kept.count) / Double(window.count) * 100).rounded())
        let successiveDifferenceCount = AtriaHRVSuccessiveDifferences.adjacentValues(kept).count
        let minimumSuccessiveDifferenceCount = max(
            1,
            Int(ceil(Double(max(0, kept.count - 1)) * 0.70))
        )
        let rmssdValue = Self.referenceRMSSD(kept)
        let ready = duration >= windowSeconds - 1
            && maxGap <= HRVSnapshot.maxReadyRRGapSeconds
            && kept.count >= 240
            && confidence >= 75
            && successiveDifferenceCount >= minimumSuccessiveDifferenceCount
            && rmssdValue != nil
        let reason: String
        if duration < windowSeconds - 1 { reason = "reference_window" }
        else if maxGap > HRVSnapshot.maxReadyRRGapSeconds { reason = "reference_gap" }
        else if kept.count < 240 { reason = "reference_beats" }
        else if confidence < 75 { reason = "reference_confidence" }
        else if successiveDifferenceCount < minimumSuccessiveDifferenceCount { reason = "reference_differences" }
        else if rmssdValue == nil { reason = "reference_metrics" }
        else { reason = "ready" }

        _ = rejectedRange
        _ = rejectedDelta
        return RRReferenceScore(raw: window.count,
                                kept: kept.count,
                                confidencePercent: confidence,
                                duration: duration,
                                maxGap: maxGap,
                                rmssd: rmssdValue,
                                ready: ready,
                                reason: reason)
    }

    private nonisolated static func localMedianExternalRR(points: [ExternalRRPoint], around index: Int) -> Double? {
        let radius = 2
        let lower = max(points.startIndex, index - radius)
        let upper = min(points.index(before: points.endIndex), index + radius)
        let values = points[lower...upper]
            .map(\.ms)
            .filter { 300...2000 ~= $0 }
            .sorted()
        guard values.count >= 3 else { return nil }
        let middle = values.count / 2
        if values.count.isMultiple(of: 2) {
            return (values[middle - 1] + values[middle]) / 2
        }
        return values[middle]
    }

    private func rrReferenceFailureReason(strap: RRSavedReferenceWindow,
                                          reference: RRReferenceScore,
                                          delta: Double?) -> String {
        if !strap.ready { return "strap_\(strap.reason)" }
        if !reference.ready { return reference.reason }
        guard let delta else { return "missing_rmssd" }
        if delta > 5 { return "rmssd_delta_over_tolerance" }
        return "unknown"
    }

    private func compareHRReference(strap: [ExternalHRSample],
                                    reference: [ExternalHRSample],
                                    toleranceBPM: Double,
                                    maxPairAge: TimeInterval) -> HRReferenceComparison {
        let paired = pairHRSamples(strap: strap, reference: reference, maxAge: maxPairAge)
        let deltas = paired.map { abs($0.strap.bpm - $0.reference.bpm) }
        let duration = pairedDuration(paired)
        let meanDelta = deltas.isEmpty ? nil : deltas.reduce(0, +) / Double(deltas.count)
        let medianDelta = median(deltas)
        let maxDelta = deltas.max()
        let withinTolerance = deltas.filter { $0 <= toleranceBPM }.count
        let withinPercent = deltas.isEmpty ? 0 : Int((Double(withinTolerance) / Double(deltas.count) * 100).rounded())
        let ready = paired.count >= 30
            && duration >= 60
            && meanDelta.map { $0 <= toleranceBPM } == true
            && maxDelta.map { $0 <= toleranceBPM } == true
        let reason: String
        if paired.count < 30 { reason = "insufficient_pairs" }
        else if duration < 60 { reason = "window_too_short" }
        else if meanDelta == nil || maxDelta == nil { reason = "missing_metrics" }
        else if meanDelta! > toleranceBPM { reason = "mean_delta_over_tolerance" }
        else if maxDelta! > toleranceBPM { reason = "max_delta_over_tolerance" }
        else { reason = "ready" }
        return HRReferenceComparison(pairs: paired.count,
                                     duration: duration,
                                     meanDelta: meanDelta,
                                     medianDelta: medianDelta,
                                     maxDelta: maxDelta,
                                     withinTolerancePercent: withinPercent,
                                     ready: ready,
                                     reason: reason)
    }

    private func pairHRSamples(strap: [ExternalHRSample],
                               reference: [ExternalHRSample],
                               maxAge: TimeInterval) -> [(strap: ExternalHRSample, reference: ExternalHRSample)] {
        let refs = reference.sorted { $0.t < $1.t }
        guard !refs.isEmpty else { return [] }
        return strap.sorted { $0.t < $1.t }.compactMap { sample in
            var best: ExternalHRSample?
            var bestDelta = maxAge
            for candidate in refs {
                let delta = abs(candidate.t - sample.t)
                if delta <= bestDelta {
                    best = candidate
                    bestDelta = delta
                } else if candidate.t > sample.t && delta > bestDelta {
                    break
                }
            }
            guard let best else { return nil }
            return (sample, best)
        }
    }

    private func pairedDuration(_ pairs: [(strap: ExternalHRSample, reference: ExternalHRSample)]) -> TimeInterval {
        guard let first = pairs.first?.strap.t,
              let last = pairs.last?.strap.t else { return 0 }
        return max(0, last - first)
    }

    private func median(_ values: [Double]) -> Double? {
        guard !values.isEmpty else { return nil }
        let ordered = values.sorted()
        let middle = ordered.count / 2
        if ordered.count.isMultiple(of: 2) {
            return (ordered[middle - 1] + ordered[middle]) / 2.0
        }
        return ordered[middle]
    }

    nonisolated static func referenceRMSSD(_ values: [(ordinal: Int, value: Double)]) -> Double? {
        let diffs = AtriaHRVSuccessiveDifferences.adjacentValues(values)
        guard !diffs.isEmpty else { return nil }
        let meanSquare = diffs.reduce(0) { $0 + ($1 * $1) } / Double(diffs.count)
        return sqrt(meanSquare)
    }

    private func hrReferenceCSV(for reference: HRSavedReferenceSession, isoFormatter: ISO8601DateFormatter) -> String {
        var rows = ["elapsed_ms,kind,source,opcode,len,label,value,iso_time,session_label"]
        for sample in reference.samples.sorted(by: { $0.t < $1.t }) {
            let elapsedMs = Int((sample.t * 1000).rounded())
            let sampleTime = reference.session.start.addingTimeInterval(sample.t)
            rows.append("\(elapsedMs),hr,0x2A37,,,hr,\(sample.bpm),\(csvEscape(isoFormatter.string(from: sampleTime))),\(csvEscape(reference.session.label))")
        }
        return rows.joined(separator: "\n") + "\n"
    }

    private func bestSavedHRReferenceSession() -> HRSavedReferenceSession? {
        let candidates = canonicalSessions().compactMap { session -> HRSavedReferenceSession? in
            let samples = session.points.filter { $0.bpm > 0 }.sorted { $0.t < $1.t }
            guard samples.count >= 30, session.duration >= 60 else { return nil }
            return HRSavedReferenceSession(session: session, samples: samples)
        }
        return candidates.max { lhs, rhs in
            let lhsScore = hrReferenceScore(lhs)
            let rhsScore = hrReferenceScore(rhs)
            if lhsScore != rhsScore { return lhsScore < rhsScore }
            return lhs.session.end < rhs.session.end
        }
    }

    private func hrReferenceScore(_ reference: HRSavedReferenceSession) -> Double {
        let coverage = reference.session.duration > 0
            ? min(1.0, observedHRSeconds(reference.samples) / reference.session.duration)
            : 0.0
        return Double(reference.samples.count) + min(reference.session.duration, 3600) + (coverage * 1000)
    }

    private func observedHRSeconds(_ points: [SavedSession.Point]) -> TimeInterval {
        guard points.count > 1 else { return 0 }
        let sorted = points.sorted { $0.t < $1.t }
        var total: TimeInterval = 0
        for index in 1..<sorted.count {
            total += min(max(0, sorted[index].t - sorted[index - 1].t), SavedSession.workoutContinuityGapLimit)
        }
        return total
    }

    private func safeFileStem(_ value: String) -> String {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        let source = trimmed.isEmpty ? "session" : trimmed
        let safe = source.replacingOccurrences(of: "[^A-Za-z0-9_-]",
                                               with: "-",
                                               options: .regularExpression)
        return String(safe.prefix(80))
    }

    private func csvEscape(_ value: String) -> String {
        let escaped = value.replacingOccurrences(of: "\"", with: "\"\"")
        if escaped.contains(",") || escaped.contains("\"") || escaped.contains("\n") {
            return "\"\(escaped)\""
        }
        return escaped
    }

    private func writeAutomaticSessionBackup(
        reason: String,
        completion: (@MainActor (Bool) -> Void)? = nil
    ) {
        guard !restorePersistenceFenceActive else {
            completion?(false)
            return
        }
        automaticBackupGeneration &+= 1
        let generation = automaticBackupGeneration
        sessionBackupStatusGeneration &+= 1
        let statusGeneration = sessionBackupStatusGeneration
        let request = makeSessionBackupWriteRequest(label: "auto-\(reason)")
        sessionBackupWorker.enqueueLatest(request) { [weak self] result in
            Task { @MainActor [weak self] in
                guard let self else { return }
                let isLatest = generation == self.automaticBackupGeneration
                    && Self.backupStatusGenerationIsCurrent(
                        resultGeneration: statusGeneration,
                        currentGeneration: self.sessionBackupStatusGeneration
                    )
                if isLatest {
                    self.refreshBackupStatusCacheDeferred(
                        reason: "automatic_\(reason)",
                        expectedAutomaticGeneration: generation,
                        expectedStatusGeneration: statusGeneration
                    )
                }
                AtriaDebugLog("ATRIADBG session_backup_auto status=%@ reason=%@ path=%@ sessions=%d generation=%d latest=%d",
                              result.url == nil ? "error" : "ok",
                              reason,
                              result.status.path,
                              result.sessions,
                              generation,
                              isLatest ? 1 : 0)
                completion?(result.url != nil)
            }
        }
    }

    private func makeSessionBackupIOSnapshot() -> SessionBackupIOSnapshot {
        let rollups = dailyRollupHistory.isEmpty ? dailyRollupStore.rollups(last: 400) : dailyRollupHistory
        return SessionBackupIOSnapshot(
            canonicalRevision: backupCanonicalRevision,
            sessions: sessions,
            baseline: baseline,
            profile: profile,
            dailyMetrics: dailyMetricHistory,
            dailyRollups: rollups,
            confirmedSleeps: cachedConfirmedSleeps,
            confirmedWorkouts: cachedConfirmedWorkouts,
            sessionFileURL: url,
            canonicalBackupMirrorsToICloud: UserDefaults.standard.bool(forKey: Self.iCloudBackupEnabledKey),
            safetyWriteRequest: SessionBackupWriteRequest(
                label: "pre-restore",
                sessions: sessions,
                baseline: baseline,
                profile: profile,
                dailyMetrics: dailyMetricHistory,
                dailyRollups: rollups,
                confirmedSleeps: cachedConfirmedSleeps,
                confirmedWorkouts: cachedConfirmedWorkouts,
                backupDirectory: sessionBackupDirectory(),
                // This is a short-lived rollback point for the local restore
                // transaction. The successful post-restore canonical backup
                // is the artifact that may mirror to iCloud; mirroring this
                // safety copy would leave an unpruned duplicate behind.
                mirrorsToICloud: false
            )
        )
    }

    /// Entire archive read/validation/preparation side. This function is called
    /// only by `sessionBackupIOWorker`; it never observes or mutates SessionStore.
    private nonisolated static func performSessionBackupIO(_ request: SessionBackupIORequest) -> SessionBackupIOResult {
        switch request {
        case .verifyLatest(let snapshot):
            return verifyLatestSessionBackup(snapshot)
        case .prepareLatestRestore(let snapshot):
            let files = sessionBackupDirectoriesForReading(sessionFileURL: snapshot.sessionFileURL)
                .flatMap { directory in
                    (try? FileManager.default.contentsOfDirectory(at: directory,
                                                                  includingPropertiesForKeys: nil,
                                                                  options: [.skipsHiddenFiles])) ?? []
                }
                .filter { isSessionBackupFile($0, includeSafetyBackups: false) }
            guard let sourceURL = bestRestorableSessionBackupURL(from: files) else {
                return .failure(SessionBackupIOFailure(reason: "no_backup_files",
                                                       path: "none",
                                                       safetyURL: nil,
                                                       schema: 0,
                                                       errorDescription: nil))
            }
            return prepareSessionBackupRestore(sourceURL: sourceURL, snapshot: snapshot)
        case .prepareRestore(let sourceURL, let snapshot):
            return prepareSessionBackupRestore(sourceURL: sourceURL, snapshot: snapshot)
        case .commitRestore(let prepared, let rollback):
            return commitPreparedSessionBackupRestore(prepared, rollback: rollback)
        }
    }

    private nonisolated static func verifyLatestSessionBackup(_ snapshot: SessionBackupIOSnapshot) -> SessionBackupIOResult {
        guard let latest = latestSessionBackupURL(sessionFileURL: snapshot.sessionFileURL,
                                                  includeSafetyBackups: false) else {
            AtriaDebugLog("ATRIADBG session_backup_verify status=missing reason=no_backup_files")
            return .verification(.missing)
        }
        do {
            let data = try sessionBackupPayloadData(at: latest)
            let envelope = try decodeSessionBackupEnvelope(from: data)
            let schemaOK = supportedBackupSchemas.contains(envelope.schema)
            let countMatches = envelope.sessions.count == snapshot.sessions.count
            let backupDigest = makeBackupContentDigest(sessions: envelope.sessions,
                                                       baseline: envelope.baseline,
                                                       profile: envelope.profile,
                                                       dailyMetrics: envelope.dailyMetrics,
                                                       dailyRollups: envelope.dailyRollups,
                                                       confirmedSleeps: envelope.confirmedSleeps,
                                                       confirmedWorkouts: envelope.confirmedWorkouts)
            let currentDigest = makeBackupContentDigest(sessions: snapshot.sessions,
                                                        baseline: snapshot.baseline,
                                                        profile: snapshot.profile,
                                                        dailyMetrics: envelope.schema >= 2 ? snapshot.dailyMetrics : nil,
                                                        dailyRollups: envelope.schema >= 2 ? snapshot.dailyRollups : nil,
                                                        confirmedSleeps: envelope.schema >= 2 ? snapshot.confirmedSleeps : nil,
                                                        confirmedWorkouts: envelope.schema >= 4 ? snapshot.confirmedWorkouts : nil)
            let digestMatches = backupDigest != nil && backupDigest == currentDigest
            let status = countMatches && schemaOK && digestMatches ? "ok" : "mismatch"
            func total(_ sessions: [SavedSession], _ value: (SavedSession) -> Int) -> Int {
                sessions.reduce(0) { $0 + value($1) }
            }
            AtriaDebugLog("ATRIADBG session_backup_verify status=%@ path=%@ schema=%d sessions=%d current_sessions=%d rr_samples=%d current_rr_samples=%d motion_hints=%d current_motion_hints=%d motion_short_samples=%d current_motion_short_samples=%d hr_raw_2a37=%d current_hr_raw_2a37=%d hr_accepted=%d current_hr_accepted=%d hr_raw_gaps=%d current_hr_raw_gaps=%d hr_accepted_gaps=%d current_hr_accepted_gaps=%d bytes=%d profile_max_hr=%d baseline_samples=%d digest=%@ current_digest=%@ digest_match=%d",
                          status,
                          backupRelativePath(for: latest),
                          envelope.schema,
                          envelope.sessions.count,
                          snapshot.sessions.count,
                          total(envelope.sessions, { $0.rrSampleCount }),
                          total(snapshot.sessions, { $0.rrSampleCount }),
                          total(envelope.sessions, { $0.motionHintCountValue }),
                          total(snapshot.sessions, { $0.motionHintCountValue }),
                          total(envelope.sessions, { $0.motionShortCountValue }),
                          total(snapshot.sessions, { $0.motionShortCountValue }),
                          total(envelope.sessions, { $0.hrRaw2A37Value }),
                          total(snapshot.sessions, { $0.hrRaw2A37Value }),
                          total(envelope.sessions, { $0.hrAcceptedValue }),
                          total(snapshot.sessions, { $0.hrAcceptedValue }),
                          total(envelope.sessions, { $0.hrRawGapsValue }),
                          total(snapshot.sessions, { $0.hrRawGapsValue }),
                          total(envelope.sessions, { $0.hrAcceptedGapsValue }),
                          total(snapshot.sessions, { $0.hrAcceptedGapsValue }),
                          data.count,
                          envelope.profile.maxHR,
                          envelope.baseline.sessions,
                          backupDigest ?? "error",
                          currentDigest ?? "error",
                          digestMatches ? 1 : 0)
            return .verification(SessionBackupStatus(available: true,
                                                     current: status == "ok",
                                                     path: backupRelativePath(for: latest),
                                                     sessions: envelope.sessions.count,
                                                     rrSamples: total(envelope.sessions, { $0.rrSampleCount }),
                                                     bytes: data.count,
                                                     reason: status == "ok" ? "current" : "digest_mismatch"))
        } catch {
            AtriaDebugLog("ATRIADBG session_backup_verify status=error error=%@", String(describing: error))
            return .verification(SessionBackupStatus(available: true,
                                                     current: false,
                                                     path: backupRelativePath(for: latest),
                                                     sessions: 0,
                                                     rrSamples: 0,
                                                     bytes: 0,
                                                     reason: "decode_error"))
        }
    }

    private nonisolated static func prepareSessionBackupRestore(sourceURL: URL,
                                                                snapshot: SessionBackupIOSnapshot) -> SessionBackupIOResult {
        // The safety archive is the crash-recovery authority. Never mutate the
        // canonical store unless its atomic write has completed successfully.
        let safety = SessionBackupWriter.write(snapshot.safetyWriteRequest)
        guard let safetyURL = safety.url else {
            return .failure(SessionBackupIOFailure(reason: "pre_restore_backup_failed",
                                                   path: backupRelativePath(for: sourceURL),
                                                   safetyURL: nil,
                                                   schema: 0,
                                                   errorDescription: nil))
        }
        SessionBackupWriter.prunePreRestoreBackups(
            in: snapshot.safetyWriteRequest.backupDirectory,
            keep: 1
        )
        do {
            let envelope = try decodeSessionBackupEnvelope(at: sourceURL)
            guard supportedBackupSchemas.contains(envelope.schema) else {
                return .failure(SessionBackupIOFailure(reason: "unsupported_schema",
                                                       path: backupRelativePath(for: sourceURL),
                                                       safetyURL: safetyURL,
                                                       schema: envelope.schema,
                                                       errorDescription: nil))
            }
            try validateSessionBackupEnvelopeForImport(envelope)
            let restoredSessions = sessionsAfterBackupRestore(current: snapshot.sessions,
                                                               backup: envelope.sessions)
            let restoredWorkouts = envelope.confirmedWorkouts.map {
                confirmedWorkoutsAfterBackupRestore(current: snapshot.confirmedWorkouts, backup: $0)
            } ?? snapshot.confirmedWorkouts
            let restoredSleeps = envelope.confirmedSleeps.map {
                confirmedSleepsAfterBackupRestore(current: snapshot.confirmedSleeps, backup: $0)
            } ?? snapshot.confirmedSleeps
            let restoredMetrics = envelope.dailyMetrics.map {
                dailyMetricsAfterBackupRestore(current: snapshot.dailyMetrics, backup: $0)
            } ?? snapshot.dailyMetrics
            let restoredRollups = envelope.dailyRollups.map {
                dailyRollupsAfterBackupRestore(current: snapshot.dailyRollups, backup: $0)
            } ?? snapshot.dailyRollups
            let restoredProfile = profileAfterBackupRestore(current: snapshot.profile,
                                                             backup: envelope.profile)
            let restoredBaseline = rebuildBaseline(from: restoredSessions,
                                                   previousBaseline: snapshot.baseline,
                                                   profile: restoredProfile,
                                                   confirmedSleeps: restoredSleeps)
            let digest = makeBackupContentDigest(sessions: restoredSessions,
                                                 baseline: restoredBaseline,
                                                 profile: restoredProfile,
                                                 dailyMetrics: envelope.schema >= 2 ? restoredMetrics : nil,
                                                 dailyRollups: envelope.schema >= 2 ? restoredRollups : nil,
                                                 confirmedSleeps: envelope.schema >= 2 ? restoredSleeps : nil,
                                                 confirmedWorkouts: envelope.schema >= 4 ? restoredWorkouts : nil) ?? "error"
            let projection = SessionBackupDerivedProjection(
                latestReferenceValidatedHRVSource: latestReferenceValidatedHRVSource(in: restoredSessions),
                latestLocalRMSSDSource: latestLocalRMSSDSource(in: restoredSessions),
                canonicalSessions: makeCanonicalSessions(from: restoredSessions),
                dailyMetricSparklines: makeDailyMetricSparklines(from: restoredMetrics),
                restingTrend14: restingTrend14(from: restoredSessions,
                                               now: Date(),
                                               calendar: .current)
            )
            return .preparedRestore(PreparedSessionBackupRestore(sourceURL: sourceURL,
                                                                 safetyURL: safetyURL,
                                                                 envelope: envelope,
                                                                 sessions: restoredSessions,
                                                                 baseline: restoredBaseline,
                                                                 profile: restoredProfile,
                                                                 dailyMetrics: restoredMetrics,
                                                                 dailyRollups: restoredRollups,
                                                                 confirmedSleeps: restoredSleeps,
                                                                 confirmedWorkouts: restoredWorkouts,
                                                                 digest: digest,
                                                                 basedOnCanonicalRevision: snapshot.canonicalRevision,
                                                                 derivedProjection: projection))
        } catch {
            return .failure(SessionBackupIOFailure(reason: String(describing: error),
                                                   path: backupRelativePath(for: sourceURL),
                                                   safetyURL: safetyURL,
                                                   schema: 0,
                                                   errorDescription: String(describing: error)))
        }
    }

    /// Persist the already-prepared canonical payload on the same FIFO utility
    /// worker. MainActor does not encode a multi-megabyte session archive or
    /// synchronously touch the filesystem during Restore.
    private nonisolated static func commitPreparedSessionBackupRestore(
        _ prepared: PreparedSessionBackupRestore,
        rollback: SessionBackupIOSnapshot
    ) -> SessionBackupIOResult {
        let documents = rollback.sessionFileURL.deletingLastPathComponent()
        let workoutsURL = documents.appendingPathComponent(ConfirmedWorkoutDefaults.fileName)
        let metricsURL = documents.appendingPathComponent("daily-metrics.json")
        let rollupsURL = documents.appendingPathComponent("daily-rollups.json")
        let markerURL = AtriaRestoreTransactionCoordinator.markerURL(nextTo: rollback.sessionFileURL)
        let encoder = JSONEncoder()

        do {
            let sessionData = try encoder.encode(prepared.sessions)
            let sleepsData = try encoder.encode(prepared.confirmedSleeps)
            let workoutsData = try encoder.encode(prepared.confirmedWorkouts)
            let baselineData = try encoder.encode(prepared.baseline)
            let profileData = try encoder.encode(prepared.profile)
            let rollbackSessionsData = try encoder.encode(rollback.sessions)
            let rollbackSleepsData = try encoder.encode(rollback.confirmedSleeps)
            let rollbackWorkoutsData = try encoder.encode(rollback.confirmedWorkouts)
            let rollbackBaselineData = try encoder.encode(rollback.baseline)
            let rollbackProfileData = try encoder.encode(rollback.profile)
            var destinations: [AtriaRestoreTransaction.Destination] = []

            if prepared.envelope.confirmedSleeps != nil {
                destinations.append(.defaults(
                    key: ConfirmedSleepDefaults.key,
                    previous: .data(rollbackSleepsData),
                    next: .data(sleepsData)
                ))
            }
            if prepared.envelope.confirmedWorkouts != nil {
                destinations.append(.file(path: workoutsURL.path,
                                          previous: rollbackWorkoutsData,
                                          next: workoutsData))
                destinations.append(.defaults(
                    key: ConfirmedWorkoutDefaults.key,
                    previous: .data(rollbackWorkoutsData),
                    next: .data(workoutsData)
                ))
            }
            if prepared.envelope.dailyMetrics != nil {
                destinations.append(.file(path: metricsURL.path,
                                          previous: try encoder.encode(rollback.dailyMetrics),
                                          next: try encoder.encode(prepared.dailyMetrics)))
            }
            if prepared.envelope.dailyRollups != nil {
                let rollupEncoder = JSONEncoder()
                rollupEncoder.outputFormatting = [.prettyPrinted, .sortedKeys]
                destinations.append(.file(path: rollupsURL.path,
                                          previous: try rollupEncoder.encode(rollback.dailyRollups),
                                          next: try rollupEncoder.encode(prepared.dailyRollups)))
            }
            destinations.append(.defaults(
                key: PersonalBaseline.persistenceKey,
                previous: .data(rollbackBaselineData),
                next: .data(baselineData)
            ))
            destinations.append(.defaults(
                key: AthleteProfile.persistenceKey,
                previous: .data(rollbackProfileData),
                next: .data(profileData)
            ))
            destinations.append(.defaults(
                key: "maxHR",
                previous: .integer(rollback.profile.maxHR),
                next: .integer(prepared.profile.maxHR)
            ))
            destinations.append(.defaults(
                key: AthleteProfile.onboardingCompletionKey,
                previous: .boolean(rollback.profile.hasCompletedOnboarding),
                next: .boolean(prepared.profile.hasCompletedOnboarding)
            ))
            destinations.append(.file(path: rollback.sessionFileURL.path,
                                      previous: rollbackSessionsData,
                                      next: sessionData))

            let transaction = AtriaRestoreTransaction(destinations: destinations)
            try AtriaRestoreTransactionCoordinator.commit(transaction, markerURL: markerURL)

            // Persist the exact merged canonical state as a new archive. This
            // makes Settings coherent after both a fresh restore and a stale
            // install whose newer local records won the merge.
            let canonicalRequest = SessionBackupWriteRequest(
                label: "post-restore",
                sessions: prepared.sessions,
                baseline: prepared.baseline,
                profile: prepared.profile,
                dailyMetrics: prepared.dailyMetrics,
                dailyRollups: prepared.dailyRollups,
                confirmedSleeps: prepared.confirmedSleeps,
                confirmedWorkouts: prepared.confirmedWorkouts,
                backupDirectory: rollback.safetyWriteRequest.backupDirectory,
                mirrorsToICloud: rollback.canonicalBackupMirrorsToICloud
            )
            let canonicalBackup = SessionBackupWriter.write(canonicalRequest)
            // The pre-restore archive remains the only standalone safety copy
            // if the canonical post-restore archive could not be written.
            SessionBackupWriter.prunePreRestoreBackups(
                in: rollback.safetyWriteRequest.backupDirectory,
                keep: canonicalBackup.url == nil ? 1 : 0
            )
            var committed = prepared
            committed.canonicalBackupStatus = canonicalBackup.url == nil
                ? SessionBackupStatus(available: false,
                                      current: false,
                                      path: "none",
                                      sessions: prepared.sessions.count,
                                      rrSamples: prepared.sessions.reduce(0) { $0 + $1.rrSampleCount },
                                      bytes: 0,
                                      reason: "post_restore_backup_failed")
                : canonicalBackup.status
            return .committedRestore(committed)
        } catch {
            let markerWasRetained = FileManager.default.fileExists(atPath: markerURL.path)
            let reason = markerWasRetained
                ? "restore_marker_retained"
                : ((error as? SessionBackupCommitError)?.reason ?? "store_save_failed")
            return .failure(SessionBackupIOFailure(reason: reason,
                                                   path: backupRelativePath(for: prepared.sourceURL),
                                                   safetyURL: prepared.safetyURL,
                                                   schema: prepared.envelope.schema,
                                                   errorDescription: String(describing: error)))
        }
    }

    private enum SessionBackupCommitError: Error {
        case persistence(String)

        var reason: String {
            switch self {
            case .persistence(let reason): reason
            }
        }
    }

    @discardableResult
    nonisolated static func recoverPendingRestoreTransaction()
        -> AtriaRestoreTransactionCoordinator.RecoveryResult {
        let documents = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
        let sessionURL = documents.appendingPathComponent("sessions.json")
        let markerURL = AtriaRestoreTransactionCoordinator.markerURL(nextTo: sessionURL)
        let result = AtriaRestoreTransactionCoordinator.recoverIfNeeded(markerURL: markerURL)
        guard result != .noMarker else { return result }
        AtriaDebugLog("ATRIADBG session_backup_restore_recovery result=%@ marker=%@",
                      String(describing: result), markerURL.lastPathComponent)
        return result
    }

    func verifyLatestSessionBackupFromLaunchIfRequested(arguments: [String] = ProcessInfo.processInfo.arguments) {
        guard arguments.contains("--atria-verify-backup")
            || arguments.contains("--atria-verify-session-backup") else { return }
        Task { @MainActor in
            _ = await verifyLatestSessionBackup()
        }
    }

    @discardableResult
    func verifyLatestSessionBackup() async -> SessionBackupStatus {
        guard !sessionBackupUserOperationInProgress else {
            AtriaDebugLog("ATRIADBG session_backup_verify status=busy reason=operation_in_progress")
            return SessionBackupStatus(available: cachedSessionBackupStatus.available,
                                       current: false,
                                       path: cachedSessionBackupStatus.path,
                                       sessions: cachedSessionBackupStatus.sessions,
                                       rrSamples: cachedSessionBackupStatus.rrSamples,
                                       bytes: cachedSessionBackupStatus.bytes,
                                       reason: "operation_in_progress")
        }
        sessionBackupUserOperationInProgress = true
        defer { sessionBackupUserOperationInProgress = false }
        sessionBackupStatusGeneration &+= 1
        let statusGeneration = sessionBackupStatusGeneration

        let result = await sessionBackupIOWorker.performAsync(.verifyLatest(makeSessionBackupIOSnapshot()))
        guard case .verification(let status) = result else { return .missing }
        guard Self.backupStatusGenerationIsCurrent(
            resultGeneration: statusGeneration,
            currentGeneration: sessionBackupStatusGeneration
        ) else {
            return cachedSessionBackupStatus
        }
        cachedSessionBackupStatus = status
        cachedHomeDashboardDiagnostics = nil
        publishDashboardRevision()
        return status
    }

    func restoreLatestSessionBackupFromLaunchIfRequested(arguments: [String] = ProcessInfo.processInfo.arguments) {
        guard arguments.contains("--atria-restore-backup") else { return }
        Task { @MainActor in
            _ = await restoreLatestSessionBackup()
        }
    }

    @discardableResult
    func restoreLatestSessionBackup() async -> Bool {
        await restoreSessionBackup(request: .prepareLatestRestore(makeSessionBackupIOSnapshot()))
    }

    @discardableResult
    func restoreSessionBackup(from backupURL: URL) async -> Bool {
        await restoreSessionBackup(request: .prepareRestore(backupURL, makeSessionBackupIOSnapshot()))
    }

    nonisolated static func restorePreparationIsCurrent(preparedRevision: UInt64,
                                                        canonicalRevision: UInt64) -> Bool {
        preparedRevision == canonicalRevision
    }

    nonisolated static func restoreRetryAllowed(completedRemerges: Int,
                                                maximumRemerges: Int = 3) -> Bool {
        completedRemerges < maximumRemerges
    }

    nonisolated static func restoreFailureRequiresRuntimeBlock(reason: String) -> Bool {
        reason == "restore_marker_retained"
    }

    nonisolated static func prunePreRestoreBackups(in directory: URL, keep: Int) {
        SessionBackupWriter.prunePreRestoreBackups(in: directory, keep: keep)
    }

    private func beginRestorePersistenceFence() async {
        restorePersistenceFenceActive = true
        await Self.confirmedRecordTransactionGate.acquire()
        restoreOwnsConfirmedRecordTransactionGate = true
        await Self.confirmedRecordWorker.fence()
        automaticBackupGeneration &+= 1
        sessionBackupStatusGeneration &+= 1
        pendingSessionSaveWorkItem?.cancel()
        pendingDailyMetricSaveWorkItem?.cancel()
        pendingDailyMetricSaveWorkItem = nil
        pendingDailyMetricPersistRevision = nil
        await dailyRollupStore.beginPersistenceFence()
        await withCheckedContinuation { continuation in
            persistenceQueue.async { continuation.resume() }
        }
        await sessionBackupWorker.fence()
    }

    private func endRestorePersistenceFence() {
        dailyRollupStore.endPersistenceFence(persistCurrentSnapshot: true)
        restorePersistenceFenceActive = false
        if restoreOwnsConfirmedRecordTransactionGate {
            restoreOwnsConfirmedRecordTransactionGate = false
            Self.confirmedRecordTransactionGate.release()
        }
        // Any session finalized while the restore worker was preparing stayed
        // in memory and advanced the CAS revision. Persist its newest learned
        // baseline/profile only after the transaction is coherent.
        baseline.save()
        profile.save()
        // Publish the newest in-memory authority after the fence. These writes
        // are never snapshots captured before restore and cover legacy imports
        // that did not include every modern destination.
        markSessionPersistenceDirty()
        scheduleSessionFilePersist(reason: "restore_fence_release", delay: 0)
        scheduleDailyMetricPersist(reason: "restore_fence_release", delay: 0)
        scheduleBehaviorInsightsAfterDailyMetricPublication()
    }

    private func enterRetainedRestoreMarkerBlock() {
        // The store transition is the authority edge. SwiftUI observes the
        // published block on a later turn, so revoke the worker/token and
        // supersede its generation here before any queued completion can
        // publish against canonical state that is no longer trusted.
        revokeSleepReviewProjection(
            reason: "restore_marker_retained",
            forceGenerationSupersession: true
        )
        restoreInitializationBlocked = true
        foregroundSleepSettlementGeneration &+= 1
        pendingSleepReadinessRetry?.cancel()
        pendingSleepReadinessRetry = nil
        pendingSleepSettlementRetry?.cancel()
        pendingSleepSettlementRetry = nil
        pendingForegroundSleepSettlementWorkItem?.cancel()
        pendingForegroundSleepSettlementWorkItem = nil
        pendingForegroundSleepSettlementOwner = nil
        drainForegroundSleepSettlementCompletions(succeeded: false)
        // This worker is non-interruptible once submitted. Preserve its active
        // sentinel, mark the result stale, and let completion drain any queued
        // request through the blocked scheduler without starting new work.
        invalidateWorkoutReviewCache()
        recoveredDataRecomputeTimeoutTask?.cancel()
        recoveredDataRecomputeTimeoutTask = nil
        recoveredDataRecomputeTimeoutContext = nil
        recoveredDataRecomputeLeaseSuspendedForBackground = false
        recoveredDataProjectionLeaseRenewals.removeAll()
        recoveredDataProjectionCompletedStages.removeAll()
        recoveredDataDerivedLeaseRenewals.removeAll()
        recoveredDataDerivedCompletedStages.removeAll()
        recoveredDataPublicationFence.failAll()
        AtriaDebugLog("ATRIADBG session_store status=blocked reason=restore_marker_retained")
    }

    #if DEBUG
    var sleepReviewProjectionStateForTesting: (
        generation: Int,
        hasForegroundAuthority: Bool,
        isDeferred: Bool,
        hasPendingProjection: Bool
    ) {
        (
            sleepReviewCacheGeneration,
            sleepReviewProjectionForegroundAuthority,
            sleepReviewRefreshDeferredUntilForeground,
            pendingSleepReviewCacheGeneration != nil
                || pendingSleepReviewCacheWorkItem != nil
                || pendingSleepReviewProjectionCancellation != nil
        )
    }

    func enterRetainedRestoreMarkerBlockForTesting() {
        enterRetainedRestoreMarkerBlock()
    }
    #endif

    private func restoreSessionBackup(request: SessionBackupIORequest) async -> Bool {
        guard !restoreInitializationBlocked else {
            AtriaDebugLog("ATRIADBG session_backup_restore status=blocked reason=restore_marker_retained")
            return false
        }
        guard !sessionBackupUserOperationInProgress else {
            AtriaDebugLog("ATRIADBG session_backup_restore status=busy reason=operation_in_progress")
            return false
        }
        sessionBackupUserOperationInProgress = true
        defer { sessionBackupUserOperationInProgress = false }
        sessionBackupStatusGeneration &+= 1

        await beginRestorePersistenceFence()
        var shouldReleaseRestoreFence = true
        var shouldPublishStressReplayAfterRestore = false
        defer {
            if shouldReleaseRestoreFence {
                endRestorePersistenceFence()
                if shouldPublishStressReplayAfterRestore {
                    publishHistoricalStressSessionAuthority()
                    publishStressReplayTerminalEdge(reason: "backup_restore")
                } else {
                    // A failed non-retained restore still releases the same
                    // calibration deferral fence. Independent fallback-rest
                    // changes may have survived while I/O was in flight, so
                    // let Home compare the final state without forcing replay.
                    publishStressCalibrationFenceDidRelease(
                        reason: "backup_restore_finished_without_apply"
                    )
                }
            }
        }

        var result = await sessionBackupIOWorker.performAsync(request)
        var completedRemerges = 0
        while true {
            switch result {
            case .failure(let failure):
                if Self.restoreFailureRequiresRuntimeBlock(reason: failure.reason) {
                    // The durable marker is now the only authority. Keep every
                    // writer fenced and replace the live app with the recovery
                    // root; a subsequent launch will retry the transaction.
                    shouldReleaseRestoreFence = false
                    enterRetainedRestoreMarkerBlock()
                }
                let status = failure.reason == "no_backup_files" ? "missing" : "error"
                AtriaDebugLog("ATRIADBG session_backup_restore status=%@ reason=%@ error=%@",
                              status,
                              failure.reason,
                              failure.errorDescription ?? "none")
                recordSessionBackupRestoreDebug(status: status,
                                                path: failure.path,
                                                safetyPath: failure.safetyURL.map { Self.backupRelativePath(for: $0) },
                                                schema: failure.schema,
                                                reason: failure.reason)
                return false

            case .verification(_), .committedRestore(_):
                return false

            case .preparedRestore(let prepared):
                let canonical = makeSessionBackupIOSnapshot()
                guard Self.restorePreparationIsCurrent(
                    preparedRevision: prepared.basedOnCanonicalRevision,
                    canonicalRevision: canonical.canonicalRevision
                ) else {
                    guard Self.restoreRetryAllowed(completedRemerges: completedRemerges) else {
                        recordSessionBackupRestoreDebug(status: "error",
                                                        path: Self.backupRelativePath(for: prepared.sourceURL),
                                                        safetyPath: Self.backupRelativePath(for: prepared.safetyURL),
                                                        schema: prepared.envelope.schema,
                                                        reason: "restore_remerge_limit")
                        return false
                    }
                    completedRemerges += 1
                    AtriaDebugLog("ATRIADBG session_backup_restore status=remerge stale_revision=%llu current_revision=%llu",
                                  prepared.basedOnCanonicalRevision,
                                  canonical.canonicalRevision)
                    result = await sessionBackupIOWorker.performAsync(
                        .prepareRestore(prepared.sourceURL, canonical)
                    )
                    continue
                }

                let commit = await sessionBackupIOWorker.performAsync(
                    .commitRestore(prepared, rollback: canonical)
                )
                switch commit {
                case .failure(let failure):
                    if Self.restoreFailureRequiresRuntimeBlock(reason: failure.reason) {
                        shouldReleaseRestoreFence = false
                        enterRetainedRestoreMarkerBlock()
                    }
                    AtriaDebugLog("ATRIADBG session_backup_restore status=error reason=%@ error=%@",
                                  failure.reason,
                                  failure.errorDescription ?? "none")
                    recordSessionBackupRestoreDebug(status: "error",
                                                    path: failure.path,
                                                    safetyPath: failure.safetyURL.map { Self.backupRelativePath(for: $0) },
                                                    schema: failure.schema,
                                                    reason: failure.reason)
                    return false

                case .committedRestore(let committed):
                    // MainActor was intentionally free while the transaction
                    // wrote. If BLE or a user action changed canonical state in
                    // that interval, never publish the stale prepared image;
                    // merge again from the fresh in-memory authority and make
                    // its transaction the final durable state.
                    guard Self.restorePreparationIsCurrent(
                        preparedRevision: canonical.canonicalRevision,
                        canonicalRevision: backupCanonicalRevision
                    ) else {
                        guard Self.restoreRetryAllowed(completedRemerges: completedRemerges) else {
                            recordSessionBackupRestoreDebug(status: "error",
                                                            path: Self.backupRelativePath(for: committed.sourceURL),
                                                            safetyPath: Self.backupRelativePath(for: committed.safetyURL),
                                                            schema: committed.envelope.schema,
                                                            reason: "restore_remerge_limit_after_commit")
                            return false
                        }
                        completedRemerges += 1
                        AtriaDebugLog("ATRIADBG session_backup_restore status=remerge_after_commit committed_revision=%llu current_revision=%llu",
                                      canonical.canonicalRevision,
                                      backupCanonicalRevision)
                        result = await sessionBackupIOWorker.performAsync(
                            .prepareRestore(committed.sourceURL, makeSessionBackupIOSnapshot())
                        )
                        continue
                    }
                    applyPreparedSessionBackupRestore(committed)
                    if let canonicalStatus = committed.canonicalBackupStatus {
                        sessionBackupStatusGeneration &+= 1
                        cachedSessionBackupStatus = canonicalStatus
                    }
                    cachedHomeDashboardDiagnostics = nil
                    refreshHomeDashboardDiagnosticsCache()
                    publishDashboardRevision()
                    shouldPublishStressReplayAfterRestore = true
                    return true

                case .verification(_), .preparedRestore(_):
                    return false
                }
            }
        }
    }

    /// The archive has already been enumerated, decompressed, decoded, merged,
    /// baseline-projected and hashed. MainActor now performs only canonical
    /// store mutation/publish. Any persistence failure rolls back to the exact
    /// pre-restore snapshot; the verified safety archive remains on disk too.
    private func applyPreparedSessionBackupRestore(_ prepared: PreparedSessionBackupRestore) {
        Self.invalidateColdSessionsFingerprint(nextTo: url)
        pendingPreparedRestingTrend14 = prepared.derivedProjection.restingTrend14
        sessions = prepared.sessions
        profile = prepared.profile
        if prepared.envelope.dailyMetrics != nil {
            pendingPreparedDailyMetricSparklines = prepared.derivedProjection.dailyMetricSparklines
            dailyMetricHistory = prepared.dailyMetrics
        }
        if prepared.envelope.dailyRollups != nil {
            dailyRollupHistory = prepared.dailyRollups
            dailyRollupHistoryRevision &+= 1
            dailyRollupStore.replaceAll(prepared.dailyRollups)
        }
        if prepared.envelope.confirmedSleeps != nil {
            setCachedConfirmedSleeps(prepared.confirmedSleeps)
            sleepHistorySnapshot = SleepHistorySnapshot(rollups: historySnapshot.rollups,
                                                        confirmedSleeps: prepared.confirmedSleeps,
                                                        dismissedCandidates: dismissedSleepCandidates)
            writeDutyCycleSleepWindow(from: prepared.confirmedSleeps)
        }
        if prepared.envelope.confirmedWorkouts != nil {
            cachedConfirmedWorkouts = prepared.confirmedWorkouts
            backupCanonicalRevision &+= 1
            confirmedWorkoutsRevision &+= 1
        }
        setLatestReferenceValidatedHRVSource(prepared.derivedProjection.latestReferenceValidatedHRVSource)
        setLatestLocalRMSSDSource(prepared.derivedProjection.latestLocalRMSSDSource)
        setCachedCanonicalSessions(prepared.derivedProjection.canonicalSessions)
        cachedHomeSavedAggregate = nil
        cachedTodayTRIMP = nil
        cachedCurrentCollectionStatus = nil
        refreshMaxHRSuggestion(reason: "backup_restore", force: false)
        baseline = prepared.baseline
        refreshHistorySnapshotCache(deferred: true)
        refreshOverviewTrendPointsCache(deferred: true)
        refreshTrainingLoadSummaryCache(deferred: true)
        refreshTodayHRZoneMinutesCache(deferred: true)

        recordSessionBackupRestoreDebug(status: "ok",
                                        path: Self.backupRelativePath(for: prepared.sourceURL),
                                        safetyPath: Self.backupRelativePath(for: prepared.safetyURL),
                                        schema: prepared.envelope.schema,
                                        sessions: sessions.count,
                                        rollups: prepared.envelope.dailyRollups?.count ?? 0,
                                        confirmedSleeps: prepared.envelope.confirmedSleeps?.count ?? 0,
                                        confirmedWorkouts: prepared.envelope.confirmedWorkouts?.count ?? 0,
                                        digest: prepared.digest,
                                        reason: "restored_latest")
        AtriaDebugLog("ATRIADBG session_backup_restore status=ok path=%@ safety=%@ schema=%d sessions=%d rollups=%d confirmed_sleeps=%d confirmed_workouts=%d baseline_samples=%d profile_max_hr=%d digest=%@",
                      Self.backupRelativePath(for: prepared.sourceURL),
                      Self.backupRelativePath(for: prepared.safetyURL),
                      prepared.envelope.schema,
                      sessions.count,
                      prepared.envelope.dailyRollups?.count ?? 0,
                      prepared.envelope.confirmedSleeps?.count ?? 0,
                      prepared.envelope.confirmedWorkouts?.count ?? 0,
                      baseline.sessions,
                      profile.maxHR,
                      prepared.digest)
    }

    private func recordSessionBackupRestoreDebug(status: String,
                                                 path: String = "none",
                                                 safetyPath: String? = nil,
                                                 schema: Int = 0,
                                                 sessions: Int = 0,
                                                 rollups: Int = 0,
                                                 confirmedSleeps: Int = 0,
                                                 confirmedWorkouts: Int = 0,
                                                 digest: String = "none",
                                                 reason: String) {
        let defaults = UserDefaults.standard
        let summary: [String: Any] = [
            "status": status,
            "path": path,
            "safetyPath": safetyPath ?? "none",
            "schema": schema,
            "sessions": sessions,
            "rollups": rollups,
            "confirmedSleeps": confirmedSleeps,
            "confirmedWorkouts": confirmedWorkouts,
            "digest": digest,
            "reason": reason
        ]
        for key in SessionBackupDebugDefaults.allRestoreKeys {
            defaults.removeObject(forKey: key)
        }
        defaults.set(summary, forKey: SessionBackupDebugDefaults.restoreSummary)
        defaults.set(status, forKey: SessionBackupDebugDefaults.restoreStatus)
        defaults.set(path, forKey: SessionBackupDebugDefaults.restorePath)
        defaults.set(safetyPath ?? "none", forKey: SessionBackupDebugDefaults.restoreSafetyPath)
        defaults.set(schema, forKey: SessionBackupDebugDefaults.restoreSchema)
        defaults.set(sessions, forKey: SessionBackupDebugDefaults.restoreSessions)
        defaults.set(rollups, forKey: SessionBackupDebugDefaults.restoreRollups)
        defaults.set(confirmedSleeps, forKey: SessionBackupDebugDefaults.restoreConfirmedSleeps)
        defaults.set(confirmedWorkouts, forKey: SessionBackupDebugDefaults.restoreConfirmedWorkouts)
        defaults.set(digest, forKey: SessionBackupDebugDefaults.restoreDigest)
        defaults.set(reason, forKey: SessionBackupDebugDefaults.restoreReason)
    }

    private func latestSessionBackupURL() -> URL? {
        latestSessionBackupURL(includeSafetyBackups: false)
    }

    private func latestRestorableSessionBackupURL() -> URL? {
        var allFiles: [URL] = []
        for backupDir in sessionBackupDirectoriesForReading() {
            guard let files = try? FileManager.default.contentsOfDirectory(at: backupDir,
                                                                           includingPropertiesForKeys: nil,
                                                                           options: [.skipsHiddenFiles])
                .filter({ Self.isSessionBackupFile($0, includeSafetyBackups: false) }) else {
                continue
            }
            allFiles.append(contentsOf: files)
        }
        return Self.bestRestorableSessionBackupURL(from: allFiles)
    }

    private func latestSessionBackupURL(includeSafetyBackups: Bool) -> URL? {
        var allFiles: [URL] = []
        for backupDir in sessionBackupDirectoriesForReading() {
            guard let files = try? FileManager.default.contentsOfDirectory(at: backupDir,
                                                                           includingPropertiesForKeys: nil,
                                                                           options: [.skipsHiddenFiles])
                .filter({ Self.isSessionBackupFile($0, includeSafetyBackups: includeSafetyBackups) }) else {
                continue
            }
            allFiles.append(contentsOf: files)
        }
        return Self.latestDecodableSessionBackupURL(from: allFiles)
    }

    private func sessionBackupDirectory() -> URL {
        url.deletingLastPathComponent().appendingPathComponent("atria-backups")
    }

    private func iCloudSessionBackupDirectory() -> URL? {
        guard let container = FileManager.default.url(forUbiquityContainerIdentifier: nil) else {
            return nil
        }
        return container
            .appendingPathComponent("Documents")
            .appendingPathComponent("Atria Backups")
    }

    private func legacySessionBackupDirectory() -> URL {
        url.deletingLastPathComponent().appendingPathComponent("whoop-backups")
    }

    private func sessionBackupDirectoriesForReading() -> [URL] {
        [sessionBackupDirectory(), legacySessionBackupDirectory()]
    }

    private func mirrorSessionBackupToICloudIfEnabled(_ backupURL: URL) {
        guard UserDefaults.standard.bool(forKey: Self.iCloudBackupEnabledKey) else {
            AtriaDebugLog("ATRIADBG session_backup_icloud status=skipped_toggle path=%@",
                          backupRelativePath(for: backupURL))
            return
        }
        guard let iCloudDir = iCloudSessionBackupDirectory() else {
            AtriaDebugLog("ATRIADBG session_backup_icloud status=unavailable path=%@",
                          backupRelativePath(for: backupURL))
            return
        }
        do {
            try FileManager.default.createDirectory(at: iCloudDir, withIntermediateDirectories: true)
            let destination = iCloudDir.appendingPathComponent(backupURL.lastPathComponent)
            if FileManager.default.fileExists(atPath: destination.path) {
                try FileManager.default.removeItem(at: destination)
            }
            try FileManager.default.copyItem(at: backupURL, to: destination)
            pruneAutomaticBackups(in: iCloudDir, keep: 3)
            AtriaDebugLog("ATRIADBG session_backup_icloud status=ok path=Documents/Atria Backups/%@",
                          destination.lastPathComponent)
        } catch {
            AtriaDebugLog("ATRIADBG session_backup_icloud status=error error=%@", String(describing: error))
        }
    }

    private func backupRelativePath(for backupURL: URL) -> String {
        let directory = backupURL.deletingLastPathComponent().lastPathComponent
        return "Documents/\(directory)/\(backupURL.lastPathComponent)"
    }

    private func backupSortDate(_ backupURL: URL) -> Date {
        if let date = (try? FileManager.default.attributesOfItem(atPath: backupURL.path)[.modificationDate]) as? Date {
            return date
        }
        return .distantPast
    }

    private func pruneAutomaticBackups(in backupDir: URL, keep: Int) {
        guard let files = try? FileManager.default.contentsOfDirectory(at: backupDir,
                                                                       includingPropertiesForKeys: nil,
                                                                       options: [.skipsHiddenFiles])
            .filter({ Self.isSessionBackupFile($0, includeSafetyBackups: true) }) else {
            AtriaDebugLog("ATRIADBG session_backup_prune status=missing_dir keep=%d deleted=0 total_json=0 auto_json=0",
                  keep)
            return
        }

        let automatic = files
            .filter { $0.deletingPathExtension().lastPathComponent.contains("-auto-") }
            .sorted { $0.lastPathComponent > $1.lastPathComponent }
        let expired = automatic.dropFirst(max(0, keep))
        var deleted = 0
        for file in expired {
            do {
                try FileManager.default.removeItem(at: file)
                deleted += 1
            } catch {
                AtriaDebugLog("ATRIADBG session_backup_prune_error file=%@ error=%@",
                      file.lastPathComponent,
                      String(describing: error))
            }
        }
        AtriaDebugLog("ATRIADBG session_backup_prune status=ok keep=%d kept_auto=%d deleted=%d total_json=%d auto_json=%d",
              keep,
              min(automatic.count, keep),
              deleted,
              files.count,
              automatic.count)
    }

    private func verifySessionBackup(at latest: URL) {
        do {
            let data = try Self.sessionBackupPayloadData(at: latest)
            let envelope = try Self.decodeSessionBackupEnvelope(from: data)
            let countMatches = envelope.sessions.count == sessions.count
            let schemaOK = Self.supportedBackupSchemas.contains(envelope.schema)
            let rollups = dailyRollupHistory.isEmpty ? dailyRollupStore.rollups(last: 400) : dailyRollupHistory
            let backupDigest = backupContentDigest(sessions: envelope.sessions,
                                                   baseline: envelope.baseline,
                                                   profile: envelope.profile,
                                                   dailyMetrics: envelope.dailyMetrics,
                                                   dailyRollups: envelope.dailyRollups,
                                                   confirmedSleeps: envelope.confirmedSleeps,
                                                   confirmedWorkouts: envelope.confirmedWorkouts)
            let currentDigest = backupContentDigest(sessions: sessions,
                                                    baseline: baseline,
                                                    profile: profile,
                                                    dailyMetrics: envelope.schema >= 2 ? dailyMetricHistory : nil,
                                                    dailyRollups: envelope.schema >= 2 ? rollups : nil,
                                                    confirmedSleeps: envelope.schema >= 2 ? cachedConfirmedSleeps : nil,
                                                    confirmedWorkouts: envelope.schema >= 4 ? cachedConfirmedWorkouts : nil)
            let digestMatches = backupDigest != nil && backupDigest == currentDigest
            let status = countMatches && schemaOK && digestMatches ? "ok" : "mismatch"
            AtriaDebugLog("ATRIADBG session_backup_verify status=%@ path=%@ schema=%d sessions=%d current_sessions=%d rr_samples=%d current_rr_samples=%d motion_hints=%d current_motion_hints=%d motion_short_samples=%d current_motion_short_samples=%d hr_raw_2a37=%d current_hr_raw_2a37=%d hr_accepted=%d current_hr_accepted=%d hr_raw_gaps=%d current_hr_raw_gaps=%d hr_accepted_gaps=%d current_hr_accepted_gaps=%d bytes=%d profile_max_hr=%d baseline_samples=%d digest=%@ current_digest=%@ digest_match=%d",
                  status,
                  backupRelativePath(for: latest),
                  envelope.schema,
                  envelope.sessions.count,
                  sessions.count,
                  totalRRSamples(in: envelope.sessions),
                  totalRRSamples(in: sessions),
                  totalMotionHints(in: envelope.sessions),
                  totalMotionHints(in: sessions),
                  totalMotionShortSamples(in: envelope.sessions),
                  totalMotionShortSamples(in: sessions),
                  totalHRRaw2A37(in: envelope.sessions),
                  totalHRRaw2A37(in: sessions),
                  totalHRAccepted(in: envelope.sessions),
                  totalHRAccepted(in: sessions),
                  totalHRRawGaps(in: envelope.sessions),
                  totalHRRawGaps(in: sessions),
                  totalHRAcceptedGaps(in: envelope.sessions),
                  totalHRAcceptedGaps(in: sessions),
                  data.count,
                  envelope.profile.maxHR,
                  envelope.baseline.sessions,
                  backupDigest ?? "error",
                  currentDigest ?? "error",
                  digestMatches ? 1 : 0)
        } catch {
            AtriaDebugLog("ATRIADBG session_backup_verify status=error error=%@", String(describing: error))
        }
    }

    private func backupContentDigest(sessions: [SavedSession],
                                     baseline: PersonalBaseline,
                                     profile: AthleteProfile,
                                     dailyMetrics: [SavedDailyMetric]?,
                                     dailyRollups: [DailyRollupStoreEntry]?,
                                     confirmedSleeps: [UserConfirmedSleep]?,
                                     confirmedWorkouts: [UserConfirmedWorkout]?) -> String? {
        Self.makeBackupContentDigest(sessions: sessions,
                                     baseline: baseline,
                                     profile: profile,
                                     dailyMetrics: dailyMetrics,
                                     dailyRollups: dailyRollups,
                                     confirmedSleeps: confirmedSleeps,
                                     confirmedWorkouts: confirmedWorkouts)
    }

    nonisolated static func makeBackupContentDigest(sessions: [SavedSession],
                                                    baseline: PersonalBaseline,
                                                    profile: AthleteProfile,
                                                    dailyMetrics: [SavedDailyMetric]?,
                                                    dailyRollups: [DailyRollupStoreEntry]?,
                                                    confirmedSleeps: [UserConfirmedSleep]?,
                                                    confirmedWorkouts: [UserConfirmedWorkout]?) -> String? {
        let schema: Int
        if confirmedWorkouts != nil {
            schema = 3
        } else if dailyMetrics != nil || dailyRollups != nil || confirmedSleeps != nil {
            schema = 2
        } else {
            schema = 1
        }
        let content = SessionBackupContentFingerprint(schema: schema,
                                                      app: "Atria.local",
                                                      sessions: sessions,
                                                      baseline: baseline,
                                                      profile: profile,
                                                      dailyMetrics: dailyMetrics,
                                                      dailyRollups: dailyRollups,
                                                      confirmedSleeps: confirmedSleeps,
                                                      confirmedWorkouts: confirmedWorkouts)
        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .iso8601
        encoder.outputFormatting = [.sortedKeys]
        guard let data = try? encoder.encode(content) else { return nil }
        return SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
    }

    func exportHealthKitFromLaunchIfRequested(arguments: [String] = ProcessInfo.processInfo.arguments) {
        guard arguments.contains("--atria-healthkit-export") else { return }
        let rest = baseline.restingInt ?? 60
        healthKitExporter.export(sessions: sessions,
                                 rest: rest,
                                 maxHR: profile.maxHR,
                                 profile: profile,
                                 restingBaselineSamples: baseline.freshRestingSampleCount(),
                                 confirmedWorkouts: confirmedWorkouts,
                                 confirmedSleeps: confirmedSleeps)
    }

