    /// idempotent and incremental, so repeated taps only write new samples.
    func exportToHealthKit() {
        let rest = baseline.restingInt ?? 60
        healthKitExporter.export(sessions: sessions,
                                 rest: rest,
                                 maxHR: profile.maxHR,
                                 profile: profile,
                                 restingBaselineSamples: baseline.freshRestingSampleCount(),
                                 confirmedWorkouts: confirmedWorkouts,
                                 confirmedSleeps: confirmedSleeps)
    }

    func requestNutritionReadAuthorizationIfEnabled() {
        healthKitExporter.requestNutritionReadAuthorizationIfEnabled()
        refreshNutritionRollupFromHealthIfEnabled(for: Date(), reason: "nutrition_authorization")
    }

    @discardableResult
    func exportRawDataPackage() -> URL? {
        let exportDir = url.deletingLastPathComponent().appendingPathComponent("atria-raw-exports")
        let exportURL = Self.rawExportURL(in: exportDir)
        let rollups = dailyRollupHistory.isEmpty ? dailyRollupStore.rollups(last: 400) : dailyRollupHistory
        return Self.writeRawDataPackageSnapshot(exportDir: exportDir,
                                                exportURL: exportURL,
                                                sessions: sessions,
                                                confirmedSleeps: confirmedSleeps,
                                                confirmedWorkouts: confirmedWorkouts,
                                                rollups: rollups)
    }

    func exportRawDataPackageAsync() async -> URL? {
        let exportDir = url.deletingLastPathComponent().appendingPathComponent("atria-raw-exports")
        let exportURL = Self.rawExportURL(in: exportDir)
        let sessions = self.sessions
        let confirmedSleeps = self.confirmedSleeps
        let confirmedWorkouts = self.confirmedWorkouts
        let rollups = dailyRollupHistory.isEmpty ? dailyRollupStore.rollups(last: 400) : dailyRollupHistory
        return await withCheckedContinuation { continuation in
            DispatchQueue.global(qos: .utility).async {
                let result = Self.writeRawDataPackageSnapshot(exportDir: exportDir,
                                                              exportURL: exportURL,
                                                              sessions: sessions,
                                                              confirmedSleeps: confirmedSleeps,
                                                              confirmedWorkouts: confirmedWorkouts,
                                                              rollups: rollups)
                continuation.resume(returning: result)
            }
        }
    }

    private nonisolated static func rawExportURL(in exportDir: URL, now: Date = Date()) -> URL {
        let formatter = DateFormatter()
        formatter.calendar = Calendar(identifier: .gregorian)
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.timeZone = TimeZone(secondsFromGMT: 0)
        formatter.dateFormat = "yyyyMMdd-HHmmss"
        return exportDir.appendingPathComponent("atria-export-\(formatter.string(from: now)).zip")
    }

    @discardableResult
    private nonisolated static func writeRawDataPackageSnapshot(exportDir: URL,
                                                               exportURL: URL,
                                                               sessions: [SavedSession],
                                                               confirmedSleeps: [UserConfirmedSleep],
                                                               confirmedWorkouts: [UserConfirmedWorkout],
                                                               rollups: [DailyRollupStoreEntry]) -> URL? {
        do {
            try FileManager.default.createDirectory(at: exportDir, withIntermediateDirectories: true)
            let telemetry = try AtriaRawExport.writePackage(to: exportURL,
                                                            sessions: sessions,
                                                            confirmedSleeps: confirmedSleeps,
                                                            confirmedWorkouts: confirmedWorkouts,
                                                            rollups: rollups)
            AtriaGeneratedArtifactRetention.prune(in: exportDir,
                                                   policy: AtriaGeneratedArtifactRetention.rawExports,
                                                   preserving: [exportURL])
            AtriaDebugLog("ATRIADBG raw_export status=ok path=%@ sessions=%d hr_samples=%d rr_samples=%d sleeps=%d workouts=%d rollups=%d schema=%d memory_peak_kb=%d",
                          "Documents/atria-raw-exports/\(exportURL.lastPathComponent)",
                          sessions.count,
                          sessions.reduce(0) { $0 + $1.points.count },
                          sessions.reduce(0) { $0 + ($1.rrPoints?.count ?? 0) },
                          confirmedSleeps.count,
                          confirmedWorkouts.count,
                          rollups.count,
                          AtriaRawExport.schemaVersion,
                          telemetry.peakResidentKilobytes)
            return exportURL
        } catch {
            AtriaDebugLog("ATRIADBG raw_export status=error error=%@", String(describing: error))
            return nil
        }
    }

    @discardableResult
