    private static func backupTimestamp() -> String {
        let formatter = DateFormatter()
        formatter.calendar = Calendar(identifier: .gregorian)
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.timeZone = TimeZone(secondsFromGMT: 0)
        formatter.dateFormat = "yyyyMMdd'T'HHmmss'Z'"
        return formatter.string(from: Date())
    }

    private func trendAnomalies(rollups recent: [DailyRollup]) -> [String] {
        let ordered = recent.sorted { $0.day < $1.day }
        guard let latest = ordered.last else { return [] }
        let rhrs = ordered.compactMap(\.restingHR).filter { $0 > 0 }
        let strains = ordered.map(\.strain).filter { $0 > 0 }
        var out: [String] = []
        if let latestRHR = latest.restingHR,
           isHighOutlier(Double(latestRHR), in: rhrs.map(Double.init)) {
            out.append("RHR elevated")
        }
        if latest.strain > 0,
           isHighOutlier(latest.strain, in: strains) {
            out.append("Strain spike")
        }
        return out
    }

    private func trendConfidence(coverageDays: Int, windowDays: Int) -> String {
        guard coverageDays > 0 else { return "learning" }
        if coverageDays >= trendRequiredCoverageDays(windowDays: windowDays) { return "high" }
        let coverage = Double(coverageDays) / Double(windowDays)
        if coverage >= 0.25 || coverageDays >= 7 { return "partial" }
        return "learning"
    }

    private func trendRequiredCoverageDays(windowDays: Int) -> Int {
        max(1, Int((Double(windowDays) * 0.70).rounded(.up)))
    }

    private func trendDetail(coverageDays: Int,
                             windowDays: Int,
                             hrvState: String,
                             rhrSamples: Int,
                             strainSamples: Int,
                             anomalySource: String,
                             anomalySampleDays: Int,
                             anomalies: [String]) -> String {
        var parts: [String] = []
        if coverageDays == 0 {
            parts.append("no saved history")
        } else if Double(coverageDays) / Double(windowDays) >= 0.70 {
            parts.append("coverage high")
        } else {
            parts.append("coverage sparse")
        }
        parts.append(hrvState == "learning" ? "HRV learning" : "HRV \(hrvState)")
        parts.append(rhrSamples > 0 ? "RHR accepted evidence \(rhrSamples)" : "RHR learning")
        parts.append(strainSamples > 0 ? "strain saved TRIMP \(strainSamples)" : "strain learning")
        parts.append("anomaly source \(anomalySource) days \(anomalySampleDays)")
        if !anomalies.isEmpty {
            parts.append("flags \(anomalies.joined(separator: ","))")
        }
        return parts.joined(separator: " · ")
    }

    private func trendSummaryBlockers(coverageDays: Int,
                                      requiredCoverageDays: Int,
                                      avgRecovery: Int?,
                                      avgHRV: Int?,
                                      hrvState: String) -> String {
        var blockers: [String] = []
        if coverageDays <= 0 {
            blockers.append("no_saved_history")
        } else if coverageDays < requiredCoverageDays {
            blockers.append("coverage_below_70pct")
        }
        if hrvState == "learning" {
            blockers.append("hrv_learning")
        }
        if avgRecovery == nil {
            blockers.append("recovery_points_missing")
        }
        if avgHRV == nil {
            blockers.append("hrv_points_missing")
        }
        return blockers.isEmpty ? "none" : blockers.joined(separator: "+")
    }

    private func trendBlockers(summary: TrendSummary?, hrvValidated _: Int) -> String {
        guard let summary else { return "no_trend_summary" }
        var blockers: [String] = []
        if summary.coverageDays <= 0 {
            blockers.append("no_saved_history")
        } else if summary.confidence != "high" {
            blockers.append("coverage_below_70pct")
        }
        if summary.hrvState == "learning" {
            blockers.append("hrv_learning")
        }
        if summary.avgRecovery == nil {
            blockers.append("recovery_points_missing")
        }
        if summary.avgHRV == nil {
            blockers.append("hrv_points_missing")
        }
        return blockers.isEmpty ? "none" : blockers.joined(separator: "+")
    }

    private func gateFStatus(summary: TrendSummary?, hrvValidated: Int) -> String {
        guard let summary else { return "learning" }
        let hasLocalNonHRVTrend = summary.avgRHR != nil || summary.avgStrain != nil
        let completeCoverage = summary.confidence == "high"
        let completeValidatedMetrics = hrvValidated > 0
            && summary.avgRecovery != nil
            && summary.avgHRV != nil
            && summary.avgRHR != nil
            && summary.avgStrain != nil
        if completeCoverage && completeValidatedMetrics {
            return "ready"
        }
        return hasLocalNonHRVTrend ? "partial" : "learning"
    }

    private func trendAnomalyFlags(_ anomalies: [String]) -> String {
        guard !anomalies.isEmpty else { return "none" }
        return anomalies.map { $0.replacingOccurrences(of: " ", with: "_") }.joined(separator: ",")
    }

    private nonisolated static func trendAnomalyFlagsSnapshot(_ anomalies: [String]) -> String {
        guard !anomalies.isEmpty else { return "none" }
        return anomalies.map { $0.replacingOccurrences(of: " ", with: "_") }.joined(separator: ",")
    }

    private func value(after flag: String, in arguments: [String]) -> String? {
        guard let index = arguments.firstIndex(of: flag) else { return nil }
        let next = arguments.index(after: index)
        guard arguments.indices.contains(next) else { return nil }
        return arguments[next]
    }

    private func doubleValue(after flag: String, in arguments: [String], default defaultValue: Double, range: ClosedRange<Double>) -> Double {
        guard let raw = value(after: flag, in: arguments), let value = Double(raw) else {
            return defaultValue
        }
        return min(max(value, range.lowerBound), range.upperBound)
    }

    private func isHighOutlier(_ value: Double, in values: [Double]) -> Bool {
        guard values.count >= 3 else { return false }
        let mean = values.reduce(0, +) / Double(values.count)
        let variance = values.reduce(0) { $0 + pow($1 - mean, 2) } / Double(values.count)
        let sd = sqrt(variance)
        return sd > 0.1 && value > mean + 2 * sd
    }

    private func averageInt(_ values: [Int]) -> Int? {
        guard !values.isEmpty else { return nil }
        return Int((Double(values.reduce(0, +)) / Double(values.count)).rounded())
    }

    private func averageDouble(_ values: [Double]) -> Double? {
        guard !values.isEmpty else { return nil }
        return values.reduce(0, +) / Double(values.count)
    }

    private nonisolated static func aggregateSleepTimeZoneIdentifier(for cluster: [SavedSession]) -> String? {
        cluster.sorted { $0.start < $1.start }.compactMap(\.eventTimeZoneIdentifier).first
    }

    /// A sleep episode belongs to the civil day on which the wearer wakes.
    /// Physiological cycle ownership is handled separately by
    /// `AtriaPhysiologicalCycle`; Activity remains civil-day visible. This is
    /// intentionally independent of clock hour so a late wake or shift-worker
    /// sleep cannot be assigned back to its bedtime day.
    nonisolated static func aggregateSleepDay(for cluster: [SavedSession],
                                               eventTimeZoneIdentifier: String?,
                                               calendar: Calendar) -> Date {
        guard let end = cluster.last?.end else {
            return calendar.startOfDay(for: Date.distantPast)
        }
        return EventCivilTime.day(containing: end,
                                  eventTimeZoneIdentifier: eventTimeZoneIdentifier,
                                  outputCalendar: calendar)
    }

    nonisolated static func sleepClusters(from sessions: [SavedSession],
                                          maxGap: TimeInterval,
                                          rest: Int,
                                          calendar: Calendar = .current) -> [[SavedSession]] {
        var clusters: [[SavedSession]] = []
        for session in sessions.sorted(by: { $0.start < $1.start }) {
            guard var current = clusters.popLast() else {
                clusters.append([session])
                continue
            }
            let gap = max(0, session.start.timeIntervalSince(current.last?.end ?? session.start))
            if gap <= maxGap, !shouldSplitPostWakeNap(from: current, next: session, rest: rest, calendar: calendar) {
                current.append(session)
                clusters.append(current)
            } else {
                clusters.append(current)
                clusters.append([session])
            }
        }
        return clusters
    }

    private nonisolated static func sleepClusters(
        fromPresorted sessions: [SavedSession],
        maxGap: TimeInterval,
        rest: Int,
        calendar: Calendar,
        sessionHRStats: [UUID: CooperativeBPMStats],
        cooperativeDeadline: AtriaSleepSettlementDeadline
    ) throws -> [[SavedSession]] {
        var clusters: [[SavedSession]] = []
        for (index, session) in sessions.enumerated() {
            if index.isMultiple(of: 8) {
                try cooperativeDeadline.checkpoint()
            }
            guard var current = clusters.popLast() else {
                clusters.append([session])
                continue
            }
            let gap = max(
                0,
                session.start.timeIntervalSince(
                    current.last?.end ?? session.start
                )
            )
            let shouldSplit = try shouldSplitPostWakeNap(
                from: current,
                next: session,
                rest: rest,
                calendar: calendar,
                sessionHRStats: sessionHRStats,
                cooperativeDeadline: cooperativeDeadline
            )
            if gap <= maxGap, !shouldSplit {
                current.append(session)
                clusters.append(current)
            } else {
                clusters.append(current)
                clusters.append([session])
            }
        }
        try cooperativeDeadline.checkpoint()
        return clusters
    }

    /// A short, isolated low-HR prelude must not hide a later independently
    /// substantial sleep merely because the generic broken-sleep cluster
    /// allowance is two hours. This is deliberately asymmetric: a meaningful
    /// first sleep (>= 90 minutes) remains part of a WHOOP-style biphasic
    /// night, while a sub-90-minute prelude separated by a long awake gap is
    /// split only when the trailing fragments already contain at least three
    /// captured hours and no further gap exceeds the ordinary 20-minute sleep
    /// gap credit. A prelude up to two hours may also split when its average HR
    /// is at least eight bpm above the trailing block, distinguishing observed
    /// wake physiology from a meaningful first sleep. The trailing candidate
    /// must still pass every physiology, density, clock-window and review-only
    /// gate below.
    private nonisolated static func splitShortPreludeFromDenseSleepCluster(
        _ cluster: [SavedSession]
    ) -> [[SavedSession]] {
        guard cluster.count >= 3 else { return [cluster] }
        let ordered = cluster.sorted { $0.start < $1.start }
        for splitIndex in 1..<ordered.count {
            let prefix = Array(ordered[..<splitIndex])
            let suffix = Array(ordered[splitIndex...])
            guard let prefixEnd = prefix.last?.end,
                  let suffixStart = suffix.first?.start else { continue }
            let separatingGap = max(0, suffixStart.timeIntervalSince(prefixEnd))
            let prefixCaptured = prefix.reduce(0) { $0 + $1.duration }
            let suffixCaptured = suffix.reduce(0) { $0 + $1.duration }
            let prefixHR = prefix.flatMap(\.bpms)
            let suffixHR = suffix.flatMap(\.bpms)
            let prefixAverage = prefixHR.isEmpty
                ? 0
                : Double(prefixHR.reduce(0, +)) / Double(prefixHR.count)
            let suffixAverage = suffixHR.isEmpty
                ? 0
                : Double(suffixHR.reduce(0, +)) / Double(suffixHR.count)
            let suffixGaps = zip(suffix, suffix.dropFirst()).map { previous, next in
                max(0, next.start.timeIntervalSince(previous.end))
            }
            let shortPrelude = prefixCaptured < 90 * 60
            // The July 26 physical miss had 104 captured prelude minutes, but
            // they were physiologically distinct wakefulness: average HR was
            // more than 8 bpm above the following four-hour low-HR block. This
            // extension remains review-only and bounded below two hours.
            let physiologicallyDistinctPrelude = prefixCaptured < 2 * 60 * 60
                && prefixAverage >= suffixAverage + 8
            guard separatingGap > 90 * 60,
                  shortPrelude || physiologicallyDistinctPrelude,
                  suffixCaptured >= AggregateSleepCandidate.strictMinimumDuration,
                  suffixGaps.allSatisfy({
                      $0 <= AggregateSleepCandidate.briefSleepGapCreditMax
                  }) else {
                continue
            }
            return [prefix, suffix]
        }
        return [ordered]
    }

    private nonisolated static func splitShortPreludeFromDenseSleepCluster(
        _ cluster: [SavedSession],
        sessionHRStats: [UUID: CooperativeBPMStats],
        cooperativeDeadline: AtriaSleepSettlementDeadline
    ) throws -> [[SavedSession]] {
        try cooperativeDeadline.checkpoint()
        guard cluster.count >= 3 else { return [cluster] }
        // The checked caller already supplies a start-sorted cluster.
        let ordered = cluster
        let count = ordered.count
        var prefixDuration = Array(repeating: 0.0, count: count + 1)
        var prefixHRSum = Array(repeating: 0, count: count + 1)
        var prefixHRCount = Array(repeating: 0, count: count + 1)
        for index in 0..<count {
            try cooperativeDeadline.checkpoint()
            guard let stats = sessionHRStats[ordered[index].id] else {
                throw AtriaSleepSettlementAbort.deadlineExceeded
            }
            prefixDuration[index + 1] = prefixDuration[index]
                + ordered[index].duration
            prefixHRSum[index + 1] = prefixHRSum[index] + stats.sum
            prefixHRCount[index + 1] = prefixHRCount[index]
                + stats.values.count
        }
        var suffixMaximumGap = Array(repeating: 0.0, count: count + 1)
        if count > 1 {
            for index in stride(from: count - 2, through: 0, by: -1) {
                try cooperativeDeadline.checkpoint()
                let gap = max(
                    0,
                    ordered[index + 1].start.timeIntervalSince(
                        ordered[index].end
                    )
                )
                suffixMaximumGap[index] = max(
                    gap,
                    suffixMaximumGap[index + 1]
                )
            }
        }
        let totalDuration = prefixDuration[count]
        let totalHRSum = prefixHRSum[count]
        let totalHRCount = prefixHRCount[count]
        for splitIndex in 1..<count {
            try cooperativeDeadline.checkpoint()
            let prefixEnd = ordered[splitIndex - 1].end
            let suffixStart = ordered[splitIndex].start
            let separatingGap = max(
                0,
                suffixStart.timeIntervalSince(prefixEnd)
            )
            let prefixCaptured = prefixDuration[splitIndex]
            let suffixCaptured = totalDuration - prefixCaptured
            let prefixCount = prefixHRCount[splitIndex]
            let suffixCount = totalHRCount - prefixCount
            let prefixAverage = prefixCount == 0
                ? 0
                : Double(prefixHRSum[splitIndex]) / Double(prefixCount)
            let suffixAverage = suffixCount == 0
                ? 0
                : Double(totalHRSum - prefixHRSum[splitIndex])
                    / Double(suffixCount)
            let shortPrelude = prefixCaptured < 90 * 60
            let physiologicallyDistinctPrelude = prefixCaptured < 2 * 60 * 60
                && prefixAverage >= suffixAverage + 8
            guard separatingGap > 90 * 60,
                  shortPrelude || physiologicallyDistinctPrelude,
                  suffixCaptured
                    >= AggregateSleepCandidate.strictMinimumDuration,
                  suffixMaximumGap[splitIndex]
                    <= AggregateSleepCandidate.briefSleepGapCreditMax else {
                continue
            }
            return [
                Array(ordered[..<splitIndex]),
                Array(ordered[splitIndex...])
            ]
        }
        return [ordered]
    }

    private nonisolated static func shouldSplitPostWakeNap(from current: [SavedSession],
                                                           next: SavedSession,
                                                           rest: Int,
                                                           calendar: Calendar) -> Bool {
        guard let start = current.first?.start, let end = current.last?.end else { return false }
        let duration = current.reduce(0) { $0 + $1.duration }
        guard duration >= AggregateSleepCandidate.strictMinimumDuration else { return false }
        let currentEventCalendar = EventCivilTime.eventCalendar(
            timeZoneIdentifier: current.first?.eventTimeZoneIdentifier,
            fallback: calendar
        )
        let startHour = currentEventCalendar.component(.hour, from: start)
        let endHour = currentEventCalendar.component(.hour, from: end)
        let mainOvernight = startHour >= 20 || startHour <= 5 || endHour <= 11
        guard mainOvernight else { return false }
        let gap = max(0, next.start.timeIntervalSince(end))
        // A short wake/rollover or reconnect after an incomplete first sleep is
        // continuation evidence, not a new nap. This specifically preserves a
        // 03:50–08:34 sleep resumed shortly afterward through 11:38. Once a
        // full main sleep has already been captured, the existing morning-rest
        // rule may split a later distinct nap (covered by the 28-minute fixture).
        let likelyResumedMainSleep = gap <= AggregateSleepCandidate.briefSleepGapCreditMax
            || (duration < AggregateSleepCandidate.minimumAutoConfirmMainSleepDuration
                && gap <= 60 * 60)
        guard !likelyResumedMainSleep else { return false }
        // A completed main-sleep-sized block must not disappear because a
        // tiny low-HR journal arrives much later in the morning. The July 28
        // physical record contained 3h38 of dense sleep, then a six-minute
        // fragment after a 95-minute wake gap; clustering that fragment into
        // the night made the otherwise valid review candidate fail its
        // continuity gate. Split only sub-nap-length tails beyond the same
        // 90-minute continuity ceiling used by the degraded-review gate.
        // A meaningful resumed sleep remains eligible for clustering/review.
        if gap > 90 * 60,
           next.duration < AggregateSleepCandidate.napMinimumDuration {
            return true
        }
        let nextEventCalendar = EventCivilTime.eventCalendar(timeZoneIdentifier: next.eventTimeZoneIdentifier,
                                                             fallback: calendar)
        let nextStartHour = nextEventCalendar.component(.hour, from: next.start)
        let nextEndHour = nextEventCalendar.component(.hour, from: next.end)
        let postWakeWindow = nextStartHour >= 8 && nextEndHour <= 20
        let shortLowHRRest = next.duration >= AggregateSleepCandidate.napMinimumDuration
            && next.duration <= AggregateSleepCandidate.napMaximumSpan
            && next.avg <= rest + 12
            && next.peak <= rest + 55
        return postWakeWindow && shortLowHRRest
    }

    private nonisolated static func shouldSplitPostWakeNap(
        from current: [SavedSession],
        next: SavedSession,
        rest: Int,
        calendar: Calendar,
        sessionHRStats: [UUID: CooperativeBPMStats],
        cooperativeDeadline: AtriaSleepSettlementDeadline
    ) throws -> Bool {
        try cooperativeDeadline.checkpoint()
        guard let start = current.first?.start,
              let end = current.last?.end else { return false }
        var duration = 0.0
        for session in current {
            try cooperativeDeadline.checkpoint()
            duration += session.duration
        }
        guard duration
                >= AggregateSleepCandidate.strictMinimumDuration else {
            return false
        }
        let currentEventCalendar = EventCivilTime.eventCalendar(
            timeZoneIdentifier: current.first?.eventTimeZoneIdentifier,
            fallback: calendar
        )
        let startHour = currentEventCalendar.component(.hour, from: start)
        let endHour = currentEventCalendar.component(.hour, from: end)
        let mainOvernight = startHour >= 20 || startHour <= 5 || endHour <= 11
        guard mainOvernight else { return false }
        let gap = max(0, next.start.timeIntervalSince(end))
        let likelyResumedMainSleep = gap
            <= AggregateSleepCandidate.briefSleepGapCreditMax
            || (duration
                    < AggregateSleepCandidate.minimumAutoConfirmMainSleepDuration
                && gap <= 60 * 60)
        guard !likelyResumedMainSleep else { return false }
        if gap > 90 * 60,
           next.duration < AggregateSleepCandidate.napMinimumDuration {
            return true
        }
        let nextEventCalendar = EventCivilTime.eventCalendar(
            timeZoneIdentifier: next.eventTimeZoneIdentifier,
            fallback: calendar
        )
        let nextStartHour = nextEventCalendar.component(.hour, from: next.start)
        let nextEndHour = nextEventCalendar.component(.hour, from: next.end)
        let postWakeWindow = nextStartHour >= 8 && nextEndHour <= 20
        guard let stats = sessionHRStats[next.id] else {
            throw AtriaSleepSettlementAbort.deadlineExceeded
        }
        let shortLowHRRest = next.duration
                >= AggregateSleepCandidate.napMinimumDuration
            && next.duration <= AggregateSleepCandidate.napMaximumSpan
            && stats.roundedAverage <= rest + 12
            && stats.peak <= rest + 55
        return postWakeWindow && shortLowHRRest
    }

    private nonisolated static func workoutClusters(from sessions: [SavedSession], maxGap: TimeInterval) -> [[SavedSession]] {
        var clusters: [[SavedSession]] = []
        for session in sessions.sorted(
            by: AtriaWorkoutAggregateSessionFlightIdentity.canonicalOrder
        ) {
            guard var current = clusters.popLast() else {
                clusters.append([session])
                continue
            }
            let gap = max(0, session.start.timeIntervalSince(current.last?.end ?? session.start))
            if gap <= maxGap {
                current.append(session)
                clusters.append(current)
            } else {
                clusters.append(current)
                clusters.append([session])
            }
        }
        return clusters
    }

    private nonisolated static func percentileHR(_ percentile: Double, values: [Int]) -> Int {
        guard !values.isEmpty else { return 0 }
        return percentileHR(percentile, presorted: values.sorted())
    }

    private nonisolated static func percentileHR(_ percentile: Double, presorted sorted: [Int]) -> Int {
        guard !sorted.isEmpty else { return 0 }
        let clamped = min(max(percentile, 0), 1)
        let index = min(sorted.count - 1, max(0, Int((Double(sorted.count - 1) * clamped).rounded(.down))))
        return sorted[index]
    }

    /// Bottom-up stable merge sort with checkpoints inside every full-row
    /// pass. Checked compact settlement uses this instead of an uninterruptible
    /// standard-library sort for inputs that may reach the 80k total cap.
    private nonisolated static func cooperativeStableSort<Element>(
        _ values: inout [Element],
        cooperativeDeadline: AtriaSleepSettlementDeadline?,
        areInIncreasingOrder: (Element, Element) -> Bool
    ) throws {
        guard values.count > 1 else { return }
        // Preserve checkpoints only for the bounded compact-settlement path.
        // Unchecked historical projections should use Swift's optimized sort
        // instead of allocating two arrays for a Swift-level merge loop.
        guard cooperativeDeadline != nil else {
            values.sort(by: areInIncreasingOrder)
            return
        }
        var source = values
        var destination = values
        var width = 1
        while width < source.count {
            try cooperativeDeadline?.checkpoint()
            var lower = 0
            while lower < source.count {
                let middle = min(lower + width, source.count)
                let upper = min(lower + width + width, source.count)
                var left = lower
                var right = middle
                var output = lower
                while output < upper {
                    if output.isMultiple(of: 256) {
                        try cooperativeDeadline?.checkpoint()
                    }
                    if left < middle,
                       (right >= upper
                        || !areInIncreasingOrder(source[right], source[left])) {
                        destination[output] = source[left]
                        left += 1
                    } else {
                        destination[output] = source[right]
                        right += 1
                    }
                    output += 1
                }
                lower = upper
            }
            swap(&source, &destination)
            width = width > source.count / 2 ? source.count : width * 2
        }
        values = source
        try cooperativeDeadline?.checkpoint()
    }

    private nonisolated static func standardDeviation(_ values: [Double]) -> Double {
        guard values.count >= 2 else { return 0 }
        let mean = values.reduce(0, +) / Double(values.count)
        let variance = values.reduce(0) { $0 + pow($1 - mean, 2) } / Double(values.count)
        return sqrt(variance)
    }

    private nonisolated static func cooperativeStandardDeviation(
        _ values: [Int],
        cooperativeDeadline: AtriaSleepSettlementDeadline?
    ) throws -> Double {
        guard values.count >= 2 else { return 0 }
        var sum = 0.0
        for (index, value) in values.enumerated() {
            if index.isMultiple(of: 256) {
                try cooperativeDeadline?.checkpoint()
            }
            sum += Double(value)
        }
        let mean = sum / Double(values.count)
        var squaredDeviationSum = 0.0
        for (index, value) in values.enumerated() {
            if index.isMultiple(of: 256) {
                try cooperativeDeadline?.checkpoint()
            }
            squaredDeviationSum += pow(Double(value) - mean, 2)
        }
        try cooperativeDeadline?.checkpoint()
        return sqrt(squaredDeviationSum / Double(values.count))
    }

    private func formatInt(_ value: Int?) -> String {
        value.map(String.init) ?? "learning"
    }

    private nonisolated static func formatDouble(_ value: Double?) -> String {
        value.map { String(format: "%.1f", $0) } ?? "learning"
    }

    private nonisolated static func formatIntSnapshot(_ value: Int?) -> String {
        value.map(String.init) ?? "learning"
    }

    private nonisolated static func formatDoubleSnapshot(_ value: Double?) -> String {
        value.map { String(format: "%.1f", $0) } ?? "learning"
    }

    private func loadPersistedSessionsDeferred() {
        let sourceURL = url
        let coldURL = coldSessionsURL
        let recoveredCheckpointURL = recoveredCurrentCheckpointURL
        let currentBaseline = baseline
        let currentProfile = profile
        let currentConfirmedSleeps = cachedConfirmedSleeps
        // Launch time-to-content fix (2026-07-05): this decode feeds the first
        // real render of History/Vitals/Journal now that the full-screen
        // "Preparing…" skeleton gate is gone, so it can no longer sit behind
        // other .utility-QoS background work. .userInitiated keeps it ahead of
        // that without touching the main actor before the decode is ready to
        // hop back.
        Task.detached(priority: .userInitiated) { [sourceURL, coldURL, recoveredCheckpointURL, currentBaseline, currentProfile, currentConfirmedSleeps] in
            let startedAt = CFAbsoluteTimeGetCurrent()
            let loadNow = Date()
            let recoveredCheckpoint = Self.readRecoveredCurrentCheckpoint(
                from: recoveredCheckpointURL,
                now: loadNow
            )
            var decoded: [SavedSession] = []
            var sourcePreservationFence = false
            var hotSourceNeedsBoundedRewrite = false
            let fullStore = AtriaFullFidelityColdSessionStore(
                rootURL: AtriaFullFidelityColdSessionStore.rootURL(nextTo: coldURL)
            )
            let manifestExistedAtLaunch = FileManager.default.fileExists(
                atPath: fullStore.manifestURL.path
            )
            do {
                // Both normal launch and first legacy adoption use the same
                // object-framed reader. It writes every source session to an
                // immutable verified chunk before publishing a manifest, while
                // retaining only the bounded newest resident window. The legacy
                // cold source participates only before the first manifest; a
                // stale monolith can never override a later generation.
                let adoption = try fullStore.adoptStreamingSources(
                    hotURL: FileManager.default.fileExists(atPath: sourceURL.path)
                        ? sourceURL
                        : nil,
                    legacyColdURL: !manifestExistedAtLaunch
                            && FileManager.default.fileExists(atPath: coldURL.path)
                        ? coldURL
                        : nil,
                    policy: .init(
                        earliestResidentStart: Self.residentSessionCutoff(now: loadNow),
                        maximumResidentSessionCount: Self.maximumResidentSessionCount,
                        maximumResidentDecodedBytes: Self.maximumResidentColdDecodedBytes
                    ),
                    generatedAt: loadNow
                )
                decoded = adoption.residentSessions
                hotSourceNeedsBoundedRewrite = adoption.residentWasTruncated

                let remainingCount = Self.maximumResidentSessionCount - decoded.count
                let remainingBytes = Self.maximumResidentColdDecodedBytes
                    > adoption.residentDecodedByteCount
                    ? Self.maximumResidentColdDecodedBytes - adoption.residentDecodedByteCount
                    : 0
                var manifestLoad: AtriaFullFidelityColdSessionStore.BoundedAppendResult?
                if remainingCount > 0, remainingBytes > 0 {
                    let coldLoad = try fullStore.appendBoundedFullFidelitySessions(
                        to: &decoded,
                        excludingIDs: Set(decoded.map(\.id)),
                        policy: .init(
                            earliestStart: Self.residentSessionCutoff(now: loadNow),
                            maximumSessionCount: remainingCount,
                            maximumDecodedBytes: remainingBytes
                        )
                    )
                    manifestLoad = coldLoad
                }
                decoded = Self.boundedResidentSessions(decoded, now: loadNow)
                AtriaDebugLog("ATRIADBG session_store_load streaming status=%@ hot_sessions=%d hot_bytes=%llu legacy_sessions=%d legacy_bytes=%llu archived_sessions=%d resident_sessions=%d resident_bytes=%llu largest_transient_payload_bytes=%llu truncated=%d manifest_appended=%d",
                              adoption.publicationStatus.rawValue,
                              adoption.hotSource?.sessionCount ?? 0,
                              adoption.hotSource?.byteCount ?? 0,
                              adoption.legacyColdSource?.sessionCount ?? 0,
                              adoption.legacyColdSource?.byteCount ?? 0,
                              adoption.archivedSessionCount,
                              decoded.count,
                              adoption.residentDecodedByteCount,
                              adoption.largestTransientPayloadBytes,
                              adoption.residentWasTruncated ? 1 : 0,
                              manifestLoad?.appendedSessionCount ?? 0)
            } catch {
                // The raw source remains byte-for-byte intact and any old
                // manifest remains authoritative. Recover what can be verified
                // from that generation, but fence every future sessions.json
                // write so malformed/truncated input cannot be replaced by a
                // partial resident snapshot.
                sourcePreservationFence = true
                decoded = []
                if manifestExistedAtLaunch {
                    _ = try? fullStore.appendBoundedFullFidelitySessions(
                        to: &decoded,
                        excludingIDs: [],
                        policy: .init(
                            earliestStart: Self.residentSessionCutoff(now: loadNow),
                            maximumSessionCount: Self.maximumResidentSessionCount,
                            maximumDecodedBytes: Self.maximumResidentColdDecodedBytes
                        )
                    )
                }
                AtriaDebugLog("ATRIADBG session_store_load streaming status=failed_source_preserved resident_sessions=%d error=%@",
                              decoded.count,
                              error.localizedDescription)
            }

            // Saved fragments are durable sensor evidence, even when they are
            // short. A previous launch migration deleted every sub-five-minute
            // "Auto-saved" fragment without proving that another session held
            // the same HR/RR samples. That made unique recorded evidence vanish
            // from sessions.json merely by launching a new build. Keep every
            // decoded session here; presentation/analytics already canonicalize
            // overlaps without mutating the source-of-truth store.
            let loadedSessions = decoded
            let preparation = Self.prepareDeferredLoad(decoded: loadedSessions,
                                                       baseline: currentBaseline,
                                                       profile: currentProfile,
                                                       confirmedSleeps: currentConfirmedSleeps,
                                                       sessionFileURL: sourceURL,
                                                       prunedShortLongWearFragments: 0)
            let elapsedMS = Int(((CFAbsoluteTimeGetCurrent() - startedAt) * 1000).rounded())
            let shouldPreserveSource = sourcePreservationFence
            let shouldRewriteHotSource = hotSourceNeedsBoundedRewrite
            let reusableRecoveredCheckpoint = recoveredCheckpoint.flatMap {
                Self.recoveredCurrentCheckpointSourceIsReusable(
                    previous: $0.sourceFingerprint,
                    current: HistoricalArchive.consumerSourceFingerprint()
                ) ? $0 : nil
            }
            let recoveredProjectionCutoff =
                Self.automaticRecoveredDataProjectionCutoff(
                    now: loadNow,
                    confirmedSleeps: currentConfirmedSleeps,
                    calendar: .current
                )
            let recoveredScannerAuthorityRestored =
                reusableRecoveredCheckpoint.map {
                    HistoricalArchive
                        .restoreAutomaticRecoveredDataCacheAuthority(
                            $0.automaticCacheAuthority,
                            since: recoveredProjectionCutoff
                        )
                } ?? false
            await MainActor.run {
                self.sessionSourcePreservationFenceActive = shouldPreserveSource
                if let reusableRecoveredCheckpoint {
                    self.applyRecoveredCurrentCheckpoint(
                        reusableRecoveredCheckpoint,
                        scannerAuthorityRestored:
                            recoveredScannerAuthorityRestored
                    )
                }
                self.finishDeferredLoad(
                    loadedSessions,
                    preparation: preparation,
                    elapsedMS: elapsedMS,
                    rewriteOversizedHotSource: shouldRewriteHotSource
                )
            }
        }
    }

    private struct ArchivedSessionQueryResult: @unchecked Sendable {
        let sessions: [SavedSession]
    }

    /// Explicit bounded access for an older detail/export flow. Returned values
    /// are not inserted into the live `sessions` array, so repeated archive
    /// queries cannot turn lifetime history back into resident state.
    func archivedSessions(overlapping interval: DateInterval,
                          maximumSessionCount: Int = 100,
                          maximumDecodedBytes: UInt64 = 32 * 1_024 * 1_024) async -> [SavedSession] {
        let coldURL = coldSessionsURL
        let result = await Task.detached(priority: .utility) {
            let store = AtriaFullFidelityColdSessionStore(
                rootURL: AtriaFullFidelityColdSessionStore.rootURL(nextTo: coldURL)
            )
            let loaded = (try? store.sessions(overlapping: interval,
                                              maximumSessionCount: maximumSessionCount,
                                              maximumDecodedBytes: maximumDecodedBytes)) ?? []
            return ArchivedSessionQueryResult(sessions: loaded)
        }.value
        return result.sessions
    }

    func archivedCompactSessionFacts(before upperBound: Date,
                                     maximumFactCount: Int = 100,
                                     maximumDecodedBytes: UInt64 = 8 * 1_024 * 1_024) async
        -> [AtriaColdSessionFact] {
        let coldURL = coldSessionsURL
        return await Task.detached(priority: .utility) {
            let root = coldURL.deletingLastPathComponent()
                .appendingPathComponent(AtriaColdSessionStore.directoryName, isDirectory: true)
            return (try? AtriaColdSessionStore(rootURL: root).factsPage(
                before: upperBound,
                maximumFactCount: maximumFactCount,
                maximumDecodedBytes: maximumDecodedBytes
            )) ?? []
        }.value
    }

    func waitForDeferredSessionLoadIfNeeded(timeoutSeconds: TimeInterval = 8) async {
        guard !hasCompletedDeferredSessionLoad else { return }
        let startedAt = Date()
        while !hasCompletedDeferredSessionLoad && Date().timeIntervalSince(startedAt) < timeoutSeconds {
            try? await Task.sleep(nanoseconds: 100_000_000)
        }
        AtriaDebugLog("ATRIADBG session_store_load_wait status=%@ elapsed_ms=%d sessions=%d",
              hasCompletedDeferredSessionLoad ? "ready" : "timeout",
              Int(Date().timeIntervalSince(startedAt) * 1000),
              sessions.count)
    }

    func queueSessionBackupAfterDeferredLoadFromLaunchIfRequested(arguments: [String] = ProcessInfo.processInfo.arguments) {
        let wantsWrite = arguments.contains("--atria-backup-sessions")
            || arguments.contains("--atria-write-session-backup")
        let wantsVerify = arguments.contains("--atria-verify-backup")
            || arguments.contains("--atria-verify-session-backup")
        guard wantsWrite || wantsVerify else { return }

        if hasCompletedDeferredSessionLoad {
            AtriaDebugLog("ATRIADBG session_backup_deferred status=ready write=%d verify=%d sessions=%d",
                          wantsWrite ? 1 : 0,
                          wantsVerify ? 1 : 0,
                          sessions.count)
            writeSessionBackupFromLaunchIfRequested(arguments: arguments)
            verifyLatestSessionBackupFromLaunchIfRequested(arguments: arguments)
        } else {
            pendingDeferredSessionBackupArguments = arguments
            AtriaDebugLog("ATRIADBG session_backup_deferred status=queued write=%d verify=%d",
                          wantsWrite ? 1 : 0,
                          wantsVerify ? 1 : 0)
        }
    }

    private func runQueuedSessionBackupAfterDeferredLoadIfNeeded() {
        guard let arguments = pendingDeferredSessionBackupArguments else { return }
        pendingDeferredSessionBackupArguments = nil
        AtriaDebugLog("ATRIADBG session_backup_deferred status=running sessions=%d",
                      sessions.count)
        writeSessionBackupFromLaunchIfRequested(arguments: arguments)
        verifyLatestSessionBackupFromLaunchIfRequested(arguments: arguments)
    }

    // Launch time-to-content fix (2026-07-05): this used to do ALL of the work
    // below (rollup refresh, sleep backfill/auto-confirm, wake-boundary
    // evaluation, trend/load caches) synchronously on the main actor in one
    // shot right as the decode landed -- a single large main-actor stall plus
    // a giant first re-render on big stores. `sessions = merged` (the field the
    // rest of the app actually reads for real content) now lands on its own,
    // immediately, so the UI picks up real data on the very next frame; the
    // heavier housekeeping below is pushed to a follow-up main-actor tick so it
    // never shares a runloop turn with the decode landing.
    private func finishDeferredLoad(_ decoded: [SavedSession],
                                    preparation: DeferredLoadPreparation,
                                    elapsedMS: Int,
                                    rewriteOversizedHotSource: Bool = false) {
        let merged = Self.mergedSessions(primary: sessions, secondary: decoded)
        let finalPreparation = merged.count == decoded.count
            ? preparation
            : Self.prepareDeferredLoad(decoded: merged,
                                       baseline: baseline,
                                       profile: profile,
                                       confirmedSleeps: cachedConfirmedSleeps,
                                       sessionFileURL: url,
                                       prunedShortLongWearFragments: preparation.prunedShortLongWearFragments)
        // A launch-time history projection may already be deriving from the
        // intentionally empty pre-load session cache. Exact-history priority
        // can defer the replacement projection without incrementing its
        // generation, allowing that stale empty result to publish after the
        // real sessions land and overwrite valid strain/Recovery rollups.
        // Invalidate both stages before exposing the loaded session authority;
        // the normal follow-up persistence below then rebuilds from `merged`.
        historySnapshotRevision &+= 1
        dailyRollupPreparationRevision &+= 1
        sessions = merged
        setLatestReferenceValidatedHRVSource(finalPreparation.latestReferenceValidatedHRVSource)
        setLatestLocalRMSSDSource(finalPreparation.latestLocalRMSSDSource)
        setCachedCanonicalSessions(Self.makeCanonicalSessions(
            from: finalPreparation.canonicalSessions + cachedRecoveredHeartRateSessions
        ))
        cachedHomeSavedAggregate = nil
        cachedCurrentCollectionStatus = nil
        cachedHomeDashboardDiagnostics = nil
        // Set the widget fence before exposing `hasLoadedSavedSessions`. The
        // sessions-landed dashboard revision below is intentionally early for UI
        // responsiveness and must not turn into a stale grey widget write.
        deferredLaunchCardSettlementPending = true
        self.hasCompletedDeferredSessionLoad = true
        requestRecoveredDataRecomputation(reason: "deferred_session_load")
        if merged.count != decoded.count || rewriteOversizedHotSource {
            // The deferred load is intentionally a bounded snapshot. Mark only
            // the concrete resident union dirty so an overlapping live session
            // cannot turn this into a destructive full-cold rewrite. A source
            // truncated by the decoded-byte ceiling is also rewritten once,
            // but only after streaming adoption durably archived and verified
            // every omitted session in the manifest.
            markSessionPersistenceDirty(affectedSessions: merged)
        }
        // A live update may have arrived while the streaming reader still held
        // the pre-load persistence fence. Its dirty revision remains pending;
        // schedule it only after the complete source has verified successfully.
        if sessionPersistenceRevision > lastCompletedSessionPersistenceRevision {
            scheduleSessionFilePersist(reason: "deferred_load_merge", delay: 0.10)
        }
        if finalPreparation.didRebuildBaseline {
            baseline = finalPreparation.baseline
        }
        publishDashboardRevision()
        AtriaDebugLog("ATRIADBG session_store_finish_checkpoint stage=sessions_landed sessions=%d elapsed_ms=%d",
                      sessions.count,
                      elapsedMS)
        if rewriteOversizedHotSource {
            AtriaDebugLog("ATRIADBG session_store_retention status=bounded_hot_rewrite_queued resident_sessions=%d decoded_cap_bytes=%llu source_preserved=1",
                          merged.count,
                          Self.maximumResidentColdDecodedBytes)
        }

        Task { @MainActor [weak self] in
            // Yield at least one runloop turn so the `sessions = merged` update
            // above gets its own commit before this heavier follow-up work runs.
            await Task.yield()
            await self?.continueDeferredLoadFollowUp(merged: merged,
                                                     finalPreparation: finalPreparation,
                                                     elapsedMS: elapsedMS)
        }
    }

    private func continueDeferredLoadFollowUp(merged: [SavedSession],
                                              finalPreparation: DeferredLoadPreparation,
                                              elapsedMS: Int) async {
        runQueuedSessionBackupAfterDeferredLoadIfNeeded()
        refreshBackupStatusCacheDeferred(reason: "deferred_session_load")
        // BGTask execution is opportunistic. Evaluate the same once-per-day,
        // shadow-only retention queue after launch content has landed so the
        // 30-day / 512-MiB policy is not dependent on iOS granting background
        // maintenance time.
        reserveArchiveCompactionForSafeBackground()

        reapplyConfirmedWorkoutStrainCalibrationIfNeeded(sourceSessions: merged)

        let didRequalifyConfirmedSleepHRV = await requalifyPersistedConfirmedSleepHRVFromSessionsIfNeeded(
            merged,
            reason: "deferred_session_load"
        ).changed

        if finalPreparation.didRebuildBaseline && !didRequalifyConfirmedSleepHRV {
            let preparedBaseline = finalPreparation.baseline
            Task.detached(priority: .utility) {
                preparedBaseline.save()
            }
        }
        AtriaDebugLog("ATRIADBG session_store_finish_checkpoint stage=before_rollup_refresh sessions=%d elapsed_ms=%d",
                      sessions.count,
                      elapsedMS)
        if !dailyMetricHistory.isEmpty {
            AtriaDebugLog("ATRIADBG session_store_finish_checkpoint stage=pre_snapshot_rollup_persist sessions=%d metrics=%d elapsed_ms=%d",
                          sessions.count,
                          dailyMetricHistory.count,
                          elapsedMS)
            persistDailyRollups(from: dailyMetricHistory)
        }
        // Stages committed by this launch pass must be visible in THIS
        // launch: the narrow republish runs after the durable save, before
        // card settlement below re-reads the same post-commit cache.
        _ = await backfillConfirmedSleepStagesFromSessions(
            reason: "deferred_session_load",
            deferDerivedPublication: true,
            narrowPublicationAfterCommit: true
        )
        resumeDeferredLaunchCardSettlementIfNeeded(reason: "deferred_session_load")
        AtriaDebugLog("ATRIADBG session_store_finish_checkpoint stage=card_settlement_requested sessions=%d elapsed_ms=%d",
                      sessions.count,
                      elapsedMS)
        refreshOverviewTrendPointsCache(deferred: true)
        refreshTrainingLoadSummaryCache(deferred: true)
        refreshTodayHRZoneMinutesCache(deferred: true)
        // Handoff-8 CP1: warm the per-chunk HR sidecar index off-main so a
        // completed Activity day's exact lookup meets a valid index instead
        // of paying a raw-archive scan. One-time per sealed chunk; cooperative
        // and utility-priority; never touches the raw archive itself.
        Task.detached(priority: .utility) {
            HistoricalArchive.backfillHeartRateSidecars()
        }
        // Handoff-8 CP3: relaunch restores the identical relative-skin result
        // from the persisted compact night summaries. Read-only — the store
        // is only rewritten by the recovered pipeline's gated producer.
        let relativeSkinReseedSleeps = confirmedSleeps.map(
            AtriaRelativeSkinSleepWindow.init(confirmedSleep:)
        )
        Task.detached(priority: .utility) {
            let store = AtriaRelativeSkinNightStore.production
            let plan = AtriaRelativeSkinProducer.plan(
                sleeps: relativeSkinReseedSleeps,
                rows: [],
                stored: store.load(),
                environment: .init(
                    snapshotChannelComplete: false,
                    drainedThroughUnix: 0,
                    now: Date()
                )
            )
            await MainActor.run {
                AtriaRelativeSkinSignalCenter.shared.install(plan.uiSummary)
            }
        }
        // Launch is most users' first morning foreground. Use the same off-main
        // immutable proposal path as app resume so the first interactive frame
        // never decodes or aggregates the growing live journal.
        autoConfirmSleepOnForegroundIfUseful(reason: "deferred_session_load")
        if ProcessInfo.processInfo.arguments.contains("--atria-compact-archive") {
            compactHistoricalArchiveIfUseful(reason: "debug_launch_arg")
        }
        #if DEBUG
        // Handoff-8 CP1 attribution probe: run the exact Activity-day HR
        // window read off-main and persist its diagnostic receipt, without
        // needing UI navigation. Value is the window's start unix; the window
        // is that instant plus 24 hours. Diagnostic metadata only.
        if let probeIndex = ProcessInfo.processInfo.arguments.firstIndex(
            of: "--atria-debug-hr-window-probe"
        ) {
            let valueIndex = ProcessInfo.processInfo.arguments.index(after: probeIndex)
            if ProcessInfo.processInfo.arguments.indices.contains(valueIndex),
               let startUnix = Double(
                ProcessInfo.processInfo.arguments[valueIndex]
               ) {
                Task.detached(priority: .userInitiated) {
                    // Handoff-9 CP1 acceptance: one cold read (receipt ring)
                    // then one warm repeat of the identical window, so the
                    // in-memory cache path gets a measured elapsed too. The
                    // priority matches the production Activity navigation
                    // (a MainActor task), and the short settle mirrors a user
                    // reaching the day view a few seconds after cold launch
                    // instead of racing the launch itself.
                    try? await Task.sleep(for: .seconds(8))
                    let coldStartedAt = Date()
                    let cold = HistoricalArchive.metricHeartRatePoints(
                        start: Date(timeIntervalSince1970: startUnix),
                        end: Date(timeIntervalSince1970: startUnix + 24 * 3_600),
                        maximumPoints: 100_000
                    )
                    let coldMs = Int(Date().timeIntervalSince(coldStartedAt) * 1_000)
                    let warmStartedAt = Date()
                    let warm = HistoricalArchive.metricHeartRatePoints(
                        start: Date(timeIntervalSince1970: startUnix),
                        end: Date(timeIntervalSince1970: startUnix + 24 * 3_600),
                        maximumPoints: 100_000
                    )
                    let warmMs = Int(Date().timeIntervalSince(warmStartedAt) * 1_000)
                    UserDefaults.standard.set(
                        "cold_ms=\(coldMs) warm_ms=\(warmMs) "
                            + "cold_points=\(cold?.points.count ?? -1) "
                            + "warm_points=\(warm?.points.count ?? -1)",
                        forKey: "atria.debug.hrWindowProbeSummary.v1"
                    )
                }
            }
        }
        // Handoff-9 CP3: read-only notification acceptance probe. Dumps the
        // pending user-facing requests, per-category enable states, and the
        // authorization status to one defaults key for the physical audit.
        // Never schedules, cancels, or mutates anything.
        if ProcessInfo.processInfo.arguments.contains(
            "--atria-debug-dump-pending-notifications"
        ) {
            let settings = AtriaNotificationSettings.load()
            let categoryStates = AtriaNotificationCategory.allCases.map {
                "\($0.rawValue)=\(settings[keyPath: $0.settingKeyPath] ? 1 : 0)"
            }.joined(separator: " ")
            let center = UNUserNotificationCenter.current()
            center.getNotificationSettings { authorization in
                center.getPendingNotificationRequests { requests in
                    let pending = requests.map { request in
                        "\(request.identifier)|\(request.content.title)"
                    }.joined(separator: "\n")
                    let dump = """
                    authorization=\(authorization.authorizationStatus.rawValue)
                    master=\(settings.allowNotifications ? 1 : 0)
                    categories=\(AtriaNotificationCategory.allCases.count) \(categoryStates)
                    pendingCount=\(requests.count)
                    \(pending)
                    """
                    UserDefaults.standard.set(
                        dump,
                        forKey: "atria.debug.notificationAcceptanceDump.v1"
                    )
                }
            }
        }
        // Handoff-11 physical acceptance fixture: run the REAL degraded
        // preparation against a real, empty, isolated compact store — whose
        // latest-night read fails `.missingShard` exactly as a device with
        // unarrived motion shards — over a dense synthetic HR/RR night, then
        // persist through the real degraded persistence path. Uses the
        // already-persisted strap identity when one exists and NEVER writes
        // the saved-link key; on a strapless simulator it falls back to the
        // store-level save so the durable/UI reconciliation stays the real
        // production path. The candidate is review-only by construction:
        // no confirmation, Recovery or canonical mutation can result.
        if ProcessInfo.processInfo.arguments.contains(
            "--atria-debug-degraded-sleep-review-fixture"
        ) {
            let fixtureRest = 60
            Task.detached(priority: .utility) { [weak self] in
                let directory = FileManager.default.temporaryDirectory
                    .appendingPathComponent(
                        "atria-degraded-review-fixture-\(UUID().uuidString)"
                    )
                defer { try? FileManager.default.removeItem(at: directory) }
                let compactStore = AtriaWhoop4MotionTickCompactStore(
                    directoryURL: directory
                )
                let now = Date()
                let end = now.addingTimeInterval(-45 * 60)
                let duration: TimeInterval = 6 * 60 * 60
                let start = end.addingTimeInterval(-duration)
                var night = SavedSession(
                    id: UUID(),
                    start: start,
                    end: end,
                    label: "Degraded review fixture night",
                    points: stride(from: 0.0, through: duration, by: 1.0)
                        .map {
                            .init(t: $0, bpm: 52 + ((Int($0) / 300) % 3))
                        }
                )
                night.rrPoints = stride(
                    from: 0.0,
                    through: duration,
                    by: 1.0
                ).map {
                    .init(
                        t: $0,
                        ms: 1_020,
                        source: .standardHeartRateMeasurement2A37
                    )
                }
                let persistedStrap = AtriaWhoop4MotionTickDailyStore
                    .persistedStrapIdentifiers()
                    .first
                let strapIdentifier = persistedStrap ?? UUID().uuidString
                let preparation = SessionStore
                    .makeCompactLatestNightSettlementPreparation(
                        fingerprint: .init(
                            canonicalSessionsRevision: 1,
                            confirmedSleepsRevision: 1,
                            restingHR: fixtureRest,
                            baselineRestingIsTrusted: true,
                            baselineRestingIsNearTrusted: true,
                            maxHR: 190
                        ),
                        canonicalSessions: [night],
                        now: now,
                        rest: fixtureRest,
                        maxHR: 190,
                        learnedWindow: nil,
                        strapIdentifier: strapIdentifier,
                        thermalState: .nominal,
                        compactStore: compactStore,
                        degradedReviewContext: .init(
                            snapshot: .empty,
                            confirmedSleeps: [],
                            dismissedCandidates: [],
                            calendar: .current
                        )
                    )
                await MainActor.run { [weak self] in
                    guard let self else { return }
                    switch preparation {
                    case .reviewOnly(let review):
                        if persistedStrap != nil {
                            self.persistCompactLatestNightDegradedReview(
                                review,
                                rest: fixtureRest,
                                source: "degraded_review_fixture"
                            )
                        } else {
                            let outcome = AtriaPendingSleepReviewStore
                                .saveDegradedReview(
                                    review.night,
                                    motionBlocker:
                                        review.motionBlocker.rawValue,
                                    evidenceFingerprint:
                                        review.evidenceFingerprint,
                                    sourceStrapIdentifier: nil
                                )
                            SessionStore.recordDegradedSleepReviewDiagnostic(
                                preparedAt: review.preparedAt,
                                motionBlocker: review.motionBlocker.rawValue,
                                reviewEligible: true,
                                reviewQualified: true,
                                persistence: outcome.rawValue,
                                fingerprint: review.evidenceFingerprint,
                                source: "degraded_review_fixture_strapless"
                            )
                            AtriaDebugLog(
                                "ATRIADBG sleep_foreground_compact status=review_only blocker=%@ persistence=%@ fingerprint=%@ source=degraded_review_fixture_strapless",
                                review.motionBlocker.rawValue,
                                outcome.rawValue,
                                review.evidenceFingerprint
                            )
                            self.sleepReviewCacheInputKey = nil
                            self.sleepReviewRefreshDeferredUntilForeground =
                                true
                            if UIApplication.shared.applicationState
                                == .active {
                                self.scheduleSleepReviewCacheRefresh(
                                    rest: fixtureRest,
                                    calendar: .current,
                                    reason: "degraded_review_fixture"
                                )
                            }
                        }
                    case .withheld(let failure):
                        AtriaDebugLog(
                            "ATRIADBG sleep_foreground_compact status=fixture_withheld reason=%@",
                            String(describing: failure)
                        )
                    case .ready:
                        AtriaDebugLog(
                            "ATRIADBG sleep_foreground_compact status=fixture_unexpected_ready"
                        )
                    }
                }
            }
        }
        #endif
        // Handoff-13 CP3-C: one read-only whole-container storage accounting
        // per launch, off the critical path. It measures physically allocated
        // bytes across every managed store and records the honest retention
        // state — currently blocked, and the receipt names exactly why.
        Task.detached(priority: .utility) {
            // Reclaim first, then measure, so the receipt reports the container
            // as it now stands rather than as it was a moment ago.
            let reclaimed = AtriaManagedStorageInventory.sweepOrphanedArtifacts()
            let categories = AtriaManagedStorageInventory.measure()
            AtriaManagedStorageInventory.recordReceipt(
                categories: categories,
                retentionExecution:
                    AtriaManagedStorageInventory
                        .currentRetentionExecutionState,
                nextEligibleAction:
                    "enable cold-session consumer parity; archive-wide maintenance is now admitted",
                reclaimedBytes: reclaimed
            )
        }
        // Insights compute AFTER the launch render (off the critical path). It's
        // light now, but never let it touch the first-frame budget on a big store.
        Task { @MainActor [weak self] in self?.recomputeBehaviorInsights() }

        AtriaDebugLog("ATRIADBG session_store_load status=ok sessions=%d pruned_short_long_wear_fragments=%d baseline_rebuilt=%d elapsed_ms=%d",
              merged.count,
              finalPreparation.prunedShortLongWearFragments,
              finalPreparation.didRebuildBaseline ? 1 : 0,
              elapsedMS)
        #if DEBUG
        await seedDebugStrengthWorkoutProofIfRequested(arguments: ProcessInfo.processInfo.arguments)
        #endif
    }

    /// The source scan is intentionally detached from launch's render path.
    /// It writes only after proving that no concurrent user action changed the
    /// confirmed-workout collection it was based on.
    private func reapplyConfirmedWorkoutStrainCalibrationIfNeeded(
        sourceSessions: [SavedSession]
    ) {
        let before = cachedConfirmedWorkouts
        let targetVersion = AtriaAnalytics.Strain.displayCalibrationVersion
        guard before.contains(where: {
            $0.strain != nil && $0.strainCalibrationVersion != targetVersion
        }) else { return }
        let rest = baseline.restingInt ?? 60
        let maxHR = profile.maxHR
        let biologicalSex = profile.biologicalSex

        Task.detached(priority: .utility) { [store = self, before, sourceSessions, rest, maxHR, biologicalSex] in
            let rescored = Self.rescoredConfirmedWorkoutsForCurrentStrainCalibration(
                before,
                sourceSessions: sourceSessions,
                rest: rest,
                maxHR: maxHR,
                biologicalSex: biologicalSex
            )
            guard rescored != before else { return }
            await Task { @MainActor in
                guard store.cachedConfirmedWorkouts == before else {
                    return
                }
                guard await store.saveConfirmedWorkouts(rescored, deferDerivedPublication: true) else {
                    return
                }
                let changed = zip(before, rescored).reduce(0) { count, pair in
                    count + (pair.0.strain != pair.1.strain ? 1 : 0)
                }
                AtriaDebugLog("ATRIADBG confirmed_workout_strain_migration status=applied version=%d workouts=%d rescored=%d source_sessions=%d",
                              targetVersion,
                              rescored.count,
                              changed,
                              sourceSessions.count)
            }.value
        }
    }

    /// Exact launch-time proof that the three card families are looking at the
    /// same already-confirmed night. Nil recovery/strain remains valid when its
    /// physiological inputs are genuinely unavailable; equality is the gate,
    /// so an older grey row can never be mistaken for the rebuilt projection.
    nonisolated static func deferredLaunchCardSettlementMatches(
        sleep: UserConfirmedSleep,
        metric: SavedDailyMetric?,
        rollup: DailyRollupStoreEntry?,
        calendar: Calendar = .current
    ) -> Bool {
        guard confirmedSleepIsPhysiologicalMainSleep(sleep),
              let metric,
              let rollup else { return false }
        let morningDay = EventCivilTime.day(
            containing: sleep.end,
            eventTimeZoneIdentifier: sleep.eventTimeZoneIdentifier,
            outputCalendar: calendar
        )
        guard calendar.isDate(metric.day, inSameDayAs: morningDay),
              calendar.isDate(rollup.day, inSameDayAs: morningDay),
              metric.sleepStart == sleep.start,
              metric.sleepEnd == sleep.end,
              abs((metric.sleepDuration ?? -1) - sleep.duration) <= 1,
              abs((rollup.sleepSeconds ?? -1) - sleep.duration) <= 1,
              metric.hrv == sleep.hrv,
              metric.restingHR == (sleep.restingHR > 0 ? sleep.restingHR : nil),
              (rollup.sleepPerformance ?? 0) > 0,
              rollup.recovery == metric.recoveryPercent,
              rollup.rhr == metric.restingHR else { return false }

        switch (metric.respiratoryRate, sleep.respiratoryRate) {
        case (nil, nil):
            break
        case (.some(let metricRate), .some(let sleepRate)):
            guard abs(metricRate - sleepRate) < 0.001 else { return false }
        default:
            return false
        }
        switch (rollup.respiratoryRate, metric.respiratoryRate) {
        case (nil, nil):
            break
        case (.some(let rollupRate), .some(let metricRate)):
            guard abs(rollupRate - metricRate) < 0.001 else { return false }
        default:
            return false
        }

        switch (metric.hrv, rollup.lnRMSSD) {
        case (nil, nil):
            break
        case (.some(let hrv), .some(let lnRMSSD)):
            guard hrv > 0, abs(exp(lnRMSSD) - Double(hrv)) < 0.01 else { return false }
        default:
            return false
        }
        // Day strain is intentionally mutable while the user is awake. The
        // metric and rollup files can be persisted a checkpoint apart, while
        // the widget recomputes current-cycle strain from the already-loaded HR
        // sessions. Requiring exact equality here held an immutable 39%
        // recovery behind 6.38-vs-6.34 strain forever. Validate shape only;
        // sleep/recovery/vitals above remain exact.
        let strainValues = [metric.strain, rollup.strain].compactMap { $0 }
        return strainValues.allSatisfy { $0.isFinite && $0 >= 0 }
    }

    private func requestDeferredLaunchCardSettlement(
        reason: String,
        attempt: Int = 0,
        allowLightweightSettlement: Bool = true
    ) {
        let calendar = Calendar.current
        let now = Date()
        let physiologicalCycle = AtriaPhysiologicalCycle.current(
            now: now,
            confirmedSleeps: cachedConfirmedSleeps,
            calendar: calendar
        )
        if physiologicalCycle.boundaryKind != .mainSleep,
           DailyRecoveryResolver.summary(
               rollups: dailyRollupHistory,
               metrics: dailyMetricHistory,
               physiologicalCycle: physiologicalCycle,
               anchorSleep: nil,
               calendar: calendar
           ) != nil {
            // A strict persisted limited-evidence row is already the authority
            // for this no-sleep/initial cycle. It does not depend on rebuilding
            // historical cards, so do not hold the widget fence behind that
            // asynchronous worker.
            deferredLaunchCardSettlementRetryTask?.cancel()
            deferredLaunchCardSettlementRetryTask = nil
            deferredLaunchCardSettlementPending = false
            publishDashboardRevision()
            onDeferredLaunchCardSettlementPublished?(
                "\(reason)_fallback_recovery"
            )
            AtriaDebugLog("ATRIADBG deferred_launch_cards status=published_fallback reason=%@ attempts=%d cycle=%@",
                          reason,
                          attempt + 1,
                          physiologicalCycle.boundaryKind.rawValue)
            return
        }

        // The persisted session, daily metric and daily rollup files are
        // already loaded before this method is entered. When those three
        // authorities agree exactly, release Home/widget publication now.
        // Waiting for a full historical projection here made a 150+ MB archive
        // scan (and its independent 90-second recovery timeout) hold an already
        // valid morning card behind an old widget snapshot.
        if let sleep = AtriaPhysiologicalCycle.latestCompletedMainSleep(
            now: now,
            confirmedSleeps: cachedConfirmedSleeps,
            calendar: calendar
        ) {
            let morningDay = EventCivilTime.day(
                containing: sleep.end,
                eventTimeZoneIdentifier: sleep.eventTimeZoneIdentifier,
                outputCalendar: calendar
            )
            let metric = dailyMetricHistory.first {
                calendar.isDate($0.day, inSameDayAs: morningDay)
            }
            let rollup = dailyRollupHistory.first {
                calendar.isDate($0.day, inSameDayAs: morningDay)
            }
            if Self.deferredLaunchCardSettlementMatches(
                sleep: sleep,
                metric: metric,
                rollup: rollup,
                calendar: calendar
            ) {
                deferredLaunchCardSettlementRetryTask?.cancel()
                deferredLaunchCardSettlementRetryTask = nil
                deferredLaunchCardSettlementPending = false
                publishDashboardRevision()
                onDeferredLaunchCardSettlementPublished?("\(reason)_persisted_fast_path")
                AtriaDebugLog("ATRIADBG deferred_launch_cards status=published_fast_path reason=%@ attempts=%d sleep_id=%@ recovery=%@ strain=%@",
                              reason,
                              attempt + 1,
                              sleep.id,
                              metric?.recoveryPercent.map(String.init) ?? "learning",
                              metric?.strain.map { String(format: "%.2f", $0) } ?? "learning")
                return
            }
        }

        // A confirmed sleep is already a compact, durable physiological
        // authority. Repair missing/stale morning files from that record before
        // asking the 150+ MB history archive to rebuild the same card.
        if allowLightweightSettlement,
           settleConfirmedMorningAuthority(
               reason: "\(reason)_launch_repair",
               now: now,
               completion: { [weak self] succeeded in
                   guard let self else { return }
                   if succeeded {
                       self.deferredLaunchCardSettlementRetryTask?.cancel()
                       self.deferredLaunchCardSettlementRetryTask = nil
                       self.deferredLaunchCardSettlementPending = false
                       self.publishDashboardRevision()
                       self.onDeferredLaunchCardSettlementPublished?(
                           "\(reason)_confirmed_sleep_repair"
                       )
                   } else {
                       self.requestDeferredLaunchCardSettlement(
                           reason: reason,
                           attempt: attempt,
                           allowLightweightSettlement: false
                       )
                   }
               }
           ) {
            return
        }

        requestRequiredHistorySnapshotRefresh(deferred: true) { [weak self] succeeded in
            guard let self, succeeded else { return }
            let calendar = Calendar.current
            guard let sleep = AtriaPhysiologicalCycle.latestCompletedMainSleep(
                now: Date(),
                confirmedSleeps: self.cachedConfirmedSleeps,
                calendar: calendar
            ) else {
                // There is no confirmed main sleep to settle. Still publish the
                // fully-loaded non-sleep dashboard once, without fabricating a
                // Sleep or Recovery value.
                self.deferredLaunchCardSettlementRetryTask?.cancel()
                self.deferredLaunchCardSettlementRetryTask = nil
                self.deferredLaunchCardSettlementPending = false
                self.publishDashboardRevision()
                self.onDeferredLaunchCardSettlementPublished?("\(reason)_no_confirmed_sleep")
                AtriaDebugLog("ATRIADBG deferred_launch_cards status=not_required reason=%@ attempts=%d",
                              reason,
                              attempt + 1)
                return
            }
            let morningDay = EventCivilTime.day(
                containing: sleep.end,
                eventTimeZoneIdentifier: sleep.eventTimeZoneIdentifier,
                outputCalendar: calendar
            )
            let metric = self.dailyMetricHistory.first {
                calendar.isDate($0.day, inSameDayAs: morningDay)
            }
            let rollup = self.dailyRollupHistory.first {
                calendar.isDate($0.day, inSameDayAs: morningDay)
            }
            guard Self.deferredLaunchCardSettlementMatches(
                sleep: sleep,
                metric: metric,
                rollup: rollup,
                calendar: calendar
            ) else {
                guard let retryDelay = Self.deferredLaunchCardSettlementRetryDelay(
                    afterFailedAttempt: attempt
                ) else {
                    self.deferredLaunchCardSettlementRetryTask?.cancel()
                    self.deferredLaunchCardSettlementRetryTask = nil
                    AtriaDebugLog("ATRIADBG deferred_launch_cards status=withheld reason=%@ attempts=%d sleep_id=%@ metric=%d rollup=%d retry=await_source_or_scene action=retain_last_durable_widget",
                                  reason,
                                  attempt + 1,
                                  sleep.id,
                                  metric == nil ? 0 : 1,
                                  rollup == nil ? 0 : 1)
                    return
                }
                AtriaDebugLog("ATRIADBG deferred_launch_cards status=withheld reason=%@ attempts=%d sleep_id=%@ metric=%d rollup=%d retry_ms=%d action=retain_last_durable_widget",
                              reason,
                              attempt + 1,
                              sleep.id,
                              metric == nil ? 0 : 1,
                              rollup == nil ? 0 : 1,
                              retryDelay)
                self.deferredLaunchCardSettlementRetryTask?.cancel()
                self.deferredLaunchCardSettlementRetryTask = Task { @MainActor [weak self] in
                    try? await Task.sleep(for: .milliseconds(retryDelay))
                    guard !Task.isCancelled, let self else { return }
                    self.requestDeferredLaunchCardSettlement(
                        reason: reason,
                        attempt: attempt + 1
                    )
                }
                return
            }
            self.deferredLaunchCardSettlementRetryTask?.cancel()
            self.deferredLaunchCardSettlementRetryTask = nil
            self.deferredLaunchCardSettlementPending = false
            self.publishDashboardRevision()
            self.onDeferredLaunchCardSettlementPublished?(reason)
            AtriaDebugLog("ATRIADBG deferred_launch_cards status=published reason=%@ attempts=%d sleep_id=%@ sleep_s=%.0f recovery=%@ strain=%@ performance=%d",
                          reason,
                          attempt + 1,
                          sleep.id,
                          sleep.duration,
                          metric?.recoveryPercent.map(String.init) ?? "learning",
                          metric?.strain.map { String(format: "%.2f", $0) } ?? "learning",
                          rollup?.sleepPerformance ?? 0)
        }
    }

    /// W3-A P0-3: the "near future" horizon for deferring the minter to a
    /// one-shot retry at the confirmed end. Wide enough for the
    /// device-observed ~6-minute future-end confirms; a more distant future
    /// end is not deferred (the save-path armed rollover boundary owns that
    /// edge), so a stray far-future record can never park the minter.
    nonisolated static let morningSettlementNearFutureRetryWindow: TimeInterval = 10 * 60

    /// Pure decision for the near-future deferral: non-nil (the retry
    /// instant, end+1s) exactly when the newest confirmed main sleep ends in
    /// (now, now+window]. A completed sleep (end <= now) or a distant future
    /// end returns nil and the minter proceeds unchanged.
    nonisolated static func morningSettlementNearFutureRetryDate(
        newestConfirmedMainSleepEnd: Date?,
        now: Date,
        window: TimeInterval = morningSettlementNearFutureRetryWindow
    ) -> Date? {
        guard let end = newestConfirmedMainSleepEnd,
              end > now,
              end.timeIntervalSince(now) <= window else { return nil }
        return end.addingTimeInterval(1)
    }

    /// W3-A P0-3: one-shot re-run of the morning minter one second after a
    /// confirmed near-future wake passes. One outstanding retry at a time;
    /// re-arming replaces it. The task re-enters
    /// `settleConfirmedMorningAuthority`, whose own guards (mutation fence,
    /// completed-main resolution, near-future re-check against any newer
    /// future-end confirm) stay authoritative at fire time.
    private func scheduleMorningSettlementNearFutureRetry(
        at retryAt: Date,
        now: Date,
        originReason: String
    ) {
        morningSettlementNearFutureRetryTask?.cancel()
        let delay = max(1, retryAt.timeIntervalSince(now))
        AtriaDebugLog(
            "ATRIADBG morning_settlement status=near_future_retry_scheduled origin=%@ delay=%.0f",
            originReason,
            delay
        )
        morningSettlementNearFutureRetryTask = Task { @MainActor [weak self] in
            try? await Task.sleep(
                nanoseconds: UInt64(delay * 1_000_000_000)
            )
            guard !Task.isCancelled, let self else { return }
            self.morningSettlementNearFutureRetryTask = nil
            _ = self.settleConfirmedMorningAuthority(
                reason: "near_future_end_retry",
                completion: { [weak self] succeeded in
                    guard succeeded else { return }
                    self?.publishDashboardRevision()
                }
            )
        }
    }

    /// Mints the morning metric and rollup directly from the exact confirmed
    /// sleep record. This is bounded by the small persisted collections and
    /// never reads the live journal or historical archive.
    @discardableResult
    private func settleConfirmedMorningAuthority(
        reason: String,
        now: Date = Date(),
        completion: ((Bool) -> Void)? = nil,
        calendar: Calendar = .current,
        preserveExistingSkinTemperature: Bool = true
    ) -> Bool {
        // A silent bail here is indistinguishable from success in the field,
        // yet it freezes the wake day's SavedDailyMetric/rollup at its pre-edit
        // image (the exact "stale 2h37m ring" failure). Name the guard that
        // fired so a de-anchored physiological day is diagnosable from logs.
        guard canonicalMutationAllowed,
              recoveredDataMutationTransaction.activeTicket == nil else {
            AtriaDebugLog(
                "ATRIADBG morning_settlement status=bailed reason=%@ guard=mutation_authority allowed=%d recovered_ticket=%d",
                reason,
                canonicalMutationAllowed ? 1 : 0,
                recoveredDataMutationTransaction.activeTicket == nil ? 0 : 1
            )
            return false
        }
        // W3-A P0-3 (belt-and-braces): a direct minter call landing minutes
        // before a confirmed future-end wake would resolve
        // `latestCompletedMainSleep` to the PREVIOUS night — its `end <= now`
        // filter is an honesty gate and stays — and silently settle
        // yesterday's wake day, leaving the new day unminted with nothing
        // scheduled to re-run the minter. Defer instead and re-run this exact
        // minter one second after the confirmed end passes. The gates are
        // never loosened: this re-triggers when their precondition becomes
        // true; it never mints from an unfinished night.
        if let retryAt = Self.morningSettlementNearFutureRetryDate(
            newestConfirmedMainSleepEnd: AtriaPhysiologicalCycle
                .canonicalMainSleeps(from: cachedConfirmedSleeps)
                .map(\.end)
                .max(),
            now: now
        ) {
            scheduleMorningSettlementNearFutureRetry(
                at: retryAt,
                now: now,
                originReason: reason
            )
            AtriaDebugLog(
                "ATRIADBG morning_settlement status=deferred reason=%@ guard=near_future_sleep_end retry_at=%.3f",
                reason,
                retryAt.timeIntervalSince1970
            )
            return false
        }
        guard let canonicalSleep = AtriaPhysiologicalCycle.latestCompletedMainSleep(
            now: now,
            confirmedSleeps: cachedConfirmedSleeps,
            calendar: calendar
        ) else {
            AtriaDebugLog(
                "ATRIADBG morning_settlement status=bailed reason=%@ guard=no_completed_main_sleep",
                reason
            )
            return false
        }
        let sleep = SleepHistorySnapshot(
            rollups: historySnapshot.rollups,
            confirmedSleeps: cachedConfirmedSleeps,
            dismissedCandidates: dismissedSleepCandidates,
            calendar: calendar
        )
        guard let projectedNight = sleep.nights.first(where: {
            $0.id == canonicalSleep.id && $0.confirmed && !$0.isNapEvidence
        }) else {
            AtriaDebugLog(
                "ATRIADBG morning_settlement status=bailed reason=%@ guard=canonical_sleep_not_projected id=%@",
                reason,
                canonicalSleep.id
            )
            return false
        }
        let wakeDay = EventCivilTime.day(
            containing: canonicalSleep.end,
            eventTimeZoneIdentifier: canonicalSleep.eventTimeZoneIdentifier,
            outputCalendar: calendar
        )
        guard let metric = Self.makeMorningFrozenDailyMetric(
            for: wakeDay,
            computed: dailyMetricHistory,
            sessions: [],
            sleep: sleep,
            baseline: baseline,
            maxHR: profile.maxHR,
            now: now,
            skinTemperatureSourceValidated: false,
            calendar: calendar
        ),
        metric.sleepStart == projectedNight.start,
        metric.sleepEnd == projectedNight.end else {
            return false
        }

        var metrics = dailyMetricHistory.filter {
            !calendar.isDate($0.day, inSameDayAs: wakeDay)
        }
        metrics.append(metric)
        metrics.sort { $0.day > $1.day }

        let preparedRollups = Self.makeDailyRollupStoreEntries(
            metrics: metrics,
            sessions: [],
            rest: baseline.restingInt ?? 60,
            maxHR: profile.maxHR,
            napHoursByDay: Self.napHoursByMorningDay(sleep: sleep, calendar: calendar),
            displaySleepEfficiencyByDay:
                Self.displaySleepEfficiencyByMorningDay(sleep: sleep, calendar: calendar),
            calendar: calendar
        )
        guard var rollup = preparedRollups.first(where: {
            calendar.isDate($0.day, inSameDayAs: wakeDay)
        }) else {
            return false
        }
        if let existing = dailyRollupStore.rollup(for: wakeDay) {
            rollup.nutrition = existing.nutrition
            rollup.fitnessAgeDelta = existing.fitnessAgeDelta
            if rollup.vitals == nil { rollup.vitals = existing.vitals }
            if rollup.strain == nil { rollup.strain = existing.strain }
            if preserveExistingSkinTemperature,
               rollup.skinTemperatureDeviationCelsius == nil {
                rollup.skinTemperatureDeviationCelsius =
                    existing.skinTemperatureDeviationCelsius
            }
        }
        if !preserveExistingSkinTemperature {
            rollup.skinTemperatureDeviationCelsius = nil
        }

        dailyMetricHistory = metrics
        let expectedMetricRevision = dailyMetricHistoryRevision
        dailyRollupStore.upsert(rollup)
        dailyRollupHistory = dailyRollupStore.rollups(last: 400)
        dailyRollupHistoryRevision &+= 1
        let expectedRollupRevision = dailyRollupHistoryRevision
        let expectedSleepRevision = confirmedSleepsRevision

        pendingDailyMetricSaveWorkItem?.cancel()
        pendingDailyMetricPersistRevision = nil
        let metricURL = dailyMetricsURL
        let metricSnapshot = metrics
        var metricWriteFinished = false
        var rollupWriteFinished = false
        var metricWriteSucceeded = false
        var rollupWriteSucceeded = false

        func finishIfPossible() {
            guard metricWriteFinished, rollupWriteFinished else { return }
            let stillCurrent = confirmedSleepsRevision == expectedSleepRevision
                && dailyMetricHistoryRevision == expectedMetricRevision
                && dailyRollupHistoryRevision == expectedRollupRevision
            let currentMetric = dailyMetricHistory.first {
                calendar.isDate($0.day, inSameDayAs: wakeDay)
            }
            let currentRollup = dailyRollupHistory.first {
                calendar.isDate($0.day, inSameDayAs: wakeDay)
            }
            let coherent = stillCurrent
                && metricWriteSucceeded
                && rollupWriteSucceeded
                && Self.deferredLaunchCardSettlementMatches(
                    sleep: canonicalSleep,
                    metric: currentMetric,
                    rollup: currentRollup,
                    calendar: calendar
                )
            AtriaDebugLog(
                "ATRIADBG confirmed_morning_settlement status=%@ reason=%@ sleep_id=%@ metric_write=%d rollup_write=%d current=%d",
                coherent ? "durable" : "failed",
                reason,
                canonicalSleep.id,
                metricWriteSucceeded ? 1 : 0,
                rollupWriteSucceeded ? 1 : 0,
                stillCurrent ? 1 : 0
            )
            completion?(coherent)
        }

        let workItem = DispatchWorkItem { [weak self] in
            let succeeded = Self.persistDailyMetricsSnapshot(
                metricSnapshot,
                to: metricURL,
                reason: reason
            )
            DispatchQueue.main.async {
                guard self != nil else { return }
                metricWriteSucceeded = succeeded
                metricWriteFinished = true
                finishIfPossible()
            }
        }
        pendingDailyMetricSaveWorkItem = workItem
        persistenceQueue.async(execute: workItem)
        dailyRollupStore.persistCurrentSnapshot { succeeded in
            rollupWriteSucceeded = succeeded
            rollupWriteFinished = true
            finishIfPossible()
        }
        publishDashboardRevision()
        return true
    }

    /// Two bounded retries cover ordinary launch worker ordering. An
    /// unsettleable/corrupt row must not create a permanent O(n) timer loop;
    /// later source publication or a scene transition explicitly retriggers it.
    nonisolated static func deferredLaunchCardSettlementRetryDelay(
        afterFailedAttempt attempt: Int
    ) -> Int? {
        let safeAttempt = max(0, attempt)
        guard safeAttempt < 2 else { return nil }
        return 250 * (safeAttempt + 1)
    }

    /// A failed launch settlement stays fail-closed for widgets, but may be
    /// retried when a real lifecycle/source event makes a different answer
    /// possible. The guards keep overlapping callbacks from spawning another
    /// rebuild while the existing required refresh still owns the fence.
    func resumeDeferredLaunchCardSettlementIfNeeded(reason: String) {
        guard hasCompletedDeferredSessionLoad,
              deferredLaunchCardSettlementPending,
              deferredLaunchCardSettlementRetryTask == nil,
              requiredHistoryPublicationCompletions.isEmpty else { return }
        requestDeferredLaunchCardSettlement(reason: reason)
    }

    /// Applies the exact-window HRV truth migration only after the deferred raw
    /// session store is available. Changed morning days are authoritative: old
    /// frozen recovery/HRV rows are removed before the ordinary history rebuild
    /// can recreate sleep/RHR/strain fields from the preserved boundary. A day
    /// whose RR cannot pass the verified transport gate therefore becomes honestly
    /// nil instead of retaining an unreproducible legacy readiness score.
    @discardableResult
    private func requalifyPersistedConfirmedSleepHRVFromSessionsIfNeeded(
        _ sourceSessions: [SavedSession],
        reason: String,
        deferDerivedPublication: Bool = false,
        affectedSince: Date? = nil,
        calendar: Calendar = .current,
        sessionsArePreFiltered: Bool = false,
        executionShouldContinue:
            @escaping @Sendable () -> Bool = { true }
    ) async -> ConfirmedSleepHRVRequalificationOutcome {
        let before = cachedConfirmedSleeps
        guard executionShouldContinue() else {
            return .init(changed: false, succeeded: false)
        }
        let eligibleSessions = sessionsArePreFiltered
            ? sourceSessions
            : (affectedSince.map { cutoff in
                sourceSessions.filter { $0.end > cutoff }
            } ?? sourceSessions)
        let after: [UserConfirmedSleep]? = await withCheckedContinuation {
            continuation in
            DispatchQueue.global(qos: .utility).async {
                let prepared = AtriaTransientWorkThread.run(
                    name: "atria.recovered-sleep-hrv-prepare",
                    qualityOfService: .utility
                ) { () -> [UserConfirmedSleep]? in
                    guard let proposed = Self
                        .requalifiedConfirmedSleepHRVRecordsCancellable(
                            before,
                            sessions: eligibleSessions,
                            shouldContinue: executionShouldContinue
                        ) else { return nil }
                    guard executionShouldContinue() else { return nil }
                    let proposedByID = Dictionary(
                        uniqueKeysWithValues: proposed.map { ($0.id, $0) }
                    )
                    var result: [UserConfirmedSleep] = []
                    result.reserveCapacity(before.count)
                    for (index, sleep) in before.enumerated() {
                        if index.isMultiple(of: 32),
                           !executionShouldContinue() { return nil }
                        guard affectedSince.map({ sleep.end > $0 })
                                ?? true else {
                            result.append(sleep)
                            continue
                        }
                        result.append(proposedByID[sleep.id] ?? sleep)
                    }
                    return executionShouldContinue() ? result : nil
                }
                continuation.resume(returning: prepared)
            }
        }
        guard let after, executionShouldContinue() else {
            return .init(changed: false, succeeded: false)
        }
        guard after != before else {
            return ConfirmedSleepHRVRequalificationOutcome(changed: false,
                                                            succeeded: true)
        }

        let afterByID = Dictionary(uniqueKeysWithValues: after.map { ($0.id, $0) })
        let changedSleeps = before.filter { old in
            guard let updated = afterByID[old.id] else { return false }
            return Self.confirmedSleepQualifiedMetricsChanged(
                previous: old,
                next: updated
            )
        }
        let changedDays = Set(changedSleeps.map {
            EventCivilTime.day(containing: $0.end,
                               eventTimeZoneIdentifier: $0.eventTimeZoneIdentifier,
                               outputCalendar: calendar)
        })
        guard !changedDays.isEmpty else {
            return ConfirmedSleepHRVRequalificationOutcome(changed: false,
                                                            succeeded: true)
        }

        let pendingInvalidationDaysBeforeSave = pendingDailyDerivedInvalidationDays
        pendingDailyDerivedInvalidationDays.formUnion(changedDays)
        guard await saveConfirmedSleeps(after,
                                  deferDerivedPublication: deferDerivedPublication,
                                  recoveredMutationBase:
                                    deferDerivedPublication ? before : nil,
                                  executionShouldContinue:
                                    executionShouldContinue),
              executionShouldContinue() else {
            // A failed canonical write must not leave a latent invalidation
            // that a later unrelated history refresh could partially publish.
            pendingDailyDerivedInvalidationDays = pendingInvalidationDaysBeforeSave
            AtriaDebugLog("ATRIADBG confirmed_sleep_hrv_requalification status=failed reason=%@ changed_records=%d action=retain_derived_rows_until_retry",
                          reason,
                          changedSleeps.count)
            return ConfirmedSleepHRVRequalificationOutcome(changed: false,
                                                            succeeded: false)
        }

        let filteredMetrics = dailyMetricHistory.filter { metric in
            !changedDays.contains(calendar.startOfDay(for: metric.day))
        }
        if filteredMetrics != dailyMetricHistory {
            dailyMetricHistory = filteredMetrics
            scheduleDailyMetricPersist(reason: "confirmed_sleep_hrv_requalification")
        }
        dailyRollupStore.reconcile([], replacingDays: changedDays)
        dailyRollupHistory = dailyRollupStore.rollups(last: 400)
        dailyRollupHistoryRevision &+= 1
        if !deferDerivedPublication {
            refreshHistorySnapshotCache(deferred: true)
        }
        AtriaDebugLog("ATRIADBG confirmed_sleep_hrv_requalification status=updated reason=%@ changed_records=%d invalidated_days=%d action=recompute_from_verified_rr",
                      reason,
                      changedSleeps.count,
                      changedDays.count)
        return ConfirmedSleepHRVRequalificationOutcome(changed: true,
                                                        succeeded: true)
    }

