    private nonisolated static func prepareDeferredLoad(decoded: [SavedSession],
                                                        baseline: PersonalBaseline,
                                                        profile: AthleteProfile,
                                                        confirmedSleeps: [UserConfirmedSleep],
                                                        sessionFileURL: URL,
                                                        prunedShortLongWearFragments: Int = 0) -> DeferredLoadPreparation {
        let shouldRebuildBaseline = shouldRebuildBaselineAfterLoading(
            decoded,
            baseline: baseline
        )
        let needsConfirmedSleepMerge = baselineNeedsConfirmedSleepMerge(
            baseline,
            confirmedSleeps: confirmedSleeps
        )
        let preparedBaseline: PersonalBaseline
        if shouldRebuildBaseline {
            preparedBaseline = rebuildBaseline(from: decoded,
                                                previousBaseline: baseline,
                                                profile: profile,
                                                confirmedSleeps: confirmedSleeps)
        } else if needsConfirmedSleepMerge {
            var merged = baseline
            _ = seedBaselineFromConfirmedSleeps(
                &merged,
                confirmedSleeps: confirmedSleeps
            )
            preparedBaseline = merged
        } else {
            preparedBaseline = baseline
        }
        let latestReferenceSource = latestReferenceValidatedHRVSource(in: decoded)
        let latestLocalSource = latestLocalRMSSDSource(in: decoded)
        return DeferredLoadPreparation(
            latestReferenceValidatedHRV: latestReferenceSource?.value,
            latestReferenceValidatedHRVSource: latestReferenceSource,
            latestLocalRMSSD: latestLocalSource?.value,
            latestLocalRMSSDSource: latestLocalSource,
            canonicalSessions: makeCanonicalSessions(from: decoded),
            baseline: preparedBaseline,
            didRebuildBaseline: shouldRebuildBaseline || needsConfirmedSleepMerge,
            prunedShortLongWearFragments: prunedShortLongWearFragments
        )
    }

    private nonisolated static func shouldRebuildBaselineAfterLoading(_ decoded: [SavedSession],
                                                                      baseline: PersonalBaseline) -> Bool {
        guard !decoded.isEmpty else { return false }
        if baseline.hrvQualificationVersion < PersonalBaseline.currentHRVQualificationVersion {
            return true
        }
        if baseline.updated == nil || baseline.restingSampleCount == 0 {
            return true
        }
        let hasLocalHRVInSessions = decoded.contains { $0.localRMSSD != nil }
        if baseline.hrvSampleCount == 0 && hasLocalHRVInSessions {
            return true
        }
        return false
    }

    nonisolated static func rebuildBaseline(from sessions: [SavedSession],
                                            previousBaseline: PersonalBaseline,
                                            profile: AthleteProfile,
                                            confirmedSleeps: [UserConfirmedSleep]) -> PersonalBaseline {
        let previousRest = previousBaseline.restingInt
        var rebuilt = PersonalBaseline()
        for session in sessions.sorted(by: { $0.start < $1.start }) {
            let bootstrapFromConfirmedSleep = confirmedSleeps.contains { sleep in
                confirmedSleepIsPhysiologicalMainSleep(sleep)
                    && session.start < sleep.end
                    && session.end > sleep.start
            }
            guard let rest = rebuilt.restingInt
                    ?? previousRest
                    ?? (bootstrapFromConfirmedSleep ? session.restingStable : nil) else {
                continue
            }
            let evidence = session.baselineLearningEvidence(rest: rest, maxHR: profile.maxHR)
            guard evidence.accepted else { continue }
            let sleepHRV = confirmedMainSleepHRVEvidence(for: session,
                                                         confirmedSleeps: confirmedSleeps)
            rebuilt.learn(fromResting: evidence.value,
                          hrv: sleepHRV?.value ?? 0,
                          at: sleepHRV?.sleepEnd ?? session.end,
                          overnight: sleepHRV != nil)
        }
        _ = seedBaselineFromConfirmedSleeps(
            &rebuilt,
            confirmedSleeps: confirmedSleeps
        )
        return rebuilt
    }

    nonisolated static func rebuildBaselineCancellable(
        from sessions: [SavedSession],
        previousBaseline: PersonalBaseline,
        profile: AthleteProfile,
        confirmedSleeps: [UserConfirmedSleep],
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> PersonalBaseline? {
        guard shouldContinue() else { return nil }
        var ordered = sessions
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &ordered,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: { $0.start < $1.start }
        ) else { return nil }
        let previousRest = previousBaseline.restingInt
        var rebuilt = PersonalBaseline()
        for (index, session) in ordered.enumerated() {
            if index.isMultiple(of: 16), !shouldContinue() { return nil }
            var bootstrapFromConfirmedSleep = false
            for (sleepIndex, sleep) in confirmedSleeps.enumerated() {
                if sleepIndex.isMultiple(of: 32), !shouldContinue() {
                    return nil
                }
                if confirmedSleepIsPhysiologicalMainSleep(sleep),
                   session.start < sleep.end,
                   session.end > sleep.start {
                    bootstrapFromConfirmedSleep = true
                    break
                }
            }
            guard let rest = rebuilt.restingInt
                    ?? previousRest
                    ?? (bootstrapFromConfirmedSleep
                        ? session.restingStable : nil) else { continue }
            guard shouldContinue() else { return nil }
            let localRMSSD = session.localRMSSDCancellable(
                shouldContinue: shouldContinue
            )
            guard shouldContinue() else { return nil }
            let evidence = session.baselineLearningEvidence(
                rest: rest,
                maxHR: profile.maxHR,
                calendar: .current,
                localRMSSD: localRMSSD
            )
            guard shouldContinue() else { return nil }
            guard evidence.accepted else { continue }
            let sleepHRV = confirmedMainSleepHRVEvidenceCancellable(
                for: session,
                confirmedSleeps: confirmedSleeps,
                shouldContinue: shouldContinue
            )
            guard shouldContinue() else { return nil }
            rebuilt.learn(
                fromResting: evidence.value,
                hrv: sleepHRV?.value ?? 0,
                at: sleepHRV?.sleepEnd ?? session.end,
                overnight: sleepHRV != nil
            )
        }
        guard shouldContinue() else { return nil }
        guard seedBaselineFromConfirmedSleepsCancellable(
            &rebuilt,
            confirmedSleeps: confirmedSleeps,
            shouldContinue: shouldContinue
        ) != nil else { return nil }
        return shouldContinue() ? rebuilt : nil
    }

    nonisolated static func baselineNeedsConfirmedSleepMerge(
        _ baseline: PersonalBaseline,
        confirmedSleeps: [UserConfirmedSleep],
        calendar: Calendar = .current
    ) -> Bool {
        AtriaPhysiologicalCycle.canonicalMainSleeps(from: confirmedSleeps)
            .contains { sleep in
                guard (35...240).contains(sleep.restingHR) else { return false }
                let qualifiedHRV = sleep.hrv.flatMap {
                    $0 > 0 && (sleep.hrvWindowCount ?? 0) >= 3 ? Double($0) : nil
                }
                return !baseline.samples.contains {
                    calendar.isDate($0.date, inSameDayAs: sleep.end)
                        && $0.isOvernightSample
                        && Int($0.restingHR.rounded()) == sleep.restingHR
                        && (qualifiedHRV == nil || $0.rmssd == qualifiedHRV)
                }
            }
    }

    /// Confirmed main-sleep records retain the exact qualified overnight
    /// physiology after raw-session retirement. Merge every missing day—not
    /// only the first—so a reinstall/relaunch cannot strand mature wear at
    /// "Learning". Resumed sleep is canonicalized into its owning night; naps
    /// never seed RHR or HRV.
    @discardableResult
    nonisolated static func seedBaselineFromConfirmedSleeps(
        _ baseline: inout PersonalBaseline,
        confirmedSleeps: [UserConfirmedSleep],
        calendar: Calendar = .current
    ) -> Int {
        seedBaselineFromConfirmedSleepsCancellable(
            &baseline,
            confirmedSleeps: confirmedSleeps,
            calendar: calendar,
            shouldContinue: { true }
        ) ?? 0
    }

    @discardableResult
    nonisolated static func seedBaselineFromConfirmedSleepsCancellable(
        _ baseline: inout PersonalBaseline,
        confirmedSleeps: [UserConfirmedSleep],
        calendar: Calendar = .current,
        shouldContinue: @escaping @Sendable () -> Bool
    ) -> Int? {
        guard shouldContinue(),
              let canonical = AtriaPhysiologicalCycle
                .canonicalMainSleepsCancellable(
                    from: confirmedSleeps,
                    shouldContinue: shouldContinue
                ) else { return nil }
        var seeds: [UserConfirmedSleep] = []
        seeds.reserveCapacity(canonical.count)
        for (index, sleep) in canonical.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            if (35...240).contains(sleep.restingHR) {
                seeds.append(sleep)
            }
        }
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &seeds,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: { $0.end < $1.end }
        ) else { return nil }
        var merged = 0
        for (index, sleep) in seeds.enumerated() {
            if index.isMultiple(of: 16), !shouldContinue() { return nil }
            let qualifiedHRV = sleep.hrv.flatMap {
                $0 > 0 && (sleep.hrvWindowCount ?? 0) >= 3 ? $0 : nil
            }
            if baseline.mergeConfirmedSleep(
                resting: sleep.restingHR,
                hrv: qualifiedHRV,
                at: sleep.end,
                calendar: calendar
            ) {
                merged += 1
            }
        }
        return shouldContinue() ? merged : nil
    }

}

// MARK: - History UI

@MainActor
final class AtriaHistoryProjectionStore: ObservableObject {
    @Published private(set) var snapshot: HistorySnapshot
    @Published private(set) var pendingSleepReview: SleepHistorySnapshot.Night?
    @Published private(set) var restingBaseline: Int?
    @Published private(set) var hrvBaselineSampleCount: Int
    @Published private(set) var sleepHistorySnapshot: SleepHistorySnapshot

    private var cancellables = Set<AnyCancellable>()

    init(store: SessionStore) {
        snapshot = store.historySnapshot
        pendingSleepReview = store.pendingSleepReviewNightForUI
        restingBaseline = store.baseline.restingInt
        hrvBaselineSampleCount = store.baseline.hrvSampleCount
        sleepHistorySnapshot = store.sleepHistorySnapshot

        store.$historySnapshot
            .dropFirst()
            .sink { [weak self] in self?.snapshot = $0 }
            .store(in: &cancellables)

        store.$pendingSleepReviewNightForUI
            .dropFirst()
            .removeDuplicates()
            .sink { [weak self] in self?.pendingSleepReview = $0 }
            .store(in: &cancellables)

        store.$sleepHistorySnapshot
            .dropFirst()
            .removeDuplicates()
            .sink { [weak self] in self?.sleepHistorySnapshot = $0 }
            .store(in: &cancellables)

        store.$baseline
            .dropFirst()
            .sink { [weak self] baseline in
                guard let self else { return }
                let resting = baseline.restingInt
                let hrvSamples = baseline.hrvSampleCount
                if resting != self.restingBaseline {
                    self.restingBaseline = resting
                }
                if hrvSamples != self.hrvBaselineSampleCount {
                    self.hrvBaselineSampleCount = hrvSamples
                }
            }
            .store(in: &cancellables)
    }
}

struct HistoryView: View {
    let store: SessionStore
    @StateObject private var projectionStore: AtriaHistoryProjectionStore
    @State private var adjustmentNight: SleepHistorySnapshot.Night?
    @State private var archivedSessionRows: [HistorySessionRowSnapshot] = []
    @State private var archivedCompactFacts: [AtriaColdSessionFact] = []
    @State private var isLoadingArchivedSessions = false
    @State private var archivedSessionsExhausted = false
    @State private var isLoadingCanonicalHistory = false
    @State private var visibleCanonicalDayLimit = 14
    @State private var visibleDetectionLimit = 5

    init(store: SessionStore) {
        self.store = store
        _projectionStore = StateObject(wrappedValue: AtriaHistoryProjectionStore(store: store))
    }

    private var snapshot: HistorySnapshot {
        #if DEBUG
        if let fixture = Self.debugFixtureHistorySnapshot(arguments: ProcessInfo.processInfo.arguments) {
            return fixture
        }
        #endif
        return projectionStore.snapshot
    }

    private var pendingSleepReview: SleepHistorySnapshot.Night? {
        #if DEBUG
        if let fixture = Self.debugFixtureSleepReviewNight(arguments: ProcessInfo.processInfo.arguments) {
            return fixture
        }
        #endif
        guard let latest = projectionStore.pendingSleepReview,
              latest.confirmed == false else { return nil }
        return latest
    }

    var body: some View {
        ZStack {
            AtriaDashboardBackdrop()
                .ignoresSafeArea()

            ScrollView(showsIndicators: false) {
                LazyVStack(alignment: .leading, spacing: 18) {
                    historyHeroCard
                    if let pendingSleepReview {
                        HistorySleepReviewCTA(night: pendingSleepReview,
                                              onConfirm: {
                                                  await store.confirmSleepHistoryNightForUI(
                                                    pendingSleepReview,
                                                    rest: projectionStore.restingBaseline ?? 60,
                                                    source: "history_sleep_review"
                                                  ) != nil
                                              },
                                              onAdjust: {
                                                  adjustmentNight = pendingSleepReview
                                              })
                    }

                    if snapshot.sessions.isEmpty
                        && snapshot.rollups.isEmpty
                        && snapshot.detections.isEmpty
                        && snapshot.verifiedHistoricalStepEvidenceDays.isEmpty {
                        ContentUnavailableView("No sessions yet",
                                               systemImage: "heart.text.square",
                                               description: Text("Finish a session to save it here."))
                            .frame(maxWidth: .infinity)
                            .padding(20)
                            .atriaCard(cornerRadius: 22, emphasis: .soft)
                    } else {
                        historySection(title: "Daily rollups", subtitle: "Recent saved evidence") {
                            LazyVStack(spacing: 12) {
                                HistoryActivityRhythmCard(rollups: Array(snapshot.rollups.prefix(14)))

                                ForEach(snapshot.rollups.prefix(visibleCanonicalDayLimit), id: \.day) { rollup in
                                    DailyRollupRow(rollup: rollup)
                                }
                            }
                        }

                        if !snapshot.verifiedHistoricalStepEvidenceDays.isEmpty
                            || snapshot.verifiedCanonicalHistoryHasMore {
                            historySection(title: "Daily steps",
                                           subtitle: "Verified complete days and honest partial coverage") {
                                LazyVStack(spacing: 10) {
                                    ForEach(snapshot.verifiedHistoricalStepEvidenceDays.prefix(visibleCanonicalDayLimit),
                                            id: \.dayStart) { day in
                                        HistoryVerifiedStepDayRow(day: day)
                                    }
                                    if snapshot.verifiedCanonicalHistoryHasMore {
                                        Button {
                                            loadCanonicalHistoryPage()
                                        } label: {
                                            if isLoadingCanonicalHistory {
                                                ProgressView().frame(maxWidth: .infinity)
                                            } else {
                                                Label("Load older verified days",
                                                      systemImage: "calendar.badge.plus")
                                                    .frame(maxWidth: .infinity)
                                            }
                                        }
                                        .buttonStyle(.bordered)
                                        .disabled(isLoadingCanonicalHistory)
                                    }
                                }
                            }
                        }

                        historySection(title: "Trends", subtitle: "Saved readiness over time") {
                            TrendSummaryView(summaries: snapshot.trends)
                        }

                        if !snapshot.detections.isEmpty {
                            historySection(title: "Detected", subtitle: "Local-only activity findings") {
                                LazyVStack(spacing: 12) {
                                    ForEach(snapshot.detections.prefix(visibleDetectionLimit)) { detection in
                                        DetectionRow(detection: detection)
                                    }
                                }
                            }
                        }

                        if snapshot.restingTrendPoints.count >= 2 {
                            historySection(title: "Resting trend", subtitle: "Saved resting HR over time") {
                                RestingTrendChart(points: snapshot.restingTrendPoints,
                                                  baseline: projectionStore.restingBaseline)
                            }
                        }

                        historySection(title: "Saved sessions", subtitle: "Open any session for detail") {
                            LazyVStack(spacing: 12) {
                                ForEach(snapshot.sessionRows) { row in
                                    NavigationLink {
                                        SessionDetail(session: row.session)
                                    } label: {
                                        historySessionRow(row)
                                    }
                                    .buttonStyle(.plain)
                                    .contextMenu {
                                        Button(role: .destructive) {
                                            store.deleteSession(id: row.id)
                                        } label: {
                                            Label("Delete session", systemImage: "trash")
                                        }
                                    }
                                }
                            }
                        }

                        historySection(title: "Older sessions",
                                       subtitle: "Loaded from the verified archive only when requested") {
                            LazyVStack(spacing: 12) {
                                ForEach(archivedSessionRows) { row in
                                    NavigationLink {
                                        SessionDetail(session: row.session)
                                    } label: {
                                        historySessionRow(row)
                                    }
                                    .buttonStyle(.plain)
                                }
                                ForEach(archivedCompactFacts, id: \.source.sessionID) { fact in
                                    compactArchivedSessionRow(fact)
                                }
                                Button {
                                    loadArchivedSessionPage()
                                } label: {
                                    if isLoadingArchivedSessions {
                                        ProgressView()
                                            .frame(maxWidth: .infinity)
                                    } else {
                                        Label(archivedSessionsExhausted
                                              ? "No more older sessions"
                                              : "Load older sessions",
                                              systemImage: archivedSessionsExhausted
                                                ? "checkmark.circle"
                                                : "archivebox")
                                            .frame(maxWidth: .infinity)
                                    }
                                }
                                .buttonStyle(.bordered)
                                .disabled(isLoadingArchivedSessions || archivedSessionsExhausted)
                            }
                        }
                    }
                }
                .padding(.horizontal, 16)
                .padding(.top, 18)
                .padding(.bottom, 36)
                .frame(maxWidth: 720)
                .frame(maxWidth: .infinity)
            }
        }
        .navigationTitle("History")
        .navigationBarTitleDisplayMode(.inline)
        .sheet(item: $adjustmentNight) { adjustment in
            AtriaManualSleepSheet(initialStart: adjustment.start,
                                  initialEnd: adjustment.end,
                                  initialIsNap: adjustment.isNapEvidence,
                                  preservesSensorStages: true,
                                  evidenceNight: adjustment,
                                  evidencePerformancePercent: projectionStore.sleepHistorySnapshot.sleepPerformancePercent(for: adjustment,
                                                                                                                           baseNeedHours: SessionStore.configuredSleepBaseNeedHours())) { start, end, isNap in
                let saved = await store.saveSleepReviewNightForUI(
                    adjustment,
                    start: start,
                    end: end,
                    isNap: isNap,
                    rest: projectionStore.restingBaseline ?? 60,
                    source: "history_sleep_review_adjust"
                ) != nil
                if saved { adjustmentNight = nil }
                return saved
            }
        }
    }

    private func loadArchivedSessionPage() {
        guard !isLoadingArchivedSessions, !archivedSessionsExhausted else { return }
        isLoadingArchivedSessions = true
        let upperBound = (archivedSessionRows.map(\.start)
            + archivedCompactFacts.map(\.source.start)
            + snapshot.sessions.map(\.start)).min()
            ?? Date()
        let archiveEpoch = Date(timeIntervalSince1970: 0)
        guard upperBound > archiveEpoch else {
            archivedSessionsExhausted = true
            isLoadingArchivedSessions = false
            return
        }
        let interval = DateInterval(start: archiveEpoch, end: upperBound)
        Task {
            let sessions = await store.archivedSessions(overlapping: interval,
                                                        maximumSessionCount: 100,
                                                        maximumDecodedBytes: 32 * 1_024 * 1_024)
            let rest = projectionStore.restingBaseline ?? 60
            let maxHR = store.profile.maxHR
            if !sessions.isEmpty {
                archivedCompactFacts = []
                archivedSessionRows = sessions.map {
                    HistorySessionRowSnapshot(session: $0,
                                              rest: rest,
                                              maxHR: maxHR,
                                              includeDerivedMetrics: true)
                }
                archivedSessionsExhausted = false
            } else {
                let facts = await store.archivedCompactSessionFacts(before: upperBound)
                archivedSessionRows = []
                archivedCompactFacts = facts
                archivedSessionsExhausted = facts.isEmpty
            }
            isLoadingArchivedSessions = false
        }
    }

    @ViewBuilder
    private func compactArchivedSessionRow(_ fact: AtriaColdSessionFact) -> some View {
        let heart = fact.heartRate.value
        let average = heart.map { Int((Double($0.sumBPM) / Double(max(1, $0.sampleCount))).rounded()) }
        HStack(spacing: 12) {
            Image(systemName: "archivebox.fill")
                .foregroundStyle(.green)
                .frame(width: 34, height: 34)
                .background(Color.green.opacity(0.12), in: Circle())
            VStack(alignment: .leading, spacing: 3) {
                Text(fact.timeline.label.isEmpty ? "Saved session" : fact.timeline.label)
                    .font(.subheadline.weight(.semibold))
                Text(fact.source.start.formatted(date: .abbreviated, time: .shortened))
                    .font(.caption)
                    .foregroundStyle(.secondary)
            }
            Spacer()
            VStack(alignment: .trailing, spacing: 3) {
                Text(average.map { "\($0) bpm" } ?? "No HR")
                    .font(.subheadline.monospacedDigit())
                Text("Compact verified")
                    .font(.caption2)
                    .foregroundStyle(.secondary)
            }
        }
        .padding(14)
        .atriaCard(cornerRadius: 18, emphasis: .soft)
        .accessibilityElement(children: .combine)
        .accessibilityLabel("\(fact.timeline.label), compact verified historical session")
    }

    private func loadCanonicalHistoryPage() {
        guard !isLoadingCanonicalHistory,
              snapshot.verifiedCanonicalHistoryHasMore else { return }
        isLoadingCanonicalHistory = true
        Task {
            let loaded = await store.loadNextVerifiedCanonicalHistoryPage()
            if loaded {
                // A requested canonical page may add rollups, activity
                // detections, sleep and step evidence together. Expand every
                // affected History list so the newly loaded page is actually
                // visible instead of remaining hidden behind fixed prefixes.
                visibleCanonicalDayLimit += 14
                visibleDetectionLimit += 10
            }
            isLoadingCanonicalHistory = false
        }
    }

    private var historyHeroCard: some View {
        VStack(alignment: .leading, spacing: 14) {
            HStack(alignment: .firstTextBaseline) {
                VStack(alignment: .leading, spacing: 4) {
                    Text("History")
                        .font(.system(size: 32, weight: .bold, design: .rounded))
                    Text(snapshot.sessions.isEmpty
                         ? "Saved trends and session detail appear here once you finish a session."
                         : "A lighter archive for saved sessions, trends, and local activity evidence.")
                        .font(.subheadline)
                        .foregroundStyle(.secondary)
                        .fixedSize(horizontal: false, vertical: true)
                }
                Spacer(minLength: 12)
                Text("\(snapshot.sessions.count)")
                    .font(.system(size: 34, weight: .bold, design: .rounded).monospacedDigit())
            }

            HStack(spacing: 12) {
                HistoryQuickStat(label: "Sessions", value: "\(snapshot.sessions.count)")
                HistoryQuickStat(label: "Detected", value: "\(snapshot.detections.count)")
                HistoryQuickStat(label: "Baseline", value: "\(projectionStore.hrvBaselineSampleCount)/\(PersonalBaseline.trustedMinimumSamples)")
            }
        }
        .padding(18)
        .atriaCard(cornerRadius: 22, emphasis: .soft)
    }

    private func historySection<Content: View>(title: String,
                                               subtitle: String,
                                               @ViewBuilder content: () -> Content) -> some View {
        VStack(alignment: .leading, spacing: 12) {
            VStack(alignment: .leading, spacing: 3) {
                Text(title)
                    .font(.title3.weight(.semibold))
                Text(subtitle)
                    .font(.subheadline)
                    .foregroundStyle(.secondary)
            }
            .frame(maxWidth: .infinity, alignment: .leading)

            content()
        }
        .padding(18)
        .atriaCard(cornerRadius: 22, emphasis: .soft)
    }

    private func historySessionRow(_ row: HistorySessionRowSnapshot) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            HStack(alignment: .firstTextBaseline) {
                Text(row.title)
                    .font(.headline.weight(.semibold))
                    .lineLimit(2)
                Spacer(minLength: 12)
                Text(row.start, style: .date)
                    .font(.caption)
                    .foregroundStyle(.secondary)
            }

            Text(row.summaryText)
                .font(.caption)
                .foregroundStyle(.secondary)

            HStack(spacing: 10) {
                historySessionPill("HRV", value: row.hrvText, tint: .purple)
                historySessionPill("Samples", value: row.samplesText, tint: .cyan)
                historySessionPill("TRIMP", value: row.trimpText, tint: .orange)
            }
        }
        .padding(16)
        .atriaInsetCard(cornerRadius: 22, tint: .white)
    }

    private func historySessionPill(_ label: String, value: String, tint: Color) -> some View {
        VStack(alignment: .leading, spacing: 3) {
            Text(label)
                .font(.caption2.weight(.semibold))
                .foregroundStyle(.secondary)
            Text(value)
                .font(.caption.weight(.semibold).monospacedDigit())
                .lineLimit(1)
                .minimumScaleFactor(0.8)
        }
        .frame(maxWidth: .infinity, alignment: .leading)
        .padding(.horizontal, 12)
        .padding(.vertical, 10)
        .background(HistoryPillBackground(tint: tint))
    }

    #if DEBUG
    private static func debugFixtureSleepReviewNight(arguments: [String]) -> SleepHistorySnapshot.Night? {
        guard let fixtureIndex = arguments.firstIndex(of: "--atria-ui-fixture") else { return nil }
        let valueIndex = arguments.index(after: fixtureIndex)
        guard arguments.indices.contains(valueIndex),
              arguments[valueIndex] == "history-sleep-review" else {
            return nil
        }

        let calendar = Calendar.current
        let end = calendar.date(bySettingHour: 7, minute: 18, second: 0, of: Date()) ?? Date()
        let start = calendar.date(byAdding: .minute, value: -438, to: end) ?? end.addingTimeInterval(-438 * 60)
        return SleepHistorySnapshot.Night(id: "debug-ui-fixture-history-sleep-review",
                                          day: calendar.startOfDay(for: end),
                                          start: start,
                                          end: end,
                                          duration: 438 * 60,
                                          restingHR: 54,
                                          hrv: 72,
                                          respiratoryRate: 14.6,
                                          sleepEfficiency: 0.89,
                                          confidence: "review_needed",
                                          source: "sleep_candidate",
                                          confirmed: false,
                                          stageSegments: [])
    }

    private static func debugFixtureHistorySnapshot(arguments: [String]) -> HistorySnapshot? {
        guard let fixtureIndex = arguments.firstIndex(of: "--atria-ui-fixture") else { return nil }
        let valueIndex = arguments.index(after: fixtureIndex)
        guard arguments.indices.contains(valueIndex),
              ["history-activity-rhythm", "history-sleep-review"].contains(arguments[valueIndex]) else {
            return nil
        }

        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())
        let rollups: [DailyRollup] = (0..<14).map { offset in
            let day = calendar.date(byAdding: .day, value: -offset, to: today) ?? today
            let hasWorkout = [1, 4, 8].contains(offset)
            let needsReview = [2, 6].contains(offset)
            let sleepContext = offset % 3 == 0
            return DailyRollup(day: day,
                               sessions: hasWorkout || needsReview || sleepContext ? 2 : 1,
                               activityCandidates: needsReview ? 1 : 0,
                               workouts: hasWorkout ? 1 : 0,
                               confirmedWorkouts: hasWorkout && offset != 8 ? 1 : 0,
                               restCandidates: offset == 10 ? 1 : 0,
                               sleepReady: sleepContext ? 1 : 0,
                               sleepCandidates: offset == 5 ? 1 : 0,
                               duration: TimeInterval((hasWorkout ? 78 : 32) * 60),
                               sleepDuration: sleepContext ? TimeInterval(7 * 60 * 60) : nil,
                               sleepSpan: nil,
                               sleepStart: nil,
                               sleepEnd: nil,
                               sleepSource: sleepContext ? "debug_fixture" : nil,
                               sleepStageSegments: [],
                               strain: hasWorkout ? 13.6 : (needsReview ? 8.8 : Double([2, 4, 3, 5][offset % 4])),
                               avgHRV: 68,
                               restingHR: 56,
                               avgRespiratoryRate: 14.8)
        }

        let start = today.addingTimeInterval(-90 * 60)
        let session = SavedSession(id: UUID(),
                                   start: start,
                                   end: today.addingTimeInterval(-12 * 60),
                                   label: "Strength",
                                   points: [
                                    SavedSession.Point(t: 0, bpm: 88),
                                    SavedSession.Point(t: 900, bpm: 132),
                                    SavedSession.Point(t: 1_800, bpm: 156),
                                    SavedSession.Point(t: 3_600, bpm: 118)
                                   ],
                                   hrv: 72)
        return HistorySnapshot(sessions: [session],
                               detections: [],
                               trends: [],
                               rollups: rollups,
                               maxHR: 190)
    }
    #endif
}

private struct HistorySleepReviewCTA: View, Equatable {
    let night: SleepHistorySnapshot.Night
    let onConfirm: () async -> Bool
    let onAdjust: () -> Void
    @State private var confirmationFailed = false
    @State private var isConfirming = false

    static func == (lhs: HistorySleepReviewCTA, rhs: HistorySleepReviewCTA) -> Bool {
        lhs.night == rhs.night
    }

    private var tint: Color {
        night.isNapEvidence ? .indigo : .cyan
    }

    private var title: String {
        night.isNapEvidence ? "Review nap" : "Review sleep"
    }

    private var stateText: String {
        night.isNapEvidence ? "Separate" : "Not counted"
    }

    private var timeText: String {
        guard let start = night.start, let end = night.end else { return night.confirmationText }
        return "\(start.formatted(date: .omitted, time: .shortened))-\(end.formatted(date: .omitted, time: .shortened))"
    }

    private var progress: Double {
        let targetHours = night.isNapEvidence ? 1.5 : 8.0
        return min(max(night.durationHours / targetHours, 0.08), 1)
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            HStack(spacing: 12) {
                ZStack {
                    Circle()
                        .stroke(tint.opacity(0.14), lineWidth: 5)
                    Circle()
                        .trim(from: 0, to: progress)
                        .stroke(tint.opacity(0.92),
                                style: StrokeStyle(lineWidth: 5, lineCap: .round))
                        .rotationEffect(.degrees(-90))
                    Image(systemName: night.isNapEvidence ? "moon.zzz.fill" : "bed.double.fill")
                        .font(.caption.weight(.black))
                        .foregroundStyle(tint)
                }
                .frame(width: 42, height: 42)

                VStack(alignment: .leading, spacing: 3) {
                    Text(title)
                        .font(.headline.weight(.semibold))
                    Text(timeText)
                        .font(.caption.weight(.medium))
                        .foregroundStyle(.secondary)
                }

                Spacer(minLength: 0)

                VStack(alignment: .trailing, spacing: 3) {
                    Text(night.durationText)
                        .font(.title3.weight(.black).monospacedDigit())
                    Text(stateText)
                        .font(.caption2.weight(.bold))
                        .foregroundStyle(tint)
                }
            }

            HStack(spacing: 8) {
                Button(action: onAdjust) {
                    Label("Adjust", systemImage: "slider.horizontal.3")
                        .font(.caption.weight(.semibold))
                        .frame(maxWidth: .infinity)
                }
                .atriaCardAction(prominent: false, tint: tint)

                Button {
                    isConfirming = true
                    Task { @MainActor in
                        confirmationFailed = !(await onConfirm())
                        isConfirming = false
                    }
                } label: {
                    Label(night.isNapEvidence ? "Confirm nap" : "Confirm sleep",
                          systemImage: "checkmark.circle")
                        .font(.caption.weight(.semibold))
                        .frame(maxWidth: .infinity)
                }
                .atriaCardAction(tint: tint)
                .disabled(isConfirming)
            }

            if confirmationFailed {
                Label("Couldn't save. This suggestion is still available — try again, or adjust its window.",
                      systemImage: "exclamationmark.triangle.fill")
                    .font(.caption.weight(.semibold))
                    .foregroundStyle(.orange)
                    .fixedSize(horizontal: false, vertical: true)
                    .accessibilityLabel("Couldn't save sleep. The suggestion remains available. Try again or adjust the detected window.")
            }
        }
        .padding(16)
        .atriaCard(cornerRadius: 22, emphasis: .soft)
        // Keep Adjust and Confirm as independent VoiceOver actions. Combining
        // this interactive card turns both buttons into one static element.
        .accessibilityElement(children: .contain)
        .accessibilityLabel("History sleep review. \(night.durationText), \(timeText), \(stateText). Confirm or adjust.")
        .onChange(of: night.id) { _, _ in
            confirmationFailed = false
        }
    }
}

struct HistorySnapshot {
    let sessions: [SavedSession]
    let sessionRows: [HistorySessionRowSnapshot]
    let restingTrendPoints: [RestingTrendPoint]
    let detections: [ActivityDetection]
    let trends: [TrendSummary]
    let rollups: [DailyRollup]
    /// Exact recovered step days only. Missing/partial canonical evidence is
    /// absent, never represented as zero.
    let verifiedHistoricalStepDays: [AtriaHistoricalDailyConsumerProjection.StepDay]
    /// Includes verified partial lower bounds for explicitly labelled archive
    /// coverage. Consumers must not promote these to complete-day totals.
    let verifiedHistoricalStepEvidenceDays: [AtriaHistoricalDailyConsumerProjection.StepDay]
    /// Confirms the replay-identity destination was consumed without retaining
    /// a second in-memory copy of every stable key.
    let verifiedReplayIdentityRowCount: Int
    /// Retained only for pages the user has requested. This lets a subsequent
    /// page rebuild consistent sleep/activity/strain projections without
    /// rescanning prior destination files.
    let verifiedCanonicalSources: [HistoricalArchive.VerifiedCanonicalConsumerSource]
    let verifiedCanonicalPageCursor: AtriaHistoricalAggregateReader.PageCursor?
    let verifiedCanonicalHistoryHasMore: Bool

    static let empty = HistorySnapshot(sessions: [], detections: [], trends: [], rollups: [], rest: 60, maxHR: 200)

    static func sessionsOnly(
        _ sessions: [SavedSession],
        verifiedHistoricalStepEvidenceDays: [AtriaHistoricalDailyConsumerProjection.StepDay] = [],
        rest: Int = 60,
        maxHR: Int
    ) -> HistorySnapshot {
        HistorySnapshot(sessions: sessions,
                        detections: [],
                        trends: [],
                        rollups: [],
                        verifiedHistoricalStepEvidenceDays:
                            verifiedHistoricalStepEvidenceDays,
                        rest: rest,
                        maxHR: maxHR,
                        includeDerivedSessionRows: false)
    }

    init(sessions: [SavedSession],
         detections: [ActivityDetection],
         trends: [TrendSummary],
         rollups: [DailyRollup],
         verifiedHistoricalStepDays: [AtriaHistoricalDailyConsumerProjection.StepDay] = [],
         verifiedHistoricalStepEvidenceDays: [AtriaHistoricalDailyConsumerProjection.StepDay] = [],
         verifiedReplayIdentityRowCount: Int = 0,
         verifiedCanonicalSources: [HistoricalArchive.VerifiedCanonicalConsumerSource] = [],
         verifiedCanonicalPageCursor: AtriaHistoricalAggregateReader.PageCursor? = nil,
         verifiedCanonicalHistoryHasMore: Bool = false,
         rest: Int = 60,
         maxHR: Int,
         includeDerivedSessionRows: Bool = true) {
        self.sessions = sessions
        self.sessionRows = sessions.map {
            HistorySessionRowSnapshot(session: $0,
                                      rest: rest,
                                      maxHR: maxHR,
                                      includeDerivedMetrics: includeDerivedSessionRows)
        }
        self.restingTrendPoints = includeDerivedSessionRows
            ? Self.makeRestingTrendPoints(sessions)
            : []
        self.detections = detections
        self.trends = trends
        self.rollups = rollups
        self.verifiedHistoricalStepDays = verifiedHistoricalStepDays
        self.verifiedHistoricalStepEvidenceDays = verifiedHistoricalStepEvidenceDays
        self.verifiedReplayIdentityRowCount = max(0, verifiedReplayIdentityRowCount)
        self.verifiedCanonicalSources = verifiedCanonicalSources
        self.verifiedCanonicalPageCursor = verifiedCanonicalPageCursor
        self.verifiedCanonicalHistoryHasMore = verifiedCanonicalHistoryHasMore
    }

    func replacingTrends(_ trends: [TrendSummary]) -> HistorySnapshot {
        HistorySnapshot(copying: self, trends: trends)
    }

    private init(copying source: HistorySnapshot, trends: [TrendSummary]) {
        sessions = source.sessions
        sessionRows = source.sessionRows
        restingTrendPoints = source.restingTrendPoints
        detections = source.detections
        self.trends = trends
        rollups = source.rollups
        verifiedHistoricalStepDays = source.verifiedHistoricalStepDays
        verifiedHistoricalStepEvidenceDays =
            source.verifiedHistoricalStepEvidenceDays
        verifiedReplayIdentityRowCount = source.verifiedReplayIdentityRowCount
        verifiedCanonicalSources = source.verifiedCanonicalSources
        verifiedCanonicalPageCursor = source.verifiedCanonicalPageCursor
        verifiedCanonicalHistoryHasMore =
            source.verifiedCanonicalHistoryHasMore
    }

    /// Exact recovery updates the canonical sensor sessions and affected-day
    /// aggregates without synchronously rebuilding every historical detail row.
    /// Existing detail rows remain truthful for their already-published
    /// sessions and a later ordinary history refresh may expand the new rows.
    init(
        recoveredSessions: [SavedSession],
        detections: [ActivityDetection],
        trends: [TrendSummary],
        rollups: [DailyRollup],
        verifiedHistoricalStepDays:
            [AtriaHistoricalDailyConsumerProjection.StepDay]? = nil,
        verifiedHistoricalStepEvidenceDays:
            [AtriaHistoricalDailyConsumerProjection.StepDay]? = nil,
        verifiedReplayIdentityRowCount: Int? = nil,
        verifiedCanonicalSources:
            [HistoricalArchive.VerifiedCanonicalConsumerSource]? = nil,
        verifiedCanonicalPageCursor:
            AtriaHistoricalAggregateReader.PageCursor? = nil,
        replaceVerifiedCanonicalPageCursor: Bool = false,
        verifiedCanonicalHistoryHasMore: Bool? = nil,
        preservingPresentationFrom source: HistorySnapshot
    ) {
        sessions = recoveredSessions
        sessionRows = source.sessionRows
        restingTrendPoints = source.restingTrendPoints
        self.detections = detections
        self.trends = trends
        self.rollups = rollups
        self.verifiedHistoricalStepDays = verifiedHistoricalStepDays
            ?? source.verifiedHistoricalStepDays
        self.verifiedHistoricalStepEvidenceDays =
            verifiedHistoricalStepEvidenceDays
                ?? source.verifiedHistoricalStepEvidenceDays
        self.verifiedReplayIdentityRowCount =
            verifiedReplayIdentityRowCount
                ?? source.verifiedReplayIdentityRowCount
        self.verifiedCanonicalSources = verifiedCanonicalSources
            ?? source.verifiedCanonicalSources
        self.verifiedCanonicalPageCursor = replaceVerifiedCanonicalPageCursor
            ? verifiedCanonicalPageCursor
            : source.verifiedCanonicalPageCursor
        self.verifiedCanonicalHistoryHasMore =
            verifiedCanonicalHistoryHasMore
                ?? source.verifiedCanonicalHistoryHasMore
    }

    private static func makeRestingTrendPoints(_ sessions: [SavedSession]) -> [RestingTrendPoint] {
        sessions
            .sorted { $0.start < $1.start }
            .map { RestingTrendPoint(id: $0.id, start: $0.start, resting: $0.restingStable) }
    }
}

struct HistorySessionRowSnapshot: Identifiable {
    let session: SavedSession
    let id: UUID
    let title: String
    let start: Date
    let summaryText: String
    let hrvText: String
    let samplesText: String
    let trimpText: String

    init(session: SavedSession, rest: Int, maxHR: Int, includeDerivedMetrics: Bool) {
        self.session = session
        id = session.id
        title = session.label.isEmpty ? "Session" : session.label
        start = session.start
        hrvText = session.hrv.map(String.init) ?? "Learning"
        samplesText = "\(session.points.count)"
        guard includeDerivedMetrics else {
            summaryText = "\(session.durationText) · \(session.points.count) samples"
            trimpText = "..."
            return
        }
        let bpms = session.points.map(\.bpm)
        let avg = bpms.isEmpty ? 0 : bpms.reduce(0, +) / bpms.count
        let peak = bpms.max() ?? 0
        let resting = bpms.min() ?? 0
        summaryText = "\(session.durationText) · avg \(avg) · peak \(peak) · rest \(resting)"
        let resolvedRest = max(1, rest)
        let resolvedMaxHR = max(maxHR, resolvedRest + 1)
        trimpText = String(format: "%.1f", session.trimp(rest: resolvedRest, max: resolvedMaxHR))
    }
}

struct SleepHistorySnapshot: Equatable {
    /// Sleep detail renders a twelve-week heat strip and cold-session retention
    /// keeps roughly the same horizon resident. Keep enough compact nightly
    /// projections to make that history real while leaving raw samples in the
    /// paged/archive stores.
    static let maximumResidentNightCount = 84

    struct Night: Identifiable, Equatable {
        let id: String
        let day: Date
        /// Durable confirmation time. Candidate projections intentionally leave
        /// this nil; a confirmed row must not pretend its wake time was its save
        /// time when settlement finished later.
        let savedAt: Date?
        let start: Date?
        let end: Date?
        /// Sensor-observed coverage retained independently from physiological
        /// total sleep time. `duration` becomes non-awake staged time when a
        /// valid hypnogram exists, but boundary/recovery eligibility must keep
        /// using this original measurement authority.
        let observedDuration: TimeInterval
        let duration: TimeInterval
        let restingHR: Int?
        let hrv: Int?
        let hrvWindowCount: Int
        let respiratoryRate: Double?
        let sleepEfficiency: Double?
        let confidence: String
        let source: String
        let confirmed: Bool
        let stageSegments: [SleepStageSegment]
        let displayStageSegments: [SleepStageSegment]
        let stageEvidence: SleepStageEvidence
        let eventTimeZoneIdentifier: String?
        /// The original main-sleep target, if this night settled after Need
        /// freezing shipped. `nil` is an intentional legacy-data gap.
        let sleepNeedSeconds: TimeInterval?
        let frozenSleepNeed: AtriaSleepBudget.FrozenNeed?
        /// Explicit motion-validation provenance where the builder knows it
        /// (confirmed records carry `UserConfirmedSleep.motionValidated`;
        /// review candidates carry `motionEvidenceValidated`). nil = unknown
        /// legacy path; presentation then falls back to the same
        /// confidence/stage derivation `resumedSleepCandidate` already uses.
        let motionValidated: Bool?
        /// `motionValidated` means the whole window met the low-motion sleep
        /// policy; it is not the same thing as proof that time-aligned motion
        /// measurements backed every displayed stage. A v2 research timeline
        /// can contain honest awake/moving epochs and therefore carry this
        /// separate, fail-closed receipt.
        private let hasTimeAlignedResearchStageReceipt: Bool
        private let stageDurationsByStage: [SleepStageKind: TimeInterval]
        /// The durable "which is your main sleep?" answer. Compact snapshots
        /// must carry it so the boundary rehydrations (`AtriaPhysiologicalDay`
        /// and the historical cycle) compute the exact same physiological-day
        /// anchor as the durable store — without it, Activity/Today windows and
        /// SessionStore's cycle can disagree on the same data.
        let dayPrimaryChoice: Bool?

        init(id: String,
             day: Date,
             savedAt: Date? = nil,
             start: Date? = nil,
             end: Date? = nil,
             duration: TimeInterval,
             observedDuration: TimeInterval? = nil,
             restingHR: Int?,
             hrv: Int?,
             hrvWindowCount: Int = 0,
             respiratoryRate: Double?,
             sleepEfficiency: Double?,
             confidence: String,
             source: String,
             confirmed: Bool,
             stageSegments: [SleepStageSegment],
             eventTimeZoneIdentifier: String? = nil,
             motionValidated: Bool? = nil,
             sleepNeedSeconds: TimeInterval? = nil,
             frozenSleepNeed: AtriaSleepBudget.FrozenNeed? = nil,
             dayPrimaryChoice: Bool? = nil) {
            self.id = id
            self.day = day
            self.savedAt = savedAt
            self.start = start
            self.end = end
            self.duration = duration
            self.observedDuration = observedDuration ?? duration
            self.restingHR = restingHR
            self.hrv = hrv
            self.hrvWindowCount = hrvWindowCount
            self.respiratoryRate = respiratoryRate
            self.sleepEfficiency = sleepEfficiency
            self.confidence = confidence
            self.source = source
            self.confirmed = confirmed
            self.stageSegments = stageSegments
            self.eventTimeZoneIdentifier = eventTimeZoneIdentifier
            self.motionValidated = motionValidated
            self.frozenSleepNeed = frozenSleepNeed
            self.sleepNeedSeconds = frozenSleepNeed?.seconds
                ?? sleepNeedSeconds.flatMap { $0 > 0 ? $0 : nil }
            self.dayPrimaryChoice = dayPrimaryChoice

            let stagesPassIntegrity: Bool
            if let start, let end, !stageSegments.isEmpty {
                stagesPassIntegrity = AtriaSleepStageIntegrity.validates(
                    stageSegments,
                    start: start,
                    end: end,
                    duration: duration,
                    span: end.timeIntervalSince(start)
                )
            } else {
                stagesPassIntegrity = !stageSegments.isEmpty
            }
            let stagesReconcileWithEpisode = stagesPassIntegrity
                && AtriaSleepStageIntegrity.reconcilesForPresentation(
                    stageSegments,
                    effectiveSleepDuration: duration
                )
            let timeAlignedResearchStageReceipt = stagesReconcileWithEpisode
                && stageSegments.allSatisfy {
                    $0.id.hasPrefix("research-motion-v2-")
                }
            self.hasTimeAlignedResearchStageReceipt = timeAlignedResearchStageReceipt
            var evidence = Self.stageEvidence(source: source,
                                              confirmed: confirmed,
                                              hasSegments: stagesReconcileWithEpisode)
            // HR-only honesty (2026-08-01, presentation only — stored
            // segments stay untouched): heart rate alone cannot separate
            // sleep stages, so a sensor-research hypnogram without validated
            // motion previously rendered as a confident all-deep band. Fold
            // it into an explicit "needs motion data" state instead.
            // Widened 2026-08-05: a manual window with backfilled HR-only
            // segments previously resolved to .manualEstimate, skipped this
            // motion gate entirely, and rendered a confident hypnogram from
            // HR alone — the exact failure mode this gate exists to stop.
            if evidence == .sensorResearch || evidence == .manualEstimate,
               !timeAlignedResearchStageReceipt,
               !Self.hasValidatedMotionEvidence(motionValidated: motionValidated,
                                                confidence: confidence,
                                                stageEvidence: evidence) {
                evidence = .hrOnlyEstimate
            }
            // Preserve an honest HR-only state even when the raw stage engine's
            // awake-heavy output fails presentation reconciliation. The raw
            // segments remain available to storage/research, but presentation
            // exposes only the estimated asleep window and measured HR context —
            // never Awake/REM/Light/Deep epochs, durations, or percentages.
            // Validated-motion nights still use the unchanged real-stage path.
            if evidence == .none,
               !Self.hasValidatedMotionEvidence(motionValidated: motionValidated,
                                                confidence: confidence,
                                                stageEvidence: evidence),
               Self.qualifiesForHROnlyEstimate(source: source,
                                               stageSegments: stageSegments,
                                               stagesPassIntegrity: stagesPassIntegrity) {
                evidence = .hrOnlyEstimate
            }
            // Estimate provenance is encoded in the segment ids themselves
            // (`research-hr-estimate-v1-` / `research-hr-estimate-rr90-v1-`;
            // the strong-RR tier is the same estimate lane through the same
            // choke point). No record-level flag — not a legacy
            // `motionValidated == true`, not a "ready" confidence —
            // may promote HR-only estimate bars to validated-style authority.
            // Contradictory records fail toward the estimate label.
            if evidence != .none,
               SleepStageSegment.allHREstimateProvenance(stageSegments) {
                evidence = .hrOnlyEstimate
            }
            self.stageEvidence = evidence
            if evidence == .hrOnlyEstimate {
                // Labeled HR-only ESTIMATE (2026-08-12, c7c15e1d product): a
                // confirmed HR-only night with a structurally valid timeline
                // renders a real hypnogram again — but only through a
                // display-only reconciliation of the engine's over-called
                // awake, and only on surfaces that show the mandatory
                // `AtriaSleepStageEstimateLabel`. Stored segments stay
                // untouched; failures fall closed to the generic estimate.
                self.displayStageSegments = Self.reconciledHROnlyDisplaySegments(
                    folded: Self.foldedDisplaySegments(from: stageSegments),
                    effectiveSleepDuration: duration,
                    start: start,
                    end: end,
                    confirmed: confirmed,
                    source: source,
                    stagesPassIntegrity: stagesPassIntegrity)
            } else {
                self.displayStageSegments = evidence == .none
                    ? []
                    : Self.foldedDisplaySegments(from: stageSegments)
            }
            self.stageDurationsByStage = Self.stageDurations(from: displayStageSegments)
        }

        /// Single presentation authority for "does validated motion back this
        /// night?". Explicit provenance wins; otherwise fall back to the same
        /// confidence/stage derivation `resumeSleepCandidate` already trusts
        /// ("ready" rollups are motion-ready; validated stages imply motion).
        static func hasValidatedMotionEvidence(motionValidated: Bool?,
                                               confidence: String,
                                               stageEvidence: SleepStageEvidence) -> Bool {
            if stageEvidence == .validated { return true }
            if let motionValidated { return motionValidated }
            return confidence.caseInsensitiveCompare("ready") == .orderedSame
                || confidence.caseInsensitiveCompare("user_confirmed_motion_validated") == .orderedSame
        }

        var hasValidatedMotionEvidence: Bool {
            hasTimeAlignedResearchStageReceipt
                || Self.hasValidatedMotionEvidence(motionValidated: motionValidated,
                                                   confidence: confidence,
                                                   stageEvidence: stageEvidence)
        }

        /// Folded segments independent of the HR-only DISPLAY gate. Daily-
        /// metric persistence and sleep-credit computation must keep storing
        /// exactly what they stored before the 2026-08-01 presentation
        /// honesty pass. For `.hrOnlyEstimate` this is the folded RAW
        /// timeline — never the display-only reconciled estimate.
        var stageSegmentsForStorage: [SleepStageSegment] {
            stageEvidence == .hrOnlyEstimate
                ? Self.foldedDisplaySegments(from: stageSegments)
                : displayStageSegments
        }

        /// True when this night's rendered stage timeline is a display-only
        /// HR-only ESTIMATE (reconciled, not motion-validated). Every surface
        /// that renders these bars must show `AtriaSleepStageEstimateLabel`
        /// alongside them — the label is part of the presentation contract,
        /// not decoration.
        var isEstimatedStageDisplay: Bool {
            stageEvidence == .hrOnlyEstimate && !displayStageSegments.isEmpty
        }

        /// Display-confidence tier for the estimate label's caption
        /// (2026-08-20 design 1.2), derived purely from the RAW segment id
        /// prefixes — never a stored flag. `.strongRR` requires EVERY raw
        /// segment to carry the strong-RR prefix; mixed sets fail toward
        /// `.standard`. Meaningful only alongside `isEstimatedStageDisplay`;
        /// the tier changes caption copy only — the mandatory estimate
        /// label, duration-credit fence, and downgrade gates are
        /// tier-independent. (Display segments preserve incoming ids through
        /// folding/reconciliation, so raw prefixes are the one authority.)
        var estimateConfidenceTier: SleepStageEstimateConfidenceTier {
            SleepStageSegment.allStrongRREstimateProvenance(stageSegments)
                ? .strongRR
                : .standard
        }

        /// Per-night stage provenance label. Unlike `stageEvidence.label`
        /// this distinguishes an HR-only night that renders labeled estimate
        /// bars from one whose segments stay hidden ("Stages need motion
        /// data" would contradict visible bars; the estimate title would
        /// falsely promise bars on a hidden night).
        var stageDisplayLabel: String {
            isEstimatedStageDisplay ? AtriaSleepStageEstimateLabel.title : stageEvidence.label
        }

        /// The stored `sleepEfficiency` for an HR-only night is captured/span
        /// coverage, not sleep efficiency — an uninterrupted HR-only capture
        /// showed a false "100%". Display surfaces must use this instead:
        /// nil (rendered "--") until validated motion backs the number.
        var displaySleepEfficiency: Double? {
            hasValidatedMotionEvidence ? sleepEfficiency : nil
        }

        /// Plain-language companion for the efficiency tiles: says why the
        /// value is withheld instead of leaving an unexplained "--".
        var sleepEfficiencyFootnote: String {
            if sleepEfficiency != nil, !hasValidatedMotionEvidence {
                return "Needs motion data"
            }
            return "Duration-based estimate"
        }

        /// Collapses `.sws` into `.deep` for display and re-merges adjacent runs of the
        /// same displayed stage so the hypnogram/legend never show a stray `.sws` segment.
        /// `stageSegments` (raw, for storage/HealthKit) is left untouched by this transform.
        private static func foldedDisplaySegments(from segments: [SleepStageSegment]) -> [SleepStageSegment] {
            guard !segments.isEmpty else { return [] }
            var merged: [SleepStageSegment] = []
            for segment in segments {
                let displayStage = segment.stage.displayStage
                if let last = merged.last,
                   last.stage == displayStage,
                   segment.start.timeIntervalSince(last.end) <= 1 {
                    merged[merged.count - 1] = SleepStageSegment(id: last.id,
                                                                 start: last.start,
                                                                 end: max(last.end, segment.end),
                                                                 stage: displayStage)
                } else {
                    merged.append(SleepStageSegment(id: segment.id,
                                                    start: segment.start,
                                                    end: segment.end,
                                                    stage: displayStage))
                }
            }
            return merged
        }

        /// Display-only reconciliation for the labeled HR-only ESTIMATE
        /// hypnogram (2026-08-12, c7c15e1d product). The stage engine
        /// over-calls awake on HR-only nights, so the raw timeline's
        /// non-awake total under-runs the credited effective sleep duration
        /// and fails the strict presentation reconcile. Because the estimate
        /// presentation is explicitly labeled, it may reconcile FOR
        /// PRESENTATION ONLY: interior over-called awake folds into a
        /// neighboring sleep stage until displayed non-awake time matches
        /// `effectiveSleepDuration`, and any surplus is trimmed so the
        /// display can never exceed it. Stored segments are never modified.
        /// Fails closed (returns []) — back to the generic estimated-asleep
        /// window — for naps, unconfirmed candidates, manual windows,
        /// integrity-failing timelines, and gaps reconciliation cannot
        /// honestly close.
        private static func reconciledHROnlyDisplaySegments(folded: [SleepStageSegment],
                                                            effectiveSleepDuration: TimeInterval,
                                                            start: Date?,
                                                            end: Date?,
                                                            confirmed: Bool,
                                                            source: String,
                                                            stagesPassIntegrity: Bool) -> [SleepStageSegment] {
            guard confirmed,
                  stagesPassIntegrity,
                  !folded.isEmpty,
                  effectiveSleepDuration > 0,
                  let start, let end, end > start,
                  !explicitNapSources.contains(source),
                  !source.hasPrefix("manual_") else { return [] }

            func nonAwakeTotal(_ segments: [SleepStageSegment]) -> TimeInterval {
                segments.reduce(0) { $0 + ($1.stage == .awake ? 0 : $1.duration) }
            }

            var working = folded
            var deficit = effectiveSleepDuration - nonAwakeTotal(working)
            // Absorb interior over-called awake (a non-awake neighbor on at
            // least one side), shortest bout first, splitting the last one
            // so the displayed non-awake lands exactly on the effective
            // sleep duration. Boundary awake — falling asleep and waking —
            // is credible evidence and is left alone.
            while deficit > 1 {
                let candidates = working.indices.filter { index in
                    working[index].stage == .awake
                        && index > working.startIndex
                        && index < working.endIndex - 1
                        && (working[index - 1].stage != .awake || working[index + 1].stage != .awake)
                }.sorted { working[$0].duration < working[$1].duration }
                guard let index = candidates.first else { break }
                let awake = working[index]
                let absorbsBackward = working[index - 1].stage != .awake
                if awake.duration <= deficit + 1 {
                    deficit -= awake.duration
                    if absorbsBackward {
                        let neighbor = working[index - 1]
                        working[index - 1] = SleepStageSegment(id: neighbor.id,
                                                               start: neighbor.start,
                                                               end: awake.end,
                                                               stage: neighbor.stage)
                    } else {
                        let neighbor = working[index + 1]
                        working[index + 1] = SleepStageSegment(id: neighbor.id,
                                                               start: awake.start,
                                                               end: neighbor.end,
                                                               stage: neighbor.stage)
                    }
                    working.remove(at: index)
                } else {
                    if absorbsBackward {
                        let neighbor = working[index - 1]
                        working[index - 1] = SleepStageSegment(id: neighbor.id,
                                                               start: neighbor.start,
                                                               end: neighbor.end.addingTimeInterval(deficit),
                                                               stage: neighbor.stage)
                        working[index] = SleepStageSegment(id: awake.id,
                                                           start: awake.start.addingTimeInterval(deficit),
                                                           end: awake.end,
                                                           stage: .awake)
                    } else {
                        let neighbor = working[index + 1]
                        working[index + 1] = SleepStageSegment(id: neighbor.id,
                                                               start: neighbor.start.addingTimeInterval(-deficit),
                                                               end: neighbor.end,
                                                               stage: neighbor.stage)
                        working[index] = SleepStageSegment(id: awake.id,
                                                           start: awake.start,
                                                           end: awake.end.addingTimeInterval(-deficit),
                                                           stage: .awake)
                    }
                    deficit = 0
                }
            }
            // Cap: displayed non-awake must never exceed the credited
            // effective sleep. Surplus trims from the end of the timeline —
            // the excess is uncredited, so it renders as nothing rather
            // than as fabricated wakefulness.
            var surplus = nonAwakeTotal(working) - effectiveSleepDuration
            var index = working.endIndex - 1
            while surplus > 1, index >= working.startIndex {
                let segment = working[index]
                if segment.stage != .awake {
                    if segment.duration <= surplus + 1 {
                        surplus -= segment.duration
                        working.remove(at: index)
                    } else {
                        working[index] = SleepStageSegment(id: segment.id,
                                                           start: segment.start,
                                                           end: segment.end.addingTimeInterval(-surplus),
                                                           stage: segment.stage)
                        surplus = 0
                    }
                }
                index -= 1
            }
            // Publish only when the estimate now reconciles with the same
            // effective-sleep authority the hero and Recovery use.
            let display = foldedDisplaySegments(from: working)
            guard nonAwakeTotal(display) <= effectiveSleepDuration + 1,
                  AtriaSleepStageIntegrity.reconcilesForPresentation(
                      display,
                      effectiveSleepDuration: effectiveSleepDuration
                  ) else { return [] }
            return display
        }

        var durationHours: Double {
            max(0, duration / 3_600)
        }

        var durationText: String {
            SleepHistorySnapshot.formatDuration(duration)
        }

        var restingHRText: String {
            restingHR.map { "\($0)" } ?? "--"
        }

        var hrvText: String {
            hrv.map { "\($0)" } ?? "--"
        }

        var respiratoryRateText: String {
            respiratoryRate.map { String(format: "%.1f", $0) } ?? "--"
        }

        var sleepEfficiencyText: String {
            // HR-only honesty (2026-08-01): without validated motion the
            // stored value is span coverage, not efficiency — show "--".
            displaySleepEfficiency.map { "\(Int(($0 * 100).rounded()))%" } ?? "--"
        }

        var confidenceText: String {
            confirmed ? "confirmed" : confidence.replacingOccurrences(of: "_", with: " ")
        }

        private var observedSpan: TimeInterval {
            guard let start, let end, end > start else { return duration }
            return max(duration, end.timeIntervalSince(start))
        }

        private var fitsNapCandidateWindow: Bool {
            duration >= AggregateSleepCandidate.napMinimumDuration
                && duration <= AggregateSleepCandidate.napMaximumSpan
                && observedSpan <= AggregateSleepCandidate.napMaximumSpan
        }

        private var fitsInferredDaytimeNapWindow: Bool {
            guard fitsNapCandidateWindow, let start, let end, end > start else { return false }
            let calendar = EventCivilTime.eventCalendar(timeZoneIdentifier: eventTimeZoneIdentifier,
                                                         fallback: .current)
            let startHour = calendar.component(.hour, from: start)
            let endHour = calendar.component(.hour, from: end)
            return startHour >= 11 && endHour <= 20
        }

        private var fitsMainSleepReviewWindow: Bool {
            if duration >= AggregateSleepCandidate.strictMinimumDuration { return true }
            // A fragmented sub-3h window is reviewable only when its rollup was
            // motion-ready. HR-only quiet awake time otherwise produced false
            // “Sleep detected” cards at this exact threshold.
            return confidence.caseInsensitiveCompare("ready") == .orderedSame
                && duration >= AggregateSleepCandidate.fragmentedMinimumDuration
                && observedSpan >= AggregateSleepCandidate.fragmentedMinimumSpan
        }

        var reviewReferenceDate: Date {
            end ?? start ?? day
        }

        fileprivate var isShortNapReviewCandidate: Bool {
            isNapEvidence && fitsNapCandidateWindow
        }

        fileprivate var isMainSleepReviewCandidate: Bool {
            guard !confirmed, !isNapEvidence else { return false }
            return fitsMainSleepReviewWindow
        }

        var isNapEvidence: Bool {
            if !confirmed && Self.reviewPromotableNapSources.contains(source) && fitsMainSleepReviewWindow {
                return false
            }
            if Self.explicitNapSources.contains(source) { return true }
            if !confirmed && Self.napSizedSleepCandidateSources.contains(source) && fitsInferredDaytimeNapWindow {
                return true
            }
            if Self.explicitSleepSources.contains(source) { return false }
            return !confirmed && fitsInferredDaytimeNapWindow
        }

        /// Hand-typed windows (2026-08-05): deliberately NOT the wider
        /// `isUserAuthoredSleepSource` — `user_adjusted_*` legitimately keeps
        /// sensor-derived stages, while `manual_*` never earns them.
        var isManualEntry: Bool { source.hasPrefix("manual_") }

        var evidenceLabel: String {
            isNapEvidence ? "Nap" : "Sleep"
        }

        var evidenceOnlyFootnote: String {
            isNapEvidence ? "Nap-only estimate" : "Sleep-only estimate"
        }

        var confirmationText: String {
            if confirmed {
                return isNapEvidence ? "Confirmed nap" : "Confirmed sleep"
            }
            if source == "resumed_sleep_candidate" {
                return "Additional sleep candidate"
            }
            return isNapEvidence ? "Nap candidate" : "Sleep candidate"
        }

        var reviewContextText: String {
            if source == "resumed_sleep_candidate" {
                return "Possible resumed sleep. Confirm to link it with your earlier sleep; the awake gap is not counted."
            }
            if source == "resumed_sleep" {
                return "Confirmed resumed sleep. Linked into one sleep episode; only recorded sleep is added and the awake gap is not counted."
            }
            if isNapEvidence {
                return confirmed
                    ? "Confirmed nap. Kept separate from main sleep."
                    : "Nap candidate. Kept separate from main sleep unless you adjust it."
            }
            return confirmed
                ? "Confirmed sleep. Used for sleep history and recovery."
                : "Sleep candidate. Review before it affects recovery."
        }

        func stageDuration(_ stage: SleepStageKind) -> TimeInterval {
            stageDurationsByStage[stage] ?? 0
        }

        func stageText(_ stage: SleepStageKind) -> String {
            SleepHistorySnapshot.formatDuration(stageDuration(stage))
        }

        private static func stageEvidence(source: String,
                                          confirmed: Bool,
                                          hasSegments: Bool) -> SleepStageEvidence {
            guard hasSegments else { return .none }
            if source == "manual_sleep" || source == "manual_nap" {
                return .manualEstimate
            }
            if source == "validated_sleep_stages" {
                return .validated
            }
            return .sensorResearch
        }

        /// A structurally-valid HR-only research timeline that fails the strict
        /// stage reconcile can still establish that this is an HR-only estimate.
        /// Its stage output remains withheld; only the generic asleep window may
        /// render. Manual windows are excluded, and a `validated_sleep_stages`
        /// night is never downgraded to an estimate.
        private static func qualifiesForHROnlyEstimate(source: String,
                                                       stageSegments: [SleepStageSegment],
                                                       stagesPassIntegrity: Bool) -> Bool {
            stagesPassIntegrity
                && !stageSegments.isEmpty
                && source != "validated_sleep_stages"
                && source != "manual_sleep"
                && source != "manual_nap"
        }

        private static func stageDurations(from segments: [SleepStageSegment]) -> [SleepStageKind: TimeInterval] {
            var totals: [SleepStageKind: TimeInterval] = [:]
            for segment in segments {
                totals[segment.stage, default: 0] += segment.duration
            }
            return totals
        }

        fileprivate static let explicitNapSources: Set<String> = [
            "manual_nap",
            "auto_nap",
            "nap_candidate",
            "hr_only_nap",
            "user_adjusted_nap"
        ]

        fileprivate static let explicitSleepSources: Set<String> = [
            "manual_sleep",
            "auto_sleep",
            "auto_confirmed_sleep",
            "auto_confirmed_sleep_hr_only",
            "aggregate_sleep",
            "sleep_window",
            "validated_sleep_window",
            "overnight_sleep",
            "sleep_candidate",
            "single_session_sleep_candidate",
            "incomplete_fragmented_sleep",
            "resumed_sleep_candidate",
            "resumed_sleep",
            "user_adjusted_sleep"
        ]

        private static let napSizedSleepCandidateSources: Set<String> = [
            "sleep_candidate",
            "single_session_sleep_candidate",
            "incomplete_fragmented_sleep"
        ]

        private static let reviewPromotableNapSources: Set<String> = [
            "nap_candidate",
            "hr_only_nap"
        ]
    }

    let nights: [Night]
    /// Extra confirmed main-sleep records that share a civil day with the
    /// canonical longest sleep. They stay out of recovery/trend calculations,
    /// but Activity must retain them so every durable record can be edited or
    /// deleted instead of becoming invisible behind a day-keyed dictionary.
    let additionalMainNights: [Night]
    /// Confirmed naps kept out of `nights`'s day-keyed dictionary so a same-calendar-day
    /// main sleep never evicts a nap (and vice versa). See sameDayNapHours(for:).
    let napNights: [Night]
    let confirmedCount: Int
    let candidateCount: Int
    let respiratoryBaselineMean: Double?
    let respiratoryBaselineCount: Int
    let averageDurationText: String
    let evidenceCountText: String
    let averageFootnoteText: String
    let sleepConsistencyText: String
    let sleepConsistencyFootnote: String
    let sleepConsistencyPercent: Int?
    let recentSleepAverageDurationHours: Double?
    let recentSleepRecordCount: Int

    static let empty = SleepHistorySnapshot(nights: [], confirmedCount: 0, candidateCount: 0)

    init(nights: [Night], confirmedCount: Int, candidateCount: Int) {
        let baselineValues = nights
            .dropFirst()
            .filter { $0.confirmed && !$0.isNapEvidence }
            .compactMap(\.respiratoryRate)
            .filter { $0 > 0 }
        self.nights = nights
        self.additionalMainNights = []
        self.napNights = nights.filter(\.isNapEvidence)
        self.confirmedCount = confirmedCount
        self.candidateCount = candidateCount
        self.respiratoryBaselineCount = baselineValues.count
        self.respiratoryBaselineMean = baselineValues.isEmpty
            ? nil
            : baselineValues.reduce(0, +) / Double(baselineValues.count)
        self.averageDurationText = Self.makeAverageDurationText(nights)
        self.evidenceCountText = Self.makeEvidenceCountText(nights)
        self.averageFootnoteText = "Average across \(self.evidenceCountText)"
        let consistency = Self.makeSleepConsistency(nights)
        self.sleepConsistencyPercent = consistency.percent
        self.sleepConsistencyText = consistency.text
        self.sleepConsistencyFootnote = consistency.footnote
        let debtBasis = Self.makeRecentSleepDebtBasis(nights)
        self.recentSleepAverageDurationHours = debtBasis.averageHours
        self.recentSleepRecordCount = debtBasis.recordCount
    }

    init(rollups: [DailyRollup],
         confirmedSleeps: [UserConfirmedSleep],
         dismissedCandidates: [AtriaDismissedSleepCandidate] = [],
         calendar: Calendar = .current,
         shouldContinue: @escaping @Sendable () -> Bool = { true }) {
        guard shouldContinue() else {
            self = .empty
            return
        }
        var nightsByDay: [Date: Night] = [:]
        var additionalMainNightsList: [Night] = []
        var napNightsList: [Night] = []
        var resumedSleepSegments: [Night] = []
        // Ids the user explicitly designated as the primary main on a day they
        // slept more than once. Those records win the one-canonical-per-day race
        // regardless of duration so the chosen sleep drives Recovery/display and
        // the other same-day main becomes the second (additional) sleep. Empty
        // when no choice was ever made, so the duration heuristic below is
        // untouched for every ordinary day.
        let chosenPrimaryMainIDs = Set(
            confirmedSleeps.filter { $0.dayPrimaryChoice == true }.map(\.id)
        )
        for (sleepIndex, sleep) in confirmedSleeps.enumerated() {
            if sleepIndex.isMultiple(of: 32), !shouldContinue() {
                self = .empty
                return
            }
            // Sleep is a wake-boundary event. Candidates, frozen recovery and
            // Activity already use the morning the sleep ended; re-keying the
            // same evidence to bedtime after confirmation made Save appear to
            // change recovery and could leave today's sleep row empty.
            let day = EventCivilTime.day(containing: sleep.end,
                                         eventTimeZoneIdentifier: sleep.eventTimeZoneIdentifier,
                                         outputCalendar: calendar)
            let stageSegments = sleep.stageSegments
                ?? Self.legacyConfirmedSleepStageCompatibility(start: sleep.start,
                                                               end: sleep.end,
                                                               source: sleep.source)
            let effectiveDuration = sleep.effectiveSleepDuration
            let night = Night(id: sleep.id,
                              day: day,
                              savedAt: sleep.createdAt,
                              start: sleep.start,
                              end: sleep.end,
                              duration: effectiveDuration,
                              observedDuration: sleep.duration,
                              restingHR: sleep.restingHR > 0 ? sleep.restingHR : nil,
                              hrv: sleep.hrv,
                              hrvWindowCount: sleep.hrvWindowCount ?? 0,
                              respiratoryRate: sleep.respiratoryRate,
                              sleepEfficiency: Self.efficiency(duration: effectiveDuration,
                                                               span: sleep.span,
                                                               source: sleep.source),
                              confidence: sleep.confidence,
                              source: sleep.source,
                              confirmed: true,
                              stageSegments: stageSegments,
                              eventTimeZoneIdentifier: sleep.eventTimeZoneIdentifier,
                              motionValidated: sleep.motionValidated,
                              sleepNeedSeconds: sleep.sleepNeedSeconds,
                              frozenSleepNeed: sleep.frozenSleepNeed,
                              dayPrimaryChoice: sleep.dayPrimaryChoice)
            // Route confirmed naps into their own list, bypassing the day-keyed dict.
            // A same-calendar-day main sleep would otherwise last-writer-wins evict the
            // nap (or vice versa), silently dropping the nap credit from sameDayNapHours.
            if Night.explicitNapSources.contains(sleep.source) {
                napNightsList.append(night)
            } else if sleep.source == "resumed_sleep" {
                // A confirmed resumed segment remains its own durable Activity
                // record. The canonical nightly projection combines only its
                // observed duration with the earlier main sleep below; it never
                // rewrites either record or credits the awake gap.
                resumedSleepSegments.append(night)
                additionalMainNightsList.append(night)
            } else {
                if let existing = nightsByDay[day] {
                    // A civil day has one recovery-driving main sleep. Prefer
                    // the major (longer) sleep, then the later wake as a stable
                    // tie-breaker, while preserving the other durable record
                    // for Activity editing rather than silently overwriting it.
                    let nightEnd = night.end ?? night.day
                    let existingEnd = existing.end ?? existing.day
                    let nightChosen = chosenPrimaryMainIDs.contains(night.id)
                    let existingChosen = chosenPrimaryMainIDs.contains(existing.id)
                    let nightIsCanonical: Bool
                    if nightChosen != existingChosen {
                        // An explicit user choice overrides the duration heuristic.
                        nightIsCanonical = nightChosen
                    } else {
                        nightIsCanonical = night.duration > existing.duration
                            || (night.duration == existing.duration && nightEnd > existingEnd)
                    }
                    if nightIsCanonical {
                        additionalMainNightsList.append(existing)
                        nightsByDay[day] = night
                    } else {
                        additionalMainNightsList.append(night)
                    }
                } else {
                    nightsByDay[day] = night
                }
            }
        }

        guard shouldContinue() else {
            self = .empty
            return
        }
        let canonicalMains = Array(nightsByDay.values)
        for (mainIndex, entry) in Array(nightsByDay).enumerated() {
            if mainIndex.isMultiple(of: 16), !shouldContinue() {
                self = .empty
                return
            }
            let (day, main) = entry
            var segments: [Night] = []
            for (segmentIndex, segment) in resumedSleepSegments.enumerated() {
                if segmentIndex.isMultiple(of: 32), !shouldContinue() {
                    self = .empty
                    return
                }
                guard let segmentStart = segment.start,
                      let mainEnd = main.end,
                      segmentStart >= mainEnd,
                      segmentStart.timeIntervalSince(mainEnd)
                        <= AggregateSleepCandidate.resumedSleepMaximumSeparationFromMain else {
                    continue
                }
                var crossesAnotherMain = false
                for (candidateIndex, candidate) in canonicalMains.enumerated() {
                    if candidateIndex.isMultiple(of: 32), !shouldContinue() {
                        self = .empty
                        return
                    }
                    if candidate.id != main.id,
                       (candidate.end ?? .distantFuture) > mainEnd,
                       (candidate.end ?? .distantPast) <= segmentStart {
                        crossesAnotherMain = true
                        break
                    }
                }
                if !crossesAnotherMain { segments.append(segment) }
            }
            guard !segments.isEmpty,
                  let combined = Self.combiningResumedSleepSegments(
                    main: main,
                    resumed: segments,
                    shouldContinue: shouldContinue
                  ) else { continue }
            nightsByDay[day] = combined
        }

        var projectedCandidateCount = 0
        for (rollupIndex, rollup) in rollups.enumerated() {
            if rollupIndex.isMultiple(of: 32), !shouldContinue() {
                self = .empty
                return
            }
            guard rollup.sleepReady > 0 || rollup.sleepCandidates > 0 else {
                continue
            }
            let day = calendar.startOfDay(for: rollup.day)
            if let existing = nightsByDay[day], existing.confirmed {
                nightsByDay[day] = Self.mergingConfirmedNight(existing, with: rollup)
                continue
            }
            let sleepDuration = rollup.sleepDuration ?? (rollup.sleepReady > 0 ? rollup.duration : min(rollup.duration, 10 * 60 * 60))
            if let candidateStart = rollup.sleepStart,
               let candidateEnd = rollup.sleepEnd {
                var overlapsConfirmed = false
                for (index, sleep) in confirmedSleeps.enumerated() {
                    if index.isMultiple(of: 32), !shouldContinue() {
                        self = .empty
                        return
                    }
                    if sleep.start < candidateEnd && sleep.end > candidateStart {
                        overlapsConfirmed = true
                        break
                    }
                }
                var wasDismissed = false
                for (index, dismissed) in dismissedCandidates.enumerated() {
                    if index.isMultiple(of: 32), !shouldContinue() {
                        self = .empty
                        return
                    }
                    if dismissed.suppresses(
                        start: candidateStart,
                        end: candidateEnd
                    ) {
                        wasDismissed = true
                        break
                    }
                }
                if overlapsConfirmed || wasDismissed { continue }
            }
            if rollup.sleepCandidates > 0 { projectedCandidateCount += rollup.sleepCandidates }
            nightsByDay[day] = Night(id: "sleep-history-\(Int(day.timeIntervalSince1970))",
                                     day: day,
                                     start: rollup.sleepStart,
                                     end: rollup.sleepEnd,
                                     duration: sleepDuration,
                                     restingHR: rollup.restingHR,
                                     hrv: rollup.avgHRV,
                                     hrvWindowCount: max(0, rollup.hrvWindowCount),
                                     respiratoryRate: rollup.avgRespiratoryRate,
                                     sleepEfficiency: Self.efficiency(duration: sleepDuration, span: rollup.sleepSpan),
                                     confidence: rollup.sleepReady > 0 ? "ready" : "candidate",
                                     source: rollup.sleepReady > 0 ? "validated_sleep_window" : (rollup.sleepSource ?? "sleep_candidate"),
                                     confirmed: false,
                                     stageSegments: rollup.sleepStageSegments)
        }

        guard shouldContinue() else {
            self = .empty
            return
        }
        var sorted = Array(nightsByDay.values)
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &sorted,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: { $0.day > $1.day }
        ) else {
            self = .empty
            return
        }
        let clippedNights = Array(sorted.prefix(Self.maximumResidentNightCount))
        let baselineValues = clippedNights
            .dropFirst()
            .filter { $0.confirmed && !$0.isNapEvidence }
            .compactMap(\.respiratoryRate)
            .filter { $0 > 0 }
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &additionalMainNightsList,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: {
                ($0.start ?? $0.day) > ($1.start ?? $1.day)
            }
        ), AtriaSleepCooperativeAlgorithms.stableSort(
            &napNightsList,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: { $0.day > $1.day }
        ), shouldContinue() else {
            self = .empty
            return
        }
        self.nights = clippedNights
        self.additionalMainNights = additionalMainNightsList
        self.napNights = napNightsList
        self.confirmedCount = confirmedSleeps.count
        self.candidateCount = projectedCandidateCount
        self.respiratoryBaselineCount = baselineValues.count
        self.respiratoryBaselineMean = baselineValues.isEmpty
            ? nil
            : baselineValues.reduce(0, +) / Double(baselineValues.count)
        self.averageDurationText = Self.makeAverageDurationText(clippedNights)
        self.evidenceCountText = Self.makeEvidenceCountText(clippedNights)
        self.averageFootnoteText = "Average across \(self.evidenceCountText)"
        let consistency = Self.makeSleepConsistency(clippedNights)
        self.sleepConsistencyPercent = consistency.percent
        self.sleepConsistencyText = consistency.text
        self.sleepConsistencyFootnote = consistency.footnote
        let debtBasis = Self.makeRecentSleepDebtBasis(clippedNights)
        self.recentSleepAverageDurationHours = debtBasis.averageHours
        self.recentSleepRecordCount = debtBasis.recordCount
    }

    /// Builds the physiological-cycle presentation from separate durable
    /// records. Only measured segment durations are summed; the wall-clock span
    /// remains start-to-final-wake so efficiency honestly exposes every awake
    /// gap. The resumed records themselves stay in `additionalMainNights`.
    nonisolated static func combiningResumedSleepSegments(
        main: Night,
        resumed: [Night],
        shouldContinue: @escaping @Sendable () -> Bool = { true }
    ) -> Night? {
        guard shouldContinue(),
              main.confirmed,
              !main.isNapEvidence,
              SessionStore.confirmedSleepIsPhysiologicalMainSleep(main),
              let mainStart = main.start,
              let mainEnd = main.end else { return nil }
        var ordered: [Night] = []
        for (index, night) in resumed.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            if night.confirmed,
               night.source == "resumed_sleep",
               !night.isNapEvidence,
               (night.start ?? .distantPast) >= mainEnd,
               (night.start ?? .distantFuture).timeIntervalSince(mainEnd)
                    <= AggregateSleepCandidate.resumedSleepMaximumSeparationFromMain {
                ordered.append(night)
            }
        }
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &ordered,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: {
                ($0.start ?? .distantPast) < ($1.start ?? .distantPast)
            }
        ) else { return nil }
        guard !ordered.isEmpty else { return nil }

        var accepted: [Night] = []
        var lastEnd = mainEnd
        for (index, segment) in ordered.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            guard let start = segment.start,
                  let end = segment.end,
                  end > start,
                  start >= lastEnd else { continue }
            accepted.append(segment)
            lastEnd = end
        }
        guard !accepted.isEmpty else { return nil }

        let creditedDuration = min(
            lastEnd.timeIntervalSince(mainStart),
            main.duration + accepted.reduce(0) { $0 + $1.duration }
        )
        let observedDuration = min(
            lastEnd.timeIntervalSince(mainStart),
            main.observedDuration
                + accepted.reduce(0) { $0 + $1.observedDuration }
        )
        var stageSegments = main.stageSegments
        for (index, night) in accepted.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            stageSegments.append(contentsOf: night.stageSegments)
        }
        guard AtriaSleepCooperativeAlgorithms.stableSort(
            &stageSegments,
            shouldContinue: shouldContinue,
            areInIncreasingOrder: { $0.start < $1.start }
        ) else { return nil }
        let physiology = [main] + accepted
        func durationWeightedInt(_ value: (Night) -> Int?) -> Int? {
            var values: [(Double, Double)] = []
            for (index, night) in physiology.enumerated() {
                if index.isMultiple(of: 32), !shouldContinue() { return nil }
                guard let candidate = value(night),
                      candidate > 0,
                      night.duration > 0 else { continue }
                values.append((Double(candidate), night.duration))
            }
            guard !values.isEmpty else { return nil }
            let weight = values.reduce(0) { $0 + $1.1 }
            return Int((values.reduce(0) { $0 + $1.0 * $1.1 } / weight).rounded())
        }
        func durationWeightedDouble(_ value: (Night) -> Double?) -> Double? {
            var values: [(Double, Double)] = []
            for (index, night) in physiology.enumerated() {
                if index.isMultiple(of: 32), !shouldContinue() { return nil }
                guard let candidate = value(night),
                      candidate > 0,
                      night.duration > 0 else { continue }
                values.append((candidate, night.duration))
            }
            guard !values.isEmpty else { return nil }
            let weight = values.reduce(0) { $0 + $1.1 }
            return values.reduce(0) { $0 + $1.0 * $1.1 } / weight
        }
        var hrvValues: [(Double, Double)] = []
        for (index, night) in physiology.enumerated() {
            if index.isMultiple(of: 32), !shouldContinue() { return nil }
            if let hrv = night.hrv, hrv > 0 {
                hrvValues.append((
                    Double(hrv),
                    Double(max(night.hrvWindowCount, 1))
                ))
            }
        }
        let combinedHRV: Int? = if hrvValues.isEmpty {
            nil
        } else {
            Int(sqrt(
                hrvValues.reduce(0) { $0 + $1.0 * $1.0 * $1.1 }
                    / hrvValues.reduce(0) { $0 + $1.1 }
            ).rounded())
        }
        guard shouldContinue() else { return nil }
        return Night(
            id: main.id,
            day: main.day,
            savedAt: ([main] + accepted).compactMap(\.savedAt).max(),
            start: mainStart,
            end: lastEnd,
            duration: creditedDuration,
            observedDuration: observedDuration,
            restingHR: durationWeightedInt(\.restingHR),
            hrv: combinedHRV,
            hrvWindowCount: physiology.reduce(0) { $0 + max($1.hrvWindowCount, 0) },
            respiratoryRate: durationWeightedDouble(\.respiratoryRate),
            sleepEfficiency: Self.efficiency(
                duration: creditedDuration,
                span: lastEnd.timeIntervalSince(mainStart),
                source: main.source
            ),
            confidence: main.confidence,
            source: main.source,
            confirmed: true,
            stageSegments: stageSegments,
            eventTimeZoneIdentifier: main.eventTimeZoneIdentifier,
            motionValidated: main.motionValidated,
            sleepNeedSeconds: main.sleepNeedSeconds,
            frozenSleepNeed: main.frozenSleepNeed,
            dayPrimaryChoice: main.dayPrimaryChoice
        )
    }

    private static func mergingConfirmedNight(_ night: Night, with rollup: DailyRollup) -> Night {
        Night(id: night.id,
              day: night.day,
              savedAt: night.savedAt,
              start: night.start,
              end: night.end,
              duration: night.duration,
              observedDuration: night.observedDuration,
              restingHR: night.restingHR ?? rollup.restingHR,
              hrv: night.hrv ?? rollup.avgHRV,
              hrvWindowCount: max(night.hrvWindowCount,
                                  max(0, rollup.hrvWindowCount)),
              respiratoryRate: night.respiratoryRate ?? rollup.avgRespiratoryRate,
              sleepEfficiency: night.sleepEfficiency,
              confidence: night.confidence,
              source: night.source,
              confirmed: night.confirmed,
              stageSegments: night.stageSegments,
              eventTimeZoneIdentifier: night.eventTimeZoneIdentifier,
              motionValidated: night.motionValidated,
              sleepNeedSeconds: night.sleepNeedSeconds,
              frozenSleepNeed: night.frozenSleepNeed,
              dayPrimaryChoice: night.dayPrimaryChoice)
    }

    private static func legacyConfirmedSleepStageCompatibility(start: Date,
                                                               end: Date,
                                                               source: String) -> [SleepStageSegment] {
        _ = start
        _ = end
        _ = source
        return []
    }

    /// Newest overnight/main-sleep record. Naps never replace the night that
    /// drives recovery, sleep need, or overnight vitals.
    var latestMainSleep: Night? {
        nights.first { $0.confirmed && !$0.isNapEvidence }
    }

    /// Total effective sleep across every distinct main sleep that shares the
    /// latest main sleep's wake civil day — the honest "total sleep hours" for a
    /// day the user slept more than once (a short overnight plus a long daytime
    /// sleep). Display-only: recovery, sleep need, debt, and baseline learning
    /// keep reading the single canonical `latestMainSleep`. Resumed segments are
    /// already folded into the canonical night, so they are excluded here.
    var latestMainSleepDayEffectiveDuration: TimeInterval? {
        guard let latest = latestMainSleep else { return nil }
        guard let end = latest.end else { return latest.duration }
        let day = EventCivilTime.day(containing: end,
                                     eventTimeZoneIdentifier: latest.eventTimeZoneIdentifier,
                                     outputCalendar: .current)
        var total = latest.duration
        for extra in additionalMainNights where extra.source != "resumed_sleep" {
            guard extra.id != latest.id, let extraEnd = extra.end else { continue }
            let extraDay = EventCivilTime.day(containing: extraEnd,
                                              eventTimeZoneIdentifier: extra.eventTimeZoneIdentifier,
                                              outputCalendar: .current)
            if extraDay == day { total += extra.duration }
        }
        return total
    }

    /// Newest sleep evidence a presentation may show numerically. This is not
    /// an authorization source for recovery, debt, baseline learning, or a
    /// physiological-cycle boundary: those must continue to use
    /// `latestMainSleep`. It exists so a reviewable first-night duration/RHR is
    /// not replaced by a grey placeholder while still being labelled review.
    var latestDisplayEvidence: Night? {
        let confirmed = latestMainSleep
        let review = latestReviewable.flatMap { $0.confirmed ? nil : $0 }
        switch (confirmed, review) {
        case (.none, .none):
            return nil
        case (.some(let confirmed), .none):
            return confirmed
        case (.none, .some(let review)):
            return review
        case (.some(let confirmed), .some(let review)):
            return review.reviewReferenceDate > confirmed.reviewReferenceDate ? review : confirmed
        }
    }

    /// Newest nap record, whether it is still a candidate in `nights` or has
    /// moved into the confirmed-nap side collection.
    var latestNap: Night? {
        var seen = Set<String>()
        return (nights.filter(\.isNapEvidence) + napNights)
            .filter { seen.insert($0.id).inserted }
            .max { $0.reviewReferenceDate < $1.reviewReferenceDate }
    }

    /// Record the review workflow should foreground. This can intentionally
    /// differ from `latestMainSleep` when a nap candidate needs review.
    var latestReviewable: Night? {
        Self.preferredReviewableLatestSleep(from: nights)
    }

    /// Compatibility alias for review-oriented callers. Physiological and
    /// overnight UI must use `latestMainSleep` explicitly.
    var latest: Night? { latestReviewable }

    private static let napVsMainSleepReviewWindow: TimeInterval = 18 * 60 * 60

    private static func preferredReviewableLatestSleep(from nights: [Night]) -> Night? {
        guard let newest = nights.first else { return nil }
        if newest.confirmed { return newest }
        if newest.isMainSleepReviewCandidate { return newest }
        guard newest.isShortNapReviewCandidate else {
            return nights.dropFirst().first {
                $0.confirmed || $0.isMainSleepReviewCandidate || $0.isShortNapReviewCandidate
            }
        }

        let reference = newest.reviewReferenceDate
        let earliest = reference.addingTimeInterval(-napVsMainSleepReviewWindow)
        let latest = reference.addingTimeInterval(60 * 60)
        return nights.first { night in
            night.isMainSleepReviewCandidate
                && night.reviewReferenceDate >= earliest
                && night.reviewReferenceDate <= latest
        } ?? newest
    }

    var respiratoryBaselineStats: (mean: Double, sd: Double, count: Int)? {
        let values = nights
            .dropFirst()
            .filter { $0.confirmed && !$0.isNapEvidence }
            .compactMap(\.respiratoryRate)
            .filter { $0 > 0 }
        guard values.count >= PersonalBaseline.trustedMinimumSamples else { return nil }
        let mean = values.reduce(0, +) / Double(values.count)
        guard values.count > 1 else { return (mean, 0, values.count) }
        let variance = values.reduce(0) { $0 + pow($1 - mean, 2) } / Double(values.count - 1)
        return (mean, sqrt(variance), values.count)
    }

    /// Assessment P0.5 (2026-08-14, Recovery model v4): the wearer's OWN sleep
    /// baseline — robust median + scaled MAD over recent confirmed main
    /// nights, excluding the current night (`dropFirst`). Hours come from
    /// every confirmed night; efficiency only from motion-validated
    /// `displaySleepEfficiency` (HR-only span coverage must never enter).
    /// Each component is nil below the same 14-night trust bar the HRV/RHR
    /// baselines use — fail closed, never a population substitute.
    var sleepBaselineStats: (hours: (location: Double, scale: Double, count: Int)?,
                             efficiency: (location: Double, scale: Double, count: Int)?)? {
        let recent = nights
            .dropFirst()
            .filter { $0.confirmed && !$0.isNapEvidence }
            .prefix(30)
        func robust(_ values: [Double]) -> (location: Double, scale: Double, count: Int)? {
            guard values.count >= PersonalBaseline.trustedMinimumSamples else { return nil }
            let sorted = values.sorted()
            let mid = sorted.count / 2
            let median = sorted.count.isMultiple(of: 2)
                ? (sorted[mid - 1] + sorted[mid]) / 2
                : sorted[mid]
            let deviations = values.map { abs($0 - median) }.sorted()
            let devMid = deviations.count / 2
            let mad = deviations.count.isMultiple(of: 2)
                ? (deviations[devMid - 1] + deviations[devMid]) / 2
                : deviations[devMid]
            return (location: median, scale: 1.4826 * mad, count: values.count)
        }
        let hours = robust(recent.map { $0.duration / 3_600 }.filter { $0 > 0 })
        let efficiency = robust(recent.compactMap(\.displaySleepEfficiency))
        guard hours != nil || efficiency != nil else { return nil }
        return (hours: hours, efficiency: efficiency)
    }

    private static func makeAverageDurationText(_ nights: [Night]) -> String {
        let confirmed = nights.filter(\.confirmed)
        guard !confirmed.isEmpty else { return "--" }
        let average = confirmed.reduce(0) { $0 + $1.duration } / Double(confirmed.count)
        return Self.formatDuration(average)
    }

    private static func makeEvidenceCountText(_ nights: [Night]) -> String {
        guard !nights.isEmpty else { return "No sleep records" }
        let napCount = nights.filter(\.isNapEvidence).count
        if napCount == nights.count {
            return nights.count == 1 ? "1 nap" : "\(nights.count) naps"
        }
        if napCount > 0 {
            return "\(nights.count) records"
        }
        return nights.count == 1 ? "1 night" : "\(nights.count) nights"
    }

    private static func recentSleepNights(_ nights: [Night]) -> [Night] {
        nights.filter { $0.confirmed && !$0.isNapEvidence }
    }

    /// Rolling sleep consistency as it was knowable on a specific morning.
    ///
    /// `sleepConsistencyPercent` is the current snapshot value. Persisting that
    /// same number into every historical daily row rewrites the past whenever a
    /// new night lands. This projection keeps only confirmed main sleeps whose
    /// wake day is at or before the requested civil day, then applies the exact
    /// same duration/schedule calculation as the live snapshot.
    func sleepConsistencyPercent(asOf day: Date,
                                 calendar: Calendar = .current) -> Int? {
        let cutoff = calendar.startOfDay(for: day)
        let available = nights.filter { night in
            night.confirmed
                && !night.isNapEvidence
                && calendar.startOfDay(for: night.day) <= cutoff
        }
        // A daily sleep row describes the morning that actually contains a
        // confirmed main sleep. Carrying the prior trend onto a no-sleep row
        // makes that civil day look observed when it was not.
        guard available.contains(where: {
            calendar.isDate($0.day, inSameDayAs: cutoff)
        }) else {
            return nil
        }
        return Self.makeSleepConsistency(available).percent
    }

    func sleepBudgetDebtHours(baseNeedHours: Double, excluding excludedNightID: String? = nil) -> Double {
        let records = Self.recentSleepNights(nights)
            .filter { night in
                guard let excludedNightID else { return true }
                return night.id != excludedNightID
            }
            .prefix(7)
        let oldestFirst = records.reversed().map { night in
            (needed: min(max(baseNeedHours, 6), 10), slept: night.durationHours)
        }
        return AtriaSleepBudget.sleepDebt(nights: Array(oldestFirst))
    }

    func sameDayNapHours(for night: Night, calendar: Calendar = .current) -> Double {
        guard let mainStart = night.start else {
            return napNights
                .filter { $0.confirmed && calendar.isDate($0.day, inSameDayAs: night.day) }
                .reduce(0) { $0 + $1.durationHours }
        }
        // `Night.day` is the wake day. Nap credit for this sleep need belongs
        // to the preceding wake-to-bed interval, not to the civil morning on
        // which the main sleep ended. Find the prior main wake when available;
        // otherwise keep the search bounded to one day before bedtime.
        let previousMainWake = nights.lazy
            .filter { candidate in
                guard candidate.id != night.id,
                      !candidate.isNapEvidence,
                      let end = candidate.end else { return false }
                return end <= mainStart
            }
            .compactMap(\.end)
            .max()
        let lowerBound = previousMainWake ?? mainStart.addingTimeInterval(-24 * 60 * 60)
        return napNights
            .filter { nap in
                guard nap.confirmed,
                      let napEnd = nap.end else { return false }
                return napEnd > lowerBound && napEnd <= mainStart
            }
            .reduce(0) { $0 + $1.durationHours }
    }

    func sleepNeedHours(for night: Night,
                        baseNeedHours: Double,
                        yesterdayStrain: Double? = nil,
                        calendar: Calendar = .current) -> Double? {
        if let frozen = night.frozenSleepNeed {
            return frozen.totalHours
        }
        // A confirmed legacy night has no trustworthy receipt. Do not make a
        // historical target appear more precise by recalculating it now.
        guard !night.confirmed else { return nil }
        return AtriaSleepBudget.sleepNeed(baseHours: baseNeedHours,
                                          yesterdayStrain: yesterdayStrain,
                                          debtHours: sleepBudgetDebtHours(baseNeedHours: baseNeedHours,
                                                                          excluding: night.id),
                                          sameDayNapHours: sameDayNapHours(for: night, calendar: calendar))
    }

    /// Itemized version of sleepNeedHours (2026-07-07 design-handoff ledger).
    func sleepNeedComponents(for night: Night,
                             baseNeedHours: Double,
                             yesterdayStrain: Double? = nil,
                             calendar: Calendar = .current) -> AtriaSleepBudget.NeedComponents? {
        if let frozen = night.frozenSleepNeed {
            return frozen.components
        }
        guard !night.confirmed else { return nil }
        return AtriaSleepBudget.sleepNeedComponents(baseHours: baseNeedHours,
                                                    yesterdayStrain: yesterdayStrain,
                                                    debtHours: sleepBudgetDebtHours(baseNeedHours: baseNeedHours,
                                                                                    excluding: night.id),
                                                    sameDayNapHours: sameDayNapHours(for: night, calendar: calendar))
    }

    /// ITEM-2 2026-08-15: tonight's PROVISIONAL projected need. Unlike a
    /// night's frozen receipt this is a live projection for the sleep that
    /// has not happened yet: debt includes the just-finished night's
    /// shortfall, the strain input is TODAY's accruing TRIMP (tonight's
    /// "yesterday"), and nap credit counts confirmed naps since the last
    /// main wake. Display-only — never persisted, never fed to
    /// performance %.
    func tonightProjectedNeedComponents(baseNeedHours: Double,
                                        todayTRIMP: Double?,
                                        todayStrainFallback: Double?) -> AtriaSleepBudget.NeedComponents {
        let napHours: Double
        if let lastWake = latestMainSleep?.end {
            napHours = napNights
                .filter { $0.confirmed && ($0.end.map { $0 > lastWake } ?? false) }
                .reduce(0) { $0 + $1.durationHours }
        } else {
            napHours = 0
        }
        return AtriaSleepBudget.sleepNeedComponents(
            baseHours: baseNeedHours,
            yesterdayTRIMP: todayTRIMP,
            yesterdayStrainFallback: todayStrainFallback,
            debtHours: sleepBudgetDebtHours(baseNeedHours: baseNeedHours),
            sameDayNapHours: napHours)
    }

    func sleepPerformancePercent(for night: Night,
                                  baseNeedHours: Double,
                                  yesterdayStrain: Double? = nil,
                                  calendar: Calendar = .current) -> Int? {
        guard let need = sleepNeedHours(for: night,
                                        baseNeedHours: baseNeedHours,
                                        yesterdayStrain: yesterdayStrain,
                                        calendar: calendar) else { return nil }
        return AtriaSleepBudget.performancePercent(slept: night.durationHours, needed: need)
    }

    func sleepPerformanceSummary(for night: Night,
                                 baseNeedHours: Double,
                                 yesterdayStrain: Double? = nil,
                                 calendar: Calendar = .current) -> String {
        guard let need = sleepNeedHours(for: night,
                                        baseNeedHours: baseNeedHours,
                                        yesterdayStrain: yesterdayStrain,
                                        calendar: calendar) else {
            return "Sleep Need unavailable for this legacy night"
        }
        let performance = AtriaSleepBudget.performancePercent(slept: night.durationHours, needed: need)
        return "Slept \(night.durationText) of \(AtriaMetricFormat.sleepHours(need)) needed · \(performance)%"
    }

    func bedtimeSuggestionText(now: Date = Date(),
                               targetHours: Double,
                               calendar: Calendar = .current) -> String? {
        guard calendar.component(.hour, from: now) >= 21 else { return nil }
        if let latest, !latest.confirmed, !latest.isNapEvidence { return nil }
        let wakeMinutes = Self.recentSleepNights(nights)
            .prefix(14)
            .compactMap { Self.sleepWakeMinute($0, calendar: calendar) }
        guard !wakeMinutes.isEmpty else { return nil }
        let medianWake = Self.medianMinute(wakeMinutes)
        let targetMinutes = Int((min(max(targetHours, 6), 10) * 60).rounded())
        let bedtimeMinute = Self.normalizedDayMinute(medianWake - targetMinutes)
        return "In bed by \(Self.formatClockMinute(bedtimeMinute)) to hit \(AtriaMetricFormat.sleepHours(targetHours))"
    }

    private static func makeSleepConsistency(_ nights: [Night]) -> (percent: Int?, text: String, footnote: String) {
        let result = AtriaSleepConsistency.result(from: nights)
        return (result.combinedPercent, result.displayText, result.footnote)
    }

    private static func makeRecentSleepDebtBasis(_ nights: [Night]) -> (averageHours: Double?, recordCount: Int) {
        let records = recentSleepNights(nights).prefix(7)
        guard !records.isEmpty else { return (nil, 0) }
        let average = records.reduce(0) { $0 + $1.durationHours } / Double(records.count)
        return (average, records.count)
    }

    private static func sleepMidpointTimeOfDaySeconds(_ night: Night) -> TimeInterval? {
        guard let start = night.start, let end = night.end, end > start else { return nil }
        let midpoint = start.addingTimeInterval(end.timeIntervalSince(start) / 2)
        let components = Calendar.current.dateComponents([.hour, .minute, .second], from: midpoint)
        guard let hour = components.hour, let minute = components.minute, let second = components.second else { return nil }
        return TimeInterval(hour * 3_600 + minute * 60 + second)
    }

    private static func sleepWakeMinute(_ night: Night, calendar: Calendar) -> Int? {
        guard let end = night.end else { return nil }
        let components = calendar.dateComponents([.hour, .minute], from: end)
        guard let hour = components.hour, let minute = components.minute else { return nil }
        return hour * 60 + minute
    }

    private static func medianMinute(_ minutes: [Int]) -> Int {
        let sorted = minutes.sorted()
        let midpoint = sorted.count / 2
        if sorted.count.isMultiple(of: 2) {
            return Int((Double(sorted[midpoint - 1]) + Double(sorted[midpoint])) / 2.0)
        }
        return sorted[midpoint]
    }

    private static func normalizedDayMinute(_ minute: Int) -> Int {
        let dayMinutes = 24 * 60
        return ((minute % dayMinutes) + dayMinutes) % dayMinutes
    }

    private static func formatClockMinute(_ minute: Int) -> String {
        let hour = minute / 60
        let displayHour = hour % 12 == 0 ? 12 : hour % 12
        return String(format: "%d:%02d", displayHour, minute % 60)
    }

    private static func circularMeanAbsoluteDeviationHours(_ seconds: [TimeInterval]) -> Double {
        let daySeconds = 24.0 * 60.0 * 60.0
        let angles = seconds.map { ($0 / daySeconds) * 2.0 * Double.pi }
        let sinMean = angles.reduce(0) { $0 + sin($1) } / Double(angles.count)
        let cosMean = angles.reduce(0) { $0 + cos($1) } / Double(angles.count)
        var meanAngle = atan2(sinMean, cosMean)
        if meanAngle < 0 { meanAngle += 2.0 * Double.pi }
        let meanSeconds = (meanAngle / (2.0 * Double.pi)) * daySeconds
        let totalDeviation = seconds.reduce(0) { total, value in
            let raw = abs(value - meanSeconds)
            return total + min(raw, daySeconds - raw)
        }
        return (totalDeviation / Double(seconds.count)) / 3_600
    }

    func sleepDebtText(goalHours: Double) -> String {
        guard let debt = sleepDebtHours(goalHours: goalHours) else { return "--" }
        if debt < 0.05 { return "Met" }
        return AtriaMetricFormat.sleepHours(debt)
    }

    func sleepDebtFootnote(goalHours: Double) -> String {
        guard let debt = sleepDebtHours(goalHours: goalHours) else {
            return "Needs recent sleep records."
        }
        if debt < 0.05 {
            return "Recent sleep meets \(AtriaMetricFormat.sleepHours(goalHours)) goal."
        }
        return "Weighted 7-night shortfall vs \(AtriaMetricFormat.sleepHours(goalHours)) goal."
    }

    private func sleepDebtHours(goalHours: Double) -> Double? {
        let records = Self.recentSleepNights(nights).prefix(7)
        guard !records.isEmpty else { return nil }
        let safeGoal = min(max(goalHours, 6), 10)
        let oldestFirst = records.reversed().map {
            (needed: safeGoal, slept: $0.durationHours)
        }
        // Keep the displayed debt and the debt term used by sleep-need on the
        // same recency-decayed ledger. The old display subtracted the unweighted
        // seven-night average while sleep need summed decayed shortfalls, so the
        // two cards could disagree by hours from identical nights.
        return AtriaSleepBudget.sleepDebt(nights: Array(oldestFirst))
    }

    var emptyEvidenceLabel: String {
        "Recent records"
    }

    var emptyEvidenceValue: String {
        if confirmedCount > 0 { return "\(confirmedCount)" }
        if candidateCount > 0 { return "\(candidateCount)" }
        return "Learning"
    }

    var emptyEvidenceFootnote: String {
        if confirmedCount > 0 { return "Confirmed sleep or nap saved locally." }
        if candidateCount > 0 { return "Sleep or nap evidence saved; confirm it when ready." }
        return "Wear the strap overnight or during a nap. Atria shows duration and RHR once saved evidence exists."
    }

    private static func efficiency(duration: TimeInterval,
                                   span: TimeInterval?,
                                   source: String? = nil) -> Double? {
        // A manually entered window tells us duration, not how much of that
        // window was actually asleep. Treating duration == span as measured
        // evidence minted a fake 100% efficiency and lifted recovery. Keep the
        // duration credit while leaving efficiency unknown until sensors support
        // it. User-adjusted sensor-backed windows use a different source and
        // retain their measured coverage/span efficiency.
        if source == "manual_sleep" || source == "manual_nap" { return nil }
        guard let span, span > 0, duration > 0 else { return nil }
        return min(max(duration / span, 0), 1)
    }

    var stateText: String {
        if confirmedCount > 0 { return "\(confirmedCount) confirmed" }
        if candidateCount > 0 { return "\(candidateCount) candidates" }
        return "Learning"
    }

    static func formatDuration(_ seconds: TimeInterval) -> String {
        guard seconds > 0 else { return "--" }
        let minutes = Int((seconds / 60).rounded())
        let hours = minutes / 60
        let remainder = minutes % 60
        if hours > 0 {
            return "\(hours)h \(remainder)m"
        }
        return "\(remainder)m"
    }
}

/// One timing-only authority for every Sleep Consistency surface. It uses the
/// local civil time recorded with each sleep event, so travelling later cannot
/// shift an old bedtime or wake time into the current phone timezone.
struct AtriaSleepConsistency: Equatable {
    static let minimumQualifiedNights = 5

    struct NightDeviation: Equatable, Identifiable {
        let id: String
        /// Wake day — lets consumers label rows and identify the latest night
        /// without re-deriving anything from a parallel nights array.
        let day: Date
        let bedtimeMinutes: Int
        let wakeMinutes: Int
        let bedtimeDeviationMinutes: Int
        let wakeDeviationMinutes: Int
    }

    /// Optional planner-derived target window (GAP-02): median qualified wake
    /// time minus the configured sleep target, expressed in the same anchored
    /// civil minutes as `NightDeviation`, so the schedule visual can draw it
    /// without a parallel calculation.
    struct RecommendedWindow: Equatable {
        let bedtimeMinutes: Int
        let wakeMinutes: Int
    }

    let bedtimeRegularity: Int?
    let wakeTimeRegularity: Int?
    let combinedPercent: Int?
    let qualifiedNightCount: Int
    let typicalBedtimeMinutes: Int?
    let typicalWakeTimeMinutes: Int?
    let deviations: [NightDeviation]
    let recommendedWindow: RecommendedWindow?

    /// The newest qualified night — every consumer highlights the same row.
    var latestNight: NightDeviation? {
        deviations.max { $0.day < $1.day }
    }

    var isQualified: Bool { combinedPercent != nil }
    var displayText: String { combinedPercent.map { "\($0)%" } ?? "--" }
    var typicalBedtimeText: String { Self.clockText(typicalBedtimeMinutes) }
    var typicalWakeTimeText: String { Self.clockText(typicalWakeTimeMinutes) }
    var bedtimeVariationMinutes: Int? {
        deviations.isEmpty ? nil : Int((Double(deviations.map(\.bedtimeDeviationMinutes).reduce(0, +)) / Double(deviations.count)).rounded())
    }
    var wakeVariationMinutes: Int? {
        deviations.isEmpty ? nil : Int((Double(deviations.map(\.wakeDeviationMinutes).reduce(0, +)) / Double(deviations.count)).rounded())
    }
    var footnote: String {
        guard let combinedPercent else {
            return "Needs \(Self.minimumQualifiedNights) qualified main-sleep nights (\(qualifiedNightCount) so far)."
        }
        if combinedPercent >= 85 { return "Very steady bed and wake timing." }
        if combinedPercent >= 70 { return "Mostly steady bed and wake timing." }
        return "Variable bed or wake timing; a steadier schedule will improve this."
    }

    static func result(from nights: [SleepHistorySnapshot.Night],
                       targetSleepHours: Double? = nil) -> Self {
        let timings = nights
            .filter { $0.confirmed && !$0.isNapEvidence }
            .compactMap { night -> (id: String, day: Date, bedtime: Int, wake: Int)? in
                guard let start = night.start, let end = night.end, end > start else { return nil }
                // GAP-02 fail-closed timezone rule: a consistency civil time is
                // only trustworthy in the sleep event's own recorded zone. A
                // legacy record without one cannot prove its civil bed/wake
                // times, and interpreting it in the phone's current zone would
                // silently shift old nights after travel — so it does not
                // qualify. (Every record written since 2026-07-13 carries the
                // identifier.)
                guard let identifier = night.eventTimeZoneIdentifier,
                      let timeZone = TimeZone(identifier: identifier) else { return nil }
                var calendar = Calendar(identifier: .gregorian)
                calendar.timeZone = timeZone
                let startParts = calendar.dateComponents([.hour, .minute], from: start)
                let endParts = calendar.dateComponents([.hour, .minute], from: end)
                let bedtime = (startParts.hour ?? 0) * 60 + (startParts.minute ?? 0)
                let wake = (endParts.hour ?? 0) * 60 + (endParts.minute ?? 0)
                // Anchor both timings at the night that starts in the evening.
                return (night.id,
                        night.day,
                        bedtime < 12 * 60 ? bedtime + 24 * 60 : bedtime,
                        wake < 12 * 60 ? wake + 24 * 60 : wake)
            }
            .prefix(14)

        guard timings.count >= minimumQualifiedNights else {
            return Self(bedtimeRegularity: nil,
                        wakeTimeRegularity: nil,
                        combinedPercent: nil,
                        qualifiedNightCount: timings.count,
                        typicalBedtimeMinutes: nil,
                        typicalWakeTimeMinutes: nil,
                        deviations: [],
                        recommendedWindow: nil)
        }
        let bedtimes = timings.map(\.bedtime)
        let wakes = timings.map(\.wake)
        let typicalBedtime = Int((Double(bedtimes.reduce(0, +)) / Double(bedtimes.count)).rounded())
        let typicalWake = Int((Double(wakes.reduce(0, +)) / Double(wakes.count)).rounded())
        let deviations = timings.map {
            NightDeviation(id: $0.id,
                           day: $0.day,
                           bedtimeMinutes: $0.bedtime,
                           wakeMinutes: $0.wake,
                           bedtimeDeviationMinutes: abs($0.bedtime - typicalBedtime),
                           wakeDeviationMinutes: abs($0.wake - typicalWake))
        }
        func regularity(_ values: [Int], typical: Int) -> Int {
            let meanDeviation = Double(values.reduce(0) { $0 + abs($1 - typical) }) / Double(values.count)
            return min(max(100 - Int((meanDeviation / 120 * 60).rounded()), 0), 100)
        }
        let bedtimeRegularity = regularity(bedtimes, typical: typicalBedtime)
        let wakeRegularity = regularity(wakes, typical: typicalWake)
        // Same shape as the planner's live nudge: median qualified wake time
        // minus the configured target. Exposed as data so the schedule visual
        // never maintains a parallel calculation.
        let recommendedWindow = targetSleepHours.map { target -> RecommendedWindow in
            let sortedWakes = wakes.sorted()
            let medianWake = sortedWakes[sortedWakes.count / 2]
            let targetMinutes = Int((min(max(target, 6), 10) * 60).rounded())
            return RecommendedWindow(bedtimeMinutes: medianWake - targetMinutes,
                                     wakeMinutes: medianWake)
        }
        return Self(bedtimeRegularity: bedtimeRegularity,
                    wakeTimeRegularity: wakeRegularity,
                    combinedPercent: Int((Double(bedtimeRegularity + wakeRegularity) / 2).rounded()),
                    qualifiedNightCount: timings.count,
                    typicalBedtimeMinutes: typicalBedtime,
                    typicalWakeTimeMinutes: typicalWake,
                    deviations: deviations,
                    recommendedWindow: recommendedWindow)
    }

    static func clockText(_ minute: Int?) -> String {
        guard let minute else { return "--" }
        let normalized = ((minute % 1_440) + 1_440) % 1_440
        let hour24 = normalized / 60
        let suffix = hour24 >= 12 ? "PM" : "AM"
        let hour12 = hour24 % 12 == 0 ? 12 : hour24 % 12
        return String(format: "%d:%02d %@", hour12, normalized % 60, suffix)
    }
}

private struct HistoryQuickStat: View {
    let label: String
    let value: String

    var body: some View {
        VStack(alignment: .leading, spacing: 4) {
            Text(label)
                .font(.caption2.weight(.semibold))
                .foregroundStyle(.secondary)
            Text(value)
                .font(.headline.weight(.semibold).monospacedDigit())
                .lineLimit(1)
                .minimumScaleFactor(0.8)
        }
        .frame(maxWidth: .infinity, alignment: .leading)
        .padding(12)
        .atriaInsetCard(cornerRadius: 22, tint: .white)
    }
}

private struct HistoryActivityRhythmCard: View {
    let rollups: [DailyRollup]

    private var recentRollups: [DailyRollup] {
        Array(rollups.prefix(14).reversed())
    }

    private var confirmedCount: Int {
        rollups.reduce(0) { $0 + $1.confirmedWorkouts }
    }

    private var reviewCount: Int {
        rollups.reduce(0) { $0 + $1.activityCandidates }
    }

    private var sleepContextCount: Int {
        // max, not sum: a ready night is also a candidate. Since sleepReady
        // became HR-only-eligible (2026-07-08) the two are no longer disjoint,
        // so summing double-counted every auto-confirmed night.
        rollups.reduce(0) { $0 + max($1.sleepReady, $1.sleepCandidates) }
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            HStack(alignment: .firstTextBaseline) {
                Label("Activity rhythm", systemImage: "waveform.path.ecg")
                    .font(.caption.weight(.bold))
                Spacer(minLength: 8)
                Text("\(recentRollups.count)d")
                    .font(.caption2.weight(.bold).monospacedDigit())
                    .foregroundStyle(.secondary)
            }

            HStack(alignment: .bottom, spacing: 5) {
                ForEach(recentRollups, id: \.day) { rollup in
                    rhythmBar(rollup)
                }
            }
            .frame(height: 68)

            daySequenceStrip

            HStack(spacing: 8) {
                rhythmPill("Saved", value: "\(confirmedCount)", systemImage: "checkmark.seal.fill", tint: .orange)
                rhythmPill("Review", value: "\(reviewCount)", systemImage: "figure.strengthtraining.traditional", tint: .cyan)
                rhythmPill("Sleep", value: "\(sleepContextCount)", systemImage: "moon.zzz.fill", tint: .secondary)
            }
        }
        .padding(12)
        .background(.primary.opacity(0.045), in: RoundedRectangle(cornerRadius: 18, style: .continuous))
        .overlay {
            RoundedRectangle(cornerRadius: 18, style: .continuous)
                .stroke(Color.white.opacity(0.14), lineWidth: 1)
        }
        .accessibilityElement(children: .combine)
        .accessibilityLabel("Activity rhythm with day sequence. \(confirmedCount) confirmed workouts, \(reviewCount) review candidates, \(sleepContextCount) sleep context days.")
    }

    private var daySequenceStrip: some View {
        VStack(alignment: .leading, spacing: 8) {
            HStack {
                Text("Day sequence")
                    .font(.caption2.weight(.bold))
                    .foregroundStyle(.secondary)
                Spacer(minLength: 8)
                Text(sequenceSummary)
                    .font(.caption2.weight(.semibold).monospacedDigit())
                    .foregroundStyle(.secondary)
            }

            HStack(spacing: 6) {
                ForEach(recentRollups, id: \.day) { rollup in
                    daySequenceNode(rollup)
                }
            }
        }
        .padding(10)
        .atriaInsetCard(cornerRadius: 18, tint: .white)
    }

    private var sequenceSummary: String {
        let reviewDays = rollups.filter { $0.activityCandidates > 0 }.count
        let sleepDays = rollups.filter { $0.sleepReady + $0.sleepCandidates > 0 }.count
        if reviewDays > 0 {
            return "\(reviewDays) review"
        }
        if confirmedCount > 0 {
            return "\(confirmedCount) saved"
        }
        return "\(sleepDays) sleep"
    }

    private func daySequenceNode(_ rollup: DailyRollup) -> some View {
        let state = sequenceState(for: rollup)
        let intensity = min(max(rollup.strain / 21.0, 0.16), 1)
        return VStack(spacing: 5) {
            ZStack {
                RoundedRectangle(cornerRadius: 9, style: .continuous)
                    .fill(state.tint.opacity(0.10 + (0.14 * intensity)))
                    .frame(height: 28)
                Image(systemName: state.symbol)
                    .font(.system(size: 10, weight: .bold))
                    .foregroundStyle(state.tint)
            }

            Capsule(style: .continuous)
                .fill(state.tint.opacity(state.isEmpty ? 0.16 : 0.70))
                .frame(width: state.isToday ? 16 : 8, height: 3)
        }
        .frame(maxWidth: .infinity)
        .accessibilityLabel("\(rollup.day.formatted(date: .abbreviated, time: .omitted)): \(state.label), strain \(String(format: "%.1f", rollup.strain)).")
    }

    private func sequenceState(for rollup: DailyRollup) -> (symbol: String, tint: Color, label: String, isToday: Bool, isEmpty: Bool) {
        let isToday = Calendar.current.isDateInToday(rollup.day)
        if rollup.activityCandidates > 0 && rollup.workouts == 0 && rollup.confirmedWorkouts == 0 {
            return ("questionmark.circle.fill", .cyan, "needs workout review", isToday, false)
        }
        if rollup.confirmedWorkouts > 0 || rollup.workouts > 0 {
            return ("bolt.heart.fill", .orange, "workout saved", isToday, false)
        }
        if rollup.sleepReady > 0 || rollup.sleepCandidates > 0 {
            return ("moon.zzz.fill", .blue, "sleep context", isToday, false)
        }
        if rollup.restCandidates > 0 {
            return ("leaf.fill", .secondary, "recovery context", isToday, false)
        }
        return ("circle.fill", .secondary, "quiet day", isToday, true)
    }

    private func rhythmBar(_ rollup: DailyRollup) -> some View {
        let active = rollup.confirmedWorkouts > 0 || rollup.workouts > 0 || rollup.activityCandidates > 0
        let tint = rollup.confirmedWorkouts > 0 || rollup.workouts > 0 ? Color.orange : (rollup.activityCandidates > 0 ? Color.cyan : Color.secondary)
        let progress = min(max(rollup.strain / 21.0, 0.08), 1)
        return VStack(spacing: 5) {
            ZStack(alignment: .bottom) {
                Capsule(style: .continuous)
                    .fill(Color.primary.opacity(0.08))
                Capsule(style: .continuous)
                    .fill(tint.opacity(active ? 0.78 : 0.25))
                    .frame(height: max(6, 54 * progress))
            }
            .frame(maxWidth: .infinity)

            Circle()
                .fill(markerTint(for: rollup))
                .frame(width: markerSize(for: rollup), height: markerSize(for: rollup))
        }
        .accessibilityLabel("\(rollup.day.formatted(date: .abbreviated, time: .omitted)): strain \(String(format: "%.1f", rollup.strain)), \(rollup.confirmedWorkouts) confirmed, \(rollup.activityCandidates) review candidates.")
    }

    private func markerTint(for rollup: DailyRollup) -> Color {
        if rollup.confirmedWorkouts > 0 || rollup.workouts > 0 { return .orange }
        if rollup.activityCandidates > 0 { return .cyan }
        if rollup.sleepReady > 0 || rollup.sleepCandidates > 0 { return .blue }
        if rollup.restCandidates > 0 { return .secondary }
        return .primary.opacity(0.18)
    }

    private func markerSize(for rollup: DailyRollup) -> CGFloat {
        if rollup.confirmedWorkouts > 0 || rollup.workouts > 0 { return 8 }
        if rollup.activityCandidates > 0 { return 7 }
        if rollup.sleepReady > 0 || rollup.sleepCandidates > 0 || rollup.restCandidates > 0 { return 6 }
        return 4
    }

    private func rhythmPill(_ label: String, value: String, systemImage: String, tint: Color) -> some View {
        HStack(spacing: 5) {
            Image(systemName: systemImage)
                .font(.caption2.weight(.bold))
            Text(value)
                .font(.caption.weight(.bold).monospacedDigit())
            Text(label)
                .font(.caption2.weight(.semibold))
                .lineLimit(1)
                .minimumScaleFactor(0.72)
        }
        .foregroundStyle(tint)
        .frame(maxWidth: .infinity)
        .padding(.horizontal, 8)
        .padding(.vertical, 7)
        .background(tint.opacity(0.10), in: Capsule(style: .continuous))
    }
}

