    var body: some View {
        VStack(alignment: .leading, spacing: 4) {
            HStack {
                Label(detection.kind.rawValue, systemImage: icon)
                    .font(.headline)
                Spacer()
                Text(detection.confidence.rawValue)
                    .font(.caption.weight(.semibold))
                    .foregroundStyle(confidenceColor)
            }
            Text("\(detection.start, style: .time)-\(detection.end, style: .time) · \(durationText) · avg \(detection.avgHR) · peak \(detection.peakHR)")
                .font(.caption)
                .foregroundStyle(.secondary)
            Text(detection.reason)
                .font(.caption2)
                .foregroundStyle(.secondary)
        }
        .padding(.vertical, 2)
    }

    private var icon: String {
        switch detection.kind {
        case .activityCandidate: return "figure.walk.motion"
        case .workout: return "figure.mixed.cardio"
        case .sleepCandidate: return "bed.double"
        case .restCandidate: return "chair.lounge"
        }
    }

    private var confidenceColor: Color {
        switch detection.confidence {
        case .low: return .orange
        case .medium: return .teal
        case .high: return .green
        }
    }

    private var durationText: String {
        let s = Int(detection.duration)
        if s >= 3600 { return "\(s / 3600)h \((s % 3600) / 60)m" }
        return "\(s / 60)m"
    }
}

struct SessionDetail: View {
    let session: SavedSession
    private let displayedPoints: [SavedSession.Point]
    private let summary: SessionDetailSummary

    init(session: SavedSession) {
        self.session = session
        self.displayedPoints = Self.downsampledPoints(session.points)
        self.summary = SessionDetailSummary(session: session,
                                            rest: PersonalBaseline.load().restingInt ?? 60,
                                            maxHR: AthleteProfile.load().maxHR)
    }

    var body: some View {
        ZStack {
            AtriaDashboardBackdrop()
                .ignoresSafeArea()

            ScrollView {
                VStack(spacing: 16) {
                    Chart(Array(displayedPoints.enumerated()), id: \.offset) { _, p in
                        LineMark(x: .value("t", p.t), y: .value("bpm", p.bpm))
                            // Dense beat-level series, same as the heart-rate
                            // traces in Vitals and the Stress monitor — smooth
                            // it the same way rather than leaving this one
                            // surface angular.
                            .interpolationMethod(.monotone)
                            .foregroundStyle(.red.gradient)
                    }
                    .frame(height: 220)
                    .padding()
                    .atriaCard(cornerRadius: 22, emphasis: .soft)
                    .atriaInspectableGraph(sessionHeartRateGraph)

                    HStack(spacing: 0) {
                        stat("Resting", summary.resting)
                        stat("Average", summary.average)
                        stat("Peak", summary.peak)
                        VStack(spacing: 2) {
                            Text(summary.strainText)
                                .font(.title2.weight(.semibold).monospacedDigit())
                            Text("Strain").font(.caption2).foregroundStyle(.secondary)
                        }
                        .frame(maxWidth: .infinity)
                    }
                    .padding()
                    .atriaCard(cornerRadius: 22, emphasis: .soft)

                    if summary.metricsComplete {
                        TimeInZoneView(rows: summary.zoneRows,
                                       total: summary.zoneTotal,
                                       boundaries: summary.zoneBoundaries)
                            .padding()
                            .atriaCard(cornerRadius: 22, emphasis: .soft)
                    } else {
                        Label(summary.coverageText, systemImage: "exclamationmark.circle")
                            .font(.subheadline.weight(.semibold))
                            .foregroundStyle(.secondary)
                            .frame(maxWidth: .infinity, alignment: .leading)
                            .padding()
                            .atriaCard(cornerRadius: 22, emphasis: .soft)
                    }
                }
                .padding()
            }
        }
        .navigationTitle(session.label.isEmpty ? "Session" : session.label)
        .navigationBarTitleDisplayMode(.inline)
    }

    private static func downsampledPoints(_ points: [SavedSession.Point], targetCount: Int = 320) -> [SavedSession.Point] {
        guard points.count > targetCount, targetCount > 1 else { return points }
        let maxIndex = points.count - 1
        let step = Double(maxIndex) / Double(targetCount - 1)
        return (0..<targetCount).map { sample in
            let index = min(maxIndex, Int((Double(sample) * step).rounded()))
            return points[index]
        }
    }

    private var sessionHeartRateGraph: AtriaInspectableGraph? {
        guard displayedPoints.count >= 2 else { return nil }
        let readings = displayedPoints.map {
            (date: session.start.addingTimeInterval($0.t), value: Double($0.bpm))
        }
        return AtriaInspectableGraph(
            title: session.label.isEmpty ? "Session heart rate" : session.label,
            subtitle: "Recorded HR; blanks are collection gaps",
            content: .timeSeries([
                .init(title: "Heart rate",
                      unit: " bpm",
                      tint: .red,
                      points: AtriaInspectableGraph.segmentedPoints(readings,
                                                                    gapThreshold: 10))
            ], domain: nil)
        )
    }

    private func stat(_ title: String, _ value: String) -> some View {
        VStack(spacing: 2) {
            Text(value).font(.title2.weight(.semibold).monospacedDigit())
            Text(title).font(.caption2).foregroundStyle(.secondary)
        }
        .frame(maxWidth: .infinity)
    }
}

private struct SessionDetailSummary {
    let resting: String
    let average: String
    let peak: String
    let strainText: String
    let zoneRows: [TimeInZoneRow]
    let zoneTotal: Double
    let zoneBoundaries: AtriaHRRZoneBoundaries?
    let metricsComplete: Bool
    let coverageText: String

    init(session: SavedSession, rest: Int, maxHR: Int) {
        let readiness = session.workoutReadiness(rest: rest, maxHR: maxHR)
        metricsComplete = session.points.count >= 2
            && session.avg > 0
            && session.peak > 0
            && readiness.streamCoveragePercent >= AtriaWorkoutMetricPresentation.minimumNumericCoveragePercent
        coverageText = "\(readiness.streamCoveragePercent)% HR coverage · metrics incomplete"
        resting = metricsComplete ? "\(session.resting)" : "--"
        average = metricsComplete ? "\(session.avg)" : "--"
        peak = metricsComplete ? "\(session.peak)" : "--"
        // Strain uses the SAME baseline rest + profile maxHR as the day/trend
        // rollups (2026-07-08 consistency audit) so a workout's strain
        // reconciles everywhere. It previously used session.restingStable +
        // a re-clamped max, which diverged from every rollup for the same
        // workout. Zones keep a clamped max (they need max > rest).
        strainText = metricsComplete
            ? String(format: "%.1f",
                     Metrics.strain(fromTRIMP: session.trimp(rest: rest, max: maxHR)))
            : "Incomplete"
        let resolvedMaxHR = max(maxHR, rest + 1)
        let zoneMap: [HRZone: TimeInterval] = metricsComplete
            ? session.timeInZone(maxHR: resolvedMaxHR, restingHR: rest)
            : [:]
        // GAP-03: surface the exact HRR boundaries these rows were computed
        // with, so the zone labels can show real BPM ranges.
        zoneBoundaries = metricsComplete
            ? AtriaHRRZoneBoundaries(restingHR: rest, maxHR: resolvedMaxHR)
            : nil
        zoneRows = HRZone.allCases.compactMap { zone in
                guard let seconds = zoneMap[zone], seconds > 0 else { return nil }
                return TimeInZoneRow(zone: zone, seconds: seconds)
            }
            .sorted { $0.seconds > $1.seconds }
        zoneTotal = max(zoneRows.reduce(0) { $0 + $1.seconds }, 1)
    }
}
